long long numberSpiral(long long y, long long x) {
    if (y > x) {
        long long ans = (y - 1) * (y - 1);
        return (y % 2 != 0) ? ans + x : ans + 2 * y - x;
    } else {
        long long ans = (x - 1) * (x - 1);
        return (x % 2 == 0) ? ans + y : ans + 2 * x - y;
    }
}

