int ferrisWheel(std::vector<int>& people, int limit) {
    std::sort(people.begin(), people.end());
    int left = 0, right = (int)people.size() - 1;
    int gondolas = 0;
    while (left <= right) {
        if (left == right) { gondolas++; break; }
        if (people[left] + people[right] <= limit) left++;
        right--;
        gondolas++;
    }
    return gondolas;
}

