std::vector<int> concertTickets(const std::vector<int>& prices, const std::vector<int>& payments) {
    std::multiset<int> available(prices.begin(), prices.end());
    std::vector<int> result;
    for (int pay : payments) {
        auto it = available.upper_bound(pay);
        if (it == available.begin()) {
            result.push_back(-1);
        } else {
            --it;
            result.push_back(*it);
            available.erase(it);
        }
    }
    return result;
}

