long long diceCombinations(int dice, int target) {
    std::vector<long long> dp(target + 1, 0);
    dp[0] = 1;
    for (int i = 1; i <= target; ++i) {
        for (int j = 1; j <= std::min(i, dice); ++j) {
            dp[i] = (dp[i] + dp[i - j]) % 1000000007;
        }
    }
    return dp[target];
}

