int bookShop(const std::vector<int>& prices, const std::vector<int>& pages, int budget) {
    std::vector<std::vector<int>> dp(prices.size() + 1, std::vector<int>(budget + 1, 0));
    for (std::size_t i = 1; i <= prices.size(); ++i) {
        for (int j = 1; j <= budget; ++j) {
            if (prices[i - 1] > j) {
                dp[i][j] = dp[i - 1][j];
            } else {
                dp[i][j] = std::max(dp[i - 1][j], dp[i - 1][j - prices[i - 1]] + pages[i - 1]);
            }
        }
    }
    return dp[prices.size()][budget];
}

