int buildingRoads(int n, const std::vector<std::vector<int>>& connections) {
    std::vector<std::vector<int>> graph(n);
    for (size_t i = 0; i < connections.size(); ++i) {
        int u = connections[i][0];
        int v = connections[i][1];
        graph[u].push_back(v);
        graph[v].push_back(u);
    }
    std::vector<bool> visited(n, false);
    int count = 0;
    for (int i = 0; i < n; ++i) {
        if (!visited[i]) {
            dfs(graph, visited, i);
            ++count;
        }
    }
    return count - 1;
}

