std::vector<int> messageRoute(const std::unordered_map<int, std::vector<int>>& graph, int start, int end) {
    std::unordered_set<int> visited;
    std::deque<std::vector<int>> queue;
    queue.push_back({start});
    while (!queue.empty()) {
        std::vector<int> path = std::move(queue.front());
        queue.pop_front();
        int node = path.back();
        if (node == end) {
            return path;
        }
        visited.insert(node);
        auto it = graph.find(node);
        if (it != graph.end()) {
            const std::vector<int>& neighbors = it->second;
            for (int neighbor : neighbors) {
                if (visited.find(neighbor) == visited.end()) {
                    std::vector<int> newPath = path;
                    newPath.push_back(neighbor);
                    queue.push_back(std::move(newPath));
                }
            }
        }
    }
    return {};
}

