std::vector<long long> investigation(int n, const std::vector<std::vector<int>>& edges) {
    const long long MOD = 1000000007;
    std::vector<std::vector<std::pair<int,int>>> graph(n);
    for (auto& e : edges) graph[e[0]].push_back({e[1], e[2]});
    std::vector<long long> dist(n, LLONG_MAX), ways(n, 0), minF(n, LLONG_MAX), maxF(n, LLONG_MIN);
    dist[0] = 0; ways[0] = 1; minF[0] = 0; maxF[0] = 0;
    std::priority_queue<std::pair<long long,int>, std::vector<std::pair<long long,int>>, std::greater<>> pq;
    pq.push({0, 0});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > dist[u]) continue;
        for (auto& [v, w] : graph[u]) {
            long long nd = dist[u] + w;
            if (nd < dist[v]) {
                dist[v] = nd;
                ways[v] = ways[u];
                minF[v] = minF[u] + 1;
                maxF[v] = maxF[u] + 1;
                pq.push({nd, v});
            } else if (nd == dist[v]) {
                ways[v] = (ways[v] + ways[u]) % MOD;
                minF[v] = std::min(minF[v], minF[u] + 1);
                maxF[v] = std::max(maxF[v], maxF[u] + 1);
            }
        }
    }
    return {dist[n-1], ways[n-1], minF[n-1], maxF[n-1]};
}

