std::vector<double> shortestRoutes(const std::vector<std::vector<double>>& graph, std::size_t start) {
    std::vector<double> distances(graph.size(), std::numeric_limits<double>::infinity());
    distances[start] = 0.0;
    for (std::size_t i = 0; i < graph.size() - 1; ++i) {
        for (std::size_t u = 0; u < graph.size(); ++u) {
            for (std::size_t v = 0; v < graph[u].size(); ++v) {
                if (graph[u][v] != 0.0 && distances[u] + graph[u][v] < distances[v]) {
                    distances[v] = distances[u] + graph[u][v];
                }
            }
        }
    }
    for (std::size_t u = 0; u < graph.size(); ++u) {
        for (std::size_t v = 0; v < graph[u].size(); ++v) {
            if (graph[u][v] != 0.0 && distances[u] + graph[u][v] < distances[v]) {
                throw std::runtime_error("Graph contains a negative-weight cycle");
            }
        }
    }
    return distances;
}

