int treeMatching(int n, const std::vector<std::vector<int>>& edges) {
    std::vector<std::vector<int>> adj(n);
    for (auto& e : edges) {
        adj[e[0]].push_back(e[1]);
        adj[e[1]].push_back(e[0]);
    }
    std::vector<int> order, parent(n, -1);
    std::vector<bool> visited(n, false);
    std::vector<int> stack = {0};
    visited[0] = true;
    while (!stack.empty()) {
        int node = stack.back(); stack.pop_back();
        order.push_back(node);
        for (int nb : adj[node]) {
            if (!visited[nb]) {
                visited[nb] = true;
                parent[nb] = node;
                stack.push_back(nb);
            }
        }
    }
    std::vector<bool> matched(n, false);
    int count = 0;
    for (int i = (int)order.size() - 1; i >= 0; --i) {
        int node = order[i];
        int p = parent[node];
        if (p != -1 && !matched[node] && !matched[p]) {
            matched[node] = true;
            matched[p] = true;
            count++;
        }
    }
    return count;
}

