std::vector<int> treeDistances(int n, const std::vector<std::vector<int>>& edges) {
    std::vector<std::vector<int>> adj(n);
    for (auto& e : edges) {
        adj[e[0]].push_back(e[1]);
        adj[e[1]].push_back(e[0]);
    }
    auto bfs = [&](int src) {
        std::vector<int> dist(n, -1);
        dist[src] = 0;
        std::queue<int> q;
        q.push(src);
        while (!q.empty()) {
            int node = q.front(); q.pop();
            for (int nb : adj[node]) {
                if (dist[nb] == -1) {
                    dist[nb] = dist[node] + 1;
                    q.push(nb);
                }
            }
        }
        return dist;
    };
    auto d0 = bfs(0);
    int a = 0;
    for (int i = 0; i < n; ++i) if (d0[i] > d0[a]) a = i;
    auto dA = bfs(a);
    int b = 0;
    for (int i = 0; i < n; ++i) if (dA[i] > dA[b]) b = i;
    auto dB = bfs(b);
    std::vector<int> result(n);
    for (int i = 0; i < n; ++i) result[i] = std::max(dA[i], dB[i]);
    return result;
}

