int reverse(int x) {
    bool isNegative = x < 0;
    long long x_abs = std::abs(static_cast<long long>(x));
    long long reversed = 0;
    while (x_abs > 0) {
        int digit = x_abs % 10;
        x_abs /= 10;
        reversed = reversed * 10 + digit;
        if (reversed > INT_MAX) return 0;
    }
    return isNegative ? -static_cast<int>(reversed) : static_cast<int>(reversed);
}

