bool isMatch(const std::string& s, const std::string& p) {
    std::vector<std::vector<bool>> dp(s.length() + 1, std::vector<bool>(p.length() + 1, false));
    dp[s.length()][p.length()] = true;
    for (int i = static_cast<int>(s.length()); i >= 0; --i) {
        for (int j = static_cast<int>(p.length()) - 1; j >= 0; --j) {
            bool match = i < static_cast<int>(s.length()) && (p[j] == s[i] || p[j] == '.');
            if (j + 1 < static_cast<int>(p.length()) && p[j + 1] == '*') {
                dp[i][j] = dp[i][j + 2];
                if (match) {
                    dp[i][j] = dp[i][j] || dp[i + 1][j];
                }
            } else {
                dp[i][j] = match && dp[i + 1][j + 1];
            }
        }
    }
    return dp[0][0];
}

