struct HeapNode {
    int val;
    int listIndex;
    ListNode* node;
};

ListNode* mergeKLists(std::vector<ListNode*>& lists) {
    std::vector<HeapNode> minHeap;
    for (int i = 0; i < static_cast<int>(lists.size()); ++i) {
        if (lists[i]) {
            minHeap.push_back({lists[i]->val, i, lists[i]});
        }
    }

    ListNode* dummyHead = new ListNode(0);
    ListNode* current = dummyHead;

    auto cmp = [](const HeapNode& a, const HeapNode& b) {
        return a.val < b.val;
    };
    std::sort(minHeap.begin(), minHeap.end(), cmp);

    while (!minHeap.empty()) {
        HeapNode smallestNode = minHeap.front();
        minHeap.erase(minHeap.begin());

        current->next = smallestNode.node;
        current = current->next;

        if (smallestNode.node->next) {
            minHeap.push_back({smallestNode.node->next->val, smallestNode.listIndex, smallestNode.node->next});
            std::sort(minHeap.begin(), minHeap.end(), cmp);
        }
    }

    ListNode* result = dummyHead->next;
    delete dummyHead;
    return result;
}

