ListNode* reverseKGroup(ListNode* head, int k) {
    int length = 0;
    ListNode* temp = head;
    while (temp != nullptr) {
        ++length;
        temp = temp->next;
    }
    if (length < k) return head;

    ListNode* prev = nullptr;
    ListNode* curr = head;
    for (int i = 0; i < k; ++i) {
        ListNode* next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }

    head->next = reverseKGroup(curr, k);
    return prev;
}

