std::vector<int> findSubstring(const std::string& s, const std::vector<std::string>& words) {
    int wordLength = static_cast<int>(words[0].size());
    int totalWords = static_cast<int>(words.size());
    int totalLength = wordLength * totalWords;
    std::unordered_map<std::string, int> wordCount;
    for (const auto& word : words) {
        ++wordCount[word];
    }
    std::vector<int> result;
    int sLen = static_cast<int>(s.size());
    for (int i = 0; i <= sLen - totalLength; ++i) {
        auto windowCount = wordCount;
        int j = 0;
        for (; j < totalWords; ++j) {
            std::string word = s.substr(i + j * wordLength, wordLength);
            auto it = windowCount.find(word);
            if (it == windowCount.end() || it->second == 0) {
                break;
            }
            --(it->second);
        }
        if (j == totalWords) {
            result.push_back(i);
        }
    }
    return result;
}

