        int left = 0;
        int right = static_cast<int>(nums.size()) - 1;
        int result = -1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] == target) {
                result = mid;
                if (findFirst) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            } else if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return result;
    };
    int first = binarySearch(true);
    int last = binarySearch(false);
    return std::vector<int>{first, last};
}

