        int br = (r / B) * B;
        int bc = (c / B) * B;
        for (int i = 0; i < B; ++i) {
            for (int j = 0; j < B; ++j) {
                if (board[br + i][bc + j] == ch) return false;
            }
        }
        return true;
    };
    std::function<bool()> dfs = [&]() -> bool {
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                if (board[i][j] == '.') {
                    for (char d = '1'; d <= '9'; ++d) {
                        if (isValid(i, j, d)) {
                            board[i][j] = d;
                            if (dfs()) return true;
                            board[i][j] = '.';
                        }
                    }
                    return false;
                }
            }
        }
        return true;
    };
    dfs();
    return board;
}

