    while (start < result.size() - 1 && result[start] == 0) {
        ++start;
    }
    std::string out;
    out.reserve(result.size() - start);
    for (size_t i = start; i < result.size(); ++i) {
        out.push_back(static_cast<char>(result[i] + '0'));
    }
    return out;
}

