int jump(const std::vector<int>& nums) {
    int maxReach = nums[0];
    int step = nums[0];
    int jumps = 1;
    for (int i = 1; i < static_cast<int>(nums.size()); ++i) {
        if (i == step) {
            ++jumps;
            step = maxReach;
        }
        maxReach = std::max(maxReach, i + nums[i]);
        if (step >= static_cast<int>(nums.size()) - 1) {
            break;
        }
    }
    return jumps;
}

