        for (size_t j = i; j < n; ++j) {
            std::swap(matrix[i][j], matrix[j][i]);
        }
    }
    for (size_t i = 0; i < n; ++i) {
        size_t left = 0, right = n - 1;
        while (left < right) {
            std::swap(matrix[i][left], matrix[i][right]);
            ++left;
            --right;
        }
    }
    return matrix;
}

