std::vector<std::vector<int>> permute(const std::vector<int>& nums) {
    std::vector<std::vector<int>> result;
    std::function<void(std::vector<int>&, const std::vector<int>&)> backtrack;
    backtrack = [&](std::vector<int>& current, const std::vector<int>& remaining) {
        if (remaining.empty()) {
            result.push_back(current);
        } else {
            for (size_t i = 0; i < remaining.size(); ++i) {
                current.push_back(remaining[i]);
                std::vector<int> newRemaining;
                newRemaining.reserve(remaining.size() - 1);
                newRemaining.insert(newRemaining.end(), remaining.begin(), remaining.begin() + i);
                newRemaining.insert(newRemaining.end(), remaining.begin() + i + 1, remaining.end());
                backtrack(current, newRemaining);
                current.pop_back();
            }
        }
    };
    std::vector<int> start;
    backtrack(start, nums);
    return result;
}

