        --colEnd;
        if (rowStart <= rowEnd) {
            for (int i = colEnd; i >= colStart; --i) {
                result.push_back(matrix[rowEnd][i]);
            }
        }
        --rowEnd;
        if (colStart <= colEnd) {
            for (int i = rowEnd; i >= rowStart; --i) {
                result.push_back(matrix[i][colStart]);
            }
        }
        ++colStart;
    }
