int totalNQueens(int n) {
    std::vector<int> board(n, -1);
    auto isValid = [&](int row, int col) -> bool {
        for (int i = 0; i < row; ++i) {
            if (board[i] == col ||
                board[i] - i == col - row ||
                board[i] + i == col + row) {
                return false;
            }
        }
        return true;
    };
    std::function<int(int)> placeQueens = [&](int row) -> int {
        if (row == n) {
            return 1;
        }
        int count = 0;
        for (int col = 0; col < n; ++col) {
            if (isValid(row, col)) {
                board[row] = col;
                count += placeQueens(row + 1);
            }
        }
        return count;
    };
    return placeQueens(0);
}

