    for (int i = 1; i <= n; ++i) {
        factorial[i] = factorial[i - 1] * i;
    }
    std::vector<int> numbers;
    numbers.reserve(n);
    for (int i = 1; i <= n; ++i) {
        numbers.push_back(i);
