    int currentWidth = 0;
    for (size_t i = 0; i < words.size(); ++i) {
        if (currentWidth + static_cast<int>(currentLine.size()) + static_cast<int>(words[i].size()) > maxWidth) {
            int spaces = maxWidth - currentWidth;
            int gaps = static_cast<int>(currentLine.size()) - 1;
            std::string justifiedLine;
            if (gaps == 0) {
                justifiedLine = currentLine[0];
                justifiedLine.append(spaces, ' ');
            } else {
                int spacePerGap = spaces / gaps;
                int extraSpaces = spaces % gaps;
                for (size_t j = 0; j < currentLine.size(); ++j) {
                    justifiedLine += currentLine[j];
                    if (j < currentLine.size() - 1) {
                        justifiedLine.append(spacePerGap + (j < static_cast<size_t>(extraSpaces) ? 1 : 0), ' ');
                    }
                }
            }
            result.push_back(justifiedLine);
            currentLine.clear();
            currentLine.push_back(words[i]);
            currentWidth = static_cast<int>(words[i].size());
        } else {
            currentLine.push_back(words[i]);
            currentWidth += static_cast<int>(words[i].size());
        }
    }
    std::string lastLine;
    for (size_t i = 0; i < currentLine.size(); ++i) {
        if (i > 0) {
            lastLine += ' ';
        }
        lastLine += currentLine[i];
    }
    lastLine.append(maxWidth - static_cast<int>(lastLine.size()), ' ');
    result.push_back(lastLine);
    return result;
}

