std::string minWindow(const std::string& s, const std::string& t) {
    std::unordered_map<char, int> tCount;
    for (char ch : t) {
        tCount[ch] = tCount[ch] + 1;
    }

    int left = 0;
    int minLen = std::numeric_limits<int>::max();
    std::string minWindow = "";
    int count = static_cast<int>(tCount.size());
    int formed = 0;

    std::unordered_map<char, int> windowCounts;

    for (int right = 0; right < static_cast<int>(s.size()); ++right) {
        char character = s[right];
        windowCounts[character] = windowCounts[character] + 1;

        if (tCount.find(character) != tCount.end() && windowCounts[character] == tCount[character]) {
            ++formed;
        }

        while (left <= right && formed == count) {
            if (right - left + 1 < minLen) {
                minLen = right - left + 1;
                minWindow = s.substr(left, minLen);
            }

            char c = s[left];
            windowCounts[c] = windowCounts[c] - 1;
            if (tCount.find(c) != tCount.end() && windowCounts[c] < tCount[c]) {
                --formed;
            }
            ++left;
        }
    }

    return minWindow;
}

