bool exist(const std::vector<std::vector<char>>& board, const std::string& word) {
    const int directions[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    int rows = board.size();
    int cols = board[0].size();
    std::vector<std::vector<bool>> visited(rows, std::vector<bool>(cols, false));

    std::function<bool(int, int, int)> dfs = [&](int row, int col, int index) -> bool {
        if (board[row][col] != word[index]) return false;
        if (index == static_cast<int>(word.size()) - 1) return true;
        visited[row][col] = true;
        for (const auto& dir : directions) {
            int nr = row + dir[0];
            int nc = col + dir[1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !visited[nr][nc]) {
                if (dfs(nr, nc, index + 1)) return true;
            }
        }
        visited[row][col] = false;
        return false;
    };

    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            if (dfs(i, j, 0)) return true;
        }
    }
    return false;
}

