int largestRectangleArea(const std::vector<int>& heights) {
    std::vector<int> stack;
    int maxArea = 0;
    int index = 0;
    while (index < static_cast<int>(heights.size())) {
        if (stack.empty() || heights[index] >= heights[stack.back()]) {
            stack.push_back(index);
            ++index;
        } else {
            int topOfStack = stack.back();
            stack.pop_back();
            int width = stack.empty() ? index : index - stack.back() - 1;
            int area = heights[topOfStack] * width;
            maxArea = std::max(maxArea, area);
        }
    }
    while (!stack.empty()) {
        int topOfStack = stack.back();
        stack.pop_back();
        int width = stack.empty() ? index : index - stack.back() - 1;
        int area = heights[topOfStack] * width;
        maxArea = std::max(maxArea, area);
    }
    return maxArea;
}

