int maximalRectangle(const std::vector<std::vector<char>>& matrix) {
    if (matrix.empty() || matrix[0].empty()) return 0;
    int maxArea = 0;
    std::vector<int> heights(matrix[0].size(), 0);
    for (const auto& row : matrix) {
        for (std::size_t i = 0; i < row.size(); ++i) {
            heights[i] = (row[i] == '1') ? heights[i] + 1 : 0;
        }
        std::vector<std::size_t> stack;
        for (std::size_t i = 0; i <= heights.size(); ++i) {
            if (stack.empty() || (i < heights.size() && heights[i] >= heights[stack.back()])) {
                stack.push_back(i);
            } else {
                while (!stack.empty() && (i == heights.size() || heights[i] < heights[stack.back()])) {
                    std::size_t top = stack.back();
                    stack.pop_back();
                    int width = stack.empty() ? static_cast<int>(i) : static_cast<int>(i - stack.back() - 1);
                    maxArea = std::max(maxArea, heights[top] * width);
                }
                stack.push_back(i);
            }
        }
    }
    return maxArea;
}

