    ListNode* beforeDummy = new ListNode(0);
    ListNode* afterDummy = new ListNode(0);
    ListNode* before = beforeDummy;
    ListNode* after = afterDummy;
    while (head) {
        if (head->val < x) {
            before->next = head;
            before = before->next;
        } else {
            after->next = head;
            after = after->next;
        }
        head = head->next;
