std::vector<std::string> restoreIpAddresses(const std::string& s) {
    std::vector<std::string> result;
    auto isValid = [&](const std::string& segment) -> bool {
        if (segment.empty() || segment.size() > 3) return false;
        if (segment.size() > 1 && segment[0] == '0') return false;
        int val = std::stoi(segment);
        return val <= 255;
    };
    std::function<void(int, std::vector<std::string>)> backtrack = [&](int start, std::vector<std::string> path) {
        if (path.size() == 4) {
            if (start == static_cast<int>(s.size())) {
                std::string ip = path[0];
                for (size_t i = 1; i < path.size(); ++i) {
                    ip += '.' + path[i];
                }
                result.push_back(ip);
            }
            return;
        }
        for (int len = 1; len <= 3; ++len) {
            if (start + len > static_cast<int>(s.size())) break;
            std::string segment = s.substr(start, len);
            if (isValid(segment)) {
                std::vector<std::string> newPath = path;
                newPath.push_back(segment);
                backtrack(start + len, newPath);
            }
        }
    };
    backtrack(0, {});
    return result;
}

