TreeNode* recursiveBuild(int preStart, int preEnd, int inStart, int inEnd,
                         const std::vector<int>& preorder,
                         const std::vector<int>& inorder,
                         const std::unordered_map<int, int>& inorderMap) {
    if (preStart > preEnd) return nullptr;
    TreeNode* root = new TreeNode(preorder[preStart]);
    int inIndex = inorderMap.at(preorder[preStart]);
    int leftSize = inIndex - inStart;
    root->left = recursiveBuild(preStart + 1, preStart + leftSize, inStart, inIndex - 1,
                                preorder, inorder, inorderMap);
    root->right = recursiveBuild(preStart + leftSize + 1, preEnd, inIndex + 1, inEnd,
                                 preorder, inorder, inorderMap);
    return root;
}

