bool isPalindrome(const std::string& s) {
    int left = 0;
    int right = static_cast<int>(s.size()) - 1;
    while (left < right) {
        if (!isAlphanumeric(s[left])) {
            ++left;
        } else if (!isAlphanumeric(s[right])) {
            --right;
        } else if (std::tolower(static_cast<unsigned char>(s[left])) != std::tolower(static_cast<unsigned char>(s[right]))) {
            return false;
        } else {
            ++left;
            --right;
        }
    }
    return true;
}

