int ladderLength(const std::string& beginWord, const std::string& endWord, const std::vector<std::string>& wordList) {
    if (beginWord.size() != endWord.size()) return 0;
    std::unordered_set<std::string> dict(wordList.begin(), wordList.end());
    if (dict.find(endWord) == dict.end()) return 0;
    std::unordered_set<std::string> beginSet{beginWord}, endSet{endWord};
    int steps = 1;
    while (!beginSet.empty() && !endSet.empty()) {
        if (beginSet.size() > endSet.size()) std::swap(beginSet, endSet);
        std::unordered_set<std::string> nextSet;
        for (const std::string& word : beginSet) {
            std::string cur = word;
            for (size_t i = 0; i < cur.size(); ++i) {
                char original = cur[i];
                for (char c = 'a'; c <= 'z'; ++c) {
                    if (c == original) continue;
                    cur[i] = c;
                    if (endSet.find(cur) != endSet.end()) {
                        return steps + 1;
                    }
                    if (dict.find(cur) != dict.end()) {
                        nextSet.insert(cur);
                        dict.erase(cur);
                    }
                }
                cur[i] = original;
            }
        }
        beginSet.swap(nextSet);
        ++steps;
    }
    return 0;
}

