std::vector<std::vector<std::string>> findLadders(const std::string& beginWord, const std::string& endWord, const std::vector<std::string>& wordList) {
    std::unordered_set<std::string> wordSet(wordList.begin(), wordList.end());
    if (wordSet.find(endWord) == wordSet.end()) {
        return {};
    }

    std::deque<std::vector<std::string>> q;
    q.push_back({beginWord});
    std::vector<std::vector<std::string>> result;
    bool found = false;

    while (!q.empty() && !found) {
        size_t levelSize = q.size();
        std::unordered_set<std::string> visitedThisLevel;
        for (size_t i = 0; i < levelSize; ++i) {
            std::vector<std::string> path = std::move(q.front());
            q.pop_front();
            const std::string& word = path.back();

            for (size_t pos = 0; pos < word.size(); ++pos) {
                std::string nextWord = word;
                for (char c = 'a'; c <= 'z'; ++c) {
                    if (c == word[pos]) continue;
                    nextWord[pos] = c;
                    if (wordSet.find(nextWord) == wordSet.end()) continue;

                    std::vector<std::string> newPath = path;
                    newPath.push_back(nextWord);
                    if (nextWord == endWord) {
                        result.push_back(std::move(newPath));
                        found = true;
                    } else {
                        q.push_back(std::move(newPath));
                    }
                    visitedThisLevel.insert(nextWord);
                }
            }
        }
        for (const auto& w : visitedThisLevel) {
            wordSet.erase(w);
        }
    }

    return result;
}

