std::vector<std::vector<char>> solve(std::vector<std::vector<char>>& board) {
    if (board.empty() || board[0].empty()) return board;
    int rows = static_cast<int>(board.size());
    int cols = static_cast<int>(board[0].size());
    std::function<void(int, int)> dfs = [&](int r, int c) {
        if (r < 0 || r >= rows || c < 0 || c >= cols || board[r][c] != 'O') return;
        board[r][c] = 'N';
        dfs(r - 1, c);
        dfs(r + 1, c);
        dfs(r, c - 1);
        dfs(r, c + 1);
    };
    for (int i = 0; i < rows; ++i) {
        dfs(i, 0);
        dfs(i, cols - 1);
    }
    for (int j = 0; j < cols; ++j) {
        dfs(0, j);
        dfs(rows - 1, j);
    }
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            if (board[i][j] == 'O') board[i][j] = 'X';
            else if (board[i][j] == 'N') board[i][j] = 'O';
        }
    }
    return board;
}

