std::vector<std::vector<std::string>> partition(const std::string& s) {
    std::vector<std::vector<std::string>> result;
    auto isPalindrome = [&](const std::string& str) -> bool {
        int l = 0;
        int r = static_cast<int>(str.size()) - 1;
        while (l < r) {
            if (str[l] != str[r]) return false;
            ++l;
            --r;
        }
        return true;
    };
    std::function<void(int, std::vector<std::string>&)> backtrack = [&](int start, std::vector<std::string>& path) {
        if (start == static_cast<int>(s.size())) {
            result.push_back(path);
            return;
        }
        for (int i = 1; i <= static_cast<int>(s.size()) - start; ++i) {
            std::string substring = s.substr(start, i);
            if (isPalindrome(substring)) {
                path.push_back(substring);
                backtrack(start + i, path);
                path.pop_back();
            }
        }
    };
    std::vector<std::string> path;
    backtrack(0, path);
    return result;
}

