int minCut(const std::string& s) {
    if (s.empty()) return 0;
    int n = static_cast<int>(s.size());
    std::vector<std::vector<bool>> isPalindrome(n, std::vector<bool>(n, false));
    for (int i = 0; i < n; ++i) {
        isPalindrome[i][i] = true;
    }
    for (int length = 2; length <= n; ++length) {
        for (int i = 0; i <= n - length; ++i) {
            int j = i + length - 1;
            if (length == 2) {
                isPalindrome[i][j] = (s[i] == s[j]);
            } else {
                isPalindrome[i][j] = (s[i] == s[j] && isPalindrome[i + 1][j - 1]);
            }
        }
    }
    std::vector<int> minCuts(n);
    minCuts[0] = 0;
    for (int i = 1; i < n; ++i) {
        int min = i;
        for (int j = 0; j <= i; ++j) {
            if (isPalindrome[j][i]) {
                if (j == 0) {
                    min = 0;
                } else if (minCuts[j - 1] + 1 < min) {
                    min = minCuts[j - 1] + 1;
                }
            }
        }
        minCuts[i] = min;
    }
    return minCuts[n - 1];
}

