std::vector<std::string> wordBreak(const std::string& s, const std::vector<std::string>& wordDict) {
    std::unordered_set<std::string> wordSet(wordDict.begin(), wordDict.end());
    std::unordered_map<int, std::vector<std::vector<std::string>>> memo;
    std::function<std::vector<std::vector<std::string>>(int)> backtrack = [&](int start) -> std::vector<std::vector<std::string>> {
        if (start == static_cast<int>(s.size())) return {{}};
        auto it = memo.find(start);
        if (it != memo.end()) return it->second;
        std::vector<std::vector<std::string>> result;
        for (int end = start + 1; end <= static_cast<int>(s.size()); ++end) {
            std::string word = s.substr(start, end - start);
            if (wordSet.find(word) != wordSet.end()) {
                std::vector<std::vector<std::string>> nextWords = backtrack(end);
                for (auto& nextWord : nextWords) {
                    if (nextWord.empty()) {
                        result.push_back({word});
                    } else {
                        std::vector<std::string> combined;
                        combined.reserve(1 + nextWord.size());
                        combined.push_back(word);
                        combined.insert(combined.end(), nextWord.begin(), nextWord.end());
                        result.push_back(std::move(combined));
                    }
                }
            }
        }
        memo[start] = result;
        return result;
    };
    std::vector<std::vector<std::string>> sentences = backtrack(0);
    std::vector<std::string> result;
    result.reserve(sentences.size());
    for (auto& sentence : sentences) {
        std::string joined;
        for (size_t i = 0; i < sentence.size(); ++i) {
            if (i) joined.push_back(' ');
            joined += sentence[i];
        }
        result.push_back(std::move(joined));
    }
    return result;
}

