std::function<int(const std::string&, int, int)> LRUCache(int capacity) {
    struct Node { int key; int value; Node* prev; Node* next; };
    std::unordered_map<int, Node*> cache;
    Node* head = new Node{0, 0, nullptr, nullptr};
    Node* tail = new Node{0, 0, nullptr, nullptr};
    head->next = tail;
    tail->prev = head;
    int size = 0;

    auto remove = [&](Node* node) {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    };
    auto add = [&](Node* node) {
        node->prev = tail->prev;
        node->next = tail;
        tail->prev->next = node;
        tail->prev = node;
    };

    return [=, &cache, &size, remove, add](const std::string& operation, int key, int value) mutable -> int {
        if (operation == "get") {
            auto it = cache.find(key);
            if (it != cache.end()) {
                Node* node = it->second;
                remove(node);
                add(node);
                return node->value;
            } else {
                return -1;
            }
        } else if (operation == "put") {
            auto it = cache.find(key);
            if (it != cache.end()) {
                Node* node = it->second;
                node->value = value;
                remove(node);
                add(node);
            } else {
                Node* node = new Node{key, value, nullptr, nullptr};
                cache[key] = node;
                add(node);
                ++size;
                if (size > capacity) {
                    Node* lruNode = head->next;
                    cache.erase(lruNode->key);
                    remove(lruNode);
                    delete lruNode;
                    --size;
                }
            }
            return 0;
        }
        return -1;
    };
}

