static std::string calculateSlope(const std::vector<int>& point1, const std::vector<int>& point2) {
    int xDiff = point2[0] - point1[0];
    int yDiff = point2[1] - point1[1];
    if (xDiff == 0) return "inf";
    double slope = static_cast<double>(yDiff) / xDiff;
    return std::to_string(slope);
}

int maxPoints(const std::vector<std::vector<int>>& points) {
    if (points.empty()) return 0;
    int maxPoints = 0;
    int n = static_cast<int>(points.size());
    for (int i = 0; i < n; ++i) {
        std::unordered_map<std::string, int> slopeMap;
        int samePoint = 1;
        for (int j = i + 1; j < n; ++j) {
            if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                ++samePoint;
            } else {
                std::string slope = calculateSlope(points[i], points[j]);
                ++slopeMap[slope];
            }
        }
        int localMax = 0;
        for (const auto& kv : slopeMap) {
            if (kv.second > localMax) localMax = kv.second;
        }
        maxPoints = std::max(maxPoints, localMax + samePoint);
    }
    return maxPoints;
}

