int evalRPN(const std::vector<std::string>& tokens) {
    std::vector<int> stack;
    for (size_t i = 0; i < tokens.size(); ++i) {
        const std::string& token = tokens[i];
        if (token == "+" || token == "-" || token == "*" || token == "/") {
            int num2 = stack.back(); stack.pop_back();
            int num1 = stack.back(); stack.pop_back();
            if (token == "+") stack.push_back(num1 + num2);
            else if (token == "-") stack.push_back(num1 - num2);
            else if (token == "*") stack.push_back(num1 * num2);
            else stack.push_back(num1 / num2);
        } else {
            stack.push_back(std::stoi(token));
        }
    }
    return stack[0];
}

