std::string reverseWords(const std::string& s) {
    size_t start = 0;
    while (start < s.size() && std::isspace(static_cast<unsigned char>(s[start]))) ++start;
    size_t end = s.size();
    while (end > start && std::isspace(static_cast<unsigned char>(s[end - 1]))) --end;
    std::string trimmed = s.substr(start, end - start);
    std::vector<std::string> words;
    size_t i = 0;
    while (i < trimmed.size()) {
        size_t j = i;
        while (j < trimmed.size() && !std::isspace(static_cast<unsigned char>(trimmed[j]))) ++j;
        words.emplace_back(trimmed.substr(i, j - i));
        i = j;
        while (i < trimmed.size() && std::isspace(static_cast<unsigned char>(trimmed[i]))) ++i;
    }
    std::reverse(words.begin(), words.end());
    std::string result;
    for (size_t k = 0; k < words.size(); ++k) {
        if (k) result.push_back(' ');
        result += words[k];
    }
    return result;
}

