int maxProduct(const std::vector<int>& nums) {
    int maxSoFar = nums[0];
    int minSoFar = nums[0];
    int result = nums[0];
    for (size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] < 0) {
            int temp = maxSoFar;
            maxSoFar = minSoFar;
            minSoFar = temp;
        }
        maxSoFar = std::max(nums[i], maxSoFar * nums[i]);
        minSoFar = std::min(nums[i], minSoFar * nums[i]);
        result = std::max(result, maxSoFar);
    }
    return result;
}

