int findMin(const std::vector<int>& nums) {
    int left = 0;
    int right = static_cast<int>(nums.size()) - 1;
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] > nums[right]) {
            left = mid + 1;
        } else if (nums[mid] < nums[right]) {
            right = mid;
        } else {
            --right;
        }
    }
    return nums[left];
}

class MinStack {
    std::vector<std::pair<int,int>> st; // (value, current min at this point)
public:
    void push(int x) {
        int newMin = st.empty() ? x : std::min(x, st.back().second);
        st.push_back({x, newMin});
    }
    void pop() {
        st.pop_back();
    }
    int top() {
        return st.back().first;
    }
    int getMin() {
        return st.back().second;
    }
};

