struct ListNode {
    int val;
    ListNode *next;
    ListNode(int x) : val(x), next(nullptr) {}
};

ListNode* getIntersectionNode(ListNode* headA, ListNode* headB) {
    int lengthA = 0;
    ListNode* tempA = headA;
    while (tempA != nullptr) {
        ++lengthA;
        tempA = tempA->next;
    }
    int lengthB = 0;
    ListNode* tempB = headB;
    while (tempB != nullptr) {
        ++lengthB;
        tempB = tempB->next;
    }
    int diff = std::abs(lengthA - lengthB);
    if (lengthA > lengthB) {
        for (int i = 0; i < diff; ++i) {
            headA = headA->next;
        }
    } else {
        for (int i = 0; i < diff; ++i) {
            headB = headB->next;
        }
    }
    while (headA != nullptr && headB != nullptr) {
        if (headA == headB) {
            return headA;
        }
        headA = headA->next;
        headB = headB->next;
    }
    return nullptr;
}

