int maximumGap(const std::vector<int>& nums) {
    if (nums.size() < 2) return 0;
    int minVal = *std::min_element(nums.begin(), nums.end());
    int maxVal = *std::max_element(nums.begin(), nums.end());
    if (minVal == maxVal) return 0;
    int bucketSize = std::max(1, (maxVal - minVal) / static_cast<int>(nums.size() - 1));
    int bucketCount = (maxVal - minVal) / bucketSize + 1;
    struct Bucket { int min; int max; };
    std::vector<Bucket> buckets(bucketCount, {INT_MAX, INT_MIN});
    for (int num : nums) {
        int index = (num - minVal) / bucketSize;
        buckets[index].min = std::min(buckets[index].min, num);
        buckets[index].max = std::max(buckets[index].max, num);
    }
    int maxGap = 0;
    int prevMax = buckets[0].max;
    for (int i = 1; i < bucketCount; ++i) {
        if (buckets[i].min != INT_MAX) {
            maxGap = std::max(maxGap, buckets[i].min - prevMax);
            prevMax = buckets[i].max;
        }
    }
    return maxGap;
}

