int compareVersion(const std::string& version1, const std::string& version2) {
    auto splitToInts = [](const std::string& version) {
        std::vector<int> result;
        std::stringstream ss(version);
        std::string token;
        while (std::getline(ss, token, '.')) {
            result.push_back(std::stoi(token));
        }
        return result;
    };
    std::vector<int> revisions1 = splitToInts(version1);
    std::vector<int> revisions2 = splitToInts(version2);
    std::size_t maxRevisions = std::max(revisions1.size(), revisions2.size());
    for (std::size_t i = 0; i < maxRevisions; ++i) {
        int revision1 = i < revisions1.size() ? revisions1[i] : 0;
        int revision2 = i < revisions2.size() ? revisions2[i] : 0;
        if (revision1 != revision2) {
            return revision1 < revision2 ? -1 : 1;
        }
    }
    return 0;
}

