std::vector<int> twoSum(const std::vector<int>& numbers, int target) {
    int left = 0;
    int right = static_cast<int>(numbers.size()) - 1;
    while (left < right) {
        int sum = numbers[left] + numbers[right];
        if (sum == target) {
            return std::vector<int>{left + 1, right + 1};
        } else if (sum < target) {
            ++left;
        } else {
            --right;
        }
    }
    return std::vector<int>{};
}

