int maxProfit(int k, const std::vector<int>& prices) {
    int n = static_cast<int>(prices.size());
    if (n == 0) return 0;
    if (k >= n / 2) {
        int total = 0;
        for (int i = 1; i < n; ++i) {
            if (prices[i] > prices[i - 1]) total += prices[i] - prices[i - 1];
        }
        return total;
    }
    std::vector<int> buy(k + 1, INT_MIN);
    std::vector<int> sell(k + 1, 0);
    for (int price : prices) {
        for (int t = 1; t <= k; ++t) {
            buy[t] = std::max(buy[t], sell[t - 1] - price);
            sell[t] = std::max(sell[t], buy[t] + price);
        }
    }
    return sell[k];
}

