std::vector<int> rotateArray(std::vector<int>& nums, int k) {
    if (nums.empty()) return nums;
    k = k % nums.size();
    std::vector<int> tmp;
    tmp.reserve(nums.size());
    tmp.insert(tmp.end(), nums.end() - k, nums.end());
    tmp.insert(tmp.end(), nums.begin(), nums.end() - k);
    nums = std::move(tmp);
    return nums;
}

