std::string fractionToDecimal(long long numerator, long long denominator) {
    if (denominator == 0) return "";
    std::string result;
    if ((numerator < 0) ^ (denominator < 0)) result += "-";
    long long n = std::llabs(numerator);
    long long d = std::llabs(denominator);
    result += std::to_string(n / d);
    long long remainder = n % d;
    if (remainder == 0) return result;
    result += ".";
    std::unordered_map<long long, std::size_t> map;
    std::string fractionalPart;
    while (remainder != 0) {
        if (map.find(remainder) != map.end()) {
            std::size_t idx = map[remainder];
            fractionalPart = fractionalPart.substr(0, idx) + "(" + fractionalPart.substr(idx) + ")";
            break;
        }
        map[remainder] = fractionalPart.size();
        remainder *= 10;
        fractionalPart += std::to_string(remainder / d);
        remainder %= d;
    }
    result += fractionalPart;
    return result;
}

