bool isHappy(int n) {
    std::unordered_set<int> seen;
    while (n != 1 && seen.find(n) == seen.end()) {
        seen.insert(n);
        int sum = 0;
        for (char c : std::to_string(n)) {
            int digit = c - '0';
            sum += digit * digit;
        }
        n = sum;
    }
    return n == 1;
}

