int countPrimes(int n) {
    std::vector<bool> prime(n, true);
    if (n > 0) prime[0] = false;
    if (n > 1) prime[1] = false;
    for (int p = 2; p * p < n; ++p) {
        if (prime[p]) {
            for (int i = p * p; i < n; i += p) {
                prime[i] = false;
            }
        }
    }
    int count = 0;
    for (int i = 0; i < n; ++i) {
        if (prime[i]) {
            ++count;
        }
    }
    return count;
}

