bool isIsomorphic(const std::string& s, const std::string& t) {
    if (s.size() != t.size()) {
        return false;
    }
    std::unordered_map<char, char> sToTMap;
    std::unordered_map<char, char> tToSMap;
    for (size_t i = 0; i < s.size(); ++i) {
        char cs = s[i];
        char ct = t[i];
        auto itS = sToTMap.find(cs);
        if (itS == sToTMap.end()) {
            if (tToSMap.find(ct) != tToSMap.end()) {
                return false;
            }
            sToTMap[cs] = ct;
            tToSMap[ct] = cs;
        } else if (itS->second != ct) {
            return false;
        }
    }
    return true;
}

