std::string shortestPalindrome(const std::string& s) {
    std::string reversed(s.rbegin(), s.rend());
    std::string combined = s + "#" + reversed;
    std::vector<int> prefixSuffixLengths(combined.size(), 0);
    int prefixLength = 0;
    for (size_t i = 1; i < combined.size(); ++i) {
        while (prefixLength > 0 && combined[i] != combined[prefixLength]) {
            prefixLength = prefixSuffixLengths[prefixLength - 1];
        }
        if (combined[i] == combined[prefixLength]) {
            ++prefixLength;
        }
        prefixSuffixLengths[i] = prefixLength;
    }
    int maxLength = prefixSuffixLengths[combined.size() - 1];
    size_t addLen = s.size() - static_cast<size_t>(maxLength);
    return reversed.substr(0, addLen) + s;
}

