int rob(const std::vector<int>& nums) {
    if (nums.size() == 1) return nums[0];
    if (nums.size() == 2) return std::max(nums[0], nums[1]);

    std::vector<int> maxAmount1(nums.size(), 0);
    maxAmount1[0] = nums[0];
    maxAmount1[1] = std::max(nums[0], nums[1]);
    for (size_t i = 2; i < nums.size() - 1; ++i) {
        maxAmount1[i] = std::max(maxAmount1[i - 1], maxAmount1[i - 2] + nums[i]);
    }

    std::vector<int> maxAmount2(nums.size(), 0);
    maxAmount2[0] = 0;
    maxAmount2[1] = nums[1];
    for (size_t i = 2; i < nums.size(); ++i) {
        maxAmount2[i] = std::max(maxAmount2[i - 1], maxAmount2[i - 2] + nums[i]);
    }

    return std::max(maxAmount1[nums.size() - 2], maxAmount2[nums.size() - 1]);
}

