int partition(std::vector<int>& nums, int left, int right, int pivotIndex) {
    int pivotValue = nums[pivotIndex];
    std::swap(nums[pivotIndex], nums[right]);
    int storeIndex = left;
    for (int i = left; i < right; ++i) {
        if (nums[i] < pivotValue) {
            std::swap(nums[storeIndex], nums[i]);
            ++storeIndex;
        }
    }
    std::swap(nums[storeIndex], nums[right]);
    return storeIndex;
}

int quickselect(std::vector<int>& nums, int left, int right, int kSmallest) {
    while (true) {
        if (left == right) {
            return nums[left];
        }
        int pivotIndex = left + std::rand() % (right - left + 1);
        pivotIndex = partition(nums, left, right, pivotIndex);
        if (kSmallest == pivotIndex) {
            return nums[kSmallest];
        } else if (kSmallest < pivotIndex) {
            right = pivotIndex - 1;
        } else {
            left = pivotIndex + 1;
        }
    }
}

int findKthLargest(std::vector<int>& nums, int k) {
    return quickselect(nums, 0, static_cast<int>(nums.size()) - 1, static_cast<int>(nums.size()) - k);
}

