auto WordDictionary() {
    struct Node {
        std::unordered_map<char, Node*> child;
        bool isEnd = false;
    };
    Node* root = new Node();

    std::function<void(const std::string&)> addWord = [root](const std::string& word) {
        Node* node = root;
        for (char c : word) {
            if (!node->child.count(c)) node->child[c] = new Node();
            node = node->child[c];
        }
        node->isEnd = true;
    };

    std::function<bool(const std::string&)> search = [root](const std::string& word) {
        std::function<bool(Node*, int)> dfs = [&](Node* node, int idx) -> bool {
            if (idx == (int)word.size()) return node->isEnd;
            char c = word[idx];
            if (c == '.') {
                for (auto& kv : node->child) {
                    if (dfs(kv.second, idx + 1)) return true;
                }
                return false;
            } else {
                if (!node->child.count(c)) return false;
                return dfs(node->child[c], idx + 1);
            }
        };
        return dfs(root, 0);
    };

    struct Dict {
        std::function<void(const std::string&)> addWord;
        std::function<bool(const std::string&)> search;
    };
    return Dict{addWord, search};
}

