struct TrieNode {
    TrieNode* child[26];
    std::string word;
    TrieNode() {
        std::memset(child, 0, sizeof(child));
    }
};

static void dfs(int i, int j, TrieNode* node, std::vector<std::vector<char>>& board, std::vector<std::string>& result) {
    char c = board[i][j];
    int idx = c - 'a';
    TrieNode* next = node->child[idx];
    if (!next) return;
    if (!next->word.empty()) {
        result.push_back(next->word);
        next->word.clear();
    }
    board[i][j] = '#';
    static const int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
    int m = board.size();
    int n = board[0].size();
    for (int d = 0; d < 4; ++d) {
        int ni = i + dirs[d][0];
        int nj = j + dirs[d][1];
        if (ni >= 0 && ni < m && nj >= 0 && nj < n && board[ni][nj] != '#') {
            dfs(ni, nj, next, board, result);
        }
    }
    board[i][j] = c;
}

std::vector<std::string> findWords(std::vector<std::vector<char>> board, const std::vector<std::string>& words) {
    TrieNode* root = new TrieNode();
    for (const std::string& w : words) {
        TrieNode* node = root;
        for (char ch : w) {
            int idx = ch - 'a';
            if (!node->child[idx]) node->child[idx] = new TrieNode();
            node = node->child[idx];
        }
        node->word = w;
    }
    std::vector<std::string> result;
    int m = board.size();
    if (m == 0) return result;
    int n = board[0].size();
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            dfs(i, j, root, board, result);
        }
    }
    std::sort(result.begin(), result.end());
    return result;
}

