bool containsNearbyAlmostDuplicate(const std::vector<int>& nums, int indexDiff, int valueDiff) {
    if (valueDiff < 0) return false;
    long long bucketSize = static_cast<long long>(valueDiff) + 1LL;
    std::unordered_map<long long, long long> buckets;
    for (std::size_t i = 0; i < nums.size(); ++i) {
        long long num = static_cast<long long>(nums[i]);
        long long bucketIndex = num / bucketSize;
        if (num < 0 && num % bucketSize != 0) {
            --bucketIndex;
        }
        if (buckets.find(bucketIndex) != buckets.end()) {
            return true;
        }
        auto itPrev = buckets.find(bucketIndex - 1);
        if (itPrev != buckets.end() && std::llabs(num - itPrev->second) <= valueDiff) {
            return true;
        }
        auto itNext = buckets.find(bucketIndex + 1);
        if (itNext != buckets.end() && std::llabs(num - itNext->second) <= valueDiff) {
            return true;
        }
        buckets[bucketIndex] = num;
        if (i >= static_cast<std::size_t>(indexDiff)) {
            long long oldNum = static_cast<long long>(nums[i - indexDiff]);
            long long oldBucketIndex = oldNum / bucketSize;
            if (oldNum < 0 && oldNum % bucketSize != 0) {
                --oldBucketIndex;
            }
            buckets.erase(oldBucketIndex);
        }
    }
    return false;
}

