std::vector<std::vector<int>> combinationSum3(int k, int n) {
    std::vector<std::vector<int>> result;
    std::function<void(int, std::vector<int>&, int)> backtrack = [&](int start, std::vector<int>& path, int target) {
        if (static_cast<int>(path.size()) == k && target == 0) {
            result.push_back(path);
        } else {
            for (int i = start; i <= 9; ++i) {
                if (i > target) break;
                path.push_back(i);
                backtrack(i + 1, path, target - i);
                path.pop_back();
            }
        }
    };
    std::vector<int> path;
    backtrack(1, path, n);
    return result;
}

