int maximalSquare(const std::vector<std::vector<char>>& matrix) {
    int rows = static_cast<int>(matrix.size());
    if (rows == 0) return 0;
    int cols = static_cast<int>(matrix[0].size());

    std::vector<std::vector<int>> dp(rows, std::vector<int>(cols));
    int maxSize = 0;

    for (int i = 0; i < rows; ++i) {
        dp[i][0] = (matrix[i][0] == '1') ? 1 : 0;
        maxSize = std::max(maxSize, dp[i][0]);
    }
    for (int j = 0; j < cols; ++j) {
        dp[0][j] = (matrix[0][j] == '1') ? 1 : 0;
        maxSize = std::max(maxSize, dp[0][j]);
    }

    for (int i = 1; i < rows; ++i) {
        for (int j = 1; j < cols; ++j) {
            if (matrix[i][j] == '1') {
                dp[i][j] = std::min({dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]}) + 1;
                maxSize = std::max(maxSize, dp[i][j]);
            }
        }
    }

    return maxSize * maxSize;
}

