std::vector<std::vector<int>> getSkyline(const std::vector<std::vector<int>>& buildings) {
    std::vector<std::pair<int, int>> criticalPoints;
    for (const auto& building : buildings) {
        criticalPoints.emplace_back(building[0], -building[2]);
        criticalPoints.emplace_back(building[1], building[2]);
    }
    std::sort(criticalPoints.begin(), criticalPoints.end(),
        [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
            if (a.first != b.first) return a.first < b.first;
            return a.second < b.second;
        });
    std::vector<std::vector<int>> result;
    int currentHeight = 0;
    std::vector<int> heights;
    heights.push_back(0);
    for (const auto& point : criticalPoints) {
        if (point.second < 0) {
            heights.push_back(-point.second);
        } else {
            auto it = std::find(heights.begin(), heights.end(), point.second);
            if (it != heights.end()) {
                heights.erase(it);
            }
        }
        int newHeight = *std::max_element(heights.begin(), heights.end());
        if (newHeight != currentHeight) {
            result.push_back({point.first, newHeight});
            currentHeight = newHeight;
        }
    }
    return result;
}

