struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

int countNodes(TreeNode* root) {
    int height = 0;
    TreeNode* node = root;
    while (node) {
        ++height;
        node = node->left;
    }
    if (height == 0) return 0;
    if (height == 1) return 1;
    long long left = 1;
    long long right = 1LL << (height - 1);
    while (left <= right) {
        long long mid = (left + right) / 2;
        TreeNode* cur = root;
        long long path = mid;
        for (int i = height - 2; i >= 0; --i) {
            cur = (path & (1LL << i)) ? cur->right : cur->left;
            if (!cur) break;
        }
        if (cur) left = mid + 1;
        else right = mid - 1;
    }
    return static_cast<int>((1LL << (height - 1)) - 1 + left);
}

