long long computeArea(long long ax1, long long ay1, long long ax2, long long ay2,
                      long long bx1, long long by1, long long bx2, long long by2) {
    long long areaA = (ax2 - ax1) * (ay2 - ay1);
    long long areaB = (bx2 - bx1) * (by2 - by1);
    long long overlapX = std::max(0LL, std::min(ax2, bx2) - std::max(ax1, bx1));
    long long overlapY = std::max(0LL, std::min(ay2, by2) - std::max(ay1, by1));
    long long overlapArea = overlapX * overlapY;
    return areaA + areaB - overlapArea;
}

