int calculate(const std::string& s) {
    std::vector<int> stack;
    int sign = 1;
    int result = 0;
    int num = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c >= '0' && c <= '9') {
            num = num * 10 + (c - '0');
        } else if (c == '+' || c == '-') {
            result += sign * num;
            num = 0;
            sign = (c == '+') ? 1 : -1;
        } else if (c == ' ') {
            continue;
        }
    }
    result += sign * num;
    return result;
}

