int calculate(const std::string& s) {
    std::vector<int> stack;
    int num = 0;
    char sign = '+';
    int n = static_cast<int>(s.size());
    for (int i = 0; i < n; ++i) {
        char c = s[i];
        if (std::isdigit(c)) {
            num = num * 10 + (c - '0');
        }
        if ((!std::isdigit(c) && !std::isspace(c)) || i == n - 1) {
            if (sign == '+') {
                stack.push_back(num);
            } else if (sign == '-') {
                stack.push_back(-num);
            } else if (sign == '*') {
                int prev = stack.back();
                stack.back() = prev * num;
            } else if (sign == '/') {
                int prev = stack.back();
                stack.back() = prev / num;
            }
            sign = c;
            num = 0;
        }
    }
    int result = 0;
    for (int v : stack) {
        result += v;
    }
    return result;
}

