std::vector<int> majorityElement(const std::vector<int>& nums) {
    int count1 = 0, count2 = 0;
    int candidate1 = 0, candidate2 = 0;
    for (int num : nums) {
        if (num == candidate1) {
            ++count1;
        } else if (num == candidate2) {
            ++count2;
        } else if (count1 == 0) {
            candidate1 = num;
            count1 = 1;
        } else if (count2 == 0) {
            candidate2 = num;
            count2 = 1;
        } else {
            --count1;
            --count2;
        }
    }
    int actualCount1 = 0, actualCount2 = 0;
    for (int num : nums) {
        if (num == candidate1) ++actualCount1;
        if (num == candidate2) ++actualCount2;
    }
    std::vector<int> result;
    int n = static_cast<int>(nums.size());
    if (actualCount1 > n / 3) result.push_back(candidate1);
    if (actualCount2 > n / 3) result.push_back(candidate2);
    return result;
}

