int countDigitOne(int n) {
    long long count = 0;
    for (long long i = 1; i <= n; i *= 10) {
        long long divider = i * 10;
        count += (n / divider) * i + std::min(std::max((long long)n % divider - i + 1, 0LL), i);
    }
    return static_cast<int>(count);
}

