std::vector<int> diffWaysToCompute(const std::string& expression) {
    std::unordered_map<std::string, std::vector<int>> memo;
    std::function<std::vector<int>(const std::string&)> compute = [&](const std::string& expr) -> std::vector<int> {
        auto it = memo.find(expr);
        if (it != memo.end()) return it->second;
        bool isNumber = true;
        for (char c : expr) {
            if (c == '+' || c == '-' || c == '*') {
                isNumber = false;
                break;
            }
        }
        if (isNumber) {
            return std::vector<int>{std::stoi(expr)};
        }
        std::vector<int> results;
        for (size_t i = 0; i < expr.size(); ++i) {
            char op = expr[i];
            if (op == '+' || op == '-' || op == '*') {
                std::vector<int> leftResults = compute(expr.substr(0, i));
                std::vector<int> rightResults = compute(expr.substr(i + 1));
                for (int left : leftResults) {
                    for (int right : rightResults) {
                        if (op == '+') results.push_back(left + right);
                        else if (op == '-') results.push_back(left - right);
                        else results.push_back(left * right);
                    }
                }
            }
        }
        memo[expr] = results;
        return results;
    };
    std::vector<int> ans = compute(expression);
    std::sort(ans.begin(), ans.end());
    return ans;
}

