bool isAnagram(const std::string& s, const std::string& t) {
    if (s.length() != t.length()) return false;
    std::unordered_map<char, int> charFrequency;
    for (char c : s) ++charFrequency[c];
    for (char c : t) {
        auto it = charFrequency.find(c);
        if (it == charFrequency.end() || it->second == 0) return false;
        --it->second;
    }
    return true;
}

