std::vector<std::string> binaryTreePaths(TreeNode* root) {
    std::vector<std::string> result;
    std::function<void(TreeNode*, const std::string&)> dfs = [&](TreeNode* node, const std::string& path) {
        if (!node->left && !node->right) {
            result.push_back(path);
        }
        if (node->left) {
            dfs(node->left, path + "->" + std::to_string(node->left->val));
        }
        if (node->right) {
            dfs(node->right, path + "->" + std::to_string(node->right->val));
        }
    };
    if (root) {
        dfs(root, std::to_string(root->val));
    }
    return result;
}

