std::vector<int> singleNumber(const std::vector<int>& nums) {
    int xorResult = 0;
    for (int num : nums) {
        xorResult ^= num;
    }
    int rightmostSetBit = xorResult & -xorResult;
    int singleNumber1 = 0, singleNumber2 = 0;
    for (int num : nums) {
        if (num & rightmostSetBit) {
            singleNumber1 ^= num;
        } else {
            singleNumber2 ^= num;
        }
    }
    return {singleNumber1, singleNumber2};
}

