int nthUglyNumber(int n) {
    std::vector<long long> uglyNumbers;
    uglyNumbers.reserve(n);
    uglyNumbers.push_back(1);
    std::size_t i2 = 0, i3 = 0, i5 = 0;
    while (uglyNumbers.size() < static_cast<std::size_t>(n)) {
        long long next2 = uglyNumbers[i2] * 2;
        long long next3 = uglyNumbers[i3] * 3;
        long long next5 = uglyNumbers[i5] * 5;
        long long nextUgly = std::min({next2, next3, next5});
        uglyNumbers.push_back(nextUgly);
        if (nextUgly == next2) ++i2;
        if (nextUgly == next3) ++i3;
        if (nextUgly == next5) ++i5;
    }
    return static_cast<int>(uglyNumbers[n - 1]);
}

