static std::string helper(int num, const std::vector<std::string>& ones, const std::vector<std::string>& tens) {
    std::string result;
    if (num >= 100) {
        result += ones[num / 100] + " Hundred ";
        num %= 100;
    }
    if (num >= 20) {
        result += tens[num / 10] + " ";
        num %= 10;
    }
    if (num > 0) {
        result += ones[num];
    }
    return trim(result);
}

std::string numberToWords(int num) {
    static const std::vector<std::string> ones = {"", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"};
    static const std::vector<std::string> tens = {"", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"};
    static const std::vector<std::string> thousands = {"", "Thousand", "Million", "Billion"};

    if (num == 0) return "Zero";

    std::string result;
    int i = 0;
    while (num > 0) {
        if (num % 1000 != 0) {
            std::string segment = helper(num % 1000, ones, tens);
            result = segment + " " + thousands[i] + " " + result;
        }
        num /= 1000;
        ++i;
    }
    return trim(result);
}

