int hIndex(const std::vector<int>& citations) {
    int left = 0;
    int right = static_cast<int>(citations.size()) - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        int h = std::min(citations[mid], static_cast<int>(citations.size() - mid));
        if (h == citations[mid]) return h;
        else if (h < citations[mid]) left = mid + 1;
        else right = mid - 1;
    }
    return static_cast<int>(citations.size() - left);
}

