#include <string>
#include <functional>

std::vector<std::string> addOperators(const std::string& num, long long target) {
    std::vector<std::string> result;
    std::function<void(int, const std::string&, long long, long long)> backtrack =
        [&](int index, const std::string& path, long long value, long long prev) {
            if (index == static_cast<int>(num.size())) {
                if (value == target) {
                    result.push_back(path);
                }
                return;
            }
            for (int i = index; i < static_cast<int>(num.size()); ++i) {
                if (i != index && num[index] == '0') break;
                std::string str = num.substr(index, i - index + 1);
                long long curr = std::stoll(str);
                if (index == 0) {
                    backtrack(i + 1, str, curr, curr);
                } else {
                    backtrack(i + 1, path + "*" + str, value - prev + prev * curr, prev * curr);
                    backtrack(i + 1, path + "+" + str, value + curr, curr);
                    backtrack(i + 1, path + "-" + str, value - curr, -curr);
                }
            }
        };
    backtrack(0, "", 0, 0);
    return result;
}

