template <typename Iterator>
auto PeekingIterator(Iterator begin, Iterator end) {
    using Value = typename std::iterator_traits<Iterator>::value_type;
    struct Wrapper {
        Iterator it;
        Iterator end;
        std::unique_ptr<Value> peeked;
        bool hasNext() const {
            return peeked != nullptr || it != end;
        }
        Value peek() {
            if (!peeked) {
                peeked = std::make_unique<Value>(*it);
            }
            return *peeked;
        }
        Value next() {
            if (peeked) {
                Value val = *peeked;
                peeked.reset();
                ++it;
                return val;
            }
            Value val = *it;
            ++it;
            return val;
        }
    };
    return Wrapper{begin, end, nullptr};
}

