bool wordPattern(const std::string& pattern, const std::string& s) {
    std::vector<std::string> words;
    std::istringstream iss(s);
    std::string token;
    while (iss >> token) {
        words.push_back(token);
    }
    if (pattern.size() != words.size()) return false;
    std::unordered_map<char, std::string> patternToWord;
    std::unordered_map<std::string, char> wordToPattern;
    for (size_t i = 0; i < pattern.size(); ++i) {
        char p = pattern[i];
        const std::string& w = words[i];
        auto itP = patternToWord.find(p);
        auto itW = wordToPattern.find(w);
        if (itP == patternToWord.end() && itW == wordToPattern.end()) {
            patternToWord[p] = w;
            wordToPattern[w] = p;
        } else {
            if (itP == patternToWord.end() || itW == wordToPattern.end()) return false;
            if (itP->second != w || itW->second != p) return false;
        }
    }
    return true;
}

