std::vector<double> MedianFinder(const std::vector<int>& nums) {
    std::priority_queue<int> maxHeap; // smaller half (max-heap)
    std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap; // larger half (min-heap)
    std::vector<double> medians;
    medians.reserve(nums.size());
    for (int num : nums) {
        if (maxHeap.empty() || num <= maxHeap.top()) {
            maxHeap.push(num);
        } else {
            minHeap.push(num);
        }
        if (maxHeap.size() > minHeap.size() + 1) {
            minHeap.push(maxHeap.top());
            maxHeap.pop();
        } else if (minHeap.size() > maxHeap.size()) {
            maxHeap.push(minHeap.top());
            minHeap.pop();
        }
        if (maxHeap.size() > minHeap.size()) {
            medians.push_back(static_cast<double>(maxHeap.top()));
        } else {
            medians.push_back((static_cast<double>(maxHeap.top()) + static_cast<double>(minHeap.top())) / 2.0);
        }
    }
    return medians;
}

