int lengthOfLIS(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    std::vector<int> dp;
    dp.push_back(nums[0]);
    for (size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] > dp.back()) {
            dp.push_back(nums[i]);
        } else {
            int left = 0;
            int right = static_cast<int>(dp.size()) - 1;
            while (left < right) {
                int mid = (left + right) / 2;
                if (nums[i] > dp[mid]) {
                    left = mid + 1;
                } else {
                    right = mid;
                }
            }
            dp[left] = nums[i];
        }
    }
    return static_cast<int>(dp.size());
}

