bool isValid(const std::string& str) {
    int count = 0;
    for (char ch : str) {
        if (ch == '(') ++count;
        else if (ch == ')') --count;
        if (count < 0) return false;
    }
    return count == 0;
}

std::vector<std::string> removeInvalidParentheses(const std::string& s) {
    std::unordered_set<std::string> level;
    level.insert(s);
    while (true) {
        std::vector<std::string> valid;
        for (const auto& str : level) {
            if (isValid(str)) {
                valid.push_back(str);
            }
        }
        if (!valid.empty()) {
            return valid;
        }
        std::unordered_set<std::string> nextLevel;
        for (const auto& str : level) {
            for (size_t i = 0; i < str.size(); ++i) {
                if (str[i] == '(' || str[i] == ')') {
                    std::string nextStr = str.substr(0, i) + str.substr(i + 1);
                    nextLevel.insert(nextStr);
                }
            }
        }
        level.swap(nextLevel);
    }
}

