static bool backtrack(const std::string& num, int start, std::vector<std::string>& path) {
    if (start == static_cast<int>(num.size()) && path.size() >= 3) {
        return true;
    }
    for (int i = start; i < static_cast<int>(num.size()); ++i) {
        std::string currNum = num.substr(start, i - start + 1);
        if (isValid(currNum)) {
            if (path.size() < 2) {
                path.push_back(currNum);
                if (backtrack(num, i + 1, path)) {
                    return true;
                }
                path.pop_back();
            } else {
                long long a = std::stoll(path[path.size() - 2]);
                long long b = std::stoll(path[path.size() - 1]);
                long long c = std::stoll(currNum);
                if (c == a + b) {
                    path.push_back(currNum);
                    if (backtrack(num, i + 1, path)) {
                        return true;
                    }
                    path.pop_back();
                }
            }
        }
    }
    return false;
}

bool isAdditiveNumber(const std::string& num) {
