    long long sell = 0;
    long long cooldown = 0;
    for (size_t i = 0; i < prices.size(); ++i) {
        long long newBuy = std::max(buy, cooldown - prices[i]);
        long long newSell = std::max(sell, buy + prices[i]);
        long long newCooldown = std::max(cooldown, sell);
        buy = newBuy;
