std::string removeDuplicateLetters(const std::string& s) {
    std::unordered_map<char, int> countMap;
    for (size_t i = 0; i < s.length(); ++i) {
        countMap[s[i]]++;
    }

    std::unordered_set<char> resultSet;
    std::string result;

    for (size_t i = 0; i < s.length(); ++i) {
        char c = s[i];
        countMap[c]--;

        if (resultSet.find(c) != resultSet.end()) {
            continue;
        }

        while (!result.empty() && result.back() > c && countMap[result.back()] > 0) {
            resultSet.erase(result.back());
            result.pop_back();
        }

        resultSet.insert(c);
        result.push_back(c);
    }

    return result;
}

