std::vector<int> wiggleSort(std::vector<int> nums) {
    int n = static_cast<int>(nums.size());
    if (n <= 1) {
        return nums;
    }
    int midIdx = n / 2;
    std::nth_element(nums.begin(), nums.begin() + midIdx, nums.end());
    int median = nums[midIdx];

    auto virtualIndex = [n](int i) -> int {
        return (1 + 2 * i) % (n | 1);
    };

    int left = 0, i = 0, right = n - 1;
    while (i <= right) {
        int vi = virtualIndex(i);
        if (nums[vi] > median) {
            std::swap(nums[virtualIndex(left)], nums[vi]);
            ++left;
            ++i;
        } else if (nums[vi] < median) {
            std::swap(nums[vi], nums[virtualIndex(right)]);
            --right;
        } else {
            ++i;
        }
    }
    return nums;
}

