long long countRangeSum(const std::vector<int>& nums, int lower, int upper) {
    std::vector<long long> prefix(nums.size() + 1, 0);
    for (size_t i = 0; i < nums.size(); ++i) {
        prefix[i + 1] = prefix[i] + static_cast<long long>(nums[i]);
    }

    std::function<long long(int, int)> sortCount = [&](int left, int right) -> long long {
        if (right - left <= 1) return 0;
        int mid = left + (right - left) / 2;
        long long count = sortCount(left, mid) + sortCount(mid, right);
        int j = mid, k = mid;
        for (int i = left; i < mid; ++i) {
            while (k < right && prefix[k] - prefix[i] < lower) ++k;
            while (j < right && prefix[j] - prefix[i] <= upper) ++j;
            count += static_cast<long long>(j - k);
        }
        std::vector<long long> merged;
        merged.reserve(right - left);
        int p = left, q = mid;
        while (p < mid && q < right) {
            if (prefix[p] <= prefix[q]) merged.push_back(prefix[p++]);
            else merged.push_back(prefix[q++]);
        }
        while (p < mid) merged.push_back(prefix[p++]);
        while (q < right) merged.push_back(prefix[q++]);
        std::copy(merged.begin(), merged.end(), prefix.begin() + left);
        return count;
    };

    return sortCount(0, static_cast<int>(prefix.size()));
}

