int longestIncreasingPath(const std::vector<std::vector<int>>& matrix) {
    if (matrix.empty() || matrix[0].empty()) return 0;

    const int rows = static_cast<int>(matrix.size());
    const int cols = static_cast<int>(matrix[0].size());
    const std::vector<std::pair<int, int>> directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    std::vector<std::vector<int>> memo(rows, std::vector<int>(cols, 0));

    std::function<int(int, int)> dfs = [&](int row, int col) -> int {
        if (memo[row][col] != 0) return memo[row][col];
        int longest = 1;
        for (const auto& dir : directions) {
            int nr = row + dir.first;
            int nc = col + dir.second;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && matrix[nr][nc] > matrix[row][col]) {
                longest = std::max(longest, 1 + dfs(nr, nc));
            }
        }
        memo[row][col] = longest;
        return longest;
    };

    int maxLength = 0;
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            maxLength = std::max(maxLength, dfs(i, j));
        }
    }
    return maxLength;
}

