vector<vector<int>> palindromePairs(vector<string>& words) {
    unordered_map<string,int> idx;
    for (int i = 0; i < (int)words.size(); i++) idx[words[i]] = i;
    vector<vector<int>> result;
    for (int i = 0; i < (int)words.size(); i++) {
        string& w = words[i];
        int n = w.size();
        for (int cut = 0; cut <= n; cut++) {
            if (isPalindrome(w, cut, n-1)) {
                string leftRev = w.substr(0, cut);
                reverse(leftRev.begin(), leftRev.end());
                if (idx.count(leftRev) && idx[leftRev] != i) result.push_back({i, idx[leftRev]});
            }
            if (cut > 0 && isPalindrome(w, 0, cut-1)) {
                string rightRev = w.substr(cut);
                reverse(rightRev.begin(), rightRev.end());
                if (idx.count(rightRev) && idx[rightRev] != i) result.push_back({idx[rightRev], i});
            }
        }
    }
    return result;
}
