static std::pair<int, int> dfs(TreeNode* node) {
    if (!node) return {0, 0};
    auto left = dfs(node->left);
    auto right = dfs(node->right);
    int without = std::max(left.first, left.second) + std::max(right.first, right.second);
    int withNode = node->val + left.second + right.second;
    return {withNode, without};
}

int rob(TreeNode* root) {
