    std::unordered_map<int, std::vector<std::pair<int, int>>> tweets; // userId -> [(time, tweetId)]
    int time;
public:
    Twitter() : time(0) {}

    void postTweet(int userId, int tweetId) {
        tweets[userId].push_back({time++, tweetId});
    }

    std::vector<int> getNewsFeed(int userId) {
        std::vector<std::pair<int,int>> all;
        std::unordered_set<int> users = userFollowings[userId];
        users.insert(userId);
        for (int u : users) {
            for (auto& p : tweets[u]) all.push_back(p);
        }
        std::sort(all.begin(), all.end(), [](auto& a, auto& b) { return a.first > b.first; });
        std::vector<int> result;
        for (int i = 0; i < (int)all.size() && i < 10; ++i) result.push_back(all[i].second);
        return result;
    }

    void follow(int followerId, int followeeId) {
        userFollowings[followerId].insert(followeeId);
    }

    void unfollow(int followerId, int followeeId) {
        userFollowings[followerId].erase(followeeId);
    }
};

