int countNumbersWithUniqueDigits(int n) {
    if (n == 0) {
        return 1;
    }
    int count = 10;
    int unique = 9;
    int available = 9;
    for (int i = 2; i <= n && i <= 10; ++i) {
        unique *= available;
        count += unique;
        --available;
    }
    return count;
}

