long long maxSumSubarray(const std::vector<long long>& nums, long long k) {
    std::set<long long> prefix;
    prefix.insert(0);
    long long cur = 0;
    long long best = LLONG_MIN;
    for (long long num : nums) {
        cur += num;
        auto it = prefix.lower_bound(cur - k);
        if (it != prefix.end()) {
            best = std::max(best, cur - *it);
        }
        prefix.insert(cur);
    }
    return best;
}

long long maxSumSubmatrix(const std::vector<std::vector<int>>& matrix, int k) {
    long long maxSum = LLONG_MIN;
    int rows = matrix.size();
    int cols = matrix[0].size();
    for (int left = 0; left < cols; ++left) {
        std::vector<long long> temp(rows, 0);
        for (int right = left; right < cols; ++right) {
            for (int i = 0; i < rows; ++i) {
                temp[i] += matrix[i][right];
            }
            maxSum = std::max(maxSum, maxSumSubarray(temp, k));
        }
    }
    return maxSum;
}

