bool isPerfectSquare(long long num) {
    long long low = 1, high = num;
    while (low <= high) {
        long long mid = (low + high) / 2;
        long long square = mid * mid;
        if (square == num) return true;
        else if (square > num) high = mid - 1;
        else low = mid + 1;
    }
    return false;
}

