int powMod(int base, int exp, int mod) {
    long long result = 1;
    long long b = base % mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * b) % mod;
        }
        b = (b * b) % mod;
        exp >>= 1;
    }
    return static_cast<int>(result);
}

int superPow(int a, const std::vector<int>& b) {
    const int MOD = 1337;
    int result = 1;
    for (size_t i = 0; i < b.size(); ++i) {
        result = (powMod(result, 10, MOD) * powMod(a, b[i], MOD)) % MOD;
    }
    return result;
}

