std::vector<std::vector<int>> kSmallestPairs(const std::vector<int>& nums1, const std::vector<int>& nums2, int k) {
    if (nums1.empty() || nums2.empty() || k <= 0) {
        return {};
    }
    std::vector<std::array<int, 4>> minHeap;
    for (size_t i = 0; i < nums1.size(); ++i) {
        minHeap.push_back({nums1[i], nums2[0], static_cast<int>(i), 0});
    }
    std::vector<std::vector<int>> result;
    while (!minHeap.empty() && static_cast<int>(result.size()) < k) {
        std::sort(minHeap.begin(), minHeap.end(),
            [](const std::array<int, 4>& a, const std::array<int, 4>& b) {
                return (a[0] + a[1]) < (b[0] + b[1]);
            });
        auto cur = minHeap.front();
        minHeap.erase(minHeap.begin());
        int u = cur[0];
        int v = cur[1];
        int i = cur[2];
        int j = cur[3];
        result.push_back({u, v});
        if (j + 1 < static_cast<int>(nums2.size())) {
            minHeap.push_back({nums1[i], nums2[j + 1], i, j + 1});
        }
    }
    return result;
}

