long long combinationSum4(const std::vector<int>& nums, int target) {
    std::vector<long long> dp(target + 1, 0);
    dp[0] = 1;
    for (int i = 1; i <= target; ++i) {
        for (int num : nums) {
            if (i - num >= 0) dp[i] += dp[i - num];
        }
    }
    return dp[target];
}

