int kthSmallest(const std::vector<std::vector<int>>& matrix, int k) {
    std::vector<std::array<int, 3>> minHeap;
    for (int i = 0; i < static_cast<int>(matrix.size()); ++i) {
        minHeap.push_back({matrix[i][0], i, 0});
    }
    std::sort(minHeap.begin(), minHeap.end(),
              [](const std::array<int, 3>& a, const std::array<int, 3>& b) {
                  return a[0] < b[0];
              });
    int count = 0;
    while (count < k) {
        std::array<int, 3> cur = minHeap.front();
        minHeap.erase(minHeap.begin());
        ++count;
        if (count == k) {
            return cur[0];
        }
        int row = cur[1];
        int col = cur[2];
        if (col + 1 < static_cast<int>(matrix[row].size())) {
            minHeap.push_back({matrix[row][col + 1], row, col + 1});
            std::sort(minHeap.begin(), minHeap.end(),
                      [](const std::array<int, 3>& a, const std::array<int, 3>& b) {
                          return a[0] < b[0];
                      });
        }
    }
    return -1;
}

