class RandomizedSet {
    std::unordered_map<int, size_t> indexMap;
    std::vector<int> elements;
public:
    bool insert(int val) {
        if (indexMap.count(val)) return false;
        indexMap[val] = elements.size();
        elements.push_back(val);
        return true;
    }
    bool remove(int val) {
        if (!indexMap.count(val)) return false;
        size_t idx = indexMap[val];
        int last = elements.back();
        elements[idx] = last;
        indexMap[last] = idx;
        elements.pop_back();
        indexMap.erase(val);
        return true;
    }
    int getRandom() { return elements[rand() % elements.size()]; }
};

