    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};

int getRandomNode(ListNode* head) {
    ListNode* result = head;
    int count = 1;
    ListNode* currentNode = head->next;
    while (currentNode) {
        ++count;
        int random = std::rand() % count + 1;
        if (random == 1) {
            result = currentNode;
        }
        currentNode = currentNode->next;
    }
    return result->val;
}

