struct RandomizedCollection {
    std::vector<int> nums;
    std::unordered_map<int, std::unordered_set<int>> indexMap;

    RandomizedCollection() : nums(), indexMap() {}

    bool insert(int val) {
        bool notPresent = indexMap.find(val) == indexMap.end() || indexMap[val].empty();
        nums.push_back(val);
        indexMap[val].insert(static_cast<int>(nums.size()) - 1);
        return notPresent;
    }

    bool remove(int val) {
        auto it = indexMap.find(val);
        if (it == indexMap.end() || it->second.empty()) {
            return false;
        }
        int removeIdx = *(it->second.begin());
        int lastIdx = static_cast<int>(nums.size()) - 1;
        int lastVal = nums[lastIdx];

        nums[removeIdx] = lastVal;
        indexMap[lastVal].insert(removeIdx);
        indexMap[lastVal].erase(lastIdx);

        it->second.erase(removeIdx);
        if (it->second.empty()) {
            indexMap.erase(it);
        }
        nums.pop_back();
        return true;
    }

    int getRandom() const {
        return nums[std::rand() % nums.size()];
    }
};

