class Solution {
public:
    std::vector<int> original, array_;
    Solution(std::vector<int>& nums) : original(nums), array_(nums) {}
    std::vector<int> reset() { array_ = original; return array_; }
    std::vector<int> shuffle() {
        array_ = original;
        static std::mt19937 gen(std::random_device{}());
        for (int i = (int)array_.size() - 1; i > 0; --i) {
            std::uniform_int_distribution<int> dist(0, i);
            int j = dist(gen);
            std::swap(array_[i], array_[j]);
        }
        return array_;
