std::vector<int> lexicalOrder(int n) {
    std::vector<int> result;
    result.reserve(n);
    std::function<void(int)> dfs = [&](int cur) {
        if (cur > n) return;
        result.push_back(cur);
        for (int d = 0; d <= 9; ++d) {
            long long next = static_cast<long long>(cur) * 10 + d;
            if (next > n) break;
            dfs(static_cast<int>(next));
        }
    };
    for (int i = 1; i <= 9; ++i) {
        dfs(i);
    }
    return result;
}

