struct Json {
    bool isString;
    std::string str;
    std::vector<Json> arr;
};

static Json parseJson(const std::string& s, std::size_t& pos) {
    if (s[pos] == '[') {
        ++pos; // skip '['
        Json node;
        node.isString = false;
        while (pos < s.size() && s[pos] != ']') {
            Json child = parseJson(s, pos);
            node.arr.push_back(std::move(child));
            if (pos < s.size() && s[pos] == ',') {
                ++pos; // skip ','
            }
        }
        ++pos; // skip ']'
        return node;
    } else if (s[pos] == '"') {
        ++pos; // skip opening quote
        std::size_t start = pos;
        while (pos < s.size() && s[pos] != '"') {
            ++pos;
        }
        Json node;
        node.isString = true;
        node.str = s.substr(start, pos - start);
        ++pos; // skip closing quote
        return node;
    }
    // Should not reach here for valid input
    return Json{};
}

Json deserialize(const std::string& s) {
    static const std::regex re(R"((-?\d+))");
    std::string transformed = std::regex_replace(s, re, R"("$1")");
    std::size_t pos = 0;
    return parseJson(transformed, pos);
}

