int lengthLongestPath(const std::string& input) {
    std::vector<std::string> paths;
    size_t start = 0;
    while (true) {
        size_t pos = input.find('\n', start);
        if (pos == std::string::npos) {
            paths.push_back(input.substr(start));
            break;
        }
        paths.push_back(input.substr(start, pos - start));
        start = pos + 1;
    }
    std::vector<std::string> stack;
    int maxLen = 0;
    for (const std::string& path : paths) {
        size_t lastTab = path.rfind('\t');
        int depth = (lastTab == std::string::npos) ? 0 : static_cast<int>(lastTab) + 1;
        std::string name = path;
        name.erase(std::remove(name.begin(), name.end(), '\t'), name.end());
        if (name.find('.') != std::string::npos) {
            int sum = 0;
            for (int i = 0; i < depth && i < static_cast<int>(stack.size()); ++i) {
                sum += static_cast<int>(stack[i].size()) + 1;
            }
            int absPathLen = static_cast<int>(name.size()) + sum;
            if (absPathLen > maxLen) {
                maxLen = absPathLen;
            }
        } else {
            if (stack.size() > static_cast<size_t>(depth)) {
                stack.resize(depth);
            }
            stack.push_back(name);
        }
    }
    return maxLen;
}

