bool isRectangleCover(const std::vector<std::vector<int>>& rectangles) {
    long long area = 0;
    int x1 = INT_MAX, y1 = INT_MAX, x2 = INT_MIN, y2 = INT_MIN;
    std::unordered_set<std::string> corners;
    for (const auto& rectangle : rectangles) {
        int x = rectangle[0];
        int y = rectangle[1];
        int a = rectangle[2];
        int b = rectangle[3];
        area += static_cast<long long>(a - x) * (b - y);
        x1 = std::min(x1, x);
        y1 = std::min(y1, y);
        x2 = std::max(x2, a);
        y2 = std::max(y2, b);
        std::pair<int, int> points[4] = {{x, y}, {x, b}, {a, y}, {a, b}};
        for (const auto& point : points) {
            std::string key = std::to_string(point.first) + "," + std::to_string(point.second);
            if (corners.count(key)) {
                corners.erase(key);
            } else {
                corners.insert(key);
            }
        }
    }
    if (area != static_cast<long long>(x2 - x1) * (y2 - y1)) return false;
    std::pair<int, int> expectedCorners[4] = {{x1, y1}, {x1, y2}, {x2, y1}, {x2, y2}};
    for (const auto& corner : expectedCorners) {
        std::string key = std::to_string(corner.first) + "," + std::to_string(corner.second);
        if (!corners.count(key)) return false;
    }
    return corners.size() == 4;
}

