int longestSubstring(const std::string& s, int k) {
    if (s.size() < static_cast<size_t>(k)) return 0;
    std::unordered_set<char> uniq(s.begin(), s.end());
    for (char ch : uniq) {
        int cnt = 0;
        for (char c : s) if (c == ch) ++cnt;
        if (cnt < k) {
            int maxLen = 0;
            size_t start = 0;
            for (size_t i = 0; i <= s.size(); ++i) {
                if (i == s.size() || s[i] == ch) {
                    if (i > start) {
                        std::string sub = s.substr(start, i - start);
                        int len = longestSubstring(sub, k);
                        maxLen = std::max(maxLen, len);
                    }
                    start = i + 1;
                }
            }
            return maxLen;
        }
    }
    return static_cast<int>(s.size());
}

