int integerReplacement(int n) {
    std::int64_t x = n;
    int operations = 0;
    while (x != 1) {
        if ((x & 1) == 0) {
            x >>= 1;
        } else {
            if (x == 3) {
                --x;
            } else if ((x & 3) == 1) {
                --x;
            } else {
                ++x;
            }
        }
        ++operations;
    }
    return operations;
}

