long long rotateFunction(const std::vector<int>& nums) {
    long long n = static_cast<long long>(nums.size());
    if (n == 0) return 0;
    long long total = 0;
    long long current = 0;
    for (long long i = 0; i < n; ++i) {
        total += nums[i];
        current += i * static_cast<long long>(nums[i]);
    }
    long long maxVal = current;
    for (long long k = 1; k < n; ++k) {
        current = current + total - n * static_cast<long long>(nums[n - k]);
        maxVal = std::max(maxVal, current);
    }
    return maxVal;
}

