std::string decodeString(const std::string& s) {
    std::vector<std::string> stackStr;
    std::vector<int> stackNum;
    int curNum = 0;
    std::string curString;
    for (size_t i = 0; i < s.length(); ++i) {
        if (std::isdigit(static_cast<unsigned char>(s[i]))) {
            curNum = curNum * 10 + (s[i] - '0');
        } else if (s[i] >= 'a' && s[i] <= 'z') {
            curString.push_back(s[i]);
        } else if (s[i] == '[') {
            stackStr.push_back(curString);
            stackNum.push_back(curNum);
            curString.clear();
            curNum = 0;
        } else if (s[i] == ']') {
            int num = stackNum.back();
            stackNum.pop_back();
            std::string prevString = stackStr.back();
            stackStr.pop_back();
            std::string repeated;
            repeated.reserve(curString.size() * num);
            for (int j = 0; j < num; ++j) {
                repeated += curString;
            }
            curString = prevString + repeated;
        }
    }
    return curString;
}

