std::vector<double> calcEquation(const std::vector<std::vector<std::string>>& equations, const std::vector<double>& values, const std::vector<std::vector<std::string>>& queries) {
    std::unordered_map<std::string, std::unordered_map<std::string, double>> graph;
    for (size_t i = 0; i < equations.size(); ++i) {
        const std::string& dividend = equations[i][0];
        const std::string& divisor = equations[i][1];
        double value = values[i];
        if (graph.find(dividend) == graph.end()) graph[dividend] = {};
        if (graph.find(divisor) == graph.end()) graph[divisor] = {};
        graph[dividend][divisor] = value;
        graph[divisor][dividend] = 1.0 / value;
    }

    std::function<double(const std::string&, const std::string&, std::unordered_set<std::string>&)> dfs = [&](const std::string& start, const std::string& end, std::unordered_set<std::string>& visited) -> double {
        if (graph.find(start) == graph.end()) return -1.0;
        if (start == end) return 1.0;
        visited.insert(start);
        double result = -1.0;
        for (const auto& kv : graph[start]) {
            const std::string& neighbor = kv.first;
            if (visited.find(neighbor) == visited.end()) {
                double tempResult = dfs(neighbor, end, visited);
                if (tempResult != -1.0) {
                    result = kv.second * tempResult;
                    break;
                }
            }
        }
        visited.erase(start);
        return result;
    };

    std::vector<double> result;
    result.reserve(queries.size());
    for (const auto& query : queries) {
        const std::string& dividend = query[0];
        const std::string& divisor = query[1];
        std::unordered_set<std::string> visited;
        double tempResult = dfs(dividend, divisor, visited);
        result.push_back(tempResult);
    }
    return result;
}

#include <bits/stdc++.h>
#include <string>

int findNthDigit(int n) {
    long long length = 1;
    long long count = 9;
    long long start = 1;
    long long nn = n;
    while (nn > length * count) {
        nn -= length * count;
        ++length;
        count *= 10;
        start *= 10;
    }
    start += (nn - 1) / length;
    std::string str = std::to_string(start);
    return str[(nn - 1) % length] - '0';
}

