bool canCross(const std::vector<int>& stones) {
    int n = stones.size();
    std::unordered_set<int> stoneSet(stones.begin(), stones.end());
    std::unordered_map<long long, bool> memo;
    std::function<bool(int, int)> dfs = [&](int stone, int k) -> bool {
        long long key = (static_cast<long long>(stone) << 32) | static_cast<unsigned int>(k);
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        if (stone == stones[n - 1]) {
            memo[key] = true;
            return true;
        }
        for (int jump = k - 1; jump <= k + 1; ++jump) {
            if (jump <= 0) continue;
            int next = stone + jump;
            if (stoneSet.find(next) != stoneSet.end()) {
                if (dfs(next, jump)) {
                    memo[key] = true;
                    return true;
                }
            }
        }
        memo[key] = false;
        return false;
    };
    return dfs(stones[0], 1);
}

