std::string toHex(long long num) {
    if (num < 0) num += (1ULL << 32);
    std::string result;
    while (num > 0) {
        long long remainder = num % 16;
        if (remainder < 10)
            result = static_cast<char>('0' + remainder) + result;
        else
            result = static_cast<char>('a' + remainder - 10) + result;
        num = num / 16;
    }
    if (result.empty()) return "0";
    return result;
}

