int longestPalindrome(const std::string& s) {
    std::unordered_map<char, int> charCount;
    for (size_t i = 0; i < s.size(); ++i) {
        charCount[s[i]] = (charCount[s[i]] ? charCount[s[i]] : 0) + 1;
    }
    int length = 0;
    bool oddCounted = false;
    for (const auto& pair : charCount) {
        if (pair.second % 2 == 0) {
            length += pair.second;
        } else {
            length += pair.second - 1;
            if (!oddCounted) {
                length += 1;
                oddCounted = true;
            }
        }
    }
    return length;
}

