long long trapRainWater(const std::vector<std::vector<int>>& heightMap) {
    if (heightMap.empty() || heightMap[0].empty()) return 0;
    std::vector<std::array<int, 3>> minHeap;
    size_t m = heightMap.size();
    size_t n = heightMap[0].size();
    std::vector<std::vector<bool>> visited(m, std::vector<bool>(n, false));
    const std::array<std::pair<int, int>, 4> directions = {std::make_pair(-1, 0), std::make_pair(1, 0), std::make_pair(0, -1), std::make_pair(0, 1)};
    long long water = 0;

    for (size_t i = 0; i < m; ++i) {
        minHeap.push_back({heightMap[i][0], static_cast<int>(i), 0});
        minHeap.push_back({heightMap[i][n - 1], static_cast<int>(i), static_cast<int>(n - 1)});
        visited[i][0] = true;
        visited[i][n - 1] = true;
    }
    for (size_t j = 1; j + 1 < n; ++j) {
        minHeap.push_back({heightMap[0][j], 0, static_cast<int>(j)});
        minHeap.push_back({heightMap[m - 1][j], static_cast<int>(m - 1), static_cast<int>(j)});
        visited[0][j] = true;
        visited[m - 1][j] = true;
    }

    std::sort(minHeap.begin(), minHeap.end(),
              [](const std::array<int, 3>& a, const std::array<int, 3>& b) { return a[0] < b[0]; });

    while (!minHeap.empty()) {
        std::array<int, 3> cur = minHeap.front();
        minHeap.erase(minHeap.begin());
        int height = cur[0];
        int x = cur[1];
        int y = cur[2];

        for (const auto& dir : directions) {
            int nx = x + dir.first;
            int ny = y + dir.second;
            if (nx >= 0 && nx < static_cast<int>(m) && ny >= 0 && ny < static_cast<int>(n) && !visited[nx][ny]) {
                water += std::max(0, height - heightMap[nx][ny]);
                int newHeight = std::max(height, heightMap[nx][ny]);
                minHeap.push_back({newHeight, nx, ny});
                visited[nx][ny] = true;
            }
        }

        std::sort(minHeap.begin(), minHeap.end(),
                  [](const std::array<int, 3>& a, const std::array<int, 3>& b) { return a[0] < b[0]; });
    }

    return water;
}

