int thirdMax(const std::vector<int>& nums) {
    std::unordered_set<int> seen;
    std::vector<int> uniqueNums;
    uniqueNums.reserve(nums.size());
    for (int x : nums) {
        if (seen.insert(x).second) {
            uniqueNums.push_back(x);
        }
    }
    if (uniqueNums.size() < 3) {
        return *std::max_element(uniqueNums.begin(), uniqueNums.end());
    } else {
        auto it = std::max_element(uniqueNums.begin(), uniqueNums.end());
        uniqueNums.erase(it);
        it = std::max_element(uniqueNums.begin(), uniqueNums.end());
        uniqueNums.erase(it);
        return *std::max_element(uniqueNums.begin(), uniqueNums.end());
    }
}

