long long numberOfArithmeticSlices(const std::vector<int>& nums) {
    long long count = 0;
    long long currentLength = 0;
    long long lastDifference = 0;
    bool hasLast = false;
    for (size_t i = 0; i + 1 < nums.size(); ++i) {
        long long difference = static_cast<long long>(nums[i + 1]) - static_cast<long long>(nums[i]);
        if (!hasLast || lastDifference == difference) {
            ++currentLength;
            lastDifference = difference;
            hasLast = true;
        } else {
            count += (currentLength - 1) * currentLength / 2;
            currentLength = 1;
            lastDifference = difference;
        }
    }
    count += (currentLength - 1) * currentLength / 2;
    return count;
}

