bool canPartition(const std::vector<int>& nums) {
    int totalSum = std::accumulate(nums.begin(), nums.end(), 0);
    if (totalSum % 2 != 0) return false;
    int targetSum = totalSum / 2;
    std::vector<bool> dp(targetSum + 1, false);
    dp[0] = true;
    for (int num : nums) {
        for (int i = targetSum; i >= num; --i) {
            dp[i] = dp[i] || dp[i - num];
        }
    }
    return dp[targetSum];
}

#include <bits/stdc++.h>

int strongPasswordChecker(const std::string& password) {
    bool hasLower = false, hasUpper = false, hasDigit = false;
    for (char c : password) {
        unsigned char uc = static_cast<unsigned char>(c);
        if (std::islower(uc)) hasLower = true;
        else if (std::isupper(uc)) hasUpper = true;
        else if (std::isdigit(uc)) hasDigit = true;
    }
    int missingTypes = (!hasLower) + (!hasUpper) + (!hasDigit);
    int n = static_cast<int>(password.size());

    if (n < 6) {
        return std::max(missingTypes, 6 - n);
    }

    int replace = 0;
    int cntMod0 = 0, cntMod1 = 0;
    for (int i = 0; i < n; ) {
        int j = i;
        while (j < n && password[j] == password[i]) ++j;
        int len = j - i;
        if (len >= 3) {
            replace += len / 3;
            if (len % 3 == 0) ++cntMod0;
            else if (len % 3 == 1) ++cntMod1;
        }
        i = j;
    }

    if (n <= 20) {
        return std::max(missingTypes, replace);
    }

    int deleteCnt = n - 20;
    int use = std::min(deleteCnt, cntMod0);
    replace -= use;
    deleteCnt -= use;

    use = std::min(deleteCnt / 2, cntMod1);
    replace -= use;
    deleteCnt -= use * 2;

    replace -= deleteCnt / 3;

    if (replace < 0) replace = 0;
    return (n - 20) + std::max(missingTypes, replace);
}

