std::vector<std::vector<int>> pacificAtlantic(const std::vector<std::vector<int>>& heights) {
    size_t rows = heights.size();
    if (rows == 0) return {};
    size_t cols = heights[0].size();

    std::unordered_set<std::string> pacific;
    std::unordered_set<std::string> atlantic;

    std::function<void(int, int, std::unordered_set<std::string>&)> dfs = [&](int row, int col, std::unordered_set<std::string>& ocean) {
        if (row < 0 || row >= static_cast<int>(rows) || col < 0 || col >= static_cast<int>(cols)) return;
        std::string key = std::to_string(row) + "," + std::to_string(col);
        if (ocean.find(key) != ocean.end()) return;
        ocean.insert(key);
        int currentHeight = heights[row][col];
        if (row > 0 && heights[row - 1][col] >= currentHeight) dfs(row - 1, col, ocean);
        if (row < static_cast<int>(rows) - 1 && heights[row + 1][col] >= currentHeight) dfs(row + 1, col, ocean);
        if (col > 0 && heights[row][col - 1] >= currentHeight) dfs(row, col - 1, ocean);
        if (col < static_cast<int>(cols) - 1 && heights[row][col + 1] >= currentHeight) dfs(row, col + 1, ocean);
    };

    for (size_t i = 0; i < rows; ++i) dfs(static_cast<int>(i), 0, pacific);
    for (size_t j = 0; j < cols; ++j) dfs(0, static_cast<int>(j), pacific);

    for (size_t i = 0; i < rows; ++i) dfs(static_cast<int>(i), static_cast<int>(cols) - 1, atlantic);
    for (size_t j = 0; j < cols; ++j) dfs(static_cast<int>(rows) - 1, static_cast<int>(j), atlantic);

    std::vector<std::vector<int>> result;
    for (const std::string& cell : pacific) {
        if (atlantic.find(cell) != atlantic.end()) {
            size_t pos = cell.find(',');
            int row = std::stoi(cell.substr(0, pos));
            int col = std::stoi(cell.substr(pos + 1));
            result.push_back({row, col});
        }
    }
    std::sort(result.begin(), result.end(), [](const std::vector<int>& a, const std::vector<int>& b) {
        return a[0] < b[0] || (a[0] == b[0] && a[1] < b[1]);
    });
    return result;
}

