struct TrieNode {
    std::unordered_map<int, TrieNode*> child;
};

int findMaximumXOR(const std::vector<int>& nums) {
    TrieNode* trie = new TrieNode();
    for (int num : nums) {
        TrieNode* node = trie;
        for (int i = 31; i >= 0; --i) {
            int bit = (num >> i) & 1;
            if (node->child.find(bit) == node->child.end()) {
                node->child[bit] = new TrieNode();
            }
            node = node->child[bit];
        }
    }
    int maxResult = 0;
    for (int num : nums) {
        TrieNode* node = trie;
        int currResult = 0;
        for (int i = 31; i >= 0; --i) {
            int bit = (num >> i) & 1;
            if (node->child.find(1 - bit) != node->child.end()) {
                currResult |= (1 << i);
                node = node->child[1 - bit];
            } else {
                node = node->child[bit];
            }
        }
        maxResult = std::max(maxResult, currResult);
    }
    return maxResult;
}

