int characterReplacement(const std::string& s, int k) {
    int maxFrequency = 0, maxLength = 0, windowStart = 0;
    std::unordered_map<char, int> frequencyMap;
    for (int windowEnd = 0; windowEnd < static_cast<int>(s.size()); ++windowEnd) {
        char rightChar = s[windowEnd];
        frequencyMap[rightChar]++;
        maxFrequency = std::max(maxFrequency, frequencyMap[rightChar]);
        if (windowEnd - windowStart + 1 > maxFrequency + k) {
            char leftChar = s[windowStart];
            frequencyMap[leftChar]--;
            ++windowStart;
        }
        maxLength = std::max(maxLength, windowEnd - windowStart + 1);
    }
    return maxLength;
}

