std::string originalDigits(const std::string& s) {
    std::unordered_map<char, int> charFrequency;
    for (char ch : s) {
        ++charFrequency[ch];
    }
    std::string result;
    int zeroCount = charFrequency['z'];
    int twoCount = charFrequency['w'];
    int fourCount = charFrequency['u'];
    int sixCount = charFrequency['x'];
    int eightCount = charFrequency['g'];
    int threeCount = charFrequency['h'] - eightCount;
    threeCount = std::max(threeCount, 0);
    int fiveCount = charFrequency['f'] - fourCount;
    fiveCount = std::max(fiveCount, 0);
    int sevenCount = charFrequency['s'] - sixCount;
    sevenCount = std::max(sevenCount, 0);
    int oneCount = charFrequency['n'] - (sevenCount * 2);
    oneCount = std::max(oneCount, 0);
    int nineCount = charFrequency['i'] - fiveCount - sixCount - eightCount;
    nineCount = std::max(nineCount, 0);
    result.append(zeroCount, '0');
    result.append(oneCount, '1');
    result.append(twoCount, '2');
    result.append(threeCount, '3');
    result.append(fourCount, '4');
    result.append(fiveCount, '5');
    result.append(sixCount, '6');
    result.append(sevenCount, '7');
    result.append(eightCount, '8');
    result.append(nineCount, '9');
    return result;
}

