struct Node {
    bool isLeaf;
    int val;
    Node* topLeft;
    Node* topRight;
    Node* bottomLeft;
    Node* bottomRight;
    Node() : isLeaf(false), val(0), topLeft(nullptr), topRight(nullptr), bottomLeft(nullptr), bottomRight(nullptr) {}
    Node(bool _isLeaf, int _val) : isLeaf(_isLeaf), val(_val), topLeft(nullptr), topRight(nullptr), bottomLeft(nullptr), bottomRight(nullptr) {}
    Node(bool _isLeaf, int _val, Node* _topLeft, Node* _topRight, Node* _bottomLeft, Node* _bottomRight)
        : isLeaf(_isLeaf), val(_val), topLeft(_topLeft), topRight(_topRight), bottomLeft(_bottomLeft), bottomRight(_bottomRight) {}
};

static Node* build(const std::vector<std::vector<int>>& grid, const std::vector<std::vector<int>>& pref, int x, int y, int sz) {
    int total = pref[x + sz][y + sz] - pref[x][y + sz] - pref[x + sz][y] + pref[x][y];
    if (total == 0) {
        return new Node(true, 0);
    }
    if (total == sz * sz) {
        return new Node(true, 1);
    }
    int half = sz / 2;
    Node* tl = build(grid, pref, x, y, half);
    Node* tr = build(grid, pref, x, y + half, half);
    Node* bl = build(grid, pref, x + half, y, half);
    Node* br = build(grid, pref, x + half, y + half, half);
    return new Node(false, 0, tl, tr, bl, br);
}

Node* construct(const std::vector<std::vector<int>>& grid) {
    int n = static_cast<int>(grid.size());
    std::vector<std::vector<int>> pref(n + 1, std::vector<int>(n + 1, 0));
    for (int i = 0; i < n; ++i) {
        int rowSum = 0;
        for (int j = 0; j < n; ++j) {
            rowSum += grid[i][j];
            pref[i + 1][j + 1] = pref[i][j + 1] + rowSum;
        }
    }
    return build(grid, pref, 0, 0, n);
}

