};

std::vector<std::vector<int>> levelOrder(Node* root) {
    std::vector<std::vector<int>> result;
    if (!root) return result;
    std::vector<Node*> queue = {root};
    while (!queue.empty()) {
        std::vector<int> levelValues;
        std::vector<Node*> nextLevelNodes;
        for (size_t i = 0; i < queue.size(); ++i) {
            levelValues.push_back(queue[i]->val);
            if (!queue[i]->children.empty()) {
                nextLevelNodes.insert(nextLevelNodes.end(),
                                      queue[i]->children.begin(),
                                      queue[i]->children.end());
            }
        }
        result.push_back(levelValues);
        queue = std::move(nextLevelNodes);
    }
    return result;
}

