struct Node {
    int val;
    Node* prev;
    Node* next;
    Node* child;
    Node() : val(0), prev(nullptr), next(nullptr), child(nullptr) {}
    Node(int _val) : val(_val), prev(nullptr), next(nullptr), child(nullptr) {}
    Node(int _val, Node* _prev, Node* _next, Node* _child)
        : val(_val), prev(_prev), next(_next), child(_child) {}
};

Node* flatten(Node* head) {
    std::function<Node*(Node*)> dfs = [&](Node* node) -> Node* {
        Node* tail = node;
        while (node) {
            if (node->child) {
                Node* child = node->child;
                Node* childTail = dfs(child);
                if (node->next) {
                    childTail->next = node->next;
                    node->next->prev = childTail;
                }
                node->next = child;
                child->prev = node;
                tail = childTail;
                node->child = nullptr;
            } else {
                tail = node;
            }
            node = node->next;
        }
        return tail;
    };
    dfs(head);
    return head;
}

