int minMutation(const std::string& startGene, const std::string& endGene, const std::vector<std::string>& bank) {
    std::unordered_set<std::string> validGenes(bank.begin(), bank.end());
    std::queue<std::pair<std::string, int>> q;
    q.push({startGene, 0});
    std::unordered_set<std::string> visited;
    visited.insert(startGene);
    const char nucleotides[4] = {'A', 'C', 'G', 'T'};
    while (!q.empty()) {
        auto current = q.front();
        q.pop();
        const std::string& currentGene = current.first;
        int distance = current.second;
        if (currentGene == endGene) return distance;
        for (int i = 0; i < 8; ++i) {
            for (char nucleotide : nucleotides) {
                std::string newGene = currentGene;
                newGene[i] = nucleotide;
                if (validGenes.find(newGene) != validGenes.end() && visited.find(newGene) == visited.end()) {
                    q.push({newGene, distance + 1});
                    visited.insert(newGene);
                }
            }
        }
    }
    return -1;
}

