class AllOne {
    std::unordered_map<std::string, int> countMap;
    std::unordered_map<int, std::unordered_set<std::string>> bucketMap;
    int minCount;
    int maxCount;
public:
    AllOne() : minCount(1), maxCount(1) {}

    void inc(std::string key) {
        auto it = countMap.find(key);
        if (it != countMap.end()) {
            int c = it->second;
            bucketMap[c].erase(key);
            if (bucketMap[c].empty() && minCount == c) minCount++;
            it->second = c + 1;
            bucketMap[c + 1].insert(key);
            maxCount = std::max(maxCount, c + 1);
        } else {
            countMap[key] = 1;
            bucketMap[1].insert(key);
            minCount = 1;
            maxCount = std::max(maxCount, 1);
        }
    }

    void dec(std::string key) {
        auto it = countMap.find(key);
        if (it == countMap.end()) return;
        int c = it->second;
        bucketMap[c].erase(key);
        if (bucketMap[c].empty() && maxCount == c) maxCount--;
        if (c > 1) {
            it->second = c - 1;
            bucketMap[c - 1].insert(key);
            minCount = std::min(minCount, c - 1);
        } else {
            countMap.erase(key);
            if (countMap.empty()) {
                minCount = 1;
                maxCount = 1;
            } else {
                int m = INT_MAX;
                for (auto& [k, s] : bucketMap) if (!s.empty() && k < m) m = k;
                minCount = m;
            }
        }
    }

    std::string getMaxKey() {
        if (bucketMap.count(maxCount) && !bucketMap[maxCount].empty()) return *bucketMap[maxCount].begin();
        return "";
    }
    std::string getMinKey() {
        if (bucketMap.count(minCount) && !bucketMap[minCount].empty()) return *bucketMap[minCount].begin();
        return "";
    }
};

