std::vector<int> findRightInterval(const std::vector<std::vector<int>>& intervals) {
    std::vector<std::array<int, 3>> indexedIntervals;
    indexedIntervals.reserve(intervals.size());
    for (size_t i = 0; i < intervals.size(); ++i) {
        indexedIntervals.push_back({intervals[i][0], intervals[i][1], static_cast<int>(i)});
    }
    std::sort(indexedIntervals.begin(), indexedIntervals.end(),
        [](const std::array<int, 3>& a, const std::array<int, 3>& b) {
            return a[0] < b[0];
        });
    std::vector<int> result(intervals.size());
    for (size_t i = 0; i < intervals.size(); ++i) {
        int left = 0;
        int right = static_cast<int>(indexedIntervals.size()) - 1;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (indexedIntervals[mid][0] >= intervals[i][1]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        if (left < static_cast<int>(indexedIntervals.size())) {
            result[i] = indexedIntervals[left][2];
        } else {
            result[i] = -1;
        }
    }
    return result;
}

