};

void dfs(TreeNode* node, int currentSum, int targetSum, int& count) {
    if (node == nullptr) return;
    currentSum += node->val;
    if (currentSum == targetSum) ++count;
    dfs(node->left, currentSum, targetSum, count);
    dfs(node->right, currentSum, targetSum, count);
}

void traverse(TreeNode* node, int targetSum, int& count) {
    if (node == nullptr) return;
    dfs(node, 0, targetSum, count);
    traverse(node->left, targetSum, count);
    traverse(node->right, targetSum, count);
}

int pathSum(TreeNode* root, int targetSum) {
    int count = 0;
    traverse(root, targetSum, count);
    return count;
}

