std::vector<int> findAnagrams(const std::string& s, const std::string& p) {
    std::unordered_map<char, int> pCount;
    for (size_t i = 0; i < p.length(); ++i) {
        char c = p[i];
        if (pCount.find(c) != pCount.end()) pCount[c]++;
        else pCount[c] = 1;
    }

    std::vector<int> result;
    std::unordered_map<char, int> windowCount;
    int requiredChars = static_cast<int>(pCount.size());
    int formedChars = 0;
    size_t left = 0;

    for (size_t right = 0; right < s.length(); ++right) {
        char character = s[right];
        if (pCount.find(character) != pCount.end()) {
            if (windowCount.find(character) != windowCount.end()) windowCount[character]++;
            else windowCount[character] = 1;
            if (windowCount[character] == pCount[character]) ++formedChars;
        }

        while (right - left + 1 > p.length()) {
            char leftChar = s[left];
            if (pCount.find(leftChar) != pCount.end()) {
                windowCount[leftChar]--;
                if (windowCount[leftChar] < pCount[leftChar]) --formedChars;
            }
            ++left;
        }

        if (right - left + 1 == p.length() && formedChars == requiredChars) {
            result.push_back(static_cast<int>(left));
        }
    }

    return result;
}

