int findKthNumber(int n, int k) {
    long long cur = 1;
    k -= 1;
    while (k > 0) {
        long long step = 0;
        long long first = cur;
        long long last = cur + 1;
        while (first <= n) {
            step += std::min(static_cast<long long>(n) + 1, last) - first;
            first *= 10;
            last *= 10;
        }
        if (k >= step) {
            k -= step;
            cur += 1;
        } else {
            k -= 1;
            cur *= 10;
        }
    }
    return static_cast<int>(cur);
}

