long long arrangeCoins(long long n) {
    long long left = 1, right = n;
    while (left <= right) {
        long long mid = (left + right) / 2;
        long long totalCoins = mid * (mid + 1) / 2;
        if (totalCoins <= n) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return right;
}

