int compress(std::vector<char>& chars) {
    int writeIndex = 0;
    int count = 1;
    for (size_t readIndex = 1; readIndex <= chars.size(); ++readIndex) {
        if (readIndex == chars.size() || chars[readIndex] != chars[readIndex - 1]) {
            chars[writeIndex++] = chars[readIndex - 1];
            if (count > 1) {
                std::string countStr = std::to_string(count);
                for (char c : countStr) {
                    chars[writeIndex++] = c;
                }
            }
            count = 1;
        } else {
            ++count;
        }
    }
    return writeIndex;
}

