long long numberOfArithmeticSlices(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    long long result = 0;
    std::vector<std::unordered_map<long long, long long>> dp(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < i; ++j) {
            long long diff = static_cast<long long>(nums[i]) - static_cast<long long>(nums[j]);
            long long cnt = 0;
            auto it = dp[j].find(diff);
            if (it != dp[j].end()) {
                cnt = it->second;
            }
            result += cnt;
            long long& cur = dp[i][diff];
            cur += cnt + 1;
        }
    }
    return result;
}

