long long numberOfBoomerangs(const std::vector<std::vector<int>>& points) {
    long long totalBoomerangs = 0;
    for (size_t i = 0; i < points.size(); ++i) {
        std::unordered_map<long long, int> distanceMap;
        for (size_t j = 0; j < points.size(); ++j) {
            if (i == j) continue;
            long long dx = static_cast<long long>(points[i][0]) - points[j][0];
            long long dy = static_cast<long long>(points[i][1]) - points[j][1];
            long long distance = dx * dx + dy * dy;
            ++distanceMap[distance];
        }
        for (const auto& entry : distanceMap) {
            long long count = entry.second;
            totalBoomerangs += count * (count - 1);
        }
    }
    return totalBoomerangs;
}

