struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};

ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
    std::vector<int> arr1, arr2;
    while (l1) {
        arr1.push_back(l1->val);
        l1 = l1->next;
    }
    while (l2) {
        arr2.push_back(l2->val);
        l2 = l2->next;
    }
    std::reverse(arr1.begin(), arr1.end());
    std::reverse(arr2.begin(), arr2.end());
    std::vector<int> result;
    int carry = 0;
    std::size_t i = 0, j = 0;
    while (i < arr1.size() || j < arr2.size() || carry > 0) {
        int digit1 = i < arr1.size() ? arr1[i++] : 0;
        int digit2 = j < arr2.size() ? arr2[j++] : 0;
        int sum = digit1 + digit2 + carry;
        carry = sum / 10;
        result.push_back(sum % 10);
    }
    std::reverse(result.begin(), result.end());
    ListNode dummy(0);
    ListNode* current = &dummy;
    for (int val : result) {
        current->next = new ListNode(val);
        current = current->next;
    }
    return dummy.next;
}

