int findNextIndex(const std::vector<int>& nums, int current, bool direction) {
    bool curDir = nums[current] > 0;
    if (curDir != direction) return -1;
    int n = static_cast<int>(nums.size());
    int next = ((current + nums[current]) % n + n) % n;
    if (next == current) return -1;
    return next;
}

bool hasCycle(const std::vector<int>& nums, int start, bool direction) {
    int cur = start;
    while (true) {
        cur = findNextIndex(nums, cur, direction);
        if (cur == -1) return false;
        if (cur == start) return true;
    }
    return false;
}

bool circularArrayLoop(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    for (int i = 0; i < n; ++i) {
        int slow = i, fast = i;
        bool direction = nums[i] > 0;
        do {
            slow = findNextIndex(nums, slow, direction);
            if (slow == -1) break;
            fast = findNextIndex(nums, fast, direction);
            if (fast == -1) break;
            fast = findNextIndex(nums, fast, direction);
            if (fast == -1) break;
        } while (slow != fast);
        if (slow != -1 && slow == fast) {
            if (hasCycle(nums, slow, direction)) return true;
        }
    }
    return false;
}

