long long fourSumCount(const std::vector<int>& nums1, const std::vector<int>& nums2, const std::vector<int>& nums3, const std::vector<int>& nums4) {
    long long count = 0;
    std::size_t n = nums1.size();
    std::unordered_map<int, int> map;
    for (std::size_t i = 0; i < n; ++i) {
        for (std::size_t j = 0; j < n; ++j) {
            int sum = nums1[i] + nums2[j];
            ++map[sum];
        }
    }
    for (std::size_t i = 0; i < n; ++i) {
        for (std::size_t j = 0; j < n; ++j) {
            int sum = nums3[i] + nums4[j];
            auto it = map.find(-sum);
            if (it != map.end()) {
                count += it->second;
            }
        }
    }
    return count;
}

