bool repeatedSubstringPattern(const std::string& s) {
    for (size_t i = 1; i <= s.size() / 2; ++i) {
        if (s.size() % i == 0) {
            std::string substring = s.substr(0, i);
            std::string repeatedSubstring;
            repeatedSubstring.reserve(s.size());
            for (size_t j = 0; j < s.size() / i; ++j) {
                repeatedSubstring += substring;
            }
            if (repeatedSubstring == s) {
                return true;
            }
        }
    }
    return false;
}

