class LFUCache {
    int capacity;
    int minFreq;
    std::unordered_map<int, std::pair<int,int>> keyMap; // key -> (value, freq)
    std::unordered_map<int, std::list<int>> freqMap; // freq -> list of keys (front = most recently used)
    std::unordered_map<int, std::list<int>::iterator> keyIter;
public:
    LFUCache(int capacity) : capacity(capacity), minFreq(1) {}

    int get(int key) {
        auto it = keyMap.find(key);
        if (it == keyMap.end()) return -1;
        touch(key);
        return keyMap[key].first;
    }

    void put(int key, int value) {
        if (capacity <= 0) return;
        if (keyMap.count(key)) {
            keyMap[key].first = value;
            touch(key);
            return;
        }
        if ((int)keyMap.size() >= capacity) {
            int evictKey = freqMap[minFreq].back();
            freqMap[minFreq].pop_back();
            if (freqMap[minFreq].empty()) freqMap.erase(minFreq);
            keyMap.erase(evictKey);
            keyIter.erase(evictKey);
        }
        keyMap[key] = {value, 1};
        freqMap[1].push_front(key);
        keyIter[key] = freqMap[1].begin();
        minFreq = 1;
    }

private:
    void touch(int key) {
        int freq = keyMap[key].second;
        freqMap[freq].erase(keyIter[key]);
        if (freqMap[freq].empty()) {
            freqMap.erase(freq);
            if (minFreq == freq) minFreq++;
        }
        keyMap[key].second = freq + 1;
        freqMap[freq + 1].push_front(key);
        keyIter[key] = freqMap[freq + 1].begin();
    }
};

