int getMaxRepetitions(const std::string& s1, int n1, const std::string& s2, int n2) {
    std::vector<std::vector<int>> dp(s2.size() + 1, std::vector<int>(s1.size() + 1, 0));
    for (int i = 1; i <= static_cast<int>(s2.size()); ++i) {
        for (int j = 1; j <= static_cast<int>(s1.size()); ++j) {
            if (s2[i - 1] == s1[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = dp[i][j - 1];
            }
        }
    }
    long long maxRepetitions = 0;
    for (int i = 1; i <= static_cast<int>(s1.size()); ++i) {
        if (dp[s2.size()][i] == static_cast<int>(s2.size())) {
            long long candidate = (static_cast<long long>(n1) * i) / s1.size();
            maxRepetitions = std::max(maxRepetitions, candidate);
        }
    }
    return static_cast<int>(maxRepetitions / n2);
}

