std::vector<std::string> split(const std::string& s, char delim) {
    std::vector<std::string> parts;
    std::size_t start = 0;
    while (true) {
        std::size_t pos = s.find(delim, start);
        if (pos == std::string::npos) {
            parts.emplace_back(s.substr(start));
            break;
        }
        parts.emplace_back(s.substr(start, pos - start));
        start = pos + 1;
    }
    return parts;
}

std::string validIPAddress(std::string queryIP) {
    if (queryIP.find('.') != std::string::npos) {
        std::vector<std::string> parts = split(queryIP, '.');
        if (parts.size() != 4) return "Neither";
        for (const std::string& part : parts) {
            bool allDigits = true;
            for (char c : part) {
                if (!std::isdigit(static_cast<unsigned char>(c))) {
                    allDigits = false;
                    break;
                }
            }
            if (!allDigits) return "Neither";
            int num = part.empty() ? 0 : std::stoi(part);
            if (num < 0 || num > 255) return "Neither";
            if (part.length() > 1 && part[0] == '0') return "Neither";
        }
        return "IPv4";
    } else if (queryIP.find(':') != std::string::npos) {
        std::vector<std::string> parts = split(queryIP, ':');
        if (parts.size() != 8) return "Neither";
        for (const std::string& part : parts) {
            if (part.length() > 4 || part.empty()) return "Neither";
            for (char c : part) {
                if (!std::isxdigit(static_cast<unsigned char>(c))) return "Neither";
            }
        }
        return "IPv6";
    } else {
        return "Neither";
    }
}

