std::vector<std::string> findAllConcatenatedWordsInADict(const std::vector<std::string>& words) {
    std::unordered_set<std::string> wordSet(words.begin(), words.end());
    std::vector<std::string> result;

    auto canForm = [&](const std::string& word) -> bool {
        if (word.empty()) return false;
        std::vector<bool> dp(word.size() + 1, false);
        dp[0] = true;
        for (size_t i = 1; i <= word.size(); ++i) {
            for (size_t j = 0; j < i; ++j) {
                if (!dp[j]) continue;
                if (wordSet.find(word.substr(j, i - j)) != wordSet.end()) {
                    dp[i] = true;
                    break;
                }
            }
        }
        return dp[word.size()];
    };

    for (const std::string& word : words) {
        if (word.empty()) continue;
        wordSet.erase(word);
        if (canForm(word)) {
            result.push_back(word);
        }
        wordSet.insert(word);
    }
    return result;
}

