std::vector<double> medianSlidingWindow(const std::vector<int>& nums, int k) {
    std::vector<int> minHeap;
    std::vector<int> maxHeap;
    std::vector<double> result;
    for (size_t i = 0; i < nums.size(); ++i) {
        if (maxHeap.empty() || nums[i] < -maxHeap[0]) {
            maxHeap.push_back(-nums[i]);
            std::sort(maxHeap.begin(), maxHeap.end());
        } else {
            minHeap.push_back(nums[i]);
            std::sort(minHeap.begin(), minHeap.end());
        }
        if (maxHeap.size() > minHeap.size() + 1) {
            int val = -maxHeap[0];
            maxHeap.erase(maxHeap.begin());
            minHeap.push_back(val);
            std::sort(minHeap.begin(), minHeap.end());
        } else if (minHeap.size() > maxHeap.size()) {
            int val = minHeap[0];
            minHeap.erase(minHeap.begin());
            maxHeap.push_back(-val);
            std::sort(maxHeap.begin(), maxHeap.end());
        }
        if (i >= static_cast<size_t>(k - 1)) {
            if (k % 2 == 0) {
                result.push_back((-maxHeap[0] + minHeap[0]) / 2.0);
            } else {
                result.push_back(-maxHeap[0]);
            }
            int out = nums[i - k + 1];
            if (out <= -maxHeap[0]) {
                auto it = std::find(maxHeap.begin(), maxHeap.end(), -out);
                if (it != maxHeap.end()) {
                    maxHeap.erase(it);
                    std::sort(maxHeap.begin(), maxHeap.end());
                }
            } else {
                auto it = std::find(minHeap.begin(), minHeap.end(), out);
                if (it != minHeap.end()) {
                    minHeap.erase(it);
                    std::sort(minHeap.begin(), minHeap.end());
                }
            }
            if (maxHeap.size() > minHeap.size() + 1) {
                int val = -maxHeap[0];
                maxHeap.erase(maxHeap.begin());
                minHeap.push_back(val);
                std::sort(minHeap.begin(), minHeap.end());
            } else if (minHeap.size() > maxHeap.size()) {
                int val = minHeap[0];
                minHeap.erase(minHeap.begin());
                maxHeap.push_back(-val);
                std::sort(maxHeap.begin(), maxHeap.end());
            }
        }
    }
    return result;
}

#include <bits/stdc++.h>

int largestPalindrome(int n) {
    if (n == 1) return 9 % 1337;
    int lower = 1;
    for (int i = 1; i < n; ++i) lower *= 10;
    int upper = lower * 10 - 1;

    auto makePalindrome = [](int x) -> long long {
        long long res = x;
        int y = x;
        while (y > 0) {
            res = res * 10 + (y % 10);
            y /= 10;
        }
        return res;
    };

    for (int i = upper; i >= lower; --i) {
        long long pal = makePalindrome(i);
        for (int d = upper; d >= lower; --d) {
            if (pal % d == 0) {
                long long other = pal / d;
                if (other >= lower && other <= upper) {
                    return static_cast<int>(pal % 1337);
                }
            }
            if (1LL * d * d < pal) break;
        }
    }
    return 0;
}

