std::string smallestGoodBase(const std::string& n) {
    unsigned long long num = std::stoull(n);
    for (int k = 63; k >= 2; --k) {
        unsigned long long low = 2;
        unsigned long long high = static_cast<unsigned long long>(std::pow((long double)num, 1.0L / k)) + 1;
        if (high < low) continue;
        while (low <= high) {
            unsigned long long mid = low + (high - low) / 2;
            unsigned long long cur = 1;
            unsigned long long sum = 1;
            bool overflow = false;
            for (int i = 1; i <= k; ++i) {
                if (cur > num / mid) { overflow = true; break; }
                cur *= mid;
                if (sum > num - cur) { overflow = true; break; }
                sum += cur;
            }
            if (!overflow && sum == num) {
                return std::to_string(mid);
            }
            if (overflow || sum > num) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
    }
    return std::to_string(num - 1);
}

