#include <bits/stdc++.h>

int findMinStep(const std::string& board, const std::string& hand) {
    std::array<int, 26> handCnt{};
    handCnt.fill(0);
    for (char c : hand) handCnt[c - 'A']++;

    auto encodeHand = [&](const std::array<int, 26>& cnt) -> std::string {
        std::string s;
        s.reserve(26);
        for (int i = 0; i < 26; ++i) s.push_back(char('0' + cnt[i]));
        return s;
    };

    auto reduceBoard = [&](const std::string& b) -> std::string {
        std::string s = b;
        bool changed = true;
        while (changed) {
            changed = false;
            std::string t;
            for (size_t i = 0; i < s.size();) {
                size_t j = i;
                while (j < s.size() && s[j] == s[i]) ++j;
                if (j - i >= 3) {
                    changed = true;
                } else {
                    t.append(s.substr(i, j - i));
                }
                i = j;
            }
            s.swap(t);
        }
        return s;
    };

    std::deque<std::pair<std::string, std::array<int, 26>>> q;
    q.emplace_back(board, handCnt);
    std::unordered_set<std::string> visited;
    int steps = 0;

    while (!q.empty()) {
        size_t sz = q.size();
        for (size_t _ = 0; _ < sz; ++_) {
            auto cur = std::move(q.front());
            q.pop_front();
            const std::string& curBoard = cur.first;
            const std::array<int, 26>& curHand = cur.second;

            std::string key = curBoard + "|" + encodeHand(curHand);
            if (visited.find(key) != visited.end()) continue;
            visited.insert(key);

            if (curBoard.empty()) return steps;

            for (int c = 0; c < 26; ++c) {
                if (curHand[c] == 0) continue;
                char color = char('A' + c);
                for (size_t pos = 0; pos <= curBoard.size(); ++pos) {
                    std::string nb = curBoard.substr(0, pos) + color + curBoard.substr(pos);
                    std::array<int, 26> nh = curHand;
                    nh[c]--;
                    std::string reduced = reduceBoard(nb);
                    q.emplace_back(std::move(reduced), nh);
                }
            }
        }
        ++steps;
    }
    return -1;
}

