long long findTargetSumWays(const std::vector<int>& nums, int target) {
    std::unordered_map<int, long long> dp;
    dp[0] = 1;
    for (int num : nums) {
        std::unordered_map<int, long long> temp;
        for (const auto& kv : dp) {
            int sum = kv.first;
            long long count = kv.second;
            int newSum = sum + num;
            if (temp.find(newSum) == temp.end()) temp[newSum] = count;
            else temp[newSum] += count;
            newSum = sum - num;
            if (temp.find(newSum) == temp.end()) temp[newSum] = count;
            else temp[newSum] += count;
        }
        dp = std::move(temp);
    }
    return dp.find(target) != dp.end() ? dp[target] : 0;
}

