long long reversePairs(std::vector<int> nums) {
    long long count = 0;
    std::vector<long long> a(nums.begin(), nums.end());
    std::function<void(int, int)> sort = [&](int left, int right) {
        if (right - left <= 1) return;
        int mid = left + (right - left) / 2;
        sort(left, mid);
        sort(mid, right);
        int j = mid;
        for (int i = left; i < mid; ++i) {
            while (j < right && a[i] > 2LL * a[j]) ++j;
            count += j - mid;
        }
        std::inplace_merge(a.begin() + left, a.begin() + mid, a.begin() + right);
    };
    sort(0, static_cast<int>(a.size()));
    return count;
}

