std::vector<int> nextGreaterElement(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    std::unordered_map<int, int> nextGreaterMap;
    std::vector<int> stack;
    for (size_t i = 0; i < nums2.size(); ++i) {
        while (!stack.empty() && nums2[i] > stack.back()) {
            nextGreaterMap[stack.back()] = nums2[i];
            stack.pop_back();
        }
        stack.push_back(nums2[i]);
    }
    while (!stack.empty()) {
        nextGreaterMap[stack.back()] = -1;
        stack.pop_back();
    }
    std::vector<int> result;
    result.reserve(nums1.size());
    for (size_t i = 0; i < nums1.size(); ++i) {
        result.push_back(nextGreaterMap[nums1[i]]);
    }
    return result;
}

