class Solution {
public:
    std::vector<std::vector<int>> rects;
    std::vector<long long> prefix;
    long long total = 0;
    Solution(std::vector<std::vector<int>>& r) : rects(r) {
        for (auto& rc : rects) {
            total += (long long)(rc[2]-rc[0]+1) * (rc[3]-rc[1]+1);
            prefix.push_back(total);
        }
    }
    std::vector<int> pick() {
        static std::mt19937_64 rng(std::random_device{}());
        std::uniform_int_distribution<long long> distIdx(0, total-1);
        long long idx = distIdx(rng);
        for (size_t i = 0; i < rects.size(); i++) {
            if (idx < prefix[i]) {
                auto& rc = rects[i];
                std::uniform_int_distribution<int> dx(rc[0], rc[2]);
                std::uniform_int_distribution<int> dy(rc[1], rc[3]);
                return {dx(rng), dy(rng)};
            }
        }
        return {};
    }
};

