std::vector<int> findDiagonalOrder(const std::vector<std::vector<int>>& mat) {
    std::vector<int> result;
    if (mat.empty() || mat[0].empty()) {
        return result;
    }
    int rows = static_cast<int>(mat.size());
    int cols = static_cast<int>(mat[0].size());
    std::unordered_map<int, std::vector<int>> map;
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            int diagonal = i + j;
            map[diagonal].push_back(mat[i][j]);
        }
    }
    for (int i = 0; i < rows + cols - 1; ++i) {
        if (i % 2 == 0) {
            std::vector<int>& diag = map[i];
            std::reverse(diag.begin(), diag.end());
            result.insert(result.end(), diag.begin(), diag.end());
        } else {
            const std::vector<int>& diag = map[i];
            result.insert(result.end(), diag.begin(), diag.end());
        }
    }
    return result;
}

