std::vector<std::string> findWords(const std::vector<std::string>& words) {
    const std::array<std::string, 3> rows = {"qwertyuiop", "asdfghjkl", "zxcvbnm"};
    std::vector<std::string> result;
    for (const std::string& w : words) {
        if (w.empty()) continue;
        char first = static_cast<char>(std::tolower(static_cast<unsigned char>(w[0])));
        const std::string* rowPtr = nullptr;
        for (const std::string& row : rows) {
            if (row.find(first) != std::string::npos) {
                rowPtr = &row;
                break;
            }
        }
        if (!rowPtr) continue;
        bool canBeTyped = true;
        for (char ch : w) {
            char lc = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
            if (rowPtr->find(lc) == std::string::npos) {
                canBeTyped = false;
                break;
            }
        }
        if (canBeTyped) {
            result.push_back(w);
        }
    }
    return result;
}

