    std::unordered_map<int, int> frequency;
    int maxFrequency = 0;
    std::vector<int> modes;
    dfs(root, frequency);
    for (const auto& kv : frequency) {
        if (kv.second > maxFrequency) {
            maxFrequency = kv.second;
