std::string convertToBase7(long long num) {
    if (num == 0) return "0";
    std::string result;
    bool isNegative = num < 0;
    long long n = std::llabs(num);
    while (n > 0) {
        int digit = static_cast<int>(n % 7);
        result.insert(result.begin(), static_cast<char>('0' + digit));
        n /= 7;
    }
    return isNegative ? "-" + result : result;
}

