    queue.push(std::make_pair(root, 0));
    int maxLevel = -1;
    int result = root->val;
    while (!queue.empty()) {
        TreeNode* node = queue.front().first;
        int level = queue.front().second;
        queue.pop();
        if (level > maxLevel) {
            maxLevel = level;
            result = node->val;
        }
        if (node->left) {
            queue.push(std::make_pair(node->left, level + 1));
        }
        if (node->right) {
            queue.push(std::make_pair(node->right, level + 1));
        }
    }
    return result;
}

