int findRotateSteps(const std::string& ring, const std::string& key) {
    std::unordered_map<char, std::vector<int>> charIndexMap;
    for (size_t i = 0; i < ring.size(); ++i) {
        charIndexMap[ring[i]].push_back(static_cast<int>(i));
    }

    const int INF = INT_MAX / 2;
    std::vector<std::vector<int>> dp(key.size(), std::vector<int>(ring.size(), INF));

    for (size_t j = 0; j < ring.size(); ++j) {
        if (ring[j] == key[0]) {
            dp[0][j] = std::min(static_cast<int>(j), static_cast<int>(ring.size() - j)) + 1;
        }
    }

    for (size_t i = 1; i < key.size(); ++i) {
        for (size_t j = 0; j < ring.size(); ++j) {
            if (ring[j] == key[i]) {
                for (size_t k = 0; k < ring.size(); ++k) {
                    if (dp[i - 1][k] != INF) {
                        int diff = std::abs(static_cast<int>(j) - static_cast<int>(k));
                        int minSteps = std::min(diff, static_cast<int>(ring.size()) - diff);
                        dp[i][j] = std::min(dp[i][j], dp[i - 1][k] + minSteps + 1);
                    }
                }
            }
        }
    }

    int minSteps = INF;
    for (size_t j = 0; j < ring.size(); ++j) {
        if (dp[key.size() - 1][j] != INF) {
            minSteps = std::min(minSteps, dp[key.size() - 1][j]);
        }
    }

    return minSteps;
}

