int findMinMoves(const std::vector<int>& machines) {
    long long total = 0;
    for (int v : machines) total += v;
    if (machines.empty() || total % machines.size() != 0) return -1;
    long long target = total / machines.size();
    long long cur = 0;
    long long ans = 0;
    for (int v : machines) {
        cur += v - target;
        long long need = std::max(std::llabs(cur), static_cast<long long>(v) - target);
        if (need > ans) ans = need;
    }
    return static_cast<int>(ans);
}

