int countArrangement(int n) {
    int count = 0;
    std::vector<bool> visited(n + 1, false);
    std::function<void(int)> backtrack = [&](int index) {
        if (index == n + 1) {
            ++count;
        } else {
            for (int i = 1; i <= n; ++i) {
                if (!visited[i] && (i % index == 0 || index % i == 0)) {
                    visited[i] = true;
                    backtrack(index + 1);
                    visited[i] = false;
                }
            }
        }
    };
    backtrack(1);
    return count;
}

