class Solution {
public:
    std::vector<double> prefixSum;
    Solution(std::vector<int>& w) {
        prefixSum.resize(w.size());
        prefixSum[0] = w[0];
        for (size_t i = 1; i < w.size(); i++) prefixSum[i] = prefixSum[i-1] + w[i];
    }
    int pickIndex() {
        static std::mt19937 rng(std::random_device{}());
        std::uniform_real_distribution<double> dist(0.0, prefixSum.back());
        double target = dist(rng);
        int left = 0, right = (int)prefixSum.size()-1;
        while (left < right) {
            int mid = (left+right)/2;
            if (target < prefixSum[mid]) right = mid; else left = mid+1;
        }
        return left;
    }
};

