int findPairs(const std::vector<int>& nums, int k) {
    if (k < 0) {
        return 0;
    }
    std::unordered_map<int, int> freq;
    for (int num : nums) {
        ++freq[num];
    }
    int count = 0;
    if (k == 0) {
        for (const auto& p : freq) {
            if (p.second > 1) {
                ++count;
            }
        }
    } else {
        for (const auto& p : freq) {
            if (freq.find(p.first + k) != freq.end()) {
                ++count;
            }
        }
    }
    return count;
}

