class Solution {
public:
    Solution() : counter(1) {}
    string encode(string longUrl) {
        auto it = longToShort.find(longUrl);
        if (it != longToShort.end()) return it->second;
        string key = encodeBase62(counter++);
        string shortUrl = PREFIX + key;
        longToShort[longUrl] = shortUrl;
        shortToLong[key] = longUrl;
        return shortUrl;
    }
    string decode(string shortUrl) {
        if (shortUrl.compare(0, PREFIX.size(), PREFIX) != 0) return shortUrl;
        if (shortUrl.size() <= PREFIX.size()) return "";
        string key = shortUrl.substr(PREFIX.size());
        auto it = shortToLong.find(key);
        if (it != shortToLong.end()) return it->second;
        return "";
    }
private:
    const string PREFIX = "http://tinyurl.com/";
    const string CHARSET = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    unordered_map<string,string> longToShort;
    unordered_map<string,string> shortToLong;
    uint64_t counter;
    string encodeBase62(uint64_t num) {
        if (num == 0) return string(1, CHARSET[0]);
        string res;
        while (num > 0) { res.push_back(CHARSET[num % 62]); num /= 62; }
        reverse(res.begin(), res.end());
        return res;
    }
};

