std::vector<std::vector<int>> updateMatrix(const std::vector<std::vector<int>>& mat) {
    std::vector<std::vector<int>> result(mat.size(), std::vector<int>(mat[0].size()));
    std::queue<std::pair<int, int>> queue;
    for (size_t i = 0; i < mat.size(); ++i) {
        for (size_t j = 0; j < mat[0].size(); ++j) {
            if (mat[i][j] == 0) {
                result[i][j] = 0;
                queue.push({static_cast<int>(i), static_cast<int>(j)});
            } else {
                result[i][j] = -1;
            }
        }
    }
    const std::vector<std::pair<int, int>> directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    while (!queue.empty()) {
        auto current = queue.front();
        queue.pop();
        for (const auto& dir : directions) {
            int x = current.first + dir.first;
            int y = current.second + dir.second;
            if (x >= 0 && x < static_cast<int>(mat.size()) && y >= 0 && y < static_cast<int>(mat[0].size()) && result[x][y] == -1) {
                result[x][y] = result[current.first][current.second] + 1;
                queue.push({x, y});
            }
        }
    }
    return result;
}

