int findMinDifference(const std::vector<std::string>& timePoints) {
    std::vector<int> minutes;
    minutes.reserve(timePoints.size());
    for (const std::string& time : timePoints) {
        size_t colonPos = time.find(':');
        int hour = std::stoi(time.substr(0, colonPos));
        int minute = std::stoi(time.substr(colonPos + 1));
        minutes.push_back(hour * 60 + minute);
    }
    std::sort(minutes.begin(), minutes.end());
    int minDiff = std::numeric_limits<int>::max();
    for (size_t i = 0; i + 1 < minutes.size(); ++i) {
        int diff = minutes[i + 1] - minutes[i];
        if (diff < minDiff) minDiff = diff;
    }
    int wrapDiff = 24 * 60 - minutes.back() + minutes.front();
    if (wrapDiff < minDiff) minDiff = wrapDiff;
    return minDiff;
}

