int removeBoxes(const std::vector<int>& boxes) {
    std::unordered_map<std::string, int> memo;
    std::function<int(int, int, int)> dp = [&](int left, int right, int k) -> int {
        if (left > right) return 0;
        std::string key = std::to_string(left) + "," + std::to_string(right) + "," + std::to_string(k);
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        int maxPoints = 0;
        if (left == right) {
            maxPoints = (k + 1) * (k + 1);
            memo[key] = maxPoints;
            return maxPoints;
        }
        for (int i = left + 1; i <= right; ++i) {
            if (boxes[i] == boxes[left]) {
                int points = dp(left + 1, i - 1, 0) + dp(i, right, k + 1);
                maxPoints = std::max(maxPoints, points);
            }
        }
        maxPoints = std::max(maxPoints, (k + 1) * (k + 1) + dp(left + 1, right, 0));
        memo[key] = maxPoints;
        return maxPoints;
    };
    return dp(0, static_cast<int>(boxes.size()) - 1, 0);
}

