int checkRecord(int n) {
    const long long MOD = 1000000007LL;
    long long dp[2][3] = {};
    dp[0][0] = 1;
    for (int i = 0; i < n; ++i) {
        long long ndp[2][3] = {};
        for (int a = 0; a <= 1; ++a) {
            for (int l = 0; l <= 2; ++l) {
                long long cur = dp[a][l];
                if (!cur) continue;
                // add 'P'
                ndp[a][0] = (ndp[a][0] + cur) % MOD;
                // add 'L'
                if (l < 2) {
                    ndp[a][l + 1] = (ndp[a][l + 1] + cur) % MOD;
                }
                // add 'A'
                if (a == 0) {
                    ndp[1][0] = (ndp[1][0] + cur) % MOD;
                }
            }
        }
        std::memcpy(dp, ndp, sizeof(dp));
    }
    long long ans = 0;
    for (int a = 0; a <= 1; ++a) {
        for (int l = 0; l <= 2; ++l) {
            ans = (ans + dp[a][l]) % MOD;
        }
    }
    return static_cast<int>(ans);
}

