int leastBricks(const std::vector<std::vector<int>>& wall) {
    std::unordered_map<int, int> edges;
    for (size_t i = 0; i < wall.size(); ++i) {
        int sum = 0;
        for (size_t j = 0; j + 1 < wall[i].size(); ++j) {
            sum += wall[i][j];
            auto it = edges.find(sum);
            if (it == edges.end()) {
                edges[sum] = 1;
            } else {
                it->second++;
            }
        }
    }
    int maxEdges = 0;
    for (const auto& kv : edges) {
        maxEdges = std::max(maxEdges, kv.second);
    }
    return static_cast<int>(wall.size()) - maxEdges;
}

