static Node* clone(Node* node) {
    if (!node) return nullptr;
    if (node->isLeaf) return new Node(node->val, true);
    return new Node(false, false,
                    clone(node->topLeft),
                    clone(node->topRight),
                    clone(node->bottomLeft),
                    clone(node->bottomRight));
}

Node* intersect(Node* quadTree1, Node* quadTree2) {
    if (quadTree1->isLeaf) {
        if (quadTree1->val) return new Node(true, true);
        return clone(quadTree2);
    }
    if (quadTree2->isLeaf) {
        if (quadTree2->val) return new Node(true, true);
        return clone(quadTree1);
    }
    Node* tl = intersect(quadTree1->topLeft, quadTree2->topLeft);
    Node* tr = intersect(quadTree1->topRight, quadTree2->topRight);
    Node* bl = intersect(quadTree1->bottomLeft, quadTree2->bottomLeft);
    Node* br = intersect(quadTree1->bottomRight, quadTree2->bottomRight);
    if (tl->isLeaf && tr->isLeaf && bl->isLeaf && br->isLeaf &&
        tl->val == tr->val && tl->val == bl->val && tl->val == br->val) {
        bool v = tl->val;
        delete tl; delete tr; delete bl; delete br;
        return new Node(v, true);
    }
    return new Node(false, false, tl, tr, bl, br);
}

