bool checkInclusion(const std::string& s1, const std::string& s2) {
    std::unordered_map<char, int> s1Map;
    for (size_t i = 0; i < s1.length(); ++i) {
        s1Map[s1[i]] = s1Map[s1[i]] + 1;
    }

    int left = 0;
    int right = 0;
    int matched = 0;
    std::unordered_map<char, int> windowCounts;

    while (right < static_cast<int>(s2.length())) {
        char character = s2[right];
        if (s1Map.find(character) != s1Map.end()) {
            windowCounts[character] = windowCounts[character] + 1;
            if (windowCounts[character] == s1Map[character]) {
                ++matched;
            }
        }

        if (right - left + 1 == static_cast<int>(s1.length())) {
            if (matched == static_cast<int>(s1Map.size())) {
                return true;
            }

            char leftChar = s2[left];
            if (s1Map.find(leftChar) != s1Map.end()) {
                if (windowCounts[leftChar] == s1Map[leftChar]) {
                    --matched;
                }
                windowCounts[leftChar]--;
            }
            ++left;
        }
        ++right;
    }
    return false;
}

