int findUnsortedSubarray(const std::vector<int>& nums) {
    std::vector<int> sortedNums = nums;
    std::sort(sortedNums.begin(), sortedNums.end());
    int left = 0;
    int right = static_cast<int>(nums.size()) - 1;
    while (left < static_cast<int>(nums.size()) && nums[left] == sortedNums[left]) ++left;
    if (left == static_cast<int>(nums.size())) return 0;
    while (right >= 0 && nums[right] == sortedNums[right]) --right;
    return right - left + 1;
}

