int minDistance(const std::string& word1, const std::string& word2) {
    std::vector<std::vector<int>> dp(word1.size() + 1, std::vector<int>(word2.size() + 1, 0));
    for (size_t i = 0; i <= word1.size(); ++i) {
        dp[i][0] = 0;
    }
    for (size_t j = 0; j <= word2.size(); ++j) {
        dp[0][j] = 0;
    }
    for (size_t i = 1; i <= word1.size(); ++i) {
        for (size_t j = 1; j <= word2.size(); ++j) {
            if (word1[i - 1] == word2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = std::max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }
    return static_cast<int>(word1.size() + word2.size() - 2 * dp[word1.size()][word2.size()]);
}

#include <bits/stdc++.h>

std::vector<std::vector<int>> outerTrees(std::vector<std::vector<int>>& trees) {
    int n = static_cast<int>(trees.size());
    if (n <= 1) return trees;
    std::vector<std::pair<int, int>> pts;
    pts.reserve(n);
    for (auto &t : trees) pts.emplace_back(t[0], t[1]);
    std::sort(pts.begin(), pts.end());
    auto cross = [](const std::pair<int, int>& a,
                    const std::pair<int, int>& b,
                    const std::pair<int, int>& c) -> long long {
        return static_cast<long long>(b.first - a.first) * (c.second - a.second) -
               static_cast<long long>(b.second - a.second) * (c.first - a.first);
    };
    std::vector<std::pair<int, int>> lower, upper;
    for (auto &p : pts) {
        while (lower.size() >= 2 && cross(lower[lower.size() - 2], lower[lower.size() - 1], p) < 0)
            lower.pop_back();
        lower.push_back(p);
    }
    for (int i = n - 1; i >= 0; --i) {
        auto &p = pts[i];
        while (upper.size() >= 2 && cross(upper[upper.size() - 2], upper[upper.size() - 1], p) < 0)
            upper.pop_back();
        upper.push_back(p);
    }
    std::vector<std::pair<int, int>> hull;
    hull.reserve(lower.size() + upper.size());
    std::unordered_set<long long> seen;
    auto encode = [](int x, int y) -> long long {
        return (static_cast<long long>(x) << 32) ^ static_cast<unsigned int>(y);
    };
    for (auto &p : lower) {
        long long key = encode(p.first, p.second);
        if (seen.insert(key).second) hull.push_back(p);
    }
    for (auto &p : upper) {
        long long key = encode(p.first, p.second);
        if (seen.insert(key).second) hull.push_back(p);
    }
    if (static_cast<int>(hull.size()) == n) {
        std::reverse(hull.begin(), hull.end());
    }
    std::vector<std::vector<int>> result;
    result.reserve(hull.size());
    for (auto &p : hull) result.push_back({p.first, p.second});
    return result;
}

