bool isValid(const std::string& code) {
    if (code.empty()) return false;
    std::vector<std::string> stack;
    std::size_t i = 0, n = code.size();
    while (i < n) {
        if (code[i] != '<') {
            if (stack.empty()) return false;
            ++i;
            continue;
        }
        if (i + 9 <= n && code.compare(i, 9, "<![CDATA[") == 0) {
            if (stack.empty()) return false;
            std::size_t pos = code.find("]]>", i + 9);
            if (pos == std::string::npos) return false;
            i = pos + 3;
            continue;
        }
        if (i + 2 < n && code[i + 1] == '/') {
            std::size_t gt = code.find('>', i + 2);
            if (gt == std::string::npos) return false;
            std::string name = code.substr(i + 2, gt - (i + 2));
            if (name.empty() || name.size() > 9) return false;
            for (char c : name) if (c < 'A' || c > 'Z') return false;
            if (stack.empty() || stack.back() != name) return false;
            stack.pop_back();
            i = gt + 1;
            if (stack.empty() && i != n) return false;
            continue;
        }
        std::size_t gt = code.find('>', i + 1);
        if (gt == std::string::npos) return false;
        std::string name = code.substr(i + 1, gt - (i + 1));
        if (name.empty() || name.size() > 9) return false;
        for (char c : name) if (c < 'A' || c > 'Z') return false;
        stack.push_back(name);
        i = gt + 1;
    }
    return stack.empty();
}

#include <bits/stdc++.h>

std::string fractionAddition(const std::string& expression) {
    size_t i = 0, n = expression.size();
    long long num = 0, den = 1;
    auto gcd = [](long long a, long long b) {
        while (b != 0) {
            long long t = b;
            b = a % b;
            a = t;
        }
        return a;
    };
    while (i < n) {
        int sign = 1;
        if (expression[i] == '+' || expression[i] == '-') {
            sign = (expression[i] == '-') ? -1 : 1;
            ++i;
        }
        long long a = 0;
        while (i < n && std::isdigit(expression[i])) {
            a = a * 10 + (expression[i] - '0');
            ++i;
        }
        a *= sign;
        ++i; // skip '/'
        long long b = 0;
        while (i < n && std::isdigit(expression[i])) {
            b = b * 10 + (expression[i] - '0');
            ++i;
        }
        long long newNum = num * b + a * den;
        long long newDen = den * b;
        long long g = gcd(std::llabs(newNum), newDen);
        num = newNum / g;
        den = newDen / g;
    }
    if (num == 0) den = 1;
    return std::to_string(num) + '/' + std::to_string(den);
}

