static long long distance(const std::vector<int>& a, const std::vector<int>& b) {
    long long dx = static_cast<long long>(a[0]) - b[0];
    long long dy = static_cast<long long>(a[1]) - b[1];
    return dx * dx + dy * dy;
}

bool validSquare(const std::vector<int>& p1, const std::vector<int>& p2, const std::vector<int>& p3, const std::vector<int>& p4) {
    std::vector<long long> distances;
    distances.push_back(distance(p1, p2));
    distances.push_back(distance(p1, p3));
    distances.push_back(distance(p1, p4));
    distances.push_back(distance(p2, p3));
    distances.push_back(distance(p2, p4));
    distances.push_back(distance(p3, p4));
    std::sort(distances.begin(), distances.end());
    return distances[0] == distances[1] && distances[1] == distances[2] && distances[2] == distances[3] &&
           distances[4] == distances[5] && distances[0] < distances[4];
}

