int findLHS(const std::vector<int>& nums) {
    std::unordered_map<int, int> countMap;
    for (int num : nums) {
        ++countMap[num];
    }
    int longestLength = 0;
    for (const auto& kv : countMap) {
        int num = kv.first;
        auto it = countMap.find(num + 1);
        if (it != countMap.end()) {
            longestLength = std::max(longestLength, kv.second + it->second);
        }
    }
    return longestLength;
}

