std::vector<std::string> findRestaurant(const std::vector<std::string>& list1, const std::vector<std::string>& list2) {
    std::unordered_map<std::string, int> map;
    for (int i = 0; i < static_cast<int>(list1.size()); ++i) {
        map[list1[i]] = i;
    }
    int minSum = std::numeric_limits<int>::max();
    std::vector<std::string> result;
    for (int i = 0; i < static_cast<int>(list2.size()); ++i) {
        auto it = map.find(list2[i]);
        if (it != map.end()) {
            int sum = i + it->second;
            if (sum < minSum) {
                minSum = sum;
                result = {list2[i]};
            } else if (sum == minSum) {
                result.push_back(list2[i]);
            }
        }
    }
    return result;
}

