long long findIntegers(int n) {
    if (n == 0) {
        return 1;
    }
    std::vector<long long> fib(32);
    fib[0] = 1;
    fib[1] = 2;
    for (int i = 2; i < 32; ++i) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }
    int msb = 31;
    while (msb >= 0 && ((n >> msb) & 1) == 0) {
        --msb;
    }
    long long ans = 0;
    int prevBit = 0;
    for (int i = msb; i >= 0; --i) {
        if ((n >> i) & 1) {
            ans += fib[i];
            if (prevBit) {
                return ans - 1;
            }
            prevBit = 1;
        } else {
            prevBit = 0;
        }
    }
    return ans + 1;
}

