bool canPlaceFlowers(std::vector<int>& flowerbed, int n) {
    int count = 0;
    for (std::size_t i = 0; i < flowerbed.size(); ++i) {
        if (flowerbed[i] == 0 && (i == 0 || flowerbed[i - 1] == 0) && (i == flowerbed.size() - 1 || flowerbed[i + 1] == 0)) {
