std::vector<std::vector<std::string>> findDuplicateFiles(const std::vector<std::string>& paths) {
    std::unordered_map<std::string, std::vector<std::string>> contentMap;
    for (const std::string& path : paths) {
        std::istringstream iss(path);
        std::string directory;
        iss >> directory;
        std::string fileToken;
        while (iss >> fileToken) {
            std::size_t posParen = fileToken.find('(');
            std::string fileName = fileToken.substr(0, posParen);
            std::string content = fileToken.substr(posParen + 1);
            if (!content.empty() && content.back() == ')') {
                content.pop_back();
            }
            contentMap[content].push_back(directory + '/' + fileName);
        }
    }
    std::vector<std::vector<std::string>> result;
    for (auto& pair : contentMap) {
        if (pair.second.size() > 1) {
            result.push_back(std::move(pair.second));
        }
    }
    return result;
}

