long long triangleNumber(std::vector<int> nums) {
    std::sort(nums.begin(), nums.end());
    long long count = 0;
    for (int i = static_cast<int>(nums.size()) - 1; i >= 2; --i) {
        int left = 0;
        int right = i - 1;
        while (left < right) {
            if (static_cast<long long>(nums[left]) + nums[right] > nums[i]) {
                count += right - left;
                --right;
            } else {
                ++left;
            }
        }
    }
    return count;
}

