int leastInterval(const std::vector<char>& tasks, int n) {
    std::unordered_map<char, int> frequencyMap;
    for (char task : tasks) {
        frequencyMap[task] = frequencyMap[task] + 1;
    }

    int maxFrequency = 0;
    for (const auto& kv : frequencyMap) {
        maxFrequency = std::max(maxFrequency, kv.second);
    }

    int maxFrequencyCount = 0;
    for (const auto& kv : frequencyMap) {
        if (kv.second == maxFrequency) {
            ++maxFrequencyCount;
        }
    }

    int intervals = (maxFrequency - 1) * (n + 1) + maxFrequencyCount;
    return std::max(intervals, static_cast<int>(tasks.size()));
}

