class MyCircularQueue {
public:
    std::vector<int> q; int head, tail, sz;
    MyCircularQueue(int k) : q(k), head(0), tail(-1), sz(0) {}
    bool enQueue(int value) {
        if (sz == (int)q.size()) return false;
        tail = (tail+1) % q.size();
        q[tail] = value; sz++;
        return true;
    }
    bool deQueue() {
        if (sz == 0) return false;
        head = (head+1) % q.size(); sz--;
        return true;
    }
    int Front() { return sz==0 ? -1 : q[head]; }
    int Rear() { return sz==0 ? -1 : q[tail]; }
    bool isEmpty() { return sz==0; }
    bool isFull() { return sz==(int)q.size(); }
};

