struct Node {
    int val;
    int listIdx;
    int elemIdx;
};

struct CompareNode {
    bool operator()(const Node& a, const Node& b) const {
        return a.val > b.val; // min-heap based on val
    }
};

std::vector<int> smallestRange(const std::vector<std::vector<int>>& nums) {
    if (nums.empty()) return {};
    std::priority_queue<Node, std::vector<Node>, CompareNode> minHeap;
    int maxVal = std::numeric_limits<int>::min();
    for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
        if (!nums[i].empty()) {
            int val = nums[i][0];
            minHeap.push({val, i, 0});
            if (val > maxVal) maxVal = val;
        }
    }
    long long minRange = std::numeric_limits<long long>::max();
    std::vector<int> res(2, -1);
    while (true) {
        Node cur = minHeap.top();   // copy (not reference) so it stays valid after pop()
        int minVal = cur.val;
        if ((long long)maxVal - minVal < minRange) {
            minRange = (long long)maxVal - minVal;
            res[0] = minVal;
            res[1] = maxVal;
        }
        minHeap.pop();
        if (cur.elemIdx + 1 == static_cast<int>(nums[cur.listIdx].size())) {
            break;
        }
        int nextVal = nums[cur.listIdx][cur.elemIdx + 1];
        minHeap.push({nextVal, cur.listIdx, cur.elemIdx + 1});
        if (nextVal > maxVal) {
            maxVal = nextVal;
        }
    }
    return res;
}

