int shoppingOffers(const std::vector<int>& price, const std::vector<std::vector<int>>& special, const std::vector<int>& needs) {
    std::unordered_map<std::string, int> memo;
    std::function<int(const std::vector<int>&)> dfs = [&](const std::vector<int>& curNeeds) -> int {
        std::string key;
        key.reserve(curNeeds.size() * 4);
        for (size_t i = 0; i < curNeeds.size(); ++i) {
            key.append(std::to_string(curNeeds[i]));
            if (i + 1 < curNeeds.size()) key.push_back(',');
        }
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;

        int minCost = 0;
        for (size_t i = 0; i < curNeeds.size(); ++i) {
            minCost += curNeeds[i] * price[i];
        }

        for (const auto& offer : special) {
            std::vector<int> clone = curNeeds;
            bool valid = true;
            for (size_t i = 0; i < curNeeds.size(); ++i) {
                clone[i] -= offer[i];
                if (clone[i] < 0) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                minCost = std::min(minCost, offer.back() + dfs(clone));
            }
        }

        memo.emplace(std::move(key), minCost);
        return minCost;
    };
    return dfs(needs);
}

