std::pair<int,int> parseSide(const std::string& side) {
    int xCoeff = 0, constant = 0;
    size_t i = 0, n = side.size();
    while (i < n) {
        size_t start = i;
        if (side[i] == '+' || side[i] == '-') i++;
        while (i < n && isdigit((unsigned char)side[i])) i++;
        bool hasX = (i < n && side[i] == 'x');
        std::string numPart = side.substr(start, i - start);
        if (hasX) {
            int coeff;
            if (numPart.empty() || numPart == "+") coeff = 1;
            else if (numPart == "-") coeff = -1;
            else coeff = std::stoi(numPart);
            xCoeff += coeff;
            i++;
        } else {
            constant += std::stoi(numPart);
        }
    }
    return {xCoeff, constant};
}

std::string solveEquation(const std::string& equation) {
    size_t eq = equation.find('=');
    std::string left = equation.substr(0, eq);
    std::string right = equation.substr(eq + 1);
    auto [leftX, leftC] = parseSide(left);
    auto [rightX, rightC] = parseSide(right);
    int xCoefficient = leftX - rightX;
    int constant = rightC - leftC;
    if (xCoefficient == 0) {
        return constant == 0 ? "Infinite solutions" : "No solution";
    }
    return "x=" + std::to_string(constant / xCoefficient);
}

