class MyCircularDeque {
public:
    int capacity, sz, head, tail;
    std::vector<int> dq;
    MyCircularDeque(int k) : capacity(k), sz(0), head(0), tail(0), dq(k) {}
    bool insertFront(int value) {
        if (sz == capacity) return false;
        head = (head - 1 + capacity) % capacity;
        dq[head] = value; sz++;
        return true;
    }
    bool insertLast(int value) {
        if (sz == capacity) return false;
        dq[tail] = value;
        tail = (tail+1) % capacity; sz++;
        return true;
    }
    bool deleteFront() {
        if (sz == 0) return false;
        head = (head+1) % capacity; sz--;
        return true;
    }
    bool deleteLast() {
        if (sz == 0) return false;
        tail = (tail - 1 + capacity) % capacity; sz--;
        return true;
    }
    int getFront() { return sz==0 ? -1 : dq[head]; }
    int getRear() { return sz==0 ? -1 : dq[(tail-1+capacity)%capacity]; }
    bool isEmpty() { return sz==0; }
    bool isFull() { return sz==capacity; }
};

