struct TrieNode {
    TrieNode* child[26];
    bool end;
    TrieNode() : end(false) {
        std::memset(child, 0, sizeof(child));
    }
};

static void insertTrie(TrieNode* root, const std::string& word) {
    TrieNode* node = root;
    for (char ch : word) {
        int idx = ch - 'a';
        if (!node->child[idx]) node->child[idx] = new TrieNode();
        node = node->child[idx];
    }
    node->end = true;
}

static std::string searchTrie(TrieNode* root, const std::string& word) {
    TrieNode* node = root;
    std::string prefix;
    for (char ch : word) {
        int idx = ch - 'a';
        if (!node->child[idx]) break;
        node = node->child[idx];
        prefix.push_back(ch);
        if (node->end) return prefix;
    }
    return "";
}

std::string replaceWords(const std::vector<std::string>& dictionary, const std::string& sentence) {
    TrieNode* trie = new TrieNode();
    for (const std::string& root : dictionary) {
        insertTrie(trie, root);
    }

    std::istringstream iss(sentence);
    std::string word;
    std::string result;
    bool first = true;
    while (iss >> word) {
        std::string repl = searchTrie(trie, word);
        if (repl.empty()) repl = word;
        if (!first) result.push_back(' ');
        result += repl;
        first = false;
    }

    // Cleanup allocated trie nodes (optional for short-lived program)
    std::function<void(TrieNode*)> deleteTrie = [&](TrieNode* node) {
        if (!node) return;
        for (int i = 0; i < 26; ++i) deleteTrie(node->child[i]);
        delete node;
    };
    deleteTrie(trie);

    return result;
}

