std::string predictPartyVictory(const std::string& senate) {
    std::queue<int> radiantQueue;
    std::queue<int> direQueue;
    int n = static_cast<int>(senate.size());
    for (int i = 0; i < n; ++i) {
        if (senate[i] == 'R') {
            radiantQueue.push(i);
        } else {
            direQueue.push(i);
        }
    }
    while (!radiantQueue.empty() && !direQueue.empty()) {
        if (radiantQueue.front() < direQueue.front()) {
            radiantQueue.push(radiantQueue.front() + n);
            radiantQueue.pop();
            direQueue.pop();
        } else {
            direQueue.push(direQueue.front() + n);
            direQueue.pop();
            radiantQueue.pop();
        }
    }
    return radiantQueue.empty() ? "Dire" : "Radiant";
}

