int getHeight(TreeNode* node) {
    if (!node) return 0;
    int leftHeight = getHeight(node->left);
    int rightHeight = getHeight(node->right);
    return 1 + (leftHeight > rightHeight ? leftHeight : rightHeight);
}

std::vector<std::vector<std::string>> printTree(TreeNode* root) {
    if (!root) return {};
    int height = getHeight(root);
    int width = (1 << height) - 1;
    std::vector<std::vector<std::string>> res(height, std::vector<std::string>(width, ""));
    std::queue<std::tuple<TreeNode*, int, int, int>> q;
    q.emplace(root, 0, 0, width - 1);
    while (!q.empty()) {
        TreeNode* node;
        int level, start, end;
        std::tie(node, level, start, end) = q.front();
        q.pop();
        int mid = (start + end) / 2;
        res[level][mid] = std::to_string(node->val);
        if (node->left) {
            q.emplace(node->left, level + 1, start, mid - 1);
        }
        if (node->right) {
            q.emplace(node->right, level + 1, mid + 1, end);
        }
    }
    return res;
}

