    for (int num : nums) {
        ++freq[num];
    }
    std::unordered_map<int, int> need;
    for (int num : nums) {
        if (freq[num] == 0) continue;
        if (need[num] > 0) {
            --freq[num];
            --need[num];
            ++need[num + 1];
        } else if (freq[num + 1] > 0 && freq[num + 2] > 0) {
            --freq[num];
