std::vector<std::vector<int>> imageSmoother(const std::vector<std::vector<int>>& img) {
    std::size_t rows = img.size();
    if (rows == 0) return {};
    std::size_t cols = img[0].size();
    std::vector<std::vector<int>> smoothedImg(rows, std::vector<int>(cols));
    for (std::size_t i = 0; i < rows; ++i) {
        for (std::size_t j = 0; j < cols; ++j) {
            int sum = 0;
            int count = 0;
            for (std::size_t x = std::max<std::size_t>(0, i > 0 ? i - 1 : 0); x <= std::min(rows - 1, i + 1); ++x) {
                for (std::size_t y = std::max<std::size_t>(0, j > 0 ? j - 1 : 0); y <= std::min(cols - 1, j + 1); ++y) {
                    sum += img[x][y];
                    ++count;
                }
            }
            smoothedImg[i][j] = sum / count;
        }
    }
    return smoothedImg;
}

