int widthOfBinaryTree(TreeNode* root) {
    int maxWidth = 0;
    std::deque<std::pair<TreeNode*, unsigned long long>> queue;
    queue.emplace_back(root, 0ULL);
    while (!queue.empty()) {
        size_t levelSize = queue.size();
        unsigned long long minIndex = queue.front().second;
        unsigned long long maxIndex = queue.front().second;
        for (size_t i = 0; i < levelSize; ++i) {
            auto nodePair = queue.front();
            queue.pop_front();
            TreeNode* node = nodePair.first;
            unsigned long long index = nodePair.second;
            minIndex = std::min(minIndex, index);
            maxIndex = std::max(maxIndex, index);
            if (node->left) queue.emplace_back(node->left, 2ULL * index + 1ULL);
            if (node->right) queue.emplace_back(node->right, 2ULL * index + 2ULL);
        }
        maxWidth = std::max(maxWidth, static_cast<int>(maxIndex - minIndex + 1ULL));
    }
    return maxWidth;
}

