int strangePrinter(const std::string& s) {
    if (s.empty()) return 0;
    std::string t;
    t.reserve(s.size());
    for (char c : s) {
        if (t.empty() || t.back() != c) t.push_back(c);
    }
    int n = static_cast<int>(t.size());
    std::vector<std::vector<int>> dp(n, std::vector<int>(n, 0));
    for (int i = 0; i < n; ++i) dp[i][i] = 1;
    for (int len = 2; len <= n; ++len) {
        for (int i = 0; i + len - 1 < n; ++i) {
            int j = i + len - 1;
            dp[i][j] = dp[i][j - 1] + 1;
            for (int k = i; k < j; ++k) {
                if (t[k] == t[j]) {
                    int mid = (k + 1 <= j - 1) ? dp[k + 1][j - 1] : 0;
                    dp[i][j] = std::min(dp[i][j], dp[i][k] + mid);
                }
            }
        }
    }
    return dp[0][n - 1];
}

