bool checkValidString(const std::string& s) {
    int left = 0, right = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        if (s[i] == '(') {
            ++left;
            ++right;
        } else if (s[i] == ')') {
            left = std::max(0, left - 1);
            --right;
            if (right < 0) return false;
        } else {
            left = std::max(0, left - 1);
            ++right;
        }
    }
    return left == 0;
}

