int maxProduct(const std::vector<std::string>& words) {
    int maxProduct = 0;
    std::vector<int> bitmasks(words.size(), 0);
    for (size_t i = 0; i < words.size(); ++i) {
        for (char c : words[i]) {
            bitmasks[i] |= 1 << (c - 'a');
        }
    }
    for (size_t i = 0; i < words.size(); ++i) {
        for (size_t j = i + 1; j < words.size(); ++j) {
            if ((bitmasks[i] & bitmasks[j]) == 0) {
                int product = static_cast<int>(words[i].size() * words[j].size());
                maxProduct = std::max(maxProduct, product);
            }
        }
    }
    return maxProduct;
}

