struct TrieNode {
    std::unordered_map<char, TrieNode*> children;
    int sum = 0;
};

struct MapSum {
    std::unordered_map<std::string, int> map;
    TrieNode root;
    void insert(const std::string& key, int val) {
        int delta = val - (map.count(key) ? map[key] : 0);
        map[key] = val;
        TrieNode* node = &root;
        node->sum += delta;
        for (char c : key) {
            if (!node->children.count(c)) node->children[c] = new TrieNode();
            node = node->children[c];
            node->sum += delta;
        }
    }
    int sum(const std::string& prefix) {
        TrieNode* node = &root;
        for (char c : prefix) {
            if (!node->children.count(c)) return 0;
            node = node->children[c];
        }
        return node->sum;
    }
};

