struct Tree {
    int h;
    int r;
    int c;
};

int bfs(const std::vector<std::vector<int>>& grid, int sr, int sc, int tr, int tc,
        std::vector<std::vector<int>>& seen, int mark) {
    if (sr == tr && sc == tc) return 0;
    int m = grid.size();
    int n = grid[0].size();
    std::queue<std::pair<int, int>> q;
    q.emplace(sr, sc);
    seen[sr][sc] = mark;
    int steps = 0;
    const int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
    while (!q.empty()) {
        ++steps;
        int sz = q.size();
        while (sz--) {
            auto rc = q.front();
            q.pop();
            int r = rc.first;
            int c = rc.second;
            for (const auto& d : dirs) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n &&
                    grid[nr][nc] != 0 && seen[nr][nc] != mark) {
                    if (nr == tr && nc == tc) return steps;
                    seen[nr][nc] = mark;
                    q.emplace(nr, nc);
                }
            }
        }
    }
    return -1;
}

int cutOffTree(std::vector<std::vector<int>> forest) {
    int m = forest.size();
    if (m == 0) return -1;
    int n = forest[0].size();
    std::vector<Tree> trees;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (forest[i][j] > 1) {
                trees.push_back({forest[i][j], i, j});
            }
        }
    }
    std::sort(trees.begin(), trees.end(), [](const Tree& a, const Tree& b) {
        return a.h < b.h;
    });
    std::vector<std::vector<int>> seen(m, std::vector<int>(n, 0));
    int mark = 1;
    int sr = 0, sc = 0;
    int total = 0;
    for (const auto& t : trees) {
        int steps = bfs(forest, sr, sc, t.r, t.c, seen, mark++);
        if (steps == -1) return -1;
        total += steps;
        sr = t.r;
        sc = t.c;
    }
    return total;
}

