bool validUtf8(const std::vector<int>& data) {
    int bytesLeft = 0;
    for (size_t i = 0; i < data.size(); ++i) {
        std::string binary = std::bitset<8>(data[i]).to_string();
        if (bytesLeft == 0) {
            if (binary[0] == '0') {
                continue;
            } else if (binary[0] == '1' && binary[1] == '1' && binary[2] == '0') {
                bytesLeft = 1;
            } else if (binary[0] == '1' && binary[1] == '1' && binary[2] == '1' && binary[3] == '0') {
                bytesLeft = 2;
            } else if (binary[0] == '1' && binary[1] == '1' && binary[2] == '1' && binary[3] == '1' && binary[4] == '0') {
                bytesLeft = 3;
            } else {
                return false;
            }
        } else {
            if (binary[0] == '1' && binary[1] == '0') {
                --bytesLeft;
            } else {
                return false;
            }
        }
    }
    if (bytesLeft != 0) {
        return false;
    }
    return true;
}

