std::vector<int> maxNumber(const std::vector<int>& nums1, const std::vector<int>& nums2, int k) {
    auto pickMax = [&](const std::vector<int>& nums, int pick) -> std::vector<int> {
        int drop = static_cast<int>(nums.size()) - pick;
        std::vector<int> out;
        out.reserve(nums.size());
        for (int num : nums) {
            while (!out.empty() && drop > 0 && out.back() < num) {
                out.pop_back();
                --drop;
            }
            out.push_back(num);
        }
        if (static_cast<int>(out.size()) > pick) out.resize(pick);
        return out;
    };

    auto greater = [&](const std::vector<int>& a, const std::vector<int>& b, int aIndex, int bIndex, int /*maxLen*/) -> bool {
        while (aIndex < static_cast<int>(a.size()) && bIndex < static_cast<int>(b.size())) {
            if (a[aIndex] != b[bIndex]) {
                return a[aIndex] > b[bIndex];
            }
            ++aIndex;
            ++bIndex;
        }
        return aIndex < static_cast<int>(a.size());
    };

    auto merge = [&](const std::vector<int>& a, const std::vector<int>& b) -> std::vector<int> {
        std::vector<int> out;
        out.reserve(a.size() + b.size());
        int i = 0, j = 0;
        while (i < static_cast<int>(a.size()) || j < static_cast<int>(b.size())) {
            if (j == static_cast<int>(b.size()) || (i < static_cast<int>(a.size()) && greater(a, b, i, j, a.size() - i))) {
                out.push_back(a[i]);
                ++i;
            } else {
                out.push_back(b[j]);
                ++j;
            }
        }
        return out;
    };

    std::vector<int> max;
    for (int i = std::max(0, k - static_cast<int>(nums2.size())); i <= std::min(k, static_cast<int>(nums1.size())); ++i) {
        std::vector<int> candidate = merge(pickMax(nums1, i), pickMax(nums2, k - i));
        if (greater(candidate, max, 0, 0, static_cast<int>(candidate.size()))) {
            max = std::move(candidate);
        }
    }
    return max;
}

