int shortestPathLength(const std::vector<std::vector<int>>& graph) {
    int n = static_cast<int>(graph.size());
    int allNodesVisited = (1 << n) - 1;
    std::queue<std::tuple<int, int, int>> q;
    std::vector<std::vector<char>> visited(n, std::vector<char>(1 << n, 0));
    for (int i = 0; i < n; ++i) {
        q.emplace(i, 1 << i, 0);
        visited[i][1 << i] = 1;
    }
    while (!q.empty()) {
        int node, bitmask, distance;
        std::tie(node, bitmask, distance) = q.front();
        q.pop();
        if (bitmask == allNodesVisited) {
            return distance;
        }
        for (int neighbor : graph[node]) {
            int newBitmask = bitmask | (1 << neighbor);
            if (!visited[neighbor][newBitmask]) {
                visited[neighbor][newBitmask] = 1;
                q.emplace(neighbor, newBitmask, distance + 1);
            }
        }
    }
    return -1;
}

