int kSimilarity(const std::string& s1, const std::string& s2) {
    std::queue<std::pair<std::string, int>> queue;
    queue.emplace(s1, 0);
    std::unordered_set<std::string> visited;
    visited.insert(s1);
    while (!queue.empty()) {
        auto current = queue.front();
        queue.pop();
        const std::string& curr = current.first;
        int swaps = current.second;
        if (curr == s2) {
            return swaps;
        }
        for (size_t i = 0; i < curr.size(); ++i) {
            if (curr[i] != s2[i]) {
                for (size_t j = i + 1; j < curr.size(); ++j) {
                    if (curr[j] == s2[i]) {
                        std::string next = curr;
                        std::swap(next[i], next[j]);
                        if (visited.find(next) == visited.end()) {
                            visited.insert(next);
                            queue.emplace(next, swaps + 1);
                        }
                    }
                }
                break;
            }
        }
    }
    return -1;
}

