int shortestPathAllKeys(const std::vector<std::string>& grid) {
    int rows = static_cast<int>(grid.size());
    int cols = static_cast<int>(grid[0].size());
    int keys = 0;
    int locks = 0;
    std::queue<std::array<int, 4>> q;
    std::unordered_set<std::string> visited;
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            char cell = grid[i][j];
            if (cell == '@') {
                q.push({i, j, 0, 0});
                visited.insert(std::to_string(i) + "," + std::to_string(j) + ",0");
            } else if (cell >= 'a' && cell <= 'f') {
                ++keys;
            } else if (cell >= 'A' && cell <= 'F') {
                ++locks;
            }
        }
    }
    const int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
    while (!q.empty()) {
        auto cur = q.front();
        q.pop();
        int x = cur[0];
        int y = cur[1];
        int collectedKeys = cur[2];
        int steps = cur[3];
        if (collectedKeys == ((1 << keys) - 1)) {
            return steps;
        }
        for (const auto& d : dirs) {
            int nx = x + d[0];
            int ny = y + d[1];
            if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && grid[nx][ny] != '#') {
                char newCell = grid[nx][ny];
                if (newCell >= 'a' && newCell <= 'f') {
                    int newCollectedKeys = collectedKeys | (1 << (newCell - 'a'));
                    std::string key = std::to_string(nx) + "," + std::to_string(ny) + "," + std::to_string(newCollectedKeys);
                    if (visited.find(key) == visited.end()) {
                        visited.insert(key);
                        q.push({nx, ny, newCollectedKeys, steps + 1});
                    }
                } else if (newCell >= 'A' && newCell <= 'F') {
                    if (collectedKeys & (1 << (newCell - 'A'))) {
                        std::string key = std::to_string(nx) + "," + std::to_string(ny) + "," + std::to_string(collectedKeys);
                        if (visited.find(key) == visited.end()) {
                            visited.insert(key);
                            q.push({nx, ny, collectedKeys, steps + 1});
                        }
                    }
                } else {
                    std::string key = std::to_string(nx) + "," + std::to_string(ny) + "," + std::to_string(collectedKeys);
                    if (visited.find(key) == visited.end()) {
                        visited.insert(key);
                        q.push({nx, ny, collectedKeys, steps + 1});
                    }
                }
            }
        }
    }
    return -1;
}

