class ExamRoom {
public:
    int n;
    std::vector<int> seats;
    ExamRoom(int n_) : n(n_) {}
    int seat() {
        if (seats.empty()) { seats.push_back(0); return 0; }
        int maxDist = seats[0], seatPos = 0;
        for (size_t i = 0; i + 1 < seats.size(); i++) {
            int d = (seats[i+1] - seats[i]) / 2;
            if (d > maxDist) { maxDist = d; seatPos = seats[i] + d; }
        }
        if (n - 1 - seats.back() > maxDist) seatPos = n - 1;
        seats.insert(std::upper_bound(seats.begin(), seats.end(), seatPos), seatPos);
        return seatPos;
    }
    void leave(int p) {
        seats.erase(std::find(seats.begin(), seats.end(), p));
    }
};

