double mincostToHireWorkers(const std::vector<int>& quality, const std::vector<int>& wage, int k) {
    std::vector<std::pair<double, int>> workers;
    workers.reserve(quality.size());
    for (size_t i = 0; i < quality.size(); ++i) {
        double ratio = static_cast<double>(wage[i]) / static_cast<double>(quality[i]);
        workers.emplace_back(ratio, quality[i]);
    }
    std::sort(workers.begin(), workers.end(),
              [](const std::pair<double, int>& a, const std::pair<double, int>& b) {
                  return a.first < b.first;
              });
    double result = std::numeric_limits<double>::infinity();
    long long qualitySum = 0;
    std::priority_queue<int> maxHeap;
    for (const auto& w : workers) {
        qualitySum += w.second;
        maxHeap.push(w.second);
        if (static_cast<int>(maxHeap.size()) > k) {
            qualitySum -= maxHeap.top();
            maxHeap.pop();
        }
        if (static_cast<int>(maxHeap.size()) == k) {
            double cost = static_cast<double>(qualitySum) * w.first;
            if (cost < result) {
                result = cost;
            }
        }
    }
    return result;
}

