class RLEIterator {
public:
    std::vector<int> encoding;
    size_t index = 0;
    RLEIterator(std::vector<int> enc) : encoding(enc) {}
    int next(int num) {
        while (index < encoding.size()) {
            int remaining = encoding[index];
            if (num <= remaining) {
                encoding[index] -= num;
                return encoding[index+1];
            }
            num -= remaining;
            index += 2;
        }
        return -1;
    }
};

