int dieSimulator(int n, const std::vector<int>& rollMax) {
    const int MOD = 1000000007;
    if (n == 0) return 0;
    std::vector<std::vector<std::vector<int>>> dp(n + 1, std::vector<std::vector<int>>(6, std::vector<int>(16, 0)));
    for (int i = 0; i < 6; ++i) {
        dp[1][i][1] = 1;
    }
    for (int i = 2; i <= n; ++i) {
        for (int j = 0; j < 6; ++j) {
            for (int k = 1; k <= 15; ++k) {
                for (int prev = 0; prev < 6; ++prev) {
                    if (prev != j) {
                        dp[i][j][1] = (dp[i][j][1] + dp[i - 1][prev][k]) % MOD;
                    } else if (k < rollMax[j]) {
                        dp[i][j][k + 1] = (dp[i][j][k + 1] + dp[i - 1][prev][k]) % MOD;
                    }
                }
            }
        }
    }
    long long res = 0;
    for (int i = 0; i < 6; ++i) {
        for (int j = 1; j <= 15; ++j) {
            res = (res + dp[n][i][j]) % MOD;
        }
    }
    return static_cast<int>(res);
}

