std::vector<int> threeEqualParts(const std::vector<int>& arr) {
    int n = static_cast<int>(arr.size());
    int totalOnes = 0;
    for (int bit : arr) {
        totalOnes += bit;
    }
    if (totalOnes == 0) {
        return {0, n - 1};
    }
    if (totalOnes % 3 != 0) {
        return {-1, -1};
    }
    int onesPerPart = totalOnes / 3;
    int first = -1, second = -1, third = -1;
    int count = 0;
    for (int i = 0; i < n; ++i) {
        if (arr[i] == 1) {
            if (count == 0) first = i;
            else if (count == onesPerPart) second = i;
            else if (count == 2 * onesPerPart) third = i;
            ++count;
        }
    }
    int len = n - third;
    if (first + len > second || second + len > n) {
        return {-1, -1};
    }
    for (int i = 0; i < len; ++i) {
        if (arr[first + i] != arr[second + i] || arr[first + i] != arr[third + i]) {
            return {-1, -1};
        }
    }
    return {first + len - 1, second + len};
}

