int maxEqualFreq(const std::vector<int>& nums) {
    std::unordered_map<int, int> freq;
    std::unordered_map<int, int> freqCount;
    int maxFreq = 0;
    int result = 0;
    for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
        int x = nums[i];
        int oldFreq = freq[x];
        if (oldFreq > 0) {
            auto it = freqCount.find(oldFreq);
            if (it != freqCount.end()) {
                if (--(it->second) == 0) {
                    freqCount.erase(it);
                }
            }
        }
        int newFreq = oldFreq + 1;
        freq[x] = newFreq;
        ++freqCount[newFreq];
        if (newFreq > maxFreq) {
            maxFreq = newFreq;
        }
        int total = i + 1;
        bool ok = false;
        if (maxFreq == 1) {
            ok = true;
        } else {
            int cntMax = freqCount.count(maxFreq) ? freqCount[maxFreq] : 0;
            int cntMaxMinus1 = freqCount.count(maxFreq - 1) ? freqCount[maxFreq - 1] : 0;
            int cnt1 = freqCount.count(1) ? freqCount[1] : 0;
            if (cntMax == 1 && (maxFreq - 1) * (cntMaxMinus1 + 1) == total) {
                ok = true;
            }
            if (cnt1 == 1 && maxFreq * cntMax == total - 1) {
                ok = true;
            }
        }
        if (ok) {
            result = total;
        }
    }
    return result;
}

