int kthFactor(int n, int k) {
    std::vector<int> factors;
    int limit = static_cast<int>(std::sqrt(n));
    for (int i = 1; i <= limit; ++i) {
        if (n % i == 0) {
            factors.push_back(i);
            if (i != n / i) {
                factors.push_back(n / i);
