            height[j] = (mat[i][j] == 1) ? height[j] + 1 : 0;
        }
        std::vector<std::size_t> stack;
        for (std::size_t j = 0; j <= n; ++j) {
            while (!stack.empty() && (j == n || height[j] < height[stack.back()])) {
                int h = height[stack.back()];
                stack.pop_back();
