double maxProbability(int n, const std::vector<std::vector<int>>& edges, const std::vector<double>& succProb, int start, int end) {
    std::vector<std::vector<std::pair<int, double>>> graph(n);
    for (size_t i = 0; i < edges.size(); ++i) {
        int u = edges[i][0];
        int v = edges[i][1];
        double p = succProb[i];
        graph[u].push_back({v, p});
        graph[v].push_back({u, p});
    }

    std::vector<double> maxProb(n, 0.0);
    maxProb[start] = 1.0;

    std::vector<std::pair<int, double>> pq;
    pq.push_back({start, 1.0});

    while (!pq.empty()) {
        int node = pq[0].first;
        double prob = pq[0].second;
        pq.erase(pq.begin());

        if (node == end) return prob;
        if (prob < maxProb[node]) continue;

        for (const auto& neighborInfo : graph[node]) {
            int neighbor = neighborInfo.first;
            double edgeProb = neighborInfo.second;
            double newProb = prob * edgeProb;
            if (newProb > maxProb[neighbor]) {
                maxProb[neighbor] = newProb;
                pq.push_back({neighbor, newProb});
                std::sort(pq.begin(), pq.end(),
                          [](const std::pair<int, double>& a, const std::pair<int, double>& b) {
                              return a.second > b.second;
                          });
            }
        }
    }
    return 0.0;
}

