std::vector<bool> canEat(const std::vector<long long>& candiesCount, const std::vector<std::vector<long long>>& queries) {
    std::vector<long long> prefix(candiesCount.size(), 0);
    if (!candiesCount.empty()) {
        prefix[0] = candiesCount[0];
        for (size_t i = 1; i < candiesCount.size(); ++i) {
            prefix[i] = prefix[i - 1] + candiesCount[i];
        }
    }

    std::vector<bool> answer(queries.size(), false);
    for (size_t i = 0; i < queries.size(); ++i) {
        long long favoriteType = queries[i][0];
        long long favoriteDay = queries[i][1];
        long long dailyCap = queries[i][2];

        long long minCandiesToEat = favoriteDay + 1;
        long long maxCandiesToEat = (favoriteDay + 1) * dailyCap;

        long long candiesBefore = favoriteType > 0 ? prefix[favoriteType - 1] : 0;
        long long candiesUpTo = prefix[favoriteType];

        if (minCandiesToEat <= candiesUpTo && maxCandiesToEat > candiesBefore) {
            answer[i] = true;
        }
    }
    return answer;
}

