int minimumSize(const std::vector<int>& nums, int maxOperations) {
    auto canDivide = [&](int maxBalls) -> bool {
        long long operations = 0;
        for (int num : nums) {
            operations += (static_cast<long long>(num) + maxBalls - 1) / maxBalls - 1;
            if (operations > maxOperations) return false;
        }
        return operations <= maxOperations;
    };
    int left = 1;
    int right = *std::max_element(nums.begin(), nums.end());
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (canDivide(mid)) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }
    return left;
}

