int maxValue(std::vector<std::vector<int>>& events, int k) {
    int n = static_cast<int>(events.size());
    std::vector<std::array<int, 3>> ev(n);
    for (int i = 0; i < n; ++i) {
        ev[i] = {events[i][0], events[i][1], events[i][2]};
    }
    std::sort(ev.begin(), ev.end(), [](const std::array<int, 3>& a, const std::array<int, 3>& b) {
        return a[0] < b[0];
    });
    std::vector<int> starts(n);
    for (int i = 0; i < n; ++i) starts[i] = ev[i][0];
    std::vector<int> nxt(n);
    for (int i = 0; i < n; ++i) {
        nxt[i] = static_cast<int>(std::lower_bound(starts.begin(), starts.end(), ev[i][1] + 1) - starts.begin());
    }
    std::vector<std::vector<long long>> dp(n + 1, std::vector<long long>(k + 1, 0));
    for (int i = n - 1; i >= 0; --i) {
        for (int j = 1; j <= k; ++j) {
            long long take = ev[i][2] + dp[nxt[i]][j - 1];
            long long skip = dp[i + 1][j];
            dp[i][j] = take > skip ? take : skip;
        }
    }
    return static_cast<int>(dp[0][k]);
}

