std::vector<long long> countPairsOfNodes(int n, const std::vector<std::vector<int>>& edges, const std::vector<int>& queries) {
    std::vector<int> degree(n + 1, 0);
    std::unordered_map<long long, int> edgeCount;
    edgeCount.reserve(edges.size() * 2);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        ++degree[u];
        ++degree[v];
        if (u > v) std::swap(u, v);
        long long key = (static_cast<long long>(u) << 32) | static_cast<unsigned int>(v);
        ++edgeCount[key];
    }

    std::vector<int> sortedDeg;
    sortedDeg.reserve(n);
    for (int i = 1; i <= n; ++i) {
        sortedDeg.push_back(degree[i]);
    }
    std::sort(sortedDeg.begin(), sortedDeg.end());

    std::vector<long long> result;
    result.reserve(queries.size());

    for (int q : queries) {
        long long total = 0;
        int l = 0, r = n - 1;
        while (l < r) {
            if (sortedDeg[l] + sortedDeg[r] > q) {
                total += (r - l);
                --r;
            } else {
                ++l;
            }
        }
        for (const auto& kv : edgeCount) {
            int u = static_cast<int>(kv.first >> 32);
            int v = static_cast<int>(kv.first & 0xffffffffULL);
            int cnt = kv.second;
            if (degree[u] + degree[v] > q && degree[u] + degree[v] - cnt <= q) {
                --total;
            }
        }
        result.push_back(total);
    }
    return result;
}

