int minTrioDegree(int n, const std::vector<std::vector<int>>& edges) {
    std::vector<std::vector<bool>> adj(n + 1, std::vector<bool>(n + 1, false));
    std::vector<int> deg(n + 1, 0);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        adj[u][v] = adj[v][u] = true;
        ++deg[u];
        ++deg[v];
    }
    int ans = INT_MAX;
    for (int i = 1; i <= n; ++i) {
        for (int j = i + 1; j <= n; ++j) {
            if (!adj[i][j]) continue;
            for (int k = j + 1; k <= n; ++k) {
                if (adj[i][k] && adj[j][k]) {
                    int cur = deg[i] + deg[j] + deg[k] - 6;
                    ans = std::min(ans, cur);
                }
            }
        }
    }
    return ans == INT_MAX ? -1 : ans;
}

