    size_t repetitions = (b.size() + a.size() - 1) / a.size();
    std::string repeated;
    repeated.reserve(a.size() * (repetitions + 1));
    for (size_t i = 0; i < repetitions; ++i) {
        repeated += a;
    }
    if (repeated.find(b) != std::string::npos) {
        return static_cast<int>(repetitions);
    }
    repeated += a;
    if (repeated.find(b) != std::string::npos) {
        return static_cast<int>(repetitions + 1);
    }
    return -1;
}

