std::vector<int> findRedundantConnection(const std::vector<std::vector<int>>& edges) {
    std::vector<int> parent(edges.size() + 1);
    for (size_t i = 0; i < parent.size(); ++i) {
        parent[i] = static_cast<int>(i);
    }
    std::function<int(int)> find = [&](int node) -> int {
        if (parent[node] != node) {
            parent[node] = find(parent[node]);
        }
        return parent[node];
    };
    auto unite = [&](int node1, int node2) -> bool {
        int root1 = find(node1);
        int root2 = find(node2);
        if (root1 == root2) return false;
        parent[root1] = root2;
        return true;
    };
    for (const auto& edge : edges) {
        int node1 = edge[0];
        int node2 = edge[1];
        if (!unite(node1, node2)) return edge;
    }
    return {};
}

