std::vector<int> findRedundantDirectedConnection(std::vector<std::vector<int>>& edges) {
    int n = static_cast<int>(edges.size());
    std::vector<int> parent(n + 1, 0);
    std::vector<int> edge1, edge2;
    int edge2Idx = -1;
    for (int i = 0; i < n; ++i) {
        int u = edges[i][0];
        int v = edges[i][1];
        if (parent[v] == 0) {
            parent[v] = u;
        } else {
            edge1 = {parent[v], v};
            edge2 = {u, v};
            edge2Idx = i;
        }
    }
    std::vector<int> dsu(n + 1);
    std::iota(dsu.begin(), dsu.end(), 0);
    std::function<int(int)> find = [&](int x) {
        return dsu[x] == x ? x : dsu[x] = find(dsu[x]);
    };
    auto unite = [&](int a, int b) -> bool {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return false;
        dsu[rb] = ra;
        return true;
    };
    for (int i = 0; i < n; ++i) {
        if (i == edge2Idx) continue;
        int u = edges[i][0];
        int v = edges[i][1];
        if (!unite(u, v)) {
            return edge2Idx == -1 ? std::vector<int>{u, v} : edge1;
        }
    }
    return edge2Idx == -1 ? std::vector<int>() : edge2;
}

