double knightProbability(int n, int k, int row, int column) {
    const std::pair<int, int> moves[8] = {
        {-2, -1}, {-1, -2}, {1, -2}, {2, -1},
        {-2, 1}, {-1, 2}, {1, 2}, {2, 1}
    };
    std::vector<std::vector<std::vector<double>>> memo(
        n, std::vector<std::vector<double>>(n, std::vector<double>(k + 1, -1.0))
    );
    std::function<double(int, int, int)> calculateProbability = [&](int x, int y, int movesLeft) -> double {
        if (x < 0 || x >= n || y < 0 || y >= n) return 0.0;
        if (movesLeft == 0) return 1.0;
        if (memo[x][y][movesLeft] != -1.0) return memo[x][y][movesLeft];
        double probability = 0.0;
        for (const auto& move : moves) {
            probability += calculateProbability(x + move.first, y + move.second, movesLeft - 1) / 8.0;
        }
        memo[x][y][movesLeft] = probability;
        return probability;
    };
    return calculateProbability(row, column, k);
}

