std::vector<int> maxSumOfThreeSubarrays(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    std::vector<long long> prefixSum(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        prefixSum[i + 1] = prefixSum[i] + nums[i];
    }
    std::vector<long long> sum1(n - k + 1, 0);
    for (int i = 0; i <= n - k; ++i) {
        sum1[i] = prefixSum[i + k] - prefixSum[i];
    }
    std::vector<long long> sum2(n - 2 * k + 1, 0);
    for (int i = 0; i <= n - 2 * k; ++i) {
        long long maxSum = std::numeric_limits<long long>::lowest();
        for (int j = i + k; j <= n - k; ++j) {
            maxSum = std::max(maxSum, sum1[i] + sum1[j]);
        }
        sum2[i] = maxSum;
    }
    long long maxSum = std::numeric_limits<long long>::lowest();
    std::vector<int> result;
    for (int i = 0; i <= n - 3 * k; ++i) {
        for (int j = i + k; j <= n - 2 * k; ++j) {
            for (int m = j + k; m <= n - k; ++m) {
                long long currentSum = sum1[i] + sum1[j] + sum1[m];
                if (currentSum > maxSum) {
                    maxSum = currentSum;
                    result = {i, j, m};
                } else if (currentSum == maxSum) {
                    if (result.empty() || i < result[0] || (i == result[0] && j < result[1]) || (i == result[0] && j == result[1] && m < result[2])) {
                        result = {i, j, m};
                    }
                }
            }
        }
    }
    return result;
}

