std::vector<std::string> topKFrequent(const std::vector<std::string>& words, int k) {
    std::unordered_map<std::string, int> frequencyMap;
    for (const auto& word : words) {
        auto it = frequencyMap.find(word);
        if (it != frequencyMap.end()) {
            ++(it->second);
        } else {
            frequencyMap[word] = 1;
        }
    }
    std::vector<std::pair<std::string, int>> wordFrequencies;
    wordFrequencies.reserve(frequencyMap.size());
    for (const auto& entry : frequencyMap) {
        wordFrequencies.emplace_back(entry.first, entry.second);
    }
    std::sort(wordFrequencies.begin(), wordFrequencies.end(),
        [](const std::pair<std::string, int>& a, const std::pair<std::string, int>& b) {
            if (a.second != b.second) {
                return b.second < a.second;
            }
            return a.first < b.first;
        });
    std::vector<std::string> result;
    result.reserve(k);
    for (int i = 0; i < k; ++i) {
        result.push_back(wordFrequencies[i].first);
    }
    return result;
}

