int minStickers(const std::vector<std::string>& stickers, const std::string& target) {
    std::vector<std::array<int, 26>> stickerCounts;
    stickerCounts.reserve(stickers.size());
    for (const std::string& s : stickers) {
        std::array<int, 26> cnt{};
        cnt.fill(0);
        for (char c : s) {
            cnt[c - 'a']++;
        }
        stickerCounts.push_back(cnt);
    }

    std::unordered_map<std::string, int> memo;
    std::function<int(const std::string&)> dfs = [&](const std::string& cur) -> int {
        if (cur.empty()) return 0;
        auto it = memo.find(cur);
        if (it != memo.end()) return it->second;

        std::array<int, 26> need{};
        need.fill(0);
        for (char c : cur) need[c - 'a']++;

        int best = INT_MAX;
        for (const auto& st : stickerCounts) {
            if (st[cur[0] - 'a'] == 0) continue;
            std::string next;
            for (int i = 0; i < 26; ++i) {
                int remain = need[i] - st[i];
                if (remain > 0) next.append(remain, static_cast<char>('a' + i));
            }
            int sub = dfs(next);
            if (sub != -1 && sub + 1 < best) best = sub + 1;
        }

        memo[cur] = (best == INT_MAX ? -1 : best);
        return memo[cur];
    };

    return dfs(target);
}

