int findShortestSubArray(const std::vector<int>& nums) {
    struct Info {
        int frequency;
        int firstIndex;
        int lastIndex;
    };
    std::unordered_map<int, Info> map;
    for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
        if (map.find(nums[i]) == map.end()) {
            map[nums[i]] = {0, i, i};
        }
        map[nums[i]].frequency++;
        map[nums[i]].lastIndex = i;
    }
    int maxFrequency = 0;
    for (const auto& kv : map) {
        maxFrequency = std::max(maxFrequency, kv.second.frequency);
    }
    int minLength = std::numeric_limits<int>::max();
    for (const auto& kv : map) {
        if (kv.second.frequency == maxFrequency) {
            int length = kv.second.lastIndex - kv.second.firstIndex + 1;
            minLength = std::min(minLength, length);
        }
    }
    return minLength;
}

