bool canPartitionKSubsets(std::vector<int> nums, int k) {
    int totalSum = std::accumulate(nums.begin(), nums.end(), 0);
    if (totalSum % k != 0) return false;
    int targetSum = totalSum / k;
    std::sort(nums.begin(), nums.end(), std::greater<int>());
    std::vector<int> subsetSums(k, 0);
    std::function<bool(int)> backtrack = [&](int index) -> bool {
        if (index == static_cast<int>(nums.size())) {
            return std::all_of(subsetSums.begin(), subsetSums.end(),
                               [&](int sum) { return sum == targetSum; });
        }
        for (int i = 0; i < k; ++i) {
            if (subsetSums[i] + nums[index] > targetSum) continue;
            subsetSums[i] += nums[index];
            if (backtrack(index + 1)) return true;
            subsetSums[i] -= nums[index];
        }
        return false;
    };
    return backtrack(0);
}

