struct ListNode {
    int val;
    ListNode* next;
    ListNode* prev;
    ListNode(int v) : val(v), next(nullptr), prev(nullptr) {}
};

class MyLinkedList {
    ListNode* head;
    ListNode* tail;
    int size;
public:
    MyLinkedList() : head(nullptr), tail(nullptr), size(0) {}

    ListNode* getNode(int index) {
        if (index <= size / 2) {
            ListNode* node = head;
            for (int i = 0; i < index; ++i) {
                node = node->next;
            }
            return node;
        } else {
            ListNode* node = tail;
            for (int i = 0; i < size - index - 1; ++i) {
                node = node->prev;
            }
            return node;
        }
    }

    void addAtHead(int val) {
        ListNode* newNode = new ListNode(val);
        if (head == nullptr) {
            head = newNode;
            tail = newNode;
        } else {
            newNode->next = head;
            head->prev = newNode;
            head = newNode;
        }
        ++size;
    }

    void addAtTail(int val) {
        ListNode* newNode = new ListNode(val);
        if (tail == nullptr) {
            head = newNode;
            tail = newNode;
        } else {
            newNode->prev = tail;
            tail->next = newNode;
            tail = newNode;
        }
        ++size;
    }

    void addAtIndex(int index, int val) {
        if (index == 0) {
            addAtHead(val);
        } else if (index == size) {
            addAtTail(val);
        } else if (index < 0 || index > size) {
            return;
        } else {
            ListNode* prevNode = getNode(index - 1);
            ListNode* newNode = new ListNode(val);
            newNode->next = prevNode->next;
            newNode->prev = prevNode;
            prevNode->next->prev = newNode;
            prevNode->next = newNode;
            ++size;
        }
    }

    void deleteAtIndex(int index) {
        if (index < 0 || index >= size) {
            return;
        }
        if (index == 0) {
            if (size == 1) {
                delete head;
                head = nullptr;
                tail = nullptr;
            } else {
                ListNode* oldHead = head;
                head = head->next;
                head->prev = nullptr;
                delete oldHead;
            }
        } else if (index == size - 1) {
            ListNode* oldTail = tail;
            tail = tail->prev;
            tail->next = nullptr;
            delete oldTail;
        } else {
            ListNode* node = getNode(index);
            node->prev->next = node->next;
            node->next->prev = node->prev;
            delete node;
        }
        --size;
    }

    int get(int index) {
        if (index < 0 || index >= size) {
            return -1;
        }
        return getNode(index)->val;
    }
};

