int minimumDeleteSum(const std::string& s1, const std::string& s2) {
    std::vector<std::vector<int>> dp(s1.length() + 1, std::vector<int>(s2.length() + 1, 0));
    for (size_t i = 1; i <= s1.length(); ++i)
        dp[i][0] = dp[i - 1][0] + static_cast<int>(s1[i - 1]);
    for (size_t j = 1; j <= s2.length(); ++j)
        dp[0][j] = dp[0][j - 1] + static_cast<int>(s2[j - 1]);
    for (size_t i = 1; i <= s1.length(); ++i)
        for (size_t j = 1; j <= s2.length(); ++j)
            if (s1[i - 1] == s2[j - 1])
                dp[i][j] = dp[i - 1][j - 1];
            else
                dp[i][j] = std::min(dp[i - 1][j] + static_cast<int>(s1[i - 1]), dp[i][j - 1] + static_cast<int>(s2[j - 1]));
    return dp[s1.length()][s2.length()];
}

