class RangeModule {
public:
    std::vector<std::pair<int, int>> intervals;
    RangeModule() {}

    void addRange(int left, int right) {
        std::vector<std::pair<int, int>> result;
        int i = 0, n = intervals.size();
        while (i < n && intervals[i].second < left) {
            result.push_back(intervals[i]);
            ++i;
        }
        while (i < n && intervals[i].first <= right) {
            left = std::min(left, intervals[i].first);
            right = std::max(right, intervals[i].second);
            ++i;
        }
        result.emplace_back(left, right);
        while (i < n) {
            result.push_back(intervals[i]);
            ++i;
        }
        intervals.swap(result);
    }

    bool queryRange(int left, int right) {
        for (const auto& p : intervals) {
            if (p.first <= left && p.second >= right) {
                return true;
            }
            if (p.first > left) {
                break;
            }
        }
        return false;
    }

    void removeRange(int left, int right) {
        std::vector<std::pair<int, int>> result;
        for (const auto& p : intervals) {
            if (p.second <= left || p.first >= right) {
                result.push_back(p);
            } else {
                if (p.first < left) {
                    result.emplace_back(p.first, left);
                }
                if (p.second > right) {
                    result.emplace_back(right, p.second);
                }
            }
        }
        intervals.swap(result);
    }
};

