int findLength(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    std::vector<std::vector<int>> dp(nums1.size() + 1, std::vector<int>(nums2.size() + 1, 0));
    int maxLength = 0;
    for (size_t i = 1; i <= nums1.size(); ++i) {
        for (size_t j = 1; j <= nums2.size(); ++j) {
            if (nums1[i - 1] == nums2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
                maxLength = std::max(maxLength, dp[i][j]);
            }
        }
    }
    return maxLength;
}

