std::vector<std::string> removeComments(const std::vector<std::string>& source) {
    std::vector<std::string> result;
    bool blockComment = false;
    std::string currentLine;
    auto trim = [](const std::string& s) -> std::string {
        size_t start = s.find_first_not_of(" \t\r\n\f\v");
        if (start == std::string::npos) return "";
        size_t end = s.find_last_not_of(" \t\r\n\f\v");
        return s.substr(start, end - start + 1);
    };
    for (size_t i = 0; i < source.size(); ++i) {
        const std::string& line = source[i];
        size_t j = 0;
        while (j < line.size()) {
            if (!blockComment && line.substr(j, 2) == "/*") {
                blockComment = true;
                j += 2;
            } else if (blockComment && line.substr(j, 2) == "*/") {
                blockComment = false;
                j += 2;
            } else if (!blockComment && line.substr(j, 2) == "//") {
                break;
            } else if (!blockComment) {
                currentLine += line[j];
                ++j;
            } else {
                ++j;
            }
        }
        if (!blockComment) {
            std::string trimmed = trim(currentLine);
            if (!trimmed.empty()) {
                result.push_back(trimmed);
                currentLine.clear();
            }
        }
    }
    return result;
}

