std::string find(const std::string& email, std::unordered_map<std::string, std::string>& parent) {
    if (parent[email] == email) return email;
    return parent[email] = find(parent[email], parent);
}

void unite(const std::string& email1, const std::string& email2, std::unordered_map<std::string, std::string>& parent) {
    std::string parent1 = find(email1, parent);
    std::string parent2 = find(email2, parent);
    if (parent1 != parent2) parent[parent1] = parent2;
}

std::vector<std::vector<std::string>> accountsMerge(const std::vector<std::vector<std::string>>& accounts) {
    std::unordered_map<std::string, std::string> parent;
    std::unordered_map<std::string, std::string> name;
    for (const auto& account : accounts) {
        const std::string& accountName = account[0];
        for (size_t i = 1; i < account.size(); ++i) {
            const std::string& email = account[i];
            parent[email] = email;
            name[email] = accountName;
        }
    }
    for (const auto& account : accounts) {
        for (size_t i = 1; i + 1 < account.size(); ++i) {
            unite(account[i], account[i + 1], parent);
        }
    }
    std::unordered_map<std::string, std::vector<std::string>> merged;
    for (const auto& kv : parent) {
        const std::string& email = kv.first;
        std::string parentEmail = find(email, parent);
        merged[parentEmail].push_back(email);
    }
    std::vector<std::vector<std::string>> result;
    result.reserve(merged.size());
    for (auto& kv : merged) {
        std::vector<std::string>& emails = kv.second;
        std::sort(emails.begin(), emails.end());
        std::vector<std::string> entry;
        entry.reserve(emails.size() + 1);
        entry.push_back(name[kv.first]);
        entry.insert(entry.end(), emails.begin(), emails.end());
        result.push_back(std::move(entry));
    }
    return result;
}

