std::string countOfAtoms(const std::string& formula) {
    std::vector<std::unordered_map<std::string, long long>> stack;
    stack.emplace_back();
    size_t i = 0;
    const size_t n = formula.size();
    while (i < n) {
        if (std::isupper(static_cast<unsigned char>(formula[i]))) {
            std::string name;
            name += formula[i++];
            while (i < n && std::islower(static_cast<unsigned char>(formula[i]))) {
                name += formula[i++];
            }
            long long count = 0;
            while (i < n && std::isdigit(static_cast<unsigned char>(formula[i]))) {
                count = count * 10 + (formula[i++] - '0');
            }
            if (count == 0) count = 1;
            stack.back()[name] += count;
        } else if (formula[i] == '(') {
            stack.emplace_back();
            ++i;
        } else if (formula[i] == ')') {
            ++i;
            long long count = 0;
            while (i < n && std::isdigit(static_cast<unsigned char>(formula[i]))) {
                count = count * 10 + (formula[i++] - '0');
            }
            if (count == 0) count = 1;
            auto temp = std::move(stack.back());
            stack.pop_back();
            for (const auto& kv : temp) {
                stack.back()[kv.first] += kv.second * count;
            }
        } else {
            ++i;
        }
    }
    std::vector<std::string> keys;
    keys.reserve(stack[0].size());
    for (const auto& kv : stack[0]) {
        keys.push_back(kv.first);
    }
    std::sort(keys.begin(), keys.end());
    std::string result;
    for (const auto& name : keys) {
        result += name;
        long long cnt = stack[0][name];
        if (cnt > 1) {
            result += std::to_string(cnt);
        }
    }
    return result;
}

