#include <bits/stdc++.h>

long long countPalindromicSubsequences(const std::string& s) {
    const long long MOD = 1000000007LL;
    int n = static_cast<int>(s.size());
    if (n == 0) return 0;
    std::vector<std::vector<int>> nextPos(4, std::vector<int>(n, n));
    std::vector<std::vector<int>> prevPos(4, std::vector<int>(n, -1));
    std::array<int,4> last{-1,-1,-1,-1};
    for (int i = 0; i < n; ++i) {
        int c = s[i] - 'a';
        last[c] = i;
        for (int ch = 0; ch < 4; ++ch) {
            prevPos[ch][i] = last[ch];
        }
    }
    std::array<int,4> nxt{n,n,n,n};
    for (int i = n - 1; i >= 0; --i) {
        int c = s[i] - 'a';
        nxt[c] = i;
        for (int ch = 0; ch < 4; ++ch) {
            nextPos[ch][i] = nxt[ch];
        }
    }
    std::vector<std::vector<long long>> dp(n, std::vector<long long>(n, 0));
    for (int i = 0; i < n; ++i) dp[i][i] = 1;
    for (int len = 2; len <= n; ++len) {
        for (int i = 0; i + len - 1 < n; ++i) {
            int j = i + len - 1;
            if (s[i] != s[j]) {
                dp[i][j] = (dp[i + 1][j] + dp[i][j - 1] - dp[i + 1][j - 1]) % MOD;
            } else {
                int c = s[i] - 'a';
                int i2 = nextPos[c][i + 1];
                int j2 = prevPos[c][j - 1];
                if (i2 > j2) {
                    dp[i][j] = (dp[i + 1][j - 1] * 2 + 2) % MOD;
                } else if (i2 == j2) {
                    dp[i][j] = (dp[i + 1][j - 1] * 2 + 1) % MOD;
                } else {
                    dp[i][j] = (dp[i + 1][j - 1] * 2 - dp[i2 + 1][j2 - 1]) % MOD;
                }
            }
            if (dp[i][j] < 0) dp[i][j] += MOD;
        }
    }
    return dp[0][n - 1] % MOD;
}

