std::vector<std::vector<int>> floodFill(std::vector<std::vector<int>> image, int sr, int sc, int color) {
    if (image[sr][sc] == color) return image;
    const std::vector<std::pair<int, int>> directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    int originalColor = image[sr][sc];
    std::function<void(int, int)> dfs = [&](int row, int col) {
        if (row < 0 || row >= static_cast<int>(image.size()) || col < 0 || col >= static_cast<int>(image[0].size()) || image[row][col] != originalColor) return;
        image[row][col] = color;
        for (const auto& direction : directions) {
            dfs(row + direction.first, col + direction.second);
        }
    };
    dfs(sr, sc);
    return image;
}

