static std::string readToken(const std::string& s, int& i) {
    int start = i;
    while (i < (int)s.size() && s[i] != ' ' && s[i] != ')') ++i;
    return s.substr(start, i - start);
}

static int lookupVar(const std::string& var, const std::vector<std::unordered_map<std::string, int>>& scopes) {
    for (int k = (int)scopes.size() - 1; k >= 0; --k) {
        auto it = scopes[k].find(var);
        if (it != scopes[k].end()) return it->second;
    }
    return 0;
}

static int eval(const std::string& s, int& i, std::vector<std::unordered_map<std::string, int>>& scopes) {
    if (s[i] != '(') {
        if (s[i] == '-' || std::isdigit(s[i])) {
            int sign = 1;
            if (s[i] == '-') { sign = -1; ++i; }
            int num = 0;
            while (i < (int)s.size() && std::isdigit(s[i])) {
                num = num * 10 + (s[i] - '0');
                ++i;
            }
            return sign * num;
        } else {
            std::string var;
            while (i < (int)s.size() && s[i] != ' ' && s[i] != ')') {
                var.push_back(s[i]);
                ++i;
            }
            return lookupVar(var, scopes);
        }
    }

    ++i; // skip '('
    while (s[i] == ' ') ++i;
    std::string op = readToken(s, i);
    while (s[i] == ' ') ++i;

    if (op == "add") {
        int v1 = eval(s, i, scopes);
        while (s[i] == ' ') ++i;
        int v2 = eval(s, i, scopes);
        while (s[i] == ' ') ++i;
        ++i; // skip ')'
        return v1 + v2;
    } else if (op == "mult") {
        int v1 = eval(s, i, scopes);
        while (s[i] == ' ') ++i;
        int v2 = eval(s, i, scopes);
        while (s[i] == ' ') ++i;
        ++i; // skip ')'
        return v1 * v2;
    } else { // let
        scopes.emplace_back();
        while (true) {
            while (s[i] == ' ') ++i;
            if (s[i] == ')') {
                ++i; // consume ')'
                scopes.pop_back();
                return 0;
            }
            if (s[i] == '(') {
                int result = eval(s, i, scopes);
                while (s[i] == ' ') ++i;
                ++i; // consume ')'
                scopes.pop_back();
                return result;
            }
            std::string token = readToken(s, i);
            while (s[i] == ' ') ++i;
            if (s[i] == ')') {
                int result;
                if (!token.empty() && (token[0] == '-' || std::isdigit(token[0]))) {
                    result = std::stoi(token);
                } else {
                    result = lookupVar(token, scopes);
                }
                ++i; // consume ')'
                scopes.pop_back();
                return result;
            } else {
                std::string var = token;
                int val = eval(s, i, scopes);
                scopes.back()[var] = val;
            }
        }
    }
}

int evaluate(std::string expression) {
    int idx = 0;
    std::vector<std::unordered_map<std::string, int>> scopes;
    return eval(expression, idx, scopes);
}

