long long deleteAndEarn(const std::vector<int>& nums) {
    std::unordered_map<int, int> frequencyMap;
    for (int num : nums) {
        ++frequencyMap[num];
    }

    int maxNum = 0;
    for (const auto& kv : frequencyMap) {
        if (kv.first > maxNum) {
            maxNum = kv.first;
        }
    }

    if (maxNum == 0) {
        return 0;
    }

    std::vector<long long> dp(maxNum + 1, 0);
    dp[1] = frequencyMap.count(1) ? static_cast<long long>(frequencyMap[1]) * 1 : 0;

    for (int i = 2; i <= maxNum; ++i) {
        long long include = dp[i - 2];
        auto it = frequencyMap.find(i);
        if (it != frequencyMap.end()) {
            include += static_cast<long long>(it->second) * i;
        }
        dp[i] = std::max(dp[i - 1], include);
    }

    return dp[maxNum];
}

#include <bits/stdc++.h>

int cherryPickup(const std::vector<std::vector<int>>& grid) {
    int n = static_cast<int>(grid.size());
    const int NEG_INF = -1e9;
    std::vector<std::vector<std::vector<int>>> memo(n,
        std::vector<std::vector<int>>(n, std::vector<int>(n, NEG_INF)));

    std::function<int(int,int,int)> dfs = [&](int r1, int c1, int r2) -> int {
        int c2 = r1 + c1 - r2;
        if (r1 < 0 || r1 >= n || c1 < 0 || c1 >= n ||
            r2 < 0 || r2 >= n || c2 < 0 || c2 >= n ||
            grid[r1][c1] == -1 || grid[r2][c2] == -1) {
            return NEG_INF;
        }
        if (r1 == n - 1 && c1 == n - 1) {
            return grid[r1][c1];
        }
        int &cached = memo[r1][c1][r2];
        if (cached != NEG_INF) {
            return cached;
        }
        int best = std::max({
            dfs(r1 + 1, c1, r2 + 1),
            dfs(r1, c1 + 1, r2),
            dfs(r1 + 1, c1, r2),
            dfs(r1, c1 + 1, r2 + 1)
        });
        if (best == NEG_INF) {
            cached = NEG_INF;
            return cached;
        }
        int cur = grid[r1][c1];
        if (r1 != r2 || c1 != c2) {
            cur += grid[r2][c2];
        }
        cached = cur + best;
        return cached;
    };

    int result = dfs(0, 0, 0);
    return result < 0 ? 0 : result;
}

