int networkDelayTime(const std::vector<std::vector<int>>& times, int n, int k) {
    std::vector<std::vector<std::pair<int, int>>> graph(n + 1);
    for (const auto& edge : times) {
        int u = edge[0];
        int v = edge[1];
        int w = edge[2];
        graph[u].push_back({v, w});
    }
    const long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<long long> distance(n + 1, INF);
    distance[k] = 0;
    std::vector<std::pair<int, long long>> pq;
    pq.push_back({k, 0});
    while (!pq.empty()) {
        int node = pq.front().first;
        long long dist = pq.front().second;
        pq.erase(pq.begin());
        if (dist > distance[node]) continue;
        for (const auto& neighborInfo : graph[node]) {
            int neighbor = neighborInfo.first;
            int weight = neighborInfo.second;
            long long newDist = dist + weight;
            if (newDist < distance[neighbor]) {
                distance[neighbor] = newDist;
                pq.push_back({neighbor, newDist});
                std::sort(pq.begin(), pq.end(),
                          [](const std::pair<int, long long>& a, const std::pair<int, long long>& b) {
                              return a.second < b.second;
                          });
            }
        }
    }
    long long maxDist = 0;
    for (int i = 1; i <= n; ++i) {
        if (distance[i] > maxDist) maxDist = distance[i];
    }
    return maxDist == INF ? -1 : static_cast<int>(maxDist);
}

