int minCostClimbingStairs(const std::vector<int>& cost) {
    int minCostToReachPreviousStep = cost[0];
    int minCostToReachCurrentStep = cost[1];
    for (size_t i = 2; i < cost.size(); ++i) {
        int temp = minCostToReachCurrentStep;
        minCostToReachCurrentStep = std::min(minCostToReachPreviousStep, minCostToReachCurrentStep) + cost[i];
        minCostToReachPreviousStep = temp;
    }
    return std::min(minCostToReachPreviousStep, minCostToReachCurrentStep);
}

