int openLock(const std::vector<std::string>& deadends, const std::string& target) {
    std::unordered_set<std::string> dead(deadends.begin(), deadends.end());
    if (dead.find("0000") != dead.end()) return -1;
    std::queue<std::pair<std::string, int>> q;
    q.emplace("0000", 0);
    std::unordered_set<std::string> visited;
    visited.insert("0000");
    while (!q.empty()) {
        auto state_turns = q.front();
        q.pop();
        const std::string& state = state_turns.first;
        int turns = state_turns.second;
        if (state == target) return turns;
        for (int i = 0; i < 4; ++i) {
            int digit = state[i] - '0';
            std::string incState = state;
            incState[i] = static_cast<char>((digit + 1) % 10 + '0');
            if (dead.find(incState) == dead.end() && visited.find(incState) == visited.end()) {
                q.emplace(incState, turns + 1);
                visited.insert(incState);
            }
            std::string decState = state;
            decState[i] = static_cast<char>((digit - 1 + 10) % 10 + '0');
            if (dead.find(decState) == dead.end() && visited.find(decState) == visited.end()) {
                q.emplace(decState, turns + 1);
                visited.insert(decState);
            }
        }
    }
    return -1;
}

