std::string crackSafe(int n, int k) {
    std::string result;
    std::unordered_set<std::string> visited;
    std::function<void(const std::string&)> dfs = [&](const std::string& node) {
        for (int i = 0; i < k; ++i) {
            std::string edge = node + static_cast<char>('0' + i);
            if (visited.find(edge) == visited.end()) {
                visited.insert(edge);
                dfs(edge.substr(1));
                result.push_back(static_cast<char>('0' + i));
            }
        }
    };
    dfs(std::string(n - 1, '0'));
    result += std::string(n - 1, '0');
    return result;
}

