int containVirus(std::vector<std::vector<int>>& isInfected) {
    const int m = static_cast<int>(isInfected.size());
    const int n = static_cast<int>(isInfected[0].size());
    const int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
    int totalWalls = 0;
    while (true) {
        std::vector<std::vector<bool>> visited(m, std::vector<bool>(n, false));
        struct RegionInfo {
            std::vector<std::pair<int,int>> cells;
            std::vector<std::pair<int,int>> frontier;
            int walls = 0;
        };
        std::vector<RegionInfo> regions;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (isInfected[i][j] == 1 && !visited[i][j]) {
                    RegionInfo info;
                    std::queue<std::pair<int,int>> q;
                    q.emplace(i, j);
                    visited[i][j] = true;
                    while (!q.empty()) {
                        std::pair<int,int> cur = q.front(); q.pop();
                        int x = cur.first;
                        int y = cur.second;
                        info.cells.emplace_back(x, y);
                        for (int d = 0; d < 4; ++d) {
                            int nx = x + dirs[d][0];
                            int ny = y + dirs[d][1];
                            if (nx < 0 || nx >= m || ny < 0 || ny >= n) continue;
                            if (isInfected[nx][ny] == 1 && !visited[nx][ny]) {
                                visited[nx][ny] = true;
                                q.emplace(nx, ny);
                            } else if (isInfected[nx][ny] == 0) {
                                ++info.walls;
                                info.frontier.emplace_back(nx, ny);
                            }
                        }
                    }
                    std::unordered_set<int> uniq;
                    std::vector<std::pair<int,int>> uniqFrontier;
                    uniqFrontier.reserve(info.frontier.size());
                    for (auto &p : info.frontier) {
                        int key = p.first * n + p.second;
                        if (uniq.insert(key).second) {
                            uniqFrontier.push_back(p);
                        }
                    }
                    info.frontier.swap(uniqFrontier);
                    regions.push_back(std::move(info));
                }
            }
        }
        if (regions.empty()) break;
        size_t maxIdx = SIZE_MAX;
        size_t maxFrontier = 0;
        for (size_t i = 0; i < regions.size(); ++i) {
            if (regions[i].frontier.size() > maxFrontier) {
                maxFrontier = regions[i].frontier.size();
                maxIdx = i;
            }
        }
        if (maxFrontier == 0) break;
        totalWalls += regions[maxIdx].walls;
        for (auto &p : regions[maxIdx].cells) {
            isInfected[p.first][p.second] = -1;
        }
        for (size_t i = 0; i < regions.size(); ++i) {
            if (i == maxIdx) continue;
            for (auto &p : regions[i].frontier) {
                isInfected[p.first][p.second] = 1;
            }
        }
    }
    return totalWalls;
}

