int calPoints(const std::vector<std::string>& operations) {
    std::vector<int> scores;
    for (size_t i = 0; i < operations.size(); ++i) {
        const std::string& op = operations[i];
        if (op != "C" && op != "D" && op != "+") {
            scores.push_back(std::stoi(op));
        } else if (op == "C") {
            if (!scores.empty()) {
                scores.pop_back();
            }
        } else if (op == "D") {
            scores.push_back(2 * scores.back());
        } else if (op == "+") {
            int sz = static_cast<int>(scores.size());
            scores.push_back(scores[sz - 1] + scores[sz - 2]);
        }
    }
    int sum = 0;
    for (int v : scores) {
        sum += v;
    }
    return sum;
}

