int findKthNumber(int m, int n, int k) {
    std::int64_t left = 1, right = static_cast<std::int64_t>(m) * n;
    while (left < right) {
        std::int64_t mid = (left + right) / 2;
        std::int64_t count = 0;
        int j = n;
        for (int i = 1; i <= m; ++i) {
            while (j >= 1 && static_cast<std::int64_t>(i) * j > mid) {
                --j;
            }
            count += j;
        }
        if (count < k) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return static_cast<int>(left);
}

