bool judgePoint24(const std::vector<double>& cards) {
    std::function<bool(std::vector<double>)> dfs = [&](std::vector<double> nums) -> bool {
        if (nums.size() == 1) return std::fabs(nums[0] - 24.0) < 1e-6;
        for (size_t i = 0; i < nums.size(); ++i) {
            for (size_t j = i + 1; j < nums.size(); ++j) {
                double a = nums[i];
                double b = nums[j];
                std::vector<double> rest;
                rest.reserve(nums.size() - 2);
                for (size_t k = 0; k < nums.size(); ++k) {
                    if (k != i && k != j) rest.push_back(nums[k]);
                }
                std::vector<double> next;
                next = rest; next.push_back(a + b);
                if (dfs(next)) return true;
                next = rest; next.push_back(a - b);
                if (dfs(next)) return true;
                next = rest; next.push_back(b - a);
                if (dfs(next)) return true;
                if (a * b != 0) {
                    next = rest; next.push_back(a * b);
                    if (dfs(next)) return true;
                }
                if (b != 0) {
                    next = rest; next.push_back(a / b);
                    if (dfs(next)) return true;
                }
                if (a != 0) {
                    next = rest; next.push_back(b / a);
                    if (dfs(next)) return true;
                }
            }
        }
        return false;
    };
    return dfs(std::vector<double>(cards.begin(), cards.end()));
}

