std::string nearestPalindromic(const std::string& n) {
    int L = n.size();
    unsigned long long original = std::stoull(n);
    std::vector<std::string> cand;
    // mirror original prefix
    auto makePal = [&](const std::string& pref, int len) -> std::string {
        if (len % 2 == 0) {
            std::string rev(pref.rbegin(), pref.rend());
            return pref + rev;
        } else {
            std::string left = pref.substr(0, pref.size() - 1);
            std::string rev(left.rbegin(), left.rend());
            return left + pref.back() + rev;
        }
    };
    std::string prefix = n.substr(0, (L + 1) / 2);
    cand.push_back(makePal(prefix, L));
    long long prefNum = std::stoll(prefix);
    for (int delta : {-1, 1}) {
        long long newPrefNum = prefNum + delta;
        if (newPrefNum < 0) continue;
        std::string newPref = std::to_string(newPrefNum);
        cand.push_back(makePal(newPref, L));
    }
    // edge cases
    std::string all9(L - 1, '9');
    if (!all9.empty()) cand.push_back(all9);
    std::string oneZeroOne = "1" + std::string(L - 1, '0') + "1";
    cand.push_back(oneZeroOne);
    if (L == 1) cand.push_back("0");
    std::string best;
    unsigned long long bestDiff = ULLONG_MAX;
    for (const std::string& s : cand) {
        if (s == n) continue;
        unsigned long long val = std::stoull(s);
        unsigned long long diff = (val > original) ? (val - original) : (original - val);
        if (diff < bestDiff || (diff == bestDiff && val < std::stoull(best))) {
            bestDiff = diff;
            best = s;
        }
    }
    return best;
}

