bool isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

int countPrimeSetBits(int left, int right) {
    int count = 0;
    for (int i = left; i <= right; ++i) {
        std::string bin;
        int temp = i;
        if (temp == 0) {
            bin = "0";
        } else {
            while (temp > 0) {
                bin.push_back((temp & 1) ? '1' : '0');
                temp >>= 1;
            }
            std::reverse(bin.begin(), bin.end());
        }
        int setBits = 0;
        for (char c : bin) {
            if (c == '1') ++setBits;
        }
        if (isPrime(setBits)) ++count;
    }
    return count;
}

