int orderOfLargestPlusSign(int n, const std::vector<std::vector<int>>& mines) {
    std::vector<std::vector<int>> grid(n, std::vector<int>(n, 1));
    for (const auto& p : mines) {
        int x = p[0];
        int y = p[1];
        if (x >= 0 && x < n && y >= 0 && y < n) {
            grid[x][y] = 0;
        }
    }
    int maxOrder = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 1) {
                int order = 1;
                while (i - order >= 0 && i + order < n && j - order >= 0 && j + order < n) {
                    if (grid[i - order][j] == 1 && grid[i + order][j] == 1 && grid[i][j - order] == 1 && grid[i][j + order] == 1) {
                        ++order;
                    } else {
                        break;
                    }
                }
                maxOrder = std::max(maxOrder, order);
            }
        }
    }
    return maxOrder;
}

