            charFrequency[c] = 1;
        }
    }

    std::vector<std::pair<char, int>> maxHeap;
    for (const auto& kv : charFrequency) {
        maxHeap.emplace_back(kv.first, kv.second);
    }
    std::sort(maxHeap.begin(), maxHeap.end(),
        [](const std::pair<char, int>& a, const std::pair<char, int>& b) {
            return a.second > b.second;
        });

    std::string result;
    while (!maxHeap.empty()) {
        if (!result.empty() && result.back() == maxHeap[0].first) {
            if (maxHeap.size() == 1) {
                return "";
            }
            std::swap(maxHeap[0], maxHeap[1]);
        }

        char ch = maxHeap[0].first;
        result.push_back(ch);
        maxHeap[0].second--;
        if (maxHeap[0].second == 0) {
            maxHeap.erase(maxHeap.begin());
        }
        if (!maxHeap.empty()) {
            std::sort(maxHeap.begin(), maxHeap.end(),
                [](const std::pair<char, int>& a, const std::pair<char, int>& b) {
                    return a.second > b.second;
                });
        }
    }

    return result;
}

#include <bits/stdc++.h>
