void generateNextRows(const std::string& row, std::size_t idx, const std::string& cur,
                      std::unordered_set<std::string>& result,
                      const std::unordered_map<std::string, std::vector<char>>& map) {
    if (idx == row.size() - 1) {
        result.insert(cur);
        return;
    }
    std::string key = row.substr(idx, 2);
    auto it = map.find(key);
    if (it == map.end()) {
        return;
    }
    const std::vector<char>& candidates = it->second;
    for (char c : candidates) {
        generateNextRows(row, idx + 1, cur + c, result, map);
    }
}

bool pyramidTransition(const std::string& bottom, const std::vector<std::string>& allowed) {
    std::unordered_map<std::string, std::vector<char>> map;
    for (const std::string& pattern : allowed) {
        std::string key = pattern.substr(0, 2);
        map[key].push_back(pattern[2]);
    }

    std::vector<std::string> currentRow;
    currentRow.push_back(bottom);

    while (!currentRow.empty() && currentRow[0].size() > 1) {
        std::vector<std::string> nextRow;
        for (const std::string& row : currentRow) {
            std::unordered_set<std::string> set;
            generateNextRows(row, 0, "", set, map);
            for (const std::string& nxt : set) {
                nextRow.push_back(nxt);
            }
        }
        currentRow = std::move(nextRow);
        if (currentRow.empty()) {
            return false;
        }
    }
    return true;
}

