int maxChunksToSorted(const std::vector<int>& arr) {
    if (arr.empty()) return 0;
    int n = static_cast<int>(arr.size());
    std::vector<int> suffixMin(n);
    suffixMin[n - 1] = arr[n - 1];
    for (int i = n - 2; i >= 0; --i) {
        suffixMin[i] = std::min(arr[i], suffixMin[i + 1]);
    }
    int chunks = 0;
    int curMax = arr[0];
    for (int i = 0; i < n; ++i) {
        curMax = std::max(curMax, arr[i]);
        if (i == n - 1 || curMax <= suffixMin[i + 1]) {
            ++chunks;
            if (i + 1 < n) curMax = arr[i + 1];
        }
    }
    return chunks;
}

