#include <unordered_map>
#include <map>

std::vector<std::string> basicCalculatorIV(const std::string& expression,
                                            const std::vector<std::string>& evalvars,
                                            const std::vector<int>& evalints) {
    using Poly = std::map<std::vector<std::string>, long long>;

    std::unordered_map<std::string, int> valMap;
    for (size_t i = 0; i < evalvars.size(); ++i) {
        valMap[evalvars[i]] = evalints[i];
    }

    size_t pos = 0;
    auto skipSpaces = [&]() {
        while (pos < expression.size() && expression[pos] == ' ') ++pos;
    };

    std::function<Poly()> parseExpression;
    std::function<Poly()> parseTerm;
    std::function<Poly()> parseFactor;

    auto addPoly = [&](Poly& a, const Poly& b, int sign = 1) {
        for (const auto& kv : b) {
            a[kv.first] += sign * kv.second;
            if (a[kv.first] == 0) a.erase(kv.first);
        }
    };

    auto mulPoly = [&](const Poly& a, const Poly& b) -> Poly {
        Poly res;
        for (const auto& kv1 : a) {
            for (const auto& kv2 : b) {
                std::vector<std::string> vars = kv1.first;
                vars.insert(vars.end(), kv2.first.begin(), kv2.first.end());
                std::sort(vars.begin(), vars.end());
                res[vars] += kv1.second * kv2.second;
                if (res[vars] == 0) res.erase(vars);
            }
        }
        return res;
    };

    parseFactor = [&]() -> Poly {
        skipSpaces();
        if (pos < expression.size() && expression[pos] == '(') {
            ++pos;
            Poly inside = parseExpression();
            skipSpaces();
            if (pos < expression.size() && expression[pos] == ')') ++pos;
            return inside;
        } else if (pos < expression.size() && std::isdigit(expression[pos])) {
            long long num = 0;
            while (pos < expression.size() && std::isdigit(expression[pos])) {
                num = num * 10 + (expression[pos] - '0');
                ++pos;
            }
            Poly p;
            p[{}] = num;
            return p;
        } else {
            std::string var;
            while (pos < expression.size() && std::isalpha(expression[pos])) {
                var.push_back(expression[pos]);
                ++pos;
            }
            Poly p;
            auto it = valMap.find(var);
            if (it != valMap.end()) {
                p[{}] = it->second;
            } else {
                p[{var}] = 1;
            }
            return p;
        }
    };

    parseTerm = [&]() -> Poly {
        Poly cur = parseFactor();
        while (true) {
            skipSpaces();
            if (pos < expression.size() && expression[pos] == '*') {
                ++pos;
                Poly nxt = parseFactor();
                cur = mulPoly(cur, nxt);
            } else break;
        }
        return cur;
    };

    parseExpression = [&]() -> Poly {
        Poly cur = parseTerm();
        while (true) {
            skipSpaces();
            if (pos < expression.size() && (expression[pos] == '+' || expression[pos] == '-')) {
                char op = expression[pos++];
                Poly nxt = parseTerm();
                addPoly(cur, nxt, op == '+' ? 1 : -1);
            } else break;
        }
        return cur;
    };

    Poly resultPoly = parseExpression();

    std::vector<std::pair<std::vector<std::string>, long long>> terms;
    for (auto& kv : resultPoly) {
        if (kv.second != 0) terms.push_back(kv);
    }

    std::sort(terms.begin(), terms.end(),
              [](const auto& a, const auto& b) {
                  if (a.first.size() != b.first.size())
                      return a.first.size() > b.first.size();
                  return a.first < b.first;
              });

    std::vector<std::string> answer;
    for (auto& kv : terms) {
        long long coeff = kv.second;
        const std::vector<std::string>& vars = kv.first;
        std::string term;
        if (vars.empty()) {
            term = std::to_string(coeff);
        } else {
            if (coeff == 1) {
                term = "1*";
            } else if (coeff == -1) {
                term = "-1*";
            } else {
                term = std::to_string(coeff) + "*";
            }
            for (size_t i = 0; i < vars.size(); ++i) {
                if (i) term.push_back('*');
                term += vars[i];
            }
        }
        answer.push_back(term);
    }
    return answer;
}

#include <bits/stdc++.h>

bool reachingPoints(int sx, int sy, int tx, int ty) {
    long long x = tx, y = ty;
    long long sX = sx, sY = sy;
    while (x >= sX && y >= sY) {
        if (x == sX && y == sY) return true;
        if (x > y) {
            if (y > sY) {
                x %= y;
                if (x == 0) x = y;
            } else {
                return (x - sX) % y == 0;
            }
        } else if (y > x) {
            if (x > sX) {
                y %= x;
                if (y == 0) y = x;
            } else {
                return (y - sY) % x == 0;
            }
        } else {
            break;
        }
    }
    return false;
}

