int swimInWater(const std::vector<std::vector<int>>& grid) {
    int n = static_cast<int>(grid.size());
    std::vector<std::array<int, 2>> directions = {std::array<int,2>{-1, 0}, std::array<int,2>{1, 0}, std::array<int,2>{0, -1}, std::array<int,2>{0, 1}};
    std::vector<std::array<int, 3>> pq;
    pq.push_back({grid[0][0], 0, 0});
    std::vector<std::vector<bool>> visited(n, std::vector<bool>(n, false));

    while (!pq.empty()) {
        auto cur = pq.front();
        pq.erase(pq.begin());
        int elevation = cur[0];
        int x = cur[1];
        int y = cur[2];
        if (x == n - 1 && y == n - 1) return elevation;
        if (visited[x][y]) continue;
        visited[x][y] = true;

        for (const auto& d : directions) {
            int nx = x + d[0];
            int ny = y + d[1];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny]) {
                pq.push_back({std::max(elevation, grid[nx][ny]), nx, ny});
                std::sort(pq.begin(), pq.end(), [](const std::array<int, 3>& a, const std::array<int, 3>& b) {
                    return a[0] < b[0];
                });
            }
        }
    }
    return -1;
}

