bool isIdealPermutation(const std::vector<int>& nums) {
    long long globalInversions = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        for (size_t j = i + 1; j < nums.size(); ++j) {
            if (nums[i] > nums[j]) ++globalInversions;
        }
    }
    long long localInversions = 0;
    for (size_t i = 0; i + 1 < nums.size(); ++i) {
        if (nums[i] > nums[i + 1]) ++localInversions;
    }
    return globalInversions == localInversions;
}

