#include <unordered_set>

int slidingPuzzle(const std::vector<std::vector<int>>& board) {
    auto encode = [](const std::vector<std::vector<int>>& b) {
        int s = 0;
        for (int i = 0; i < 2; ++i)
            for (int j = 0; j < 3; ++j)
                s = s * 6 + b[i][j];
        return s;
    };
    const int target = 11190;
    const std::vector<std::vector<int>> adj = {
        {1,3}, {0,2,4}, {1,5}, {0,4}, {1,3,5}, {2,4}
    };
    int start = encode(board);
    if (start == target) return 0;
    std::queue<std::pair<int,int>> q;
    q.emplace(start, 0);
    std::unordered_set<int> visited;
    visited.insert(start);
    while (!q.empty()) {
        int state = q.front().first;
        int moves = q.front().second;
        q.pop();
        int tmp = state;
        int digits[6];
        for (int i = 5; i >= 0; --i) {
            digits[i] = tmp % 6;
            tmp /= 6;
        }
        int zeroPos = 0;
        while (digits[zeroPos] != 0) ++zeroPos;
        for (int nb : adj[zeroPos]) {
            std::swap(digits[zeroPos], digits[nb]);
            int nextState = 0;
            for (int i = 0; i < 6; ++i) nextState = nextState * 6 + digits[i];
            if (visited.find(nextState) == visited.end()) {
                if (nextState == target) return moves + 1;
                visited.insert(nextState);
                q.emplace(nextState, moves + 1);
            }
            std::swap(digits[zeroPos], digits[nb]);
        }
    }
    return -1;
}

