struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

void inOrderTraversal(TreeNode* node, int& minDiff, int& prevVal, bool& hasPrev) {
    if (!node) return;
    inOrderTraversal(node->left, minDiff, prevVal, hasPrev);
    if (hasPrev) {
        int diff = node->val - prevVal;
        if (diff < minDiff) minDiff = diff;
    }
    prevVal = node->val;
    hasPrev = true;
    inOrderTraversal(node->right, minDiff, prevVal, hasPrev);
}

int minDiffInBST(TreeNode* root) {
    int minDiff = INT_MAX;
    int prevVal = 0;
    bool hasPrev = false;
    inOrderTraversal(root, minDiff, prevVal, hasPrev);
    return minDiff;
}

