#include <bits/stdc++.h>

int movesToMakeZigzag(const std::vector<std::vector<int>>& board) {
    int n = static_cast<int>(board.size());
    if (n == 0) return -1;
    if (n == 1) return 0;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int expected = board[0][0] ^ board[i][0] ^ board[0][j];
            if (board[i][j] != expected) return -1;
        }
    }

    int rowSum = 0, colSum = 0;
    for (int j = 0; j < n; ++j) rowSum += board[0][j];
    for (int i = 0; i < n; ++i) colSum += board[i][0];

    auto validCount = [&](int sum) {
        if (n % 2 == 0) return sum == n / 2;
        return sum == n / 2 || sum == n / 2 + 1;
    };
    if (!validCount(rowSum) || !validCount(colSum)) return -1;

    std::vector<int> firstCol(n), firstRow(n);
    for (int i = 0; i < n; ++i) firstCol[i] = board[i][0];
    for (int j = 0; j < n; ++j) firstRow[j] = board[0][j];

    auto computeSwaps = [&](const std::vector<int>& line) -> int {
        int mismatches = 0;
        for (int i = 0; i < n; ++i) {
            if (line[i] != (i % 2)) ++mismatches;
        }
        if (n % 2 == 0) {
            return std::min(mismatches, n - mismatches);
        } else {
            if (mismatches % 2 == 1) mismatches = n - mismatches;
            return mismatches;
        }
    };

    int rowSwaps = computeSwaps(firstCol);
    int colSwaps = computeSwaps(firstRow);

    return (rowSwaps + colSwaps) / 2;
}

