std::vector<std::string> letterCasePermutation(const std::string& s) {
    std::vector<std::string> result;
    std::function<void(std::size_t, std::string&)> backtrack = [&](std::size_t index, std::string& current) {
        if (index == s.size()) {
            result.push_back(current);
            return;
        }
        if (std::isdigit(static_cast<unsigned char>(s[index]))) {
            current.push_back(s[index]);
            backtrack(index + 1, current);
            current.pop_back();
        } else {
            current.push_back(static_cast<char>(std::tolower(static_cast<unsigned char>(s[index]))));
            backtrack(index + 1, current);
            current.pop_back();
            current.push_back(static_cast<char>(std::toupper(static_cast<unsigned char>(s[index]))));
            backtrack(index + 1, current);
            current.pop_back();
        }
    };
    std::string cur;
    backtrack(0, cur);
    return result;
}

