std::vector<int> kthSmallestPrimeFraction(const std::vector<int>& arr, int k) {
    struct Node {
        int i;
        int j;
        double val;
    };
    struct Comp {
        bool operator()(const Node& a, const Node& b) const {
            return a.val > b.val;
        }
    };
    std::priority_queue<Node, std::vector<Node>, Comp> pq;
    int n = static_cast<int>(arr.size());
    for (int i = 0; i < n - 1; ++i) {
        pq.push({i, n - 1, static_cast<double>(arr[i]) / arr[n - 1]});
    }
    Node cur;
    for (int count = 0; count < k; ++count) {
        cur = pq.top();
        pq.pop();
        if (cur.j - 1 > cur.i) {
            int newJ = cur.j - 1;
            pq.push({cur.i, newJ, static_cast<double>(arr[cur.i]) / arr[newJ]});
        }
    }
    return {arr[cur.i], arr[cur.j]};
}

