int numTilings(int n) {
    const int64_t MOD = 1000000007LL;
    if (n == 0) {
        return 1;
    }
    std::vector<int64_t> dp(n + 3, 0);
    dp[0] = 1;
    dp[1] = 1;
    if (n >= 2) {
        dp[2] = 2;
    }
    for (int i = 3; i <= n; ++i) {
        dp[i] = (2 * dp[i - 1] + dp[i - 3]) % MOD;
    }
    return static_cast<int>(dp[n]);
}

