int preimageSizeFZF(long long k) {
    auto findTrailingZeroes = [&](long long x) -> long long {
        long long count = 0;
        long long i = 5;
        while (x / i >= 1) {
            count += x / i;
            i *= 5;
        }
        return count;
    };
    long long left = 0;
    long long right = 5 * k;
    while (left < right) {
        long long mid = (left + right) / 2;
        long long tz = findTrailingZeroes(mid);
        if (tz < k) {
            left = mid + 1;
        } else if (tz > k) {
            right = mid;
        } else {
            right = mid;
        }
    }
    if (findTrailingZeroes(left) == k) {
        if (findTrailingZeroes(left + 4) == k) {
            return 5;
        } else {
            return 1;
        }
    } else {
        return 0;
    }
}

