int rotatedDigits(int n) {
    int count = 0;
    for (int i = 1; i <= n; ++i) {
        bool isGood = false;
        bool isValid = true;
        int rotated = 0;
        int temp = i;
        int base = 1;
        while (temp > 0) {
            int digit = temp % 10;
            if (digit == 3 || digit == 4 || digit == 7) {
                isValid = false;
                break;
            }
            int rotatedDigit;
            if (digit == 0) rotatedDigit = 0;
            else if (digit == 1) rotatedDigit = 1;
            else if (digit == 6) rotatedDigit = 9;
            else if (digit == 8) rotatedDigit = 8;
            else if (digit == 9) rotatedDigit = 6;
            else rotatedDigit = 9;
            if (rotatedDigit != digit) {
                isGood = true;
            }
            rotated += rotatedDigit * base;
            base *= 10;
            temp /= 10;
        }
        if (isValid && isGood) {
            ++count;
        }
    }
    return count;
}

#include <bits/stdc++.h>
