#include <tuple>
#include <limits>
#include <queue>

int findCheapestPrice(int n, const std::vector<std::vector<int>>& flights, int src, int dst, int k) {
    std::vector<std::vector<std::pair<int, int>>> graph(n);
    for (const auto& f : flights) {
        graph[f[0]].push_back({f[1], f[2]});
    }

    const long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<std::vector<long long>> best(n, std::vector<long long>(k + 2, INF));
    using State = std::tuple<long long, int, int>;
    std::priority_queue<State, std::vector<State>, std::greater<State>> pq;

    best[src][0] = 0;
    pq.emplace(0LL, src, 0);

    while (!pq.empty()) {
        State cur = pq.top();
        pq.pop();
        long long cost = std::get<0>(cur);
        int city = std::get<1>(cur);
        int edges = std::get<2>(cur);

        if (city == dst) {
            return static_cast<int>(cost);
        }
        if (edges == k + 1) {
            continue;
        }

        for (const auto& edge : graph[city]) {
            int neighbor = edge.first;
            int price = edge.second;
            long long newCost = cost + price;
            int newEdges = edges + 1;
            if (newEdges <= k + 1 && newCost < best[neighbor][newEdges]) {
                best[neighbor][newEdges] = newCost;
                pq.emplace(newCost, neighbor, newEdges);
            }
        }
    }

    return -1;
}

