int bestRotation(const std::vector<int>& nums) {
    int maxScore = 0;
    int rotationIndex = 0;
    std::size_t n = nums.size();
    for (std::size_t k = 0; k < n; ++k) {
        int score = 0;
        for (std::size_t i = 0; i < n; ++i) {
            if (nums[(i + k) % n] <= static_cast<int>(i)) {
                ++score;
            }
        }
        if (score > maxScore) {
            maxScore = score;
            rotationIndex = static_cast<int>(k);
        } else if (score == maxScore) {
            rotationIndex = std::min(rotationIndex, static_cast<int>(k));
        }
    }
    return rotationIndex;
}

