double champagneTower(int poured, int query_row, int query_glass) {
    std::vector<std::vector<double>> champagne(query_row + 1, std::vector<double>(query_row + 1, 0.0));
    champagne[0][0] = poured;
    for (int row = 0; row < query_row; ++row) {
        for (int glass = 0; glass <= row; ++glass) {
            if (champagne[row][glass] > 1.0) {
                double excess = (champagne[row][glass] - 1.0) / 2.0;
                champagne[row + 1][glass] += excess;
                champagne[row + 1][glass + 1] += excess;
                champagne[row][glass] = 1.0;
            }
        }
    }
    return std::min(1.0, champagne[query_row][query_glass]);
}

