int minSwap(std::vector<int>& nums1, std::vector<int>& nums2) {
    int n = static_cast<int>(nums1.size());
    int keep = 0;
    int swap = 1;
    for (int i = 1; i < n; ++i) {
        int keepNew = INT_MAX;
        int swapNew = INT_MAX;
        if (nums1[i] > nums1[i - 1] && nums2[i] > nums2[i - 1]) {
            keepNew = std::min(keepNew, keep);
            swapNew = std::min(swapNew, swap + 1);
        }
        if (nums1[i] > nums2[i - 1] && nums2[i] > nums1[i - 1]) {
            keepNew = std::min(keepNew, swap);
            swapNew = std::min(swapNew, keep + 1);
        }
        keep = keepNew;
        swap = swapNew;
    }
    return std::min(keep, swap);
}

