#include <bits/stdc++.h>

std::vector<int> hitBricks(std::vector<std::vector<int>>& grid, const std::vector<std::vector<int>>& hits) {
    int rows = static_cast<int>(grid.size());
    int cols = static_cast<int>(grid[0].size());
    int total = rows * cols + 1;
    int top = rows * cols;

    std::vector<int> parent(total);
    std::vector<int> sz(total, 1);
    for (int i = 0; i < total; ++i) parent[i] = i;

    std::function<int(int)> find = [&](int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    auto unite = [&](int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return;
        if (sz[ra] < sz[rb]) std::swap(ra, rb);
        parent[rb] = ra;
        sz[ra] += sz[rb];
    };

    auto idx = [&](int r, int c) { return r * cols + c; };

    std::vector<std::vector<int>> work = grid;
    for (const auto& h : hits) {
        int r = h[0], c = h[1];
        if (work[r][c] == 1) work[r][c] = 0;
    }

    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            if (work[r][c] == 0) continue;
            int cur = idx(r, c);
            if (r == 0) unite(cur, top);
            if (r > 0 && work[r - 1][c] == 1) unite(cur, idx(r - 1, c));
            if (c > 0 && work[r][c - 1] == 1) unite(cur, idx(r, c - 1));
        }
    }

    std::vector<int> result(hits.size(), 0);
    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};

    for (int i = static_cast<int>(hits.size()) - 1; i >= 0; --i) {
        int r = hits[i][0];
        int c = hits[i][1];
        if (grid[r][c] == 0) {
            result[i] = 0;
            continue;
        }
        int before = sz[find(top)];
        work[r][c] = 1;
        int cur = idx(r, c);
        if (r == 0) unite(cur, top);
        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
            if (work[nr][nc] == 1) unite(cur, idx(nr, nc));
        }
        int after = sz[find(top)];
        int fallen = after - before - 1;
        result[i] = fallen > 0 ? fallen : 0;
    }
    return result;
}

