double soupServings(int n) {
    int N = (n + 24) / 25; // ceil division by 25
    if (N >= 179) return 1.0;
    std::vector<std::vector<double>> memo(N + 1, std::vector<double>(N + 1, 0.0));
    std::function<double(int, int)> dfs = [&](int a, int b) -> double {
        if (a <= 0 && b <= 0) return 0.5;
        if (a <= 0) return 1.0;
        if (b <= 0) return 0.0;
        if (memo[a][b] != 0.0) return memo[a][b];
        memo[a][b] = 0.25 * (dfs(a - 4, b) + dfs(a - 3, b - 1) + dfs(a - 2, b - 2) + dfs(a - 1, b - 3));
        return memo[a][b];
    };
    return dfs(N, N);
}

