std::vector<std::string> subdomainVisits(const std::vector<std::string>& cpdomains) {
    std::unordered_map<std::string, long long> countMap;
    std::vector<std::string> result;

    for (const std::string& domain : cpdomains) {
        size_t spacePos = domain.find(' ');
        std::string countStr = domain.substr(0, spacePos);
        std::string fullDomain = domain.substr(spacePos + 1);
        int count = std::stoi(countStr);

        std::vector<std::string> subdomains;
        size_t start = 0;
        while (true) {
            size_t dotPos = fullDomain.find('.', start);
            if (dotPos == std::string::npos) {
                subdomains.push_back(fullDomain.substr(start));
                break;
            } else {
                subdomains.push_back(fullDomain.substr(start, dotPos - start));
                start = dotPos + 1;
            }
        }

        for (size_t i = 0; i < subdomains.size(); ++i) {
            std::string subdomain;
            for (size_t j = i; j < subdomains.size(); ++j) {
                if (j > i) subdomain.push_back('.');
                subdomain += subdomains[j];
            }
            countMap[subdomain] += count;
        }
    }

    for (const auto& kv : countMap) {
        result.push_back(std::to_string(kv.second) + " " + kv.first);
    }

    return result;
}

