int expressiveWords(const std::string& s, const std::vector<std::string>& words) {
    auto isStretchy = [&](const std::string& word) -> bool {
        std::size_t i = 0, j = 0;
        while (i < s.size() && j < word.size()) {
            if (s[i] != word[j]) return false;
            char c = s[i];
            std::size_t cntS = 0;
            while (i < s.size() && s[i] == c) {
                ++cntS;
                ++i;
            }
            std::size_t cntW = 0;
            while (j < word.size() && word[j] == c) {
                ++cntW;
                ++j;
            }
            if (cntW > cntS) return false;
            if (cntS < 3 && cntS != cntW) return false;
        }
        return i == s.size() && j == word.size();
    };

    int count = 0;
    for (const auto& word : words) {
        if (isStretchy(word)) ++count;
    }
    return count;
}

