std::string mostCommonWord(const std::string& paragraph, const std::vector<std::string>& banned) {
    std::string processed;
    processed.reserve(paragraph.size());
    for (char ch : paragraph) {
        unsigned char uc = static_cast<unsigned char>(ch);
        char lower = static_cast<char>(std::tolower(uc));
        if (std::isalnum(lower) || lower == '_' || std::isspace(lower)) {
            processed.push_back(lower);
        } else {
            processed.push_back(' ');
        }
    }
    std::unordered_map<std::string, int> wordCount;
    std::istringstream iss(processed);
    std::string word;
    while (iss >> word) {
        if (!word.empty()) {
            ++wordCount[word];
        }
    }
    std::unordered_set<std::string> bannedSet;
    for (const auto& w : banned) {
        std::string low;
        low.reserve(w.size());
        for (char ch : w) {
            unsigned char uc = static_cast<unsigned char>(ch);
            low.push_back(static_cast<char>(std::tolower(uc)));
        }
        bannedSet.insert(low);
    }
    int maxCount = 0;
    std::string mostCommon;
    for (const auto& kv : wordCount) {
        const std::string& w = kv.first;
        int cnt = kv.second;
        if (bannedSet.find(w) == bannedSet.end() && cnt > maxCount) {
            maxCount = cnt;
            mostCommon = w;
        }
    }
    return mostCommon;
}

