int numBusesToDestination(const std::vector<std::vector<int>>& routes, int source, int target) {
    if (source == target) return 0;
    std::unordered_map<int, std::vector<int>> stopToBuses;
    for (int i = 0; i < static_cast<int>(routes.size()); ++i) {
        for (int stop : routes[i]) {
            stopToBuses[stop].push_back(i);
        }
    }
    std::queue<std::pair<int, int>> q;
    q.emplace(source, 0);
    std::unordered_set<int> visitedStops;
    visitedStops.insert(source);
    std::vector<char> visitedBuses(routes.size(), 0);
    while (!q.empty()) {
        auto frontPair = q.front();
        q.pop();
        int stop = frontPair.first;
        int busCount = frontPair.second;
        if (stop == target) return busCount;
        auto it = stopToBuses.find(stop);
        if (it == stopToBuses.end()) continue;
        for (int busIdx : it->second) {
            if (visitedBuses[busIdx]) continue;
            visitedBuses[busIdx] = 1;
            for (int nextStop : routes[busIdx]) {
                if (visitedStops.find(nextStop) != visitedStops.end()) continue;
                visitedStops.insert(nextStop);
                q.emplace(nextStop, busCount + 1);
            }
        }
    }
    return -1;
}

