std::vector<std::string> ambiguousCoordinates(const std::string& s) {
    std::string str = s.substr(1, s.size() - 2);
    std::vector<std::string> result;
    auto getVariants = [&](const std::string& part) {
        std::vector<std::string> variants;
        int n = static_cast<int>(part.size());
        if (n == 0) return variants;
        if (n == 1) {
            variants.push_back(part);
            return variants;
        }
        if (part[0] == '0') {
            if (part.back() != '0') {
                variants.push_back("0." + part.substr(1));
            }
            return variants;
        }
        variants.push_back(part);
        for (int i = 1; i < n; ++i) {
            if (part.substr(i).back() != '0') {
                variants.push_back(part.substr(0, i) + "." + part.substr(i));
            }
        }
        return variants;
    };
    int n = static_cast<int>(str.size());
    for (int i = 1; i < n; ++i) {
        std::string left = str.substr(0, i);
        std::string right = str.substr(i);
        std::vector<std::string> leftVariants = getVariants(left);
        std::vector<std::string> rightVariants = getVariants(right);
        for (const std::string& l : leftVariants) {
            for (const std::string& r : rightVariants) {
                result.push_back("(" + l + ", " + r + ")");
            }
        }
    }
    std::sort(result.begin(), result.end());
    return result;
}

