double largestSumOfAverages(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    std::vector<double> prefixSum(n + 1, 0.0);
    for (int i = 0; i < n; ++i) {
        prefixSum[i + 1] = prefixSum[i] + nums[i];
    }

    double negInf = -std::numeric_limits<double>::infinity();
    std::vector<std::vector<double>> dp(n, std::vector<double>(k + 1, negInf));

    for (int i = 0; i < n; ++i) {
        dp[i][1] = prefixSum[i + 1] / (i + 1);
    }

    for (int j = 2; j <= k; ++j) {
        for (int i = j - 1; i < n; ++i) {
            for (int x = j - 2; x < i; ++x) {
                double avg = (prefixSum[i + 1] - prefixSum[x + 1]) / (i - x);
                dp[i][j] = std::max(dp[i][j], dp[x][j - 1] + avg);
            }
        }
    }

    return dp[n - 1][k];
}

