int racecar(int target) {
    std::deque<std::array<int, 3>> queue;
    queue.push_back({0, 1, 0});
    std::unordered_set<std::string> visited;
    while (!queue.empty()) {
        std::array<int, 3> cur = queue.front();
        queue.pop_front();
        int position = cur[0];
        int speed = cur[1];
        int steps = cur[2];
        if (position == target) return steps;
        std::string key = std::to_string(position) + "," + std::to_string(speed);
        if (visited.find(key) != visited.end()) continue;
        visited.insert(key);
        queue.push_back({position + speed, speed * 2, steps + 1});
        if ((speed > 0 && position + speed > target) || (speed < 0 && position + speed < target)) {
            queue.push_back({position, -1, steps + 1});
        }
    }
    return -1;
}

