int flipgame(const std::vector<int>& fronts, const std::vector<int>& backs) {
    std::unordered_set<int> same;
    for (size_t i = 0; i < fronts.size(); ++i) {
        if (fronts[i] == backs[i]) {
            same.insert(fronts[i]);
        }
    }
    int res = INT_MAX;
    for (size_t i = 0; i < fronts.size(); ++i) {
        if (same.find(fronts[i]) == same.end() && fronts[i] < res) {
            res = fronts[i];
        }
        if (same.find(backs[i]) == same.end() && backs[i] < res) {
            res = backs[i];
        }
    }
    return res == INT_MAX ? 0 : res;
}

