    Node* trie = new Node();
    for (const std::string& word : words) {
        Node* node = trie;
        for (int i = static_cast<int>(word.size()) - 1; i >= 0; --i) {
            char c = word[i];
            if (node->children.find(c) == node->children.end()) {
                node->children[c] = new Node();
            }
            node = node->children[c];
        }
    }
    int result = dfs(trie, 0);
    return result;
}

