std::string toGoatLatin(const std::string& sentence) {
    std::vector<std::string> words;
    size_t start = 0;
    while (true) {
        size_t pos = sentence.find(' ', start);
        if (pos == std::string::npos) {
            words.push_back(sentence.substr(start));
            break;
        } else {
            words.push_back(sentence.substr(start, pos - start));
            start = pos + 1;
        }
    }
    std::vector<std::string> result;
    const std::string vowels = "aeiouAEIOU";
    for (size_t i = 0; i < words.size(); ++i) {
        const std::string& w = words[i];
        std::string repeated(i + 1, 'a');
        if (!w.empty() && vowels.find(w[0]) != std::string::npos) {
            result.push_back(w + "ma" + repeated);
        } else {
            if (!w.empty()) {
                result.push_back(w.substr(1) + w[0] + "ma" + repeated);
            } else {
                result.push_back("ma" + repeated);
            }
        }
    }
    std::string output;
    for (size_t i = 0; i < result.size(); ++i) {
        if (i) output.push_back(' ');
        output += result[i];
    }
    return output;
}

