std::vector<int> shortestToChar(const std::string& s, char c) {
    std::vector<int> res(s.size(), INT_MAX);
    int prev = INT_MIN;
    for (size_t i = 0; i < s.size(); ++i) {
        if (s[i] == c) {
            prev = static_cast<int>(i);
            res[i] = 0;
        } else if (prev != INT_MIN) {
            res[i] = std::min(res[i], static_cast<int>(i) - prev);
        }
    }
    int next = INT_MAX;
    for (int i = static_cast<int>(s.size()) - 1; i >= 0; --i) {
        if (s[i] == c) {
            next = i;
        } else if (next != INT_MAX) {
            res[i] = std::min(res[i], next - i);
        }
    }
    return res;
}

