long long maxProfitAssignment(const std::vector<int>& difficulty, const std::vector<int>& profit, const std::vector<int>& worker) {
    std::size_t n = difficulty.size();
    if (n == 0) return 0;
    std::vector<std::pair<int, int>> jobs;
    jobs.reserve(n);
    for (std::size_t i = 0; i < n; ++i) {
        jobs.emplace_back(difficulty[i], profit[i]);
    }
    std::sort(jobs.begin(), jobs.end(), [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
        return a.first < b.first;
    });
    std::vector<int> maxProfit(jobs.size());
    maxProfit[0] = jobs[0].second;
    for (std::size_t i = 1; i < jobs.size(); ++i) {
        maxProfit[i] = std::max(maxProfit[i - 1], jobs[i].second);
    }
    long long totalProfit = 0;
    for (int w : worker) {
        int left = 0;
        int right = static_cast<int>(jobs.size()) - 1;
        while (left < right) {
            int mid = (left + right + 1) / 2;
            if (jobs[mid].first <= w) {
                left = mid;
            } else {
                right = mid - 1;
            }
        }
        if (jobs[left].first <= w) {
            totalProfit += maxProfit[left];
        }
    }
    return totalProfit;
}

