long long countUniqueChars(const std::string& s) {
    const std::size_t n = s.size();
    std::vector<long long> last(256, -1), prev(256, -1);
    long long result = 0;
    for (std::size_t i = 0; i < n; ++i) {
        unsigned char c = static_cast<unsigned char>(s[i]);
        result += (static_cast<long long>(i) - last[c]) * (last[c] - prev[c]);
        prev[c] = last[c];
        last[c] = static_cast<long long>(i);
    }
    for (std::size_t c = 0; c < 256; ++c) {
        result += (static_cast<long long>(n) - last[c]) * (last[c] - prev[c]);
    }
    return result;
}

