int largestIsland(std::vector<std::vector<int>>& grid) {
    int n = grid.size();
    const std::vector<std::pair<int,int>> directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    int islandIndex = 2;
    std::unordered_map<int,int> islandSizes;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 1) {
                islandSizes[islandIndex] = dfs(grid, i, j, islandIndex, directions);
                ++islandIndex;
            }
        }
    }

    int maxSize = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 0) {
                std::unordered_set<int> seen;
                int size = 1;
                for (const auto& d : directions) {
                    int x = i + d.first;
                    int y = j + d.second;
                    if (x >= 0 && x < n && y >= 0 && y < n && grid[x][y] > 1 && seen.find(grid[x][y]) == seen.end()) {
                        size += islandSizes[grid[x][y]];
                        seen.insert(grid[x][y]);
                    }
                }
                maxSize = std::max(maxSize, size);
            }
        }
    }

    if (maxSize == 0) {
        int overallMax = 0;
        for (const auto& kv : islandSizes) {
            overallMax = std::max(overallMax, kv.second);
        }
        return overallMax;
    }

    return maxSize;
}

