std::string maskPII(const std::string& s) {
    if (s.find('@') != std::string::npos) {
        size_t atPos = s.find('@');
        std::string local = s.substr(0, atPos);
        std::string domain = s.substr(atPos + 1);
        std::transform(local.begin(), local.end(), local.begin(),
                       [](unsigned char c) { return std::tolower(c); });
        std::transform(domain.begin(), domain.end(), domain.begin(),
                       [](unsigned char c) { return std::tolower(c); });
        std::string maskedLocal = std::string(1, local[0]) + "*****" + std::string(1, local[local.size() - 1]);
        return maskedLocal + "@" + domain;
    } else {
        std::string digits;
        digits.reserve(s.size());
        for (char ch : s) {
            if (std::isdigit(static_cast<unsigned char>(ch))) {
                digits.push_back(ch);
            }
        }
        std::string countryCode;
        if (digits.size() == 13) {
            countryCode = "+***-";
            digits = digits.substr(3);
        } else if (digits.size() == 12) {
            countryCode = "+**-";
            digits = digits.substr(2);
        } else if (digits.size() == 11) {
            countryCode = "+*-";
            digits = digits.substr(1);
        }
        std::string maskedDigits = countryCode + "***-***-" + digits.substr(digits.size() - 4);
        return maskedDigits;
    }
}

