std::string pushDominoes(const std::string& dominoes) {
    std::string result(dominoes.size(), '.');
    std::vector<int> force(dominoes.size(), 0);
    int f = 0;
    for (size_t i = 0; i < dominoes.size(); ++i) {
        if (dominoes[i] == 'R') f = static_cast<int>(dominoes.size());
        else if (dominoes[i] == 'L') f = 0;
        else f = std::max(f - 1, 0);
        force[i] += f;
    }
    f = 0;
    for (int i = static_cast<int>(dominoes.size()) - 1; i >= 0; --i) {
        if (dominoes[i] == 'L') f = static_cast<int>(dominoes.size());
        else if (dominoes[i] == 'R') f = 0;
        else f = std::max(f - 1, 0);
        force[i] -= f;
    }
    for (size_t i = 0; i < dominoes.size(); ++i) {
        if (force[i] > 0) result[i] = 'R';
        else if (force[i] < 0) result[i] = 'L';
    }
    return result;
}

class Solution {
public:
    double new21Game(int n, int k, int maxPts) {
        if (k == 0 || n >= k + maxPts - 1) return 1.0;
        vector<double> f(k + maxPts + 1, 0.0);
        for (int y = k; y <= k + maxPts; y++) f[y] = (y <= n) ? 1.0 : 0.0;
        double winSum = 0.0;
        for (int y = k; y < k + maxPts; y++) winSum += f[y];
        vector<double> dpx(k, 0.0);
        for (int x = k - 1; x >= 0; x--) {
            dpx[x] = winSum / maxPts;
            winSum += dpx[x] - f[x + maxPts];
            f[x] = dpx[x];
        }
        return dpx[0];
    }
};

