std::vector<int> sumOfDistancesInTree(int n, const std::vector<std::vector<int>>& edges) {
    std::vector<std::vector<int>> graph(n);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        graph[u].push_back(v);
        graph[v].push_back(u);
    }

    std::vector<int> count(n, 1);
    std::vector<int> answer(n, 0);

    std::function<void(int, int)> dfs = [&](int node, int parent) {
        for (int child : graph[node]) {
            if (child == parent) continue;
            dfs(child, node);
            count[node] += count[child];
            answer[0] += answer[child] + count[child];
        }
    };

    std::function<void(int, int)> dfs2 = [&](int node, int parent) {
        for (int child : graph[node]) {
            if (child == parent) continue;
            answer[child] = answer[node] + n - 2 * count[child];
            dfs2(child, node);
        }
    };

    dfs(0, -1);
    dfs2(0, -1);
    return answer;
}

