int numSimilarGroups(const std::vector<std::string>& strs) {
    std::vector<int> parent(strs.size());
    for (size_t i = 0; i < parent.size(); ++i) parent[i] = static_cast<int>(i);
    auto find = [&](int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    auto unite = [&](int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) parent[rootX] = rootY;
    };
    auto isSimilar = [&](const std::string& s1, const std::string& s2) {
        int count = 0;
        for (size_t i = 0; i < s1.size(); ++i) {
            if (s1[i] != s2[i]) ++count;
            if (count > 2) return false;
        }
        return count == 0 || count == 2;
    };
    for (size_t i = 0; i < strs.size(); ++i) {
        for (size_t j = i + 1; j < strs.size(); ++j) {
            if (isSimilar(strs[i], strs[j])) unite(static_cast<int>(i), static_cast<int>(j));
        }
    }
    int count = 0;
    for (size_t i = 0; i < parent.size(); ++i) {
        if (parent[i] == static_cast<int>(i)) ++count;
    }
    return count;
}

