bool isFibonacci(const std::vector<std::string>& arr) {
    for (size_t i = 2; i < arr.size(); ++i) {
        long long a = std::stoll(arr[i - 2]);
        long long b = std::stoll(arr[i - 1]);
        long long c = std::stoll(arr[i]);
        if (a + b != c) {
            return false;
        }
    }
    return true;
}

std::vector<std::string> backtrack(int start, const std::string& num, const std::vector<std::string>& path) {
    if (start == (int)num.size() && path.size() >= 3 && isFibonacci(path)) {
        return path;
    }
    for (int i = start; i < (int)num.size(); ++i) {
        if (i > start && num[start] == '0') {
            break;
        }
        std::string curr = num.substr(start, i - start + 1);
        if (curr.size() > 10) {
            break;
        }
        long long val = 0;
        for (char c : curr) {
            val = val * 10 + (c - '0');
            if (val > INT_MAX) break;
        }
        if (val > INT_MAX) {
            break;
        }
        std::vector<std::string> newPath = path;
        newPath.push_back(curr);
        std::vector<std::string> result = backtrack(i + 1, num, newPath);
        if (!result.empty()) {
            return result;
        }
    }
    return {};
}

std::vector<long long> splitIntoFibonacci(const std::string& num) {
    std::vector<std::string> result = backtrack(0, num, {});
    if (!result.empty()) {
        std::vector<long long> out;
        out.reserve(result.size());
        for (const auto& s : result) {
            out.push_back(std::stoll(s));
        }
        return out;
    }
    return {};
}

