int longestMountain(const std::vector<int>& arr) {
    int maxLength = 0;
    for (size_t i = 1; i + 1 < arr.size(); ++i) {
        if (arr[i - 1] < arr[i] && arr[i] > arr[i + 1]) {
            int left = static_cast<int>(i) - 1;
            int right = static_cast<int>(i) + 1;
            while (left >= 0 && arr[left] < arr[left + 1]) {
                --left;
            }
            while (right < static_cast<int>(arr.size()) && arr[right] < arr[right - 1]) {
                ++right;
