bool backspaceCompare(const std::string& s, const std::string& t) {
    int i = static_cast<int>(s.size()) - 1;
    int j = static_cast<int>(t.size()) - 1;
    int backS = 0, backT = 0;
    while (i >= 0 || j >= 0) {
        while (i >= 0) {
            if (s[i] == '#') {
                ++backS;
                --i;
            } else if (backS > 0) {
                --backS;
                --i;
            } else {
                break;
            }
        }
        while (j >= 0) {
            if (t[j] == '#') {
                ++backT;
                --j;
            } else if (backT > 0) {
                --backT;
                --j;
            } else {
                break;
            }
        }
        if (i < 0 && j < 0) {
            return true;
        }
        if (i < 0 || j < 0) {
            return false;
        }
        if (s[i] != t[j]) {
            return false;
        }
        --i;
        --j;
    }
    return true;
}

