int rectangleArea(const std::vector<std::vector<int>>& rectangles) {
    const long long MOD = 1000000007LL;
    std::vector<int> xs;
    xs.reserve(rectangles.size() * 2);
    for (const auto& r : rectangles) {
        xs.push_back(r[0]);
        xs.push_back(r[2]);
    }
    std::sort(xs.begin(), xs.end());
    xs.erase(std::unique(xs.begin(), xs.end()), xs.end());

    long long total = 0;
    for (size_t i = 0; i + 1 < xs.size(); ++i) {
        int x1 = xs[i];
        int x2 = xs[i + 1];
        long long width = static_cast<long long>(x2) - x1;
        std::vector<std::pair<int, int>> ys;
        for (const auto& r : rectangles) {
            if (r[0] <= x1 && r[2] >= x2) {
                ys.emplace_back(r[1], r[3]);
            }
        }
        if (ys.empty()) continue;
        std::sort(ys.begin(), ys.end(),
                  [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
                      return a.first < b.first;
                  });
        long long coveredY = 0;
        int curStart = ys[0].first;
        int curEnd = ys[0].second;
        for (size_t j = 1; j < ys.size(); ++j) {
            if (ys[j].first > curEnd) {
                coveredY += static_cast<long long>(curEnd) - curStart;
                curStart = ys[j].first;
                curEnd = ys[j].second;
            } else {
                curEnd = std::max(curEnd, ys[j].second);
            }
        }
        coveredY += static_cast<long long>(curEnd) - curStart;
        total = (total + coveredY % MOD * (width % MOD)) % MOD;
    }
    return static_cast<int>(total);
}

