template <typename Master>
void findSecretWord(const std::vector<std::string>& wordlist, Master& master) {
    std::vector<std::string> possibleWords = wordlist;
    const int allowedGuesses = 10;
    for (int i = 0; i < allowedGuesses; ++i) {
        std::string wordToGuess = possibleWords[0];
        int maxMatches = 0;
        for (size_t j = 1; j < possibleWords.size(); ++j) {
            int matches = 0;
            const std::string& wj = possibleWords[j];
            const std::string& w0 = possibleWords[0];
            for (size_t k = 0; k < wj.size(); ++k) {
                if (wj[k] == w0[k]) ++matches;
            }
            if (matches > maxMatches) {
                maxMatches = matches;
                wordToGuess = wj;
            }
        }
        int matches = master.guess(wordToGuess);
        if (matches == 6) return;
        std::vector<std::string> filtered;
        for (const std::string& word : possibleWords) {
            int count = 0;
            for (size_t k = 0; k < word.size(); ++k) {
                if (word[k] == wordToGuess[k]) ++count;
            }
            if (count == matches) {
                filtered.push_back(word);
            }
        }
        possibleWords = std::move(filtered);
    }
}

