static int gcd_int(int a, int b) {
    while (b != 0) {
        int t = b;
        b = a % b;
        a = t;
    }
    return a;
}

int mirrorReflection(int p, int q) {
    int g = gcd_int(p, q);
    p /= g;
    q /= g;
    if (p % 2 == 0) return 2;
    if (q % 2 == 0) return 0;
    return 1;
}

