int nextPrimePalindrome(int n) {
    auto isPalindrome = [&](int num) -> bool {
        std::string s = std::to_string(num);
        std::string rev = s;
        std::reverse(rev.begin(), rev.end());
        return s == rev;
    };
    auto isPrime = [&](int num) -> bool {
        if (num < 2) return false;
        int limit = static_cast<int>(std::sqrt(num));
        for (int i = 2; i <= limit; ++i) {
            if (num % i == 0) return false;
        }
        return true;
    };
    while (true) {
        if (isPalindrome(n) && isPrime(n)) return n;
        ++n;
    }
}

