int binaryGap(long long n) {
    std::string binaryString;
    if (n == 0) {
        binaryString = "0";
    } else {
        while (n > 0) {
            binaryString.push_back((n & 1) ? '1' : '0');
            n >>= 1;
        }
        std::reverse(binaryString.begin(), binaryString.end());
    }
    int maxDistance = 0;
    int lastOneIndex = -1;
    for (int i = 0; i < static_cast<int>(binaryString.size()); ++i) {
        if (binaryString[i] == '1') {
            if (lastOneIndex != -1) {
                int dist = i - lastOneIndex;
                if (dist > maxDistance) {
                    maxDistance = dist;
                }
            }
            lastOneIndex = i;
        }
    }
    return maxDistance;
}

