struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

std::vector<int> distanceK(TreeNode* root, TreeNode* target, int k) {
    std::unordered_map<int, TreeNode*> parentMap;
    std::function<void(TreeNode*, TreeNode*)> dfs = [&](TreeNode* node, TreeNode* parent) {
        if (!node) return;
        parentMap[node->val] = parent;
        dfs(node->left, node);
        dfs(node->right, node);
    };
    dfs(root, nullptr);

    std::queue<std::pair<TreeNode*, int>> q;
    q.emplace(target, 0);
    std::unordered_set<int> visited;
    visited.insert(target->val);
    std::vector<int> result;

    while (!q.empty()) {
        TreeNode* node = q.front().first;
        int distance = q.front().second;
        q.pop();

        if (distance == k) result.push_back(node->val);
        if (distance > k) break;

        TreeNode* neighbors[3] = {node->left, node->right, parentMap[node->val]};
        for (TreeNode* neighbor : neighbors) {
            if (neighbor && visited.find(neighbor->val) == visited.end()) {
                visited.insert(neighbor->val);
                q.emplace(neighbor, distance + 1);
            }
        }
    }
    return result;
}

