    int n = static_cast<int>(stations.size());
    long long fuel = startFuel;
    int stops = 0;
    while (fuel < target) {
        while (i < n && stations[i][0] <= fuel) {
            pq.push(stations[i][1]);
            ++i;
        }
        if (pq.empty()) {
            return -1;
        }
        fuel += pq.top();
        pq.pop();
        ++stops;
    }
    return stops;
}

