long long matrixScore(std::vector<std::vector<int>>& grid) {
    long long score = 0;
    int rows = static_cast<int>(grid.size());
    int cols = static_cast<int>(grid[0].size());
    for (int i = 0; i < rows; ++i) {
        if (grid[i][0] == 0) {
            for (int j = 0; j < cols; ++j) {
                grid[i][j] = 1 - grid[i][j];
            }
        }
    }
    for (int j = 1; j < cols; ++j) {
        int ones = 0;
        for (int i = 0; i < rows; ++i) {
            if (grid[i][j] == 1) {
                ++ones;
            }
        }
        if (ones < rows - ones) {
            for (int i = 0; i < rows; ++i) {
                grid[i][j] = 1 - grid[i][j];
            }
        }
    }
    for (int i = 0; i < rows; ++i) {
        long long rowScore = 0;
        for (int j = 0; j < cols; ++j) {
            rowScore += static_cast<long long>(grid[i][j]) * (1LL << (cols - 1 - j));
        }
        score += rowScore;
    }
    return score;
}

