    for (std::size_t i = 0; i < bills.size(); ++i) {
        if (bills[i] == 5) {
            ++fiveDollars;
        } else if (bills[i] == 10) {
            if (fiveDollars == 0) return false;
            --fiveDollars;
            ++tenDollars;
        } else {
            if (tenDollars > 0 && fiveDollars > 0) {
                --tenDollars;
                --fiveDollars;
            } else if (fiveDollars >= 3) {
                fiveDollars -= 3;
            } else {
