        if (command < 0) {
            if (command == -1) {
                int ndx = dy;
                int ndy = -dx;
                dx = ndx;
                dy = ndy;
            } else {
                int ndx = -dy;
                int ndy = dx;
                dx = ndx;
                dy = ndy;
            }
        } else {
            for (int i = 0; i < command; ++i) {
                int newX = x + dx;
                int newY = y + dy;
                std::string key = std::to_string(newX) + "," + std::to_string(newY);
                if (obstacleSet.find(key) != obstacleSet.end()) {
                    break;
                }
                x = newX;
                y = newY;
            }
        }
        maxDistance = std::max(maxDistance, x * x + y * y);
    }
    return maxDistance;
}

