static long long gcd_ll(long long a, long long b) {
    while (b) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

long long nthMagicalNumber(long long n, long long a, long long b) {
    const long long MOD = 1000000007LL;
    long long left = std::min(a, b);
    long long right = n * std::min(a, b);
    long long g = gcd_ll(a, b);
    long long lcm = (a / g) * b;
    while (left < right) {
        long long mid = left + (right - left) / 2;
        long long cnt = mid / a + mid / b - mid / lcm;
        if (cnt < n) left = mid + 1;
        else right = mid;
    }
    return left % MOD;
}

