char decodeAtIndex(const std::string& s, long long k) {
    long long size = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        if (std::isdigit(s[i])) {
            size *= s[i] - '0';
        } else {
            ++size;
        }
    }
    for (long long i = static_cast<long long>(s.size()) - 1; i >= 0; --i) {
        char c = s[i];
        if (std::isdigit(c)) {
            int d = c - '0';
            k %= size;
            size /= d;
        } else {
            if (k == size) {
                return c;
            }
            --size;
        }
    }
    return '\0';
}

