int minEatingSpeed(const std::vector<int>& piles, int h) {
    auto canEatAll = [&](int k) -> bool {
        long long time = 0;
        for (int pile : piles) {
            time += (pile + k - 1) / k;
        }
        return time <= h;
    };
    int left = 1;
    int right = *std::max_element(piles.begin(), piles.end());
    while (left < right) {
        int mid = left + (right - left) / 2;
