int profitableSchemes(int n, int minProfit, std::vector<int> group, std::vector<int> profit) {
    const int MOD = 1000000007;
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(minProfit + 1, 0));
    dp[0][0] = 1;
    for (size_t idx = 0; idx < group.size(); ++idx) {
        int g = group[idx];
        int p = profit[idx];
        for (int members = n; members >= g; --members) {
            for (int prof = minProfit; prof >= 0; --prof) {
                int newProf = prof - p;
                if (newProf < 0) newProf = 0;
                dp[members][prof] = (dp[members][prof] + dp[members - g][newProf]) % MOD;
            }
        }
    }
    int result = 0;
    for (int members = 0; members <= n; ++members) {
        result = (result + dp[members][minProfit]) % MOD;
    }
    return result;
}

