int reachableNodes(const std::vector<std::vector<int>>& edges, int maxMoves, int n) {
    std::vector<std::vector<std::pair<int, int>>> graph(n);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        int cnt = e[2];
        int w = cnt + 1;
        graph[u].emplace_back(v, w);
        graph[v].emplace_back(u, w);
    }
    const long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<long long> dist(n, INF);
    dist[0] = 0;
    using P = std::pair<long long, int>;
    std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
    pq.emplace(0, 0);
    while (!pq.empty()) {
        P top = pq.top();
        pq.pop();
        long long d = top.first;
        int node = top.second;
        if (d != dist[node]) continue;
        for (const auto& nb : graph[node]) {
            int neighbor = nb.first;
            int weight = nb.second;
            long long nd = d + weight;
            if (nd < dist[neighbor]) {
                dist[neighbor] = nd;
                pq.emplace(nd, neighbor);
            }
        }
    }
    int count = 0;
    for (long long d : dist) {
        if (d <= maxMoves) ++count;
    }
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        int cnt = e[2];
        long long fromU = (dist[u] == INF) ? 0 : std::max(0LL, static_cast<long long>(maxMoves) - dist[u]);
        long long fromV = (dist[v] == INF) ? 0 : std::max(0LL, static_cast<long long>(maxMoves) - dist[v]);
        long long reachableOnEdge = std::min(static_cast<long long>(cnt), fromU + fromV);
        count += static_cast<int>(reachableOnEdge);
    }
    return count;
}

