std::vector<std::vector<int>> spiralMatrixIII(int rows, int cols, int rStart, int cStart) {
    std::vector<std::vector<int>> result;
    std::vector<std::array<int, 2>> directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
    int directionIndex = 0;
    int steps = 1;
    int stepCount = 0;
    int row = rStart;
    int col = cStart;
    result.push_back({row, col});
    while (result.size() < static_cast<size_t>(rows * cols)) {
        int nextRow = row + directions[directionIndex][0];
        int nextCol = col + directions[directionIndex][1];
        if (nextRow >= 0 && nextRow < rows && nextCol >= 0 && nextCol < cols) {
            result.push_back({nextRow, nextCol});
        }
        row = nextRow;
        col = nextCol;
        stepCount++;
        if (stepCount == steps) {
            stepCount = 0;
            directionIndex = (directionIndex + 1) % 4;
            if (directionIndex % 2 == 0) {
                steps++;
            }
        }
    }
    return result;
}

