TreeNode* constructHelper(const std::vector<int>& preorder, const std::vector<int>& postorder,
                          const std::unordered_map<int, int>& postIndexMap,
                          int preStart, int preEnd, int postStart, int postEnd) {
    if (preStart > preEnd) return nullptr;
    TreeNode* root = new TreeNode(preorder[preStart]);
    if (preStart + 1 > preEnd) return root;
    int leftChildPostIndex = postIndexMap.at(preorder[preStart + 1]);
    int leftSubtreeSize = leftChildPostIndex - postStart + 1;
    root->left = constructHelper(preorder, postorder, postIndexMap,
                                 preStart + 1, preStart + leftSubtreeSize,
                                 postStart, leftChildPostIndex);
    root->right = constructHelper(preorder, postorder, postIndexMap,
                                  preStart + leftSubtreeSize + 1, preEnd,
                                  leftChildPostIndex + 1, postEnd - 1);
    return root;
}

TreeNode* constructFromPrePost(const std::vector<int>& preorder, const std::vector<int>& postorder) {
    std::unordered_map<int, int> postIndexMap;
    for (int i = 0; i < static_cast<int>(postorder.size()); ++i) {
        postIndexMap[postorder[i]] = i;
    }
    return constructHelper(preorder, postorder, postIndexMap,
                           0, static_cast<int>(preorder.size()) - 1,
                           0, static_cast<int>(postorder.size()) - 1);
}

