int numPermsDISequence(const std::string& s) {
    const int MOD = 1000000007;
    int n = static_cast<int>(s.size());
    std::vector<int> dpPrev(1, 1); // dp for i = 0
    for (int i = 1; i <= n; ++i) {
        std::vector<int> prefix(i, 0);
        prefix[0] = dpPrev[0];
        for (int k = 1; k < i; ++k) {
            prefix[k] = (prefix[k - 1] + dpPrev[k]) % MOD;
        }
        std::vector<int> dpCurr(i + 1, 0);
        if (s[i - 1] == 'I') {
            for (int j = 0; j <= i; ++j) {
                if (j == 0) dpCurr[j] = 0;
                else dpCurr[j] = prefix[j - 1];
            }
        } else { // 'D'
            int total = prefix[i - 1];
            for (int j = 0; j <= i; ++j) {
                int left = (j == 0) ? 0 : prefix[j - 1];
                dpCurr[j] = (total - left + MOD) % MOD;
            }
        }
        dpPrev.swap(dpCurr);
    }
    int result = 0;
    for (int v : dpPrev) {
        result = (result + v) % MOD;
    }
    return result;
}

