    long long res = 0;
    for (size_t i = 1; i < nStr.length(); ++i) {
        res += static_cast<long long>(std::pow(digits.size(), i));
    }
    std::vector<long long> dp(nStr.length(), 0);
    for (size_t i = 0; i < digits.size(); ++i) {
        if (digits[i][0] < nStr[0]) {
            dp[0]++;
        } else if (digits[i][0] == nStr[0]) {
            dp[0] = 1;
            break;
        }
