    for (size_t i = 1; i < nStr.length(); ++i) {
        for (size_t j = 0; j < digits.size(); ++j) {
            if (digits[j][0] < nStr[i]) {
                dp[i] += dp[i - 1] * digits.size();
            } else if (digits[j][0] == nStr[i]) {
                dp[i] += dp[i - 1];
            }
        }
    }
    res += dp[nStr.length() - 1];
    return res;
}

