        if (!st.empty()) {
            right[i] = st.back();
        }
        st.push_back(i);
    }
    long long sum = 0;
    for (int i = 0; i < n; ++i) {
        long long leftCount = i - left[i];
        long long rightCount = right[i] - i;
        long long contrib = (leftCount * rightCount) % MOD;
        contrib = (contrib * arr[i]) % MOD;
        sum = (sum + contrib) % MOD;
    }
    return static_cast<int>(sum);
}

