int snakesAndLadders(const std::vector<std::vector<int>>& board) {
    int n = static_cast<int>(board.size());
    int total = n * n;
    std::vector<int> cells(total, -1);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int idx = (i % 2 == 0) ? i * n + j : i * n + (n - j - 1);
            cells[idx] = board[n - 1 - i][j];
        }
    }
    std::vector<int> dist(total, -1);
    std::queue<int> q;
    q.push(0);
    dist[0] = 0;
    while (!q.empty()) {
        int cur = q.front();
        q.pop();
        if (cur == total - 1) {
            return dist[cur];
        }
        for (int dice = 1; dice <= 6; ++dice) {
            int nxt = cur + dice;
            if (nxt >= total) break;
            if (cells[nxt] != -1) {
                nxt = cells[nxt] - 1;
            }
            if (dist[nxt] == -1) {
                dist[nxt] = dist[cur] + 1;
                q.push(nxt);
            }
        }
    }
    return -1;
}

