bool isNStraightHand(const std::vector<int>& deck) {
    std::unordered_map<int, int> countMap;
    for (size_t i = 0; i < deck.size(); ++i) {
        ++countMap[deck[i]];
    }

    std::vector<int> sortedCards;
    sortedCards.reserve(countMap.size());
    for (const auto& kv : countMap) {
        sortedCards.push_back(kv.first);
    }
    std::sort(sortedCards.begin(), sortedCards.end());

    for (size_t i = 0; i < sortedCards.size(); ++i) {
        int card = sortedCards[i];
        auto itCard = countMap.find(card);
        if (itCard != countMap.end() && itCard->second > 0) {
            int count = itCard->second;
            for (int j = card; j < card + count; ++j) {
                auto it = countMap.find(j);
                if (it == countMap.end() || it->second < count) {
                    return false;
                }
                it->second -= count;
            }
        }
    }
    return true;
}

