std::vector<int> sortArray(const std::vector<int>& nums) {
    std::function<std::vector<int>(const std::vector<int>&)> mergeSort = [&](const std::vector<int>& arr) -> std::vector<int> {
        if (arr.size() <= 1) return arr;
        size_t mid = arr.size() / 2;
        std::vector<int> left(arr.begin(), arr.begin() + mid);
        std::vector<int> right(arr.begin() + mid, arr.end());
        auto merge = [&](const std::vector<int>& l, const std::vector<int>& r) -> std::vector<int> {
            std::vector<int> result;
            result.reserve(l.size() + r.size());
            size_t i = 0, j = 0;
            while (i < l.size() && j < r.size()) {
                if (l[i] < r[j]) {
                    result.push_back(l[i]);
                    ++i;
                } else {
                    result.push_back(r[j]);
                    ++j;
                }
            }
            while (i < l.size()) {
                result.push_back(l[i]);
                ++i;
            }
            while (j < r.size()) {
                result.push_back(r[j]);
                ++j;
            }
            return result;
        };
        return merge(mergeSort(left), mergeSort(right));
    };
    return mergeSort(nums);
}

