std::vector<std::string> wordSubsets(const std::vector<std::string>& words1, const std::vector<std::string>& words2) {
    std::unordered_map<char, int> maxFreq;
    for (const std::string& word : words2) {
        std::unordered_map<char, int> freq;
        for (char c : word) {
            ++freq[c];
        }
        for (const auto& p : freq) {
            char c = p.first;
            int count = p.second;
            int existing = 0;
            auto it = maxFreq.find(c);
            if (it != maxFreq.end()) {
                existing = it->second;
            }
            maxFreq[c] = std::max(existing, count);
        }
    }

    std::vector<std::string> result;
    for (const std::string& word : words1) {
        std::unordered_map<char, int> freq;
        for (char c : word) {
            ++freq[c];
        }
        bool isUniversal = true;
        for (const auto& p : maxFreq) {
            char c = p.first;
            int required = p.second;
            int have = 0;
            auto it = freq.find(c);
            if (it != freq.end()) {
                have = it->second;
            }
            if (have < required) {
                isUniversal = false;
                break;
            }
        }
        if (isUniversal) {
            result.push_back(word);
        }
    }
    return result;
}

