class TopVotedCandidate {
public:
    std::vector<int> times, leaders;
    TopVotedCandidate(std::vector<int>& persons, std::vector<int>& times_) : times(times_) {
        std::unordered_map<int,int> counts;
        int leader = -1, maxCount = 0;
        for (int p : persons) {
            counts[p]++;
            if (counts[p] >= maxCount) { maxCount = counts[p]; leader = p; }
            leaders.push_back(leader);
        }
    }
    int q(int t) {
        int left = 0, right = (int)times.size()-1;
        while (left < right) {
            int mid = (left+right+1)/2;
            if (times[mid] <= t) left = mid; else right = mid-1;
        }
        return leaders[left];
    }
};

#include <bits/stdc++.h>

int catMouseGame(const std::vector<std::vector<int>>& graph) {
    int n = static_cast<int>(graph.size());
    const int DRAW = 0, MOUSE_WIN = 1, CAT_WIN = 2;
    std::vector<std::vector<std::array<int, 2>>> result(n, std::vector<std::array<int, 2>>(n, {DRAW, DRAW}));
    std::vector<std::vector<std::array<int, 2>>> degree(n, std::vector<std::array<int, 2>>(n, {0, 0}));
    for (int m = 0; m < n; ++m) {
        for (int c = 0; c < n; ++c) {
            degree[m][c][0] = static_cast<int>(graph[m].size());
            int cnt = 0;
            for (int nxt : graph[c]) {
                if (nxt != 0) ++cnt;
            }
            degree[m][c][1] = cnt;
        }
    }
    std::queue<std::tuple<int, int, int>> q;
    for (int c = 0; c < n; ++c) {
        for (int turn = 0; turn < 2; ++turn) {
            if (result[0][c][turn] == DRAW) {
                result[0][c][turn] = MOUSE_WIN;
                q.emplace(0, c, turn);
            }
        }
    }
    for (int m = 1; m < n; ++m) {
        for (int turn = 0; turn < 2; ++turn) {
            if (result[m][m][turn] == DRAW) {
                result[m][m][turn] = CAT_WIN;
                q.emplace(m, m, turn);
            }
        }
    }
    while (!q.empty()) {
        auto tup = q.front();
        q.pop();
        int m = std::get<0>(tup);
        int c = std::get<1>(tup);
        int turn = std::get<2>(tup);
        int curRes = result[m][c][turn];
        if (turn == 0) {
            for (int prevC = 0; prevC < n; ++prevC) {
                if (prevC == 0) continue;
                bool canMove = false;
                for (int nxt : graph[prevC]) {
                    if (nxt == c) { canMove = true; break; }
                }
                if (!canMove) continue;
                int pm = m;
                int pturn = 1;
                if (result[pm][prevC][pturn] != DRAW) continue;
                if (curRes == CAT_WIN) {
                    result[pm][prevC][pturn] = CAT_WIN;
                    q.emplace(pm, prevC, pturn);
                } else {
                    degree[pm][prevC][pturn]--;
                    if (degree[pm][prevC][pturn] == 0) {
                        result[pm][prevC][pturn] = MOUSE_WIN;
                        q.emplace(pm, prevC, pturn);
                    }
                }
            }
        } else {
            for (int prevM = 0; prevM < n; ++prevM) {
                bool canMove = false;
                for (int nxt : graph[prevM]) {
                    if (nxt == m) { canMove = true; break; }
                }
                if (!canMove) continue;
                int pc = c;
                int pturn = 0;
                if (result[prevM][pc][pturn] != DRAW) continue;
                if (curRes == MOUSE_WIN) {
                    result[prevM][pc][pturn] = MOUSE_WIN;
                    q.emplace(prevM, pc, pturn);
                } else {
                    degree[prevM][pc][pturn]--;
                    if (degree[prevM][pc][pturn] == 0) {
                        result[prevM][pc][pturn] = CAT_WIN;
                        q.emplace(prevM, pc, pturn);
                    }
                }
            }
        }
    }
    return result[1][2][0];
}

