long long maxSubarraySumCircular(const std::vector<int>& nums) {
    long long totalSum = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        totalSum += nums[i];
    }

    long long maxSum = LLONG_MIN;
    long long currentMaxSum = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        currentMaxSum = std::max<long long>(nums[i], currentMaxSum + nums[i]);
        maxSum = std::max(maxSum, currentMaxSum);
    }

    long long minSum = LLONG_MAX;
    long long currentMinSum = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        currentMinSum = std::min<long long>(nums[i], currentMinSum + nums[i]);
        minSum = std::min(minSum, currentMinSum);
    }

    if (totalSum == minSum) {
        return maxSum;
    } else {
        return std::max(maxSum, totalSum - minSum);
    }
}

