class CBTInserter {
public:
    TreeNode* root;
    std::deque<TreeNode*> q;
    CBTInserter(TreeNode* root_) : root(root_) {
        std::deque<TreeNode*> bfs{root};
        while (!bfs.empty()) {
            TreeNode* node = bfs.front(); bfs.pop_front();
            if (!node->left || !node->right) q.push_back(node);
            if (node->left) bfs.push_back(node->left);
            if (node->right) bfs.push_back(node->right);
        }
    }
    int insert(int val) {
        TreeNode* node = new TreeNode(val);
        TreeNode* parent = q.front();
        if (!parent->left) parent->left = node;
        else { parent->right = node; q.pop_front(); }
        q.push_back(node);
        return parent->val;
    }
    TreeNode* get_root() { return root; }
};

