long long threeSumMulti(std::vector<int> arr, int target) {
    std::sort(arr.begin(), arr.end());
    long long count = 0;
    int n = static_cast<int>(arr.size());
    for (int i = 0; i < n - 2; ++i) {
        int left = i + 1;
        int right = n - 1;
        while (left < right) {
            int sum = arr[i] + arr[left] + arr[right];
            if (sum < target) {
                ++left;
            } else if (sum > target) {
                --right;
            } else {
                if (arr[left] == arr[right]) {
                    long long m = right - left + 1;
                    count += m * (m - 1) / 2;
                    break;
                }
                long long leftCount = 1;
                while (left + 1 < right && arr[left] == arr[left + 1]) {
                    ++leftCount;
                    ++left;
                }
                long long rightCount = 1;
                while (right - 1 > left && arr[right] == arr[right - 1]) {
                    ++rightCount;
                    --right;
                }
                count += leftCount * rightCount;
                ++left;
                --right;
            }
        }
    }
    return count;
}

