int minFallingPathSum(const std::vector<std::vector<int>>& matrix) {
    int n = static_cast<int>(matrix.size());
    std::vector<int> dp = matrix[0];
    for (int i = 1; i < n; ++i) {
        std::vector<int> temp(n, std::numeric_limits<int>::max());
        for (int j = 0; j < n; ++j) {
            if (j == 0) {
                temp[j] = std::min(dp[j], dp[j + 1]) + matrix[i][j];
            } else if (j == n - 1) {
                temp[j] = std::min(dp[j - 1], dp[j]) + matrix[i][j];
            } else {
                temp[j] = std::min({dp[j - 1], dp[j], dp[j + 1]}) + matrix[i][j];
            }
        }
        dp.swap(temp);
    }
    return *std::min_element(dp.begin(), dp.end());
}

