int minMalwareSpread(const std::vector<std::vector<int>>& graph, const std::vector<int>& initial) {
    int n = graph.size();
    std::vector<int> parent(n);
    std::vector<int> rank(n, 0);
    for (int i = 0; i < n; ++i) parent[i] = i;

    std::function<int(int)> find = [&](int x) -> int {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    };

    auto unite = [&](int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    };

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (graph[i][j] == 1) {
                unite(i, j);
            }
        }
    }

    std::unordered_map<int, int> groupSize;
    for (int i = 0; i < n; ++i) {
        int root = find(i);
        ++groupSize[root];
    }

    std::unordered_map<int, int> infectedCount;
    for (int node : initial) {
        int root = find(node);
        ++infectedCount[root];
    }

    int minSize = INT_MAX;
    int nodeToRemove = -1;

    for (int node : initial) {
        int root = find(node);
        if (infectedCount[root] == 1) {
            int size = groupSize[root];
            if (size < minSize) {
                minSize = size;
                nodeToRemove = node;
            } else if (size == minSize && node < nodeToRemove) {
                nodeToRemove = node;
            }
        }
    }

    if (minSize == INT_MAX) {
        return *std::min_element(initial.begin(), initial.end());
    }
    return nodeToRemove;
}

#include <bits/stdc++.h>

int minMalwareSpread(const std::vector<std::vector<int>>& graph, const std::vector<int>& initial) {
    int n = static_cast<int>(graph.size());
    std::vector<std::vector<int>> adj(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (graph[i][j] == 1 && i != j) {
                adj[i].push_back(j);
            }
        }
    }

    int bestNode = 0;
    int bestInfected = n + 1; // larger than possible

    for (int removed = 0; removed < n; ++removed) {
        std::vector<char> infected(n, false);
        std::queue<int> q;
        for (int src : initial) {
            if (src == removed) continue;
            if (!infected[src]) {
                infected[src] = true;
                q.push(src);
            }
        }
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int v : adj[u]) {
                if (v == removed) continue;
                if (!infected[v]) {
                    infected[v] = true;
                    q.push(v);
                }
            }
        }
        int cnt = 0;
        for (int i = 0; i < n; ++i) {
            if (infected[i]) ++cnt;
        }
        if (cnt < bestInfected || (cnt == bestInfected && removed < bestNode)) {
            bestInfected = cnt;
            bestNode = removed;
        }
    }
