int knightDialer(int n) {
    const int MOD = 1000000007;
    const std::vector<std::vector<int>> moves = {
        {4, 6},
        {6, 8},
        {7, 9},
        {4, 8},
        {3, 9, 0},
        {},
        {1, 7, 0},
        {2, 6},
        {1, 3},
        {2, 4}
    };
    std::vector<int64_t> dp(10, 1);
    for (int i = 2; i <= n; ++i) {
        std::vector<int64_t> next(10, 0);
        for (int j = 0; j < 10; ++j) {
            for (int move : moves[j]) {
                next[j] = (next[j] + dp[move]) % MOD;
            }
        }
        dp.swap(next);
    }
    int64_t total = 0;
    for (int64_t count : dp) {
        total = (total + count) % MOD;
    }
    return static_cast<int>(total);
}

