std::vector<std::string> reorderLogFiles(const std::vector<std::string>& logs) {
    std::vector<std::string> letterLogs;
    std::vector<std::string> digitLogs;
    for (const std::string& log : logs) {
        std::size_t firstSpace = log.find(' ');
        std::string rest = log.substr(firstSpace + 1);
        std::size_t secondSpace = rest.find(' ');
        std::string secondToken = (secondSpace == std::string::npos) ? rest : rest.substr(0, secondSpace);
        if (!secondToken.empty() && std::isdigit(static_cast<unsigned char>(secondToken[0]))) {
            digitLogs.push_back(log);
        } else {
            letterLogs.push_back(log);
        }
    }
    std::sort(letterLogs.begin(), letterLogs.end(),
        [](const std::string& a, const std::string& b) {
            std::size_t idxA = a.find(' ');
            std::size_t idxB = b.find(' ');
            std::string contentA = a.substr(idxA + 1);
            std::string contentB = b.substr(idxB + 1);
            if (contentA < contentB) return true;
            if (contentA > contentB) return false;
            return a < b;
        });
    std::vector<std::string> result = letterLogs;
    result.insert(result.end(), digitLogs.begin(), digitLogs.end());
    return result;
}

