std::vector<int> movesToStamp(const std::string& stamp, const std::string& target) {
    std::vector<int> result;
    std::string cur = target;
    int n = static_cast<int>(target.size());
    int m = static_cast<int>(stamp.size());
    std::vector<bool> visited(n, false);
    int stampedCount = 0;
    while (stampedCount < n) {
        bool madeProgress = false;
        for (int i = 0; i <= n - m; ++i) {
            if (visited[i]) continue;
            bool canStamp = true;
            bool willChange = false;
            for (int j = 0; j < m; ++j) {
                char c = cur[i + j];
                if (c == '?') continue;
                if (c != stamp[j]) {
                    canStamp = false;
                    break;
                }
                willChange = true;
            }
            if (canStamp && willChange) {
                for (int j = 0; j < m; ++j) {
                    if (cur[i + j] != '?') {
                        cur[i + j] = '?';
                        ++stampedCount;
                    }
                }
                visited[i] = true;
                result.push_back(i);
                madeProgress = true;
                break;
            }
        }
        if (!madeProgress) break;
    }
    if (stampedCount == n) {
        std::reverse(result.begin(), result.end());
        return result;
    }
    return {};
}

