int rangeSumBST(TreeNode* root, int low, int high) {
    int sum = 0;
    std::function<void(TreeNode*)> dfs = [&](TreeNode* node) {
        if (!node) return;
        dfs(node->left);
        if (node->val >= low && node->val <= high) sum += node->val;
        dfs(node->right);
    };
    dfs(root);
    return sum;
}

