long long distinctSubseqII(const std::string& s) {
    const long long MOD = 1000000007LL;
    int n = s.size();
    std::vector<long long> dp(n + 1, 0);
    dp[0] = 1;
    std::unordered_map<char, int> last;
    for (int i = 1; i <= n; ++i) {
        dp[i] = (dp[i - 1] * 2) % MOD;
        char c = s[i - 1];
        auto it = last.find(c);
        if (it != last.end()) {
            dp[i] = (dp[i] - dp[it->second - 1] + MOD) % MOD;
        }
        last[c] = i;
    }
    return (dp[n] - 1 + MOD) % MOD;
}

