std::string shortestSuperstring(const std::vector<std::string>& words) {
    std::vector<std::string> filtered;
    for (size_t i = 0; i < words.size(); ++i) {
        bool keep = true;
        for (size_t j = 0; j < words.size(); ++j) {
            if (i != j && words[j].find(words[i]) != std::string::npos) {
                keep = false;
                break;
            }
        }
        if (keep) filtered.push_back(words[i]);
    }
    int n = static_cast<int>(filtered.size());
    if (n == 0) return "";
    if (n == 1) return filtered[0];

    std::vector<std::vector<int>> overlap(n, std::vector<int>(n, 0));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i == j) continue;
            int maxK = std::min(filtered[i].size(), filtered[j].size());
            for (int k = maxK; k > 0; --k) {
                if (filtered[i].compare(filtered[i].size() - k, k, filtered[j], 0, k) == 0) {
                    overlap[i][j] = k;
                    break;
                }
            }
        }
    }

    int totalMask = 1 << n;
    std::vector<std::vector<std::string>> dp(totalMask, std::vector<std::string>(n));
    for (int i = 0; i < n; ++i) {
        dp[1 << i][i] = filtered[i];
    }

    for (int mask = 1; mask < totalMask; ++mask) {
        for (int i = 0; i < n; ++i) {
            if (!((mask >> i) & 1)) continue;
            int prevMask = mask ^ (1 << i);
            if (prevMask == 0) continue;
            for (int j = 0; j < n; ++j) {
                if (!((prevMask >> j) & 1)) continue;
                if (dp[prevMask][j].empty()) continue;
                std::string candidate = dp[prevMask][j] + filtered[i].substr(overlap[j][i]);
                if (dp[mask][i].empty() ||
                    candidate.size() < dp[mask][i].size() ||
                    (candidate.size() == dp[mask][i].size() && candidate < dp[mask][i])) {
                    dp[mask][i] = std::move(candidate);
                }
            }
        }
    }

    int fullMask = totalMask - 1;
    std::string answer;
    for (int i = 0; i < n; ++i) {
        if (dp[fullMask][i].empty()) continue;
        if (answer.empty() ||
            dp[fullMask][i].size() < answer.size() ||
            (dp[fullMask][i].size() == answer.size() && dp[fullMask][i] < answer)) {
            answer = dp[fullMask][i];
        }
    }

    std::string baseConcat;
    for (const std::string& s : filtered) baseConcat += s;
    if (baseConcat.size() == answer.size()) return baseConcat;
    return answer;
}

