void permute(std::vector<int>& a, int l, int r, const std::function<void(const std::vector<int>&)>& callback) {
    if (l == r) {
        callback(a);
    } else {
        for (int i = l; i <= r; ++i) {
            std::swap(a[l], a[i]);
            permute(a, l + 1, r, callback);
            std::swap(a[l], a[i]);
        }
    }
}

std::string largestTimeFromDigits(std::vector<int> arr) {
    int maxTime = -1;
    permute(arr, 0, static_cast<int>(arr.size()) - 1, [&](const std::vector<int>& permutation) {
        int hours = permutation[0] * 10 + permutation[1];
        int minutes = permutation[2] * 10 + permutation[3];
        if (hours < 24 && minutes < 60) {
            maxTime = std::max(maxTime, hours * 60 + minutes);
        }
    });
    if (maxTime == -1) {
        return "";
    }
    int hours = maxTime / 60;
    int minutes = maxTime % 60;
    std::ostringstream oss;
    oss << std::setw(2) << std::setfill('0') << hours << ':' << std::setw(2) << std::setfill('0') << minutes;
    return oss.str();
}

