static std::vector<int> getPrimeFactors(int n) {
    std::vector<int> factors;
    int x = n;
    for (int p = 2; p * 1LL * p <= x; ++p) {
        if (x % p == 0) {
            factors.push_back(p);
            while (x % p == 0) {
                x /= p;
            }
        }
    }
    if (x > 1) {
        factors.push_back(x);
    }
    return factors;
}

int largestComponentSize(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;
    std::vector<int> parent(n), sz(n, 1);
    for (int i = 0; i < n; ++i) parent[i] = i;
    std::function<int(int)> find = [&](int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    auto unite = [&](int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return;
        if (sz[ra] < sz[rb]) std::swap(ra, rb);
        parent[rb] = ra;
        sz[ra] += sz[rb];
    };
    std::unordered_map<int, int> factorToIndex;
    for (int i = 0; i < n; ++i) {
        std::vector<int> factors = getPrimeFactors(nums[i]);
        for (int f : factors) {
            auto it = factorToIndex.find(f);
            if (it == factorToIndex.end()) {
                factorToIndex[f] = i;
            } else {
                unite(i, it->second);
            }
        }
    }
    int maxSize = 0;
    for (int i = 0; i < n; ++i) {
        if (parent[i] == i) {
            maxSize = std::max(maxSize, sz[i]);
        }
    }
    return maxSize;
}

