int tallestBillboard(const std::vector<int>& rods) {
    std::unordered_map<int, int> dp;
    dp[0] = 0;
    for (int rod : rods) {
        std::unordered_map<int, int> temp;
        for (const auto& kv : dp) {
            int diff = kv.first;
            int val = kv.second;
            auto it = temp.find(diff);
            if (it == temp.end() || it->second < val) temp[diff] = val;
            int diff1 = diff + rod;
            it = temp.find(diff1);
            if (it == temp.end() || it->second < val) temp[diff1] = val;
            int diff2 = std::abs(diff - rod);
            int newVal = val + std::min(diff, rod);
            it = temp.find(diff2);
            if (it == temp.end() || it->second < newVal) temp[diff2] = newVal;
        }
        dp.swap(temp);
    }
    return dp[0];
}

