bool canReorderDoubled(std::vector<int> arr) {
    std::unordered_map<long long, int> cnt;
    for (int v : arr) {
        ++cnt[static_cast<long long>(v)];
    }
    std::sort(arr.begin(), arr.end(), [](int a, int b) {
        return std::abs(a) < std::abs(b);
    });
    for (int v : arr) {
        long long val = static_cast<long long>(v);
        if (cnt[val] == 0) continue;
        long long dbl = val * 2;
        if (cnt[dbl] < cnt[val]) return false;
        cnt[dbl] -= cnt[val];
        cnt[val] = 0;
    }
    return true;
}

