    if (n == 0) n = 14;
    for (int i = 0; i < n; ++i) {
        std::vector<int> nextState(8, 0);
        for (int j = 1; j < 7; ++j) {
            nextState[j] = (cells[j - 1] == cells[j + 1]) ? 1 : 0;
        }
        cells = std::move(nextState);
    }
    return cells;
}

