int repeatedNTimes(const std::vector<int>& nums) {
    std::unordered_map<int, int> countMap;
    for (size_t i = 0; i < nums.size(); ++i) {
        if (countMap.find(nums[i]) != countMap.end()) {
            countMap[nums[i]]++;
        } else {
            countMap[nums[i]] = 1;
        }
    }
    int half = static_cast<int>(nums.size() / 2);
    for (const auto& kv : countMap) {
        if (kv.second == half) {
            return kv.first;
        }
    }
    return 0;
}

