int maxWidthRamp(const std::vector<int>& nums) {
    std::vector<int> stack;
    for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
        if (stack.empty() || nums[i] < nums[stack.back()]) {
            stack.push_back(i);
        }
    }
    int maxWidth = 0;
    for (int j = static_cast<int>(nums.size()) - 1; j >= 0; --j) {
        while (!stack.empty() && nums[j] >= nums[stack.back()]) {
            maxWidth = std::max(maxWidth, j - stack.back());
            stack.pop_back();
        }
    }
    return maxWidth;
}

