int minDeletionSize(const std::vector<std::string>& strs) {
    int n = static_cast<int>(strs.size());
    int m = static_cast<int>(strs[0].size());
    std::vector<int> dp(m, 1);
    int best = 0;
    for (int j = 0; j < m; ++j) {
        for (int i = 0; i < j; ++i) {
            bool ok = true;
            for (int r = 0; r < n; ++r) {
                if (strs[r][i] > strs[r][j]) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                dp[j] = std::max(dp[j], dp[i] + 1);
            }
        }
        best = std::max(best, dp[j]);
    }
    return m - best;
}

