double minAreaFreeRect(const std::vector<std::vector<int>>& points) {
    struct Key {
        long long mx, my, len;
        bool operator==(const Key& other) const noexcept {
            return mx == other.mx && my == other.my && len == other.len;
        }
    };
    struct KeyHash {
        std::size_t operator()(const Key& k) const noexcept {
            std::size_t h1 = std::hash<long long>{}(k.mx);
            std::size_t h2 = std::hash<long long>{}(k.my);
            std::size_t h3 = std::hash<long long>{}(k.len);
            return h1 ^ (h2 << 1) ^ (h3 << 2);
        }
    };
    std::unordered_map<Key, std::vector<std::pair<long long, long long>>, KeyHash> groups;
    double minArea = std::numeric_limits<double>::infinity();
    int n = static_cast<int>(points.size());
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            long long mx = static_cast<long long>(points[i][0]) + points[j][0];
            long long my = static_cast<long long>(points[i][1]) + points[j][1];
            long long dx = static_cast<long long>(points[i][0]) - points[j][0];
            long long dy = static_cast<long long>(points[i][1]) - points[j][1];
            long long len = dx * dx + dy * dy;
            Key key{mx, my, len};
            auto& vecs = groups[key];
            for (const auto& v : vecs) {
                long long cross = std::llabs(dx * v.second - dy * v.first);
                double area = cross / 2.0;
                if (area > 0 && area < minArea) {
                    minArea = area;
                }
            }
            vecs.emplace_back(dx, dy);
        }
    }
    return minArea == std::numeric_limits<double>::infinity() ? 0 : minArea;
}

