static void dfs(std::vector<std::vector<int>>& grid, int i, int j) {
    int rows = grid.size();
    int cols = grid[0].size();
    if (i < 0 || i >= rows || j < 0 || j >= cols || grid[i][j] != 0) {
        return;
    }
    grid[i][j] = 1;
    dfs(grid, i + 1, j);
    dfs(grid, i - 1, j);
    dfs(grid, i, j + 1);
    dfs(grid, i, j - 1);
}

int regionsBySlashes(const std::vector<std::string>& grid) {
    int n = grid.size();
    int size = n * 3;
    std::vector<std::vector<int>> newGrid(size, std::vector<int>(size, 0));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == '/') {
                newGrid[i * 3][j * 3 + 2] = 1;
                newGrid[i * 3 + 1][j * 3 + 1] = 1;
                newGrid[i * 3 + 2][j * 3] = 1;
            } else if (grid[i][j] == '\\') {
                newGrid[i * 3][j * 3] = 1;
                newGrid[i * 3 + 1][j * 3 + 1] = 1;
                newGrid[i * 3 + 2][j * 3 + 2] = 1;
            }
        }
    }
    int count = 0;
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            if (newGrid[i][j] == 0) {
                dfs(newGrid, i, j);
                ++count;
            }
        }
    }
    return count;
}

