std::string toLower(const std::string& s) {
    std::string res = s;
    for (char& c : res) {
        c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    }
    return res;
}

std::string vowelIgnore(const std::string& s) {
    std::string res = s;
    for (char& c : res) {
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
            c = '*';
        }
    }
    return res;
}

std::vector<std::string> spellchecker(const std::vector<std::string>& wordlist, const std::vector<std::string>& queries) {
    std::unordered_set<std::string> wordSet(wordlist.begin(), wordlist.end());
    std::unordered_map<std::string, std::string> lowerCaseMap;
    std::unordered_map<std::string, std::string> vowelMap;
    lowerCaseMap.reserve(wordlist.size());
    vowelMap.reserve(wordlist.size());

    for (const std::string& word : wordlist) {
        std::string lower = toLower(word);
        if (lowerCaseMap.find(lower) == lowerCaseMap.end()) {
            lowerCaseMap[lower] = word;
        }
        std::string vowelIgnored = vowelIgnore(lower);
        if (vowelMap.find(vowelIgnored) == vowelMap.end()) {
            vowelMap[vowelIgnored] = word;
        }
    }

    std::vector<std::string> result;
    result.reserve(queries.size());
    for (const std::string& query : queries) {
        if (wordSet.find(query) != wordSet.end()) {
            result.push_back(query);
        } else {
            std::string lower = toLower(query);
            auto itLower = lowerCaseMap.find(lower);
            if (itLower != lowerCaseMap.end()) {
                result.push_back(itLower->second);
            } else {
                std::string vowelIgnored = vowelIgnore(lower);
                auto itVowel = vowelMap.find(vowelIgnored);
                if (itVowel != vowelMap.end()) {
                    result.push_back(itVowel->second);
                } else {
                    result.push_back("");
                }
            }
        }
    }
    return result;
}

