std::vector<int> numsSameConsecDiff(int n, int k) {
    std::vector<int> result;
    if (n == 1) {
        for (int i = 0; i <= 9; ++i) result.push_back(i);
        return result;
    }
    std::function<void(int,int)> dfs = [&](int cur, int last) {
        int len = 0;
        int temp = cur;
        while (temp > 0) {
            ++len;
            temp /= 10;
        }
        if (len == n) {
            result.push_back(cur);
            return;
        }
        std::vector<int> next;
        if (last - k >= 0) next.push_back(last - k);
        if (k != 0 && last + k <= 9) next.push_back(last + k);
        std::sort(next.begin(), next.end());
        for (int nd : next) {
            dfs(cur * 10 + nd, nd);
        }
    };
    for (int i = 1; i <= 9; ++i) {
        dfs(i, i);
    }
    std::sort(result.begin(), result.end());
    return result;
}

