std::vector<int> pancakeSort(std::vector<int> arr) {
    std::vector<int> res;
    int n = static_cast<int>(arr.size());
    for (int size = n; size > 1; --size) {
        int maxIdx = static_cast<int>(std::distance(arr.begin(), std::max_element(arr.begin(), arr.begin() + size)));
        if (maxIdx == size - 1) {
            continue;
        }
        if (maxIdx == 0) {
            res.push_back(size);
            std::reverse(arr.begin(), arr.begin() + size);
        } else {
            res.push_back(size);
            std::reverse(arr.begin(), arr.begin() + size);
            int newIdx = size - 1 - maxIdx;
            res.push_back(newIdx + 1);
            std::reverse(arr.begin(), arr.begin() + newIdx + 1);
            res.push_back(size);
            std::reverse(arr.begin(), arr.begin() + size);
        }
    }
    return res;
}

