std::vector<std::vector<int>> kClosest(const std::vector<std::vector<int>>& points, int k) {
    struct Item { std::vector<int> point; double distance; };
    std::vector<Item> pointsWithDistance;
    pointsWithDistance.reserve(points.size());
    for (const auto& p : points) {
        double d = std::sqrt(p[0] * p[0] + p[1] * p[1]);
        pointsWithDistance.push_back({p, d});
    }
    std::sort(pointsWithDistance.begin(), pointsWithDistance.end(),
        [](const Item& a, const Item& b) { return a.distance < b.distance; });
    std::vector<std::vector<int>> result;
    result.reserve(k);
    for (int i = 0; i < k && i < static_cast<int>(pointsWithDistance.size()); ++i) {
        result.push_back(pointsWithDistance[i].point);
    }
    return result;
}

