long long subarraysDivByK(const std::vector<int>& nums, int k) {
    std::unordered_map<long long, long long> prefixSumCount;
    prefixSumCount[0] = 1;
    long long currentSum = 0;
    long long count = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        currentSum += nums[i];
        long long remainder = ((currentSum % k) + k) % k;
        auto it = prefixSumCount.find(remainder);
