static std::pair<long long, long long> toFraction(const std::string& s) {
    size_t dotPos = s.find('.');
    std::string intPart, nonRep, rep;
    if (dotPos == std::string::npos) {
        intPart = s;
    } else {
        intPart = s.substr(0, dotPos);
        size_t parPos = s.find('(', dotPos);
        if (parPos == std::string::npos) {
            nonRep = s.substr(dotPos + 1);
        } else {
            nonRep = s.substr(dotPos + 1, parPos - dotPos - 1);
            size_t closePos = s.find(')', parPos);
            rep = s.substr(parPos + 1, closePos - parPos - 1);
        }
    }

    long long ip = std::stoll(intPart.empty() ? "0" : intPart);
    int b = static_cast<int>(nonRep.size());
    int c = static_cast<int>(rep.size());

    long long num, den;
    if (c == 0) {
        long long pow10b = 1;
        for (int i = 0; i < b; ++i) pow10b *= 10;
        long long Bval = b ? std::stoll(nonRep) : 0;
        den = pow10b;
        num = ip * den + Bval;
    } else {
        long long pow10b = 1;
        for (int i = 0; i < b; ++i) pow10b *= 10;
        long long pow10c = 1;
        for (int i = 0; i < c; ++i) pow10c *= 10;
        long long repDen = pow10c - 1;
        den = pow10b * repDen;
        long long Bval = b ? std::stoll(nonRep) : 0;
        long long Cval = std::stoll(rep);
        long long fracNum = Bval * repDen + Cval;
        num = ip * den + fracNum;
    }

    auto gcd_ll = [](long long a, long long b) {
        while (b != 0) {
            long long t = a % b;
            a = b;
            b = t;
        }
        return a < 0 ? -a : a;
    };
    long long g = gcd_ll(num, den);
    num /= g;
    den /= g;
    return {num, den};
}

bool isRationalEqual(const std::string& s, const std::string& t) {
    auto f1 = toFraction(s);
    auto f2 = toFraction(t);
    return f1.first == f2.first && f1.second == f2.second;
}

