int oddEvenJumps(const std::vector<int>& arr) {
    int n = static_cast<int>(arr.size());
    if (n == 0) return 0;
    std::vector<int> nextHigher(n, -1), nextLower(n, -1);
    std::vector<std::pair<int, int>> order;
    order.reserve(n);
    for (int i = 0; i < n; ++i) order.emplace_back(arr[i], i);
    std::sort(order.begin(), order.end(),
              [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
                  if (a.first != b.first) return a.first < b.first;
                  return a.second < b.second;
              });
    std::vector<int> stk;
    for (const auto& p : order) {
        int idx = p.second;
        while (!stk.empty() && idx > stk.back()) {
            nextHigher[stk.back()] = idx;
            stk.pop_back();
        }
        stk.push_back(idx);
    }
    std::sort(order.begin(), order.end(),
              [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
                  if (a.first != b.first) return a.first > b.first;
                  return a.second < b.second;
              });
    stk.clear();
    for (const auto& p : order) {
        int idx = p.second;
        while (!stk.empty() && idx > stk.back()) {
            nextLower[stk.back()] = idx;
            stk.pop_back();
        }
        stk.push_back(idx);
    }
    std::vector<char> odd(n, 0), even(n, 0);
    odd[n - 1] = 1;
    even[n - 1] = 1;
    for (int i = n - 2; i >= 0; --i) {
        if (nextHigher[i] != -1) odd[i] = even[nextHigher[i]];
        if (nextLower[i] != -1) even[i] = odd[nextLower[i]];
    }
    int count = 0;
    for (int i = 0; i < n; ++i) {
        if (odd[i]) ++count;
    }
    return count;
}

