    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            if (grid[i][j] != -1) ++nonObstacles;
            if (grid[i][j] == 1) {
                startRow = i;
                startCol = j;
            }
        }
    }
    const int directions[4][2] = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    int result = 0;
    std::function<void(int, int, int)> backtrack = [&](int row, int col, int steps) {
        if (grid[row][col] == 2) {
            if (steps == nonObstacles) ++result;
            return;
        }
        for (int d = 0; d < 4; ++d) {
            int newRow = row + directions[d][0];
            int newCol = col + directions[d][1];
            if (newRow < 0 || newRow >= rows || newCol < 0 || newCol >= cols) continue;
            if (grid[newRow][newCol] == -1 || grid[newRow][newCol] == -2) continue;
            if (grid[newRow][newCol] == 2) {
                backtrack(newRow, newCol, steps + 1);
            } else {
                int temp = grid[newRow][newCol];
                grid[newRow][newCol] = -2;
                backtrack(newRow, newCol, steps + 1);
                grid[newRow][newCol] = temp;
            }
        }
    };
    grid[startRow][startCol] = -2;
    backtrack(startRow, startCol, 1);
    return result;
}

