std::vector<long long> sumEvenAfterQueries(std::vector<int> nums, const std::vector<std::vector<int>>& queries) {
    long long evenSum = 0;
    for (int num : nums) {
        if (num % 2 == 0) {
            evenSum += num;
        }
    }
    std::vector<long long> result;
    result.reserve(queries.size());
    for (const auto& query : queries) {
        int val = query[0];
        int index = query[1];
        if (nums[index] % 2 == 0) {
            evenSum -= nums[index];
        }
        nums[index] += val;
        if (nums[index] % 2 == 0) {
            evenSum += nums[index];
        }
        result.push_back(evenSum);
    }
    return result;
}

