std::string strWithout3a3b(int a, int b) {
    std::string result;
    auto feasible = [](int a_rem, int b_rem) {
        int mx = std::max(a_rem, b_rem);
        int mn = std::min(a_rem, b_rem);
        return mx <= 2 * (mn + 1);
    };
    while (a > 0 || b > 0) {
        bool canPlaceA = false;
        if (a > 0) {
            if (result.size() < 2 || !(result[result.size() - 1] == 'a' && result[result.size() - 2] == 'a')) {
                if (feasible(a - 1, b)) {
                    canPlaceA = true;
                }
            }
        }
        if (canPlaceA) {
            result.push_back('a');
            --a;
        } else {
            // place 'b' (guaranteed to be possible)
            result.push_back('b');
            --b;
        }
    }
    return result;
}

