int brokenCalculator(int startValue, int target) {
    long long ops = 0;
    long long s = startValue;
    long long t = target;
    if (s >= t) {
        return static_cast<int>(s - t);
    }
    while (t > s) {
        if (t % 2 == 0) {
            t /= 2;
        } else {
            t += 1;
        }
        ++ops;
    }
    ops += (s - t);
    return static_cast<int>(ops);
}

