long long subarraysWithKDistinct(const std::vector<int>& nums, int k) {
    auto atMostK = [&](int kk) -> long long {
        int left = 0;
        long long count = 0;
        std::unordered_map<int, int> freq;
        for (int right = 0; right < static_cast<int>(nums.size()); ++right) {
            freq[nums[right]]++;
            while (static_cast<int>(freq.size()) > kk) {
                freq[nums[left]]--;
                if (freq[nums[left]] == 0) {
                    freq.erase(nums[left]);
                }
                ++left;
            }
            count += right - left + 1;
        }
        return count;
    };
    return atMostK(k) - atMostK(k - 1);
}

