std::vector<int> addToArrayForm(const std::vector<int>& num, long long k) {
    std::string s;
    s.reserve(num.size());
    for (int digit : num) {
        s.push_back(static_cast<char>('0' + digit));
    }
    std::string ks = std::to_string(k);
    int i = static_cast<int>(s.size()) - 1;
    int j = static_cast<int>(ks.size()) - 1;
    int carry = 0;
    std::string result;
    while (i >= 0 || j >= 0 || carry) {
        int sum = carry;
        if (i >= 0) sum += s[i--] - '0';
        if (j >= 0) sum += ks[j--] - '0';
        result.push_back(static_cast<char>('0' + (sum % 10)));
        carry = sum / 10;
    }
    std::reverse(result.begin(), result.end());
    std::vector<int> out;
    out.reserve(result.size());
    for (char c : result) {
        out.push_back(c - '0');
    }
    return out;
}

