};

bool isCousins(TreeNode* root, int x, int y) {
    struct NodeInfo {
        TreeNode* node;
        int depth;
        int parent;
    };
    std::queue<NodeInfo> q;
    q.push({root, 0, -1});
    int xDepth = -1, xParent = -1;
    int yDepth = -1, yParent = -1;
    while (!q.empty()) {
        NodeInfo cur = q.front();
        q.pop();
        TreeNode* node = cur.node;
        int depth = cur.depth;
        int parent = cur.parent;
        if (node->val == x) {
            xDepth = depth;
            xParent = parent;
        }
        if (node->val == y) {
            yDepth = depth;
            yParent = parent;
        }
        if (xDepth != -1 && yDepth != -1) break;
        if (node->left) q.push({node->left, depth + 1, node->val});
        if (node->right) q.push({node->right, depth + 1, node->val});
    }
    return (xDepth == yDepth) && (xParent != yParent);
}

