std::vector<std::vector<int>> verticalTraversal(TreeNode* root) {
    if (!root) return {};
    std::unordered_map<int, std::vector<int>> columnTable;
    int minColumn = 0, maxColumn = 0;
    std::queue<std::pair<TreeNode*, int>> q;
    q.push({root, 0});
    while (!q.empty()) {
        int size = q.size();
        std::unordered_map<int, std::vector<int>> temp;
        for (int i = 0; i < size; ++i) {
            auto nodePair = q.front();
            q.pop();
            TreeNode* node = nodePair.first;
            int column = nodePair.second;
            minColumn = std::min(minColumn, column);
            maxColumn = std::max(maxColumn, column);
            temp[column].push_back(node->val);
            if (node->left) q.push({node->left, column - 1});
            if (node->right) q.push({node->right, column + 1});
        }
        for (auto& kv : temp) {
            std::vector<int>& vec = kv.second;
            std::sort(vec.begin(), vec.end());
            columnTable[kv.first].insert(columnTable[kv.first].end(), vec.begin(), vec.end());
        }
    }
    std::vector<std::vector<int>> result;
    for (int i = minColumn; i <= maxColumn; ++i) {
        if (columnTable.find(i) != columnTable.end())
            result.push_back(columnTable[i]);
        else
            result.push_back({});
    }
    return result;
}

