bool equationsPossible(const std::vector<std::string>& equations) {
    std::vector<int> parent(26);
    for (int i = 0; i < 26; ++i) {
        parent[i] = i;
    }

    for (const std::string& equation : equations) {
        if (equation[1] == '=') {
            int x = equation[0] - 'a';
            int y = equation[3] - 'a';
            parent[find(parent, x)] = find(parent, y);
        }
    }

    for (const std::string& equation : equations) {
        if (equation[1] == '!') {
            int x = equation[0] - 'a';
            int y = equation[3] - 'a';
            if (find(parent, x) == find(parent, y)) {
                return false;
            }
        }
    }

    return true;
}

