int minKBitFlips(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    std::vector<int> diff(n, 0);
    int cur = 0;
    int flips = 0;
    for (int i = 0; i < n; ++i) {
        if (i >= k) {
            cur -= diff[i - k];
        }
        if ((nums[i] + cur) % 2 == 0) {
            if (i + k > n) {
                return -1;
            }
            ++flips;
            ++cur;
            diff[i] = 1;
        }
    }
    return flips;
}

