int numSquarefulPerms(const std::vector<int>& nums) {
    std::vector<int> a = nums;
    std::sort(a.begin(), a.end());
    int n = static_cast<int>(a.size());
    std::vector<bool> used(n, false);
    long long count = 0;
    std::function<void(int)> dfs = [&](int depth) {
        if (depth == n) {
            ++count;
            return;
        }
        for (int i = 0; i < n; ++i) {
            if (used[i]) continue;
            if (i > 0 && a[i] == a[i - 1] && !used[i - 1]) continue;
            if (depth > 0) {
                int sum = a[i] + a[depth - 1];
                int r = static_cast<int>(std::sqrt(sum));
                if (r * r != sum) continue;
            }
            used[i] = true;
            dfs(depth + 1);
            used[i] = false;
        }
    };
    dfs(0);
    return static_cast<int>(count);
}

