std::vector<int> gridIllumination(int n, std::vector<std::vector<int>>& lamps, std::vector<std::vector<int>>& queries) {
    std::unordered_set<std::string> lampSet;
    for (const auto& lamp : lamps) {
        lampSet.insert(std::to_string(lamp[0]) + "," + std::to_string(lamp[1]));
    }

    std::vector<int> rowMap(n, 0);
    std::vector<int> colMap(n, 0);
    std::vector<int> diagMap1(2 * n - 1, 0);
    std::vector<int> diagMap2(2 * n - 1, 0);

    for (const auto& lamp : lamps) {
        int row = lamp[0];
        int col = lamp[1];
        rowMap[row]++;
        colMap[col]++;
        diagMap1[row + col]++;
        diagMap2[row - col + n - 1]++;
    }

    std::vector<int> result(queries.size(), 0);

    for (size_t i = 0; i < queries.size(); ++i) {
        int row = queries[i][0];
        int col = queries[i][1];

        if (rowMap[row] > 0 || colMap[col] > 0 || diagMap1[row + col] > 0 || diagMap2[row - col + n - 1] > 0) {
            result[i] = 1;
        }

        for (int r = std::max(0, row - 1); r <= std::min(n - 1, row + 1); ++r) {
            for (int c = std::max(0, col - 1); c <= std::min(n - 1, col + 1); ++c) {
                std::string key = std::to_string(r) + "," + std::to_string(c);
                if (lampSet.find(key) != lampSet.end()) {
                    rowMap[r]--;
                    colMap[c]--;
                    diagMap1[r + c]--;
                    diagMap2[r - c + n - 1]--;
                    lampSet.erase(key);
                }
            }
        }
    }

    return result;
}

