long long clumsy(int n) {
    if (n <= 2) {
        return n;
    }
    if (n == 3) {
        return 6;
    }
    if (n == 4) {
        return 7;
    }
    int mod = n % 4;
    if (mod == 0) {
        return static_cast<long long>(n) + 1;
    }
    if (mod == 1) {
        return static_cast<long long>(n) + 2;
    }
    if (mod == 2) {
