long long numDupDigitsAtMostN(long long n) {
    long long count = 0;
    long long i = 1;
    while (i <= n) {
        long long num = i;
        std::unordered_set<int> seen;
        bool hasRepeated = false;
        while (num > 0) {
            int digit = static_cast<int>(num % 10);
            if (seen.find(digit) != seen.end()) {
                hasRepeated = true;
                break;
            }
            seen.insert(digit);
            num /= 10;
        }
        if (!hasRepeated) {
            ++count;
        }
        ++i;
    }
    return n - count;
}

