int shipWithinDays(const std::vector<int>& weights, int days) {
    int left = *std::max_element(weights.begin(), weights.end());
    long long sum = std::accumulate(weights.begin(), weights.end(), 0LL);
    int right = static_cast<int>(sum);
    while (left < right) {
        int mid = left + (right - left) / 2;
        int need = 1;
        int cur = 0;
        for (int weight : weights) {
            if (cur + weight > mid) {
                ++need;
                cur = 0;
            }
            cur += weight;
        }
        if (need <= days) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }
    return left;
}

