TreeNode* bstFromPreorder(const std::vector<int>& preorder) {
    if (preorder.empty()) return nullptr;
    TreeNode* root = new TreeNode(preorder[0]);
    std::vector<TreeNode*> stack;
    stack.push_back(root);
    for (size_t i = 1; i < preorder.size(); ++i) {
        if (preorder[i] < stack.back()->val) {
            stack.back()->left = new TreeNode(preorder[i]);
            stack.push_back(stack.back()->left);
        } else {
            TreeNode* last = nullptr;
            while (!stack.empty() && stack.back()->val < preorder[i]) {
                last = stack.back();
                stack.pop_back();
            }
            last->right = new TreeNode(preorder[i]);
            stack.push_back(last->right);
        }
    }
    return root;
}

