    int count = 0, currEnd = 0, farEnd = 0, i = 0;
    while (i < static_cast<int>(clips.size()) && clips[i][0] <= currEnd) {
        while (i < static_cast<int>(clips.size()) && clips[i][0] <= currEnd) {
