    int maxLength = 0;
    std::unordered_map<long long, std::unordered_map<int, int>> sequenceLengths;
    for (size_t i = 0; i < nums.size(); ++i) {
        for (size_t j = 0; j < i; ++j) {
            long long difference = static_cast<long long>(nums[i]) - static_cast<long long>(nums[j]);
            auto diffIt = sequenceLengths.find(difference);
            if (diffIt != sequenceLengths.end() && diffIt->second.find(static_cast<int>(j)) != diffIt->second.end()) {
                sequenceLengths[difference][static_cast<int>(i)] = diffIt->second[static_cast<int>(j)] + 1;
            } else {
                if (diffIt == sequenceLengths.end()) {
                    sequenceLengths[difference] = std::unordered_map<int, int>();
                }
                sequenceLengths[difference][static_cast<int>(i)] = 2;
            }
            maxLength = std::max(maxLength, sequenceLengths[difference][static_cast<int>(i)]);
        }
    }
    return maxLength;
}

