    size_t index = 0;
    std::function<TreeNode*(int)> dfs = [&](int depth) -> TreeNode* {
        size_t start = index;
        int dashes = 0;
        while (index < traversal.size() && traversal[index] == '-') {
            ++dashes;
            ++index;
        }
        if (dashes != depth) {
            index = start; // rewind: these dashes belong to an ancestor level
            return nullptr;
        }
        int value = 0;
        while (index < traversal.size() && traversal[index] != '-') {
            value = value * 10 + (traversal[index] - '0');
            ++index;
        }
        TreeNode* node = new TreeNode(value);
        node->left = dfs(depth + 1);
        node->right = dfs(depth + 1);
        return node;
    };
    return dfs(0);
}

