class StreamChecker {
public:
    TrieNode* trie;
    std::string stream;
    StreamChecker(std::vector<std::string>& words) {
        trie = new TrieNode();
        for (auto& word : words) {
            TrieNode* node = trie;
            for (int i = (int)word.size()-1; i >= 0; i--) {
                char c = word[i];
                if (!node->children.count(c)) node->children[c] = new TrieNode();
                node = node->children[c];
            }
            node->end = true;
        }
    }
    bool query(char letter) {
        stream += letter;
        TrieNode* node = trie;
        for (int i = (int)stream.size()-1; i >= 0; i--) {
            if (!node->children.count(stream[i])) return false;
            node = node->children[stream[i]];
            if (node->end) return true;
        }
        return false;
    }
};

