std::vector<std::vector<int>> colorBorder(std::vector<std::vector<int>>& grid, int row, int col, int color) {
    int rows = grid.size();
    int cols = grid[0].size();
    int originalColor = grid[row][col];
    std::unordered_set<std::string> visited;
    std::unordered_set<std::string> borderCells;
    std::vector<std::pair<int, int>> directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    std::function<void(int, int)> dfs = [&](int r, int c) {
        if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] != originalColor) {
            return;
        }
        std::string key = std::to_string(r) + "," + std::to_string(c);
        if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
            borderCells.insert(key);
        } else {
            if (grid[r - 1][c] != originalColor || grid[r + 1][c] != originalColor ||
                grid[r][c - 1] != originalColor || grid[r][c + 1] != originalColor) {
                borderCells.insert(key);
            }
        }
        visited.insert(key);
        for (const auto& dir : directions) {
            int nr = r + dir.first;
            int nc = c + dir.second;
            std::string nkey = std::to_string(nr) + "," + std::to_string(nc);
            if (visited.find(nkey) == visited.end()) {
                dfs(nr, nc);
            }
        }
    };
    dfs(row, col);
    for (const auto& cell : borderCells) {
        size_t commaPos = cell.find(',');
        int r = std::stoi(cell.substr(0, commaPos));
        int c = std::stoi(cell.substr(commaPos + 1));
        grid[r][c] = color;
    }
    return grid;
}

