long long minScoreTriangulation(const std::vector<int>& values) {
    std::size_t n = values.size();
    std::vector<std::vector<long long>> dp(n, std::vector<long long>(n, 0));
    for (std::size_t length = 2; length < n; ++length) {
        for (std::size_t i = 0; i + length < n; ++i) {
            std::size_t j = i + length;
            dp[i][j] = std::numeric_limits<long long>::max();
            for (std::size_t k = i + 1; k < j; ++k) {
                long long score = static_cast<long long>(values[i]) * values[k] * values[j] + dp[i][k] + dp[k][j];
                dp[i][j] = std::min(dp[i][j], score);
            }
        }
    }
    return dp[0][n - 1];
}

