        if (stones[n - 2] - stones[0] == n - 2 && stones[n - 1] - stones[n - 2] > 2) {
            special = true;
        }
        if (stones[n - 1] - stones[1] == n - 2 && stones[1] - stones[0] > 2) {
            special = true;
        }
        if (special) {
            minMoves = 2;
        }
    }
    return {minMoves, maxMoves};
}

