bool isEscapePossible(const std::vector<std::vector<int>>& blocked, const std::vector<int>& source, const std::vector<int>& target) {
    std::unordered_set<std::string> blockedSet;
    for (size_t i = 0; i < blocked.size(); ++i) {
        blockedSet.insert(std::to_string(blocked[i][0]) + "," + std::to_string(blocked[i][1]));
    }

    const int moves[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    std::deque<std::pair<int, int>> queue;
    queue.emplace_back(source[0], source[1]);

    std::unordered_set<std::string> visited;
    visited.insert(std::to_string(source[0]) + "," + std::to_string(source[1]));

    while (!queue.empty()) {
        auto current = queue.front();
        queue.pop_front();

        if (current.first == target[0] && current.second == target[1]) {
            return true;
        }

        for (int i = 0; i < 4; ++i) {
            int newX = current.first + moves[i][0];
            int newY = current.second + moves[i][1];

            if (newX >= 0 && newX < 1000000 && newY >= 0 && newY < 1000000) {
                std::string key = std::to_string(newX) + "," + std::to_string(newY);
                if (blockedSet.find(key) == blockedSet.end() && visited.find(key) == visited.end()) {
                    queue.emplace_back(newX, newY);
                    visited.insert(key);
                }
            }
        }

        if (queue.size() > 200) {
            return true;
        }
    }

    return false;
}

