    int totalSum = 0;
    for (size_t i = 0; i < stones.size(); ++i) {
        totalSum += stones[i];
    }
    int half = totalSum / 2;
    std::vector<int> dp(half + 1, 0);
    for (size_t i = 0; i < stones.size(); ++i) {
        int w = stones[i];
        for (int j = half; j >= w; --j) {
