static unsigned long long base = 256ULL;

static int checkDuplicate(const std::string& s, int len) {
    if (len == 0) return -1;
    int n = static_cast<int>(s.size());
    unsigned long long hash = 0;
    unsigned long long power = 1;
    for (int i = 0; i < len; ++i) {
        hash = hash * base + static_cast<unsigned long long>(s[i]);
        power *= base;
    }
    std::unordered_map<unsigned long long, std::vector<int>> mp;
    mp.reserve(n);
    mp[hash].push_back(0);
    for (int i = 1; i <= n - len; ++i) {
        hash = hash * base + static_cast<unsigned long long>(s[i + len - 1]);
        hash -= static_cast<unsigned long long>(s[i - 1]) * power;
        auto it = mp.find(hash);
        if (it != mp.end()) {
            for (int start : it->second) {
                if (s.compare(start, len, s, i, len) == 0) {
                    return i;
                }
            }
        }
        mp[hash].push_back(i);
    }
    return -1;
}

std::string longestDuplicateSubstring(const std::string& s) {
    int n = static_cast<int>(s.size());
    int left = 1, right = n - 1;
    int bestLen = 0, bestPos = -1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        int pos = checkDuplicate(s, mid);
        if (pos != -1) {
            bestLen = mid;
            bestPos = pos;
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    if (bestLen == 0) return "";
    return s.substr(bestPos, bestLen);
}

