static char findChar(char x, std::vector<char>& parent) {
    int idx = x - 'a';
    if (parent[idx] != x) {
        parent[idx] = findChar(parent[idx], parent);
    }
    return parent[idx];
}

static void unionChar(char x, char y, std::vector<char>& parent) {
    char rootX = findChar(x, parent);
    char rootY = findChar(y, parent);
    if (rootX > rootY) {
        parent[rootX - 'a'] = rootY;
    } else {
        parent[rootY - 'a'] = rootX;
    }
}

