std::vector<int> addNegabinary(const std::vector<int>& arr1, const std::vector<int>& arr2) {
    std::vector<int> result;
    int carry = 0;
    std::size_t i = arr1.size();
    std::size_t j = arr2.size();
    while (i > 0 || j > 0 || carry != 0) {
        int a = 0, b = 0;
        if (i > 0) a = arr1[--i];
        if (j > 0) b = arr2[--j];
        int sum = a + b + carry;
        int digit = (sum % 2 + 2) % 2;
        result.push_back(digit);
        carry = (sum - digit) / -2;
    }
    while (result.size() > 1 && result.back() == 0) {
        result.pop_back();
    }
    std::reverse(result.begin(), result.end());
    return result;
}

