int numSubmatrixSumTarget(const std::vector<std::vector<int>>& matrix, int target) {
    int count = 0;
    int rows = static_cast<int>(matrix.size());
    int cols = static_cast<int>(matrix[0].size());
    std::vector<std::vector<long long>> prefixSum(rows + 1, std::vector<long long>(cols + 1, 0));
    for (int i = 1; i <= rows; ++i) {
        for (int j = 1; j <= cols; ++j) {
            prefixSum[i][j] = prefixSum[i - 1][j] + prefixSum[i][j - 1] - prefixSum[i - 1][j - 1] + matrix[i - 1][j - 1];
        }
    }
    for (int x1 = 0; x1 < rows; ++x1) {
        for (int y1 = 0; y1 < cols; ++y1) {
            for (int x2 = x1; x2 < rows; ++x2) {
                for (int y2 = y1; y2 < cols; ++y2) {
                    long long sum = prefixSum[x2 + 1][y2 + 1] - prefixSum[x2 + 1][y1] - prefixSum[x1][y2 + 1] + prefixSum[x1][y1];
                    if (sum == target) {
                        ++count;
                    }
                }
            }
        }
    }
    return count;
}

