std::string smallestSubsequence(const std::string& s) {
    std::unordered_set<char> seen;
    std::vector<char> stack;
    std::unordered_map<char, std::size_t> lastOccurrence;
    for (std::size_t i = 0; i < s.size(); ++i) {
        lastOccurrence[s[i]] = i;
