bool carPooling(const std::vector<std::vector<int>>& trips, int capacity) {
    std::vector<std::pair<int, int>> locations;
    locations.reserve(trips.size() * 2);
    for (size_t i = 0; i < trips.size(); ++i) {
        locations.emplace_back(trips[i][1], trips[i][0]);
        locations.emplace_back(trips[i][2], -trips[i][0]);
    }
    std::sort(locations.begin(), locations.end(),
        [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
            if (a.first != b.first) return a.first < b.first;
            return a.second < b.second;
        });
    int currentPassengers = 0;
    for (const auto& loc : locations) {
        currentPassengers += loc.second;
        if (currentPassengers > capacity) return false;
    }
    return true;
}

