class MountainArray {
public:
    int get(int index);
    int length();
};

int findInMountainArray(int target, MountainArray &mountainArr) {
    int left = 0, right = mountainArr.length() - 1;
    while (left < right) {
        int mid = (left + right) / 2;
        if (mountainArr.get(mid) < mountainArr.get(mid + 1)) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    int peak = left;
    left = 0;
    right = peak;
    while (left <= right) {
        int mid = (left + right) / 2;
        int val = mountainArr.get(mid);
        if (val == target) {
            return mid;
        } else if (val < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    left = peak;
    right = mountainArr.length() - 1;
    while (left <= right) {
        int mid = (left + right) / 2;
        int val = mountainArr.get(mid);
        if (val == target) {
            return mid;
        } else if (val < target) {
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }
    return -1;
}

