std::vector<std::string> braceExpansionII(const std::string& expression) {
    std::function<std::unordered_set<std::string>(size_t&)> parseExpression;
    std::function<std::unordered_set<std::string>(size_t&)> parseTerm;
    std::function<std::unordered_set<std::string>(size_t&)> parseUnion;

    parseExpression = [&](size_t& i) -> std::unordered_set<std::string> {
        std::unordered_set<std::string> cur;
        cur.insert("");
        while (i < expression.size() && expression[i] != '}' && expression[i] != ',') {
            std::unordered_set<std::string> term = parseTerm(i);
            std::unordered_set<std::string> next;
            for (const std::string& a : cur) {
                for (const std::string& b : term) {
                    next.insert(a + b);
                }
            }
            cur.swap(next);
        }
        return cur;
    };

    parseTerm = [&](size_t& i) -> std::unordered_set<std::string> {
        if (expression[i] == '{') {
            ++i; // skip '{'
            std::unordered_set<std::string> inner = parseUnion(i);
            ++i; // skip '}'
            return inner;
        } else {
            std::string ch(1, expression[i]);
            ++i;
            return {ch};
        }
    };

    parseUnion = [&](size_t& i) -> std::unordered_set<std::string> {
        std::unordered_set<std::string> result;
        while (true) {
            std::unordered_set<std::string> expr = parseExpression(i);
            result.insert(expr.begin(), expr.end());
            if (i < expression.size() && expression[i] == ',') {
                ++i; // skip ','
            } else {
                break;
            }
        }
        return result;
    };

    size_t idx = 0;
    std::unordered_set<std::string> resSet = parseExpression(idx);
    std::vector<std::string> result(resSet.begin(), resSet.end());
    std::sort(result.begin(), result.end());
    return result;
}

