std::vector<int> distributeCandies(int candies, int num_people) {
    std::vector<int> distribution(num_people, 0);
    int i = 0;
    int candiesGiven = 1;
    while (candies > 0) {
        int candiesToGive = std::min(candiesGiven, candies);
        distribution[i] += candiesToGive;
        candies -= candiesToGive;
        i = (i + 1) % num_people;
        ++candiesGiven;
    }
    return distribution;
}

