std::vector<int> pathInZigZagTree(int label) {
    std::vector<int> path;
    long long cur = label;
    long long level = 0;
    while ((1LL << level) <= cur) ++level;
    while (true) {
        path.push_back(static_cast<int>(cur));
        if (level == 1) break;
        long long left = 1LL << (level - 1);
        long long right = (1LL << level) - 1;
        cur = (left + right - cur) / 2;
        --level;
    }
    std::reverse(path.begin(), path.end());
    return path;
}

