int minHeightShelves(const std::vector<std::vector<int>>& books, int shelfWidth) {
    int n = static_cast<int>(books.size());
    const int INF = std::numeric_limits<int>::max() / 2;
    std::vector<int> dp(n + 1, INF);
    dp[0] = 0;
    for (int i = 1; i <= n; ++i) {
        int width = 0;
        int height = 0;
        for (int j = i - 1; j >= 0; --j) {
            width += books[j][0];
            height = std::max(height, books[j][1]);
            if (width > shelfWidth) break;
            dp[i] = std::min(dp[i], dp[j] + height);
        }
    }
    return dp[n];
}

