bool parseBoolExpr(const std::string& expression) {
    std::function<bool(const std::string&, size_t&)> eval = [&](const std::string& s, size_t& pos) -> bool {
        if (s[pos] == 't') {
            ++pos;
            return true;
        }
        if (s[pos] == 'f') {
            ++pos;
            return false;
        }
        char op = s[pos];
        ++pos; // skip operator
        ++pos; // skip '('
        if (op == '!') {
            bool val = eval(s, pos);
            ++pos; // skip ')'
            return !val;
        }
        if (op == '&') {
            bool result = true;
            while (true) {
                bool val = eval(s, pos);
                result = result && val;
                if (s[pos] == ')') {
                    ++pos;
                    break;
                }
                ++pos; // skip ','
            }
            return result;
        }
        // op == '|'
        bool result = false;
        while (true) {
            bool val = eval(s, pos);
            result = result || val;
            if (s[pos] == ')') {
                ++pos;
                break;
            }
            ++pos; // skip ','
        }
        return result;
    };
    size_t start = 0;
    return eval(expression, start);
}

