std::vector<int> relativeSortArray(const std::vector<int>& arr1, const std::vector<int>& arr2) {
    std::unordered_map<int, int> frequencyMap;
    for (int val : arr1) {
        ++frequencyMap[val];
    }
    std::vector<int> result;
    result.reserve(arr1.size());
    for (int val : arr2) {
        auto it = frequencyMap.find(val);
        while (it != frequencyMap.end() && it->second > 0) {
            result.push_back(val);
            --(it->second);
        }
    }
    std::vector<int> remaining;
    remaining.reserve(frequencyMap.size());
    for (const auto& p : frequencyMap) {
        if (p.second > 0) {
            remaining.push_back(p.first);
        }
    }
    std::sort(remaining.begin(), remaining.end());
    for (int key : remaining) {
        int cnt = frequencyMap[key];
        for (int i = 0; i < cnt; ++i) {
            result.push_back(key);
        }
    }
    return result;
}

