std::vector<int> smallestSufficientTeam(const std::vector<std::string>& req_skills, const std::vector<std::vector<std::string>>& people) {
    std::unordered_map<std::string, int> skillToBit;
    for (size_t i = 0; i < req_skills.size(); ++i) {
        skillToBit[req_skills[i]] = 1 << i;
    }

    std::vector<int> personSkills;
    personSkills.reserve(people.size());
    for (const auto& person : people) {
        int skillBitmask = 0;
        for (const auto& skill : person) {
            auto it = skillToBit.find(skill);
            if (it != skillToBit.end()) {
                skillBitmask |= it->second;
            }
        }
        personSkills.push_back(skillBitmask);
    }

    int fullMask = (1 << req_skills.size()) - 1;
    std::vector<std::vector<int>> dp(1 << req_skills.size());
    std::vector<bool> has(1 << req_skills.size(), false);
    dp[0] = std::vector<int>();
    has[0] = true;

    for (size_t i = 0; i < people.size(); ++i) {
        for (int j = fullMask; j >= 0; --j) {
            if (has[j]) {
                int newMask = j | personSkills[i];
                if (!has[newMask] || dp[j].size() + 1 < dp[newMask].size()) {
                    dp[newMask] = dp[j];
                    dp[newMask].push_back(static_cast<int>(i));
                    has[newMask] = true;
                }
            }
        }
    }

    return dp[fullMask];
}

