long long mctFromLeafValues(const std::vector<int>& arr) {
    long long result = 0;
    std::vector<int> stack;
    stack.push_back(std::numeric_limits<int>::max());
    for (int num : arr) {
        while (stack.back() < num) {
            int mid = stack.back();
            stack.pop_back();
            result += static_cast<long long>(mid) * std::min(stack.back(), num);
        }
        stack.push_back(num);
    }
    while (stack.size() > 2) {
        int mid = stack.back();
        stack.pop_back();
        result += static_cast<long long>(mid) * stack.back();
    }
    return result;
}

