std::vector<int> shortestAlternatingPaths(int n, const std::vector<std::vector<int>>& redEdges, const std::vector<std::vector<int>>& blueEdges) {
    std::vector<std::vector<int>> redGraph(n), blueGraph(n);
    for (const auto& e : redEdges) {
        redGraph[e[0]].push_back(e[1]);
    }
    for (const auto& e : blueEdges) {
        blueGraph[e[0]].push_back(e[1]);
    }

    std::vector<int> result(n, -1);
    std::queue<std::tuple<int, int, bool>> q;
    q.emplace(0, 0, true);
    q.emplace(0, 0, false);
    result[0] = 0;

    while (!q.empty()) {
        int node, length;
        bool isRed;
        std::tie(node, length, isRed) = q.front();
        q.pop();

        if (isRed) {
            for (int neighbor : blueGraph[node]) {
                if (result[neighbor] == -1) {
                    result[neighbor] = length + 1;
                    q.emplace(neighbor, length + 1, false);
                }
            }
        } else {
            for (int neighbor : redGraph[node]) {
                if (result[neighbor] == -1) {
                    result[neighbor] = length + 1;
                    q.emplace(neighbor, length + 1, true);
                }
            }
        }
    }

    return result;
}

