int stoneGameII(const std::vector<int>& piles) {
    int n = static_cast<int>(piles.size());
    std::vector<long long> suffixSum(n + 1, 0);
    for (int i = n - 1; i >= 0; --i) {
        suffixSum[i] = suffixSum[i + 1] + piles[i];
    }
    std::vector<std::vector<long long>> memo(n, std::vector<long long>(n + 1, -1));
    std::function<long long(int, int)> dp = [&](int i, int m) -> long long {
        if (i + 2 * m >= n) {
            return suffixSum[i];
        }
        if (memo[i][m] != -1) {
            return memo[i][m];
        }
        long long maxScore = LLONG_MIN;
        for (int x = 1; x <= 2 * m; ++x) {
            long long score = suffixSum[i] - dp(i + x, std::max(x, m));
            if (score > maxScore) {
                maxScore = score;
            }
        }
        memo[i][m] = maxScore;
        return maxScore;
    };
    return static_cast<int>(dp(0, 1));
}

