int movesToMakeZigzag(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    long long movesEvenPeak = 0; // even indices are peaks, odd are valleys
    long long movesOddPeak = 0;  // odd indices are peaks, even are valleys
    const int INF = INT_MAX;
    for (int i = 0; i < n; ++i) {
        int left = (i > 0) ? nums[i - 1] : INF;
        int right = (i + 1 < n) ? nums[i + 1] : INF;
        int need = std::max(0, nums[i] - std::min(left, right) + 1);
        if (i % 2 == 0) {
            movesOddPeak += need; // make even index a valley
        } else {
            movesEvenPeak += need; // make odd index a valley
        }
    }
    return static_cast<int>(std::min(movesEvenPeak, movesOddPeak));
}

