bool btreeGameWinningMove(TreeNode* root, int n, int x) {
    TreeNode* targetNode = nullptr;
    std::function<void(TreeNode*)> findNode = [&](TreeNode* node) {
        if (node && node->val == x) targetNode = node;
        if (node && node->left) findNode(node->left);
        if (node && node->right) findNode(node->right);
    };
    findNode(root);
    std::function<int(TreeNode*)> countSize = [&](TreeNode* node) -> int {
        if (!node) return 0;
        return 1 + countSize(node->left) + countSize(node->right);
    };
    int leftCount = countSize(targetNode->left);
    int rightCount = countSize(targetNode->right);
    return leftCount > n / 2 || rightCount > n / 2 || n - leftCount - rightCount - 1 > n / 2;
}

