    void set(int index, int val) { snapshots[index][snapId] = val; }
    int snap() { return snapId++; }
    int get(int index, int snap_id) {
        int bestId = -1, bestVal = 0;
        for (auto& [sid, val] : snapshots[index]) {
            if (sid <= snap_id && sid > bestId) { bestId = sid; bestVal = val; }
        }
        return bestVal;
    }
};

