int maxRepOpt1(const std::string& text) {
    int n = static_cast<int>(text.size());
    if (n == 0) return 0;
    std::vector<int> total(26, 0);
    for (char c : text) total[c - 'a']++;

    std::vector<char> runChars;
    std::vector<int> runLengths;
    runChars.reserve(n);
    runLengths.reserve(n);

    for (int i = 0; i < n; ) {
        char c = text[i];
        int j = i;
        while (j < n && text[j] == c) ++j;
        runChars.push_back(c);
        runLengths.push_back(j - i);
        i = j;
    }

    int answer = 0;
    int runsCount = static_cast<int>(runChars.size());

    for (int i = 0; i < runsCount; ++i) {
        int idx = runChars[i] - 'a';
        int len = runLengths[i];
        answer = std::max(answer, std::min(len + 1, total[idx]));
    }

    for (int i = 0; i + 2 < runsCount; ++i) {
        if (runChars[i] == runChars[i + 2] && runLengths[i + 1] == 1) {
            int idx = runChars[i] - 'a';
            int combined = runLengths[i] + runLengths[i + 2];
            answer = std::max(answer, std::min(combined + 1, total[idx]));
        }
    }

    return answer;
}

