bool hasBorder(const std::vector<std::vector<int>>& grid, int i, int j, int size) {
    int endCol = j + size - 1;
    int endRow = i + size - 1;
    for (int col = j; col <= endCol; ++col) {
        if (grid[i][col] != 1) return false;
    }
    for (int col = j; col <= endCol; ++col) {
        if (grid[endRow][col] != 1) return false;
    }
    for (int row = i + 1; row < endRow; ++row) {
        if (grid[row][j] != 1) return false;
    }
    for (int row = i + 1; row < endRow; ++row) {
        if (grid[row][endCol] != 1) return false;
    }
    return true;
}

int largest1BorderedSquare(const std::vector<std::vector<int>>& grid) {
    int rows = static_cast<int>(grid.size());
    if (rows == 0) return 0;
    int cols = static_cast<int>(grid[0].size());
    int maxSize = std::min(rows, cols);
    int result = 0;
    for (int size = 1; size <= maxSize; ++size) {
        for (int i = 0; i <= rows - size; ++i) {
            for (int j = 0; j <= cols - size; ++j) {
                if (hasBorder(grid, i, j, size)) {
                    result = std::max(result, size * size);
                }
            }
        }
    }
    return result;
}

