std::vector<int> numSmallerByFrequency(const std::vector<std::string>& queries, const std::vector<std::string>& words) {
    std::vector<int> wordFreqs;
    wordFreqs.reserve(words.size());
    for (const auto& word : words) {
        char minChar = *std::min_element(word.begin(), word.end());
        int freq = static_cast<int>(std::count(word.begin(), word.end(), minChar));
        wordFreqs.push_back(freq);
    }
    std::sort(wordFreqs.begin(), wordFreqs.end());
    std::vector<int> result;
    result.reserve(queries.size());
    for (const auto& query : queries) {
        char minChar = *std::min_element(query.begin(), query.end());
        int queryFreq = static_cast<int>(std::count(query.begin(), query.end(), minChar));
        size_t left = 0, right = wordFreqs.size();
        while (left < right) {
            size_t mid = (left + right) / 2;
            if (wordFreqs[mid] > queryFreq) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        result.push_back(static_cast<int>(wordFreqs.size() - left));
    }
    return result;
}

