    ListNode(int x) : val(x), next(nullptr) {}
    ListNode(int x, ListNode* next) : val(x), next(next) {}
};

ListNode* removeZeroSumSublists(ListNode* head) {
    ListNode dummy(0, head);
    long long prefix = 0;
    std::unordered_map<long long, ListNode*> seen;
    seen[0] = &dummy;
    while (head) {
        prefix += head->val;
        auto it = seen.find(prefix);
        if (it != seen.end()) {
            ListNode* node = it->second;
            ListNode* tmp = node->next;
            long long tmpPrefix = prefix + tmp->val;
            while (tmp != head) {
                seen.erase(tmpPrefix);
                tmp = tmp->next;
                tmpPrefix += tmp->val;
            }
            node->next = head->next;
        } else {
            seen[prefix] = head;
        }
        head = head->next;
    }
    return dummy.next;
}

