long long numPrimeArrangements(int n) {
    const long long MOD = 1000000007LL;
    std::vector<bool> isPrime(n + 1, true);
    if (n >= 0) isPrime[0] = false;
    if (n >= 1) isPrime[1] = false;
    for (int i = 2; i * i <= n; ++i) {
        if (isPrime[i]) {
            for (int j = i * i; j <= n; j += i) {
                isPrime[j] = false;
            }
        }
    }
    int primeCount = 0, nonPrimeCount = 0;
    for (int i = 1; i <= n; ++i) {
        if (isPrime[i]) ++primeCount;
        else ++nonPrimeCount;
    }
    long long result = 1;
    for (int i = 2; i <= primeCount; ++i) {
        result = (result * i) % MOD;
    }
    for (int i = 2; i <= nonPrimeCount; ++i) {
        result = (result * i) % MOD;
    }
    return result;
}

