std::vector<int> findNumOfValidWords(const std::vector<std::string>& words, const std::vector<std::string>& puzzles) {
    std::unordered_map<int, int> wordCount;
    for (const std::string& word : words) {
        int mask = 0;
        for (char ch : word) {
            mask |= 1 << (ch - 'a');
        }
        ++wordCount[mask];
    }

    std::vector<int> result;
    for (const std::string& puzzle : puzzles) {
        int count = 0;
        int mask = 0;
        for (char ch : puzzle) {
            mask |= 1 << (ch - 'a');
        }
        int firstLetterMask = 1 << (puzzle[0] - 'a');
        for (const auto& kv : wordCount) {
            int wordMask = kv.first;
            if ((wordMask & mask) == wordMask && (wordMask & firstLetterMask) != 0) {
                count += kv.second;
            }
        }
        result.push_back(count);
    }
    return result;
}

