std::string reverseParentheses(const std::string& s) {
    std::vector<std::string> stack;
    for (char ch : s) {
        if (ch == '(') {
            stack.emplace_back("");
        } else if (ch == ')') {
            std::string temp = stack.back();
            stack.pop_back();
            std::reverse(temp.begin(), temp.end());
            if (!stack.empty()) {
                stack.back() += temp;
            } else {
                stack.emplace_back(temp);
            }
        } else {
            if (stack.empty()) {
                stack.emplace_back(1, ch);
            } else {
                stack.back() += ch;
            }
        }
    }
    return stack.empty() ? std::string() : stack[0];
}

