long long maximumSum(const std::vector<int>& arr) {
    size_t n = arr.size();
    std::vector<long long> forward(n, 0);
    std::vector<long long> backward(n, 0);
    long long maxSum = arr[0];
    forward[0] = arr[0];
    for (size_t i = 1; i < n; ++i) {
        forward[i] = std::max<long long>(arr[i], forward[i - 1] + arr[i]);
        maxSum = std::max(maxSum, forward[i]);
    }
    backward[n - 1] = arr[n - 1];
    for (size_t i = n - 2; i < n; --i) {
        backward[i] = std::max<long long>(arr[i], backward[i + 1] + arr[i]);
        maxSum = std::max(maxSum, backward[i]);
        if (i == 0) break;
    }
    for (size_t i = 1; i + 1 < n; ++i) {
        maxSum = std::max(maxSum, forward[i - 1] + backward[i + 1]);
    }
    return maxSum;
}

#include <bits/stdc++.h>

long long kConcatenationMaxSum(const std::vector<long long>& arr, long long k) {
    const long long MOD = 1000000007LL;
    long long totalSum = 0;
    for (long long v : arr) totalSum += v;

    long long maxSub = 0, cur = 0;
    for (long long v : arr) {
        cur = std::max(0LL, cur + v);
        maxSub = std::max(maxSub, cur);
    }

    long long maxPrefix = 0, pref = 0;
    for (long long v : arr) {
        pref += v;
        maxPrefix = std::max(maxPrefix, pref);
    }

    long long maxSuffix = 0, suff = 0;
    for (auto it = arr.rbegin(); it != arr.rend(); ++it) {
        suff += *it;
        maxSuffix = std::max(maxSuffix, suff);
    }

    if (k == 1) {
        return maxSub % MOD;
    }

    long long combined = maxSuffix + maxPrefix;
    if (totalSum > 0) {
        combined += (k - 2) * totalSum;
    }
    long long ans = std::max(maxSub, combined);
    return ans % MOD;
}

