int makeArrayIncreasing(const std::vector<int>& arr1, const std::vector<int>& arr2) {
    std::vector<int> sortedArr2 = arr2;
    std::sort(sortedArr2.begin(), sortedArr2.end());
    sortedArr2.erase(std::unique(sortedArr2.begin(), sortedArr2.end()), sortedArr2.end());

    const int INF = std::numeric_limits<int>::max() / 2;
    std::unordered_map<int, int> dp;
    dp.reserve(arr1.size() * 2);
    dp[arr1[0]] = 0;
    for (int v : sortedArr2) {
        auto it = dp.find(v);
        if (it == dp.end() || 1 < it->second) {
            dp[v] = 1;
        }
    }

    for (size_t i = 1; i < arr1.size(); ++i) {
        std::unordered_map<int, int> newDp;
        newDp.reserve(dp.size() * (sortedArr2.size() + 1));
        for (const auto& kv : dp) {
            int prev = kv.first;
            int ops = kv.second;
            if (arr1[i] > prev) {
                auto it = newDp.find(arr1[i]);
                if (it == newDp.end() || ops < it->second) {
                    newDp[arr1[i]] = ops;
                }
            }
            auto it = std::upper_bound(sortedArr2.begin(), sortedArr2.end(), prev);
            for (; it != sortedArr2.end(); ++it) {
                int v = *it;
                int newOps = ops + 1;
                auto it2 = newDp.find(v);
                if (it2 == newDp.end() || newOps < it2->second) {
                    newDp[v] = newOps;
                }
            }
        }
        dp.swap(newDp);
        if (dp.empty()) break;
    }

    int ans = INF;
    for (const auto& kv : dp) {
        ans = std::min(ans, kv.second);
    }
    return ans >= INF ? -1 : ans;
}

