    int rank = 0;
    std::vector<std::vector<int>> result;

    std::function<void(int)> dfs = [&](int u) {
        disc[u] = rank;
        low[u] = rank;
        ++rank;
        visited[u] = true;

        for (size_t i = 0; i < graph[u].size(); ++i) {
            int v = graph[u][i];
            if (!visited[v]) {
                parent[v] = u;
                dfs(v);
                low[u] = std::min(low[u], low[v]);
                if (low[v] > disc[u]) {
                    result.push_back({u, v});
                }
            } else if (v != parent[u]) {
                low[u] = std::min(low[u], disc[v]);
            }
        }
    };

    dfs(0);
    return result;
}

