long long gcd_ll(long long x, long long y) {
    return y == 0 ? x : gcd_ll(y, x % y);
}

long long lcm_ll(long long x, long long y) {
    return x / gcd_ll(x, y) * y;
}

long long nthUglyNumber(long long n, long long a, long long b, long long c) {
    long long lcm_ab = lcm_ll(a, b);
    long long lcm_bc = lcm_ll(b, c);
    long long lcm_ac = lcm_ll(a, c);
    long long lcm_abc = lcm_ll(lcm_ab, c);

    long long left = 1;
    long long right = 2000000000LL;
    while (left < right) {
        long long mid = left + (right - left) / 2;
        long long count = mid / a + mid / b + mid / c;
        count -= mid / lcm_ab + mid / lcm_bc + mid / lcm_ac;
        count += mid / lcm_abc;
        if (count < n) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left;
}

