std::string smallestStringWithSwaps(const std::string& s, const std::vector<std::vector<int>>& pairs) {
    int n = static_cast<int>(s.size());
    std::vector<int> parent(n);
    std::iota(parent.begin(), parent.end(), 0);
    std::vector<int> rank(n, 0);

    std::function<int(int)> find = [&](int x) -> int {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    };

    auto union_sets = [&](int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX == rootY) return;
        if (rank[rootX] < rank[rootY]) parent[rootX] = rootY;
        else if (rank[rootX] > rank[rootY]) parent[rootY] = rootX;
        else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    };

    for (const auto& p : pairs) {
        union_sets(p[0], p[1]);
    }

    std::unordered_map<int, std::vector<char>> tempMap;
    for (int i = 0; i < n; ++i) {
        int root = find(i);
        tempMap[root].push_back(s[i]);
    }

    std::unordered_map<int, std::deque<char>> groups;
    for (auto& kv : tempMap) {
        std::vector<char>& vec = kv.second;
        std::sort(vec.begin(), vec.end());
        groups[kv.first] = std::deque<char>(vec.begin(), vec.end());
    }

    std::string result(n, ' ');
    for (int i = 0; i < n; ++i) {
        int root = find(i);
        char c = groups[root].front();
        groups[root].pop_front();
        result[i] = c;
    }

    return result;
}

