struct Node {
    int val;
    std::vector<Node*> forward;
    Node(int v, int level) : val(v), forward(level, nullptr) {}
};
class Skiplist {
public:
    int levels = 16;
    double p = 0.5;
    Node* head;
    Skiplist() { head = new Node(0, levels); }
    int randomLevel() {
        int lvl = 1;
        while ((double)rand()/RAND_MAX < p && lvl < levels) lvl++;
        return lvl;
    }
    bool search(int target) {
        Node* node = head;
        for (int i = levels-1; i >= 0; i--) {
            while (node->forward[i] && node->forward[i]->val < target) node = node->forward[i];
        }
        node = node->forward[0];
        return node && node->val == target;
    }
    void add(int num) {
        std::vector<Node*> update(levels, nullptr);
        Node* node = head;
        for (int i = levels-1; i >= 0; i--) {
            while (node->forward[i] && node->forward[i]->val < num) node = node->forward[i];
            update[i] = node;
        }
        int lvl = randomLevel();
        Node* newNode = new Node(num, lvl);
        for (int i = 0; i < lvl; i++) {
            newNode->forward[i] = update[i]->forward[i];
            update[i]->forward[i] = newNode;
        }
    }
    bool erase(int num) {
        std::vector<Node*> update(levels, nullptr);
        Node* node = head;
        for (int i = levels-1; i >= 0; i--) {
            while (node->forward[i] && node->forward[i]->val < num) node = node->forward[i];
            update[i] = node;
        }
        node = node->forward[0];
        if (!node || node->val != num) return false;
        for (int i = 0; i < levels; i++) {
            if (update[i]->forward[i] != node) break;
            update[i]->forward[i] = node->forward[i];
        }
        return true;
    }
};

