std::vector<int> sortItems(int n, int m, const std::vector<int>& group, const std::vector<std::vector<int>>& beforeItems) {
    std::vector<int> grp = group;
    for (int i = 0; i < n; ++i) {
        if (grp[i] == -1) {
            grp[i] = m++;
        }
    }

    std::vector<std::vector<int>> itemGraph(n);
    std::vector<int> itemIndeg(n, 0);
    std::vector<std::vector<int>> groupGraph(m);
    std::vector<int> groupIndeg(m, 0);
    std::unordered_set<long long> edgeSet;

    for (int i = 0; i < n; ++i) {
        for (int pre : beforeItems[i]) {
            itemGraph[pre].push_back(i);
            ++itemIndeg[i];
            int gPre = grp[pre];
            int gCur = grp[i];
            if (gPre != gCur) {
                long long key = static_cast<long long>(gPre) * m + gCur;
                if (edgeSet.insert(key).second) {
                    groupGraph[gPre].push_back(gCur);
                    ++groupIndeg[gCur];
                }
            }
        }
    }

    std::deque<int> dq;
    for (int i = 0; i < m; ++i) {
        if (groupIndeg[i] == 0) {
            dq.push_back(i);
        }
    }
    std::vector<int> groupOrder;
    while (!dq.empty()) {
        int cur = dq.front();
        dq.pop_front();
        groupOrder.push_back(cur);
        for (int nxt : groupGraph[cur]) {
            if (--groupIndeg[nxt] == 0) {
                dq.push_front(nxt);
            }
        }
    }
    if ((int)groupOrder.size() != m) {
        return {};
    }

    std::queue<int> qi;
    for (int i = 0; i < n; ++i) {
        if (itemIndeg[i] == 0) {
            qi.push(i);
        }
    }
    std::vector<int> itemOrder;
    while (!qi.empty()) {
        int cur = qi.front();
        qi.pop();
        itemOrder.push_back(cur);
        for (int nxt : itemGraph[cur]) {
            if (--itemIndeg[nxt] == 0) {
                qi.push(nxt);
            }
        }
    }
    if ((int)itemOrder.size() != n) {
        return {};
    }

    std::vector<std::vector<int>> itemsInGroup(m);
    for (int item : itemOrder) {
        itemsInGroup[grp[item]].push_back(item);
    }

    std::vector<int> result;
    for (int g : groupOrder) {
        result.insert(result.end(), itemsInGroup[g].begin(), itemsInGroup[g].end());
    }
    return result;
}

