int minimumMoves(std::vector<std::vector<int>>& grid) {
    int n = static_cast<int>(grid.size());
    std::vector<std::vector<std::vector<bool>>> visited(n,
        std::vector<std::vector<bool>>(n, std::vector<bool>(2, false)));
    std::queue<std::tuple<int, int, int, int>> q; // x, y, dir, steps
    q.emplace(0, 0, 0, 0);
    visited[0][0][0] = true;
    while (!q.empty()) {
        int x, y, dir, steps;
        std::tie(x, y, dir, steps) = q.front();
        q.pop();
        if (x == n - 1 && y == n - 2 && dir == 0) return steps;
        if (dir == 0) { // horizontal
            if (y + 2 < n && grid[x][y + 2] == 0 && !visited[x][y + 1][0]) {
                visited[x][y + 1][0] = true;
                q.emplace(x, y + 1, 0, steps + 1);
            }
            if (x + 1 < n && grid[x + 1][y] == 0 && grid[x + 1][y + 1] == 0 && !visited[x + 1][y][0]) {
                visited[x + 1][y][0] = true;
                q.emplace(x + 1, y, 0, steps + 1);
            }
            if (x + 1 < n && grid[x + 1][y] == 0 && grid[x + 1][y + 1] == 0 && !visited[x][y][1]) {
                visited[x][y][1] = true;
                q.emplace(x, y, 1, steps + 1);
            }
        } else { // vertical
            if (x + 2 < n && grid[x + 2][y] == 0 && !visited[x + 1][y][1]) {
                visited[x + 1][y][1] = true;
                q.emplace(x + 1, y, 1, steps + 1);
            }
            if (y + 1 < n && grid[x][y + 1] == 0 && grid[x + 1][y + 1] == 0 && !visited[x][y + 1][1]) {
                visited[x][y + 1][1] = true;
                q.emplace(x, y + 1, 1, steps + 1);
            }
            if (y + 1 < n && grid[x][y + 1] == 0 && grid[x + 1][y + 1] == 0 && !visited[x][y][0]) {
                visited[x][y][0] = true;
                q.emplace(x, y, 0, steps + 1);
            }
        }
    }
    return -1;
}

