int countVowelPermutation(int n) {
    const long long MOD = 1000000007LL;
    std::vector<long long> dp(5, 1);
    for (int i = 2; i <= n; ++i) {
        std::vector<long long> temp(5, 0);
        for (int j = 0; j < 5; ++j) {
            if (j == 0) {
                temp[1] = (temp[1] + dp[j]) % MOD;
            } else if (j == 1) {
                temp[0] = (temp[0] + dp[j]) % MOD;
                temp[2] = (temp[2] + dp[j]) % MOD;
            } else if (j == 2) {
                temp[0] = (temp[0] + dp[j]) % MOD;
                temp[1] = (temp[1] + dp[j]) % MOD;
                temp[3] = (temp[3] + dp[j]) % MOD;
                temp[4] = (temp[4] + dp[j]) % MOD;
            } else if (j == 3) {
                temp[2] = (temp[2] + dp[j]) % MOD;
                temp[4] = (temp[4] + dp[j]) % MOD;
            } else if (j == 4) {
                temp[0] = (temp[0] + dp[j]) % MOD;
            }
        }
        dp = std::move(temp);
    }
    long long total = 0;
    for (int i = 0; i < 5; ++i) {
        total = (total + dp[i]) % MOD;
    }
    return static_cast<int>(total);
}

