int getMaximumGold(const std::vector<std::vector<int>>& grid) {
    if (grid.empty() || grid[0].empty()) return 0;
    const std::vector<std::pair<int, int>> directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    int maxGold = 0;
    std::function<void(int, int, int, std::unordered_set<std::string>&)> backtrack =
        [&](int row, int col, int currentGold, std::unordered_set<std::string>& visited) {
            maxGold = std::max(maxGold, currentGold);
            for (int i = 0; i < 4; ++i) {
                int newRow = row + directions[i].first;
                int newCol = col + directions[i].second;
                if (newRow >= 0 && newRow < static_cast<int>(grid.size()) &&
                    newCol >= 0 && newCol < static_cast<int>(grid[0].size()) &&
                    grid[newRow][newCol] != 0) {
                    std::string key = std::to_string(newRow) + "," + std::to_string(newCol);
                    if (visited.find(key) == visited.end()) {
                        visited.insert(key);
                        backtrack(newRow, newCol, currentGold + grid[newRow][newCol], visited);
                        visited.erase(key);
                    }
                }
            }
        };
    for (int i = 0; i < static_cast<int>(grid.size()); ++i) {
        for (int j = 0; j < static_cast<int>(grid[0].size()); ++j) {
            if (grid[i][j] != 0) {
                std::unordered_set<std::string> visited;
                visited.insert(std::to_string(i) + "," + std::to_string(j));
                backtrack(i, j, grid[i][j], visited);
            }
        }
    }
    return maxGold;
}

