        for (size_t i = 2; i < coordinates.size(); ++i) {
            int xi = coordinates[i][0];
            int yi = coordinates[i][1];
            if (static_cast<double>(yi - y0) / static_cast<double>(xi - x0) != slope) return false;
        }
        return true;
    }
}

