int maxLength(const std::vector<std::string>& arr) {
    int maxLengthResult = 0;
    auto hasUniqueChars = [&](const std::string& str) -> bool {
        std::unordered_set<char> charSet;
        for (char ch : str) {
            if (charSet.find(ch) != charSet.end()) return false;
            charSet.insert(ch);
        }
        return true;
    };
    std::function<void(int, const std::string&)> backtrack = [&](int index, const std::string& currentString) {
        maxLengthResult = std::max(maxLengthResult, static_cast<int>(currentString.size()));
        for (int i = index; i < static_cast<int>(arr.size()); ++i) {
            if (hasUniqueChars(currentString + arr[i])) {
                backtrack(i + 1, currentString + arr[i]);
            }
        }
    };
    backtrack(0, "");
    return maxLengthResult;
}

