int balancedString(const std::string& s) {
    int n = static_cast<int>(s.size());
    int target = n / 4;
    int total[4] = {0, 0, 0, 0};
    auto idx = [](char c) -> int {
        if (c == 'Q') return 0;
        if (c == 'W') return 1;
        if (c == 'E') return 2;
        return 3; // 'R'
    };
    for (char c : s) total[idx(c)]++;

    int need[4];
    bool allZero = true;
    for (int i = 0; i < 4; ++i) {
        need[i] = std::max(0, total[i] - target);
        if (need[i] != 0) allZero = false;
    }
    if (allZero) return 0;

    int window[4] = {0, 0, 0, 0};
    int left = 0;
    int ans = n;
    for (int right = 0; right < n; ++right) {
        window[idx(s[right])]++;
        while (true) {
            bool ok = true;
            for (int i = 0; i < 4; ++i) {
                if (window[i] < need[i]) { ok = false; break; }
            }
            if (!ok) break;
            ans = std::min(ans, right - left + 1);
            window[idx(s[left])]--;
            ++left;
        }
    }
    return ans;
}

