long long maxSumDivisibleByThree(const std::vector<int>& nums) {
    const long long NEG_INF = LLONG_MIN / 4;
    std::vector<long long> dp(3, NEG_INF);
    dp[0] = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        long long cur = nums[i];
        std::vector<long long> next = dp;
        for (int r = 0; r < 3; ++r) {
            if (dp[r] != NEG_INF) {
                int newR = (r + cur) % 3;
                if (newR < 0) newR += 3;
                next[newR] = std::max(next[newR], dp[r] + cur);
            }
        }
        dp = next;
    }
    return dp[0];
}

