std::vector<std::vector<std::string>> suggestedProducts(std::vector<std::string> products, const std::string& searchWord) {
    std::sort(products.begin(), products.end());
    std::vector<std::vector<std::string>> result;
    size_t n = products.size();

    for (size_t i = 1; i <= searchWord.size(); ++i) {
        std::string prefix = searchWord.substr(0, i);
        size_t left = 0, right = n;
        while (left < right) {
            size_t mid = (left + right) >> 1;
            if (products[mid] < prefix) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        std::vector<std::string> suggestions;
        for (size_t j = left; j < std::min(left + 3, n); ++j) {
            if (products[j].compare(0, prefix.size(), prefix) == 0) {
                suggestions.push_back(products[j]);
            } else {
                break;
            }
        }
        result.push_back(std::move(suggestions));
    }
    return result;
}

