#include <bits/stdc++.h>
int numWays(int steps, int arrLen) {
    const int MOD = 1000000007;
    int limit = std::min(arrLen - 1, steps);
    std::vector<int> dp(limit + 1, 0), ndp(limit + 1, 0);
    dp[0] = 1;
    for (int s = 1; s <= steps; ++s) {
        std::fill(ndp.begin(), ndp.end(), 0);
        for (int i = 0; i <= limit; ++i) {
            long long ways = dp[i];
            if (i > 0) ways += dp[i - 1];
            if (i + 1 <= limit) ways += dp[i + 1];
            ndp[i] = static_cast<int>(ways % MOD);
        }
        dp.swap(ndp);
    }
    return dp[0];
}

#include <bits/stdc++.h>
int minPushBox(std::vector<std::string>& grid) {
    int m = grid.size();
    int n = grid[0].size();
    int sx = -1, sy = -1, bx = -1, by = -1, tx = -1, ty = -1;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 'S') { sx = i; sy = j; }
            else if (grid[i][j] == 'B') { bx = i; by = j; }
            else if (grid[i][j] == 'T') { tx = i; ty = j; }
        }
    }
    if (bx == tx && by == ty) return 0;
    const int dx[4] = { -1, 1, 0, 0 };
    const int dy[4] = { 0, 0, -1, 1 };
    std::queue<std::tuple<int, int, int, int, int>> q;
    q.emplace(bx, by, sx, sy, 0);
    std::unordered_set<std::uint64_t> visited;
    visited.reserve(200000);
    visited.insert(((std::uint64_t)bx << 24) | ((std::uint64_t)by << 16) | ((std::uint64_t)sx << 8) | (std::uint64_t)sy);
    while (!q.empty()) {
        auto cur = q.front();
        q.pop();
        int cbx = std::get<0>(cur);
        int cby = std::get<1>(cur);
        int cpx = std::get<2>(cur);
        int cpy = std::get<3>(cur);
        int pushes = std::get<4>(cur);
        if (cbx == tx && cby == ty) return pushes;
        bool seen[20][20];
        std::memset(seen, 0, sizeof(seen));
        std::queue<std::pair<int, int>> qq;
        qq.emplace(cpx, cpy);
        seen[cpx][cpy] = true;
        while (!qq.empty()) {
            std::pair<int, int> p = qq.front();
            qq.pop();
            int x = p.first;
            int y = p.second;
            for (int d = 0; d < 4; ++d) {
                int nx = x + dx[d];
                int ny = y + dy[d];
                if (nx < 0 || nx >= m || ny < 0 || ny >= n) continue;
                if (seen[nx][ny]) continue;
                if (grid[nx][ny] == '#') continue;
                if (nx == cbx && ny == cby) continue;
                seen[nx][ny] = true;
                qq.emplace(nx, ny);
            }
        }
        for (int d = 0; d < 4; ++d) {
            int nbx = cbx + dx[d];
            int nby = cby + dy[d];
            int needPx = cbx - dx[d];
            int needPy = cby - dy[d];
            if (nbx < 0 || nbx >= m || nby < 0 || nby >= n) continue;
            if (grid[nbx][nby] == '#') continue;
            if (needPx < 0 || needPx >= m || needPy < 0 || needPy >= n) continue;
            if (grid[needPx][needPy] == '#') continue;
            if (!seen[needPx][needPy]) continue;
            std::uint64_t code = ((std::uint64_t)nbx << 24) | ((std::uint64_t)nby << 16) | ((std::uint64_t)cbx << 8) | (std::uint64_t)cby;
            if (visited.find(code) != visited.end()) continue;
            visited.insert(code);
            q.emplace(nbx, nby, cbx, cby, pushes + 1);
        }
    }
    return -1;
}

