std::string tictactoe(const std::vector<std::vector<int>>& moves) {
    int rowsA[3] = {0, 0, 0};
    int colsA[3] = {0, 0, 0};
    int rowsB[3] = {0, 0, 0};
    int colsB[3] = {0, 0, 0};
    int diagA = 0, antiA = 0;
    int diagB = 0, antiB = 0;

    for (size_t i = 0; i < moves.size(); ++i) {
        int r = moves[i][0];
        int c = moves[i][1];
        bool isA = (i % 2 == 0);
        int* rows = isA ? rowsA : rowsB;
        int* cols = isA ? colsA : colsB;
        int* diag = isA ? &diagA : &diagB;
        int* anti = isA ? &antiA : &antiB;

        rows[r]++;
        cols[c]++;
        if (r == c) (*diag)++;
        if (r + c == 2) (*anti)++;

        if (rows[r] == 3 || cols[c] == 3 || *diag == 3 || *anti == 3) {
            return isA ? "A" : "B";
        }
    }

    return moves.size() == 9 ? "Draw" : "Pending";
}

