    size_t cols = matrix[0].size();
    std::vector<int> dp(cols, 0);
    long long total = 0;
    int prevDiag = 0;
    for (size_t i = 0; i < rows; ++i) {
        prevDiag = 0;
        for (size_t j = 0; j < cols; ++j) {
            int temp = dp[j];
            if (matrix[i][j] == 1) {
                if (i == 0 || j == 0) {
                    dp[j] = 1;
                } else {
                    int left = dp[j - 1];
                    dp[j] = std::min({dp[j], left, prevDiag}) + 1;
                }
                total += dp[j];
            } else {
                dp[j] = 0;
            }
            prevDiag = temp;
        }
    }
    return total;
}

