int palindromePartition(const std::string& s, int k) {
    int n = static_cast<int>(s.size());
    const int INF = 1e9;
    std::vector<std::vector<int>> cost(n, std::vector<int>(n, 0));
    for (int len = 2; len <= n; ++len) {
        for (int i = 0; i + len - 1 < n; ++i) {
            int j = i + len - 1;
            if (len == 2) {
                cost[i][j] = (s[i] == s[j]) ? 0 : 1;
            } else {
                cost[i][j] = cost[i + 1][j - 1] + ((s[i] == s[j]) ? 0 : 1);
            }
        }
    }
    std::vector<int> prev(n + 1, INF), cur(n + 1, INF);
    prev[0] = 0;
    for (int p = 1; p <= k; ++p) {
        std::fill(cur.begin(), cur.end(), INF);
        for (int i = 1; i <= n; ++i) {
            int best = INF;
            for (int j = 0; j < i; ++j) {
                if (prev[j] == INF) continue;
                int cand = prev[j] + cost[j][i - 1];
                if (cand < best) best = cand;
            }
            cur[i] = best;
        }
        prev.swap(cur);
    }
    return prev[n];
}

