int smallestDivisor(const std::vector<int>& nums, int threshold) {
    int low = 1;
    int high = *std::max_element(nums.begin(), nums.end());
    int answer = high;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        long long sum = 0;
        for (int num : nums) {
            sum += (num + mid - 1) / mid;
            if (sum > threshold) break;
        }
        if (sum <= threshold) {
            answer = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return answer;
}

