int minFallingPathSum(const std::vector<std::vector<int>>& grid) {
    std::size_t n = grid.size();
    if (n == 0) return 0;
    std::vector<long long> prev(grid[0].begin(), grid[0].end());

    long long min1 = std::numeric_limits<long long>::max();
    long long min2 = std::numeric_limits<long long>::max();
    int idx1 = -1;
    for (std::size_t j = 0; j < n; ++j) {
        long long v = prev[j];
        if (v < min1) {
            min2 = min1;
            min1 = v;
            idx1 = static_cast<int>(j);
        } else if (v < min2) {
            min2 = v;
        }
    }

    for (std::size_t i = 1; i < n; ++i) {
        std::vector<long long> cur(n);
        long long newMin1 = std::numeric_limits<long long>::max();
        long long newMin2 = std::numeric_limits<long long>::max();
        int newIdx1 = -1;

        for (std::size_t j = 0; j < n; ++j) {
            long long bestPrev = (static_cast<int>(j) == idx1) ? min2 : min1;
            cur[j] = static_cast<long long>(grid[i][j]) + bestPrev;

            long long val = cur[j];
            if (val < newMin1) {
                newMin2 = newMin1;
                newMin1 = val;
                newIdx1 = static_cast<int>(j);
            } else if (val < newMin2) {
                newMin2 = val;
            }
        }
        prev.swap(cur);
        min1 = newMin1;
        min2 = newMin2;
        idx1 = newIdx1;
    }
    return static_cast<int>(min1);
}

#include <bits/stdc++.h>
#include <vector>
#include <queue>
#include <unordered_set>
#include <cstdint>

int minFlips(const std::vector<std::vector<int>>& mat) {
    std::size_t m = mat.size();
    std::size_t n = mat[0].size();
    std::size_t total = m * n;

    uint32_t startMask = 0;
    for (std::size_t r = 0; r < m; ++r) {
        for (std::size_t c = 0; c < n; ++c) {
            if (mat[r][c] == 1) {
                startMask |= static_cast<uint32_t>(1) << (r * n + c);
            }
        }
    }
    if (startMask == 0) return 0;

    std::vector<uint32_t> flipMask(total, 0);
    const std::pair<int, int> dirs[5] = {{0,0},{1,0},{-1,0},{0,1},{0,-1}};
    for (std::size_t r = 0; r < m; ++r) {
        for (std::size_t c = 0; c < n; ++c) {
            uint32_t mask = 0;
            for (const auto& d : dirs) {
                int nr = static_cast<int>(r) + d.first;
                int nc = static_cast<int>(c) + d.second;
                if (nr >= 0 && nr < static_cast<int>(m) && nc >= 0 && nc < static_cast<int>(n)) {
                    mask |= static_cast<uint32_t>(1) << (nr * n + nc);
                }
            }
            flipMask[r * n + c] = mask;
        }
    }

    std::unordered_set<uint32_t> visited;
    std::queue<std::pair<uint32_t, int>> q;
    visited.insert(startMask);
    q.emplace(startMask, 0);

    while (!q.empty()) {
        uint32_t curMask = q.front().first;
        int steps = q.front().second;
        q.pop();
        for (std::size_t i = 0; i < total; ++i) {
            uint32_t nextMask = curMask ^ flipMask[i];
            if (nextMask == 0) return steps + 1;
            if (visited.insert(nextMask).second) {
                q.emplace(nextMask, steps + 1);
            }
        }
    }
    return -1;
}

