int maxSideLength(const std::vector<std::vector<int>>& mat, int threshold) {
    int m = static_cast<int>(mat.size());
    int n = static_cast<int>(mat[0].size());
    std::vector<std::vector<long long>> pref(m + 1, std::vector<long long>(n + 1, 0));
    for (int i = 0; i < m; ++i) {
        long long rowSum = 0;
        for (int j = 0; j < n; ++j) {
            rowSum += mat[i][j];
            pref[i + 1][j + 1] = pref[i][j + 1] + rowSum;
        }
    }
    auto canFit = [&](int k) -> bool {
        for (int i = k; i <= m; ++i) {
            for (int j = k; j <= n; ++j) {
                long long total = pref[i][j] - pref[i - k][j] - pref[i][j - k] + pref[i - k][j - k];
                if (total <= static_cast<long long>(threshold)) return true;
            }
        }
        return false;
    };
    int lo = 0, hi = std::min(m, n);
    while (lo < hi) {
        int mid = (lo + hi + 1) / 2;
        if (canFit(mid)) lo = mid;
        else hi = mid - 1;
    }
    return lo;
}

