int shortestPath(const std::vector<std::vector<int>>& grid, int k) {
    int rows = static_cast<int>(grid.size());
    int cols = static_cast<int>(grid[0].size());

    if (k >= rows + cols - 2) return rows + cols - 2;
    if (rows == 1 && cols == 1) return 0;

    const int dr[4] = {1, -1, 0, 0};
    const int dc[4] = {0, 0, 1, -1};

    std::vector<std::vector<int>> visited(rows, std::vector<int>(cols, -1));
    std::vector<std::array<int, 4>> queue;
    queue.push_back({0, 0, k, 0});
    visited[0][0] = k;
    std::size_t head = 0;

    while (head < queue.size()) {
        const auto& cur = queue[head++];
        int r = cur[0];
        int c = cur[1];
        int remain = cur[2];
        int steps = cur[3];

        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
            int newRemain = remain - grid[nr][nc];
            if (newRemain < 0) continue;
            if (nr == rows - 1 && nc == cols - 1) return steps + 1;
            if (visited[nr][nc] >= newRemain) continue;
            visited[nr][nc] = newRemain;
            queue.push_back({nr, nc, newRemain, steps + 1});
        }
    }
    return -1;
}

