bool divideArray(std::vector<int> nums, int k) {
    if (nums.size() % k != 0) return false;
    std::sort(nums.begin(), nums.end());
    std::unordered_map<int, int> freq;
    for (int v : nums) {
        ++freq[v];
    }
    for (int v : nums) {
        int cnt = freq[v];
        if (cnt > 0) {
            for (int i = 0; i < k; ++i) {
                int cur = v + i;
                int curCnt = freq[cur];
                if (curCnt < cnt) return false;
                freq[cur] = curCnt - cnt;
            }
        }
    }
    return true;
}

#include <bits/stdc++.h>
#include <string>
#include <vector>
#include <unordered_map>
#include <algorithm>

int maxFreq(const std::string& s, int maxLetters, int minSize, int maxSize) {
    int n = static_cast<int>(s.size());
    std::unordered_map<std::string, int> freq;
    std::vector<int> cnt(26, 0);
    int unique = 0;

    for (int i = 0; i < minSize; ++i) {
        int idx = s[i] - 'a';
        if (cnt[idx] == 0) ++unique;
        ++cnt[idx];
    }
    if (unique <= maxLetters) {
        std::string sub = s.substr(0, minSize);
        ++freq[sub];
    }

    for (int i = minSize; i < n; ++i) {
        int outIdx = s[i - minSize] - 'a';
        --cnt[outIdx];
        if (cnt[outIdx] == 0) --unique;

        int inIdx = s[i] - 'a';
        if (cnt[inIdx] == 0) ++unique;
        ++cnt[inIdx];

        if (unique <= maxLetters) {
            std::string sub = s.substr(i - minSize + 1, minSize);
            ++freq[sub];
        }
    }

    int ans = 0;
    for (const auto& p : freq) {
        if (p.second > ans) ans = p.second;
    }
    return ans;
}

