int findBestValue(std::vector<int>& arr, int target) {
    if (arr.empty()) return 0;
    std::sort(arr.begin(), arr.end());
    int n = static_cast<int>(arr.size());
    std::vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + arr[i];
    int maxVal = *std::max_element(arr.begin(), arr.end());

    auto getSum = [&](int v) -> long long {
        int idx = static_cast<int>(std::upper_bound(arr.begin(), arr.end(), v) - arr.begin());
        return pref[idx] + static_cast<long long>(n - idx) * v;
    };

    int low = 0, high = maxVal;
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (getSum(mid) < target) low = mid + 1;
        else high = mid;
    }

    int bestVal = low;
    long long bestDiff = std::llabs(getSum(bestVal) - static_cast<long long>(target));
    if (low > 0) {
        int cand = low - 1;
        long long diff = std::llabs(getSum(cand) - static_cast<long long>(target));
        if (diff < bestDiff || (diff == bestDiff && cand < bestVal)) {
            bestVal = cand;
            bestDiff = diff;
        }
    }
    return bestVal;
}

