std::vector<int> numberOfPaths(const std::vector<std::string>& board) {
    const int MOD = 1000000007;
    int n = static_cast<int>(board.size());
    int m = static_cast<int>(board[0].size());
    std::vector<std::vector<int>> best(n, std::vector<int>(m, -1));
    std::vector<std::vector<int>> ways(n, std::vector<int>(m, 0));

    best[n - 1][m - 1] = 0;
    ways[n - 1][m - 1] = 1;

    for (int i = n - 1; i >= 0; --i) {
        for (int j = m - 1; j >= 0; --j) {
            if (board[i][j] == 'X') continue;
            if (i == n - 1 && j == m - 1) continue;

            int maxPrev = -1;
            int cnt = 0;

            const int dirs[3][2] = {{1, 0}, {0, 1}, {1, 1}};
            for (int d = 0; d < 3; ++d) {
                int ni = i + dirs[d][0];
                int nj = j + dirs[d][1];
                if (ni >= n || nj >= m) continue;
                if (best[ni][nj] == -1) continue;
                if (best[ni][nj] > maxPrev) {
                    maxPrev = best[ni][nj];
                    cnt = ways[ni][nj];
                } else if (best[ni][nj] == maxPrev) {
                    cnt = (cnt + ways[ni][nj]) % MOD;
                }
            }

            if (maxPrev == -1) continue;

            char cellChar = board[i][j];
            int add = (cellChar >= '0' && cellChar <= '9') ? (cellChar - '0') : 0;
            best[i][j] = maxPrev + add;
            ways[i][j] = cnt % MOD;
        }
    }

    if (best[0][0] == -1) return {0, 0};
    return {best[0][0], ways[0][0]};
}

