int deepestLeavesSum(TreeNode* root) {
    int maxDepth = -1;
    int sumAtMax = 0;
    std::function<void(TreeNode*, int)> dfs = [&](TreeNode* node, int depth) {
        if (!node) return;
        if (!node->left && !node->right) {
            if (depth > maxDepth) {
                maxDepth = depth;
                sumAtMax = node->val;
            } else if (depth == maxDepth) {
                sumAtMax += node->val;
            }
        }
        dfs(node->left, depth + 1);
        dfs(node->right, depth + 1);
    };
    dfs(root, 0);
    return sumAtMax;
}

