int maxCandies(const std::vector<int>& status,
               const std::vector<int>& candies,
               const std::vector<std::vector<int>>& keys,
               const std::vector<std::vector<int>>& containedBoxes,
               const std::vector<int>& initialBoxes) {
    int n = static_cast<int>(status.size());
    std::vector<char> haveBox(n, 0), haveKey(n, 0), opened(n, 0);
    for (int b : initialBoxes) {
        if (b >= 0 && b < n) haveBox[b] = 1;
    }
    std::queue<int> q;
    for (int i = 0; i < n; ++i) {
        if (haveBox[i] && (status[i] == 1 || haveKey[i])) {
            q.push(i);
        }
    }
    long long total = 0;
    while (!q.empty()) {
        int i = q.front();
        q.pop();
        if (opened[i]) continue;
        opened[i] = 1;
        total += candies[i];
        for (int k : keys[i]) {
            if (k >= 0 && k < n && !haveKey[k]) {
                haveKey[k] = 1;
                if (haveBox[k] && !opened[k] && (status[k] == 1 || haveKey[k])) {
                    q.push(k);
                }
            }
        }
        for (int b : containedBoxes[i]) {
            if (b >= 0 && b < n && !haveBox[b]) {
                haveBox[b] = 1;
                if (!opened[b] && (status[b] == 1 || haveKey[b])) {
                    q.push(b);
                }
            }
        }
    }
    return static_cast<int>(total);
}

