bool isSolvable(std::vector<std::string>& words, std::string result) {
    int n = static_cast<int>(words.size());
    std::vector<std::string> revWords(n);
    for (int i = 0; i < n; ++i) revWords[i] = std::string(words[i].rbegin(), words[i].rend());
    std::string revResult = std::string(result.rbegin(), result.rend());

    int maxLen = static_cast<int>(revResult.size());
    for (const auto& w : revWords) maxLen = std::max(maxLen, static_cast<int>(w.size()));

    std::array<bool, 26> leading{};
    leading.fill(false);
    for (const auto& w : words) if (w.size() > 1) leading[w[0] - 'A'] = true;
    if (result.size() > 1) leading[result[0] - 'A'] = true;

    std::array<int, 26> assign;
    assign.fill(-1);
    bool used[10] = {false};

    std::function<bool(int,int,int)> dfs = [&](int col, int row, int sum) -> bool {
        if (col == maxLen) return sum == 0;
        if (row < n) {
            if (col >= static_cast<int>(revWords[row].size())) return dfs(col, row + 1, sum);
            char ch = revWords[row][col];
            int idx = ch - 'A';
            if (assign[idx] != -1) return dfs(col, row + 1, sum + assign[idx]);
            for (int d = 0; d <= 9; ++d) {
                if (used[d]) continue;
                if (d == 0 && leading[idx]) continue;
                assign[idx] = d;
                used[d] = true;
                if (dfs(col, row + 1, sum + d)) return true;
                assign[idx] = -1;
                used[d] = false;
            }
            return false;
        } else {
            int expected = sum % 10;
            int newCarry = sum / 10;
            if (col >= static_cast<int>(revResult.size())) {
                if (expected != 0) return false;
                return dfs(col + 1, 0, newCarry);
            }
            char ch = revResult[col];
            int idx = ch - 'A';
            if (assign[idx] != -1) {
                if (assign[idx] != expected) return false;
                return dfs(col + 1, 0, newCarry);
            }
            if (used[expected]) return false;
            if (expected == 0 && leading[idx]) return false;
            assign[idx] = expected;
            used[expected] = true;
            if (dfs(col + 1, 0, newCarry)) return true;
            assign[idx] = -1;
            used[expected] = false;
            return false;
        }
    };

    return dfs(0, 0, 0);
}

