std::vector<std::string> getWatchedVideosByFriends(const std::vector<std::vector<std::string>>& watchedVideos, const std::vector<std::vector<int>>& friends, int id, int level) {
    int n = static_cast<int>(friends.size());
    std::vector<bool> visited(n, false);
    std::deque<int> queue;
    visited[id] = true;
    queue.push_back(id);
    int depth = 0;
    while (!queue.empty() && depth < level) {
        size_t size = queue.size();
        for (size_t i = 0; i < size; ++i) {
            int cur = queue.front();
            queue.pop_front();
            for (int nb : friends[cur]) {
                if (!visited[nb]) {
                    visited[nb] = true;
                    queue.push_back(nb);
                }
            }
        }
        ++depth;
    }
    std::unordered_map<std::string, int> freq;
    for (int person : queue) {
        for (const std::string& video : watchedVideos[person]) {
            ++freq[video];
        }
    }
    std::vector<std::pair<std::string, int>> entries(freq.begin(), freq.end());
    std::sort(entries.begin(), entries.end(), [](const std::pair<std::string, int>& a, const std::pair<std::string, int>& b) {
        if (a.second != b.second) return a.second < b.second;
        return a.first < b.first;
    });
    std::vector<std::string> result;
    result.reserve(entries.size());
    for (const auto& p : entries) {
        result.push_back(p.first);
    }
    return result;
}

