int minInsertions(const std::string& s) {
    int n = static_cast<int>(s.size());
    std::string rev(s.rbegin(), s.rend());
    std::vector<uint16_t> prev(n + 1, 0);
    std::vector<uint16_t> curr(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (s[i - 1] == rev[j - 1]) {
                curr[j] = prev[j - 1] + 1;
            } else {
                curr[j] = std::max(prev[j], curr[j - 1]);
            }
        }
        std::swap(prev, curr);
    }
    int lps = prev[n];
    return n - lps;
}

