int distinctEchoSubstrings(const std::string& text) {
    int n = static_cast<int>(text.size());
    using ULL = unsigned long long;
    const ULL base = 1315423911ULL;

    std::vector<ULL> pref(n + 1, 0), powb(n + 1, 1);
    for (int i = 0; i < n; ++i) {
        pref[i + 1] = pref[i] * base + static_cast<unsigned char>(text[i]);
        powb[i + 1] = powb[i] * base;
    }

    auto getHash = [&](int l, int r) -> ULL {
        return pref[r] - pref[l] * powb[r - l];
    };

    std::unordered_set<ULL> seen;
    for (int len = 2; len <= n; len += 2) {
        int half = len >> 1;
        for (int i = 0; i + len <= n; ++i) {
            if (getHash(i, i + half) == getHash(i + half, i + len)) {
                seen.insert(getHash(i, i + len));
            }
        }
    }
    return static_cast<int>(seen.size());
}

