std::vector<std::vector<int>> matrixBlockSum(const std::vector<std::vector<int>>& mat, int k) {
    int m = mat.size();
    int n = mat[0].size();
    std::vector<std::vector<int>> pref(m + 1, std::vector<int>(n + 1, 0));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            pref[i + 1][j + 1] = mat[i][j] + pref[i][j + 1] + pref[i + 1][j] - pref[i][j];
        }
    }
    std::vector<std::vector<int>> answer(m, std::vector<int>(n));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            int top = std::max(0, i - k);
            int bottom = std::min(m - 1, i + k);
            int left = std::max(0, j - k);
            int right = std::min(n - 1, j + k);
            answer[i][j] = pref[bottom + 1][right + 1] - pref[top][right + 1] - pref[bottom + 1][left] + pref[top][left];
        }
    }
    return answer;
}

