int minFlips(int a, int b, int c) {
    int flips = 0;
    uint32_t ua = static_cast<uint32_t>(a);
    uint32_t ub = static_cast<uint32_t>(b);
    uint32_t uc = static_cast<uint32_t>(c);
    for (int i = 0; i < 32; ++i) {
        uint32_t mask = 1u << i;
        uint32_t bitA = (ua & mask) >> i;
        uint32_t bitB = (ub & mask) >> i;
        uint32_t bitC = (uc & mask) >> i;
        if (bitC == 1) {
            if (bitA == 0 && bitB == 0) ++flips;
        } else {
            flips += bitA + bitB;
        }
    }
    return flips;
}

