int minimumDistance(std::string word) {
    constexpr int INF = 1e9;
    constexpr int UNUSED = 26;
    auto dist = [&](int a, int b) -> int {
        if (a == UNUSED || b == UNUSED) return 0;
        int ra = a / 6, ca = a % 6;
        int rb = b / 6, cb = b % 6;
        return std::abs(ra - rb) + std::abs(ca - cb);
    };
    int dp[27][27];
    int ndp[27][27];
    for (int i = 0; i < 27; ++i)
        for (int j = 0; j < 27; ++j)
            dp[i][j] = INF;
    dp[UNUSED][UNUSED] = 0;
    for (char ch : word) {
        int cur = ch - 'A';
        for (int i = 0; i < 27; ++i)
            for (int j = 0; j < 27; ++j)
                ndp[i][j] = INF;
        for (int f1 = 0; f1 <= 26; ++f1) {
            for (int f2 = 0; f2 <= 26; ++f2) {
                int curCost = dp[f1][f2];
                if (curCost == INF) continue;
                int cost1 = curCost + dist(f1, cur);
                if (cost1 < ndp[cur][f2]) ndp[cur][f2] = cost1;
                int cost2 = curCost + dist(f2, cur);
                if (cost2 < ndp[f1][cur]) ndp[f1][cur] = cost2;
            }
        }
        for (int i = 0; i < 27; ++i)
            for (int j = 0; j < 27; ++j)
                dp[i][j] = ndp[i][j];
    }
    int ans = INF;
    for (int f1 = 0; f1 <= 26; ++f1)
        for (int f2 = 0; f2 <= 26; ++f2)
            ans = std::min(ans, dp[f1][f2]);
    return ans;
}

