int makeConnected(int n, const std::vector<std::vector<int>>& connections) {
    if (connections.size() < static_cast<size_t>(n - 1)) return -1;

    std::vector<int> parent(n);
    std::vector<int> rank(n, 0);
    for (int i = 0; i < n; ++i) parent[i] = i;

    auto find = [&](int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    auto unionSet = [&](int a, int b) {
        int rootA = find(a);
        int rootB = find(b);
        if (rootA == rootB) return false;
        if (rank[rootA] < rank[rootB]) parent[rootA] = rootB;
        else if (rank[rootA] > rank[rootB]) parent[rootB] = rootA;
        else {
            parent[rootB] = rootA;
            rank[rootA]++;
        }
        return true;
    };

    int extraEdges = 0;
    for (const auto& edge : connections) {
        int u = edge[0];
        int v = edge[1];
        if (!unionSet(u, v)) ++extraEdges;
    }

    std::unordered_set<int> components;
    for (int i = 0; i < n; ++i) components.insert(find(i));

    int needed = static_cast<int>(components.size()) - 1;
    return extraEdges >= needed ? needed : -1;
}

#include <bits/stdc++.h>
int maximum69Number(int num) {
    int n = num;
    int place = 1;
    int mostSignificantSix = -1;
    while (n > 0) {
        int digit = n % 10;
        if (digit == 6) {
            mostSignificantSix = place;
        }
        n = n / 10;
        place *= 10;
