#include <bits/stdc++.h>

int maxValueAfterReverse(std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    long long base = 0;
    for (int i = 0; i + 1 < n; ++i) {
        base += std::abs(nums[i] - nums[i + 1]);
    }
    long long bestGain = 0;
    // Improve first element
    for (int i = 1; i < n; ++i) {
        long long gain = std::abs(nums[i] - nums[0]) - std::abs(nums[i] - nums[i - 1]);
        if (gain > bestGain) bestGain = gain;
    }
    // Improve last element
    for (int i = 0; i + 1 < n; ++i) {
        long long gain = std::abs(nums[i] - nums[n - 1]) - std::abs(nums[i + 1] - nums[i]);
        if (gain > bestGain) bestGain = gain;
    }
    // General interior case
    int minHigh = INT_MAX;
    int maxLow = INT_MIN;
    for (int i = 0; i + 1 < n; ++i) {
        int a = nums[i];
        int b = nums[i + 1];
        int low = std::min(a, b);
        int high = std::max(a, b);
        if (low > maxLow) maxLow = low;
        if (high < minHigh) minHigh = high;
    }
    long long interiorGain = std::max(0, maxLow - minHigh) * 2LL;
    if (interiorGain > bestGain) bestGain = interiorGain;
    return static_cast<int>(base + bestGain);
}

