int minTaps(int n, const std::vector<int>& ranges) {
    std::vector<int> maxReach(n + 1, 0);
    for (int i = 0; i <= n; ++i) {
        int left = std::max(0, i - ranges[i]);
        int right = std::min(n, i + ranges[i]);
        if (right > maxReach[left]) maxReach[left] = right;
    }

    int taps = 0;
    int curEnd = 0;
    int farthest = 0;

    for (int i = 0; i <= n; ++i) {
        farthest = std::max(farthest, maxReach[i]);
        if (i == curEnd) {
            ++taps;
            curEnd = farthest;
            if (curEnd <= i) return -1;
        }
        if (curEnd >= n) break;
    }
    return curEnd >= n ? taps : -1;
}

