std::vector<std::vector<int>> diagonalSort(std::vector<std::vector<int>> mat) {
    int rows = static_cast<int>(mat.size());
    if (rows == 0) return mat;
    int cols = static_cast<int>(mat[0].size());

    for (int startCol = 0; startCol < cols; ++startCol) {
        int r = 0, c = startCol;
        std::vector<int> diag;
        while (r < rows && c < cols) {
            diag.push_back(mat[r][c]);
            ++r;
            ++c;
        }
        std::sort(diag.begin(), diag.end());
        r = 0;
        c = startCol;
        int idx = 0;
        while (r < rows && c < cols) {
            mat[r][c] = diag[idx++];
            ++r;
            ++c;
        }
    }

    for (int startRow = 1; startRow < rows; ++startRow) {
        int r = startRow, c = 0;
        std::vector<int> diag;
        while (r < rows && c < cols) {
            diag.push_back(mat[r][c]);
            ++r;
            ++c;
        }
        std::sort(diag.begin(), diag.end());
        r = startRow;
        c = 0;
        int idx = 0;
        while (r < rows && c < cols) {
            mat[r][c] = diag[idx++];
            ++r;
            ++c;
        }
    }

    return mat;
}

