int findTheCity(int n, const std::vector<std::vector<int>>& edges, int distanceThreshold) {
    const long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<std::vector<long long>> dist(n, std::vector<long long>(n, INF));
    for (int i = 0; i < n; ++i) dist[i][i] = 0;
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        int w = e[2];
        dist[u][v] = w;
        dist[v][u] = w;
    }
    for (int k = 0; k < n; ++k) {
        for (int i = 0; i < n; ++i) {
            long long dik = dist[i][k];
            if (dik == INF) continue;
            for (int j = 0; j < n; ++j) {
                long long newDist = dik + dist[k][j];
                if (newDist < dist[i][j]) dist[i][j] = newDist;
            }
        }
    }
    int bestCity = -1;
    int bestCount = std::numeric_limits<int>::max();
    for (int i = 0; i < n; ++i) {
        int cnt = 0;
        for (int j = 0; j < n; ++j) {
            if (i != j && dist[i][j] <= distanceThreshold) ++cnt;
        }
        if (cnt < bestCount || (cnt == bestCount && i > bestCity)) {
            bestCount = cnt;
            bestCity = i;
        }
    }
    return bestCity;
}

