int minDifficulty(const std::vector<int>& jobDifficulty, int d) {
    int n = jobDifficulty.size();
    if (d > n) return -1;
    const long long INF = LLONG_MAX / 4;
    std::vector<long long> prev(n + 1, INF), cur(n + 1, INF);
    prev[0] = 0;
    for (int day = 1; day <= d; ++day) {
        std::fill(cur.begin(), cur.end(), INF);
        for (int i = day; i <= n; ++i) {
            int dayMax = 0;
            for (int j = i - 1; j >= day - 1; --j) {
                dayMax = std::max(dayMax, jobDifficulty[j]);
                cur[i] = std::min(cur[i], prev[j] + dayMax);
            }
        }
        prev.swap(cur);
    }
    return prev[n] >= INF ? -1 : static_cast<int>(prev[n]);
}

