std::vector<int> kWeakestRows(const std::vector<std::vector<int>>& mat, int k) {
    auto countOnes = [&](const std::vector<int>& row) -> int {
        int lo = 0, hi = static_cast<int>(row.size());
        while (lo < hi) {
            int mid = (lo + hi) >> 1;
            if (row[mid] == 1) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    };

    auto greater = [&](const std::pair<int, int>& a, const std::pair<int, int>& b) -> bool {
        if (a.first != b.first) return a.first > b.first;
        return a.second > b.second;
    };

    auto heapPush = [&](std::vector<std::pair<int, int>>& heap, const std::pair<int, int>& node) {
        heap.push_back(node);
        int i = static_cast<int>(heap.size()) - 1;
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (greater(heap[p], heap[i])) break;
            std::swap(heap[p], heap[i]);
            i = p;
        }
    };

    auto heapPop = [&](std::vector<std::pair<int, int>>& heap) -> std::pair<int, int> {
        std::pair<int, int> top = heap[0];
        std::pair<int, int> last = heap.back();
        heap.pop_back();
        if (!heap.empty()) {
            heap[0] = last;
            int i = 0;
            while (true) {
                int l = i * 2 + 1;
                int r = i * 2 + 2;
                int largest = i;
                if (l < static_cast<int>(heap.size()) && !greater(heap[largest], heap[l])) largest = l;
                if (r < static_cast<int>(heap.size()) && !greater(heap[largest], heap[r])) largest = r;
                if (largest == i) break;
                std::swap(heap[i], heap[largest]);
                i = largest;
            }
        }
        return top;
    };

    std::vector<std::pair<int, int>> heap;
    for (int i = 0; i < static_cast<int>(mat.size()); ++i) {
        int soldiers = countOnes(mat[i]);
        heapPush(heap, {soldiers, i});
        if (static_cast<int>(heap.size()) > k) heapPop(heap);
    }

    std::sort(heap.begin(), heap.end(), [&](const std::pair<int, int>& a, const std::pair<int, int>& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second < b.second;
    });

    std::vector<int> result;
    result.reserve(heap.size());
    for (const auto& p : heap) result.push_back(p.second);
    return result;
}

