    TreeNode* right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode* l, TreeNode* r) : val(x), left(l), right(r) {}
};

int maxProduct(TreeNode* root) {
    const long long MOD = 1000000007LL;
    long long best = 0;

    std::function<long long(TreeNode*)> sum = [&](TreeNode* node) -> long long {
        if (!node) return 0;
        return static_cast<long long>(node->val) + sum(node->left) + sum(node->right);
    };
    long long total = sum(root);

    std::function<long long(TreeNode*)> dfs = [&](TreeNode* node) -> long long {
        if (!node) return 0;
        long long left = dfs(node->left);
        long long right = dfs(node->right);
        long long cur = static_cast<long long>(node->val) + left + right;
        long long product = cur * (total - cur);
        if (product > best) best = product;
        return cur;
    };
    dfs(root);

    return static_cast<int>(best % MOD);
}

