int maxJumps(const std::vector<int>& arr, int d) {
    int n = static_cast<int>(arr.size());
    std::vector<int> memo(n, 0);
    std::function<int(int)> dfs = [&](int i) -> int {
        if (memo[i] != 0) return memo[i];
        int best = 1;
        for (int step = 1; step <= d && i - step >= 0; ++step) {
            if (arr[i] > arr[i - step]) {
                best = std::max(best, 1 + dfs(i - step));
            } else {
                break;
            }
        }
        for (int step = 1; step <= d && i + step < n; ++step) {
            if (arr[i] > arr[i + step]) {
                best = std::max(best, 1 + dfs(i + step));
            } else {
                break;
            }
        }
        memo[i] = best;
        return best;
    };
    int answer = 0;
    for (int i = 0; i < n; ++i) {
        answer = std::max(answer, dfs(i));
    }
    return answer;
}

