int minJumps(const std::vector<int>& arr) {
    int n = static_cast<int>(arr.size());
    if (n <= 1) return 0;

    std::unordered_map<int, std::vector<int>> posMap;
    for (int i = 0; i < n; ++i) {
        posMap[arr[i]].push_back(i);
    }

    std::vector<bool> visited(n, false);
    std::deque<int> queue;
    visited[0] = true;
    queue.push_back(0);
    int steps = 0;

    while (!queue.empty()) {
        int levelSize = static_cast<int>(queue.size());
        for (int k = 0; k < levelSize; ++k) {
            int i = queue.front();
            queue.pop_front();
            if (i == n - 1) return steps;

            std::vector<int> neighbours;
            if (i - 1 >= 0) neighbours.push_back(i - 1);
            if (i + 1 < n) neighbours.push_back(i + 1);
            auto it = posMap.find(arr[i]);
            if (it != posMap.end()) {
                neighbours.insert(neighbours.end(), it->second.begin(), it->second.end());
                posMap.erase(it);
            }

            for (int nb : neighbours) {
                if (!visited[nb]) {
                    visited[nb] = true;
                    queue.push_back(nb);
                }
            }
        }
        ++steps;
    }
    return -1;
}

