int maxStudents(const std::vector<std::vector<char>>& seats) {
    int m = seats.size();
    if (m == 0) return 0;
    int n = seats[0].size();
    int maxMask = 1 << n;

    std::vector<int> popcnt(maxMask);
    for (int mask = 0; mask < maxMask; ++mask) popcnt[mask] = __builtin_popcount(mask);

    std::vector<std::vector<int>> validMasks(m);
    for (int i = 0; i < m; ++i) {
        for (int mask = 0; mask < maxMask; ++mask) {
            if (mask & (mask << 1)) continue;
            bool ok = true;
            for (int j = 0; j < n; ++j) {
                if (mask & (1 << j)) {
                    if (seats[i][j] == '#') { ok = false; break; }
                }
            }
            if (ok) validMasks[i].push_back(mask);
        }
    }

    std::vector<std::vector<char>> compatible(maxMask, std::vector<char>(maxMask, 0));
    for (int a = 0; a < maxMask; ++a) {
        for (int b = 0; b < maxMask; ++b) {
            if (a & (b << 1)) continue;
            if (a & (b >> 1)) continue;
            compatible[a][b] = 1;
        }
    }

    const int NEG = -1e9;
    std::vector<int> dpPrev(maxMask, NEG), dpCurr(maxMask, NEG);
    for (int mask : validMasks[0]) dpPrev[mask] = popcnt[mask];

    for (int i = 1; i < m; ++i) {
        std::fill(dpCurr.begin(), dpCurr.end(), NEG);
        for (int mask : validMasks[i]) {
            for (int prevMask : validMasks[i - 1]) {
                if (dpPrev[prevMask] == NEG) continue;
                if (!compatible[mask][prevMask]) continue;
                dpCurr[mask] = std::max(dpCurr[mask], dpPrev[prevMask] + popcnt[mask]);
            }
        }
        dpPrev.swap(dpCurr);
    }

    int ans = 0;
    for (int mask = 0; mask < maxMask; ++mask) ans = std::max(ans, dpPrev[mask]);
    return ans;
}

