        long long t = heap[i];
        heap[i] = heap[j];
        heap[j] = t;
    };
    auto push = [&](long long val) {
        heap.push_back(val);
        size_t i = heap.size() - 1;
        while (i > 0) {
            size_t p = (i - 1) >> 1;
            if (heap[p] >= heap[i]) break;
            swap(i, p);
            i = p;
        }
    };
    auto pop = [&]() -> long long {
        long long top = heap[0];
        long long last = heap.back();
        heap.pop_back();
        if (!heap.empty()) {
            heap[0] = last;
            size_t i = 0;
            while (true) {
                size_t l = i * 2 + 1;
                size_t r = i * 2 + 2;
                size_t largest = i;
                if (l < heap.size() && heap[l] > heap[largest]) largest = l;
                if (r < heap.size() && heap[r] > heap[largest]) largest = r;
                if (largest == i) break;
                swap(i, largest);
                i = largest;
            }
        }
        return top;
    };

    if (target.size() == 1) return target[0] == 1;

    long long total = 0;
    for (int v : target) {
        push(v);
        total += v;
    }

    while (true) {
        long long max = pop();
        long long rest = total - max;

        if (max == 1 || rest == 1) return true;

        long long prev = max % rest;
        if (prev == 0) prev = rest;

        if (prev == 0 || prev == max) return false;

        push(prev);
        total = rest + prev;
    }
}

