int maxEvents(std::vector<std::vector<int>>& events) {
    std::sort(events.begin(), events.end(),
              [](const std::vector<int>& a, const std::vector<int>& b) {
                  return a[0] < b[0];
              });

    std::vector<int> heap;
    auto push = [&](int x) {
        heap.push_back(x);
        int i = static_cast<int>(heap.size()) - 1;
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (heap[p] <= heap[i]) break;
            std::swap(heap[p], heap[i]);
            i = p;
        }
    };
    auto pop = [&]() -> int {
        if (heap.empty()) return -1;
        int min = heap[0];
        int last = heap.back();
        heap.pop_back();
        if (!heap.empty()) {
            heap[0] = last;
            int i = 0;
            while (true) {
                int l = i * 2 + 1;
                int r = i * 2 + 2;
                int s = i;
                if (l < static_cast<int>(heap.size()) && heap[l] < heap[s]) s = l;
                if (r < static_cast<int>(heap.size()) && heap[r] < heap[s]) s = r;
                if (s == i) break;
                std::swap(heap[i], heap[s]);
                i = s;
            }
        }
        return min;
    };

    int day = 0, i = 0, attended = 0;
    while (i < static_cast<int>(events.size()) || !heap.empty()) {
        if (heap.empty()) day = events[i][0];
        while (i < static_cast<int>(events.size()) && events[i][0] <= day) {
            push(events[i][1]);
            ++i;
        }
        while (!heap.empty() && heap[0] < day) {
            pop();
        }
        if (!heap.empty()) {
            pop();
            ++attended;
            ++day;
        }
    }
    return attended;
}

