long long countOrders(int n) {
    const long long MOD = 1000000007LL;
    long long fact = 1;
    for (long long i = 2; i <= 2LL * n; ++i) {
        fact = (fact * i) % MOD;
    }
    long long pow2 = 1;
    long long b = 2 % MOD;
    long long e = n;
    while (e > 0) {
        if (e & 1LL) pow2 = (pow2 * b) % MOD;
        b = (b * b) % MOD;
        e >>= 1LL;
    }
    long long invPow2 = 1;
    b = pow2 % MOD;
    e = MOD - 2;
    while (e > 0) {
        if (e & 1LL) invPow2 = (invPow2 * b) % MOD;
        b = (b * b) % MOD;
        e >>= 1LL;
    }
    return (fact * invPow2) % MOD;
}

