    auto idx = [](char ch) -> int { return ch - 'a'; };
    int left = 0, right = 0;
    long long ans = 0;
    while (left < n) {
        while (right < n && (cnt[0] == 0 || cnt[1] == 0 || cnt[2] == 0)) {
            cnt[idx(s[right])] ++;
            ++right;
        }
        if (cnt[0] > 0 && cnt[1] > 0 && cnt[2] > 0) {
            ans += static_cast<long long>(n - right + 1);
