bool validateBinaryTreeNodes(int n, const std::vector<int>& leftChild, const std::vector<int>& rightChild) {
    std::vector<int> indegree(n, 0);
    for (int i = 0; i < n; ++i) {
        int l = leftChild[i];
        int r = rightChild[i];
        if (l != -1) ++indegree[l];
        if (r != -1) ++indegree[r];
    }

    int root = -1;
    for (int i = 0; i < n; ++i) {
        if (indegree[i] == 0) {
            if (root != -1) return false;
            root = i;
        } else if (indegree[i] > 1) {
            return false;
        }
    }
    if (root == -1) return false;

    std::vector<int> stack;
    stack.push_back(root);
    std::vector<bool> visited(n, false);
    visited[root] = true;
    int visitedCount = 0;

    while (!stack.empty()) {
        int node = stack.back();
        stack.pop_back();
        ++visitedCount;

        int l = leftChild[node];
        int r = rightChild[node];

        if (l != -1) {
            if (visited[l]) return false;
            visited[l] = true;
            stack.push_back(l);
        }
        if (r != -1) {
            if (visited[r]) return false;
            visited[r] = true;
            stack.push_back(r);
        }
    }

    return visitedCount == n;
}

