static inline int64_t days_from_civil(int64_t y, unsigned m, unsigned d) {
    y -= m <= 2;
    int64_t era = (y >= 0 ? y : y - 399) / 400;
    unsigned yoe = static_cast<unsigned>(y - era * 400);
    unsigned doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
    unsigned doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    return era * 146097 + static_cast<int64_t>(doe) - 719468;
}

double daysBetween(const std::string& date1, const std::string& date2) {
    int64_t y1 = std::stoll(date1.substr(0, 4));
    unsigned m1 = static_cast<unsigned>(std::stoll(date1.substr(5, 2)));
    unsigned d1 = static_cast<unsigned>(std::stoll(date1.substr(8, 2)));
    int64_t y2 = std::stoll(date2.substr(0, 4));
    unsigned m2 = static_cast<unsigned>(std::stoll(date2.substr(5, 2)));
    unsigned d2 = static_cast<unsigned>(std::stoll(date2.substr(8, 2)));
    int64_t t1 = days_from_civil(y1, m1, d1) * 86400000LL;
    int64_t t2 = days_from_civil(y2, m2, d2) * 86400000LL;
    return static_cast<double>(std::llabs(t2 - t1)) / (1000.0 * 60 * 60 * 24);
}

