std::vector<int> closestDivisors(int num) {
    std::vector<int> bestPair;
    long long bestDiff = LLONG_MAX;

    for (int add = 1; add <= 2; ++add) {
        long long target = static_cast<long long>(num) + add;
        long long i = static_cast<long long>(std::sqrt(static_cast<double>(target)));

        while (i >= 1 && target % i != 0) {
            --i;
        }

        long long a = i;
        long long b = target / i;
        long long diff = std::llabs(a - b);

        if (diff < bestDiff) {
            bestDiff = diff;
            bestPair = {static_cast<int>(a), static_cast<int>(b)};
        }
    }
    return bestPair;
}

