std::string largestMultipleOfThree(const std::vector<int>& digits) {
    std::array<int, 10> cnt{};
    int sum = 0;
    for (int d : digits) {
        cnt[d]++;
        sum += d;
    }

    int rem = sum % 3;

    auto tryRemove = [&](int target, int need) -> bool {
        for (int d = 0; d <= 9 && need > 0; ++d) {
            if (d % 3 == target) {
                int take = std::min(cnt[d], need);
                cnt[d] -= take;
                need -= take;
            }
        }
        return need == 0;
    };

    if (rem == 1) {
        if (!tryRemove(1, 1)) {
            if (!tryRemove(2, 2)) {
                return "";
            }
        }
    } else if (rem == 2) {
        if (!tryRemove(2, 1)) {
            if (!tryRemove(1, 2)) {
                return "";
            }
        }
    }

    std::string result;
    for (int d = 9; d >= 0; --d) {
        if (cnt[d] > 0) {
            result.append(cnt[d], static_cast<char>('0' + d));
        }
    }

    if (result.empty()) return "";
    std::size_t firstNonZero = result.find_first_not_of('0');
    if (firstNonZero == std::string::npos) return "0";
    return result.substr(firstNonZero);
}

