int minCost(const std::vector<std::vector<int>>& grid) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    const int INF = std::numeric_limits<int>::max();
    std::vector<std::vector<int>> dist(m, std::vector<int>(n, INF));
    std::deque<std::pair<int, int>> dq;
    dist[0][0] = 0;
    dq.emplace_front(0, 0);
    const std::array<int, 4> dx = {0, 0, 1, -1};
    const std::array<int, 4> dy = {1, -1, 0, 0};
    while (!dq.empty()) {
        std::pair<int, int> cur = dq.front();
        dq.pop_front();
        int x = cur.first;
        int y = cur.second;
        int curDist = dist[x][y];
        for (int dir = 0; dir < 4; ++dir) {
            int nx = x + dx[dir];
            int ny = y + dy[dir];
            if (nx < 0 || ny < 0 || nx >= m || ny >= n) continue;
            int w = (grid[x][y] == dir + 1) ? 0 : 1;
            if (curDist + w < dist[nx][ny]) {
                dist[nx][ny] = curDist + w;
                if (w == 0) dq.emplace_front(nx, ny);
                else dq.emplace_back(nx, ny);
            }
        }
    }
    return dist[m - 1][n - 1];
}

