std::string rankTeams(const std::vector<std::string>& votes) {
    if (votes.empty()) return "";
    int teamCount = static_cast<int>(votes[0].size());
    std::unordered_map<char, std::vector<int>> cnt;
    for (const std::string& vote : votes) {
        for (int i = 0; i < teamCount; ++i) {
            char t = vote[i];
            if (!cnt.count(t)) {
                cnt[t] = std::vector<int>(teamCount, 0);
            }
            cnt[t][i]++;
        }
    }
    std::vector<char> teams;
    teams.reserve(cnt.size());
    for (const auto& p : cnt) {
        teams.push_back(p.first);
    }
    std::sort(teams.begin(), teams.end(), [&](char a, char b) {
        for (int i = 0; i < teamCount; ++i) {
            if (cnt[a][i] != cnt[b][i]) {
                return cnt[a][i] > cnt[b][i];
            }
        }
        return a < b;
    });
    std::string result;
    result.reserve(teamCount);
    for (char c : teams) {
        result.push_back(c);
    }
    return result;
}

