int longestZigZag(TreeNode* root) {
    int maxLen = 0;
    std::function<std::pair<int, int>(TreeNode*)> dfs = [&](TreeNode* node) -> std::pair<int, int> {
        if (!node) {
            return std::make_pair(-1, -1);
        }
        std::pair<int, int> leftChild = dfs(node->left);
        std::pair<int, int> rightChild = dfs(node->right);
        int leftZig = 1 + leftChild.second;
        int rightZig = 1 + rightChild.first;
        if (leftZig > maxLen) maxLen = leftZig;
        if (rightZig > maxLen) maxLen = rightZig;
        return std::make_pair(leftZig, rightZig);
    };
    dfs(root);
    return maxLen;
}

