struct Result {
    bool isBST;
    long long sum;
    long long min;
    long long max;
};

Result dfs(TreeNode* node, long long& maxSum) {
    if (!node) {
        return {true, 0, std::numeric_limits<long long>::max(), std::numeric_limits<long long>::min()};
    }
    Result left = dfs(node->left, maxSum);
    Result right = dfs(node->right, maxSum);
    bool isBST = left.isBST && right.isBST && node->val > left.max && node->val < right.min;
    long long sum = isBST ? left.sum + right.sum + node->val : 0;
    if (isBST) {
        maxSum = std::max(maxSum, sum);
    }
    long long mn = std::min<long long>(node->val, left.min);
    long long mx = std::max<long long>(node->val, right.max);
    return {isBST, sum, mn, mx};
}

long long maxSumBST(TreeNode* root) {
    long long maxSum = 0;
    dfs(root, maxSum);
