int numOfMinutes(int n, int headID, const std::vector<int>& manager, const std::vector<int>& informTime) {
    std::vector<std::vector<int>> subordinates(n);
    for (int i = 0; i < n; ++i) {
        int mgr = manager[i];
        if (mgr != -1) {
            subordinates[mgr].push_back(i);
        }
    }
    std::function<int(int)> dfs = [&](int emp) -> int {
        int longest = 0;
        for (int sub : subordinates[emp]) {
            int subTime = dfs(sub);
            if (subTime > longest) longest = subTime;
        }
        return longest + informTime[emp];
    };
    return dfs(headID);
}

