double frogPosition(int n, const std::vector<std::vector<int>>& edges, int t, int target) {
    std::vector<std::vector<int>> adj(n + 1);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    std::queue<std::tuple<int, double, int>> q;
    q.emplace(1, 1.0, 0);
    std::vector<bool> visited(n + 1, false);
    visited[1] = true;

    while (!q.empty()) {
        int node;
        double prob;
        int time;
        std::tie(node, prob, time) = q.front();
        q.pop();

        std::vector<int> unvisited;
        for (int v : adj[node]) {
            if (!visited[v]) {
                unvisited.push_back(v);
            }
        }

        if (node == target) {
            if (time == t || (time < t && unvisited.empty())) {
                return prob;
            }
        }

        if (time == t) continue;

        int cnt = static_cast<int>(unvisited.size());
        if (cnt == 0) continue;

        double nextProb = prob / cnt;
        for (int nb : unvisited) {
            visited[nb] = true;
            q.emplace(nb, nextProb, time + 1);
        }
    }
    return 0.0;
}

