    int maxSize;
    CustomStack(int maxSize_) : maxSize(maxSize_), inc(maxSize_, 0) {}
    void push(int x) { if ((int)stack.size() < maxSize) stack.push_back(x); }
    int pop() {
        if (stack.empty()) return -1;
        int i = (int)stack.size()-1;
        int val = stack.back() + inc[i];
        stack.pop_back();
        if (i > 0) inc[i-1] += inc[i];
        inc[i] = 0;
        return val;
    }
    void increment(int k, int val) {
        int i = std::min(k, (int)stack.size()) - 1;
        if (i >= 0) inc[i] += val;
    }
};

