    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

void inorder(TreeNode* node, std::vector<int>& sorted) {
    if (!node) return;
    inorder(node->left, sorted);
    sorted.push_back(node->val);
    inorder(node->right, sorted);
}

TreeNode* build(const std::vector<int>& sorted, int l, int r) {
    if (l > r) return nullptr;
    int m = (l + r) >> 1;
    TreeNode* node = new TreeNode(sorted[m]);
    node->left = build(sorted, l, m - 1);
    node->right = build(sorted, m + 1, r);
    return node;
}

TreeNode* balanceBST(TreeNode* root) {
    std::vector<int> sorted;
    inorder(root, sorted);
    return build(sorted, 0, static_cast<int>(sorted.size()) - 1);
}

