long long maxPerformance(int n, const std::vector<int>& speed, const std::vector<int>& efficiency, int k) {
    const long long MOD = 1000000007LL;
    std::vector<std::pair<int, int>> engineers;
    engineers.reserve(n);
    for (int i = 0; i < n; ++i) {
        engineers.emplace_back(efficiency[i], speed[i]);
    }
    std::sort(engineers.begin(), engineers.end(),
              [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
                  return a.first > b.first;
              });

    std::priority_queue<long long, std::vector<long long>, std::greater<long long>> minHeap;
    long long sumSpeeds = 0;
    long long best = 0;

    for (const auto& eng : engineers) {
        long long eff = eng.first;
        long long spd = eng.second;
        minHeap.push(spd);
        sumSpeeds += spd;
        if (static_cast<int>(minHeap.size()) > k) {
            sumSpeeds -= minHeap.top();
            minHeap.pop();
        }
        long long perf = (sumSpeeds * eff) % MOD;
        if (perf > best) {
            best = perf;
        }
    }
    return best;
}

