int maxNumberOfFamilies(int n, const std::vector<std::vector<int>>& reservedSeats) {
    std::unordered_map<int, uint16_t> rowMask;
    rowMask.reserve(reservedSeats.size());
    for (const auto& rs : reservedSeats) {
        int r = rs[0];
        int s = rs[1];
        rowMask[r] |= static_cast<uint16_t>(1u << s);
    }

    long long families = static_cast<long long>(n - static_cast<int>(rowMask.size())) * 2LL;

    const uint16_t leftMask   = (1u << 2) | (1u << 3) | (1u << 4) | (1u << 5);
    const uint16_t rightMask  = (1u << 6) | (1u << 7) | (1u << 8) | (1u << 9);
    const uint16_t middleMask = (1u << 4) | (1u << 5) | (1u << 6) | (1u << 7);

    for (const auto& entry : rowMask) {
        uint16_t mask = entry.second;
        bool leftFree   = (mask & leftMask)   == 0;
        bool rightFree  = (mask & rightMask)  == 0;
        bool middleFree = (mask & middleMask) == 0;

        if (leftFree && rightFree) {
            families += 2;
        } else if (middleFree) {
            families += 1;
        } else if (leftFree || rightFree) {
            families += 1;
        }
    }
    return static_cast<int>(families);
}

