int getKth(int lo, int hi, int k) {
    std::unordered_map<long long, int> memo;
    memo[1] = 0;
    std::function<int(long long)> power = [&](long long x) -> int {
        auto it = memo.find(x);
        if (it != memo.end()) return it->second;
        long long next = (x % 2 == 0) ? x / 2 : 3 * x + 1;
        int val = 1 + power(next);
        memo[x] = val;
        return val;
    };
    std::vector<std::pair<int, int>> pairs;
    pairs.reserve(hi - lo + 1);
    for (int n = lo; n <= hi; ++n) {
        pairs.emplace_back(n, power(n));
    }
    std::sort(pairs.begin(), pairs.end(), [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
        return a.second == b.second ? a.first < b.first : a.second < b.second;
    });
    return pairs[k - 1].first;
}

