int distanceValue(const std::vector<int>& arr1, std::vector<int> arr2, int d) {
    std::sort(arr2.begin(), arr2.end());
    int count = 0;
    for (size_t i = 0; i < arr1.size(); ++i) {
        int x = arr1[i];
        size_t lo = 0, hi = arr2.size();
        while (lo < hi) {
            size_t mid = (lo + hi) >> 1;
            if (arr2[mid] < x) lo = mid + 1;
            else hi = mid;
        }
        bool ok = true;
        if (lo < arr2.size() && std::abs(arr2[lo] - x) <= d) ok = false;
        if (lo > 0 && std::abs(arr2[lo - 1] - x) <= d) ok = false;
        if (ok) ++count;
    }
    return count;
}

