bool hasValidPath(const std::vector<std::vector<int>>& grid) {
    int m = static_cast<int>(grid.size());
    if (m == 0) return false;
    int n = static_cast<int>(grid[0].size());
    const std::array<int, 4> dr = {-1, 1, 0, 0};
    const std::array<int, 4> dc = {0, 0, -1, 1};
    const std::array<int, 4> opposite = {1, 0, 3, 2};
    const std::array<std::array<int, 2>, 7> allowed = {{
        {{-1, -1}},
        {{2, 3}},
        {{0, 1}},
        {{2, 1}},
        {{3, 1}},
        {{2, 0}},
        {{3, 0}}
    }};
    std::vector<char> visited(m * n, 0);
    std::queue<std::pair<int, int>> q;
    q.emplace(0, 0);
    visited[0] = 1;
    while (!q.empty()) {
        int r = q.front().first;
        int c = q.front().second;
        q.pop();
        if (r == m - 1 && c == n - 1) return true;
        int type = grid[r][c];
        for (int k = 0; k < 2; ++k) {
            int dir = allowed[type][k];
            if (dir == -1) continue;
            int nr = r + dr[dir];
            int nc = c + dc[dir];
            if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
            int ntype = grid[nr][nc];
            int opp = opposite[dir];
            if (allowed[ntype][0] == opp || allowed[ntype][1] == opp) {
                int idx = nr * n + nc;
                if (!visited[idx]) {
                    visited[idx] = 1;
                    q.emplace(nr, nc);
                }
            }
        }
    }
    return false;
}

