int solveLinear(const std::vector<int>& arr, int picks) {
    int L = static_cast<int>(arr.size());
    const int NEG = -1000000000;
    std::vector<int> dpPrevPrev(picks + 1, NEG), dpPrev(picks + 1, NEG), cur(picks + 1, NEG);
    dpPrevPrev[0] = dpPrev[0] = 0;
    for (int i = 1; i <= L; ++i) {
        cur.assign(picks + 1, NEG);
        for (int k = 0; k <= picks; ++k) {
            int notTake = dpPrev[k];
            int take = NEG;
            if (k > 0) {
                if (i >= 2) {
                    take = dpPrevPrev[k - 1] + arr[i - 1];
                } else if (i == 1 && k == 1) {
                    take = arr[0];
                }
            }
            cur[k] = std::max(notTake, take);
        }
        dpPrevPrev.swap(dpPrev);
        dpPrev.swap(cur);
    }
    return dpPrev[picks];
}

int maxSizeSlices(std::vector<int>& slices) {
    int m = static_cast<int>(slices.size());
    int n = m / 3;
    std::vector<int> case1(slices.begin(), slices.end() - 1);
    std::vector<int> case2(slices.begin() + 1, slices.end());
    int ans1 = solveLinear(case1, n);
    int ans2 = solveLinear(case2, n);
    return std::max(ans1, ans2);
}

