long long sumFourDivisors(const std::vector<int>& nums) {
    int maxNum = 0;
    for (int v : nums) {
        if (v > maxNum) maxNum = v;
    }
    int limit = static_cast<int>(std::sqrt(maxNum));
    std::vector<unsigned char> isPrime(limit + 1, 0);
    std::vector<int> primes;
    for (int i = 2; i <= limit; ++i) {
        if (!isPrime[i]) {
            primes.push_back(i);
            if ((long long)i * i <= limit) {
                for (int j = i * i; j <= limit; j += i) {
                    isPrime[j] = 1;
                }
            }
        }
    }

    long long total = 0;
    for (int num : nums) {
        if (num < 2) continue;
        long long n = num;
        int distinct = 0;
        long long firstPrime = 0, secondPrime = 0;
        int firstExp = 0, secondExp = 0;

        for (int p : primes) {
            if ((long long)p * p > n) break;
            if (n % p == 0) {
                ++distinct;
                int exp = 0;
                while (n % p == 0) {
                    n /= p;
                    ++exp;
                }
                if (distinct == 1) {
                    firstPrime = p;
                    firstExp = exp;
                } else {
                    secondPrime = p;
                    secondExp = exp;
                }
                if (distinct > 2) break;
            }
        }
        if (n > 1) {
            ++distinct;
            if (distinct == 1) {
                firstPrime = n;
                firstExp = 1;
            } else {
                secondPrime = n;
                secondExp = 1;
            }
        }

        if (distinct == 1 && firstExp == 3) {
            long long p = firstPrime;
            total += 1 + p + p * p + p * p * p;
        } else if (distinct == 2 && firstExp == 1 && secondExp == 1) {
            long long p = firstPrime, q = secondPrime;
            total += 1 + p + q + p * q;
        }
    }
    return total;
}

