class UndergroundSystem {
public:
    std::unordered_map<int, std::pair<std::string,int>> checkInMap;
    std::unordered_map<std::string, std::pair<long long,int>> travelMap;
    void checkIn(int id, std::string stationName, int t) { checkInMap[id] = {stationName, t}; }
    void checkOut(int id, std::string stationName, int t) {
        auto [startStation, startTime] = checkInMap[id];
        checkInMap.erase(id);
        std::string key = startStation + "_" + stationName;
        auto& agg = travelMap[key];
        agg.first += (t - startTime);
        agg.second += 1;
    }
    double getAverageTime(std::string startStation, std::string endStation) {
        auto& agg = travelMap[startStation + "_" + endStation];
        return (double)agg.first / agg.second;
    }
};

