int numTeams(std::vector<int> rating) {
    int n = rating.size();
    long long ans = 0;
    for (int j = 0; j < n; ++j) {
        int leftSmaller = 0;
        for (int i = 0; i < j; ++i) {
            if (rating[i] < rating[j]) ++leftSmaller;
        }
        int leftGreater = j - leftSmaller;
        int rightSmaller = 0;
        for (int k = j + 1; k < n; ++k) {
            if (rating[k] < rating[j]) ++rightSmaller;
        }
        int rightGreater = (n - 1 - j) - rightSmaller;
        ans += static_cast<long long>(leftSmaller) * rightGreater;
        ans += static_cast<long long>(leftGreater) * rightSmaller;
    }
    return static_cast<int>(ans);
}

#include <bits/stdc++.h>
int findGoodStrings(int n, std::string s1, std::string s2, std::string evil) {
    const int MOD = 1000000007;
    int m = (int)evil.size();
    std::vector<int> pi(m, 0);
    for (int i = 1; i < m; ++i) {
        int j = pi[i - 1];
        while (j > 0 && evil[i] != evil[j]) j = pi[j - 1];
        if (evil[i] == evil[j]) ++j;
        pi[i] = j;
    }
    std::vector<std::array<int, 26>> nxt(m + 1);
    for (int state = 0; state <= m; ++state) {
        for (int ch = 0; ch < 26; ++ch) {
            char c = 'a' + ch;
            int k = state;
            while (k > 0 && (k == m || c != evil[k])) k = pi[k - 1];
            if (k < m && c == evil[k]) ++k;
            nxt[state][ch] = k;
        }
    }
    static long long dp[2][2][2][51];
    std::memset(dp, 0, sizeof(dp));
    dp[0][1][1][0] = 1;
    int cur = 0, nxtLayer = 1;
    for (int pos = 0; pos < n; ++pos) {
        std::memset(dp[nxtLayer], 0, sizeof(dp[nxtLayer]));
        for (int low = 0; low <= 1; ++low) {
            for (int high = 0; high <= 1; ++high) {
                for (int state = 0; state < m; ++state) {
                    long long val = dp[cur][low][high][state];
                    if (!val) continue;
                    char lo = low ? s1[pos] : 'a';
                    char hi = high ? s2[pos] : 'z';
                    for (char c = lo; c <= hi; ++c) {
                        int nl = low && (c == s1[pos]);
                        int nh = high && (c == s2[pos]);
                        int ns = nxt[state][c - 'a'];
                        if (ns == m) continue;
                        dp[nxtLayer][nl][nh][ns] += val;
                        if (dp[nxtLayer][nl][nh][ns] >= MOD) dp[nxtLayer][nl][nh][ns] -= MOD;
                    }
                }
            }
        }
        std::swap(cur, nxtLayer);
    }
    long long ans = 0;
    for (int low = 0; low <= 1; ++low) {
        for (int high = 0; high <= 1; ++high) {
            for (int state = 0; state < m; ++state) {
                ans += dp[cur][low][high][state];
                if (ans >= MOD) ans -= MOD;
            }
        }
    }
    return (int)(ans % MOD);
}

