std::string stoneGameIII(const std::vector<int>& stoneValue) {
    int n = static_cast<int>(stoneValue.size());
    std::vector<long long> diff(n + 3, 0);
    for (int i = n - 1; i >= 0; --i) {
        long long best = LLONG_MIN;
        long long sum = 0;
        for (int k = 1; k <= 3 && i + k <= n; ++k) {
            sum += stoneValue[i + k - 1];
            best = std::max(best, sum - diff[i + k]);
        }
        diff[i] = best;
    }
    if (diff[0] > 0) return "Alice";
    if (diff[0] < 0) return "Bob";
    return "Tie";
}

