std::vector<int> processQueries(const std::vector<int>& queries, int m) {
    int n = static_cast<int>(queries.size());
    int size = n + m + 2;
    std::vector<int> bit(size, 0);
    auto add = [&](int i, int delta) {
        for (; i < size; i += i & -i) bit[i] += delta;
    };
    auto sum = [&](int i) {
        int res = 0;
        for (; i > 0; i -= i & -i) res += bit[i];
        return res;
    };
    std::vector<int> pos(m + 1);
    for (int v = 1; v <= m; ++v) {
        int idx = n + v;
        pos[v] = idx;
        add(idx, 1);
    }
    std::vector<int> result(n);
    int front = n;
    for (int i = 0; i < n; ++i) {
        int x = queries[i];
        int idx = pos[x];
        result[i] = sum(idx) - 1;
        add(idx, -1);
        add(front, 1);
        pos[x] = front;
        --front;
    }
    return result;
}

