std::string longestDiverseString(int a, int b, int c) {
    std::string result;
    std::vector<std::pair<char, int>> pool = { {'a', a}, {'b', b}, {'c', c} };

    while (true) {
        std::sort(pool.begin(), pool.end(),
                  [](const std::pair<char, int>& x, const std::pair<char, int>& y) {
                      return x.second > y.second;
                  });

        if (pool[0].second == 0) break;

        if (result.size() >= 2 &&
            result[result.size() - 1] == pool[0].first &&
            result[result.size() - 2] == pool[0].first) {

            if (pool[1].second == 0) break;
            result.push_back(pool[1].first);
            pool[1].second--;
            continue;
        }

        int maxAdd = (!result.empty() && result.back() == pool[0].first) ? 1 : 2;
        int use = std::min(pool[0].second, maxAdd);
        result.append(use, pool[0].first);
        pool[0].second -= use;
    }

    return result;
}

