std::string htmlEntityParser(const std::string& text) {
    static const std::unordered_map<std::string, std::string> entityMap = {
        {"&quot;", "\""},
        {"&apos;", "'"},
        {"&amp;", "&"},
        {"&gt;", ">"},
        {"&lt;", "<"},
        {"&frasl;", "/"}
    };
    const size_t maxLen = 7;
    std::string result;
    result.reserve(text.size());
    for (size_t i = 0; i < text.size(); ++i) {
        if (text[i] == '&') {
            bool replaced = false;
            for (size_t l = 2; l <= maxLen && i + l < text.size(); ++l) {
                std::string candidate = text.substr(i, l + 1);
                auto it = entityMap.find(candidate);
                if (it != entityMap.end()) {
                    result += it->second;
                    i += l;
                    replaced = true;
                    break;
                }
            }
            if (!replaced) {
                result += '&';
            }
        } else {
            result += text[i];
        }
    }
    return result;
}

