int minFibonacciNumbers(long long k) {
    std::vector<long long> fib = {1, 2};
    while (fib[fib.size() - 1] + fib[fib.size() - 2] <= k) {
        fib.push_back(fib[fib.size() - 1] + fib[fib.size() - 2]);
    }
    int count = 0;
    while (k > 0) {
        int lo = 0, hi = static_cast<int>(fib.size()) - 1;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (fib[mid] <= k) lo = mid;
            else hi = mid - 1;
        }
        k -= fib[lo];
        ++count;
    }
    return count;
}

