int restoreArray(const std::string& s, long long k) {
    const long long MOD = 1000000007LL;
    size_t n = s.size();
    int maxLen = std::to_string(k).size();

    std::vector<long long> dp(n + 1, 0);
    dp[0] = 1;

    for (size_t i = 1; i <= n; ++i) {
        for (int j = static_cast<int>(i) - 1; j >= 0 && i - j <= static_cast<size_t>(maxLen); --j) {
            if (s[j] == '0') continue;
            long long num = std::stoll(s.substr(j, i - j));
            if (num > k) continue;
            dp[i] = (dp[i] + dp[j]) % MOD;
        }
    }
    return static_cast<int>(dp[n]);
}

