std::string getHappyString(int n, long long k) {
    long long total = 3LL * (1LL << (n - 1));
    if (k > total) return "";
    const char letters[3] = {'a', 'b', 'c'};
    std::string result;
    char prev = '\0';
    for (int i = 0; i < n; ++i) {
        int remaining = n - i - 1;
        long long blockSize = 1LL << remaining;
        for (char ch : letters) {
            if (ch == prev) continue;
            if (k > blockSize) {
                k -= blockSize;
            } else {
                result.push_back(ch);
                prev = ch;
                break;
            }
        }
    }
    return result;
}

