std::string reformatString(const std::string& s) {
    std::vector<char> letters;
    std::vector<char> digits;
    for (size_t i = 0; i < s.length(); ++i) {
        char ch = s[i];
        if (ch >= '0' && ch <= '9')
            digits.push_back(ch);
        else
            letters.push_back(ch);
    }
    if (std::abs(static_cast<int>(letters.size()) - static_cast<int>(digits.size())) > 1)
        return "";
    std::vector<char> res;
    size_t li = 0, di = 0;
    bool startWithLetter = letters.size() > digits.size();
    while (li < letters.size() || di < digits.size()) {
        if (startWithLetter) {
            if (li < letters.size()) res.push_back(letters[li++]);
            if (di < digits.size())  res.push_back(digits[di++]);
        } else {
            if (di < digits.size())  res.push_back(digits[di++]);
            if (li < letters.size()) res.push_back(letters[li++]);
        }
    }
    return std::string(res.begin(), res.end());
}

