std::vector<std::vector<std::string>> displayTable(const std::vector<std::vector<std::string>>& orders) {
    std::unordered_set<std::string> foodSet;
    std::unordered_map<std::string, std::unordered_map<std::string, int>> tableMap;

    for (size_t i = 0; i < orders.size(); ++i) {
        const std::string& tableStr = orders[i][1];
        const std::string& food = orders[i][2];
        foodSet.insert(food);
        auto& foodCountMap = tableMap[tableStr];
        foodCountMap[food] = foodCountMap[food] + 1;
    }

    std::vector<std::string> foods(foodSet.begin(), foodSet.end());
    std::sort(foods.begin(), foods.end());

    std::vector<int> tableInts;
    tableInts.reserve(tableMap.size());
    for (const auto& kv : tableMap) {
        tableInts.push_back(std::stoi(kv.first));
    }
    std::sort(tableInts.begin(), tableInts.end());

    std::vector<std::string> tables;
    tables.reserve(tableInts.size());
    for (int t : tableInts) {
        tables.push_back(std::to_string(t));
    }

    std::vector<std::vector<std::string>> result;
    std::vector<std::string> header;
    header.push_back("Table");
    header.insert(header.end(), foods.begin(), foods.end());
    result.push_back(std::move(header));

    for (const std::string& tbl : tables) {
        std::vector<std::string> row;
        row.push_back(tbl);
        const auto& foodCountMap = tableMap[tbl];
        for (const std::string& f : foods) {
            auto it = foodCountMap.find(f);
            int cnt = (it != foodCountMap.end()) ? it->second : 0;
            row.push_back(std::to_string(cnt));
        }
        result.push_back(std::move(row));
    }

    return result;
}

