int minNumberOfFrogs(const std::string& croakOfFrogs) {
    int stage[4] = {0, 0, 0, 0};
    int maxFrogs = 0;
    for (char ch : croakOfFrogs) {
        switch (ch) {
            case 'c':
                ++stage[0];
                break;
            case 'r':
                if (stage[0] == 0) return -1;
                --stage[0];
                ++stage[1];
                break;
            case 'o':
                if (stage[1] == 0) return -1;
                --stage[1];
                ++stage[2];
                break;
            case 'a':
                if (stage[2] == 0) return -1;
                --stage[2];
                ++stage[3];
                break;
            case 'k':
                if (stage[3] == 0) return -1;
                --stage[3];
                break;
            default:
                return -1;
        }
        int current = stage[0] + stage[1] + stage[2] + stage[3];
        if (current > maxFrogs) maxFrogs = current;
    }
    if (stage[0] != 0 || stage[1] != 0 || stage[2] != 0 || stage[3] != 0) return -1;
    return maxFrogs;
}

#include <bits/stdc++.h>
int numOfArrays(int n, int m, int k) {
    const int MOD = 1000000007;
    if (k > n) return 0;
    std::vector<std::vector<long long>> dp(k + 2, std::vector<long long>(m + 1, 0));
    for (int v = 1; v <= m; ++v) dp[1][v] = 1;
    for (int len = 2; len <= n; ++len) {
        std::vector<std::vector<long long>> ndp(k + 2, std::vector<long long>(m + 1, 0));
        for (int comp = 1; comp <= k; ++comp) {
            std::vector<long long> pref(m + 1, 0);
            for (int mx = 1; mx <= m; ++mx) {
                pref[mx] = (pref[mx - 1] + dp[comp][mx]) % MOD;
            }
            for (int mx = 1; mx <= m; ++mx) {
                ndp[comp][mx] = (ndp[comp][mx] + dp[comp][mx] * mx) % MOD;
                if (comp + 1 <= k) {
                    ndp[comp + 1][mx] = (ndp[comp + 1][mx] + pref[mx - 1]) % MOD;
                }
            }
        }
        dp.swap(ndp);
    }
    long long ans = 0;
    for (int mx = 1; mx <= m; ++mx) ans = (ans + dp[k][mx]) % MOD;
    return static_cast<int>(ans);
}

