int maxScore(const std::string& s) {
    int totalOnes = 0;
    for (char ch : s) {
        if (ch == '1') {
            ++totalOnes;
        }
    }
    int zerosLeft = 0;
    int onesSeen = 0;
    int best = 0;
    for (size_t i = 0; i + 1 < s.size(); ++i) {
        if (s[i] == '0') {
            ++zerosLeft;
        } else {
            ++onesSeen;
        }
        int onesRight = totalOnes - onesSeen;
        int score = zerosLeft + onesRight;
        if (score > best) {
            best = score;
        }
    }
    return best;
}

