std::vector<int> diagonalTraverse(const std::vector<std::vector<int>>& nums) {
    std::vector<std::vector<int>> buckets;
    for (size_t i = 0; i < nums.size(); ++i) {
        const std::vector<int>& row = nums[i];
        for (size_t j = 0; j < row.size(); ++j) {
            size_t d = i + j;
            if (d >= buckets.size()) {
                buckets.resize(d + 1);
            }
            buckets[d].push_back(row[j]);
        }
    }
    std::vector<int> result;
    for (size_t d = 0; d < buckets.size(); ++d) {
        const std::vector<int>& bucket = buckets[d];
        for (int k = static_cast<int>(bucket.size()) - 1; k >= 0; --k) {
            result.push_back(bucket[k]);
        }
    }
    return result;
}

