long long constrainedSubsequenceSum(const std::vector<int>& nums, int k) {
    int n = nums.size();
    std::vector<long long> dp(n);
    std::deque<int> deque;
    long long best = std::numeric_limits<long long>::min();
    for (int i = 0; i < n; ++i) {
        while (!deque.empty() && deque.front() < i - k) {
            deque.pop_front();
        }
        long long maxPrev = deque.empty() ? 0 : dp[deque.front()];
        dp[i] = nums[i] + std::max<long long>(0, maxPrev);
        while (!deque.empty() && dp[deque.back()] <= dp[i]) {
            deque.pop_back();
        }
        deque.push_back(i);
        if (dp[i] > best) {
            best = dp[i];
        }
    }
    return best;
}

