long long maxScore(const std::vector<int>& cardPoints, int k) {
    int n = static_cast<int>(cardPoints.size());
    int windowSize = n - k;
    if (windowSize == 0) {
        long long sum = 0;
        for (int v : cardPoints) sum += v;
        return sum;
    }
    long long total = 0;
    for (int v : cardPoints) total += v;
    long long current = 0;
    for (int i = 0; i < windowSize; ++i) current += cardPoints[i];
    long long minSum = current;
    for (int i = windowSize; i < n; ++i) {
        current += cardPoints[i] - cardPoints[i - windowSize];
        if (current < minSum) minSum = current;
    }
    return total - minSum;
}

