#include <bits/stdc++.h>
#include <vector>

int numberOfWays(const std::vector<std::vector<int>>& hats) {
    const int MOD = 1000000007;
    int n = static_cast<int>(hats.size());
    int fullMask = (1 << n) - 1;
    std::vector<std::vector<int>> hatToPeople(41);
    for (int person = 0; person < n; ++person) {
        for (int h : hats[person]) {
            hatToPeople[h].push_back(person);
        }
    }
    std::vector<int> dp(1 << n, 0);
    dp[0] = 1;
    for (int h = 1; h <= 40; ++h) {
        std::vector<int> next = dp;
        for (int mask = 0; mask <= fullMask; ++mask) {
            int ways = dp[mask];
            if (!ways) continue;
            for (int p : hatToPeople[h]) {
                if ((mask & (1 << p)) == 0) {
                    int newMask = mask | (1 << p);
                    next[newMask] = (next[newMask] + ways) % MOD;
                }
            }
        }
        dp.swap(next);
    }
    return dp[fullMask];
}

