#include <cstddef>

long long kthSmallestSum(const std::vector<std::vector<int>>& mat, int k) {
    if (mat.empty() || mat[0].empty()) return 0;
    int initLimit = std::min(k, static_cast<int>(mat[0].size()));
    std::vector<long long> sums(initLimit);
    for (int i = 0; i < initLimit; ++i) sums[i] = mat[0][i];
    for (size_t r = 1; r < mat.size(); ++r) {
        const std::vector<int>& row = mat[r];
        struct Node {
            long long total;
            int i;
            int j;
        };
        struct Compare {
            bool operator()(const Node& a, const Node& b) const { return a.total > b.total; }
        };
        std::priority_queue<Node, std::vector<Node>, Compare> heap;
        int curLimit = std::min(k, static_cast<int>(sums.size()));
        for (int i = 0; i < curLimit; ++i) {
            heap.push({sums[i] + row[0], i, 0});
        }
        std::vector<long long> newSums;
        newSums.reserve(k);
        while (static_cast<int>(newSums.size()) < k && !heap.empty()) {
            Node cur = heap.top();
            heap.pop();
            newSums.push_back(cur.total);
            if (cur.j + 1 < static_cast<int>(row.size())) {
                heap.push({sums[cur.i] + row[cur.j + 1], cur.i, cur.j + 1});
            }
        }
        sums.swap(newSums);
    }
    return sums[k - 1];
}

