int countTriplets(std::vector<int>& arr) {
    int n = static_cast<int>(arr.size());
    std::vector<int> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] ^ arr[i];
    std::unordered_map<int, std::pair<long long, long long>> mp;
    mp.reserve(static_cast<std::size_t>(n) * 2);
    long long ans = 0;
    for (int idx = 0; idx <= n; ++idx) {
        int x = pref[idx];
        auto it = mp.find(x);
        if (it != mp.end()) {
            ans += it->second.first * (idx - 1LL) - it->second.second;
            it->second.first += 1;
            it->second.second += idx;
        } else {
            mp.emplace(x, std::make_pair(1LL, static_cast<long long>(idx)));
        }
    }
    return static_cast<int>(ans);
}

