int minTime(int n, const std::vector<std::vector<int>>& edges, const std::vector<bool>& hasApple) {
    std::vector<std::vector<int>> graph(n);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        graph[u].push_back(v);
        graph[v].push_back(u);
    }
    std::function<int(int, int)> dfs = [&](int node, int parent) -> int {
        int total = 0;
        for (int nxt : graph[node]) {
            if (nxt == parent) continue;
            int childTime = dfs(nxt, node);
            if (childTime > 0 || hasApple[nxt]) {
                total += childTime + 2;
            }
        }
        return total;
    };
    return dfs(0, -1);
}

#include <bits/stdc++.h>

int ways(std::vector<std::string>& pizza, int k) {
    const int MOD = 1000000007;
    int rows = static_cast<int>(pizza.size());
    int cols = static_cast<int>(pizza[0].size());
    std::vector<std::vector<int>> apples(rows + 1, std::vector<int>(cols + 1, 0));
    for (int i = rows - 1; i >= 0; --i) {
        for (int j = cols - 1; j >= 0; --j) {
            apples[i][j] = (pizza[i][j] == 'A') + apples[i + 1][j] + apples[i][j + 1] - apples[i + 1][j + 1];
        }
    }
    if (apples[0][0] == 0) return 0;
    std::vector<std::vector<int>> dp(rows, std::vector<int>(cols, 0));
    for (int i = rows - 1; i >= 0; --i) {
        for (int j = cols - 1; j >= 0; --j) {
            dp[i][j] = (apples[i][j] > 0) ? 1 : 0;
        }
    }
    for (int cut = 1; cut < k; ++cut) {
        std::vector<std::vector<int>> ndp(rows, std::vector<int>(cols, 0));
        for (int i = rows - 1; i >= 0; --i) {
            for (int j = cols - 1; j >= 0; --j) {
                long long ways = 0;
                for (int r = i + 1; r < rows; ++r) {
                    if (apples[i][j] - apples[r][j] > 0) {
                        ways += dp[r][j];
                    }
                }
                for (int c = j + 1; c < cols; ++c) {
                    if (apples[i][j] - apples[i][c] > 0) {
                        ways += dp[i][c];
                    }
                }
                ndp[i][j] = static_cast<int>(ways % MOD);
            }
        }
        dp.swap(ndp);
    }
    return dp[0][0];
}

