std::string rearrangeWords(const std::string& text) {
    std::vector<std::string> words;
    std::istringstream iss(text);
    std::string token;
    while (std::getline(iss, token, ' ')) {
        words.push_back(token);
    }

    std::vector<std::string> lower;
    lower.reserve(words.size());
    for (const auto& w : words) {
        std::string lw = w;
        std::transform(lw.begin(), lw.end(), lw.begin(),
                       [](unsigned char c) { return std::tolower(c); });
        lower.push_back(std::move(lw));
    }

    struct Item {
        std::string word;
        std::size_t len;
        std::size_t idx;
    };
    std::vector<Item> items;
    items.reserve(lower.size());
    for (std::size_t i = 0; i < lower.size(); ++i) {
        items.push_back({lower[i], lower[i].size(), i});
    }

    std::sort(items.begin(), items.end(),
              [](const Item& a, const Item& b) {
                  if (a.len != b.len) return a.len < b.len;
                  return a.idx < b.idx;
              });

    std::string result;
    for (std::size_t i = 0; i < items.size(); ++i) {
        std::string w = items[i].word;
        if (i == 0 && !w.empty()) {
            w[0] = static_cast<char>(std::toupper(static_cast<unsigned char>(w[0])));
        }
        if (i > 0) result.push_back(' ');
        result += w;
    }
    return result;
}

