std::string largestNumber(const std::vector<int>& cost, int target) {
    const int NEG = INT_MIN / 2;
    std::vector<int> dp(target + 1, NEG);
    dp[0] = 0;
    for (int t = 1; t <= target; ++t) {
        for (int d = 1; d <= 9; ++d) {
            int c = cost[d - 1];
            if (t >= c && dp[t - c] != NEG) {
                dp[t] = std::max(dp[t], dp[t - c] + 1);
            }
        }
    }
    if (dp[target] <= 0) return "0";
    int remaining = dp[target];
    std::string result;
    while (remaining > 0) {
        for (int d = 9; d >= 1; --d) {
            int c = cost[d - 1];
            if (target >= c && dp[target - c] == remaining - 1) {
                result.push_back('0' + d);
                target -= c;
                --remaining;
                break;
            }
        }
    }
    return result;
}

