int maxVowels(const std::string& s, int k) {
    static const std::unordered_set<char> vowels = {'a', 'e', 'i', 'o', 'u'};
    int windowCount = 0;
    for (int i = 0; i < k; ++i) {
        if (vowels.find(s[i]) != vowels.end()) ++windowCount;
    }
    int maxCount = windowCount;
    for (int i = k; i < static_cast<int>(s.size()); ++i) {
        if (vowels.find(s[i]) != vowels.end()) ++windowCount;
        if (vowels.find(s[i - k]) != vowels.end()) --windowCount;
        if (windowCount > maxCount) maxCount = windowCount;
    }
    return maxCount;
}

