std::vector<int> peopleIndexes(const std::vector<std::vector<std::string>>& favoriteCompanies) {
    std::size_t n = favoriteCompanies.size();
    std::vector<std::unordered_set<std::string>> sets;
    sets.reserve(n);
    for (const auto& list : favoriteCompanies) {
        std::unordered_set<std::string> s;
        s.reserve(list.size() * 2);
        for (const auto& company : list) {
            s.insert(company);
        }
        sets.push_back(std::move(s));
    }

    std::vector<int> result;
    for (std::size_t i = 0; i < n; ++i) {
        bool isSubset = false;
        for (std::size_t j = 0; j < n; ++j) {
            if (i == j) continue;
            if (sets[i].size() > sets[j].size()) continue;
            bool allFound = true;
            for (const auto& elem : sets[i]) {
                if (sets[j].find(elem) == sets[j].end()) {
                    allFound = false;
                    break;
                }
            }
            if (allFound) {
                isSubset = true;
                break;
            }
        }
        if (!isSubset) {
            result.push_back(static_cast<int>(i));
        }
    }
    return result;
}

