int numPoints(const std::vector<std::vector<int>>& darts, int r) {
    const double EPS = 1e-7;
    double r2 = static_cast<double>(r) * r;
    int n = darts.size();
    int best = 1;
    for (int i = 0; i < n; ++i) {
        // Center at point i
        double cx = darts[i][0];
        double cy = darts[i][1];
        int cnt = 0;
        for (int k = 0; k < n; ++k) {
            double dx = darts[k][0] - cx;
            double dy = darts[k][1] - cy;
            if (dx * dx + dy * dy <= r2 + EPS) ++cnt;
        }
        best = std::max(best, cnt);
    }
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            double x1 = darts[i][0], y1 = darts[i][1];
            double x2 = darts[j][0], y2 = darts[j][1];
            double dx = x2 - x1;
            double dy = y2 - y1;
            double d2 = dx * dx + dy * dy;
            double d = std::sqrt(d2);
            if (d > 2.0 * r + EPS) continue;
            // midpoint
            double mx = (x1 + x2) / 2.0;
            double my = (y1 + y2) / 2.0;
            // distance from midpoint to centers
            double h = std::sqrt(std::max(0.0, r2 - (d / 2.0) * (d / 2.0)));
            // unit perpendicular vector
            double ux = -dy / d;
            double uy = dx / d;
            for (int sign = -1; sign <= 1; sign += 2) {
                double cx = mx + ux * h * sign;
                double cy = my + uy * h * sign;
                int cnt = 0;
                for (int k = 0; k < n; ++k) {
                    double dxk = darts[k][0] - cx;
                    double dyk = darts[k][1] - cy;
                    if (dxk * dxk + dyk * dyk <= r2 + EPS) ++cnt;
                }
                best = std::max(best, cnt);
            }
        }
    }
    return best;
}

