int isPrefixOfWord(const std::string& sentence, const std::string& searchWord) {
    size_t i = 0;
    int wordIdx = 1;
    while (i < sentence.size()) {
        size_t start = i;
        while (i < sentence.size() &&
               sentence[i] != ' ' &&
               i - start < searchWord.size() &&
               sentence[i] == searchWord[i - start]) {
            ++i;
        }
        if (i - start == searchWord.size()) {
            return wordIdx;
        }
        while (i < sentence.size() && sentence[i] != ' ') {
            ++i;
        }
        if (i < sentence.size() && sentence[i] == ' ') {
            ++i;
        }
        ++wordIdx;
    }
    return -1;
}

