static void dfs(TreeNode* node, uint32_t mask, int& result) {
    if (!node) return;
    mask ^= 1u << node->val;
    if (!node->left && !node->right) {
        if ((mask & (mask - 1)) == 0) ++result;
        return;
    }
    dfs(node->left, mask, result);
    dfs(node->right, mask, result);
}

