double maxDotProduct(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    int m = static_cast<int>(nums1.size());
    int n = static_cast<int>(nums2.size());
    std::vector<double> dp(n + 1, -std::numeric_limits<double>::infinity());
    for (int i = 1; i <= m; ++i) {
        std::vector<double> newRow(n + 1, -std::numeric_limits<double>::infinity());
        double prevDiag = -std::numeric_limits<double>::infinity();
        for (int j = 1; j <= n; ++j) {
            double prod = static_cast<double>(nums1[i - 1]) * static_cast<double>(nums2[j - 1]);
            double best = std::max({prevDiag + prod, prod, dp[j], newRow[j - 1]});
            newRow[j] = best;
            prevDiag = dp[j];
        }
        dp = std::move(newRow);
    }
    return dp[n];
}

