int maxArea(int h, int w, std::vector<int> horizontalCuts, std::vector<int> verticalCuts) {
    const int64_t MOD = 1000000007LL;
    std::sort(horizontalCuts.begin(), horizontalCuts.end());
    std::sort(verticalCuts.begin(), verticalCuts.end());

    int64_t maxHeight = horizontalCuts[0];
    for (size_t i = 1; i < horizontalCuts.size(); ++i) {
        int64_t gap = static_cast<int64_t>(horizontalCuts[i]) - horizontalCuts[i - 1];
        if (gap > maxHeight) maxHeight = gap;
    }
    int64_t lastHeightGap = static_cast<int64_t>(h) - horizontalCuts.back();
    if (lastHeightGap > maxHeight) maxHeight = lastHeightGap;

    int64_t maxWidth = verticalCuts[0];
    for (size_t i = 1; i < verticalCuts.size(); ++i) {
        int64_t gap = static_cast<int64_t>(verticalCuts[i]) - verticalCuts[i - 1];
        if (gap > maxWidth) maxWidth = gap;
    }
    int64_t lastWidthGap = static_cast<int64_t>(w) - verticalCuts.back();
    if (lastWidthGap > maxWidth) maxWidth = lastWidthGap;

    int64_t area = (maxHeight % MOD) * (maxWidth % MOD) % MOD;
    return static_cast<int>(area);
}

