int cherryPickup(const std::vector<std::vector<int>>& grid) {
    int rows = static_cast<int>(grid.size());
    int cols = static_cast<int>(grid[0].size());
    const int NEG_INF = INT_MIN / 2;

    std::vector<std::vector<int>> dp(cols, std::vector<int>(cols, NEG_INF));
    dp[0][cols - 1] = grid[0][0] + (cols == 1 ? 0 : grid[0][cols - 1]);

    for (int r = 1; r < rows; ++r) {
        std::vector<std::vector<int>> next(cols, std::vector<int>(cols, NEG_INF));
        for (int c1 = 0; c1 < cols; ++c1) {
            for (int c2 = 0; c2 < cols; ++c2) {
                if (dp[c1][c2] == NEG_INF) continue;
                for (int d1 = -1; d1 <= 1; ++d1) {
                    int nc1 = c1 + d1;
                    if (nc1 < 0 || nc1 >= cols) continue;
                    for (int d2 = -1; d2 <= 1; ++d2) {
                        int nc2 = c2 + d2;
                        if (nc2 < 0 || nc2 >= cols) continue;
                        int add = grid[r][nc1];
                        if (nc1 != nc2) add += grid[r][nc2];
                        next[nc1][nc2] = std::max(next[nc1][nc2], dp[c1][c2] + add);
                    }
                }
            }
        }
        dp = std::move(next);
    }

    int ans = 0;
    for (int c1 = 0; c1 < cols; ++c1) {
        for (int c2 = 0; c2 < cols; ++c2) {
            ans = std::max(ans, dp[c1][c2]);
        }
    }
    return ans;
}

#include <bits/stdc++.h>
double getProbability(std::vector<int> balls) {
    int k = static_cast<int>(balls.size());
    int total = 0;
    for (int v : balls) total += v;
    int n = total / 2;
    std::vector<long double> fact(total + 1);
    fact[0] = 1;
    for (int i = 1; i <= total; ++i) fact[i] = fact[i - 1] * i;
    auto C = [&](int a, int b) -> long double {
        if (b < 0 || b > a) return 0;
        return fact[a] / (fact[b] * fact[a - b]);
    };
    int offset = k;
    std::vector<std::vector<long double>> dp(total + 1, std::vector<long double>(2 * k + 1, 0));
    dp[0][offset] = 1.0L;
    for (int cnt : balls) {
        std::vector<std::vector<long double>> ndp(total + 1, std::vector<long double>(2 * k + 1, 0));
        for (int taken = 0; taken <= total; ++taken) {
            for (int diff = -k; diff <= k; ++diff) {
                long double cur = dp[taken][diff + offset];
                if (cur == 0) continue;
                if (taken + cnt <= total && diff + 1 <= k)
                    ndp[taken + cnt][diff + 1 + offset] += cur;
                if (diff - 1 >= -k)
                    ndp[taken][diff - 1 + offset] += cur;
                for (int x = 1; x < cnt; ++x) {
                    if (taken + x > total) break;
                    ndp[taken + x][diff + offset] += cur * C(cnt, x);
                }
            }
        }
        dp.swap(ndp);
    }
    long double favorable = dp[n][offset];
    long double totalWays = C(total, n);
    double prob = static_cast<double>(favorable / totalWays);
    return std::round(prob * 1e5) / 1e5;
}

