bool hasAllCodes(const std::string& s, int k) {
    std::size_t totalCodes = 1u << k;
    if (s.length() < static_cast<std::size_t>(k)) return false;

    std::vector<std::uint8_t> seen(totalCodes);
    std::size_t hash = 0;

    for (int i = 0; i < k; ++i) {
        hash = (hash << 1) | static_cast<std::size_t>(s[i] - '0');
    }
    seen[hash] = 1;
    std::size_t found = 1;

    std::size_t mask = totalCodes - 1;

    for (std::size_t i = k; i < s.length(); ++i) {
        hash = ((hash << 1) & mask) | static_cast<std::size_t>(s[i] - '0');
        if (!seen[hash]) {
            seen[hash] = 1;
            if (++found == totalCodes) return true;
        }
    }
    return found == totalCodes;
}

