int minReorder(int n, const std::vector<std::vector<int>>& connections) {
    std::vector<std::vector<std::pair<int, int>>> adj(n);
    for (const auto& conn : connections) {
        int a = conn[0];
        int b = conn[1];
        adj[a].push_back({b, 1}); // original direction a->b needs reversal when moving from a
        adj[b].push_back({a, 0}); // reverse direction b->a is already correct
    }

    std::vector<bool> visited(n, false);
    int changes = 0;
    std::vector<int> stack;
    stack.push_back(0);
    visited[0] = true;

    while (!stack.empty()) {
        int node = stack.back();
        stack.pop_back();
        for (const auto& edge : adj[node]) {
            int next = edge.first;
            int needReverse = edge.second;
            if (!visited[next]) {
                changes += needReverse;
                visited[next] = true;
                stack.push_back(next);
            }
        }
    }
    return changes;
}

