    void visit(std::string url) {
        history.resize(curr+1);
        history.push_back(url);
        curr++;
    }
    std::string back(int steps) {
        curr = (size_t)std::max(0, (int)curr - steps);
        return history[curr];
    }
    std::string forward(int steps) {
        curr = std::min(history.size()-1, curr + (size_t)steps);
        return history[curr];
