long long minCost(const std::vector<int>& houses, const std::vector<std::vector<int>>& cost, int m, int n, int target) {
    const long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<std::vector<long long>> dpPrev(target + 1, std::vector<long long>(n + 1, INF));
    std::vector<std::vector<long long>> dpCur(target + 1, std::vector<long long>(n + 1, INF));

    if (houses[0] != 0) {
        dpPrev[1][houses[0]] = 0;
    } else {
        for (int c = 1; c <= n; ++c) dpPrev[1][c] = cost[0][c - 1];
    }

    for (int i = 1; i < m; ++i) {
        for (int t = 1; t <= target; ++t) {
            std::fill(dpCur[t].begin(), dpCur[t].end(), INF);
        }

        std::vector<int> allowed;
        if (houses[i] != 0) {
            allowed.push_back(houses[i]);
        } else {
            allowed.reserve(n);
            for (int c = 1; c <= n; ++c) allowed.push_back(c);
        }

        for (int t = 1; t <= target; ++t) {
            long long best1 = INF, best2 = INF;
            int bestColor = -1;
            if (t > 1) {
                for (int c = 1; c <= n; ++c) {
                    long long val = dpPrev[t - 1][c];
                    if (val < best1) {
                        best2 = best1;
                        best1 = val;
                        bestColor = c;
                    } else if (val < best2) {
                        best2 = val;
                    }
                }
            }

            for (int curC : allowed) {
                long long add = (houses[i] == 0) ? cost[i][curC - 1] : 0;
                long long cand = dpPrev[t][curC];
                if (t > 1) {
                    long long diff = (curC == bestColor) ? best2 : best1;
                    if (diff < cand) cand = diff;
                }
                if (cand != INF) {
                    long long total = cand + add;
                    if (total < dpCur[t][curC]) dpCur[t][curC] = total;
                }
            }
        }
        dpPrev.swap(dpCur);
    }

    long long ans = INF;
    for (int c = 1; c <= n; ++c) ans = std::min(ans, dpPrev[target][c]);
    return ans == INF ? -1 : ans;
}

