std::vector<int> strongestValues(const std::vector<int>& arr, int k) {
    int n = static_cast<int>(arr.size());
    std::vector<int> sorted = arr;
    std::sort(sorted.begin(), sorted.end());
    int centre = sorted[(n - 1) / 2];
    std::vector<int> result;
    result.reserve(k);
    int l = 0, r = n - 1;
    while (static_cast<int>(result.size()) < k) {
        int leftDist = std::abs(sorted[l] - centre);
        int rightDist = std::abs(sorted[r] - centre);
        if (rightDist > leftDist) {
            result.push_back(sorted[r--]);
        } else if (leftDist > rightDist) {
            result.push_back(sorted[l++]);
        } else {
            if (sorted[r] > sorted[l]) {
                result.push_back(sorted[r--]);
            } else {
                result.push_back(sorted[l++]);
            }
        }
    }
    return result;
}

