int minSumOfLengths(const std::vector<int>& arr, int target) {
    std::size_t n = arr.size();
    const long long INF = LLONG_MAX;
    std::vector<long long> minLenEndingAt(n, INF);
    std::vector<long long> minLenStartingAt(n, INF);
    long long sum = 0;
    std::size_t left = 0;
    for (std::size_t right = 0; right < n; ++right) {
        sum += arr[right];
        while (sum > target && left <= right) {
            sum -= arr[left++];
        }
        if (sum == target) {
            long long len = static_cast<long long>(right - left + 1);
            minLenEndingAt[right] = len;
            minLenStartingAt[left] = len;
        }
    }
    std::vector<long long> bestPrefix(n, INF);
    for (std::size_t i = 0; i < n; ++i) {
        bestPrefix[i] = (i == 0) ? minLenEndingAt[i] : std::min(bestPrefix[i - 1], minLenEndingAt[i]);
    }
    std::vector<long long> bestSuffix(n, INF);
    for (std::size_t i = n; i-- > 0;) {
        bestSuffix[i] = (i == n - 1) ? minLenStartingAt[i] : std::min(bestSuffix[i + 1], minLenStartingAt[i]);
    }
    long long answer = INF;
    for (std::size_t i = 0; i + 1 < n; ++i) {
        if (bestPrefix[i] < INF && bestSuffix[i + 1] < INF) {
            answer = std::min(answer, bestPrefix[i] + bestSuffix[i + 1]);
        }
    }
    return answer == INF ? -1 : static_cast<int>(answer);
}

#include <bits/stdc++.h>

long long allocateMailboxes(std::vector<int> houses, int k) {
    std::sort(houses.begin(), houses.end());
    int n = static_cast<int>(houses.size());
    if (k >= n) return 0;
    std::vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        prefix[i + 1] = prefix[i] + houses[i];
    }
    auto cost = [&](int i, int j) -> long long {
        int mid = (i + j) / 2;
        long long left = static_cast<long long>(houses[mid]) * (mid - i) - (prefix[mid] - prefix[i]);
        long long right = (prefix[j + 1] - prefix[mid + 1]) - static_cast<long long>(houses[mid]) * (j - mid);
        return left + right;
    };
    const long long INF = LLONG_MAX / 4;
    std::vector<long long> prev(n, INF), cur(n, INF);
    for (int i = 0; i < n; ++i) {
        prev[i] = cost(0, i);
    }
    for (int m = 2; m <= k; ++m) {
        for (int i = m - 1; i < n; ++i) {
            long long best = INF;
            for (int p = m - 2; p < i; ++p) {
                long long curCost = prev[p] + cost(p + 1, i);
                if (curCost < best) best = curCost;
            }
            cur[i] = best;
        }
        std::fill(prev.begin(), prev.end(), INF);
        std::swap(prev, cur);
    }
    return prev[n - 1];
}

