int xorOperation(int n, int start) {
    std::int64_t a = static_cast<std::int64_t>(start) >> 1;
    std::int64_t b = start & 1;
    auto xor0To = [](std::int64_t k) -> std::int64_t {
        switch (k & 3LL) {
            case 0: return k;
            case 1: return 1;
            case 2: return k + 1;
            default: return 0;
        }
    };
    std::int64_t highXor = xor0To(a + n - 1) ^ xor0To(a - 1);
    return static_cast<int>((highXor << 1) | (b & (n & 1)));
}

