class TreeAncestor {
public:
    int LOG;
    std::vector<std::vector<int>> up;
    TreeAncestor(int n, std::vector<int>& parent) {
        LOG = (int)std::ceil(std::log2(std::max(n,2))) + 1;
        up.assign(LOG, std::vector<int>(n));
        for (int i = 0; i < n; i++) up[0][i] = parent[i];
        for (int j = 1; j < LOG; j++)
            for (int i = 0; i < n; i++) {
                int mid = up[j-1][i];
                up[j][i] = mid == -1 ? -1 : up[j-1][mid];
            }
    }
    int getKthAncestor(int node, int k) {
        for (int j = 0; j < LOG && node != -1; j++) if (k & (1<<j)) node = up[j][node];
        return node;
    }
};

