std::vector<int> avoidFlood(const std::vector<int>& rains) {
    int n = static_cast<int>(rains.size());
    std::vector<int> ans(n, 1);
    std::unordered_map<int, int> lastRainDay;
    std::set<int> dryDays;
    for (int i = 0; i < n; ++i) {
        int lake = rains[i];
        if (lake == 0) {
            dryDays.insert(i);
        } else {
            ans[i] = -1;
            auto itPrev = lastRainDay.find(lake);
            if (itPrev != lastRainDay.end()) {
                int prevDay = itPrev->second;
                auto itDry = dryDays.lower_bound(prevDay + 1);
                if (itDry == dryDays.end() || *itDry >= i) {
                    return std::vector<int>();
                }
                ans[*itDry] = lake;
                dryDays.erase(itDry);
            }
            lastRainDay[lake] = i;
        }
    }
    for (int idx : dryDays) {
        ans[idx] = 1;
    }
    return ans;
}

