struct DSU {
    vector<int> parent, rank;
    DSU(int n = 0) { parent.resize(n); rank.assign(n, 0); for (int i = 0; i < n; ++i) parent[i] = i; }
    int find(int x) { return parent[x] == x ? x : parent[x] = find(parent[x]); }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (rank[a] < rank[b]) std::swap(a, b);
        parent[b] = a;
        if (rank[a] == rank[b]) ++rank[a];
        return true;
    }
};

int mstWeight(int n, const vector<pair<pair<int,int>, pair<int,int>>>& sortedEdges,
              int skipIdx, int forceIdx) {
    DSU dsu(n);
    int total = 0;
    int used = 0;
    if (forceIdx != -1) {
        auto e = sortedEdges[forceIdx];
        if (dsu.unite(e.first.first, e.first.second)) {
            total += e.second.first;
            ++used;
        }
    }
    for (size_t i = 0; i < sortedEdges.size(); ++i) {
        if ((int)i == skipIdx) continue;
        if ((int)i == forceIdx) continue;
        auto e = sortedEdges[i];
        if (dsu.unite(e.first.first, e.first.second)) {
            total += e.second.first;
            ++used;
            if (used == n - 1) break;
        }
    }
    return (used == n - 1) ? total : numeric_limits<int>::max();
}

vector<vector<int>> findCriticalAndPseudoCriticalEdges(int n, vector<vector<int>>& edges) {
    vector<pair<pair<int,int>, pair<int,int>>> edgeList; // ((u,v),(w,idx))
    edgeList.reserve(edges.size());
    for (size_t i = 0; i < edges.size(); ++i) {
        edgeList.push_back({{edges[i][0], edges[i][1]}, {edges[i][2], (int)i}});
    }
    sort(edgeList.begin(), edgeList.end(),
         [](const auto& a, const auto& b){ return a.second.first < b.second.first; });
    int originalWeight = mstWeight(n, edgeList, -1, -1);
    vector<int> critical, pseudo;
    for (size_t i = 0; i < edgeList.size(); ++i) {
        int wSkip = mstWeight(n, edgeList, (int)i, -1);
        if (wSkip > originalWeight) {
            critical.push_back(edgeList[i].second.second);
        } else {
            int wForce = mstWeight(n, edgeList, -1, (int)i);
            if (wForce == originalWeight) {
                pseudo.push_back(edgeList[i].second.second);
            }
        }
    }
    return {critical, pseudo};
}

