bool canArrange(const std::vector<int>& arr, int k) {
    std::unordered_map<int, int> freq;
    for (size_t i = 0; i < arr.size(); ++i) {
        int rem = ((arr[i] % k) + k) % k;
        ++freq[rem];
    }
    if (freq[0] % 2 != 0) return false;
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) return false;
    for (const auto& entry : freq) {
        int rem = entry.first;
        int cnt = entry.second;
        if (rem == 0 || (k % 2 == 0 && rem == k / 2)) continue;
        int complement = k - rem;
        auto it = freq.find(complement);
        int complementCnt = (it != freq.end()) ? it->second : 0;
        if (complementCnt != cnt) return false;
    }
    return true;
}

