long long maxValueOfEquation(const std::vector<std::vector<int>>& points, int k) {
    struct Node { long long x; long long val; };
    std::deque<Node> deque;
    long long best = LLONG_MIN;
    for (size_t i = 0; i < points.size(); ++i) {
        long long xj = points[i][0];
