static const long long MOD = 1000000007LL;

class BIT {
    int n;
    vector<long long> tree;
public:
    BIT(int n_) : n(n_), tree(n_ + 2, 0) {}
    void add(int idx, long long val) {
        for (int i = idx; i <= n; i += i & -i) {
            tree[i] += val;
        }
    }
    long long query(int idx) const {
        long long res = 0;
        for (int i = idx; i > 0; i -= i & -i) {
            res += tree[i];
        }
        return res;
    }
};

static int lowerBound(const vector<long long>& arr, long long key) {
    int l = 0, r = (int)arr.size();
    while (l < r) {
        int mid = (l + r) >> 1;
        if (arr[mid] < key) l = mid + 1;
        else r = mid;
    }
    return l;
}

static pair<long long, long long> countAndSum(const vector<long long>& pref, const vector<long long>& uniq, long long limit) {
    int m = (int)uniq.size();
    BIT bitCnt(m);
    BIT bitSum(m);
    long long totalCnt = 0;
    long long totalSum = 0;
    long long sumPrev = 0;
    for (int j = 0; j < (int)pref.size(); ++j) {
        long long p = pref[j];
        long long target = p - limit;
        int idx = lowerBound(uniq, target);
        int pos = idx; // number of elements < target
        long long cntLess = bitCnt.query(pos);
        long long sumLess = bitSum.query(pos);
        long long cntGe = j - cntLess;
        long long sumGe = sumPrev - sumLess;
        totalCnt += cntGe;
        totalSum += cntGe * p - sumGe;
        int pIdx = lowerBound(uniq, p) + 1;
        bitCnt.add(pIdx, 1);
        bitSum.add(pIdx, p);
        sumPrev += p;
    }
    return {totalCnt, totalSum};
}

static long long prefixSum(const vector<long long>& pref, const vector<long long>& uniq, long long k) {
    if (k <= 0) return 0;
    long long low = 0;
    long long high = pref.back();
    while (low < high) {
        long long mid = (low + high) >> 1;
        long long cnt = countAndSum(pref, uniq, mid).first;
        if (cnt >= k) high = mid;
        else low = mid + 1;
    }
    auto cs = countAndSum(pref, uniq, low);
    long long cnt = cs.first;
    long long sum = cs.second;
    long long extra = cnt - k;
    sum -= extra * low;
    return sum;
}

int rangeSum(const vector<int>& nums, int n, int left, int right) {
    vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        pref[i + 1] = pref[i] + nums[i];
    }
    vector<long long> uniq = pref;
    std::sort(uniq.begin(), uniq.end());
    int m = 0;
    for (int i = 0; i < (int)uniq.size(); ++i) {
        if (i == 0 || uniq[i] != uniq[i - 1]) {
            uniq[m++] = uniq[i];
        }
    }
    uniq.resize(m);
    long long sumRight = prefixSum(pref, uniq, right);
    long long sumLeft = prefixSum(pref, uniq, (long long)left - 1);
    long long ans = (sumRight - sumLeft) % MOD;
    if (ans < 0) ans += MOD;
    return (int)ans;
}

