    }

    std::vector<int> ans(n, 0);
    std::vector<char> visited(n, 0);

    std::function<std::array<int, 26>(int)> dfs = [&](int u) -> std::array<int, 26> {
        visited[u] = 1;
        std::array<int, 26> cnt;
        cnt.fill(0);
        int idx = labels[u] - 'a';
        cnt[idx] = 1;
        for (int v : g[u]) {
            if (!visited[v]) {
                std::array<int, 26> childCnt = dfs(v);
                for (int i = 0; i < 26; ++i) {
                    cnt[i] += childCnt[i];
                }
            }
        }
        ans[u] = cnt[idx];
        return cnt;
    };

    dfs(0);
    return ans;
}

#include <bits/stdc++.h>

double getMinDistSum(const std::vector<std::vector<int>>& positions) {
    int n = positions.size();
    if (n == 0) return 0.0;
    double x = 0.0, y = 0.0;
    for (const auto& p : positions) {
        x += p[0];
        y += p[1];
    }
    x /= n;
    y /= n;
    const double eps = 1e-7;
    for (int iter = 0; iter < 10000; ++iter) {
        double numX = 0.0, numY = 0.0, denom = 0.0;
        bool coincident = false;
        for (const auto& p : positions) {
            double dx = x - p[0];
            double dy = y - p[1];
            double dist = std::sqrt(dx * dx + dy * dy);
            if (dist < eps) {
                coincident = true;
                break;
            }
            double w = 1.0 / dist;
            numX += p[0] * w;
            numY += p[1] * w;
            denom += w;
        }
        if (coincident) break;
        double newX = numX / denom;
        double newY = numY / denom;
        if (std::hypot(newX - x, newY - y) < eps) {
            x = newX;
            y = newY;
            break;
        }
        x = newX;
        y = newY;
    }
    double total = 0.0;
    for (const auto& p : positions) {
        double dx = x - p[0];
        double dy = y - p[1];
        total += std::sqrt(dx * dx + dy * dy);
    }
    total = std::round(total * 100000.0) / 100000.0;
    return total;
}

