std::vector<std::string> maxNumOfSubstrings(const std::string& s) {
    const int INF = static_cast<int>(s.size()) + 1;
    int left[26];
    int right[26];
    for (int i = 0; i < 26; ++i) {
        left[i] = INF;
        right[i] = -1;
    }
    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        int c = s[i] - 'a';
        left[c] = std::min(left[c], i);
        right[c] = std::max(right[c], i);
    }
    std::vector<std::pair<int, int>> intervals;
    intervals.reserve(26);
    for (int c = 0; c < 26; ++c) {
        if (right[c] == -1) continue;
        int l = left[c];
        int r = right[c];
        bool ok = true;
        int i = l;
        while (i <= r) {
            int ch = s[i] - 'a';
            if (left[ch] < l) {
                ok = false;
                break;
            }
            r = std::max(r, right[ch]);
            ++i;
        }
        if (ok) intervals.emplace_back(l, r);
    }
    std::sort(intervals.begin(), intervals.end(),
              [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
                  return a.second < b.second;
              });
    std::vector<std::pair<int, int>> chosen;
    int prev_end = -1;
    for (const auto& p : intervals) {
        if (p.first > prev_end) {
            chosen.push_back(p);
            prev_end = p.second;
        }
    }
    std::sort(chosen.begin(), chosen.end(),
              [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
                  int lenA = a.second - a.first + 1;
                  int lenB = b.second - b.first + 1;
                  if (lenA != lenB) return lenA < lenB;
                  return a.first < b.first;
              });
    std::vector<std::string> result;
    result.reserve(chosen.size());
    for (const auto& p : chosen) {
        result.push_back(s.substr(p.first, p.second - p.first + 1));
    }
    return result;
}

