int numberOfGoodSplits(const std::string& s) {
    int n = static_cast<int>(s.size());
    if (n < 2) return 0;
    std::vector<int> suffix(n);
    std::array<bool, 26> seenRight{};
    int distinctRight = 0;
    for (int i = n - 1; i >= 0; --i) {
        int idx = s[i] - 'a';
        if (!seenRight[idx]) {
            seenRight[idx] = true;
            ++distinctRight;
        }
        suffix[i] = distinctRight;
    }
    std::array<bool, 26> seenLeft{};
    int distinctLeft = 0;
    int goodSplits = 0;
    for (int i = 1; i < n; ++i) {
        int idx = s[i - 1] - 'a';
        if (!seenLeft[idx]) {
            seenLeft[idx] = true;
            ++distinctLeft;
        }
        if (distinctLeft == suffix[i]) ++goodSplits;
    }
    return goodSplits;
}

