int minSwaps(const std::vector<std::vector<int>>& grid) {
    int n = static_cast<int>(grid.size());
    std::vector<int> rightmostOne(n);
    for (int i = 0; i < n; ++i) {
        int pos = -1;
        for (int j = n - 1; j >= 0; --j) {
            if (grid[i][j] == 1) {
                pos = j;
                break;
            }
        }
        rightmostOne[i] = pos;
    }

    int swaps = 0;
    for (int i = 0; i < n; ++i) {
        int j = i;
        while (j < n && rightmostOne[j] > i) {
            ++j;
        }
        if (j == n) {
            return -1;
        }
        while (j > i) {
            int tmp = rightmostOne[j];
            rightmostOne[j] = rightmostOne[j - 1];
            rightmostOne[j - 1] = tmp;
            ++swaps;
            --j;
        }
    }
    return swaps;
}

