struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

int countPairs(TreeNode* root, int distance) {
    int goodPairs = 0;
    std::function<std::vector<int>(TreeNode*)> dfs = [&](TreeNode* node) -> std::vector<int> {
        if (!node) return {};
        if (!node->left && !node->right) return {1};

        std::vector<int> leftDist = dfs(node->left);
        std::vector<int> rightDist = dfs(node->right);

        for (int l : leftDist) {
            for (int r : rightDist) {
                if (l + r <= distance) ++goodPairs;
            }
        }

        std::vector<int> curDist;
        for (int d : leftDist) {
            if (d + 1 <= distance) curDist.push_back(d + 1);
        }
        for (int d : rightDist) {
            if (d + 1 <= distance) curDist.push_back(d + 1);
        }
        return curDist;
    };
    dfs(root);
    return goodPairs;
}

#include <bits/stdc++.h>
int getLengthOfOptimalCompression(const std::string& s, int k) {
    int n = s.size();
    const int INF = 1e9;
    auto digit = [](int cnt) {
        if (cnt >= 100) return 3;
        if (cnt >= 10) return 2;
        return 1;
    };
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(k + 1, INF));
    for (int j = 0; j <= k; ++j) dp[0][j] = 0;
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= k; ++j) {
            if (j > 0) dp[i][j] = std::min(dp[i][j], dp[i - 1][j - 1]);
            int cnt = 0, del_needed = 0;
            for (int p = i; p >= 1; --p) {
                if (s[p - 1] == s[i - 1]) ++cnt;
                else ++del_needed;
                if (del_needed > j) break;
                int prev = dp[p - 1][j - del_needed];
                int add = 1 + (cnt > 1 ? digit(cnt) : 0);
                dp[i][j] = std::min(dp[i][j], prev + add);
                if (cnt >= 100) break;
            }
        }
    }
    int ans = INF;
    for (int j = 0; j <= k; ++j) ans = std::min(ans, dp[n][j]);
    return ans;
}

