long long maxScore(const std::vector<long long>& nums1, const std::vector<long long>& nums2) {
    const long long MOD = 1000000007LL;
    std::size_t i = 0, j = 0;
    long long sum1 = 0, sum2 = 0, ans = 0;

    while (i < nums1.size() && j < nums2.size()) {
        if (nums1[i] < nums2[j]) {
            sum1 += nums1[i++];
        } else if (nums1[i] > nums2[j]) {
            sum2 += nums2[j++];
        } else {
            ans = (ans + std::max(sum1, sum2) + nums1[i]) % MOD;
            sum1 = 0;
            sum2 = 0;
            ++i;
            ++j;
        }
    }

    while (i < nums1.size()) sum1 += nums1[i++];
    while (j < nums2.size()) sum2 += nums2[j++];

    ans = (ans + std::max(sum1, sum2)) % MOD;
