int findKthMissingPositive(const std::vector<int>& arr, int k) {
    int left = 0;
    int right = static_cast<int>(arr.size()) - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        int missing = arr[mid] - (mid + 1);
        if (missing < k) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    if (left == static_cast<int>(arr.size())) {
        int totalMissing = arr.back() - static_cast<int>(arr.size());
        return arr.back() + (k - totalMissing);
    }
    int missingAtLeft = arr[left] - (left + 1);
    return arr[left] - (missingAtLeft - k + 1);
}

