int minCost(int n, std::vector<int> cuts) {
    std::vector<int> pos;
    pos.reserve(cuts.size() + 2);
    pos.push_back(0);
    std::sort(cuts.begin(), cuts.end());
    pos.insert(pos.end(), cuts.begin(), cuts.end());
    pos.push_back(n);
    int m = static_cast<int>(pos.size());
    std::vector<std::vector<long long>> dp(m, std::vector<long long>(m, 0));
    std::vector<std::vector<int>> opt(m, std::vector<int>(m, 0));
    for (int i = 0; i + 1 < m; ++i) opt[i][i + 1] = i + 1;
    for (int len = 2; len < m; ++len) {
        for (int i = 0; i + len < m; ++i) {
            int j = i + len;
            long long best = LLONG_MAX;
            int start = opt[i][j - 1];
            int end = opt[i + 1][j];
            if (start < i + 1) start = i + 1;
            if (end > j - 1) end = j - 1;
            int bestk = start;
            for (int k = start; k <= end; ++k) {
                long long cost = dp[i][k] + dp[k][j] + static_cast<long long>(pos[j] - pos[i]);
                if (cost < best) {
                    best = cost;
                    bestk = k;
                }
            }
            dp[i][j] = best;
            opt[i][j] = bestk;
        }
    }
    return static_cast<int>(dp[0][m - 1]);
}

