std::string findKthBit(int n, int k) {
    std::function<char(int, long long)> solve = [&](int level, long long pos) -> char {
        if (level == 1) return '0';
        long long mid = 1LL << (level - 1);
        if (pos == mid) return '1';
        if (pos < mid) return solve(level - 1, pos);
        // right side: mirror and invert
        char mirrored = solve(level - 1, (1LL << level) - pos);
        return (mirrored == '0') ? '1' : '0';
    };
    char ans = solve(n, k);
    return std::string(1, ans);
}

