long long minDays(long long n) {
    static std::unordered_map<long long, long long> memo{{0, 0}, {1, 1}};
    auto dfs = [&](auto&& self, long long x) -> long long {
        auto it = memo.find(x);
        if (it != memo.end()) return it->second;
        long long daysVia2 = x % 2 + self(self, x / 2);
        long long daysVia3 = x % 3 + self(self, x / 3);
        long long res = 1 + std::min(daysVia2, daysVia3);
        memo[x] = res;
        return res;
    };
    return dfs(dfs, n);
}

