int stoneGameV(std::vector<int>& stoneValue) {
    int n = stoneValue.size();
    if (n <= 1) return 0;
    std::vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + stoneValue[i];
    std::vector<std::vector<long long>> dp(n, std::vector<long long>(n, 0));
    for (int len = 2; len <= n; ++len) {
        for (int l = 0; l + len - 1 < n; ++l) {
            int r = l + len - 1;
            int lo = l, hi = r - 1;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                long long left = pref[mid + 1] - pref[l];
                long long right = pref[r + 1] - pref[mid + 1];
                if (left < right) lo = mid + 1;
                else hi = mid;
            }
            auto eval = [&](int k) -> long long {
                long long left = pref[k + 1] - pref[l];
                long long right = pref[r + 1] - pref[k + 1];
                if (left < right) return left + dp[l][k];
                if (left > right) return right + dp[k + 1][r];
                return left + std::max(dp[l][k], dp[k + 1][r]);
            };
            long long best = eval(lo);
            if (lo - 1 >= l) best = std::max(best, eval(lo - 1));
            dp[l][r] = best;
        }
    }
    return static_cast<int>(dp[0][n - 1]);
}

#include <bits/stdc++.h>
#include <vector>
#include <stack>
#include <tuple>

bool containsCycle(std::vector<std::vector<char>>& grid) {
    int m = static_cast<int>(grid.size());
    if (m == 0) return false;
    int n = static_cast<int>(grid[0].size());
    std::vector<std::vector<char>> visited(m, std::vector<char>(n, 0));
    const int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (visited[i][j]) continue;
            std::stack<std::tuple<int,int,int,int>> st;
            st.emplace(i, j, -1, -1);
            while (!st.empty()) {
                int x, y, px, py;
                std::tie(x, y, px, py) = st.top();
                st.pop();
                if (visited[x][y]) continue;
                visited[x][y] = 1;
                for (const auto& d : dirs) {
                    int nx = x + d[0];
                    int ny = y + d[1];
                    if (nx < 0 || nx >= m || ny < 0 || ny >= n) continue;
                    if (grid[nx][ny] != grid[x][y]) continue;
                    if (!visited[nx][ny]) {
                        st.emplace(nx, ny, x, y);
                    } else if (!(nx == px && ny == py)) {
                        return true;
                    }
                }
            }
        }
    }
    return false;
}

