            result.push_back(i);
        }
        for (int i = start; i <= n; ++i) {
            result.push_back(i);
        }
    }
    return result;
}

#include <bits/stdc++.h>

int minDays(std::vector<std::vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();
    int totalLand = 0;
    for (auto& row : grid)
        for (int v : row)
            if (v == 1) ++totalLand;

    auto countIslands = [&]() -> int {
        std::vector<std::vector<bool>> visited(m, std::vector<bool>(n, false));
        int islands = 0;
        const int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};
        std::vector<std::pair<int,int>> stack;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] == 1 && !visited[i][j]) {
                    ++islands;
                    stack.emplace_back(i, j);
                    visited[i][j] = true;
                    while (!stack.empty()) {
                        int x = stack.back().first;
                        int y = stack.back().second;
                        stack.pop_back();
                        for (const auto& d : dirs) {
                            int nx = x + d[0];
                            int ny = y + d[1];
                            if (nx >= 0 && nx < m && ny >= 0 && ny < n &&
                                grid[nx][ny] == 1 && !visited[nx][ny]) {
                                visited[nx][ny] = true;
                                stack.emplace_back(nx, ny);
                            }
                        }
                    }
                }
            }
        }
        return islands;
    };

    if (countIslands() != 1) return 0;
    if (totalLand <= 2) return totalLand;

    int N = m * n;
    std::vector<int> disc(N, -1), low(N, -1), parent(N, -1);
    std::vector<bool> isArt(N, false);
    int timer = 0;
    const int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};

    std::function<void(int,int,int)> dfs = [&](int u, int ux, int uy) {
        disc[u] = low[u] = timer++;
        int children = 0;
        for (const auto& d : dirs) {
            int vx = ux + d[0];
            int vy = uy + d[1];
            if (vx < 0 || vx >= m || vy < 0 || vy >= n) continue;
            if (grid[vx][vy] != 1) continue;
            int v = vx * n + vy;
            if (disc[v] == -1) {
                parent[v] = u;
                ++children;
                dfs(v, vx, vy);
                low[u] = std::min(low[u], low[v]);
                if (parent[u] == -1 && children > 1) isArt[u] = true;
                if (parent[u] != -1 && low[v] >= disc[u]) isArt[u] = true;
            } else if (v != parent[u]) {
                low[u] = std::min(low[u], disc[v]);
            }
        }
    };

    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 1) {
                int id = i * n + j;
                if (disc[id] == -1) {
                    dfs(id, i, j);
                }
            }
        }
    }

    for (bool b : isArt) if (b) return 1;
    return 2;
}

