int findLatestStep(std::vector<int>& arr, int m) {
    int n = static_cast<int>(arr.size());
    if (m == n) return n;
    std::vector<int> length(n + 2, 0);
    std::vector<int> cnt(n + 1, 0);
    int answer = -1;
    for (int i = 0; i < n; ++i) {
        int p = arr[i];
        int left = length[p - 1];
        int right = length[p + 1];
        int cur = left + right + 1;
        length[p - left] = cur;
        length[p + right] = cur;
        if (left > 0) --cnt[left];
        if (right > 0) --cnt[right];
        ++cnt[cur];
        if (cnt[m] > 0) answer = i + 1;
    }
    return answer;
}

#include <bits/stdc++.h>
const int MOD = 1000000007;

long long modPow(long long a, long long e) {
    long long res = 1;
    while (e) {
        if (e & 1) res = res * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return res;
}

std::vector<long long> fact, invFact;

long long comb(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
}

long long dfs(const std::vector<int>& seq) {
    if (seq.size() <= 2) return 1LL;
    int root = seq[0];
    std::vector<int> left, right;
    left.reserve(seq.size());
    right.reserve(seq.size());
    for (size_t i = 1; i < seq.size(); ++i) {
        if (seq[i] < root) left.push_back(seq[i]);
        else right.push_back(seq[i]);
    }
    long long leftWays = dfs(left);
    long long rightWays = dfs(right);
    long long ways = leftWays * rightWays % MOD;
    ways = ways * comb(static_cast<int>(left.size() + right.size()), static_cast<int>(left.size())) % MOD;
    return ways;
}

int numberOfWays(std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    fact.assign(n + 1, 1);
    for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i % MOD;
    invFact.assign(n + 1, 1);
    invFact[n] = modPow(fact[n], MOD - 2);
    for (int i = n; i > 0; --i) invFact[i - 1] = invFact[i] * i % MOD;
    long long totalWays = dfs(nums);
    totalWays = (totalWays - 1 + MOD) % MOD;
    return static_cast<int>(totalWays);
}

#include <bits/stdc++.h>
#include <vector>

bool detectPattern(const std::vector<int>& arr, int m, int k) {
    int n = static_cast<int>(arr.size());
    if (static_cast<long long>(m) * k > n) return false;

    const long long MOD = 1000000007LL;
    const long long BASE = 1000003LL;

    std::vector<long long> prefix(n + 1, 0);
    std::vector<long long> power(n + 1, 1);
    for (int i = 0; i < n; ++i) {
        prefix[i + 1] = (prefix[i] * BASE + arr[i]) % MOD;
        power[i + 1] = (power[i] * BASE) % MOD;
    }

    auto getHash = [&](int l, int r) -> long long {
        long long val = (prefix[r] - (prefix[l] * power[r - l]) % MOD + MOD) % MOD;
        return val;
    };

    std::vector<int> repeat(n, 0);
    for (int i = n - m; i >= 0; --i) {
        if (i + 2 * m <= n && getHash(i, i + m) == getHash(i + m, i + 2 * m)) {
            repeat[i] = repeat[i + m] + 1;
        } else {
            repeat[i] = 1;
        }
        if (repeat[i] >= k) return true;
    }
    return false;
}

