int getMaxLen(const std::vector<int>& nums) {
    int pos = 0;
    int neg = 0;
    int best = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        int x = nums[i];
        if (x > 0) {
            pos = pos + 1;
            neg = (neg > 0) ? neg + 1 : 0;
        } else if (x < 0) {
            int newPos = (neg > 0) ? neg + 1 : 0;
            int newNeg = pos + 1;
            pos = newPos;
            neg = newNeg;
        } else {
            pos = 0;
            neg = 0;
        }
        if (pos > best) best = pos;
    }
    return best;
}

