int countRoutes(const std::vector<int>& locations, int start, int finish, int fuel) {
    const int MOD = 1000000007;
    int n = locations.size();
    std::vector<std::vector<int>> memo(n, std::vector<int>(fuel + 1, -1));

    std::function<int(int, int)> dfs = [&](int city, int remaining) -> int {
        if (memo[city][remaining] != -1) return memo[city][remaining];
        long long ways = (city == finish) ? 1 : 0;
        for (int nxt = 0; nxt < n; ++nxt) {
            if (nxt == city) continue;
            int cost = std::abs(locations[city] - locations[nxt]);
            if (cost <= remaining) {
                ways = (ways + dfs(nxt, remaining - cost)) % MOD;
            }
        }
        memo[city][remaining] = static_cast<int>(ways);
        return memo[city][remaining];
    };

    return dfs(start, fuel);
}

