#include <bits/stdc++.h>

long long numberOfWays(const std::string& s) {
    const long long MOD = 1000000007LL;
    size_t n = s.size();
    long long totalOnes = 0;
    for (char c : s) if (c == '1') ++totalOnes;
    if (totalOnes % 3 != 0) return 0;
    if (totalOnes == 0) {
        long long prod = (n - 1) * (n - 2) / 2;
        return prod % MOD;
    }
    long long target = totalOnes / 3;
    long long onesSeen = 0;
    long long zerosAfterFirst = 0, zerosAfterSecond = 0;
    size_t i = 0;
    while (i < n) {
        if (s[i] == '1') ++onesSeen;
        if (onesSeen == target) {
            ++i;
            while (i < n && s[i] == '0') { ++zerosAfterFirst; ++i; }
            break;
        }
        ++i;
    }
    while (i < n) {
        if (s[i] == '1') ++onesSeen;
        if (onesSeen == 2 * target) {
            ++i;
            while (i < n && s[i] == '0') { ++zerosAfterSecond; ++i; }
            break;
        }
        ++i;
    }
    long long ways = ((zerosAfterFirst + 1) % MOD) * ((zerosAfterSecond + 1) % MOD) % MOD;
    return ways;
}

