int findLengthOfShortestSubarray(const std::vector<int>& arr) {
    int n = static_cast<int>(arr.size());
    int left = 0;
    while (left + 1 < n && arr[left] <= arr[left + 1]) ++left;
    if (left == n - 1) return 0;
    int right = n - 1;
    while (right > 0 && arr[right - 1] <= arr[right]) --right;
    int answer = std::min(n - left - 1, right);
    int i = 0, j = right;
    while (i <= left && j < n) {
        if (arr[i] <= arr[j]) {
            answer = std::min(answer, j - i - 1);
            ++i;
        } else {
            ++j;
        }
    }
    return answer;
}

#include <bits/stdc++.h>

struct DSU {
    std::vector<int> parent;
    std::vector<int> sz;
    int components;
    DSU(int n) : parent(n + 1), sz(n + 1, 1), components(n) {
        for (int i = 1; i <= n; ++i) parent[i] = i;
    }
    int find(int x) {
        return parent[x] == x ? x : parent[x] = find(parent[x]);
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (sz[a] < sz[b]) std::swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
        --components;
        return true;
    }
};

int maxNumEdgesToRemove(int n, const std::vector<std::vector<int>>& edges) {
    DSU alice(n), bob(n);
    int used = 0;
    for (const auto& e : edges) {
        if (e[0] == 3) {
            bool a = alice.unite(e[1], e[2]);
            bool b = bob.unite(e[1], e[2]);
            if (a || b) ++used;
        }
    }
    for (const auto& e : edges) {
        if (e[0] == 1) {
            if (alice.unite(e[1], e[2])) ++used;
        } else if (e[0] == 2) {
            if (bob.unite(e[1], e[2])) ++used;
        }
    }
    if (alice.components != 1 || bob.components != 1) return -1;
    return static_cast<int>(edges.size()) - used;
}

