#include <bits/stdc++.h>
#include <vector>
#include <unordered_map>

long long numTriplets(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    std::unordered_map<long long, long long> freq1;
    std::unordered_map<long long, long long> freq2;
    for (int v : nums1) freq1[v] += 1;
    for (int v : nums2) freq2[v] += 1;

    auto countPairs = [&](long long target, const std::unordered_map<long long, long long>& freq) -> long long {
        long long pairs = 0;
        for (long long d = 1; d * d <= target; ++d) {
            if (target % d != 0) continue;
            long long e = target / d;
            auto itd = freq.find(d);
            auto ite = freq.find(e);
            long long fd = (itd != freq.end()) ? itd->second : 0;
            long long fe = (ite != freq.end()) ? ite->second : 0;
            if (fd && fe) {
                if (d == e) {
                    pairs += fd * (fd - 1) / 2;
                } else {
                    pairs += fd * fe;
                }
            }
        }
        return pairs;
    };

    long long answer = 0;
    for (const auto& kv : freq1) {
        long long val = kv.first;
        long long cnt = kv.second;
        long long target = val * val;
        long long pairCnt = countPairs(target, freq2);
        answer += cnt * pairCnt;
    }
    for (const auto& kv : freq2) {
        long long val = kv.first;
        long long cnt = kv.second;
        long long target = val * val;
        long long pairCnt = countPairs(target, freq1);
        answer += cnt * pairCnt;
    }
    return answer;
}

