int countUnhappyFriends(int n, const std::vector<std::vector<int>>& preferences, const std::vector<std::vector<int>>& pairs) {
    std::vector<int> partner(n);
    for (const auto& p : pairs) {
        int a = p[0];
        int b = p[1];
        partner[a] = b;
        partner[b] = a;
    }

    std::vector<std::vector<int>> rank(n, std::vector<int>(n));
    for (int i = 0; i < n; ++i) {
        const std::vector<int>& list = preferences[i];
        for (int pos = 0; pos < static_cast<int>(list.size()); ++pos) {
            rank[i][list[pos]] = pos;
        }
    }

    std::vector<bool> unhappy(n, false);

    for (const auto& p : pairs) {
        int x = p[0];
        int y = p[1];

        for (int u : preferences[x]) {
            if (u == y) break;
            int v = partner[u];
            if (rank[u][x] < rank[u][v]) {
                unhappy[x] = true;
                break;
            }
        }

        for (int u : preferences[y]) {
            if (u == x) break;
            int v = partner[u];
            if (rank[u][y] < rank[u][v]) {
                unhappy[y] = true;
                break;
            }
        }
    }

    int ans = 0;
    for (bool flag : unhappy) {
        if (flag) ++ans;
    }
    return ans;
}

