bool isTransformable(const std::string& s, const std::string& t) {
    std::size_t n = s.size();
    std::vector<std::vector<std::size_t>> pos(10);
    for (std::size_t i = 0; i < n; ++i) {
        pos[s[i] - '0'].push_back(i);
    }
    std::vector<std::size_t> idx(10, 0);
    std::vector<std::size_t> front(10, static_cast<std::size_t>(-1));
    for (int d = 0; d < 10; ++d) {
        if (!pos[d].empty()) front[d] = pos[d][0];
    }
    for (std::size_t i = 0; i < n; ++i) {
        int need = t[i] - '0';
        if (idx[need] >= pos[need].size()) return false;
        std::size_t cur = pos[need][idx[need]++];
        front[need] = (idx[need] < pos[need].size()) ? pos[need][idx[need]] : static_cast<std::size_t>(-1);
        for (int d = 0; d < need; ++d) {
            if (front[d] != static_cast<std::size_t>(-1) && front[d] < cur) {
                return false;
            }
        }
    }
    return true;
}

