int minSubarray(const std::vector<int>& nums, int p) {
    long long total = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        total = (total + nums[i]) % p;
    }
    int target = static_cast<int>(total);
    if (target == 0) return 0;

    int prefix = 0;
    int best = static_cast<int>(nums.size());
    std::unordered_map<int, int> firstIdx;
    firstIdx[0] = -1;

    for (size_t i = 0; i < nums.size(); ++i) {
        prefix = (prefix + nums[i]) % p;
        int need = (prefix - target + p) % p;
        auto it = firstIdx.find(need);
        if (it != firstIdx.end()) {
            int len = static_cast<int>(i) - it->second;
            if (len < best) best = len;
        }
        firstIdx[prefix] = static_cast<int>(i);
    }
    return best == static_cast<int>(nums.size()) ? -1 : best;
}

