std::string rearrangeSpaces(const std::string& text) {
    int totalSpaces = 0;
    for (char ch : text) {
        if (ch == ' ') ++totalSpaces;
    }

    std::vector<std::string> words;
    std::string cur;
    for (char ch : text) {
        if (ch != ' ') {
            cur.push_back(ch);
        } else {
            if (!cur.empty()) {
                words.push_back(cur);
                cur.clear();
            }
        }
    }
    if (!cur.empty()) {
        words.push_back(cur);
    }

    size_t wordCount = words.size();

    if (wordCount == 1) {
        return words[0] + std::string(totalSpaces, ' ');
    }

    int gapSpaces = totalSpaces / static_cast<int>(wordCount - 1);
    int extraSpaces = totalSpaces % static_cast<int>(wordCount - 1);
    std::string between(gapSpaces, ' ');
    std::string result;
    for (size_t i = 0; i < wordCount; ++i) {
        result += words[i];
        if (i + 1 < wordCount) {
            result += between;
        }
    }
    result += std::string(extraSpaces, ' ');
    return result;
}

