int maxUniqueSplit(const std::string& s) {
    const int n = static_cast<int>(s.size());
    int best = 0;
    std::unordered_set<std::string> used;
    std::function<void(int, int)> dfs = [&](int pos, int cnt) {
        if (pos == n) {
            if (cnt > best) best = cnt;
            return;
        }
        if (cnt + (n - pos) <= best) return;
        for (int i = pos + 1; i <= n; ++i) {
            std::string sub = s.substr(pos, i - pos);
            if (used.find(sub) == used.end()) {
                used.insert(sub);
                dfs(i, cnt + 1);
                used.erase(sub);
            }
        }
    };
    dfs(0, 0);
    return best;
}

#include <bits/stdc++.h>

bool isPrintable(const std::vector<std::vector<int>>& targetGrid) {
    int m = static_cast<int>(targetGrid.size());
    int n = static_cast<int>(targetGrid[0].size());

    int maxColor = 0;
    for (int r = 0; r < m; ++r)
        for (int c = 0; c < n; ++c)
            maxColor = std::max(maxColor, targetGrid[r][c]);

    if (maxColor == 0) return true;

    std::vector<int> minR(maxColor + 1, m), maxR(maxColor + 1, -1);
    std::vector<int> minC(maxColor + 1, n), maxC(maxColor + 1, -1);
    for (int r = 0; r < m; ++r) {
        for (int c = 0; c < n; ++c) {
            int col = targetGrid[r][c];
            if (col == 0) continue;
            minR[col] = std::min(minR[col], r);
            maxR[col] = std::max(maxR[col], r);
            minC[col] = std::min(minC[col], c);
            maxC[col] = std::max(maxC[col], c);
        }
    }

    std::vector<int> colors;
    for (int col = 1; col <= maxColor; ++col) {
        if (maxR[col] != -1) colors.push_back(col);
    }

    int C = static_cast<int>(colors.size());
    std::vector<int> indegree(maxColor + 1, 0);
    std::vector<std::vector<int>> adj(maxColor + 1);
    std::vector<std::vector<char>> hasEdge(maxColor + 1, std::vector<char>(maxColor + 1, 0));

    for (int col : colors) {
        for (int r = minR[col]; r <= maxR[col]; ++r) {
            for (int c = minC[col]; c <= maxC[col]; ++c) {
                int inner = targetGrid[r][c];
                if (inner != col && inner != 0 && !hasEdge[col][inner]) {
                    hasEdge[col][inner] = 1;
                    adj[col].push_back(inner);
                    ++indegree[inner];
                }
            }
        }
    }

    std::queue<int> q;
    for (int col : colors) {
        if (indegree[col] == 0) q.push(col);
    }

    int visited = 0;
    while (!q.empty()) {
        int cur = q.front();
        q.pop();
        ++visited;
        for (int nxt : adj[cur]) {
            if (--indegree[nxt] == 0) q.push(nxt);
        }
    }

    return visited == C;
}

