int maxProductPath(std::vector<std::vector<int>>& grid) {
    const int MOD = 1000000007;
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    std::vector<std::vector<long long>> maxProd(m, std::vector<long long>(n, LLONG_MIN));
    std::vector<std::vector<long long>> minProd(m, std::vector<long long>(n, LLONG_MAX));
    maxProd[0][0] = minProd[0][0] = grid[0][0];
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i == 0 && j == 0) continue;
            long long cur = grid[i][j];
            long long curMax = LLONG_MIN;
            long long curMin = LLONG_MAX;
            if (i > 0) {
                if (maxProd[i - 1][j] != LLONG_MIN) {
                    long long val = cur * maxProd[i - 1][j];
                    curMax = std::max(curMax, val);
                    curMin = std::min(curMin, val);
                }
                if (minProd[i - 1][j] != LLONG_MAX) {
                    long long val = cur * minProd[i - 1][j];
                    curMax = std::max(curMax, val);
                    curMin = std::min(curMin, val);
                }
            }
            if (j > 0) {
                if (maxProd[i][j - 1] != LLONG_MIN) {
                    long long val = cur * maxProd[i][j - 1];
                    curMax = std::max(curMax, val);
                    curMin = std::min(curMin, val);
                }
                if (minProd[i][j - 1] != LLONG_MAX) {
                    long long val = cur * minProd[i][j - 1];
                    curMax = std::max(curMax, val);
                    curMin = std::min(curMin, val);
                }
            }
            maxProd[i][j] = curMax;
            minProd[i][j] = curMin;
        }
    }
    long long ans = maxProd[m - 1][n - 1];
    if (ans < 0) return -1;
    return static_cast<int>(ans % MOD);
}

