long long maxSumRangeQuery(std::vector<int> nums, const std::vector<std::vector<int>>& requests) {
    const int64_t MOD = 1000000007LL;
    int n = static_cast<int>(nums.size());
    std::vector<int64_t> diff(n + 1, 0);
    for (size_t i = 0; i < requests.size(); ++i) {
        int l = requests[i][0];
        int r = requests[i][1];
        diff[l] += 1;
        if (r + 1 < n) diff[r + 1] -= 1;
    }
    std::vector<int64_t> freq(n);
    int64_t cur = 0;
    for (int i = 0; i < n; ++i) {
        cur += diff[i];
        freq[i] = cur;
    }
    std::sort(nums.begin(), nums.end(), std::greater<int>());
    std::sort(freq.begin(), freq.end(), std::greater<int64_t>());
    int64_t ans = 0;
    for (int i = 0; i < n; ++i) {
        ans = (ans + (static_cast<int64_t>(nums[i]) % MOD) * (freq[i] % MOD) % MOD) % MOD;
    }
    return ans;
}

#include <bits/stdc++.h>

int minimumCost(std::vector<std::vector<int>>& cost) {
    int n = static_cast<int>(cost.size());
    int m = static_cast<int>(cost[0].size());
    int fullMask = (1 << m) - 1;
    const int INF = 1e9;

    std::vector<int> minSecond(m, INF);
    for (int j = 0; j < m; ++j) {
        for (int i = 0; i < n; ++i) {
            minSecond[j] = std::min(minSecond[j], cost[i][j]);
        }
    }

    std::vector<int> dp(1 << m, INF);
    dp[0] = 0;

    for (int i = 0; i < n; ++i) {
        std::vector<int> sumCost(1 << m, 0);
        for (int mask = 1; mask <= fullMask; ++mask) {
            int lsb = mask & -mask;
            int bit = __builtin_ctz(lsb);
            sumCost[mask] = sumCost[mask ^ lsb] + cost[i][bit];
        }
        int minEdge = *std::min_element(cost[i].begin(), cost[i].end());

        std::vector<int> newdp(1 << m, INF);
        for (int mask = 0; mask <= fullMask; ++mask) {
            int best = INF;
            for (int sub = mask;; sub = (sub - 1) & mask) {
                int cand = dp[mask ^ sub] + sumCost[sub];
                if (sub == 0) cand += minEdge;
                best = std::min(best, cand);
                if (sub == 0) break;
            }
            newdp[mask] = best;
        }
        dp.swap(newdp);
    }

    int answer = INF;
    for (int mask = 0; mask <= fullMask; ++mask) {
        if (dp[mask] == INF) continue;
        int extra = 0;
        for (int j = 0; j < m; ++j) {
            if ((mask & (1 << j)) == 0) extra += minSecond[j];
        }
        answer = std::min(answer, dp[mask] + extra);
    }
    return answer;
}

