int maximumRequests(int n, const std::vector<std::vector<int>>& requests) {
    int m = requests.size();
    std::vector<int> balance(n, 0);
    int best = 0;
    std::function<void(int, int)> dfs = [&](int idx, int cnt) {
        if (cnt + (m - idx) <= best) return;
        if (idx == m) {
            for (int i = 0; i < n; ++i) {
                if (balance[i] != 0) return;
            }
            if (cnt > best) best = cnt;
            return;
        }
        dfs(idx + 1, cnt);
        int from = requests[idx][0];
        int to = requests[idx][1];
        balance[from]--;
        balance[to]++;
        dfs(idx + 1, cnt + 1);
        balance[from]++;
        balance[to]--;
    };
    dfs(0, 0);
    return best;
}

