int maxProfitRotation(const std::vector<int>& customers, int boardingCost, int runningCost) {
    int waiting = 0;
    std::size_t i = 0;
    int rotations = 0;
    long long served = 0;
    long long profit = 0;
    long long maxProfit = 0;
    int bestRot = -1;
    while (i < customers.size() || waiting > 0) {
        if (i < customers.size()) {
            waiting += customers[i++];
        }
        int board = std::min(waiting, 4);
        waiting -= board;
        served += board;
        ++rotations;
        profit = served * boardingCost - static_cast<long long>(rotations) * runningCost;
        if (profit > maxProfit) {
            maxProfit = profit;
            bestRot = rotations;
        }
    }
    return maxProfit > 0 ? bestRot : -1;
}

