std::vector<int> busiestServers(int k, std::vector<int>& arrival, std::vector<int>& load) {
    std::vector<int> cnt(k, 0);
    std::set<int> freeServers;
    for (int i = 0; i < k; ++i) freeServers.insert(i);
    using Pair = std::pair<long long, int>;
    std::priority_queue<Pair, std::vector<Pair>, std::greater<Pair>> busy;
    int n = static_cast<int>(arrival.size());
    for (int i = 0; i < n; ++i) {
        long long curTime = arrival[i];
        long long finishTime = curTime + load[i];
        while (!busy.empty() && busy.top().first <= curTime) {
            int srv = busy.top().second;
            busy.pop();
            freeServers.insert(srv);
        }
        if (freeServers.empty()) continue;
        int start = i % k;
        auto it = freeServers.lower_bound(start);
        if (it == freeServers.end()) it = freeServers.begin();
        int srv = *it;
        ++cnt[srv];
        freeServers.erase(it);
        busy.emplace(finishTime, srv);
    }
    int maxCnt = 0;
    for (int c : cnt) if (c > maxCnt) maxCnt = c;
    std::vector<int> result;
    for (int i = 0; i < k; ++i) if (cnt[i] == maxCnt) result.push_back(i);
    return result;
}

