std::vector<std::vector<int>> restoreMatrix(std::vector<int> rowSum, std::vector<int> colSum) {
    std::size_t m = rowSum.size();
    std::size_t n = colSum.size();
    std::vector<std::vector<int>> matrix(m, std::vector<int>(n, 0));
    using Pair = std::pair<int, int>;
    struct Compare {
        bool operator()(const Pair& a, const Pair& b) const {
            if (a.first != b.first) return a.first > b.first;
            return a.second > b.second;
        }
    };
    std::priority_queue<Pair, std::vector<Pair>, Compare> pq;
    for (int j = 0; j < static_cast<int>(n); ++j) {
        pq.emplace(colSum[j], j);
    }
    for (int i = 0; i < static_cast<int>(m); ++i) {
        int need = rowSum[i];
        while (need > 0) {
            Pair cur = pq.top();
            pq.pop();
            int take = std::min(need, cur.first);
            matrix[i][cur.second] = take;
            need -= take;
            cur.first -= take;
            if (cur.first > 0) {
                pq.emplace(cur);
            }
        }
    }
    return matrix;
}

