int visiblePoints(const std::vector<std::vector<int>>& points, int angle, const std::vector<int>& location) {
    int locX = location[0];
    int locY = location[1];
    int samePlace = 0;
    std::vector<double> angles;
    const double PI = std::acos(-1.0);
    for (const auto& p : points) {
        int x = p[0];
        int y = p[1];
        double dx = static_cast<double>(x - locX);
        double dy = static_cast<double>(y - locY);
        if (dx == 0.0 && dy == 0.0) {
            ++samePlace;
            continue;
        }
        double deg = std::atan2(dy, dx) * 180.0 / PI;
        if (deg < 0.0) deg += 360.0;
        angles.push_back(deg);
    }
    if (angles.empty()) return samePlace;
    if (angle >= 360) return static_cast<int>(points.size());
    std::sort(angles.begin(), angles.end());
    std::vector<double> extended;
    extended.reserve(angles.size() * 2);
    for (double v : angles) extended.push_back(v);
    for (double v : angles) extended.push_back(v + 360.0);
    int maxInWindow = 0;
    size_t left = 0;
    for (size_t right = 0; right < extended.size(); ++right) {
        while (extended[right] - extended[left] > static_cast<double>(angle) + 1e-9) {
            ++left;
        }
        int windowSize = static_cast<int>(right - left + 1);
        if (windowSize > maxInWindow) maxInWindow = windowSize;
    }
    return maxInWindow + samePlace;
}

