int minimumOneBitOperations(int n) {
    if (n == 0) return 0;
    if (n == 1) return 1;
    unsigned int x = static_cast<unsigned int>(n);
    int msbPos = 31 - __builtin_clz(x);
    unsigned int highestPower = 1u << msbPos;
    unsigned int remaining = x - highestPower;
    return ((1u << (msbPos + 1)) - 1) - minimumOneBitOperations(static_cast<int>(remaining));
}

