std::vector<int> countSubgraphsForEachDiameter(int n, std::vector<std::vector<int>>& edges) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0] - 1;
        int v = e[1] - 1;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    std::vector<int> ans(n - 1, 0);
    int totalMasks = 1 << n;
    std::vector<char> visited(n);
    std::vector<int> dist(n);
    std::queue<int> q;
    for (int mask = 1; mask < totalMasks; ++mask) {
        int sz = __builtin_popcount(mask);
        if (sz < 2) continue;
        int start = __builtin_ctz(mask);
        std::fill(visited.begin(), visited.end(), 0);
        while (!q.empty()) q.pop();
        visited[start] = 1;
        q.push(start);
        int cnt = 0;
        while (!q.empty()) {
            int cur = q.front(); q.pop();
            ++cnt;
            for (int nb : adj[cur]) {
                if ((mask >> nb) & 1 && !visited[nb]) {
                    visited[nb] = 1;
                    q.push(nb);
                }
            }
        }
        if (cnt != sz) continue;
        std::fill(dist.begin(), dist.end(), -1);
        while (!q.empty()) q.pop();
        dist[start] = 0;
        q.push(start);
        int farNode = start;
        while (!q.empty()) {
            int cur = q.front(); q.pop();
            for (int nb : adj[cur]) {
                if ((mask >> nb) & 1 && dist[nb] == -1) {
                    dist[nb] = dist[cur] + 1;
                    q.push(nb);
                    if (dist[nb] > dist[farNode]) farNode = nb;
                }
            }
        }
        std::fill(dist.begin(), dist.end(), -1);
        while (!q.empty()) q.pop();
        dist[farNode] = 0;
        q.push(farNode);
        int diameter = 0;
        while (!q.empty()) {
            int cur = q.front(); q.pop();
            for (int nb : adj[cur]) {
                if ((mask >> nb) & 1 && dist[nb] == -1) {
                    dist[nb] = dist[cur] + 1;
                    q.push(nb);
                    if (dist[nb] > diameter) diameter = dist[nb];
                }
            }
        }
        ans[diameter - 1] += 1;
    }
    return ans;
}

