double meanAfterRemoving(std::vector<double> arr) {
    std::size_t n = arr.size();
    std::size_t k = static_cast<std::size_t>(std::floor(n * 0.05));
    if (k == 0) {
        double total = 0.0;
        for (double v : arr) {
            total += v;
        }
        double mean = total / static_cast<double>(n);
        return std::round(mean * 1e5) / 1e5;
    }
    std::sort(arr.begin(), arr.end());
    double sum = 0.0;
    for (std::size_t i = k; i < n - k; ++i) {
        sum += arr[i];
    }
    double mean = sum / static_cast<double>(n - 2 * k);
    return std::round(mean * 1e5) / 1e5;
}

