int maximalNetworkRank(int n, const std::vector<std::vector<int>>& roads) {
    std::vector<int> degree(n, 0);
    std::vector<std::unordered_set<int>> adjacency(n);
    for (const auto& edge : roads) {
        int a = edge[0];
        int b = edge[1];
        ++degree[a];
        ++degree[b];
        adjacency[a].insert(b);
        adjacency[b].insert(a);
    }
    int best = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            int rank = degree[i] + degree[j] - (adjacency[i].count(j) ? 1 : 0);
            if (rank > best) best = rank;
        }
    }
    return best;
}

