std::vector<int> coordinateWithMaxNetworkQuality(const std::vector<std::vector<int>>& towers, int radius) {
    int minX = std::numeric_limits<int>::max();
    int maxX = std::numeric_limits<int>::min();
    int minY = std::numeric_limits<int>::max();
    int maxY = std::numeric_limits<int>::min();
    for (size_t i = 0; i < towers.size(); ++i) {
        int x = towers[i][0];
        int y = towers[i][1];
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
    }

    int bestQuality = -1;
    int bestX = 0;
    int bestY = 0;

    for (int x = minX - radius; x <= maxX + radius; ++x) {
        for (int y = minY - radius; y <= maxY + radius; ++y) {
            int total = 0;
            for (size_t i = 0; i < towers.size(); ++i) {
                int tx = towers[i][0];
                int ty = towers[i][1];
                int q = towers[i][2];
                int dx = x - tx;
                int dy = y - ty;
                double dist = std::sqrt(static_cast<double>(dx) * dx + static_cast<double>(dy) * dy);
                if (dist <= static_cast<double>(radius)) {
                    total += static_cast<int>(std::floor(q / (1.0 + dist)));
                }
            }
            if (total > bestQuality || (total == bestQuality && (x < bestX || (x == bestX && y < bestY)))) {
                bestQuality = total;
                bestX = x;
                bestY = y;
            }
        }
    }
    return {bestX, bestY};
}

