int numberOfSets(int n, int k) {
    const long long MOD = 1000000007LL;
    if (k == 0) return 1;
    if (k > n / 2) return 0;
    std::vector<long long> dpPrev(k + 1, 0), prefPrev(k + 1, 0);
    dpPrev[0] = 1;
    prefPrev[0] = 1;
    std::vector<long long> dpCurr(k + 1), prefCurr(k + 1);
    for (int i = 1; i < n; ++i) {
        dpCurr[0] = 1;
        prefCurr[0] = (prefPrev[0] + dpCurr[0]) % MOD;
        for (int j = 1; j <= k; ++j) {
            dpCurr[j] = (dpPrev[j] + prefPrev[j - 1]) % MOD;
            prefCurr[j] = (prefPrev[j] + dpCurr[j]) % MOD;
        }
        dpPrev.swap(dpCurr);
        prefPrev.swap(prefCurr);
    }
    return static_cast<int>(dpPrev[k] % MOD);
}

