int bestTeamScore(const std::vector<int>& scores, const std::vector<int>& ages) {
    int n = static_cast<int>(scores.size());
    struct Player { int age; int score; };
    std::vector<Player> players;
    players.reserve(n);
    for (int i = 0; i < n; ++i) {
        players.push_back({ages[i], scores[i]});
    }
    std::sort(players.begin(), players.end(), [](const Player& a, const Player& b) {
        if (a.age != b.age) return a.age < b.age;
        return a.score < b.score;
    });
    std::vector<int> allScores;
    allScores.reserve(n);
    for (const auto& p : players) allScores.push_back(p.score);
    std::sort(allScores.begin(), allScores.end());
    allScores.erase(std::unique(allScores.begin(), allScores.end()), allScores.end());
    int m = static_cast<int>(allScores.size());
    std::vector<int> bit(m + 1, 0);
    auto bitUpdate = [&](int idx, int val) {
        for (; idx <= m; idx += idx & -idx) {
            if (val > bit[idx]) bit[idx] = val;
        }
    };
    auto bitQuery = [&](int idx) {
        int res = 0;
        for (; idx > 0; idx -= idx & -idx) {
            if (bit[idx] > res) res = bit[idx];
        }
        return res;
    };
    int best = 0;
    for (const auto& p : players) {
        int idx = static_cast<int>(std::lower_bound(allScores.begin(), allScores.end(), p.score) - allScores.begin()) + 1;
        int cur = bitQuery(idx) + p.score;
        bitUpdate(idx, cur);
        if (cur > best) best = cur;
    }
    return best;
}

