class Fancy {
public:
    static const int64_t MOD = 1000000007LL;
    std::vector<int64_t> vals, mulAt, addAt;
    int64_t curMul = 1, curAdd = 0;
    int64_t modPow(int64_t base, int64_t exp) const {
        int64_t result = 1; base %= MOD;
        while (exp > 0) { if (exp & 1) result = result*base%MOD; base = base*base%MOD; exp >>= 1; }
        return result;
    }
    void append(int val) { vals.push_back(val % MOD); mulAt.push_back(curMul); addAt.push_back(curAdd); }
    void addAll(int inc) { curAdd = (curAdd + inc) % MOD; }
    void multAll(int m) { curMul = curMul*m%MOD; curAdd = curAdd*m%MOD; }
    int getIndex(int idx) {
        if (idx < 0 || idx >= (int)vals.size()) return -1;
        int64_t inv = modPow(mulAt[idx], MOD-2);
        int64_t factor = curMul*inv%MOD;
        int64_t addPart = ((curAdd - addAt[idx]*factor%MOD) % MOD + MOD) % MOD;
        return (int)((vals[idx]*factor%MOD + addPart) % MOD);
    }
};

