int minimumEffortPath(const std::vector<std::vector<int>>& heights) {
    int rows = static_cast<int>(heights.size());
    int cols = static_cast<int>(heights[0].size());
    const std::array<std::pair<int, int>, 4> dirs{{{1,0},{-1,0},{0,1},{0,-1}}};
    const int INF = INT_MAX;

    std::vector<std::vector<int>> distance(rows, std::vector<int>(cols, INF));
    distance[0][0] = 0;

    std::vector<std::array<int,3>> heap;

    auto heapPush = [&](const std::array<int,3>& node) {
        heap.push_back(node);
        int i = static_cast<int>(heap.size()) - 1;
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (heap[p][0] <= heap[i][0]) break;
            std::swap(heap[p], heap[i]);
            i = p;
        }
    };

    auto heapPop = [&]() -> std::array<int,3> {
        std::array<int,3> top = heap[0];
        std::array<int,3> last = heap.back();
        heap.pop_back();
        if (!heap.empty()) {
            heap[0] = last;
            int i = 0;
            while (true) {
                int l = i * 2 + 1;
                int r = i * 2 + 2;
                int smallest = i;
                if (l < static_cast<int>(heap.size()) && heap[l][0] < heap[smallest][0]) smallest = l;
                if (r < static_cast<int>(heap.size()) && heap[r][0] < heap[smallest][0]) smallest = r;
                if (smallest == i) break;
                std::swap(heap[i], heap[smallest]);
                i = smallest;
            }
        }
        return top;
    };

    heapPush({0, 0, 0});

    while (!heap.empty()) {
        std::array<int,3> cur = heapPop();
        int curEffort = cur[0];
        int r = cur[1];
        int c = cur[2];
        if (r == rows - 1 && c == cols - 1) return curEffort;
        if (curEffort != distance[r][c]) continue;

        for (const auto& d : dirs) {
            int nr = r + d.first;
            int nc = c + d.second;
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
            int edge = std::abs(heights[nr][nc] - heights[r][c]);
            int newEffort = std::max(curEffort, edge);
            if (newEffort < distance[nr][nc]) {
                distance[nr][nc] = newEffort;
                heapPush({newEffort, nr, nc});
            }
        }
    }
    return -1;
}

