std::vector<bool> areConnected(int n, int threshold, const std::vector<std::vector<int>>& queries) {
    std::vector<int> parent(n + 1);
    std::vector<int8_t> rank(n + 1, 0);
    for (int i = 1; i <= n; ++i) parent[i] = i;

    auto find = [&](int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    auto union_sets = [&](int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return;
        if (rank[ra] < rank[rb]) std::swap(ra, rb);
        parent[rb] = ra;
        if (rank[ra] == rank[rb]) ++rank[ra];
    };

    for (int d = threshold + 1; d <= n; ++d) {
        for (int multiple = d * 2; multiple <= n; multiple += d) {
            union_sets(d, multiple);
        }
    }

    std::vector<bool> ans;
    ans.reserve(queries.size());
    for (const auto& q : queries) {
        int a = q[0];
        int b = q[1];
        ans.push_back(find(a) == find(b));
    }
    return ans;
}

