std::string findLexSmallestString(std::string s, int a, int b) {
    std::string best = s;
    std::unordered_set<std::string> visited;
    std::queue<std::string> q;
    visited.insert(s);
    q.push(s);
    int n = static_cast<int>(s.size());
    int rot = b % n;
    while (!q.empty()) {
        std::string cur = q.front();
        q.pop();
        if (cur < best) best = cur;
        std::string add = cur;
        for (int i = 1; i < n; i += 2) {
            int d = add[i] - '0';
            d = (d + a) % 10;
            add[i] = static_cast<char>('0' + d);
        }
        if (visited.insert(add).second) q.push(add);
        std::string rotStr = cur.substr(n - rot) + cur.substr(0, n - rot);
        if (visited.insert(rotStr).second) q.push(rotStr);
    }
    return best;
}

