std::vector<bool> checkArithmeticSubarrays(const std::vector<int>& nums, const std::vector<int>& l, const std::vector<int>& r) {
    std::size_t m = l.size();
    std::vector<bool> answer(m);
    for (std::size_t i = 0; i < m; ++i) {
        int start = l[i];
        int end = r[i];
        int len = end - start + 1;
        if (len <= 2) {
            answer[i] = true;
            continue;
        }
        long long minVal = nums[start];
        long long maxVal = nums[start];
        for (int j = start + 1; j <= end; ++j) {
            long long v = nums[j];
            if (v < minVal) minVal = v;
            if (v > maxVal) maxVal = v;
        }
        if ((maxVal - minVal) % (len - 1) != 0) {
            answer[i] = false;
            continue;
        }
        long long diff = (maxVal - minVal) / (len - 1);
        if (diff == 0) {
            answer[i] = true;
            continue;
        }
        std::vector<char> seen(len, 0);
        bool ok = true;
        for (int j = start; j <= end && ok; ++j) {
            long long v = nums[j];
            if ((v - minVal) % diff != 0) {
                ok = false;
                break;
            }
            long long idx = (v - minVal) / diff;
            if (idx < 0 || idx >= len || seen[idx]) {
                ok = false;
                break;
            }
            seen[idx] = 1;
        }
        answer[i] = ok;
    }
    return answer;
}

