class DSU {
public:
    vector<int> parent, sz;
    DSU(int n = 0) { init(n); }
    void init(int n) {
        parent.resize(n);
        sz.assign(n, 1);
        for (int i = 0; i < n; ++i) parent[i] = i;
    }
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) std::swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
    }
};

vector<vector<int>> matrixRankTransform(vector<vector<int>>& matrix) {
    int m = matrix.size();
    int n = matrix[0].size();
    struct Cell { int val, r, c; };
    vector<Cell> cells;
    cells.reserve(m * n);
    for (int i = 0; i < m; ++i)
        for (int j = 0; j < n; ++j)
            cells.push_back({matrix[i][j], i, j});
    sort(cells.begin(), cells.end(), [](const Cell& a, const Cell& b) {
        return a.val < b.val;
    });
    vector<int> rowMax(m, 0), colMax(n, 0);
    vector<vector<int>> answer(m, vector<int>(n, 0));
    vector<int> rowMap(m, -1), colMap(n, -1);
    vector<int> touchedRows, touchedCols;
    int idx = 0;
    while (idx < (int)cells.size()) {
        int j = idx;
        while (j < (int)cells.size() && cells[j].val == cells[idx].val) ++j;
        int groupSize = j - idx;
        DSU dsu(groupSize);
        touchedRows.clear();
        touchedCols.clear();
        for (int k = idx; k < j; ++k) {
            int localIdx = k - idx;
            int r = cells[k].r;
            int c = cells[k].c;
            if (rowMap[r] == -1) {
                rowMap[r] = localIdx;
                touchedRows.push_back(r);
            } else {
                dsu.unite(localIdx, rowMap[r]);
            }
            if (colMap[c] == -1) {
                colMap[c] = localIdx;
                touchedCols.push_back(c);
            } else {
                dsu.unite(localIdx, colMap[c]);
            }
        }
        vector<int> compRank(groupSize, 0);
        for (int k = idx; k < j; ++k) {
            int localIdx = k - idx;
            int r = cells[k].r;
            int c = cells[k].c;
            int root = dsu.find(localIdx);
            int cand = max(rowMax[r], colMax[c]) + 1;
            if (cand > compRank[root]) compRank[root] = cand;
        }
        for (int k = idx; k < j; ++k) {
            int localIdx = k - idx;
            int r = cells[k].r;
            int c = cells[k].c;
            int root = dsu.find(localIdx);
            int rank = compRank[root];
            answer[r][c] = rank;
            if (rank > rowMax[r]) rowMax[r] = rank;
            if (rank > colMax[c]) colMax[c] = rank;
        }
        for (int r : touchedRows) rowMap[r] = -1;
        for (int c : touchedCols) colMap[c] = -1;
        idx = j;
    }
    return answer;
}

