int numWays(const std::vector<std::string>& words, const std::string& target) {
    const long long MOD = 1000000007LL;
    int n = static_cast<int>(words.size());
    int m = static_cast<int>(words[0].size());
    int tLen = static_cast<int>(target.size());

    std::vector<std::vector<int>> count(26, std::vector<int>(m, 0));
    for (int w = 0; w < n; ++w) {
        const std::string& word = words[w];
        for (int c = 0; c < m; ++c) {
            int idx = word[c] - 'a';
            ++count[idx][c];
        }
    }

    std::vector<long long> dp(tLen + 1, 0);
    dp[0] = 1;

    for (int col = 0; col < m; ++col) {
        int maxI = std::min(tLen - 1, col);
        for (int i = maxI; i >= 0; --i) {
            int chIdx = target[i] - 'a';
            int ways = count[chIdx][col];
            if (ways) {
                dp[i + 1] = (dp[i + 1] + dp[i] * ways) % MOD;
            }
        }
    }
    return static_cast<int>(dp[tLen]);
}

