long long countSubstrings(const std::string& s, const std::string& t) {
    std::size_t n = s.size();
    std::size_t m = t.size();
    std::vector<std::vector<uint16_t>> pre(n + 1, std::vector<uint16_t>(m + 1, 0));
    std::vector<std::vector<uint16_t>> post(n + 1, std::vector<uint16_t>(m + 1, 0));

    for (std::size_t i = 0; i < n; ++i) {
        for (std::size_t j = 0; j < m; ++j) {
            if (s[i] == t[j]) {
                pre[i + 1][j + 1] = static_cast<uint16_t>(pre[i][j] + 1);
            }
        }
    }

    for (int i = static_cast<int>(n) - 1; i >= 0; --i) {
        for (int j = static_cast<int>(m) - 1; j >= 0; --j) {
            if (s[i] == t[j]) {
                post[i][j] = static_cast<uint16_t>(post[i + 1][j + 1] + 1);
            }
        }
    }

    long long ans = 0;
    for (std::size_t i = 0; i < n; ++i) {
        for (std::size_t j = 0; j < m; ++j) {
            if (s[i] != t[j]) {
                ans += static_cast<long long>(pre[i][j] + 1) * static_cast<long long>(post[i + 1][j + 1] + 1);
            }
        }
    }
    return ans;
}

