std::string kthSmallestPath(std::vector<int>& destination, int k) {
    int row = destination[0];
    int col = destination[1];
    int n = row + col;
    std::vector<std::vector<long long>> C(n + 1, std::vector<long long>(n + 1, 0));
    for (int i = 0; i <= n; ++i) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; ++j) {
            C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
        }
    }
    std::string ans;
    while (row > 0 || col > 0) {
        if (col == 0) {
            ans.push_back('V');
            --row;
            continue;
        }
        if (row == 0) {
            ans.push_back('H');
            --col;
            continue;
        }
        long long cnt = C[row + col - 1][row];
        if (cnt >= k) {
            ans.push_back('H');
            --col;
        } else {
            ans.push_back('V');
            k -= (int)cnt;
            --row;
        }
    }
    return ans;
}

