    for (char ch : s) {
        auto it = freq.find(ch);
        if (it != freq.end()) {
            it->second += 1;
        } else {
            freq.emplace(ch, 1);
        }
    }
    std::unordered_set<int> used;
    int deletions = 0;
    for (const auto& pair : freq) {
