#include <vector>

int furthestBuilding(const std::vector<int>& heights, int bricks, int ladders) {
    std::vector<int> heap;
    auto heapPush = [&](int val) {
        heap.push_back(val);
        int i = static_cast<int>(heap.size()) - 1;
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (heap[p] <= heap[i]) break;
            std::swap(heap[p], heap[i]);
            i = p;
        }
    };
    auto heapPop = [&]() -> int {
        if (heap.size() == 1) {
            int v = heap.back();
            heap.pop_back();
            return v;
        }
        int min = heap[0];
        heap[0] = heap.back();
        heap.pop_back();
        int i = 0;
        while (true) {
            int l = i * 2 + 1;
            int r = i * 2 + 2;
            int smallest = i;
            if (l < static_cast<int>(heap.size()) && heap[l] < heap[smallest]) smallest = l;
            if (r < static_cast<int>(heap.size()) && heap[r] < heap[smallest]) smallest = r;
            if (smallest == i) break;
            std::swap(heap[i], heap[smallest]);
            i = smallest;
        }
        return min;
    };
    for (size_t i = 0; i + 1 < heights.size(); ++i) {
        int diff = heights[i + 1] - heights[i];
        if (diff <= 0) continue;
        heapPush(diff);
        if (static_cast<int>(heap.size()) > ladders) {
            bricks -= heapPop();
            if (bricks < 0) return static_cast<int>(i);
        }
    }
    return static_cast<int>(heights.size() - 1);
}

