long long createSortedArray(const std::vector<int>& instructions) {
    const int64_t MOD = 1000000007;
    int n = static_cast<int>(instructions.size());
    int maxVal = *std::max_element(instructions.begin(), instructions.end());
    std::vector<int64_t> bit(maxVal + 2, 0);

    auto add = [&](int i, int delta) {
        for (i += 1; i < static_cast<int>(bit.size()); i += i & -i) {
            bit[i] += delta;
        }
    };

    auto sum = [&](int i) {
        int64_t res = 0;
        for (i += 1; i > 0; i -= i & -i) {
            res += bit[i];
        }
        return res;
    };

    int64_t total = 0;
    for (int i = 0; i < n; ++i) {
        int x = instructions[i];
        int64_t less = sum(x - 1);
        int64_t greater = i - sum(x);
        total = (total + std::min(less, greater)) % MOD;
        add(x, 1);
    }
    return total;
}

