static const long long MOD = 1000000007LL;

static long long mul_mod(long long a, long long b) {
    return (a % MOD) * (b % MOD) % MOD;
}

int maxProfit(std::vector<int>& inventory, int orders) {
    std::sort(inventory.begin(), inventory.end(), std::greater<int>());
    inventory.push_back(0);
    long long profit = 0;
    int n = static_cast<int>(inventory.size());
    for (int i = 0; i < n - 1 && orders > 0; ++i) {
        long long cur = inventory[i];
        long long nxt = inventory[i + 1];
        long long cnt = i + 1;
        long long diff = cur - nxt;
        long long balls = diff * cnt;
        if (orders >= balls) {
            long long num = diff * (cur + nxt + 1);
            long long sumPerColor = (num / 2) % MOD;
            profit = (profit + mul_mod(sumPerColor, cnt)) % MOD;
            orders -= static_cast<int>(balls);
        } else {
            long long full = orders / cnt;
            long long rem = orders % cnt;
            long long low = cur - full;
            long long numFull = full * (cur + low + 1);
            long long sumFull = (numFull / 2) % MOD;
            profit = (profit + mul_mod(sumFull, cnt)) % MOD;
            profit = (profit + mul_mod(rem % MOD, low % MOD)) % MOD;
            orders = 0;
            break;
        }
    }
    return static_cast<int>(profit);
}

#include <bits/stdc++.h>
