bool canDistribute(const std::vector<int>& nums, const std::vector<int>& quantity) {
    std::unordered_map<int, int> freqMap;
    for (int v : nums) {
        ++freqMap[v];
    }
    std::vector<int> counts;
    counts.reserve(freqMap.size());
    for (const auto& kv : freqMap) {
        counts.push_back(kv.second);
    }

    int m = static_cast<int>(quantity.size());
    int fullMask = (1 << m) - 1;

    std::vector<int> need(1 << m, 0);
    for (int mask = 1; mask <= fullMask; ++mask) {
        int lsb = mask & -mask;
        int idx = __builtin_ctz(lsb);
        need[mask] = need[mask ^ lsb] + quantity[idx];
    }

    std::vector<bool> dp(1 << m, false);
    dp[0] = true;

    for (int c : counts) {
        std::vector<bool> next = dp;
        for (int mask = 0; mask <= fullMask; ++mask) {
            if (!dp[mask]) continue;
            int remaining = fullMask ^ mask;
            for (int sub = remaining; sub; sub = (sub - 1) & remaining) {
                if (need[sub] <= c) {
                    next[mask | sub] = true;
                }
            }
        }
        dp.swap(next);
    }

    return dp[fullMask];
}

