std::vector<int> decrypt(const std::vector<int>& code, int k) {
    int n = static_cast<int>(code.size());
    std::vector<int> result(n);
    if (k == 0) {
        std::fill(result.begin(), result.end(), 0);
        return result;
    }
    if (k > 0) {
        long long windowSum = 0;
        for (int i = 1; i <= k; ++i) {
            windowSum += code[i % n];
        }
        for (int i = 0; i < n; ++i) {
            result[i] = static_cast<int>(windowSum);
            windowSum -= code[(i + 1) % n];
            windowSum += code[(i + k + 1) % n];
        }
    } else {
        int m = -k;
        long long windowSum = 0;
        for (int i = 0; i < m; ++i) {
            int idx = (n - 1 - i + n) % n;
            windowSum += code[idx];
        }
        for (int i = 0; i < n; ++i) {
            result[i] = static_cast<int>(windowSum);
            int removeIdx = (i - m + n) % n;
            windowSum -= code[removeIdx];
            windowSum += code[i];
        }
    }
    return result;
}

