int minimumJumps(const std::vector<int>& forbidden, int a, int b, int x) {
    std::unordered_set<int> forbiddenSet(forbidden.begin(), forbidden.end());
    int maxForbidden = 0;
    for (int v : forbidden) {
        maxForbidden = std::max(maxForbidden, v);
    }
    int limit = std::max(maxForbidden, x) + a + b;

    std::vector<std::tuple<int, int, bool>> queue;
    queue.emplace_back(0, 0, false);
    std::unordered_set<std::string> visited;
    visited.insert("0,false");

    std::size_t head = 0;
    while (head < queue.size()) {
        int pos, steps;
        bool lastBack;
        std::tie(pos, steps, lastBack) = queue[head++];
        if (pos == x) return steps;

        int forward = pos + a;
        std::string fKey = std::to_string(forward) + ",false";
        if (forward <= limit && !forbiddenSet.count(forward) && !visited.count(fKey)) {
            visited.insert(fKey);
            queue.emplace_back(forward, steps + 1, false);
        }

        if (!lastBack) {
            int backward = pos - b;
            std::string bKey = std::to_string(backward) + ",true";
            if (backward >= 0 && !forbiddenSet.count(backward) && !visited.count(bKey)) {
                visited.insert(bKey);
                queue.emplace_back(backward, steps + 1, true);
            }
        }
    }
    return -1;
}

