int waysToMakeFair(const std::vector<int>& nums) {
    long long totalEven = 0, totalOdd = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        if (i % 2 == 0) totalEven += nums[i];
        else totalOdd += nums[i];
    }
    long long leftEven = 0, leftOdd = 0;
    int answer = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        long long rightEven = totalEven - leftEven - (i % 2 == 0 ? nums[i] : 0);
        long long rightOdd = totalOdd - leftOdd - (i % 2 == 1 ? nums[i] : 0);
        if (leftEven + rightOdd == leftOdd + rightEven) ++answer;
        if (i % 2 == 0) leftEven += nums[i];
        else leftOdd += nums[i];
    }
    return answer;
}

#include <bits/stdc++.h>

int maxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
    const int total = m * n;
    const int base[3] = {0, 120, 40};
    const int delta[3][3] = {
        {0,   0,   0},
        {0, -60, -10},
        {0, -10,  40}
    };
    int pow3[6];
    pow3[0] = 1;
    for (int i = 1; i <= n; ++i) pow3[i] = pow3[i - 1] * 3;

    std::unordered_map<long long, int> memo;
    std::function<int(int,int,int,int,int)> dfs = [&](int pos, int mask, int introLeft, int extroLeft, int left) -> int {
        if (pos == total) return 0;
        long long key = (static_cast<long long>(pos) << 48) |
                        (static_cast<long long>(mask) << 32) |
                        (static_cast<long long>(introLeft) << 24) |
                        (static_cast<long long>(extroLeft) << 16) |
                        static_cast<long long>(left);
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;

        int row = pos / n;
        int col = pos % n;

        int up = (mask / pow3[col]) % 3;
        int effectiveLeft = (col == 0 ? 0 : left);

        int best = dfs(pos + 1,
                       mask - up * pow3[col],
                       introLeft,
                       extroLeft,
                       0);

        if (introLeft > 0) {
            int add = base[1] + delta[1][up] + delta[1][effectiveLeft];
            int newMask = mask - up * pow3[col] + 1 * pow3[col];
            best = std::max(best, add + dfs(pos + 1, newMask, introLeft - 1, extroLeft, 1));
        }
        if (extroLeft > 0) {
            int add = base[2] + delta[2][up] + delta[2][effectiveLeft];
            int newMask = mask - up * pow3[col] + 2 * pow3[col];
            best = std::max(best, add + dfs(pos + 1, newMask, introLeft, extroLeft - 1, 2));
        }

        memo[key] = best;
        return best;
    };

    return dfs(0, 0, introvertsCount, extrovertsCount, 0);
}

