int minimumMountainRemovals(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    std::vector<int> inc(n);
    std::vector<int> dec(n);
    std::vector<int> tails;

    // compute inc[i] (LIS ending at i)
    for (int i = 0; i < n; ++i) {
        int x = nums[i];
        auto it = std::lower_bound(tails.begin(), tails.end(), x);
        int pos = static_cast<int>(it - tails.begin());
        if (pos == static_cast<int>(tails.size())) {
            tails.push_back(x);
        } else {
            tails[pos] = x;
        }
        inc[i] = pos + 1;
    }

    // compute dec[i] (LDS starting at i)
    tails.clear();
    for (int i = n - 1; i >= 0; --i) {
        int x = nums[i];
        auto it = std::lower_bound(tails.begin(), tails.end(), x);
        int pos = static_cast<int>(it - tails.begin());
        if (pos == static_cast<int>(tails.size())) {
            tails.push_back(x);
        } else {
            tails[pos] = x;
        }
        dec[i] = pos + 1;
    }

    // find best mountain
    int best = 0;
    for (int i = 1; i < n - 1; ++i) {
        if (inc[i] > 1 && dec[i] > 1) {
            int cur = inc[i] + dec[i] - 1;
            if (cur > best) best = cur;
        }
    }
    return n - best;
}

