class FrontMiddleBackQueue {
private:
    std::deque<int> left, right;
public:
    void pushFront(int val) {
        left.push_front(val);
        if (left.size() > right.size() + 1) { right.push_front(left.back()); left.pop_back(); }
    }
    void pushMiddle(int val) {
        if (left.size() > right.size()) { right.push_front(left.back()); left.pop_back(); }
        left.push_back(val);
    }
    void pushBack(int val) {
        right.push_back(val);
        if (left.size() < right.size()) { left.push_back(right.front()); right.pop_front(); }
    }
    int popFront() {
        if (left.empty() && right.empty()) return -1;
        int val;
        if (!left.empty()) { val = left.front(); left.pop_front(); }
        else { val = right.front(); right.pop_front(); }
        if (left.size() < right.size()) { left.push_back(right.front()); right.pop_front(); }
        return val;
    }
    int popMiddle() {
        if (left.empty() && right.empty()) return -1;
        int val = left.back(); left.pop_back();
        if (left.size() < right.size()) { left.push_back(right.front()); right.pop_front(); }
        return val;
    }
    int popBack() {
        if (left.empty() && right.empty()) return -1;
        int val;
        if (!right.empty()) { val = right.back(); right.pop_back(); }
        else { val = left.back(); left.pop_back(); }
        if (left.size() > right.size() + 1) { right.push_front(left.back()); left.pop_back(); }
