int minimumDeviation(const std::vector<int>& nums) {
    std::priority_queue<int> heap;
    int minVal = INT_MAX;
    for (int x : nums) {
        if (x % 2 == 1) x *= 2;
        heap.push(x);
        if (x < minVal) minVal = x;
    }
    int answer = heap.top() - minVal;
    while (heap.top() % 2 == 0) {
        int max = heap.top();
        heap.pop();
        int newVal = max / 2;
        heap.push(newVal);
        if (newVal < minVal) minVal = newVal;
        int curDev = heap.top() - minVal;
        if (curDev < answer) answer = curDev;
    }
    return answer;
}

