std::vector<int> mostCompetitive(const std::vector<int>& nums, int k) {
    std::vector<int> stack;
    int n = static_cast<int>(nums.size());
    for (int i = 0; i < n; ++i) {
        int cur = nums[i];
        while (!stack.empty() && stack.back() > cur && static_cast<int>(stack.size()) - 1 + (n - i) >= k) {
            stack.pop_back();
        }
        if (static_cast<int>(stack.size()) < k) {
            stack.push_back(cur);
        }
    }
    return stack;
}

