long long concatenatedBinary(int n) {
    const long long MOD = 1000000007LL;
    long long result = 0;
    int bits = 0;
    for (int i = 1; i <= n; ++i) {
        if ((i & (i - 1)) == 0) ++bits;
        long long shift = 1LL << bits;
        result = ((result * shift) % MOD + i) % MOD;
    }
    return result;
}

