int minMoves(const std::vector<int>& nums, int limit) {
    int n = static_cast<int>(nums.size());
    int maxSum = 2 * limit;
    std::vector<int> diff(maxSum + 2, 0);
    for (int i = 0; i < n / 2; ++i) {
        int a = nums[i];
        int b = nums[n - 1 - i];
        int sum = a + b;
        diff[2] += 2;
        diff[sum] -= 1;
        diff[sum + 1] += 1;
        int low = std::min(a, b) + 1;
        int high = std::max(a, b) + limit;
        diff[low] -= 1;
        diff[high + 1] += 1;
    }
    int cur = 0;
    int answer = INT_MAX;
    for (int s = 2; s <= maxSum; ++s) {
        cur += diff[s];
        if (cur < answer) answer = cur;
    }
    return answer;
}

