std::vector<long long> sumAbsDifferences(const std::vector<long long>& nums) {
    std::size_t n = nums.size();
    std::vector<long long> result(n);
    long long totalSum = 0;
    for (auto v : nums) totalSum += v;
    long long leftSum = 0;
    for (std::size_t i = 0; i < n; ++i) {
        long long cur = nums[i];
        long long left = static_cast<long long>(i) * cur - leftSum;
        long long right = (totalSum - leftSum - cur) - static_cast<long long>(n - i - 1) * cur;
        result[i] = left + right;
        leftSum += cur;
    }
    return result;
}

