int stoneGameVI(const std::vector<int>& aliceValues, const std::vector<int>& bobValues) {
    std::size_t n = aliceValues.size();
    std::vector<int> combined(n);
    for (std::size_t i = 0; i < n; ++i) {
        combined[i] = aliceValues[i] + bobValues[i];
    }

    std::vector<int> indices(n);
    std::iota(indices.begin(), indices.end(), 0);
    std::sort(indices.begin(), indices.end(),
        [&](int i, int j) { return combined[i] > combined[j]; });

    long long aliceScore = 0, bobScore = 0;
    for (std::size_t turn = 0; turn < n; ++turn) {
        int idx = indices[turn];
        if (turn % 2 == 0) {
            aliceScore += aliceValues[idx];
        } else {
            bobScore += bobValues[idx];
        }
    }

    if (aliceScore > bobScore) return 1;
    if (aliceScore < bobScore) return -1;
    return 0;
}

