int boxDelivering(const std::vector<std::vector<int>>& boxes, int portsCount, int maxBoxes, int maxWeight) {
    int n = static_cast<int>(boxes.size());
    std::vector<int> cnt(n + 1, 0); // port changes prefix
    for (int i = 2; i <= n; ++i) {
        cnt[i] = cnt[i - 1] + (boxes[i - 1][0] != boxes[i - 2][0] ? 1 : 0);
    }

    std::vector<int> dp(n + 1, 0);
    std::deque<int> dq; // store start indices j
    long long weightSum = 0;
    int left = 1;

    for (int i = 1; i <= n; ++i) {
        weightSum += boxes[i - 1][1];

        while (i - left + 1 > maxBoxes || weightSum > maxWeight) {
            weightSum -= boxes[left - 1][1];
            ++left;
        }

        // add candidate j = i
        int curVal = dp[i - 1] - cnt[i];
        while (!dq.empty() && (dp[dq.back() - 1] - cnt[dq.back()]) >= curVal) {
            dq.pop_back();
        }
        dq.push_back(i);

        // remove out‑of‑window candidates
        while (!dq.empty() && dq.front() < left) {
            dq.pop_front();
        }

        int bestIdx = dq.front();
        dp[i] = cnt[i] + 2 + (dp[bestIdx - 1] - cnt[bestIdx]);
    }

    return dp[n];
}

#include <bits/stdc++.h>
