#include <unordered_set>
#include <limits>

int minIncompatibility(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    int g = n / k;

    std::unordered_map<int, int> freq;
    for (int v : nums) {
        ++freq[v];
        if (freq[v] > k) return -1;
    }

    int totalMask = 1 << n;
    std::vector<int> inc(totalMask, -1);

    auto popcnt = [](int x) {
        int c = 0;
        while (x) { x &= x - 1; ++c; }
        return c;
    };

    for (int mask = 0; mask < totalMask; ++mask) {
        if (popcnt(mask) != g) continue;
        int mn = std::numeric_limits<int>::max();
        int mx = std::numeric_limits<int>::min();
        std::unordered_set<int> seen;
        bool ok = true;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) {
                int v = nums[i];
                if (seen.find(v) != seen.end()) { ok = false; break; }
                seen.insert(v);
                if (v < mn) mn = v;
                if (v > mx) mx = v;
            }
        }
        if (ok) inc[mask] = mx - mn;
    }

    const int INF = 1e9;
    std::vector<int> dp(totalMask, INF);
    dp[0] = 0;
    for (int mask = 1; mask < totalMask; ++mask) {
        if (popcnt(mask) % g != 0) continue;
        for (int sub = mask; sub; sub = (sub - 1) & mask) {
            int cost = inc[sub];
            if (cost == -1) continue;
            int prev = dp[mask ^ sub];
            if (prev + cost < dp[mask]) dp[mask] = prev + cost;
        }
    }

    int ans = dp[totalMask - 1];
    return ans >= INF ? -1 : ans;
}

