std::string reformatNumber(const std::string& number) {
    std::string digits;
    digits.reserve(number.size());
    for (char c : number) {
        if (std::isdigit(static_cast<unsigned char>(c))) {
            digits.push_back(c);
        }
    }
    std::vector<std::string> groups;
    size_t i = 0;
    size_t remaining = digits.size();
    while (remaining > 4) {
        groups.push_back(digits.substr(i, 3));
        i += 3;
        remaining -= 3;
    }
    if (remaining == 4) {
        groups.push_back(digits.substr(i, 2));
        groups.push_back(digits.substr(i + 2, 2));
    } else {
        groups.push_back(digits.substr(i));
    }
    std::string result;
    for (size_t idx = 0; idx < groups.size(); ++idx) {
        if (idx) result.push_back('-');
        result += groups[idx];
    }
    return result;
}

