long long stoneGameVII(const std::vector<int>& stones) {
    int n = stones.size();
    std::vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        prefix[i + 1] = prefix[i] + stones[i];
    }
    std::vector<std::vector<long long>> dp(n, std::vector<long long>(n, 0));
    for (int len = 2; len <= n; ++len) {
        for (int i = 0; i + len - 1 < n; ++i) {
            int j = i + len - 1;
            long long sumLeft = prefix[j + 1] - prefix[i + 1];
            long long sumRight = prefix[j] - prefix[i];
            dp[i][j] = std::max(sumLeft - dp[i + 1][j],
                               sumRight - dp[i][j - 1]);
        }
    }
    return dp[0][n - 1];
}

