std::vector<bool> checkEdgeLimitedPaths(int n, const std::vector<std::vector<int>>& edgeList, const std::vector<std::vector<int>>& queries) {
    struct DSU {
        std::vector<int> parent;
        std::vector<int> rank;
        DSU(int n) : parent(n), rank(n, 0) {
            for (int i = 0; i < n; ++i) parent[i] = i;
        }
        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }
        void unite(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (rank[ra] < rank[rb]) parent[ra] = rb;
            else if (rank[ra] > rank[rb]) parent[rb] = ra;
            else {
                parent[rb] = ra;
                ++rank[ra];
            }
        }
    };

    std::vector<std::vector<int>> edges = edgeList;
    std::sort(edges.begin(), edges.end(),
              [](const std::vector<int>& a, const std::vector<int>& b) { return a[2] < b[2]; });

    struct Query {
        int p;
        int q;
        int limit;
        int idx;
    };
    std::vector<Query> queriesWithIdx;
    queriesWithIdx.reserve(queries.size());
    for (size_t i = 0; i < queries.size(); ++i) {
        queriesWithIdx.push_back({queries[i][0], queries[i][1], queries[i][2], static_cast<int>(i)});
    }
    std::sort(queriesWithIdx.begin(), queriesWithIdx.end(),
              [](const Query& a, const Query& b) { return a.limit < b.limit; });

    std::vector<bool> answer(queries.size());
    DSU dsu(n);
    size_t eIdx = 0;
    for (const Query& qu : queriesWithIdx) {
        while (eIdx < edges.size() && edges[eIdx][2] < qu.limit) {
            dsu.unite(edges[eIdx][0], edges[eIdx][1]);
            ++eIdx;
        }
        answer[qu.idx] = dsu.find(qu.p) == dsu.find(qu.q);
    }
    return answer;
}

