long long minMoves(const std::vector<int>& nums, int k) {
    std::vector<long long> adjusted;
    for (size_t i = 0; i < nums.size(); ++i) {
        if (nums[i] == 1) {
            adjusted.push_back(static_cast<long long>(i) - static_cast<long long>(adjusted.size()));
        }
    }
    if (k <= 1) return 0;
    if (adjusted.size() < static_cast<size_t>(k)) return -1;
    std::vector<long long> pref(adjusted.size() + 1, 0);
    for (size_t i = 0; i < adjusted.size(); ++i) {
        pref[i + 1] = pref[i] + adjusted[i];
    }
    long long answer = std::numeric_limits<long long>::max();
    for (size_t left = 0; left + k - 1 < adjusted.size(); ++left) {
        size_t right = left + k - 1;
        size_t medianIdx = left + static_cast<size_t>(k / 2);
        long long median = adjusted[medianIdx];
        long long leftDist = median * static_cast<long long>(medianIdx - left) - (pref[medianIdx] - pref[left]);
        long long rightDist = (pref[right + 1] - pref[medianIdx + 1]) - median * static_cast<long long>(right - medianIdx);
        long long moves = leftDist + rightDist;
        if (moves < answer) answer = moves;
    }
    return answer;
}

