int maxEatenApples(const std::vector<int>& apples, const std::vector<int>& days) {
    struct Node { int expire; int count; };
    std::vector<Node> heap;
    auto swap = [&](int i, int j) {
        Node t = heap[i];
        heap[i] = heap[j];
        heap[j] = t;
    };
    auto up = [&](int i) {
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (heap[p].expire <= heap[i].expire) break;
            swap(i, p);
            i = p;
        }
    };
    auto down = [&](int i) {
        int n = heap.size();
        while (true) {
            int l = i * 2 + 1;
            int r = l + 1;
            int smallest = i;
            if (l < n && heap[l].expire < heap[smallest].expire) smallest = l;
            if (r < n && heap[r].expire < heap[smallest].expire) smallest = r;
            if (smallest == i) break;
            swap(i, smallest);
            i = smallest;
        }
    };
    auto push = [&](Node node) {
        heap.push_back(node);
        up(heap.size() - 1);
    };
    auto pop = [&]() -> Node {
        if (heap.size() == 1) {
            Node top = heap.back();
            heap.pop_back();
            return top;
        }
        Node top = heap[0];
        heap[0] = heap.back();
        heap.pop_back();
        down(0);
        return top;
    };
    auto peek = [&]() -> Node& {
        return heap[0];
    };

    int day = 0;
    int eaten = 0;
    int n = apples.size();
    while (day < n || !heap.empty()) {
        if (day < n && apples[day] > 0) {
            push({day + days[day], apples[day]});
        }
        while (!heap.empty() && peek().expire <= day) {
            pop();
        }
        if (!heap.empty()) {
            Node& top = peek();
            top.count--;
            eaten++;
            if (top.count == 0) {
                pop();
            }
        }
        ++day;
    }
    return eaten;
}

#include <bits/stdc++.h>
std::vector<int> maximizeXor(std::vector<int>& nums, std::vector<std::vector<int>>& queries) {
    struct TrieNode {
        int child[2];
        TrieNode() { child[0] = child[1] = -1; }
    };
    std::vector<TrieNode> trie;
    trie.emplace_back(); // root

    auto insert = [&](int val) {
        int node = 0;
        for (int i = 31; i >= 0; --i) {
            int b = (val >> i) & 1;
            if (trie[node].child[b] == -1) {
                trie[node].child[b] = (int)trie.size();
                trie.emplace_back();
            }
            node = trie[node].child[b];
        }
    };

    auto maxXor = [&](int x) -> int {
        if (trie.size() == 1) return -1;
        int node = 0;
        int res = 0;
        for (int i = 31; i >= 0; --i) {
            int b = (x >> i) & 1;
            int want = b ^ 1;
            if (trie[node].child[want] != -1) {
                res |= (1 << i);
                node = trie[node].child[want];
            } else {
                node = trie[node].child[b];
            }
        }
        return res;
    };

    std::sort(nums.begin(), nums.end());
    struct Q {
        int x, m, idx;
    };
    std::vector<Q> qs;
    qs.reserve(queries.size());
    for (int i = 0; i < (int)queries.size(); ++i) {
        qs.push_back({queries[i][0], queries[i][1], i});
    }
    std::sort(qs.begin(), qs.end(), [](const Q& a, const Q& b){ return a.m < b.m; });

    std::vector<int> ans(queries.size());
    size_t p = 0;
    for (const auto& q : qs) {
        while (p < nums.size() && nums[p] <= q.m) {
            insert(nums[p]);
            ++p;
        }
        ans[q.idx] = maxXor(q.x);
    }
    return ans;
}

