int countGoodMeals(const std::vector<int>& deliciousness) {
    const int MOD = 1000000007;
    std::unordered_map<int, std::int64_t> freq;
    std::int64_t ans = 0;

    int maxVal = *std::max_element(deliciousness.begin(), deliciousness.end());
    int limit = maxVal * 2;
    std::vector<std::int64_t> powers;
    for (std::int64_t p = 1; p <= limit; p <<= 1) {
        powers.push_back(p);
    }

    for (size_t i = 0; i < deliciousness.size(); ++i) {
        int cur = deliciousness[i];
        for (size_t j = 0; j < powers.size(); ++j) {
            std::int64_t need = powers[j] - cur;
            auto it = freq.find(static_cast<int>(need));
            if (it != freq.end()) {
                ans = (ans + it->second) % MOD;
            }
        }
        freq[cur] = freq[cur] + 1;
    }
    return static_cast<int>(ans);
}

#include <bits/stdc++.h>
#include <vector>
#include <cstdint>

int waysToSplit(const std::vector<int>& nums) {
    const long long MOD = 1000000007LL;
    int n = static_cast<int>(nums.size());
    std::vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        pref[i + 1] = pref[i] + nums[i];
    }
    long long total = pref[n];
    long long ans = 0;
    int leftPtr = 1, rightPtr = 1;
    for (int i = 1; i <= n - 2; ++i) {
        if (leftPtr < i + 1) leftPtr = i + 1;
        if (rightPtr < i + 1) rightPtr = i + 1;
        long long leftSum = pref[i];
        while (leftPtr < n && pref[leftPtr] < 2LL * leftSum) ++leftPtr;
        while (rightPtr < n && pref[rightPtr] <= (total + leftSum) / 2) ++rightPtr;
        if (rightPtr > leftPtr) {
            ans += rightPtr - leftPtr;
            if (ans >= MOD) ans %= MOD;
        }
    }
    return static_cast<int>(ans % MOD);
}

