long long maximumScore(const std::string& s, int x, int y) {
    std::string first = (x > y) ? "ab" : "ba";
    int firstScore = std::max(x, y);
    std::string second = (x > y) ? "ba" : "ab";
    int secondScore = std::min(x, y);

    long long total = 0;
    std::vector<char> stack;

    for (char ch : s) {
        if (!stack.empty() && stack.back() == first[0] && ch == first[1]) {
            stack.pop_back();
            total += firstScore;
        } else {
            stack.push_back(ch);
        }
    }

    std::vector<char> stack2;
    for (char ch : stack) {
        if (!stack2.empty() && stack2.back() == second[0] && ch == second[1]) {
            stack2.pop_back();
            total += secondScore;
        } else {
            stack2.push_back(ch);
        }
    }

    return total;
}

