int minOperations(const std::vector<int>& target, const std::vector<int>& arr) {
    std::unordered_map<int, int> pos;
    for (size_t i = 0; i < target.size(); ++i) {
        pos[target[i]] = static_cast<int>(i);
    }
    std::vector<int> seq;
    seq.reserve(arr.size());
    for (int v : arr) {
        auto it = pos.find(v);
        if (it != pos.end()) {
            seq.push_back(it->second);
        }
    }
    std::vector<int> tails;
    tails.reserve(seq.size());
    for (int idx : seq) {
        auto it = std::lower_bound(tails.begin(), tails.end(), idx);
        if (it == tails.end()) {
            tails.push_back(idx);
        } else {
            *it = idx;
        }
    }
    return static_cast<int>(target.size()) - static_cast<int>(tails.size());
}

#include <bits/stdc++.h>

std::vector<int> constructLargestValidSequence(int n) {
    int len = 2 * n - 1;
    std::vector<int> ans(len, 0);
    std::vector<bool> used(n + 1, false);

    std::function<bool(int)> dfs = [&](int idx) -> bool {
        if (idx == len) return true;
        if (ans[idx] != 0) return dfs(idx + 1);
        for (int i = n; i >= 2; --i) {
            if (!used[i] && idx + i < len && ans[idx + i] == 0) {
                ans[idx] = ans[idx + i] = i;
                used[i] = true;
                if (dfs(idx + 1)) return true;
                ans[idx] = ans[idx + i] = 0;
                used[i] = false;
            }
        }
        if (!used[1]) {
            ans[idx] = 1;
            used[1] = true;
            if (dfs(idx + 1)) return true;
            ans[idx] = 0;
            used[1] = false;
        }
        return false;
    };

    dfs(0);
    return ans;
}

