#include <unordered_map>

int minimumHammingDistance(const std::vector<int>& source, const std::vector<int>& target, const std::vector<std::vector<int>>& allowedSwaps) {
    int n = source.size();
    std::vector<int> parent(n);
    std::vector<int> rank(n, 0);
    for (int i = 0; i < n; ++i) parent[i] = i;

    auto find = [&](int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    auto unite = [&](int x, int y) {
        int rx = find(x);
        int ry = find(y);
        if (rx == ry) return;
        if (rank[rx] < rank[ry]) parent[rx] = ry;
        else if (rank[rx] > rank[ry]) parent[ry] = rx;
        else { parent[ry] = rx; rank[rx]++; }
    };

    for (const auto& pair : allowedSwaps) unite(pair[0], pair[1]);

    std::unordered_map<int, std::vector<int>> groups;
    for (int i = 0; i < n; ++i) {
        int root = find(i);
        groups[root].push_back(i);
    }

    int mismatches = 0;
    for (const auto& kv : groups) {
        const std::vector<int>& indices = kv.second;
        std::unordered_map<int, int> freq;
        for (int idx : indices) {
            int val = source[idx];
            ++freq[val];
        }
        for (int idx : indices) {
            int val = target[idx];
            auto it = freq.find(val);
            if (it != freq.end() && it->second > 0) {
                --(it->second);
            } else {
                ++mismatches;
            }
        }
    }
    return mismatches;
}

