#include <bits/stdc++.h>

int numberOfWays(std::vector<std::vector<int>>& pairs) {
    std::unordered_map<int, std::unordered_set<int>> adj;
    for (const auto& p : pairs) {
        int x = p[0], y = p[1];
        adj[x].insert(y);
        adj[y].insert(x);
    }
    int n = static_cast<int>(adj.size());
    int maxDegree = n - 1;
    int root = -1;
    int rootCount = 0;
    for (const auto& kv : adj) {
        if (static_cast<int>(kv.second.size()) == maxDegree) {
            ++rootCount;
            if (root == -1) root = kv.first;
        }
    }
    if (rootCount == 0) return 0;
    int answer = (rootCount > 1) ? 2 : 1;
    for (const auto& kv : adj) {
        int v = kv.first;
        int degV = static_cast<int>(kv.second.size());
        if (degV == maxDegree) continue; // possible root, no parent needed
        int bestSize = INT_MAX;
        int parentCnt = 0;
        for (int u : kv.second) {
            int degU = static_cast<int>(adj[u].size());
            if (degU <= degV) continue;
            bool subset = true;
            for (int w : kv.second) {
                if (w == u) continue;
                if (!adj[u].count(w)) { subset = false; break; }
            }
            if (!subset) continue;
            if (degU < bestSize) {
                bestSize = degU;
                parentCnt = 1;
            } else if (degU == bestSize) {
                ++parentCnt;
            }
        }
        if (bestSize == INT_MAX) return 0;
        if (parentCnt > 1) answer = 2;
    }
    return answer;
}

