struct ListNode {
    int val;
    ListNode* next;
    ListNode() : val(0), next(nullptr) {}
    ListNode(int x) : val(x), next(nullptr) {}
    ListNode(int x, ListNode* next) : val(x), next(next) {}
};

ListNode* swapNodes(ListNode* head, int k) {
    ListNode* first = head;
    for (int i = 1; i < k; ++i) {
        first = first->next;
    }

    ListNode* second = head;
    ListNode* fast = first;
    while (fast->next) {
        fast = fast->next;
        second = second->next;
    }

    int tmp = first->val;
    first->val = second->val;
    second->val = tmp;

    return head;
}

#include <bits/stdc++.h>

int minimumTimeRequired(std::vector<int> jobs, int k) {
    if (jobs.empty()) return 0;
    std::sort(jobs.begin(), jobs.end(), std::greater<int>());
    int low = *std::max_element(jobs.begin(), jobs.end());
    long long total = std::accumulate(jobs.begin(), jobs.end(), 0LL);
    int high = static_cast<int>(total);
    while (low < high) {
        int mid = low + (high - low) / 2;
        std::vector<int> loads(k, 0);
        std::function<bool(int)> dfs = [&](int idx) -> bool {
            if (idx == static_cast<int>(jobs.size())) return true;
            int cur = jobs[idx];
            std::unordered_set<int> seen;
            for (int i = 0; i < k; ++i) {
                if (loads[i] + cur > mid) continue;
                if (seen.find(loads[i]) != seen.end()) continue;
                seen.insert(loads[i]);
                loads[i] += cur;
                if (dfs(idx + 1)) return true;
                loads[i] -= cur;
                if (loads[i] == 0) break;
            }
            return false;
        };
        if (dfs(0)) high = mid;
        else low = mid + 1;
    }
    return low;
}

#include <bits/stdc++.h>
