int minimumTeachings(int n, const std::vector<std::vector<int>>& languages, const std::vector<std::vector<int>>& friendships) {
    std::vector<std::unordered_set<int>> userLang;
    userLang.reserve(languages.size());
    for (const auto& arr : languages) {
        std::unordered_set<int> s;
        s.reserve(arr.size() * 2);
        for (int lang : arr) {
            s.insert(lang);
        }
        userLang.push_back(std::move(s));
    }

    std::unordered_set<int> badUsers;
    for (const auto& pair : friendships) {
        int a = pair[0] - 1;
        int b = pair[1] - 1;
        bool share = false;
        for (int lang : userLang[a]) {
            if (userLang[b].find(lang) != userLang[b].end()) {
                share = true;
                break;
            }
        }
        if (!share) {
            badUsers.insert(a);
            badUsers.insert(b);
        }
    }

    if (badUsers.empty()) {
        return 0;
    }

    int answer = INT_MAX;
    for (int L = 1; L <= n; ++L) {
        int teach = 0;
        for (int u : badUsers) {
            if (userLang[u].find(L) == userLang[u].end()) {
                ++teach;
            }
        }
        if (teach < answer) {
            answer = teach;
        }
    }
    return answer;
}

