std::vector<int> decodeXorPermutation(const std::vector<int>& encoded) {
    int n = static_cast<int>(encoded.size()) + 1;
    int totalXor = 0;
    for (int i = 1; i <= n; ++i) totalXor ^= i;
    int oddXor = 0;
    for (int i = 1; i < static_cast<int>(encoded.size()); i += 2) oddXor ^= encoded[i];
    std::vector<int> perm(n);
    perm[0] = totalXor ^ oddXor;
    for (int i = 1; i < n; ++i) perm[i] = perm[i - 1] ^ encoded[i - 1];
    return perm;
}

