int largestSubmatrix(const std::vector<std::vector<int>>& matrix) {
    int m = static_cast<int>(matrix.size());
    if (m == 0) return 0;
    int n = static_cast<int>(matrix[0].size());
    std::vector<int> heights(n, 0);
    int maxArea = 0;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            heights[j] = (matrix[i][j] == 1) ? heights[j] + 1 : 0;
        }
        std::vector<int> cnt(m + 1, 0);
        for (int h : heights) {
            ++cnt[h];
        }
        int colsAtLeast = 0;
        for (int h = m; h >= 1; --h) {
            colsAtLeast += cnt[h];
            int area = h * colsAtLeast;
            if (area > maxArea) maxArea = area;
        }
    }
    return maxArea;
}

#include <bits/stdc++.h>
std::vector<std::string> _grid;
int _rows, _cols;
int _catJump, _mouseJump;
int _foodIdx;
std::vector<std::vector<int>> _mouseMoves;
std::vector<std::vector<int>> _catMoves;
std::vector<std::vector<int>> _revMouse;
std::vector<std::vector<int>> _revCat;

inline int idx(int r, int c) { return r * _cols + c; }

void precompute() {
    int total = _rows * _cols;
    _mouseMoves.assign(total, {});
    _catMoves.assign(total, {});
    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};

    for (int r = 0; r < _rows; ++r) {
        for (int c = 0; c < _cols; ++c) {
            if (_grid[r][c] == '#') continue;
            int cur = idx(r, c);
            // mouse moves
            std::vector<int> &mvM = _mouseMoves[cur];
            mvM.push_back(cur);
            for (int d = 0; d < 4; ++d) {
                for (int step = 1; step <= _mouseJump; ++step) {
                    int nr = r + dr[d] * step;
                    int nc = c + dc[d] * step;
                    if (nr < 0 || nr >= _rows || nc < 0 || nc >= _cols) break;
                    if (_grid[nr][nc] == '#') break;
                    mvM.push_back(idx(nr, nc));
                }
            }
            // cat moves
            std::vector<int> &mvC = _catMoves[cur];
            mvC.push_back(cur);
            for (int d = 0; d < 4; ++d) {
                for (int step = 1; step <= _catJump; ++step) {
                    int nr = r + dr[d] * step;
                    int nc = c + dc[d] * step;
                    if (nr < 0 || nr >= _rows || nc < 0 || nc >= _cols) break;
                    if (_grid[nr][nc] == '#') break;
                    mvC.push_back(idx(nr, nc));
                }
            }
        }
    }
    _revMouse.assign(total, {});
    _revCat.assign(total, {});
    for (int i = 0; i < total; ++i) {
        for (int nxt : _mouseMoves[i]) _revMouse[nxt].push_back(i);
        for (int nxt : _catMoves[i]) _revCat[nxt].push_back(i);
    }
}

bool canMouseWin(std::vector<std::string> grid, int catJump, int mouseJump) {
    _grid = std::move(grid);
    _rows = _grid.size();
    _cols = _grid[0].size();
    _catJump = catJump;
    _mouseJump = mouseJump;

    int mouseStart = -1, catStart = -1;
    for (int r = 0; r < _rows; ++r) {
        for (int c = 0; c < _cols; ++c) {
            if (_grid[r][c] == 'M') mouseStart = idx(r, c);
            else if (_grid[r][c] == 'C') catStart = idx(r, c);
            else if (_grid[r][c] == 'F') _foodIdx = idx(r, c);
        }
    }

    precompute();

    int total = _rows * _cols;
    int stateCount = total * total * 2;
    std::vector<char> result(stateCount, 0); // 0 unknown, 1 mouse win, 2 cat win
    std::vector<int> degree(stateCount, 0);
    auto encode = [&](int m, int c, int turn) {
        return ((m * total + c) << 1) | turn;
    };

    for (int m = 0; m < total; ++m) {
        for (int c = 0; c < total; ++c) {
            degree[encode(m, c, 0)] = _mouseMoves[m].size();
            degree[encode(m, c, 1)] = _catMoves[c].size();
        }
    }

    std::queue<int> q;
    for (int m = 0; m < total; ++m) {
        for (int c = 0; c < total; ++c) {
            if (m == _foodIdx) {
                for (int turn = 0; turn < 2; ++turn) {
                    int s = encode(m, c, turn);
                    if (result[s] == 0) {
                        result[s] = 1;
                        q.push(s);
                    }
                }
            } else if (c == _foodIdx || m == c) {
                for (int turn = 0; turn < 2; ++turn) {
                    int s = encode(m, c, turn);
                    if (result[s] == 0) {
                        result[s] = 2;
                        q.push(s);
                    }
                }
            }
        }
    }

    while (!q.empty()) {
        int cur = q.front();
        q.pop();
        int turn = cur & 1;
        int tmp = cur >> 1;
        int catPos = tmp % total;
        int mousePos = tmp / total;
        char curRes = result[cur]; // 1 mouse win, 2 cat win

        int prevTurn = 1 - turn;
        const std::vector<std::vector<int>> &revMoves = (prevTurn == 0) ? _revMouse : _revCat;
        const std::vector<std::vector<int>> &moves = (prevTurn == 0) ? _mouseMoves : _catMoves;

        if (prevTurn == 0) { // predecessor was mouse's turn
            for (int prevMouse : revMoves[mousePos]) {
                int prevState = encode(prevMouse, catPos, prevTurn);
                if (result[prevState] != 0) continue;
                if (curRes == 1) {
                    result[prevState] = 1;
                    q.push(prevState);
                } else {
                    if (--degree[prevState] == 0) {
                        result[prevState] = 2;
                        q.push(prevState);
                    }
                }
            }
        } else { // predecessor was cat's turn
            for (int prevCat : revMoves[catPos]) {
                int prevState = encode(mousePos, prevCat, prevTurn);
                if (result[prevState] != 0) continue;
                if (curRes == 2) {
                    result[prevState] = 2;
                    q.push(prevState);
                } else {
                    if (--degree[prevState] == 0) {
                        result[prevState] = 1;
                        q.push(prevState);
                    }
                }
            }
        }
    }

    return result[encode(mouseStart, catStart, 0)] == 1;
}

#include <bits/stdc++.h>
