int minChanges(const std::string& a, const std::string& b) {
    int cntA[26] = {0}, cntB[26] = {0};
    for (char ch : a) ++cntA[ch - 'a'];
    for (char ch : b) ++cntB[ch - 'a'];
    int nA = static_cast<int>(a.size());
    int nB = static_cast<int>(b.size());
    int prefA = 0, prefB = 0;
    int ans = INT_MAX;
    for (int c = 0; c < 25; ++c) {
        prefA += cntA[c];
        prefB += cntB[c];
        int changes1 = (nA - prefA) + prefB;
        int changes2 = (nB - prefB) + prefA;
        ans = std::min(ans, std::min(changes1, changes2));
    }
    int maxCommon = 0;
    for (int i = 0; i < 26; ++i) {
        maxCommon = std::max(maxCommon, cntA[i] + cntB[i]);
    }
    ans = std::min(ans, nA + nB - maxCommon);
    return ans;
}

#include <bits/stdc++.h>
