int kthLargestXorCoordinate(const std::vector<std::vector<int>>& matrix, int k) {
    int m = static_cast<int>(matrix.size());
    int n = static_cast<int>(matrix[0].size());
    std::vector<int> prev(n, 0), cur(n, 0);
    std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            int top = (i > 0) ? prev[j] : 0;
            int left = (j > 0) ? cur[j - 1] : 0;
            int diag = (i > 0 && j > 0) ? prev[j - 1] : 0;
            int val = top ^ left ^ diag ^ matrix[i][j];
            cur[j] = val;
            if (static_cast<int>(minHeap.size()) < k) {
                minHeap.push(val);
            } else if (val > minHeap.top()) {
                minHeap.pop();
                minHeap.push(val);
            }
        }
        std::swap(prev, cur);
    }
    return minHeap.top();
}

