long long minimumBoxes(int n) {
    if (n <= 0) return 0;
    long long low = 0, high = 2000000; // sufficient upper bound
    while (low < high) {
        long long mid = (low + high) / 2;
        unsigned long long t = (unsigned long long)mid * (mid + 1) * (mid + 2) / 6;
        if (t >= (unsigned long long)n) {
            high = mid;
        } else {
