static const long long MOD = 1000000007LL;

static long long modPow(long long a, long long e) {
    long long res = 1;
    while (e) {
        if (e & 1) res = res * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return res;
}

std::vector<int> waysToMakeArray(std::vector<std::vector<int>>& queries) {
    int max_n = 0, max_k = 0;
    for (const auto& q : queries) {
        max_n = std::max(max_n, q[0]);
        max_k = std::max(max_k, q[1]);
    }

    int limit = std::max(2, max_k);
    std::vector<int> spf(limit + 1);
    for (int i = 0; i <= limit; ++i) spf[i] = i;
    for (int i = 2; i * i <= limit; ++i) {
        if (spf[i] == i) {
            for (int j = i * i; j <= limit; j += i) {
                if (spf[j] == j) spf[j] = i;
            }
        }
    }

    int maxFact = max_n + max_k;
    std::vector<long long> fact(maxFact + 1), invFact(maxFact + 1);
    fact[0] = 1;
    for (int i = 1; i <= maxFact; ++i) fact[i] = fact[i - 1] * i % MOD;
    invFact[maxFact] = modPow(fact[maxFact], MOD - 2);
    for (int i = maxFact; i > 0; --i) invFact[i - 1] = invFact[i] * i % MOD;

    auto C = [&](int n, int k) -> long long {
        if (k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    };

    std::vector<int> answer;
    answer.reserve(queries.size());
    for (const auto& q : queries) {
        int n = q[0];
        int k = q[1];
        long long ways = 1;
        int temp = k;
        while (temp > 1) {
            int p = spf[temp];
            int cnt = 0;
            while (temp % p == 0) {
                temp /= p;
                ++cnt;
            }
            ways = ways * C(cnt + n - 1, n - 1) % MOD;
        }
        answer.push_back(static_cast<int>(ways));
    }
    return answer;
}

