bool checkPartitioning(const std::string& s) {
    int n = static_cast<int>(s.size());
    if (n < 3) return false;
    std::vector<char> pref(n, 0), suff(n, 0);
    // First pass: compute prefix and suffix palindrome flags
    for (int center = 0; center < n; ++center) {
        // odd length palindromes
        for (int l = center, r = center; l >= 0 && r < n && s[l] == s[r]; --l, ++r) {
            if (l == 0) pref[r] = 1;
            if (r == n - 1) suff[l] = 1;
        }
        // even length palindromes
        for (int l = center, r = center + 1; l >= 0 && r < n && s[l] == s[r]; --l, ++r) {
            if (l == 0) pref[r] = 1;
            if (r == n - 1) suff[l] = 1;
        }
    }
    // Second pass: look for middle palindrome with valid prefix and suffix
    for (int center = 0; center < n; ++center) {
        // odd length
        for (int l = center, r = center; l >= 0 && r < n && s[l] == s[r]; --l, ++r) {
            if (l > 0 && r < n - 1 && pref[l - 1] && suff[r + 1]) return true;
        }
        // even length
        for (int l = center, r = center + 1; l >= 0 && r < n && s[l] == s[r]; --l, ++r) {
            if (l > 0 && r < n - 1 && pref[l - 1] && suff[r + 1]) return true;
        }
    }
    return false;
}

