std::vector<int> restoreArray(const std::vector<std::vector<int>>& adjacentPairs) {
    std::unordered_map<int, std::vector<int>> adj;
    for (const auto& pair : adjacentPairs) {
        int a = pair[0];
        int b = pair[1];
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    int start = 0;
    for (const auto& pair : adjacentPairs) {
        if (adj[pair[0]].size() == 1) {
            start = pair[0];
            break;
        }
        if (adj[pair[1]].size() == 1) {
            start = pair[1];
            break;
        }
    }

    int n = static_cast<int>(adjacentPairs.size()) + 1;
    std::vector<int> result(n);
    result[0] = start;
    result[1] = adj[start][0];

    for (int i = 2; i < n; ++i) {
        int prev = result[i - 2];
        int cur = result[i - 1];
        const std::vector<int>& candidates = adj[cur];
        result[i] = (candidates[0] == prev) ? candidates[1] : candidates[0];
    }
    return result;
}

