long long closestSubsequenceSum(const std::vector<int>& nums, long long goal) {
    size_t mid = nums.size() / 2;
    std::vector<int> left(nums.begin(), nums.begin() + mid);
    std::vector<int> right(nums.begin() + mid, nums.end());

    auto allSums = [](const std::vector<int>& arr) -> std::vector<long long> {
        size_t n = arr.size();
        size_t total = 1ULL << n;
        std::vector<long long> sums(total);
        for (size_t mask = 0; mask < total; ++mask) {
            long long sum = 0;
            for (size_t i = 0; i < n; ++i) {
                if (mask & (1ULL << i)) sum += arr[i];
            }
            sums[mask] = sum;
        }
        return sums;
    };

    std::vector<long long> leftSums = allSums(left);
    std::vector<long long> rightSums = allSums(right);
    std::sort(rightSums.begin(), rightSums.end());

    long long best = LLONG_MAX;

    for (long long sL : leftSums) {
        long long need = goal - sL;
        auto it = std::lower_bound(rightSums.begin(), rightSums.end(), need);
        if (it != rightSums.end()) {
            long long cur = std::llabs(sL + *it - goal);
            if (cur < best) best = cur;
        }
        if (it != rightSums.begin()) {
            --it;
            long long cur = std::llabs(sL + *it - goal);
            if (cur < best) best = cur;
        }
        if (best == 0) return 0;
    }
    return best;
}

