bool canChoose(const std::vector<std::vector<int>>& groups, const std::vector<int>& nums) {
    int pos = 0;
    for (const auto& g : groups) {
        std::vector<int> lps(g.size(), 0);
        for (int i = 1, len = 0; i < static_cast<int>(g.size()); ) {
            if (g[i] == g[len]) {
                lps[i++] = ++len;
            } else if (len) {
                len = lps[len - 1];
            } else {
                ++i;
            }
        }

        int i = pos, j = 0, found = -1;
        while (i < static_cast<int>(nums.size())) {
            if (nums[i] == g[j]) {
                ++i;
                ++j;
                if (j == static_cast<int>(g.size())) {
                    found = i - static_cast<int>(g.size());
                    break;
                }
            } else if (j) {
                j = lps[j - 1];
            } else {
                ++i;
            }
        }

        if (found == -1) return false;
        pos = found + static_cast<int>(g.size());
    }
    return true;
}

