std::string longestNiceSubstring(const std::string& s) {
    int n = static_cast<int>(s.size());
    int bestStart = 0, bestLen = 0;
    for (int target = 1; target <= 26; ++target) {
        int lower[26] = {0}, upper[26] = {0};
        int unique = 0, both = 0;
        int left = 0;
        for (int right = 0; right < n; ++right) {
            char c = s[right];
            int idx = (c >= 'a' && c <= 'z') ? c - 'a' : c - 'A';
            bool isLower = (c >= 'a' && c <= 'z');
            if (lower[idx] == 0 && upper[idx] == 0) ++unique;
            if (isLower) {
                ++lower[idx];
                if (lower[idx] == 1 && upper[idx] > 0) ++both;
            } else {
                ++upper[idx];
                if (upper[idx] == 1 && lower[idx] > 0) ++both;
            }
            while (unique > target) {
                char cl = s[left];
                int idl = (cl >= 'a' && cl <= 'z') ? cl - 'a' : cl - 'A';
                bool isLowerL = (cl >= 'a' && cl <= 'z');
                if (isLowerL) {
                    if (lower[idl] == 1 && upper[idl] > 0) --both;
                    --lower[idl];
                } else {
                    if (upper[idl] == 1 && lower[idl] > 0) --both;
                    --upper[idl];
                }
                if (lower[idl] == 0 && upper[idl] == 0) --unique;
                ++left;
            }
            if (unique == target && both == target) {
                int len = right - left + 1;
                if (len > bestLen) {
                    bestLen = len;
                    bestStart = left;
                }
            }
        }
    }
    return s.substr(bestStart, bestLen);
}

