int gcd_int(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

std::vector<int> getCoprimes(std::vector<int>& nums, std::vector<std::vector<int>>& edges) {
    int n = nums.size();
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    std::vector<std::vector<int>> coprime(51);
    for (int i = 1; i <= 50; ++i) {
        for (int j = 1; j <= 50; ++j) {
            if (gcd_int(i, j) == 1) coprime[i].push_back(j);
        }
    }
    std::vector<int> ans(n, -1);
    int lastNode[51];
    int lastDepth[51];
    for (int i = 0; i <= 50; ++i) {
        lastNode[i] = -1;
        lastDepth[i] = -1;
    }
    struct Frame {
        int node;
        int parent;
        int depth;
        int state; // 0 = enter, 1 = exit
        int prevNode;
        int prevDepth;
    };
    std::vector<Frame> stack;
    stack.reserve(2 * n);
    stack.push_back({0, -1, 0, 0, -1, -1});
    while (!stack.empty()) {
        Frame cur = stack.back();
        stack.pop_back();
        int u = cur.node;
        if (cur.state == 0) {
            int bestNode = -1, bestDepth = -1;
            for (int v : coprime[nums[u]]) {
                if (lastNode[v] != -1 && lastDepth[v] > bestDepth) {
                    bestDepth = lastDepth[v];
                    bestNode = lastNode[v];
                }
            }
            ans[u] = bestNode;
            int prevNode = lastNode[nums[u]];
            int prevDepth = lastDepth[nums[u]];
            lastNode[nums[u]] = u;
            lastDepth[nums[u]] = cur.depth;
            stack.push_back({u, cur.parent, cur.depth, 1, prevNode, prevDepth});
            for (int v : adj[u]) {
                if (v == cur.parent) continue;
                stack.push_back({v, u, cur.depth + 1, 0, -1, -1});
            }
        } else {
            lastNode[nums[u]] = cur.prevNode;
            lastDepth[nums[u]] = cur.prevDepth;
        }
    }
    return ans;
}

#include <bits/stdc++.h>

int longestPalindromeFromSubsequences(const std::string& word1, const std::string& word2) {
    size_t n = word1.size();
    size_t m = word2.size();
    if (n == 0 || m == 0) return 0;
    std::string rev2(word2.rbegin(), word2.rend());
    std::vector<int> prev(m + 1, 0), cur(m + 1, 0);
    for (size_t i = 1; i <= n; ++i) {
        cur[0] = 0;
        char c1 = word1[i - 1];
        for (size_t j = 1; j <= m; ++j) {
            if (c1 == rev2[j - 1]) {
                cur[j] = prev[j - 1] + 1;
            } else {
                cur[j] = prev[j] > cur[j - 1] ? prev[j] : cur[j - 1];
            }
        }
        std::swap(prev, cur);
    }
    int k = prev[m];
    int ans = 2 * k;
    std::array<bool, 256> has1{}, has2{};
    for (char c : word1) has1[static_cast<unsigned char>(c)] = true;
    for (char c : word2) has2[static_cast<unsigned char>(c)] = true;
    bool common = false;
    for (int i = 0; i < 256; ++i) {
        if (has1[i] && has2[i]) { common = true; break; }
    }
    if (common) {
        ans = std::max(ans, 2 * k + 1);
    }
    return ans;
}

