std::vector<std::vector<int>> highestPeak(const std::vector<std::vector<int>>& isWater) {
    int m = static_cast<int>(isWater.size());
    int n = static_cast<int>(isWater[0].size());
    std::vector<std::vector<int>> height(m, std::vector<int>(n, -1));
    std::vector<std::pair<int, int>> queue;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isWater[i][j] == 1) {
                height[i][j] = 0;
                queue.emplace_back(i, j);
            }
        }
    }
    const int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};
    size_t qIdx = 0;
    while (qIdx < queue.size()) {
        int x = queue[qIdx].first;
        int y = queue[qIdx].second;
        ++qIdx;
        for (const auto& d : dirs) {
            int nx = x + d[0];
            int ny = y + d[1];
            if (nx >= 0 && nx < m && ny >= 0 && ny < n && height[nx][ny] == -1) {
                height[nx][ny] = height[x][y] + 1;
                queue.emplace_back(nx, ny);
            }
        }
    }
    return height;
}

