int closestDessertCost(const std::vector<int>& baseCosts, const std::vector<int>& toppingCosts, int target) {
    std::vector<int> toppingSums;
    std::function<void(int, int)> dfs = [&](int i, int cur) {
        if (i == static_cast<int>(toppingCosts.size())) {
            toppingSums.push_back(cur);
            return;
        }
        dfs(i + 1, cur);
        dfs(i + 1, cur + toppingCosts[i]);
        dfs(i + 1, cur + 2 * toppingCosts[i]);
    };
    dfs(0, 0);
    std::sort(toppingSums.begin(), toppingSums.end());

    long long best = LLONG_MAX;
    auto update = [&](int cost) {
        long long diff = std::llabs(static_cast<long long>(cost) - target);
        long long bestDiff = best == LLONG_MAX ? LLONG_MAX : std::llabs(best - target);
        if (diff < bestDiff || (diff == bestDiff && cost < best)) {
            best = cost;
        }
    };

    for (int base : baseCosts) {
        int need = target - base;
        int lo = 0, hi = static_cast<int>(toppingSums.size()) - 1;
        while (lo <= hi) {
            int mid = (lo + hi) >> 1;
            if (toppingSums[mid] < need) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        if (lo < static_cast<int>(toppingSums.size())) {
            update(base + toppingSums[lo]);
        }
        if (hi >= 0) {
            update(base + toppingSums[hi]);
        }
    }
    return static_cast<int>(best);
}

