std::vector<double> getCollisionTimes(const std::vector<std::vector<int>>& cars) {
    int n = static_cast<int>(cars.size());
    std::vector<double> answer(n, -1.0);
    std::vector<int> stack;
    for (int i = n - 1; i >= 0; --i) {
        while (!stack.empty()) {
            int j = stack.back();
            double speedI = static_cast<double>(cars[i][1]);
            double speedJ = static_cast<double>(cars[j][1]);
            if (speedI <= speedJ) {
                stack.pop_back();
                continue;
            }
            double time = (static_cast<double>(cars[j][0]) - static_cast<double>(cars[i][0])) / (speedI - speedJ);
            if (answer[j] < 0.0 || time <= answer[j]) {
                answer[i] = time;
                break;
            }
            stack.pop_back();
        }
        stack.push_back(i);
    }
    return answer;
}

