int minimumChanges(std::vector<int> nums, int k) {
    const int MAXX = 1024;
    const int NEG = -1000000000;
    int n = static_cast<int>(nums.size());
    int p = k;  // period length
    std::vector<std::vector<int>> groups(p);
    for (int i = 0; i < n; ++i) groups[i % p].push_back(nums[i]);
    int dp[MAXX];
    int ndp[MAXX];
    int freq[MAXX];
    for (int i = 0; i < MAXX; ++i) dp[i] = NEG;
    dp[0] = 0;
    for (int r = 0; r < p; ++r) {
        std::fill(freq, freq + MAXX, 0);
        for (int v : groups[r]) ++freq[v];
        int bestPrev = NEG;
        for (int i = 0; i < MAXX; ++i) if (dp[i] > bestPrev) bestPrev = dp[i];
        for (int i = 0; i < MAXX; ++i) ndp[i] = bestPrev;
        for (int cur = 0; cur < MAXX; ++cur) {
            if (dp[cur] == NEG) continue;
            for (int val = 0; val < MAXX; ++val) {
                int add = freq[val];
                if (add == 0) continue;
                int nx = cur ^ val;
                int cand = dp[cur] + add;
                if (cand > ndp[nx]) ndp[nx] = cand;
            }
        }
        std::copy(ndp, ndp + MAXX, dp);
    }
    int unchanged = dp[0];
    return n - unchanged;
}

