double maxAverageRatio(std::vector<std::vector<int>>& classes, int extraStudents) {
    int n = static_cast<int>(classes.size());
    std::vector<int> pass(n), total(n);
    for (int i = 0; i < n; ++i) {
        pass[i] = classes[i][0];
        total[i] = classes[i][1];
    }
    auto gain = [&](int p, int t) -> double {
        return static_cast<double>(p + 1) / (t + 1) - static_cast<double>(p) / t;
    };
    std::priority_queue<std::pair<double, int>> pq;
    for (int i = 0; i < n; ++i) {
        pq.emplace(gain(pass[i], total[i]), i);
    }
    for (int k = 0; k < extraStudents; ++k) {
        auto cur = pq.top();
        pq.pop();
        int idx = cur.second;
        ++pass[idx];
        ++total[idx];
        pq.emplace(gain(pass[idx], total[idx]), idx);
    }
    double sum = 0.0;
    for (int i = 0; i < n; ++i) {
        sum += static_cast<double>(pass[i]) / total[i];
    }
    double result = sum / n;
    long long rounded = static_cast<long long>(result * 1e5 + 0.5);
    return rounded / 1e5;
}

