int maximumScore(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    int left = k, right = k;
    int curMin = nums[k];
    int best = curMin;
    while (left > 0 || right < n - 1) {
        if (right == n - 1) {
            --left;
            curMin = std::min(curMin, nums[left]);
        } else if (left == 0) {
            ++right;
            curMin = std::min(curMin, nums[right]);
        } else {
            if (nums[left - 1] > nums[right + 1]) {
                --left;
                curMin = std::min(curMin, nums[left]);
            } else {
                ++right;
                curMin = std::min(curMin, nums[right]);
            }
        }
        best = std::max(best, curMin * (right - left + 1));
    }
    return best;
}

#include <bits/stdc++.h>
#include <vector>
#include <cstddef>

long long maxScore(const std::vector<int>& nums) {
    const int m = static_cast<int>(nums.size());
    const int fullMask = (1 << m) - 1;

    std::vector<std::vector<int>> gcd(m, std::vector<int>(m, 0));
    auto computeGcd = [](int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    };
    for (int i = 0; i < m; ++i) {
        for (int j = i + 1; j < m; ++j) {
            gcd[i][j] = computeGcd(nums[i], nums[j]);
        }
    }

    std::vector<long long> dp(1 << m, 0);
    for (int mask = 0; mask <= fullMask; ++mask) {
        int used = __builtin_popcount(mask);
        if (used % 2 != 0) continue;
        int op = used / 2 + 1;

        int i = 0;
        while (i < m && (mask & (1 << i))) ++i;
        if (i == m) continue;

        for (int j = i + 1; j < m; ++j) {
            if (mask & (1 << j)) continue;
            int newMask = mask | (1 << i) | (1 << j);
            long long candidate = dp[mask] + static_cast<long long>(op) * gcd[i][j];
            if (candidate > dp[newMask]) dp[newMask] = candidate;
        }
    }
    return dp[fullMask];
}

