struct Node {
    long long price;
    long long amount;
};

template <typename Compare>
void heapPush(std::vector<Node>& heap, const Node& node, Compare compare) {
    heap.push_back(node);
    std::size_t i = heap.size() - 1;
    while (i > 0) {
        std::size_t p = (i - 1) >> 1;
        if (compare(heap[p], heap[i])) break;
        std::swap(heap[p], heap[i]);
        i = p;
    }
}

template <typename Compare>
Node heapPop(std::vector<Node>& heap, Compare compare) {
    Node top = heap[0];
    Node last = heap.back();
    heap.pop_back();
    if (!heap.empty()) {
        heap[0] = last;
        std::size_t i = 0;
        while (true) {
            std::size_t l = i * 2 + 1;
            std::size_t r = l + 1;
            std::size_t best = i;
            if (l < heap.size() && !compare(heap[best], heap[l])) best = l;
            if (r < heap.size() && !compare(heap[best], heap[r])) best = r;
            if (best == i) break;
            std::swap(heap[i], heap[best]);
            i = best;
        }
    }
    return top;
}

long long getNumberOfBacklogOrders(const std::vector<std::vector<int>>& orders) {
    const long long MOD = 1000000007LL;
    std::vector<Node> buyHeap;
    std::vector<Node> sellHeap;

    auto compareBuy = [](const Node& a, const Node& b) { return a.price >= b.price; };
    auto compareSell = [](const Node& a, const Node& b) { return a.price <= b.price; };

    for (const auto& ord : orders) {
        long long price = ord[0];
        long long amount = ord[1];
        int type = ord[2];
        if (type == 0) { // BUY
            while (amount > 0 && !sellHeap.empty() && sellHeap[0].price <= price) {
                Node& sell = sellHeap[0];
                long long matched = amount < sell.amount ? amount : sell.amount;
                amount -= matched;
                sell.amount -= matched;
                if (sell.amount == 0) {
                    heapPop(sellHeap, compareSell);
                }
            }
            if (amount > 0) {
                heapPush(buyHeap, Node{price, amount}, compareBuy);
            }
        } else { // SELL
            while (amount > 0 && !buyHeap.empty() && buyHeap[0].price >= price) {
                Node& buy = buyHeap[0];
                long long matched = amount < buy.amount ? amount : buy.amount;
                amount -= matched;
                buy.amount -= matched;
                if (buy.amount == 0) {
                    heapPop(buyHeap, compareBuy);
                }
            }
            if (amount > 0) {
                heapPush(sellHeap, Node{price, amount}, compareSell);
            }
        }
    }

    long long total = 0;
    for (const Node& node : buyHeap) {
        total = (total + node.amount) % MOD;
    }
    for (const Node& node : sellHeap) {
        total = (total + node.amount) % MOD;
    }
    return total;
}

#include <bits/stdc++.h>

int maxValue(int n, int index, int maxSum) {
    auto sideSum = [&](long long x, long long len) -> long long {
        if (len == 0) return 0;
        if (x > len) {
            long long high = x - 1;
            long long low = x - len;
            return (high + low) * len / 2;
        } else {
            long long high = x - 1;
            long long sum = high * (high + 1) / 2;
            long long remaining = len - high;
            sum += remaining;
            return sum;
        }
    };
    auto can = [&](long long x) -> bool {
        long long left = index;
        long long right = n - index - 1;
        long long total = sideSum(x, left) + sideSum(x, right) + x;
        return total <= maxSum;
    };
    long long lo = 1, hi = maxSum;
    while (lo < hi) {
        long long mid = (lo + hi + 1) / 2;
        if (can(mid)) lo = mid;
        else hi = mid - 1;
    }
    return static_cast<int>(lo);
}

