    while (i < word.size()) {
        if (word[i] >= '0' && word[i] <= '9') {
            std::size_t j = i;
            while (j < word.size() && word[j] >= '0' && word[j] <= '9') {
                ++j;
            }
            std::string num = word.substr(i, j - i);
            std::size_t pos = 0;
            while (pos < num.size() && num[pos] == '0') {
                ++pos;
