struct TrieNode {
    int child[2];
    int cnt;
    TrieNode() : cnt(0) { child[0] = child[1] = -1; }
};

long long countPairs(const std::vector<int>& nums, int low, int high) {
    const int MAX_BIT = 31; // enough for 32-bit signed integers
    auto insert = [&](int x, std::vector<TrieNode>& trie) {
        int node = 0;
        for (int i = MAX_BIT - 1; i >= 0; --i) {
            int b = (x >> i) & 1;
            if (trie[node].child[b] == -1) {
                trie[node].child[b] = static_cast<int>(trie.size());
                trie.emplace_back();
            }
            node = trie[node].child[b];
            ++trie[node].cnt;
        }
    };

    auto query = [&](int x, int K, const std::vector<TrieNode>& trie) -> long long {
        if (K < 0) return 0;
        long long res = 0;
        int node = 0;
        for (int i = MAX_BIT - 1; i >= 0; --i) {
            if (node == -1) break;
            int xb = (x >> i) & 1;
            int kb = (K >> i) & 1;
            if (kb == 1) {
                int childIdx = trie[node].child[xb];
                if (childIdx != -1) res += trie[childIdx].cnt;
                node = trie[node].child[1 - xb];
            } else {
                node = trie[node].child[xb];
            }
        }
        if (node != -1) res += trie[node].cnt; // numbers whose XOR with x is exactly K also satisfy <= K
        return res;
    };

    auto countLessOrEqual = [&](int bound) -> long long {
        std::vector<TrieNode> trie;
        trie.reserve((nums.size() + 1) * MAX_BIT);
        trie.emplace_back(); // root
        long long ans = 0;
        for (int v : nums) {
            ans += query(v, bound, trie);
            insert(v, trie);
        }
        return ans;
    };

    return countLessOrEqual(high) - countLessOrEqual(low - 1);
}

