long long maxNiceDivisors(long long primeFactors) {
    const long long MOD = 1000000007LL;
    auto modPow = [&](long long base, long long exp) -> long long {
        long long res = 1;
        base %= MOD;
        while (exp > 0) {
            if (exp & 1LL) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1LL;
        }
        return res;
    };
    if (primeFactors == 1) return 1;
    long long a = primeFactors / 3;
    long long r = primeFactors % 3;
    if (r == 0) {
        return modPow(3, a);
    }
    if (r == 1) {
        return (modPow(3, a - 1) * 4) % MOD;
    }
    return (modPow(3, a) * 2) % MOD;
}

