#include <bits/stdc++.h>

int maxHappyGroups(int batchSize, std::vector<int>& groups) {
    std::vector<int> cnt(batchSize, 0);
    for (int g : groups) ++cnt[g % batchSize];
    int baseHappy = cnt[0];
    cnt[0] = 0;

    for (int r = 1; r * 2 < batchSize; ++r) {
        int m = std::min(cnt[r], cnt[batchSize - r]);
        baseHappy += m;
        cnt[r] -= m;
        cnt[batchSize - r] -= m;
    }
    if (batchSize % 2 == 0) {
        int r = batchSize / 2;
        baseHappy += cnt[r] / 2;
        cnt[r] %= 2;
    }

    std::unordered_map<long long, int> memo;

    auto encode = [&](const std::vector<int>& c) -> long long {
        long long key = 0;
        for (int i = 1; i < batchSize; ++i) {
            key = key * 31 + c[i];
        }
        return key;
    };

    std::function<int(std::vector<int>&, int)> dfs = [&](std::vector<int>& c, int cur) -> int {
        long long key = (encode(c) << 4) | cur;
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        int best = 0;
        for (int r = 1; r < batchSize; ++r) {
            if (c[r] == 0) continue;
            c[r]--;
            int add = (cur == 0) ? 1 : 0;
            int nxt = dfs(c, (cur + r) % batchSize);
            best = std::max(best, add + nxt);
            c[r]++;
        }
        memo[key] = best;
        return best;
    };

    int extra = dfs(cnt, 0);
    return baseHappy + extra;
}

