std::vector<int> findingUsersActiveMinutes(const std::vector<std::vector<int>>& logs, int k) {
    std::unordered_map<int, std::unordered_set<int>> minutesPerUser;
    for (const auto& entry : logs) {
        int id = entry[0];
        int minute = entry[1];
        minutesPerUser[id].insert(minute);
    }
    std::vector<int> answer(k, 0);
    for (const auto& pair : minutesPerUser) {
        int uam = static_cast<int>(pair.second.size());
        if (uam >= 1 && uam <= k) {
            answer[uam - 1]++;
