int minAbsoluteSumDiff(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    const int MOD = 1000000007;
    int n = static_cast<int>(nums1.size());
    std::vector<int> sorted = nums1;
    std::sort(sorted.begin(), sorted.end());

    auto lowerBound = [&](const std::vector<int>& arr, int target) -> int {
        int lo = 0, hi = static_cast<int>(arr.size());
        while (lo < hi) {
            int mid = (lo + hi) >> 1;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    };

    long long totalDiff = 0;
    long long bestGain = 0;
    for (int i = 0; i < n; ++i) {
        int a = nums1[i];
        int b = nums2[i];
        long long curDiff = std::llabs(static_cast<long long>(a) - b);
        totalDiff = (totalDiff + curDiff) % MOD;

        int pos = lowerBound(sorted, b);
        long long minDiff = curDiff;
        if (pos < n) {
            long long cand = std::llabs(static_cast<long long>(sorted[pos]) - b);
            if (cand < minDiff) minDiff = cand;
        }
        if (pos > 0) {
            long long cand = std::llabs(static_cast<long long>(sorted[pos - 1]) - b);
            if (cand < minDiff) minDiff = cand;
        }

        long long gain = curDiff - minDiff;
        if (gain > bestGain) bestGain = gain;
    }

    long long answer = (totalDiff - bestGain + MOD) % MOD;
    return static_cast<int>(answer);
}

