int countNicePairs(const std::vector<int>& nums) {
    const long long MOD = 1000000007LL;
    auto rev = [](int x) -> long long {
        long long r = 0;
        while (x > 0) {
            r = r * 10 + (x % 10);
            x /= 10;
        }
        return r;
    };
    std::unordered_map<long long, long long> freq;
    freq.reserve(nums.size() * 2);
    freq.max_load_factor(0.7);
    long long ans = 0;
    for (int v : nums) {
        long long diff = static_cast<long long>(v) - rev(v);
        auto it = freq.find(diff);
        if (it != freq.end()) {
            ans = (ans + it->second) % MOD;
            ++it->second;
        } else {
            freq.emplace(diff, 1);
        }
    }
    return static_cast<int>(ans);
}

