int minSideJumps(const std::vector<int>& obstacles) {
    const int INF = std::numeric_limits<int>::max() / 2;
    int dp[3] = {1, 0, 1};
    for (size_t i = 1; i < obstacles.size(); ++i) {
        int obs = obstacles[i] - 1;
        if (obs >= 0) dp[obs] = INF;
        int minAll = std::min({dp[0], dp[1], dp[2]});
        for (int l = 0; l < 3; ++l) {
            if (l != obs) dp[l] = std::min(dp[l], minAll + 1);
        }
    }
    return std::min({dp[0], dp[1], dp[2]});
}

