    }
    std::vector<unsigned int> freq(maxVal + 1);
    for (int v : nums) {
        ++freq[v];
    }
    auto gcd = [](int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    };
    int answer = 0;
    for (int g = 1; g <= maxVal; ++g) {
        int cur = 0;
        for (int m = g; m <= maxVal; m += g) {
            if (freq[m]) {
                cur = cur ? gcd(cur, m) : m;
            }
        }
        if (cur == g) ++answer;
    }
    return answer;
}

