std::vector<int> countPoints(const std::vector<std::vector<int>>& points, const std::vector<std::vector<int>>& queries) {
    const int MAXC = 500;
    const int SZ = MAXC + 1;
    static int grid[SZ][SZ];
    for (int i = 0; i < SZ; ++i)
        for (int j = 0; j < SZ; ++j)
            grid[i][j] = 0;
    for (const auto& p : points) {
        int x = p[0];
        int y = p[1];
        ++grid[x][y];
    }
    static int pref[SZ][SZ + 1];
    for (int y = 0; y < SZ; ++y) {
        pref[y][0] = 0;
        for (int x = 0; x < SZ; ++x) {
            pref[y][x + 1] = pref[y][x] + grid[x][y];
        }
    }
    std::vector<int> ans;
    ans.reserve(queries.size());
    for (const auto& q : queries) {
        int cx = q[0];
        int cy = q[1];
        int r = q[2];
        long long r2 = 1LL * r * r;
        int cnt = 0;
        int yStart = std::max(0, cy - r);
        int yEnd = std::min(MAXC, cy + r);
        for (int y = yStart; y <= yEnd; ++y) {
            long long dy = y - cy;
            long long remain = r2 - dy * dy;
            if (remain < 0) continue;
            int dx = static_cast<int>(std::sqrt(static_cast<double>(remain)));
            int xL = std::max(0, cx - dx);
            int xR = std::min(MAXC, cx + dx);
            cnt += pref[y][xR + 1] - pref[y][xL];
        }
        ans.push_back(cnt);
    }
    return ans;
}

