const long long MOD = 1000000007LL;

long long modPow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int makeStringSorted(const std::string& s) {
    int n = static_cast<int>(s.size());
    std::vector<long long> fact(n + 1), invFact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i % MOD;
    invFact[n] = modPow(fact[n], MOD - 2);
    for (int i = n; i > 0; --i) invFact[i - 1] = invFact[i] * i % MOD;

    int cnt[26] = {0};
    for (char ch : s) cnt[ch - 'a']++;

    long long den = 1;
    for (int i = 0; i < 26; ++i) den = den * invFact[cnt[i]] % MOD;

    long long ans = 0;
    for (int i = 0; i < n; ++i) {
        int cur = s[i] - 'a';
        int remaining = n - i - 1;
        long long base = fact[remaining] * den % MOD;
        for (int c = 0; c < cur; ++c) {
            if (cnt[c] > 0) {
                ans = (ans + base * cnt[c]) % MOD;
            }
        }
        den = den * cnt[cur] % MOD;
        cnt[cur]--;
    }
    return static_cast<int>(ans % MOD);
}

#include <bits/stdc++.h>

class MKAverage {
    int m, k;
    std::queue<int> window;
    std::multiset<int> low;
    std::multiset<int> high;
    std::multiset<int> mid;
    long long sumMid = 0;

    void balance() {
        while (low.size() > (size_t)k) {
            auto it = std::prev(low.end());
            int val = *it;
            low.erase(it);
            mid.insert(val);
            sumMid += val;
        }
        while (low.size() < (size_t)k && !mid.empty()) {
            auto it = mid.begin();
            int val = *it;
            mid.erase(it);
            sumMid -= val;
            low.insert(val);
        }
        while (high.size() > (size_t)k) {
            auto it = high.begin();
            int val = *it;
            high.erase(it);
            mid.insert(val);
            sumMid += val;
        }
        while (high.size() < (size_t)k && !mid.empty()) {
            auto it = std::prev(mid.end());
            int val = *it;
            mid.erase(it);
            sumMid -= val;
            high.insert(val);
        }
    }

public:
    MKAverage(int m_, int k_) : m(m_), k(k_) {}

    void addElement(int num) {
        window.push(num);
        if (!low.empty() && num <= *std::prev(low.end())) {
            low.insert(num);
        } else if (!high.empty() && num >= *high.begin()) {
            high.insert(num);
        } else {
            mid.insert(num);
            sumMid += num;
        }
        balance();

        if ((int)window.size() > m) {
            int old = window.front();
            window.pop();
            auto itLow = low.find(old);
            if (itLow != low.end()) {
                low.erase(itLow);
            } else {
                auto itHigh = high.find(old);
                if (itHigh != high.end()) {
                    high.erase(itHigh);
                } else {
                    auto itMid = mid.find(old);
                    if (itMid != mid.end()) {
                        mid.erase(itMid);
                        sumMid -= old;
                    }
                }
            }
            balance();
        }
    }

    int calculateMKAverage() {
        if ((int)window.size() < m) return -1;
        return static_cast<int>(sumMid / (m - 2 * k));
    }
};

