std::vector<int> getOrder(std::vector<std::vector<int>>& tasks) {
    int n = static_cast<int>(tasks.size());
    std::vector<std::tuple<long long, long long, int>> sorted;
    sorted.reserve(n);
    for (int i = 0; i < n; ++i) {
        sorted.emplace_back(static_cast<long long>(tasks[i][0]),
                            static_cast<long long>(tasks[i][1]),
                            i);
    }
    std::sort(sorted.begin(), sorted.end(),
              [](const auto& a, const auto& b) {
                  return std::get<0>(a) < std::get<0>(b);
              });

    struct Compare {
        bool operator()(const std::tuple<long long, long long, int>& a,
                        const std::tuple<long long, long long, int>& b) const {
            if (std::get<1>(a) != std::get<1>(b))
                return std::get<1>(a) > std::get<1>(b);
            return std::get<2>(a) > std::get<2>(b);
        }
    };

    std::priority_queue<std::tuple<long long, long long, int>,
                        std::vector<std::tuple<long long, long long, int>>,
                        Compare> pq;

    std::vector<int> result;
    result.reserve(n);
    long long time = 0;
    int idx = 0;

    while (idx < n || !pq.empty()) {
        if (pq.empty() && time < std::get<0>(sorted[idx])) {
            time = std::get<0>(sorted[idx]);
        }
        while (idx < n && std::get<0>(sorted[idx]) <= time) {
            pq.push(sorted[idx]);
            ++idx;
        }
        auto cur = pq.top();
        pq.pop();
        result.push_back(std::get<2>(cur));
        time += std::get<1>(cur);
    }

    return result;
}

