int maxFrequency(std::vector<int>& nums, long long k) {
    std::sort(nums.begin(), nums.end());
    std::size_t left = 0;
    long long windowSum = 0;
    int best = 1;
    for (std::size_t right = 0; right < nums.size(); ++right) {
        windowSum += nums[right];
        while (static_cast<long long>(nums[right]) * (right - left + 1) - windowSum > k) {
            windowSum -= nums[left];
            ++left;
        }
        int current = static_cast<int>(right - left + 1);
        if (current > best) best = current;
    }
    return best;
}

