int maxBuilding(int n, std::vector<std::vector<int>> restrictions) {
    restrictions.push_back({1, 0});
    restrictions.push_back({n, n - 1});
    std::sort(restrictions.begin(), restrictions.end(),
        [](const std::vector<int>& a, const std::vector<int>& b) {
            return a[0] < b[0];
        });
    for (size_t i = 1; i < restrictions.size(); ++i) {
        int dist = restrictions[i][0] - restrictions[i - 1][0];
        restrictions[i][1] = std::min(restrictions[i][1], restrictions[i - 1][1] + dist);
    }
    for (int i = static_cast<int>(restrictions.size()) - 2; i >= 0; --i) {
        int dist = restrictions[i + 1][0] - restrictions[i][0];
        restrictions[i][1] = std::min(restrictions[i][1], restrictions[i + 1][1] + dist);
    }
    int answer = 0;
    for (size_t i = 0; i + 1 < restrictions.size(); ++i) {
        int leftPos = restrictions[i][0];
        int rightPos = restrictions[i + 1][0];
        int leftH = restrictions[i][1];
        int rightH = restrictions[i + 1][1];
        int distance = rightPos - leftPos;
        int peak = (leftH + rightH + distance) / 2;
        answer = std::max(answer, peak);
        answer = std::max(answer, leftH);
        answer = std::max(answer, rightH);
    }
    return answer;
}

