std::vector<int> closestRoom(std::vector<std::vector<int>>& rooms, std::vector<std::vector<int>>& queries) {
    std::vector<std::pair<int, int>> roomList;
    roomList.reserve(rooms.size());
    for (const auto& r : rooms) {
        roomList.emplace_back(r[1], r[0]);
    }
    std::sort(roomList.begin(), roomList.end(),
              [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
                  return a.first > b.first;
              });

    std::vector<std::tuple<int, int, int>> queryList;
    queryList.reserve(queries.size());
    for (int i = 0; i < static_cast<int>(queries.size()); ++i) {
        queryList.emplace_back(queries[i][1], queries[i][0], i);
    }
    std::sort(queryList.begin(), queryList.end(),
              [](const std::tuple<int, int, int>& a, const std::tuple<int, int, int>& b) {
                  return std::get<0>(a) > std::get<0>(b);
              });

    std::set<int> eligibleIds;
    std::vector<int> answer(queries.size(), -1);
    std::size_t roomIdx = 0;

    for (const auto& q : queryList) {
        int minSize = std::get<0>(q);
        int preferred = std::get<1>(q);
        int idx = std::get<2>(q);

        while (roomIdx < roomList.size() && roomList[roomIdx].first >= minSize) {
            eligibleIds.insert(roomList[roomIdx].second);
            ++roomIdx;
        }

        if (eligibleIds.empty()) {
            answer[idx] = -1;
            continue;
        }

        long long bestDiff = LLONG_MAX;
        int bestId = -1;

        auto it = eligibleIds.lower_bound(preferred);
        if (it != eligibleIds.end()) {
            int cand = *it;
            long long diff = std::llabs(static_cast<long long>(cand) - static_cast<long long>(preferred));
            if (diff < bestDiff || (diff == bestDiff && cand < bestId)) {
                bestDiff = diff;
                bestId = cand;
            }
        }
        if (it != eligibleIds.begin()) {
            --it;
            int cand = *it;
            long long diff = std::llabs(static_cast<long long>(cand) - static_cast<long long>(preferred));
            if (diff < bestDiff || (diff == bestDiff && cand < bestId)) {
                bestDiff = diff;
                bestId = cand;
            }
        }

        answer[idx] = bestId;
    }

    return answer;
}

