int maximumPopulation(const std::vector<std::vector<int>>& logs) {
    const int OFFSET = 1950;
    const int RANGE = 101;
    std::vector<int> diff(RANGE + 1, 0);
    for (size_t i = 0; i < logs.size(); ++i) {
        int birth = logs[i][0] - OFFSET;
        int death = logs[i][1] - OFFSET;
        diff[birth] += 1;
        diff[death] -= 1;
    }
    int cur = 0, best = -1, answer = OFFSET;
    for (int y = 0; y < RANGE; ++y) {
        cur += diff[y];
        if (cur > best) {
            best = cur;
            answer = y + OFFSET;
        }
    }
    return answer;
}

