bool dfs(const std::string& s, int pos, long long prev, int taken) {
    int n = static_cast<int>(s.size());
    if (pos == n) return taken >= 2;
    long long cur = 0;
    for (int i = pos; i < n; ++i) {
        if (cur > LLONG_MAX / 10) break;
        cur = cur * 10 + (s[i] - '0');
        if (taken == 0) {
            if (dfs(s, i + 1, cur, 1)) return true;
        } else {
            long long diff = prev - cur;
            if (diff == 1) {
                if (dfs(s, i + 1, cur, taken + 1)) return true;
            } else if (diff < 1) {
                break;
            }
        }
    }
    return false;
}

