long long minSwaps(const std::string& num, int k) {
    std::vector<char> target(num.begin(), num.end());
    for (int step = 0; step < k; ++step) {
        int i = static_cast<int>(target.size()) - 2;
        while (i >= 0 && target[i] >= target[i + 1]) --i;
        int j = static_cast<int>(target.size()) - 1;
        while (target[j] <= target[i]) --j;
        std::swap(target[i], target[j]);
        int left = i + 1;
        int right = static_cast<int>(target.size()) - 1;
        while (left < right) {
            std::swap(target[left], target[right]);
            ++left;
            --right;
        }
    }
    std::vector<char> orig(num.begin(), num.end());
    long long swaps = 0;
    for (size_t i = 0; i < orig.size(); ++i) {
        if (orig[i] == target[i]) continue;
        size_t j = i + 1;
        while (orig[j] != target[i]) ++j;
        while (j > i) {
            std::swap(orig[j], orig[j - 1]);
            ++swaps;
            --j;
        }
    }
    return swaps;
}

