std::vector<int> minInterval(const std::vector<std::vector<int>>& intervals, const std::vector<int>& queries) {
    std::vector<std::vector<int>> sortedIntervals = intervals;
    std::sort(sortedIntervals.begin(), sortedIntervals.end(),
              [](const std::vector<int>& a, const std::vector<int>& b) {
                  return a[0] < b[0];
              });

    std::vector<std::pair<int, int>> qWithIdx;
    qWithIdx.reserve(queries.size());
    for (size_t i = 0; i < queries.size(); ++i) {
        qWithIdx.emplace_back(queries[i], static_cast<int>(i));
    }
    std::sort(qWithIdx.begin(), qWithIdx.end(),
              [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
                  return a.first < b.first;
              });

    struct Compare {
        bool operator()(const std::pair<int, int>& a, const std::pair<int, int>& b) const {
            if (a.first != b.first) return a.first > b.first;
            return a.second > b.second;
        }
    };
    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, Compare> heap;

    std::vector<int> ans(queries.size(), -1);
    size_t intPtr = 0;

    for (const auto& qi : qWithIdx) {
        int q = qi.first;
        int idx = qi.second;

        while (intPtr < sortedIntervals.size() && sortedIntervals[intPtr][0] <= q) {
            int l = sortedIntervals[intPtr][0];
            int r = sortedIntervals[intPtr][1];
            int size = r - l + 1;
            heap.emplace(size, r);
            ++intPtr;
        }

        while (!heap.empty() && heap.top().second < q) {
            heap.pop();
        }

        if (!heap.empty()) {
            ans[idx] = heap.top().first;
        }
    }

    return ans;
}

