int largestPathValue(const std::string& colors, const std::vector<std::vector<int>>& edges) {
    int n = static_cast<int>(colors.size());
    std::vector<std::vector<int>> adj(n);
    std::vector<uint32_t> indeg(n, 0);
    for (const auto& e : edges) {
        int a = e[0];
        int b = e[1];
        adj[a].push_back(b);
        indeg[b]++;
    }

    std::vector<std::array<uint16_t, 26>> dp(n);
    for (int i = 0; i < n; ++i) {
        dp[i][static_cast<int>(colors[i] - 'a')] = 1;
    }

    std::queue<int> q;
    for (int i = 0; i < n; ++i) {
        if (indeg[i] == 0) q.push(i);
    }

    int processed = 0;
    int answer = 0;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        ++processed;
        for (int c = 0; c < 26; ++c) {
            if (dp[u][c] > answer) answer = dp[u][c];
        }
        for (int v : adj[u]) {
            for (int c = 0; c < 26; ++c) {
                uint16_t cand = dp[u][c] + (static_cast<int>(colors[v] - 'a') == c ? 1 : 0);
                if (cand > dp[v][c]) dp[v][c] = cand;
            }
            if (--indeg[v] == 0) q.push(v);
        }
    }

    return processed == n ? answer : -1;
}

