long long maxSumMinProduct(const std::vector<int>& nums) {
    std::size_t n = nums.size();
    if (n == 0) return 0;
    const long long MOD = 1000000007LL;

    std::vector<long long> prefix(n + 1, 0LL);
    for (std::size_t i = 0; i < n; ++i) {
        prefix[i + 1] = prefix[i] + static_cast<long long>(nums[i]);
    }

    std::vector<int> left(n), right(n);
    std::vector<int> st;
    st.reserve(n);

    for (std::size_t i = 0; i < n; ++i) {
        while (!st.empty() && nums[st.back()] >= nums[i]) {
            st.pop_back();
        }
        left[i] = st.empty() ? -1 : st.back();
        st.push_back(static_cast<int>(i));
    }

    st.clear();

    for (int i = static_cast<int>(n) - 1; i >= 0; --i) {
        while (!st.empty() && nums[st.back()] >= nums[i]) {
            st.pop_back();
        }
        right[i] = st.empty() ? static_cast<int>(n) : st.back();
        st.push_back(i);
    }

    long long maxProd = 0;
    for (std::size_t i = 0; i < n; ++i) {
        int l = left[i];
        int r = right[i];
        long long subSum = prefix[r] - prefix[l + 1];
        long long prod = static_cast<long long>(nums[i]) * subSum;
        if (prod > maxProd) {
            maxProd = prod;
        }
    }

    return maxProd % MOD;
}

