std::vector<long long> incrementalMemoryLeak(long long memory1, long long memory2) {
    long long t = 1;
    while (true) {
        if (memory1 >= memory2) {
            if (memory1 >= t) {
                memory1 -= t;
                ++t;
            } else {
                break;
            }
        } else {
            if (memory2 >= t) {
                memory2 -= t;
                ++t;
            } else {
                break;
            }
        }
    }
    return std::vector<long long>{t, memory1, memory2};
}

