        for (int v : nums2) ++freq[v];
    }
    void add(int index, int val) {
        int oldVal = nums2[index];
        int newVal = oldVal + val;
        nums2[index] = newVal;
        auto it = freq.find(oldVal);
        if (it != freq.end()) { if (it->second==1) freq.erase(it); else --(it->second); }
        ++freq[newVal];
    }
    long long count(int tot) const {
        long long pairs = 0;
        for (int x : nums1) { auto it = freq.find(tot-x); if (it != freq.end()) pairs += it->second; }
        return pairs;
    }
};

