long long sumOfFlooredPairs(const std::vector<int>& nums) {
    int maxVal = 0;
    for (int v : nums) if (v > maxVal) maxVal = v;
    std::vector<long long> cnt(maxVal + 1, 0);
    for (int v : nums) ++cnt[v];
    std::vector<long long> pref(maxVal + 1, 0);
    for (int i = 1; i <= maxVal; ++i) pref[i] = pref[i - 1] + cnt[i];
    long long answer = 0;
    for (int d = 1; d <= maxVal; ++d) {
        long long freqDen = cnt[d];
        if (freqDen == 0) continue;
        for (int k = 1; (long long)k * d <= maxVal; ++k) {
            int left = k * d;
            int right = std::min((k + 1) * d - 1, maxVal);
            long long rangeCount = pref[right] - pref[left - 1];
            if (rangeCount == 0) continue;
            answer += freqDen * k * rangeCount;
        }
    }
    return answer;
}

