int minSwaps(const std::string& s) {
    int n = static_cast<int>(s.size());
    int zeros = 0, ones = 0;
    for (char ch : s) {
        if (ch == '0') ++zeros;
        else ++ones;
    }

    auto swapsIfPossible = [&](char startChar) -> int {
        int needZeros = (startChar == '0') ? (n + 1) / 2 : n / 2;
        int needOnes = n - needZeros;
        if (zeros != needZeros || ones != needOnes) return INT_MAX;

        int zeroToOne = 0;
        for (int i = 0; i < n; ++i) {
            char expected = (i % 2 == 0) ? startChar : (startChar == '0' ? '1' : '0');
            if (s[i] != expected) {
                if (s[i] == '0') ++zeroToOne;
            }
        }
        return zeroToOne;
    };

    int ans = std::min(swapsIfPossible('0'), swapsIfPossible('1'));
    return ans == INT_MAX ? -1 : ans;
}

