bool longerOnesThanZeros(const std::string& s) {
    if (s.empty()) return false;
    int maxOnes = 0, maxZeros = 0;
    char currChar = s[0];
    int currLen = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        if (s[i] == currChar) {
            ++currLen;
        } else {
            if (currChar == '1') maxOnes = std::max(maxOnes, currLen);
            else maxZeros = std::max(maxZeros, currLen);
            currChar = s[i];
            currLen = 1;
        }
    }
    if (currChar == '1') maxOnes = std::max(maxOnes, currLen);
    else maxZeros = std::max(maxZeros, currLen);
    return maxOnes > maxZeros;
}

