long long rearrangeSticks(int n, int k) {
    const long long MOD = 1000000007LL;
    if (k > n) return 0;
    std::vector<long long> dp(k + 1, 0);
    dp[0] = 1;
    for (int i = 1; i <= n; ++i) {
        int limit = std::min(i, k);
        for (int j = limit; j >= 1; --j) {
            dp[j] = (dp[j - 1] + static_cast<long long>(i - 1) * dp[j]) % MOD;
        }
        dp[0] = 0;
    }
    return dp[k];
}

