int minSpeedOnTime(const std::vector<int>& dist, double hour) {
    int n = static_cast<int>(dist.size());

    auto can = [&](int speed) -> bool {
        double total = 0.0;
        for (int i = 0; i < n - 1; ++i) {
            total += std::ceil(static_cast<double>(dist[i]) / speed);
        }
        total += static_cast<double>(dist[n - 1]) / speed;
        return total <= hour + 1e-9;
    };

    if (hour < n - 1) return -1;

    int lo = 1, hi = 10000000;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (can(mid)) hi = mid;
        else lo = mid + 1;
    }
    return can(lo) ? lo : -1;
}

