std::vector<int> getBiggestThree(std::vector<std::vector<int>>& grid) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    std::vector<std::vector<int>> diag1(m, std::vector<int>(n));
    std::vector<std::vector<int>> diag2(m, std::vector<int>(n));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            diag1[i][j] = grid[i][j];
            if (i > 0 && j > 0) diag1[i][j] += diag1[i - 1][j - 1];
            diag2[i][j] = grid[i][j];
            if (i > 0 && j + 1 < n) diag2[i][j] += diag2[i - 1][j + 1];
        }
    }
    std::set<int, std::greater<int>> top;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            top.insert(grid[i][j]);
            if (top.size() > 3) top.erase(std::prev(top.end()));
            for (int k = 1; i + 2 * k < m && j - k >= 0 && j + k < n; ++k) {
                int sumTL = diag2[i + k][j - k];
                if (i > 0 && j + 1 < n) sumTL -= diag2[i - 1][j + 1];
                int sumLB = diag1[i + 2 * k][j];
                if (i + k > 0 && j - k > 0) sumLB -= diag1[i + k - 1][j - k - 1];
                int sumBR = diag2[i + 2 * k][j];
                if (i + k > 0 && j + k + 1 < n) sumBR -= diag2[i + k - 1][j + k + 1];
                int sumRT = diag1[i + k][j + k];
                if (i > 0 && j > 0) sumRT -= diag1[i - 1][j - 1];
                int total = sumTL + sumLB + sumBR + sumRT
                            - (grid[i][j] + grid[i + k][j - k] + grid[i + 2 * k][j] + grid[i + k][j + k]);
                top.insert(total);
                if (top.size() > 3) top.erase(std::prev(top.end()));
            }
        }
    }
    return std::vector<int>(top.begin(), top.end());
}

