int stoneGameVIII(std::vector<int>& stones) {
    int n = stones.size();
    if (n == 1) return 0;
    long long total = 0;
    for (int v : stones) total += v;
    long long best = total; // pref[n-1] - dp[n-1] where dp[n-1]=0
    long long suffix = 0;
    long long dp_i = 0;
    for (int i = n - 2; i >= 0; --i) {
        suffix += stones[i + 1];
        long long pref_i = total - suffix;
        dp_i = best;
        long long cur = pref_i - dp_i;
        if (cur > best) best = cur;
    }
    return static_cast<int>(dp_i);
}

