#include <bits/stdc++.h>

std::vector<int> assignTasks(std::vector<int>& servers, std::vector<int>& tasks) {
    int n = servers.size();
    int m = tasks.size();
    using FreeItem = std::pair<int,int>; // weight, index
    using BusyItem = std::tuple<long long,int,int>; // freeTime, weight, index

    struct FreeComp {
        bool operator()(const FreeItem& a, const FreeItem& b) const {
            if (a.first != b.first) return a.first > b.first;
            return a.second > b.second;
        }
    };
    struct BusyComp {
        bool operator()(const BusyItem& a, const BusyItem& b) const {
            if (std::get<0>(a) != std::get<0>(b)) return std::get<0>(a) > std::get<0>(b);
            if (std::get<1>(a) != std::get<1>(b)) return std::get<1>(a) > std::get<1>(b);
            return std::get<2>(a) > std::get<2>(b);
        }
    };

    std::priority_queue<FreeItem, std::vector<FreeItem>, FreeComp> freePQ;
    std::priority_queue<BusyItem, std::vector<BusyItem>, BusyComp> busyPQ;

    for (int i = 0; i < n; ++i) {
        freePQ.emplace(servers[i], i);
    }

    std::vector<int> ans(m);
    long long curTime = 0;

    for (int i = 0; i < m; ++i) {
        curTime = i;
        while (!busyPQ.empty() && std::get<0>(busyPQ.top()) <= curTime) {
            auto t = busyPQ.top(); busyPQ.pop();
            freePQ.emplace(std::get<1>(t), std::get<2>(t));
        }
        if (freePQ.empty()) {
            curTime = std::get<0>(busyPQ.top());
            while (!busyPQ.empty() && std::get<0>(busyPQ.top()) <= curTime) {
                auto t = busyPQ.top(); busyPQ.pop();
                freePQ.emplace(std::get<1>(t), std::get<2>(t));
            }
        }
        auto server = freePQ.top(); freePQ.pop();
        ans[i] = server.second;
        busyPQ.emplace(curTime + tasks[i], server.first, server.second);
    }

    return ans;
}

#include <bits/stdc++.h>
#include <vector>
#include <cmath>
#include <algorithm>

int minSkips(const std::vector<int>& dist, int speed, double hoursBefore) {
    int n = static_cast<int>(dist.size());

    auto canFinish = [&](int maxSkips) -> bool {
        const double INF = 1e30;
        std::vector<double> dp(maxSkips + 1, INF);
        dp[0] = 0.0;

        for (int i = 0; i < n; ++i) {
            std::vector<double> ndp(maxSkips + 1, INF);
            double travel = static_cast<double>(dist[i]) / static_cast<double>(speed);

            for (int used = 0; used <= maxSkips; ++used) {
                if (dp[used] == INF) continue;

                double arrive = dp[used] + travel;

                if (i == n - 1) {
                    ndp[used] = std::min(ndp[used], arrive);
                } else {
                    double wait = std::ceil(arrive);
                    ndp[used] = std::min(ndp[used], wait);
                    if (used < maxSkips) {
                        ndp[used + 1] = std::min(ndp[used + 1], arrive);
                    }
                }
            }
            dp.swap(ndp);
        }

        for (int used = 0; used <= maxSkips; ++used) {
            if (dp[used] <= hoursBefore + 1e-9) return true;
        }
        return false;
    };

    if (canFinish(0)) return 0;

    int lo = 1, hi = n - 1, answer = -1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        if (canFinish(mid)) {
            answer = mid;
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }
    return answer;
}

#include <bits/stdc++.h>
