#include <cstdint>
#include <climits>

long long minimumXORSum(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    int n = static_cast<int>(nums1.size());
    int fullMask = (1 << n) - 1;
    const long long INF = 1000000000000000LL;
    std::vector<long long> dp(1 << n, INF);
    dp[0] = 0;
    for (int mask = 0; mask <= fullMask; ++mask) {
        int k = __builtin_popcount(mask);
        if (k >= n) continue;
        long long cur = dp[mask];
        for (int j = 0; j < n; ++j) {
            if ((mask & (1 << j)) == 0) {
                int newMask = mask | (1 << j);
                long long cand = cur + (nums1[k] ^ nums2[j]);
                if (cand < dp[newMask]) dp[newMask] = cand;
            }
        }
    }
    return dp[fullMask];
}

