bool isWordSum(const std::string& firstWord, const std::string& secondWord, const std::string& targetWord) {
    int i = static_cast<int>(firstWord.size()) - 1;
    int j = static_cast<int>(secondWord.size()) - 1;
    int k = static_cast<int>(targetWord.size()) - 1;
    int carry = 0;
    while (i >= 0 || j >= 0 || carry) {
        int sum = carry;
        if (i >= 0) sum += firstWord[i--] - 'a';
        if (j >= 0) sum += secondWord[j--] - 'a';
        int digit = sum % 10;
        carry = sum / 10;
        if (k < 0 || digit != targetWord[k--] - 'a') return false;
    }
    while (k >= 0 && targetWord[k] == 'a') --k;
    return k == -1;
}

