int minFlips(const std::string& s) {
    size_t n = s.size();
    std::string doubled = s + s;
    int diffA = 0, diffB = 0;
    int best = INT_MAX;
    for (size_t i = 0; i < doubled.size(); ++i) {
        char ch = doubled[i];
        char expectedA = (i % 2 == 0) ? '0' : '1';
        char expectedB = (i % 2 == 0) ? '1' : '0';
        if (ch != expectedA) ++diffA;
        if (ch != expectedB) ++diffB;
        if (i >= n) {
            size_t j = i - n;
            char left = doubled[j];
            char leftExpA = (j % 2 == 0) ? '0' : '1';
            char leftExpB = (j % 2 == 0) ? '1' : '0';
            if (left != leftExpA) --diffA;
            if (left != leftExpB) --diffB;
        }
        if (i >= n - 1) {
            best = std::min(best, std::min(diffA, diffB));
        }
    }
    return best;
}

#include <bits/stdc++.h>

long long minWastedSpace(std::vector<int> packages, std::vector<std::vector<int>> boxes) {
    const long long MOD = 1000000007LL;
    std::sort(packages.begin(), packages.end());
    size_t n = packages.size();
    std::vector<long long> prefix(n + 1, 0);
    for (size_t i = 0; i < n; ++i) {
        prefix[i + 1] = prefix[i] + packages[i];
    }

    long long best = LLONG_MAX;

    for (auto& supplier : boxes) {
        std::sort(supplier.begin(), supplier.end());
        if (supplier.empty() || supplier.back() < packages.back()) continue;

        long long waste = 0;
        size_t prevIdx = 0;

        for (int size : supplier) {
            size_t idx = std::upper_bound(packages.begin(), packages.end(), size) - packages.begin();
            size_t cnt = idx - prevIdx;
            if (cnt > 0) {
                waste += static_cast<long long>(size) * static_cast<long long>(cnt) - (prefix[idx] - prefix[prevIdx]);
                if (waste >= best) break;
            }
            prevIdx = idx;
            if (prevIdx == n) break;
        }

        if (prevIdx == n && waste < best) {
            best = waste;
        }
    }

    if (best == LLONG_MAX) return -1;
    return best % MOD;
}

