bool canBeRotated(std::vector<std::vector<int>>& mat, const std::vector<std::vector<int>>& target) {
    int n = static_cast<int>(mat.size());

    auto same = [&]() -> bool {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (mat[i][j] != target[i][j]) return false;
            }
        }
        return true;
    };

    auto rotate = [&]() {
        for (int layer = 0; layer < n / 2; ++layer) {
            int first = layer;
            int last = n - 1 - layer;
            for (int i = first; i < last; ++i) {
                int offset = i - first;
                int top = mat[first][i];
                mat[first][i] = mat[last - offset][first];
                mat[last - offset][first] = mat[last][last - offset];
                mat[last][last - offset] = mat[i][last];
                mat[i][last] = top;
            }
        }
    };

    for (int k = 0; k < 4; ++k) {
        if (same()) return true;
        rotate();
    }
    return false;
}

