long long reductionOperations(std::vector<int> nums) {
    if (nums.empty()) {
        return 0;
    }
    std::sort(nums.begin(), nums.end(), std::greater<int>());
    long long ops = 0;
    long long processed = 0;
    std::size_t i = 0;
    while (i < nums.size()) {
        std::size_t j = i;
        while (j < nums.size() && nums[j] == nums[i]) {
            ++j;
        }
        if (i != 0) {
            ops += processed;
        }
        processed += static_cast<long long>(j - i);
        i = j;
    }
    return ops;
}

