bool isCovered(const std::vector<std::vector<int>>& ranges, int left, int right) {
    int maxCoord = right;
    for (size_t i = 0; i < ranges.size(); ++i) {
        if (ranges[i][1] > maxCoord) maxCoord = ranges[i][1];
    }
    std::vector<int> diff(maxCoord + 2, 0);
    for (size_t i = 0; i < ranges.size(); ++i) {
        int start = ranges[i][0];
        int end = ranges[i][1];
        diff[start] += 1;
        diff[end + 1] -= 1;
    }
    int cur = 0;
    for (int x = 0; x <= maxCoord; ++x) {
        cur += diff[x];
        if (x >= left && x <= right && cur == 0) return false;
    }
    return true;
}

