int findStudent(const std::vector<long long>& chalk, long long k) {
    long long total = 0;
    for (size_t i = 0; i < chalk.size(); ++i) total += chalk[i];
    k %= total;
    std::vector<long long> prefixSum(chalk.size());
    long long prefix = 0;
    for (size_t i = 0; i < chalk.size(); ++i) {
        prefix += chalk[i];
        prefixSum[i] = prefix;
    }
    int left = 0;
    int right = static_cast<int>(chalk.size()) - 1;
    while (left <= right) {
        int mid = (left + right) >> 1;
        if (prefixSum[mid] <= k) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return left;
}

