int largestMagicSquare(std::vector<std::vector<int>>& grid) {
    std::size_t m = grid.size();
    if (m == 0) return 0;
    std::size_t n = grid[0].size();
    std::vector<std::vector<std::int64_t>> rowPref(m, std::vector<std::int64_t>(n + 1, 0));
    std::vector<std::vector<std::int64_t>> colPref(m + 1, std::vector<std::int64_t>(n, 0));
    std::vector<std::vector<std::int64_t>> diag1(m + 1, std::vector<std::int64_t>(n + 1, 0));
    std::vector<std::vector<std::int64_t>> diag2(m + 1, std::vector<std::int64_t>(n + 1, 0));

    for (std::size_t i = 0; i < m; ++i) {
        for (std::size_t j = 0; j < n; ++j) {
            rowPref[i][j + 1] = rowPref[i][j] + grid[i][j];
            colPref[i + 1][j] = colPref[i][j] + grid[i][j];
            diag1[i + 1][j + 1] = diag1[i][j] + grid[i][j];
        }
    }
    for (std::size_t i = 0; i < m; ++i) {
        for (std::size_t j = n; j-- > 0;) {
            diag2[i + 1][j] = diag2[i][j + 1] + grid[i][j];
        }
    }

    int maxK = static_cast<int>(std::min(m, n));
    for (int k = maxK; k >= 1; --k) {
        for (std::size_t i = 0; i + k <= m; ++i) {
            for (std::size_t j = 0; j + k <= n; ++j) {
                std::int64_t target = rowPref[i][j + k] - rowPref[i][j];
                bool ok = true;
                for (std::size_t r = i; r < i + k; ++r) {
                    if (rowPref[r][j + k] - rowPref[r][j] != target) { ok = false; break; }
                }
                if (!ok) continue;
                for (std::size_t c = j; c < j + k; ++c) {
                    if (colPref[i + k][c] - colPref[i][c] != target) { ok = false; break; }
                }
                if (!ok) continue;
                if (diag1[i + k][j + k] - diag1[i][j] != target) continue;
                if (diag2[i + k][j] - diag2[i][j + k] != target) continue;
                return k;
            }
        }
    }
    return 1;
}

