    int needC = target[2];
    int curA = 0, curB = 0, curC = 0;
    for (size_t i = 0; i < triplets.size(); ++i) {
        int a = triplets[i][0];
        int b = triplets[i][1];
        int c = triplets[i][2];
        if (a <= needA && b <= needB && c <= needC) {
            if (a > curA) curA = a;
            if (b > curB) curB = b;
            if (c > curC) curC = c;
        }
    }
    return curA == needA && curB == needB && curC == needC;
}

