int maximumRemovals(const std::string& s, const std::string& p, const std::vector<int>& removable) {
    int n = static_cast<int>(s.size());
    std::vector<int> order(n, INT_MAX);
    for (int i = 0; i < static_cast<int>(removable.size()); ++i) {
        order[removable[i]] = i;
    }
    auto can = [&](int k) -> bool {
        int j = 0;
        for (int i = 0; i < n && j < static_cast<int>(p.size()); ++i) {
            if (order[i] < k) continue;
            if (s[i] == p[j]) ++j;
        }
        return j == static_cast<int>(p.size());
    };
    int lo = 0, hi = static_cast<int>(removable.size());
    while (lo < hi) {
        int mid = (lo + hi + 1) / 2;
        if (can(mid)) lo = mid;
        else hi = mid - 1;
    }
    return lo;
}

