int minCost(const std::string& expression) {
    std::vector<std::array<int, 2>> vals;
    std::vector<char> ops;
    vals.reserve(expression.size());
    ops.reserve(expression.size());
    auto applyOp = [&](char op) {
        auto right = vals.back(); vals.pop_back();
        auto left = vals.back(); vals.pop_back();
        int l0 = left[0], l1 = left[1];
        int r0 = right[0], r1 = right[1];
        int keep0, keep1, flip0, flip1;
        if (op == '&') {
            keep1 = l1 + r1;
            keep0 = std::min({l0 + r0, l0 + r1, l1 + r0});
            flip0 = l0 + r0;
            flip1 = std::min({l1 + r1, l0 + r1, l1 + r0});
        } else { // op == '|'
            keep0 = l0 + r0;
            keep1 = std::min({l1 + r1, l0 + r1, l1 + r0});
            flip1 = l1 + r1;
            flip0 = std::min({l0 + r0, l0 + r1, l1 + r0});
        }
        int res0 = std::min(keep0, flip0 + 1);
        int res1 = std::min(keep1, flip1 + 1);
        vals.push_back({res0, res1});
    };
    for (char c : expression) {
        if (c == '0' || c == '1') {
            int v = c - '0';
            vals.push_back({v == 0 ? 0 : 1, v == 1 ? 0 : 1});
            while (!ops.empty() && ops.back() != '(' && vals.size() >= 2) {
                char op = ops.back(); ops.pop_back();
                applyOp(op);
            }
        } else if (c == '(') {
            ops.push_back(c);
        } else if (c == '&' || c == '|') {
            ops.push_back(c);
        } else if (c == ')') {
            while (!ops.empty() && ops.back() != '(') {
                char op = ops.back(); ops.pop_back();
                applyOp(op);
            }
            if (!ops.empty() && ops.back() == '(') ops.pop_back();
            while (!ops.empty() && ops.back() != '(' && vals.size() >= 2) {
                char op = ops.back(); ops.pop_back();
                applyOp(op);
            }
        }
    }
    while (!ops.empty()) {
        char op = ops.back(); ops.pop_back();
        applyOp(op);
    }
    auto final = vals.back();
    return final[0] == 0 ? final[1] : final[0];
}

