int numberOfFullRounds(const std::string& loginTime, const std::string& logoutTime) {
    auto toMin = [](const std::string& t) {
        return std::stoi(t.substr(0, 2)) * 60 + std::stoi(t.substr(3, 2));
    };
    int login = toMin(loginTime);
    int logout = toMin(logoutTime);
    if (logout < login) logout += 24 * 60;
