    int lastStart = static_cast<int>(std::floor((logout - 15) / 15.0)) * 15;
    return firstStart > lastStart ? 0 : (lastStart - firstStart) / 15 + 1;
}

#include <bits/stdc++.h>

std::vector<long long> minimumAbsoluteDifferenceQueries(const std::vector<int>& nums, const std::vector<std::vector<int>>& queries) {
    struct Q { int l, r, idx; };
    int n = static_cast<int>(nums.size());
    int qn = static_cast<int>(queries.size());
    std::vector<Q> qs(qn);
    for (int i = 0; i < qn; ++i) qs[i] = {queries[i][0], queries[i][1], i};
    int block = static_cast<int>(std::sqrt(n)) + 1;
    std::sort(qs.begin(), qs.end(), [&](const Q& a, const Q& b) {
        int block_a = a.l / block;
        int block_b = b.l / block;
        if (block_a != block_b) return block_a < block_b;
        if (block_a & 1) return a.r > b.r;
        return a.r < b.r;
    });

    std::vector<long long> ans(qn);
    std::unordered_map<int, int> freq;
    std::set<int> uniq;
    std::multiset<long long> diffs;

    auto add = [&](int pos) {
        int x = nums[pos];
        int f = ++freq[x];
        if (f == 1) {
            auto it = uniq.lower_bound(x);
            int succ = (it != uniq.end()) ? *it : -1;
            int pred = (it != uniq.begin()) ? *std::prev(it) : -1;
            if (pred != -1 && succ != -1) {
                diffs.erase(diffs.find(static_cast<long long>(succ) - pred));
            }
            if (pred != -1) diffs.insert(static_cast<long long>(x) - pred);
            if (succ != -1) diffs.insert(static_cast<long long>(succ) - x);
            uniq.insert(it, x);
        }
    };

    auto remove = [&](int pos) {
        int x = nums[pos];
        int f = freq[x];
        if (f == 1) {
            auto it = uniq.find(x);
            int succ = (std::next(it) != uniq.end()) ? *std::next(it) : -1;
            int pred = (it != uniq.begin()) ? *std::prev(it) : -1;
            if (pred != -1) diffs.erase(diffs.find(static_cast<long long>(x) - pred));
            if (succ != -1) diffs.erase(diffs.find(static_cast<long long>(succ) - x));
            if (pred != -1 && succ != -1) {
                diffs.insert(static_cast<long long>(succ) - pred);
            }
            uniq.erase(it);
        }
        if (f == 1) freq.erase(x); else --freq[x];
    };

    int curL = 0, curR = -1;
    for (const auto& qq : qs) {
        while (curL > qq.l) add(--curL);
        while (curR < qq.r) add(++curR);
        while (curL < qq.l) remove(curL++);
        while (curR > qq.r) remove(curR--);
        if (uniq.size() <= 1) {
            ans[qq.idx] = -1; // -1 only when at most one DISTINCT value in range
        } else {
            ans[qq.idx] = *diffs.begin();
        }
    }
    return ans;
}

class Solution {
public:
    map<tuple<int,int,int>, pair<int,int>> memo;

    pair<int,int> dfs(int l, int r, int n) {
        if (l + r == n - 1) return {1, 1};
        auto key = make_tuple(l, r, n);
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        int mn = INT_MAX, mx = INT_MIN;
        int m = n >> 1;
        for (int i = 0; i < (1 << m); i++) {
            vector<bool> win(n, false);
            for (int j = 0; j < m; j++) {
                if ((i >> j) & 1) win[j] = true;
                else win[n-1-j] = true;
            }
            if (n & 1) win[m] = true;
            win[n-1-l] = false;
            win[n-1-r] = false;
            win[l] = true;
            win[r] = true;
            int a = 0, b = 0, c = 0;
            for (int j = 0; j < n; j++) {
                if (j == l) a = c;
                if (j == r) b = c;
                if (win[j]) c++;
            }
            auto [x, y] = dfs(a, b, c);
            mn = min(mn, x+1);
            mx = max(mx, y+1);
        }
        memo[key] = {mn, mx};
        return {mn, mx};
    }

    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memo.clear();
        auto [x, y] = dfs(firstPlayer-1, secondPlayer-1, n);
        return {x, y};
    }
};

#include <bits/stdc++.h>

std::vector<int> findPeakGrid(const std::vector<std::vector<int>>& mat) {
    int rows = static_cast<int>(mat.size());
    int cols = static_cast<int>(mat[0].size());
    int top = 0, bottom = rows - 1;
    while (top <= bottom) {
        int mid = (top + bottom) / 2;
        int maxCol = 0;
        for (int c = 1; c < cols; ++c) {
            if (mat[mid][c] > mat[mid][maxCol]) {
                maxCol = c;
            }
        }
        int upVal = (mid > 0) ? mat[mid - 1][maxCol] : INT_MIN;
        int downVal = (mid < rows - 1) ? mat[mid + 1][maxCol] : INT_MIN;
        int curVal = mat[mid][maxCol];
        if (curVal > upVal && curVal > downVal) {
            return {mid, maxCol};
        }
        if (upVal > curVal) {
            bottom = mid - 1;
        } else {
            top = mid + 1;
        }
    }
    return {};
}

