long long maxAlternatingSum(const std::vector<int>& nums) {
    long long even = 0;
    long long odd = LLONG_MIN;
    for (int x : nums) {
        long long candOdd = even + static_cast<long long>(x);
        long long newOdd = odd > candOdd ? odd : candOdd;
        long long candEven = (odd == LLONG_MIN) ? LLONG_MIN : odd - static_cast<long long>(x);
        long long newEven = even > candEven ? even : candEven;
        odd = newOdd;
        even = newEven;
    }
    return odd;
}

#include <bits/stdc++.h>
#include <vector>
#include <utility>

int countSubIslands(const std::vector<std::vector<int>>& grid1, std::vector<std::vector<int>>& grid2) {
    int rows = static_cast<int>(grid1.size());
    int cols = rows ? static_cast<int>(grid1[0].size()) : 0;
    int subIslandCount = 0;
    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};
    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            if (grid2[r][c] == 1) {
                bool isSub = true;
                std::vector<std::pair<int, int>> stack;
                stack.emplace_back(r, c);
                grid2[r][c] = 0;
                while (!stack.empty()) {
                    int cr = stack.back().first;
                    int cc = stack.back().second;
                    stack.pop_back();
                    if (grid1[cr][cc] == 0) {
                        isSub = false;
                    }
                    for (int k = 0; k < 4; ++k) {
                        int nr = cr + dr[k];
                        int nc = cc + dc[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid2[nr][nc] == 1) {
                            grid2[nr][nc] = 0;
                            stack.emplace_back(nr, nc);
                        }
                    }
                }
                if (isSub) {
                    ++subIslandCount;
                }
            }
        }
    }
    return subIslandCount;
}

#include <bits/stdc++.h>
#include <vector>
#include <limits>

int maxProductDifference(const std::vector<int>& nums) {
    int max1 = std::numeric_limits<int>::min();
    int max2 = std::numeric_limits<int>::min();
    int min1 = std::numeric_limits<int>::max();
    int min2 = std::numeric_limits<int>::max();

    for (size_t i = 0; i < nums.size(); ++i) {
        int v = nums[i];
        if (v > max1) { max2 = max1; max1 = v; }
        else if (v > max2) { max2 = v; }

        if (v < min1) { min2 = min1; min1 = v; }
        else if (v < min2) { min2 = v; }
    }

    return max1 * max2 - min1 * min2;
}

