std::string removeOccurrences(const std::string& s, const std::string& part) {
    int m = static_cast<int>(part.size());
    std::vector<int> lps(m, 0);
    for (int i = 1, len = 0; i < m; ) {
        if (part[i] == part[len]) {
            lps[i++] = ++len;
        } else if (len) {
            len = lps[len - 1];
        } else {
            lps[i++] = 0;
        }
    }

    std::vector<char> stack;
    std::vector<int> matchStack;

    for (char ch : s) {
        stack.push_back(ch);
        int k = matchStack.empty() ? 0 : matchStack.back();
        while (k > 0 && ch != part[k]) {
            k = lps[k - 1];
        }
        if (k < m && ch == part[k]) {
            ++k;
        }
        matchStack.push_back(k);
        if (k == m) {
            for (int j = 0; j < m; ++j) {
                stack.pop_back();
                matchStack.pop_back();
            }
        }
    }

    return std::string(stack.begin(), stack.end());
}

