bool canBeIncreasing(const std::vector<int>& nums) {
    int violations = 0;
    for (size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] <= nums[i - 1]) {
            ++violations;
            if (violations > 1) return false;
            if (i > 1 && nums[i] <= nums[i - 2]) {
                if (i + 1 < nums.size() && nums[i + 1] <= nums[i - 1]) {
                    return false;
                }
            }
        }
    }
    return true;
}

