std::vector<std::vector<int>> rotateGrid(std::vector<std::vector<int>>& grid, int k) {
    int rows = static_cast<int>(grid.size());
    int cols = static_cast<int>(grid[0].size());
    int layers = std::min(rows, cols) >> 1;

    for (int layer = 0; layer < layers; ++layer) {
        int top = layer, left = layer;
        int bottom = rows - 1 - layer, right = cols - 1 - layer;
        std::vector<int> vals;

        for (int c = left; c <= right; ++c) vals.push_back(grid[top][c]);
        for (int r = top + 1; r < bottom; ++r) vals.push_back(grid[r][right]);
        for (int c = right; c >= left; --c) vals.push_back(grid[bottom][c]);
        for (int r = bottom - 1; r > top; --r) vals.push_back(grid[r][left]);

        int len = static_cast<int>(vals.size());
        int shift = k % len;

        int idx = 0;
        for (int c = left; c <= right; ++c) grid[top][c] = vals[(idx + shift) % len], ++idx;
        for (int r = top + 1; r < bottom; ++r) grid[r][right] = vals[(idx + shift) % len], ++idx;
        for (int c = right; c >= left; --c) grid[bottom][c] = vals[(idx + shift) % len], ++idx;
        for (int r = bottom - 1; r > top; --r) grid[r][left] = vals[(idx + shift) % len], ++idx;
    }
    return grid;
}

