class MovieRentingSystem {
public:
    std::unordered_map<long long,int> priceMap;
    std::unordered_map<int, std::set<std::pair<int,int>>> available;
    std::set<std::tuple<int,int,int>> rentedSetOrdered;
    std::set<std::pair<int,int>> rentedPairs;
    long long key(int shop, int movie) { return (long long)shop * 1000000 + movie; }
    MovieRentingSystem(int n, std::vector<std::vector<int>>& entries) {
        for (auto& e : entries) {
            int shop = e[0], movie = e[1], price = e[2];
            priceMap[key(shop, movie)] = price;
            available[movie].insert({price, shop});
        }
    }
    std::vector<int> search(int movie) {
        std::vector<int> result;
        if (!available.count(movie)) return result;
        for (auto& [price, shop] : available[movie]) {
            if (result.size() >= 5) break;
            result.push_back(shop);
        }
        return result;
    }
    void rent(int shop, int movie) {
        int price = priceMap[key(shop, movie)];
        available[movie].erase({price, shop});
        rentedPairs.insert({shop, movie});
        rentedSetOrdered.insert({price, shop, movie});
    }
    void drop(int shop, int movie) {
        int price = priceMap[key(shop, movie)];
        rentedPairs.erase({shop, movie});
        rentedSetOrdered.erase({price, shop, movie});
        available[movie].insert({price, shop});
    }
    std::vector<std::vector<int>> report() {
        std::vector<std::vector<int>> result;
        for (auto& [price, shop, movie] : rentedSetOrdered) {
            if (result.size() >= 5) break;
            result.push_back({shop, movie});
        }
        return result;
    }
};

