int eliminateMaximum(const std::vector<int>& dist, const std::vector<int>& speed) {
    std::size_t n = dist.size();
    std::vector<int> deadline(n);
    for (std::size_t i = 0; i < n; ++i) {
        deadline[i] = (dist[i] + speed[i] - 1) / speed[i];
    }
    std::sort(deadline.begin(), deadline.end());
    int killed = 0;
    for (std::size_t i = 0; i < n; ++i) {
        if (deadline[i] <= static_cast<int>(i)) break;
        ++killed;
    }
    return killed;
}

