const long long MOD = 1000000007LL;

long long modPow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int countOrders(std::vector<int>& prevRoom) {
    int n = (int)prevRoom.size();
    std::vector<std::vector<int>> children(n);
    for (int i = 1; i < n; ++i) {
        children[prevRoom[i]].push_back(i);
    }

    std::vector<long long> fact(n + 1), invFact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i % MOD;
    invFact[n] = modPow(fact[n], MOD - 2);
    for (int i = n; i > 0; --i) invFact[i - 1] = invFact[i] * i % MOD;

    std::vector<int> order;
    order.reserve(n);
    std::stack<int> st;
    st.push(0);
    while (!st.empty()) {
        int u = st.top(); st.pop();
        order.push_back(u);
        for (int v : children[u]) st.push(v);
    }

    std::vector<int> sz(n);
    std::vector<long long> ways(n);
    for (int idx = (int)order.size() - 1; idx >= 0; --idx) {
        int u = order[idx];
        long long w = 1;
        int total = 0;
        for (int v : children[u]) {
            w = w * ways[v] % MOD;
            total += sz[v];
        }
        long long multinom = fact[total];
        for (int v : children[u]) {
            multinom = multinom * invFact[sz[v]] % MOD;
        }
        w = w * multinom % MOD;
        ways[u] = w;
        sz[u] = total + 1;
    }
    return (int)(ways[0] % MOD);
}

