#include <bits/stdc++.h>
int longestCommonSubpath(int n, std::vector<std::vector<int>>& paths) {
    const long long mod1 = 1000000007LL;
    const long long mod2 = 1000000009LL;
    const long long base = 100007LL;
    int maxLen = 0;
    for (auto& p : paths) if ((int)p.size() > maxLen) maxLen = p.size();
    std::vector<long long> pow1(maxLen + 1), pow2(maxLen + 1);
    pow1[0] = pow2[0] = 1;
    for (int i = 1; i <= maxLen; ++i) {
        pow1[i] = (pow1[i - 1] * base) % mod1;
        pow2[i] = (pow2[i - 1] * base) % mod2;
    }
    int m = paths.size();
    std::vector<std::vector<long long>> pref1(m), pref2(m);
    for (int i = 0; i < m; ++i) {
        int sz = paths[i].size();
        pref1[i].resize(sz + 1);
        pref2[i].resize(sz + 1);
        pref1[i][0] = pref2[i][0] = 0;
        for (int j = 0; j < sz; ++j) {
            pref1[i][j + 1] = (pref1[i][j] * base + paths[i][j]) % mod1;
            pref2[i][j + 1] = (pref2[i][j] * base + paths[i][j]) % mod2;
        }
    }
    auto hasCommon = [&](int L) -> bool {
        if (L == 0) return true;
        std::unordered_set<unsigned long long> common;
        bool first = true;
        for (int idx = 0; idx < m; ++idx) {
            if ((int)paths[idx].size() < L) return false;
            std::unordered_set<unsigned long long> cur;
            cur.reserve(paths[idx].size());
            for (int i = 0; i + L <= (int)paths[idx].size(); ++i) {
                long long h1 = (pref1[idx][i + L] - pref1[idx][i] * pow1[L]) % mod1;
                if (h1 < 0) h1 += mod1;
                long long h2 = (pref2[idx][i + L] - pref2[idx][i] * pow2[L]) % mod2;
                if (h2 < 0) h2 += mod2;
                unsigned long long key = (static_cast<unsigned long long>(h1) << 32) | static_cast<unsigned long long>(h2);
                cur.insert(key);
            }
            if (first) {
                common.swap(cur);
                first = false;
                if (common.empty()) return false;
            } else {
                std::unordered_set<unsigned long long> nxt;
                nxt.reserve(common.size());
                for (auto& h : cur) {
                    if (common.find(h) != common.end()) nxt.insert(h);
                }
                common.swap(nxt);
                if (common.empty()) return false;
            }
        }
        return !common.empty();
    };
    int lo = 0, hi = maxLen;
    while (lo < hi) {
        int mid = (lo + hi + 1) / 2;
        if (hasCommon(mid)) lo = mid;
        else hi = mid - 1;
    }
    return lo;
}

