static inline int gcd_int(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

long long countSquareSumTriples(int n) {
    long long count = 0;
    for (int m = 2; m * m <= n; ++m) {
        for (int n1 = 1; n1 < m; ++n1) {
            if (((m - n1) & 1) == 0) continue;
            if (gcd_int(m, n1) != 1) continue;
            long long a = 1LL * m * m - 1LL * n1 * n1;
            long long b = 2LL * m * n1;
            long long c = 1LL * m * m + 1LL * n1 * n1;
            if (c > n) break;
            if (a > b) std::swap(a, b);
            for (long long k = 1; k * c <= n; ++k) {
                count += (a == b ? 1 : 2);
            }
        }
    }
    return count;
}

