bool sumGame(const std::string& num) {
    int n = static_cast<int>(num.size());
    int half = n / 2;
    long long left_sum = 0, right_sum = 0;
    long long left_q = 0, right_q = 0;
    for (int i = 0; i < half; ++i) {
        if (num[i] == '?') ++left_q;
        else left_sum += num[i] - '0';
    }
    for (int i = half; i < n; ++i) {
        if (num[i] == '?') ++right_q;
        else right_sum += num[i] - '0';
    }
    long long total_q = left_q + right_q;
    if (total_q % 2 == 1) {
        return true;
    }
    long long diff = left_sum - right_sum;
    if (2 * diff == 9 * (right_q - left_q)) {
        return false;
    }
    return true;
}

