long long countGoodNumbers(long long n) {
    const long long MOD = 1000000007LL;
    long long evenCnt = (n + 1) / 2;
    long long oddCnt = n / 2;
    auto modPow = [&](long long base, long long exp) -> long long {
        long long result = 1LL;
        long long b = base % MOD;
        while (exp > 0) {
            if (exp & 1LL) result = (result * b) % MOD;
            b = (b * b) % MOD;
            exp >>= 1LL;
        }
        return result;
    };
    long long pow5 = modPow(5, evenCnt);
    long long pow4 = modPow(4, oddCnt);
    long long ans = (pow5 * pow4) % MOD;
    return ans;
}

