int nearestExit(std::vector<std::vector<char>>& maze, const std::vector<int>& entrance) {
    int rows = static_cast<int>(maze.size());
    int cols = static_cast<int>(maze[0].size());
    int startR = entrance[0];
    int startC = entrance[1];

    std::vector<std::array<int, 3>> queue;
    std::size_t head = 0;
    queue.push_back({startR, startC, 0});
    maze[startR][startC] = '+';

    const std::array<std::array<int, 2>, 4> dirs = {{
        {{-1, 0}},
        {{1, 0}},
        {{0, -1}},
        {{0, 1}}
    }};

    while (head < queue.size()) {
        int r = queue[head][0];
        int c = queue[head][1];
        int dist = queue[head][2];
        ++head;

        if ((r == 0 || r == rows - 1 || c == 0 || c == cols - 1) &&
            !(r == startR && c == startC)) {
            return dist;
        }

        for (const auto& dir : dirs) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && maze[nr][nc] == '.') {
                maze[nr][nc] = '+';
                queue.push_back({nr, nc, dist + 1});
            }
        }
    }
    return -1;
}

