struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

static void collectLeaves(TreeNode* node, std::unordered_set<int>& leaves) {
    if (!node) return;
    if (!node->left && !node->right) {
        leaves.insert(node->val);
    } else {
        collectLeaves(node->left, leaves);
        collectLeaves(node->right, leaves);
    }
}

static TreeNode* dfs(TreeNode* node, long long low, long long high,
                     std::unordered_map<int, TreeNode*>& mp,
                     std::unordered_set<int>& used, bool& ok) {
    if (!node) return nullptr;
    if (node->val <= low || node->val >= high) {
        ok = false;
        return nullptr;
    }
    if (!node->left && !node->right) {
        auto it = mp.find(node->val);
        if (it != mp.end()) {
            used.insert(it->first);
            TreeNode* mergeRoot = it->second;
            mp.erase(it);
            node->val = mergeRoot->val;
            node->left = mergeRoot->left;
            node->right = mergeRoot->right;
        }
    }
    node->left = dfs(node->left, low, node->val, mp, used, ok);
    node->right = dfs(node->right, node->val, high, mp, used, ok);
    return node;
}

TreeNode* canMerge(std::vector<TreeNode*>& trees) {
    std::unordered_map<int, TreeNode*> rootMap;
    for (TreeNode* t : trees) {
        rootMap[t->val] = t;
    }

    std::unordered_set<int> leafVals;
    for (TreeNode* t : trees) {
        collectLeaves(t, leafVals);
    }

    TreeNode* root = nullptr;
    for (TreeNode* t : trees) {
        if (leafVals.find(t->val) == leafVals.end()) {
            if (root) return nullptr;
            root = t;
        }
    }
    if (!root) return nullptr;

    std::unordered_set<int> used;
    used.insert(root->val);
    rootMap.erase(root->val);

    bool ok = true;
    root = dfs(root, std::numeric_limits<long long>::min(), std::numeric_limits<long long>::max(),
               rootMap, used, ok);
    if (!ok) return nullptr;
    if (used.size() != trees.size()) return nullptr;
    return root;
}

#include <bits/stdc++.h>

long long minCost(int maxTime, const std::vector<std::vector<int>>& edges, const std::vector<int>& passingFees) {
    int n = static_cast<int>(passingFees.size());
    std::vector<std::vector<std::pair<int, int>>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1], t = e[2];
        adj[u].emplace_back(v, t);
        adj[v].emplace_back(u, t);
    }
    const long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<std::vector<long long>> best(n, std::vector<long long>(maxTime + 1, INF));
    best[0][0] = passingFees[0];
    using State = std::tuple<long long, int, int>;
    std::priority_queue<State, std::vector<State>, std::greater<State>> heap;
    heap.emplace(best[0][0], 0, 0);
    while (!heap.empty()) {
        State cur = heap.top();
        heap.pop();
        long long cost = std::get<0>(cur);
        int city = std::get<1>(cur);
        int time = std::get<2>(cur);
        if (cost != best[city][time]) continue;
        if (city == n - 1) return cost;
        for (const auto& edge : adj[city]) {
            int next = edge.first;
            int roadTime = edge.second;
            int newTime = time + roadTime;
            if (newTime > maxTime) continue;
            long long newCost = cost + passingFees[next];
            if (newCost < best[next][newTime]) {
                best[next][newTime] = newCost;
                heap.emplace(newCost, next, newTime);
            }
        }
    }
    long long answer = INF;
    for (int t = 0; t <= maxTime; ++t) {
        answer = std::min(answer, best[n - 1][t]);
    }
    return answer == INF ? -1 : answer;
}

#include <bits/stdc++.h>
