int countPalindromicSubsequence(const std::string& s) {
    int n = static_cast<int>(s.size());
    std::vector<int> suffix(n);
    int mask = 0;
    for (int i = n - 1; i >= 0; --i) {
        suffix[i] = mask;
        mask |= 1 << (s[i] - 'a');
    }
    bool seen[26][26] = {};
    int prefixMask = 0;
    for (int i = 0; i < n; ++i) {
        int inter = prefixMask & suffix[i];
        int mid = s[i] - 'a';
        while (inter) {
            int lowbit = inter & -inter;
            int x = __builtin_ctz(lowbit);
            seen[x][mid] = true;
            inter ^= lowbit;
        }
        prefixMask |= 1 << mid;
    }
    int ans = 0;
    for (int x = 0; x < 26; ++x)
        for (int y = 0; y < 26; ++y)
            if (seen[x][y]) ++ans;
    return ans;
}

#include <bits/stdc++.h>
int colorTheGrid(int m, int n) {
    constexpr int MOD = 1000000007;
    int maxState = 1;
    for (int i = 0; i < m; ++i) maxState *= 3;
    std::vector<int> pow3(m);
    pow3[0] = 1;
    for (int i = 1; i < m; ++i) pow3[i] = pow3[i - 1] * 3;
    std::vector<int> valid;
    for (int s = 0; s < maxState; ++s) {
        bool ok = true;
        for (int i = 0; i < m - 1; ++i) {
            int c1 = (s / pow3[i]) % 3;
            int c2 = (s / pow3[i + 1]) % 3;
            if (c1 == c2) { ok = false; break; }
        }
        if (ok) valid.push_back(s);
    }
    int sz = static_cast<int>(valid.size());
    std::vector<std::vector<int>> compat(sz);
    for (int i = 0; i < sz; ++i) {
        for (int j = 0; j < sz; ++j) {
            bool ok = true;
            for (int row = 0; row < m; ++row) {
                int c1 = (valid[i] / pow3[row]) % 3;
                int c2 = (valid[j] / pow3[row]) % 3;
                if (c1 == c2) { ok = false; break; }
            }
            if (ok) compat[i].push_back(j);
        }
    }
    std::vector<int> dp(sz, 1), ndp(sz);
    for (int col = 1; col < n; ++col) {
        std::fill(ndp.begin(), ndp.end(), 0);
        for (int i = 0; i < sz; ++i) {
            int cur = dp[i];
            if (!cur) continue;
            for (int j : compat[i]) {
                int val = ndp[j] + cur;
                if (val >= MOD) val -= MOD;
                ndp[j] = val;
            }
        }
        dp.swap(ndp);
    }
    long long ans = 0;
    for (int v : dp) {
        ans += v;
        if (ans >= MOD) ans -= MOD;
    }
    return static_cast<int>(ans % MOD);
}

#include <bits/stdc++.h>
