int addMinimumRungs(const std::vector<int>& rungs, int dist) {
    int added = 0;
    int previousHeight = 0;
    for (size_t i = 0; i < rungs.size(); ++i) {
        int gap = rungs[i] - previousHeight;
        if (gap > dist) {
            added += ((gap + dist - 1) / dist) - 1;
        }
        previousHeight = rungs[i];
    }
    return added;
}

#include <bits/stdc++.h>

long long maxPoints(const std::vector<std::vector<int>>& points) {
    if (points.empty() || points[0].empty()) return 0;
    size_t m = points.size();
    size_t n = points[0].size();
    std::vector<long long> dp;
    dp.reserve(n);
    for (int v : points[0]) dp.push_back(v);
    for (size_t i = 1; i < m; ++i) {
        std::vector<long long> left(n);
        left[0] = dp[0];
        for (size_t j = 1; j < n; ++j) {
            left[j] = std::max(dp[j], left[j - 1] - 1);
        }
        std::vector<long long> newDp(n);
        long long right = dp[n - 1];
        newDp[n - 1] = static_cast<long long>(points[i][n - 1]) + std::max(left[n - 1], right);
        for (int j = static_cast<int>(n) - 2; j >= 0; --j) {
            right = std::max(dp[j], right - 1);
            newDp[j] = static_cast<long long>(points[i][j]) + std::max(left[j], right);
        }
        dp.swap(newDp);
    }
    return *std::max_element(dp.begin(), dp.end());
}

