#include <bits/stdc++.h>
std::vector<int> maximumGeneticDifference(std::vector<int>& parents, std::vector<std::vector<int>>& queries) {
    int n = (int)parents.size();
    std::vector<std::vector<int>> children(n);
    int root = -1;
    for (int i = 0; i < n; ++i) {
        if (parents[i] == -1) root = i;
        else children[parents[i]].push_back(i);
    }
    int qsz = (int)queries.size();
    std::vector<std::vector<std::pair<int,int>>> qAtNode(n);
    int maxVal = 0;
    for (int i = 0; i < qsz; ++i) {
        int node = queries[i][0];
        int val = queries[i][1];
        qAtNode[node].push_back({val, i});
        if (val > maxVal) maxVal = val;
    }
    if (n - 1 > maxVal) maxVal = n - 1;
    int MAXBIT = 0;
    while ((1 << (MAXBIT + 1)) <= maxVal) ++MAXBIT;
    struct TrieNode { int child[2]; int cnt; TrieNode() { child[0] = child[1] = -1; cnt = 0; } };
    std::vector<TrieNode> trie;
    trie.emplace_back();
    auto trieInsert = [&](int x, int delta) {
        int node = 0;
        trie[node].cnt += delta;
        for (int b = MAXBIT; b >= 0; --b) {
            int bit = (x >> b) & 1;
            if (trie[node].child[bit] == -1) {
                trie[node].child[bit] = (int)trie.size();
                trie.emplace_back();
            }
            node = trie[node].child[bit];
            trie[node].cnt += delta;
        }
    };
    auto trieQuery = [&](int x) {
        int node = 0;
        int res = 0;
        for (int b = MAXBIT; b >= 0; --b) {
            int bit = (x >> b) & 1;
            int want = bit ^ 1;
            int nxt = trie[node].child[want];
            if (nxt != -1 && trie[nxt].cnt > 0) {
                res |= (1 << b);
                node = nxt;
            } else {
                node = trie[node].child[bit];
            }
        }
        return res;
    };
    std::vector<int> ans(qsz);
    std::vector<std::pair<int,int>> st;
    st.reserve(n * 2);
    st.emplace_back(root, 0);
    while (!st.empty()) {
        int u = st.back().first;
        int state = st.back().second;
        st.pop_back();
        if (state == 0) {
            trieInsert(u, 1);
            for (auto &pr : qAtNode[u]) ans[pr.second] = trieQuery(pr.first);
            st.emplace_back(u, 1);
            for (int i = (int)children[u].size() - 1; i >= 0; --i) st.emplace_back(children[u][i], 0);
        } else {
            trieInsert(u, -1);
        }
    }
    return ans;
}

