int smallestChair(const std::vector<std::vector<int>>& times, int targetFriend) {
    int n = static_cast<int>(times.size());
    struct Event {
        int time;
        bool isArrival;
        int idx;
    };
    std::vector<Event> events;
    events.reserve(n * 2);
    for (int i = 0; i < n; ++i) {
        events.push_back({times[i][0], true, i});
        events.push_back({times[i][1], false, i});
    }
    std::sort(events.begin(), events.end(), [](const Event& a, const Event& b) {
        if (a.time != b.time) return a.time < b.time;
        return a.isArrival < b.isArrival;
    });
    std::priority_queue<int, std::vector<int>, std::greater<int>> freeChairs;
    std::vector<int> assigned(n, -1);
    int nextChair = 0;
    for (const auto& e : events) {
        if (e.isArrival) {
            int chair;
            if (!freeChairs.empty()) {
                chair = freeChairs.top();
                freeChairs.pop();
            } else {
                chair = nextChair++;
            }
            assigned[e.idx] = chair;
            if (e.idx == targetFriend) {
                return chair;
            }
        } else {
            freeChairs.push(assigned[e.idx]);
        }
    }
    return -1;
}

