int sumOfDigitsAfterConvert(const std::string& s, int k) {
    long long total = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        int v = static_cast<int>(s[i]) - 96;
        if (v < 10) total += v;
        else total += v / 10 + v % 10;
    }
    long long result = total;
    for (int i = 1; i < k; ++i) {
        long long sum = 0;
        while (result > 0) {
            sum += result % 10;
            result /= 10;
        }
        result = sum;
    }
    return static_cast<int>(result);
}

