int maxCompatibilitySum(const std::vector<std::vector<int>>& students, const std::vector<std::vector<int>>& mentors) {
    int m = static_cast<int>(students.size());
    int n = static_cast<int>(students[0].size());

    std::vector<std::vector<int>> score(m, std::vector<int>(m, 0));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < m; ++j) {
            int cnt = 0;
            for (int k = 0; k < n; ++k) {
                if (students[i][k] == mentors[j][k]) ++cnt;
            }
            score[i][j] = cnt;
        }
    }

    int size = 1 << m;
    std::vector<int> dp(size, -1);
    dp[0] = 0;

    for (int mask = 0; mask < size; ++mask) {
        if (dp[mask] < 0) continue;
        int student = __builtin_popcount(mask);
        for (int j = 0; j < m; ++j) {
            if ((mask & (1 << j)) == 0) {
                int newMask = mask | (1 << j);
                int val = dp[mask] + score[student][j];
                if (val > dp[newMask]) dp[newMask] = val;
            }
        }
    }
    return dp[size - 1];
}

struct TrieNode {
    map<string, TrieNode*> children;
};

class Solution {
public:
    unordered_map<TrieNode*, string> serial;
    unordered_map<string, vector<TrieNode*>> groups;
    unordered_set<TrieNode*> deleted;

    string build(TrieNode* node) {
        string s = "(";
        for (auto& [name, child] : node->children) {
            s += name + build(child);
        }
        s += ")";
        serial[node] = s;
        // only non-empty subtrees (has at least one child) can be marked as duplicates
        if (s != "()") groups[s].push_back(node);
        return s;
    }

    void dfs(TrieNode* node, vector<string>& path, vector<vector<string>>& ans) {
        if (deleted.count(node)) return;
        if (!path.empty()) ans.push_back(path);
        for (auto& [name, child] : node->children) {
            path.push_back(name);
            dfs(child, path, ans);
            path.pop_back();
        }
    }

    vector<vector<string>> deleteDuplicateFolder(vector<vector<string>>& paths) {
        TrieNode* root = new TrieNode();
        for (auto& path : paths) {
            TrieNode* node = root;
            for (auto& p : path) {
                if (!node->children.count(p)) node->children[p] = new TrieNode();
                node = node->children[p];
            }
        }
        build(root);
        for (auto& [s, nodes] : groups) {
            if (nodes.size() > 1) {
                for (auto* n : nodes) deleted.insert(n);
            }
        }
        vector<vector<string>> ans;
        vector<string> path;
        dfs(root, path, ans);
        return ans;
    }
};

