std::vector<std::vector<long long>> describePainting(const std::vector<std::vector<long long>>& segments) {
    std::vector<std::pair<long long, long long>> events;
    events.reserve(segments.size() * 2);
    for (size_t i = 0; i < segments.size(); ++i) {
        long long l = segments[i][0];
        long long r = segments[i][1];
        long long c = segments[i][2];
        events.emplace_back(l, c);
        events.emplace_back(r, -c);
    }
    if (events.empty()) {
        return {};
    }
    std::sort(events.begin(), events.end(),
              [](const std::pair<long long, long long>& a, const std::pair<long long, long long>& b) {
                  return a.first < b.first;
              });
    std::vector<std::vector<long long>> result;
    long long curSum = 0;
    long long prev = events[0].first;
    size_t i = 0;
    while (i < events.size()) {
        long long x = events[i].first;
        if (prev < x && curSum != 0) {
            result.push_back({prev, x, curSum});
        }
        while (i < events.size() && events[i].first == x) {
            curSum += events[i].second;
            ++i;
        }
        prev = x;
    }
    return result;
}

