std::vector<int> numberOfVisiblePeople(const std::vector<int>& heights) {
    int n = static_cast<int>(heights.size());
    std::vector<int> answer(n);
    std::vector<int> stack;
    stack.reserve(n);
    for (int i = n - 1; i >= 0; --i) {
        int visible = 0;
        while (!stack.empty() && heights[stack.back()] < heights[i]) {
            stack.pop_back();
            ++visible;
        }
        if (!stack.empty()) {
            ++visible;
        }
        answer[i] = visible;
        stack.push_back(i);
    }
    return answer;
}

