long long minimumPerimeter(long long neededApples) {
    auto totalApples = [](unsigned long long k) -> unsigned long long {
        return 2ULL * k * (k + 1ULL) * (2ULL * k + 1ULL);
    };

    unsigned long long target = static_cast<unsigned long long>(neededApples);
    unsigned long long low = 0, high = 1;
    while (totalApples(high) < target) {
        high <<= 1;
    }
    while (low < high) {
        unsigned long long mid = low + (high - low) / 2;
        if (totalApples(mid) >= target) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return static_cast<long long>(low * 8ULL);
}

#include <bits/stdc++.h>

int minSpaceWasted(std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    std::vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        prefix[i + 1] = prefix[i] + nums[i];
    }

    std::vector<std::vector<long long>> waste(n, std::vector<long long>(n, 0));
    for (int l = 0; l < n; ++l) {
        int curMax = 0;
        for (int r = l; r < n; ++r) {
            curMax = std::max(curMax, nums[r]);
            long long sum = prefix[r + 1] - prefix[l];
            waste[l][r] = static_cast<long long>(curMax) * (r - l + 1) - sum;
        }
    }

    int maxBlocks = std::min(k + 1, n);
    const long long INF = (1LL << 60);
    std::vector<std::vector<long long>> dp(maxBlocks + 1, std::vector<long long>(n + 1, INF));
    dp[0][0] = 0;

    for (int i = 1; i <= n; ++i) {
        dp[1][i] = waste[0][i - 1];
    }

    for (int b = 2; b <= maxBlocks; ++b) {
        for (int i = b; i <= n; ++i) {
            long long best = INF;
            for (int p = b - 1; p <= i - 1; ++p) {
                if (dp[b - 1][p] == INF) continue;
                long long cand = dp[b - 1][p] + waste[p][i - 1];
                if (cand < best) best = cand;
            }
            dp[b][i] = best;
        }
    }

    long long answer = INF;
    for (int b = 1; b <= maxBlocks; ++b) {
        answer = std::min(answer, dp[b][n]);
    }
    return static_cast<int>(answer);
}

