long long maxProduct(const std::string& s) {
    int n = static_cast<int>(s.size());
    if (n < 2) return 0;
    std::vector<int> d1(n), d2(n);
    int l = 0, r = -1;
    for (int i = 0; i < n; ++i) {
        int k = (i > r) ? 1 : std::min(d1[l + r - i], r - i + 1);
        while (i - k >= 0 && i + k < n && s[i - k] == s[i + k]) ++k;
        d1[i] = k;
        if (i + k - 1 > r) {
            l = i - k + 1;
            r = i + k - 1;
        }
    }
    l = 0; r = -1;
    for (int i = 0; i < n; ++i) {
        int k = (i > r) ? 0 : std::min(d2[l + r - i + 1], r - i + 1);
        while (i - k - 1 >= 0 && i + k < n && s[i - k - 1] == s[i + k]) ++k;
        d2[i] = k;
        if (i + k - 1 > r) {
            l = i - k;
            r = i + k - 1;
        }
    }
    std::vector<int> bestEnd(n, 0), bestStart(n, 0);
    for (int i = 0; i < n; ++i) {
        int rad = d1[i];
        int len = 2 * rad - 1;
        int left = i - rad + 1;
        int right = i + rad - 1;
        bestEnd[right] = std::max(bestEnd[right], len);
        bestStart[left] = std::max(bestStart[left], len);
        rad = d2[i];
        if (rad > 0) {
            len = 2 * rad;
            left = i - rad;
            right = i + rad - 1;
            bestEnd[right] = std::max(bestEnd[right], len);
            bestStart[left] = std::max(bestStart[left], len);
        }
    }
    std::vector<int> leftMax(n), rightMax(n);
    leftMax[0] = bestEnd[0];
    for (int i = 1; i < n; ++i) leftMax[i] = std::max(leftMax[i - 1], bestEnd[i]);
    rightMax[n - 1] = bestStart[n - 1];
    for (int i = n - 2; i >= 0; --i) rightMax[i] = std::max(rightMax[i + 1], bestStart[i]);
    long long ans = 0;
    for (int i = 0; i < n - 1; ++i) {
        long long prod = static_cast<long long>(leftMax[i]) * rightMax[i + 1];
        if (prod > ans) ans = prod;
    }
    return ans;
}

#include <bits/stdc++.h>

static long long modPow(long long base, long long exp, long long mod) {
    long long res = 1 % mod;
    base %= mod;
    while (exp > 0) {
        if (exp & 1LL) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1LL;
    }
    return res;
}

long long minNonZeroProduct(int p) {
    const long long MOD = 1000000007LL;
    const long long MODM1 = MOD - 1; // for exponent reduction
    long long pow2_mod = modPow(2LL, p, MOD);
    long long maxNumMod = (pow2_mod - 1 + MOD) % MOD;
    long long base = (pow2_mod - 2 + MOD) % MOD;
    long long exp_mod = (modPow(2LL, p - 1, MODM1) - 1 + MODM1) % MODM1;
    long long other = modPow(base, exp_mod, MOD);
    return (maxNumMod * other) % MOD;
}

