int latestDayToCross(int row, int col, const std::vector<std::vector<int>>& cells) {
    int n = row * col;
    int top = n;
    int bottom = n + 1;
    std::vector<int> parent(n + 2);
    std::vector<int> rank_(n + 2, 0);
    for (int i = 0; i < n + 2; ++i) parent[i] = i;
    auto find = [&](auto&& self, int x) -> int {
        return parent[x] == x ? x : parent[x] = self(self, parent[x]);
    };
    auto unite = [&](int a, int b) {
        int ra = find(find, a);
        int rb = find(find, b);
        if (ra == rb) return;
        if (rank_[ra] < rank_[rb]) std::swap(ra, rb);
        parent[rb] = ra;
        if (rank_[ra] == rank_[rb]) ++rank_[ra];
    };
    std::vector<char> land(n, 0);
    const int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};
    for (int i = static_cast<int>(cells.size()) - 1; i >= 0; --i) {
        int r = cells[i][0] - 1;
        int c = cells[i][1] - 1;
        int idx = r * col + c;
        land[idx] = 1;
        if (r == 0) unite(idx, top);
        if (r == row - 1) unite(idx, bottom);
        for (const auto& d : dirs) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (nr >= 0 && nr < row && nc >= 0 && nc < col) {
                int nidx = nr * col + nc;
                if (land[nidx]) unite(idx, nidx);
            }
        }
        if (find(find, top) == find(find, bottom)) {
            return i;
        }
    }
    return 0;
}

