std::vector<int> rearrange(std::vector<int> nums) {
    std::sort(nums.begin(), nums.end());
    int n = static_cast<int>(nums.size());
    std::vector<int> res(n);
    int left = 0, right = n - 1, idx = 0;
    while (left <= right) {
        res[idx++] = nums[left++];
        if (left <= right) {
            res[idx++] = nums[right--];
        }
    }
    return res;
}

