#include <queue>

int numberOfPatterns(const std::vector<std::string>& patterns, const std::string& word) {
    struct Node {
        std::unordered_map<char, int> children;
        int fail = 0;
        std::vector<int> out;
    };
    std::vector<Node> nodes;
    nodes.push_back(Node()); // root = 0

    // build trie
    for (size_t i = 0; i < patterns.size(); ++i) {
        int cur = 0;
        for (char ch : patterns[i]) {
            auto it = nodes[cur].children.find(ch);
            if (it == nodes[cur].children.end()) {
                nodes[cur].children[ch] = static_cast<int>(nodes.size());
                nodes.push_back(Node());
            }
            cur = nodes[cur].children[ch];
        }
        nodes[cur].out.push_back(static_cast<int>(i));
    }

    // build failure links
    std::queue<int> q;
    for (const auto& kv : nodes[0].children) {
        int child = kv.second;
        nodes[child].fail = 0;
        q.push(child);
    }
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        for (const auto& kv : nodes[v].children) {
            char ch = kv.first;
            int u = kv.second;
            int f = nodes[v].fail;
            while (f && nodes[f].children.find(ch) == nodes[f].children.end()) {
                f = nodes[f].fail;
            }
            if (nodes[f].children.find(ch) != nodes[f].children.end()) {
                nodes[u].fail = nodes[f].children[ch];
            } else {
                nodes[u].fail = 0;
            }
            nodes[u].out.insert(nodes[u].out.end(),
                                nodes[nodes[u].fail].out.begin(),
                                nodes[nodes[u].fail].out.end());
            q.push(u);
        }
    }

    // search word
    std::vector<bool> found(patterns.size(), false);
    int state = 0;
    for (char ch : word) {
        while (state && nodes[state].children.find(ch) == nodes[state].children.end()) {
            state = nodes[state].fail;
        }
        auto it = nodes[state].children.find(ch);
        if (it != nodes[state].children.end()) {
            state = it->second;
        } else {
            state = 0;
        }
        for (int idx : nodes[state].out) {
            found[idx] = true;
        }
    }

    // count results
    int cnt = 0;
    for (bool f : found) {
        if (f) ++cnt;
    }
    return cnt;
}

