long long maxMatrixSum(const std::vector<std::vector<long long>>& matrix) {
    long long sumAbs = 0;
    int negCount = 0;
    long long minAbs = LLONG_MAX;
    bool hasZero = false;

    for (size_t i = 0; i < matrix.size(); ++i) {
        const std::vector<long long>& row = matrix[i];
        for (size_t j = 0; j < row.size(); ++j) {
            long long v = row[j];
            long long a = std::llabs(v);
            sumAbs += a;
            if (v < 0) ++negCount;
            if (a < minAbs) minAbs = a;
            if (v == 0) hasZero = true;
        }
    }

    if (negCount % 2 == 1 && !hasZero) {
        sumAbs -= 2 * minAbs;
    }
    return sumAbs;
}

