bool validPath(int n, const std::vector<std::vector<int>>& edges, int source, int destination) {
    std::vector<std::vector<int>> graph(n);
    for (const auto& edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph[u].push_back(v);
        graph[v].push_back(u);
    }

    std::vector<bool> visited(n, false);
    std::queue<int> q;
    q.push(source);
    visited[source] = true;

    while (!q.empty()) {
        int node = q.front();
        q.pop();
        if (node == destination) return true;
        const auto& neighbors = graph[node];
        for (int nxt : neighbors) {
            if (!visited[nxt]) {
                visited[nxt] = true;
                q.push(nxt);
            }
        }
    }
    return false;
}

