int numberOfWays(int n, const std::vector<std::vector<int>>& roads) {
    const int MOD = 1000000007;
    std::vector<std::vector<std::pair<int, int>>> adj(n);
    for (const auto& r : roads) {
        int u = r[0], v = r[1], w = r[2];
        adj[u].emplace_back(v, w);
        adj[v].emplace_back(u, w);
    }

    std::vector<long long> dist(n, std::numeric_limits<long long>::max());
    std::vector<int> ways(n, 0);
    dist[0] = 0;
    ways[0] = 1;

    using Node = std::pair<long long, int>;
    std::priority_queue<Node, std::vector<Node>, std::greater<Node>> heap;
    heap.emplace(0LL, 0);

    while (!heap.empty()) {
        Node top = heap.top();
        heap.pop();
        long long d = top.first;
        int u = top.second;
        if (d != dist[u]) continue;
        for (const auto& edge : adj[u]) {
            int v = edge.first;
            int w = edge.second;
            long long nd = d + w;
            if (nd < dist[v]) {
                dist[v] = nd;
                ways[v] = ways[u];
                heap.emplace(nd, v);
            } else if (nd == dist[v]) {
                ways[v] += ways[u];
                if (ways[v] >= MOD) ways[v] -= MOD;
            }
        }
    }

    return ways[n - 1];
}

