int findGCDofArray(const std::vector<int>& nums) {
    int min = nums[0];
    int max = nums[0];
    for (size_t i = 1; i < nums.size(); ++i) {
        int v = nums[i];
        if (v < min) min = v;
        else if (v > max) max = v;
    }
    auto gcd = [](int a, int b) {
        while (b != 0) {
            int r = a % b;
            a = b;
            b = r;
        }
        return a;
    };
    return gcd(min, max);
}

