int minAbsDifference(const std::vector<std::vector<int>>& mat, int target) {
    int maxSum = 0;
    for (const auto& row : mat) {
        if (!row.empty()) {
            int rowMax = *std::max_element(row.begin(), row.end());
            maxSum += rowMax;
        }
    }
    std::vector<unsigned char> dp(maxSum + 1, 0);
    dp[0] = 1;
    for (const auto& row : mat) {
        std::vector<unsigned char> next(maxSum + 1, 0);
        for (int val : row) {
            for (int s = 0; s + val <= maxSum; ++s) {
                if (dp[s]) next[s + val] = 1;
            }
        }
        dp.swap(next);
    }
    int best = INT_MAX;
    for (int s = 0; s <= maxSum; ++s) {
        if (dp[s]) {
            int diff = std::abs(target - s);
            if (diff < best) best = diff;
            if (best == 0) break;
        }
    }
    return best;
}

#include <bits/stdc++.h>

std::vector<int> recoverArray(int n, std::vector<int> sums) {
    std::sort(sums.begin(), sums.end());
    std::vector<int> result;
    std::function<bool(const std::vector<int>&, int)> dfs = [&](const std::vector<int>& cur, int k) -> bool {
        if (k == 0) return true;
        int diff = cur[1] - cur[0];
        for (int sign = 1; sign >= -1; sign -= 2) {
            int x = diff * sign;
            std::unordered_map<int, int> freq;
            freq.reserve(cur.size() * 2);
            for (int v : cur) ++freq[v];
            std::vector<int> without;
            std::vector<int> with;
            without.reserve(cur.size() / 2);
            with.reserve(cur.size() / 2);
            bool ok = true;
            for (int v : cur) {
                if (freq[v] == 0) continue;
                --freq[v];
                int w = v + x;
                if (freq[w] == 0) { ok = false; break; }
                --freq[w];
                without.push_back(v);
                with.push_back(w);
            }
            if (!ok) continue;
            if (std::find(without.begin(), without.end(), 0) != without.end()) {
                if (dfs(without, k - 1)) {
                    result.push_back(x);
                    return true;
                }
            } else {
                if (dfs(with, k - 1)) {
                    result.push_back(-x);
                    return true;
                }
            }
        }
        return false;
    };
    dfs(sums, n);
    std::reverse(result.begin(), result.end());
    return result;
}

#include <bits/stdc++.h>
#include <cstdint>
#include <string>
#include <vector>

int numberOfWaysSeparateNumbers(const std::string& num) {
    const uint32_t MOD = 1000000007U;
    int n = static_cast<int>(num.size());

    // Rolling hash preparation
    const uint64_t BASE = 1315423911ULL;
    std::vector<uint64_t> powBase(n + 1);
    std::vector<uint64_t> prefHash(n + 1);
    powBase[0] = 1;
    for (int i = 0; i < n; ++i) {
        powBase[i + 1] = powBase[i] * BASE;
        prefHash[i + 1] = prefHash[i] * BASE + static_cast<uint64_t>(num[i] - '0' + 1);
    }
    auto getHash = [&](int l, int r) -> uint64_t { // [l, r)
        return prefHash[r] - prefHash[l] * powBase[r - l];
    };
    auto lcp = [&](int a, int b) -> int {
        int maxLen = std::min(n - a, n - b);
        int lo = 0, hi = maxLen;
        while (lo < hi) {
            int mid = (lo + hi + 1) >> 1;
            if (getHash(a, a + mid) == getHash(b, b + mid))
                lo = mid;
            else
                hi = mid - 1;
        }
        return lo;
    };

    // Triangular storage for prefix sums
    size_t totalSize = static_cast<size_t>(n + 1) * (n + 2) / 2;
    std::vector<uint32_t> pref(totalSize, 0);
    auto idx = [&](int i, int len) -> size_t {
        return static_cast<size_t>(i) * (i + 1) / 2 + len;
    };
    auto getPref = [&](int i, int len) -> uint32_t {
        if (len < 0) return 0;
        return pref[idx(i, len)];
    };
    auto setPref = [&](int i, int len, uint32_t value) {
        pref[idx(i, len)] = value;
    };

    for (int i = 1; i <= n; ++i) {
        for (int len = 1; len <= i; ++len) {
            int start = i - len;
            if (num[start] == '0') {
                setPref(i, len, getPref(i, len - 1));
                continue;
            }
            uint32_t total = 0;
            if (start == 0) {
                total = 1;
            } else {
                if (len > 1) total = getPref(start, len - 1);
                if (len <= start) {
                    int a = start - len;
                    int b = start;
                    int common = lcp(a, b);
                    if (common < len && num[a + common] < num[b + common]) {
                        uint32_t dpVal = (getPref(start, len) + MOD - getPref(start, len - 1)) % MOD;
                        total += dpVal;
                        if (total >= MOD) total -= MOD;
                    }
                }
            }
            uint32_t curPref = (getPref(i, len - 1) + total) % MOD;
            setPref(i, len, curPref);
        }
    }
    return static_cast<int>(getPref(n, n));
}

