#include <bits/stdc++.h>
#include <vector>
#include <utility>
#include <climits>

int minimumSessions(const std::vector<int>& tasks, int sessionTime) {
    int n = static_cast<int>(tasks.size());
    int totalMask = 1 << n;
    std::vector<std::pair<int, int>> dp(totalMask, {INT_MAX, INT_MAX});
    dp[0] = {1, 0};
    for (int mask = 0; mask < totalMask; ++mask) {
        if (dp[mask].first == INT_MAX) continue;
        int sess = dp[mask].first;
        int used = dp[mask].second;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) continue;
            int newMask = mask | (1 << i);
            int newSess = sess;
            int newUsed = used + tasks[i];
            if (newUsed > sessionTime) {
                newSess = sess + 1;
                newUsed = tasks[i];
            }
            if (dp[newMask].first == INT_MAX ||
                newSess < dp[newMask].first ||
                (newSess == dp[newMask].first && newUsed < dp[newMask].second)) {
                dp[newMask] = {newSess, newUsed};
            }
        }
    }
    return dp[totalMask - 1].first;
}

