int numberOfUniqueGoodSubsequences(const std::string& binary) {
    const long long MOD = 1000000007LL;
    long long dp = 0;
    long long last[2] = {0, 0};
    bool hasZero = false;
    for (char ch : binary) {
        int x = ch - '0';
        if (x == 0) hasZero = true;
        long long add = (dp + (x == 1 ? 1 : 0)) % MOD;
        long long cur = (add - last[x] + MOD) % MOD;
        last[x] = add;
        dp = (dp + cur) % MOD;
    }
    long long ans = dp;
    if (hasZero) ans = (ans + 1) % MOD;
    return static_cast<int>(ans);
}

