int partition(std::vector<std::string>& arr, int lo, int hi) {
    const std::string& pivot = arr[hi];
    int i = lo;
    for (int j = lo; j < hi; ++j) {
        if (compare(arr[j], pivot) <= 0) {
            std::swap(arr[i], arr[j]);
            ++i;
        }
    }
    std::swap(arr[i], arr[hi]);
    return i;
}

std::string findKthLargest(std::vector<std::string> nums, int k) {
    int target = static_cast<int>(nums.size()) - k;
    int left = 0;
    int right = static_cast<int>(nums.size()) - 1;
    while (true) {
        int pivotIdx = partition(nums, left, right);
        if (pivotIdx == target) return nums[pivotIdx];
        if (pivotIdx < target) left = pivotIdx + 1;
        else right = pivotIdx - 1;
    }
}

