std::vector<std::vector<int>> findFarmland(std::vector<std::vector<int>>& land) {
    int m = static_cast<int>(land.size());
    if (m == 0) return {};
    int n = static_cast<int>(land[0].size());
    std::vector<std::vector<int>> ans;

    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (land[i][j] == 1) {
                if ((i == 0 || land[i - 1][j] == 0) && (j == 0 || land[i][j - 1] == 0)) {
                    int r = i;
                    while (r + 1 < m && land[r + 1][j] == 1) ++r;

                    int c = j;
                    while (c + 1 < n && land[i][c + 1] == 1) ++c;

                    for (int x = i; x <= r; ++x) {
                        for (int y = j; y <= c; ++y) {
                            land[x][y] = 0;
                        }
                    }

                    ans.push_back({i, j, r, c});
                }
            }
        }
    }
    return ans;
}

