bool canSortByGCD(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n <= 1) return true;

    std::vector<int> parent(n);
    std::vector<int> rank(n, 0);
    for (int i = 0; i < n; ++i) parent[i] = i;

    auto find = [&](int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    auto unite = [&](int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return;
        if (rank[ra] < rank[rb]) parent[ra] = rb;
        else if (rank[ra] > rank[rb]) parent[rb] = ra;
        else { parent[rb] = ra; ++rank[ra]; }
    };

    int maxVal = 0;
    for (int v : nums) if (v > maxVal) maxVal = v;

    std::vector<int> spf(maxVal + 1);
    for (int i = 2; i <= maxVal; ++i) {
        if (spf[i] == 0) {
            for (int j = i; j <= maxVal; j += i) {
                if (spf[j] == 0) spf[j] = i;
            }
        }
    }

    std::unordered_map<int, int> primeOwner;
    for (int i = 0; i < n; ++i) {
        int x = nums[i];
        std::unordered_set<int> seen;
        while (x > 1) {
            int p = spf[x];
            if (seen.find(p) == seen.end()) {
                seen.insert(p);
                auto it = primeOwner.find(p);
                if (it != primeOwner.end()) unite(i, it->second);
                else primeOwner[p] = i;
            }
            while (x % p == 0) x /= p;
        }
    }

    std::unordered_map<int, std::vector<int>> groups;
    for (int i = 0; i < n; ++i) {
        int r = find(i);
        groups[r].push_back(nums[i]);
    }

    for (auto& kv : groups) {
        std::sort(kv.second.begin(), kv.second.end(), std::greater<int>());
    }

    std::vector<int> target(nums);
    std::sort(target.begin(), target.end());

    for (int i = 0; i < n; ++i) {
        int r = find(i);
        auto& arr = groups[r];
        int smallest = arr.back();
        arr.pop_back();
        if (smallest != target[i]) return false;
    }
    return true;
}

