std::vector<int> smallestMissingValueSubtree(const std::vector<int>& parents, const std::vector<int>& nums) {
    int n = static_cast<int>(parents.size());
    std::vector<std::vector<int>> children(n);
    for (int i = 1; i < n; ++i) {
        children[parents[i]].push_back(i);
    }

    int nodeWithOne = -1;
    for (int i = 0; i < n; ++i) {
        if (nums[i] == 1) {
            nodeWithOne = i;
            break;
        }
    }

    std::vector<int> ans(n, 1);
    if (nodeWithOne == -1) {
        return ans;
    }

    int limit = n + 2;
    std::vector<char> seen(limit, 0);
    std::vector<char> visitedNode(n, 0);
    int mex = 1;
    int cur = nodeWithOne;

    while (cur != -1) {
        std::stack<int> st;
        st.push(cur);
        while (!st.empty()) {
            int u = st.top();
            st.pop();
            if (visitedNode[u]) continue;
            visitedNode[u] = 1;
            if (nums[u] < limit) seen[nums[u]] = 1;
            for (int v : children[u]) {
                if (!visitedNode[v]) st.push(v);
            }
        }
        while (mex < limit && seen[mex]) ++mex;
        ans[cur] = mex;
        cur = parents[cur];
    }

    return ans;
}

