struct PairHash {
    std::size_t operator()(const std::pair<int, int>& p) const noexcept {
        return (static_cast<std::size_t>(static_cast<std::uint64_t>(p.first) << 32) ^
                static_cast<std::size_t>(static_cast<std::uint64_t>(p.second)));
    }
};

static int compute_gcd(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

long long interchangeableRectangles(const std::vector<std::vector<int>>& rectangles) {
    std::unordered_map<std::pair<int, int>, long long, PairHash> freq;
    freq.reserve(rectangles.size() * 2);
    long long result = 0;
    for (const auto& rect : rectangles) {
        int w = rect[0];
        int h = rect[1];
        int g = compute_gcd(w, h);
        w /= g;
        h /= g;
        std::pair<int, int> key = {w, h};
        auto it = freq.find(key);
        if (it != freq.end()) {
            result += it->second;
            ++it->second;
        } else {
            freq.emplace(key, 1);
        }
    }
    return result;
}

#include <bits/stdc++.h>

int maxProduct(const std::string& s) {
    int n = static_cast<int>(s.size());
    int total = 1 << n;
    std::vector<int> popcnt(total);
    for (int mask = 0; mask < total; ++mask) {
        popcnt[mask] = __builtin_popcount(mask);
    }
    std::vector<int> palLen(total, 0);
    for (int mask = 1; mask < total; ++mask) {
        if (popcnt[mask] <= 1) {
            palLen[mask] = popcnt[mask];
        } else {
            int first = __builtin_ctz(mask);
            int last = 31 - __builtin_clz(mask);
            if (s[first] == s[last]) {
                int inner = mask ^ (1 << first) ^ (1 << last);
                if (palLen[inner] == popcnt[inner]) {
                    palLen[mask] = popcnt[mask];
                }
            }
        }
    }
    int best = 0;
    for (int mask = 1; mask < total; ++mask) {
        if (palLen[mask] == 0) continue;
        int complement = (total - 1) ^ mask;
        for (int sub = complement; sub; sub = (sub - 1) & complement) {
            if (palLen[sub] == 0) continue;
            int prod = palLen[mask] * palLen[sub];
            if (prod > best) best = prod;
        }
    }
    return best;
}

