std::vector<int> findOriginalArray(const std::vector<int>& changed) {
    if (changed.size() % 2 != 0) {
        return {};
    }

    std::unordered_map<long long, int> freq;
    for (int v : changed) {
        ++freq[v];
    }

    std::vector<long long> sorted;
    sorted.reserve(changed.size());
    for (int v : changed) {
        sorted.push_back(v);
    }
    std::sort(sorted.begin(), sorted.end(),
              [](long long a, long long b) { return std::llabs(a) < std::llabs(b); });

    std::vector<int> original;
    original.reserve(changed.size() / 2);

    for (long long val : sorted) {
        int cnt = freq[val];
        if (cnt == 0) continue;

        if (val == 0) {
            if (cnt % 2 != 0) return {};
            for (int i = 0; i < cnt / 2; ++i) original.push_back(0);
            freq[0] = 0;
            continue;
        }

        long long doubleVal = val * 2;
        int doubleCnt = freq[doubleVal];
        if (doubleCnt < cnt) return {};

        for (int i = 0; i < cnt; ++i) original.push_back(static_cast<int>(val));
        freq[val] = 0;
        freq[doubleVal] = doubleCnt - cnt;
    }

    return original;
}

