long long maxTaxiEarnings(int n, std::vector<std::vector<int>> rides) {
    if (rides.empty()) return 0;
    std::sort(rides.begin(), rides.end(),
        [](const std::vector<int>& a, const std::vector<int>& b) {
            return a[0] < b[0] || (a[0] == b[0] && a[1] < b[1]);
        });
    int m = static_cast<int>(rides.size());
    std::vector<int> starts(m);
    for (int i = 0; i < m; ++i) starts[i] = rides[i][0];
    std::vector<long long> dp(m + 1, 0);
    for (int i = m - 1; i >= 0; --i) {
        long long profit = static_cast<long long>(rides[i][1] - rides[i][0]) + rides[i][2];
        int nextIdx = std::lower_bound(starts.begin() + i + 1, starts.end(), rides[i][1]) - starts.begin();
        dp[i] = std::max(dp[i + 1], profit + dp[nextIdx]);
    }
    return dp[0];
}

