std::string longestSubsequenceRepeatedKTimes(const std::string& s, int k) {
    std::vector<int> freq(26, 0);
    for (char ch : s) ++freq[ch - 'a'];
    auto canForm = [&](const std::string& t) -> bool {
        if (t.empty()) return true;
        int need = static_cast<int>(t.size());
        int idx = 0, cnt = 0;
        for (char ch : s) {
            if (ch == t[idx]) {
                ++idx;
                if (idx == need) {
                    ++cnt;
                    if (cnt >= k) return true;
                    idx = 0;
                }
            }
        }
        return cnt >= k;
    };
    std::string best;
    std::function<void(const std::string&)> dfs = [&](const std::string& cur) {
        if (cur.size() > best.size() || (cur.size() == best.size() && cur > best))
            best = cur;
        for (int ci = 25; ci >= 0; --ci) {
            if (freq[ci] < k) continue;
            char c = static_cast<char>('a' + ci);
            std::string nxt = cur;
            nxt.push_back(c);
            if (canForm(nxt))
                dfs(nxt);
        }
    };
    dfs("");
    return best;
}

