class DetectSquares {
public:
    std::unordered_map<int, std::unordered_map<int,int>> pointsMap;
    void add(std::vector<int> point) {
        pointsMap[point[0]][point[1]]++;
    }
    int count(std::vector<int> point) {
        int x = point[0], y = point[1];
        int total = 0;
        auto itX = pointsMap.find(x);
        if (itX == pointsMap.end()) return 0;
        for (auto& [y2, cnt] : itX->second) {
            if (y2 == y) continue;
            int d = std::abs(y2 - y);
            for (int xOther : {x+d, x-d}) {
                auto it = pointsMap.find(xOther);
                if (it != pointsMap.end()) {
                    int cnt1 = it->second.count(y) ? it->second[y] : 0;
                    int cnt2 = it->second.count(y2) ? it->second[y2] : 0;
                    total += cnt * cnt1 * cnt2;
                }
            }
        }
        return total;
    }
};

