bool placeWordInCrossword(const std::vector<std::string>& board, const std::string& word) {
    int rows = static_cast<int>(board.size());
    int cols = static_cast<int>(board[0].size());
    std::string rev(word.rbegin(), word.rend());

    auto matches = [&](const std::string& seg, const std::string& w) -> bool {
        for (size_t i = 0; i < seg.size(); ++i) {
            if (seg[i] != ' ' && seg[i] != w[i]) return false;
        }
        return true;
    };

    for (int r = 0; r < rows; ++r) {
        int c = 0;
        while (c < cols) {
            while (c < cols && board[r][c] == '#') ++c;
            if (c >= cols) break;
            int start = c;
            while (c < cols && board[r][c] != '#') ++c;
            std::string segment = board[r].substr(start, c - start);
            if (segment.size() == word.size()) {
                if (matches(segment, word) || matches(segment, rev)) return true;
            }
        }
    }

    for (int c = 0; c < cols; ++c) {
        int r = 0;
        while (r < rows) {
            while (r < rows && board[r][c] == '#') ++r;
            if (r >= rows) break;
            int start = r;
            while (r < rows && board[r][c] != '#') ++r;
            std::string segment;
            segment.reserve(r - start);
            for (int k = start; k < r; ++k) segment.push_back(board[k][c]);
            if (segment.size() == word.size()) {
                if (matches(segment, word) || matches(segment, rev)) return true;
            }
        }
    }

    return false;
}

