int gradeStudents(const std::string& s, const std::vector<int>& answers) {
    long long correct = 0, product = 1;
    for (char c : s) {
        if (c >= '0' && c <= '9') {
            product *= (c - '0');
        } else if (c == '+') {
            correct += product;
            product = 1;
        }
    }
    correct += product;
    long long leftToRight = s[0] - '0';
    for (size_t i = 1; i + 1 < s.size(); i += 2) {
        char op = s[i];
        int val = s[i + 1] - '0';
        if (op == '+')
            leftToRight += val;
        else
            leftToRight *= val;
    }
    int totalPoints = 0;
    for (int ans : answers) {
        if (ans == correct)
            totalPoints += 5;
        else if (ans == leftToRight)
            totalPoints += 2;
    }
    return totalPoints;
}

