#include <bits/stdc++.h>

int maxWays(std::vector<int> nums, int k) {
    int n = static_cast<int>(nums.size());
    if (n <= 1) return 0;
    std::vector<long long> prefix(n);
    long long sum = 0;
    for (int i = 0; i < n; ++i) {
        sum += nums[i];
        prefix[i] = sum;
    }
    std::vector<long long> diff;
    diff.reserve(n - 1);
    for (int i = 0; i < n - 1; ++i) {
        diff.push_back(2LL * prefix[i] - sum);
    }
    std::unordered_map<long long, int> leftMap, rightMap;
    leftMap.reserve(diff.size());
    rightMap.reserve(diff.size() * 2);
    for (long long d : diff) ++rightMap[d];
    int baseCount = 0;
    auto it0 = rightMap.find(0);
    if (it0 != rightMap.end()) baseCount = it0->second;
    int answer = baseCount;
    for (int j = 0; j < n; ++j) {
        if (j > 0) {
            long long d = diff[j - 1];
            auto it = rightMap.find(d);
            if (it != rightMap.end()) {
                if (--it->second == 0) rightMap.erase(it);
            }
            ++leftMap[d];
        }
        long long needLeft = static_cast<long long>(k) - nums[j];
        long long needRight = static_cast<long long>(nums[j]) - k;
        int leftCount = 0, rightCount = 0;
        auto itL = leftMap.find(needLeft);
        if (itL != leftMap.end()) leftCount = itL->second;
        auto itR = rightMap.find(needRight);
        if (itR != rightMap.end()) rightCount = itR->second;
        answer = std::max(answer, leftCount + rightCount);
    }
    return answer;
}

