    if (k >= n) return n;
    int best = 0;
    for (char target : {'T', 'F'}) {
        int left = 0, flips = 0;
        for (int right = 0; right < n; ++right) {
            if (answerKey[right] != target) ++flips;
            while (flips > k) {
