vector<int> findMissingObservations(vector<int>& rolls, int mean, int n) {
    int m = rolls.size();
    long long totalNeeded = (long long)mean * (n + m);
    long long knownSum = 0;
    for (int v : rolls) knownSum += v;
    long long missingSum = totalNeeded - knownSum;
    if (missingSum < n || missingSum > 6LL*n) return {};
    vector<int> result(n, 1);
    long long remaining = missingSum - n;
    for (int i = 0; i < n && remaining > 0; i++) {
        long long add = min(5LL, remaining);
        result[i] += add;
        remaining -= add;
    }
    return result;
}
