        timePrice[timestamp] = price;
        maxHeap.push({price, timestamp});
        minHeap.push({price, timestamp});
        if (timestamp >= latestTimestamp) latestTimestamp = timestamp;
    }
    int current() { return timePrice[latestTimestamp]; }
    int maximum() {
        while (true) {
            auto [price, ts] = maxHeap.top();
            if (timePrice[ts] == price) return price;
            maxHeap.pop();
        }
    }
    int minimum() {
        while (true) {
            auto [price, ts] = minHeap.top();
            if (timePrice[ts] == price) return price;
            minHeap.pop();
        }
    }
};

