std::string smallestSubsequence(const std::string& s, int k, char letter, int repetition) {
    int n = static_cast<int>(s.size());
    std::vector<int> suffix(n + 1, 0);
    for (int i = n - 1; i >= 0; --i) {
        suffix[i] = suffix[i + 1] + (s[i] == letter);
    }
    std::string st;
    st.reserve(k);
    int cntLetter = 0;
    for (int i = 0; i < n; ++i) {
        char c = s[i];
        while (!st.empty() && c < st.back() && static_cast<int>(st.size()) - 1 + (n - i) >= k) {
            if (st.back() == letter) {
                if (cntLetter - 1 + suffix[i] < repetition) break;
            } else {
                if (cntLetter + suffix[i] < repetition) break;
            }
            if (st.back() == letter) --cntLetter;
            st.pop_back();
        }
        int remaining = k - static_cast<int>(st.size());
        if (remaining > 0) {
            int possible = cntLetter + (c == letter) + suffix[i];
            if (possible >= repetition) {
                st.push_back(c);
                if (c == letter) ++cntLetter;
            }
        }
    }
    if (static_cast<int>(st.size()) > k) st.resize(k);
    return st;
}

