long long minDifference(const std::vector<int>& nums) {
    long long total = std::accumulate(nums.begin(), nums.end(), 0LL);
    double half = total / 2.0;
    size_t n = nums.size() >> 1;
    std::vector<int> left(nums.begin(), nums.begin() + n);
    std::vector<int> right(nums.begin() + n, nums.end());

    auto allSums = [&](const std::vector<int>& arr) {
        size_t m = arr.size();
        std::vector<std::vector<long long>> sumsByCnt(m + 1);
        int limit = 1 << m;
        for (int mask = 0; mask < limit; ++mask) {
            int cnt = 0;
            long long sum = 0;
            for (size_t i = 0; i < m; ++i) {
                if (mask & (1 << i)) {
                    ++cnt;
                    sum += arr[i];
                }
            }
            sumsByCnt[cnt].push_back(sum);
        }
        return sumsByCnt;
    };

    std::vector<std::vector<long long>> leftSums = allSums(left);
    std::vector<std::vector<long long>> rightSums = allSums(right);

    for (size_t i = 0; i <= n; ++i) {
        std::sort(rightSums[i].begin(), rightSums[i].end());
    }

    long long best = LLONG_MAX;

    for (size_t i = 0; i <= n; ++i) {
        const std::vector<long long>& L = leftSums[i];
        const std::vector<long long>& R = rightSums[n - i];
        if (L.empty() || R.empty()) continue;
        for (long long sL : L) {
            double target = half - static_cast<double>(sL);
            auto it = std::lower_bound(R.begin(), R.end(), target);
            size_t loIdx = it - R.begin();
            for (long long idx : {static_cast<long long>(loIdx), static_cast<long long>(loIdx) - 1}) {
                if (idx < 0 || static_cast<size_t>(idx) >= R.size()) continue;
                long long s = sL + R[static_cast<size_t>(idx)];
                long long diff = std::llabs(total - 2 * s);
                if (diff < best) best = diff;
                if (best == 0) return 0;
            }
        }
    }
    return best;
}

