long long kthSmallestProduct(const std::vector<int>& nums1, const std::vector<int>& nums2, long long k) {
    const std::vector<int>& A = nums1;
    const std::vector<int>& B = nums2;
    int n = static_cast<int>(A.size());
    int m = static_cast<int>(B.size());

    auto countLE = [&](long long x) -> long long {
        long long cnt = 0;
        for (int i = 0; i < n; ++i) {
            long long a = A[i];
            if (a > 0) {
                long long limit = x / a;
                if (x < 0 && x % a != 0) --limit;
                cnt += std::upper_bound(B.begin(), B.end(), limit) - B.begin();
            } else if (a < 0) {
                long long limit = x / a;
                if (x < 0 && a < 0 && x % a != 0) ++limit;
                cnt += B.end() - std::lower_bound(B.begin(), B.end(), limit);
            } else { // a == 0
                if (x >= 0) cnt += m;
            }
        }
        return cnt;
    };

    long long candidates[4] = {
        static_cast<long long>(A.front()) * B.front(),
        static_cast<long long>(A.front()) * B.back(),
        static_cast<long long>(A.back()) * B.front(),
        static_cast<long long>(A.back()) * B.back()
    };
    long long low = *std::min_element(candidates, candidates + 4);
    long long high = *std::max_element(candidates, candidates + 4);

    while (low < high) {
        long long mid = low + (high - low) / 2;
        if (countLE(mid) >= k) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

