int secondMinimum(int n, std::vector<std::vector<int>>& edges, int time, int change) {
    std::vector<std::vector<int>> adj(n + 1);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    const long long INF = (1LL << 60);
    std::vector<long long> first(n + 1, INF), second(n + 1, INF);
    using State = std::pair<long long, int>;
    std::priority_queue<State, std::vector<State>, std::greater<State>> pq;
    first[1] = 0;
    pq.emplace(0, 1);
    long long cycle = 2LL * change;
    while (!pq.empty()) {
        State top = pq.top();
        pq.pop();
        long long curTime = top.first;
        int u = top.second;
        if (curTime > second[u]) continue;
        for (int v : adj[u]) {
            long long depart = curTime;
            long long mod = depart % cycle;
            if (mod >= change) depart += cycle - mod;
            long long nxt = depart + time;
            if (nxt < first[v]) {
                second[v] = first[v];
                first[v] = nxt;
                pq.emplace(nxt, v);
            } else if (nxt > first[v] && nxt < second[v]) {
                second[v] = nxt;
                pq.emplace(nxt, v);
            }
        }
    }
    return static_cast<int>(second[n]);
}

