long long networkBecomesIdle(const std::vector<std::vector<int>>& edges, const std::vector<int>& patience) {
    int n = static_cast<int>(patience.size());
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    std::vector<int> dist(n, -1);
    std::vector<int> q;
    q.reserve(n);
    q.push_back(0);
    dist[0] = 0;
    size_t qIdx = 0;
    while (qIdx < q.size()) {
        int cur = q[qIdx++];
        for (int nb : adj[cur]) {
            if (dist[nb] == -1) {
                dist[nb] = dist[cur] + 1;
                q.push_back(nb);
            }
        }
    }
    long long answer = 0;
    for (int i = 1; i < n; ++i) {
        long long roundTrip = static_cast<long long>(dist[i]) * 2;
        long long lastSend = ((roundTrip - 1) / patience[i]) * patience[i];
        long long arrival = lastSend + roundTrip;
        if (arrival > answer) answer = arrival;
    }
    return answer + 1;
}

