long long countMaxOrSubsets(const std::vector<int>& nums) {
    int maxOr = 0;
    for (int v : nums) {
        maxOr |= v;
    }
    std::unordered_map<int, long long> cnt;
    cnt.reserve(1024);
    for (int x : nums) {
        std::unordered_map<int, long long> newCnt = cnt;
        newCnt.reserve(cnt.size() * 2 + 1);
        for (const auto& kv : cnt) {
            int newOr = kv.first | x;
            newCnt[newOr] += kv.second;
        }
        newCnt[x] += 1;
        cnt.swap(newCnt);
    }
    auto it = cnt.find(maxOr);
    return it != cnt.end() ? it->second : 0LL;
}

