int countHighestScoreNodes(const std::vector<int>& parents) {
    int n = static_cast<int>(parents.size());
    std::vector<std::vector<int>> children(n);
    for (int i = 1; i < n; ++i) {
        children[parents[i]].push_back(i);
    }
    std::vector<int> order;
    order.reserve(n);
    std::stack<int> st;
    st.push(0);
    while (!st.empty()) {
        int v = st.top();
        st.pop();
        order.push_back(v);
        for (int c : children[v]) {
            st.push(c);
        }
    }
    std::vector<long long> subSize(n, 1);
    for (int i = n - 1; i >= 0; --i) {
        int v = order[i];
        for (int c : children[v]) {
            subSize[v] += subSize[c];
        }
    }
    long long maxScore = 0;
    int count = 0;
    for (int v = 0; v < n; ++v) {
        long long score = 1;
        for (int c : children[v]) {
            score *= subSize[c];
        }
        long long rest = n - subSize[v];
        if (rest > 0) score *= rest;
        if (score > maxScore) {
            maxScore = score;
            count = 1;
        } else if (score == maxScore) {
            ++count;
        }
    }
    return count;
}

