long long minimumTime(int n, std::vector<std::vector<int>>& relations, std::vector<int>& time) {
    std::vector<std::vector<int>> adj(n);
    std::vector<int> indeg(n, 0);
    for (const auto& rel : relations) {
        int u = rel[0] - 1;
        int v = rel[1] - 1;
        adj[u].push_back(v);
        ++indeg[v];
    }
    std::vector<long long> start(n, 0), finish(n, 0);
    std::queue<int> q;
    for (int i = 0; i < n; ++i) {
        if (indeg[i] == 0) {
            finish[i] = time[i];
            q.push(i);
        }
    }
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            if (start[v] < finish[u]) start[v] = finish[u];
            if (--indeg[v] == 0) {
                finish[v] = start[v] + time[v];
                q.push(v);
            }
        }
    }
    long long ans = 0;
    for (long long f : finish) if (f > ans) ans = f;
    return ans;
}

