int countValidWords(const std::string& sentence) {
    std::vector<std::string> tokens;
    size_t start = 0;
    while (true) {
        size_t pos = sentence.find(' ', start);
        if (pos == std::string::npos) {
            tokens.push_back(sentence.substr(start));
            break;
        } else {
            tokens.push_back(sentence.substr(start, pos - start));
            start = pos + 1;
        }
    }

    int validCount = 0;
    for (size_t i = 0; i < tokens.size(); ++i) {
        const std::string& token = tokens[i];
        if (token.empty()) continue;

        bool hyphenSeen = false, punctSeen = false;
        bool ok = true;

        for (size_t j = 0; j < token.size(); ++j) {
            unsigned char c = token[j];

            if (c >= '0' && c <= '9') { ok = false; break; }

            if (c == '-') {
                if (hyphenSeen) { ok = false; break; }
                if (j == 0 || j == token.size() - 1) { ok = false; break; }
                unsigned char prev = token[j - 1];
                unsigned char next = token[j + 1];
                if (!(prev >= 'a' && prev <= 'z' && next >= 'a' && next <= 'z')) {
                    ok = false; break;
                }
                hyphenSeen = true;
                continue;
            }

            if (c == '!' || c == '.' || c == ',') {
                if (punctSeen) { ok = false; break; }
                if (j != token.size() - 1) { ok = false; break; }
                punctSeen = true;
                continue;
            }

            if (c >= 'a' && c <= 'z') continue;

            ok = false; break;
        }

        if (ok) ++validCount;
    }

    return validCount;
}

