long long maxTwoEvents(const std::vector<std::vector<long long>>& events) {
    std::vector<std::vector<long long>> ev = events;
    std::sort(ev.begin(), ev.end(), [](const std::vector<long long>& a, const std::vector<long long>& b) {
        return a[1] < b[1];
    });

    std::size_t n = ev.size();
    std::vector<long long> ends(n);
    std::vector<long long> prefMax(n);
    long long bestSingle = 0, bestTwo = 0;

    for (std::size_t i = 0; i < n; ++i) {
        ends[i] = ev[i][1];
        long long val = ev[i][2];
        prefMax[i] = (i == 0) ? val : std::max(prefMax[i - 1], val);
        bestSingle = std::max(bestSingle, val);
    }

    for (std::size_t i = 0; i < n; ++i) {
        long long start = ev[i][0];
        long long val = ev[i][2];

        long long lo = 0, hi = static_cast<long long>(i) - 1, j = -1;
        while (lo <= hi) {
            long long mid = (lo + hi) >> 1;
            if (ends[mid] < start) {
                j = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }

        if (j != -1) {
            bestTwo = std::max(bestTwo, val + prefMax[j]);
        }
    }

    return std::max(bestSingle, bestTwo);
}

#include <bits/stdc++.h>

int countValidMoveCombinations(const std::vector<std::string>& pieces, const std::vector<std::vector<int>>& positions) {
    int n = static_cast<int>(pieces.size());
    std::vector<std::vector<std::vector<int>>> piecePaths(n);
    for (int i = 0; i < n; ++i) {
        const std::string& type = pieces[i];
        int r0 = positions[i][0];
        int c0 = positions[i][1];
        for (int r = 1; r <= 8; ++r) {
            for (int c = 1; c <= 8; ++c) {
                int dr = r - r0;
                int dc = c - c0;
                int absDr = std::abs(dr);
                int absDc = std::abs(dc);
                bool ok = false;
                if (type == "rook") {
                    ok = (r == r0 || c == c0);
                } else if (type == "bishop") {
                    ok = (absDr == absDc);
                } else { // queen
                    ok = (r == r0 || c == c0 || absDr == absDc);
                }
                if (!ok) continue;
                int stepR = (dr > 0) - (dr < 0);
                int stepC = (dc > 0) - (dc < 0);
                std::vector<int> path;
                int curR = r0, curC = c0;
                path.push_back((curR - 1) * 8 + (curC - 1));
                while (curR != r || curC != c) {
                    curR += stepR;
                    curC += stepC;
                    path.push_back((curR - 1) * 8 + (curC - 1));
                }
                piecePaths[i].push_back(std::move(path));
            }
        }
    }

    long long total = 0;
    std::vector<std::vector<int>> selected;
    selected.reserve(n);

    std::function<void(int)> dfs = [&](int idx) {
        if (idx == n) {
            ++total;
            return;
        }
        for (const auto& path : piecePaths[idx]) {
            bool conflict = false;
            for (const auto& prevPath : selected) {
                size_t maxLen = std::max(prevPath.size(), path.size());
                int finalPrev = prevPath.back();
                int finalCurr = path.back();
                for (size_t t = 0; t < maxLen; ++t) {
                    int posPrev = (t < prevPath.size()) ? prevPath[t] : finalPrev;
                    int posCurr = (t < path.size()) ? path[t] : finalCurr;
                    if (posPrev == posCurr) {
                        conflict = true;
                        break;
                    }
                }
                if (conflict) break;
            }
            if (conflict) continue;
            selected.push_back(path);
            dfs(idx + 1);
            selected.pop_back();
        }
    };

    dfs(0);
    return static_cast<int>(total);
}

#include <bits/stdc++.h>

bool possiblyEquals(const std::string& s1, const std::string& s2) {
    const int OFFSET = 2000;
    std::unordered_set<std::string> visited;

    std::function<bool(int,int,int)> dfs = [&](int i, int j, int diff) -> bool {
        std::string key = std::to_string(i) + "#" + std::to_string(j) + "#" + std::to_string(diff + OFFSET);
        if (visited.count(key)) return false;

        if (i == (int)s1.size() && j == (int)s2.size()) return diff == 0;

        if (diff > 0) { // need to consume from s2
            if (j < (int)s2.size()) {
                if (std::isalpha(s2[j])) {
                    if (dfs(i, j + 1, diff - 1)) return true;
                } else {
                    int val = 0;
                    for (int len = 1; j + len <= (int)s2.size() && len <= 3 && std::isdigit(s2[j + len - 1]); ++len) {
                        val = val * 10 + (s2[j + len - 1] - '0');
                        if (dfs(i, j + len, diff - val)) return true;
                    }
                }
            }
        } else if (diff < 0) { // need to consume from s1
            if (i < (int)s1.size()) {
                if (std::isalpha(s1[i])) {
                    if (dfs(i + 1, j, diff + 1)) return true;
                } else {
                    int val = 0;
                    for (int len = 1; i + len <= (int)s1.size() && len <= 3 && std::isdigit(s1[i + len - 1]); ++len) {
                        val = val * 10 + (s1[i + len - 1] - '0');
                        if (dfs(i + len, j, diff + val)) return true;
                    }
                }
            }
        } else { // diff == 0
            if (i < (int)s1.size() && j < (int)s2.size()) {
                bool aLetter = std::isalpha(s1[i]);
                bool bLetter = std::isalpha(s2[j]);
                if (aLetter && bLetter) {
                    if (s1[i] == s2[j]) {
                        if (dfs(i + 1, j + 1, 0)) return true;
                    }
                } else if (!aLetter && !bLetter) { // both numbers
                    int val1 = 0;
                    for (int len1 = 1; i + len1 <= (int)s1.size() && len1 <= 3 && std::isdigit(s1[i + len1 - 1]); ++len1) {
                        val1 = val1 * 10 + (s1[i + len1 - 1] - '0');
                        if (dfs(i + len1, j, val1)) return true;
                    }
                    int val2 = 0;
                    for (int len2 = 1; j + len2 <= (int)s2.size() && len2 <= 3 && std::isdigit(s2[j + len2 - 1]); ++len2) {
                        val2 = val2 * 10 + (s2[j + len2 - 1] - '0');
                        if (dfs(i, j + len2, -val2)) return true;
                    }
                } else if (!aLetter) { // s1 number
                    int val = 0;
                    for (int len = 1; i + len <= (int)s1.size() && len <= 3 && std::isdigit(s1[i + len - 1]); ++len) {
                        val = val * 10 + (s1[i + len - 1] - '0');
                        if (dfs(i + len, j, val)) return true;
                    }
                } else { // s2 number
                    int val = 0;
                    for (int len = 1; j + len <= (int)s2.size() && len <= 3 && std::isdigit(s2[j + len - 1]); ++len) {
                        val = val * 10 + (s2[j + len - 1] - '0');
                        if (dfs(i, j + len, -val)) return true;
                    }
                }
            }
        }

        visited.insert(key);
        return false;
    };

    return dfs(0, 0, 0);
}

