int minimumOperations(const std::vector<int>& nums, int start, int goal) {
    if (start == goal) return 0;

    const int MAX = 1000;
    std::vector<bool> visited(MAX + 1, false);
    std::vector<std::pair<int, int>> queue;
    std::size_t head = 0;

    if (0 <= start && start <= MAX) {
        visited[start] = true;
        queue.emplace_back(start, 0);
    }

    while (head < queue.size()) {
        int x = queue[head].first;
        int steps = queue[head].second;
        ++head;

        for (std::size_t i = 0; i < nums.size(); ++i) {
            int add = x + nums[i];
            int sub = x - nums[i];

            if (add == goal || sub == goal) return steps + 1;

            if (0 <= add && add <= MAX && !visited[add]) {
                visited[add] = true;
                queue.emplace_back(add, steps + 1);
            }
            if (0 <= sub && sub <= MAX && !visited[sub]) {
                visited[sub] = true;
                queue.emplace_back(sub, steps + 1);
            }
        }
    }
    return -1;
}

