static inline bool isVowelChar(char c) {
    return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
}

long long countVowelSubstrings(const std::string& word) {
    int n = static_cast<int>(word.size());
    long long total = 0;
    int i = 0;
    while (i < n) {
        if (!isVowelChar(word[i])) {
            ++i;
            continue;
        }
        int blockStart = i;
        while (i < n && isVowelChar(word[i])) ++i;
        int blockEnd = i;
        std::array<int, 5> cnt = {0, 0, 0, 0, 0};
        int left = blockStart;
        for (int right = blockStart; right < blockEnd; ++right) {
            switch (word[right]) {
                case 'a': ++cnt[0]; break;
                case 'e': ++cnt[1]; break;
                case 'i': ++cnt[2]; break;
                case 'o': ++cnt[3]; break;
                case 'u': ++cnt[4]; break;
            }
            while (cnt[0] && cnt[1] && cnt[2] && cnt[3] && cnt[4]) {
                total += (blockEnd - right);
                switch (word[left]) {
                    case 'a': --cnt[0]; break;
                    case 'e': --cnt[1]; break;
                    case 'i': --cnt[2]; break;
                    case 'o': --cnt[3]; break;
                    case 'u': --cnt[4]; break;
                }
                ++left;
            }
        }
    }
    return total;
}

