int maxTaskAssign(const std::vector<int>& tasks, const std::vector<int>& workers, int pills, int strength) {
    std::vector<int> t = tasks;
    std::vector<int> w = workers;
    std::sort(t.begin(), t.end());
    std::sort(w.begin(), w.end());

    int n = static_cast<int>(t.size());
    int m = static_cast<int>(w.size());

    int low = 0, high = std::min(n, m);
    auto canAssign = [&](int k) -> bool {
        std::multiset<int> ms(w.begin(), w.end());
        int remaining = pills;
        for (int i = k - 1; i >= 0; --i) {
            int task = t[i];
            auto it = ms.lower_bound(task);
            if (it != ms.end()) {
                ms.erase(it);
            } else {
                if (remaining == 0) return false;
                int need = task - strength;
                it = ms.lower_bound(need);
                if (it == ms.end()) return false;
                ms.erase(it);
                --remaining;
            }
        }
        return true;
    };
    while (low < high) {
        int mid = (low + high + 1) / 2;
        if (canAssign(mid)) low = mid;
        else high = mid - 1;
    }
    return low;
}

