std::vector<int> mostBeautifulItem(const std::vector<std::vector<int>>& items, const std::vector<int>& queries) {
    std::vector<std::vector<int>> sorted = items;
    std::sort(sorted.begin(), sorted.end(), [](const std::vector<int>& a, const std::vector<int>& b) {
        return a[0] < b[0];
    });

    std::vector<int> priceList;
    std::vector<int> bestList;
    int curMax = 0;

    for (const auto& pair : sorted) {
        int price = pair[0];
        int beauty = pair[1];
        curMax = std::max(curMax, beauty);
        priceList.push_back(price);
        bestList.push_back(curMax);
    }

    std::vector<int> answers(queries.size());

    for (size_t i = 0; i < queries.size(); ++i) {
        int q = queries[i];
        int lo = 0;
        int hi = static_cast<int>(priceList.size()) - 1;
        int idx = -1;
        while (lo <= hi) {
            int mid = (lo + hi) >> 1;
            if (priceList[mid] <= q) {
                idx = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        answers[i] = (idx == -1) ? 0 : bestList[idx];
    }

    return answers;
}

