int minimizedMaximum(int n, const std::vector<int>& quantities) {
    int low = 1;
    int high = *std::max_element(quantities.begin(), quantities.end());
    while (low < high) {
        int mid = low + (high - low) / 2;
        long long needed = 0;
        for (size_t i = 0; i < quantities.size(); ++i) {
            needed += (quantities[i] + mid - 1) / mid;
            if (needed > n) break;
        }
        if (needed <= n) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

