    ListNode* next;
    ListNode() : val(0), next(nullptr) {}
    ListNode(int x) : val(x), next(nullptr) {}
    ListNode(int x, ListNode* next) : val(x), next(next) {}
};

ListNode* reverseEvenLengthGroups(ListNode* head) {
    ListNode dummy(0);
    dummy.next = head;
    ListNode* prevGroupTail = &dummy;
    ListNode* current = head;
    int groupSize = 1;

    while (current != nullptr) {
        ListNode* groupHead = current;
        int count = 0;
        ListNode* prev = nullptr;
        while (count < groupSize && current != nullptr) {
            prev = current;
            current = current->next;
            ++count;
        }
        ListNode* groupTail = prev;
        ListNode* nextGroupHead = current;

        if (count % 2 == 0) {
            ListNode* prevNode = nullptr;
            ListNode* node = groupHead;
            while (node != nextGroupHead) {
                ListNode* nxt = node->next;
                node->next = prevNode;
                prevNode = node;
                node = nxt;
            }
            prevGroupTail->next = groupTail;
            groupHead->next = nextGroupHead;
            prevGroupTail = groupHead;
        } else {
            prevGroupTail = groupTail;
        }

        ++groupSize;
    }

    return dummy.next;
}

