std::string decodeCiphertext(const std::string& encodedText, int rows) {
    if (encodedText.empty() || rows == 0) return "";
    int n = static_cast<int>(encodedText.size());
    int cols = n / rows;
    std::vector<std::string> mat(rows, std::string(cols, ' '));
    int pos = 0;
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            mat[i][j] = encodedText[pos++];
        }
    }
    std::string result;
    for (int col = 0; col < cols; ++col) {
        int r = 0, c = col;
        while (r < rows && c < cols) {
            result.push_back(mat[r][c]);
            ++r;
            ++c;
        }
    }
    for (int row = 1; row < rows; ++row) {
        int r = row, c = 0;
        while (r < rows && c < cols) {
            result.push_back(mat[r][c]);
            ++r;
            ++c;
        }
    }
    while (!result.empty() && result.back() == ' ') {
        result.pop_back();
    }
    return result;
}

