    int water = capacity;
    for (size_t i = 0; i < plants.size(); ++i) {
        if (water < plants[i]) {
            steps += position + 1;
            position = -1;
            water = capacity;
        }
        steps += static_cast<long long>(i) - position;
        position = static_cast<long long>(i);
        water -= plants[i];
    }
    return steps;
}

