std::vector<bool> processRestrictedFriendRequests(int n, const std::vector<std::vector<int>>& restrictions, const std::vector<std::vector<int>>& requests) {
    std::vector<int> parent(n);
    std::vector<int> rank(n, 0);
    for (int i = 0; i < n; ++i) parent[i] = i;

    auto find = [&](int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    auto unite = [&](int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (rank[ra] < rank[rb]) parent[ra] = rb;
        else if (rank[ra] > rank[rb]) parent[rb] = ra;
        else { parent[rb] = ra; rank[ra]++; }
    };

    std::vector<bool> answer;
    answer.reserve(requests.size());

    for (const auto& req : requests) {
        int u = req[0];
        int v = req[1];
        int ru = find(u);
        int rv = find(v);
        if (ru == rv) {
            answer.push_back(true);
            continue;
        }

        bool conflict = false;
        for (const auto& res : restrictions) {
            int x = res[0];
            int y = res[1];
            int rx = find(x);
            int ry = find(y);
            if ((rx == ru && ry == rv) || (rx == rv && ry == ru)) {
                conflict = true;
                break;
            }
        }

        if (conflict) answer.push_back(false);
        else {
            answer.push_back(true);
            unite(ru, rv);
        }
    }

    return answer;
}

#include <bits/stdc++.h>

long long sumOfKMirrorNumbers(int k, int n) {
    auto isBaseKPalindrome = [&](long long x) -> bool {
        long long rev = 0, tmp = x;
        while (tmp > 0) {
            rev = rev * k + (tmp % k);
            tmp /= k;
        }
        return rev == x;
    };
    auto makePalindrome = [&](long long half, bool odd) -> long long {
        long long pal = half;
        long long x = odd ? half / 10 : half;
        while (x > 0) {
            pal = pal * 10 + (x % 10);
            x /= 10;
        }
        return pal;
    };
    long long sum = 0;
    int count = 0;
    for (int len = 1; ; ++len) {
        int halfLen = (len + 1) / 2;
        long long start = 1;
        for (int i = 1; i < halfLen; ++i) start *= 10;
        long long end = start * 10 - 1;
        for (long long half = start; half <= end; ++half) {
            long long pal = makePalindrome(half, len % 2 == 1);
            if (isBaseKPalindrome(pal)) {
                sum += pal;
                ++count;
                if (count == n) return sum;
            }
        }
    }
    return sum;
}

