class RangeFreqQuery {
public:
    std::unordered_map<int, std::vector<int>> posMap;
    RangeFreqQuery(std::vector<int>& arr) {
        for (int i = 0; i < (int)arr.size(); i++) posMap[arr[i]].push_back(i);
    }
    static int lowerBound(const std::vector<int>& a, int t) {
        int lo=0,hi=(int)a.size();
        while(lo<hi){int m=(lo+hi)>>1; if(a[m]<t)lo=m+1; else hi=m;}
        return lo;
    }
    static int upperBound(const std::vector<int>& a, int t) {
        int lo=0,hi=(int)a.size();
        while(lo<hi){int m=(lo+hi)>>1; if(a[m]<=t)lo=m+1; else hi=m;}
        return lo;
    }
    int query(int left, int right, int value) {
        auto it = posMap.find(value);
        if (it == posMap.end()) return 0;
        return upperBound(it->second, right) - lowerBound(it->second, left);
    }
};

