int minimumBuckets(const std::string& hamsters) {
    int n = static_cast<int>(hamsters.size());
    std::vector<char> bucket(n, 0);
    int answer = 0;
    for (int i = 0; i < n; ++i) {
        if (hamsters[i] != 'H') continue;
        if (i > 0 && bucket[i - 1]) continue;
        if (i + 1 < n && hamsters[i + 1] == '.' && !bucket[i + 1]) {
            bucket[i + 1] = 1;
            ++answer;
        } else if (i > 0 && hamsters[i - 1] == '.' && !bucket[i - 1]) {
            bucket[i - 1] = 1;
            ++answer;
        } else {
            return -1;
        }
    }
    return answer;
}

