int countPyramids(std::vector<std::vector<int>>& grid) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    long long ans = 0;

    std::vector<int> next(n, 0), cur(n, 0);
    for (int i = m - 1; i >= 0; --i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 1) {
                if (i == m - 1 || j == 0 || j == n - 1) {
                    cur[j] = 1;
                } else {
                    int mn = std::min({next[j - 1], next[j], next[j + 1]});
                    cur[j] = 1 + mn;
                }
                ans += cur[j] - 1;
            } else {
                cur[j] = 0;
            }
        }
        next.swap(cur);
    }

    std::vector<int> prev(n, 0);
    cur.assign(n, 0);
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 1) {
                if (i == 0 || j == 0 || j == n - 1) {
                    cur[j] = 1;
                } else {
                    int mn = std::min({prev[j - 1], prev[j], prev[j + 1]});
                    cur[j] = 1 + mn;
                }
                ans += cur[j] - 1;
            } else {
                cur[j] = 0;
            }
        }
        prev.swap(cur);
    }

    return static_cast<int>(ans);
}

