std::vector<int> findEvenNumbers(const std::vector<int>& digits) {
    std::array<int, 10> freq{};
    for (int d : digits) {
        freq[d]++;
    }

    std::unordered_set<int> resultSet;

    for (int a = 1; a <= 9; ++a) {
        if (freq[a] == 0) continue;
        for (int b = 0; b <= 9; ++b) {
            if (freq[b] == 0) continue;
            for (int c = 0; c <= 9; c += 2) {
                if (freq[c] == 0) continue;

                std::array<int, 10> need{};
                need[a]++; need[b]++; need[c]++;

                bool ok = true;
                for (int d = 0; d <= 9; ++d) {
                    if (need[d] > freq[d]) { ok = false; break; }
                }
                if (!ok) continue;

                int number = 100 * a + 10 * b + c;
                resultSet.insert(number);
            }
        }
    }

    std::vector<int> result(resultSet.begin(), resultSet.end());
    std::sort(result.begin(), result.end());
    return result;
}

