};

ListNode* deleteMiddle(ListNode* head) {
    if (!head || !head->next) return nullptr;

    ListNode* slow = head;
    ListNode* fast = head;
    ListNode* prev = nullptr;

    while (fast && fast->next) {
        fast = fast->next;
        if (fast) fast = fast->next;
        prev = slow;
        slow = slow->next;
    }

    prev->next = slow->next;
    return head;
}

