int minDeletion(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    int minIdx = 0, maxIdx = 0;
    for (int i = 1; i < n; ++i) {
        if (nums[i] < nums[minIdx]) minIdx = i;
        if (nums[i] > nums[maxIdx]) maxIdx = i;
    }
    int frontBoth = std::max(minIdx, maxIdx) + 1;
    int backBoth = n - std::min(minIdx, maxIdx);
    int frontMinBackMax = minIdx + 1 + (n - maxIdx);
    int frontMaxBackMin = maxIdx + 1 + (n - minIdx);
    int ans = std::min({frontBoth, backBoth, frontMinBackMax, frontMaxBackMin});
    return ans;
}

