std::vector<int> findAllPeople(int n, std::vector<std::vector<int>>& meetings, int firstPerson) {
    std::sort(meetings.begin(), meetings.end(),
              [](const std::vector<int>& a, const std::vector<int>& b) {
                  return a[2] < b[2];
              });

    std::vector<bool> knows(n, false);
    knows[0] = true;
    knows[firstPerson] = true;

    size_t i = 0;
    while (i < meetings.size()) {
        int curTime = meetings[i][2];
        std::vector<std::pair<int, int>> group;
        std::unordered_set<int> nodesSet;

        while (i < meetings.size() && meetings[i][2] == curTime) {
            int x = meetings[i][0];
            int y = meetings[i][1];
            group.emplace_back(x, y);
            nodesSet.insert(x);
            nodesSet.insert(y);
            ++i;
        }

        std::unordered_map<int, int> parent;
        std::function<int(int)> find = [&](int v) -> int {
            if (parent[v] != v) parent[v] = find(parent[v]);
            return parent[v];
        };
        auto unionSet = [&](int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra != rb) parent[rb] = ra;
        };

        for (int v : nodesSet) parent[v] = v;

        for (const auto& p : group) unionSet(p.first, p.second);

        std::unordered_map<int, bool> compHasSecret;
        for (int v : nodesSet) {
            int root = find(v);
            if (knows[v]) compHasSecret[root] = true;
        }

        for (int v : nodesSet) {
            int root = find(v);
            if (compHasSecret[root]) knows[v] = true;
        }
    }

    std::vector<int> result;
    for (int p = 0; p < n; ++p) {
        if (knows[p]) result.push_back(p);
    }
    return result;
}

