std::vector<int> maxSubsequence(std::vector<int> nums, int k) {
    std::vector<int> sorted = nums;
    std::sort(sorted.begin(), sorted.end(), std::greater<int>());
    std::unordered_map<int, int> need;
    for (int i = 0; i < k; ++i) {
        ++need[sorted[i]];
    }
    std::vector<int> result;
    result.reserve(k);
    for (int x : nums) {
        auto it = need.find(x);
        if (it != need.end() && it->second > 0) {
            result.push_back(x);
            --(it->second);
            if (result.size() == static_cast<size_t>(k)) break;
        }
    }
    return result;
}

