std::vector<int> findGoodDays(const std::vector<int>& security, int time) {
    int n = static_cast<int>(security.size());
    std::vector<int> left(n, 0);
    std::vector<int> right(n, 0);
    for (int i = 1; i < n; ++i) {
        if (security[i - 1] >= security[i]) {
            left[i] = left[i - 1] + 1;
        }
    }
    for (int i = n - 2; i >= 0; --i) {
        if (security[i] <= security[i + 1]) {
            right[i] = right[i + 1] + 1;
        }
    }
    std::vector<int> goodDays;
    for (int i = 0; i < n; ++i) {
        if (left[i] >= time && right[i] >= time) {
            goodDays.push_back(i);
        }
    }
    return goodDays;
}

