bool dfsFind(TreeNode* node, int target, const std::string& cur, std::string& out) {
    if (!node) return false;
    if (node->val == target) {
        out = cur;
        return true;
    }
    if (dfsFind(node->left, target, cur + 'L', out)) return true;
    if (dfsFind(node->right, target, cur + 'R', out)) return true;
    return false;
}

std::string getDirections(TreeNode* root, int startValue, int destValue) {
    std::string pathStart, pathDest;
    dfsFind(root, startValue, "", pathStart);
    dfsFind(root, destValue, "", pathDest);
    size_t i = 0;
    while (i < pathStart.size() && i < pathDest.size() && pathStart[i] == pathDest[i]) ++i;
    return std::string(pathStart.size() - i, 'U') + pathDest.substr(i);
}

