std::vector<std::vector<int>> validArrangement(std::vector<std::vector<int>>& pairs) {
    using int64 = long long;
    int n = pairs.size();
    std::vector<std::pair<int64, int64>> edges;
    edges.reserve(n);
    std::unordered_map<int64, std::vector<int>> adj;
    adj.reserve(n * 2);
    std::unordered_map<int64, int> indeg, outdeg;
    indeg.reserve(n * 2);
    outdeg.reserve(n * 2);
    for (int i = 0; i < n; ++i) {
        int64 u = pairs[i][0];
        int64 v = pairs[i][1];
        edges.emplace_back(u, v);
        adj[u].push_back(i);
        ++outdeg[u];
        ++indeg[v];
    }
    int64 startNode = edges[0].first;
    for (const auto& kv : outdeg) {
        int64 node = kv.first;
        int diff = outdeg[node] - indeg[node];
        if (diff == 1) {
            startNode = node;
            break;
        }
    }
    std::vector<int> circuit;
    circuit.reserve(n);
    std::vector<int64> nodeStack;
    nodeStack.push_back(startNode);
    std::vector<int> edgeStack;
    while (!nodeStack.empty()) {
        int64 v = nodeStack.back();
        auto& vec = adj[v];
        if (!vec.empty()) {
            int e = vec.back();
            vec.pop_back();
            nodeStack.push_back(edges[e].second);
            edgeStack.push_back(e);
        } else {
            nodeStack.pop_back();
            if (!edgeStack.empty()) {
                circuit.push_back(edgeStack.back());
                edgeStack.pop_back();
            }
        }
    }
    std::reverse(circuit.begin(), circuit.end());
    std::vector<std::vector<int>> result;
    result.reserve(n);
    for (int idx : circuit) {
        result.push_back({static_cast<int>(edges[idx].first), static_cast<int>(edges[idx].second)});
    }
    return result;
}

