long long subArrayRanges(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;
    std::vector<long long> left(n), right(n);
    std::stack<int> st;

    // contributions as maximum
    while (!st.empty()) st.pop();
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && nums[st.top()] <= nums[i]) st.pop();
        left[i] = i - (st.empty() ? -1 : st.top());
        st.push(i);
    }
    while (!st.empty()) st.pop();
    for (int i = n - 1; i >= 0; --i) {
        while (!st.empty() && nums[st.top()] < nums[i]) st.pop();
        right[i] = (st.empty() ? n : st.top()) - i;
        st.push(i);
    }
    long long totalMax = 0;
    for (int i = 0; i < n; ++i) {
        totalMax += static_cast<long long>(nums[i]) * left[i] * right[i];
    }

    // contributions as minimum
    while (!st.empty()) st.pop();
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && nums[st.top()] >= nums[i]) st.pop();
        left[i] = i - (st.empty() ? -1 : st.top());
        st.push(i);
    }
    while (!st.empty()) st.pop();
    for (int i = n - 1; i >= 0; --i) {
        while (!st.empty() && nums[st.top()] > nums[i]) st.pop();
        right[i] = (st.empty() ? n : st.top()) - i;
        st.push(i);
    }
    long long totalMin = 0;
    for (int i = 0; i < n; ++i) {
        totalMin += static_cast<long long>(nums[i]) * left[i] * right[i];
    }

    return totalMax - totalMin;
}

