int maxTotalFruits(std::vector<std::vector<int>>& fruits, int startPos, int k) {
    int n = static_cast<int>(fruits.size());
    int l = 0;
    long long curSum = 0;
    int best = 0;
    for (int r = 0; r < n; ++r) {
        curSum += fruits[r][1];
        while (l <= r) {
            int leftPos = fruits[l][0];
            int rightPos = fruits[r][0];
            int steps;
            if (rightPos < startPos) {
                steps = startPos - leftPos;
            } else if (leftPos > startPos) {
                steps = rightPos - startPos;
            } else {
                int leftDist = startPos - leftPos;
                int rightDist = rightPos - startPos;
                steps = std::min(leftDist * 2 + rightDist, rightDist * 2 + leftDist);
            }
            if (steps <= k) break;
            curSum -= fruits[l][1];
            ++l;
        }
        best = std::max(best, static_cast<int>(curSum));
    }
    return best;
}

