int maximumDetonation(const std::vector<std::vector<int>>& bombs) {
    int n = static_cast<int>(bombs.size());
    std::vector<std::vector<int>> adj(n);
    for (int i = 0; i < n; ++i) {
        int xi = bombs[i][0];
        int yi = bombs[i][1];
        int ri = bombs[i][2];
        int ri2 = ri * ri;
        for (int j = 0; j < n; ++j) {
            if (i == j) continue;
            int xj = bombs[j][0];
            int yj = bombs[j][1];
            int dx = xi - xj;
            int dy = yi - yj;
            if (dx * dx + dy * dy <= ri2) {
                adj[i].push_back(j);
            }
        }
    }

    int best = 0;
    for (int start = 0; start < n; ++start) {
        std::vector<bool> visited(n, false);
        std::vector<int> queue;
        queue.push_back(start);
        visited[start] = true;
        int count = 0;
        while (!queue.empty()) {
            int v = queue.back();
            queue.pop_back();
            ++count;
            for (int w : adj[v]) {
                if (!visited[w]) {
                    visited[w] = true;
                    queue.push_back(w);
                }
            }
        }
        if (count > best) best = count;
    }
    return best;
}

