struct Item { std::string name; int score; };
// "best" top() must be the WORST of the current top-k (smallest score; tie -> alphabetically later)
struct BestCmp { bool operator()(const Item& a, const Item& b) const { if (a.score!=b.score) return a.score>b.score; return a.name<b.name; } };
// "rest" top() must be the BEST of the leftovers (largest score; tie -> alphabetically first)
struct RestCmp { bool operator()(const Item& a, const Item& b) const { if (a.score!=b.score) return a.score<b.score; return a.name>b.name; } };
class SORTracker {
    std::priority_queue<Item, std::vector<Item>, BestCmp> best;
    std::priority_queue<Item, std::vector<Item>, RestCmp> rest;
    int k = 0;
public:
    void add(const std::string& name, int score) {
        Item it{name, score};
        best.push(it);
        if ((int)best.size() > k) {
            Item moved = best.top(); best.pop(); rest.push(moved);
        }
    }
    std::string get() {
        ++k;
        if (!rest.empty()) { Item moved = rest.top(); rest.pop(); best.push(moved); }
        return best.top().name;
    }
};

