int wateringPlants(const std::vector<int>& plants, int capacityA, int capacityB) {
    int left = 0;
    int right = static_cast<int>(plants.size()) - 1;
    int waterA = capacityA;
    int waterB = capacityB;
    int refill = 0;
    while (left <= right) {
        if (left == right) {
            if (waterA < plants[left]) {
                ++refill;
                waterA = capacityA;
            }
            break;
        }
        if (waterA < plants[left]) {
            ++refill;
            waterA = capacityA;
        }
        waterA -= plants[left];
        ++left;
        if (waterB < plants[right]) {
            ++refill;
            waterB = capacityB;
        }
        waterB -= plants[right];
        --right;
    }
    return refill;
}

