        const std::string& s = words[i];
        if (s.empty()) {
            return s;
        }
        size_t left = 0;
        size_t right = s.size() - 1;
        while (left < right && s[left] == s[right]) {
            ++left;
            --right;
        }
        if (left >= right) {
            return s;
        }
    }
    return "";
}

