int minOperations(const std::vector<int>& arr, int k) {
    size_t n = arr.size();
    int kept = 0;
    for (int start = 0; start < k; ++start) {
        std::vector<int> tails;
        for (size_t i = start; i < n; i += k) {
            int x = arr[i];
            auto it = std::upper_bound(tails.begin(), tails.end(), x);
            if (it == tails.end()) {
                tails.push_back(x);
            } else {
                *it = x;
            }
        }
        kept += static_cast<int>(tails.size());
    }
    return static_cast<int>(n) - kept;
}

