std::vector<std::string> findAllRecipes(const std::vector<std::string>& recipes, const std::vector<std::vector<std::string>>& ingredients, const std::vector<std::string>& supplies) {
    std::unordered_set<std::string> available(supplies.begin(), supplies.end());
    std::unordered_set<std::string> recipeSet(recipes.begin(), recipes.end());

    std::unordered_map<std::string, int> indegree;
    std::unordered_map<std::string, std::vector<std::string>> graph;
    std::unordered_map<std::string, bool> possible;

    for (const auto& r : recipes) {
        indegree[r] = 0;
        possible[r] = true;
    }

    for (size_t i = 0; i < recipes.size(); ++i) {
        const std::string& rec = recipes[i];
        for (const std::string& ing : ingredients[i]) {
            if (recipeSet.count(ing)) {
                indegree[rec] += 1;
                graph[ing].push_back(rec);
            } else if (!available.count(ing)) {
                possible[rec] = false;
            }
        }
    }

    std::vector<std::string> queue;
    for (const auto& r : recipes) {
        if (possible[r] && indegree[r] == 0) {
            queue.push_back(r);
        }
    }

    std::vector<std::string> result;
    size_t qHead = 0;
    while (qHead < queue.size()) {
        const std::string& cur = queue[qHead++];
        result.push_back(cur);
        available.insert(cur);

        auto it = graph.find(cur);
        if (it == graph.end()) continue;
        for (const std::string& nxt : it->second) {
            indegree[nxt] -= 1;
            if (indegree[nxt] == 0 && possible[nxt]) {
                queue.push_back(nxt);
            }
        }
    }
    return result;
}

#include <bits/stdc++.h>
#include <string>

bool canBeValid(const std::string& s, const std::string& locked) {
    size_t n = s.size();
    if (n % 2 == 1) return false;
    int balance = 0;
    int free = 0;
    for (size_t i = 0; i < n; ++i) {
        if (locked[i] == '1') {
            balance += (s[i] == '(') ? 1 : -1;
        } else {
            ++free;
        }
        if (balance < 0) {
            if (free == 0) return false;
            --free;
            ++balance;
        }
    }
    return balance <= free;
}

#include <bits/stdc++.h>

std::vector<int> executeInstructions(int n, std::vector<int>& startPos, std::string s) {
    int m = static_cast<int>(s.size());
    std::vector<int> answer(m);
    std::vector<std::vector<int>> next(n, std::vector<int>(n, 0));
    std::vector<std::vector<int>> cur(n, std::vector<int>(n, 0));
    for (int i = m - 1; i >= 0; --i) {
        char c = s[i];
        for (int r = 0; r < n; ++r) {
            for (int col = 0; col < n; ++col) {
                int nr = r, nc = col;
                if (c == 'L') --nc;
                else if (c == 'R') ++nc;
                else if (c == 'U') --nr;
                else if (c == 'D') ++nr;
                if (nr < 0 || nr >= n || nc < 0 || nc >= n) {
                    cur[r][col] = 0;
                } else {
                    cur[r][col] = 1 + next[nr][nc];
                }
            }
        }
        answer[i] = cur[startPos[0]][startPos[1]];
        std::swap(cur, next);
    }
    return answer;
}

#include <bits/stdc++.h>

std::string abbreviateProduct(int left, int right) {
    if (left == 0) return std::string("0e0");
    long long cnt2 = 0, cnt5 = 0;
    const long long MOD = 100000; // 10^5
    long long cur = 1;
    long double logSum = 0.0L;
    for (int i = left; i <= right; ++i) {
        int x = i;
        while ((x & 1) == 0) { ++cnt2; x >>= 1; }
        while (x % 5 == 0) { ++cnt5; x /= 5; }
        cur = (cur * (x % MOD)) % MOD;
        logSum += std::log10((long double)i);
    }
    long long zeros = std::min(cnt2, cnt5);
    long long extra2 = cnt2 - zeros;
    long long extra5 = cnt5 - zeros;

    auto modPow = [&](long long base, long long exp) {
        long long res = 1 % MOD;
        base %= MOD;
        while (exp) {
            if (exp & 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    };

    cur = (cur * modPow(2, extra2)) % MOD;
    cur = (cur * modPow(5, extra5)) % MOD;

    long double effectiveLog = logSum - (long double)zeros;
    long long totalDigits = (long long)std::floor(effectiveLog) + 1;
    if (totalDigits <= 10) {
        unsigned long long prod = 1;
        for (int i = left; i <= right; ++i) prod *= (unsigned long long)i;
        std::string s;
        while (prod > 0) {
            s.push_back('0' + (int)(prod % 10));
            prod /= 10;
        }
        if (s.empty()) s = "0";
        std::reverse(s.begin(), s.end());
        long long z = 0;
        while (!s.empty() && s.back() == '0') {
            s.pop_back();
            ++z;
        }
        if (s.empty()) s = "0";
        return s + "e" + std::to_string(z);
    }

    long double frac = effectiveLog - std::floor(effectiveLog);
    long double leadingVal = std::pow(10.0L, frac + 4); // 5 digits
    int first5 = (int)leadingVal;
    std::ostringstream oss;
    oss << std::setw(5) << std::setfill('0') << cur;
    std::string last5 = oss.str();

    return std::to_string(first5) + "..." + last5 + "e" + std::to_string(zeros);
}

