#include <unordered_map>

std::vector<long long> intervalsBetweenIdentical(const std::vector<int>& arr) {
    std::unordered_map<int, std::vector<int>> groups;
    for (int i = 0; i < static_cast<int>(arr.size()); ++i) {
        int v = arr[i];
        groups[v].push_back(i);
    }

    std::vector<long long> ans(arr.size(), 0);
    for (auto& kv : groups) {
        const std::vector<int>& indices = kv.second;
        int m = static_cast<int>(indices.size());
        if (m == 1) continue;

        std::vector<long long> pref(m);
        pref[0] = indices[0];
        for (int i = 1; i < m; ++i) pref[i] = pref[i - 1] + indices[i];
        long long total = pref[m - 1];

        for (int i = 0; i < m; ++i) {
            int idx = indices[i];
            long long left = static_cast<long long>(idx) * i - (i > 0 ? pref[i - 1] : 0LL);
            long long right = (total - pref[i]) - static_cast<long long>(idx) * (m - i - 1);
            ans[idx] = left + right;
        }
    }
    return ans;
}

