#include <unordered_map>

std::vector<int> recoverArray(std::vector<int>& nums) {
    int m = static_cast<int>(nums.size());
    int n = m / 2;
    std::sort(nums.begin(), nums.end());
    long long smallest = nums[0];
    for (int i = 1; i < m; ++i) {
        long long diff = static_cast<long long>(nums[i]) - smallest;
        if (diff <= 0 || diff % 2 != 0) continue;
        long long k = diff / 2;
        std::unordered_map<long long, int> cnt;
        cnt.reserve(m * 2);
        for (int v : nums) ++cnt[v];
        std::vector<int> arr;
        arr.reserve(n);
        bool ok = true;
        for (int v : nums) {
            long long cur = v;
            if (cnt[cur] == 0) continue;
            --cnt[cur];
            long long partner = cur + 2 * k;
            if (cnt[partner] == 0) {
                ok = false;
                break;
            }
            --cnt[partner];
            arr.push_back(static_cast<int>(cur + k));
        }
        if (ok && static_cast<int>(arr.size()) == n) return arr;
    }
    return {};
}

