struct ListNode {
    int val;
    ListNode* next;
    ListNode() : val(0), next(nullptr) {}
    ListNode(int x) : val(x), next(nullptr) {}
    ListNode(int x, ListNode* next) : val(x), next(next) {}
};

int maxTwinSum(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    ListNode* prev = nullptr;
    ListNode* curr = slow;
    while (curr) {
        ListNode* nxt = curr->next;
        curr->next = prev;
        prev = curr;
        curr = nxt;
    }
    int maxSum = 0;
    ListNode* left = head;
    ListNode* right = prev;
    while (right) {
        int twinSum = left->val + right->val;
        if (twinSum > maxSum) maxSum = twinSum;
        left = left->next;
        right = right->next;
    }
    return maxSum;
}

