std::string capitalizeTitle(const std::string& title) {
    std::vector<std::string> words;
    size_t start = 0;
    for (size_t i = 0; i < title.size(); ++i) {
        if (title[i] == ' ') {
            words.emplace_back(title.substr(start, i - start));
            start = i + 1;
        }
    }
    words.emplace_back(title.substr(start));
    for (size_t i = 0; i < words.size(); ++i) {
        std::string& w = words[i];
        std::string lower;
        lower.reserve(w.size());
        for (char c : w) {
            lower.push_back(static_cast<char>(std::tolower(static_cast<unsigned char>(c))));
        }
        if (w.size() < 3) {
            w = lower;
        } else {
            if (!lower.empty()) {
                lower[0] = static_cast<char>(std::toupper(static_cast<unsigned char>(lower[0])));
            }
            w = lower;
        }
    }
    std::string result;
    for (size_t i = 0; i < words.size(); ++i) {
        if (i) result.push_back(' ');
        result += words[i];
    }
    return result;
}

#include <bits/stdc++.h>

int maximumInvitations(std::vector<int> favorite) {
    int n = static_cast<int>(favorite.size());
    std::vector<std::vector<int>> rev(n);
    std::vector<int> indeg(n, 0);
    for (int i = 0; i < n; ++i) {
        rev[favorite[i]].push_back(i);
        ++indeg[favorite[i]];
    }

    std::vector<int> depth(n, 0);
    std::queue<int> q;
    for (int i = 0; i < n; ++i) {
        if (indeg[i] == 0) q.push(i);
    }

    while (!q.empty()) {
        int u = q.front(); q.pop();
        int v = favorite[u];
        depth[v] = std::max(depth[v], depth[u] + 1);
        if (--indeg[v] == 0) q.push(v);
    }

    std::vector<char> visited(n, 0);
    int maxCycle = 0;
    for (int i = 0; i < n; ++i) {
        if (indeg[i] > 0 && !visited[i]) {
            int cur = i, cnt = 0;
            do {
                visited[cur] = 1;
                cur = favorite[cur];
                ++cnt;
            } while (cur != i);
            maxCycle = std::max(maxCycle, cnt);
        }
    }

    long long sumPairs = 0;
    for (int i = 0; i < n; ++i) {
        int j = favorite[i];
        if (i < j && favorite[j] == i) {
            sumPairs += 2 + depth[i] + depth[j];
        }
    }

    return std::max(maxCycle, static_cast<int>(sumPairs));
}

