int longestPalindrome(const std::vector<std::string>& words) {
    std::unordered_map<std::string, int> freq;
    for (const auto& w : words) {
        ++freq[w];
    }

    int length = 0;
    bool hasCenter = false;

    for (auto& entry : freq) {
        const std::string& w = entry.first;
        int cnt = entry.second;
        if (cnt == 0) continue;

        std::string rev;
        rev.push_back(w[1]);
        rev.push_back(w[0]);

        if (w == rev) {
            int pairs = cnt / 2;
            length += pairs * 4;
            if (cnt % 2 == 1) hasCenter = true;
        } else {
            auto it = freq.find(rev);
            if (it != freq.end() && it->second > 0) {
                int pairs = std::min(cnt, it->second);
                length += pairs * 4;
                it->second = 0;
            }
        }
    }

    if (hasCenter) length += 2;
    return length;
}

