long long earliestFullBloom(const std::vector<int>& plantTime, const std::vector<int>& growTime) {
    std::vector<std::pair<int, int>> seeds;
    seeds.reserve(plantTime.size());
    for (size_t i = 0; i < plantTime.size(); ++i) {
        seeds.emplace_back(plantTime[i], growTime[i]);
    }
    std::sort(seeds.begin(), seeds.end(),
        [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
            return a.second > b.second;
        });
    long long currentDay = 0;
    long long answer = 0;
    for (const auto& s : seeds) {
        currentDay += s.first;
        long long bloomDay = currentDay + s.second;
        if (bloomDay > answer) answer = bloomDay;
    }
    return answer;
}

#include <bits/stdc++.h>
#include <vector>

bool possible(const std::vector<std::vector<int>>& grid, int stampHeight, int stampWidth) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());

    std::vector<std::vector<int>> pref(m + 1, std::vector<int>(n + 1, 0));
    for (int i = 0; i < m; ++i) {
        int rowSum = 0;
        for (int j = 0; j < n; ++j) {
            rowSum += grid[i][j];
            pref[i + 1][j + 1] = pref[i][j + 1] + rowSum;
        }
    }

    std::vector<std::vector<int>> diff(m + 1, std::vector<int>(n + 1, 0));

    for (int i = 0; i + stampHeight <= m; ++i) {
        for (int j = 0; j + stampWidth <= n; ++j) {
            int total = pref[i + stampHeight][j + stampWidth]
                      - pref[i][j + stampWidth]
                      - pref[i + stampHeight][j]
                      + pref[i][j];
            if (total == 0) {
                diff[i][j] += 1;
                diff[i + stampHeight][j] -= 1;
                diff[i][j + stampWidth] -= 1;
                diff[i + stampHeight][j + stampWidth] += 1;
            }
        }
    }

    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i > 0) diff[i][j] += diff[i - 1][j];
            if (j > 0) diff[i][j] += diff[i][j - 1];
            if (i > 0 && j > 0) diff[i][j] -= diff[i - 1][j - 1];
            if (grid[i][j] == 0 && diff[i][j] == 0) return false;
        }
    }
    return true;
}

