bool isValidMatrix(const std::vector<std::vector<int>>& matrix) {
    int n = static_cast<int>(matrix.size());
    for (int i = 0; i < n; ++i) {
        if (matrix[i].size() != static_cast<std::size_t>(n)) return false;
    }
    std::vector<unsigned char> seenRow(n + 1);
    std::vector<unsigned char> seenCol(n + 1);
    for (int i = 0; i < n; ++i) {
        std::fill(seenRow.begin(), seenRow.end(), 0);
        std::fill(seenCol.begin(), seenCol.end(), 0);
        for (int j = 0; j < n; ++j) {
            int rowVal = matrix[i][j];
            if (rowVal < 1 || rowVal > n || seenRow[rowVal]) return false;
            seenRow[rowVal] = 1;
            int colVal = matrix[j][i];
            if (colVal < 1 || colVal > n || seenCol[colVal]) return false;
            seenCol[colVal] = 1;
        }
    }
    return true;
}

