std::vector<std::string> divideString(const std::string& s, int k, const std::string& fill) {
    std::vector<std::string> groups;
    for (size_t i = 0; i < s.size(); i += static_cast<size_t>(k)) {
        std::string part = s.substr(i, static_cast<size_t>(k));
        if (static_cast<int>(part.size()) < k) {
            int missing = k - static_cast<int>(part.size());
            for (int j = 0; j < missing; ++j) {
                part += fill;
            }
        }
        groups.push_back(part);
    }
    return groups;
}

