long long maxPoints(const std::vector<std::vector<int>>& questions) {
    int n = static_cast<int>(questions.size());
    std::vector<long long> dp(n + 1, 0);
    for (int i = n - 1; i >= 0; --i) {
        int pts = questions[i][0];
        int skip = questions[i][1];
        int next = i + skip + 1;
        long long take = pts + (next < n ? dp[next] : 0);
        long long skipIt = dp[i + 1];
        dp[i] = take > skipIt ? take : skipIt;
    }
    return dp[0];
}

