int countWords(const std::vector<std::string>& startWords, const std::vector<std::string>& targetWords) {
    std::unordered_set<int> startMasks;
    for (const std::string& w : startWords) {
        int mask = 0;
        for (size_t i = 0; i < w.size(); ++i) {
            mask |= 1 << (w[i] - 'a');
        }
        startMasks.insert(mask);
    }

    int answer = 0;
    for (const std::string& w : targetWords) {
        int mask = 0;
        for (size_t i = 0; i < w.size(); ++i) {
            mask |= 1 << (w[i] - 'a');
        }
        for (size_t i = 0; i < w.size(); ++i) {
            int without = mask ^ (1 << (w[i] - 'a'));
            if (startMasks.find(without) != startMasks.end()) {
                ++answer;
                break;
            }
        }
    }
    return answer;
}

