long long countHiddenSequences(const std::vector<int>& differences, long long lower, long long upper) {
    long long pref = 0;
    long long maxLow = lower;
    long long minHigh = upper;
    for (size_t i = 0; i < differences.size(); ++i) {
        pref += differences[i];
        maxLow = std::max(maxLow, lower - pref);
        minHigh = std::min(minHigh, upper - pref);
    }
    long long ans = std::max(0LL, minHigh - maxLow + 1);
    return ans;
}

