long long maxRunTime(int n, const std::vector<long long>& batteries) {
    if (static_cast<int>(batteries.size()) < n) return 0;
    long long totalSum = 0;
    for (long long v : batteries) totalSum += v;
    long long low = 0, high = totalSum / n;
    while (low < high) {
        long long mid = (low + high + 1) / 2;
        long long available = 0;
        for (long long v : batteries) {
            available += (v < mid ? v : mid);
            if (available >= static_cast<long long>(n) * mid) break;
        }
        if (available >= static_cast<long long>(n) * mid) low = mid;
        else high = mid - 1;
    }
    return low;
}

