long long numberOfWays(const std::string& corridor) {
    constexpr long long MOD = 1000000007LL;
    std::vector<long long> seats;
    for (size_t i = 0; i < corridor.size(); ++i) {
        if (corridor[i] == 'S') {
            seats.push_back(static_cast<long long>(i));
        }
    }
    if (seats.empty() || seats.size() % 2 == 1) {
        return 0;
    }
    long long ans = 1;
    for (size_t i = 1; i + 1 < seats.size(); i += 2) {
        long long gap = seats[i + 1] - seats[i] - 1;
        ans = ans * (gap + 1) % MOD;
    }
    return ans;
}

