std::vector<std::vector<int>> highestRankedKItems(const std::vector<std::vector<int>>& grid, const std::vector<int>& pricing, const std::vector<int>& start, int k) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    int low = pricing[0];
    int high = pricing[1];
    std::vector<char> visited(m * n, 0);
    std::queue<int> q;
    int startIdx = start[0] * n + start[1];
    q.push(startIdx);
    visited[startIdx] = 1;
    struct Item {
        int dist;
        int price;
        int row;
        int col;
    };
    std::vector<Item> items;
    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};
    int dist = 0;
    while (!q.empty()) {
        int sz = static_cast<int>(q.size());
        for (int i = 0; i < sz; ++i) {
            int idx = q.front();
            q.pop();
            int r = idx / n;
            int c = idx % n;
            int price = grid[r][c];
            if (price >= low && price <= high) {
                items.push_back({dist, price, r, c});
            }
            for (int d = 0; d < 4; ++d) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
                int nIdx = nr * n + nc;
                if (visited[nIdx]) continue;
                if (grid[nr][nc] == 0) continue;
                visited[nIdx] = 1;
                q.push(nIdx);
            }
        }
        ++dist;
    }
    auto cmp = [](const Item& a, const Item& b) {
        if (a.dist != b.dist) return a.dist < b.dist;
        if (a.price != b.price) return a.price < b.price;
        if (a.row != b.row) return a.row < b.row;
        return a.col < b.col;
    };
    if (static_cast<int>(items.size()) > k) {
        std::nth_element(items.begin(), items.begin() + k, items.end(), cmp);
        items.resize(k);
    }
    std::sort(items.begin(), items.end(), cmp);
    std::vector<std::vector<int>> result;
    result.reserve(std::min(k, static_cast<int>(items.size())));
    for (const auto& it : items) {
        result.push_back({it.row, it.col});
    }
    return result;
}

