std::string subStrHash(std::string s, int power, int modulo, int k, int hashValue) {
    int n = static_cast<int>(s.size());
    long long power_k = 1;
    for (int i = 0; i < k; ++i) {
        power_k = (power_k * power) % modulo;
    }

    long long curHash = 0;
    long long pow = 1;
    for (int i = n - k; i < n; ++i) {
        int val = s[i] - 'a' + 1;
        curHash = (curHash + val * pow) % modulo;
        pow = (pow * power) % modulo;
    }

    int answerIdx = n - k;
    if (curHash == hashValue) {
        answerIdx = n - k;
    }

    for (int i = n - k - 1; i >= 0; --i) {
        int valNew = s[i] - 'a' + 1;
        int valOld = s[i + k] - 'a' + 1;
        curHash = (valNew + (long long)power * curHash % modulo - (long long)valOld * power_k % modulo) % modulo;
        if (curHash < 0) curHash += modulo;
        if (curHash == hashValue) {
            answerIdx = i;
        }
    }

    return s.substr(answerIdx, k);
}

