class DSU {
public:
    DSU(int n) : parent(n), sz(n, 1) {
        for (int i = 0; i < n; ++i) parent[i] = i;
    }
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    void unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (sz[ra] < sz[rb]) std::swap(ra, rb);
        parent[rb] = ra;
        sz[ra] += sz[rb];
    }
private:
    vector<int> parent, sz;
};

vector<int> groupStrings(const vector<string>& words) {
    int n = static_cast<int>(words.size());
    vector<int> masks(n);
    unordered_map<int, int> mp;
    mp.reserve(n * 2);
    mp.max_load_factor(0.7f);
    DSU dsu(n);
    for (int i = 0; i < n; ++i) {
        int mask = 0;
        for (char ch : words[i]) mask |= 1 << (ch - 'a');
        masks[i] = mask;
        auto it = mp.find(mask);
        if (it != mp.end()) dsu.unite(i, it->second);
        else mp.emplace(mask, i);
    }
    for (int i = 0; i < n; ++i) {
        int mask = masks[i];
        for (int b = 0; b < 26; ++b) {
            int bitb = 1 << b;
            if (mask & bitb) {
                int nb = mask ^ bitb;
                auto it = mp.find(nb);
                if (it != mp.end()) dsu.unite(i, it->second);
                for (int c = 0; c < 26; ++c) {
                    if (c == b) continue;
                    int bitc = 1 << c;
                    if (!(mask & bitc)) {
                        int nb2 = nb | bitc;
                        auto it2 = mp.find(nb2);
                        if (it2 != mp.end()) dsu.unite(i, it2->second);
                    }
                }
            } else {
                int nb = mask | bitb;
                auto it = mp.find(nb);
                if (it != mp.end()) dsu.unite(i, it->second);
            }
        }
    }
    unordered_map<int, int> compCount;
    compCount.reserve(n);
    int maxSize = 0;
    for (int i = 0; i < n; ++i) {
        int root = dsu.find(i);
        int cnt = ++compCount[root];
        if (cnt > maxSize) maxSize = cnt;
    }
    int groups = static_cast<int>(compCount.size());
    return {groups, maxSize};
}

