std::vector<int> maxScoreDivisions(const std::vector<int>& nums) {
    size_t n = nums.size();
    int totalOnes = 0;
    for (size_t i = 0; i < n; ++i) {
        if (nums[i] == 1) ++totalOnes;
    }

    int zerosLeft = 0, onesSeen = 0;
    int maxScore = -1;
    std::vector<int> answer;

    for (size_t i = 0; i <= n; ++i) {
        int onesRight = totalOnes - onesSeen;
        int score = zerosLeft + onesRight;

        if (score > maxScore) {
            maxScore = score;
            answer = {static_cast<int>(i)};
        } else if (score == maxScore) {
            answer.push_back(static_cast<int>(i));
        }

        if (i < n) {
            if (nums[i] == 0) ++zerosLeft;
            else ++onesSeen;
        }
    }
    return answer;
}

