std::vector<int> partitionArray(const std::vector<int>& nums, int pivot) {
    std::vector<int> less;
    std::vector<int> equal;
    std::vector<int> greater;
    less.reserve(nums.size());
    equal.reserve(nums.size());
    greater.reserve(nums.size());
    for (size_t i = 0; i < nums.size(); ++i) {
        int v = nums[i];
        if (v < pivot) less.push_back(v);
        else if (v == pivot) equal.push_back(v);
        else greater.push_back(v);
    }
    std::vector<int> result;
    result.reserve(nums.size());
    result.insert(result.end(), less.begin(), less.end());
    result.insert(result.end(), equal.begin(), equal.end());
    result.insert(result.end(), greater.begin(), greater.end());
    return result;
}

