int minCostSetTime(int startAt, int moveCost, int pushCost, int targetSeconds) {
    const int INF = 1e9;
    int best = INF;
    for (int minutes = 0; minutes <= 99; ++minutes) {
        int seconds = targetSeconds - minutes * 60;
        if (seconds < 0 || seconds > 99) continue;
        int d[4];
        d[0] = minutes / 10;
        d[1] = minutes % 10;
        d[2] = seconds / 10;
        d[3] = seconds % 10;
        int leadingZeros = 0;
        while (leadingZeros < 4 && d[leadingZeros] == 0) ++leadingZeros;
        for (int start = 0; start <= leadingZeros; ++start) {
            if (start == 4) continue;
            int cost = 0;
            int cur = startAt;
            for (int i = start; i < 4; ++i) {
                int digit = d[i];
                if (digit != cur) cost += moveCost;
                cost += pushCost;
                cur = digit;
            }
            best = std::min(best, cost);
        }
    }
    return best;
}

