long long minimumDifference(std::vector<int>& nums) {
    int total = static_cast<int>(nums.size());
    int n = total / 3;
    int two_n = 2 * n;
    std::vector<long long> leftMin(two_n + 1);
    std::vector<long long> rightMax(two_n + 1);
    std::priority_queue<int> maxHeap;
    long long sum = 0;
    for (int i = 0; i < two_n; ++i) {
        sum += nums[i];
        maxHeap.push(nums[i]);
        if (static_cast<int>(maxHeap.size()) > n) {
            sum -= maxHeap.top();
            maxHeap.pop();
        }
        if (i >= n - 1) {
            leftMin[i + 1] = sum;
        }
    }
    std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap;
    sum = 0;
    for (int i = total - 1; i >= n; --i) {
        sum += nums[i];
        minHeap.push(nums[i]);
        if (static_cast<int>(minHeap.size()) > n) {
            sum -= minHeap.top();
            minHeap.pop();
        }
        if (i <= two_n) {
            rightMax[i] = sum;
        }
    }
    long long answer = LLONG_MAX;
    for (int i = n; i <= two_n; ++i) {
        long long diff = leftMin[i] - rightMax[i];
        if (diff < answer) answer = diff;
    }
    return answer;
}

