long long smallestRearranged(long long num) {
    if (num == 0) return 0;
    bool isNeg = num < 0;
    std::string s = std::to_string(isNeg ? -num : num);
    std::vector<char> digits(s.begin(), s.end());
    if (isNeg) {
        std::sort(digits.begin(), digits.end(), std::greater<char>());
        return -std::stoll(std::string(digits.begin(), digits.end()));
    } else {
        std::sort(digits.begin(), digits.end());
        if (!digits.empty() && digits[0] == '0') {
            size_t i = 0;
            while (i < digits.size() && digits[i] == '0') ++i;
            char firstNonZero = digits[i];
            digits.erase(digits.begin() + i);
            digits.insert(digits.begin(), firstNonZero);
        }
        return std::stoll(std::string(digits.begin(), digits.end()));
    }
}

