class Bitset {
public:
    int n;
    std::vector<uint8_t> bits;
    bool flipped;
    int onesCount;
    Bitset(int size) : n(size), bits(size, 0), flipped(false), onesCount(0) {}
    void fix(int idx) {
        if ((bits[idx] ^ (flipped ? 1 : 0)) == 0) { bits[idx] = flipped ? 0 : 1; ++onesCount; }
    }
    void unfix(int idx) {
        if ((bits[idx] ^ (flipped ? 1 : 0)) == 1) { bits[idx] = flipped ? 1 : 0; --onesCount; }
    }
    void flip() { flipped = !flipped; onesCount = n - onesCount; }
    bool all() const { return onesCount == n; }
    bool one() const { return onesCount > 0; }
    int count() const { return onesCount; }
    std::string toString() const {
        std::string result; result.reserve(n);
        for (int i = 0; i < n; ++i) result.push_back('0' + (bits[i] ^ (flipped ? 1 : 0)));
        return result;
    }
};

