static std::pair<std::pair<int, int>, std::pair<int, int>> topTwo(const std::unordered_map<int, int>& freqMap) {
    std::pair<int, int> first = {-1, 0}, second = {-1, 0};
    for (const auto& kv : freqMap) {
        int val = kv.first;
        int cnt = kv.second;
        if (cnt > first.second) {
            second = first;
            first = {val, cnt};
        } else if (cnt > second.second) {
            second = {val, cnt};
        }
    }
    return {first, second};
}

int minOperations(const std::vector<int>& nums) {
    std::unordered_map<int, int> evenFreq;
    std::unordered_map<int, int> oddFreq;

    for (size_t i = 0; i < nums.size(); ++i) {
        if ((i & 1) == 0) {
            ++evenFreq[nums[i]];
        } else {
            ++oddFreq[nums[i]];
        }
    }

    auto evenPairs = topTwo(evenFreq);
    auto oddPairs = topTwo(oddFreq);
    auto evenBest = evenPairs.first;
    auto evenSecond = evenPairs.second;
    auto oddBest = oddPairs.first;
    auto oddSecond = oddPairs.second;

    int keep;
    if (evenBest.first != oddBest.first) {
        keep = evenBest.second + oddBest.second;
    } else {
        keep = std::max(evenBest.second + oddSecond.second,
                        evenSecond.second + oddBest.second);
    }

    return static_cast<int>(nums.size()) - keep;
}

