long long maximumANDSum(const std::vector<int>& nums, int numSlots) {
    int n = static_cast<int>(nums.size());
    int fullMask = (1 << n) - 1;
    const long long NEG = LLONG_MIN / 4;
    std::vector<long long> dp(1 << n, NEG);
    dp[0] = 0;
    for (int slot = 1; slot <= numSlots; ++slot) {
        std::vector<long long> ndp = dp; // option to skip this slot
        for (int mask = 0; mask <= fullMask; ++mask) {
            if (dp[mask] == NEG) continue;
            int remain = (~mask) & fullMask;
            // pick one number for this slot
            for (int i = 0; i < n; ++i) {
                if (remain & (1 << i)) {
                    int nmask = mask | (1 << i);
                    long long cand = dp[mask] + (static_cast<long long>(nums[i] & slot));
                    if (cand > ndp[nmask]) ndp[nmask] = cand;
                }
            }
            // pick two numbers for this slot
            for (int i = 0; i < n; ++i) {
                if (!(remain & (1 << i))) continue;
                for (int j = i + 1; j < n; ++j) {
                    if (!(remain & (1 << j))) continue;
                    int nmask = mask | (1 << i) | (1 << j);
                    long long cand = dp[mask] + (static_cast<long long>(nums[i] & slot)) + (static_cast<long long>(nums[j] & slot));
                    if (cand > ndp[nmask]) ndp[nmask] = cand;
                }
            }
        }
        dp.swap(ndp);
    }
    return dp[fullMask];
}

