std::vector<long long> maximumSplit(long long finalSum) {
    if (finalSum % 2 != 0) return std::vector<long long>();
    std::vector<long long> result;
    long long next = 2;
    long long remaining = finalSum;
    while (remaining >= next) {
        result.push_back(next);
        remaining -= next;
        next += 2;
    }
    if (remaining > 0) result.back() += remaining;
    return result;
}

int main() {
    for (auto v : {12LL, 7LL, 28LL}) {
        auto r = maximumSplit(v);
        for (auto x : r) cout << x << " ";
        cout << "\n";
    }
}

