struct ListNode {
    int val;
    ListNode* next;
    ListNode() : val(0), next(nullptr) {}
    ListNode(int x) : val(x), next(nullptr) {}
};

ListNode* mergeNodes(ListNode* head) {
    ListNode dummy(0);
    ListNode* tail = &dummy;
    ListNode* cur = head ? head->next : nullptr;
    int segmentSum = 0;
    while (cur) {
        if (cur->val == 0) {
            tail->next = new ListNode(segmentSum);
            tail = tail->next;
            segmentSum = 0;
        } else {
            segmentSum += cur->val;
        }
        cur = cur->next;
    }
    return dummy.next;
}

