std::string repeatLimitedString(const std::string& s, int repeatLimit) {
    std::array<int, 26> cnt{};
    for (char ch : s) {
        ++cnt[ch - 'a'];
    }
    std::string res;
    res.reserve(s.size());
    int lastIdx = -1;
    int lastRun = 0;
    while (true) {
        int i = 25;
        while (i >= 0 && cnt[i] == 0) --i;
        if (i < 0) break;
        if (i == lastIdx && lastRun == repeatLimit) {
            int j = i - 1;
            while (j >= 0 && cnt[j] == 0) --j;
            if (j < 0) break;
            res.push_back(static_cast<char>('a' + j));
            --cnt[j];
            lastIdx = j;
            lastRun = 1;
        } else {
            res.push_back(static_cast<char>('a' + i));
            --cnt[i];
            if (i == lastIdx) {
                ++lastRun;
            } else {
                lastIdx = i;
                lastRun = 1;
            }
        }
    }
    return res;
}

