class FenwickTree {
public:
    explicit FenwickTree(int n) : n_(n), tree_(n + 1, 0) {}
    void add(int idx, long long delta) {
        for (++idx; idx <= n_; idx += idx & -idx) {
            tree_[idx] += delta;
        }
    }
    long long sum(int idx) const {
        long long res = 0;
        for (++idx; idx > 0; idx -= idx & -idx) {
            res += tree_[idx];
        }
        return res;
    }
    long long rangeSum(int l, int r) const {
        if (l > r) return 0;
        return sum(r) - (l ? sum(l - 1) : 0);
    }
private:
    int n_;
    std::vector<long long> tree_;
};

long long countGoodTriplets(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    int n = static_cast<int>(nums1.size());
    std::vector<int> posIn2(n);
    for (int i = 0; i < n; ++i) {
        posIn2[nums2[i]] = i;
    }
    std::vector<int> p(n);
    for (int i = 0; i < n; ++i) {
        p[i] = posIn2[nums1[i]];
    }
    std::vector<long long> leftLess(n);
    FenwickTree bitLeft(n);
    for (int i = 0; i < n; ++i) {
        leftLess[i] = (p[i] > 0) ? bitLeft.sum(p[i] - 1) : 0;
        bitLeft.add(p[i], 1);
    }
    FenwickTree bitRight(n);
    long long ans = 0;
    for (int i = n - 1; i >= 0; --i) {
        long long rightGreater = (p[i] < n - 1) ? bitRight.rangeSum(p[i] + 1, n - 1) : 0;
        ans += leftLess[i] * rightGreater;
        bitRight.add(p[i], 1);
    }
    return ans;
}

