long long countEvenDigitSum(long long num) {
    std::string s = std::to_string(num);
    int n = static_cast<int>(s.size());
    std::vector<std::vector<long long>> memo(n, std::vector<long long>(2, -1));
    std::function<long long(int, int, bool)> dfs = [&](int pos, int parity, bool tight) -> long long {
        if (pos == n) return parity == 0 ? 1 : 0;
        if (!tight && memo[pos][parity] != -1) return memo[pos][parity];
        int limit = tight ? s[pos] - '0' : 9;
        long long res = 0;
        for (int d = 0; d <= limit; ++d) {
            int nextParity = (parity + d) & 1;
            bool nextTight = tight && d == limit;
            res += dfs(pos + 1, nextParity, nextTight);
        }
        if (!tight) memo[pos][parity] = res;
        return res;
    };
    return dfs(0, 0, true) - 1;
}

