static long long gcd_ll(long long a, long long b) {
    while (b != 0) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

long long countPairs(const std::vector<long long>& nums, long long k) {
    std::unordered_map<long long, long long> cnt;
    for (size_t i = 0; i < nums.size(); ++i) {
        long long g = gcd_ll(nums[i], k);
        auto it = cnt.find(g);
        if (it == cnt.end()) {
            cnt.emplace(g, 1);
        } else {
            it->second += 1;
        }
    }

    std::vector<long long> divisors;
    divisors.reserve(cnt.size());
    for (const auto& p : cnt) {
        divisors.push_back(p.first);
    }

    long long ans = 0;
    for (size_t i = 0; i < divisors.size(); ++i) {
        long long d1 = divisors[i];
        long long c1 = cnt[d1];
        for (size_t j = i; j < divisors.size(); ++j) {
            long long d2 = divisors[j];
            if ((d1 * d2) % k != 0) continue;
            long long c2 = cnt[d2];
            if (i == j) {
                ans += c1 * (c1 - 1) / 2;
            } else {
                ans += c1 * c2;
            }
        }
    }
    return ans;
}

