int minSteps(const std::string& s, const std::string& t) {
    std::vector<int> freq(26, 0);
    for (size_t i = 0; i < s.size(); ++i) {
        freq[s[i] - 'a']++;
    }
    for (size_t i = 0; i < t.size(); ++i) {
        freq[t[i] - 'a']--;
    }
    int steps = 0;
    for (int i = 0; i < 26; ++i) {
        steps += std::abs(freq[i]);
    }
    return steps;
}

