std::vector<std::vector<int>> getAncestors(int n, const std::vector<std::vector<int>>& edges) {
    std::vector<std::vector<int>> adj(n);
    std::vector<int> indeg(n, 0);
    for (const auto& e : edges) {
        int a = e[0];
        int b = e[1];
        adj[a].push_back(b);
        ++indeg[b];
    }

    std::vector<std::unordered_set<int>> ancestors(n);
    std::queue<int> q;
    for (int i = 0; i < n; ++i) {
        if (indeg[i] == 0) {
            q.push(i);
        }
    }

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            ancestors[v].insert(u);
            for (int anc : ancestors[u]) {
                ancestors[v].insert(anc);
            }
            if (--indeg[v] == 0) {
                q.push(v);
            }
        }
    }

    std::vector<std::vector<int>> answer;
    answer.reserve(n);
    for (const auto& s : ancestors) {
        std::vector<int> vec(s.begin(), s.end());
        std::sort(vec.begin(), vec.end());
        answer.push_back(std::move(vec));
    }
    return answer;
}

