long long minimumTime(const std::vector<int>& time, long long totalTrips) {
    long long low = 1;
    long long high = static_cast<long long>(*std::min_element(time.begin(), time.end())) * totalTrips;
    while (low < high) {
        long long mid = (low + high) / 2;
        long long trips = 0;
        for (size_t i = 0; i < time.size(); ++i) {
            trips += mid / time[i];
            if (trips >= totalTrips) break;
        }
        if (trips >= totalTrips) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

#include <bits/stdc++.h>

int minimumFinishTime(std::vector<std::vector<int>>& tires, int changeTime, int numLaps) {
    const long long INF = (1LL << 60);
    std::vector<long long> best(numLaps + 1, INF);
    for (const auto& t : tires) {
        long long f = t[0];
        long long r = t[1];
        long long cur = f;
        long long sum = 0;
        for (int lap = 1; lap <= numLaps; ++lap) {
            sum += cur;
            if (sum > INF) break;
            if (sum < best[lap]) best[lap] = sum;
            if (cur > changeTime + f) break;
            if (cur > INF / r) break;
            cur *= r;
        }
    }
    std::vector<long long> dp(numLaps + 1, INF);
    dp[0] = 0;
    for (int i = 1; i <= numLaps; ++i) {
        for (int k = 1; k <= i; ++k) {
            long long cand = dp[i - k] + (i - k == 0 ? 0 : changeTime) + best[k];
            if (cand < dp[i]) dp[i] = cand;
        }
    }
    return static_cast<int>(dp[numLaps]);
}

