struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

TreeNode* createBinaryTree(const std::vector<std::vector<int>>& descriptions) {
    std::unordered_map<int, TreeNode*> nodes;
    std::unordered_set<int> children;

    auto getNode = [&](int val) -> TreeNode* {
        auto it = nodes.find(val);
        if (it == nodes.end()) {
            TreeNode* newNode = new TreeNode(val);
            nodes.emplace(val, newNode);
            return newNode;
        }
        return it->second;
    };

    for (const auto& desc : descriptions) {
        int parentVal = desc[0];
        int childVal = desc[1];
        int isLeft = desc[2];
        TreeNode* parentNode = getNode(parentVal);
        TreeNode* childNode = getNode(childVal);
        if (isLeft) {
            parentNode->left = childNode;
        } else {
            parentNode->right = childNode;
        }
        children.insert(childVal);
    }

    for (const auto& kv : nodes) {
        if (!children.count(kv.first)) {
            return kv.second;
        }
    }
    return nullptr;
}

