std::vector<long long> replaceNonCoprime(const std::vector<long long>& nums) {
    std::vector<long long> stack;
    for (size_t i = 0; i < nums.size(); ++i) {
        stack.push_back(nums[i]);
        while (stack.size() >= 2) {
            long long b = stack[stack.size() - 1];
            long long a = stack[stack.size() - 2];
            long long g = gcd_ll(a, b);
            if (g == 1) break;
            stack.pop_back();
            stack.pop_back();
            long long lcm = (a / g) * b;
            stack.push_back(lcm);
        }
    }
    return stack;
}

