int mostFrequentFollowing(const std::vector<int>& nums, int key) {
    std::unordered_map<int, int> followCount;
    for (size_t i = 0; i + 1 < nums.size(); ++i) {
        if (nums[i] == key) {
            int target = nums[i + 1];
            ++followCount[target];
        }
    }
    int bestTarget = 0;
    int maxCount = -1;
    for (const auto& entry : followCount) {
        int t = entry.first;
        int cnt = entry.second;
        if (cnt > maxCount) {
            maxCount = cnt;
            bestTarget = t;
        }
    }
    return bestTarget;
}

