std::vector<std::string> cellsInRange(const std::string& s) {
    size_t colonPos = s.find(':');
    std::string part0 = s.substr(0, colonPos);
    std::string part1 = s.substr(colonPos + 1);
    int startCol = static_cast<int>(part0[0]);
    int endCol = static_cast<int>(part1[0]);
    int startRow = std::stoi(part0.substr(1));
    int endRow = std::stoi(part1.substr(1));
    std::vector<std::string> result;
    for (int c = startCol; c <= endCol; ++c) {
        for (int r = startRow; r <= endRow; ++r) {
            result.push_back(std::string(1, static_cast<char>(c)) + std::to_string(r));
        }
    }
    return result;
}

#include <bits/stdc++.h>

long long minMovesToMakePalindrome(std::string s) {
    long long moves = 0;
    int i = 0;
    int j = static_cast<int>(s.size()) - 1;
    while (i < j) {
        if (s[i] == s[j]) {
            ++i;
            --j;
            continue;
        }
        int k = j;
        while (k > i && s[k] != s[i]) {
            --k;
        }
        if (k == i) {
            std::swap(s[i], s[i + 1]);
            ++moves;
        } else {
            while (k < j) {
                std::swap(s[k], s[k + 1]);
                ++moves;
                ++k;
            }
            ++i;
            --j;
        }
    }
    return moves;
}

