long long minimalAppendSum(const std::vector<int>& nums, int k) {
    std::unordered_set<int> present;
    present.reserve(nums.size() * 2);
    for (int v : nums) {
        present.insert(v);
    }
    long long sum = 0;
    int added = 0;
    int candidate = 1;
    while (added < k) {
        if (present.find(candidate) == present.end()) {
            sum += candidate;
            ++added;
        }
        ++candidate;
    }
    return sum;
}

