std::vector<int> findKDistantIndices(const std::vector<int>& nums, int key, int k) {
    int n = static_cast<int>(nums.size());
    std::vector<int> diff(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        if (nums[i] == key) {
            int l = std::max(0, i - k);
            int r = std::min(n - 1, i + k);
            diff[l] += 1;
            diff[r + 1] -= 1;
        }
    }
    std::vector<int> result;
    int cur = 0;
    for (int i = 0; i < n; ++i) {
        cur += diff[i];
        if (cur > 0) {
            result.push_back(i);
        }
    }
    return result;
}

