int maximumTop(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    if (k == 0) return n ? nums[0] : -1;
    if (n == 1) {
        return (k % 2 == 1) ? -1 : nums[0];
    }
    int best = INT_MIN;
    int limit = std::min(n, k - 1);
    for (int i = 0; i < limit; ++i) {
        if (nums[i] > best) best = nums[i];
    }
    if (k < n && nums[k] > best) best = nums[k];
    return best;
}

