int countArtifacts(int n, const std::vector<std::vector<int>>& artifacts, const std::vector<std::vector<int>>& dig) {
    std::unordered_map<std::string, int> cellToArtifact;
    std::vector<int> remaining(artifacts.size());

    for (size_t i = 0; i < artifacts.size(); ++i) {
        int r1 = artifacts[i][0];
        int c1 = artifacts[i][1];
        int r2 = artifacts[i][2];
        int c2 = artifacts[i][3];
        int area = (r2 - r1 + 1) * (c2 - c1 + 1);
        remaining[i] = area;
        for (int r = r1; r <= r2; ++r) {
            for (int c = c1; c <= c2; ++c) {
                cellToArtifact[std::to_string(r) + ',' + std::to_string(c)] = static_cast<int>(i);
            }
        }
    }

    for (const auto& pair : dig) {
        int r = pair[0];
        int c = pair[1];
        std::string key = std::to_string(r) + ',' + std::to_string(c);
        auto it = cellToArtifact.find(key);
        if (it != cellToArtifact.end()) {
            int idx = it->second;
            --remaining[idx];
            cellToArtifact.erase(it);
        }
    }

    int extracted = 0;
    for (size_t i = 0; i < remaining.size(); ++i) {
        if (remaining[i] == 0) ++extracted;
    }
    return extracted;
}

#include <bits/stdc++.h>
#include <vector>
#include <queue>
#include <limits>
#include <utility>

std::vector<long long> dijkstra(int src, const std::vector<std::vector<std::pair<int,long long>>>& g) {
    const long long INF = std::numeric_limits<long long>::max() / 4;
    int n = static_cast<int>(g.size());
    std::vector<long long> dist(n, INF);
    dist[src] = 0;
    using Node = std::pair<long long,int>;
    std::priority_queue<Node, std::vector<Node>, std::greater<Node>> pq;
    pq.emplace(0, src);
    while (!pq.empty()) {
        Node top = pq.top();
        pq.pop();
        long long d = top.first;
        int u = top.second;
        if (d != dist[u]) continue;
        for (const auto& e : g[u]) {
            int v = e.first;
            long long w = e.second;
            if (dist[v] > d + w) {
                dist[v] = d + w;
                pq.emplace(dist[v], v);
            }
        }
    }
    return dist;
}

long long minimumWeight(int n, std::vector<std::vector<int>>& edges, int src1, int src2, int dest) {
    const long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<std::vector<std::pair<int,long long>>> adj(n), radj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        long long w = e[2];
        adj[u].emplace_back(v, w);
        radj[v].emplace_back(u, w);
    }
    std::vector<long long> d1 = dijkstra(src1, adj);
    std::vector<long long> d2 = dijkstra(src2, adj);
    std::vector<long long> d3 = dijkstra(dest, radj);
    long long ans = INF;
    for (int v = 0; v < n; ++v) {
        if (d1[v] == INF || d2[v] == INF || d3[v] == INF) continue;
        long long total = d1[v] + d2[v] + d3[v];
        if (total < ans) ans = total;
    }
    return ans == INF ? -1 : ans;
}

#include <bits/stdc++.h>
#include <vector>
#include <queue>

int halveArray(std::vector<int>& nums) {
    double total = 0.0;
    for (int v : nums) total += v;
    double target = total / 2.0;
    std::priority_queue<double> pq;
    for (int v : nums) pq.push(static_cast<double>(v));
    int ops = 0;
    while (total > target) {
        double cur = pq.top();
        pq.pop();
        double half = cur / 2.0;
        total -= half;
        pq.push(half);
        ++ops;
    }
    return ops;
}

