long long maxSubsequenceCount(std::string text, std::string pattern) {
    char a = pattern[0];
    char b = pattern[1];
    if (a == b) {
        long long cnt = 0;
        for (char c : text) {
            if (c == a) ++cnt;
        }
        return cnt * (cnt - 1) / 2 + cnt;
    }
    long long cntA = 0, cntB = 0, baseline = 0;
    for (char c : text) {
        if (c == a) {
            ++cntA;
        } else if (c == b) {
            baseline += cntA;
            ++cntB;
        }
    }
    return baseline + std::max(cntA, cntB);
}

