int minimumWhiteTiles(const std::string& floor, int numCarpets, int carpetLen) {
    int n = static_cast<int>(floor.size());
    std::vector<int> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        pref[i + 1] = pref[i] + (floor[i] == '1' ? 1 : 0);
    }

    std::vector<int> dpPrev = pref;

    for (int k = 1; k <= numCarpets; ++k) {
        std::vector<int> dpCurr(n + 1, 0);
        dpCurr[0] = 0;
        for (int i = 1; i <= n; ++i) {
            int notCover = dpCurr[i - 1] + (floor[i - 1] == '1' ? 1 : 0);
            int j = i - carpetLen >= 0 ? i - carpetLen : 0;
            int cover = dpPrev[j];
            dpCurr[i] = std::min(notCover, cover);
        }
        dpPrev = std::move(dpCurr);
    }
    return dpPrev[n];
}

