std::vector<int> maximumBobArrows(int numArrows, const std::vector<int>& aliceArrows) {
    const int n = 12;
    int bestScore = -1;
    int bestMask = 0;
    for (int mask = 0; mask < (1 << n); ++mask) {
        int arrowsNeeded = 0;
        int score = 0;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) {
                arrowsNeeded += aliceArrows[i] + 1;
                score += i;
            }
        }
        if (arrowsNeeded > numArrows) continue;
        if (score > bestScore) {
            bestScore = score;
            bestMask = mask;
        }
    }
    std::vector<int> bobArrows(n, 0);
    int used = 0;
    for (int i = 0; i < n; ++i) {
        if (bestMask & (1 << i)) {
            bobArrows[i] = aliceArrows[i] + 1;
            used += bobArrows[i];
        }
    }
    bobArrows[0] += numArrows - used;
    return bobArrows;
}

