struct Node {
    int len;
    char leftChar;
    int leftLen;
    char rightChar;
    int rightLen;
    int best;
};

static Node makeNode(char ch) {
    return Node{1, ch, 1, ch, 1, 1};
}

static Node merge(const Node& a, const Node& b) {
    Node node;
    node.len = a.len + b.len;
    node.leftChar = a.leftChar;
    node.leftLen = a.leftLen;
    node.rightChar = b.rightChar;
    node.rightLen = b.rightLen;
    node.best = std::max(a.best, b.best);
    if (a.rightChar == b.leftChar) {
        int cross = a.rightLen + b.leftLen;
        if (cross > node.best) node.best = cross;
    }
    if (a.leftLen == a.len && a.rightChar == b.leftChar) {
        node.leftLen = a.len + b.leftLen;
    }
    if (b.rightLen == b.len && a.rightChar == b.leftChar) {
        node.rightLen = b.len + a.rightLen;
    }
    return node;
}

static void build(std::vector<Node>& tree, const std::string& s, int idx, int l, int r) {
    if (l == r) {
        tree[idx] = makeNode(s[l]);
        return;
    }
    int mid = (l + r) >> 1;
    build(tree, s, idx << 1, l, mid);
    build(tree, s, idx << 1 | 1, mid + 1, r);
    tree[idx] = merge(tree[idx << 1], tree[idx << 1 | 1]);
}

static void update(std::vector<Node>& tree, int idx, int l, int r, int pos, char ch) {
    if (l == r) {
        tree[idx] = makeNode(ch);
        return;
    }
    int mid = (l + r) >> 1;
    if (pos <= mid) update(tree, idx << 1, l, mid, pos, ch);
    else update(tree, idx << 1 | 1, mid + 1, r, pos, ch);
    tree[idx] = merge(tree[idx << 1], tree[idx << 1 | 1]);
}

std::vector<int> longestRepeatingSubstring(std::string s, const std::vector<char>& queryCharacters, const std::vector<int>& queryIndices) {
    int n = static_cast<int>(s.length());
    if (n == 0) return {};
    int size = 4 * n;
    std::vector<Node> tree(size);
    build(tree, s, 1, 0, n - 1);
    std::vector<int> ans;
    ans.reserve(queryIndices.size());
    for (size_t i = 0; i < queryIndices.size(); ++i) {
        int pos = queryIndices[i];
        char ch = queryCharacters[i];
        if (s[pos] != ch) {
            s[pos] = ch;
            update(tree, 1, 0, n - 1, pos, ch);
        }
        ans.push_back(tree[1].best);
    }
    return ans;
}

