long long maxValueOfCoins(const std::vector<std::vector<int>>& piles, int k) {
    std::vector<long long> dp(k + 1, 0);
    for (size_t pileIdx = 0; pileIdx < piles.size(); ++pileIdx) {
        const std::vector<int>& pile = piles[pileIdx];
        int maxTake = std::min(static_cast<int>(pile.size()), k);
        std::vector<long long> pref(maxTake + 1, 0);
        for (int t = 1; t <= maxTake; ++t) {
            pref[t] = pref[t - 1] + pile[t - 1];
        }
        std::vector<long long> next = dp;
        for (int j = 0; j <= k; ++j) {
            int limit = std::min(maxTake, j);
            for (int t = 1; t <= limit; ++t) {
                long long candidate = dp[j - t] + pref[t];
                if (candidate > next[j]) {
                    next[j] = candidate;
                }
            }
        }
        dp = std::move(next);
    }
    return dp[k];
}

