std::vector<long long> findPalindromes(const std::vector<long long>& queries, int intLength) {
    int halfLen = (intLength + 1) / 2;
    long long start = static_cast<long long>(std::pow(10, halfLen - 1));
    long long maxCount = 9 * static_cast<long long>(std::pow(10, halfLen - 1));
    std::vector<long long> res;
    res.reserve(queries.size());
    for (size_t i = 0; i < queries.size(); ++i) {
        long long k = queries[i];
        if (k > maxCount) {
            res.push_back(-1);
            continue;
        }
        long long halfNum = start + k - 1;
        std::string halfStr = std::to_string(halfNum);
        std::string rev = halfStr;
        std::reverse(rev.begin(), rev.end());
        std::string palStr;
        if (intLength % 2 == 0) {
            palStr = halfStr + rev;
        } else {
            palStr = halfStr + rev.substr(1);
        }
        res.push_back(std::stoll(palStr));
    }
    return res;
}

