long long numberOfWays(const std::string& s) {
    std::size_t n = s.size();
    if (n < 3) return 0;
    std::size_t totalZero = 0;
    for (char ch : s) if (ch == '0') ++totalZero;
    std::size_t totalOne = n - totalZero;
    std::size_t prefixZero = 0;
    std::size_t prefixOne = 0;
    long long answer = 0;
    for (std::size_t j = 0; j < n; ++j) {
        std::size_t left, right;
        if (s[j] == '0') {
            left = prefixOne;
            right = totalOne - prefixOne;
        } else {
            left = prefixZero;
            right = totalZero - prefixZero;
        }
        answer += static_cast<long long>(left) * static_cast<long long>(right);
        if (s[j] == '0') ++prefixZero;
        else ++prefixOne;
    }
    return answer;
}

