long long sumScores(const std::string& s) {
    int n = static_cast<int>(s.size());
    if (n == 0) return 0;
    std::vector<int> Z(n, 0);
    Z[0] = n;
    int l = 0, r = 0;
    for (int i = 1; i < n; ++i) {
        if (i <= r) {
            Z[i] = std::min(r - i + 1, Z[i - l]);
        }
        while (i + Z[i] < n && s[Z[i]] == s[i + Z[i]]) {
            ++Z[i];
        }
        if (i + Z[i] - 1 > r) {
            l = i;
            r = i + Z[i] - 1;
        }
    }
    long long total = 0;
    for (int v : Z) total += v;
    return total;
}

