long long largestNumberAfterParitySwaps(long long num) {
    std::string s = std::to_string(num);
    int evenCnt[10] = {0};
    int oddCnt[10] = {0};

    for (char ch : s) {
        int d = ch - '0';
        if ((d & 1) == 0) {
            ++evenCnt[d];
        } else {
            ++oddCnt[d];
        }
    }

    int evenPtr = 8;
    int oddPtr = 9;
    std::string res;
    res.reserve(s.size());

    for (char ch : s) {
        int d = ch - '0';
        if ((d & 1) == 0) {
            while (evenPtr >= 0 && evenCnt[evenPtr] == 0) evenPtr -= 2;
            res.push_back(static_cast<char>(evenPtr + '0'));
            --evenCnt[evenPtr];
        } else {
            while (oddPtr >= 1 && oddCnt[oddPtr] == 0) oddPtr -= 2;
            res.push_back(static_cast<char>(oddPtr + '0'));
            --oddCnt[oddPtr];
        }
    }

    return std::stoll(res);
}

