long long maximumProduct(std::vector<int> nums, int k) {
    const long long MOD = 1000000007LL;
    std::priority_queue<long long, std::vector<long long>, std::greater<long long>> pq;
    for (int v : nums) pq.push(v);
    for (int i = 0; i < k; ++i) {
        long long x = pq.top();
        pq.pop();
        ++x;
        pq.push(x);
    }
    long long prod = 1;
    while (!pq.empty()) {
        prod = (prod * (pq.top() % MOD)) % MOD;
        pq.pop();
    }
    return prod;
}

