std::string minimizeResult(std::string expression) {
    int n = static_cast<int>(expression.size());
    int plusPos = static_cast<int>(expression.find('+'));
    long long bestVal = LLONG_MAX;
    std::string bestExpr;
    for (int i = 0; i < plusPos; ++i) {
        long long leftFactor = (i == 0) ? 1 : std::stoll(expression.substr(0, i));
        long long leftInside = std::stoll(expression.substr(i, plusPos - i));
        for (int j = plusPos + 1; j < n; ++j) {
            long long rightInside = std::stoll(expression.substr(plusPos + 1, j - plusPos));
            long long rightFactor = (j + 1 == n) ? 1 : std::stoll(expression.substr(j + 1));
            long long val = leftFactor * (leftInside + rightInside) * rightFactor;
            if (val < bestVal) {
                bestVal = val;
                bestExpr = expression.substr(0, i) + "(" + expression.substr(i, plusPos - i) + "+" + expression.substr(plusPos + 1, j - plusPos) + ")" + expression.substr(j + 1);
            }
        }
    }
    return bestExpr;
}

