long long maximumBeauty(std::vector<int>& flowers, long long newFlowers, int target, int full, int partial) {
    int n = static_cast<int>(flowers.size());
    std::sort(flowers.begin(), flowers.end());
    std::vector<long long> pref(n);
    for (int i = 0; i < n; ++i) {
        pref[i] = flowers[i] + (i ? pref[i - 1] : 0LL);
    }
    std::vector<long long> suff(n + 1, 0);
    for (int i = n - 1; i >= 0; --i) {
        long long need = static_cast<long long>(target) - flowers[i];
        if (need < 0) need = 0;
        suff[i] = suff[i + 1] + need;
    }
    long long ans = 0;
    for (int k = 0; k <= n; ++k) {
        long long costComplete = suff[n - k];
        if (costComplete > newFlowers) continue;
        long long remaining = newFlowers - costComplete;
        if (k == n) {
            ans = std::max(ans, static_cast<long long>(full) * n);
            continue;
        }
        if (partial == 0) {
            ans = std::max(ans, static_cast<long long>(full) * k);
            continue;
        }
        long long lo = 0, hi = static_cast<long long>(target) - 1;
        while (lo < hi) {
            long long mid = (lo + hi + 1) / 2;
            int idx = static_cast<int>(std::upper_bound(flowers.begin(), flowers.begin() + (n - k), static_cast<int>(mid)) - flowers.begin()) - 1;
            long long cost = 0;
            if (idx >= 0) cost = mid * (idx + 1) - pref[idx];
            if (cost <= remaining) lo = mid;
            else hi = mid - 1;
        }
        long long candidate = static_cast<long long>(full) * k + static_cast<long long>(partial) * lo;
        ans = std::max(ans, candidate);
    }
    return ans;
}

