int maximumScore(const std::vector<int>& scores, const std::vector<std::vector<int>>& edges) {
    int n = scores.size();
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    struct Neighbor { int id; int score; };
    std::vector<std::array<Neighbor, 2>> best(n);
    for (int i = 0; i < n; ++i) {
        best[i][0] = best[i][1] = Neighbor{-1, -1};
    }
    for (int i = 0; i < n; ++i) {
        for (int nb : adj[i]) {
            int sc = scores[nb];
            if (sc > best[i][0].score) {
                best[i][1] = best[i][0];
                best[i][0] = Neighbor{nb, sc};
            } else if (sc > best[i][1].score) {
                best[i][1] = Neighbor{nb, sc};
            }
        }
    }
    long long ans = -1;
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        std::vector<int> candU, candV;
        for (int k = 0; k < 2; ++k) {
            if (best[u][k].id != -1 && best[u][k].id != v) candU.push_back(best[u][k].id);
            if (best[v][k].id != -1 && best[v][k].id != u) candV.push_back(best[v][k].id);
        }
        for (int a : candU) {
            for (int d : candV) {
                if (a == d) continue;
                long long sum = (long long)scores[u] + scores[v] + scores[a] + scores[d];
                if (sum > ans) ans = sum;
            }
        }
    }
    return ans == -1 ? -1 : static_cast<int>(ans);
}

