std::string digitSumString(std::string s, int k) {
    while (static_cast<int>(s.size()) > k) {
        std::string next;
        for (size_t i = 0; i < s.size(); i += static_cast<size_t>(k)) {
            int sum = 0;
            size_t end = std::min(i + static_cast<size_t>(k), s.size());
            for (size_t j = i; j < end; ++j) {
                sum += s[j] - '0';
            }
            next += std::to_string(sum);
        }
        s.swap(next);
    }
    return s;
}

#include <bits/stdc++.h>

int maxTrailingZeros(std::vector<std::vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();
    std::vector<std::vector<int>> cnt2(m, std::vector<int>(n));
    std::vector<std::vector<int>> cnt5(m, std::vector<int>(n));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            int x = grid[i][j];
            if (x == 0) {
                cnt2[i][j] = cnt5[i][j] = 1;
                continue;
            }
            int c2 = 0, c5 = 0;
            while (x % 2 == 0) { ++c2; x /= 2; }
            while (x % 5 == 0) { ++c5; x /= 5; }
            cnt2[i][j] = c2;
            cnt5[i][j] = c5;
        }
    }
    std::vector<std::vector<int>> row2(m, std::vector<int>(n));
    std::vector<std::vector<int>> row5(m, std::vector<int>(n));
    std::vector<std::vector<int>> col2(m, std::vector<int>(n));
    std::vector<std::vector<int>> col5(m, std::vector<int>(n));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            row2[i][j] = cnt2[i][j] + (j > 0 ? row2[i][j - 1] : 0);
            row5[i][j] = cnt5[i][j] + (j > 0 ? row5[i][j - 1] : 0);
            col2[i][j] = cnt2[i][j] + (i > 0 ? col2[i - 1][j] : 0);
            col5[i][j] = cnt5[i][j] + (i > 0 ? col5[i - 1][j] : 0);
        }
    }
    int best = 0;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            int up2 = col2[i][j];
            int up5 = col5[i][j];
            int down2 = col2[m - 1][j] - (i > 0 ? col2[i - 1][j] : 0);
            int down5 = col5[m - 1][j] - (i > 0 ? col5[i - 1][j] : 0);
            int left2 = row2[i][j];
            int left5 = row5[i][j];
            int right2 = row2[i][n - 1] - (j > 0 ? row2[i][j - 1] : 0);
            int right5 = row5[i][n - 1] - (j > 0 ? row5[i][j - 1] : 0);
            int cell2 = cnt2[i][j];
            int cell5 = cnt5[i][j];
            {
                int total2 = up2 + left2 - cell2;
                int total5 = up5 + left5 - cell5;
                best = std::max(best, std::min(total2, total5));
            }
            {
                int total2 = up2 + right2 - cell2;
                int total5 = up5 + right5 - cell5;
                best = std::max(best, std::min(total2, total5));
            }
            {
                int total2 = down2 + left2 - cell2;
                int total5 = down5 + left5 - cell5;
                best = std::max(best, std::min(total2, total5));
            }
            {
                int total2 = down2 + right2 - cell2;
                int total5 = down5 + right5 - cell5;
                best = std::max(best, std::min(total2, total5));
            }
        }
    }
    return best;
}

