std::vector<int> intersectionMultiple(const std::vector<std::vector<int>>& nums) {
    if (nums.empty()) return {};

    size_t arrayCount = nums.size();
    std::unordered_map<int, int> freq;

    for (size_t i = 0; i < arrayCount; ++i) {
        std::unordered_set<int> uniqueInCurrent(nums[i].begin(), nums[i].end());
        for (const int& val : uniqueInCurrent) {
            ++freq[val];
        }
    }

    std::vector<int> result;
    for (const auto& pair : freq) {
        if (pair.second == static_cast<int>(arrayCount)) {
            result.push_back(pair.first);
        }
    }

    std::sort(result.begin(), result.end());
    return result;
}

