std::vector<int> countRectangles(std::vector<std::vector<int>> rectangles, std::vector<std::vector<int>> points) {
    std::sort(rectangles.begin(), rectangles.end(),
              [](const std::vector<int>& a, const std::vector<int>& b) { return b[0] < a[0]; });

    std::vector<std::tuple<int, int, int>> pts;
    pts.reserve(points.size());
    for (size_t i = 0; i < points.size(); ++i) {
        pts.emplace_back(points[i][0], points[i][1], static_cast<int>(i));
    }
    std::sort(pts.begin(), pts.end(),
              [](const std::tuple<int, int, int>& a, const std::tuple<int, int, int>& b) {
                  return std::get<0>(b) < std::get<0>(a);
              });

    std::vector<int> allHeights;
    allHeights.reserve(rectangles.size() + points.size());
    for (const auto& rec : rectangles) allHeights.push_back(rec[1]);
    for (const auto& pt : points) allHeights.push_back(pt[1]);

    std::sort(allHeights.begin(), allHeights.end());
    allHeights.erase(std::unique(allHeights.begin(), allHeights.end()), allHeights.end());

    std::unordered_map<int, int> idx;
    idx.reserve(allHeights.size() * 2);
    for (size_t i = 0; i < allHeights.size(); ++i) {
        idx[allHeights[i]] = static_cast<int>(i) + 1; // 1‑based
    }
    int size = static_cast<int>(allHeights.size());

    std::vector<int> bit(size + 2, 0);
    auto add = [&](int i, int delta) {
        for (int x = i; x <= size; x += x & -x) bit[x] += delta;
    };
    auto sum = [&](int i) {
        int s = 0;
        for (int x = i; x > 0; x -= x & -x) s += bit[x];
        return s;
    };

    std::vector<int> ans(points.size());
    size_t r = 0;
    for (const auto& tup : pts) {
        int x = std::get<0>(tup);
        int y = std::get<1>(tup);
        int orig = std::get<2>(tup);
        while (r < rectangles.size() && rectangles[r][0] >= x) {
            add(idx[rectangles[r][1]], 1);
            ++r;
        }
        int total = static_cast<int>(r);
        int belowY = sum(idx[y] - 1);
        ans[orig] = total - belowY;
    }
    return ans;
}

#include <bits/stdc++.h>

int longestPath(const std::vector<int>& parent, const std::string& s) {
    int n = static_cast<int>(parent.size());
    std::vector<std::vector<int>> children(n);
    for (int i = 1; i < n; ++i) {
        children[parent[i]].push_back(i);
    }
    std::vector<int> order;
    order.reserve(n);
    std::stack<int> st;
    st.push(0);
    while (!st.empty()) {
        int u = st.top();
        st.pop();
        order.push_back(u);
        for (int v : children[u]) {
            st.push(v);
        }
    }
    std::vector<int> dp(n, 0);
    int answer = 1;
    for (int i = n - 1; i >= 0; --i) {
        int u = order[i];
        int best1 = 0, best2 = 0;
        for (int v : children[u]) {
            if (s[v] == s[u]) continue;
            int len = dp[v];
            if (len > best1) {
                best2 = best1;
                best1 = len;
            } else if (len > best2) {
                best2 = len;
            }
        }
        answer = std::max(answer, best1 + best2 + 1);
        dp[u] = best1 + 1;
    }
    return answer;
}

