int countLatticePoints(const std::vector<std::vector<int>>& circles) {
    std::unordered_set<std::string> visited;
    for (size_t i = 0; i < circles.size(); ++i) {
        int cx = circles[i][0];
        int cy = circles[i][1];
        int r = circles[i][2];
        long long r2 = 1LL * r * r;
        for (int x = cx - r; x <= cx + r; ++x) {
            long long dx = static_cast<long long>(x) - cx;
            long long remaining = r2 - dx * dx;
            if (remaining < 0) continue;
            int maxDy = static_cast<int>(std::floor(std::sqrt(static_cast<double>(remaining))));
            for (int y = cy - maxDy; y <= cy + maxDy; ++y) {
                visited.insert(std::to_string(x) + "," + std::to_string(y));
            }
        }
    }
    return static_cast<int>(visited.size());
}

