std::vector<int> fullBloomFlowers(const std::vector<std::vector<int>>& flowers, const std::vector<int>& people) {
    std::vector<int> starts;
    std::vector<int> ends;
    starts.reserve(flowers.size());
    ends.reserve(flowers.size());

    for (size_t i = 0; i < flowers.size(); ++i) {
        starts.push_back(flowers[i][0]);
        ends.push_back(flowers[i][1]);
    }

    std::sort(starts.begin(), starts.end());
    std::sort(ends.begin(), ends.end());

    std::vector<int> ans(people.size());

    for (size_t i = 0; i < people.size(); ++i) {
        int t = people[i];
        int started = std::upper_bound(starts.begin(), starts.end(), t) - starts.begin();
        int ended = std::lower_bound(ends.begin(), ends.end(), t) - ends.begin();
        ans[i] = started - ended;
    }

    return ans;
}

