int minimumAverageDifference(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    long long totalSum = 0;
    for (int v : nums) totalSum += v;

    long long prefixSum = 0;
    int bestIdx = 0;
    long long bestDiff = std::numeric_limits<long long>::max();

    for (int i = 0; i < n; ++i) {
        prefixSum += nums[i];
        long long leftAvg = prefixSum / (i + 1);

        int rightCount = n - i - 1;
        long long rightAvg = rightCount > 0 ? (totalSum - prefixSum) / rightCount : 0;

        long long diff = leftAvg - rightAvg;
        if (diff < 0) diff = -diff;

        if (diff < bestDiff) {
            bestDiff = diff;
            bestIdx = i;
        }
    }
    return bestIdx;
}

