int countUnguarded(int m, int n, const std::vector<std::vector<int>>& guards, const std::vector<std::vector<int>>& walls) {
    const char EMPTY = 0;
    const char GUARD = 1;
    const char WALL = 2;
    const char GUARDED = 3;
    std::vector<std::vector<char>> grid(m, std::vector<char>(n, EMPTY));
    for (const auto& g : guards) {
        grid[g[0]][g[1]] = GUARD;
    }
    for (const auto& w : walls) {
        grid[w[0]][w[1]] = WALL;
    }
    // Row sweeps
    for (int i = 0; i < m; ++i) {
        bool seen = false;
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == GUARD) {
                seen = true;
            } else if (grid[i][j] == WALL) {
                seen = false;
            } else if (seen) {
                grid[i][j] = GUARDED;
            }
        }
        seen = false;
        for (int j = n - 1; j >= 0; --j) {
            if (grid[i][j] == GUARD) {
                seen = true;
            } else if (grid[i][j] == WALL) {
                seen = false;
            } else if (seen) {
                grid[i][j] = GUARDED;
            }
        }
    }
    // Column sweeps
    for (int j = 0; j < n; ++j) {
        bool seen = false;
        for (int i = 0; i < m; ++i) {
            if (grid[i][j] == GUARD) {
                seen = true;
            } else if (grid[i][j] == WALL) {
                seen = false;
            } else if (seen) {
                grid[i][j] = GUARDED;
            }
        }
        seen = false;
        for (int i = m - 1; i >= 0; --i) {
            if (grid[i][j] == GUARD) {
                seen = true;
            } else if (grid[i][j] == WALL) {
                seen = false;
            } else if (seen) {
                grid[i][j] = GUARDED;
            }
        }
    }
    int unguarded = 0;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == EMPTY) {
                ++unguarded;
            }
        }
    }
    return unguarded;
}

class Solution {
public:
    int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
    bool canReach(vector<vector<int>>& grid, vector<vector<int>>& fire, int wait) {
        int m = grid.size(), n = grid[0].size();
        if (wait >= fire[0][0]) return false;
        vector<vector<int>> person(m, vector<int>(n, INT_MAX));
        person[0][0] = wait;
        queue<pair<int,int>> q;
        q.push({0,0});
        while (!q.empty()) {
            auto [i,j] = q.front(); q.pop();
            for (auto& d : dirs) {
                int ni = i+d[0], nj = j+d[1];
                if (ni>=0 && ni<m && nj>=0 && nj<n && grid[ni][nj]!=2 && person[ni][nj]==INT_MAX) {
                    int t = person[i][j] + 1;
                    if (ni==m-1 && nj==n-1) {
                        if (t <= fire[ni][nj]) { person[ni][nj]=t; q.push({ni,nj}); }
                    } else {
                        if (t < fire[ni][nj]) { person[ni][nj]=t; q.push({ni,nj}); }
                    }
                }
            }
        }
        return person[m-1][n-1] != INT_MAX;
    }
    int maximumMinutes(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> fire(m, vector<int>(n, INT_MAX));
        queue<pair<int,int>> q;
        for (int i=0;i<m;i++) for (int j=0;j<n;j++) if (grid[i][j]==1) { fire[i][j]=0; q.push({i,j}); }
        while (!q.empty()) {
            auto [i,j] = q.front(); q.pop();
            for (auto& d : dirs) {
                int ni=i+d[0], nj=j+d[1];
                if (ni>=0 && ni<m && nj>=0 && nj<n && grid[ni][nj]!=2 && fire[ni][nj]==INT_MAX) {
                    fire[ni][nj] = fire[i][j]+1;
                    q.push({ni,nj});
                }
            }
        }
        if (fire[m-1][n-1] == INT_MAX) return canReach(grid, fire, 0) ? 1000000000 : -1;
        if (!canReach(grid, fire, 0)) return -1;
        int lo=0, hi=fire[m-1][n-1], ans=0;
        while (lo<=hi) {
            int mid = lo + (hi-lo)/2;
            if (canReach(grid, fire, mid)) { ans=mid; lo=mid+1; } else hi=mid-1;
        }
        return ans;
    }
};

