int countDistinctSubarrays(const std::vector<int>& nums, int k, int p) {
    const int64_t MOD1 = 1000000007LL;
    const int64_t MOD2 = 1000000009LL;
    const int64_t BASE = 91138233LL;
    int n = static_cast<int>(nums.size());

    std::vector<int64_t> pref1(n + 1, 0);
    std::vector<int64_t> pref2(n + 1, 0);
    std::vector<int64_t> pow1(n + 1, 1);
    std::vector<int64_t> pow2(n + 1, 1);

    for (int i = 0; i < n; ++i) {
        pref1[i + 1] = (pref1[i] * BASE + nums[i]) % MOD1;
        pref2[i + 1] = (pref2[i] * BASE + nums[i]) % MOD2;
        pow1[i + 1] = (pow1[i] * BASE) % MOD1;
        pow2[i + 1] = (pow2[i] * BASE) % MOD2;
    }

    std::unordered_set<std::string> seen;

    for (int i = 0; i < n; ++i) {
        int divCnt = 0;
        for (int j = i; j < n; ++j) {
            if (nums[j] % p == 0) ++divCnt;
            if (divCnt > k) break;

            int len = j - i + 1;
            int64_t h1 = (pref1[j + 1] - pref1[i] * pow1[len]) % MOD1;
            int64_t h2 = (pref2[j + 1] - pref2[i] * pow2[len]) % MOD2;
            if (h1 < 0) h1 += MOD1;
            if (h2 < 0) h2 += MOD2;

            std::string key = std::to_string(h1) + "," + std::to_string(h2);
            seen.insert(key);
        }
    }

    return static_cast<int>(seen.size());
}

