long long totalAppeal(const std::string& s) {
    std::unordered_map<char, int> last;
    long long cur = 0;
    long long total = 0;
    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        char ch = s[i];
        int prev = -1;
        auto it = last.find(ch);
        if (it != last.end()) {
            prev = it->second;
