struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode* left, TreeNode* right) : val(x), left(left), right(right) {}
};

static long long floorDiv(long long a, long long b) {
    if (a >= 0) return a / b;
    return - ((-a + b - 1) / b);
}

int countNodesEqualToAverage(TreeNode* root) {
    int answer = 0;
    std::function<std::pair<long long, int>(TreeNode*)> dfs = [&](TreeNode* node) -> std::pair<long long, int> {
        if (!node) return {0, 0};
        auto left = dfs(node->left);
        auto right = dfs(node->right);
        long long subtreeSum = node->val + left.first + right.first;
        int subtreeSize = 1 + left.second + right.second;
        if (node->val == floorDiv(subtreeSum, subtreeSize)) ++answer;
        return {subtreeSum, subtreeSize};
    };
    dfs(root);
    return answer;
}

#include <bits/stdc++.h>

int countTexts(const std::string& pressedKeys) {
    const int MOD = 1000000007;
    int n = static_cast<int>(pressedKeys.size());
    std::vector<int> dp3(n + 1, 0), dp4(n + 1, 0);
    dp3[0] = dp4[0] = 1;
    for (int i = 1; i <= n; ++i) {
        long long sum3 = dp3[i - 1];
        if (i >= 2) sum3 += dp3[i - 2];
        if (i >= 3) sum3 += dp3[i - 3];
        dp3[i] = static_cast<int>(sum3 % MOD);
        long long sum4 = dp4[i - 1];
        if (i >= 2) sum4 += dp4[i - 2];
        if (i >= 3) sum4 += dp4[i - 3];
        if (i >= 4) sum4 += dp4[i - 4];
        dp4[i] = static_cast<int>(sum4 % MOD);
    }
    long long result = 1;
    for (int i = 0; i < n; ) {
        char digit = pressedKeys[i];
        int j = i;
        while (j < n && pressedKeys[j] == digit) ++j;
        int len = j - i;
        if (digit == '7' || digit == '9')
            result = result * dp4[len] % MOD;
        else
            result = result * dp3[len] % MOD;
        i = j;
    }
    return static_cast<int>(result);
}

#include <bits/stdc++.h>
#include <vector>
#include <bitset>

bool hasValidPath(const std::vector<std::vector<char>>& grid) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    const int MAX = 205; // enough for m+n <= 200
    if (grid[0][0] == ')') return false;

    std::vector<std::vector<std::bitset<MAX>>> dp(m, std::vector<std::bitset<MAX>>(n));
    dp[0][0].set(1); // balance = 1 after first '('

    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i == 0 && j == 0) continue;
            std::bitset<MAX> cur;
            if (i > 0) cur |= dp[i - 1][j];
            if (j > 0) cur |= dp[i][j - 1];
            if (cur.none()) continue;
            if (grid[i][j] == '(') {
                cur <<= 1;
            } else {
                cur >>= 1;
            }
            dp[i][j] = cur;
        }
    }
    return dp[m - 1][n - 1].test(0);
}

