int maximumWhiteTiles(std::vector<std::vector<int>>& tiles, int carpetLen) {
    std::sort(tiles.begin(), tiles.end(), [](const std::vector<int>& a, const std::vector<int>& b) {
        return a[0] < b[0];
    });
    int n = static_cast<int>(tiles.size());
    int left = 0;
    long long curLen = 0;
    long long best = 0;
    for (int right = 0; right < n; ++right) {
        curLen += static_cast<long long>(tiles[right][1] - tiles[right][0] + 1);
        int carpetStart = tiles[right][1] - carpetLen + 1;
        while (left <= right && tiles[left][1] < carpetStart) {
            curLen -= static_cast<long long>(tiles[left][1] - tiles[left][0] + 1);
            ++left;
        }
        long long covered = curLen;
        if (tiles[left][0] < carpetStart) {
            covered -= static_cast<long long>(carpetStart - tiles[left][0]);
        }
        if (covered > best) best = covered;
    }
    return static_cast<int>(best);
}

