int64_t totalStrength(const std::vector<int>& strength) {
    const int64_t MOD = 1000000007LL;
    int n = static_cast<int>(strength.size());
    std::vector<int64_t> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        pref[i + 1] = (pref[i] + strength[i]) % MOD;
    }
    std::vector<int64_t> pref2(n + 2, 0);
    for (int i = 0; i <= n; ++i) {
        pref2[i + 1] = (pref2[i] + pref[i]) % MOD;
    }

    std::vector<int> leftLess(n), rightLessOrEqual(n);
    std::stack<int> st;
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && strength[st.top()] >= strength[i]) st.pop();
        leftLess[i] = st.empty() ? -1 : st.top();
        st.push(i);
    }
    while (!st.empty()) st.pop();
    for (int i = n - 1; i >= 0; --i) {
        while (!st.empty() && strength[st.top()] > strength[i]) st.pop();
        rightLessOrEqual[i] = st.empty() ? n : st.top();
        st.push(i);
    }

    int64_t answer = 0;
    for (int i = 0; i < n; ++i) {
        int64_t L = leftLess[i];
        int64_t R = rightLessOrEqual[i];
        int64_t leftCount = i - L;
        int64_t rightCount = R - i;

        int64_t sumRight = (pref2[R + 1] - pref2[i + 1] + MOD) % MOD;
        int64_t sumLeft = (pref2[i + 1] - pref2[L + 1] + MOD) % MOD;

        int64_t total = (leftCount % MOD) * sumRight % MOD;
        total = (total - (rightCount % MOD) * sumLeft % MOD + MOD) % MOD;

        answer = (answer + (strength[i] % MOD) * total) % MOD;
    }
    return answer;
}

