long long gcd_ll(long long a, long long b) {
    while (b != 0) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int minLines(std::vector<std::vector<int>>& stockPrices) {
    const int n = static_cast<int>(stockPrices.size());
    if (n <= 1) return 0;

    std::sort(stockPrices.begin(), stockPrices.end(),
              [](const std::vector<int>& p, const std::vector<int>& q) {
                  return p[0] < q[0];
              });

    long long dy = static_cast<long long>(stockPrices[1][1]) - stockPrices[0][1];
    long long dx = static_cast<long long>(stockPrices[1][0]) - stockPrices[0][0];
    long long g = gcd_ll(std::llabs(dy), std::llabs(dx));
    dy /= g;
    dx /= g;
    if (dx < 0) { dx = -dx; dy = -dy; }
    if (dx == 0) dy = 1;

    int lines = 1;

    for (int i = 2; i < n; ++i) {
        long long ndy = static_cast<long long>(stockPrices[i][1]) - stockPrices[i - 1][1];
        long long ndx = static_cast<long long>(stockPrices[i][0]) - stockPrices[i - 1][0];
        long long ng = gcd_ll(std::llabs(ndy), std::llabs(ndx));
        ndy /= ng;
        ndx /= ng;
        if (ndx < 0) { ndx = -ndx; ndy = -ndy; }
        if (ndx == 0) ndy = 1;

        if (ndy != dy || ndx != dx) {
            ++lines;
            dy = ndy;
            dx = ndx;
        }
    }
    return lines;
}

