int rearrange(const std::string& s, const std::string& target) {
    std::unordered_map<char, int> sCount;
    std::unordered_map<char, int> tCount;

    for (char ch : s) {
        sCount[ch] = sCount[ch] + 1;
    }

    for (char ch : target) {
        tCount[ch] = tCount[ch] + 1;
    }

    int copies = INT_MAX;
    for (const auto& kv : tCount) {
        char ch = kv.first;
        int needed = kv.second;
        int available = sCount.count(ch) ? sCount[ch] : 0;
        copies = std::min(copies, available / needed);
    }
    return copies == INT_MAX ? 0 : copies;
}

