std::string discountPrices(const std::string& sentence, int discount) {
    std::vector<std::string> words;
    size_t start = 0;
    for (size_t i = 0; i <= sentence.size(); ++i) {
        if (i == sentence.size() || sentence[i] == ' ') {
            words.push_back(sentence.substr(start, i - start));
            start = i + 1;
        }
    }
    for (size_t i = 0; i < words.size(); ++i) {
        const std::string& w = words[i];
        if (!w.empty() && w[0] == '$' && w.size() > 1) {
            bool isNumber = true;
            for (size_t j = 1; j < w.size(); ++j) {
                char c = w[j];
                if (c < '0' || c > '9') {
                    isNumber = false;
                    break;
                }
            }
            if (isNumber) {
                int price = std::stoi(w.substr(1));
                double discounted = price * (100 - discount) / 100.0;
                std::ostringstream oss;
                oss << '$' << std::fixed << std::setprecision(2) << discounted;
                words[i] = oss.str();
            }
        }
    }
    std::string result;
    for (size_t i = 0; i < words.size(); ++i) {
        if (i > 0) result.push_back(' ');
        result += words[i];
    }
    return result;
}

