int stepsToMakeNonDecreasing(const std::vector<int>& nums) {
    int maxSteps = 0;
    std::vector<std::pair<int, int>> stack;
    for (size_t i = 0; i < nums.size(); ++i) {
        int curSteps = 0;
        int maxPrev = 0;
        while (!stack.empty() && nums[i] >= stack.back().first) {
            maxPrev = std::max(maxPrev, stack.back().second);
            stack.pop_back();
        }
        if (!stack.empty()) {
            curSteps = maxPrev + 1;
        }
        maxSteps = std::max(maxSteps, curSteps);
        stack.emplace_back(nums[i], curSteps);
    }
    return maxSteps;
}

