class BookMyShow {
public:
    int n, m;
    std::vector<int> rem;
    std::vector<long long> sumTree;
    std::vector<int> maxTree;
    BookMyShow(int n_, int m_) : n(n_), m(m_), rem(n_, m_), sumTree(4*n_, 0), maxTree(4*n_, 0) {
        build(1, 0, n-1);
    }
    void build(int node, int l, int r) {
        if (l == r) { sumTree[node] = m; maxTree[node] = m; return; }
        int mid = (l+r)>>1;
        build(node*2, l, mid); build(node*2+1, mid+1, r);
        sumTree[node] = sumTree[node*2]+sumTree[node*2+1];
        maxTree[node] = std::max(maxTree[node*2], maxTree[node*2+1]);
    }
    void update(int node, int l, int r, int idx, int val) {
        if (l == r) { sumTree[node] = val; maxTree[node] = val; return; }
        int mid = (l+r)>>1;
        if (idx <= mid) update(node*2, l, mid, idx, val); else update(node*2+1, mid+1, r, idx, val);
        sumTree[node] = sumTree[node*2]+sumTree[node*2+1];
        maxTree[node] = std::max(maxTree[node*2], maxTree[node*2+1]);
    }
    int findGather(int node, int l, int r, int maxRow, int k) {
        if (l > maxRow || maxTree[node] < k) return -1;
        if (l == r) return l;
        int mid = (l+r)>>1;
        int left = findGather(node*2, l, mid, maxRow, k);
        if (left != -1) return left;
        return findGather(node*2+1, mid+1, r, maxRow, k);
    }
    long long querySum(int node, int l, int r, int ql, int qr) {
        if (ql > r || qr < l) return 0;
        if (ql <= l && r <= qr) return sumTree[node];
        int mid = (l+r)>>1;
        return querySum(node*2,l,mid,ql,qr) + querySum(node*2+1,mid+1,r,ql,qr);
    }
    int findFirstPositive(int node, int l, int r, int maxRow) {
        if (l > maxRow || maxTree[node] == 0) return -1;
        if (l == r) return l;
        int mid = (l+r)>>1;
        int left = findFirstPositive(node*2, l, mid, maxRow);
        if (left != -1) return left;
        return findFirstPositive(node*2+1, mid+1, r, maxRow);
    }
    std::vector<int> gather(int k, int maxRow) {
        int row = findGather(1, 0, n-1, maxRow, k);
        if (row == -1) return {};
        int startSeat = m - rem[row];
        rem[row] -= k;
        update(1, 0, n-1, row, rem[row]);
        return {row, startSeat};
    }
    bool scatter(int k, int maxRow) {
        long long total = querySum(1, 0, n-1, 0, maxRow);
        if (total < k) return false;
        while (k > 0) {
            int row = findFirstPositive(1, 0, n-1, maxRow);
            int take = std::min(rem[row], k);
            rem[row] -= take;
            update(1, 0, n-1, row, rem[row]);
            k -= take;
        }
        return true;
    }
};

