int minMaxGame(std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    while (n > 1) {
        for (int i = 0; i < n / 2; ++i) {
            if (i % 2 == 0) {
                nums[i] = std::min(nums[2 * i], nums[2 * i + 1]);
            } else {
                nums[i] = std::max(nums[2 * i], nums[2 * i + 1]);
            }
        }
        n = n / 2;
    }
    return nums[0];
}

