    std::vector<int> sorted = nums;
    std::sort(sorted.begin(), sorted.end());
    int groups = 1;
    int start = sorted[0];
    for (size_t i = 1; i < sorted.size(); ++i) {
        if (sorted[i] - start > k) {
            ++groups;
            start = sorted[i];
        }
    }
