std::vector<int> replaceElements(std::vector<int> nums, const std::vector<std::vector<int>>& operations) {
    std::unordered_map<int, std::size_t> pos;
    for (std::size_t i = 0; i < nums.size(); ++i) {
        pos[nums[i]] = i;
    }
    for (const auto& op : operations) {
        int oldVal = op[0];
        int newVal = op[1];
        auto it = pos.find(oldVal);
        if (it != pos.end()) {
            std::size_t idx = it->second;
            nums[idx] = newVal;
            pos.erase(it);
            pos[newVal] = idx;
        }
    }
    return nums;
}

