        long long spell = spells[i];
        long long need = (success + spell - 1) / spell;
        size_t lo = 0, hi = m;
        while (lo < hi) {
            size_t mid = (lo + hi) >> 1;
            if (potions[mid] < need) lo = mid + 1;
            else hi = mid;
        }
        answer[i] = static_cast<int>(m - lo);
    }
    return answer;
}

