bool matchSubstringAfterReplacement(const std::string& s, const std::string& sub, const std::vector<std::pair<char, char>>& mappings) {
    std::array<std::bitset<256>, 256> allow{};
    for (const auto& p : mappings) {
        unsigned char a = static_cast<unsigned char>(p.first);
        unsigned char b = static_cast<unsigned char>(p.second);
        allow[a].set(b);
    }
    size_t n = s.size();
    size_t m = sub.size();
