            unsigned char a = static_cast<unsigned char>(sub[j]);
            unsigned char b = static_cast<unsigned char>(s[i + j]);
            if (a != b && !allow[a].test(b)) {
                ok = false;
                break;
            }
        }
        if (ok) return true;
    }
    return false;
}

