int minimumPathCost(const std::vector<std::vector<int>>& grid, const std::vector<std::vector<int>>& moveCost) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());

    std::vector<long long> dpPrev(n);
    for (int j = 0; j < n; ++j) dpPrev[j] = grid[0][j];

    for (int i = 1; i < m; ++i) {
        std::vector<long long> dpCur(n);
        for (int j = 0; j < n; ++j) {
            long long best = LLONG_MAX;
            for (int k = 0; k < n; ++k) {
                long long cand = dpPrev[k] + moveCost[grid[i - 1][k]][j];
                if (cand < best) best = cand;
            }
            dpCur[j] = grid[i][j] + best;
        }
        dpPrev.swap(dpCur);
    }

    long long answer = LLONG_MAX;
    for (long long v : dpPrev) if (v < answer) answer = v;
    return static_cast<int>(answer);
}

