int distributeCookies(std::vector<int> cookies, int k) {
    std::sort(cookies.begin(), cookies.end(), std::greater<int>());
    int n = cookies.size();
    if (k >= n) return *std::max_element(cookies.begin(), cookies.end());
    int total = std::accumulate(cookies.begin(), cookies.end(), 0);
    int low = *std::max_element(cookies.begin(), cookies.end()), high = total;
    while (low < high) {
        int mid = (low + high) / 2;
        std::vector<int> load(k, 0);
        std::function<bool(int)> dfs = [&](int idx) -> bool {
            if (idx == n) return true;
            int cur = cookies[idx];
            for (int i = 0; i < k; ++i) {
                if (load[i] + cur > mid) continue;
                load[i] += cur;
                if (dfs(idx + 1)) return true;
                load[i] -= cur;
                if (load[i] == 0) break;
            }
            return false;
        };
        bool possible = dfs(0);
        if (possible) high = mid;
        else low = mid + 1;
    }
    return low;
}

