int maxProfit(int m, int n, const std::vector<std::array<int, 3>>& prices) {
    std::vector<std::vector<int>> priceMap(m + 1, std::vector<int>(n + 1, 0));
    for (const auto& triple : prices) {
        int h = triple[0];
        int w = triple[1];
        int p = triple[2];
        if (h <= m && w <= n && p > priceMap[h][w]) {
            priceMap[h][w] = p;
        }
    }

    std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1, 0));

    for (int h = 1; h <= m; ++h) {
        for (int w = 1; w <= n; ++w) {
            int best = priceMap[h][w];
            for (int cut = 1; cut < h; ++cut) {
                int cur = dp[cut][w] + dp[h - cut][w];
                if (cur > best) best = cur;
            }
            for (int cut = 1; cut < w; ++cut) {
                int cur = dp[h][cut] + dp[h][w - cut];
                if (cur > best) best = cur;
            }
            dp[h][w] = best;
        }
    }
    return dp[m][n];
}

