int longestBinarySubsequenceLength(const std::string& s, long long k) {
    int length = 0;
    for (int i = static_cast<int>(s.size()) - 1; i >= 0; --i) {
        if (s[i] == '0') {
            ++length;
        } else {
            if (length >= 63) continue;
            long long weight = 1LL << length;
            if (weight <= k) {
                k -= weight;
                ++length;
            }
        }
    }
    return length;
}

