long long distinctNames(const std::vector<std::string>& ideas) {
    std::array<std::unordered_set<std::string>, 26> groups;
    for (const std::string& w : ideas) {
        std::size_t first = static_cast<std::size_t>(w[0] - 'a');
        std::string suffix = w.substr(1);
        groups[first].insert(suffix);
    }

    long long answer = 0;
    for (std::size_t i = 0; i < 26; ++i) {
        if (groups[i].empty()) continue;
        for (std::size_t j = i + 1; j < 26; ++j) {
            if (groups[j].empty()) continue;

            const std::unordered_set<std::string>& setA = groups[i];
            const std::unordered_set<std::string>& setB = groups[j];
            const std::unordered_set<std::string>& smaller = (setA.size() < setB.size()) ? setA : setB;
            const std::unordered_set<std::string>& larger = (setA.size() < setB.size()) ? setB : setA;

            std::size_t common = 0;
            for (const auto& s : smaller) {
                if (larger.find(s) != larger.end()) ++common;
            }

            std::size_t uniqueI = groups[i].size() - common;
            std::size_t uniqueJ = groups[j].size() - common;
            answer += static_cast<long long>(uniqueI) * static_cast<long long>(uniqueJ) * 2;
        }
    }
    return answer;
}

