long long countPairs(int n, const std::vector<std::vector<int>>& edges) {
    std::vector<int> parent(n);
    std::vector<int> size(n);
    for (int i = 0; i < n; ++i) {
        parent[i] = i;
        size[i] = 1;
    }

    auto find = [&](int x) -> int {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    auto union_sets = [&](int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return;
        if (size[ra] < size[rb]) std::swap(ra, rb);
        parent[rb] = ra;
        size[ra] += size[rb];
    };

    for (const auto& e : edges) {
        union_sets(e[0], e[1]);
    }

    std::unordered_map<int, long long> compCount;
    for (int i = 0; i < n; ++i) {
        int root = find(i);
        ++compCount[root];
    }

    long long totalPairs = static_cast<long long>(n) * (n - 1) / 2;
    long long intraPairs = 0;
    for (const auto& kv : compCount) {
        long long c = kv.second;
        intraPairs += c * (c - 1) / 2;
    }

    return totalPairs - intraPairs;
}

#include <bits/stdc++.h>
using namespace std;

int countDistinctRollSequences(int n) {
    const long long MOD = 1000000007;
    auto gcd = [](int a, int b) {
        while (b) { int t = b; b = a % b; a = t; }
        return a;
    };
    if (n == 1) return 6;
    map<pair<int,int>, long long> dp;
    for (int a = 1; a <= 6; a++) {
        for (int b = 1; b <= 6; b++) {
            if (a == b || gcd(a, b) != 1) continue;
            dp[{b, a}] += 1;
        }
    }
    for (int len = 3; len <= n; len++) {
        map<pair<int,int>, long long> ndp;
        for (auto& [key, cnt] : dp) {
            int prev = key.first, prevprev = key.second;
            for (int v = 1; v <= 6; v++) {
                if (v == prev || v == prevprev || gcd(v, prev) != 1) continue;
                ndp[{v, prev}] = (ndp[{v, prev}] + cnt) % MOD;
            }
        }
        dp = ndp;
    }
    long long total = 0;
    for (auto& [key, cnt] : dp) total = (total + cnt) % MOD;
    return (int)total;
}

