static const long long MOD = 1000000007LL;

std::pair<long long, long long> fib(long long k) {
    if (k == 0) return {0, 1};
    auto p = fib(k / 2);
    long long a = p.first;
    long long b = p.second;
    long long twoBminusA = (2 * b % MOD - a + MOD) % MOD;
    long long c = (a * twoBminusA) % MOD;
    long long d = ((a * a) % MOD + (b * b) % MOD) % MOD;
    if (k % 2 == 0) return {c, d};
    return {d, (c + d) % MOD};
}

