std::vector<std::vector<int>> spiralMatrix(int m, int n, ListNode* head) {
    std::vector<std::vector<int>> matrix(m, std::vector<int>(n, -1));
    int top = 0, bottom = m - 1, left = 0, right = n - 1;
    ListNode* cur = head;
    int filled = 0;
    int total = m * n;
    while (filled < total && cur) {
        for (int col = left; col <= right && cur; ++col) {
            matrix[top][col] = cur->val;
            cur = cur->next;
            ++filled;
        }
        ++top;
        for (int row = top; row <= bottom && cur; ++row) {
            matrix[row][right] = cur->val;
            cur = cur->next;
            ++filled;
        }
        --right;
        for (int col = right; col >= left && cur; --col) {
            matrix[bottom][col] = cur->val;
            cur = cur->next;
            ++filled;
        }
        --bottom;
        for (int row = bottom; row >= top && cur; --row) {
            matrix[row][left] = cur->val;
            cur = cur->next;
            ++filled;
        }
        ++left;
    }
    return matrix;
}

