int peopleAwareOfSecret(int n, int delay, int forget) {
    const int MOD = 1000000007;
    std::vector<long long> dp(n + 2, 0);
    dp[1] = 1;
    long long active = 0;
    for (int day = 2; day <= n; ++day) {
        if (day - delay >= 1) {
            active += dp[day - delay];
            if (active >= MOD) active -= MOD;
        }
        if (day - forget >= 1) {
            active -= dp[day - forget];
            if (active < 0) active += MOD;
        }
        dp[day] = active;
    }
    long long ans = 0;
    int start = std::max(1, n - forget + 1);
    for (int i = start; i <= n; ++i) {
        ans += dp[i];
        if (ans >= MOD) ans -= MOD;
    }
    return static_cast<int>(ans);
}

