long long maximumScore(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    int n = static_cast<int>(nums1.size());
    long long sum1 = 0, sum2 = 0;
    for (int i = 0; i < n; ++i) {
        sum1 += nums1[i];
        sum2 += nums2[i];
    }

    long long maxDiff = LLONG_MIN, curMax = 0;
    long long minDiff = LLONG_MAX, curMin = 0;

    for (int i = 0; i < n; ++i) {
        long long d = static_cast<long long>(nums2[i]) - static_cast<long long>(nums1[i]);

        curMax = std::max(d, curMax + d);
        maxDiff = std::max(maxDiff, curMax);

        curMin = std::min(d, curMin + d);
        minDiff = std::min(minDiff, curMin);
    }

    return std::max({sum1, sum2, sum1 + maxDiff, sum2 - minDiff});
}

#include <bits/stdc++.h>

int minimumScore(std::vector<int>& nums, std::vector<std::vector<int>>& edges) {
    int n = static_cast<int>(nums.size());
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    std::vector<int> parent(n, -1), depth(n, 0), tin(n), tout(n), subXor(n);
    int timer = 0;
    std::function<void(int,int)> dfs = [&](int u, int p) {
        parent[u] = p;
        tin[u] = ++timer;
        int cur = nums[u];
        for (int v : adj[u]) {
            if (v == p) continue;
            depth[v] = depth[u] + 1;
            dfs(v, u);
            cur ^= subXor[v];
        }
        subXor[u] = cur;
        tout[u] = ++timer;
    };
    dfs(0, -1);
    int totalXor = subXor[0];
    int ans = INT_MAX;

    auto isAncestor = [&](int a, int b) {
        return tin[a] <= tin[b] && tout[b] <= tout[a];
    };

    for (int a = 1; a < n; ++a) {
        for (int b = a + 1; b < n; ++b) {
            int x1, x2, x3;
            if (isAncestor(a, b)) {
                x1 = subXor[b];
                x2 = subXor[a] ^ subXor[b];
                x3 = totalXor ^ subXor[a];
            } else if (isAncestor(b, a)) {
                x1 = subXor[a];
                x2 = subXor[b] ^ subXor[a];
                x3 = totalXor ^ subXor[b];
            } else {
                x1 = subXor[a];
                x2 = subXor[b];
                x3 = totalXor ^ subXor[a] ^ subXor[b];
            }
            int mx = std::max({x1, x2, x3});
            int mn = std::min({x1, x2, x3});
            ans = std::min(ans, mx - mn);
            if (ans == 0) return 0;
        }
    }
    return ans;
}

