int latestTimeCatchTheBus(std::vector<int> buses, std::vector<int> passengers, int capacity) {
    std::sort(buses.begin(), buses.end());
    std::sort(passengers.begin(), passengers.end());
    std::unordered_set<int> passengerSet(passengers.begin(), passengers.end());

    size_t i = 0;
    int lastTaken = -1;
    int lastBusTime = -1;
    int lastBusCnt = 0;

    for (int bus : buses) {
        int cnt = 0;
        while (i < passengers.size() && passengers[i] <= bus && cnt < capacity) {
            lastTaken = passengers[i];
            ++i;
            ++cnt;
        }
        lastBusTime = bus;
        lastBusCnt = cnt;
    }

    int answer;
    if (lastBusCnt < capacity) {
        answer = lastBusTime;
    } else {
        answer = lastTaken - 1;
    }

    while (passengerSet.count(answer)) {
        --answer;
    }
    return answer;
}

