class SmallestInfiniteSet {
public:
    int next_ = 1;
    std::vector<int> heap;
    std::unordered_set<int> inHeap;
    void heapPush(int val) {
        heap.push_back(val);
        int i = (int)heap.size() - 1;
        while (i > 0) { int p=(i-1)>>1; if (heap[p]<=heap[i]) break; std::swap(heap[p],heap[i]); i=p; }
    }
    int heapPop() {
        int top = heap[0]; int last = heap.back(); heap.pop_back();
        if (!heap.empty()) {
            heap[0] = last; int i=0, n=(int)heap.size();
            while (true) {
                int l=i*2+1,r=l+1,s=i;
                if (l<n&&heap[l]<heap[s]) s=l;
                if (r<n&&heap[r]<heap[s]) s=r;
                if (s==i) break;
                std::swap(heap[i],heap[s]); i=s;
            }
        }
        return top;
    }
    int popSmallest() {
        if (!heap.empty()) { int val=heapPop(); inHeap.erase(val); return val; }
        return next_++;
    }
    void addBack(int num) {
        if (num < next_ && inHeap.find(num)==inHeap.end()) { heapPush(num); inHeap.insert(num); }
    }
};

