static const long long MOD = 1000000007LL;

long long modPow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int idealArrays(int n, int maxValue) {
    int limit = n + 20;
    std::vector<long long> fact(limit + 1), invFact(limit + 1);
    fact[0] = 1;
    for (int i = 1; i <= limit; ++i) fact[i] = fact[i - 1] * i % MOD;
    invFact[limit] = modPow(fact[limit], MOD - 2);
    for (int i = limit; i > 0; --i) invFact[i - 1] = invFact[i] * i % MOD;

    auto comb = [&](int a, int b) -> long long {
        if (b < 0 || b > a) return 0;
        return fact[a] * invFact[b] % MOD * invFact[a - b] % MOD;
    };

    std::vector<int> spf(maxValue + 1);
    for (int i = 2; i <= maxValue; ++i) {
        if (spf[i] == 0) {
            for (int j = i; j <= maxValue; j += i) {
                if (spf[j] == 0) spf[j] = i;
            }
        }
    }

    long long ans = 0;
    for (int v = 1; v <= maxValue; ++v) {
        int x = v;
        long long ways = 1;
        while (x > 1) {
            int p = spf[x];
            int cnt = 0;
            while (x % p == 0) {
                x /= p;
                ++cnt;
            }
            ways = ways * comb(cnt + n - 1, n - 1) % MOD;
        }
        ans = (ans + ways) % MOD;
    }
    return static_cast<int>(ans);
}

