int subarrayLength(const std::vector<int>& nums, int threshold) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return -1;
    std::vector<int> left(n);
    std::vector<int> st;
    st.reserve(n);
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && nums[st.back()] >= nums[i]) st.pop_back();
        left[i] = st.empty() ? -1 : st.back();
        st.push_back(i);
    }
    st.clear();
    int best = std::numeric_limits<int>::max();
    for (int i = n - 1; i >= 0; --i) {
        while (!st.empty() && nums[st.back()] >= nums[i]) st.pop_back();
        int right = st.empty() ? n : st.back();
        long long maxLen = static_cast<long long>(right) - left[i] - 1;
        long long need = static_cast<long long>(threshold) / nums[i] + 1;
        if (need <= maxLen) best = std::min(best, static_cast<int>(need));
        st.push_back(i);
    }
    return best == std::numeric_limits<int>::max() ? -1 : best;
}

