long long minSumSquareDiff(const std::vector<int>& nums1, const std::vector<int>& nums2, int k1, int k2) {
    const long long MOD = 1000000007LL;
    std::size_t n = nums1.size();
    std::priority_queue<long long> heap;
    for (std::size_t i = 0; i < n; ++i) {
        long long diff = std::llabs(static_cast<long long>(nums1[i]) - static_cast<long long>(nums2[i]));
        heap.push(diff);
    }
    long long ops = static_cast<long long>(k1) + static_cast<long long>(k2);
    while (ops-- > 0 && !heap.empty()) {
        long long top = heap.top();
        heap.pop();
        if (top == 0) {
            heap.push(0);
            break;
        }
        heap.push(top - 1);
    }
    long long ans = 0;
    while (!heap.empty()) {
        long long v = heap.top();
        heap.pop();
        ans = (ans + (v % MOD) * (v % MOD) % MOD) % MOD;
    }
    return ans;
}

