std::vector<int> smallestTrimmedNumbers(const std::vector<std::string>& nums, const std::vector<std::vector<int>>& queries) {
    int n = static_cast<int>(nums.size());
    int maxTrim = 0;
    for (const auto& q : queries) {
        maxTrim = std::max(maxTrim, q[1]);
    }
    std::vector<std::vector<std::string>> trimmed(n, std::vector<std::string>(maxTrim + 1));
    for (int i = 0; i < n; ++i) {
        const std::string& s = nums[i];
        int len = static_cast<int>(s.size());
        for (int t = 1; t <= maxTrim; ++t) {
            trimmed[i][t] = s.substr(len - t);
        }
    }
    std::vector<int> answers(queries.size());
    for (size_t qi = 0; qi < queries.size(); ++qi) {
        int k = queries[qi][0];
        int trim = queries[qi][1];
        std::vector<int> idxs(n);
        std::iota(idxs.begin(), idxs.end(), 0);
        std::sort(idxs.begin(), idxs.end(), [&](int a, int b) {
            const std::string& sa = trimmed[a][trim];
            const std::string& sb = trimmed[b][trim];
            if (sa.size() != sb.size()) return sa.size() < sb.size();
            if (sa != sb) return sa < sb;
            return a < b;
        });
        answers[qi] = idxs[k - 1];
    }
    return answers;
}

