int maxSum(const std::vector<int>& nums) {
    std::unordered_map<int, std::pair<int, int>> best;
    for (size_t i = 0; i < nums.size(); ++i) {
        int num = nums[i];
        int ds = 0;
        int x = num;
        while (x > 0) {
            ds += x % 10;
            x /= 10;
        }
        auto it = best.find(ds);
        if (it == best.end()) {
            best[ds] = std::make_pair(num, -1);
        } else {
            std::pair<int, int>& p = it->second;
            if (num > p.first) {
                p.second = p.first;
                p.first = num;
            } else if (num > p.second) {
                p.second = num;
            }
        }
    }
    int answer = -1;
    for (const auto& kv : best) {
        const std::pair<int, int>& p = kv.second;
        if (p.second != -1) {
            int cur = p.first + p.second;
            if (cur > answer) answer = cur;
        }
    }
    return answer;
}

