int shortestImpossibleSequence(const std::vector<int>& rolls, int k) {
    int n = static_cast<int>(rolls.size());
    std::vector<std::vector<int>> nxt(n + 1, std::vector<int>(k + 1, -1));
    std::vector<int> cur(k + 1, -1);
    for (int i = n - 1; i >= 0; --i) {
        cur[rolls[i]] = i;
        for (int v = 1; v <= k; ++v) {
            nxt[i][v] = cur[v];
        }
    }
    std::vector<char> visited(n + 1, 0);
    std::deque<std::pair<int, int>> q;
    q.emplace_back(0, 0);
    visited[0] = 1;

    while (!q.empty()) {
        auto front = q.front();
        q.pop_front();
        int state = front.first;
        int depth = front.second;
        for (int v = 1; v <= k; ++v) {
            int pos = nxt[state][v];
            if (pos == -1) {
                return depth + 1;
            }
            int nextState = pos + 1;
            if (!visited[nextState]) {
                visited[nextState] = 1;
                q.emplace_back(nextState, depth + 1);
            }
        }
    }
    return n + 1;
}

