    std::unordered_map<int, std::priority_queue<int, std::vector<int>, std::greater<int>>> numToHeap;
    void change(int index, int number) {
        idxToNum[index] = number;
        numToHeap[number].push(index);
    }
    int find(int number) {
        auto it = numToHeap.find(number);
        if (it == numToHeap.end()) return -1;
        auto& heap = it->second;
        while (!heap.empty()) {
            int top = heap.top();
            if (idxToNum.count(top) && idxToNum[top] == number) return top;
            heap.pop();
        }
        return -1;
    }
};

