long long countExcellentPairs(const std::vector<int>& nums, int k) {
    std::unordered_set<int> uniq(nums.begin(), nums.end());
    const int MAX_BITS = 60;
    std::vector<long long> cnt(MAX_BITS + 1, 0);
    for (int x : uniq) {
        int pc = __builtin_popcountll(static_cast<unsigned long long>(x));
        cnt[pc]++;
    }
    std::vector<long long> suffix(MAX_BITS + 2, 0);
    for (int i = MAX_BITS; i >= 0; --i) {
        suffix[i] = suffix[i + 1] + cnt[i];
    }
    long long ans = 0;
    for (int i = 0; i <= MAX_BITS; ++i) {
        if (cnt[i] == 0) continue;
        int need = k - i;
        if (need < 0) need = 0;
        if (need > MAX_BITS) continue;
        ans += cnt[i] * suffix[need];
    }
    return ans;
}

