class FoodRatings {
public:
    std::unordered_map<std::string,std::string> foodToCuisine;
    std::unordered_map<std::string,int> foodToRating;
    struct Heap {
        std::vector<std::pair<int,std::string>> data;
        static bool cmp(const std::pair<int,std::string>& a, const std::pair<int,std::string>& b) {
            return a.first > b.first || (a.first == b.first && a.second < b.second);
        }
        std::pair<int,std::string>& peek() { return data[0]; }
        void push(const std::pair<int,std::string>& x) {
            data.push_back(x);
            size_t i = data.size()-1;
            while (i > 0) { size_t p=(i-1)>>1; if (cmp(data[p],data[i])) break; std::swap(data[p],data[i]); i=p; }
        }
        void pop() {
            std::pair<int,std::string> last = data.back(); data.pop_back();
            if (!data.empty()) {
                data[0] = last;
                size_t i = 0;
                while (true) {
                    size_t l=i*2+1,r=i*2+2,best=i;
                    if (l<data.size() && !cmp(data[best],data[l])) best=l;
                    if (r<data.size() && !cmp(data[best],data[r])) best=r;
                    if (best==i) break;
                    std::swap(data[i],data[best]); i=best;
                }
            }
        }
    };
    std::unordered_map<std::string, Heap> cuisineHeap;
    FoodRatings(std::vector<std::string>& foods, std::vector<int>& ratings, std::vector<std::string>& cuisines) {
        for (size_t i = 0; i < foods.size(); ++i) {
            foodToCuisine[foods[i]] = cuisines[i];
            foodToRating[foods[i]] = ratings[i];
            cuisineHeap[cuisines[i]].push({ratings[i], foods[i]});
        }
    }
    void changeRating(std::string food, int newRating) {
        std::string c = foodToCuisine[food];
        foodToRating[food] = newRating;
        cuisineHeap[c].push({newRating, food});
    }
    std::string highestRated(std::string cuisine) {
        auto& heap = cuisineHeap[cuisine];
        while (true) {
            auto& top = heap.peek();
            if (foodToRating[top.second] == top.first) break;
            heap.pop();
        }
        return heap.peek().second;
    }
};

