int findClosestNode(const std::vector<int>& edges, int node1, int node2) {
    int n = static_cast<int>(edges.size());
    const int INF = std::numeric_limits<int>::max();
    std::vector<int> dist1(n, INF);
    std::vector<int> dist2(n, INF);
    int cur = node1;
    int d = 0;
    while (cur != -1 && dist1[cur] == INF) {
        dist1[cur] = d++;
        cur = edges[cur];
    }
    cur = node2;
    d = 0;
    while (cur != -1 && dist2[cur] == INF) {
        dist2[cur] = d++;
        cur = edges[cur];
    }
    int bestNode = -1;
    int bestDist = INF;
    for (int i = 0; i < n; ++i) {
        if (dist1[i] != INF && dist2[i] != INF) {
            int curMax = std::max(dist1[i], dist2[i]);
            if (curMax < bestDist || (curMax == bestDist && i < bestNode)) {
                bestDist = curMax;
                bestNode = i;
            }
        }
    }
    return bestNode;
}

