int longestCycle(const std::vector<int>& edges) {
    int n = static_cast<int>(edges.size());
    std::vector<bool> visited(n, false);
    int best = -1;

    for (int i = 0; i < n; ++i) {
        if (visited[i]) continue;

        int cur = i;
        int step = 0;
        std::unordered_map<int, int> localStep;

        while (cur != -1 && !visited[cur]) {
            visited[cur] = true;
            localStep[cur] = step;
            cur = edges[cur];
            ++step;
        }

        if (cur != -1) {
            auto it = localStep.find(cur);
            if (it != localStep.end()) {
                int cycleLen = step - it->second;
                if (cycleLen > best) best = cycleLen;
            }
        }
    }
    return best;
}

