std::vector<std::vector<int>> mergeSimilarItems(const std::vector<std::vector<int>>& items1, const std::vector<std::vector<int>>& items2) {
    std::unordered_map<int, long long> weightMap;
    for (const auto& pair : items1) {
        int value = pair[0];
        int weight = pair[1];
        weightMap[value] += weight;
    }
    for (const auto& pair : items2) {
        int value = pair[0];
        int weight = pair[1];
        weightMap[value] += weight;
    }
    std::vector<std::vector<int>> merged;
    merged.reserve(weightMap.size());
    for (const auto& entry : weightMap) {
        merged.push_back({entry.first, static_cast<int>(entry.second)});
    }
    std::sort(merged.begin(), merged.end(), [](const std::vector<int>& a, const std::vector<int>& b) {
        return a[0] < b[0];
    });
    return merged;
}

