int reachableNodes(int n, const std::vector<std::vector<int>>& edges, const std::vector<int>& restricted) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    std::unordered_set<int> restrictedSet(restricted.begin(), restricted.end());
    std::vector<char> visited(n, false);
    std::vector<int> stack;
    stack.push_back(0);
    visited[0] = true;
    int reachableCount = 0;

    while (!stack.empty()) {
        int node = stack.back();
        stack.pop_back();
        ++reachableCount;
        for (int nb : adj[node]) {
            if (!visited[nb] && restrictedSet.find(nb) == restrictedSet.end()) {
                visited[nb] = true;
                stack.push_back(nb);
            }
        }
    }
    return reachableCount;
}

