int longestIdealString(const std::string& s, int k) {
    std::vector<int> dp(26, 0);
    for (size_t i = 0; i < s.size(); ++i) {
        int cur = s[i] - 'a';
        int best = 1;
        for (int j = 0; j < 26; ++j) {
            if (std::abs(j - cur) <= k) {
                if (dp[j] + 1 > best) best = dp[j] + 1;
            }
        }
        if (best > dp[cur]) dp[cur] = best;
    }
    int ans = 0;
    for (int v : dp) if (v > ans) ans = v;
    return ans;
}

#include <bits/stdc++.h>

int countSpecialNumbers(int n) {
    std::string s = std::to_string(n);
    int len = static_cast<int>(s.size());
    auto perm = [](int m, int k) -> long long {
        long long res = 1;
        for (int i = 0; i < k; ++i) {
            res *= (m - i);
        }
        return res;
    };
    long long ans = 0;
    for (int l = 1; l < len; ++l) {
        ans += 9LL * perm(9, l - 1);
    }
    std::vector<bool> used(10, false);
    for (int i = 0; i < len; ++i) {
        int cur = s[i] - '0';
        for (int d = (i == 0 ? 1 : 0); d < cur; ++d) {
            if (used[d]) continue;
            ans += perm(10 - i - 1, len - i - 1);
        }
        if (used[cur]) {
            return static_cast<int>(ans);
        }
        used[cur] = true;
    }
    ans += 1;
    return static_cast<int>(ans);
}

