std::string constructSmallestNumber(const std::string& pattern) {
    int n = static_cast<int>(pattern.size());
    std::vector<int> stack;
    std::string result;
    for (int i = 0; i <= n; ++i) {
        stack.push_back(i + 1);
        if (i == n || pattern[i] == 'I') {
            while (!stack.empty()) {
                int val = stack.back();
                stack.pop_back();
                result += std::to_string(val);
            }
        }
    }
    return result;
}

