std::string largestPalindromic(const std::string& num) {
    int cnt[10] = {0};
    for (char ch : num) {
        cnt[ch - '0']++;
    }

    std::string left;
    for (int d = 9; d >= 1; --d) {
        int pair = cnt[d] / 2;
        if (pair > 0) {
            left.append(pair, static_cast<char>('0' + d));
            cnt[d] -= pair * 2;
        }
    }

    if (!left.empty()) {
        int pair0 = cnt[0] / 2;
        if (pair0 > 0) {
            left.append(pair0, '0');
            cnt[0] -= pair0 * 2;
        }
    }

    std::string middle;
    for (int d = 9; d >= 0; --d) {
        if (cnt[d] > 0) {
            middle = std::string(1, static_cast<char>('0' + d));
            break;
        }
    }

    if (left.empty() && middle.empty()) return "0";
    if (left.empty()) return middle;

    std::string right = left;
    std::reverse(right.begin(), right.end());
    return left + middle + right;
}

