int minRecolors(const std::string& blocks, int k) {
    int n = static_cast<int>(blocks.size());
    if (k == 0) return 0;
    if (k > n) return 0;

    int whiteInWindow = 0;
    for (int i = 0; i < k; ++i) {
        if (blocks[i] == 'W') ++whiteInWindow;
    }
    int minWhite = whiteInWindow;

    for (int i = k; i < n; ++i) {
        if (blocks[i - k] == 'W') --whiteInWindow;
        if (blocks[i] == 'W') ++whiteInWindow;
        if (whiteInWindow < minWhite) minWhite = whiteInWindow;
    }
    return minWhite;
}

#include <bits/stdc++.h>

long long kthLargestSum(const std::vector<int>& nums, int k) {
    long long base = 0;
    std::vector<long long> absVals;
    absVals.reserve(nums.size());
    for (int x : nums) {
        if (x > 0) base += x;
        absVals.push_back(std::llabs(static_cast<long long>(x)));
    }
    std::sort(absVals.begin(), absVals.end());
    if (k == 1) return base;
    using Node = std::pair<long long, int>;
    std::priority_queue<Node, std::vector<Node>, std::greater<Node>> pq;
    if (!absVals.empty()) pq.emplace(absVals[0], 0);
    long long reduction = 0;
    int count = 1;
    while (count < k && !pq.empty()) {
        Node topNode = pq.top();
        pq.pop();
        ++count;
        long long cur = topNode.first;
        int idx = topNode.second;
        reduction = cur;
        if (idx + 1 < static_cast<int>(absVals.size())) {
            long long sum1 = cur - absVals[idx] + absVals[idx + 1];
            pq.emplace(sum1, idx + 1);
            long long sum2 = cur + absVals[idx + 1];
            pq.emplace(sum2, idx + 1);
        }
    }
    return base - reduction;
}

