struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

int amountOfTime(TreeNode* root, int start) {
    std::unordered_map<int, std::vector<int>> adj;

    std::function<void(TreeNode*)> dfs = [&](TreeNode* node) {
        if (!node) return;
        if (adj.find(node->val) == adj.end()) adj[node->val] = std::vector<int>();
        if (node->left) {
            if (adj.find(node->left->val) == adj.end()) adj[node->left->val] = std::vector<int>();
            adj[node->val].push_back(node->left->val);
            adj[node->left->val].push_back(node->val);
            dfs(node->left);
        }
        if (node->right) {
            if (adj.find(node->right->val) == adj.end()) adj[node->right->val] = std::vector<int>();
            adj[node->val].push_back(node->right->val);
            adj[node->right->val].push_back(node->val);
            dfs(node->right);
        }
    };
    dfs(root);

    std::queue<int> q;
    std::unordered_set<int> visited;
    q.push(start);
    visited.insert(start);
    int minutes = -1;
    while (!q.empty()) {
        int size = q.size();
        ++minutes;
        for (int i = 0; i < size; ++i) {
            int cur = q.front();
            q.pop();
            auto it = adj.find(cur);
            if (it != adj.end()) {
                for (int nb : it->second) {
                    if (visited.find(nb) == visited.end()) {
                        visited.insert(nb);
                        q.push(nb);
                    }
                }
            }
        }
    }
    return minutes;
}

