std::vector<int> longestSubsequenceWithLimitedSum(const std::vector<int>& nums, const std::vector<long long>& queries) {
    std::vector<int> sorted(nums);
    std::sort(sorted.begin(), sorted.end());

    std::vector<long long> pref(sorted.size());
    for (size_t i = 0; i < sorted.size(); ++i) {
        pref[i] = (i ? pref[i - 1] : 0) + sorted[i];
    }

    std::vector<int> answer;
    answer.reserve(queries.size());

    for (long long q : queries) {
        int lo = 0;
        int hi = static_cast<int>(sorted.size()) - 1;
        int best = -1;
        while (lo <= hi) {
            int mid = (lo + hi) >> 1;
            if (pref[mid] <= q) {
                best = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        answer.push_back(best + 1);
    }

    return answer;
}

#include <bits/stdc++.h>

std::vector<std::vector<int>> buildMatrix(int k, const std::vector<std::vector<int>>& rowConditions, const std::vector<std::vector<int>>& colConditions) {
    auto dfsTopo = [&](const std::vector<std::vector<int>>& edges) -> std::vector<int> {
        std::vector<std::vector<int>> adj(k + 1);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
        }
        std::vector<int> state(k + 1, 0); // 0=unvisited,1=visiting,2=visited
        std::vector<int> order;
        std::function<bool(int)> dfs = [&](int u) -> bool {
            state[u] = 1;
            for (int v : adj[u]) {
                if (state[v] == 1) return false; // cycle
                if (state[v] == 0 && !dfs(v)) return false;
            }
            state[u] = 2;
            order.push_back(u);
            return true;
        };
        for (int i = 1; i <= k; ++i) {
            if (state[i] == 0) {
                if (!dfs(i)) return {};
            }
        }
        std::reverse(order.begin(), order.end());
        return order;
    };

    std::vector<int> rowOrder = dfsTopo(rowConditions);
    std::vector<int> colOrder = dfsTopo(colConditions);
    if (rowOrder.empty() || colOrder.empty()) return {};

    std::vector<int> rowPos(k + 1);
    std::vector<int> colPos(k + 1);
    for (int i = 0; i < k; ++i) rowPos[rowOrder[i]] = i;
    for (int i = 0; i < k; ++i) colPos[colOrder[i]] = i;

    std::vector<std::vector<int>> ans(k, std::vector<int>(k, 0));
    for (int v = 1; v <= k; ++v) {
        ans[rowPos[v]][colPos[v]] = v;
    }
    return ans;
}

