int maxRowsCovered(const std::vector<std::vector<int>>& matrix, int numSelect) {
    int m = static_cast<int>(matrix.size());
    int n = static_cast<int>(matrix[0].size());
    if (numSelect > n) numSelect = n;
    if (n <= 20) {
        int N = 1 << n;
        std::vector<int> freq(N, 0);
        for (int i = 0; i < m; ++i) {
            int mask = 0;
            for (int j = 0; j < n; ++j) {
                if (matrix[i][j] == 1) mask |= (1 << j);
            }
            ++freq[mask];
        }
        for (int i = 0; i < n; ++i) {
            for (int mask = 0; mask < N; ++mask) {
                if (mask & (1 << i)) {
                    freq[mask] += freq[mask ^ (1 << i)];
                }
            }
        }
        int best = 0;
        for (int mask = 0; mask < N; ++mask) {
            if (__builtin_popcount(mask) == numSelect) {
                best = std::max(best, freq[mask]);
            }
        }
        return best;
    } else {
        std::vector<unsigned long long> rowMasks(m);
        for (int i = 0; i < m; ++i) {
            unsigned long long mask = 0;
            for (int j = 0; j < n; ++j) {
                if (matrix[i][j] == 1) mask |= (1ULL << j);
            }
            rowMasks[i] = mask;
        }
        int best = 0;
        std::function<void(int, unsigned long long, int)> dfs = [&](int start, unsigned long long chosenMask, int chosenCnt) {
            if (chosenCnt == numSelect) {
                int covered = 0;
                for (auto rm : rowMasks) {
                    if ((rm & ~chosenMask) == 0) ++covered;
                }
                best = std::max(best, covered);
                return;
            }
            for (int col = start; col < n; ++col) {
                dfs(col + 1, chosenMask | (1ULL << col), chosenCnt + 1);
            }
        };
        dfs(0, 0ULL, 0);
        return best;
    }
}

#include <bits/stdc++.h>
#include <vector>
#include <deque>
#include <algorithm>

int maxRobots(const std::vector<long long>& chargeTimes, const std::vector<long long>& runningCosts, long long budget) {
    const std::size_t n = chargeTimes.size();
    std::size_t left = 0;
    long long sumRun = 0;
    int best = 0;
    std::deque<std::size_t> dq; // stores indices, decreasing chargeTimes

    for (std::size_t right = 0; right < n; ++right) {
        sumRun += runningCosts[right];

        while (!dq.empty() && chargeTimes[right] >= chargeTimes[dq.back()]) {
            dq.pop_back();
        }
        dq.push_back(right);

        while (left <= right) {
            long long maxCharge = chargeTimes[dq.front()];
            long long windowSize = static_cast<long long>(right - left + 1);
            long long cost = maxCharge + windowSize * sumRun;
            if (cost <= budget) {
                break;
            }
            if (dq.front() == left) {
                dq.pop_front();
            }
            sumRun -= runningCosts[left];
            ++left;
        }

        best = std::max(best, static_cast<int>(right - left + 1));
    }
    return best;
}

#include <bits/stdc++.h>
const int MOD = 1000000007;

long long modPow(long long base, long long exp) {
    long long res = 1 % MOD;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

int numberOfWays(int startPos, int endPos, int k) {
    int d = std::abs(endPos - startPos);
    if (d > k || ((k - d) & 1)) return 0;
    int r = (k + d) / 2;
    long long fact = 1;
    long long factR = 1, factKR = 1;
    for (int i = 1; i <= k; ++i) {
        fact = fact * i % MOD;
        if (i == r) factR = fact;
        if (i == k - r) factKR = fact;
    }
    long long invFactR = modPow(factR, MOD - 2);
    long long invFactKR = modPow(factKR, MOD - 2);
    long long ans = fact * invFactR % MOD * invFactKR % MOD;
    return static_cast<int>(ans);
}

