int longestNiceSubarray(const std::vector<int>& nums) {
    int left = 0;
    int curMask = 0;
    int best = 0;
    for (int right = 0; right < static_cast<int>(nums.size()); ++right) {
        while ((curMask & nums[right]) != 0) {
            curMask ^= nums[left];
            ++left;
        }
        curMask |= nums[right];
        int len = right - left + 1;
        if (len > best) best = len;
    }
    return best;
}

