int mostBooked(int n, std::vector<std::vector<int>>& meetings) {
    std::sort(meetings.begin(), meetings.end(),
              [](const std::vector<int>& a, const std::vector<int>& b) {
                  return a[0] < b[0];
              });

    std::priority_queue<int, std::vector<int>, std::greater<int>> free;
    for (int i = 0; i < n; ++i) free.push(i);

    using Pair = std::pair<long long, int>;
    std::priority_queue<Pair, std::vector<Pair>, std::greater<Pair>> busy;

    std::vector<int> cnt(n, 0);

    for (const auto& meeting : meetings) {
        long long start = meeting[0];
        long long end = meeting[1];

        while (!busy.empty() && busy.top().first <= start) {
            int room = busy.top().second;
            busy.pop();
            free.push(room);
        }

        if (!free.empty()) {
            int room = free.top();
            free.pop();
            ++cnt[room];
            busy.emplace(end, room);
        } else {
            auto top = busy.top();
            busy.pop();
            int room = top.second;
            long long finish = top.first;
            ++cnt[room];
            long long duration = end - start;
            busy.emplace(finish + duration, room);
        }
    }

    int best = 0;
    for (int i = 1; i < n; ++i) {
        if (cnt[i] > cnt[best]) best = i;
    }
    return best;
}

