int gcd(int a, int b) {
    if (b == 0) return a;
    return gcd(b, a % b);
}

bool isGoodArray(const std::vector<int>& nums) {
    int result = nums[0];
    for (size_t i = 1; i < nums.size(); ++i) {
        result = gcd(result, nums[i]);
    }
    return result == 1;
}

