std::string minRemoveToMakeValid(const std::string& s) {
    std::vector<int> stack;
    std::unordered_set<int> removeSet;
    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        if (s[i] == '(') {
            stack.push_back(i);
        } else if (s[i] == ')') {
            if (stack.empty()) {
                removeSet.insert(i);
            } else {
                stack.pop_back();
            }
        }
    }
    while (!stack.empty()) {
        removeSet.insert(stack.back());
        stack.pop_back();
    }
    std::string result;
