int tilingRectangle(int n, int m) {
    if (n == m) return 1;
    if (n > m) std::swap(n, m);
    std::vector<int> heights(m, 0);
    int best = n * m;
    std::function<void(int)> dfs = [&](int used) {
        if (used >= best) return;
        int idx = -1, minH = INT_MAX;
        for (int i = 0; i < m; ++i) {
            if (heights[i] < minH) {
                minH = heights[i];
                idx = i;
            }
        }
        if (minH == n) {
            best = used;
            return;
        }
        int maxSize = n - minH;
        int width = 0;
        while (idx + width < m && heights[idx + width] == minH && width < maxSize) ++width;
        for (int size = width; size >= 1; --size) {
            for (int k = 0; k < size; ++k) heights[idx + k] += size;
            dfs(used + 1);
            for (int k = 0; k < size; ++k) heights[idx + k] -= size;
        }
    };
    dfs(0);
    return best;
}

