long long jobScheduling(const std::vector<int>& startTime, const std::vector<int>& endTime, const std::vector<int>& profit) {
    struct Job { int start; int end; int profit; };
    size_t n = startTime.size();
    if (n == 0) return 0;
    std::vector<Job> jobs;
    jobs.reserve(n);
    for (size_t i = 0; i < n; ++i) {
        jobs.push_back({startTime[i], endTime[i], profit[i]});
    }
    std::sort(jobs.begin(), jobs.end(), [](const Job& a, const Job& b) { return a.end < b.end; });
    std::vector<long long> dp(jobs.size(), 0);
    dp[0] = jobs[0].profit;
    for (size_t i = 1; i < jobs.size(); ++i) {
        long long maxProfit = jobs[i].profit;
        for (int j = static_cast<int>(i) - 1; j >= 0; --j) {
            if (jobs[j].end <= jobs[i].start) {
                maxProfit = std::max(maxProfit, dp[j] + jobs[i].profit);
                break;
            }
        }
        dp[i] = std::max(dp[i - 1], maxProfit);
    }
    return dp.back();
}

