int closedIsland(std::vector<std::vector<int>>& grid) {
    const std::vector<std::pair<int, int>> directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    std::function<void(int, int)> dfs = [&](int row, int col) {
        if (row < 0 || row >= static_cast<int>(grid.size()) || col < 0 || col >= static_cast<int>(grid[0].size())) return;
        if (grid[row][col] == 1) return;
        grid[row][col] = 1;
        for (const auto& d : directions) {
            dfs(row + d.first, col + d.second);
        }
    };
    for (int i = 0; i < static_cast<int>(grid.size()); ++i) {
        dfs(i, 0);
        dfs(i, static_cast<int>(grid[0].size()) - 1);
    }
    for (int j = 0; j < static_cast<int>(grid[0].size()); ++j) {
        dfs(0, j);
        dfs(static_cast<int>(grid.size()) - 1, j);
    }
    int count = 0;
    for (int i = 1; i < static_cast<int>(grid.size()) - 1; ++i) {
        for (int j = 1; j < static_cast<int>(grid[0].size()) - 1; ++j) {
            if (grid[i][j] == 0) {
                ++count;
                dfs(i, j);
            }
        }
    }
    return count;
}

