std::vector<std::vector<int>> reconstructMatrix(int upper, int lower, const std::vector<int>& colsum) {
    size_t n = colsum.size();
    std::vector<std::vector<int>> matrix(2, std::vector<int>(n, 0));
    int upperRemain = upper;
    int lowerRemain = lower;

    for (size_t i = 0; i < n; ++i) {
        if (colsum[i] == 2) {
            matrix[0][i] = 1;
            matrix[1][i] = 1;
            --upperRemain;
            --lowerRemain;
            if (upperRemain < 0 || lowerRemain < 0) {
                return {};
            }
        }
    }

    for (size_t i = 0; i < n; ++i) {
        if (colsum[i] == 1) {
            if (upperRemain > 0) {
                matrix[0][i] = 1;
                --upperRemain;
            } else if (lowerRemain > 0) {
                matrix[1][i] = 1;
                --lowerRemain;
            } else {
                return {};
            }
        }
    }

    if (upperRemain != 0 || lowerRemain != 0) {
        return {};
    }
    return matrix;
}

