int maxScoreWords(const std::vector<std::string>& words, const std::vector<char>& letters, const std::vector<int>& score) {
    std::vector<int> letterCount(26, 0);
    for (char letter : letters) {
        letterCount[letter - 'a']++;
    }

    std::vector<std::vector<int>> wordCounts;
    wordCounts.reserve(words.size());
    for (const std::string& word : words) {
        std::vector<int> count(26, 0);
        for (char letter : word) {
            count[letter - 'a']++;
        }
        wordCounts.push_back(std::move(count));
    }

    int maxScore = 0;
    int n = static_cast<int>(words.size());
    for (int mask = 0; mask < (1 << n); ++mask) {
        int currentScore = 0;
        std::vector<int> currentCount(26, 0);
        bool invalid = false;
        for (int i = 0; i < n; ++i) {
            if ((mask & (1 << i)) != 0) {
                const std::vector<int>& wordCount = wordCounts[i];
                for (int j = 0; j < 26; ++j) {
                    if (currentCount[j] + wordCount[j] > letterCount[j]) {
                        currentScore = -1;
                        invalid = true;
                        break;
                    }
                }
                if (invalid) break;
                for (int j = 0; j < 26; ++j) {
                    currentCount[j] += wordCount[j];
                    currentScore += score[j] * wordCount[j];
                }
            }
        }
        if (currentScore > maxScore) {
            maxScore = currentScore;
        }
    }
    return maxScore;
}

