int mostFrequentEvenElement(const std::vector<int>& nums) {
    std::unordered_map<int, int> frequency;
    for (size_t i = 0; i < nums.size(); ++i) {
        if (nums[i] % 2 == 0) {
            if (frequency.find(nums[i]) != frequency.end()) {
                frequency[nums[i]]++;
            } else {
                frequency[nums[i]] = 1;
            }
        }
    }

    int maxFrequency = 0;
    int smallestElement = -1;

    for (const auto& kv : frequency) {
        int key = kv.first;
        int freq = kv.second;
        if (freq > maxFrequency) {
            maxFrequency = freq;
            smallestElement = key;
        } else if (freq == maxFrequency && key < smallestElement) {
            smallestElement = key;
        }
    }

    return smallestElement == -1 ? -1 : smallestElement;
}

