int countDaysTogether(const std::string& arriveAlice, const std::string& leaveAlice, const std::string& arriveBob, const std::string& leaveBob) {
    auto getTotalDays = [](const std::string& date) -> int {
        const std::vector<int> daysPerMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        int month = std::stoi(date.substr(0, 2)) - 1;
        int day = std::stoi(date.substr(3));
        int totalDays = 0;
        for (int i = 0; i < month; ++i) {
            totalDays += daysPerMonth[i];
        }
        totalDays += day;
        return totalDays;
    };

    int arriveAliceDays = getTotalDays(arriveAlice);
    int leaveAliceDays = getTotalDays(leaveAlice);
    int arriveBobDays = getTotalDays(arriveBob);
    int leaveBobDays = getTotalDays(leaveBob);
    int maxArriveDays = std::max(arriveAliceDays, arriveBobDays);
    int minLeaveDays = std::min(leaveAliceDays, leaveBobDays);
    int daysTogether = std::max(0, minLeaveDays - maxArriveDays + 1);
    return daysTogether;
}

