std::vector<long long> sumPrefixScores(const std::vector<std::string>& words) {
    struct Node {
        int child[26];
        int cnt;
        Node() : cnt(0) {
            std::fill(std::begin(child), std::end(child), -1);
        }
    };
    std::vector<Node> trie;
    trie.emplace_back(); // root at index 0

    // Build trie and count prefixes
    for (const std::string& w : words) {
        int node = 0;
        for (char ch : w) {
            int idx = ch - 'a';
            if (trie[node].child[idx] == -1) {
                trie[node].child[idx] = static_cast<int>(trie.size());
                trie.emplace_back();
            }
            node = trie[node].child[idx];
            ++trie[node].cnt;
        }
    }

    // Compute answers
    std::vector<long long> answer;
    answer.reserve(words.size());
    for (const std::string& w : words) {
        long long sum = 0;
        int node = 0;
        for (char ch : w) {
            int idx = ch - 'a';
            node = trie[node].child[idx];
            sum += trie[node].cnt;
        }
        answer.push_back(sum);
    }
    return answer;
}

