std::vector<long long> maximumSegmentSum(const std::vector<int>& nums, const std::vector<int>& removeQueries) {
    int n = nums.size();
    std::vector<int> parent(n, -1);
    std::vector<long long> segSum(n, 0);
    std::vector<char> added(n, 0);
    std::vector<long long> answer(n);
    long long curMax = 0;

    auto find = [&](int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    auto union_sets = [&](int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return segSum[ra];
        parent[rb] = ra;
        segSum[ra] += segSum[rb];
        return segSum[ra];
    };

    for (int i = n - 1; i >= 0; --i) {
        answer[i] = curMax;
        int idx = removeQueries[i];
        added[idx] = 1;
        parent[idx] = idx;
        segSum[idx] = nums[idx];

        if (idx > 0 && added[idx - 1]) {
            curMax = std::max(curMax, union_sets(idx, idx - 1));
        }
        if (idx + 1 < n && added[idx + 1]) {
            curMax = std::max(curMax, union_sets(idx, idx + 1));
        }
        curMax = std::max(curMax, segSum[find(idx)]);
    }

    return answer;
}

