int longestSubarray(const std::vector<int>& nums) {
    int maxAnd = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        int cur = nums[i];
        maxAnd = std::max(maxAnd, cur);
        for (size_t j = i + 1; j < nums.size(); ++j) {
            cur &= nums[j];
            maxAnd = std::max(maxAnd, cur);
        }
    }
    int maxLength = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        int cur = nums[i];
        if (cur == maxAnd) maxLength = std::max(maxLength, 1);
        for (size_t j = i + 1; j < nums.size(); ++j) {
            cur &= nums[j];
            if (cur == maxAnd) {
                maxLength = std::max(maxLength, static_cast<int>(j - i + 1));
            } else if (cur < maxAnd) {
                break;
            }
        }
    }
    return maxLength;
}

