bool canEqualizeWord(const std::string& word) {
    std::unordered_map<char, int> frequencyMap;
    for (char ch : word) {
        ++frequencyMap[ch];
    }

    std::unordered_map<int, int> freqCount;
    for (const auto& p : frequencyMap) {
        ++freqCount[p.second];
    }

    if (freqCount.size() == 1) {
        int freq = freqCount.begin()->first;
        int distinctChars = static_cast<int>(frequencyMap.size());
        return (freq == 1) || (distinctChars == 1);
    }

    if (freqCount.size() != 2) {
        return false;
    }

    auto it = freqCount.begin();
    int freq1 = it->first;
    int count1 = it->second;
    ++it;
    int freq2 = it->first;
    int count2 = it->second;

    if (freq1 > freq2) {
        std::swap(freq1, freq2);
        std::swap(count1, count2);
    }

    if (freq2 - freq1 == 1 && count2 == 1) {
        return true;
    }
    if (freq1 == 1 && count1 == 1) {
        return true;
    }

    return false;
}

