long long numberOfGoodPaths(const std::vector<int>& vals, const std::vector<std::vector<int>>& edges) {
    int n = static_cast<int>(vals.size());
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        adj[e[0]].push_back(e[1]);
        adj[e[1]].push_back(e[0]);
    }

    std::vector<int> parent(n);
    std::vector<int> sz(n, 1);
    for (int i = 0; i < n; ++i) parent[i] = i;

    std::function<int(int)> findRoot = [&](int x) -> int {
        if (parent[x] != x) parent[x] = findRoot(parent[x]);
        return parent[x];
    };

    auto unite = [&](int a, int b) {
        int ra = findRoot(a);
        int rb = findRoot(b);
        if (ra == rb) return;
        if (sz[ra] < sz[rb]) std::swap(ra, rb);
        parent[rb] = ra;
        sz[ra] += sz[rb];
    };

    std::vector<int> order(n);
    std::iota(order.begin(), order.end(), 0);
    std::sort(order.begin(), order.end(),
        [&](int a, int b) { return vals[a] < vals[b]; });

    long long ans = n;
    size_t i = 0;
    while (i < order.size()) {
        int curVal = vals[order[i]];
        size_t j = i;
        while (j < order.size() && vals[order[j]] == curVal) ++j;

        for (size_t k = i; k < j; ++k) {
            int node = order[k];
            for (int nb : adj[node]) {
                if (vals[nb] <= curVal) unite(node, nb);
            }
        }

        std::unordered_map<int, long long> compCnt;
        for (size_t k = i; k < j; ++k) {
            int root = findRoot(order[k]);
            ++compCnt[root];
        }
        for (const auto& p : compCnt) {
            long long cnt = p.second;
            ans += cnt * (cnt - 1) / 2;
        }

        i = j;
    }
    return ans;
}

