static const long long MOD = 1000000007LL;

long long modPow(long long base, long long exp) {
    long long result = 1 % MOD;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

std::vector<long long> productQueries(int n, const std::vector<std::vector<int>>& queries) {
    std::vector<int> exponents;
    for (int i = 0; n > 0; ++i) {
        if (n & 1) exponents.push_back(i);
        n >>= 1;
    }
    int m = exponents.size();
    std::vector<long long> prefix(m + 1, 0);
    for (int i = 0; i < m; ++i) {
        prefix[i + 1] = prefix[i] + exponents[i];
    }
    std::vector<long long> answers;
    answers.reserve(queries.size());
    for (const auto& q : queries) {
        int l = q[0];
        int r = q[1];
        long long sumExp = prefix[r + 1] - prefix[l];
        answers.push_back(modPow(2, sumExp));
    }
    return answers;
}

