int componentValue(const std::vector<int>& nums, const std::vector<std::vector<int>>& edges) {
    int n = static_cast<int>(nums.size());
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        adj[e[0]].push_back(e[1]);
        adj[e[1]].push_back(e[0]);
    }
    long long total = std::accumulate(nums.begin(), nums.end(), 0LL);
    if (total == 0) {
        return n - 1;
    }
    int best = 0;
    std::vector<long long> divisors;
    for (long long d = 1; d * d <= total; ++d) {
        if (total % d == 0) {
            divisors.push_back(d);
            if (d * d != total) divisors.push_back(total / d);
        }
    }
    for (long long target : divisors) {
        if (target == total) continue;
        bool ok = true;
        int components = 0;
        std::function<long long(int,int)> dfs = [&](int u, int parent) -> long long {
            long long sum = nums[u];
            for (int v : adj[u]) {
                if (v == parent) continue;
                long long child = dfs(v, u);
                sum += child;
            }
            if (sum > target) {
                ok = false;
                return 0;
            }
            if (sum == target) {
                ++components;
                return 0;
            }
            return sum;
        };
        dfs(0, -1);
        if (ok && components == total / target) {
            best = std::max(best, components - 1);
        }
    }
    return best;
}

