long long minCost(std::vector<long long> nums, const std::vector<long long>& cost) {
    size_t n = nums.size();
    std::vector<std::pair<long long, long long>> pairs;
    pairs.reserve(n);
    for (size_t i = 0; i < n; ++i) {
        pairs.emplace_back(nums[i], cost[i]);
    }
    std::sort(pairs.begin(), pairs.end(),
              [](const std::pair<long long, long long>& a,
                 const std::pair<long long, long long>& b) {
                  return a.first < b.first;
              });
    long long totalWeight = 0;
    for (const auto& p : pairs) {
        totalWeight += p.second;
    }
    long long cumulative = 0;
    long long median = 0;
    for (const auto& p : pairs) {
        cumulative += p.second;
        if (cumulative * 2 >= totalWeight) {
            median = p.first;
            break;
        }
    }
    long long totalCost = 0;
    for (const auto& p : pairs) {
        totalCost += std::llabs(p.first - median) * p.second;
    }
    return totalCost;
}

