int64_t pathsDivisible(const std::vector<std::vector<int>>& grid, int k) {
    const int MOD = 1000000007;
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    std::vector<std::vector<int>> dpPrev(n, std::vector<int>(k, 0));
    for (int i = 0; i < m; ++i) {
        std::vector<std::vector<int>> dpCurr(n, std::vector<int>(k, 0));
        for (int j = 0; j < n; ++j) {
            int valMod = grid[i][j] % k;
            if (valMod < 0) valMod += k;
            std::vector<int>& cur = dpCurr[j];
            if (i == 0 && j == 0) {
                cur[valMod] = 1;
                continue;
            }
            if (i > 0) {
                const std::vector<int>& top = dpPrev[j];
                for (int r = 0; r < k; ++r) {
                    int cnt = top[r];
                    if (cnt) {
                        int nr = (r + valMod) % k;
                        cur[nr] = (cur[nr] + cnt) % MOD;
                    }
                }
            }
            if (j > 0) {
                const std::vector<int>& left = dpCurr[j - 1];
                for (int r = 0; r < k; ++r) {
                    int cnt = left[r];
                    if (cnt) {
                        int nr = (r + valMod) % k;
                        cur[nr] = (cur[nr] + cnt) % MOD;
                    }
                }
            }
        }
        dpPrev.swap(dpCurr);
    }
    return dpPrev[n - 1][0];
}

