    for (std::size_t i = n; i-- > 0;) {
        if (i == n - 1) minSuffix[i] = s[i];
        else minSuffix[i] = s[i] < minSuffix[i + 1] ? s[i] : minSuffix[i + 1];
    }
    std::vector<char> stack;
    std::string result;
    for (std::size_t i = 0; i < n; ++i) {
        stack.push_back(s[i]);
        while (!stack.empty() && (i == n - 1 || stack.back() <= minSuffix[i + 1])) {
            result.push_back(stack.back());
            stack.pop_back();
        }
    }
    while (!stack.empty()) {
        result.push_back(stack.back());
        stack.pop_back();
    }
    return result;
}

