std::vector<std::vector<std::string>> mostPopularCreator(const std::vector<std::string>& creators, const std::vector<std::string>& ids, const std::vector<int>& views) {
    std::unordered_map<std::string, long long> creatorViews;
    for (size_t i = 0; i < creators.size(); ++i) {
        creatorViews[creators[i]] += views[i];
    }
    long long maxViews = std::numeric_limits<long long>::min();
    for (const auto& kv : creatorViews) {
        if (kv.second > maxViews) maxViews = kv.second;
    }
    struct VideoInfo { std::string id; int views; };
    std::unordered_map<std::string, VideoInfo> mostViewedVideos;
    for (size_t i = 0; i < creators.size(); ++i) {
        if (creatorViews[creators[i]] == maxViews) {
            auto it = mostViewedVideos.find(creators[i]);
            if (it == mostViewedVideos.end()) {
                mostViewedVideos.emplace(creators[i], VideoInfo{ids[i], views[i]});
            } else {
                if (views[i] > it->second.views) {
                    it->second = VideoInfo{ids[i], views[i]};
                } else if (views[i] == it->second.views && ids[i] < it->second.id) {
                    it->second = VideoInfo{ids[i], views[i]};
                }
            }
        }
    }
    std::vector<std::vector<std::string>> result;
    for (const auto& kv : mostViewedVideos) {
        result.push_back({kv.first, kv.second.id});
    }
    std::sort(result.begin(), result.end(), [](const std::vector<std::string>& a, const std::vector<std::string>& b) {
        return a[0] < b[0];
    });
    return result;
}

