std::vector<std::string> twoEditWords(const std::vector<std::string>& queries, const std::vector<std::string>& dictionary) {
    auto isWithinTwoEdits = [](const std::string& word1, const std::string& word2) -> bool {
        int diffCount = 0;
        for (size_t i = 0; i < word1.size(); ++i) {
            if (word1[i] != word2[i]) ++diffCount;
            if (diffCount > 2) return false;
        }
        return true;
    };
    std::vector<std::string> result;
    for (const auto& query : queries) {
        for (const auto& dictWord : dictionary) {
            if (isWithinTwoEdits(query, dictWord)) {
                result.push_back(query);
                break;
            }
        }
    }
    return result;
}

