int maximumSum(const std::vector<int>& nums, int k) {
    int maxSum = 0;
    for (size_t i = 0; i + static_cast<size_t>(k) <= nums.size(); ++i) {
        std::unordered_set<int> set;
        int sum = 0;
        for (size_t j = i; j < i + static_cast<size_t>(k); ++j) {
            set.insert(nums[j]);
            sum += nums[j];
        }
        if (set.size() == static_cast<size_t>(k)) {
            maxSum = std::max(maxSum, sum);
        }
    }
    return maxSum;
}

