long long destroyTargets(const std::vector<long long>& nums, long long space) {
    std::unordered_map<long long, std::pair<int, long long>> info;
    for (long long num : nums) {
        long long seed = num % space;
        auto it = info.find(seed);
        if (it == info.end()) {
            info[seed] = {1, num};
        } else {
            ++it->second.first;
            if (num < it->second.second) {
                it->second.second = num;
            }
        }
    }
    int maxCount = -1;
    long long answer = LLONG_MAX;
    for (const auto& kv : info) {
        int cnt = kv.second.first;
        long long minNum = kv.second.second;
        if (cnt > maxCount) {
            maxCount = cnt;
            answer = minNum;
        } else if (cnt == maxCount && minNum < answer) {
            answer = minNum;
        }
    }
    return answer;
}

