struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

void dfs(TreeNode* node, TreeNode* parent, int depth,
         std::unordered_map<int, TreeNode*>& parentMap,
         std::unordered_map<int, int>& depthMap,
         std::vector<int>& leafDepths) {
    if (!node) return;
    parentMap[node->val] = parent;
    depthMap[node->val] = depth;
    if (!node->left && !node->right) {
        leafDepths.push_back(depth);
        return;
    }
    dfs(node->left, node, depth + 1, parentMap, depthMap, leafDepths);
    dfs(node->right, node, depth + 1, parentMap, depthMap, leafDepths);
}

bool isDescendantOrSelf(int node, int ancestor, std::unordered_map<int, TreeNode*>& parentMap) {
    while (true) {
        if (node == ancestor) return true;
        auto it = parentMap.find(node);
        if (it == parentMap.end() || !it->second) return false;
        node = it->second->val;
    }
}

std::vector<int> treeQueries(TreeNode* root, const std::vector<int>& queries) {
    std::unordered_map<int, TreeNode*> parentMap;
    std::unordered_map<int, int> depthMap;
    std::vector<int> leafDepths;
    // need (leafValue, depth) pairs to check exclusion; redo with values tracked
    std::vector<std::pair<int,int>> leaves; // (val, depth)
    std::function<void(TreeNode*, TreeNode*, int)> build = [&](TreeNode* node, TreeNode* parent, int depth) {
        if (!node) return;
        parentMap[node->val] = parent;
        depthMap[node->val] = depth;
        if (!node->left && !node->right) {
            leaves.push_back({node->val, depth});
            return;
        }
        build(node->left, node, depth + 1);
        build(node->right, node, depth + 1);
    };
    build(root, nullptr, 0);

    std::vector<int> result(queries.size());
    for (size_t i = 0; i < queries.size(); ++i) {
        int q = queries[i];
        int best = 0;
        for (auto& [leafVal, leafDepth] : leaves) {
            if (!isDescendantOrSelf(leafVal, q, parentMap)) {
                best = std::max(best, leafDepth);
            }
        }
        result[i] = best;
    }
    return result;
}

