long long mostProfitablePath(const std::vector<std::vector<int>>& edges, int bob, const std::vector<int>& amount) {
    int n = amount.size();
    std::vector<std::vector<int>> g(n);
    for (const auto& e : edges) {
        g[e[0]].push_back(e[1]);
        g[e[1]].push_back(e[0]);
    }
    std::vector<int> parent(n, -1), depth(n, 0);
    std::queue<int> q;
    q.push(0);
    parent[0] = -2;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : g[u]) if (v != parent[u]) {
            parent[v] = u;
            depth[v] = depth[u] + 1;
            q.push(v);
        }
    }
    const int INF = n + 5;
    std::vector<int> distBob(n, INF);
    int cur = bob, d = 0;
    while (cur != -2) {
        distBob[cur] = d;
        cur = parent[cur];
        ++d;
    }
    std::vector<long long> contrib(n);
    for (int i = 0; i < n; ++i) {
        if (depth[i] < distBob[i]) contrib[i] = amount[i];
        else if (depth[i] > distBob[i]) contrib[i] = 0;
        else contrib[i] = amount[i] / 2;
    }
    std::vector<int> order;
    order.reserve(n);
    std::stack<int> st;
    st.push(0);
    while (!st.empty()) {
        int u = st.top(); st.pop();
        order.push_back(u);
        for (int v : g[u]) if (v != parent[u]) st.push(v);
    }
    std::vector<long long> dp(n, 0);
    for (int i = (int)order.size() - 1; i >= 0; --i) {
        int u = order[i];
        long long best = LLONG_MIN;
        bool hasChild = false;
        for (int v : g[u]) if (v != parent[u]) {
            hasChild = true;
            if (dp[v] > best) best = dp[v];
        }
        dp[u] = hasChild ? contrib[u] + best : contrib[u];
    }
    return dp[0];
}

