ListNode* removeNodes(ListNode* head) {
    ListNode* prev = nullptr;
    ListNode* cur = head;
    while (cur) {
        ListNode* nxt = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nxt;
    }
    long long maxSoFar = LLONG_MIN;
    ListNode* newHead = nullptr;
    cur = prev;
    while (cur) {
        ListNode* nxt = cur->next; // save before possibly overwriting cur->next
        if (cur->val >= maxSoFar) {
            maxSoFar = cur->val;
            cur->next = newHead;
            newHead = cur;
        }
        cur = nxt;
    }
    return newHead;
}

