int countGoodStrings(int low, int high, int zero, int one) {
    const int MOD = 1000000007;
    std::vector<int> dp(high + 1, 0);
    dp[0] = 1;
    int answer = 0;
    for (int i = 1; i <= high; ++i) {
        int64_t ways = 0;
        if (i >= zero) ways = (ways + dp[i - zero]) % MOD;
        if (i >= one)  ways = (ways + dp[i - one]) % MOD;
        dp[i] = static_cast<int>(ways);
        if (i >= low) answer = (answer + dp[i]) % MOD;
    }
    return answer;
}

