long long subarrayLCM(const std::vector<int>& nums, int k) {
    auto gcd = [](long long a, long long b) {
        while (b != 0) {
            long long t = a % b;
            a = b;
            b = t;
        }
        return a;
    };
    auto lcm = [&](long long a, long long b) {
        return a / gcd(a, b) * b;
    };
    long long count = 0;
    for (std::size_t i = 0; i < nums.size(); ++i) {
        long long currentLcm = nums[i];
        for (std::size_t j = i; j < nums.size(); ++j) {
            currentLcm = lcm(currentLcm, nums[j]);
            if (currentLcm == k) ++count;
            if (currentLcm > k) break;
        }
    }
    return count;
}

