int magnificentSets(int n, std::vector<std::vector<int>>& edges) {
    std::vector<std::vector<int>> adj(n + 1);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    std::vector<int> visited(n + 1, 0);
    std::vector<int> color(n + 1, -1);
    int totalGroups = 0;

    for (int start = 1; start <= n; ++start) {
        if (visited[start]) continue;

        // Gather component and check bipartite
        std::vector<int> component;
        std::queue<int> q;
        q.push(start);
        visited[start] = 1;
        color[start] = 0;
        bool bipartite = true;

        while (!q.empty()) {
            int u = q.front(); q.pop();
            component.push_back(u);
            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = 1;
                    color[v] = color[u] ^ 1;
                    q.push(v);
                } else {
                    if (color[v] == color[u]) {
                        bipartite = false;
                    }
                }
            }
        }

        if (!bipartite) return -1;

        // Compute diameter of this component
        int diam = 0;
        for (int u : component) {
            std::vector<int> dist(n + 1, -1);
            std::queue<int> qq;
            dist[u] = 0;
            qq.push(u);
            while (!qq.empty()) {
                int x = qq.front(); qq.pop();
                for (int y : adj[x]) {
                    if (dist[y] == -1) {
                        dist[y] = dist[x] + 1;
                        qq.push(y);
                    }
                }
            }
            for (int v : component) {
                if (dist[v] > diam) diam = dist[v];
            }
        }

        totalGroups += diam + 1;
    }

    return totalGroups;
}

