long long dividePlayers(const std::vector<int>& skill) {
    std::size_t n = skill.size();
    long long total = 0;
    for (int v : skill) {
        total += v;
    }
    if (n == 0) return -1;
    if ((2 * total) % n != 0) return -1;
    long long target = (2 * total) / n;

    std::unordered_map<long long, int> cnt;
    for (int v : skill) {
        ++cnt[v];
    }

    long long chemistrySum = 0;
    for (auto& entry : cnt) {
        long long val = entry.first;
        while (cnt[val] > 0) {
            long long partner = target - val;
            auto itPartner = cnt.find(partner);
            if (itPartner == cnt.end() || itPartner->second == 0) return -1;
            if (partner == val && cnt[val] < 2) return -1;
            cnt[val]--;
            itPartner->second--;
            chemistrySum += val * partner;
        }
    }
    return chemistrySum;
}

