int longestSquareStreak(const std::vector<int>& nums) {
    std::unordered_set<long long> present;
    present.reserve(nums.size() * 2);
    for (int v : nums) {
        present.insert(static_cast<long long>(v));
    }
    std::unordered_map<long long, int> memo;
    memo.reserve(present.size() * 2);
    std::function<int(long long)> chainLen = [&](long long x) -> int {
        if (present.find(x) == present.end()) return 0;
        auto it = memo.find(x);
        if (it != memo.end()) return it->second;
        long long next = x * x;
        int len = 1;
        if (present.find(next) != present.end()) len = 1 + chainLen(next);
        memo[x] = len;
        return len;
    };
    int best = 0;
    for (const long long& v : present) {
        best = std::max(best, chainLen(v));
    }
    return best >= 2 ? best : -1;
}

#include <bits/stdc++.h>

long long totalCost(std::vector<long long>& costs, int k, int candidates) {
    int n = static_cast<int>(costs.size());
    int leftPtr = 0;
    int rightPtr = n - 1;
    using P = std::pair<long long, int>;
    auto cmp = std::greater<P>();
    std::priority_queue<P, std::vector<P>, decltype(cmp)> leftHeap(cmp);
    std::priority_queue<P, std::vector<P>, decltype(cmp)> rightHeap(cmp);

    for (int i = 0; i < candidates && leftPtr <= rightPtr; ++i) {
        leftHeap.emplace(costs[leftPtr], leftPtr);
        ++leftPtr;
    }
    for (int i = 0; i < candidates && leftPtr <= rightPtr; ++i) {
        rightHeap.emplace(costs[rightPtr], rightPtr);
        --rightPtr;
    }

    long long total = 0;
    for (int hired = 0; hired < k; ++hired) {
        if (leftHeap.empty()) {
            P top = rightHeap.top();
            rightHeap.pop();
            total += top.first;
            if (leftPtr <= rightPtr) {
                rightHeap.emplace(costs[rightPtr], rightPtr);
                --rightPtr;
            }
        } else if (rightHeap.empty()) {
            P top = leftHeap.top();
            leftHeap.pop();
            total += top.first;
            if (leftPtr <= rightPtr) {
                leftHeap.emplace(costs[leftPtr], leftPtr);
                ++leftPtr;
            }
        } else {
            P leftTop = leftHeap.top();
            P rightTop = rightHeap.top();
            if (leftTop.first < rightTop.first || (leftTop.first == rightTop.first && leftTop.second < rightTop.second)) {
                leftHeap.pop();
                total += leftTop.first;
                if (leftPtr <= rightPtr) {
                    leftHeap.emplace(costs[leftPtr], leftPtr);
                    ++leftPtr;
                }
            } else {
                rightHeap.pop();
                total += rightTop.first;
                if (leftPtr <= rightPtr) {
                    rightHeap.emplace(costs[rightPtr], rightPtr);
                    --rightPtr;
                }
            }
        }
    }
    return total;
}

