int minScore(int n, const std::vector<std::vector<int>>& roads) {
    std::vector<std::vector<std::pair<int, int>>> adj(n + 1);
    for (const auto& r : roads) {
        int a = r[0];
        int b = r[1];
        int w = r[2];
        adj[a].push_back({b, w});
        adj[b].push_back({a, w});
    }
    std::vector<char> visited(n + 1, 0);
    std::vector<int> stack;
    stack.push_back(1);
