            if (w < best) best = w;
            if (!visited[to]) {
                visited[to] = 1;
                stack.push_back(to);
            }
        }
    }
    return best;
}

#include <bits/stdc++.h>

long long minimumTotalCost(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    int n = static_cast<int>(nums1.size());
    const long long INF = 4e18;
    std::vector<long long> u(n + 1, 0), v(n + 1, 0);
    std::vector<int> p_match(n + 1, 0), way(n + 1, 0);

    for (int i = 1; i <= n; ++i) {
        p_match[0] = i;
        int j0 = 0;
        std::vector<long long> minv(n + 1, INF);
        std::vector<char> used(n + 1, false);
        do {
            used[j0] = true;
            int i0 = p_match[j0];
            long long delta = INF;
            int j1 = 0;
            for (int j = 1; j <= n; ++j) {
                if (used[j]) continue;
                long long cur;
                if (nums1[i0 - 1] == nums2[j - 1]) {
                    cur = INF;
                } else {
                    cur = (i0 - 1 == j - 1) ? 0LL : (i0 - 1) + (j - 1);
                }
                cur -= u[i0] + v[j];
                if (cur < minv[j]) {
                    minv[j] = cur;
                    way[j] = j0;
                }
                if (minv[j] < delta) {
                    delta = minv[j];
                    j1 = j;
                }
            }
            for (int j = 0; j <= n; ++j) {
                if (used[j]) {
                    u[p_match[j]] += delta;
                    v[j] -= delta;
                } else {
                    minv[j] -= delta;
                }
            }
            j0 = j1;
        } while (p_match[j0] != 0);
        do {
            int j1 = way[j0];
            p_match[j0] = p_match[j1];
            j0 = j1;
        } while (j0);
    }

    std::vector<int> assignment(n, -1);
    for (int j = 1; j <= n; ++j) {
        if (p_match[j] != 0) {
            assignment[p_match[j] - 1] = j - 1;
        }
    }

    long long total = 0;
    for (int i = 0; i < n; ++i) {
        int j = assignment[i];
        if (nums1[i] == nums2[j]) return -1;
        total += (i == j) ? 0LL : i + j;
    }
    return total / 2;
}

