class MemoryAllocator {
public:
    struct Interval { int start, end; };
    struct IntervalCmp { bool operator()(const Interval& a, const Interval& b) const { return a.start < b.start; } };
    std::set<Interval, IntervalCmp> intervals;
    std::unordered_map<int, std::vector<std::pair<int,int>>> allocations;
    MemoryAllocator(int n) { intervals.insert({0, n-1}); }
    int allocate(int size, int mID) {
        for (auto it = intervals.begin(); it != intervals.end(); ++it) {
            int length = it->end - it->start + 1;
            if (length >= size) {
                int allocStart = it->start;
                if (length == size) intervals.erase(it);
                else { Interval updated = {it->start + size, it->end}; intervals.erase(it); intervals.insert(updated); }
                allocations[mID].push_back({allocStart, size});
                return allocStart;
            }
        }
        return -1;
    }
    void freeInterval(int start, int size) {
        int newStart = start, newEnd = start + size - 1;
        auto it = intervals.lower_bound({newStart, 0});
        if (it != intervals.begin()) {
            auto prevIt = std::prev(it);
            if (prevIt->end + 1 >= newStart) {
                newStart = std::min(newStart, prevIt->start);
                newEnd = std::max(newEnd, prevIt->end);
                intervals.erase(prevIt);
            }
        }
        it = intervals.lower_bound({newStart, 0});
        while (it != intervals.end() && it->start <= newEnd + 1) {
            newEnd = std::max(newEnd, it->end);
            it = intervals.erase(it);
        }
        intervals.insert({newStart, newEnd});
    }
    int free(int mID) {
        auto it = allocations.find(mID);
        if (it == allocations.end()) return 0;
        int freed = 0;
        for (auto& [start, size] : it->second) { freeInterval(start, size); freed += size; }
        allocations.erase(it);
        return freed;
    }
};

#include <bits/stdc++.h>

bool isPossible(int n, std::vector<std::vector<int>>& edges) {
    std::vector<int> degree(n + 1, 0);
    std::unordered_set<long long> edgeSet;
    edgeSet.reserve(edges.size() * 2 + 1);
    const long long mul = static_cast<long long>(n) + 1;
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        degree[u]++; degree[v]++;
        if (u > v) std::swap(u, v);
        edgeSet.insert(static_cast<long long>(u) * mul + v);
    }

    std::vector<int> odd;
    odd.reserve(4);
    for (int i = 1; i <= n; ++i) {
        if (degree[i] & 1) odd.push_back(i);
    }

    if (odd.empty()) return true;
    if (odd.size() > 4) return false;

    auto hasEdge = [&](int a, int b) -> bool {
        if (a > b) std::swap(a, b);
        return edgeSet.find(static_cast<long long>(a) * mul + b) != edgeSet.end();
    };

    if (odd.size() == 2) {
        int a = odd[0], b = odd[1];
        if (!hasEdge(a, b)) return true;
        bool hasA = false, hasB = false;
        for (int v = 1; v <= n; ++v) {
            if (v == a || v == b) continue;
            if (!hasEdge(a, v)) hasA = true;
            if (!hasEdge(b, v)) hasB = true;
            if (hasA && hasB) return true;
        }
        return false;
    }

    // odd.size() == 4
    int o0 = odd[0], o1 = odd[1], o2 = odd[2], o3 = odd[3];
    if (!hasEdge(o0, o1) && !hasEdge(o2, o3)) return true;
    if (!hasEdge(o0, o2) && !hasEdge(o1, o3)) return true;
    if (!hasEdge(o0, o3) && !hasEdge(o1, o2)) return true;
    return false;
}

