std::vector<int> topStudents(const std::vector<std::string>& positive_feedback,
                             const std::vector<std::string>& negative_feedback,
                             const std::vector<std::string>& report,
                             const std::vector<int>& student_id,
                             int k) {
    std::unordered_set<std::string> posSet(positive_feedback.begin(), positive_feedback.end());
    std::unordered_set<std::string> negSet(negative_feedback.begin(), negative_feedback.end());

    std::unordered_map<int, long long> points;
    for (size_t i = 0; i < report.size(); ++i) {
        std::istringstream iss(report[i]);
        std::string w;
        long long cur = 0;
        while (iss >> w) {
            if (posSet.find(w) != posSet.end()) cur += 3;
            else if (negSet.find(w) != negSet.end()) cur -= 1;
        }
        int id = student_id[i];
        points[id] = points[id] + cur;
    }

    struct Node { int id; long long pts; };
    std::vector<Node> heap;

    auto less = [](const Node& a, const Node& b) {
        return a.pts < b.pts || (a.pts == b.pts && a.id > b.id);
    };

    auto swap_nodes = [&](size_t i, size_t j) {
        Node t = heap[i];
        heap[i] = heap[j];
        heap[j] = t;
    };

    std::function<void(size_t)> heapifyUp = [&](size_t idx) {
        while (idx > 0) {
            size_t p = (idx - 1) >> 1;
            if (!less(heap[idx], heap[p])) break;
            swap_nodes(idx, p);
            idx = p;
        }
    };

    std::function<void(size_t)> heapifyDown = [&](size_t idx) {
        size_t n = heap.size();
        while (true) {
            size_t left = idx * 2 + 1;
            size_t right = left + 1;
            size_t smallest = idx;
            if (left < n && less(heap[left], heap[smallest])) smallest = left;
            if (right < n && less(heap[right], heap[smallest])) smallest = right;
            if (smallest == idx) break;
            swap_nodes(idx, smallest);
            idx = smallest;
        }
    };

    auto push = [&](const Node& node) {
        heap.push_back(node);
        heapifyUp(heap.size() - 1);
        if (static_cast<int>(heap.size()) > k) {
            Node last = heap.back();
            heap.pop_back();
            heap[0] = last;
            heapifyDown(0);
        }
    };

    for (const auto& kv : points) {
        push({kv.first, kv.second});
    }

    std::sort(heap.begin(), heap.end(), [](const Node& a, const Node& b) {
        if (a.pts != b.pts) return a.pts > b.pts;
        return a.id < b.id;
    });

    std::vector<int> result;
    result.reserve(heap.size());
    for (const auto& node : heap) result.push_back(node.id);
    return result;
}

