int takeCharacters(std::string s, int k) {
    int n = static_cast<int>(s.size());
    if (k == 0) return 0;
    std::array<int, 3> total = {0, 0, 0};
    for (char ch : s) total[ch - 'a']++;
    for (int i = 0; i < 3; ++i) if (total[i] < k) return -1;
    std::array<int, 3> limit;
    for (int i = 0; i < 3; ++i) limit[i] = total[i] - k;
    std::array<int, 3> cnt = {0, 0, 0};
    int left = 0, maxLen = 0;
    for (int right = 0; right < n; ++right) {
        cnt[s[right] - 'a']++;
        while (cnt[0] > limit[0] || cnt[1] > limit[1] || cnt[2] > limit[2]) {
            cnt[s[left] - 'a']--;
            ++left;
        }
        maxLen = std::max(maxLen, right - left + 1);
    }
    return n - maxLen;
}

