long long countAnagrams(const std::string& s) {
    const long long MOD = 1000000007LL;

    std::vector<std::string> words;
    size_t start = 0;
    while (true) {
        size_t pos = s.find(' ', start);
        if (pos == std::string::npos) {
            words.push_back(s.substr(start));
            break;
        } else {
            words.push_back(s.substr(start, pos - start));
            start = pos + 1;
        }
    }

    size_t maxLen = 0;
    for (const auto& w : words) if (w.size() > maxLen) maxLen = w.size();

    std::vector<long long> fact(maxLen + 1);
    std::vector<long long> invFact(maxLen + 1);
    fact[0] = 1LL;
    for (size_t i = 1; i <= maxLen; ++i) fact[i] = (fact[i - 1] * static_cast<long long>(i)) % MOD;

    auto modPow = [&](long long base, long long exp) -> long long {
        long long res = 1LL;
        long long b = base % MOD;
        long long e = exp;
        while (e > 0) {
            if (e & 1LL) res = (res * b) % MOD;
            b = (b * b) % MOD;
            e >>= 1LL;
        }
        return res;
    };

    invFact[maxLen] = modPow(fact[maxLen], MOD - 2);
    for (size_t i = maxLen; i > 0; --i) {
        invFact[i - 1] = (invFact[i] * static_cast<long long>(i)) % MOD;
    }

    long long answer = 1LL;
    for (const auto& w : words) {
        long long ways = fact[w.size()];
        std::unordered_map<char, int> freq;
        for (char ch : w) ++freq[ch];
        for (const auto& kv : freq) {
            int cnt = kv.second;
            ways = (ways * invFact[cnt]) % MOD;
        }
        answer = (answer * ways) % MOD;
    }

    return answer;
}

