#include <bits/stdc++.h>
long long minimumMaximum(int divisor1, int divisor2, int uniqueCnt1, int uniqueCnt2) {
    using int64 = long long;
    int64 d1 = divisor1, d2 = divisor2;
    int64 cnt1 = uniqueCnt1, cnt2 = uniqueCnt2;
    auto gcd = [](int64 a, int64 b) {
        while (b) { int64 t = a % b; a = b; b = t; }
        return a;
    };
    int64 lcm = d1 / gcd(d1, d2) * d2;
    auto feasible = [&](int64 M) -> bool {
        int64 total1 = M - M / d1;
        int64 total2 = M - M / d2;
        int64 both = M - M / d1 - M / d2 + M / lcm;
        int64 exclusive1 = total1 - both;
        int64 exclusive2 = total2 - both;
        int64 need1 = cnt1 > exclusive1 ? cnt1 - exclusive1 : 0;
        int64 need2 = cnt2 > exclusive2 ? cnt2 - exclusive2 : 0;
        return need1 + need2 <= both;
    };
    int64 low = 1, high = 1;
    while (!feasible(high)) high <<= 1;
    while (low < high) {
        int64 mid = low + (high - low) / 2;
        if (feasible(mid)) high = mid;
        else low = mid + 1;
    }
    return low;
}

#include <bits/stdc++.h>
