int numberOfGreatPartitions(const std::vector<int>& nums, int k) {
    const uint32_t MOD = 1000000007u;
    int total = 0;
    for (int v : nums) total += v;
    if (k > total) return 0;
    std::vector<uint32_t> dp(total + 1);
    dp[0] = 1;
    int curMax = 0;
    for (int v : nums) {
        for (int t = curMax; t >= 0; --t) {
            uint32_t add = dp[t];
            if (add) {
                int nxt = t + v;
                uint32_t val = dp[nxt] + add;
                if (val >= MOD) val -= MOD;
                dp[nxt] = val;
            }
        }
        curMax += v;
    }
    uint32_t ans = 0;
    int upper = total - k;
    for (int t = k; t <= upper; ++t) {
        ans += dp[t];
        if (ans >= MOD) ans -= MOD;
    }
    return static_cast<int>(ans);
}

