long long maxPower(std::vector<int>& stations, int r, int k) {
    int n = static_cast<int>(stations.size());
    std::vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + stations[i];
    std::vector<long long> initPower(n);
    for (int i = 0; i < n; ++i) {
        int left = std::max(0, i - r);
        int right = std::min(n - 1, i + r);
        initPower[i] = pref[right + 1] - pref[left];
    }
    long long low = 0, high = *std::max_element(initPower.begin(), initPower.end()) + static_cast<long long>(k);
    auto feasible = [&](long long target) -> bool {
        std::vector<long long> diff(n + 1, 0);
        long long cur = 0, used = 0;
        for (int i = 0; i < n; ++i) {
            cur += diff[i];
            long long total = initPower[i] + cur;
            if (total < target) {
                long long need = target - total;
                used += need;
                if (used > k) return false;
                int pos = std::min(n - 1, i + r);
                int l = std::max(0, pos - r);
                int rr = std::min(n - 1, pos + r);
                diff[l] += need;
                diff[rr + 1] -= need;
                cur += need;
            }
        }
        return true;
    };
    while (low < high) {
        long long mid = (low + high + 1) / 2;
        if (feasible(mid)) low = mid;
        else high = mid - 1;
    }
    return low;
}

