std::vector<int> closestPrimes(int left, int right) {
    int limit = right;
    std::vector<unsigned char> isPrime(limit + 1, 0);
    if (limit >= 2) {
        std::fill(isPrime.begin() + 2, isPrime.end(), 1);
    }
    for (int p = 2; p * p <= limit; ++p) {
        if (isPrime[p] == 1) {
            for (int mult = p * p; mult <= limit; mult += p) {
                isPrime[mult] = 2;
            }
        }
    }

    std::vector<int> primesInRange;
    int start = std::max(2, left);
    for (int i = start; i <= right; ++i) {
        if (isPrime[i] == 1) {
            primesInRange.push_back(i);
        }
    }

    if (primesInRange.size() < 2) {
        return std::vector<int>{-1, -1};
    }
    int bestGap = std::numeric_limits<int>::max();
    std::vector<int> bestPair{-1, -1};
    for (size_t i = 1; i < primesInRange.size(); ++i) {
        int gap = primesInRange[i] - primesInRange[i - 1];
        if (gap < bestGap) {
            bestGap = gap;
            bestPair[0] = primesInRange[i - 1];
            bestPair[1] = primesInRange[i];
        }
    }
    return bestPair;
}

