int maximumCount(const std::vector<int>& nums) {
    auto firstGreater = [&](int target) {
        int lo = 0, hi = static_cast<int>(nums.size());
        while (lo < hi) {
            int mid = (lo + hi) >> 1;
            if (nums[mid] > target) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    };
    auto firstGE = [&](int target) {
        int lo = 0, hi = static_cast<int>(nums.size());
        while (lo < hi) {
            int mid = (lo + hi) >> 1;
            if (nums[mid] >= target) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    };
    int n = static_cast<int>(nums.size());
    int firstNonNeg = firstGE(0);
    int firstPos = firstGreater(0);
    int negCount = firstNonNeg;
    int posCount = n - firstPos;
    return negCount > posCount ? negCount : posCount;
}

#include <bits/stdc++.h>
#include <vector>

long long maximalScore(const std::vector<int>& nums, int k) {
    std::vector<long long> heap;
    heap.reserve(nums.size());
    auto heapPush = [&](long long val) {
        heap.push_back(val);
        int idx = static_cast<int>(heap.size()) - 1;
        while (idx > 0) {
            int parent = (idx - 1) >> 1;
            if (heap[parent] >= heap[idx]) break;
            std::swap(heap[parent], heap[idx]);
            idx = parent;
        }
    };
    auto heapPop = [&]() -> long long {
        long long top = heap[0];
        long long last = heap.back();
        heap.pop_back();
        if (!heap.empty()) {
            heap[0] = last;
            int idx = 0;
            while (true) {
                int left = idx * 2 + 1;
                int right = left + 1;
                int largest = idx;
                if (left < static_cast<int>(heap.size()) && heap[left] > heap[largest]) largest = left;
                if (right < static_cast<int>(heap.size()) && heap[right] > heap[largest]) largest = right;
                if (largest == idx) break;
                std::swap(heap[idx], heap[largest]);
                idx = largest;
            }
        }
        return top;
    };
    for (int v : nums) heapPush(v);
    long long answer = 0;
    for (int i = 0; i < k; ++i) {
        long long cur = heapPop();
        answer += cur;
        long long next = (cur + 2) / 3;
        heapPush(next);
    }
    return answer;
}

