bool isItPossible(const std::string& word1, const std::string& word2) {
    int f1[26] = {0}, f2[26] = {0};
    for (char c : word1) ++f1[c - 'a'];
    for (char c : word2) ++f2[c - 'a'];
    int d1 = 0, d2 = 0;
    for (int i = 0; i < 26; ++i) {
        if (f1[i] > 0) ++d1;
        if (f2[i] > 0) ++d2;
    }
    if (d1 == d2) return true;
    for (int a = 0; a < 26; ++a) {
        if (f1[a] == 0) continue;
        for (int b = 0; b < 26; ++b) {
            if (f2[b] == 0) continue;
            if (a == b) continue;
            int nd1 = d1, nd2 = d2;
            if (f1[a] == 1) --nd1;
            if (f1[b] == 0) ++nd1;
            if (f2[b] == 1) --nd2;
            if (f2[a] == 0) ++nd2;
            if (nd1 == nd2) return true;
        }
    }
    return false;
}

#include <bits/stdc++.h>
using namespace std;

long long timeToCrossBridge(int n, int k, vector<vector<int>>& time) {
    vector<int> right(k), pick(k), left(k), put(k), crossSum(k);
    for (int i = 0; i < k; i++) {
        right[i] = time[i][0]; pick[i] = time[i][1];
        left[i] = time[i][2]; put[i] = time[i][3];
        crossSum[i] = right[i] + left[i];
    }

    // "least efficient first" = highest crossSum, tie -> highest index
    auto effCmp = [&](int a, int b) {
        if (crossSum[a] != crossSum[b]) return crossSum[a] < crossSum[b]; // max-heap on crossSum
        return a < b; // max-heap on index
    };
    priority_queue<int, vector<int>, decltype(effCmp)> waitingLeft(effCmp), waitingRight(effCmp);
    for (int i = 0; i < k; i++) waitingLeft.push(i);

    using PLI = pair<long long,int>;
    priority_queue<PLI, vector<PLI>, greater<PLI>> workingRight, workingLeft;

    long long currentTime = 0;
    int boxesLeftToPick = n, boxesPut = 0;

    auto releaseUpTo = [&](long long t) {
        while (!workingRight.empty() && workingRight.top().first <= t) {
            int idx = workingRight.top().second; workingRight.pop();
            waitingRight.push(idx);
        }
        while (!workingLeft.empty() && workingLeft.top().first <= t) {
            int idx = workingLeft.top().second; workingLeft.pop();
            waitingLeft.push(idx);
        }
    };

    while (boxesPut < n) {
        releaseUpTo(currentTime);
        if (!waitingRight.empty()) {
            int idx = waitingRight.top(); waitingRight.pop();
            currentTime += left[idx];
            boxesPut++;
            if (boxesPut == n) return currentTime;
            workingLeft.push({currentTime + put[idx], idx});
        } else if (!waitingLeft.empty() && boxesLeftToPick > 0) {
            int idx = waitingLeft.top(); waitingLeft.pop();
            boxesLeftToPick--;
            currentTime += right[idx];
            workingRight.push({currentTime + pick[idx], idx});
        } else {
            long long next = LLONG_MAX;
            if (!workingRight.empty()) next = min(next, workingRight.top().first);
            if (!workingLeft.empty()) next = min(next, workingLeft.top().first);
            currentTime = next;
        }
    }
    return currentTime;
}

