long long differenceOfSums(const std::vector<int>& nums) {
    long long elementSum = 0;
    long long digitSum = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        int num = nums[i];
        elementSum += num;
        while (num > 0) {
            digitSum += num % 10;
            num = num / 10;
        }
    }
    long long diff = elementSum - digitSum;
    return diff >= 0 ? diff : -diff;
}

