long long countGoodSubarrays(const std::vector<int>& nums, long long k) {
    if (k <= 0) {
        long long n = static_cast<long long>(nums.size());
        return (n * (n + 1)) >> 1;
    }

    std::unordered_map<int, long long> freq;
    long long pairCnt = 0;
    std::size_t left = 0;
    long long answer = 0;

    for (std::size_t right = 0; right < nums.size(); ++right) {
        int val = nums[right];
        long long cur = 0;
        auto it = freq.find(val);
        if (it != freq.end()) cur = it->second;
        pairCnt += cur;
        freq[val] = cur + 1;

        while (pairCnt >= k) {
            int leftVal = nums[left];
            long long leftCnt = freq[leftVal];
            long long pairsLost = leftCnt - 1;
            if (pairCnt - pairsLost < k) break;

            pairCnt -= pairsLost;
            if (leftCnt == 1) {
                freq.erase(leftVal);
            } else {
                freq[leftVal] = leftCnt - 1;
            }
            ++left;
        }

        if (pairCnt >= k) {
            answer += static_cast<long long>(left) + 1;
        }
    }
    return answer;
}

