bool isCircularSentence(const std::string& sentence) {
    std::vector<std::string> words;
    size_t start = 0;
    while (true) {
        size_t pos = sentence.find(' ', start);
        if (pos == std::string::npos) {
            words.push_back(sentence.substr(start));
            break;
        } else {
            words.push_back(sentence.substr(start, pos - start));
            start = pos + 1;
        }
    }
    for (size_t i = 0; i < words.size(); ++i) {
        if (i == words.size() - 1) {
            if (words[i].back() != words[0].front()) {
                return false;
            }
        } else {
            if (words[i].back() != words[i + 1].front()) {
                return false;
            }
        }
    }
    return true;
}

