struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

std::vector<std::vector<int>> closestNodes(TreeNode* root, const std::vector<int>& queries) {
    std::vector<int> values;
    std::function<void(TreeNode*)> inOrder = [&](TreeNode* node) {
        if (node) {
            inOrder(node->left);
            values.push_back(node->val);
            inOrder(node->right);
        }
    };
    inOrder(root);

    std::vector<std::vector<int>> result;
    for (int query : queries) {
        int mini = -1;
        for (int value : values) {
            if (value <= query) {
                mini = value;
            } else {
                break;
            }
        }

        int maxi = -1;
        for (int value : values) {
            if (value >= query) {
                maxi = value;
                break;
            }
        }

        result.push_back({mini, maxi});
    }
    return result;
}

