bool isPalindrome(const std::string& str) {
    int len = static_cast<int>(str.size());
    for (int i = 0; i < len / 2; ++i) {
        if (str[i] != str[len - 1 - i]) {
            return false;
        }
    }
    return true;
}

int maxNonOverlappingPalindromeSubstrings(const std::string& s, int k) {
    int count = 0;
    int left = 0;
    int n = static_cast<int>(s.size());
    while (left < n) {
        bool found = false;
        for (int right = left + k; right <= n; ++right) {
            std::string substring = s.substr(left, right - left);
            if (isPalindrome(substring)) {
                ++count;
                left = right;
                found = true;
                break;
            }
        }
        if (!found) {
            ++left;
        }
    }
    return count;
}

