long long minimumFuelCost(const std::vector<std::vector<int>>& roads, int seats) {
    std::vector<std::vector<int>> graph(roads.size() + 1);
    for (const auto& edge : roads) {
        int u = edge[0];
        int v = edge[1];
        graph[u].push_back(v);
        graph[v].push_back(u);
    }
    long long result = 0;
    std::function<int(int, int)> dfs = [&](int node, int parent) -> int {
        int count = 1;
        for (int child : graph[node]) {
            if (child == parent) continue;
            count += dfs(child, node);
        }
        if (node > 0) result += (count + seats - 1) / seats;
        return count;
    };
    dfs(0, -1);
    return result;
}

#include <bits/stdc++.h>

int countPalindromicSubsequences(const std::string& s) {
    const int MOD = 1000000007;
    int n = static_cast<int>(s.size());
    using PairArr = std::array<std::array<int,10>,10>;

    std::vector<PairArr> rightPairs(n);
    std::array<int,10> cntRight{};
    PairArr curRightPairs{};
    for (int k = n - 1; k >= 0; --k) {
        rightPairs[k] = curRightPairs;
        int d = s[k] - '0';
        for (int d2 = 0; d2 < 10; ++d2) {
            curRightPairs[d][d2] += cntRight[d2];
        }
        ++cntRight[d];
    }

    PairArr leftPairs{};
    std::array<int,10> cntLeft{};
    long long ans = 0;
    for (int k = 0; k < n; ++k) {
        for (int a = 0; a < 10; ++a) {
            for (int b = 0; b < 10; ++b) {
                long long add = static_cast<long long>(leftPairs[a][b]) * rightPairs[k][b][a];
                ans += add;
                if (ans >= (1LL<<62)) ans %= MOD; // prevent overflow
            }
        }
        ans %= MOD;
        int d = s[k] - '0';
        for (int a = 0; a < 10; ++a) {
            leftPairs[a][d] += cntLeft[a];
        }
        ++cntLeft[d];
    }
    return static_cast<int>(ans % MOD);
}

