#include <vector>

std::vector<std::string> splitMessage(const std::string& message, int limit) {
    int msgLen = static_cast<int>(message.size());
    auto digits = [](int x) { return static_cast<int>(std::to_string(x).size()); };
    for (int n = 1; ; ++n) {
        int maxSuffix = 3 + digits(n) + digits(n);
        if (maxSuffix > limit) break;
        long long total = 0;
        bool invalid = false;
        for (int i = 1; i <= n; ++i) {
            int suffixLen = 3 + digits(i) + digits(n);
            int contentLen = limit - suffixLen;
            if (contentLen < 0) { invalid = true; break; }
            total += contentLen;
        }
        if (invalid) continue;
        if (total >= msgLen) {
            std::vector<std::string> result;
            int idx = 0;
            for (int i = 1; i <= n; ++i) {
                int suffixLen = 3 + digits(i) + digits(n);
                int contentLen = limit - suffixLen;
                int take = std::min(contentLen, msgLen - idx);
                std::string suffix = "<" + std::to_string(i) + "/" + std::to_string(n) + ">";
                result.push_back(message.substr(idx, take) + suffix);
                idx += take;
            }
            return result;
        }
    }
    return std::vector<std::string>();
}

#include <bits/stdc++.h>

std::vector<int> maxPoints(const std::vector<std::vector<int>>& grid, const std::vector<int>& queries) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    int total = m * n;
    struct Cell { int val; int r; int c; };
    std::vector<Cell> cells;
    cells.reserve(total);
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            cells.push_back({grid[i][j], i, j});
        }
    }
    std::sort(cells.begin(), cells.end(), [](const Cell& a, const Cell& b) { return a.val < b.val; });

    struct Query { int val; int idx; };
    std::vector<Query> qs;
    qs.reserve(queries.size());
    for (int i = 0; i < (int)queries.size(); ++i) {
        qs.push_back({queries[i], i});
    }
    std::sort(qs.begin(), qs.end(), [](const Query& a, const Query& b) { return a.val < b.val; });

    std::vector<int> answer(queries.size(), 0);
    std::vector<int> parent(total), sz(total, 1);
    std::vector<char> active(total, 0);
    for (int i = 0; i < total; ++i) parent[i] = i;

    std::function<int(int)> find = [&](int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    auto unite = [&](int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) std::swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
    };

    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};

    int cellIdx = 0;
    for (const auto& q : qs) {
        while (cellIdx < total && cells[cellIdx].val < q.val) {
            int r = cells[cellIdx].r;
            int c = cells[cellIdx].c;
            int id = r * n + c;
            active[id] = 1;
            for (int d = 0; d < 4; ++d) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    int nid = nr * n + nc;
                    if (active[nid]) unite(id, nid);
                }
            }
            ++cellIdx;
        }
        int startId = 0;
        if (active[startId]) {
            answer[q.idx] = sz[find(startId)];
        } else {
            answer[q.idx] = 0;
        }
    }
    return answer;
}

#include <bits/stdc++.h>
struct TreeNode {
    int val; TreeNode* left; TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};
int minimumOperations(TreeNode* root) {
    if (!root) return 0;
    int result = 0;
    std::queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        int levelSize = static_cast<int>(q.size());
        std::vector<int> levelValues;
        levelValues.reserve(levelSize);
        for (int i = 0; i < levelSize; ++i) {
            TreeNode* node = q.front(); q.pop();
            levelValues.push_back(node->val);
            if (node->left) q.push(node->left);
            if (node->right) q.push(node->right);
        }
        std::vector<int> sortedLevelValues = levelValues;
        std::sort(sortedLevelValues.begin(), sortedLevelValues.end());
        std::unordered_map<int,int> indexMapping;
        for (int i = 0; i < levelSize; ++i) indexMapping[levelValues[i]] = i;
        std::vector<bool> visited(levelSize, false);
        for (int i = 0; i < levelSize; ++i) {
            if (visited[i] || levelValues[i] == sortedLevelValues[i]) continue;
            int cycleSize = 0, j = i;
            while (!visited[j]) { visited[j]=true; j=indexMapping[sortedLevelValues[j]]; ++cycleSize; }
            result += (cycleSize - 1);
        }
    }
    return result;
}

#include <bits/stdc++.h>

long long numberOfBeautifulPartitions(const std::string& s, int k, int minLength) {
    const long long MOD = 1000000007LL;
    int n = static_cast<int>(s.size());
    if (n == 0) return 0;
    auto isPrimeDigit = [&](char c) -> bool {
        return c == '2' || c == '3' || c == '5' || c == '7';
    };
    auto isNonPrimeDigit = [&](char c) -> bool {
        return !(c == '2' || c == '3' || c == '5' || c == '7');
    };
    if (!isPrimeDigit(s[0])) return 0;
    std::vector<long long> dpPrev(n, 0), dpCurr(n, 0);
    for (int i = minLength - 1; i < n; ++i) {
        if (isNonPrimeDigit(s[i])) dpPrev[i] = 1;
    }
    for (int part = 2; part <= k; ++part) {
        std::vector<long long> prefixAdd(n, 0);
        for (int start = 1; start < n; ++start) {
            long long add = isPrimeDigit(s[start]) ? dpPrev[start - 1] : 0;
            prefixAdd[start] = (prefixAdd[start - 1] + add) % MOD;
        }
        std::fill(dpCurr.begin(), dpCurr.end(), 0);
        for (int i = 0; i < n; ++i) {
            if (!isNonPrimeDigit(s[i])) continue;
            int maxStart = i - minLength + 1;
            if (maxStart < 1) continue;
            dpCurr[i] = prefixAdd[maxStart];
        }
        dpPrev.swap(dpCurr);
    }
    return dpPrev[n - 1] % MOD;
}

#include <bits/stdc++.h>

std::vector<int> cycleLengthQueries(int n, const std::vector<std::vector<int>>& queries) {
    auto depth = [&](int node) -> int {
        int d = 0;
        while (node > 1) {
            node >>= 1;
            ++d;
        }
        return d;
    };
    std::vector<int> ans;
    ans.reserve(queries.size());
    for (const auto& q : queries) {
        int a = q[0];
        int b = q[1];
        int depthA = depth(a);
        int depthB = depth(b);
        int aa = a, bb = b;
        int da = depthA, db = depthB;
        while (da > db) {
            aa >>= 1;
            --da;
        }
        while (db > da) {
            bb >>= 1;
            --db;
        }
        while (aa != bb) {
            aa >>= 1;
            bb >>= 1;
            --da;
        }
        int lcaDepth = da;
        int cycleLen = (depthA - lcaDepth) + (depthB - lcaDepth) + 1;
        ans.push_back(cycleLen);
    }
    return ans;
}

