long long maxStarSum(const std::vector<int>& vals, const std::vector<std::vector<int>>& edges, int k) {
    std::vector<std::vector<int>> graph(vals.size());
    for (const auto& e : edges) {
        int a = e[0];
        int b = e[1];
        graph[a].push_back(b);
        graph[b].push_back(a);
    }
    long long maxSum = std::numeric_limits<long long>::lowest();
    for (size_t i = 0; i < vals.size(); ++i) {
        std::vector<int>& neighbors = graph[i];
        std::sort(neighbors.begin(), neighbors.end(),
                  [&](int a, int b) { return vals[a] > vals[b]; });
        long long sum = vals[i];
        int limit = std::min(k, static_cast<int>(neighbors.size()));
        for (int j = 0; j < limit; ++j) {
            sum += vals[neighbors[j]];
        }
        if (sum > maxSum) {
            maxSum = sum;
        }
    }
    return maxSum;
}

