int minCommonValue(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    std::size_t i = 0, j = 0;
    while (i < nums1.size() && j < nums2.size()) {
        if (nums1[i] == nums2[j]) return nums1[i];
        if (nums1[i] < nums2[j]) ++i;
        else ++j;
