#include <bits/stdc++.h>

long long minOperations(const std::vector<long long>& nums1, const std::vector<long long>& nums2, long long k) {
    if (k == 0) {
        for (std::size_t i = 0; i < nums1.size(); ++i) {
            if (nums1[i] != nums2[i]) return -1;
        }
        return 0;
    }
    long long pos = 0, neg = 0;
    for (std::size_t i = 0; i < nums1.size(); ++i) {
        long long diff = nums1[i] - nums2[i];
        if (diff % k != 0) return -1;
        long long d = diff / k;
        if (d > 0) pos += d;
        else if (d < 0) neg -= d;
    }
    if (pos != neg) return -1;
    return pos;
}

