long long maxDifferenceBetweenMaxAndMinPriceSum(int n, const std::vector<std::vector<int>>& edges, const std::vector<int>& price) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    std::vector<long long> dist(n);
    auto computeDist = [&](int src, std::vector<long long>& d) {
        std::fill(d.begin(), d.end(), LLONG_MIN);
        d[src] = price[src];
        std::stack<int> st;
        st.push(src);
        while (!st.empty()) {
            int u = st.top();
            st.pop();
            for (int v : adj[u]) {
                if (d[v] == LLONG_MIN) {
                    d[v] = d[u] + price[v];
                    st.push(v);
                }
            }
        }
    };

    computeDist(0, dist);
    int A = 0;
    for (int i = 1; i < n; ++i) {
        if (dist[i] > dist[A]) A = i;
    }

    std::vector<long long> distA(n);
    computeDist(A, distA);
    int B = A;
    for (int i = 0; i < n; ++i) {
        if (distA[i] > distA[B]) B = i;
    }

    std::vector<long long> distB(n);
    computeDist(B, distB);

    long long answer = 0;
    for (int i = 0; i < n; ++i) {
        long long best = std::max(distA[i], distB[i]) - price[i];
        if (best > answer) answer = best;
    }
    return answer;
}

