std::size_t distinctNumbersOnBoard(long long n) {
    if (n < 2) return 1;
    std::unordered_set<long long> visited;
    visited.insert(n);
    std::vector<long long> stack = {n};
    while (!stack.empty()) {
        long long x = stack.back(); stack.pop_back();
        long long m = x - 1;
        if (m < 2) continue;
        for (long long d = 2; d * d <= m; ++d) {
            if (m % d == 0) {
                if (!visited.count(d)) { visited.insert(d); stack.push_back(d); }
                long long other = m / d;
                if (other != d && !visited.count(other)) { visited.insert(other); stack.push_back(other); }
            }
        }
        if (!visited.count(m)) { visited.insert(m); stack.push_back(m); }
    }
    return visited.size();
}

