const long long MOD = 1000000007LL;

long long modPow(long long base, long long exp) {
    long long result = 1 % MOD;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1LL) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1LL;
    }
    return result;
}

long long monkeyMove(long long n) {
    long long total = modPow(2LL, n);
    long long ans = (total - 2LL) % MOD;
    if (ans < 0) ans += MOD;
    return ans;
}

