long long maxScore(const std::vector<int>& nums1, const std::vector<int>& nums2, int k) {
    int n = static_cast<int>(nums1.size());
    std::vector<int> order(n);
    std::iota(order.begin(), order.end(), 0);
    std::sort(order.begin(), order.end(), [&](int a, int b) {
        return nums2[a] > nums2[b];
    });

    std::priority_queue<long long, std::vector<long long>, std::greater<long long>> heap;
    long long sum = 0;
    long long best = 0;

    for (int i = 0; i < n; ++i) {
        int idx = order[i];
        long long v = nums1[idx];
        heap.push(v);
        sum += v;

        if (static_cast<int>(heap.size()) > k) {
            sum -= heap.top();
            heap.pop();
        }

        if (static_cast<int>(heap.size()) == k) {
            long long score = sum * static_cast<long long>(nums2[idx]);
            if (score > best) best = score;
        }
    }
    return best;
}

