bool isPossibleToDisconnect(std::vector<std::vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();
    int L = m + n - 2;
    std::vector<std::vector<char>> fromStart(m, std::vector<char>(n, 0));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (!grid[i][j]) continue;
            if (i == 0 && j == 0) {
                fromStart[i][j] = 1;
            } else {
                if (i > 0 && fromStart[i - 1][j]) fromStart[i][j] = 1;
                if (j > 0 && fromStart[i][j - 1]) fromStart[i][j] = 1;
            }
        }
    }
    if (!fromStart[m - 1][n - 1]) return true;
    std::vector<int> cnt(L + 1, 0);
    std::vector<std::vector<char>> toEnd(m, std::vector<char>(n, 0));
    for (int i = m - 1; i >= 0; --i) {
        for (int j = n - 1; j >= 0; --j) {
            if (!grid[i][j]) continue;
            if (i == m - 1 && j == n - 1) {
                toEnd[i][j] = 1;
            } else {
                if (i + 1 < m && toEnd[i + 1][j]) toEnd[i][j] = 1;
                if (j + 1 < n && toEnd[i][j + 1]) toEnd[i][j] = 1;
            }
            if (fromStart[i][j] && toEnd[i][j]) {
                ++cnt[i + j];
            }
        }
    }
    for (int k = 1; k < L; ++k) {
        if (cnt[k] == 1) return true;
    }
    return false;
}

#include <bits/stdc++.h>

long long minimumImpossibleOR(const std::vector<long long>& nums) {
    long long maxOr = 0;
    for (long long v : nums) {
        maxOr |= v;
    }
    if (maxOr == 0) {
        return 1;
    }
    int maxBit = 0;
    while ((1LL << maxBit) <= maxOr) {
        ++maxBit;
    }
    if (maxBit <= 20) {
        int size = 1 << maxBit;
        std::vector<long long> dp(size, 0);
        for (long long v : nums) {
            dp[static_cast<int>(v)] |= v;
        }
        for (int i = 0; i < maxBit; ++i) {
            for (int mask = 0; mask < size; ++mask) {
                if (mask & (1 << i)) {
                    dp[mask] |= dp[mask ^ (1 << i)];
                }
            }
        }
        for (long long x = 1; x <= maxOr + 1; ++x) {
            if (dp[static_cast<int>(x)] != x) {
                return x;
            }
        }
        return maxOr + 1;
    } else {
        std::unordered_set<long long> reachable;
        reachable.reserve(nums.size() * 2);
        reachable.insert(0);
        for (long long v : nums) {
            std::vector<long long> add;
            add.reserve(reachable.size());
            for (long long cur : reachable) {
                add.push_back(cur | v);
            }
            for (long long val : add) {
                reachable.insert(val);
            }
        }
        for (long long x = 1;; ++x) {
            if (!reachable.count(x)) {
                return x;
            }
        }
    }
}

#include <bits/stdc++.h>
#include <vector>
#include <cmath>

long long takeGifts(const std::vector<int>& gifts, int k) {
    std::vector<int> heap;

    auto heapSwap = [&](size_t i, size_t j) {
        int tmp = heap[i];
        heap[i] = heap[j];
        heap[j] = tmp;
    };

    auto heapPush = [&](int val) {
        heap.push_back(val);
        size_t idx = heap.size() - 1;
        while (idx > 0) {
            size_t parent = (idx - 1) >> 1;
            if (heap[parent] >= heap[idx]) break;
            heapSwap(parent, idx);
            idx = parent;
        }
    };

    auto heapPop = [&]() -> int {
        int top = heap[0];
        int last = heap.back();
        heap.pop_back();
        if (!heap.empty()) {
            heap[0] = last;
            size_t idx = 0;
            while (true) {
                size_t left = idx * 2 + 1;
                size_t right = left + 1;
                size_t largest = idx;
                if (left < heap.size() && heap[left] > heap[largest]) largest = left;
                if (right < heap.size() && heap[right] > heap[largest]) largest = right;
                if (largest == idx) break;
                heapSwap(idx, largest);
                idx = largest;
            }
        }
        return top;
    };

    for (int v : gifts) heapPush(v);

    for (int i = 0; i < k; ++i) {
        int mx = heapPop();
        int newVal = static_cast<int>(std::sqrt(mx));
        heapPush(newVal);
        if (mx == 1) break;
    }

    long long total = 0;
    for (int v : heap) total += v;
    return total;
}

#include <bits/stdc++.h>

std::vector<long long> handleSumQueries(const std::vector<int>& nums1, const std::vector<int>& nums2, const std::vector<std::vector<int>>& queries) {
    int n = static_cast<int>(nums1.size());
    std::vector<int> tree(4 * n);
    std::vector<char> lazy(4 * n, 0);

    std::function<void(int,int,int)> build = [&](int idx, int l, int r) {
        if (l == r) {
            tree[idx] = nums1[l];
            return;
        }
        int mid = (l + r) >> 1;
        build(idx << 1, l, mid);
        build(idx << 1 | 1, mid + 1, r);
        tree[idx] = tree[idx << 1] + tree[idx << 1 | 1];
    };

    auto applyFlip = [&](int idx, int l, int r) {
        tree[idx] = (r - l + 1) - tree[idx];
        lazy[idx] ^= 1;
    };

    std::function<void(int,int,int)> push = [&](int idx, int l, int r) {
        if (!lazy[idx]) return;
        int mid = (l + r) >> 1;
        applyFlip(idx << 1, l, mid);
        applyFlip(idx << 1 | 1, mid + 1, r);
        lazy[idx] = 0;
    };

    std::function<void(int,int,int,int,int)> flipRange = [&](int idx, int l, int r, int ql, int qr) {
        if (qr < l || r < ql) return;
        if (ql <= l && r <= qr) {
            applyFlip(idx, l, r);
            return;
        }
        push(idx, l, r);
        int mid = (l + r) >> 1;
        flipRange(idx << 1, l, mid, ql, qr);
        flipRange(idx << 1 | 1, mid + 1, r, ql, qr);
        tree[idx] = tree[idx << 1] + tree[idx << 1 | 1];
    };

    if (n > 0) build(1, 0, n - 1);

    long long sumNums2 = 0;
    for (int v : nums2) sumNums2 += v;

    std::vector<long long> answer;
    for (const auto& q : queries) {
        int type = q[0];
        if (type == 1) {
            if (n > 0) {
                int left = q[1];
                int right = q[2];
                flipRange(1, 0, n - 1, left, right);
            }
        } else if (type == 2) {
            long long val = q[1];
            long long ones = (n > 0) ? tree[1] : 0;
            sumNums2 += val * ones;
        } else if (type == 3) {
            answer.push_back(sumNums2);
        }
    }
    return answer;
}

