int minOperations(int n) {
    int cnt = 0;
    while (n > 0) {
        if ((n & 1) == 0) {
            n >>= 1;
        } else {
            ++cnt;
            if (n % 4 == 1) {
                n = (n - 1) >> 1;
            } else if (n % 4 == 3 && n != 3) {
                n = (n + 1) >> 1;
            } else {
                n = (n - 1) >> 1;
            }
        }
    }
    return cnt;
}

