std::vector<std::vector<int>> mergeArrays(const std::vector<std::vector<int>>& nums1, const std::vector<std::vector<int>>& nums2) {
    std::vector<std::vector<int>> merged;
    std::size_t i = 0, j = 0;
    std::size_t n1 = nums1.size(), n2 = nums2.size();

    while (i < n1 && j < n2) {
        int id1 = nums1[i][0];
        int val1 = nums1[i][1];
        int id2 = nums2[j][0];
        int val2 = nums2[j][1];

        if (id1 == id2) {
            merged.push_back({id1, val1 + val2});
            ++i;
            ++j;
        } else if (id1 < id2) {
            merged.push_back({id1, val1});
            ++i;
        } else {
            merged.push_back({id2, val2});
            ++j;
        }
    }

    while (i < n1) {
        merged.push_back(nums1[i]);
        ++i;
    }

    while (j < n2) {
        merged.push_back(nums2[j]);
        ++j;
    }

    return merged;
}

