long long minTime(const std::vector<std::vector<int>>& grid) {
    int m = grid.size(), n = grid[0].size();
    vector<vector<long long>> dist(m, vector<long long>(n, LLONG_MAX));
    vector<pair<int,int>> dirs = {{1,0},{-1,0},{0,1},{0,-1}};
    long long startTime = max(0, grid[0][0]);
    dist[0][0] = startTime;
    priority_queue<tuple<long long,int,int>, vector<tuple<long long,int,int>>, greater<>> pq;
    pq.push({startTime, 0, 0});
    while (!pq.empty()) {
        auto [time, r, c] = pq.top(); pq.pop();
        if (time != dist[r][c]) continue;
        if (r == m-1 && c == n-1) return time;
        for (auto& [dr, dc] : dirs) {
            int nr = r+dr, nc = c+dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                long long arrival = time + 1;
                if (arrival >= grid[nr][nc]) {
                    if (arrival < dist[nr][nc]) {
                        dist[nr][nc] = arrival;
                        pq.push({arrival, nr, nc});
                    }
                }
            }
        }
    }
    return -1;
}

