    std::vector<int> rowOnes(m, 0);
    std::vector<int> colOnes(n, 0);
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 1) {
                ++rowOnes[i];
                ++colOnes[j];
