long long countWays(std::vector<std::vector<long long>> ranges) {
    const long long MOD = 1000000007LL;
    std::sort(ranges.begin(), ranges.end(),
        [](const std::vector<long long>& a, const std::vector<long long>& b) {
            if (a[0] != b[0]) return a[0] < b[0];
            return a[1] < b[1];
        });
    long long components = 0;
    long long curEnd = std::numeric_limits<long long>::min();
    for (size_t i = 0; i < ranges.size(); ++i) {
        long long s = ranges[i][0];
        long long e = ranges[i][1];
        if (s > curEnd) {
            ++components;
            curEnd = e;
        } else {
            if (e > curEnd) curEnd = e;
        }
    }
    long long ans = 1;
    for (long long i = 0; i < components; ++i) {
        ans = (ans * 2) % MOD;
    }
    return ans;
}

