    if (n == 0) return "";
    // basic validation
    for (int i = 0; i < n; ++i) {
        if ((int)lcp[i].size() != n) return "";
        if (lcp[i][i] != n - i) return "";
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (lcp[i][j] != lcp[j][i]) return "";
            int maxLen = std::min(n - i, n - j);
            if (lcp[i][j] < 0 || lcp[i][j] > maxLen) return "";
            if (lcp[i][j] > 0 && i + 1 < n && j + 1 < n) {
                if (lcp[i + 1][j + 1] != lcp[i][j] - 1) return "";
            }
        }
    }

    // DSU for equality constraints
    struct DSU {
        std::vector<int> p, r;
        DSU(int n = 0) : p(n), r(n, 0) { std::iota(p.begin(), p.end(), 0); }
        int find(int x) { return p[x] == x ? x : p[x] = find(p[x]); }
        void unite(int a, int b) {
            a = find(a); b = find(b);
            if (a == b) return;
            if (r[a] < r[b]) std::swap(a, b);
            p[b] = a;
            if (r[a] == r[b]) ++r[a];
        }
    };
    DSU dsu(n);
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (lcp[i][j] > 0) dsu.unite(i, j);
        }
    }

    // Build inequality graph
    std::vector<std::vector<int>> adj(n);
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            int k = lcp[i][j];
            int maxLen = std::min(n - i, n - j);
            if (k < maxLen) {
                int a = dsu.find(i + k);
                int b = dsu.find(j + k);
                if (a == b) return "";
                adj[a].push_back(b);
                adj[b].push_back(a);
            }
        }
    }

    // Assign letters greedily
    std::vector<char> compChar(n, 0);
    std::string ans;
    ans.reserve(n);
    for (int i = 0; i < n; ++i) {
        int root = dsu.find(i);
        if (compChar[root] == 0) {
            bool used[26] = {false};
            for (int nb : adj[root]) {
                if (compChar[nb] != 0) used[compChar[nb] - 'a'] = true;
            }
            int c = 0;
            while (c < 26 && used[c]) ++c;
            if (c == 26) return "";
            compChar[root] = char('a' + c);
        }
        ans.push_back(compChar[root]);
    }
    return ans;
}

#include <bits/stdc++.h>

int rootCount(std::vector<std::vector<int>>& edges, std::vector<std::vector<int>>& guesses, int k) {
    int n = static_cast<int>(edges.size()) + 1;
    struct Edge {int to; bool guessFromParent; bool guessToParent;};
    std::vector<std::vector<Edge>> adj(n);
    std::unordered_set<long long> guessSet;
    guessSet.reserve(guesses.size() * 2);
    for (const auto& g : guesses) {
        long long key = static_cast<long long>(g[0]) * n + g[1];
        guessSet.insert(key);
    }
    for (const auto& e : edges) {
        int a = e[0], b = e[1];
        bool gab = guessSet.find(static_cast<long long>(a) * n + b) != guessSet.end();
        bool gba = guessSet.find(static_cast<long long>(b) * n + a) != guessSet.end();
        adj[a].push_back({b, gab, gba});
        adj[b].push_back({a, gba, gab});
    }
    int initCount = 0;
    std::vector<int> parent(n, -1);
    std::stack<int> st;
    st.push(0);
    parent[0] = -2;
    while (!st.empty()) {
        int u = st.top(); st.pop();
        for (const auto& e : adj[u]) {
            int v = e.to;
            if (parent[v] != -1) continue;
            parent[v] = u;
            if (e.guessFromParent) ++initCount;
            st.push(v);
        }
    }
    int ans = 0;
    std::stack<std::tuple<int,int,int>> st2;
    st2.emplace(0, -1, initCount);
    while (!st2.empty()) {
        auto tup = st2.top(); st2.pop();
        int u = std::get<0>(tup);
        int p = std::get<1>(tup);
        int cur = std::get<2>(tup);
        if (cur >= k) ++ans;
        for (const auto& e : adj[u]) {
            int v = e.to;
            if (v == p) continue;
            int newCur = cur - (e.guessFromParent ? 1 : 0) + (e.guessToParent ? 1 : 0);
            st2.emplace(v, u, newCur);
        }
    }
    return ans;
}

