int numberOfWays(int target, std::vector<std::vector<int>>& types) {
    const int MOD = 1000000007;
    std::vector<int> dp(target + 1, 0);
    dp[0] = 1;
    for (const auto& tp : types) {
        int cnt = tp[0];
        int marks = tp[1];
        std::vector<int> ndp(target + 1, 0);
        for (int r = 0; r < marks; ++r) {
            long long sum = 0;
            int steps = 0;
            for (int j = r; j <= target; j += marks, ++steps) {
                sum += dp[j];
                if (sum >= MOD) sum -= MOD;
                if (steps > cnt) {
                    sum -= dp[j - (cnt + 1) * marks];
                    if (sum < 0) sum += MOD;
                }
                ndp[j] = static_cast<int>(sum);
            }
        }
        dp.swap(ndp);
    }
    return dp[target];
}

