    std::sort(digits.begin(), digits.end());
    std::string a, b;
    a.reserve(digits.size() / 2 + 1);
    b.reserve(digits.size() / 2 + 1);
    for (size_t i = 0; i < digits.size(); ++i) {
        if (i % 2 == 0) {
            a.push_back('0' + digits[i]);
        } else {
            b.push_back('0' + digits[i]);
        }
    }
    long long valA = a.empty() ? 0 : std::stoll(a);
    long long valB = b.empty() ? 0 : std::stoll(b);
    return valA + valB;
}

