int minTime(std::vector<std::vector<int>>& tasks) {
    std::sort(tasks.begin(), tasks.end(),
        [](const std::vector<int>& a, const std::vector<int>& b) {
            if (a[1] != b[1]) return a[1] < b[1];
            return a[0] < b[0];
        });
    std::unordered_set<int> occupiedTimes;
    int total = 0;
    for (const auto& task : tasks) {
        int l = task[0];
        int r = task[1];
        int d = task[2];
        int already = 0;
        for (int t = r; t >= l; --t) {
            if (occupiedTimes.find(t) != occupiedTimes.end()) {
                ++already;
            }
        }
        int need = d - already;
        if (need <= 0) continue;
        for (int t = r; t >= l && need > 0; --t) {
            if (occupiedTimes.find(t) == occupiedTimes.end()) {
                occupiedTimes.insert(t);
                ++total;
                --need;
            }
        }
    }
    return total;
}

