long long minRepairTime(const std::vector<int>& ranks, int cars) {
    long long low = 0;
    int minRank = *std::min_element(ranks.begin(), ranks.end());
    long long high = static_cast<long long>(minRank) * cars * cars;
    while (low < high) {
        long long mid = (low + high) / 2;
        long long total = 0;
        for (size_t i = 0; i < ranks.size(); ++i) {
            total += static_cast<long long>(std::floor(std::sqrt(static_cast<double>(mid) / ranks[i])));
            if (total >= cars) break;
        }
        if (total >= cars) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

