long long beautifulSubsets(const std::vector<long long>& nums, long long k) {
    std::vector<long long> a(nums);
    std::sort(a.begin(), a.end());
    std::vector<std::pair<long long, long long>> vals;
    for (size_t i = 0; i < a.size(); ) {
        size_t j = i;
        while (j < a.size() && a[j] == a[i]) ++j;
        vals.emplace_back(a[i], static_cast<long long>(j - i));
        i = j;
    }
    long long totalWays = 1;
    size_t i = 0;
    while (i < vals.size()) {
        long long dpPrevPrev = 1;
        long long w0 = (1LL << vals[i].second) - 1;
        long long dpPrev = 1 + w0;
        ++i;
        while (i < vals.size() && vals[i].first - vals[i - 1].first == k) {
            long long w = (1LL << vals[i].second) - 1;
            long long cur = dpPrev + dpPrevPrev * w;
            dpPrevPrev = dpPrev;
            dpPrev = cur;
            ++i;
        }
        totalWays *= dpPrev;
    }
    return totalWays - 1;
}

