struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

long long kthLargestLevelSum(TreeNode* root, int k) {
    if (!root) return -1;

    std::vector<TreeNode*> queue;
    queue.push_back(root);
    size_t head = 0;
    std::vector<long long> minHeap;

    auto heapPush = [&](long long val) {
        minHeap.push_back(val);
        size_t i = minHeap.size() - 1;
        while (i > 0) {
            size_t p = (i - 1) >> 1;
            if (minHeap[p] <= minHeap[i]) break;
            std::swap(minHeap[p], minHeap[i]);
            i = p;
        }
    };

    auto heapReplaceRoot = [&](long long val) {
        minHeap[0] = val;
        size_t i = 0;
        while (true) {
            size_t l = i * 2 + 1;
            size_t r = i * 2 + 2;
            size_t smallest = i;
            if (l < minHeap.size() && minHeap[l] < minHeap[smallest]) smallest = l;
            if (r < minHeap.size() && minHeap[r] < minHeap[smallest]) smallest = r;
            if (smallest == i) break;
            std::swap(minHeap[i], minHeap[smallest]);
            i = smallest;
        }
    };

    while (head < queue.size()) {
        size_t levelSize = queue.size() - head;
        long long levelSum = 0;
        for (size_t i = 0; i < levelSize; ++i) {
            TreeNode* node = queue[head++];
            levelSum += node->val;
            if (node->left) queue.push_back(node->left);
            if (node->right) queue.push_back(node->right);
        }
        if (minHeap.size() < static_cast<size_t>(k)) {
            heapPush(levelSum);
        } else if (levelSum > minHeap[0]) {
            heapReplaceRoot(levelSum);
        }
    }

    return minHeap.size() == static_cast<size_t>(k) ? minHeap[0] : -1;
}

