bool primeSubOperation(std::vector<int>& nums) {
    if (nums.empty()) return true;
    int maxVal = 0;
    for (int v : nums) {
        if (v > maxVal) maxVal = v;
    }
    int limit = std::max(2, maxVal);
    std::vector<char> isPrime(limit + 1, true);
    isPrime[0] = isPrime[1] = false;
    for (int p = 2; p * p <= limit; ++p) {
        if (isPrime[p]) {
            for (int multiple = p * p; multiple <= limit; multiple += p) {
                isPrime[multiple] = false;
            }
        }
    }
    std::vector<int> nextPrime(limit + 2, limit + 1);
    for (int i = limit; i >= 0; --i) {
        nextPrime[i] = isPrime[i] ? i : nextPrime[i + 1];
    }

    for (int i = static_cast<int>(nums.size()) - 2; i >= 0; --i) {
        if (nums[i] < nums[i + 1]) continue;
        int minP = nums[i] - (nums[i + 1] - 1);
        if (minP < 2) minP = 2;
        int upper = nums[i] - 1;
        if (minP > upper) return false;
        int p = nextPrime[minP];
        if (p > upper) return false;
        nums[i] = nums[i + 1] - 1;
    }
    return true;
}

