bool checkValidKnightTour(const std::vector<std::vector<int>>& grid) {
    int n = static_cast<int>(grid.size());
    int total = n * n;
    std::vector<std::pair<int, int>> pos(total);
    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < n; ++c) {
            int v = grid[r][c];
            if (v < 0 || v >= total) return false;
            pos[v] = {r, c};
        }
    }
    if (grid[0][0] != 0) return false;
    for (int k = 0; k < total - 1; ++k) {
        int r1 = pos[k].first;
        int c1 = pos[k].second;
        int r2 = pos[k + 1].first;
        int c2 = pos[k + 1].second;
        int dr = std::abs(r1 - r2);
        int dc = std::abs(c1 - c2);
        bool ok = (dr == 1 && dc == 2) || (dr == 2 && dc == 1);
        if (!ok) return false;
    }
    return true;
}

