std::vector<long long> minOperations(const std::vector<int>& nums, const std::vector<int>& queries) {
    size_t n = nums.size();
    std::vector<long long> sorted(n);
    for (size_t i = 0; i < n; ++i) sorted[i] = nums[i];
    std::sort(sorted.begin(), sorted.end());
    std::vector<long long> pref(n);
    long long sum = 0;
    for (size_t i = 0; i < n; ++i) {
        sum += sorted[i];
        pref[i] = sum;
    }
    long long total = sum;

    std::vector<long long> res(queries.size());
    for (size_t qi = 0; qi < queries.size(); ++qi) {
        long long t = queries[qi];
        size_t lo = 0, hi = n;
        while (lo < hi) {
            size_t mid = (lo + hi) >> 1;
            if (sorted[mid] <= t) lo = mid + 1;
            else hi = mid;
        }
        size_t k = lo;
        long long left = (k == 0) ? 0 : t * static_cast<long long>(k) - pref[k - 1];
        long long right = (k == n) ? 0 : (total - (k == 0 ? 0 : pref[k - 1])) - t * static_cast<long long>(n - k);
        res[qi] = left + right;
    }
    return res;
}

