#include <bits/stdc++.h>
int collectCoinsInTree(const std::vector<int>& coins, const std::vector<std::vector<int>>& edges) {
    int n = static_cast<int>(coins.size());
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int a = e[0], b = e[1];
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    std::vector<int> degree(n);
    for (int i = 0; i < n; ++i) degree[i] = static_cast<int>(adj[i].size());
    std::vector<char> removed(n, 0);
    std::deque<int> q;
    for (int i = 0; i < n; ++i) {
        if (degree[i] == 1 && coins[i] == 0) q.push_back(i);
    }
    while (!q.empty()) {
        int u = q.front(); q.pop_front();
        if (removed[u]) continue;
        removed[u] = 1;
        for (int v : adj[u]) {
            if (removed[v]) continue;
            if (--degree[v] == 1 && coins[v] == 0) q.push_back(v);
        }
    }
    std::deque<std::pair<int,int>> bfs;
    for (int i = 0; i < n; ++i) {
        if (!removed[i] && degree[i] == 1) bfs.emplace_back(i, 0);
    }
    while (!bfs.empty()) {
        auto p = bfs.front(); bfs.pop_front();
        int u = p.first;
        int d = p.second;
        if (removed[u] || d == 2) continue;
        removed[u] = 1;
        for (int v : adj[u]) {
            if (removed[v]) continue;
            if (--degree[v] == 1) bfs.emplace_back(v, d + 1);
        }
    }
    int remaining = 0;
    for (int i = 0; i < n; ++i) if (!removed[i]) ++remaining;
    return remaining;
}

