#include <unordered_map>

std::vector<std::vector<int>> convertArray(const std::vector<int>& nums) {
    std::unordered_map<int, int> freq;
    std::vector<int> order;
    int maxFreq = 0;
    for (int v : nums) {
        if (freq.find(v) == freq.end()) {
            order.push_back(v);
        }
        int f = ++freq[v];
        if (f > maxFreq) maxFreq = f;
    }
    if (maxFreq == 0) {
        return {};
    }
    std::vector<std::vector<int>> rows(maxFreq);
    for (int v : order) {
        int cnt = freq[v];
        for (int i = 0; i < cnt; ++i) {
            rows[i].push_back(v);
        }
    }
    if (maxFreq == 1) {
        std::reverse(rows[0].begin(), rows[0].end());
    }
    return rows;
}

