static int gcd_int(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

long long makeKSubarraySumsEqual(std::vector<int>& arr, int k) {
    int n = static_cast<int>(arr.size());
    int g = gcd_int(n, k);
    long long ans = 0;
    int cycleLen = n / g;
    std::vector<long long> vals;
    vals.reserve(cycleLen);
    for (int start = 0; start < g; ++start) {
        vals.clear();
        int idx = start;
        for (int cnt = 0; cnt < cycleLen; ++cnt) {
            vals.push_back(static_cast<long long>(arr[idx]));
            idx = (idx + k) % n;
        }
        int mid = vals.size() / 2;
        std::nth_element(vals.begin(), vals.begin() + mid, vals.end());
        long long median = vals[mid];
        for (long long v : vals) {
            ans += std::llabs(v - median);
        }
    }
    return ans;
}

#include <bits/stdc++.h>

int longestBalancedSubstring(const std::string& s) {
    if (s.empty()) {
        return 0;
    }
    int maxLen = 0;
    int prevRun = 0;
    int curRun = 1;
    for (std::size_t i = 1; i < s.size(); ++i) {
        if (s[i] == s[i - 1]) {
            ++curRun;
        } else {
            int candidate = 2 * std::min(prevRun, curRun);
            if (candidate > maxLen) {
                maxLen = candidate;
            }
            prevRun = curRun;
            curRun = 1;
        }
    }
    int candidate = 2 * std::min(prevRun, curRun);
    if (candidate > maxLen) {
        maxLen = candidate;
    }
    return maxLen;
}

#include <bits/stdc++.h>

std::vector<int> minimumReverseOperations(int n, int p, const std::vector<int>& banned, int k) {
    std::vector<int> answer(n, -1);
    std::vector<int> nxt(n + 2);
    for (int i = 0; i <= n + 1; ++i) nxt[i] = i;

    auto find = [&](int i) {
        if (i >= n) return n;
        int root = i;
        while (root < n && nxt[root] != root) root = nxt[root];
        while (i < n && nxt[i] != i) {
            int parent = nxt[i];
            nxt[i] = root;
            i = parent;
        }
        return root;
    };

    auto remove = [&](int i) {
        nxt[i] = find(i + 2);
    };

    for (int b : banned) remove(b);

    answer[p] = 0;
    remove(p);
    std::vector<int> q;
    q.push_back(p);
    std::size_t head = 0;

    while (head < q.size()) {
        int x = q[head++];
        int dMin = std::max(0, x - (n - k));
        int dMax = std::min(k - 1, x);
        int L = x + (k - 1) - 2 * dMax;
        int R = x + (k - 1) - 2 * dMin;
        if (L < 0) L = 0;
        if (R >= n) R = n - 1;
        if (L > R) continue;
        int cur = find(L);
        while (cur <= R) {
            answer[cur] = answer[x] + 1;
            q.push_back(cur);
            int nxtCur = find(cur + 2);
            nxt[cur] = nxtCur;
            cur = nxtCur;
        }
    }
    return answer;
}

#include <bits/stdc++.h>
int findShortestCycle(int n, const std::vector<std::vector<int>>& edges) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    const int INF = INT_MAX;
    int best = INF;
    for (int s = 0; s < n; ++s) {
        std::vector<int> dist(n, -1), parent(n, -1);
        std::queue<int> q;
        dist[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    parent[v] = u;
                    q.push(v);
                } else if (parent[u] != v) {
                    int cycle_len = dist[u] + dist[v] + 1;
                    if (cycle_len < best) best = cycle_len;
                }
            }
            if (best == 3) return 3; // smallest possible cycle
        }
    }
    return (best == INF) ? -1 : best;
}

