long long maxSum(long long numOnes, long long numZeros, long long numNegOnes, long long k) {
    long long onesTaken = std::min(numOnes, k);
    long long remaining = k - onesTaken;
    long long zerosTaken = std::min(numZeros, remaining);
    remaining -= zerosTaken;
    long long negOnesTaken = remaining;
    return onesTaken - negOnesTaken;
}

#include <bits/stdc++.h>

int minimumVisitedCells(std::vector<std::vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();
    std::vector<std::vector<int>> dist(m, std::vector<int>(n, -1));
    std::vector<std::vector<int>> rowParent(m, std::vector<int>(n + 1));
    std::vector<std::vector<int>> colParent(n, std::vector<int>(m + 1));
    for (int i = 0; i < m; ++i)
        for (int j = 0; j <= n; ++j)
            rowParent[i][j] = j;
    for (int j = 0; j < n; ++j)
        for (int i = 0; i <= m; ++i)
            colParent[j][i] = i;
    std::function<int(int,int)> findRow = [&](int r, int c) -> int {
        if (c > n) return n;
        if (rowParent[r][c] == c) return c;
        return rowParent[r][c] = findRow(r, rowParent[r][c]);
    };
    std::function<int(int,int)> findCol = [&](int c, int r) -> int {
        if (r > m) return m;
        if (colParent[c][r] == r) return r;
        return colParent[c][r] = findCol(c, colParent[c][r]);
    };
    std::queue<std::pair<int,int>> q;
    dist[0][0] = 1;
    q.emplace(0,0);
    rowParent[0][0] = findRow(0,1);
    colParent[0][0] = findCol(0,1);
    while (!q.empty()) {
        auto p = q.front(); q.pop();
        int i = p.first;
        int j = p.second;
        if (i == m-1 && j == n-1) return dist[i][j];
        int limit = grid[i][j];
        int maxCol = std::min(n-1, j + limit);
        int col = findRow(i, j+1);
        while (col <= maxCol) {
            dist[i][col] = dist[i][j] + 1;
            q.emplace(i, col);
            rowParent[i][col] = findRow(i, col+1);
            colParent[col][i] = findCol(col, i+1);
            col = findRow(i, col);
        }
        int maxRow = std::min(m-1, i + limit);
        int row = findCol(j, i+1);
        while (row <= maxRow) {
            dist[row][j] = dist[i][j] + 1;
            q.emplace(row, j);
            colParent[j][row] = findCol(j, row+1);
            rowParent[row][j] = findRow(row, j+1);
            row = findCol(j, row);
        }
    }
    return -1;
}

