long long maxPoints(const std::vector<int>& reward1, const std::vector<int>& reward2, int k) {
    std::size_t n = reward1.size();
    long long base = 0;
    std::vector<long long> diffs(n);
    for (std::size_t i = 0; i < n; ++i) {
        base += reward2[i];
        diffs[i] = static_cast<long long>(reward1[i]) - reward2[i];
    }
    std::sort(diffs.begin(), diffs.end(), std::greater<long long>());
    long long add = 0;
    for (int i = 0; i < k; ++i) {
        add += diffs[i];
    }
    return base + add;
}

