bool isPrime(int n) {
    if (n < 2) return false;
    if (n % 2 == 0) return n == 2;
    for (int i = 3; i * (long long)i <= n; i += 2) {
        if (n % i == 0) return false;
    }
    return true;
}

int largestPrimeDiagonal(const std::vector<std::vector<int>>& nums) {
    int rows = static_cast<int>(nums.size());
    int cols = static_cast<int>(nums[0].size());
    int maxPrime = 0;
    for (int i = 0; i < rows; ++i) {
        if (i < cols) {
            int v = nums[i][i];
            if (v > maxPrime && isPrime(v)) maxPrime = v;
        }
        int j = cols - 1 - i;
        if (j >= 0 && j < cols && j != i) {
            int v = nums[i][j];
            if (v > maxPrime && isPrime(v)) maxPrime = v;
        }
    }
    return maxPrime;
}

