};

struct JSClass {
    JSObject prototype;
};

bool checkIfInstanceOf(JSObject* value, JSClass* cls) {
    if (cls == nullptr) return false;
    if (value == nullptr) return false;
    JSObject* proto = value->__proto;
    JSObject* targetProto = &(cls->prototype);
    while (proto != nullptr) {
        if (proto == targetProto) return true;
        proto = proto->__proto;
    }
    return false;
}

