struct CacheImpl {
    struct Entry {
        int value;
        std::chrono::steady_clock::time_point expire;
    };
    std::unordered_map<int, Entry> map;
    bool set(int key, int value, int duration) {
        auto now = std::chrono::steady_clock::now();
        bool stillValid = false;
        auto it = map.find(key);
        if (it != map.end() && it->second.expire > now) {
            stillValid = true;
        }
        map[key] = {value, now + std::chrono::milliseconds(duration)};
        return stillValid;
    }
    int get(int key) {
        auto now = std::chrono::steady_clock::now();
        auto it = map.find(key);
        if (it != map.end()) {
            if (it->second.expire > now) {
                return it->second.value;
            }
            map.erase(it);
        }
        return -1;
    }
    int count() {
        auto now = std::chrono::steady_clock::now();
        int active = 0;
        for (auto it = map.begin(); it != map.end(); ) {
            if (it->second.expire > now) {
                ++active;
                ++it;
            } else {
                it = map.erase(it);
            }
        }
        return active;
    }
};

CacheImpl TimeLimitedCache() {
    return CacheImpl();
}

#include <bits/stdc++.h>
#include <vector>
#include <unordered_map>

std::vector<long long> sumOfDistances(const std::vector<int>& nums) {
    size_t n = nums.size();
    std::vector<long long> answer(n, 0);
    std::unordered_map<int, std::vector<int>> groups;
    for (size_t i = 0; i < n; ++i) {
        int v = nums[i];
        groups[v].push_back(static_cast<int>(i));
    }
    for (auto& kv : groups) {
        const std::vector<int>& positions = kv.second;
        size_t m = positions.size();
        if (m == 1) continue;
        std::vector<long long> prefix(m, 0);
        for (size_t i = 0; i < m; ++i) {
            prefix[i] = static_cast<long long>(positions[i]) + (i ? prefix[i - 1] : 0);
        }
        long long total = prefix[m - 1];
        for (size_t i = 0; i < m; ++i) {
            long long pos = static_cast<long long>(positions[i]);
            long long leftSum = i ? prefix[i - 1] : 0;
            long long rightSum = total - prefix[i];
            long long leftCnt = static_cast<long long>(i);
            long long rightCnt = static_cast<long long>(m - i - 1);
            answer[static_cast<size_t>(pos)] = pos * leftCnt - leftSum + rightSum - pos * rightCnt;
        }
    }
    return answer;
}

