template <typename Ret, typename... Args>
struct Memoized {
    std::function<Ret(Args...)> fn;
    std::unordered_map<std::string, Ret> cache;
    int callCount = 0;

    Ret operator()(Args... args) {
        std::ostringstream oss;
        ((oss << args << '|'), ...);
        std::string key = oss.str();
        if (!key.empty()) key.pop_back();
        auto it = cache.find(key);
        if (it != cache.end()) {
            return it->second;
        }
        Ret result = fn(args...);
        cache.emplace(key, result);
        ++callCount;
        return result;
    }

    int getCallCount() const {
        return callCount;
    }
};

template <typename Ret, typename... Args>
Memoized<Ret, Args...> memoize(const std::function<Ret(Args...)>& fn) {
    return Memoized<Ret, Args...>{fn};
}

