template <typename T>
std::vector<std::vector<T>> snail(const std::vector<T>& arr, int rowsCount, int colsCount) {
    if (rowsCount <= 0 || colsCount <= 0 ||
        static_cast<std::size_t>(rowsCount) * static_cast<std::size_t>(colsCount) != arr.size()) {
        return {};
    }
    std::vector<std::vector<T>> matrix(rowsCount, std::vector<T>(colsCount));
    std::size_t idx = 0;
    for (int col = 0; col < colsCount; ++col) {
        if (col % 2 == 0) {
            for (int row = 0; row < rowsCount; ++row) {
                matrix[row][col] = arr[idx++];
            }
        } else {
            for (int row = rowsCount - 1; row >= 0; --row) {
                matrix[row][col] = arr[idx++];
            }
        }
    }
    return matrix;
}

