struct Call {
    int t;
    std::vector<int> inputs;
};

struct Result {
    int t;
    std::vector<int> inputs;
};

std::vector<Result> debounce(int interval, const std::vector<Call>& calls) {
    std::vector<Result> output;
    output.reserve(calls.size());
    long long pendingTime = -1;
    std::vector<int> pendingInputs;

    for (const auto& c : calls) {
        if (pendingTime == -1) {
            pendingTime = static_cast<long long>(c.t) + interval;
            pendingInputs = c.inputs;
        } else if (c.t >= pendingTime) {
            output.push_back({static_cast<int>(pendingTime), std::move(pendingInputs)});
            pendingTime = static_cast<long long>(c.t) + interval;
            pendingInputs = c.inputs;
        } else {
            pendingTime = static_cast<long long>(c.t) + interval;
            pendingInputs = c.inputs;
        }
    }

    if (pendingTime != -1) {
        output.push_back({static_cast<int>(pendingTime), std::move(pendingInputs)});
    }

    return output;
}

