struct Node {
    bool isInt;
    int value;
    std::vector<Node> children;
    Node(int v) : isInt(true), value(v) {}
    Node(const std::vector<Node>& c) : isInt(false), value(0), children(c) {}
    Node() : isInt(true), value(0) {}
};

static void flattenHelper(const std::vector<Node>& arr, int depth, int n, std::vector<Node>& out) {
    for (const Node& elem : arr) {
        if (elem.isInt) {
            out.push_back(elem);
        } else {
            if (depth < n) {
                flattenHelper(elem.children, depth + 1, n, out);
            } else {
                out.push_back(elem);
            }
        }
    }
}

std::vector<Node> flatten(const std::vector<Node>& arr, int n) {
    std::vector<Node> result;
    result.reserve(arr.size());
    flattenHelper(arr, 0, n, result);
    return result;
}

