template <typename F>
auto memoize(F fn) {
    struct Node {
        std::unordered_map<std::string, std::unique_ptr<Node>> children;
        bool hasResult = false;
        std::shared_ptr<void> result;
    };
    auto root = std::make_unique<Node>();
    return [fn, root = std::move(root)](auto&&... args) mutable {
        using Return = decltype(fn(args...));
        Node* node = root.get();
        auto process = [&](auto&& arg) {
            std::ostringstream oss;
            oss << arg;
            const std::string key = oss.str();
            auto& childPtr = node->children[key];
            if (!childPtr) childPtr = std::make_unique<Node>();
            node = childPtr.get();
        };
        (process(args), ...);
        if (node->hasResult) {
            Return* ptr = static_cast<Return*>(node->result.get());
            return *ptr;
        }
        Return value = fn(args...);
        node->hasResult = true;
        node->result = std::make_shared<Return>(value);
        return value;
    };
}

