template <typename T>
std::function<T(T)> compose(const std::vector<std::function<T(T)>>& functions) {
    if (functions.empty()) {
        return [](T x) { return x; };
    }
    return [functions](T x) {
        for (int i = static_cast<int>(functions.size()) - 1; i >= 0; --i) {
            x = functions[i](x);
        }
        return x;
    };
}

