template <typename Func>
auto timeLimit(Func fn, int t) {
    return [fn, t](auto&&... args) {
        using ReturnType = decltype(fn(args...));
        std::promise<ReturnType> prom;
        auto fut = prom.get_future();
        auto taskFuture = std::make_shared<std::future<void>>();
        *taskFuture = std::async(std::launch::async, [fn, t, prom = std::move(prom), taskFuture, args...]() mutable {
            std::future<ReturnType> inner = std::async(std::launch::async, fn, args...);
            if (inner.wait_for(std::chrono::milliseconds(t)) == std::future_status::ready) {
                try {
                    prom.set_value(inner.get());
                } catch (...) {
                    prom.set_exception(std::current_exception());
                }
            } else {
                prom.set_exception(std::make_exception_ptr(std::runtime_error("Time Limit Exceeded")));
            }
        });
        return fut;
    };
}

