struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode* l, TreeNode* r) : val(x), left(l), right(r) {}
};

TreeNode* replaceValueInTree(TreeNode* root) {
    if (!root) return nullptr;
    std::queue<std::pair<TreeNode*, long long>> q;
    q.emplace(root, root->val);
    while (!q.empty()) {
        int sz = static_cast<int>(q.size());
        std::vector<std::pair<TreeNode*, long long>> level;
        level.reserve(sz);
        long long levelSum = 0;
        for (int i = 0; i < sz; ++i) {
            auto cur = q.front();
            q.pop();
            level.push_back(cur);
            levelSum += cur.first->val;
        }
        for (auto& p : level) {
            p.first->val = static_cast<int>(levelSum - p.second);
        }
        for (auto& p : level) {
            TreeNode* node = p.first;
            long long childSum = 0;
            if (node->left) childSum += node->left->val;
            if (node->right) childSum += node->right->val;
            if (node->left) q.emplace(node->left, childSum);
            if (node->right) q.emplace(node->right, childSum);
        }
    }
    return root;
}

