}

#include <bits/stdc++.h>

long long minimumTotalPrice(int n, std::vector<std::vector<int>>& edges, std::vector<int>& price, std::vector<std::vector<int>>& trips) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int a = e[0], b = e[1];
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    int LOG = 1;
    while ((1 << LOG) <= n) ++LOG;
    std::vector<int> depth(n, 0);
    std::vector<std::vector<int>> up(LOG, std::vector<int>(n, -1));

    std::function<void(int,int)> dfsInit = [&](int u, int p) {
        up[0][u] = p;
        for (int k = 1; k < LOG; ++k) {
            if (up[k-1][u] != -1)
                up[k][u] = up[k-1][up[k-1][u]];
        }
        for (int v : adj[u]) if (v != p) {
            depth[v] = depth[u] + 1;
            dfsInit(v, u);
        }
    };
    dfsInit(0, -1);

    auto lca = [&](int u, int v) {
        if (depth[u] < depth[v]) std::swap(u, v);
        int diff = depth[u] - depth[v];
        for (int k = LOG - 1; k >= 0; --k) {
            if ((diff >> k) & 1) u = up[k][u];
        }
        if (u == v) return u;
        for (int k = LOG - 1; k >= 0; --k) {
            if (up[k][u] != up[k][v]) {
                u = up[k][u];
                v = up[k][v];
            }
        }
        return up[0][u];
    };

    std::vector<long long> cnt(n, 0);
    for (const auto& tr : trips) {
        int s = tr[0], t = tr[1];
        int L = lca(s, t);
        cnt[s] += 1;
        cnt[t] += 1;
        cnt[L] -= 1;
        int p = up[0][L];
        if (p != -1) cnt[p] -= 1;
    }

    std::function<long long(int,int)> dfsAcc = [&](int u, int p) -> long long {
        long long sum = cnt[u];
        for (int v : adj[u]) if (v != p) {
            sum += dfsAcc(v, u);
        }
        cnt[u] = sum;
        return sum;
    };
    dfsAcc(0, -1);

    std::vector<long long> weight(n, 0);
    long long total = 0;
    for (int i = 0; i < n; ++i) {
        total += static_cast<long long>(price[i]) * cnt[i];
        weight[i] = (static_cast<long long>(price[i]) / 2) * cnt[i];
    }

    std::vector<long long> dp0(n, 0), dp1(n, 0);
    std::function<void(int,int)> dfsDP = [&](int u, int p) {
        dp1[u] = weight[u];
        dp0[u] = 0;
        for (int v : adj[u]) if (v != p) {
            dfsDP(v, u);
            dp1[u] += dp0[v];
            dp0[u] += std::max(dp0[v], dp1[v]);
        }
    };
    dfsDP(0, -1);
    long long bestReduction = std::max(dp0[0], dp1[0]);
    return total - bestReduction;
}

