int minCapability(const std::vector<int>& nums, int k) {
    int left = *std::min_element(nums.begin(), nums.end());
    int right = *std::max_element(nums.begin(), nums.end());
    while (left < right) {
        int mid = (left + right) / 2;
        int count = 0;
        int prev = -2;
        for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
            if (nums[i] <= mid && i - prev > 1) {
                ++count;
                prev = i;
            }
        }
        if (count < k) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left;
}

