int findValidSplit(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n < 2) return -1;
    std::unordered_map<int, int> lastPos;
    for (int i = 0; i < n; ++i) {
        int x = nums[i];
        int v = x;
        for (int p = 2; p * p <= v; ++p) {
            if (v % p == 0) {
                lastPos[p] = i;
                while (v % p == 0) v /= p;
            }
        }
        if (v > 1) lastPos[v] = i;
    }
    int maxLast = -1;
    for (int i = 0; i < n - 1; ++i) {
        int x = nums[i];
        int v = x;
        for (int p = 2; p * p <= v; ++p) {
            if (v % p == 0) {
                maxLast = std::max(maxLast, lastPos[p]);
                while (v % p == 0) v /= p;
            }
        }
        if (v > 1) {
            maxLast = std::max(maxLast, lastPos[v]);
        }
        if (maxLast == i) return i;
    }
    return -1;
}

