int minimumScore(const std::string& s, const std::string& t) {
    std::size_t n = s.size();
    std::size_t m = t.size();
    std::vector<int> pref(n + 1, 0), suff(n + 1, 0);
    int p = 0;
    for (std::size_t i = 0; i < n; ++i) {
        if (p < (int)m && s[i] == t[p]) ++p;
        pref[i + 1] = p;
    }
    int q = (int)m - 1;
    for (int i = (int)n - 1; i >= 0; --i) {
        if (q >= 0 && s[i] == t[q]) --q;
        suff[i] = (int)m - 1 - q;
    }
    suff[n] = 0;
    int maxMatch = 0;
    std::size_t j = 0;
    for (std::size_t i = 0; i <= n; ++i) {
        if (j < i) j = i;
        while (j <= n && pref[i] + suff[j] > (int)m) ++j;
        if (j <= n) {
            maxMatch = std::max(maxMatch, pref[i] + suff[j]);
        }
    }
    return (int)m - maxMatch;
}

