    for (int i = 0; i <= 9; ++i) {
        for (int j = 0; j <= 9; ++j) {
            std::string newStr = numStr;
            char ci = static_cast<char>('0' + i);
            char cj = static_cast<char>('0' + j);
            for (char &c : newStr) {
