std::vector<std::vector<int>> substringXorQueries(const std::string& s, const std::vector<std::vector<int>>& queries) {
    std::unordered_map<unsigned int, std::pair<int, int>> best;
    int n = static_cast<int>(s.size());
    for (int i = 0; i < n; ++i) {
        if (s[i] == '0') {
            auto it = best.find(0);
            if (it == best.end() || i < it->second.first || (i == it->second.first && i < it->second.second)) {
                best[0] = {i, i};
            }
            continue;
        }
        unsigned int val = 0;
        for (int j = i; j < n && j - i < 31; ++j) {
            val = (val << 1) | static_cast<unsigned int>(s[j] - '0');
            auto it = best.find(val);
            if (it == best.end() || i < it->second.first || (i == it->second.first && j < it->second.second)) {
                best[val] = {i, j};
            }
        }
    }
    std::vector<std::vector<int>> ans;
    for (const auto& q : queries) {
        int target = q[0] ^ q[1];
        auto it = best.find(static_cast<unsigned int>(target));
        if (it != best.end()) {
            ans.push_back({it->second.first, it->second.second});
        } else {
            ans.push_back({-1, -1});
        }
    }
    return ans;
}

#include <bits/stdc++.h>

long long minCost(const std::vector<int>& basket1, const std::vector<int>& basket2) {
    std::unordered_map<int, int> cnt1, cnt2;
    for (int v : basket1) ++cnt1[v];
    for (int v : basket2) ++cnt2[v];

    int globalMin = INT_MAX;
    for (const auto& p : cnt1) globalMin = std::min(globalMin, p.first);
    for (const auto& p : cnt2) globalMin = std::min(globalMin, p.first);

    for (const auto& p : cnt1) {
        int total = p.second + cnt2[p.first];
        if (total % 2 != 0) return -1;
    }
    for (const auto& p : cnt2) {
        if (cnt1.find(p.first) == cnt1.end() && (p.second % 2 != 0)) return -1;
    }

    std::vector<int> diffList;
    for (const auto& p : cnt1) {
        int diff = p.second - cnt2[p.first];
        if (diff > 0) {
            for (int i = 0; i < diff / 2; ++i) diffList.push_back(p.first);
        } else if (diff < 0) {
            for (int i = 0; i < (-diff) / 2; ++i) diffList.push_back(p.first);
        }
    }
    for (const auto& p : cnt2) {
        if (cnt1.find(p.first) == cnt1.end()) {
            int diff = -p.second;
            for (int i = 0; i < (-diff) / 2; ++i) diffList.push_back(p.first);
        }
    }

    std::sort(diffList.begin(), diffList.end());

    long long cheap = 2LL * globalMin;
    long long cost = 0;
    for (size_t i = 0; i < diffList.size() / 2; ++i) {
        cost += std::min<long long>(diffList[i], cheap);
    }
    return cost;
}

