int maximizeWinFromTwoSegments(const std::vector<int>& prizePositions, int k) {
    if (prizePositions.empty()) return 0;
    std::vector<int> pos = prizePositions;
    std::sort(pos.begin(), pos.end());
    int n = static_cast<int>(pos.size());
    std::vector<int> cnt(n);
    std::vector<int> nxt(n);
    int r = 0;
    for (int l = 0; l < n; ++l) {
        while (r < n && pos[r] - pos[l] <= k) ++r;
        cnt[l] = r - l;
        nxt[l] = r;
    }
    std::vector<int> suffixMax(n + 1, 0);
    for (int i = n - 1; i >= 0; --i) {
        suffixMax[i] = std::max(cnt[i], suffixMax[i + 1]);
    }
    int ans = 0;
    for (int i = 0; i < n; ++i) {
        ans = std::max(ans, cnt[i] + suffixMax[nxt[i]]);
    }
    return ans;
}

