long long countFairPairs(std::vector<int> nums, int lower, int upper) {
    std::sort(nums.begin(), nums.end());
    long long count = 0;
    int n = static_cast<int>(nums.size());
    for (int i = 0; i < n - 1; ++i) {
        int l = static_cast<int>(std::lower_bound(nums.begin() + i + 1, nums.end(), lower - nums[i]) - nums.begin());
        int r = static_cast<int>(std::upper_bound(nums.begin() + i + 1, nums.end(), upper - nums[i]) - nums.begin()) - 1;
        if (l < n && r >= i + 1 && l <= r) {
            count += static_cast<long long>(r - l + 1);
        }
    }
    return count;
}

