long long minimumCost(std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    const int MAXV = n; // nums[i] < n
    const long long INF = (1LL<<60);
    std::vector<long long> dp(n + 1, INF);
    dp[0] = 0;
    for (int i = 1; i <= n; ++i) {
        std::vector<int> freq(MAXV, 0);
        int unique = 0;
        for (int j = i - 1; j >= 0; --j) {
            int x = nums[j];
            ++freq[x];
            if (freq[x] == 1) {
                ++unique;
            } else if (freq[x] == 2) {
                --unique;
            }
            int len = i - j;
            long long cost = static_cast<long long>(k) + (len - unique);
            dp[i] = std::min(dp[i], dp[j] + cost);
        }
    }
    return dp[n];
}

