std::vector<int> vowelStrings(const std::vector<std::string>& words, const std::vector<std::vector<int>>& queries) {
    std::vector<int> prefixSum(words.size(), 0);
    const std::string vowels = "aeiou";
    for (size_t i = 0; i < words.size(); ++i) {
        bool isVowelString = !words[i].empty() &&
                             vowels.find(words[i].front()) != std::string::npos &&
                             vowels.find(words[i].back()) != std::string::npos;
        prefixSum[i] = (i > 0 ? prefixSum[i - 1] : 0) + (isVowelString ? 1 : 0);
    }
    std::vector<int> ans(queries.size(), 0);
    for (size_t i = 0; i < queries.size(); ++i) {
        int left = queries[i][0];
        int right = queries[i][1];
        ans[i] = prefixSum[right] - (left > 0 ? prefixSum[left - 1] : 0);
    }
    return ans;
}

