    int n = static_cast<int>(weights.size());
    std::vector<long long> adj;
    adj.reserve(n - 1);
    for (int i = 0; i < n - 1; ++i) {
        adj.push_back(static_cast<long long>(weights[i]) + static_cast<long long>(weights[i + 1]));
