    std::sort(adj.begin(), adj.end());
    long long minSum = 0, maxSum = 0;
    for (int i = 0; i < k - 1; ++i) {
        minSum += adj[i];
        maxSum += adj[adj.size() - 1 - i];
    }
    return maxSum - minSum;
}

