int minOperations(std::vector<int> nums) {
    int n = nums.size();
    std::vector<int> order(n);
    std::iota(order.begin(), order.end(), 0);
    std::sort(order.begin(), order.end(), [&](int a, int b){ return nums[a] < nums[b]; });
    std::vector<int> tree(n + 1, 0);
    auto update = [&](int i, int delta) {
        i++;
        while (i <= n) { tree[i] += delta; i += i & (-i); }
    };
    auto query = [&](int i) -> int {
        i++;
        int s = 0;
        while (i > 0) { s += tree[i]; i -= i & (-i); }
        return s;
    };
    for (int i = 0; i < n; i++) update(i, 1);

    int cur = 0;
    long long total = 0;
    for (int idx : order) {
        int activeBefore;
        if (idx >= cur) {
            activeBefore = query(idx) - query(cur - 1) - 1;
        } else {
            activeBefore = (query(n - 1) - query(cur - 1)) + query(idx) - 1;
        }
        total += activeBefore + 1;
        update(idx, -1);
        cur = idx + 1;
        if (cur == n) cur = 0;
    }
    return (int)total;
}

