std::vector<int> getSubarrayBeauty(const std::vector<int>& nums, int k, int x) {
    std::vector<int> result;
    size_t n = nums.size();
    if (k > static_cast<int>(n) || k <= 0) {
        return result;
    }
    result.reserve(n - k + 1);
    for (size_t i = 0; i + static_cast<size_t>(k) <= n; ++i) {
        std::vector<int> negatives;
        negatives.reserve(k);
        for (size_t j = i; j < i + static_cast<size_t>(k); ++j) {
            if (nums[j] < 0) {
                negatives.push_back(nums[j]);
            }
        }
        std::sort(negatives.begin(), negatives.end());
        int beauty = (negatives.size() >= static_cast<size_t>(x)) ? negatives[x - 1] : 0;
        result.push_back(beauty);
    }
    return result;
}

