long long getGcd(long long a, long long b) {
    while (b != 0) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

long long minOperations(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    int n = static_cast<int>(nums.size());
    int ones = 0;
    for (int v : nums) if (v == 1) ++ones;
    if (ones > 0) return n - ones;
    long long overall = nums[0];
    for (int i = 1; i < n; ++i) overall = getGcd(overall, nums[i]);
    if (overall != 1) return -1;
    int minLen = n + 1;
    for (int i = 0; i < n; ++i) {
        long long cur = nums[i];
        for (int j = i; j < n; ++j) {
            cur = getGcd(cur, nums[j]);
            if (cur == 1) {
                minLen = std::min(minLen, j - i + 1);
                break;
            }
        }
    }
    return static_cast<long long>(minLen - 1 + n - 1);
}

