template <typename Generator>
auto cancellable(Generator gen) -> std::pair<std::function<void()>, std::future<decltype(gen())>> {
    using ReturnType = decltype(gen());
    std::promise<ReturnType> promise;
    std::future<ReturnType> fut = promise.get_future();
    auto cancelled = std::make_shared<std::atomic<bool>>(false);
    auto pptr = std::make_shared<std::promise<ReturnType>>(std::move(promise));

    auto taskFuture = std::make_shared<std::future<void>>();
    *taskFuture = std::async(std::launch::async, [gen = std::move(gen), cancelled, pptr, taskFuture]() mutable {
        try {
            ReturnType result = gen();
            if (!cancelled->load(std::memory_order_acquire)) {
                pptr->set_value(std::move(result));
            }
        } catch (...) {
            if (!cancelled->load(std::memory_order_acquire)) {
                pptr->set_exception(std::current_exception());
            }
        }
    });

    std::function<void()> cancel = [cancelled, pptr]() {
        bool expected = false;
        if (cancelled->compare_exchange_strong(expected, true, std::memory_order_acq_rel)) {
            try {
                throw std::runtime_error("Cancelled");
            } catch (...) {
                pptr->set_exception(std::current_exception());
            }
        }
    };

    return {std::move(cancel), std::move(fut)};
}

