long long minimumCost(const std::vector<int>& start, const std::vector<int>& target, const std::vector<std::vector<int>>& specialRoads) {
    auto serialize = [](const std::vector<int>& p) -> std::string {
        return std::to_string(p[0]) + "," + std::to_string(p[1]);
    };
    std::vector<std::vector<int>> points;
    points.push_back(start);
    points.push_back(target);
    for (const auto& road : specialRoads) {
        points.push_back({road[0], road[1]});
        points.push_back({road[2], road[3]});
    }
    std::unordered_set<std::string> seen;
    std::vector<std::vector<int>> uniqPoints;
    for (const auto& p : points) {
        std::string key = serialize(p);
        if (seen.insert(key).second) {
            uniqPoints.push_back(p);
        }
    }
    points = std::move(uniqPoints);
    std::unordered_map<std::string, long long> distances;
    for (const auto& p : points) {
        distances[serialize(p)] = LLONG_MAX;
    }
    distances[serialize(start)] = 0;
    std::vector<std::pair<long long, std::vector<int>>> queue;
    queue.emplace_back(0LL, start);
    while (!queue.empty()) {
        auto cur = queue.front();
        queue.erase(queue.begin());
        long long dist = cur.first;
        const std::vector<int>& point = cur.second;
        std::string pointKey = serialize(point);
        if (dist > distances[pointKey]) {
            continue;
        }
        for (const auto& road : specialRoads) {
            if (point[0] == road[0] && point[1] == road[1]) {
                long long newDist = dist + road[4];
                std::vector<int> newPoint = {road[2], road[3]};
                std::string newKey = serialize(newPoint);
                if (newDist < distances[newKey]) {
                    distances[newKey] = newDist;
                    queue.emplace_back(newDist, newPoint);
                    std::sort(queue.begin(), queue.end(),
                              [](const auto& a, const auto& b) { return a.first < b.first; });
                }
            }
        }
        for (const auto& other : points) {
            long long newDist = dist + std::abs((long long)other[0] - point[0]) + std::abs((long long)other[1] - point[1]);
            std::string otherKey = serialize(other);
            if (newDist < distances[otherKey]) {
                distances[otherKey] = newDist;
                queue.emplace_back(newDist, other);
                std::sort(queue.begin(), queue.end(),
                          [](const auto& a, const auto& b) { return a.first < b.first; });
            }
        }
    }
    return distances[serialize(target)];
}

