    for (int i = n - 1; i >= 0; --i) {
        for (char c = static_cast<char>(s[i] + 1); c < 'a' + k; ++c) {
            if (i > 0 && c == s[i - 1]) continue;
            std::string ans = s;
            ans[i] = c;
            bool ok = true;
            for (int j = i + 1; j < n; ++j) {
                for (char d = 'a'; d < 'a' + k; ++d) {
                    if (d != ans[j - 1]) {
                        ans[j] = d;
                        break;
