    long long cur = 0;
    long long maxSoFar = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        long long v = static_cast<long long>(nums[i]);
        if (i == 0) {
            cur = 2LL * v;
            maxSoFar = v;
        } else {
            long long extra = std::max(0LL, maxSoFar - v);
            cur += 2LL * v + extra;
            if (v > maxSoFar) {
                maxSoFar = v;
            }
        }
        ans.push_back(cur);
    }
    return ans;
}

