        if (!called) {
            fn(args...);
            called = true;
        }
    };
}

template <typename R, typename... Args>
std::function<R(Args...)> once(std::function<R(Args...)> fn) {
    bool called = false;
    std::shared_ptr<R> result;
    return [fn = std::move(fn), called, result](Args... args) mutable -> R {
        if (!called) {
            result = std::make_shared<R>(fn(args...));
            called = true;
        }
        return *result;
    };
}

