long long minIncrements(int n, const std::vector<long long>& cost) {
    if (n == 0) return 0;
    std::vector<long long> required(n, 0);
    long long totalIncrements = 0;
    for (int i = n - 1; i >= 0; --i) {
        int leftIdx = 2 * i + 1;
        int rightIdx = 2 * i + 2;
        if (leftIdx >= n) {
            required[i] = cost[i];
        } else {
            long long leftSum = required[leftIdx];
            long long rightSum = (rightIdx < n) ? required[rightIdx] : 0;
            if (rightIdx < n) {
                totalIncrements += std::llabs(leftSum - rightSum);
                required[i] = cost[i] + std::max(leftSum, rightSum);
            } else {
                required[i] = cost[i] + leftSum;
            }
        }
    }
    return totalIncrements;
}

