    int intVal;
    std::vector<NestedArray> children;
    NestedArray(int v) : isInt(true), intVal(v) {}
    NestedArray(std::vector<NestedArray> c) : isInt(false), intVal(0), children(std::move(c)) {}
};

std::vector<int> nestedArrayGenerator(const std::vector<NestedArray>& arr) {
    std::vector<int> result;
    std::vector<const NestedArray*> stack;
    stack.reserve(arr.size());
    for (auto it = arr.rbegin(); it != arr.rend(); ++it) {
        stack.push_back(&*it);
    }
    while (!stack.empty()) {
        const NestedArray* cur = stack.back();
        stack.pop_back();
        if (cur->isInt) {
            result.push_back(cur->intVal);
        } else {
            const auto& vec = cur->children;
            for (auto it = vec.rbegin(); it != vec.rend(); ++it) {
                stack.push_back(&*it);
            }
        }
    }
    return result;
}

