int countCompleteComponents(int n, const std::vector<std::vector<int>>& edges) {
    std::vector<std::vector<int>> graph(n);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        graph[u].push_back(v);
        graph[v].push_back(u);
    }

    std::vector<bool> visited(n, false);
    int count = 0;

    for (int i = 0; i < n; ++i) {
        if (!visited[i]) {
            std::vector<int> component;
            dfs(graph, visited, i, component);

            bool isComplete = true;
            for (int u : component) {
                for (int v : component) {
                    if (u != v && std::find(graph[u].begin(), graph[u].end(), v) == graph[u].end()) {
                        isComplete = false;
                        break;
                    }
                }
                if (!isComplete) break;
            }

            if (isComplete) ++count;
        }
    }

    return count;
}

