std::vector<int> circularGameLosers(int n, int k) {
    std::vector<bool> received(n + 1, false);
    int current = 1;
    received[current] = true;
    int step = k;
    while (true) {
        int next = ( (current - 1 + step) % n ) + 1;
        if (received[next]) break;
        received[next] = true;
        current = next;
        step += k;
    }
    std::vector<int> losers;
    for (int i = 1; i <= n; ++i) {
        if (!received[i]) losers.push_back(i);
    }
    return losers;
}

