int maximumMoves(const std::vector<std::vector<int>>& grid) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    std::vector<std::vector<int>> dp(m, std::vector<int>(n, -1));
    for (int i = 0; i < m; ++i) {
        dp[i][0] = 0;
    }
    int ans = 0;
    for (int j = 1; j < n; ++j) {
        for (int i = 0; i < m; ++i) {
            int best = -1;
            for (int di = -1; di <= 1; ++di) {
                int k = i + di;
                if (k < 0 || k >= m) continue;
                if (grid[k][j - 1] < grid[i][j] && dp[k][j - 1] != -1) {
                    best = std::max(best, dp[k][j - 1]);
                }
            }
            if (best != -1) {
                dp[i][j] = best + 1;
                ans = std::max(ans, dp[i][j]);
            }
        }
    }
    return ans;
}

