struct Json;
using JsonPtr = std::shared_ptr<Json>;
using JsonArray = std::vector<JsonPtr>;
using JsonObject = std::unordered_map<std::string, JsonPtr>;

enum class JsonType { Null, Bool, Number, String, Array, Object };

struct Json {
    JsonType type;
    bool bool_val = false;
    double num_val = 0.0;
    std::string str_val;
    JsonArray arr_val;
    JsonObject obj_val;

    Json() : type(JsonType::Null) {}
    Json(std::nullptr_t) : type(JsonType::Null) {}
    Json(bool b) : type(JsonType::Bool), bool_val(b) {}
    Json(double d) : type(JsonType::Number), num_val(d) {}
    Json(const std::string& s) : type(JsonType::String), str_val(s) {}
    Json(const char* s) : type(JsonType::String), str_val(s) {}
    Json(const JsonArray& arr) : type(JsonType::Array), arr_val(arr) {}
    Json(const JsonObject& obj) : type(JsonType::Object), obj_val(obj) {}
};

inline bool isTruthy(const Json& v) {
    switch (v.type) {
        case JsonType::Null:   return false;
        case JsonType::Bool:   return v.bool_val;
        case JsonType::Number: return v.num_val != 0.0;
        case JsonType::String: return !v.str_val.empty();
        case JsonType::Array:  return true;
        case JsonType::Object: return true;
    }
    return false;
}

JsonPtr compactObject(const JsonPtr& obj) {
    if (!obj) return nullptr;
    if (obj->type == JsonType::Array) {
        const JsonArray& src = obj->arr_val;
        JsonArray dst;
        dst.reserve(src.size());
        bool changed = false;
        for (const auto& el : src) {
            if (!el) continue;
            if (!isTruthy(*el)) { changed = true; continue; }
            if (el->type == JsonType::Array || el->type == JsonType::Object) {
                JsonPtr compacted = compactObject(el);
                if (compacted != el) changed = true;
                dst.push_back(compacted);
            } else {
                dst.push_back(el);
            }
        }
        if (!changed) return obj;
        return std::make_shared<Json>(dst);
    } else if (obj->type == JsonType::Object) {
        const JsonObject& src = obj->obj_val;
        JsonObject dst;
        bool changed = false;
        for (const auto& kv : src) {
            const JsonPtr& val = kv.second;
            if (!val) continue;
            if (!isTruthy(*val)) { changed = true; continue; }
            if (val->type == JsonType::Array || val->type == JsonType::Object) {
                JsonPtr compacted = compactObject(val);
                if (compacted != val) changed = true;
                dst.emplace(kv.first, compacted);
            } else {
                dst.emplace(kv.first, val);
            }
        }
        if (!changed) return obj;
        return std::make_shared<Json>(dst);
    } else {
        return obj;
    }
}

