static bool canPartition(const std::string& s, long long target) {
    int len = static_cast<int>(s.size());
    std::function<bool(int, long long)> dfs = [&](int pos, long long cur) -> bool {
        if (pos == len) return cur == target;
        long long val = 0;
        for (int i = pos; i < len; ++i) {
            val = val * 10 + (s[i] - '0');
            if (cur + val > target) break;
            if (dfs(i + 1, cur + val)) return true;
        }
        return false;
    };
    return dfs(0, 0);
}

long long punishmentNumber(long long n) {
    long long result = 0;
    for (long long i = 1; i <= n; ++i) {
        long long sq = i * i;
        if (canPartition(std::to_string(sq), i)) {
            result += sq;
        }
    }
    return result;
}

