long long maximumStrength(const std::vector<long long>& nums) {
    long long maxStrength = 0;
    size_t n = nums.size();
    unsigned long long total = 1ULL << n;
    for (unsigned long long mask = 0; mask < total; ++mask) {
        long long subsetProduct = 1;
        for (size_t i = 0; i < n; ++i) {
            if (mask & (1ULL << i)) {
                subsetProduct *= nums[i];
            }
        }
        maxStrength = std::max(maxStrength, subsetProduct);
    }
    return maxStrength;
}

class Solution {
public:
    vector<vector<int>> modifiedGraphEdges(int n, vector<vector<int>>& edges, int source, int destination, int target) {
        const long long kMax = 2000000000LL;
        vector<vector<pair<int,long long>>> graph(n);
        for (auto& e : edges) if (e[2] != -1) { graph[e[0]].push_back({e[1], e[2]}); graph[e[1]].push_back({e[0], e[2]}); }
        long long d = dijkstra(graph, n, source, destination);
        if (d < target) return {};
        if (d == target) {
            for (auto& e : edges) if (e[2] == -1) e[2] = kMax;
            return edges;
        }
        for (int i = 0; i < (int)edges.size(); i++) {
            if (edges[i][2] != -1) continue;
            edges[i][2] = 1;
            graph[edges[i][0]].push_back({edges[i][1], 1});
            graph[edges[i][1]].push_back({edges[i][0], 1});
            d = dijkstra(graph, n, source, destination);
            if (d <= target) {
                edges[i][2] += (target - d);
                for (int j = i+1; j < (int)edges.size(); j++) if (edges[j][2] == -1) edges[j][2] = kMax;
                return edges;
            }
        }
        return {};
    }
private:
    long long dijkstra(vector<vector<pair<int,long long>>>& graph, int n, int src, int dst) {
        vector<long long> dist(n, LLONG_MAX);
        dist[src] = 0;
        priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
        pq.push({0, src});
        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (d > dist[u]) continue;
            for (auto& [v, w] : graph[u]) if (d + w < dist[v]) { dist[v] = d+w; pq.push({dist[v], v}); }
        }
        return dist[dst];
    }
};

