bool gcdTraversal(const std::vector<int>& nums) {
    std::vector<int> parent(nums.size());
    for (size_t i = 0; i < parent.size(); ++i) parent[i] = static_cast<int>(i);
    std::function<int(int)> find = [&](int x) -> int {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    };
    auto unite = [&](int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) parent[rootX] = rootY;
    };
    std::function<int(int, int)> gcd = [&](int a, int b) -> int {
        return b == 0 ? a : gcd(b, a % b);
    };
    for (size_t i = 0; i < nums.size(); ++i) {
        for (size_t j = i + 1; j < nums.size(); ++j) {
            if (gcd(nums[i], nums[j]) > 1) unite(static_cast<int>(i), static_cast<int>(j));
        }
    }
    int root = find(0);
    for (size_t i = 1; i < nums.size(); ++i) {
        if (find(static_cast<int>(i)) != root) return false;
    }
    return true;
}

