std::vector<std::vector<int>> diffOfDiagonals(const std::vector<std::vector<int>>& grid) {
    int m = grid.size(), n = grid[0].size();
    std::vector<std::vector<int>> answer(m, std::vector<int>(n, 0));
    for (int r = 0; r < m; r++) {
        for (int c = 0; c < n; c++) {
            std::unordered_set<int> tl, br;
            int i = r - 1, j = c - 1;
            while (i >= 0 && j >= 0) { tl.insert(grid[i][j]); i--; j--; }
            i = r + 1; j = c + 1;
            while (i < m && j < n) { br.insert(grid[i][j]); i++; j++; }
            answer[r][c] = std::abs((int)tl.size() - (int)br.size());
        }
    }
    return answer;
}

