class EventEmitter {
public:
    using Callback = std::function<std::string(const std::vector<std::string>&)>;
    using ListIter = std::list<std::pair<int, Callback>>::iterator;

    EventEmitter() : nextId(0) {}

    int subscribe(const std::string& eventName, Callback cb) {
        int id = nextId++;
        auto& lst = events[eventName];
        lst.emplace_back(id, std::move(cb));
        auto it = std::prev(lst.end());
        idInfo[id] = {eventName, it};
        return id;
    }

    std::vector<std::string> emit(const std::string& eventName, const std::vector<std::string>& args = {}) {
        std::vector<std::string> results;
        auto it = events.find(eventName);
        if (it != events.end()) {
            for (auto& p : it->second) {
                results.push_back(p.second(args));
            }
        }
        return results;
    }

    void unsubscribe(int id) {
        auto it = idInfo.find(id);
        if (it != idInfo.end()) {
            const std::string& eventName = it->second.first;
            auto listIt = it->second.second;
            auto evIt = events.find(eventName);
            if (evIt != events.end()) {
                evIt->second.erase(listIt);
                if (evIt->second.empty()) {
                    events.erase(evIt);
                }
            }
            idInfo.erase(it);
        }
    }

private:
    int nextId;
    std::unordered_map<std::string, std::list<std::pair<int, Callback>>> events;
    std::unordered_map<int, std::pair<std::string, ListIter>> idInfo;
};

