long long sumInMatrix(const std::vector<std::vector<int>>& nums) {
    if (nums.empty() || nums[0].empty()) return 0;
    size_t rows = nums.size();
    size_t cols = nums[0].size();
    long long score = 0;
    for (size_t c = 0; c < cols; ++c) {
        int colMax = std::numeric_limits<int>::lowest();
        for (size_t r = 0; r < rows; ++r) {
            if (nums[r][c] > colMax) colMax = nums[r][c];
        }
        score += colMax;
    }
    return score;
}

