int minSwaps(std::vector<int>& nums) {
    std::size_t n = nums.size();
    if (n == 0) return 0;
    std::size_t pos1 = 0, posn = 0;
    for (std::size_t i = 0; i < n; ++i) {
        if (nums[i] == 1) pos1 = i;
        if (nums[i] == static_cast<int>(n)) posn = i;
    }
    int swaps = 0;
    if (pos1 < posn) {
        swaps = static_cast<int>(pos1) + static_cast<int>((n - 1) - posn);
    } else {
        swaps = static_cast<int>(pos1) + static_cast<int>((n - 1) - posn) - 1;
    }
    return swaps;
}

