int maxCellsInMatrix(const std::vector<std::vector<int>>& mat) {
    if (mat.empty() || mat[0].empty()) return 0;
    int m = static_cast<int>(mat.size());
    int n = static_cast<int>(mat[0].size());
    std::vector<std::tuple<int,int,int>> cells;
    cells.reserve(m * n);
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            cells.emplace_back(mat[i][j], i, j);
        }
    }
    std::sort(cells.begin(), cells.end(),
              [](const std::tuple<int,int,int>& a, const std::tuple<int,int,int>& b) {
                  return std::get<0>(a) < std::get<0>(b);
              });
    std::vector<int> bestRow(m, 0), bestCol(n, 0);
    std::vector<std::vector<int>> dp(m, std::vector<int>(n, 0));
    int answer = 0;
    std::size_t idx = 0;
    while (idx < cells.size()) {
        std::size_t start = idx;
        while (idx < cells.size() && std::get<0>(cells[idx]) == std::get<0>(cells[start])) {
            int r = std::get<1>(cells[idx]);
            int c = std::get<2>(cells[idx]);
            dp[r][c] = 1 + std::max(bestRow[r], bestCol[c]);
            answer = std::max(answer, dp[r][c]);
            ++idx;
        }
        for (std::size_t k = start; k < idx; ++k) {
            int r = std::get<1>(cells[k]);
            int c = std::get<2>(cells[k]);
            bestRow[r] = std::max(bestRow[r], dp[r][c]);
            bestCol[c] = std::max(bestCol[c], dp[r][c]);
        }
    }
    return answer;
}

