long long sumOfMatrixAfterQueries(int n, const std::vector<std::vector<int>>& queries) {
    std::vector<std::vector<int>> matrix(n, std::vector<int>(n, 0));
    long long sum = 0;
    for (const auto& q : queries) {
        int type = q[0];
        int index = q[1];
        int val = q[2];
        if (type == 0) {
            long long oldRowSum = 0;
            for (int x : matrix[index]) {
                oldRowSum += x;
            }
            long long newRowSum = static_cast<long long>(val) * n;
            sum = sum - oldRowSum + newRowSum;
            std::fill(matrix[index].begin(), matrix[index].end(), val);
        } else {
            long long oldColSum = 0;
            for (int j = 0; j < n; ++j) {
                oldColSum += matrix[j][index];
            }
            long long newColSum = static_cast<long long>(val) * n;
            sum = sum - oldColSum + newColSum;
            for (int j = 0; j < n; ++j) {
                matrix[j][index] = val;
            }
        }
    }
    return sum;
}

#include <bits/stdc++.h>

int countGoodIntegers(const std::string& num1, const std::string& num2, int min_sum, int max_sum) {
    const long long MOD = 1000000007LL;

    auto countUpTo = [&](const std::string& s) -> long long {
        int n = static_cast<int>(s.size());
        std::vector<std::vector<std::array<long long, 2>>> dp(n + 1,
            std::vector<std::array<long long, 2>>(max_sum + 1, { -1, -1 }));

        std::function<long long(int, int, bool)> dfs = [&](int pos, int sum, bool tight) -> long long {
            if (sum > max_sum) return 0;
            if (pos == n) {
                return (sum >= min_sum && sum <= max_sum) ? 1 : 0;
            }
            long long &res = dp[pos][sum][tight ? 1 : 0];
            if (res != -1) return res;
            res = 0;
            int limit = tight ? (s[pos] - '0') : 9;
            for (int d = 0; d <= limit; ++d) {
                bool ntight = tight && (d == limit);
                res += dfs(pos + 1, sum + d, ntight);
                if (res >= MOD) res -= MOD;
            }
            return res;
        };

        return dfs(0, 0, true);
    };

    auto decrement = [&](std::string s) -> std::string {
        int i = static_cast<int>(s.size()) - 1;
        while (i >= 0 && s[i] == '0') {
            s[i] = '9';
            --i;
        }
        if (i >= 0) {
            s[i] = static_cast<char>(s[i] - 1);
        }
        size_t pos = s.find_first_not_of('0');
        if (pos == std::string::npos) return "0";
        return s.substr(pos);
    };

    long long total = countUpTo(num2);
    std::string lower = decrement(num1);
    total = (total - countUpTo(lower) + MOD) % MOD;
    return static_cast<int>(total);
}

