template <typename T>
struct PromiseAllResult {
    long long t;
    std::vector<T> resolved;
    std::exception_ptr rejected;
};

template <typename T>
PromiseAllResult<T> promiseAll(const std::vector<std::function<std::future<T>()>>& functions) {
    auto start = std::chrono::steady_clock::now();
    PromiseAllResult<T> result;
    result.rejected = nullptr;
    if (functions.empty()) {
        result.t = 0;
        result.resolved = {};
        return result;
    }
    std::vector<T> results(functions.size());
    std::vector<std::future<T>> futures;
    futures.reserve(functions.size());
    for (const auto& func : functions) {
        futures.emplace_back(func());
    }
    std::vector<bool> done(futures.size(), false);
    size_t doneCount = 0;
    while (doneCount < futures.size()) {
        for (size_t i = 0; i < futures.size(); ++i) {
            if (done[i]) continue;
            if (futures[i].wait_for(std::chrono::milliseconds(1)) == std::future_status::ready) {
                done[i] = true;
                doneCount++;
                try {
                    results[i] = futures[i].get();
                } catch (...) {
                    result.rejected = std::current_exception();
                    auto end = std::chrono::steady_clock::now();
                    result.t = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();
                    return result;
                }
            }
        }
    }
    auto end = std::chrono::steady_clock::now();
    result.t = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();
    result.resolved = std::move(results);
    return result;
}

