bool isFascinating(int n) {
    std::unordered_set<int> digitSet;
    std::string concatenated = std::to_string(n) + std::to_string(2 * n) + std::to_string(3 * n);
    for (size_t i = 0; i < concatenated.size(); ++i) {
        int digit = concatenated[i] - '0';
        if (digit >= 1 && digit <= 9) {
            digitSet.insert(digit);
        } else {
            return false;
        }
    }
    return digitSet.size() == 9;
}

