int findNonMinOrMax(const std::vector<int>& nums) {
    if (nums.size() < 3) return -1;
    int mn = *std::min_element(nums.begin(), nums.end());
    int mx = *std::max_element(nums.begin(), nums.end());
    int candidate = std::numeric_limits<int>::max();
    for (int v : nums) {
        if (v != mn && v != mx) {
            if (v < candidate) {
                candidate = v;
            }
        }
    }
    return candidate == std::numeric_limits<int>::max() ? -1 : candidate;
