long long robotDistances(const std::vector<long long>& nums, std::string s, int d) {
    const long long MOD = 1000000007LL;
    std::size_t n = nums.size();
    std::vector<long long> pos;
    pos.reserve(n);
    for (std::size_t i = 0; i < n; ++i) {
        long long delta = (s[i] == 'R') ? static_cast<long long>(d) : -static_cast<long long>(d);
        pos.push_back(nums[i] + delta);
    }
    std::sort(pos.begin(), pos.end());
    long long total = 0;
    long long prefix = 0;
    for (std::size_t i = 0; i < n; ++i) {
        long long cur = pos[i] % MOD;
        if (cur < 0) cur += MOD;
        total = (total + (cur * static_cast<long long>(i) % MOD) - (prefix % MOD) + MOD) % MOD;
        prefix = (prefix + cur) % MOD;
    }
    return total;
}

