int specialPerm(const std::vector<int>& nums) {
    constexpr int MOD = 1000000007;
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;
    std::vector<std::vector<char>> can(n, std::vector<char>(n, 0));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i == j) continue;
            if (nums[i] % nums[j] == 0 || nums[j] % nums[i] == 0) can[i][j] = 1;
        }
    }
    int totalMask = 1 << n;
    std::vector<std::vector<int>> dp(totalMask, std::vector<int>(n, 0));
    for (int i = 0; i < n; ++i) dp[1 << i][i] = 1;
    for (int mask = 0; mask < totalMask; ++mask) {
        for (int last = 0; last < n; ++last) {
            int cur = dp[mask][last];
            if (!cur) continue;
            for (int nxt = 0; nxt < n; ++nxt) {
                if (mask & (1 << nxt)) continue;
                if (can[last][nxt]) {
                    int nmask = mask | (1 << nxt);
                    dp[nmask][nxt] = (dp[nmask][nxt] + cur) % MOD;
                }
            }
        }
    }
    int fullMask = totalMask - 1;
    long long ans = 0;
    for (int i = 0; i < n; ++i) ans = (ans + dp[fullMask][i]) % MOD;
    return static_cast<int>(ans);
}

