int longestEvenOddSubarray(const std::vector<int>& nums, int threshold) {
    int best = 0;
    int cur_len = 0;
    int prevParity = -1;
    for (int x : nums) {
        if (x > threshold) {
            cur_len = 0;
            prevParity = -1;
            continue;
        }
        int parity = x & 1;
        if (cur_len == 0) {
            if (parity == 0) {
                cur_len = 1;
                prevParity = 0;
            }
        } else {
            if (parity != prevParity) {
                ++cur_len;
                prevParity = parity;
            } else {
                if (parity == 0) {
                    cur_len = 1;
                    prevParity = 0;
                } else {
                    cur_len = 0;
                    prevParity = -1;
                }
            }
        }
        best = std::max(best, cur_len);
    }
    return best;
}

