int longestAlternatingSubarray(const std::vector<int>& nums) {
    if (nums.size() < 2) return -1;

    int maxLen = 0;
    int curLen = 1;
    int prevSign = 0;

    for (size_t i = 1; i < nums.size(); ++i) {
        int diff = nums[i] - nums[i - 1];
        if (diff == 0) {
            curLen = 1;
            prevSign = 0;
            continue;
        }
        int sign = diff > 0 ? 1 : -1;

        if (prevSign != 0 && sign != prevSign) {
            ++curLen;
        } else {
            curLen = 2;
        }

        prevSign = sign;
        if (curLen > maxLen) maxLen = curLen;
    }

    return maxLen >= 2 ? maxLen : -1;
}

