int minimumLength(const std::vector<std::string>& words) {
    int n = static_cast<int>(words.size());
    if (n == 0) return 0;
    int totalLen = 0;
    for (const auto& w : words) totalLen += static_cast<int>(w.size());

    const int INF_NEG = -1e9;
    int fullMask = (1 << n) - 1;
    std::vector<std::vector<int>> dp(1 << n, std::vector<int>(n, INF_NEG));

    for (int i = 0; i < n; ++i) {
        dp[1 << i][i] = 0;
    }

    for (int mask = 0; mask <= fullMask; ++mask) {
        for (int last = 0; last < n; ++last) {
            if (!(mask & (1 << last))) continue;
            int cur = dp[mask][last];
            if (cur == INF_NEG) continue;
            for (int nxt = 0; nxt < n; ++nxt) {
                if (mask & (1 << nxt)) continue;
                int add = (words[last].back() == words[nxt].front()) ? 1 : 0;
                int nmask = mask | (1 << nxt);
                dp[nmask][nxt] = std::max(dp[nmask][nxt], cur + add);
            }
        }
    }

    int maxOverlap = 0;
    for (int last = 0; last < n; ++last) {
        maxOverlap = std::max(maxOverlap, dp[fullMask][last]);
    }
    return totalLen - maxOverlap;
}

#include <bits/stdc++.h>

int minBeautifulSubstrings(const std::string& s) {
    int n = static_cast<int>(s.size());
    std::vector<std::string> powers;
    unsigned long long val = 1;
    while (true) {
        unsigned long long temp = val;
        std::string bin;
        while (temp > 0) {
            bin.push_back((temp & 1ULL) ? '1' : '0');
            temp >>= 1ULL;
        }
        if (bin.empty()) bin = "0";
        std::reverse(bin.begin(), bin.end());
        if (static_cast<int>(bin.size()) > n) break;
        powers.push_back(std::move(bin));
        if (val > ULLONG_MAX / 5ULL) break;
        val *= 5ULL;
    }
    const int INF = 1e9;
    std::vector<int> dp(n + 1, INF);
    dp[0] = 0;
    for (int i = 1; i <= n; ++i) {
        for (const std::string& b : powers) {
            int len = static_cast<int>(b.size());
            if (len <= i && s.compare(i - len, len, b) == 0) {
                dp[i] = std::min(dp[i], dp[i - len] + 1);
            }
        }
    }
    return dp[n] >= INF ? -1 : dp[n];
}

#include <bits/stdc++.h>
