int maxJumps(const std::vector<int>& nums, int target) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return -1;
    if (n == 1) return 0;
    const int NEG_INF = INT_MIN;
    std::vector<int> vals = nums;
    std::sort(vals.begin(), vals.end());
    vals.erase(std::unique(vals.begin(), vals.end()), vals.end());
    int m = static_cast<int>(vals.size());
    std::vector<int> seg(4 * m, NEG_INF);
    auto update = [&](auto&& self, int idx, int val, int node, int l, int r) -> void {
        if (l == r) {
            seg[node] = std::max(seg[node], val);
            return;
        }
        int mid = (l + r) >> 1;
        if (idx <= mid) self(self, idx, val, node * 2, l, mid);
        else self(self, idx, val, node * 2 + 1, mid + 1, r);
        seg[node] = std::max(seg[node * 2], seg[node * 2 + 1]);
    };
    auto query = [&](auto&& self, int ql, int qr, int node, int l, int r) -> int {
        if (ql > r || qr < l) return NEG_INF;
        if (ql <= l && r <= qr) return seg[node];
        int mid = (l + r) >> 1;
        return std::max(self(self, ql, qr, node * 2, l, mid),
                        self(self, ql, qr, node * 2 + 1, mid + 1, r));
    };
    std::vector<int> dp(n, NEG_INF);
    dp[0] = 0;
    int pos0 = static_cast<int>(std::lower_bound(vals.begin(), vals.end(), nums[0]) - vals.begin());
    update(update, pos0, dp[0], 1, 0, m - 1);
    for (int i = 1; i < n; ++i) {
        int lowVal = nums[i] - target;
        int highVal = nums[i] + target;
        int l = static_cast<int>(std::lower_bound(vals.begin(), vals.end(), lowVal) - vals.begin());
        int r = static_cast<int>(std::upper_bound(vals.begin(), vals.end(), highVal) - vals.begin()) - 1;
        if (l <= r) {
            int best = query(query, l, r, 1, 0, m - 1);
            if (best != NEG_INF) dp[i] = best + 1;
        }
        int pos = static_cast<int>(std::lower_bound(vals.begin(), vals.end(), nums[i]) - vals.begin());
        update(update, pos, dp[i], 1, 0, m - 1);
    }
    return dp[n - 1] == NEG_INF ? -1 : dp[n - 1];
}

#include <bits/stdc++.h>

long long sumImbalanceNumbers(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    long long total = 0;
    for (int i = 0; i < n; ++i) {
        std::set<int> distinct;
        long long cur = 0;
        for (int j = i; j < n; ++j) {
            int x = nums[j];
            if (distinct.find(x) == distinct.end()) {
                auto it = distinct.lower_bound(x);
                int succ = (it != distinct.end()) ? *it : -1;
                int pred = -1;
                if (it != distinct.begin()) {
                    pred = *std::prev(it);
                }
                if (pred != -1 && succ != -1 && succ - pred > 1) {
                    --cur;
                }
                if (pred != -1 && x - pred > 1) {
                    ++cur;
                }
                if (succ != -1 && succ - x > 1) {
                    ++cur;
                }
                distinct.insert(x);
            }
            total += cur;
        }
    }
    return total;
}

