bool checkArray(std::vector<int>& nums, int k) {
    std::size_t n = nums.size();
    if (k <= 0) return false;
    std::vector<long long> pending(k, 0);
    long long cur = 0;
    for (std::size_t i = 0; i < n; ++i) {
        if (i >= static_cast<std::size_t>(k)) {
            cur -= pending[i % k];
        }
        long long need = static_cast<long long>(nums[i]) - cur;
        if (need < 0) return false;
        if (need > 0) {
            if (i + static_cast<std::size_t>(k) > n) return false;
            cur += need;
            pending[i % k] = need;
        } else {
            pending[i % k] = 0;
        }
    }
    return true;
}

