std::vector<int> numberOfBlackBlocks(int m, int n, const std::vector<std::vector<int>>& coordinates) {
    std::unordered_map<long long, int> blockCount;
    for (size_t i = 0; i < coordinates.size(); ++i) {
        int x = coordinates[i][0];
        int y = coordinates[i][1];
        for (int dx = -1; dx <= 0; ++dx) {
            int r = x + dx;
            if (r < 0 || r >= m - 1) continue;
            for (int dy = -1; dy <= 0; ++dy) {
                int c = y + dy;
                if (c < 0 || c >= n - 1) continue;
                long long key = static_cast<long long>(r) * n + c;
                ++blockCount[key];
            }
        }
    }

    std::vector<int> ans(5, 0);
    long long totalBlocks = std::max(0, (m - 1) * (n - 1));
    ans[0] = static_cast<int>(totalBlocks - static_cast<long long>(blockCount.size()));

    for (const auto& kv : blockCount) {
        int cnt = kv.second;
        ++ans[cnt];
    }
    return ans;
}

