        if (nums2[i - 1] <= nums1[i]) cur1 = std::max(cur1, dp2 + 1);
        if (nums1[i - 1] <= nums2[i]) cur2 = std::max(cur2, dp1 + 1);
        if (nums2[i - 1] <= nums2[i]) cur2 = std::max(cur2, dp2 + 1);
        dp1 = cur1;
