bool isGoodArray(const std::vector<int>& nums) {
    if (nums.empty()) return false;
    int max = 0;
    for (int v : nums) {
        if (v > max) max = v;
    }
    if (static_cast<int>(nums.size()) != max + 1) return false;
    std::unordered_map<int, int> freq;
    freq.reserve(nums.size() * 2);
    for (int v : nums) {
        if (v < 1 || v > max) return false;
        ++freq[v];
    }
    for (int i = 1; i < max; ++i) {
        auto it = freq.find(i);
        if (it == freq.end() || it->second != 1) return false;
    }
    auto itmax = freq.find(max);
    if (itmax == freq.end() || itmax->second != 2) return false;
    return true;
}

