int minValidSplit(const std::vector<int>& nums) {
    int candidate = 0;
    int cnt = 0;
    for (int v : nums) {
        if (cnt == 0) {
            candidate = v;
            cnt = 1;
        } else if (v == candidate) {
            cnt++;
        } else {
            cnt--;
        }
    }
    int d = candidate;
    int total = 0;
    for (int v : nums) {
        if (v == d) total++;
    }
    int leftCnt = 0;
    int n = static_cast<int>(nums.size());
    for (int i = 0; i < n - 1; ++i) {
        if (nums[i] == d) leftCnt++;
        int leftLen = i + 1;
        int rightLen = n - leftLen;
        if (leftCnt * 2 > leftLen && (total - leftCnt) * 2 > rightLen) {
            return i;
        }
    }
    return -1;
}

