int longestValidSubstring(const std::string& word, const std::vector<std::string>& forbidden) {
    std::unordered_set<std::string> forb;
    forb.reserve(forbidden.size() * 2);
    for (const auto& s : forbidden) {
        forb.insert(s);
    }
    const int MAXL = 10;
    int n = static_cast<int>(word.size());
    int left = 0;
    int best = 0;
    for (int i = 0; i < n; ++i) {
        for (int len = 1; len <= MAXL && len <= i + 1; ++len) {
            std::string sub = word.substr(i - len + 1, len);
            if (forb.find(sub) != forb.end()) {
                int start = i - len + 1;
                if (start >= left) {
                    left = start + 1;
                }
            }
        }
        int curLen = i - left + 1;
        if (curLen > best) best = curLen;
    }
    return best;
}

