long long maxScore(const std::vector<int>& nums, int x) {
    if (nums.empty()) return 0;
    const long long NEG = std::numeric_limits<long long>::min() / 4;
    long long bestEven = NEG, bestOdd = NEG;
    long long answer = NEG;
    const long long X = static_cast<long long>(x);
    for (size_t i = 0; i < nums.size(); ++i) {
        long long cur;
        if (i == 0) {
            cur = nums[0];
        } else {
            if (nums[i] % 2 == 0) {
                cur = nums[i] + std::max(bestEven, bestOdd - X);
            } else {
                cur = nums[i] + std::max(bestOdd, bestEven - X);
            }
        }
        if (nums[i] % 2 == 0) {
            bestEven = std::max(bestEven, cur);
        } else {
            bestOdd = std::max(bestOdd, cur);
        }
        answer = std::max(answer, cur);
    }
    return answer;
}

