std::vector<std::string> splitStringsBySeparator(const std::vector<std::string>& words, const std::string& separator) {
    std::vector<std::string> result;
    for (const auto& word : words) {
        if (separator.empty()) {
            for (char c : word) {
                std::string part(1, c);
                if (!part.empty()) result.push_back(part);
            }
