long long countPalindromePairs(const std::vector<int>& parent, const std::string& s) {
    int n = static_cast<int>(parent.size());
    std::vector<std::vector<int>> children(n);
    for (int i = 1; i < n; ++i) {
        children[parent[i]].push_back(i);
    }

    std::unordered_map<int, long long> freq;
    freq.reserve(n * 2);
    freq.max_load_factor(0.7);

    long long ans = 0;
    std::vector<std::pair<int, int>> stack;
    stack.emplace_back(0, 1 << (s[0] - 'a'));

    while (!stack.empty()) {
        int node = stack.back().first;
        int mask = stack.back().second;
        stack.pop_back();

        auto it = freq.find(mask);
        if (it != freq.end()) ans += it->second;
        for (int b = 0; b < 26; ++b) {
            int m2 = mask ^ (1 << b);
            auto it2 = freq.find(m2);
            if (it2 != freq.end()) ans += it2->second;
        }

        ++freq[mask];

        for (int child : children[node]) {
            int newMask = mask ^ (1 << (s[child] - 'a'));
            stack.emplace_back(child, newMask);
        }
    }

    return ans;
}

