int waysToExpress(int n, int x) {
    const int MOD = 1000000007;
    std::vector<int> powers;
    for (int base = 1;; ++base) {
        long long val = 1;
        for (int i = 0; i < x; ++i) {
            val *= base;
            if (val > n) break;
        }
        if (val > n) break;
        powers.push_back(static_cast<int>(val));
    }
    std::vector<int> dp(n + 1, 0);
    dp[0] = 1;
    for (int v : powers) {
        for (int s = n; s >= v; --s) {
            dp[s] += dp[s - v];
            if (dp[s] >= MOD) dp[s] -= MOD;
        }
    }
    return dp[n];
}

