long long countCompleteSubarrays(const std::vector<int>& nums) {
    std::size_t n = nums.size();
    std::size_t required = std::unordered_set<int>(nums.begin(), nums.end()).size();
    std::unordered_map<int, int> freq;
    std::size_t distinct = 0;
    std::size_t right = 0;
    long long answer = 0;

    for (std::size_t left = 0; left < n; ++left) {
        while (right < n && distinct < required) {
            int v = nums[right];
            int cnt = freq[v] + 1;
            freq[v] = cnt;
            if (cnt == 1) ++distinct;
            ++right;
        }

        if (distinct == required) {
            answer += static_cast<long long>(n - (right - 1));
        } else {
            break;
        }

        int vL = nums[left];
        int cntL = freq[vL] - 1;
        if (cntL == 0) {
            freq.erase(vL);
            --distinct;
        } else {
            freq[vL] = cntL;
        }
    }
    return answer;
}

