std::string shortestString(const std::string& a, const std::string& b, const std::string& c) {
    auto isSub = [](const std::string& t, const std::string& s) -> bool {
        return t.find(s) != std::string::npos;
    };
    auto merge = [&](const std::string& s, const std::string& t) -> std::string {
        if (isSub(s, t)) return s;
        size_t max = 0;
        size_t limit = std::min(s.size(), t.size());
        for (size_t k = limit; k > 0; --k) {
            if (s.compare(s.size() - k, k, t, 0, k) == 0) {
                max = k;
                break;
            }
        }
        return s + t.substr(max);
    };

    std::vector<std::string> arr = {a, b, c};
    std::vector<std::string> filtered;
    for (size_t i = 0; i < 3; ++i) {
        bool keep = true;
        for (size_t j = 0; j < 3; ++j) {
            if (i != j && isSub(arr[j], arr[i])) {
                keep = false;
                break;
            }
        }
        if (keep) filtered.push_back(arr[i]);
    }

    size_t n = filtered.size();
    if (n == 0) return "";
    if (n == 1) return filtered[0];

    std::vector<std::vector<std::string>> perms;
    std::vector<bool> used(n, false);
    std::vector<std::string> cur;
    std::function<void()> dfs = [&]() {
        if (cur.size() == n) {
            perms.push_back(cur);
            return;
        }
        for (size_t i = 0; i < n; ++i) {
            if (!used[i]) {
                used[i] = true;
                cur.push_back(filtered[i]);
                dfs();
                cur.pop_back();
                used[i] = false;
            }
        }
    };
    dfs();

    std::string best;
    bool first = true;
    for (const auto& p : perms) {
        std::string merged = p[0];
        for (size_t i = 1; i < p.size(); ++i) {
            merged = merge(merged, p[i]);
        }
        if (first || merged.size() < best.size() || (merged.size() == best.size() && merged < best)) {
            best = merged;
            first = false;
        }
    }
    return best;
}

