static int gcd(int a, int b) {
    while (b != 0) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

ListNode* insertGreatestCommonDivisors(ListNode* head) {
    if (!head || !head->next) return head;
    ListNode* cur = head;
    while (cur && cur->next) {
        int g = gcd(cur->val, cur->next->val);
        ListNode* gNode = new ListNode(g);
        gNode->next = cur->next;
        cur->next = gNode;
        cur = gNode->next;
    }
    return head;
}

