static const long long MOD = 1000000007LL;
static long long dp[105][11][2][2];
static std::string boundStr;

static long long dfs(int pos, int prev, int tight, int started) {
    if (pos == (int)boundStr.size()) return started ? 1 : 0;
    long long &res = dp[pos][prev + 1][tight][started];
    if (res != -1) return res;
    res = 0;
    int limit = tight ? boundStr[pos] - '0' : 9;
    for (int d = 0; d <= limit; ++d) {
        int ntight = tight && (d == limit);
        int nstarted = started || (d != 0);
        if (!nstarted) {
            res = (res + dfs(pos + 1, -1, ntight, 0)) % MOD;
        } else {
            if (!started) {
                res = (res + dfs(pos + 1, d, ntight, 1)) % MOD;
            } else {
                if (std::abs(d - prev) == 1) {
                    res = (res + dfs(pos + 1, d, ntight, 1)) % MOD;
                }
            }
        }
    }
    return res;
}

static long long countUpTo(const std::string &s) {
    boundStr = s;
    std::memset(dp, -1, sizeof(dp));
    return dfs(0, -1, 1, 0);
}

static std::string decrementString(std::string s) {
    int i = (int)s.size() - 1;
    while (i >= 0 && s[i] == '0') {
        s[i] = '9';
        --i;
    }
    if (i >= 0) {
        s[i]--;
    }
    size_t pos = s.find_first_not_of('0');
    if (pos == std::string::npos) return "0";
    return s.substr(pos);
}

int countSteppingNumbers(std::string low, std::string high) {
    std::string lowMinusOne = decrementString(low);
    long long highCount = countUpTo(high);
    long long lowCount = countUpTo(lowMinusOne);
    long long ans = (highCount - lowCount) % MOD;
    if (ans < 0) ans += MOD;
    return (int)ans;
}

