class Solution {
public:
    int minimumTime(vector<int>& nums1, vector<int>& nums2, int x) {
        int n = nums1.size();
        vector<pair<int,int>> pairs(n);
        for (int i = 0; i < n; i++) pairs[i] = {nums2[i], nums1[i]};
        sort(pairs.begin(), pairs.end()); // sort by growth rate (nums2) ascending
        // dp[j] = max total reduction achievable by resetting j elements, where the item
        // reset j-th (1-indexed, in growth-rate order) contributes nums1[i] + nums2[i]*j
        vector<long long> dp(n + 1, 0);
        for (int idx = 0; idx < n; idx++) {
            long long b = pairs[idx].first, a = pairs[idx].second;
            for (int j = idx + 1; j >= 1; j--) {
                dp[j] = max(dp[j], dp[j - 1] + a + b * j);
            }
        }
        long long s1 = 0, s2 = 0;
        for (int v : nums1) s1 += v;
        for (int v : nums2) s2 += v;
        for (int t = 0; t <= n; t++) {
            if (s1 + s2 * t - dp[t] <= x) return t;
        }
        return -1;
    }
};

