long long maxElegance(std::vector<std::vector<long long>>& items, int k) {
    std::sort(items.begin(), items.end(), [](const std::vector<long long>& a, const std::vector<long long>& b) {
        return a[0] > b[0];
    });

    std::unordered_set<long long> seen;
    std::priority_queue<long long, std::vector<long long>, std::greater<long long>> dupHeap;
    long long profitSum = 0;
    long long distinct = 0;

    for (int i = 0; i < k; ++i) {
        long long p = items[i][0];
        long long c = items[i][1];
        profitSum += p;
        if (seen.count(c)) {
            dupHeap.push(p);
        } else {
            seen.insert(c);
            ++distinct;
        }
    }

    long long best = profitSum + distinct * distinct;

    for (size_t i = k; i < items.size(); ++i) {
        long long p = items[i][0];
        long long c = items[i][1];
        if (seen.count(c)) continue;
        if (dupHeap.empty()) break;
        long long removed = dupHeap.top();
        dupHeap.pop();
        profitSum = profitSum - removed + p;
        seen.insert(c);
        ++distinct;
        long long cur = profitSum + distinct * distinct;
        if (cur > best) best = cur;
    }

    return best;
}

#include <bits/stdc++.h>

int minimumSeconds(std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    struct Info { int first; int prev; int max_gap; bool seen; };
    std::unordered_map<int, Info> mp;
    mp.reserve(nums.size() * 2);
    for (int i = 0; i < n; ++i) {
        int v = nums[i];
        auto &info = mp[v];
        if (!info.seen) {
            info.first = info.prev = i;
            info.max_gap = 0;
            info.seen = true;
        } else {
            int gap = i - info.prev - 1;
            if (gap > info.max_gap) info.max_gap = gap;
            info.prev = i;
        }
    }
    int answer = INT_MAX;
    for (auto &p : mp) {
        Info &info = p.second;
        int circular_gap = (info.first + n) - info.prev - 1;
        if (circular_gap > info.max_gap) info.max_gap = circular_gap;
        int seconds = (info.max_gap + 1) / 2;
        if (seconds < answer) answer = seconds;
    }
    return answer;
}

