ListNode* doubleLinkedList(ListNode* head) {
    ListNode* prev = nullptr;
    ListNode* cur = head;
    while (cur) {
        ListNode* nxt = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nxt;
    }
    ListNode* node = prev;
    int carry = 0;
    ListNode* last = nullptr;
    while (node) {
        int sum = node->val * 2 + carry;
        node->val = sum % 10;
        carry = sum / 10;
        last = node;
        node = node->next;
    }
    if (carry) {
        last->next = new ListNode(carry);
    }
    cur = prev;
    prev = nullptr;
    while (cur) {
        ListNode* nxt = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nxt;
    }
    return prev;
}

