long long minimumAbsoluteDifference(const std::vector<int>& nums, int x) {
    std::multiset<long long> ms;
    long long best = LLONG_MAX;
    for (size_t i = 0; i < nums.size(); ++i) {
        if (i >= static_cast<size_t>(x)) {
            ms.insert(static_cast<long long>(nums[i - x]));
        }
        if (ms.empty()) continue;
        long long cur = static_cast<long long>(nums[i]);
        auto it = ms.lower_bound(cur);
        if (it != ms.end()) {
            long long diff = std::llabs(*it - cur);
            if (diff < best) best = diff;
        }
        if (it != ms.begin()) {
            auto pred = std::prev(it);
            long long diff = std::llabs(*pred - cur);
            if (diff < best) best = diff;
        }
        if (best == 0) break;
    }
    return best == LLONG_MAX ? 0 : best;
}

