int maximumSafenessFactor(std::vector<std::vector<int>>& grid) {
    int n = static_cast<int>(grid.size());
    if (n == 0) return 0;
    int total = n * n;
    std::vector<int> dist(total, -1);
    std::queue<int> q;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 1) {
                int idx = i * n + j;
                dist[idx] = 0;
                q.push(idx);
            }
        }
    }
    const int dr[4] = {1, -1, 0, 0};
    const int dc[4] = {0, 0, 1, -1};
    while (!q.empty()) {
        int idx = q.front();
        q.pop();
        int r = idx / n;
        int c = idx % n;
        int d = dist[idx];
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k];
            int nc = c + dc[k];
            if (nr < 0 || nr >= n || nc < 0 || nc >= n) continue;
            int nidx = nr * n + nc;
            if (dist[nidx] == -1) {
                dist[nidx] = d + 1;
                q.push(nidx);
            }
        }
    }
    int INF = n * n;
    for (int i = 0; i < total; ++i) {
        if (dist[i] == -1) dist[i] = INF;
    }
    std::vector<int> best(total, -1);
    std::priority_queue<std::pair<int, int>> pq;
    best[0] = dist[0];
    pq.emplace(best[0], 0);
    int target = total - 1;
    while (!pq.empty()) {
        std::pair<int, int> top = pq.top();
        pq.pop();
        int safety = top.first;
        int idx = top.second;
        if (idx == target) return safety;
        if (safety < best[idx]) continue;
        int r = idx / n;
        int c = idx % n;
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k];
            int nc = c + dc[k];
            if (nr < 0 || nr >= n || nc < 0 || nc >= n) continue;
            int nidx = nr * n + nc;
            int cand = std::min(safety, dist[nidx]);
            if (cand > best[nidx]) {
                best[nidx] = cand;
                pq.emplace(cand, nidx);
            }
        }
    }
    return best[target];
}

