long long maxProfit(int n, std::vector<std::vector<int>> offers) {
    std::sort(offers.begin(), offers.end(),
        [](const std::vector<int>& a, const std::vector<int>& b) {
            return a[1] < b[1];
        });
    int m = static_cast<int>(offers.size());
    std::vector<int> ends(m);
    for (int i = 0; i < m; ++i) ends[i] = offers[i][1];
    std::vector<long long> dp(m + 1, 0);
    for (int i = 1; i <= m; ++i) {
        int start = offers[i - 1][0];
        int gold = offers[i - 1][2];
        int lo = 0, hi = i - 2, pos = 0;
        while (lo <= hi) {
            int mid = (lo + hi) >> 1;
            if (ends[mid] < start) {
                pos = mid + 1;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        dp[i] = std::max(dp[i - 1], static_cast<long long>(gold) + dp[pos]);
    }
    return dp[m];
}

