    long long smallCount = k / 2;
    if (n <= smallCount) {
        return n * (n + 1) / 2;
    }
    long long sumSmall = smallCount * (smallCount + 1) / 2;
    long long extra = n - smallCount;
    long long sumExtra = extra * k + extra * (extra - 1) / 2;
