static long long memo[20][41][21][2];
static bool seen[20][41][21][2];
static string digitsStr;
static int lenDigits;
static int K;
static const int OFFSET = 20;

static long long dfs(int pos, int diff, int rem, bool started, bool tight) {
    if (pos == lenDigits) {
        return (started && diff == 0 && rem == 0) ? 1LL : 0LL;
    }
    if (!tight && seen[pos][diff + OFFSET][rem][started]) {
        return memo[pos][diff + OFFSET][rem][started];
    }
    int limit = tight ? (digitsStr[pos] - '0') : 9;
    long long ans = 0;
    for (int d = 0; d <= limit; ++d) {
        bool nStarted = started || (d != 0);
        int nDiff = diff;
        if (nStarted) {
            if (d % 2 == 0) --nDiff;
            else ++nDiff;
        }
        int nRem = (rem * 10 + d) % K;
        bool nTight = tight && (d == limit);
        ans += dfs(pos + 1, nDiff, nRem, nStarted, nTight);
    }
    if (!tight) {
        seen[pos][diff + OFFSET][rem][started] = true;
        memo[pos][diff + OFFSET][rem][started] = ans;
    }
    return ans;
}

