int longestEqualSubarray(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;
    std::unordered_map<int, int> cnt;
    std::vector<int> freqCount(n + 1, 0);
    int left = 0;
    int maxFreq = 0;
    int answer = 0;
    for (int right = 0; right < n; ++right) {
        int v = nums[right];
        int old = cnt[v];
        if (old > 0) --freqCount[old];
        ++cnt[v];
        int cur = cnt[v];
        ++freqCount[cur];
        if (cur > maxFreq) maxFreq = cur;
        while ((right - left + 1) - maxFreq > k) {
            int vl = nums[left];
            int oldl = cnt[vl];
            --freqCount[oldl];
            --cnt[vl];
            int newl = cnt[vl];
            if (newl > 0) ++freqCount[newl];
            ++left;
            while (maxFreq > 0 && freqCount[maxFreq] == 0) --maxFreq;
        }
        answer = std::max(answer, maxFreq);
    }
    return answer;
}

