long long minimumPossibleSum(long long n, long long target) {
    const long long MOD = 1000000007LL;
    const long long INV2 = 500000004LL; // modular inverse of 2 modulo MOD
    long long a = target / 2; // floor(target/2)
    long long sum = 0;
    if (n <= a) {
        long long nn = n % MOD;
        sum = nn * ((nn + 1) % MOD) % MOD;
        sum = sum * INV2 % MOD;
        return sum;
    }
    // take all numbers 1..a
    long long aa = a % MOD;
    long long sumLow = aa * ((aa + 1) % MOD) % MOD;
    sumLow = sumLow * INV2 % MOD;
    long long r = n - a; // remaining numbers starting from target
    long long rr = r % MOD;
    long long tt = target % MOD;
    long long term = ( (2LL * tt) % MOD + ((r - 1) % MOD + MOD) % MOD ) % MOD;
    long long sumHigh = rr * term % MOD;
    sumHigh = sumHigh * INV2 % MOD;
    sum = (sumLow + sumHigh) % MOD;
    return sum;
}

