long long getMaxFunctionValue(const std::vector<int>& receiver, long long k) {
    int n = static_cast<int>(receiver.size());
    long long stepsNeeded = k + 1;
    int LOG = 0;
    while ((1LL << LOG) <= stepsNeeded) ++LOG;
    std::vector<std::vector<int>> nxt(LOG, std::vector<int>(n));
    std::vector<std::vector<long long>> sum(LOG, std::vector<long long>(n));
    for (int i = 0; i < n; ++i) {
        nxt[0][i] = receiver[i];
        sum[0][i] = i;
    }
    for (int j = 1; j < LOG; ++j) {
        for (int i = 0; i < n; ++i) {
            int mid = nxt[j - 1][i];
            nxt[j][i] = nxt[j - 1][mid];
            sum[j][i] = sum[j - 1][i] + sum[j - 1][mid];
        }
    }
    long long best = 0;
    for (int start = 0; start < n; ++start) {
        long long remaining = stepsNeeded;
        long long cur = start;
        long long total = 0;
        for (int j = LOG - 1; j >= 0; --j) {
            if ((1LL << j) <= remaining) {
                total += sum[j][cur];
                cur = nxt[j][cur];
                remaining -= (1LL << j);
            }
        }
        if (total > best) best = total;
    }
    return best;
}

