long long maxSumAlmostUnique(const std::vector<int>& nums, int m, int k) {
    if (k > static_cast<int>(nums.size()) || m > k) return 0;

    std::unordered_map<int, int> freq;
    int distinctCnt = 0;
    long long curSum = 0;

    for (int i = 0; i < k; ++i) {
        curSum += nums[i];
        if (++freq[nums[i]] == 1) ++distinctCnt;
    }

    long long maxSum = (distinctCnt >= m) ? curSum : 0;

    for (int i = k; i < static_cast<int>(nums.size()); ++i) {
        int left = nums[i - k];
        int right = nums[i];

        if (--freq[left] == 0) --distinctCnt;
        curSum -= left;

        if (++freq[right] == 1) ++distinctCnt;
        curSum += right;

        if (distinctCnt >= m && curSum > maxSum) {
            maxSum = curSum;
        }
    }

    return maxSum;
}

#include <bits/stdc++.h>

int minOperations(const std::vector<int>& nums, int target) {
    const int MAX_BITS = 31;
    int cnt[MAX_BITS] = {};
    for (int v : nums) {
        int e = __builtin_ctz(v);
        cnt[e]++;
    }
    int ops = 0;
    for (int i = 0; i < MAX_BITS; ++i) {
        if ((target >> i) & 1) {
            if (cnt[i] > 0) {
                cnt[i]--;
            } else {
                int j = i + 1;
                while (j < MAX_BITS && cnt[j] == 0) ++j;
                if (j == MAX_BITS) return -1;
                while (j > i) {
                    cnt[j]--;
                    cnt[j - 1] += 2;
                    ++ops;
                    --j;
                }
                cnt[i]--;
            }
        }
        if (i + 1 < MAX_BITS) {
            cnt[i + 1] += cnt[i] / 2;
        }
    }
    return ops;
}

