#include <bits/stdc++.h>

std::vector<int> minimumEdgeWeightEquilibriumQueries(int n, std::vector<std::vector<int>>& edges, std::vector<std::vector<int>>& queries) {
    const int MAXW = 27; // weights are 1..26
    const int LOG = 17;  // sufficient for n up to 1e5+
    std::vector<std::vector<std::pair<int,int>>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1], w = e[2];
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }
    std::vector<int> parent(n, -1), depth(n, 0);
    std::vector<std::array<int, MAXW>> pref(n);
    for (auto& a : pref) a.fill(0);
    std::stack<int> st;
    st.push(0);
    while (!st.empty()) {
        int v = st.top(); st.pop();
        for (const auto& edge : adj[v]) {
            int to = edge.first, w = edge.second;
            if (to == parent[v]) continue;
            parent[to] = v;
            depth[to] = depth[v] + 1;
            pref[to] = pref[v];
            pref[to][w] += 1;
            st.push(to);
        }
    }
    std::vector<std::array<int, LOG>> up(n);
    for (int i = 0; i < n; ++i) up[i].fill(-1);
    for (int i = 0; i < n; ++i) up[i][0] = parent[i];
    for (int k = 1; k < LOG; ++k) {
        for (int i = 0; i < n; ++i) {
            int mid = up[i][k-1];
            up[i][k] = (mid != -1) ? up[mid][k-1] : -1;
        }
    }
    auto lca = [&](int a, int b) {
        if (depth[a] < depth[b]) std::swap(a, b);
        int diff = depth[a] - depth[b];
        for (int k = 0; k < LOG; ++k) {
            if (diff & (1 << k)) a = up[a][k];
        }
        if (a == b) return a;
        for (int k = LOG - 1; k >= 0; --k) {
            if (up[a][k] != -1 && up[a][k] != up[b][k]) {
                a = up[a][k];
                b = up[b][k];
            }
        }
        return parent[a];
    };
    std::vector<int> ans;
    ans.reserve(queries.size());
    for (const auto& q : queries) {
        int a = q[0], b = q[1];
        int L = lca(a, b);
        int pathLen = depth[a] + depth[b] - 2 * depth[L];
        int maxFreq = 0;
        for (int w = 1; w < MAXW; ++w) {
            int cnt = pref[a][w] + pref[b][w] - 2 * pref[L][w];
            if (cnt > maxFreq) maxFreq = cnt;
        }
        ans.push_back(pathLen - maxFreq);
    }
    return ans;
}

#include <bits/stdc++.h>

int countSymmetricIntegers(int low, int high) {
    int answer = 0;
    int pow10[11];
    pow10[0] = 1;
    for (int i = 1; i < 11; ++i) pow10[i] = pow10[i - 1] * 10;
    for (int x = low; x <= high; ++x) {
        int len = (x == 0) ? 1 : static_cast<int>(std::log10(x)) + 1;
        if (len % 2 != 0) continue;
        int half = len / 2;
        int left = x / pow10[half];
        int right = x % pow10[half];
        int leftSum = 0, rightSum = 0;
        while (left > 0) {
            leftSum += left % 10;
            left /= 10;
        }
        for (int i = 0; i < half; ++i) {
            rightSum += right % 10;
            right /= 10;
        }
        if (leftSum == rightSum) ++answer;
    }
    return answer;
}

