#include <bits/stdc++.h>
const long long MOD = 1000000007LL;

static long long modPow(long long a, long long e) {
    long long r = 1 % MOD;
    a %= MOD;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

static long long modInv(long long x) {
    return modPow(x, MOD - 2);
}

int countKSubsequencesWithMaximumBeauty(const std::string& s, int k) {
    if (k == 0) return 1;
    std::vector<int> freq(26, 0);
    for (char ch : s) freq[ch - 'a']++;
    std::vector<int> vals;
    for (int f : freq) if (f > 0) vals.push_back(f);
    int distinct = (int)vals.size();
    if (k > distinct) return 0;
    std::sort(vals.begin(), vals.end(), std::greater<int>());
    int threshold = vals[k - 1];
    int cntGreater = 0, cntEqual = 0;
    long long prodGreater = 1;
    for (int f : vals) {
        if (f > threshold) {
            ++cntGreater;
            prodGreater = prodGreater * f % MOD;
        } else if (f == threshold) {
            ++cntEqual;
        } else break;
    }
    int needFromEqual = k - cntGreater;
    static long long fact[27] = {0}, invFact[27] = {0};
    if (fact[0] == 0) {
        fact[0] = 1;
        for (int i = 1; i <= 26; ++i) fact[i] = fact[i - 1] * i % MOD;
        invFact[26] = modInv(fact[26]);
        for (int i = 25; i >= 0; --i) invFact[i] = invFact[i + 1] * (i + 1) % MOD;
    }
    auto C = [&](int n, int r) -> long long {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    };
    long long comb = C(cntEqual, needFromEqual);
    long long powThresh = modPow(threshold, needFromEqual);
    long long ans = comb * prodGreater % MOD * powThresh % MOD;
    return (int)ans;
}

