int minMoves(const std::vector<std::vector<int>>& grid) {
    std::vector<std::pair<int, int>> stones;
    for (int r = 0; r < 3; ++r) {
        for (int c = 0; c < 3; ++c) {
            int cnt = grid[r][c];
            for (int i = 0; i < cnt; ++i) {
                stones.emplace_back(r, c);
            }
        }
    }

    std::vector<std::pair<int, int>> targets;
    for (int r = 0; r < 3; ++r) {
        for (int c = 0; c < 3; ++c) {
            targets.emplace_back(r, c);
        }
    }

    const int n = 9;
    std::vector<std::vector<int>> dist(n, std::vector<int>(n, 0));
    for (int i = 0; i < n; ++i) {
        int sr = stones[i].first;
        int sc = stones[i].second;
        for (int j = 0; j < n; ++j) {
            int tr = targets[j].first;
            int tc = targets[j].second;
            dist[i][j] = std::abs(sr - tr) + std::abs(sc - tc);
        }
    }

    const int INF = 1000000000;
    const int size = 1 << n;
    std::vector<int> dp(size, INF);
    dp[0] = 0;

    for (int mask = 0; mask < size; ++mask) {
        int k = __builtin_popcount(mask);
        if (k >= n) continue;
        int cur = dp[mask];
        if (cur == INF) continue;
        for (int j = 0; j < n; ++j) {
            if (mask & (1 << j)) continue;
            int nextMask = mask | (1 << j);
            int cand = cur + dist[k][j];
            if (cand < dp[nextMask]) dp[nextMask] = cand;
        }
    }
    return dp[size - 1];
}

