class Solution {
public:
    static const long long MOD = 1000000007;

    vector<vector<long long>> matMul(vector<vector<long long>>& a, vector<vector<long long>>& b) {
        vector<vector<long long>> r(2, vector<long long>(2, 0));
        for (int i = 0; i < 2; i++)
            for (int j = 0; j < 2; j++) {
                long long sum = 0;
                for (int x = 0; x < 2; x++) sum = (sum + a[i][x] * b[x][j]) % MOD;
                r[i][j] = sum;
            }
        return r;
    }

    vector<vector<long long>> matPow(vector<vector<long long>> m, long long e) {
        vector<vector<long long>> result = {{1, 0}, {0, 1}};
        while (e > 0) {
            if (e & 1) result = matMul(result, m);
            m = matMul(m, m);
            e >>= 1;
        }
        return result;
    }

    int numberOfWays(string s, string t, long long k) {
        int n = s.size();
        vector<vector<long long>> trans = {{0, 1}, {(long long)(n - 1), (long long)(n - 2)}};
        auto p = matPow(trans, k);
        long long dp0 = p[0][0], dp1 = p[0][1];

        string combined = s + t + t;
        int m = combined.size();
        vector<int> z(m, 0);
        int left = 0, right = 0;
        for (int i = 1; i < m; i++) {
            int zi = 0;
            if (i <= right && z[i - left] <= right - i) {
                zi = z[i - left];
            } else {
                zi = max(0, right - i + 1);
                while (i + zi < m && combined[i + zi] == combined[zi]) zi++;
            }
            z[i] = zi;
            if (i + zi - 1 > right) { left = i; right = i + zi - 1; }
        }

        long long result = 0;
        for (int i = n; i < 2 * n; i++) {
            if (z[i] >= n) {
                int rot = i - n;
                result = (result + (rot == 0 ? dp0 : dp1)) % MOD;
            }
        }
        return (int) result;
    }
};

