    std::sort(nums.begin(), nums.end(), [](const std::vector<long long>& a, const std::vector<long long>& b) {
        return a[0] < b[0];
    });
    long long total = 0;
    long long curStart = nums[0][0];
    long long curEnd = nums[0][1];
    for (size_t i = 1; i < nums.size(); ++i) {
        long long s = nums[i][0];
        long long e = nums[i][1];
        if (s <= curEnd + 1) {
            if (e > curEnd) curEnd = e;
        } else {
            total += curEnd - curStart + 1;
            curStart = s;
            curEnd = e;
        }
    }
    total += curEnd - curStart + 1;
    return total;
}

