long long countPairs(const std::vector<std::pair<int, int>>& coordinates, int k) {
    std::unordered_map<std::uint64_t, int> freq;
    freq.reserve(coordinates.size() * 2);
    for (const auto& p : coordinates) {
        std::uint64_t key = (static_cast<std::uint64_t>(static_cast<std::uint32_t>(p.first)) << 32) |
                           static_cast<std::uint64_t>(static_cast<std::uint32_t>(p.second));
        ++freq[key];
    }

    long long ans = 0;
    for (const auto& p : coordinates) {
        std::uint64_t curKey = (static_cast<std::uint64_t>(static_cast<std::uint32_t>(p.first)) << 32) |
                               static_cast<std::uint64_t>(static_cast<std::uint32_t>(p.second));
        auto curIt = freq.find(curKey);
        if (curIt != freq.end()) {
            --curIt->second;
        }

        for (int a = 0; a <= k; ++a) {
            int b = k - a;
            int nx = p.first ^ a;
            int ny = p.second ^ b;
            std::uint64_t partnerKey = (static_cast<std::uint64_t>(static_cast<std::uint32_t>(nx)) << 32) |
                                       static_cast<std::uint64_t>(static_cast<std::uint32_t>(ny));
            auto it = freq.find(partnerKey);
            if (it != freq.end()) {
                ans += it->second;
            }
        }
    }

    return ans;
}

