long long countInterestingSubarrays(const std::vector<long long>& nums, long long modulo, long long k) {
    std::unordered_map<long long, long long> freq;
    freq[0] = 1;
    long long prefix = 0;
    long long answer = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        if (nums[i] % modulo == k) ++prefix;
        long long curMod = prefix % modulo;
        long long need = (curMod - k + modulo) % modulo;
        auto it = freq.find(need);
        if (it != freq.end()) answer += it->second;
        ++freq[curMod];
    }
    return answer;
}

