long long maxCompleteSubsetSum(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    std::vector<unsigned int> spf(n + 1);
    for (int i = 2; i <= n; ++i) {
        if (spf[i] == 0) {
            for (int j = i; j <= n; j += i) {
                if (spf[j] == 0) spf[j] = i;
            }
        }
    }

    std::unordered_map<unsigned long long, long long> groupSum;
    long long best = LLONG_MIN;

    for (int idx = 1; idx <= n; ++idx) {
        int x = idx;
        unsigned long long sqFree = 1;
        while (x > 1) {
            unsigned int p = spf[x];
            int cnt = 0;
            while (x % p == 0) {
                x /= p;
                ++cnt;
            }
            if (cnt & 1) sqFree *= p;
        }
        unsigned long long key = sqFree;
        long long newSum = groupSum[key] + nums[idx - 1];
        groupSum[key] = newSum;
        if (newSum > best) best = newSum;
    }
    return best;
}

