long long maxAlloys(int n, int k, long long budget, const std::vector<std::vector<long long>>& composition, const std::vector<long long>& stock, const std::vector<long long>& cost) {
    long long stockValue = 0;
    for (int j = 0; j < n; ++j) {
        stockValue += stock[j] * cost[j];
    }

    long long best = 0;

    for (int i = 0; i < k; ++i) {
        long long baseCost = 0;
        for (int j = 0; j < n; ++j) {
            baseCost += composition[i][j] * cost[j];
        }

        if (baseCost == 0) continue;

        long long high = (budget + stockValue) / baseCost;
        long long low = 0;

        while (low < high) {
            long long mid = (low + high + 1) / 2;
            long long needed = 0;
            for (int j = 0; j < n; ++j) {
                long long required = mid * composition[i][j];
                if (required > stock[j]) {
                    needed += (required - stock[j]) * cost[j];
                    if (needed > budget) break;
                }
            }
            if (needed <= budget) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }

        if (low > best) best = low;
    }

    return best;
}

class Solution {
public:
    int countWays(vector<int>& nums) {
        int n = nums.size();
        sort(nums.begin(), nums.end());
        int count = 0;
        for (int k = 0; k <= n; k++) {
            bool leftOk = (k == 0) || (nums[k-1] < k);
            bool rightOk = (k == n) || (nums[k] > k);
            if (leftOk && rightOk) count++;
        }
        return count;
    }
};

