long long maximumSum(std::vector<int> maxHeights) {
    int n = static_cast<int>(maxHeights.size());
    std::vector<long long> left(n), right(n);
    std::stack<int> st;
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && maxHeights[st.top()] >= maxHeights[i]) st.pop();
        if (st.empty()) left[i] = static_cast<long long>(i + 1) * maxHeights[i];
        else {
            int prev = st.top();
            left[i] = left[prev] + static_cast<long long>(i - prev) * maxHeights[i];
        }
        st.push(i);
    }
    while (!st.empty()) st.pop();
    long long ans = 0;
    for (int i = n - 1; i >= 0; --i) {
        while (!st.empty() && maxHeights[st.top()] >= maxHeights[i]) st.pop();
        if (st.empty()) right[i] = static_cast<long long>(n - i) * maxHeights[i];
        else {
            int nxt = st.top();
            right[i] = right[nxt] + static_cast<long long>(nxt - i) * maxHeights[i];
        }
        long long total = left[i] + right[i] - maxHeights[i];
        if (total > ans) ans = total;
        st.push(i);
    }
    return ans;
}

