#include <bits/stdc++.h>

long long maximumSum(const std::vector<int>& heights) {
    std::size_t n = heights.size();
    if (n == 0) return 0;
    std::vector<long long> leftSum(n), rightSum(n);
    std::vector<std::size_t> st;
    st.reserve(n);
    for (std::size_t i = 0; i < n; ++i) {
        while (!st.empty() && heights[st.back()] >= heights[i]) st.pop_back();
        if (st.empty()) {
            leftSum[i] = static_cast<long long>(heights[i]) * (i + 1);
        } else {
            std::size_t prev = st.back();
            leftSum[i] = leftSum[prev] + static_cast<long long>(heights[i]) * (i - prev);
        }
        st.push_back(i);
    }
    st.clear();
    for (std::size_t idx = n; idx-- > 0;) {
        while (!st.empty() && heights[st.back()] >= heights[idx]) st.pop_back();
        if (st.empty()) {
            rightSum[idx] = static_cast<long long>(heights[idx]) * (n - idx);
        } else {
            std::size_t nxt = st.back();
            rightSum[idx] = rightSum[nxt] + static_cast<long long>(heights[idx]) * (nxt - idx);
        }
        st.push_back(idx);
    }
    long long ans = 0;
    for (std::size_t i = 0; i < n; ++i) {
        long long total = leftSum[i] + rightSum[i] - heights[i];
        if (total > ans) ans = total;
    }
    return ans;
}

