long long countValidPaths(int n, const std::vector<std::vector<int>>& edges) {
    std::vector<char> isPrime(n + 1, 0);
    if (n >= 2) {
        std::fill(isPrime.begin() + 2, isPrime.end(), 1);
        int limit = static_cast<int>(std::sqrt(n));
        for (int i = 2; i <= limit; ++i) {
            if (isPrime[i]) {
                for (int j = i * i; j <= n; j += i) {
                    isPrime[j] = 0;
                }
            }
        }
    }

    std::vector<std::vector<int>> adj(n + 1);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    std::vector<int> compId(n + 1, 0);
    std::vector<int> compSize(1, 0);
    int compCnt = 0;
    std::vector<int> stack;
    for (int i = 1; i <= n; ++i) {
        if (isPrime[i] || compId[i]) continue;
        ++compCnt;
        compSize.push_back(0);
        int size = 0;
        stack.push_back(i);
        compId[i] = compCnt;
        while (!stack.empty()) {
            int node = stack.back();
            stack.pop_back();
            ++size;
            for (int nb : adj[node]) {
                if (!isPrime[nb] && !compId[nb]) {
                    compId[nb] = compCnt;
                    stack.push_back(nb);
                }
            }
        }
        compSize[compCnt] = size;
    }

    long long answer = 0;
    for (int p = 1; p <= n; ++p) {
        if (!isPrime[p]) continue;
        long long total = 0;
        long long sumSq = 0;
        for (int nb : adj[p]) {
            if (isPrime[nb]) continue;
            int sz = compSize[compId[nb]];
            total += sz;
            sumSq += static_cast<long long>(sz) * sz;
        }
        if (total == 0) continue;
        long long contribution = total + (total * total - sumSq) / 2;
        answer += contribution;
    }
    return answer;
}

