struct Result {
    long long modSum;
    long long compCnt;
};

static Result dfs(int u, int parent, const std::vector<std::vector<int>>& adj, const std::vector<long long>& values, long long k) {
    long long sumMod = values[u] % k;
    long long comps = 0;
    for (int v : adj[u]) {
        if (v == parent) continue;
        Result child = dfs(v, u, adj, values, k);
        if (child.modSum == 0) {
            comps += child.compCnt + 1;
        } else {
            comps += child.compCnt;
            sumMod = (sumMod + child.modSum) % k;
        }
    }
    return {sumMod, comps};
}

long long maxKDivisibleComponents(int n, const std::vector<std::pair<int, int>>& edges, const std::vector<long long>& values, long long k) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        adj[e.first].push_back(e.second);
        adj[e.second].push_back(e.first);
    }
    Result root = dfs(0, -1, adj, values, k);
    return root.compCnt + (root.modSum == 0 ? 1 : 0);
}

