long long maxTripletValue(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n < 3) return 0;
    long long maxPrefix = nums[0];
    long long bestDiff = LLONG_MIN;
    long long answer = LLONG_MIN;
    for (int idx = 1; idx < n; ++idx) {
        if (idx >= 2 && bestDiff != LLONG_MIN) {
            answer = std::max(answer, bestDiff * static_cast<long long>(nums[idx]));
        }
        long long diff = maxPrefix - static_cast<long long>(nums[idx]);
        if (diff > bestDiff) bestDiff = diff;
        if (static_cast<long long>(nums[idx]) > maxPrefix) maxPrefix = nums[idx];
    }
    if (answer == LLONG_MIN || answer < 0) return 0;
    return answer;
}

