long long maximumTripletValue(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n < 3) return 0;
    std::vector<int> prefixMax(n), prefixMin(n);
    std::vector<int> suffixMax(n), suffixMin(n);
    prefixMax[0] = nums[0];
    prefixMin[0] = nums[0];
    for (int i = 1; i < n; ++i) {
        prefixMax[i] = std::max(prefixMax[i - 1], nums[i]);
        prefixMin[i] = std::min(prefixMin[i - 1], nums[i]);
    }
    suffixMax[n - 1] = nums[n - 1];
    suffixMin[n - 1] = nums[n - 1];
    for (int i = n - 2; i >= 0; --i) {
        suffixMax[i] = std::max(suffixMax[i + 1], nums[i]);
        suffixMin[i] = std::min(suffixMin[i + 1], nums[i]);
    }
    long long best = LLONG_MIN;
    for (int j = 1; j <= n - 2; ++j) {
        long long maxX = static_cast<long long>(prefixMax[j - 1]) - nums[j];
        long long minX = static_cast<long long>(prefixMin[j - 1]) - nums[j];
        long long maxY = suffixMax[j + 1];
        long long minY = suffixMin[j + 1];
        long long candidates[4] = {
            maxX * maxY,
            maxX * minY,
            minX * maxY,
            minX * minY
        };
        for (long long cand : candidates) {
            if (cand > best) best = cand;
        }
    }
    return best > 0 ? best : 0;
}

#include <bits/stdc++.h>
