std::vector<int> countVisitedNodes(const std::vector<int>& edges) {
    int n = static_cast<int>(edges.size());
    std::vector<int> answer(n, 0);
    std::vector<unsigned char> visited(n, 0); // 0 = unvisited, 1 = in current walk, 2 = done

    for (int start = 0; start < n; ++start) {
        if (answer[start]) continue;

        int cur = start;
        std::vector<int> stack;

        while (visited[cur] == 0) {
            visited[cur] = 1;
            stack.push_back(cur);
            cur = edges[cur];
        }

        if (visited[cur] == 1) {
            int cycleLen = 1;
            int node = edges[cur];
            while (node != cur) {
                ++cycleLen;
                node = edges[node];
            }
            node = cur;
            do {
                answer[node] = cycleLen;
                visited[node] = 2;
                node = edges[node];
            } while (node != cur);
        }

        while (!stack.empty()) {
            int node = stack.back();
            stack.pop_back();
            if (answer[node]) {
                visited[node] = 2;
                continue;
            }
            int nxt = edges[node];
            answer[node] = answer[nxt] + 1;
            visited[node] = 2;
        }
    }
    return answer;
}

