long long minimumSizeSubarrayInInfiniteArray(const std::vector<long long>& nums, long long target) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return -1;
    std::vector<long long> prefix(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        prefix[i] = prefix[i - 1] + nums[i - 1];
    }
    long long totalSum = prefix[n];
    if (totalSum == 0) {
        // Only sums achievable within one period are possible.
        std::unordered_map<long long, int> firstIdx;
        for (int i = 0; i <= n; ++i) {
            if (firstIdx.find(prefix[i]) == firstIdx.end())
                firstIdx[prefix[i]] = i;
        }
        long long answer = LLONG_MAX;
        for (int s = 0; s < n; ++s) {
            long long needed = target + prefix[s];
            auto it = firstIdx.find(needed);
            if (it != firstIdx.end() && it->second > s) {
                answer = std::min(answer, static_cast<long long>(it->second - s));
            }
        }
        return answer == LLONG_MAX ? -1 : answer;
    }

    std::unordered_map<long long, int> firstIdx;
    for (int i = 0; i <= n; ++i) {
        if (firstIdx.find(prefix[i]) == firstIdx.end())
            firstIdx[prefix[i]] = i;
    }

    long long answer = LLONG_MAX;
    for (int s = 0; s < n; ++s) {
        long long startPref = prefix[s];
        long long sumToEnd = totalSum - startPref;

        if (target == sumToEnd) {
            answer = std::min(answer, static_cast<long long>(n - s));
            continue;
        }

        if (target < sumToEnd) {
            long long needed = target + startPref;
            auto it = firstIdx.find(needed);
            if (it != firstIdx.end() && it->second > s) {
                answer = std::min(answer, static_cast<long long>(it->second - s));
            }
            continue;
        }

        long long remaining = target - sumToEnd;
        long long cycles = remaining / totalSum;
        long long leftover = remaining - cycles * totalSum;

        if (leftover == 0) {
            long long len = static_cast<long long>(n - s) + cycles * n;
            answer = std::min(answer, len);
        } else {
            auto it = firstIdx.find(leftover);
            if (it != firstIdx.end()) {
                long long len = static_cast<long long>(n - s) + cycles * n + it->second;
                answer = std::min(answer, len);
            }
        }
    }
    return answer == LLONG_MAX ? -1 : answer;
}

