int minCostToMakeEqual(const std::string& s1, const std::string& s2, int x) {
    int n = static_cast<int>(s1.size());
    std::vector<int> diff;
    diff.reserve(n);
    for (int i = 0; i < n; ++i) {
        if (s1[i] != s2[i]) diff.push_back(i);
    }
    int m = static_cast<int>(diff.size());
    if (m == 0) return 0;
    if (m % 2 == 1) return -1;
    if (x >= 2) return (m / 2) * 2;
    const int INF = 1e9;
    std::vector<int> dp(m + 1, INF);
    dp[0] = 0;
    for (int i = 2; i <= m; i += 2) {
        // Pair the last two mismatches as non‑adjacent (cost 2)
        dp[i] = std::min(dp[i], dp[i - 2] + 2);
        // If they are adjacent, we may use the cheaper operation of cost x
        if (diff[i - 1] == diff[i - 2] + 1) {
            dp[i] = std::min(dp[i], dp[i - 2] + x);
        }
    }
    return dp[m] >= INF ? -1 : dp[m];
}

