long long maxSumOfSquares(const std::vector<int>& nums, int k) {
    const long long MOD = 1000000007LL;
    std::vector<int> bitCounts(31, 0);
    for (int x : nums) {
        for (int b = 0; b < 31; ++b) {
            if (x & (1 << b)) ++bitCounts[b];
        }
    }
    std::vector<long long> arr(k, 0);
    for (int b = 30; b >= 0; --b) {
        int cnt = bitCounts[b];
        long long add = 1LL << b;
        int limit = cnt < k ? cnt : k;
        for (int i = 0; i < limit; ++i) {
            arr[i] += add;
        }
    }
    long long ans = 0;
    for (int i = 0; i < k; ++i) {
        long long v = arr[i] % MOD;
        long long prod = (v * v) % MOD;
        ans = (ans + prod) % MOD;
    }
    return ans;
}

