std::vector<int> findLastVisitedIntegers(const std::vector<int>& nums) {
    std::vector<int> history;
    std::vector<int> ans;
    history.reserve(nums.size());
    ans.reserve(nums.size());
    int idx = -1;
    for (int v : nums) {
        if (v == -1) {
            if (idx >= 0) {
                ans.push_back(history[idx]);
                --idx;
            } else {
                ans.push_back(-1);
            }
        } else {
            history.push_back(v);
            idx = static_cast<int>(history.size()) - 1;
        }
    }
    return ans;
}

