std::string shortestBeautifulSubstring(const std::string& s, int k) {
    const size_t n = s.size();
    if (k == 0) {
        for (char c : s) {
            if (c == '0') return "0";
        }
        return "";
    }

    size_t left = 0;
    int ones = 0;
    size_t minLen = n + 1;

    for (size_t right = 0; right < n; ++right) {
        if (s[right] == '1') ++ones;
        while (ones > k) {
            if (s[left] == '1') --ones;
            ++left;
        }
        if (ones == k) {
            while (left <= right && s[left] == '0') ++left;
            if (left <= right) {
                size_t curLen = right - left + 1;
                if (curLen < minLen) minLen = curLen;
            }
        }
    }

    if (minLen == n + 1) return "";

    size_t bestPos = n;
    int cntOnes = 0;
    for (size_t i = 0; i < minLen; ++i) {
        if (s[i] == '1') ++cntOnes;
    }
    if (cntOnes == k) bestPos = 0;

    for (size_t start = 1; start + minLen <= n; ++start) {
        if (s[start - 1] == '1') --cntOnes;
        if (s[start + minLen - 1] == '1') ++cntOnes;
        if (cntOnes == k) {
            if (bestPos == n) {
                bestPos = start;
            } else {
                const std::string cur = s.substr(start, minLen);
                const std::string best = s.substr(bestPos, minLen);
                if (cur < best) bestPos = start;
            }
        }
    }

    if (bestPos == n) return "";
    return s.substr(bestPos, minLen);
}

