#include <vector>
#include <string>

std::vector<std::string> longestUnequalAdjacentGroupsSubsequenceII(const std::vector<std::string>& words, const std::vector<int>& groups) {
    std::size_t n = words.size();
    if (n == 0) return {};
    std::vector<int> dp(n, 1);
    std::vector<int> prev(n, -1);

    auto buildSeq = [&](int idx) {
        std::vector<std::string> seq;
        while (idx != -1) {
            seq.push_back(words[idx]);
            idx = prev[idx];
        }
        std::reverse(seq.begin(), seq.end());
        return seq;
    };

    auto betterSeq = [&](int a, int b) {
        std::vector<std::string> seqA = buildSeq(a);
        std::vector<std::string> seqB = buildSeq(b);
        return seqA < seqB;
    };

    for (std::size_t i = 0; i < n; ++i) {
        for (std::size_t j = 0; j < i; ++j) {
            if (groups[j] == groups[i]) continue;
            int candLen = dp[j] + 1;
            if (candLen > dp[i]) {
                dp[i] = candLen;
                prev[i] = static_cast<int>(j);
            } else if (candLen == dp[i]) {
                int oldPrev = prev[i];
                // temporarily set prev[i] to j to compare sequences
                int savedPrev = prev[i];
                prev[i] = static_cast<int>(j);
                bool useNew = betterSeq(i, i);
                prev[i] = savedPrev;
                if (useNew) {
                    prev[i] = static_cast<int>(j);
                }
            }
        }
    }

    int bestIdx = 0;
    for (std::size_t i = 1; i < n; ++i) {
        if (dp[i] > dp[bestIdx]) {
            bestIdx = static_cast<int>(i);
        } else if (dp[i] == dp[bestIdx]) {
            if (betterSeq(i, bestIdx)) {
                bestIdx = static_cast<int>(i);
            }
        }
    }

    return buildSeq(bestIdx);
}

