std::vector<int> findIndices(const std::vector<int>& nums, int indexDifference, int valueDifference) {
    int n = static_cast<int>(nums.size());
    if (indexDifference <= 0 && valueDifference <= 0) {
        return {0, 0};
    }
    std::deque<int> maxDeque;
    std::deque<int> minDeque;
    for (int j = 0; j < n; ++j) {
        int i = j - indexDifference;
        if (i >= 0) {
            while (!maxDeque.empty() && nums[i] >= nums[maxDeque.back()]) {
                maxDeque.pop_back();
            }
            maxDeque.push_back(i);
            while (!minDeque.empty() && nums[i] <= nums[minDeque.back()]) {
                minDeque.pop_back();
            }
            minDeque.push_back(i);
        }
        if (!maxDeque.empty() && static_cast<long long>(nums[maxDeque.front()]) - nums[j] >= valueDifference) {
            return {maxDeque.front(), j};
        }
        if (!minDeque.empty() && static_cast<long long>(nums[j]) - nums[minDeque.front()] >= valueDifference) {
            return {minDeque.front(), j};
        }
    }
    return {-1, -1};
}

