int minimumSum(std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n < 3) return -1;
    const int INF = std::numeric_limits<int>::max();
    std::vector<int> leftMin(n, INF);
    int curMin = INF;
    for (int i = 0; i < n; ++i) {
        if (curMin < nums[i]) leftMin[i] = curMin;
        curMin = std::min(curMin, nums[i]);
    }
    int curMinRight = INF;
    long long best = std::numeric_limits<long long>::max();
    for (int i = n - 1; i >= 0; --i) {
        if (curMinRight < nums[i] && leftMin[i] != INF) {
            long long sum = static_cast<long long>(leftMin[i]) + nums[i] + curMinRight;
            if (sum < best) best = sum;
        }
        curMinRight = std::min(curMinRight, nums[i]);
    }
    return best == std::numeric_limits<long long>::max() ? -1 : static_cast<int>(best);
}

