int minChanges(const std::string& s, int k) {
    int n = static_cast<int>(s.size());
    if (k >= n) return 0;
    std::vector<std::vector<std::uint16_t>> cost(n, std::vector<std::uint16_t>(n, 0));
    for (int len = 2; len <= n; ++len) {
        for (int i = 0; i + len <= n; ++i) {
            int j = i + len - 1;
            if (s[i] == s[j]) {
                cost[i][j] = (len == 2) ? 0 : cost[i + 1][j - 1];
            } else {
                cost[i][j] = (len == 2) ? 1 : static_cast<std::uint16_t>(cost[i + 1][j - 1] + 1);
            }
        }
    }
    const int INF = 1e9;
    std::vector<int> dpPrev(n + 1, INF), dpCurr(n + 1, INF);
    dpPrev[0] = 0;
    for (int p = 1; p <= k; ++p) {
        std::fill(dpCurr.begin(), dpCurr.end(), INF);
        for (int i = 1; i <= n; ++i) {
            int best = INF;
            for (int t = p - 1; t < i; ++t) {
                if (dpPrev[t] == INF) continue;
                int cur = dpPrev[t] + cost[t][i - 1];
                if (cur < best) best = cur;
            }
            dpCurr[i] = best;
        }
        dpPrev.swap(dpCurr);
    }
    return dpPrev[n];
}

