long long subarraysDistinctElementSumOfSquares(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    std::vector<int> uniq = nums;
    std::sort(uniq.begin(), uniq.end());
    uniq.erase(std::unique(uniq.begin(), uniq.end()), uniq.end());
    std::unordered_map<int, int> comp;
    comp.reserve(uniq.size() * 2);
    for (int i = 0; i < (int)uniq.size(); ++i) {
        comp[uniq[i]] = i;
    }
    std::vector<int> lastSeen(uniq.size(), -1);
    long long total = 0;
    for (int i = 0; i < n; ++i) {
        int distinct = 0;
        for (int j = i; j < n; ++j) {
            int idx = comp[nums[j]];
            if (lastSeen[idx] != i) {
                lastSeen[idx] = i;
                ++distinct;
            }
            total += 1LL * distinct * distinct;
        }
    }
    return total;
}

