    long long result = 0;
    for (int i = 0; i < n; ++i) {
        std::unordered_set<int> seen;
        int distinct = 0;
        for (int j = i; j < n; ++j) {
            if (seen.insert(nums[j]).second) {
                ++distinct;
            }
            long long add = 1LL * distinct * distinct % MOD;
            result += add;
            if (result >= MOD) result -= MOD;
        }
    }
    return result;
}

