int maxNumberOfPairs(const std::vector<std::string>& words) {
    std::unordered_map<std::string, int> cnt;
    for (const std::string& w : words) {
        ++cnt[w];
    }
    int pairs = 0;
    for (const auto& kv : cnt) {
        const std::string& s = kv.first;
        const std::string rev(s.rbegin(), s.rend());
        if (s == rev) {
            pairs += kv.second / 2;
        } else if (s < rev) {
            auto it = cnt.find(rev);
            if (it != cnt.end()) {
                pairs += std::min(kv.second, it->second);
            }
        }
    }
    return pairs;
}

