struct Result {
    long long time;
    long long returned;
};

std::vector<Result> intervalCancellation(const std::function<long long(const std::vector<long long>&)>& fn,
                                          const std::vector<long long>& args,
                                          long long t,
                                          long long cancelTimeMs) {
    std::vector<Result> logs;
    if (t <= 0 || cancelTimeMs <= 0) {
        return logs;
    }
    long long iterations = (cancelTimeMs + t - 1) / t;
    logs.reserve(static_cast<size_t>(iterations));
    for (long long i = 0; i < iterations; ++i) {
        long long current = i * t;
        long long ret = fn(args);
        logs.push_back({current, ret});
    }
    return logs;
}

