template <typename T>
std::vector<T> joinTwoArrays(const std::vector<T>& arr1, const std::vector<T>& arr2) {
    std::unordered_map<decltype(std::declval<T>().id), T> map;
    for (const auto& obj : arr1) {
        map[obj.id] = obj;
    }
    for (const auto& obj : arr2) {
        auto it = map.find(obj.id);
        if (it != map.end()) {
            for (const auto& kv : obj.props) it->second.props[kv.first] = kv.second;
        } else {
            map[obj.id] = obj;
        }
    }
    std::vector<T> result;
    result.reserve(map.size());
    for (auto& kv : map) {
        result.push_back(kv.second);
    }
    std::sort(result.begin(), result.end(), [](const T& a, const T& b) { return a.id < b.id; });
    return result;
}

