std::vector<int> countZeroRequestServers(int n, const std::vector<std::vector<int>>& logs, int x, const std::vector<int>& queries) {
    std::vector<std::pair<int,int>> events;
    events.reserve(logs.size());
    for (const auto& log : logs) {
        int server = log[0];
        int time = log[1];
        events.emplace_back(time, server);
    }
    std::sort(events.begin(), events.end(), [](const auto& a, const auto& b){ return a.first < b.first; });
    struct Q { int time; int idx; };
    std::vector<Q> qs;
    qs.reserve(queries.size());
    for (size_t i = 0; i < queries.size(); ++i) {
        qs.push_back({queries[i], static_cast<int>(i)});
    }
    std::sort(qs.begin(), qs.end(), [](const Q& a, const Q& b){ return a.time < b.time; });
    std::vector<int> cnt(n + 1, 0);
    int active = 0;
    size_t L = 0, R = 0;
    std::vector<int> ans(queries.size());
    for (const auto& q : qs) {
        int cur = q.time;
        while (R < events.size() && events[R].first <= cur) {
            int srv = events[R].second;
            if (cnt[srv] == 0) ++active;
            ++cnt[srv];
            ++R;
        }
        while (L < events.size() && events[L].first < cur - x) {
            int srv = events[L].second;
            --cnt[srv];
            if (cnt[srv] == 0) --active;
            ++L;
        }
        ans[q.idx] = n - active;
    }
    return ans;
}

