std::vector<int> findGoodSubset(const std::vector<std::vector<int>>& grid) {
    std::vector<std::vector<int>> subsets;
    int n = static_cast<int>(grid.size());
    for (int i = 1; i < (1 << n); ++i) {
        std::vector<int> subset;
        for (int j = 0; j < n; ++j) {
            if ((i & (1 << j)) != 0) {
                subset.push_back(j);
            }
        }
        subsets.push_back(std::move(subset));
    }
    int m = grid.empty() ? 0 : static_cast<int>(grid[0].size());
    for (const auto& subset : subsets) {
        int k = static_cast<int>(subset.size());
        std::vector<int> columnSums(m, 0);
        for (int row : subset) {
            for (int j = 0; j < m; ++j) {
                columnSums[j] += grid[row][j];
            }
        }
        bool isGood = true;
        int limit = k / 2;
        for (int sum : columnSums) {
            if (sum > limit) {
                isGood = false;
                break;
            }
        }
        if (isGood) {
            return subset;
        }
    }
    return {};
}

