}

long long countBeautifulPairs(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    std::vector<int> first(n), last(n);
    for (int i = 0; i < n; ++i) {
        int x = nums[i];
        int l = x % 10;
        while (x >= 10) x /= 10;
        int f = x;
        first[i] = f;
        last[i] = l;
    }
    int suffixCount[10] = {};
    for (int d : last) ++suffixCount[d];
    long long ans = 0;
    for (int i = 0; i < n; ++i) {
        --suffixCount[last[i]];
        for (int d = 1; d <= 9; ++d) {
