std::vector<int> robotCollisions(const std::vector<int>& positions, const std::vector<int>& healths, const std::vector<char>& directions) {
    int n = static_cast<int>(positions.size());
    std::vector<int> order(n);
    for (int i = 0; i < n; ++i) order[i] = i;
    std::sort(order.begin(), order.end(), [&](int a, int b) { return positions[a] < positions[b]; });

    // stack entries: [origIdx, health, dir(1=R,-1=L)]
    std::vector<std::array<int,3>> st;
    for (int idx : order) {
        int dir = (directions[idx] == 'R') ? 1 : -1;
        if (dir == 1) {
            st.push_back({idx, healths[idx], 1});
        } else {
            int curIdx = idx;
            int curHealth = healths[idx];
            while (!st.empty() && st.back()[2] == 1 && curHealth > 0) {
                int topHealth = st.back()[1];
                if (topHealth > curHealth) {
                    st.back()[1] = topHealth - 1;
                    curHealth = 0;
                    break;
                } else if (topHealth < curHealth) {
                    curHealth -= 1;
                    st.pop_back();
                } else {
                    st.pop_back();
                    curHealth = 0;
                    break;
                }
            }
            if (curHealth > 0) {
                st.push_back({curIdx, curHealth, -1});
            }
        }
    }
    std::sort(st.begin(), st.end(), [](const std::array<int,3>& a, const std::array<int,3>& b) { return a[0] < b[0]; });
    std::vector<int> result;
    for (auto& e : st) result.push_back(e[1]);
    return result;
}

