int longestSubsequenceSum(const std::vector<int>& nums, int target) {
    std::unordered_map<int, int> dp;
    dp[0] = 0;
    for (int x : nums) {
        std::unordered_map<int, int> next(dp);
        for (const auto& kv : dp) {
            int newSum = kv.first + x;
            int newLen = kv.second + 1;
            auto it = next.find(newSum);
            if (it == next.end() || it->second < newLen) {
                next[newSum] = newLen;
            }
        }
        dp = std::move(next);
    }
    auto it = dp.find(target);
    return it != dp.end() ? it->second : -1;
}

