#include <bits/stdc++.h>
int countSubMultisets(const std::vector<int>& nums, int l, int r) {
    const int MOD = 1000000007;
    long long zeroCount = 0;
    int maxVal = 0;
    long long totalSum = 0;
    std::vector<int> freq(20001, 0);
    for (int v : nums) {
        if (v == 0) {
            ++zeroCount;
        } else {
            if (v > maxVal) maxVal = v;
            ++freq[v];
            totalSum += v;
        }
    }
    int maxSum = static_cast<int>(totalSum);
    std::vector<int> dp(maxSum + 1, 0);
    dp[0] = 1;
    for (int v = 1; v <= maxVal; ++v) {
        int c = freq[v];
        if (c == 0) continue;
        std::vector<int> ndp(maxSum + 1, 0);
        for (int rem = 0; rem < v; ++rem) {
            std::deque<int> q;
            long long sum = 0;
            for (int s = rem; s <= maxSum; s += v) {
                sum += dp[s];
                if (sum >= MOD) sum -= MOD;
                q.push_back(dp[s]);
                if ((int)q.size() > c + 1) {
                    sum -= q.front();
                    if (sum < 0) sum += MOD;
                    q.pop_front();
                }
                ndp[s] = static_cast<int>(sum);
            }
        }
        dp.swap(ndp);
    }
    if (zeroCount > 0) {
        long long factor = 1, base = 2, exp = zeroCount;
        while (exp) {
            if (exp & 1) factor = factor * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        for (int s = 0; s <= maxSum; ++s) {
            dp[s] = static_cast<int>((static_cast<long long>(dp[s]) * factor) % MOD);
        }
    }
    if (l > maxSum) return 0;
    if (r > maxSum) r = maxSum;
    long long ans = 0;
    for (int s = l; s <= r; ++s) {
        ans += dp[s];
        if (ans >= MOD) ans -= MOD;
    }
    return static_cast<int>(ans);
}

