std::vector<int> findIndices(const std::vector<int>& nums, int indexDifference, int valueDifference) {
    if (nums.empty()) return {-1, -1};
    long long maxVal = LLONG_MIN;
    int maxIdx = -1;
    long long minVal = LLONG_MAX;
    int minIdx = -1;
    for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
        int addIdx = i - indexDifference;
        if (addIdx >= 0) {
            long long v = static_cast<long long>(nums[addIdx]);
            if (v > maxVal) { maxVal = v; maxIdx = addIdx; }
            if (v < minVal) { minVal = v; minIdx = addIdx; }
        }
        if (maxIdx != -1 && std::llabs(static_cast<long long>(nums[i]) - maxVal) >= valueDifference) {
            return {maxIdx, i};
        }
        if (minIdx != -1 && std::llabs(static_cast<long long>(nums[i]) - minVal) >= valueDifference) {
            return {minIdx, i};
        }
    }
    return {-1, -1};
}

