int minimumSum(std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n < 3) return -1;
    const long long INF = 4e18;
    std::vector<long long> leftMin(n, INF), rightMin(n, INF);
    long long curMin = INF;
    for (int i = 0; i < n; ++i) {
        if (curMin < nums[i]) leftMin[i] = curMin;
        if (nums[i] < curMin) curMin = nums[i];
    }
    curMin = INF;
    for (int i = n - 1; i >= 0; --i) {
        if (curMin < nums[i]) rightMin[i] = curMin;
        if (nums[i] < curMin) curMin = nums[i];
    }
    long long ans = INF;
    for (int i = 0; i < n; ++i) {
        if (leftMin[i] != INF && rightMin[i] != INF) {
            long long sum = leftMin[i] + nums[i] + rightMin[i];
            if (sum < ans) ans = sum;
        }
    }
    return ans == INF ? -1 : static_cast<int>(ans);
}

