int minGroupsForValidAssignment(const std::vector<int>& balls) {
    std::unordered_map<int, int> freq;
    int maxFreq = 0;
    for (int x : balls) {
        int f = ++freq[x];
        if (f > maxFreq) maxFreq = f;
    }

    auto feasible = [&](int k) -> bool {
        for (const auto& p : freq) {
            int f = p.second;
            int q = f / k;
            int r = f % k;
            if (q < r) return false;
        }
        return true;
    };

    int lo = 1, hi = maxFreq;
    while (lo < hi) {
        int mid = lo + (hi - lo + 1) / 2;
        if (feasible(mid))
            lo = mid;
        else
            hi = mid - 1;
    }
    int k = lo;
    long long ans = 0;
    int kp1 = k + 1;
    for (const auto& p : freq) {
        int f = p.second;
        ans += (f + kp1 - 1) / kp1;
    }
    return static_cast<int>(ans);
}

