long long maximumScoreAfterOperations(const std::vector<std::vector<int>>& edges, const std::vector<long long>& values) {
    int n = values.size();
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    std::vector<long long> keep(n, 0);
    std::function<void(int,int)> dfs = [&](int u, int parent) {
        long long sumChildren = 0;
        bool isLeaf = true;
        for (int v : adj[u]) {
            if (v == parent) continue;
            isLeaf = false;
            dfs(v, u);
            sumChildren += keep[v];
        }
        if (isLeaf) {
            keep[u] = values[u];
        } else {
            keep[u] = std::min(values[u], sumChildren);
        }
    };
    dfs(0, -1);
    long long total = 0;
    for (long long v : values) total += v;
    return total - keep[0];
}

