int numberOfGoodStrings(int n) {
    const long long MOD = 1000000007LL;
    if (n < 4) return 0;
    auto modpow = [&](long long base, long long exp) -> long long {
        long long res = 1 % MOD;
        while (exp) {
            if (exp & 1) res = res * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return res;
    };
    long long total = modpow(26, n);
    long long pow25 = modpow(25, n);
    long long pow24 = modpow(24, n);
    long long pow23 = modpow(23, n);
    long long pow25_n1 = modpow(25, n - 1);
    long long pow24_n1 = modpow(24, n - 1);
    long long pow23_n1 = modpow(23, n - 1);
    long long nmod = n % MOD;
    long long C = (pow25 + nmod * pow25_n1) % MOD;
    long long AC = (pow24 + nmod * pow24_n1) % MOD;
    long long ABC = (pow23 + nmod * pow23_n1) % MOD;
    long long A = pow25;
    long long B = pow25;
    long long AB = pow24;
    long long good = total;
    good = (good - A + MOD) % MOD;
    good = (good - B + MOD) % MOD;
    good = (good - C + MOD) % MOD;
    good = (good + AB) % MOD;
    good = (good + AC) % MOD;
    good = (good + AC) % MOD; // BC is same as AC
    good = (good - ABC + MOD) % MOD;
    return static_cast<int>(good);
}

