int maximumStrongPairXor(std::vector<int> nums) {
    std::sort(nums.begin(), nums.end());
    const int MAX_BIT = 20;
    struct Node { int child[2]; int cnt; };
    std::vector<Node> trie;
    trie.reserve((nums.size() + 1) * (MAX_BIT + 2));
    auto newNode = [&]() -> int {
        trie.push_back({{-1, -1}, 0});
        return static_cast<int>(trie.size()) - 1;
    };
    int root = newNode();

    auto insert = [&](int val) {
        int node = root;
        ++trie[node].cnt;
        for (int i = MAX_BIT; i >= 0; --i) {
            int bit = (val >> i) & 1;
            if (trie[node].child[bit] == -1) trie[node].child[bit] = newNode();
            node = trie[node].child[bit];
            ++trie[node].cnt;
        }
    };

    auto remove = [&](int val) {
        int node = root;
        --trie[node].cnt;
        for (int i = MAX_BIT; i >= 0; --i) {
            int bit = (val >> i) & 1;
            node = trie[node].child[bit];
            --trie[node].cnt;
        }
    };

    auto query = [&](int val) {
        int node = root;
        int xorVal = 0;
        for (int i = MAX_BIT; i >= 0; --i) {
            int bit = (val >> i) & 1;
            int toggled = bit ^ 1;
            int nxt = trie[node].child[toggled];
            if (nxt != -1 && trie[nxt].cnt > 0) {
                xorVal |= (1 << i);
                node = nxt;
            } else {
                node = trie[node].child[bit];
            }
        }
        return xorVal;
    };

    int ans = 0;
    int left = 0;
    for (int right = 0; right < static_cast<int>(nums.size()); ++right) {
        while (static_cast<long long>(nums[right]) > 2LL * nums[left]) {
            remove(nums[left]);
            ++left;
        }
        insert(nums[right]);
        int cur = query(nums[right]);
        if (cur > ans) ans = cur;
    }
    return ans;
}

#include <bits/stdc++.h>

int maximumStrongPairXor(const std::vector<int>& nums) {
    std::vector<int> a = nums;
    std::sort(a.begin(), a.end());
    struct Node {
        int child[2];
        int cnt;
        Node() { child[0] = child[1] = -1; cnt = 0; }
    };
    std::vector<Node> trie(1);
    auto insert = [&](int x) {
        int node = 0;
        for (int bit = 30; bit >= 0; --bit) {
            int b = (x >> bit) & 1;
            if (trie[node].child[b] == -1) {
                trie[node].child[b] = trie.size();
                trie.emplace_back();
            }
            node = trie[node].child[b];
            ++trie[node].cnt;
        }
    };
    auto erase = [&](int x) {
        int node = 0;
        for (int bit = 30; bit >= 0; --bit) {
            int b = (x >> bit) & 1;
            node = trie[node].child[b];
            --trie[node].cnt;
        }
    };
    auto maxXor = [&](int x) {
        int node = 0;
        int res = 0;
        for (int bit = 30; bit >= 0; --bit) {
            int b = (x >> bit) & 1;
            int want = b ^ 1;
            int nxt = trie[node].child[want];
            if (nxt != -1 && trie[nxt].cnt > 0) {
                res |= (1 << bit);
                node = nxt;
            } else {
                node = trie[node].child[b];
            }
        }
        return res;
    };
    int ans = 0;
    std::size_t l = 0;
    for (std::size_t i = 0; i < a.size(); ++i) {
        while (l < i && static_cast<long long>(a[i]) > 2LL * a[l]) {
            erase(a[l]);
            ++l;
        }
        insert(a[i]);
        ans = std::max(ans, maxXor(a[i]));
    }
    return ans;
}

