long minCoins(const std::vector<int>& prices) {
    int n = prices.size();
    vector<long> dp(n + 1, LONG_MAX / 2);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int lo = (i + 1) / 2;
        for (int j = lo; j <= i; j++) {
            long cost = dp[j - 1] + prices[j - 1];
            if (cost < dp[i]) dp[i] = cost;
        }
    }
    return dp[n];
}

