#include <bits/stdc++.h>
std::vector<int> leftmostBuildingQueries(const std::vector<int>& heights, const std::vector<std::vector<int>>& queries) {
    int n = heights.size();
    std::vector<int> seg(4 * n);
    std::function<void(int,int,int)> build = [&](int idx, int l, int r) {
        if (l == r) {
            seg[idx] = heights[l];
            return;
        }
        int mid = (l + r) >> 1;
        build(idx*2, l, mid);
        build(idx*2+1, mid+1, r);
        seg[idx] = std::max(seg[idx*2], seg[idx*2+1]);
    };
    build(1, 0, n-1);
    std::function<int(int,int,int,int,int)> findFirst = [&](int idx, int l, int r, int ql, int X) -> int {
        if (r < ql || seg[idx] <= X) return -1;
        if (l == r) return l;
        int mid = (l + r) >> 1;
        int left = findFirst(idx*2, l, mid, ql, X);
        if (left != -1) return left;
        return findFirst(idx*2+1, mid+1, r, ql, X);
    };
    std::vector<int> ans;
    ans.reserve(queries.size());
    for (const auto& q : queries) {
        int a = q[0];
        int b = q[1];
        if (a == b) {
            ans.push_back(a);
            continue;
        }
        int L = std::max(a, b);
        int S = std::min(a, b);
        bool meetAtL = false;
        if (L == a) {
            if (heights[b] < heights[a]) meetAtL = true;
        } else {
            if (heights[a] < heights[b]) meetAtL = true;
        }
        if (meetAtL) {
            ans.push_back(L);
            continue;
        }
        int need = std::max(heights[a], heights[b]);
        if (L + 1 >= n) {
            ans.push_back(-1);
            continue;
        }
        int pos = findFirst(1, 0, n-1, L + 1, need);
        ans.push_back(pos);
    }
    return ans;
}

