bool findRotation(std::vector<std::vector<int>>& mat, long long k) {
    if (mat.empty() || mat[0].empty()) {
        return true;
    }
    long long cols = static_cast<long long>(mat[0].size());
    long long kk = k % cols;
    const std::vector<std::vector<int>> original = mat;
    for (size_t i = 0; i < mat.size(); ++i) {
        for (size_t j = 0; j < mat[i].size(); ++j) {
            long long srcIdx;
            if (i % 2 == 0) {
                srcIdx = (j - kk + cols) % cols;
            } else {
                srcIdx = (j + kk) % cols;
            }
            if (mat[i][j] != original[i][static_cast<size_t>(srcIdx)]) {
                return false;
            }
        }
    }
    return true;
}

