std::vector<int> lexicographicallySmallestArray(std::vector<int> nums, int limit) {
    int n = static_cast<int>(nums.size());
    std::vector<std::pair<int,int>> arr;
    arr.reserve(n);
    for (int i = 0; i < n; ++i) {
        arr.emplace_back(nums[i], i);
    }
    std::sort(arr.begin(), arr.end(),
              [](const std::pair<int,int>& a, const std::pair<int,int>& b) {
                  return a.first < b.first;
              });
    std::vector<int> result = nums;
    int i = 0;
    while (i < n) {
        int start = i;
        while (i + 1 < n && static_cast<long long>(arr[i + 1].first) - arr[i].first <= limit) {
            ++i;
        }
        // component from start to i inclusive
        std::vector<int> indices;
        indices.reserve(i - start + 1);
        for (int k = start; k <= i; ++k) {
            indices.push_back(arr[k].second);
        }
        std::sort(indices.begin(), indices.end());
        for (int t = 0; t < static_cast<int>(indices.size()); ++t) {
            result[indices[t]] = arr[start + t].first;
        }
        ++i;
    }
    return result;
}

