int minOperations(const std::string& word) {
    const int INF = 1e9;
    int n = static_cast<int>(word.size());
    if (n == 0) return 0;
    std::vector<std::array<int, 26>> dp(n);
    for (int c = 0; c < 26; ++c) {
        dp[0][c] = (c == word[0] - 'a') ? 0 : 1;
    }
    for (int i = 1; i < n; ++i) {
        for (int c = 0; c < 26; ++c) {
            int cost = (c == word[i] - 'a') ? 0 : 1;
            int best = INF;
            for (int p = 0; p < 26; ++p) {
                if (std::abs(c - p) > 1) {
                    best = std::min(best, dp[i - 1][p]);
                }
            }
            dp[i][c] = best + cost;
        }
    }
    int ans = INF;
    for (int c = 0; c < 26; ++c) {
        ans = std::min(ans, dp[n - 1][c]);
    }
    return ans;
}

#include <bits/stdc++.h>

long long numInfectionSequences(int n, const std::vector<int>& sick) {
    const long long MOD = 1000000007LL;
    std::vector<int> s = sick;
    std::sort(s.begin(), s.end());
    int totalUninfected = n - static_cast<int>(s.size());

    std::vector<long long> fact(n + 1, 1), invFact(n + 1, 1);
    for (int i = 1; i <= n; ++i) {
        fact[i] = fact[i - 1] * i % MOD;
    }
    auto modPow = [&](long long base, long long exp) {
        long long res = 1;
        while (exp) {
            if (exp & 1) res = res * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return res;
    };
    invFact[n] = modPow(fact[n], MOD - 2);
    for (int i = n; i > 0; --i) {
        invFact[i - 1] = invFact[i] * i % MOD;
    }

    long long result = fact[totalUninfected];
    int prev = -1;
    for (size_t i = 0; i < s.size(); ++i) {
        int gap = s[i] - prev - 1;
        result = result * invFact[gap] % MOD;
        if (prev != -1 && gap > 0) {
            result = result * modPow(2, gap - 1) % MOD;
        }
        prev = s[i];
    }
    int rightGap = n - 1 - prev;
    result = result * invFact[rightGap] % MOD;
    return result;
}

