int numberOfGoodPartitions(const std::vector<int>& nums) {
    const int MOD = 1000000007;
    int n = static_cast<int>(nums.size());
    std::vector<int> lastPos(n);
    std::unordered_map<int, int> last;
    for (int i = n - 1; i >= 0; --i) {
        if (last.find(nums[i]) == last.end()) {
            last[nums[i]] = i;
        }
        lastPos[i] = last[nums[i]];
    }
    long long total = 0; // sum of dp values for previous allowed cuts
    long long dp_i = 0;  // dp for current allowed cut
    int curMax = -1;
    for (int i = 0; i < n; ++i) {
        curMax = std::max(curMax, lastPos[i]);
        if (i == curMax) {            // can cut after i
            dp_i = (total + 1) % MOD; // include empty prefix
            total = (total + dp_i) % MOD;
        }
    }
    return static_cast<int>(dp_i);
}

#include <bits/stdc++.h>
int numberOfSets(int n, int maxDistance, std::vector<std::vector<int>> roads) {
    const long long INF = 4e18;
    std::vector<std::vector<long long>> base(n, std::vector<long long>(n, INF));
    for (int i = 0; i < n; ++i) base[i][i] = 0;
    for (const auto& r : roads) {
        int u = r[0], v = r[1];
        long long w = r[2];
        if (w < base[u][v]) {
            base[u][v] = base[v][u] = w;
        }
    }
    long long ans = 0;
    int total = 1 << n;
    for (int mask = 0; mask < total; ++mask) {
        int cnt = __builtin_popcount(mask);
        if (cnt <= 1) {
            ++ans;
            continue;
        }
        std::vector<std::vector<long long>> d = base;
        for (int k = 0; k < n; ++k) if (mask & (1 << k)) {
            for (int i = 0; i < n; ++i) if (mask & (1 << i)) {
                if (d[i][k] == INF) continue;
                for (int j = 0; j < n; ++j) if (mask & (1 << j)) {
                    if (d[k][j] == INF) continue;
                    long long nd = d[i][k] + d[k][j];
                    if (nd < d[i][j]) d[i][j] = nd;
                }
            }
        }
        bool ok = true;
        for (int i = 0; i < n && ok; ++i) if (mask & (1 << i)) {
            for (int j = i + 1; j < n; ++j) if (mask & (1 << j)) {
                if (d[i][j] == INF || d[i][j] > maxDistance) {
                    ok = false;
                    break;
                }
            }
        }
        if (ok) ++ans;
    }
    return static_cast<int>(ans);
}

