long long minimumCost(std::vector<int> nums) {
    const int LIMIT = 1000000000;
    std::vector<int> pals;
    pals.reserve(110000);
    for (int len = 1; len <= 9; ++len) {
        int halfLen = (len + 1) / 2;
        int start = (halfLen == 1) ? 1 : static_cast<int>(std::pow(10, halfLen - 1));
        int end = static_cast<int>(std::pow(10, halfLen)) - 1;
        for (int half = start; half <= end; ++half) {
            std::string s = std::to_string(half);
            std::string rev = s;
            if (len % 2 == 1) rev.pop_back();
            std::reverse(rev.begin(), rev.end());
            int pal = std::stoi(s + rev);
            if (pal < LIMIT) pals.push_back(pal);
        }
    }
    std::sort(pals.begin(), pals.end());

    std::sort(nums.begin(), nums.end());
    int n = static_cast<int>(nums.size());
    std::vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + nums[i];
    long long totalSum = pref[n];
    long long best = LLONG_MAX;

    for (int y : pals) {
        auto it = std::upper_bound(nums.begin(), nums.end(), y);
        int k = static_cast<int>(it - nums.begin());
        long long leftCost = static_cast<long long>(y) * k - pref[k];
        long long rightCost = (totalSum - pref[k]) - static_cast<long long>(y) * (n - k);
        long long cost = leftCost + rightCost;
        if (cost < best) best = cost;
    }
    return best;
}

