    for (std::size_t i = 0; i < n; ++i) {
        pref[i + 1] = pref[i] + static_cast<long long>(nums[i]);
    }
    int best = 0;
    std::size_t left = 0;
    for (std::size_t right = 0; right < n; ++right) {
        while (true) {
            std::size_t mid = (left + right) / 2;
            long long leftCost = static_cast<long long>(nums[mid]) * static_cast<long long>(mid - left) - (pref[mid] - pref[left]);
            long long rightCost = (pref[right + 1] - pref[mid + 1]) - static_cast<long long>(nums[mid]) * static_cast<long long>(right - mid);
            long long totalCost = leftCost + rightCost;
            if (totalCost <= k) break;
            ++left;
        }
        int current = static_cast<int>(right - left + 1);
        if (current > best) best = current;
    }
    return best;
}

