    std::vector<int> result;
    result.reserve(nums.size());
    for (size_t i = 0; i + 1 < nums.size(); i += 2) {
        result.push_back(nums[i + 1]);
        result.push_back(nums[i]);
    }
    if (nums.size() % 2 == 1) {
        result.push_back(nums.back());
    }
    return result;
}

#include <bits/stdc++.h>

std::vector<long long> placedCoins(const std::vector<std::vector<int>>& edges, const std::vector<int>& cost) {
    int n = cost.size();
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int a = e[0], b = e[1];
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    struct Info {
        int sz = 0;
        std::vector<long long> top;   // up to 3 largest
        std::vector<long long> bot;   // up to 2 smallest
    };

    std::vector<long long> answer(n, 1);
    std::function<Info(int,int)> dfs = [&](int u, int parent) -> Info {
        Info cur;
        cur.sz = 1;
        cur.top.push_back(cost[u]);
        cur.bot.push_back(cost[u]);

        for (int v : adj[u]) {
            if (v == parent) continue;
            Info child = dfs(v, u);
            cur.sz += child.sz;

            // merge top values
            cur.top.insert(cur.top.end(), child.top.begin(), child.top.end());
            // keep only three largest
            std::nth_element(cur.top.begin(), cur.top.begin() + std::min((size_t)3, cur.top.size()) - 1, cur.top.end(), std::greater<long long>());
            if (cur.top.size() > 3) cur.top.resize(3);

            // merge bot values
            cur.bot.insert(cur.bot.end(), child.bot.begin(), child.bot.end());
            // keep only two smallest
            std::nth_element(cur.bot.begin(), cur.bot.begin() + std::min((size_t)2, cur.bot.size()) - 1, cur.bot.end());
            if (cur.bot.size() > 2) cur.bot.resize(2);
        }

        if (cur.sz < 3) {
            answer[u] = 1;
        } else {
            // ensure top has three elements
            while (cur.top.size() < 3) cur.top.push_back(LLONG_MIN);
            // ensure bot has two elements
            while (cur.bot.size() < 2) cur.bot.push_back(LLONG_MAX);

            // sort needed parts
            std::sort(cur.top.begin(), cur.top.end(), std::greater<long long>());
            std::sort(cur.bot.begin(), cur.bot.end());

            long long prod1 = cur.top[0] * cur.top[1] * cur.top[2];
            long long prod2 = cur.bot[0] * cur.bot[1] * cur.top[0];
            long long best = std::max(prod1, prod2);
            answer[u] = (best > 0) ? best : 0;
        }
        return cur;
    };

    dfs(0, -1);
    return answer;
}

