long long numberOfSubarrays(const std::vector<int>& nums) {
    long long count = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        for (size_t j = i; j < nums.size(); ++j) {
            std::vector<int> temp;
            temp.reserve(i + (nums.size() - (j + 1)));
            temp.insert(temp.end(), nums.begin(), nums.begin() + i);
            temp.insert(temp.end(), nums.begin() + j + 1, nums.end());
            bool isIncreasing = true;
            for (size_t k = 0; k + 1 < temp.size(); ++k) {
                if (temp[k] >= temp[k + 1]) {
                    isIncreasing = false;
                    break;
                }
            }
            if (isIncreasing) {
                ++count;
            }
        }
    }
    return count;
}

#include <bits/stdc++.h>
long long maxSquareArea(long long m, long long n, std::vector<int> hFences, std::vector<int> vFences) {
    const long long MOD = 1000000007LL;
    std::vector<long long> hx;
    hx.reserve(hFences.size() + 2);
    hx.push_back(1);
    for (int x : hFences) hx.push_back(x);
    hx.push_back(m);
    std::sort(hx.begin(), hx.end());
    std::vector<long long> hgaps;
    for (size_t i = 1; i < hx.size(); ++i) hgaps.push_back(hx[i] - hx[i - 1]);

    std::vector<long long> vy;
    vy.reserve(vFences.size() + 2);
    vy.push_back(1);
    for (int y : vFences) vy.push_back(y);
    vy.push_back(n);
    std::sort(vy.begin(), vy.end());
    std::vector<long long> vgaps;
    for (size_t i = 1; i < vy.size(); ++i) vgaps.push_back(vy[i] - vy[i - 1]);

    std::unordered_set<long long> horizLengths;
    for (size_t i = 0; i < hgaps.size(); ++i) {
        long long sum = 0;
        for (size_t j = i; j < hgaps.size(); ++j) {
            sum += hgaps[j];
            horizLengths.insert(sum);
        }
    }

    long long best = -1;
    for (size_t i = 0; i < vgaps.size(); ++i) {
        long long sum = 0;
        for (size_t j = i; j < vgaps.size(); ++j) {
            sum += vgaps[j];
            if (horizLengths.find(sum) != horizLengths.end()) {
                if (sum > best) best = sum;
            }
        }
    }

    if (best == -1) return -1;
    long long sideMod = best % MOD;
    return (sideMod * sideMod) % MOD;
}

#include <bits/stdc++.h>
#include <string>
#include <vector>
#include <unordered_map>
#include <climits>

long long minCostToConvertString(const std::string& source, const std::string& target,
                                 const std::vector<std::string>& original,
                                 const std::vector<std::string>& changed,
                                 const std::vector<long long>& cost) {
    const long long INF = LLONG_MAX / 4;
    size_t n = source.size();
    // Group strings by their length
    std::unordered_map<size_t, std::vector<std::string>> nodesByLen;
    for (size_t i = 0; i < original.size(); ++i) {
        size_t len = original[i].size();
        nodesByLen[len].push_back(original[i]);
        nodesByLen[len].push_back(changed[i]);
    }
    // Build distance maps for each length
    struct LenInfo {
        std::unordered_map<std::string, int> idx;
        std::vector<std::vector<long long>> dist;
    };
    std::unordered_map<size_t, LenInfo> infoByLen;
    for (auto& kv : nodesByLen) {
        size_t len = kv.first;
        auto& vec = kv.second;
        std::sort(vec.begin(), vec.end());
        vec.erase(std::unique(vec.begin(), vec.end()), vec.end());
        LenInfo li;
        int m = static_cast<int>(vec.size());
        li.idx.reserve(m * 2);
        for (int i = 0; i < m; ++i) li.idx[vec[i]] = i;
        li.dist.assign(m, std::vector<long long>(m, INF));
        for (int i = 0; i < m; ++i) li.dist[i][i] = 0;
        infoByLen[len] = std::move(li);
    }
    // Add direct edges
    for (size_t i = 0; i < original.size(); ++i) {
        size_t len = original[i].size();
        auto& li = infoByLen[len];
        int u = li.idx[original[i]];
        int v = li.idx[changed[i]];
        li.dist[u][v] = std::min(li.dist[u][v], cost[i]);
    }
    // Floyd‑Warshall for each length
    for (auto& kv : infoByLen) {
        auto& d = kv.second.dist;
        int m = static_cast<int>(d.size());
        for (int k = 0; k < m; ++k)
            for (int i = 0; i < m; ++i) if (d[i][k] < INF)
                for (int j = 0; j < m; ++j) if (d[k][j] < INF)
                    d[i][j] = std::min(d[i][j], d[i][k] + d[k][j]);
    }
    // DP over prefixes
    std::vector<long long> dp(n + 1, INF);
    dp[0] = 0;
    for (size_t i = 1; i <= n; ++i) {
        // match single character for free
        if (source[i - 1] == target[i - 1]) dp[i] = std::min(dp[i], dp[i - 1]);
        // try all operation lengths
        for (auto& kv : infoByLen) {
            size_t len = kv.first;
            if (len > i) continue;
            const std::string subS = source.substr(i - len, len);
            const std::string subT = target.substr(i - len, len);
            auto itS = kv.second.idx.find(subS);
            auto itT = kv.second.idx.find(subT);
            if (itS == kv.second.idx.end() || itT == kv.second.idx.end()) continue;
            long long c = kv.second.dist[itS->second][itT->second];
            if (c >= INF) continue;
            dp[i] = std::min(dp[i], dp[i - len] + c);
        }
    }
    return dp[n] >= INF ? -1 : dp[n];
}

#include <bits/stdc++.h>
#include <string>
#include <vector>

long long minCostToConvertString(const std::string& source, const std::string& target,
                                 const std::vector<char>& original, const std::vector<char>& changed,
                                 const std::vector<long long>& cost) {
    const long long INF = LLONG_MAX / 4;
    const int MAXC = 256;
    long long dist[MAXC][MAXC];
    for (int i = 0; i < MAXC; ++i) {
        for (int j = 0; j < MAXC; ++j) {
            dist[i][j] = (i == j) ? 0 : INF;
        }
    }
    for (size_t i = 0; i < original.size(); ++i) {
        unsigned char u = static_cast<unsigned char>(original[i]);
        unsigned char v = static_cast<unsigned char>(changed[i]);
        if (cost[i] < dist[u][v]) dist[u][v] = cost[i];
    }
    for (int k = 0; k < MAXC; ++k) {
        for (int i = 0; i < MAXC; ++i) {
            if (dist[i][k] == INF) continue;
            for (int j = 0; j < MAXC; ++j) {
                if (dist[k][j] == INF) continue;
                long long nd = dist[i][k] + dist[k][j];
                if (nd < dist[i][j]) dist[i][j] = nd;
            }
        }
    }
    if (source.size() != target.size()) return -1;
    long long total = 0;
    for (size_t i = 0; i < source.size(); ++i) {
        unsigned char s = static_cast<unsigned char>(source[i]);
        unsigned char t = static_cast<unsigned char>(target[i]);
        if (s == t) continue;
        if (dist[s][t] == INF) return -1;
        total += dist[s][t];
    }
    return total;
}

#include <bits/stdc++.h>

int longestSpecialSubstring(const std::string& s) {
    int n = static_cast<int>(s.size());
    int best = -1;
    const unsigned long long base = 1315423911ULL;
    std::vector<unsigned long long> pow(n + 1);
    pow[0] = 1;
    for (int i = 1; i <= n; ++i) pow[i] = pow[i - 1] * base;
    std::vector<unsigned long long> pref(n + 1);
    pref[0] = 0;
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] * base + static_cast<unsigned long long>(static_cast<unsigned char>(s[i]) + 1);
    for (int len = 1; len <= n; ++len) {
        std::unordered_map<unsigned long long, int> cnt;
        std::unordered_map<unsigned long long, int> pos;
        cnt.reserve(n);
        pos.reserve(n);
        for (int i = 0; i + len <= n; ++i) {
            unsigned long long h = pref[i + len] - pref[i] * pow[len];
            ++cnt[h];
            if (cnt[h] == 1) pos[h] = i;
        }
        for (const auto& kv : cnt) {
            if (kv.second >= 3) {
                int i = pos[kv.first];
                std::string sub = s.substr(i, len);
                bool ok = true;
                int seen[256] = {0};
                int distinct = 0;
                for (char c : sub) {
                    unsigned char uc = static_cast<unsigned char>(c);
                    if (!seen[uc]) {
                        seen[uc] = 1;
                        ++distinct;
                        if (distinct > 2) {
                            ok = false;
                            break;
                        }
                    }
                }
                if (ok) best = std::max(best, len);
            }
        }
    }
    return best;
}

#include <bits/stdc++.h>

int longestSpecialSubstring(const std::string& s) {
    int n = static_cast<int>(s.size());
    if (n == 0) return -1;
    std::unordered_map<char, std::vector<int>> cntMap;
    for (int i = 0; i < n; ) {
        int j = i;
        while (j < n && s[j] == s[i]) ++j;
        int len = j - i;
        char c = s[i];
        auto& vec = cntMap[c];
        if (vec.empty()) vec.assign(n + 2, 0);
        vec[len] += 1;
        i = j;
    }
    int answer = -1;
    for (auto& kv : cntMap) {
        const std::vector<int>& cnt = kv.second;
        std::vector<long long> suffCnt(n + 3, 0), suffSum(n + 3, 0);
        for (int len = n; len >= 1; --len) {
            suffCnt[len] = suffCnt[len + 1] + cnt[len];
            suffSum[len] = suffSum[len + 1] + static_cast<long long>(len + 1) * cnt[len];
        }
        for (int L = 1; L <= n; ++L) {
            long long total = suffSum[L] - static_cast<long long>(L) * suffCnt[L];
            if (total >= 3) {
                if (L > answer) answer = L;
            }
        }
    }
    return answer;
}

#include <bits/stdc++.h>

std::vector<bool> canMakePalindrome(const std::string& s, const std::vector<std::vector<int>>& queries) {
    int n = static_cast<int>(s.size());
    std::vector<bool> ans;
    ans.reserve(queries.size());

    for (const auto& q : queries) {
        int a = q[0];
        int b = q[1];
        int c = q[2];
        int d = q[3];

        std::vector<char> mutablePos(n, 0);
        for (int i = a; i <= b; ++i) mutablePos[i] = 1;
        for (int i = c; i <= d; ++i) mutablePos[i] = 1;

        std::vector<int> freq(26, 0);
        for (int i = 0; i < n; ++i) {
            if (mutablePos[i]) ++freq[s[i] - 'a'];
        }

        bool possible = true;

        for (int i = 0; i < n / 2 && possible; ++i) {
            int j = n - 1 - i;
            bool mi = mutablePos[i];
            bool mj = mutablePos[j];
            if (!mi && !mj) {
                if (s[i] != s[j]) possible = false;
            } else if (mi && !mj) {
                int idx = s[j] - 'a';
                if (freq[idx] == 0) possible = false;
                else --freq[idx];
            } else if (!mi && mj) {
                int idx = s[i] - 'a';
                if (freq[idx] == 0) possible = false;
                else --freq[idx];
            }
        }

        if (possible) {
            int odd = 0;
            for (int cnt : freq) if (cnt % 2) ++odd;
            bool middleMutable = (n % 2 == 1 && mutablePos[n / 2]);
            if (middleMutable) {
                if (odd > 1) possible = false;
            } else {
                if (odd > 0) possible = false;
            }
        }

        ans.push_back(possible);
    }

    return ans;
}

