using namespace std;

int minOperations(int x, int y) {
    if (x == y) return 0;
    queue<pair<int,int>> q;
    q.push({x, 0});
    set<int> visited = {x};
    while (!q.empty()) {
        auto [current, steps] = q.front(); q.pop();
        if (current == y) return steps;
        vector<int> nexts;
        if (current % 5 == 0) nexts.push_back(current / 5);
        if (current % 11 == 0) nexts.push_back(current / 11);
        nexts.push_back(current + 1);
        nexts.push_back(current - 1);
        for (int nxt : nexts) {
            if (nxt <= 0 || visited.count(nxt)) continue;
            visited.insert(nxt);
            q.push({nxt, steps + 1});
        }
    }
    return -1;
}

