double maximumAreaOfLongestDiagonalRectangle(const std::vector<std::vector<int>>& dimensions) {
    double maxDiagonal = 0.0;
    double maxArea = 0.0;
    for (size_t i = 0; i < dimensions.size(); ++i) {
        double diagonalLength = std::sqrt(
            static_cast<double>(dimensions[i][0]) * dimensions[i][0] +
            static_cast<double>(dimensions[i][1]) * dimensions[i][1]
        );
