#include <bits/stdc++.h>

int minMovesToCaptureTheQueen(int a, int b, int c, int d, int e, int f) {
    // Check rook capture in one move
    if (a == e) { // same row
        bool blocked = (c == a) && ((b < d && d < f) || (f < d && d < b));
        if (!blocked) return 1;
    }
    if (b == f) { // same column
        bool blocked = (d == b) && ((a < c && c < e) || (e < c && c < a));
        if (!blocked) return 1;
    }
    // Check bishop capture in one move
    if (std::abs(c - e) == std::abs(d - f)) { // same diagonal
        bool blocked = false;
        // rook lies on the same diagonal?
        if (std::abs(a - e) == std::abs(b - f)) {
            // is rook between bishop and queen?
            bool betweenX = (a > c && a < e) || (a < c && a > e);
            bool betweenY = (b > d && b < f) || (b < d && b > f);
            blocked = betweenX && betweenY;
        }
        if (!blocked) return 1;
    }
    // Otherwise, two moves are sufficient
    return 2;
}

