int maxPartitions(std::string s, int k) {
    int max = 0;
    int n = static_cast<int>(s.size());
    for (int i = 0; i < n; ++i) {
        std::unordered_set<char> set;
        for (int j = 0; j < n; ++j) {
            if (i == j) {
                for (int c = static_cast<int>('a'); c <= static_cast<int>('z'); ++c) {
                    char ch = static_cast<char>(c);
                    if (ch != s[j]) {
                        set.insert(ch);
                    } else {
                        set.insert(s[j]);
                    }
                    if (static_cast<int>(set.size()) <= k) {
                        int partitions = 1;
                        std::unordered_set<char> distinct;
                        for (int x = 0; x < n; ++x) {
                            if (x == j) {
                                distinct.insert(ch);
                            } else {
                                distinct.insert(s[x]);
                            }
                            if (static_cast<int>(distinct.size()) > k) {
                                ++partitions;
                                distinct.clear();
                                if (x == j) {
                                    distinct.insert(ch);
                                } else {
                                    distinct.insert(s[x]);
                                }
                            }
                        }
                        if (partitions > max) {
                            max = partitions;
                        }
                    }
                    set.clear();
                }
            } else {
                set.insert(s[j]);
            }
        }
    }
    std::unordered_set<char> set;
    int partitions = 1;
    for (int i = 0; i < n; ++i) {
        set.insert(s[i]);
        if (static_cast<int>(set.size()) > k) {
            ++partitions;
            set.clear();
            set.insert(s[i]);
        }
    }
    if (partitions > max) {
        max = partitions;
    }
    return max;
}

