int minCoinsToAdd(std::vector<int> coins, long long target) {
    std::sort(coins.begin(), coins.end());
    long long maxReach = 0;
    int added = 0;
    std::size_t i = 0;
    while (maxReach < target) {
        if (i < coins.size() && static_cast<long long>(coins[i]) <= maxReach + 1) {
            maxReach += coins[i];
            ++i;
        } else {
            ++added;
            maxReach += maxReach + 1;
        }
    }
    return added;
}

#include <bits/stdc++.h>

long long maximumNumber(long long k, int x) {
    auto accumulated = [&](unsigned long long n) -> unsigned long long {
        unsigned long long total = 0;
        for (int shift = x - 1; shift < 64; shift += x) {
            if (shift >= 63) break; // beyond 63 bits, no contribution for n up to 2^63-1
            unsigned long long cycle = 1ULL << (shift + 1);
            unsigned long long full = (n + 1) / cycle;
            unsigned long long ones = full * (1ULL << shift);
            unsigned long long rem = (n + 1) % cycle;
            if (rem > (1ULL << shift)) ones += rem - (1ULL << shift);
            total += ones;
            if (total > (unsigned long long)k) break; // early exit
        }
        return total;
    };

    unsigned long long low = 0, high = 1;
    while (accumulated(high) <= (unsigned long long)k) {
        high <<= 1;
        if (high == 0) { // overflow protection
            high = std::numeric_limits<unsigned long long>::max();
            break;
        }
    }

    while (low < high) {
        unsigned long long mid = low + (high - low + 1) / 2;
        if (accumulated(mid) <= (unsigned long long)k) {
            low = mid;
        } else {
            high = mid - 1;
        }
    }
    return (long long)low;
}

