std::vector<std::vector<int>> findGridRegionAverage(const std::vector<std::vector<int>>& image, int threshold) {
    int m = static_cast<int>(image.size());
    if (m == 0) return {};
    int n = static_cast<int>(image[0].size());
    if (n == 0) return {};

    if (m < 3 || n < 3) {
        return image;
    }

    std::vector<std::vector<long long>> sumDiff(m + 1, std::vector<long long>(n + 1, 0));
    std::vector<std::vector<int>> cntDiff(m + 1, std::vector<int>(n + 1, 0));

    for (int i = 0; i <= m - 3; ++i) {
        for (int j = 0; j <= n - 3; ++j) {
            bool ok = true;
            for (int r = 0; r < 3 && ok; ++r) {
                for (int c = 0; c < 3 && ok; ++c) {
                    int cur = image[i + r][j + c];
                    if (c < 2 && std::abs(cur - image[i + r][j + c + 1]) > threshold) ok = false;
                    if (r < 2 && std::abs(cur - image[i + r + 1][j + c]) > threshold) ok = false;
                }
            }
            if (!ok) continue;

            long long regionSum = 0;
            for (int r = 0; r < 3; ++r) {
                for (int c = 0; c < 3; ++c) {
                    regionSum += image[i + r][j + c];
                }
            }
            long long regionAvg = regionSum / 9;

            sumDiff[i][j] += regionAvg;
            sumDiff[i + 3][j] -= regionAvg;
            sumDiff[i][j + 3] -= regionAvg;
            sumDiff[i + 3][j + 3] += regionAvg;

            cntDiff[i][j] += 1;
            cntDiff[i + 3][j] -= 1;
            cntDiff[i][j + 3] -= 1;
            cntDiff[i + 3][j + 3] += 1;
        }
    }

    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i > 0) {
                sumDiff[i][j] += sumDiff[i - 1][j];
                cntDiff[i][j] += cntDiff[i - 1][j];
            }
            if (j > 0) {
                sumDiff[i][j] += sumDiff[i][j - 1];
                cntDiff[i][j] += cntDiff[i][j - 1];
            }
            if (i > 0 && j > 0) {
                sumDiff[i][j] -= sumDiff[i - 1][j - 1];
                cntDiff[i][j] -= cntDiff[i - 1][j - 1];
            }
        }
    }

    std::vector<std::vector<int>> result(m, std::vector<int>(n));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (cntDiff[i][j] == 0) {
                result[i][j] = image[i][j];
            } else {
                result[i][j] = static_cast<int>(sumDiff[i][j] / cntDiff[i][j]);
            }
        }
    }
    return result;
}

#include <bits/stdc++.h>

int minimumTimeToRevert(const std::string& word, int k) {
    int n = static_cast<int>(word.size());
    using u64 = unsigned long long;
    const u64 base = 91138233ULL;
    std::vector<u64> pref(n + 1), power(n + 1);
    pref[0] = 0;
    power[0] = 1;
    for (int i = 0; i < n; ++i) {
        pref[i + 1] = pref[i] * base + static_cast<unsigned char>(word[i]);
        power[i + 1] = power[i] * base;
    }
    auto getHash = [&](int l, int r) -> u64 {
        return pref[r] - pref[l] * power[r - l];
    };
    int maxT = (n + k - 1) / k;
    for (int t = 1; t <= maxT; ++t) {
        int d = k * t;
        if (d > n) return t;
        if (getHash(0, n - d) == getHash(d, n)) return t;
    }
    return maxT;
}

