long long countValidPairs(const std::vector<std::vector<int>>& points) {
    int n = static_cast<int>(points.size());
    std::vector<int> xs, ys;
    xs.reserve(n);
    ys.reserve(n);
    for (const auto& p : points) {
        xs.push_back(p[0]);
        ys.push_back(p[1]);
    }
    std::sort(xs.begin(), xs.end());
    xs.erase(std::unique(xs.begin(), xs.end()), xs.end());
    std::sort(ys.begin(), ys.end());
    ys.erase(std::unique(ys.begin(), ys.end()), ys.end());

    std::unordered_map<int, int> xIndex;
    std::unordered_map<int, int> yIndex;
    xIndex.reserve(xs.size() * 2);
    yIndex.reserve(ys.size() * 2);
    for (int i = 0; i < (int)xs.size(); ++i) xIndex[xs[i]] = i + 1;
    for (int i = 0; i < (int)ys.size(); ++i) yIndex[ys[i]] = i + 1;

    int nx = static_cast<int>(xs.size());
    int ny = static_cast<int>(ys.size());

    std::vector<std::vector<int>> grid(nx + 1, std::vector<int>(ny + 1, 0));
    for (const auto& p : points) {
        int xi = xIndex[p[0]];
        int yi = yIndex[p[1]];
        grid[xi][yi] = 1;
    }

    std::vector<std::vector<int>> ps(nx + 1, std::vector<int>(ny + 1, 0));
    for (int i = 1; i <= nx; ++i) {
        int rowSum = 0;
        for (int j = 1; j <= ny; ++j) {
            rowSum += grid[i][j];
            ps[i][j] = ps[i - 1][j] + rowSum;
        }
    }

    long long ans = 0;
    for (int a = 0; a < n; ++a) {
        int xa = points[a][0];
        int ya = points[a][1];
        int xiA = xIndex[xa];
        int yiA = yIndex[ya];
        for (int b = 0; b < n; ++b) {
            if (a == b) continue;
            int xb = points[b][0];
            int yb = points[b][1];
            if (xa <= xb && ya >= yb && (xa < xb || ya > yb)) {
                int xiB = xIndex[xb];
                int yiB = yIndex[yb];
                int x1 = xiA, x2 = xiB;
                int y1 = yiA, y2 = yiB;
                int cnt = ps[x2][y1] - ps[x1 - 1][y1] - ps[x2][y2 - 1] + ps[x1 - 1][y2 - 1];
                if (cnt == 2) ++ans;
            }
        }
    }
    return ans;
}

