int minimumTime(const std::string& word, int k) {
    int n = static_cast<int>(word.size());
    if (n == 0) return 0;
    std::vector<int> pi(n);
    for (int i = 1; i < n; ++i) {
        int j = pi[i - 1];
        while (j > 0 && word[i] != word[j]) {
            j = pi[j - 1];
        }
        if (word[i] == word[j]) ++j;
        pi[i] = j;
    }
    int ans = (n + k - 1) / k;
    for (int len = pi[n - 1]; len > 0; len = pi[len - 1]) {
        int diff = n - len;
        if (diff % k == 0) ans = std::min(ans, diff / k);
    }
    return ans;
}

