int numberOfSubarrays(const std::vector<int>& nums, const std::vector<int>& pattern) {
    int n = static_cast<int>(nums.size());
    int m = static_cast<int>(pattern.size());
    if (m == 0) return n;
    if (m > n - 1) return 0;
    std::vector<int> lps(m, 0);
    for (int i = 1, len = 0; i < m; ) {
        if (pattern[i] == pattern[len]) {
            lps[i++] = ++len;
        } else if (len) {
            len = lps[len - 1];
        } else {
            lps[i++] = 0;
        }
    }
    int count = 0;
    int j = 0;
    for (int i = 0; i < n - 1; ++i) {
        int delta = nums[i + 1] - nums[i];
        int diff = (delta > 0) - (delta < 0);
        while (j && diff != pattern[j]) {
            j = lps[j - 1];
        }
        if (diff == pattern[j]) {
            ++j;
            if (j == m) {
                ++count;
                j = lps[j - 1];
            }
        }
    }
    return count;
}

#include <bits/stdc++.h>

int maximumPalindromesAfterOperations(const std::vector<std::string>& words) {
    std::array<long long, 26> freq{};
    long long totalChars = 0;
    for (const auto& w : words) {
        totalChars += static_cast<long long>(w.size());
        for (char ch : w) {
            ++freq[ch - 'a'];
        }
    }
    long long totalPairs = 0;
    for (long long cnt : freq) {
        totalPairs += cnt / 2;
    }

    struct Info {
        int pairsNeeded;
        bool oddLength;
    };
    std::vector<Info> infos;
    infos.reserve(words.size());
    for (const auto& w : words) {
        infos.push_back({static_cast<int>(w.size() / 2), static_cast<bool>(w.size() % 2)});
    }
    std::sort(infos.begin(), infos.end(), [](const Info& a, const Info& b) {
        return a.pairsNeeded < b.pairsNeeded;
    });

    long long usedPairs = 0;
    int answer = 0;
    std::size_t idx = 0;
    for (; idx < infos.size(); ++idx) {
        if (usedPairs + infos[idx].pairsNeeded <= totalPairs) {
            usedPairs += infos[idx].pairsNeeded;
            ++answer;
        } else {
            break;
        }
    }

    long long leftoverChars = totalChars - usedPairs * 2;
    if (answer < static_cast<int>(words.size()) && leftoverChars > 0) {
        for (std::size_t j = idx; j < infos.size(); ++j) {
            if (infos[j].oddLength) {
                ++answer;
                break;
            }
        }
    }
    return answer;
}

