int maxConsecutive(std::vector<int> nums) {
    if (nums.empty()) return 0;
    std::sort(nums.begin(), nums.end());
    std::size_t n = nums.size();
    std::vector<long long> b;
    b.reserve(n);
    for (std::size_t i = 0; i < n; ++i) {
        b.push_back(static_cast<long long>(nums[i]) - static_cast<long long>(i));
    }
    std::deque<std::size_t> maxD, minD;
    std::size_t left = 0;
    int answer = 0;
    for (std::size_t right = 0; right < n; ++right) {
        while (!maxD.empty() && b[right] >= b[maxD.back()]) maxD.pop_back();
        maxD.push_back(right);
        while (!minD.empty() && b[right] <= b[minD.back()]) minD.pop_back();
        minD.push_back(right);
        while (!maxD.empty() && !minD.empty() && b[maxD.front()] - b[minD.front()] > 1) {
            if (maxD.front() == left) maxD.pop_front();
            if (minD.front() == left) minD.pop_front();
            ++left;
        }
        answer = std::max(answer, static_cast<int>(right - left + 1));
    }
    return answer;
}

