    for (int v : nums) ++cnt[v];
    int ans = 0;
    for (int s = 2; s <= 2 * maxVal; ++s) {
        int cur = 0;
        int limit = s / 2;
        for (int x = 1; x <= limit; ++x) {
            int y = s - x;
            if (y < 1 || y > maxVal) continue;
            if (x == y) cur += cnt[x] / 2;
            else cur += std::min(cnt[x], cnt[y]);
        }
        if (cur > ans) ans = cur;
    }
    return ans;
}

