int countPrefixSuffixPairs(const std::vector<std::string>& words) {
    std::unordered_map<std::string, int> freq;
    long long ans = 0;
    for (const std::string& w : words) {
        int m = static_cast<int>(w.size());
        std::vector<int> pi(m, 0);
        for (int i = 1; i < m; ++i) {
            int j = pi[i - 1];
            while (j > 0 && w[i] != w[j]) j = pi[j - 1];
            if (w[i] == w[j]) ++j;
            pi[i] = j;
        }
        int len = m ? pi[m - 1] : 0;
        while (len > 0) {
            ans += freq[w.substr(0, len)];
            len = pi[len - 1];
        }
        ans += freq[w];
        ++freq[w];
    }
    return static_cast<int>(ans);
}

