bool splitArray(std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    std::unordered_map<int, int> freq;
    freq.reserve(nums.size() * 2);
    for (int x : nums) {
        int c = ++freq[x];
        if (c > 2) {
            return false;
        }
    }
    return static_cast<int>(freq.size()) >= n / 2;
}

