std::vector<int> beautifulIndices(const std::string& s, const std::string& a, const std::string& b, int k) {
    std::vector<int> beautifulIndices;
    size_t aLength = a.size();
    size_t bLength = b.size();
    for (size_t i = 0; i + aLength <= s.size(); ++i) {
        if (s.substr(i, aLength) == a) {
            for (size_t j = 0; j + bLength <= s.size(); ++j) {
                if (s.substr(j, bLength) == b && std::abs(static_cast<long long>(i) - static_cast<long long>(j)) <= k) {
                    beautifulIndices.push_back(static_cast<int>(i));
                    break;
                }
            }
        }
    }
    std::sort(beautifulIndices.begin(), beautifulIndices.end());
    beautifulIndices.erase(std::unique(beautifulIndices.begin(), beautifulIndices.end()), beautifulIndices.end());
    return beautifulIndices;
}

