#include <bits/stdc++.h>

int minOperations(const std::vector<int>& nums, int k) {
    using ll = long long;
    std::priority_queue<ll, std::vector<ll>, std::greater<ll>> pq;
    for (int v : nums) {
        pq.push(static_cast<ll>(v));
    }
    int ops = 0;
    while (pq.size() >= 2) {
        ll a = pq.top(); pq.pop();
        ll b = pq.top();
        if (a + b >= static_cast<ll>(k)) {
            pq.push(a);
            break;
        }
        pq.pop();
        pq.push(a + b);
        ++ops;
    }
    return ops;
}

