using namespace std;

int signalSpeedG;
vector<vector<pair<int,int>>> adjG;

int dfs(int u, int parent, long long dist) {
    int cnt = (dist % signalSpeedG == 0) ? 1 : 0;
    for (auto& [v, w] : adjG[u]) {
        if (v == parent) continue;
        cnt += dfs(v, u, dist + w);
    }
    return cnt;
}

vector<int> countPairsOfConnectableServers(vector<vector<int>>& edges, int signalSpeed) {
    int n = edges.size() + 1;
    signalSpeedG = signalSpeed;
    adjG.assign(n, {});
    for (auto& e : edges) {
        adjG[e[0]].push_back({e[1], e[2]});
        adjG[e[1]].push_back({e[0], e[2]});
    }
    vector<int> count(n, 0);
    for (int root = 0; root < n; root++) {
        long long total = 0, pairs = 0;
        for (auto& [child, w] : adjG[root]) {
            long long branchCount = dfs(child, root, w);
            pairs += total * branchCount;
            total += branchCount;
        }
        count[root] = (int)pairs;
    }
    return count;
}

long long maxNodeValueSum(std::vector<long long>& nums, long long k, std::vector<std::vector<int>>& edges) {
    long long base_sum = 0;
    for (long long v : nums) base_sum += v;
    long long pos_sum = 0, pos_cnt = 0, min_pos = 0;
    bool has_min_pos = false;
    long long max_neg = 0;
    bool has_max_neg = false;
    for (long long v : nums) {
        long long diff = (v ^ k) - v;
        if (diff > 0) {
            pos_sum += diff;
            ++pos_cnt;
            if (!has_min_pos || diff < min_pos) { min_pos = diff; has_min_pos = true; }
        } else {
            if (!has_max_neg || diff > max_neg) { max_neg = diff; has_max_neg = true; }
        }
    }
    long long ans;
    if (pos_cnt % 2 == 0) {
        ans = base_sum + pos_sum;
    } else {
        long long cand1 = LLONG_MIN;
        if (has_min_pos) cand1 = base_sum + pos_sum - min_pos;
        long long cand2 = LLONG_MIN;
        if (has_max_neg) cand2 = base_sum + pos_sum + max_neg;
        ans = std::max(cand1, cand2);
    }
    return ans;
}

