long long countSubmatrices(const std::vector<std::vector<int>>& grid, long long k) {
    std::size_t m = grid.size();
    if (m == 0) return 0;
    std::size_t n = grid[0].size();
    std::vector<long long> colPref(n, 0);
    long long answer = 0;
    for (std::size_t i = 0; i < m; ++i) {
        long long rowSum = 0;
        for (std::size_t j = 0; j < n; ++j) {
            rowSum += grid[i][j];
            colPref[j] += rowSum;
            if (colPref[j] <= k) ++answer;
        }
    }
    return answer;
}

int minimumOperationsToWriteY(std::vector<std::vector<int>>& grid) {
    int n = static_cast<int>(grid.size());
    int mid = n / 2;
    std::array<int, 3> ycnt{0, 0, 0}, othercnt{0, 0, 0};
    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < n; ++c) {
            int val = grid[r][c];
            bool isY = (c == mid && r >= mid) ||
                       (r == c && r <= mid) ||
                       (r + c == n - 1 && r <= mid);
            if (isY) ycnt[val]++; else othercnt[val]++;
        }
    }
    int y_total = ycnt[0] + ycnt[1] + ycnt[2];
    int other_total = othercnt[0] + othercnt[1] + othercnt[2];
    int best = std::numeric_limits<int>::max();
    for (int a = 0; a < 3; ++a) {
        for (int b = 0; b < 3; ++b) {
            if (a == b) continue;
            int changes = (y_total - ycnt[a]) + (other_total - othercnt[b]);
            if (changes < best) best = changes;
        }
    }
    return best;
}

