std::vector<int> distributeElements(const std::vector<int>& nums) {
    size_t n = nums.size();
    if (n == 0) return std::vector<int>();
    if (n == 1) return std::vector<int>{nums[0]};
    std::vector<int> arr1;
    std::vector<int> arr2;
    arr1.push_back(nums[0]);
    arr2.push_back(nums[1]);
    for (size_t i = 2; i < n; ++i) {
        if (arr1.back() > arr2.back()) {
            arr1.push_back(nums[i]);
        } else {
            arr2.push_back(nums[i]);
        }
    }
    std::vector<int> result = arr1;
    result.insert(result.end(), arr2.begin(), arr2.end());
    return result;
}

#include <bits/stdc++.h>

class Fenwick {
public:
    Fenwick(int n = 0) : n_(n), bit_(n + 1, 0) {}
    void init(int n) { n_ = n; bit_.assign(n + 1, 0); }
    void add(int idx, int delta) {
        for (; idx <= n_; idx += idx & -idx) bit_[idx] += delta;
    }
    int sum(int idx) const {
        int res = 0;
        for (; idx > 0; idx -= idx & -idx) res += bit_[idx];
        return res;
    }
private:
    int n_;
    std::vector<int> bit_;
};

std::vector<int> distributeArray(std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return {};
    std::vector<int> vals = nums;
    std::sort(vals.begin(), vals.end());
    vals.erase(std::unique(vals.begin(), vals.end()), vals.end());
    int m = static_cast<int>(vals.size());
    auto getIdx = [&](int x) {
        return static_cast<int>(std::lower_bound(vals.begin(), vals.end(), x) - vals.begin()) + 1;
    };
    Fenwick bit1(m), bit2(m);
    std::vector<int> arr1, arr2;
    arr1.reserve(n);
    arr2.reserve(n);
    arr1.push_back(nums[0]);
    bit1.add(getIdx(nums[0]), 1);
    int sz1 = 1, sz2 = 0;
    if (n > 1) {
        arr2.push_back(nums[1]);
        bit2.add(getIdx(nums[1]), 1);
        sz2 = 1;
    }
    for (int i = 2; i < n; ++i) {
        int idx = getIdx(nums[i]);
        int greater1 = sz1 - bit1.sum(idx);
        int greater2 = sz2 - bit2.sum(idx);
        bool toArr1;
        if (greater1 > greater2) toArr1 = true;
        else if (greater2 > greater1) toArr1 = false;
        else {
            if (sz1 < sz2) toArr1 = true;
            else if (sz2 < sz1) toArr1 = false;
            else toArr1 = true;
        }
        if (toArr1) {
            arr1.push_back(nums[i]);
            bit1.add(idx, 1);
            ++sz1;
        } else {
            arr2.push_back(nums[i]);
            bit2.add(idx, 1);
            ++sz2;
        }
    }
    std::vector<int> result;
    result.reserve(n);
    result.insert(result.end(), arr1.begin(), arr1.end());
    result.insert(result.end(), arr2.begin(), arr2.end());
    return result;
}

