int minBoxes(const std::vector<int>& apple, std::vector<int> capacity) {
    long long totalApples = 0;
    for (size_t i = 0; i < apple.size(); ++i) totalApples += apple[i];
    std::sort(capacity.begin(), capacity.end(), std::greater<int>());
    int used = 0;
    long long sum = 0;
    for (size_t i = 0; i < capacity.size() && sum < totalApples; ++i) {
        sum += capacity[i];
        ++used;
    }
    return sum >= totalApples ? used : -1;
}

