std::vector<std::string> shortestUncommonSubstring(const std::vector<std::string>& arr) {
    std::unordered_map<std::string, int> freq;
    for (size_t idx = 0; idx < arr.size(); ++idx) {
        const std::string& s = arr[idx];
        std::unordered_set<std::string> seen;
        for (size_t i = 0; i < s.size(); ++i) {
            std::string sub;
            sub.reserve(s.size() - i);
            for (size_t j = i; j < s.size(); ++j) {
                sub.push_back(s[j]);
                if (seen.insert(sub).second) {
                    freq[sub] = freq[sub] + 1;
                }
            }
        }
    }
    std::vector<std::string> answer;
    for (const std::string& s : arr) {
        std::string best = "";
        for (size_t len = 1; len <= s.size(); ++len) {
            std::string candidate;
            bool hasCandidate = false;
            for (size_t i = 0; i + len <= s.size(); ++i) {
                std::string sub = s.substr(i, len);
                auto it = freq.find(sub);
                if (it != freq.end() && it->second == 1) {
                    if (!hasCandidate || sub < candidate) {
                        candidate = sub;
                        hasCandidate = true;
                    }
                }
            }
            if (hasCandidate) {
                best = candidate;
                break;
            }
        }
        answer.push_back(best);
    }
    return answer;
}

