std::string replaceQuestionMarks(const std::string& s) {
    size_t n = s.size();
    std::array<int, 26> counts{};
    for (char ch : s) {
        if (ch != '?') {
            counts[ch - 'a']++;
        }
    }
    std::string result;
    result.resize(n);
    for (size_t i = 0; i < n; ++i) {
        char ch = s[i];
        if (ch != '?') {
            result[i] = ch;
        } else {
            int bestIdx = 0;
            int bestCnt = counts[0];
            for (int j = 1; j < 26; ++j) {
                int cnt = counts[j];
                if (cnt < bestCnt || (cnt == bestCnt && j < bestIdx)) {
                    bestCnt = cnt;
                    bestIdx = j;
                }
            }
            char chosen = static_cast<char>('a' + bestIdx);
            result[i] = chosen;
            counts[bestIdx]++;
        }
    }
    return result;
}

