using namespace std;
const long long MOD = 1000000007LL;

long long mod_pow(long long base, long long exp) {
    long long res = 1 % MOD;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

long long sumOfPower(std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    std::vector<long long> dp(k + 1, 0);
    dp[0] = 1;
    const long long inv2 = (MOD + 1) / 2;
    for (int val : nums) {
        if (val > k) continue;
        for (long long s = k; s >= val; --s) {
            dp[s] = (dp[s] + dp[s - val] * inv2) % MOD;
        }
    }
    long long ans = dp[k] * mod_pow(2, n) % MOD;
    return ans;
}

