#include <bits/stdc++.h>
std::vector<long long> markElements(const std::vector<int>& nums, const std::vector<std::vector<int>>& queries) {
    int n = nums.size();
    std::vector<char> marked(n, 0);
    long long currentSum = 0;
    for (int v : nums) currentSum += v;
    using P = std::pair<int,int>;
    std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
    for (int i = 0; i < n; ++i) pq.emplace(nums[i], i);
    std::vector<long long> answer;
    answer.reserve(queries.size());
    for (const auto& q : queries) {
        int idx = q[0];
        int k = q[1];
        if (!marked[idx]) {
            marked[idx] = 1;
            currentSum -= nums[idx];
        }
        int need = k;
        while (need > 0 && !pq.empty()) {
            auto top = pq.top(); pq.pop();
            int val = top.first;
            int id = top.second;
            if (marked[id]) continue;
            marked[id] = 1;
            currentSum -= val;
            --need;
        }
        answer.push_back(currentSum);
    }
    return answer;
}

#include <bits/stdc++.h>

long long minimumMoves(const std::vector<int>& nums, long long k, long long maxChanges) {
    long long n = static_cast<long long>(nums.size());
    std::vector<long long> cnt(n + 1, 0), s(n + 1, 0);
    for (long long i = 1; i <= n; ++i) {
        long long x = nums[i - 1];
        cnt[i] = cnt[i - 1] + x;
        s[i] = s[i - 1] + i * x;
    }
    long long ans = LLONG_MAX;
    for (long long i = 1; i <= n; ++i) {
        long long x = nums[i - 1];
        long long t = 0;
        long long need = k - x;
        for (long long j : {i - 1, i + 1}) {
            if (need > 0 && j >= 1 && j <= n && nums[j - 1] == 1) { need -= 1; t += 1; }
        }
        long long c = std::min(need, maxChanges);
        need -= c;
        t += c * 2;
        if (need <= 0) { ans = std::min(ans, t); continue; }
        long long l = 2, r = std::max(i - 1, n - i);
        while (l <= r) {
            long long mid = (l + r) >> 1;
            long long l1 = std::max(1LL, i - mid), r1 = std::max(0LL, i - 2);
            long long l2 = std::min(n + 1, i + 2), r2 = std::min(n, i + mid);
            long long c1 = cnt[r1] - cnt[l1 - 1];
            long long c2 = cnt[r2] - cnt[l2 - 1];
            if (c1 + c2 >= need) {
                long long t1 = c1 * i - (s[r1] - s[l1 - 1]);
                long long t2 = s[r2] - s[l2 - 1] - c2 * i;
                ans = std::min(ans, t + t1 + t2);
                r = mid - 1;
            } else {
                l = mid + 1;
            }
        }
    }
    return ans;
}

