int minOperationsToReachK(int k) {
    if (k <= 1) return 0;
    int best = k - 1;
    for (int v = 1; v <= k; ++v) {
        int copies = 0;
        if (k > v) {
            copies = (k - 1) / v;
        }
        int ops = (v - 1) + copies;
        if (ops < best) best = ops;
    }
    return best;
}

