struct Node {
    std::unordered_map<char, Node*> children;
    int bestIdx;
    Node() : bestIdx(-1) {}
};

std::vector<int> longestCommonSuffixQueries(const std::vector<std::string>& wordsContainer, const std::vector<std::string>& wordsQuery) {
    Node root;
    std::vector<int> lengths(wordsContainer.size());
    for (size_t i = 0; i < wordsContainer.size(); ++i) lengths[i] = (int)wordsContainer[i].size();

    auto update = [&](Node* node, int idx) {
        int cur = node->bestIdx;
        if (cur == -1 ||
            lengths[idx] < lengths[cur] ||
            (lengths[idx] == lengths[cur] && idx < cur)) {
            node->bestIdx = idx;
        }
    };

    for (int i = 0; i < (int)wordsContainer.size(); ++i) {
        const std::string& s = wordsContainer[i];
        Node* node = &root;
        update(node, i);
        for (int p = (int)s.size() - 1; p >= 0; --p) {
            char ch = s[p];
            auto it = node->children.find(ch);
            if (it == node->children.end()) {
                Node* newNode = new Node();
                node->children[ch] = newNode;
                node = newNode;
            } else {
                node = it->second;
            }
            update(node, i);
        }
    }

    std::vector<int> answer(wordsQuery.size());
    for (size_t qi = 0; qi < wordsQuery.size(); ++qi) {
        const std::string& q = wordsQuery[qi];
        Node* node = &root;
        int best = node->bestIdx;
        for (int p = (int)q.size() - 1; p >= 0; --p) {
            char ch = q[p];
            auto it = node->children.find(ch);
            if (it == node->children.end()) break;
            node = it->second;
            best = node->bestIdx;
        }
        answer[qi] = best;
    }
    return answer;
}

