std::vector<long long> mostFrequentIDs(const std::vector<long long>& nums, const std::vector<long long>& freq) {
    size_t n = nums.size();
    std::vector<long long> ans(n);
    std::unordered_map<long long, long long> idCount;
    std::vector<std::pair<long long, long long>> heap; // (frequency, id)

    auto heapPush = [&](const std::pair<long long, long long>& item) {
        heap.push_back(item);
        size_t i = heap.size() - 1;
        while (i > 0) {
            size_t p = (i - 1) >> 1;
            if (heap[p].first >= heap[i].first) break;
            std::swap(heap[p], heap[i]);
            i = p;
        }
    };

    auto heapPop = [&]() -> std::pair<long long, long long> {
        std::pair<long long, long long> top = heap[0];
        std::pair<long long, long long> last = heap.back();
        heap.pop_back();
        if (!heap.empty()) {
            heap[0] = last;
            size_t i = 0;
            while (true) {
                size_t l = i * 2 + 1;
                size_t r = l + 1;
                size_t largest = i;
                if (l < heap.size() && heap[l].first > heap[largest].first) largest = l;
                if (r < heap.size() && heap[r].first > heap[largest].first) largest = r;
                if (largest == i) break;
                std::swap(heap[i], heap[largest]);
                i = largest;
            }
        }
        return top;
    };

    for (size_t i = 0; i < n; ++i) {
        long long id = nums[i];
        long long delta = freq[i];
        auto it = idCount.find(id);
        long long prev = (it != idCount.end()) ? it->second : 0;
        long long now = prev + delta;

        if (now > 0) {
            idCount[id] = now;
            heapPush({now, id});
        } else {
            idCount.erase(id);
        }

        while (!heap.empty()) {
            auto it2 = idCount.find(heap[0].second);
            if (it2 == idCount.end() || it2->second != heap[0].first) {
                heapPop();
            } else {
                break;
            }
        }

        ans[i] = heap.empty() ? 0 : heap[0].first;
    }
    return ans;
}

