#include <bits/stdc++.h>

int shortestSubarrayOr(const std::vector<int>& nums, int k) {
    if (nums.empty()) return -1;
    if (k == 0) return 1;
    const int B = 32;
    std::vector<int> cnt(B, 0);
    unsigned int curOr = 0;
    std::size_t left = 0;
    int best = INT_MAX;
    for (std::size_t right = 0; right < nums.size(); ++right) {
        int x = nums[right];
        for (int b = 0; b < B; ++b) {
            if ((x >> b) & 1) {
                ++cnt[b];
                curOr |= (1u << b);
            }
        }
        while (curOr >= static_cast<unsigned int>(k) && left <= right) {
            best = std::min(best, static_cast<int>(right - left + 1));
            int y = nums[left];
            for (int b = 0; b < B; ++b) {
                if ((y >> b) & 1) {
                    --cnt[b];
                    if (cnt[b] == 0) {
                        curOr &= ~(1u << b);
                    }
                }
            }
            ++left;
        }
    }
    return best == INT_MAX ? -1 : best;
}

