    const int BIT = 31;
    std::vector<int> cnt(BIT, 0);
    int curOr = 0;
    int left = 0;
    int best = INT_MAX;
    size_t n = nums.size();

    for (size_t right = 0; right < n; ++right) {
        int x = nums[right];
        for (int b = 0; b < BIT; ++b) {
            if (x & (1 << b)) {
                ++cnt[b];
                curOr |= (1 << b);
            }
        }
        while ((curOr & k) == k) {
            best = std::min(best, static_cast<int>(right - left + 1));
            int y = nums[left];
            for (int b = 0; b < BIT; ++b) {
                if (y & (1 << b)) {
                    --cnt[b];
                    if (cnt[b] == 0) {
                        curOr &= ~(1 << b);
                    }
                }
            }
            ++left;
        }
    }
    return best == INT_MAX ? -1 : best;
}

