#include <bits/stdc++.h>

int sumPower(std::vector<int> nums, int k) {
    const long long MOD = 1000000007LL;
    int n = (int)nums.size();
    std::sort(nums.begin(), nums.end());

    std::vector<long long> diffs;
    diffs.push_back(0);
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            diffs.push_back((long long)nums[j] - nums[i]);
        }
    }
    std::sort(diffs.begin(), diffs.end());
    diffs.erase(std::unique(diffs.begin(), diffs.end()), diffs.end());

    std::vector<long long> cnt_atleast(diffs.size(), 0);

    for (size_t idx = 0; idx < diffs.size(); ++idx) {
        long long d = diffs[idx];
        std::vector<std::vector<long long>> dp(n, std::vector<long long>(k + 1, 0));
        for (int i = 0; i < n; ++i) dp[i][1] = 1;
        for (int t = 2; t <= k; ++t) {
            for (int i = 0; i < n; ++i) {
                long long sum = 0;
                for (int j = 0; j < i; ++j) {
                    if ((long long)nums[i] - nums[j] >= d) {
                        sum += dp[j][t - 1];
                        if (sum >= MOD) sum -= MOD;
                    }
                }
                dp[i][t] = sum;
            }
        }
        long long total = 0;
        for (int i = 0; i < n; ++i) {
            total += dp[i][k];
            if (total >= MOD) total -= MOD;
        }
        cnt_atleast[idx] = total;
    }

    long long ans = 0;
    for (int idx = (int)diffs.size() - 1; idx >= 0; --idx) {
        long long cnt_exact = cnt_atleast[idx];
        if (idx + 1 < (int)diffs.size()) {
            cnt_exact = (cnt_exact - cnt_atleast[idx + 1] + MOD) % MOD;
        }
        long long contrib = (diffs[idx] % MOD) * cnt_exact % MOD;
        ans += contrib;
        if (ans >= MOD) ans -= MOD;
    }
    return (int)ans;
}

#include <bits/stdc++.h>
long long minimumDistance(const std::vector<std::vector<int>>& points) {
    int n = points.size();
    std::vector<long long> u(n), v(n);
    for (int i = 0; i < n; ++i) {
        long long x = points[i][0];
        long long y = points[i][1];
        u[i] = x + y;
        v[i] = x - y;
    }

    long long max_u = LLONG_MIN, second_max_u = LLONG_MIN, cnt_max_u = 0;
    long long min_u = LLONG_MAX, second_min_u = LLONG_MAX, cnt_min_u = 0;
    long long max_v = LLONG_MIN, second_max_v = LLONG_MIN, cnt_max_v = 0;
    long long min_v = LLONG_MAX, second_min_v = LLONG_MAX, cnt_min_v = 0;

    for (int i = 0; i < n; ++i) {
        long long val = u[i];
        if (val > max_u) {
            second_max_u = max_u;
            max_u = val;
            cnt_max_u = 1;
        } else if (val == max_u) {
            ++cnt_max_u;
        } else if (val > second_max_u) {
            second_max_u = val;
        }

        if (val < min_u) {
            second_min_u = min_u;
            min_u = val;
            cnt_min_u = 1;
        } else if (val == min_u) {
            ++cnt_min_u;
        } else if (val < second_min_u) {
            second_min_u = val;
        }

        val = v[i];
        if (val > max_v) {
            second_max_v = max_v;
            max_v = val;
            cnt_max_v = 1;
        } else if (val == max_v) {
            ++cnt_max_v;
        } else if (val > second_max_v) {
            second_max_v = val;
        }

        if (val < min_v) {
            second_min_v = min_v;
            min_v = val;
            cnt_min_v = 1;
        } else if (val == min_v) {
            ++cnt_min_v;
        } else if (val < second_min_v) {
            second_min_v = val;
        }
    }

    long long answer = LLONG_MAX;
    for (int i = 0; i < n; ++i) {
        long long cur_max_u = (u[i] == max_u && cnt_max_u == 1) ? second_max_u : max_u;
        long long cur_min_u = (u[i] == min_u && cnt_min_u == 1) ? second_min_u : min_u;
        long long cur_max_v = (v[i] == max_v && cnt_max_v == 1) ? second_max_v : max_v;
        long long cur_min_v = (v[i] == min_v && cnt_min_v == 1) ? second_min_v : min_v;

        long long candidate = std::max(cur_max_u - cur_min_u, cur_max_v - cur_min_v);
        if (candidate < answer) answer = candidate;
    }
    return answer;
}

