std::string smallestString(const std::string& s, int k) {
    int n = static_cast<int>(s.size());
    std::string result;
    result.reserve(n);
    for (int i = 0; i < n; ++i) {
        int cur = s[i] - 'a';
        for (int c = 0; c < 26; ++c) {
            int diff = std::abs(cur - c);
            int cost = std::min(diff, 26 - diff);
            int maxRemain = 13 * (n - i - 1);
            if (k - cost <= maxRemain && k - cost >= 0) {
                result.push_back('a' + c);
                k -= cost;
                break;
            }
        }
    }
    return result;
}

