long long countSubarrays(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    std::vector<int> nextGreater(n, n);
    std::vector<int> st;
    st.reserve(n);
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && nums[i] > nums[st.back()]) {
            int idx = st.back();
            st.pop_back();
            nextGreater[idx] = i;
        }
        st.push_back(i);
    }

    std::vector<int> comp = nums;
    std::sort(comp.begin(), comp.end());
    comp.erase(std::unique(comp.begin(), comp.end()), comp.end());
    int m = static_cast<int>(comp.size());
    std::vector<std::vector<int>> posLists(m);
    for (int i = 0; i < n; ++i) {
        int id = static_cast<int>(std::lower_bound(comp.begin(), comp.end(), nums[i]) - comp.begin());
        posLists[id].push_back(i);
    }

    long long ans = 0;
    for (const auto& positions : posLists) {
        if (positions.empty()) continue;
        long long cnt = 0;
        int prev = -1;
        for (int pos : positions) {
            if (cnt == 0) {
                cnt = 1;
                prev = pos;
            } else {
                if (nextGreater[prev] > pos) {
                    ++cnt;
                } else {
                    ans += cnt * (cnt + 1) / 2;
                    cnt = 1;
                }
                prev = pos;
            }
        }
        ans += cnt * (cnt + 1) / 2;
    }
    return ans;
}

