std::vector<long long> minimumTime(int n, const std::vector<std::vector<int>>& edges, const std::vector<long long>& disappear) {
    std::vector<std::vector<std::pair<int, long long>>> adj(n);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        long long w = static_cast<long long>(e[2]);
        adj[u].emplace_back(v, w);
        adj[v].emplace_back(u, w);
    }

    const long long INF = std::numeric_limits<long long>::max();
    std::vector<long long> dist(n, INF);

    if (disappear.empty() || disappear[0] <= 0) {
        return std::vector<long long>(n, -1);
    }
    dist[0] = 0;

    using State = std::pair<long long, int>;
    std::priority_queue<State, std::vector<State>, std::greater<State>> heap;
    heap.emplace(0, 0);

    while (!heap.empty()) {
        State top = heap.top();
        heap.pop();
        long long time = top.first;
        int node = top.second;
        if (time != dist[node]) continue;
        if (time >= disappear[node]) continue;

        for (const auto& edge : adj[node]) {
            int nbr = edge.first;
            long long w = edge.second;
            long long newTime = time + w;
            if (newTime < disappear[nbr] && newTime < dist[nbr]) {
                dist[nbr] = newTime;
                heap.emplace(newTime, nbr);
            }
        }
    }

    for (auto& d : dist) {
        if (d == INF) d = -1;
    }
    return dist;
}

