int kthSmallestAmount(const std::vector<int>& coins, int k) {
    std::unordered_set<int> seenCoins;
    std::vector<int> uniq;
    uniq.reserve(coins.size());
    for (int c : coins) {
        if (seenCoins.insert(c).second) {
            uniq.push_back(c);
        }
    }

    using Node = std::pair<long long, int>;
    auto cmp = [](const Node& a, const Node& b) { return a.first > b.first; };
    std::priority_queue<Node, std::vector<Node>, decltype(cmp)> heap(cmp);

    for (int c : uniq) {
        heap.emplace(c, c);
    }

    std::unordered_set<long long> seen;
    int cnt = 0;
    long long answer = 0;

    while (cnt < k) {
        Node cur = heap.top();
        heap.pop();
        long long val = cur.first;
        int coin = cur.second;
        if (seen.insert(val).second) {
            ++cnt;
            answer = val;
        }
        heap.emplace(val + coin, coin);
    }
    return static_cast<int>(answer);
}

