int countSpecialCharacters(const std::string& word) {
    uint32_t lowerMask = 0, upperMask = 0;
    for (unsigned char c : word) {
        if (c >= 'a' && c <= 'z')
            lowerMask |= 1u << (c - 'a');
        else if (c >= 'A' && c <= 'Z')
            upperMask |= 1u << (c - 'A');
    }
    uint32_t both = lowerMask & upperMask;
    return static_cast<int>(__builtin_popcount(both));
}

