int max_prime_difference(const std::vector<int>& nums) {
    auto is_prime = [](int x) -> bool {
        if (x < 2) return false;
        if (x == 2) return true;
        if ((x & 1) == 0) return false;
        int limit = static_cast<int>(std::sqrt(x));
        for (int d = 3; d <= limit; d += 2) {
            if (x % d == 0) return false;
        }
        return true;
    };
    int first = -1, last = -1;
    for (int i = 0, n = static_cast<int>(nums.size()); i < n; ++i) {
        if (is_prime(nums[i])) {
            if (first == -1) first = i;
            last = i;
        }
    }
    return (first == -1) ? 0 : last - first;
}

