long long minimumValueSum(const std::vector<long long>& nums, const std::vector<long long>& andValues) {
    int n = static_cast<int>(nums.size());
    int m = static_cast<int>(andValues.size());
    const long long INF = (long long)1e15;
    std::vector<long long> dpPrev(n, INF);
    for (int k = 1; k <= m; ++k) {
        long long target = andValues[k - 1];
        std::vector<long long> dpCurr(n, INF);
        std::unordered_map<long long, long long> curMap;
        for (int i = 0; i < n; ++i) {
            std::unordered_map<long long, long long> nextMap;
            long long startPrev = (i == 0) ? 0LL : dpPrev[i - 1];
            if (startPrev < INF) {
                long long val = nums[i];
                auto it = nextMap.find(val);
                if (it == nextMap.end() || startPrev < it->second) nextMap[val] = startPrev;
            }
            for (const auto& kv : curMap) {
                long long newAnd = kv.first & nums[i];
                long long prevCost = kv.second;
                auto it = nextMap.find(newAnd);
                if (it == nextMap.end() || prevCost < it->second) nextMap[newAnd] = prevCost;
            }
            auto bit = nextMap.find(target);
            if (bit != nextMap.end()) dpCurr[i] = bit->second + nums[i];
            curMap = std::move(nextMap);
        }
        dpPrev = std::move(dpCurr);
    }
    long long ans = dpPrev[n - 1];
    return ans >= INF ? -1 : ans;
}

