#include <bits/stdc++.h>

int countStableBinaryArrays(int zero, int one, int limit) {
    const int MOD = 1000000007;
    if (limit <= 0) return 0;
    std::vector<std::vector<std::vector<int>>> dp0(zero + 1,
        std::vector<std::vector<int>>(one + 1, std::vector<int>(limit + 1, 0)));
    std::vector<std::vector<std::vector<int>>> dp1(zero + 1,
        std::vector<std::vector<int>>(one + 1, std::vector<int>(limit + 1, 0)));
    if (zero > 0) dp0[1][0][1] = 1;
    if (one > 0) dp1[0][1][1] = 1;
    for (int z = 0; z <= zero; ++z) {
        for (int o = 0; o <= one; ++o) {
            for (int len = 1; len <= limit; ++len) {
                int cur0 = dp0[z][o][len];
                if (cur0) {
                    if (z < zero && len < limit) {
                        dp0[z + 1][o][len + 1] = (dp0[z + 1][o][len + 1] + cur0) % MOD;
                    }
                    if (o < one) {
                        dp1[z][o + 1][1] = (dp1[z][o + 1][1] + cur0) % MOD;
                    }
                }
                int cur1 = dp1[z][o][len];
                if (cur1) {
                    if (o < one && len < limit) {
                        dp1[z][o + 1][len + 1] = (dp1[z][o + 1][len + 1] + cur1) % MOD;
                    }
                    if (z < zero) {
                        dp0[z + 1][o][1] = (dp0[z + 1][o][1] + cur1) % MOD;
                    }
                }
            }
        }
    }
    int ans = 0;
    for (int len = 1; len <= limit; ++len) {
        ans = (ans + dp0[zero][one][len]) % MOD;
        ans = (ans + dp1[zero][one][len]) % MOD;
    }
    return ans;
}

