#include <bits/stdc++.h>
#include <cstdint>

long long countStableBinaryArrays(int zero, int one, int limit) {
    const int MOD = 1000000007;
    std::vector<std::vector<int>> dp0(zero + 1, std::vector<int>(one + 1, 0));
    std::vector<std::vector<int>> dp1(zero + 1, std::vector<int>(one + 1, 0));
    std::vector<int> win1(one + 1, 0);
    for (int i = 0; i <= zero; ++i) {
        if (i > 0) {
            int removeIdx = i - 1 - limit;
            for (int j = 0; j <= one; ++j) {
                win1[j] = (win1[j] + dp1[i - 1][j]) % MOD;
                if (removeIdx >= 0) {
                    win1[j] -= dp1[removeIdx][j];
                    if (win1[j] < 0) win1[j] += MOD;
                }
            }
        }
        for (int j = 0; j <= one; ++j) {
            long long val = 0;
            if (i > 0) val = win1[j];
            if (j == 0 && i > 0 && i <= limit) {
                val += 1;
            }
            dp0[i][j] = static_cast<int>(val % MOD);
        }
        long long win0 = 0;
        for (int j = 0; j <= one; ++j) {
            if (j > 0) {
                win0 += dp0[i][j - 1];
                if (win0 >= MOD) win0 -= MOD;
                int removeIdx = j - 1 - limit;
                if (removeIdx >= 0) {
                    win0 -= dp0[i][removeIdx];
                    if (win0 < 0) win0 += MOD;
                }
            }
            long long val = 0;
            if (j > 0) val = win0;
            if (i == 0 && j > 0 && j <= limit) {
                val += 1;
            }
            dp1[i][j] = static_cast<int>(val % MOD);
        }
    }
    long long result = dp0[zero][one] + dp1[zero][one];
    if (result >= MOD) result -= MOD;
    return result;
}

