std::size_t minLengthAnagramConcat(const std::string& s) {
    std::size_t n = s.size();
    if (n == 0) return 0;
    for (std::size_t L = 1; L <= n; ++L) {
        if (n % L != 0) continue;
        std::size_t blocks = n / L;
        std::array<int, 26> baseFreq{};
        for (std::size_t i = 0; i < L; ++i) ++baseFreq[s[i] - 'a'];
        bool ok = true;
        for (std::size_t b = 1; b < blocks && ok; ++b) {
            std::array<int, 26> f{};
            for (std::size_t i = 0; i < L; ++i) ++f[s[b * L + i] - 'a'];
            if (f != baseFreq) ok = false;
        }
        if (ok) return L;
    }
    return n;
}

