long long findMinimumX(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    int n = static_cast<int>(nums1.size());
    std::vector<long long> a(n), b(n - 2);
    for (int i = 0; i < n; ++i) a[i] = nums1[i];
    for (int i = 0; i < n - 2; ++i) b[i] = nums2[i];
    std::sort(a.begin(), a.end());
    std::sort(b.begin(), b.end());
    long long best = LLONG_MAX;
    for (int start = 0; start <= 2 && start < n; ++start) {
        long long x = b[0] - a[start];
        int i = 0, j = 0, removed = 0;
        while (i < n && j < n - 2) {
            if (a[i] + x == b[j]) {
                ++i;
                ++j;
            } else {
                ++i;
                ++removed;
                if (removed > 2) break;
            }
        }
        if (removed > 2) continue;
        removed += (n - i);
        if (removed == 2 && j == n - 2) {
            if (x < best) best = x;
        }
    }
    return best;
}

