int medianUniqueness(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    long long total = 1LL * n * (n + 1) / 2;
    long long k = (total + 1) / 2;

    std::vector<int> comp = nums;
    std::sort(comp.begin(), comp.end());
    comp.erase(std::unique(comp.begin(), comp.end()), comp.end());
    int m = static_cast<int>(comp.size());

    std::vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        a[i] = static_cast<int>(std::lower_bound(comp.begin(), comp.end(), nums[i]) - comp.begin());
    }

    auto countAtMost = [&](int limit) -> long long {
        std::vector<int> freq(m, 0);
        int distinct = 0;
        int left = 0;
        long long cnt = 0;
        for (int right = 0; right < n; ++right) {
            if (freq[a[right]]++ == 0) ++distinct;
            while (distinct > limit) {
                if (--freq[a[left]] == 0) --distinct;
                ++left;
            }
            cnt += right - left + 1;
        }
        return cnt;
    };

    int low = 1, high = n;
    while (low < high) {
        int mid = (low + high) / 2;
        if (countAtMost(mid) >= k) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

