bool isValidWord(const std::string& word) {
    if (word.size() < 3) {
        return false;
    }
    bool hasVowel = false;
    bool hasDigit = false;
    for (char ch : word) {
        unsigned char uch = static_cast<unsigned char>(ch);
        if (!std::isalpha(uch) && !std::isdigit(uch)) {
            return false;
        }
        if (!hasVowel) {
            switch (ch) {
                case 'a': case 'e': case 'i': case 'o': case 'u':
                case 'A': case 'E': case 'I': case 'O': case 'U':
                    hasVowel = true;
                    break;
                default:
                    break;
            }
        }
        if (!hasDigit && std::isdigit(uch)) {
            hasDigit = true;
        }
    }
    return hasVowel && hasDigit;
}

#include <bits/stdc++.h>

static std::pair<unsigned long long, unsigned long long> countBitsAndPosSum(unsigned long long N) {
    unsigned long long totalBits = 0, totalPos = 0;
    for (int i = 0; i < 63; ++i) {
        unsigned long long bitVal = 1ULL << i;
        if (bitVal > N) break;
        unsigned long long block = bitVal << 1;
        unsigned long long full = (N + 1) / block;
        unsigned long long cnt = full * bitVal;
        unsigned long long rem = (N + 1) % block;
        if (rem > bitVal) cnt += rem - bitVal;
        totalBits += cnt;
        totalPos += cnt * static_cast<unsigned long long>(i);
    }
    return {totalBits, totalPos};
}

static unsigned long long prefixExponent(unsigned long long t) {
    if (t == 0) return 0;
    unsigned long long low = 1, high = t;
    while (low < high) {
        unsigned long long mid = (low + high) >> 1;
        unsigned long long bits = countBitsAndPosSum(mid).first;
        if (bits >= t) high = mid;
        else low = mid + 1;
    }
    unsigned long long N = low;
    auto prev = countBitsAndPosSum(N - 1);
    unsigned long long prevCount = prev.first;
    unsigned long long prevSumPos = prev.second;
    unsigned long long remaining = t - prevCount;
    unsigned long long add = 0;
    for (int i = 0; remaining > 0; ++i) {
        if (N >> i & 1ULL) {
            add += static_cast<unsigned long long>(i);
            --remaining;
        }
    }
    return prevSumPos + add;
}

static long long modPow(long long base, unsigned long long exp, long long mod) {
    if (mod == 1) return 0;
    long long result = 1 % mod;
    long long b = base % mod;
    while (exp) {
        if (exp & 1ULL) result = (result * b) % mod;
        b = (b * b) % mod;
        exp >>= 1ULL;
    }
    return result;
}

std::vector<int> productQueries(std::vector<std::vector<long long>>& queries) {
    std::vector<int> ans;
    ans.reserve(queries.size());
    for (const auto& q : queries) {
        unsigned long long from = static_cast<unsigned long long>(q[0]);
        unsigned long long to = static_cast<unsigned long long>(q[1]);
        long long mod = q[2];
        unsigned long long exp = prefixExponent(to + 1) - prefixExponent(from);
        ans.push_back(static_cast<int>(modPow(2, exp, mod)));
    }
    return ans;
}

