const long long MOD = 1000000007LL;

long long minimumCost(const std::vector<int>& nums, long long cost1, long long cost2) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;
    long long minNum = *std::min_element(nums.begin(), nums.end());
    long long maxNum = *std::max_element(nums.begin(), nums.end());
    long long summ = 0;
    for (int v : nums) summ += v;

    if (cost1 * 2 <= cost2 || n < 3) {
        long long totalGap = maxNum * n - summ;
        return (cost1 % MOD * (totalGap % MOD)) % MOD;
    }
    auto getMinCost = [&](long long target) -> long long {
        long long maxGap = target - minNum;
        long long totalGap = target * n - summ;
        long long pairs = std::min(totalGap / 2, totalGap - maxGap);
        return cost1 * (totalGap - 2 * pairs) + cost2 * pairs;
    };
    long long best = std::numeric_limits<long long>::max();
    for (long long target = maxNum; target < 2 * maxNum; ++target) {
        long long c = getMinCost(target);
        if (c < best) best = c;
    }
    return best % MOD;
}

