long long maxEnergy(const std::vector<int>& energy, int k) {
    int n = static_cast<int>(energy.size());
    if (n == 0) return 0;
    if (k <= 0) {
        long long sum = 0;
        for (int v : energy) sum += v;
        return sum;
    }
    std::vector<long long> buf(k, 0);
    long long best = LLONG_MIN;
    for (int i = n - 1; i >= 0; --i) {
        long long cur = static_cast<long long>(energy[i]);
        if (i + k < n) cur += buf[(i + k) % k];
        buf[i % k] = cur;
        if (cur > best) best = cur;
    }
    return best;
}

#include <bits/stdc++.h>

std::vector<int> minCostPermutation(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    int fullMask = (1 << n) - 1;
    const long long INF = LLONG_MAX / 4;

    std::vector<long long> dp((1 << n) * n, INF);
    std::vector<int> prev((1 << n) * n, -1);
    auto idx = [&](int mask, int last) { return mask * n + last; };

    dp[idx(1 << 0, 0)] = 0;

    for (int mask = 0; mask <= fullMask; ++mask) {
        if ((mask & 1) == 0) continue;
        for (int last = 0; last < n; ++last) {
            if ((mask & (1 << last)) == 0) continue;
            long long cur = dp[idx(mask, last)];
            if (cur == INF) continue;
            for (int nxt = 0; nxt < n; ++nxt) {
                if (mask & (1 << nxt)) continue;
                int nmask = mask | (1 << nxt);
                long long nd = cur + std::llabs(static_cast<long long>(last) - static_cast<long long>(nums[nxt]));
                if (nd < dp[idx(nmask, nxt)]) {
                    dp[idx(nmask, nxt)] = nd;
                    prev[idx(nmask, nxt)] = last;
                }
            }
        }
    }

    long long bestTotal = INF;
    int bestLast = -1;
    for (int last = 0; last < n; ++last) {
        long long cur = dp[idx(fullMask, last)];
        if (cur == INF) continue;
        long long total = cur + std::llabs(static_cast<long long>(last) - static_cast<long long>(nums[0]));
        if (total < bestTotal) {
            bestTotal = total;
            bestLast = last;
        }
    }

    std::vector<int> perm;
    int mask = fullMask;
    int last = bestLast;
    while (mask != (1 << 0)) {
        perm.push_back(last);
        int p = prev[idx(mask, last)];
        mask ^= (1 << last);
        last = p;
    }
    perm.push_back(0);
    std::reverse(perm.begin(), perm.end());
    return perm;
}

