int maxPointsInsideSquare(const std::vector<std::pair<long long, long long>>& points, const std::vector<std::string>& s) {
    size_t n = points.size();
    std::vector<std::pair<long long, size_t>> arr;
    arr.reserve(n);
    for (size_t i = 0; i < n; ++i) {
        long long d = std::max(std::llabs(points[i].first), std::llabs(points[i].second));
        arr.emplace_back(d, i);
    }
    std::sort(arr.begin(), arr.end(),
              [](const std::pair<long long, size_t>& a, const std::pair<long long, size_t>& b) {
                  return a.first < b.first;
              });
    std::unordered_set<std::string> seen;
    int count = 0;
    size_t i = 0;
    while (i < n) {
        size_t j = i;
        while (j < n && arr[j].first == arr[i].first) ++j;
        std::unordered_set<std::string> group;
        for (size_t k = i; k < j; ++k) {
            std::string tag = s[arr[k].second];
            if (seen.find(tag) != seen.end() || group.find(tag) != group.end()) {
                return count;
            }
            group.insert(tag);
        }
        for (const auto& tag : group) {
            seen.insert(tag);
        }
        count += static_cast<int>(group.size());
        i = j;
    }
    return count;
}

