long long sumDigitDifferences(const std::vector<long long>& nums) {
    long long n = static_cast<long long>(nums.size());
    if (n < 2) return 0;

    long long maxVal = *std::max_element(nums.begin(), nums.end());
    int digitCount = 0;
    do {
        ++digitCount;
        maxVal /= 10;
    } while (maxVal > 0);

    std::vector<long long> pow10(digitCount);
    pow10[0] = 1;
    for (int i = 1; i < digitCount; ++i) pow10[i] = pow10[i - 1] * 10;

    long long totalSum = 0;
    long long totalPairs = n * (n - 1) / 2;

    for (int pos = 0; pos < digitCount; ++pos) {
        long long freq[10] = {0};
        long long divisor = pow10[pos];
        for (long long v : nums) {
            int digit = static_cast<int>((v / divisor) % 10);
            ++freq[digit];
        }
        long long sameDigitPairs = 0;
        for (int d = 0; d < 10; ++d) {
            sameDigitPairs += freq[d] * (freq[d] - 1) / 2;
        }
        totalSum += totalPairs - sameDigitPairs;
    }
    return totalSum;
}

