    int n = static_cast<int>(grid.size());
    int m = static_cast<int>(grid[0].size());
    int ans = std::numeric_limits<int>::min();
    std::vector<std::vector<int>> suffixMax(n, std::vector<int>(m, 0));
    for (int i = n - 1; i >= 0; --i) {
        for (int j = m - 1; j >= 0; --j) {
            int maxFuture = std::numeric_limits<int>::min();
            if (i + 1 < n) {
                maxFuture = std::max(maxFuture, suffixMax[i + 1][j]);
            }
            if (j + 1 < m) {
                maxFuture = std::max(maxFuture, suffixMax[i][j + 1]);
            }
            if (maxFuture != std::numeric_limits<int>::min()) {
                ans = std::max(ans, maxFuture - grid[i][j]);
            }
            suffixMax[i][j] = std::max(grid[i][j], maxFuture);
        }
    }
    return ans;
}

