static long long combi(long long a, long long b) {
    if (b > a - b) b = a - b;
    long long r = 1;
    for (long long i = 0; i < b; ++i) {
        r *= (a - i);
        r /= (i + 1);
    }
    return r;
}

unsigned long long countWaysToReachK(long long k) {
    if (k < 0) return 0ULL;
    long long x = 1, y = 1, ans = 0;
    while (x > 0 && x - y <= k) {
        if (x >= k) {
            ans += combi(y, x - k);
        }
        x <<= 1;
        ++y;
    }
    return static_cast<unsigned long long>(ans);
}

