long long countGoodPairs(const std::vector<int>& nums1, const std::vector<int>& nums2, int k) {
    if (k == 0) return 0;
    std::unordered_map<int, long long> freq;
    freq.reserve(nums2.size() * 2);
    for (int b : nums2) {
        if (b != 0) ++freq[b];
    }
    long long total = 0;
    for (int a : nums1) {
        if (a % k != 0) continue;
        long long target = static_cast<long long>(a) / k;
        for (long long d = 1; d * d <= target; ++d) {
            if (target % d == 0) {
                int div1 = static_cast<int>(d);
                auto it1 = freq.find(div1);
                if (it1 != freq.end()) total += it1->second;
                long long other = target / d;
                if (other != d) {
                    int div2 = static_cast<int>(other);
                    auto it2 = freq.find(div2);
                    if (it2 != freq.end()) total += it2->second;
                }
            }
        }
    }
    return total;
}

