struct SegTree {
    int n;
    vector<int> tree;
    SegTree(int n_) : n(n_), tree(2*n_, 0) {}
    void update(int pos, int val) {
        pos += n;
        tree[pos] = val;
        pos >>= 1;
        while (pos >= 1) {
            tree[pos] = max(tree[2*pos], tree[2*pos+1]);
            pos >>= 1;
        }
    }
    int query(int l, int r) { // inclusive
        if (l > r) return 0;
        int res = 0;
        l += n; r += n+1;
        while (l < r) {
            if (l & 1) res = max(res, tree[l++]);
            if (r & 1) res = max(res, tree[--r]);
            l >>= 1; r >>= 1;
        }
        return res;
    }
};

vector<bool> getResults(vector<vector<int>>& queries) {
    const int MAXX = 50002;
    SegTree seg(MAXX+1);
    set<int> obstacles = {0};
    vector<bool> ans;
    for (auto& q : queries) {
        if (q[0] == 1) {
            int x = q[1];
            auto it = obstacles.upper_bound(x); // first > x (successor, if any)
            auto itL = prev(it); // predecessor (largest <= x), guaranteed to exist since 0 is always present
            int L = *itL;
            if (it != obstacles.end()) {
                int R = *it;
                seg.update(R, R-x);
            }
            seg.update(x, x-L);
            obstacles.insert(x);
        } else {
            int x = q[1], sz = q[2];
            auto it = obstacles.upper_bound(x); // first > x
            int last = *prev(it);
            int trailing = x - last;
            int best = max(seg.query(0, x), trailing);
            ans.push_back(best >= sz);
        }
    }
    return ans;
}

