std::string stringCompression(const std::string& word) {
    std::string comp;
    comp.reserve(word.size() * 2);
    std::size_t i = 0, n = word.size();
    while (i < n) {
        char ch = word[i];
        std::size_t count = 0;
        while (i < n && word[i] == ch) {
            ++count;
            ++i;
        }
        while (count > 0) {
            std::size_t chunk = count > 9 ? 9 : count;
            comp.push_back('0' + static_cast<char>(chunk));
            comp.push_back(ch);
            count -= chunk;
        }
    }
    return comp;
}

