int count_days_without_meetings(int days, std::vector<std::vector<int>> meetings) {
    if (meetings.empty()) {
        return days;
    }
    std::sort(meetings.begin(), meetings.end(),
              [](const std::vector<int>& a, const std::vector<int>& b) {
                  return a[0] < b[0];
              });
    long long covered = 0;
    int cur_start = meetings[0][0];
    int cur_end = meetings[0][1];
    for (size_t i = 1; i < meetings.size(); ++i) {
        int s = meetings[i][0];
        int e = meetings[i][1];
        if (s <= cur_end) {
            if (e > cur_end) cur_end = e;
        } else {
            covered += static_cast<long long>(cur_end) - cur_start + 1;
            cur_start = s;
            cur_end = e;
        }
    }
    covered += static_cast<long long>(cur_end) - cur_start + 1;
    long long free_days = static_cast<long long>(days) - covered;
    return free_days > 0 ? static_cast<int>(free_days) : 0;
}

#include <bits/stdc++.h>
using namespace std;

int maximumSumQueries(vector<int> nums, vector<vector<int>> queries) {
    const long long MOD = 1000000007LL;
    const long long NEG = -(1LL << 60);
    struct Mat {
        long long v[2][2];
    };
    auto makeLeaf = [&](long long a) -> Mat {
        Mat m;
        m.v[0][0] = 0;
        m.v[0][1] = 0;
        m.v[1][0] = a;
        m.v[1][1] = NEG;
        return m;
    };
    auto identity = [&]() -> Mat {
        Mat m;
        m.v[0][0] = 0;
        m.v[0][1] = NEG;
        m.v[1][0] = NEG;
        m.v[1][1] = 0;
        return m;
    };
    auto mul = [&](const Mat& A, const Mat& B) -> Mat {
        Mat C;
        for (int i = 0; i < 2; ++i) {
            for (int j = 0; j < 2; ++j) {
                long long best = NEG;
                for (int k = 0; k < 2; ++k) {
                    if (A.v[i][k] == NEG || B.v[k][j] == NEG) continue;
                    long long cand = A.v[i][k] + B.v[k][j];
                    if (cand > best) best = cand;
                }
                C.v[i][j] = best;
            }
        }
        return C;
    };
    int n = nums.size();
    int size = 1;
    while (size < n) size <<= 1;
    vector<Mat> seg(2 * size);
    for (int i = 0; i < size; ++i) {
        seg[size + i] = (i < n) ? makeLeaf(nums[i]) : identity();
    }
    for (int i = size - 1; i > 0; --i) {
        seg[i] = mul(seg[i << 1 | 1], seg[i << 1]);
    }
    long long total = 0;
    for (const auto& q : queries) {
        int pos = q[0];
        int x = q[1];
        int idx = pos + size;
        seg[idx] = makeLeaf(x);
        for (idx >>= 1; idx > 0; idx >>= 1) {
            seg[idx] = mul(seg[idx << 1 | 1], seg[idx << 1]);
        }
        const Mat& root = seg[1];
        long long ans = max(root.v[0][0], root.v[1][0]);
        total = (total + ans) % MOD;
    }
    return static_cast<int>(total);
}

