long long countGoodPairs(const std::vector<int>& nums1, const std::vector<int>& nums2, int k) {
    if (nums1.empty() || nums2.empty()) return 0;
    int maxV = *std::max_element(nums1.begin(), nums1.end());
    std::vector<int> freq(maxV + 1, 0);
    for (int v : nums1) ++freq[v];
    std::vector<int> cnt(maxV + 1, 0);
    for (int d = 1; d <= maxV; ++d) {
        for (int mult = d; mult <= maxV; mult += d) {
            cnt[d] += freq[mult];
        }
    }
    long long ans = 0;
    for (int b : nums2) {
        long long target = 1LL * b * k;
        if (target <= maxV) ans += cnt[static_cast<int>(target)];
    }
    return ans;
}

