int maximumLength(const std::vector<int>& nums, int k) {
    std::vector<std::unordered_map<int, int>> dp(k + 1);
    std::vector<int> best(k + 1, 0);
    for (int x : nums) {
        std::vector<int> prevBest = best;
        for (int t = 0; t <= k; ++t) {
            int extend = 0;
            auto it = dp[t].find(x);
            if (it != dp[t].end()) extend = it->second;
            int cand1 = extend + 1;
            int cand2 = -1;
            if (t > 0) cand2 = prevBest[t - 1] + 1;
            int newVal = cand1 > cand2 ? cand1 : cand2;
            if (newVal > extend) {
                dp[t][x] = newVal;
                if (newVal > best[t]) best[t] = newVal;
            }
        }
    }
    int ans = 0;
    for (int t = 0; t <= k; ++t) ans = std::max(ans, best[t]);
    return ans;
}

