int minAbsDifference(const std::vector<int>& nums, int k) {
    if (nums.empty()) return 0;
    long long best = LLONG_MAX;
    std::vector<int> cur;
    cur.reserve(32);
    for (int x : nums) {
        std::vector<int> nxt;
        nxt.reserve(cur.size() + 1);
        nxt.push_back(x);
        for (int v : cur) {
            nxt.push_back(v | x);
        }
        std::sort(nxt.begin(), nxt.end());
        nxt.erase(std::unique(nxt.begin(), nxt.end()), nxt.end());
        cur.swap(nxt);
        for (int v : cur) {
            long long diff = std::llabs((long long)k - v);
            if (diff < best) {
                best = diff;
                if (best == 0) return 0;
            }
        }
    }
    return static_cast<int>(best);
}

class Solution {
public:
    int valueAfterKSeconds(int n, int k) {
        const long long MOD = 1e9+7;
        // Pascal's-triangle argument: a[n-1] after k seconds == C(n+k-1, n-1) mod MOD
        int top = n + k - 1;
        long long num = 1;
        for (int i = 0; i < n-1; i++) num = num * ((top - i) % MOD) % MOD;
        long long den = 1;
        for (int i = 1; i <= n-1; i++) den = den * i % MOD;
        return (int)(num * power(den, MOD-2, MOD) % MOD);
    }
private:
    long long power(long long b, long long e, long long m) {
        long long r = 1; b %= m;
        while (e > 0) { if (e&1) r = r*b%m; b=b*b%m; e>>=1; }
        return r;
    }
};

