int maxLengthGoodSubsequence(const vector<int>& nums, int k) {
    unordered_map<int, vector<int>> best;
    vector<int> global(k + 1, 0);
    for (int x : nums) {
        auto &vec = best[x];
        if (vec.empty()) vec.assign(k + 1, 0);
        vector<int> oldVec = vec;
        vec[0] = max(vec[0], 1);
        for (int c = 0; c <= k; ++c) {
            if (oldVec[c] > 0) vec[c] = max(vec[c], oldVec[c] + 1);
            if (c > 0 && global[c - 1] > 0) vec[c] = max(vec[c], global[c - 1] + 1);
        }
        for (int c = 0; c <= k; ++c) {
            global[c] = max(global[c], vec[c]);
        }
    }
    int ans = 0;
    for (int c = 0; c <= k; ++c) ans = max(ans, global[c]);
    return ans;
}

