int minKBitFlips(std::vector<int>& nums) {
    const int k = 3; // fixed window size for "...Equal to One I"
    int n = static_cast<int>(nums.size());
    std::vector<int> diff(n, 0);
    int curFlip = 0;
    int ans = 0;
    for (int i = 0; i < n; ++i) {
        if (i >= k) {
            curFlip -= diff[i - k];
        }
        int currentBit = (nums[i] + curFlip) % 2;
        if (currentBit == 0) {
            if (i + k > n) {
                return -1;
            }
            diff[i] = 1;
            ++curFlip;
            ++ans;
        }
    }
    return ans;
}

#include <bits/stdc++.h>
int countPermutations(int n, std::vector<std::vector<int>>& requirements) {
    const int MOD = 1000000007;
    std::vector<int> reqCnt(n, -1);
    int maxCnt = 0;
    for (const auto& r : requirements) {
        int endi = r[0];
        int cnti = r[1];
        reqCnt[endi] = cnti;
        if (cnti > maxCnt) maxCnt = cnti;
    }
    std::vector<int> prev(maxCnt + 1, 0), cur(maxCnt + 1, 0);
    prev[0] = 1;
    for (int i = 1; i <= n; ++i) {
        std::vector<int> pref(maxCnt + 1, 0);
        pref[0] = prev[0];
        for (int k = 1; k <= maxCnt; ++k) {
            int v = pref[k - 1] + prev[k];
            if (v >= MOD) v -= MOD;
            pref[k] = v;
        }
        for (int k = 0; k <= maxCnt; ++k) {
            int left = k - (i - 1);
            long long val = pref[k];
            if (left > 0) {
                val -= pref[left - 1];
                if (val < 0) val += MOD;
            }
            cur[k] = static_cast<int>(val);
        }
        int endIdx = i - 1;
        if (reqCnt[endIdx] != -1) {
            int need = reqCnt[endIdx];
            if (need > endIdx * (endIdx + 1) / 2) {
                return 0;
            }
            for (int k = 0; k <= maxCnt; ++k) {
                if (k != need) cur[k] = 0;
            }
        }
        std::swap(prev, cur);
        std::fill(cur.begin(), cur.end(), 0);
    }
    int finalNeed = reqCnt[n - 1];
    if (finalNeed == -1) return 0;
    return prev[finalNeed];
}

