long long minAreaThreeRectangles(const std::vector<std::vector<int>>& grid) {
    int R = static_cast<int>(grid.size());
    int C = static_cast<int>(grid[0].size());

    std::vector<std::vector<int>> rowPref(R, std::vector<int>(C + 1, 0));
    std::vector<std::vector<int>> colPref(C, std::vector<int>(R + 1, 0));
    bool anyOne = false;
    for (int i = 0; i < R; ++i) {
        for (int j = 0; j < C; ++j) {
            int v = grid[i][j];
            if (v == 1) anyOne = true;
            rowPref[i][j + 1] = rowPref[i][j] + v;
            colPref[j][i + 1] = colPref[j][i] + v;
        }
    }
    if (!anyOne) return 0;

    auto box = [&](int r1, int r2, int c1, int c2) -> long long {
        int minR = -1, maxR = -1, minC = -1, maxC = -1;
        for (int i = r1; i <= r2; ++i) {
            if (rowPref[i][c2 + 1] - rowPref[i][c1] > 0) {
                minR = i;
                break;
            }
        }
        for (int i = r2; i >= r1; --i) {
            if (rowPref[i][c2 + 1] - rowPref[i][c1] > 0) {
                maxR = i;
                break;
            }
        }
        for (int j = c1; j <= c2; ++j) {
            if (colPref[j][r2 + 1] - colPref[j][r1] > 0) {
                minC = j;
                break;
            }
        }
        for (int j = c2; j >= c1; --j) {
            if (colPref[j][r2 + 1] - colPref[j][r1] > 0) {
                maxC = j;
                break;
            }
        }
        if (minR == -1) return -1;
        long long area = static_cast<long long>(maxR - minR + 1) *
                         static_cast<long long>(maxC - minC + 1);
        return area;
    };

    long long ans = LLONG_MAX;

    for (int i = 0; i < R - 2; ++i) {
        for (int j = i + 1; j < R - 1; ++j) {
            long long a1 = box(0, i, 0, C - 1);
            long long a2 = box(i + 1, j, 0, C - 1);
            long long a3 = box(j + 1, R - 1, 0, C - 1);
            if (a1 != -1 && a2 != -1 && a3 != -1) {
                long long sum = a1 + a2 + a3;
                if (sum < ans) ans = sum;
            }
        }
    }

    for (int i = 0; i < C - 2; ++i) {
        for (int j = i + 1; j < C - 1; ++j) {
            long long a1 = box(0, R - 1, 0, i);
            long long a2 = box(0, R - 1, i + 1, j);
            long long a3 = box(0, R - 1, j + 1, C - 1);
            if (a1 != -1 && a2 != -1 && a3 != -1) {
                long long sum = a1 + a2 + a3;
                if (sum < ans) ans = sum;
            }
        }
    }

    for (int r = 0; r < R - 1; ++r) {
        for (int c = 0; c < C - 1; ++c) {
            long long tl = box(0, r, 0, c);
            long long tr = box(0, r, c + 1, C - 1);
            long long bl = box(r + 1, R - 1, 0, c);
            long long br = box(r + 1, R - 1, c + 1, C - 1);
            bool has[4] = { tl != -1, tr != -1, bl != -1, br != -1 };
            int cnt = (has[0] ? 1 : 0) + (has[1] ? 1 : 0) + (has[2] ? 1 : 0) + (has[3] ? 1 : 0);
            if (cnt == 3) {
                long long sum = (has[0] ? tl : 0) + (has[1] ? tr : 0) + (has[2] ? bl : 0) + (has[3] ? br : 0);
                if (sum < ans) ans = sum;
            }
        }
    }

    return ans;
}

