        for (int c = 0; c < cols; ++c) {
            if (row[c] == 1) {
                if (r < top) top = r;
                if (r > bottom) bottom = r;
                if (c < left) left = c;
                if (c > right) right = c;
            }
        }
    }
    if (bottom == -1) return 0;
    return (bottom - top + 1) * (right - left + 1);
}

