int maxValidSubsequenceLength(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    int count = 1;
    for (size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] != nums[i - 1]) ++count;
    }
    return count;
}

#include <bits/stdc++.h>

int maxLength(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;
    std::vector<int> vals = nums;
    std::sort(vals.begin(), vals.end());
    vals.erase(std::unique(vals.begin(), vals.end()), vals.end());
    int m = static_cast<int>(vals.size());
    int size = 1;
    while (size < m) size <<= 1;
    std::vector<int> seg(2 * size, 0);
    auto query = [&](int l, int r) {
        int res = 0;
        l += size;
        r += size;
        while (l <= r) {
            if (l & 1) res = std::max(res, seg[l++]);
            if (!(r & 1)) res = std::max(res, seg[r--]);
            l >>= 1;
            r >>= 1;
        }
        return res;
    };
    auto update = [&](int pos, int val) {
        pos += size;
        seg[pos] = std::max(seg[pos], val);
        for (pos >>= 1; pos; pos >>= 1) {
            seg[pos] = std::max(seg[pos << 1], seg[(pos << 1) | 1]);
        }
    };
    int answer = 0;
    for (int i = 0; i < n; ++i) {
        int leftVal = nums[i] - k;
        int l = std::lower_bound(vals.begin(), vals.end(), leftVal) - vals.begin();
        int r = std::lower_bound(vals.begin(), vals.end(), nums[i]) - vals.begin() - 1;
        int best = 0;
        if (l <= r) best = query(l, r);
        int cur = best + 1;
        int idx = std::lower_bound(vals.begin(), vals.end(), nums[i]) - vals.begin();
        update(idx, cur);
        answer = std::max(answer, cur);
    }
    return answer;
}

