struct DiaRad {
    int diameter;
    int radius;
};

static DiaRad getDiameterAndRadius(const std::vector<std::vector<int>>& edges) {
    int n = static_cast<int>(edges.size()) + 1;
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    auto bfs = [&](int start) {
        std::vector<int> dist(n, -1);
        std::queue<int> q;
        q.push(start);
        dist[start] = 0;
        int far = start;
        while (!q.empty()) {
            int cur = q.front();
            q.pop();
            for (int nb : adj[cur]) {
                if (dist[nb] == -1) {
                    dist[nb] = dist[cur] + 1;
                    q.push(nb);
                    if (dist[nb] > dist[far]) far = nb;
                }
            }
        }
        return std::make_pair(far, std::move(dist));
    };

    auto first = bfs(0);
    auto second = bfs(first.first);
    int diameter = second.second[second.first];
    int radius = (diameter + 1) / 2;
    return {diameter, radius};
}

int findMinDiameter(const std::vector<std::vector<int>>& edges1, const std::vector<std::vector<int>>& edges2) {
    DiaRad t1 = getDiameterAndRadius(edges1);
    DiaRad t2 = getDiameterAndRadius(edges2);
    int candidate = t1.radius + 1 + t2.radius;
    return std::max({t1.diameter, t2.diameter, candidate});
}

#include <bits/stdc++.h>

long long countSubarrays(const std::vector<int>& nums, int k) {
    long long answer = 0;
    std::vector<std::pair<int, long long>> prev;
    prev.reserve(32);
    std::vector<std::pair<int, long long>> cur;
    cur.reserve(32);
    for (int x : nums) {
        cur.clear();
        cur.emplace_back(x, 1);
        for (const auto& p : prev) {
            int newVal = p.first & x;
            if (newVal == cur.back().first) {
                cur.back().second += p.second;
            } else {
                cur.emplace_back(newVal, p.second);
            }
        }
        for (const auto& p : cur) {
            if (p.first == k) {
                answer += p.second;
            }
        }
        prev.swap(cur);
    }
    return answer;
}

