static void dfsHelper(int n, int pos, bool prevZero, std::string& cur, std::vector<std::string>& result) {
    if (pos == n) {
        result.push_back(cur);
        return;
    }
    if (!prevZero) {
        cur.push_back('0');
        dfsHelper(n, pos + 1, true, cur, result);
        cur.pop_back();
    }
    cur.push_back('1');
    dfsHelper(n, pos + 1, false, cur, result);
    cur.pop_back();
}

std::vector<std::string> generateBinaryStrings(int n) {
    std::vector<std::string> result;
    if (n < 0) {
        return result;
    }
    auto fib = [&](int k) {
        std::size_t a = 0, b = 1;
        for (int i = 0; i < k; ++i) {
            std::size_t c = a + b;
            a = b;
            b = c;
        }
        return a;
    };
    result.reserve(fib(n + 2));
    std::string cur;
    cur.reserve(n);
    dfsHelper(n, 0, false, cur, result);
    return result;
}

class Solution {
public:
    int numberOfSubmatrices(vector<vector<char>>& grid) {
        int m = grid.size(), n = grid[0].size();
        // rowX[j]/rowY[j]: running count of X/Y in the submatrix from (0,0) to (current row, j)
        vector<int> rowX(n, 0), rowY(n, 0);
        int ans = 0;
        for (int i = 0; i < m; i++) {
            int cx = 0, cy = 0; // running count within THIS row up to column j
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'X') cx++;
                else if (grid[i][j] == 'Y') cy++;
                rowX[j] += cx;
                rowY[j] += cy;
                if (rowX[j] > 0 && rowX[j] == rowY[j]) ans++;
            }
        }
        return ans;
    }
};

