int count_alternating_groups(const std::vector<int>& colors) {
    std::size_t n = colors.size();
    if (n < 3) return 0;
    int groups = 0;
    for (std::size_t i = 0; i < n; ++i) {
        std::size_t left = (i + n - 1) % n;
        std::size_t right = (i + 1) % n;
        if (colors[i] != colors[left] && colors[left] == colors[right]) {
            ++groups;
        }
    }
    return groups;
}

#include <bits/stdc++.h>
#include <vector>

int numberOfAlternatingGroups(std::vector<int>& colors, int k) {
    int n = static_cast<int>(colors.size());
    int need = k - 1;
    auto diffAt = [&](int idx) -> int {
        int i = idx % n;
        int j = (i + 1) % n;
        return colors[i] != colors[j];
    };
    int sum = 0;
    for (int i = 0; i < need; ++i) sum += diffAt(i);
    int ans = (sum == need) ? 1 : 0;
    for (int start = 1; start < n; ++start) {
        sum -= diffAt(start - 1);
        sum += diffAt(start + need - 1);
        if (sum == need) ++ans;
    }
    return ans;
}

