std::string find_encrypted_string(const std::string& s, int k) {
    std::size_t n = s.size();
    if (n == 0) {
        return {};
    }
    k = ((k % static_cast<int>(n)) + static_cast<int>(n)) % static_cast<int>(n);
    std::string result;
    result.reserve(n);
    result.append(s, static_cast<std::size_t>(k), n - static_cast<std::size_t>(k));
    result.append(s, 0, static_cast<std::size_t>(k));
    return result;
}

