int constructString(const std::string& target, const std::vector<std::string>& words, const std::vector<int>& costs) {
    constexpr int INF = std::numeric_limits<int>::max() / 2;
    struct Node {
        int cost;
        std::unordered_map<char, int> nxt;
        Node() : cost(INF) {}
    };
    std::vector<Node> trie(1);
    for (size_t i = 0; i < words.size(); ++i) {
        const std::string& w = words[i];
        int c = costs[i];
        int node = 0;
        for (char ch : w) {
            auto it = trie[node].nxt.find(ch);
            if (it == trie[node].nxt.end()) {
                trie[node].nxt[ch] = static_cast<int>(trie.size());
                trie.emplace_back();
                node = static_cast<int>(trie.size()) - 1;
            } else {
                node = it->second;
            }
        }
        trie[node].cost = std::min(trie[node].cost, c);
    }
    int n = static_cast<int>(target.size());
    std::vector<int> dp(n + 1, INF);
    dp[0] = 0;
    for (int i = 0; i < n; ++i) {
        if (dp[i] == INF) continue;
        int node = 0;
        for (int j = i; j < n; ++j) {
            char ch = target[j];
            auto it = trie[node].nxt.find(ch);
            if (it == trie[node].nxt.end()) break;
            node = it->second;
            if (trie[node].cost != INF) {
                int newCost = dp[i] + trie[node].cost;
                if (newCost < dp[j + 1]) dp[j + 1] = newCost;
            }
        }
    }
    return dp[n] == INF ? -1 : dp[n];
}

