long long minCost(int m, int n, std::vector<long long> horizontalCut, std::vector<long long> verticalCut) {
    std::sort(horizontalCut.begin(), horizontalCut.end(), std::greater<long long>());
    std::sort(verticalCut.begin(), verticalCut.end(), std::greater<long long>());

    std::size_t i = 0, j = 0;
    long long horizPieces = 1, vertPieces = 1;
    long long total = 0;

    while (i < horizontalCut.size() && j < verticalCut.size()) {
        if (horizontalCut[i] > verticalCut[j]) {
            total += horizontalCut[i] * vertPieces;
            ++horizPieces;
            ++i;
        } else {
            total += verticalCut[j] * horizPieces;
            ++vertPieces;
            ++j;
        }
    }

    while (i < horizontalCut.size()) {
        total += horizontalCut[i] * vertPieces;
        ++i;
    }

    while (j < verticalCut.size()) {
        total += verticalCut[j] * horizPieces;
        ++j;
    }

    return total;
}

