struct ListNode {
    int val;
    ListNode* next;
    ListNode() : val(0), next(nullptr) {}
    ListNode(int x) : val(x), next(nullptr) {}
    ListNode(int x, ListNode* nextNode) : val(x), next(nextNode) {}
};

ListNode* deleteNodes(const std::vector<int>& nums, ListNode* head) {
    std::unordered_set<int> toDelete(nums.begin(), nums.end());
    ListNode dummy(0);
    dummy.next = head;
    ListNode* prev = &dummy;
    ListNode* curr = head;
    while (curr) {
        if (toDelete.find(curr->val) != toDelete.end()) {
            ListNode* tmp = curr;
            prev->next = curr->next;
            curr = curr->next;
            delete tmp;
        } else {
            prev = curr;
            curr = curr->next;
        }
    }
    return dummy.next;
}

