int minChanges(std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    int m = n / 2;
    int maxSum = 2 * k;
    std::vector<int> diff(maxSum + 2, 0);
    std::vector<int> exact(maxSum + 2, 0);
    for (int i = 0; i < m; ++i) {
        int a = nums[i];
        int b = nums[n - 1 - i];
        int lo = std::min(a, b);
        int hi = std::max(a, b);
        int low = lo + 1;
        int high = hi + k;
        diff[low] += 1;
        diff[high + 1] -= 1;
        if (a >= 1 && a <= k && b >= 1 && b <= k) {
            ++exact[a + b];
        }
    }
    int best = INT_MAX;
    int cur = 0;
    for (int s = 0; s <= maxSum; ++s) {
        cur += diff[s];
        int changes = 2 * m - cur - exact[s];
        if (changes < best) best = changes;
    }
    return best;
}

