int number_of_bit_changes(int n, int k) {
    if ((n & k) != k) {
        return -1;
    }
    unsigned int diff = static_cast<unsigned int>(n ^ k);
    int changes = 0;
    while (diff) {
        diff &= diff - 1;
        ++changes;
    }
    return changes;
}

