long long countNotSpecial(long long l, long long r) {
    long long total = r - l + 1;
    auto floor_sqrt = [](long long x) -> long long {
        long long s = static_cast<long long>(std::sqrt(static_cast<long double>(x)));
        while ((s + 1) * (s + 1) <= x) ++s;
        while (s * s > x) --s;
        return s;
    };
    auto ceil_sqrt = [&](long long x) -> long long {
        long long s = floor_sqrt(x);
        return (s * s == x) ? s : s + 1;
    };
    long long low = ceil_sqrt(l);
    long long high = floor_sqrt(r);
    if (low > high) return total;
    std::vector<char> isPrime(high + 1, true);
    if (high >= 0) isPrime[0] = false;
    if (high >= 1) isPrime[1] = false;
    long long limit = floor_sqrt(high);
    for (long long i = 2; i <= limit; ++i) {
        if (isPrime[i]) {
            for (long long j = i * i; j <= high; j += i) {
                isPrime[j] = false;
            }
        }
    }
    long long primeSquareCount = 0;
    for (long long p = low; p <= high; ++p) {
        if (isPrime[p]) ++primeSquareCount;
    }
    return total - primeSquareCount;
}

