bool canAliceWin(const std::string& s) {
    int vowelCount = 0;
    for (char ch : s) {
        switch (ch) {
            case 'a': case 'e': case 'i': case 'o': case 'u':
                ++vowelCount;
        }
    }
    if (vowelCount == 0) {
        return false;
    }
    int aliceMoves = (static_cast<int>(s.size()) + 1) / 2;
    return vowelCount < 2 * aliceMoves;
}

