int minFlips(const std::vector<std::vector<int>>& grid) {
    if (grid.empty() || grid[0].empty()) return 0;
    const size_t m = grid.size();
    const size_t n = grid[0].size();
    int rowFlips = 0;
    for (size_t i = 0; i < m; ++i) {
        for (size_t j = 0; j < n / 2; ++j) {
            if (grid[i][j] != grid[i][n - 1 - j]) ++rowFlips;
        }
    }
    int colFlips = 0;
    for (size_t j = 0; j < n; ++j) {
        for (size_t i = 0; i < m / 2; ++i) {
            if (grid[i][j] != grid[m - 1 - i][j]) ++colFlips;
        }
    }
    return std::min(rowFlips, colFlips);
}

bool touchesSide(long long x, long long y, long long r, int side, long long xCorner, long long yCorner) {
    long long dx, dy;
    if (side == 0) { // left: x=0, y in [0,yCorner]
        dx = x;
        dy = (y < 0) ? -y : (y > yCorner ? y - yCorner : 0);
    } else if (side == 1) { // right: x=xCorner, y in [0,yCorner]
        dx = x - xCorner;
        dy = (y < 0) ? -y : (y > yCorner ? y - yCorner : 0);
    } else if (side == 2) { // bottom: y=0, x in [0,xCorner]
        dy = y;
        dx = (x < 0) ? -x : (x > xCorner ? x - xCorner : 0);
    } else { // top: y=yCorner, x in [0,xCorner]
        dy = y - yCorner;
        dx = (x < 0) ? -x : (x > xCorner ? x - xCorner : 0);
    }
    return dx*dx + dy*dy <= r*r;
}
