struct DSU {
    std::vector<int> parent;
    std::vector<int> rank;
    DSU(int n) : parent(n), rank(n, 0) {
        std::iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (rank[a] < rank[b]) std::swap(a, b);
        parent[b] = a;
        if (rank[a] == rank[b]) ++rank[a];
    }
};

bool isPathPossible(int xCorner, int yCorner, const std::vector<std::vector<int>>& circles) {
    int n = static_cast<int>(circles.size());
    int leftIdx = n;
    int rightIdx = n + 1;
    int bottomIdx = n + 2;
    int topIdx = n + 3;
    DSU dsu(n + 4);

    for (int i = 0; i < n; ++i) {
        long long x = circles[i][0];
        long long y = circles[i][1];
        long long r = circles[i][2];
        if (x - r <= 0) dsu.unite(i, leftIdx);
        if (x + r >= static_cast<long long>(xCorner)) dsu.unite(i, rightIdx);
        if (y - r <= 0) dsu.unite(i, bottomIdx);
        if (y + r >= static_cast<long long>(yCorner)) dsu.unite(i, topIdx);
    }

    auto blocked = [&](int a, int b) { return dsu.find(a) == dsu.find(b); };

    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            long long dx = circles[i][0] - circles[j][0];
            long long dy = circles[i][1] - circles[j][1];
            long long radSum = circles[i][2] + circles[j][2];
            if (dx * dx + dy * dy <= radSum * radSum) {
                dsu.unite(i, j);
            }
        }
        if (blocked(leftIdx, rightIdx) || blocked(bottomIdx, topIdx) ||
            blocked(leftIdx, bottomIdx) || blocked(rightIdx, topIdx))
            return false;
    }

    return !(blocked(leftIdx, rightIdx) || blocked(bottomIdx, topIdx) ||
             blocked(leftIdx, bottomIdx) || blocked(rightIdx, topIdx));
}

