int numberOfWinningPlayers(int n, const std::vector<std::vector<int>>& pick) {
    std::vector<int> maxCnt(n, 0);
    std::unordered_map<long long, int> cnt;
    cnt.reserve(pick.size() * 2);
    for (const auto& p : pick) {
        int x = p[0];
        int y = p[1];
        long long key = (static_cast<long long>(x) << 32) | static_cast<unsigned int>(y);
        int c = ++cnt[key];
        if (c > maxCnt[x]) maxCnt[x] = c;
    }
    int ans = 0;
    for (int i = 0; i < n; ++i) {
        if (maxCnt[i] > i) ++ans;
    }
    return ans;
}

class Solution {
public:
    vector<int> timeTaken(vector<vector<int>>& edges) {
        int n = edges.size() + 1;
        vector<vector<int>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }

        auto w = [](int destNode) { return destNode % 2 == 0 ? 2 : 1; };

        vector<long long> down(n, 0), top1(n, 0), top2(n, 0);
        vector<int> top1child(n, -1), parent(n, -1), order;
        order.reserve(n);
        {
            vector<int> stack = {0};
            vector<bool> visited(n, false);
            visited[0] = true;
            while (!stack.empty()) {
                int u = stack.back(); stack.pop_back();
                order.push_back(u);
                for (int v : adj[u]) if (!visited[v]) {
                    visited[v] = true;
                    parent[v] = u;
                    stack.push_back(v);
                }
            }
        }
        for (int idx = (int)order.size()-1; idx >= 0; idx--) {
            int u = order[idx];
            for (int v : adj[u]) {
                if (v == parent[u]) continue;
                long long cand = down[v] + w(v);
                if (cand > top1[u]) { top2[u] = top1[u]; top1[u] = cand; top1child[u] = v; }
                else if (cand > top2[u]) { top2[u] = cand; }
            }
            down[u] = top1[u];
        }

        // up[v]: best cost from v going up through its parent u to anywhere outside v's
        // subtree. The step v->u costs w(u) (destination-dependent), NOT w(v).
        vector<long long> up(n, 0);
        for (int u : order) {
            for (int v : adj[u]) {
                if (v == parent[u]) continue;
                long long best_sibling = (v == top1child[u]) ? top2[u] : top1[u];
                up[v] = w(u) + max(up[u], best_sibling);
            }
        }

        vector<int> ans(n);
        for (int i = 0; i < n; i++) ans[i] = (int) max(down[i], up[i]);
        return ans;
    }
};

