int minFlips(std::vector<std::vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();
    const long long INF = (1LL << 60);
    std::array<long long, 4> dp{}, ndp{};
    dp.fill(INF);
    dp[0] = 0;
    for (int i = 0; i <= (m - 1) / 2; ++i) {
        for (int j = 0; j <= (n - 1) / 2; ++j) {
            int sz = 0, ones = 0;
            auto add = [&](int x, int y) {
                ++sz;
                ones += grid[x][y];
            };
            add(i, j);
            if (j != n - 1 - j) add(i, n - 1 - j);
            if (i != m - 1 - i) add(m - 1 - i, j);
            if (i != m - 1 - i && j != n - 1 - j) add(m - 1 - i, n - 1 - j);
            long long cost0 = ones;
            long long cost1 = sz - ones;
            ndp.fill(INF);
            for (int mod = 0; mod < 4; ++mod) {
                if (dp[mod] == INF) continue;
                ndp[mod] = std::min(ndp[mod], dp[mod] + cost0);
                int nmod = (mod + sz) % 4;
                ndp[nmod] = std::min(ndp[nmod], dp[mod] + cost1);
            }
            dp = ndp;
        }
    }
    return static_cast<int>(dp[0]);
}

