std::vector<double> shortest_distance_after_road_addition_queries_ii(int n, const std::vector<std::pair<int, int>>& queries) {
    std::vector<std::vector<int>> adj(n);
    std::vector<int> dist(n);
    for (int i = 0; i < n; ++i) {
        dist[i] = i;
    }
    std::vector<double> results;
    results.reserve(queries.size());
    for (const auto& q : queries) {
        int l = q.first;
        int r = q.second;
        adj[l].push_back(r);
        if (dist[l] + 1 < dist[r]) {
            dist[r] = dist[l] + 1;
            std::queue<int> qv;
            qv.push(r);
            while (!qv.empty()) {
                int u = qv.front();
                qv.pop();
                int nd = dist[u] + 1;
                if (u + 1 < n && nd < dist[u + 1]) {
                    dist[u + 1] = nd;
                    qv.push(u + 1);
                }
                for (int v : adj[u]) {
                    if (nd < dist[v]) {
                        dist[v] = nd;
                        qv.push(v);
                    }
                }
            }
        }
        results.push_back(static_cast<double>(dist[n - 1]));
    }
    return results;
}

