int snakePosition(int n, const std::vector<std::string>& commands) {
    int row = 0, col = 0;
    for (const std::string& cmd : commands) {
        if (cmd[0] == 'U') {
            --row;
        } else if (cmd[0] == 'D') {
            ++row;
        } else if (cmd[0] == 'L') {
            --col;
        } else {
            ++col;
        }
    }
    return row * n + col;
}

