static int dfs(int u, int p, const vector<vector<int>>& adj, int& good) {
    int childSize = -1;
    bool isGood = true;
    int total = 1;
    for (int v : adj[u]) {
        if (v == p) continue;
        int sz = dfs(v, u, adj, good);
        if (childSize == -1) childSize = sz;
        else if (sz != childSize) isGood = false;
        total += sz;
    }
    if (isGood) ++good;
    return total;
}

