int find_smallest_missing_integer(const std::vector<int>& nums) {
    long long best_sum = 0;
    int best_len = 0;
    long long cur_sum = 0;
    int cur_len = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        if (i == 0 || nums[i] == nums[i - 1] + 1) {
            cur_sum += nums[i];
            ++cur_len;
        } else {
            if (cur_len > best_len) {
                best_len = cur_len;
                best_sum = cur_sum;
            }
            cur_sum = nums[i];
            cur_len = 1;
        }
    }
    if (cur_len > best_len) {
        best_len = cur_len;
        best_sum = cur_sum;
    }
    std::unordered_set<int> present(nums.begin(), nums.end());
    long long candidate = best_sum;
    while (present.find(static_cast<int>(candidate)) != present.end()) {
        ++candidate;
    }
    return static_cast<int>(candidate);
}

