int countMonotonicPairs(std::vector<int> nums) {
    const int MOD = 1000000007;
    const int MAXV = 50;
    int n = (int)nums.size();
    std::vector<int> dp(MAXV + 1, 0), ndp(MAXV + 1, 0), pref(MAXV + 1, 0);
    for (int v = 0; v <= nums[0] && v <= MAXV; ++v) dp[v] = 1;
    for (int i = 1; i < n; ++i) {
        int delta = nums[i] - nums[i - 1];
        if (delta < 0) delta = 0;
        pref[0] = dp[0];
        for (int v = 1; v <= MAXV; ++v) {
            pref[v] = pref[v - 1] + dp[v];
            if (pref[v] >= MOD) pref[v] -= MOD;
        }
        std::fill(ndp.begin(), ndp.end(), 0);
        for (int v = 0; v <= nums[i] && v <= MAXV; ++v) {
            int maxPrev = v - delta;
            if (maxPrev >= 0) ndp[v] = pref[maxPrev];
        }
        dp.swap(ndp);
    }
    long long ans = 0;
    for (int v = 0; v <= nums.back() && v <= MAXV; ++v) {
        ans += dp[v];
        if (ans >= MOD) ans -= MOD;
    }
    return (int)ans;
}

