vector<int> numberOfAlternatingGroups(vector<int> colors, vector<vector<int>>& queries) {
    int n = colors.size();
    vector<int> res;
    for (auto& q : queries) {
        if (q[0] == 2) { colors[q[1]] = q[2]; continue; }
        int size = q[1];
        // check if whole circle alternates
        bool allAlt = true;
        for (int i = 0; i < n; i++) if (colors[i] == colors[(i+1)%n]) { allAlt = false; break; }
        if (allAlt) { res.push_back(size <= n ? n : 0); continue; }
        // find a break point, then walk segments
        int start = -1;
        for (int i = 0; i < n; i++) if (colors[i] == colors[(i+1)%n]) { start = (i+1)%n; break; }
        long long total = 0;
        int i = 0;
        while (i < n) {
            int len = 1;
            int cur = (start + i) % n;
            while (i + len < n) {
                int a = (start + i + len - 1) % n, b = (start + i + len) % n;
                if (colors[a] == colors[b]) break;
                len++;
            }
            if (len >= size) total += len - size + 1;
            i += len;
        }
        res.push_back((int)total);
    }
    return res;
}

