long long countKConstraintSubstrings(const std::string& s, int k) {
    std::size_t n = s.size();
    std::size_t right = 0;
    int zeros = 0, ones = 0;
    long long ans = 0;
    for (std::size_t left = 0; left < n; ++left) {
        while (right < n) {
            int nz = zeros + (s[right] == '0' ? 1 : 0);
            int no = ones + (s[right] == '1' ? 1 : 0);
            if (nz <= k || no <= k) {
                zeros = nz;
                ones = no;
                ++right;
            } else {
                break;
            }
        }
        ans += static_cast<long long>(right - left);
        if (s[left] == '0') --zeros;
        else --ones;
    }
    return ans;
}

