std::vector<int> findPowerOfKSizeSubarrays(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    if (k <= 0 || k > n) return {};
    std::vector<int> result(n - k + 1);
    if (k == 1) {
        for (int i = 0; i < n; ++i) result[i] = nums[i];
        return result;
    }
    std::vector<int> inc(n, 0);
    for (int i = 1; i < n; ++i) inc[i] = (nums[i] > nums[i - 1]) ? 1 : 0;
    int cnt = 0;
    for (int i = 1; i < k; ++i) cnt += inc[i];
    for (int start = 0; start <= n - k; ++start) {
        result[start] = (cnt == k - 1) ? nums[start + k - 1] : -1;
        if (start + k < n) {
            cnt += inc[start + k];
            cnt -= inc[start + 1];
        }
    }
    return result;
}

