                    for (int row = 0; row < m; ++row) {
                        for (int t = 0; t < 8; ++t) ndp[t] = dp[t];
                        for (int mask = 0; mask < 8; ++mask) {
                            if (dp[mask] == NEG_INF) continue;
                            for (int c = 0; c < 3; ++c) {
                                if (mask & (1 << c)) continue;
                                int nmask = mask | (1 << c);
                                long long val = dp[mask] + static_cast<long long>(board[row][cols[c]]);
                                if (val > ndp[nmask]) ndp[nmask] = val;
                            }
                        }
                        for (int t = 0; t < 8; ++t) dp[t] = ndp[t];
