std::vector<int> getFinalState(std::vector<int> nums, int k, int multiplier) {
    using Pair = std::pair<long long, int>;
    struct Compare {
        bool operator()(const Pair& a, const Pair& b) const {
            if (a.first != b.first) return a.first > b.first;
            return a.second > b.second;
        }
    };
    std::priority_queue<Pair, std::vector<Pair>, Compare> pq;
    for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
        pq.emplace(static_cast<long long>(nums[i]), i);
    }
    while (k-- > 0) {
        Pair cur = pq.top();
        pq.pop();
        long long newVal = cur.first * multiplier;
        nums[cur.second] = static_cast<int>(newVal);
        pq.emplace(newVal, cur.second);
    }
    return nums;
}

