long long maxEnergyBoost(const std::vector<int>& energyDrinkA, const std::vector<int>& energyDrinkB) {
    std::size_t n = energyDrinkA.size();
    if (n == 0) return 0;
    long long a = energyDrinkA[0];
    long long b = energyDrinkB[0];
    long long s = 0;
    for (std::size_t i = 1; i < n; ++i) {
        long long prevA = a, prevB = b, prevS = s;
        a = std::max(prevA, prevS) + energyDrinkA[i];
        b = std::max(prevB, prevS) + energyDrinkB[i];
        s = std::max({prevA, prevB, prevS});
    }
    return std::max({a, b, s});
}

