std::string largestPalindrome(int n, int k) {
    if (k == 0) return "";
    int m = (n + 1) / 2;
    std::vector<int> pow10(n);
    pow10[0] = 1 % k;
    for (int i = 1; i < n; ++i) pow10[i] = (pow10[i - 1] * 10) % k;
    std::vector<int> weight(m);
    for (int i = 0; i < m; ++i) {
        int j = n - 1 - i;
        if (i == j) weight[i] = pow10[i] % k;
        else weight[i] = (pow10[i] + pow10[j]) % k;
    }
    std::vector<std::vector<char>> reachable(m + 1, std::vector<char>(k, 0));
    reachable[m][0] = 1;
    for (int i = m - 1; i >= 0; --i) {
        int digitWeight[10];
        for (int d = 0; d < 10; ++d) digitWeight[d] = (d * weight[i]) % k;
        for (int r = 0; r < k; ++r) if (reachable[i + 1][r]) {
            for (int d = 0; d < 10; ++d) {
                if (i == 0 && d == 0) continue;
                int nr = digitWeight[d] + r;
                if (nr >= k) nr -= k;
                reachable[i][nr] = 1;
            }
        }
    }
    if (!reachable[0][0]) return "";
    std::vector<char> firstHalf(m);
    int need = 0;
    for (int i = 0; i < m; ++i) {
        int digitWeight[10];
        for (int d = 0; d < 10; ++d) digitWeight[d] = (d * weight[i]) % k;
        for (int d = 9; d >= 0; --d) {
            if (i == 0 && d == 0) continue;
            int contrib = digitWeight[d];
            int suffix = need - contrib;
            suffix %= k;
            if (suffix < 0) suffix += k;
            if (reachable[i + 1][suffix]) {
                firstHalf[i] = char('0' + d);
                need = suffix;
                break;
            }
        }
    }
    std::string res;
    res.reserve(n);
    for (char c : firstHalf) res.push_back(c);
    int start = (n % 2 == 0) ? m - 1 : m - 2;
    for (int i = start; i >= 0; --i) res.push_back(firstHalf[i]);
    return res;
}

