int findKey(int num1, int num2, int num3) {
    auto trim = [](int n) {
        while (n >= 10000) n /= 10;
        return n;
    };
    num1 = trim(num1);
    num2 = trim(num2);
    num3 = trim(num3);
    int key = 0;
    int divisor = 1000;
    for (int i = 0; i < 4; ++i) {
        int d1 = (num1 / divisor) % 10;
        int d2 = (num2 / divisor) % 10;
        int d3 = (num3 / divisor) % 10;
        int minDigit = d1;
        if (d2 < minDigit) minDigit = d2;
        if (d3 < minDigit) minDigit = d3;
        key = key * 10 + minDigit;
        divisor /= 10;
    }
    return key;
}

