long long countPairs(std::vector<int> nums) {
    int n = nums.size();
    std::vector<std::string> strs(n);
    for (int i = 0; i < n; ++i) strs[i] = std::to_string(nums[i]);

    auto canSwapToEqual = [&](const std::string& s, int target) -> bool {
        std::string t = s;
        int len = t.size();
        for (int i = 0; i < len; ++i) {
            for (int j = i + 1; j < len; ++j) {
                if (t[i] == t[j]) continue;
                std::swap(t[i], t[j]);
                int val = std::stoi(t);
                if (val == target) return true;
                std::swap(t[i], t[j]);
            }
        }
        return false;
    };

    long long ans = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (nums[i] == nums[j]) {
                ++ans;
            } else if (canSwapToEqual(strs[i], nums[j]) || canSwapToEqual(strs[j], nums[i])) {
                ++ans;
            }
        }
    }
    return ans;
}

