static std::unordered_set<int> getReachable(int num) {
    std::unordered_set<int> vals;
    std::string orig = std::to_string(num);
    int L = static_cast<int>(orig.size());

    auto add = [&](const std::string &s) {
        int p = 0;
        while (p < static_cast<int>(s.size()) && s[p] == '0') ++p;
        std::string t = (p == static_cast<int>(s.size())) ? "0" : s.substr(p);
        vals.insert(std::stoi(t));
    };

    add(orig);
    for (int i = 0; i < L; ++i) {
        for (int j = i + 1; j < L; ++j) {
            std::string s = orig;
            std::swap(s[i], s[j]);
            add(s);
        }
    }
    return vals;
}

long long countPairs(const std::vector<int> &nums) {
    std::unordered_map<int, std::vector<int>> mp;
    long long ans = 0;
    int n = static_cast<int>(nums.size());
    for (int i = 0; i < n; ++i) {
        std::unordered_set<int> reachable = getReachable(nums[i]);
        std::unordered_set<int> prevIdx;
        for (int v : reachable) {
            auto it = mp.find(v);
            if (it != mp.end()) {
                for (int idx : it->second) {
                    prevIdx.insert(idx);
                }
            }
        }
        ans += static_cast<long long>(prevIdx.size());
        for (int v : reachable) {
            mp[v].push_back(i);
        }
    }
    return ans;
}

