static long long modPow(long long base, long long exp, long long mod) {
    long long result = 1 % mod;
    long long b = base % mod;
    while (exp) {
        if (exp & 1) result = (result * b) % mod;
        b = (b * b) % mod;
        exp >>= 1;
    }
    return result;
}

std::vector<int> finalArrayState(std::vector<int> nums, long long k, int multiplier) {
    const long long MOD = 1000000007LL;
    std::size_t n = nums.size();
    if (multiplier == 1 || k == 0) {
        std::vector<int> res(n);
        for (std::size_t i = 0; i < n; ++i) {
            long long v = nums[i] % MOD;
            if (v < 0) v += MOD;
            res[i] = static_cast<int>(v);
        }
        return res;
    }

    long double logM = std::log((long double)multiplier);
    std::vector<long long> cnt(n, 0);

    struct Node {
        long double key;
        std::size_t idx;
    };
    struct Compare {
        bool operator()(const Node& a, const Node& b) const {
            return a.key > b.key;
        }
    };
    std::priority_queue<Node, std::vector<Node>, Compare> pq;

    for (std::size_t i = 0; i < n; ++i) {
        long double key;
        if (nums[i] == 0) {
            key = -std::numeric_limits<long double>::infinity();
        } else {
            long long v = nums[i];
            long double mag = std::log((long double)(v >= 0 ? v : -v));
            key = (v < 0) ? -mag : mag;
        }
        pq.push({key, i});
    }

    for (long long step = 0; step < k; ++step) {
        Node cur = pq.top();
        pq.pop();
        std::size_t i = cur.idx;
        ++cnt[i];
        long double key;
        if (nums[i] == 0) {
            key = -std::numeric_limits<long double>::infinity();
        } else {
            long long v = nums[i];
            long double mag = std::log((long double)(v >= 0 ? v : -v)) + cnt[i] * logM;
            key = (v < 0) ? -mag : mag;
        }
        pq.push({key, i});
    }

    std::vector<int> result(n);
    for (std::size_t i = 0; i < n; ++i) {
        long long base = nums[i] % MOD;
        if (base < 0) base += MOD;
        long long mult = modPow(multiplier, cnt[i], MOD);
        long long val = (base * mult) % MOD;
        result[i] = static_cast<int>(val);
    }
    return result;
}

