std::vector<long long> kthNearestObstacle(const std::vector<std::pair<int, int>>& queries, int k) {
    std::vector<long long> results;
    if (k <= 0) {
        results.assign(queries.size(), -1);
        return results;
    }
    std::priority_queue<long long> maxHeap;
    for (const auto& p : queries) {
        long long dist = std::llabs(static_cast<long long>(p.first)) + std::llabs(static_cast<long long>(p.second));
        if (static_cast<int>(maxHeap.size()) < k) {
            maxHeap.push(dist);
        } else if (dist < maxHeap.top()) {
            maxHeap.pop();
            maxHeap.push(dist);
        }
        results.push_back(static_cast<int>(maxHeap.size()) == k ? maxHeap.top() : -1);
    }
    return results;
}

