int maxScore(const std::vector<std::vector<int>>& grid) {
    int rows = static_cast<int>(grid.size());
    if (rows == 0) return 0;
    int cols = static_cast<int>(grid[0].size());
    int maxMask = 1 << cols;
    const long long NEG = LLONG_MIN / 4;
    std::vector<long long> dp(maxMask, NEG), ndp(maxMask);
    dp[0] = 0;
    int fullMask = maxMask - 1;
    for (int i = 0; i < rows; ++i) {
        ndp = dp;
        for (int mask = 0; mask < maxMask; ++mask) {
            long long cur = dp[mask];
            if (cur == NEG) continue;
            int avail = (~mask) & fullMask;
            while (avail) {
                int j = __builtin_ctz(avail);
                int nmask = mask | (1 << j);
                long long cand = cur + grid[i][j];
                if (cand > ndp[nmask]) ndp[nmask] = cand;
                avail &= avail - 1;
            }
        }
        dp.swap(ndp);
    }
    long long ans = 0;
    for (int mask = 1; mask < maxMask; ++mask) {
        if (dp[mask] > ans) ans = dp[mask];
    }
    return static_cast<int>(ans);
}

class Solution {
public:
    vector<int> maximumSubarrayXor(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        // f[i][j]: XOR score of nums[i..j] (repeated adjacent-XOR reduction), via the
        // Pascal's-triangle-style recurrence f[i][j] = f[i][j-1] ^ f[i+1][j]
        vector<vector<int>> f(n, vector<int>(n, 0)), dp(n, vector<int>(n, 0));
        for (int i = 0; i < n; i++) { f[i][i] = nums[i]; dp[i][i] = nums[i]; }
        for (int length = 2; length <= n; length++) {
            for (int i = 0; i + length - 1 < n; i++) {
                int j = i + length - 1;
                f[i][j] = f[i][j - 1] ^ f[i + 1][j];
                // dp[i][j] = best XOR score of any sub-subarray within [i,j]
                dp[i][j] = max({f[i][j], dp[i][j - 1], dp[i + 1][j]});
            }
        }
        vector<int> ans;
        for (auto& q : queries) ans.push_back(dp[q[0]][q[1]]);
        return ans;
    }
};

#include <bits/stdc++.h>

static std::vector<unsigned long long> fact;
static int N, K;
static long long answer;
static int cnt_g[10];

static unsigned long long validOriginalPerms(int cnt_[10]) {
    unsigned long long total = fact[N];
    for (int c = 0; c < 10; ++c) total /= fact[cnt_[c]];
    if (cnt_[0] == 0) return total;
    unsigned long long leading = fact[N - 1];
    leading /= fact[cnt_[0] - 1];
    for (int d = 1; d < 10; ++d) leading /= fact[cnt_[d]];
    return total - leading;
}

static void backtrack(int pos, int halfLen, std::vector<int>& half, int used[10], int halfCounts[10], int oddDigit, bool& found) {
    if (found) return;
    if (pos == halfLen) {
        std::string left;
        for (int d : half) left += char('0' + d);
        std::string pal = left;
        if (N % 2 != 0) pal += char('0' + oddDigit);
        std::string rev = left;
        std::reverse(rev.begin(), rev.end());
        pal += rev;
        if (pal[0] == '0') return;
        long long val = 0;
        for (char c : pal) val = (val * 10 + (c - '0')) % K;
        if (val == 0) found = true;
        return;
    }
    for (int d = 0; d < 10; ++d) {
        if (halfCounts[d] - used[d] > 0) {
            used[d]++;
            half[pos] = d;
            backtrack(pos + 1, halfLen, half, used, halfCounts, oddDigit, found);
            used[d]--;
            if (found) return;
        }
    }
}

static void dfs(int digit, int remaining) {
    if (digit == 9) {
        cnt_g[digit] = remaining;
        int oddCnt = 0, oddDigit = -1;
        for (int i = 0; i < 10; ++i) if (cnt_g[i] % 2 == 1) { oddCnt++; oddDigit = i; }
        if ((N % 2 == 0 && oddCnt != 0) || (N % 2 == 1 && oddCnt != 1)) return;
        int halfLen = N / 2;
        int halfCounts[10];
        for (int i = 0; i < 10; ++i) halfCounts[i] = cnt_g[i] / 2;
        std::vector<int> half(halfLen);
        int used[10] = {0};
        bool found = false;
        backtrack(0, halfLen, half, used, halfCounts, oddDigit, found);
        if (found) answer += validOriginalPerms(cnt_g);
        return;
    }
    for (int c = 0; c <= remaining; ++c) { cnt_g[digit] = c; dfs(digit + 1, remaining - c); }
}

long long countGoodIntegers(int n, int k) {
    N = n; K = k; answer = 0;
    fact.assign(n + 1, 1);
    for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i;
    dfs(0, n);
    return answer;
}

#include <bits/stdc++.h>

int maxMoves(int kx, int ky, std::vector<std::vector<int>> positions) {
    const int N = 50;
    int p = static_cast<int>(positions.size());
    std::vector<std::pair<int, int>> pts(p + 1);
    for (int i = 0; i < p; ++i) {
        pts[i] = {positions[i][0], positions[i][1]};
    }
    pts[p] = {kx, ky};

    const int INF = 1e9;
    std::vector<std::vector<int>> dist(p + 1, std::vector<int>(p + 1, INF));
    int dirs[8][2] = {{2,1},{2,-1},{1,2},{1,-2},{-1,2},{-1,-2},{-2,1},{-2,-1}};

    for (int s = 0; s <= p; ++s) {
        std::vector<std::vector<int>> d(N, std::vector<int>(N, -1));
        std::queue<std::pair<int, int>> q;
        int sx = pts[s].first;
        int sy = pts[s].second;
        d[sx][sy] = 0;
        q.emplace(sx, sy);
        while (!q.empty()) {
            int x = q.front().first;
            int y = q.front().second;
            q.pop();
            for (int i = 0; i < 8; ++i) {
                int nx = x + dirs[i][0];
                int ny = y + dirs[i][1];
                if (nx >= 0 && nx < N && ny >= 0 && ny < N && d[nx][ny] == -1) {
                    d[nx][ny] = d[x][y] + 1;
                    q.emplace(nx, ny);
                }
            }
        }
        for (int t = 0; t <= p; ++t) {
            int tx = pts[t].first;
            int ty = pts[t].second;
            dist[s][t] = d[tx][ty];
        }
    }

    int total = p;
    int maxMask = 1 << p;
    std::vector<std::vector<int>> memo(maxMask, std::vector<int>(p + 1, -1));

    std::function<int(int, int)> dfs = [&](int mask, int last) -> int {
        if (mask == 0) return 0;
        int &res = memo[mask][last];
        if (res != -1) return res;
        int captured = total - __builtin_popcount(static_cast<unsigned int>(mask));
        bool aliceTurn = (captured % 2 == 0);
        if (aliceTurn) {
            int best = -INF;
            for (int i = 0; i < p; ++i) if (mask & (1 << i)) {
                int cand = dist[last][i] + dfs(mask ^ (1 << i), i);
                if (cand > best) best = cand;
            }
            res = best;
        } else {
            int best = INF;
            for (int i = 0; i < p; ++i) if (mask & (1 << i)) {
                int cand = dist[last][i] + dfs(mask ^ (1 << i), i);
                if (cand < best) best = cand;
            }
            res = best;
        }
        return res;
    };

    return dfs((1 << p) - 1, p);
}

#include <bits/stdc++.h>

int countMonotonicPairs(std::vector<int> nums) {
    const int MOD = 1000000007;
    int n = nums.size();
    int maxVal = 0;
    for (int x : nums) if (x > maxVal) maxVal = x;
    std::vector<int> dpPrev(maxVal + 1, 0), dpCurr(maxVal + 1, 0), pref(maxVal + 1, 0);
    for (int v = 0; v <= nums[0]; ++v) dpPrev[v] = 1;
    pref[0] = dpPrev[0];
    for (int v = 1; v <= maxVal; ++v) {
        pref[v] = pref[v - 1] + dpPrev[v];
        if (pref[v] >= MOD) pref[v] -= MOD;
    }
    for (int i = 1; i < n; ++i) {
        std::fill(dpCurr.begin(), dpCurr.end(), 0);
        int delta = nums[i] - nums[i - 1];
        int k = delta > 0 ? delta : 0;
        for (int v = 0; v <= nums[i]; ++v) {
            int limit = v - k;
            if (limit >= 0) {
                dpCurr[v] = pref[limit];
            }
        }
        pref[0] = dpCurr[0];
        for (int v = 1; v <= maxVal; ++v) {
            int sum = pref[v - 1] + dpCurr[v];
            if (sum >= MOD) sum -= MOD;
            pref[v] = sum;
        }
        dpPrev.swap(dpCurr);
    }
    int ans = 0;
    for (int v = 0; v <= nums.back(); ++v) {
        ans += dpPrev[v];
        if (ans >= MOD) ans -= MOD;
    }
    return ans;
}

