int maxScore(std::vector<int> start, int d) {
    int n = static_cast<int>(start.size());
    std::vector<std::int64_t> s;
    s.reserve(n);
    for (int v : start) s.push_back(v);
    std::sort(s.begin(), s.end());
    std::int64_t minL = s.front();
    std::int64_t maxR = s.back() + static_cast<std::int64_t>(d);
    std::int64_t lo = 0;
    std::int64_t hi = maxR - minL + 1;
    auto feasible = [&](std::int64_t dist) -> bool {
        std::int64_t prev = s[0];
        for (int i = 1; i < n; ++i) {
            std::int64_t need = prev + dist;
            std::int64_t left = s[i];
            std::int64_t right = s[i] + static_cast<std::int64_t>(d);
            std::int64_t pos = left > need ? left : need;
            if (pos > right) return false;
            prev = pos;
        }
        return true;
    };
    while (lo < hi) {
        std::int64_t mid = lo + (hi - lo) / 2;
        if (feasible(mid)) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return static_cast<int>(lo - 1);
}

