std::string convert_date_to_binary(const std::string& date) {
    std::istringstream ss(date);
    std::string year_str, month_str, day_str;
    std::getline(ss, year_str, '-');
    std::getline(ss, month_str, '-');
    std::getline(ss, day_str, '-');

    auto to_binary = [](int value) -> std::string {
        if (value == 0) return "0";
        std::string result;
        result.reserve(32);
        while (value > 0) {
            result.push_back((value & 1) ? '1' : '0');
            value >>= 1;
        }
        std::reverse(result.begin(), result.end());
        return result;
    };

    std::string year_bin = to_binary(std::stoi(year_str));
    std::string month_bin = to_binary(std::stoi(month_str));
    std::string day_bin = to_binary(std::stoi(day_str));

    return year_bin + "-" + month_bin + "-" + day_bin;
}

#include <bits/stdc++.h>

struct Line {
    long long m, b;
    long long eval(long long x) const { return m * x + b; }
};

struct Node {
    Line line;
    Node *l, *r;
    Node(const Line& ln) : line(ln), l(nullptr), r(nullptr) {}
};

void add_line(Line nw, Node* &node, long long l, long long r) {
    if (!node) {
        node = new Node(nw);
        return;
    }
    long long mid = (l + r) >> 1;
    bool left = nw.eval(l) > node->line.eval(l);
    bool middle = nw.eval(mid) > node->line.eval(mid);
    if (middle) std::swap(nw, node->line);
    if (l == r) return;
    if (left != middle) add_line(nw, node->l, l, mid);
    else add_line(nw, node->r, mid + 1, r);
}

long long query(Node* node, long long l, long long r, long long x) {
    if (!node) return LLONG_MIN;
    long long res = node->line.eval(x);
    if (l == r) return res;
    long long mid = (l + r) >> 1;
    if (x <= mid) return std::max(res, query(node->l, l, mid, x));
    else return std::max(res, query(node->r, mid + 1, r, x));
}

long long findMaximumScore(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n <= 1) return 0LL;
    Node* root = nullptr;
    std::vector<long long> dp(n, 0);
    add_line({static_cast<long long>(nums[0]), 0LL}, root, 0, n - 1);
    for (int j = 1; j < n; ++j) {
        long long best = query(root, 0, n - 1, j);
        dp[j] = best;
        if (j != n - 1) {
            long long m = static_cast<long long>(nums[j]);
            long long b = dp[j] - m * j;
            add_line({m, b}, root, 0, n - 1);
        }
    }
    return dp[n - 1];
}

class Solution {
public:
    int maxValue(vector<int>& nums, int k) {
        int m = 1 << 7;
        int n = nums.size();
        vector<vector<vector<bool>>> f(n + 1, vector<vector<bool>>(k + 2, vector<bool>(m, false)));
        f[0][0][0] = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= k; j++) {
                for (int x = 0; x < m; x++) {
                    if (f[i][j][x]) {
                        f[i + 1][j][x] = true;
                        f[i + 1][j + 1][x | nums[i]] = true;
                    }
                }
            }
        }
        vector<vector<vector<bool>>> g(n + 1, vector<vector<bool>>(k + 2, vector<bool>(m, false)));
        g[n][0][0] = true;
        for (int i = n; i > 0; i--) {
            for (int j = 0; j <= k; j++) {
                for (int y = 0; y < m; y++) {
                    if (g[i][j][y]) {
                        g[i - 1][j][y] = true;
                        g[i - 1][j + 1][y | nums[i - 1]] = true;
                    }
                }
            }
        }
        int ans = 0;
        for (int i = k; i <= n - k; i++) {
            for (int x = 0; x < m; x++) {
                if (f[i][k][x]) {
                    for (int y = 0; y < m; y++) {
                        if (g[i][k][y]) ans = max(ans, x ^ y);
                    }
                }
            }
        }
        return ans;
    }
};

