std::vector<int> findTwoSneaky(const std::vector<int>& nums) {
    std::unordered_map<int, int> freq;
    for (int v : nums) {
        ++freq[v];
    }
    std::vector<int> result;
    result.reserve(2);
    for (const auto& p : freq) {
        if (p.second == 2) {
            result.push_back(p.first);
            if (result.size() == 2) {
                break;
            }
        }
    }
    std::sort(result.begin(), result.end());
    return result;
}

