int longestIncreasingPath(const std::vector<std::vector<int>>& coordinates, int k) {
    struct Point { int x; int y; int idx; };
    int n = static_cast<int>(coordinates.size());
    std::vector<Point> points;
    points.reserve(n);
    std::vector<int> allY;
    allY.reserve(n);
    for (int i = 0; i < n; ++i) {
        int x = coordinates[i][0];
        int y = coordinates[i][1];
        points.push_back({x, y, i});
        allY.push_back(y);
    }
    std::sort(allY.begin(), allY.end());
    allY.erase(std::unique(allY.begin(), allY.end()), allY.end());
    int m = static_cast<int>(allY.size());
    std::unordered_map<int, int> yIdx;
    yIdx.reserve(m * 2);
    for (int i = 0; i < m; ++i) yIdx[allY[i]] = i + 1; // 1‑based

    struct BIT {
        int size;
        std::vector<int> tree;
        BIT(int n = 0) : size(n), tree(n + 1, 0) {}
        void reset(int n) { size = n; tree.assign(n + 1, 0); }
        void update(int idx, int val) {
            for (; idx <= size; idx += idx & -idx)
                if (val > tree[idx]) tree[idx] = val;
        }
        int query(int idx) const {
            int res = 0;
            for (; idx > 0; idx -= idx & -idx)
                if (tree[idx] > res) res = tree[idx];
            return res;
        }
    };

    std::vector<int> forward(n, 1), backward(n, 1);
    std::vector<Point> sorted = points;
    std::sort(sorted.begin(), sorted.end(), [](const Point& a, const Point& b) {
        if (a.x != b.x) return a.x < b.x;
        return a.y < b.y;
    });

    BIT bit(m);
    for (int i = 0; i < n; ) {
        int j = i;
        while (j < n && sorted[j].x == sorted[i].x) ++j;
        for (int t = i; t < j; ++t) {
            int yid = yIdx[sorted[t].y];
            int best = bit.query(yid - 1);
            forward[sorted[t].idx] = best + 1;
        }
        for (int t = i; t < j; ++t) {
            int yid = yIdx[sorted[t].y];
            bit.update(yid, forward[sorted[t].idx]);
        }
        i = j;
    }

    std::sort(sorted.begin(), sorted.end(), [](const Point& a, const Point& b) {
        if (a.x != b.x) return a.x > b.x;
        return a.y > b.y;
    });
    BIT bit2(m);
    for (int i = 0; i < n; ) {
        int j = i;
        while (j < n && sorted[j].x == sorted[i].x) ++j;
        for (int t = i; t < j; ++t) {
            int yid = yIdx[sorted[t].y];
            int rev = m - yid + 1;
            int best = bit2.query(rev - 1);
            backward[sorted[t].idx] = best + 1;
        }
        for (int t = i; t < j; ++t) {
            int yid = yIdx[sorted[t].y];
            int rev = m - yid + 1;
            bit2.update(rev, backward[sorted[t].idx]);
        }
        i = j;
    }

    return forward[k] + backward[k] - 1;
}

#include <bits/stdc++.h>
