#include <limits>

bool canReachSafe(const std::vector<std::vector<int>>& grid, int health) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    const int INF = std::numeric_limits<int>::max();
    std::vector<int> dist(m * n, INF);
    auto idx = [&](int x, int y) { return x * n + y; };
    std::deque<int> dq;
    dist[0] = grid[0][0];
    dq.push_front(0);
    const int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    while (!dq.empty()) {
        int cur = dq.front();
        dq.pop_front();
        int x = cur / n;
        int y = cur % n;
        if (cur == idx(m - 1, n - 1)) break;
        int curDist = dist[cur];
        for (const auto& d : dirs) {
            int nx = x + d[0];
            int ny = y + d[1];
            if (nx < 0 || ny < 0 || nx >= m || ny >= n) continue;
            int nid = idx(nx, ny);
            int ndist = curDist + grid[nx][ny];
            if (ndist < dist[nid]) {
                dist[nid] = ndist;
                if (grid[nx][ny] == 0) dq.push_front(nid);
                else dq.push_back(nid);
            }
        }
    }
    return dist[idx(m - 1, n - 1)] <= health - 1;
}

