long long maxMultiplicationScore(const std::vector<long long>& a, const std::vector<long long>& b) {
    std::array<long long, 5> dp;
    dp.fill(std::numeric_limits<long long>::min());
    dp[0] = 0;
    for (long long x : b) {
        for (int k = 4; k >= 1; --k) {
            if (dp[k - 1] != std::numeric_limits<long long>::min()) {
                long long cand = dp[k - 1] + a[k - 1] * x;
                if (cand > dp[k]) dp[k] = cand;
            }
        }
    }
    return dp[4];
}

#include <bits/stdc++.h>

long long minNumberOfSeconds(int mountainHeight, const std::vector<int>& workerTimes) {
    using int64 = long long;
    int64 H = mountainHeight;
    int64 minTime = *std::min_element(workerTimes.begin(), workerTimes.end());
    int64 high = minTime * H * (H + 1) / 2;
    int64 low = 0;

    auto unitsAt = [&](int64 T) -> int64 {
        int64 total = 0;
        for (int wt : workerTimes) {
            int64 t = wt;
            if (t > T) continue;
            long double disc = 1.0L + 8.0L * (long double)T / (long double)t;
            int64 k = (int64)((std::sqrt(disc) - 1.0L) / 2.0L);
            // adjust for possible rounding errors
            while (k > 0 && t * k * (k + 1) / 2 > T) --k;
            while (t * (k + 1) * (k + 2) / 2 <= T) ++k;
            total += k;
            if (total >= H) return total;
        }
        return total;
    };

    while (low < high) {
        int64 mid = low + (high - low) / 2;
        if (unitsAt(mid) >= H) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

#include <bits/stdc++.h>

int minValidStrings(const std::vector<std::string>& words, const std::string& target) {
    const int n = static_cast<int>(target.size());
    const int INF = std::numeric_limits<int>::max() / 2;
    std::vector<int> dp(n + 1, INF);
    dp[n] = 0;
    for (int i = n - 1; i >= 0; --i) {
        for (const std::string& w : words) {
            int pos = i;
            for (char c : w) {
                if (pos < n && c == target[pos]) ++pos;
            }
            if (pos > i && dp[pos] != INF) {
                dp[i] = std::min(dp[i], 1 + dp[pos]);
            }
        }
    }
    return dp[0] == INF ? -1 : dp[0];
}

