struct TrieNode {
    int next[26];
    TrieNode() {
        std::fill(std::begin(next), std::end(next), -1);
    }
};

int minValidStrings(const std::vector<std::string>& words, const std::string& target) {
    std::vector<TrieNode> trie(1); // root at index 0
    for (const std::string& w : words) {
        int node = 0;
        for (char ch : w) {
            int idx = ch - 'a';
            if (trie[node].next[idx] == -1) {
                trie[node].next[idx] = static_cast<int>(trie.size());
                trie.emplace_back();
            }
            node = trie[node].next[idx];
        }
    }

    int n = static_cast<int>(target.size());
    const int INF = INT_MAX / 2;
    std::vector<int> dp(n + 1, INF);
    dp[0] = 0;

    for (int i = 0; i < n; ++i) {
        if (dp[i] == INF) continue;
        int node = 0;
        for (int j = i; j < n; ++j) {
            int idx = target[j] - 'a';
            if (trie[node].next[idx] == -1) break;
            node = trie[node].next[idx];
            dp[j + 1] = std::min(dp[j + 1], dp[i] + 1);
        }
    }

    return dp[n] == INF ? -1 : dp[n];
}

