bool isSpamMessage(const std::vector<std::string>& message, const std::vector<std::string>& bannedWords) {
    std::unordered_set<std::string> bannedSet;
    bannedSet.reserve(bannedWords.size() * 2);
    for (const auto& w : bannedWords) {
        bannedSet.insert(w);
    }
    int matchCount = 0;
    for (const auto& w : message) {
        if (bannedSet.find(w) != bannedSet.end()) {
            if (++matchCount >= 2) {
                return true;
            }
        }
    }
    return false;
}

