long long minElementAfterDigitSum(const std::vector<long long>& nums) {
    if (nums.empty()) return 0;
    long long minValue = std::numeric_limits<long long>::max();
    for (long long x : nums) {
        long long digitSum = 0;
        long long t = x;
        while (t > 0) {
            digitSum += t % 10;
            t /= 10;
        }
        if (digitSum < minValue) {
            minValue = digitSum;
        }
    }
    return minValue;
}

#include <bits/stdc++.h>

long long countSubstrings(const std::string& word1, const std::string& word2) {
    int n = static_cast<int>(word1.size());
    int m = static_cast<int>(word2.size());
    if (m == 0) return static_cast<long long>(n) * (n + 1) / 2;
    if (m > n) return 0LL;
    std::array<int, 26> need{}, have{};
    need.fill(0);
    have.fill(0);
    for (char c : word2) ++need[c - 'a'];
    int missing = 0;
    for (int v : need) missing += v;
    long long ans = 0;
    int R = 0;
    for (int L = 0; L < n; ++L) {
        while (R < n && missing > 0) {
            int idx = word1[R] - 'a';
            if (have[idx] < need[idx]) --missing;
            ++have[idx];
            ++R;
        }
        if (missing == 0) {
            ans += static_cast<long long>(n - (R - 1));
        } else {
            break;
        }
        int idxL = word1[L] - 'a';
        if (have[idxL] <= need[idxL]) ++missing;
        --have[idxL];
    }
    return ans;
}

#include <bits/stdc++.h>
std::vector<int> getLexicographicallySmallestValidSequence(const std::string& word1, const std::string& word2) {
    int n = static_cast<int>(word1.size());
    int m = static_cast<int>(word2.size());
    if (m == 0) return {};
    struct State {
        bool reachable = false;
        std::vector<int> seq;
    };
    std::vector<std::array<State, 2>> dp(m + 1);
    dp[0][0].reachable = true;
    for (int idx = 0; idx < n; ++idx) {
        for (int i = m - 1; i >= 0; --i) {
            for (int err = 0; err <= 1; ++err) {
                if (!dp[i][err].reachable) continue;
                if (!dp[i][err].seq.empty() && dp[i][err].seq.back() >= idx) continue;
                int newErr = err + (word1[idx] != word2[i] ? 1 : 0);
                if (newErr > 1) continue;
                std::vector<int> cand = dp[i][err].seq;
                cand.push_back(idx);
                if (!dp[i + 1][newErr].reachable ||
                    std::lexicographical_compare(cand.begin(), cand.end(),
                                                 dp[i + 1][newErr].seq.begin(),
                                                 dp[i + 1][newErr].seq.end())) {
                    dp[i + 1][newErr].reachable = true;
                    dp[i + 1][newErr].seq = std::move(cand);
                }
            }
        }
    }
    std::vector<int> best;
    bool found = false;
    for (int err = 0; err <= 1; ++err) {
        if (!dp[m][err].reachable) continue;
        if (!found || std::lexicographical_compare(dp[m][err].seq.begin(), dp[m][err].seq.end(),
                                                    best.begin(), best.end())) {
            best = dp[m][err].seq;
            found = true;
        }
    }
    if (!found) return {};
    return best;
}

#include <bits/stdc++.h>
#include <string>
#include <array>

long long countSubstrings(const std::string& word1, const std::string& word2) {
    std::size_t n = word1.size();
    std::size_t m = word2.size();
    if (m > n) return 0;
    std::array<int, 26> need{};
    for (char c : word2) ++need[c - 'a'];
    std::array<int, 26> diff{};
    int deficit = 0;
    for (int i = 0; i < 26; ++i) {
        diff[i] = -need[i];
        if (diff[i] < 0) ++deficit;
    }
    long long ans = 0;
    std::size_t r = 0;
    for (std::size_t l = 0; l < n; ++l) {
        while (r < n && deficit > 0) {
            int idx = word1[r] - 'a';
            ++diff[idx];
            if (diff[idx] == 0) --deficit;
            ++r;
        }
        if (deficit > 0) break;
        ans += static_cast<long long>(n - r + 1);
        int idxL = word1[l] - 'a';
        --diff[idxL];
        if (diff[idxL] == -1) ++deficit;
    }
    return ans;
}

