int findFirstAlmostEqual(const std::string& s, const std::string& pattern) {
    std::size_t n = s.size();
    std::size_t m = pattern.size();
    if (m > n) return -1;
    for (std::size_t start = 0; start <= n - m; ++start) {
        int mismatches = 0;
        for (std::size_t i = 0; i < m; ++i) {
            if (s[start + i] != pattern[i]) {
                ++mismatches;
                if (mismatches > 1) break;
            }
        }
        if (mismatches <= 1) return static_cast<int>(start);
    }
    return -1;
}

