char kthCharacter(long long k) {
    if (k <= 0) return '\0';
    unsigned long long x = static_cast<unsigned long long>(k - 1);
    int cnt = __builtin_popcountll(x);
    return static_cast<char>('a' + (cnt % 26));
}

