long long max_total_height(std::vector<int> maximum_height) {
    std::sort(maximum_height.rbegin(), maximum_height.rend());
    long long prev = std::numeric_limits<long long>::max();
    long long total = 0;
    for (int h : maximum_height) {
        long long cur = std::min<long long>(h, prev - 1);
        if (cur <= 0) {
            return -1;
        }
        total += cur;
        prev = cur;
    }
    return total;
}

#include <bits/stdc++.h>
#include <vector>

char findKthChar(long long k, const std::vector<int>& operations) {
    const unsigned long long INF = 4000000000000000000ULL;
    int n = static_cast<int>(operations.size());
    std::vector<unsigned long long> len(n + 1);
    len[0] = 1;
    for (int i = 0; i < n; ++i) {
        unsigned long long cur = len[i];
        if (cur > INF / 2) len[i + 1] = INF;
        else {
            unsigned long long nxt = cur * 2;
            len[i + 1] = nxt > INF ? INF : nxt;
        }
    }
    unsigned long long pos = static_cast<unsigned long long>(k);
    int shift = 0;
    for (int i = n; i > 0; --i) {
        if (pos > len[i - 1]) {
            pos -= len[i - 1];
            if (operations[i - 1] == 1) shift = (shift + 1) % 26;
        }
    }
    return static_cast<char>('a' + shift);
}

#include <bits/stdc++.h>

long long count_vowel_consonant_substrings(const std::string& word, int k) {
    const std::string vowels = "aeiou";
    int vowelIdx[26];
    std::fill(std::begin(vowelIdx), std::end(vowelIdx), -1);
    for (int i = 0; i < 5; ++i) vowelIdx[vowels[i] - 'a'] = i;

    int n = static_cast<int>(word.size());
    std::vector<std::vector<int>> positions(n + 1);
    std::vector<int> ptr(n + 1, 0);
    positions[0].push_back(0);

    int last[5];
    for (int i = 0; i < 5; ++i) last[i] = -1;

    long long ans = 0;
    int prefC = 0; // number of consonants up to current index (inclusive)

    for (int i = 0; i < n; ++i) {
        char ch = word[i];
        int idx = vowelIdx[ch - 'a'];
        if (idx != -1) {
            last[idx] = i;
        } else {
            ++prefC;
        }

        int min_last = INT_MAX;
        for (int v = 0; v < 5; ++v) {
            if (last[v] < min_last) min_last = last[v];
        }

        if (min_last != -1) {
            int target = prefC - k;
            if (target >= 0 && target <= n) {
                while (ptr[target] < static_cast<int>(positions[target].size()) &&
                       positions[target][ptr[target]] <= min_last) {
                    ++ptr[target];
                }
                ans += ptr[target];
            }
        }

        positions[prefC].push_back(i + 1);
    }

    return ans;
}

#include <bits/stdc++.h>
#include <array>

long long countVowelConsonantSubstrings(const std::string& word, int k) {
    static const std::array<int, 256> VOWEL_IDX = []{
        std::array<int, 256> arr;
        arr.fill(-1);
        arr['a'] = 0;
        arr['e'] = 1;
        arr['i'] = 2;
        arr['o'] = 3;
        arr['u'] = 4;
        return arr;
    }();

    int n = static_cast<int>(word.size());
    int latest[5];
    std::fill(std::begin(latest), std::end(latest), -1);

    int leftAtMostK = 0, leftAtMostKm1 = 0;
    int cntConK = 0, cntConKm1 = 0;
    long long answer = 0;

    for (int r = 0; r < n; ++r) {
        int vIdx = VOWEL_IDX[static_cast<unsigned char>(word[r])];
        if (vIdx == -1) {
            ++cntConK;
            ++cntConKm1;
        } else {
            latest[vIdx] = r;
        }

        while (cntConK > k) {
            if (VOWEL_IDX[static_cast<unsigned char>(word[leftAtMostK])] == -1) --cntConK;
            ++leftAtMostK;
        }

        if (k > 0) {
            while (cntConKm1 > k - 1) {
                if (VOWEL_IDX[static_cast<unsigned char>(word[leftAtMostKm1])] == -1) --cntConKm1;
                ++leftAtMostKm1;
            }
        }

        int minPos = n;
        for (int i = 0; i < 5; ++i) {
            if (latest[i] == -1) {
                minPos = -1;
                break;
            }
            if (latest[i] < minPos) minPos = latest[i];
        }

        long long cntAtMostK = 0, cntAtMostKm1 = 0;
        if (minPos >= leftAtMostK) cntAtMostK = static_cast<long long>(minPos - leftAtMostK + 1);
        if (k > 0 && minPos >= leftAtMostKm1) cntAtMostKm1 = static_cast<long long>(minPos - leftAtMostKm1 + 1);

        answer += cntAtMostK - cntAtMostKm1;
    }

    return answer;
}

