std::vector<int> removeMethods(int n, int k, const std::vector<std::pair<int, int>>& invocations) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : invocations) {
        adj[e.first].push_back(e.second);
    }
    std::vector<char> suspicious(n, 0);
    std::vector<int> stack;
    stack.push_back(k);
    while (!stack.empty()) {
        int cur = stack.back();
        stack.pop_back();
        if (suspicious[cur]) continue;
        suspicious[cur] = 1;
        for (int nxt : adj[cur]) {
            if (!suspicious[nxt]) stack.push_back(nxt);
        }
    }
    for (const auto& e : invocations) {
        if (!suspicious[e.first] && suspicious[e.second]) {
            std::vector<int> all(n);
            for (int i = 0; i < n; ++i) all[i] = i;
            return all;
        }
    }
    std::vector<int> remaining;
    remaining.reserve(n);
    for (int i = 0; i < n; ++i) {
        if (!suspicious[i]) remaining.push_back(i);
    }
    return remaining;
}

