std::vector<int> constructMinimumBitwiseArray(const std::vector<int>& nums) {
    std::vector<int> ans(nums.size());
    for (std::size_t i = 0; i < nums.size(); ++i) {
        int p = nums[i];
        if ((p & 1) == 0) {
            ans[i] = -1;
        } else {
            int t = __builtin_ctz(~static_cast<unsigned int>(p));
            ans[i] = p - (1 << (t - 1));
        }
    }
    return ans;
}

