std::vector<int> constructMinimumBitwiseArray(const std::vector<int>& nums) {
    std::vector<int> ans;
    ans.reserve(nums.size());
    for (int p : nums) {
        std::uint32_t up = static_cast<std::uint32_t>(p);
        std::uint32_t mask = (~up) & (up + 1);
        if (mask == 1u) {
            ans.push_back(-1);
        } else {
            ans.push_back(p - static_cast<int>(mask >> 1));
        }
    }
    return ans;
}

#include <bits/stdc++.h>

std::vector<long long> xSumAllKLongSubarrays(const std::vector<int>& nums, int k, int x) {
    int n = static_cast<int>(nums.size());
    std::vector<long long> result;
    if (k > n) return result;

    struct Cmp {
        bool operator()(const std::pair<int,int>& a, const std::pair<int,int>& b) const {
            if (a.first != b.first) return a.first > b.first;
            return a.second > b.second;
        }
    };

    std::unordered_map<int,int> freq;
    std::set<std::pair<int,int>, Cmp> ordered;

    auto adjust = [&](int val, int delta) {
        auto it = freq.find(val);
        int old = 0;
        if (it != freq.end()) {
            old = it->second;
            ordered.erase({old, val});
        }
        int nw = old + delta;
        if (nw > 0) {
            freq[val] = nw;
            ordered.insert({nw, val});
        } else if (it != freq.end()) {
            freq.erase(it);
        }
    };

    for (int i = 0; i < k; ++i) adjust(nums[i], +1);

    auto computeSum = [&]() -> long long {
        long long sum = 0;
        int cnt = 0;
        for (auto it = ordered.begin(); it != ordered.end() && cnt < x; ++it, ++cnt) {
            sum += static_cast<long long>(it->second) * it->first;
        }
        return sum;
    };

    result.push_back(computeSum());

    for (int i = k; i < n; ++i) {
        adjust(nums[i - k], -1);
        adjust(nums[i], +1);
        result.push_back(computeSum());
    }

    return result;
}

