struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

int kthLargestPerfectSubtree(TreeNode* root, int k) {
    std::vector<int> sizes;

    struct Info {
        bool isPerfect;
        int height;
        int size;
    };

    std::function<Info(TreeNode*)> dfs = [&](TreeNode* node) -> Info {
        if (!node) {
            return {true, -1, 0};
        }
        Info leftInfo = dfs(node->left);
        Info rightInfo = dfs(node->right);
        bool isPerf = leftInfo.isPerfect && rightInfo.isPerfect && leftInfo.height == rightInfo.height;
        int h = std::max(leftInfo.height, rightInfo.height) + 1;
        int sz;
        if (isPerf) {
            long long fullSize = (1LL << (h + 1)) - 1;
            sz = static_cast<int>(fullSize);
            sizes.push_back(sz);
        } else {
            sz = std::max(leftInfo.size, rightInfo.size);
        }
        return {isPerf, h, sz};
    };

    dfs(root);
    if (k <= 0 || k > static_cast<int>(sizes.size())) {
        return -1;
    }
    std::nth_element(sizes.begin(), sizes.begin() + (k - 1), sizes.end(),
                     std::greater<int>());
    return sizes[k - 1];
}

