std::vector<int> sortedGCDPairQueries(const std::vector<int>& nums, const std::vector<int>& queries) {
    int n = static_cast<int>(nums.size());
    int maxVal = 0;
    for (int v : nums) if (v > maxVal) maxVal = v;
    std::vector<int> freq(maxVal + 1, 0);
    for (int v : nums) ++freq[v];
    std::vector<int> cntDiv(maxVal + 1, 0);
    for (int d = 1; d <= maxVal; ++d) {
        for (int m = d; m <= maxVal; m += d) {
            cntDiv[d] += freq[m];
        }
    }
    std::vector<long long> exact(maxVal + 1, 0);
    for (int d = maxVal; d >= 1; --d) {
        long long total = 1LL * cntDiv[d] * (cntDiv[d] - 1) / 2;
        for (int m = d + d; m <= maxVal; m += d) {
            total -= exact[m];
        }
        exact[d] = total;
    }
    std::vector<long long> prefix(maxVal + 1, 0);
    for (int d = 1; d <= maxVal; ++d) {
        prefix[d] = prefix[d - 1] + exact[d];
    }
    std::vector<int> answer;
    answer.reserve(queries.size());
    for (int q : queries) {
        long long target = static_cast<long long>(q) + 1;
        auto it = std::lower_bound(prefix.begin() + 1, prefix.end(), target);
        int d = (it == prefix.end()) ? maxVal : static_cast<int>(it - prefix.begin());
        answer.push_back(d);
    }
    return answer;
}

#include <bits/stdc++.h>

int maximumRemovals(const std::string& source, const std::string& pattern, const std::vector<int>& targetIndices) {
    int n = static_cast<int>(source.size());
    int m = static_cast<int>(pattern.size());
    std::vector<char> isTarget(n, 0);
    for (int idx : targetIndices) {
        if (idx >= 0 && idx < n) isTarget[idx] = 1;
    }
    const int INF = 1e9;
    std::vector<int> dp(m + 1, INF);
    dp[0] = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = m - 1; j >= 0; --j) {
            if (source[i] == pattern[j] && dp[j] != INF) {
                int cost = dp[j] + (isTarget[i] ? 1 : 0);
                if (cost < dp[j + 1]) dp[j + 1] = cost;
            }
        }
    }
    int minNeeded = dp[m];
    int total = static_cast<int>(targetIndices.size());
    return total - minNeeded;
}

#include <bits/stdc++.h>
const int MOD = 1000000007;

int countWinningSequences(const std::string& s) {
    int n = static_cast<int>(s.size());
    int offset = n;
    int range = 2 * n + 1;

    auto idx = [&](char c) -> int {
        if (c == 'F') return 0;
        if (c == 'W') return 1;
        return 2; // 'E'
    };

    std::vector<int> alice(n);
    for (int i = 0; i < n; ++i) alice[i] = idx(s[i]);

    int win[3][3];
    for (int b = 0; b < 3; ++b) {
        for (int a = 0; a < 3; ++a) {
            if (b == a) win[b][a] = 0;
            else if ((b == 0 && a == 2) || (b == 1 && a == 0) || (b == 2 && a == 1))
                win[b][a] = 1;
            else
                win[b][a] = -1;
        }
    }

    std::vector<std::array<int,3>> dp(range);
    for (int cur = 0; cur < 3; ++cur) {
        int delta = win[cur][alice[0]];
        int sc = offset + delta;
        dp[sc][cur] = 1;
    }

    for (int i = 1; i < n; ++i) {
        std::vector<int> sumAll(range);
        for (int sc = 0; sc < range; ++sc) {
            long long s = dp[sc][0];
            s += dp[sc][1];
            if (s >= MOD) s -= MOD;
            s += dp[sc][2];
            if (s >= MOD) s -= MOD;
            sumAll[sc] = static_cast<int>(s);
        }
        std::vector<std::array<int,3>> ndp(range);
        for (int cur = 0; cur < 3; ++cur) {
            int delta = win[cur][alice[i]];
            for (int sc = 0; sc < range; ++sc) {
                int src = sc - delta;
                if (src < 0 || src >= range) continue;
                int val = sumAll[src] - dp[src][cur];
                if (val < 0) val += MOD;
                ndp[sc][cur] = (ndp[sc][cur] + val) % MOD;
            }
        }
        dp.swap(ndp);
    }

    long long ans = 0;
    for (int cur = 0; cur < 3; ++cur) {
        for (int sc = offset + 1; sc < range; ++sc) {
            ans += dp[sc][cur];
            if (ans >= MOD) ans -= MOD;
        }
    }
    return static_cast<int>(ans % MOD);
}

#include <bits/stdc++.h>
using namespace std;

vector<long long> xSumOfKSubarrays(const vector<int>& nums, int k, int x) {
    int n = (int)nums.size();
    unordered_map<int,int> freqOf;
    multiset<pair<int,int>, greater<pair<int,int>>> order; // (freq, value) desc
    auto insertVal = [&](int v, int f){ order.insert({f,v}); };
    auto eraseVal = [&](int v, int f){ order.erase(order.find({f,v})); };
    auto addOcc = [&](int v){
        int f = freqOf[v];
        if (f>0) eraseVal(v,f);
        freqOf[v] = f+1;
        insertVal(v, f+1);
    };
    auto removeOcc = [&](int v){
        int f = freqOf[v];
        eraseVal(v,f);
        if (f-1>0) { freqOf[v]=f-1; insertVal(v,f-1); }
        else freqOf.erase(v);
    };
    auto currentXSum = [&]() -> long long {
        long long sum=0; int cnt=0;
        for (auto& pr : order) { if (cnt>=x) break; sum += (long long)pr.first * pr.second; ++cnt; }
        return sum;
    };
    vector<long long> answer;
    for (int i=0;i<k;++i) addOcc(nums[i]);
    answer.push_back(currentXSum());
    for (int i=k;i<n;++i) {
        removeOcc(nums[i-k]);
        addOcc(nums[i]);
        answer.push_back(currentXSum());
    }
    return answer;
}

#include <bits/stdc++.h>
const int MOD = 1000000007;

static long long modPow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int numberOfWays(int n, int x, int y) {
    int maxN = std::max(n, x);
    std::vector<long long> fact(maxN + 1), invFact(maxN + 1);
    fact[0] = 1;
    for (int i = 1; i <= maxN; ++i) fact[i] = fact[i - 1] * i % MOD;
    invFact[maxN] = modPow(fact[maxN], MOD - 2);
    for (int i = maxN; i > 0; --i) invFact[i - 1] = invFact[i] * i % MOD;
    auto C = [&](int N, int K) -> long long {
        if (K < 0 || K > N) return 0;
        return fact[N] * invFact[K] % MOD * invFact[N - K] % MOD;
    };
    int limit = std::min(n, x);
    std::vector<long long> stir(limit + 1);
    stir[0] = 1;
    for (int i = 1; i <= n; ++i) {
        int up = std::min(i, limit);
        for (int k = up; k >= 1; --k) {
            stir[k] = (stir[k - 1] + (long long)k * stir[k]) % MOD;
        }
        stir[0] = 0;
    }
    long long ans = 0;
    long long ypow = 1;
    for (int k = 1; k <= limit; ++k) {
        ypow = ypow * y % MOD;
        long long ways = C(x, k);
        ways = ways * fact[k] % MOD;
        ways = ways * stir[k] % MOD;
        ways = ways * ypow % MOD;
        ans = (ans + ways) % MOD;
    }
    return (int)ans;
}

