std::vector<std::string> findScreenSequence(const std::string& target) {
    std::vector<std::string> result;
    size_t n = target.size();
    size_t total = 0;
    for (char c : target) {
        total += 1 + static_cast<size_t>(c - 'a');
    }
    result.reserve(total);
    std::string cur;
    cur.reserve(n);
    for (size_t i = 0; i < n; ++i) {
        cur.push_back('a');
        result.emplace_back(cur);
        int steps = target[i] - 'a';
        for (int s = 0; s < steps; ++s) {
            cur.back() = static_cast<char>((cur.back() - 'a' + 1) % 26 + 'a');
            result.emplace_back(cur);
        }
    }
    return result;
}

#include <bits/stdc++.h>

int minimumOperations(std::vector<int> nums) {
    const int INF = 1e9;
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;

    int maxVal = 0;
    for (int v : nums) if (v > maxVal) maxVal = v;
    std::vector<int> spf;
    if (maxVal >= 2) {
        spf.resize(maxVal + 1);
        for (int i = 0; i <= maxVal; ++i) spf[i] = i;
        for (int i = 2; i * i <= maxVal; ++i) {
            if (spf[i] == i) {
                for (int j = i * i; j <= maxVal; j += i) {
                    if (spf[j] == j) spf[j] = i;
                }
            }
        }
    }

    int prevOrig = nums[0];
    int prevSpf = (nums[0] <= 1) ? 1 : spf[nums[0]];
    bool prevHasSpf = (prevSpf != prevOrig);

    int dp0 = 0;
    int dp1 = prevHasSpf ? 1 : INF;

    for (int i = 1; i < n; ++i) {
        int curOrig = nums[i];
        int curSpf = (nums[i] <= 1) ? 1 : spf[nums[i]];
        bool curHasSpf = (curSpf != curOrig);

        int ndp0 = INF, ndp1 = INF;

        if (dp0 < INF) {
            if (prevOrig <= curOrig) ndp0 = std::min(ndp0, dp0);
            if (curHasSpf && prevOrig <= curSpf) ndp1 = std::min(ndp1, dp0 + 1);
        }
        if (dp1 < INF) {
            if (prevSpf <= curOrig) ndp0 = std::min(ndp0, dp1);
            if (curHasSpf && prevSpf <= curSpf) ndp1 = std::min(ndp1, dp1 + 1);
        }

        dp0 = ndp0;
        dp1 = ndp1;
        prevOrig = curOrig;
        prevSpf = curSpf;
    }

    int ans = std::min(dp0, dp1);
    return ans >= INF ? -1 : ans;
}

