vector<bool> dfsStringsArePalindromes(const vector<int>& parent, const string& s) {
    int n = parent.size();
    vector<vector<int>> children(n);
    for (int i = 1; i < n; ++i) children[parent[i]].push_back(i);
    vector<int> tin(n), tout(n);
    string seq;
    seq.reserve(n);
    function<void(int)> dfs = [&](int u) {
        tin[u] = seq.size();
        for (int v : children[u]) dfs(v);
        seq.push_back(s[u]);
        tout[u] = seq.size() - 1;
    };
    dfs(0);
    int m = seq.size();
    const unsigned long long base = 91138233ULL;
    vector<unsigned long long> pw(m + 1);
    pw[0] = 1;
    for (int i = 1; i <= m; ++i) pw[i] = pw[i - 1] * base;
    vector<unsigned long long> pref(m + 1), rpref(m + 1);
    for (int i = 0; i < m; ++i) pref[i + 1] = pref[i] * base + static_cast<unsigned long long>(seq[i]);
    for (int i = 0; i < m; ++i) rpref[i + 1] = rpref[i] * base + static_cast<unsigned long long>(seq[m - 1 - i]);
    auto getHash = [&](const vector<unsigned long long>& p, int l, int r) -> unsigned long long {
        return p[r + 1] - p[l] * pw[r - l + 1];
    };
    vector<bool> answer(n);
    for (int i = 0; i < n; ++i) {
        int l = tin[i], r = tout[i];
        unsigned long long h1 = getHash(pref, l, r);
        int rl = m - 1 - r, rr = m - 1 - l;
        unsigned long long h2 = getHash(rpref, rl, rr);
        answer[i] = h1 == h2;
    }
    return answer;
}

#include <bits/stdc++.h>

static inline long long ll_gcd(long long a, long long b) {
    while (b) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

long long maxFactorScore(const std::vector<int>& nums) {
    int n = nums.size();
    std::vector<long long> pref_gcd(n), pref_lcm(n);
    std::vector<long long> suff_gcd(n), suff_lcm(n);
    auto lcm = [](long long a, long long b) -> long long {
        if (a == 0 || b == 0) return 0;
        return a / ll_gcd(a, b) * b;
    };
    for (int i = 0; i < n; ++i) {
        if (i == 0) {
            pref_gcd[i] = nums[i];
            pref_lcm[i] = nums[i];
        } else {
            pref_gcd[i] = ll_gcd(pref_gcd[i - 1], (long long)nums[i]);
            pref_lcm[i] = lcm(pref_lcm[i - 1], nums[i]);
        }
    }
    for (int i = n - 1; i >= 0; --i) {
        if (i == n - 1) {
            suff_gcd[i] = nums[i];
            suff_lcm[i] = nums[i];
        } else {
            suff_gcd[i] = ll_gcd(suff_gcd[i + 1], (long long)nums[i]);
            suff_lcm[i] = lcm(suff_lcm[i + 1], nums[i]);
        }
    }
    long long best = pref_gcd[n - 1] * pref_lcm[n - 1];
    for (int i = 0; i < n; ++i) {
        long long left_gcd = (i > 0) ? pref_gcd[i - 1] : 0;
        long long right_gcd = (i + 1 < n) ? suff_gcd[i + 1] : 0;
        long long cur_gcd = ll_gcd(left_gcd, right_gcd);
        if (cur_gcd == 0) {
            best = std::max(best, 0LL);
            continue;
        }
        long long left_lcm = (i > 0) ? pref_lcm[i - 1] : 1;
        long long right_lcm = (i + 1 < n) ? suff_lcm[i + 1] : 1;
        long long cur_lcm = lcm(left_lcm, right_lcm);
        best = std::max(best, cur_gcd * cur_lcm);
    }
    return best;
}

#include <bits/stdc++.h>
#include <cstdint>

int countEqualGcdSubsequencePairs(const std::vector<int>& nums) {
    const int MOD = 1000000007;
    const int MAXV = 200;
    static int gcdTable[MAXV + 1][MAXV + 1];
    for (int i = 0; i <= MAXV; ++i) {
        for (int j = 0; j <= MAXV; ++j) {
            int a = i, b = j;
            while (b) {
                int t = a % b;
                a = b;
                b = t;
            }
            gcdTable[i][j] = a;
        }
    }
    static std::uint32_t dp[MAXV + 1][MAXV + 1];
    static std::uint32_t ndp[MAXV + 1][MAXV + 1];
    for (int i = 0; i <= MAXV; ++i)
        for (int j = 0; j <= MAXV; ++j)
            dp[i][j] = 0;
    dp[0][0] = 1;
    for (int x : nums) {
        for (int i = 0; i <= MAXV; ++i)
            for (int j = 0; j <= MAXV; ++j)
                ndp[i][j] = 0;
        for (int a = 0; a <= MAXV; ++a) {
            for (int b = 0; b <= MAXV; ++b) {
                std::uint32_t cur = dp[a][b];
                if (!cur) continue;
                std::uint32_t sum = ndp[a][b] + cur;
                if (sum >= MOD) sum -= MOD;
                ndp[a][b] = sum;
                int na = (a == 0) ? x : gcdTable[a][x];
                sum = ndp[na][b] + cur;
                if (sum >= MOD) sum -= MOD;
                ndp[na][b] = sum;
                int nb = (b == 0) ? x : gcdTable[b][x];
                sum = ndp[a][nb] + cur;
                if (sum >= MOD) sum -= MOD;
                ndp[a][nb] = sum;
            }
        }
        for (int i = 0; i <= MAXV; ++i)
            for (int j = 0; j <= MAXV; ++j)
                dp[i][j] = ndp[i][j];
    }
    long long ans = 0;
    for (int g = 1; g <= MAXV; ++g) {
        ans += dp[g][g];
        if (ans >= MOD) ans -= MOD;
    }
    return static_cast<int>(ans);
}

#include <bits/stdc++.h>

std::vector<int> findSubtreeSizes(const std::vector<int>& parent, const std::string& s) {
    int n = static_cast<int>(parent.size());
    std::vector<std::vector<int>> origChildren(n);
    for (int i = 1; i < n; ++i) {
        origChildren[parent[i]].push_back(i);
    }

    std::vector<int> newParent = parent;
    std::vector<int> savedPrev(n, -1);
    std::vector<int> lastSeen(26, -1);
    struct Item { int node; int state; };
    std::vector<Item> stack;
    stack.reserve(2 * n);
    stack.push_back({0, 0});

    while (!stack.empty()) {
        Item cur = stack.back();
        stack.pop_back();
        int u = cur.node;
        if (cur.state == 0) {
            int c = s[u] - 'a';
            savedPrev[u] = lastSeen[c];
            lastSeen[c] = u;
            stack.push_back({u, 1});
            for (int v : origChildren[u]) {
                int cc = s[v] - 'a';
                if (lastSeen[cc] != -1) newParent[v] = lastSeen[cc];
                else newParent[v] = parent[v];
                stack.push_back({v, 0});
            }
        } else {
            int c = s[u] - 'a';
            lastSeen[c] = savedPrev[u];
        }
    }

    std::vector<std::vector<int>> finalChildren(n);
    for (int i = 1; i < n; ++i) {
        finalChildren[newParent[i]].push_back(i);
    }

    std::vector<int> ans(n, 1);
    std::vector<Item> stack2;
    stack2.reserve(2 * n);
    stack2.push_back({0, 0});
    while (!stack2.empty()) {
        Item cur = stack2.back();
        stack2.pop_back();
        int u = cur.node;
        if (cur.state == 0) {
            stack2.push_back({u, 1});
            for (int v : finalChildren[u]) {
                stack2.push_back({v, 0});
            }
        } else {
            for (int v : finalChildren[u]) {
                ans[u] += ans[v];
            }
        }
    }
    return ans;
}

#include <bits/stdc++.h>
static const int MOD = 1000000007;

int originalStringCount(const std::string& word, int k) {
    int n = static_cast<int>(word.size());
    std::vector<int> groups;
    for (int i = 0; i < n; ) {
        int j = i;
        while (j < n && word[j] == word[i]) ++j;
        groups.push_back(j - i);
        i = j;
    }
    long long totalWays = 1;
    for (int g : groups) {
        totalWays = totalWays * g % MOD;
    }
    if (k <= 0) return static_cast<int>(totalWays);
    std::vector<int> dp(k, 0), ndp(k, 0), pref(k, 0);
    dp[0] = 1;
    for (int g : groups) {
        int limit = std::min(g, k - 1);
        pref[0] = dp[0];
        for (int i = 1; i < k; ++i) {
            int v = pref[i - 1] + dp[i];
            if (v >= MOD) v -= MOD;
            pref[i] = v;
        }
        ndp[0] = 0;
        for (int t = 1; t < k; ++t) {
            int left = t - limit;
            if (left < 0) left = 0;
            int sum = pref[t - 1];
            if (left > 0) {
                sum -= pref[left - 1];
                if (sum < 0) sum += MOD;
            }
            ndp[t] = sum;
        }
        dp.swap(ndp);
    }
    long long lessThanK = 0;
    for (int i = 0; i < k; ++i) {
        lessThanK += dp[i];
        if (lessThanK >= MOD) lessThanK -= MOD;
    }
    long long ans = totalWays - lessThanK;
    ans %= MOD;
    if (ans < 0) ans += MOD;
    return static_cast<int>(ans);
}

