long long maxScore(int n, int k, const std::vector<std::vector<int>>& stayScore, const std::vector<std::vector<int>>& travelScore) {
    const long long NEG = LLONG_MIN / 4;
    std::vector<long long> dpPrev(n, NEG), dpCurr(n, NEG);

    // Day 0 initialization
    for (int s = 0; s < n; ++s) {
        dpPrev[s] = std::max(dpPrev[s], (long long)stayScore[0][s]);
        for (int t = 0; t < n; ++t) {
            if (t == s) continue;
            dpPrev[t] = std::max(dpPrev[t], (long long)travelScore[s][t]);
        }
    }

    // Subsequent days
    for (int day = 1; day < k; ++day) {
        std::fill(dpCurr.begin(), dpCurr.end(), NEG);
        for (int s = 0; s < n; ++s) {
            if (dpPrev[s] == NEG) continue;
            // Stay
            dpCurr[s] = std::max(dpCurr[s], dpPrev[s] + stayScore[day][s]);
            // Travel
            for (int t = 0; t < n; ++t) {
                if (t == s) continue;
                dpCurr[t] = std::max(dpCurr[t], dpPrev[s] + travelScore[s][t]);
            }
        }
        dpPrev.swap(dpCurr);
    }

    long long ans = NEG;
    for (long long v : dpPrev) ans = std::max(ans, v);
    return ans;
}

#include <bits/stdc++.h>

int totalLengthAfterTransformations(const std::string& s, int t) {
    const long long MOD = 1000000007LL;
    const int N = 26;
    std::vector<long long> cnt(N, 0);
    for (char ch : s) {
        cnt[ch - 'a'] = (cnt[ch - 'a'] + 1) % MOD;
    }
    std::array<std::array<long long, N>, N> base{};
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) base[i][j] = 0;
    }
    base[0][25] = 2;
    for (int i = 1; i < N; ++i) base[i][i - 1] = 1;
    std::array<std::array<long long, N>, N> result{};
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) result[i][j] = (i == j) ? 1 : 0;
    }
    int exp = t;
    while (exp > 0) {
        if (exp & 1) {
            std::array<std::array<long long, N>, N> tmp{};
            for (int i = 0; i < N; ++i) {
                for (int k = 0; k < N; ++k) {
                    long long rik = result[i][k];
                    if (rik == 0) continue;
                    for (int j = 0; j < N; ++j) {
                        tmp[i][j] = (tmp[i][j] + rik * base[k][j]) % MOD;
                    }
                }
            }
            result = tmp;
        }
        std::array<std::array<long long, N>, N> tmp{};
        for (int i = 0; i < N; ++i) {
            for (int k = 0; k < N; ++k) {
                long long bik = base[i][k];
                if (bik == 0) continue;
                for (int j = 0; j < N; ++j) {
                    tmp[i][j] = (tmp[i][j] + bik * base[k][j]) % MOD;
                }
            }
        }
        base = tmp;
        exp >>= 1;
    }
    std::vector<long long> finalCnt(N, 0);
    for (int i = 0; i < N; ++i) {
        long long sum = 0;
        for (int j = 0; j < N; ++j) {
            sum = (sum + result[i][j] * cnt[j]) % MOD;
        }
        finalCnt[i] = sum;
    }
    long long ans = 0;
    for (long long v : finalCnt) ans = (ans + v) % MOD;
    return static_cast<int>(ans);
}

