bool is_balanced_string(const std::string& num) {
    std::uint_fast32_t even_sum = 0, odd_sum = 0;
    for (std::size_t i = 0; i < num.size(); ++i) {
        unsigned int digit = static_cast<unsigned int>(num[i] - '0');
        if ((i & 1u) == 0) {
            even_sum += digit;
        } else {
            odd_sum += digit;
        }
    }
    return even_sum == odd_sum;
}

#include <bits/stdc++.h>
const long long MOD = 1000000007LL;
using Matrix = std::array<std::array<long long, 26>, 26>;

Matrix multiplyMatrix(const Matrix& A, const Matrix& B) {
    Matrix C{};
    for (int i = 0; i < 26; ++i) {
        for (int k = 0; k < 26; ++k) {
            long long aik = A[i][k];
            if (aik == 0) continue;
            for (int j = 0; j < 26; ++j) {
                C[i][j] = (C[i][j] + aik * B[k][j]) % MOD;
            }
        }
    }
    return C;
}

std::array<long long, 26> multiplyMatrixVector(const Matrix& A, const std::array<long long, 26>& v) {
    std::array<long long, 26> res{};
    for (int i = 0; i < 26; ++i) {
        long long sum = 0;
        for (int j = 0; j < 26; ++j) {
            sum = (sum + A[i][j] * v[j]) % MOD;
        }
        res[i] = sum;
    }
    return res;
}

int totalCharactersAfterTransformationsII(std::string s, int t, std::vector<int> nums) {
    Matrix A{};
    for (int c = 0; c < 26; ++c) {
        int cnt = nums[c];
        for (int d = 1; d <= cnt; ++d) {
            int nxt = (c + d) % 26;
            A[c][nxt] = (A[c][nxt] + 1) % MOD;
        }
    }
    std::array<long long, 26> vec{};
    vec.fill(1);
    Matrix cur = A;
    long long exp = t;
    while (exp > 0) {
        if (exp & 1LL) vec = multiplyMatrixVector(cur, vec);
        cur = multiplyMatrix(cur, cur);
        exp >>= 1LL;
    }
    long long ans = 0;
    for (char ch : s) {
        ans = (ans + vec[ch - 'a']) % MOD;
    }
    return static_cast<int>(ans);
}

#include <bits/stdc++.h>
#include <vector>
#include <queue>
#include <tuple>
#include <array>
#include <climits>

long long minimumTime(const std::vector<std::vector<int>>& moveTime) {
    int n = static_cast<int>(moveTime.size());
    int m = static_cast<int>(moveTime[0].size());
    const long long INF = LLONG_MAX / 4;
    std::vector<std::vector<std::array<long long, 2>>> dist(n, std::vector<std::array<long long, 2>>(m, {INF, INF}));
    using State = std::tuple<long long, int, int, int>;
    std::priority_queue<State, std::vector<State>, std::greater<State>> pq;
    dist[0][0][0] = 0;
    pq.emplace(0LL, 0, 0, 0);
    const int di[4] = {-1, 1, 0, 0};
    const int dj[4] = {0, 0, -1, 1};
    while (!pq.empty()) {
        State top = pq.top();
        pq.pop();
        long long curTime = std::get<0>(top);
        int i = std::get<1>(top);
        int j = std::get<2>(top);
        int par = std::get<3>(top);
        if (curTime != dist[i][j][par]) continue;
        long long moveCost = (par == 0) ? 1LL : 2LL;
        int nextPar = 1 - par;
        for (int dir = 0; dir < 4; ++dir) {
            int ni = i + di[dir];
            int nj = j + dj[dir];
            if (ni < 0 || ni >= n || nj < 0 || nj >= m) continue;
            long long start = curTime > moveTime[ni][nj] ? curTime : static_cast<long long>(moveTime[ni][nj]);
            long long arrival = start + moveCost;
            if (arrival < dist[ni][nj][nextPar]) {
                dist[ni][nj][nextPar] = arrival;
                pq.emplace(arrival, ni, nj, nextPar);
            }
        }
    }
    return std::min(dist[n - 1][m - 1][0], dist[n - 1][m - 1][1]);
}

#include <bits/stdc++.h>

long long minimumTime(const std::vector<std::vector<int>>& moveTime) {
    int n = static_cast<int>(moveTime.size());
    int m = static_cast<int>(moveTime[0].size());
    const long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<long long> dist(n * m, INF);
    using State = std::pair<long long, int>; // time, index
    struct Compare {
        bool operator()(const State& a, const State& b) const { return a.first > b.first; }
    };
    std::priority_queue<State, std::vector<State>, Compare> pq;
    dist[0] = 0;
    pq.emplace(0, 0);
    const int dx[4] = {1, -1, 0, 0};
    const int dy[4] = {0, 0, 1, -1};
    while (!pq.empty()) {
        State cur = pq.top();
        pq.pop();
        long long t = cur.first;
        int idx = cur.second;
        if (t != dist[idx]) continue;
        int x = idx / m;
        int y = idx % m;
        if (x == n - 1 && y == m - 1) break;
        for (int dir = 0; dir < 4; ++dir) {
            int nx = x + dx[dir];
            int ny = y + dy[dir];
            if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
            int nidx = nx * m + ny;
            long long arrive = std::max(t + 1LL, static_cast<long long>(moveTime[nx][ny]) + 1LL);
            if (arrive < dist[nidx]) {
                dist[nidx] = arrive;
                pq.emplace(arrive, nidx);
            }
        }
    }
    return dist[n * m - 1];
}

#include <bits/stdc++.h>
#include <cstdint>

long long smallestDivisibleDigitProduct(long long n, long long t) {
    auto digitProductMod = [&](long long x) -> long long {
        if (x == 0) return 0;
        long long prod = 1;
        while (x > 0) {
            int d = x % 10;
            prod *= d;
            if (prod == 0) break;
            x /= 10;
        }
        return prod % t;
    };
    if (digitProductMod(n) == 0) return n;

    auto nextWithZero = [&](long long x) -> long long {
        std::string s = std::to_string(x);
        if (s.find('0') != std::string::npos) return x;
        for (int i = (int)s.size() - 1; i >= 0; --i) {
            if (s[i] != '9') {
                s[i] = char(s[i] + 1);
                for (size_t j = i + 1; j < s.size(); ++j) s[j] = '0';
                return std::stoll(s);
            }
        }
        // all 9's
        std::string res = "1";
        res.append(s.size(), '0');
        return std::stoll(res);
    };
    long long zeroCandidate = nextWithZero(n);
    std::string s = std::to_string(n);
    int L = s.size();
    std::vector<std::vector<std::vector<char>>> memo(L + 1,
        std::vector<std::vector<char>>(2, std::vector<char>(t, -1)));

    std::function<char(int, int, long long)> can = [&](int pos, int tight, long long mod) -> char {
        if (pos == L) return (mod == 0);
        char &res = memo[pos][tight][mod];
        if (res != -1) return res;
        int low = tight ? (s[pos] - '0') : 1;
        for (int d = low; d <= 9; ++d) {
            if (d == 0) continue;
            int ntight = tight && (d == low);
            long long nmod = (mod * d) % t;
            if (can(pos + 1, ntight, nmod)) return res = 1;
        }
        return res = 0;
    };

    if (can(0, 1, 1 % t)) {
        std::string ans;
        int tight = 1;
        long long mod = 1 % t;
        for (int pos = 0; pos < L; ++pos) {
            int low = tight ? (s[pos] - '0') : 1;
            for (int d = low; d <= 9; ++d) {
                if (d == 0) continue;
                int ntight = tight && (d == low);
                long long nmod = (mod * d) % t;
                if (can(pos + 1, ntight, nmod)) {
                    ans.push_back(char('0' + d));
                    tight = ntight;
                    mod = nmod;
                    break;
                }
            }
        }
        long long candidate = std::stoll(ans);
        if (candidate >= n) return candidate;
    }
    return zeroCandidate;
}

#include <bits/stdc++.h>
int countBalancedPermutations(std::string num) {
    const int MOD = 1000000007;
    int n = static_cast<int>(num.size());
    int E = (n + 1) / 2;
    int O = n / 2;
    int total = 0;
    int cnt[10] = {0};
    for (char ch : num) {
        int d = ch - '0';
        cnt[d]++;
        total += d;
    }
    if (total % 2 != 0) return 0;
    int target = total / 2;
    if (target > 9 * E) return 0;
    std::vector<long long> fact(n + 1), invFact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i % MOD;
    auto modpow = [&](long long a, long long e) {
        long long r = 1 % MOD;
        while (e) {
            if (e & 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    };
    invFact[n] = modpow(fact[n], MOD - 2);
    for (int i = n; i >= 1; --i) invFact[i - 1] = invFact[i] * i % MOD;
    std::vector<std::vector<long long>> dp(E + 1, std::vector<long long>(target + 1, 0));
    dp[0][0] = 1;
    for (int d = 0; d <= 9; ++d) {
        int c = cnt[d];
        if (c == 0) continue;
        std::vector<long long> contrib(c + 1);
        for (int k = 0; k <= c; ++k) contrib[k] = invFact[k] * invFact[c - k] % MOD;
        std::vector<std::vector<long long>> ndp(E + 1, std::vector<long long>(target + 1, 0));
        for (int e = 0; e <= E; ++e) {
            for (int s = 0; s <= target; ++s) {
                long long cur = dp[e][s];
                if (!cur) continue;
                for (int k = 0; k <= c; ++k) {
                    int ne = e + k;
                    int ns = s + k * d;
                    if (ne > E || ns > target) continue;
                    ndp[ne][ns] = (ndp[ne][ns] + cur * contrib[k]) % MOD;
                }
            }
        }
        dp.swap(ndp);
    }
    long long ways = dp[E][target];
    ways = ways * fact[E] % MOD * fact[O] % MOD;
    return static_cast<int>(ways);
}

