bool check(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    if (n < 2 * k) return false;
    if (k == 1) return true;
    std::vector<int> inc(n - 1, 0);
    for (int i = 0; i + 1 < n; ++i) {
        inc[i] = (nums[i] < nums[i + 1]) ? 1 : 0;
    }
    std::vector<int> pref(n, 0);
    for (int i = 0; i < n - 1; ++i) {
        pref[i + 1] = pref[i] + inc[i];
    }
    int need = k - 1;
    for (int i = 0; i + 2 * k - 1 <= n; ++i) {
        int sum1 = pref[i + k - 1] - pref[i];
        int sum2 = pref[i + 2 * k - 1] - pref[i + k];
        if (sum1 == need && sum2 == need) return true;
    }
    return false;
}

#include <bits/stdc++.h>

int maxFrequency(std::vector<int>& nums, int k, int numOperations) {
    if (k == 0) {
        std::unordered_map<int, int> cnt;
        int best = 0;
        for (int v : nums) {
            ++cnt[v];
            best = std::max(best, cnt[v]);
        }
        return best;
    }

    std::vector<std::pair<int, long long>> items;
    items.reserve(nums.size());
    for (int v : nums) {
        int r = v % k;
        long long base = (v - r) / static_cast<long long>(k);
        items.emplace_back(r, base);
    }
    std::sort(items.begin(), items.end(), [](const auto& a, const auto& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second < b.second;
    });

    int answer = 0;
    std::size_t i = 0;
    while (i < items.size()) {
        std::size_t j = i;
        while (j < items.size() && items[j].first == items[i].first) ++j;
        long long sum = 0;
        std::size_t left = i;
        for (std::size_t right = i; right < j; ++right) {
            sum += items[right].second;
            while (items[right].second * (right - left + 1) - sum > static_cast<long long>(numOperations)) {
                sum -= items[left].second;
                ++left;
            }
            answer = std::max(answer, static_cast<int>(right - left + 1));
        }
        i = j;
    }
    return answer;
}

#include <bits/stdc++.h>

int maxFrequencyAfterOperations(const std::vector<int>& nums, int k, int numOperations) {
    if (nums.empty()) return 0;
    std::vector<int> sorted(nums);
    std::sort(sorted.begin(), sorted.end());
    std::unordered_map<int, int> freq;
    for (int v : nums) ++freq[v];
    std::vector<int> distinctVals;
    distinctVals.reserve(freq.size());
    for (const auto& p : freq) distinctVals.push_back(p.first);
    std::sort(distinctVals.begin(), distinctVals.end());
    size_t left = 0, right = 0;
    int ans = 0;
    const size_t n = sorted.size();
    for (int v : distinctVals) {
        long long low = static_cast<long long>(v) - k;
        long long high = static_cast<long long>(v) + k;
        while (left < n && static_cast<long long>(sorted[left]) < low) ++left;
        while (right < n && static_cast<long long>(sorted[right]) <= high) ++right;
        int intervalCount = static_cast<int>(right - left);
        int cntSame = freq[v];
        int cntOther = intervalCount - cntSame;
        int possible = cntSame + std::min(numOperations, cntOther);
        if (possible > ans) ans = possible;
    }
    return ans;
}

