#include <bits/stdc++.h>

bool isZeroArray(const std::vector<int>& nums, const std::vector<std::vector<int>>& queries) {
    int n = static_cast<int>(nums.size());
    struct DSU {
        std::vector<int> parent, sz, nxt;
        DSU(int n) : parent(n), sz(n,1), nxt(n) {
            for (int i = 0; i < n; ++i) {
                parent[i] = i;
                nxt[i] = i + 1;
            }
        }
        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }
        void unite(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return;
            if (sz[a] < sz[b]) std::swap(a, b);
            parent[b] = a;
            sz[a] += sz[b];
        }
        int next(int x) {
            return nxt[x];
        }
        void setNext(int x, int v) {
            nxt[x] = v;
        }
    };
    DSU dsu(n);
    for (const auto& q : queries) {
        int l = q[0];
        int r = q[1];
        if (l < 0) l = 0;
        if (r >= n) r = n - 1;
        int i = l;
        while (i < r) {
            dsu.unite(i, i + 1);
            int nxt = dsu.next(i);
            dsu.setNext(i, r);
            i = nxt;
        }
    }
    std::vector<char> hasZero(n, 0);
    for (int i = 0; i < n; ++i) {
        if (nums[i] == 0) {
            hasZero[dsu.find(i)] = 1;
        }
    }
    for (int i = 0; i < n; ++i) {
        if (!hasZero[dsu.find(i)]) return false;
    }
    return true;
}

