long long shiftDistance(const std::string& s, const std::string& t, const std::vector<int>& nextCost, const std::vector<int>& previousCost) {
    std::array<long long, 27> prefNext{}, prefPrev{};
    for (int i = 0; i < 26; ++i) {
        prefNext[i + 1] = prefNext[i] + nextCost[i];
        prefPrev[i + 1] = prefPrev[i] + previousCost[i];
    }
    long long total = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        int a = s[i] - 'a';
        int b = t[i] - 'a';
        long long forwardCost;
        if (a <= b) {
            forwardCost = prefNext[b] - prefNext[a];
        } else {
            forwardCost = prefNext[26] - prefNext[a] + prefNext[b];
        }
        long long backwardCost;
        if (a >= b) {
            backwardCost = prefPrev[a + 1] - prefPrev[b + 1];
        } else {
            backwardCost = prefPrev[26] - prefPrev[b + 1] + prefPrev[a + 1];
        }
        total += std::min(forwardCost, backwardCost);
    }
    return total;
}

