long long minimizeMaxDiff(const std::vector<int>& nums) {
    size_t n = nums.size();
    long long base = 0;
    long long minV = std::numeric_limits<long long>::max();
    long long maxV = std::numeric_limits<long long>::min();
    for (size_t i = 0; i + 1 < n; ++i) {
        long long a = nums[i];
        long long b = nums[i + 1];
        if (a != -1 && b != -1) {
            long long diff = std::llabs(a - b);
            if (diff > base) base = diff;
        }
        if (a == -1 && b != -1) {
            if (b < minV) minV = b;
            if (b > maxV) maxV = b;
        }
        if (a != -1 && b == -1) {
            if (a < minV) minV = a;
            if (a > maxV) maxV = a;
        }
    }
    if (minV == std::numeric_limits<long long>::max()) return 0;
    long long diff = maxV - minV;
    long long kDiff = (diff + 1) / 2;
    return std::max(base, kDiff);
}

#include <bits/stdc++.h>
using namespace std;

struct SegTree {
    int n;
    vector<long long> maxTree, lazy;
    vector<int> nums;
    SegTree(vector<int>& a) : n((int)a.size()), maxTree(4*(int)a.size(),0), lazy(4*(int)a.size(),0), nums(a) {
        build(1,0,n-1);
    }
    void build(int node, int l, int r) {
        if (l==r) { maxTree[node]=nums[l]; return; }
        int mid=(l+r)>>1;
        build(node<<1,l,mid); build(node<<1|1,mid+1,r);
        maxTree[node]=max(maxTree[node<<1],maxTree[node<<1|1]);
    }
    void apply(int node, long long dec) {
        if (maxTree[node]==0) return;
        if (maxTree[node]<=dec) { maxTree[node]=0; lazy[node]=0; }
        else { maxTree[node]-=dec; lazy[node]+=dec; }
    }
    void push(int node) {
        long long lz=lazy[node];
        if (lz!=0) { apply(node<<1,lz); apply(node<<1|1,lz); lazy[node]=0; }
    }
    void update(int node, int l, int r, int ql, int qr, long long dec) {
        if (ql>r||qr<l||maxTree[node]==0) return;
        if (ql<=l && r<=qr && maxTree[node]<=dec) { maxTree[node]=0; lazy[node]=0; return; }
        if (l==r) { apply(node,dec); return; }
        push(node);
        int mid=(l+r)>>1;
        if (ql<=mid) update(node<<1,l,mid,ql,qr,dec);
        if (qr>mid) update(node<<1|1,mid+1,r,ql,qr,dec);
        maxTree[node]=max(maxTree[node<<1],maxTree[node<<1|1]);
    }
};

int minimumOperations(vector<int>& nums, vector<vector<int>>& queries) {
    int n=(int)nums.size();
    if (n==0) return 0;
    SegTree st(nums);
    if (st.maxTree[1]==0) return 0;
    for (int i=0;i<(int)queries.size();++i) {
        int l=queries[i][0], r=queries[i][1], v=queries[i][2];
        st.update(1,0,n-1,l,r,v);
        if (st.maxTree[1]==0) return i+1;
    }
    return -1;
}

