int maxCollectedFruits(vector<vector<int>>& fruits) {
    int n = fruits.size();
    const int INF = INT_MIN/2;
    vector<vector<int>> f(n, vector<int>(n, INF));
    f[0][n-1] = fruits[0][n-1];
    for (int i = 1; i < n; i++) {
        for (int j = i+1; j < n; j++) {
            int best = max(f[i-1][j], f[i-1][j-1]);
            if (j+1 < n) best = max(best, f[i-1][j+1]);
            f[i][j] = best + fruits[i][j];
        }
    }
    vector<vector<int>> g(n, vector<int>(n, INF));
    g[n-1][0] = fruits[n-1][0];
    for (int j = 1; j < n; j++) {
        for (int i = j+1; i < n; i++) {
            int best = max(g[i][j-1], g[i-1][j-1]);
            if (i+1 < n) best = max(best, g[i+1][j-1]);
            g[i][j] = best + fruits[i][j];
        }
    }
    int ans = f[n-2][n-1] + g[n-1][n-2];
    for (int i = 0; i < n; i++) ans += fruits[i][i];
    return ans;
}

