long long minPositiveSumSubarray(const std::vector<int>& nums, int l, int r) {
    int n = static_cast<int>(nums.size());
    if (l > n) return -1;
    std::vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + nums[i];
    std::multiset<long long> candidates;
    long long answer = LLONG_MAX;
    for (int i = l; i <= n; ++i) {
        candidates.insert(pref[i - l]);
        if (i - r - 1 >= 0) {
            auto it = candidates.find(pref[i - r - 1]);
            if (it != candidates.end()) candidates.erase(it);
        }
        auto it = candidates.lower_bound(pref[i]);
        if (it != candidates.begin()) {
            --it;
            long long diff = pref[i] - *it;
            if (diff > 0 && diff < answer) answer = diff;
        }
    }
    return answer == LLONG_MAX ? -1 : answer;
}

#include <bits/stdc++.h>

int max_removable_queries(const std::vector<int>& nums, const std::vector<std::vector<int>>& queries) {
    int n = static_cast<int>(nums.size());
    int q = static_cast<int>(queries.size());
    std::vector<std::vector<int>> start_at(n);
    for (int i = 0; i < q; ++i) {
        int l = queries[i][0];
        int r = queries[i][1];
        if (l >= 0 && l < n) {
            start_at[l].push_back(r);
        }
    }
    std::priority_queue<int, std::vector<int>, std::greater<int>> start_heap;
    std::priority_queue<int, std::vector<int>, std::greater<int>> selected_heap;
    int active = 0;
    int used = 0;
    for (int i = 0; i < n; ++i) {
        for (int r : start_at[i]) {
            start_heap.push(r);
        }
        while (!selected_heap.empty() && selected_heap.top() < i) {
            selected_heap.pop();
            --active;
        }
        while (!start_heap.empty() && start_heap.top() < i) {
            start_heap.pop();
        }
        while (active < nums[i]) {
            if (start_heap.empty()) {
                return -1;
            }
            int r = start_heap.top();
            start_heap.pop();
            selected_heap.push(r);
            ++active;
            ++used;
        }
    }
    return q - used;
}

