long long largestOutlier(const std::vector<int>& nums) {
    long long total = 0;
    for (int v : nums) {
        total += v;
    }
    std::unordered_map<int, int> freq;
    freq.reserve(nums.size() * 2);
    for (int v : nums) {
        ++freq[v];
    }
    long long best = LLONG_MIN;
    for (int v : nums) {
        long long outlier = total - 2LL * v;
        if (outlier < INT_MIN || outlier > INT_MAX) continue;
        auto it = freq.find(static_cast<int>(outlier));
        if (it == freq.end()) continue;
        if (outlier == v && it->second < 2) continue;
        if (outlier > best) best = outlier;
    }
    return best;
}

class Solution {
public:
    long long maximizeSumOfWeights(vector<vector<int>>& edges, int K) {
        int n = edges.size() + 1;
        vector<vector<pair<int,int>>> g(n);
        for (auto& e : edges) {
            g[e[0]].push_back({e[1], e[2]});
            g[e[1]].push_back({e[0], e[2]});
        }

        vector<int> parent(n, -1), order;
        order.reserve(n);
        vector<bool> visited(n, false);
        vector<int> stack_ = {0};
        visited[0] = true;
        while (!stack_.empty()) {
            int u = stack_.back(); stack_.pop_back();
            order.push_back(u);
            for (auto& [v, w] : g[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    parent[v] = u;
                    stack_.push_back(v);
                }
            }
        }

        // sumK[u] = max weight in u's subtree keeping at most K edges at u;
        // sumK1[u] = same but at most K-1 (needed when u itself is chosen as a child elsewhere).
        vector<long long> sumK(n, 0), sumK1(n, 0);
        for (int idx = (int)order.size()-1; idx >= 0; idx--) {
            int u = order[idx];
            long long s = 0;
            vector<long long> t;
            for (auto& [v, w] : g[u]) {
                if (v == parent[u]) continue;
                s += sumK[v];
                long long d = (long long)w + sumK1[v] - sumK[v];
                if (d > 0) t.push_back(d);
            }
            sort(t.rbegin(), t.rend());
            long long vk = s, vk1 = s;
            for (int i = 0; i < (int)t.size(); i++) {
                if (i < K) vk += t[i];
                if (i < K-1) vk1 += t[i];
            }
            sumK[u] = vk;
            sumK1[u] = vk1;
        }
        return max(sumK[0], sumK1[0]);
    }
};

