std::vector<int> maximizeTargetNodes(const std::vector<std::vector<int>>& edges1,
                                     const std::vector<std::vector<int>>& edges2,
                                     int k) {
    int n = static_cast<int>(edges1.size()) + 1;
    int m = static_cast<int>(edges2.size()) + 1;

    auto buildAdj = [&](int sz, const std::vector<std::vector<int>>& edges) {
        std::vector<std::vector<int>> adj(sz);
        for (const auto& e : edges) {
            int a = e[0];
            int b = e[1];
            adj[a].push_back(b);
            adj[b].push_back(a);
        }
        return adj;
    };

    std::vector<std::vector<int>> adj1 = buildAdj(n, edges1);
    std::vector<std::vector<int>> adj2 = buildAdj(m, edges2);

    std::vector<int> bestSecond(k + 1, 0);
    std::vector<int> dist(m);
    for (int start = 0; start < m; ++start) {
        std::fill(dist.begin(), dist.end(), -1);
        std::queue<int> q;
        dist[start] = 0;
        q.push(start);
        std::vector<int> cnt(k + 1, 0);
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            int d = dist[u];
            if (d <= k) ++cnt[d];
            if (d == k) continue;
            for (int v : adj2[u]) {
                if (dist[v] == -1) {
                    dist[v] = d + 1;
                    q.push(v);
                }
            }
        }
        for (int r = 1; r <= k; ++r) cnt[r] += cnt[r - 1];
        for (int r = 0; r <= k; ++r) bestSecond[r] = std::max(bestSecond[r], cnt[r]);
    }

    std::vector<int> result(n);
    std::vector<int> dist1(n);
    for (int i = 0; i < n; ++i) {
        std::fill(dist1.begin(), dist1.end(), -1);
        std::queue<int> q;
        dist1[i] = 0;
        q.push(i);
        int countFirst = 0;
        int maxAdd = 0;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            int d = dist1[u];
            if (d <= k) ++countFirst;
            int R = k - d - 1;
            if (R >= 0) maxAdd = std::max(maxAdd, bestSecond[R]);
            if (d == k) continue;
            for (int v : adj1[u]) {
                if (dist1[v] == -1) {
                    dist1[v] = d + 1;
                    q.push(v);
                }
            }
        }
        result[i] = countFirst + maxAdd;
    }
    return result;
}

