long long minCostTransform(long long n, long long m) {
    std::string nStr = std::to_string(n);
    std::string mStr = std::to_string(m);
    int L = static_cast<int>(nStr.length());
    if (static_cast<int>(mStr.length()) != L) return -1;
    int maxVal = 1;
    for (int i = 0; i < L; ++i) maxVal *= 10;
    maxVal -= 1;

    std::vector<char> isPrime(maxVal + 1, true);
    if (maxVal >= 0) isPrime[0] = false;
    if (maxVal >= 1) isPrime[1] = false;
    for (int i = 2; i * i <= maxVal; ++i) {
        if (isPrime[i]) {
            for (int j = i * i; j <= maxVal; j += i) {
                isPrime[j] = false;
            }
        }
    }

    int nInt = static_cast<int>(n);
    int mInt = static_cast<int>(m);
    if (isPrime[nInt] || isPrime[mInt]) return -1;
    if (nInt == mInt) return n;

    const long long INF = LLONG_MAX / 4;
    std::vector<long long> dist(maxVal + 1, INF);
    dist[nInt] = n;
    using P = std::pair<long long, int>;
    std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
    pq.push({dist[nInt], nInt});

    while (!pq.empty()) {
        long long curCost = pq.top().first;
        int u = pq.top().second;
        pq.pop();
        if (curCost != dist[u]) continue;
        if (u == mInt) return curCost;

        std::string s = std::to_string(u);
        if (static_cast<int>(s.length()) < L) s = std::string(L - s.length(), '0') + s;

        for (int i = 0; i < L; ++i) {
            int digit = s[i] - '0';

            if (digit > 0) {
                std::string ns = s;
                ns[i] = static_cast<char>('0' + digit - 1);
                int v = std::stoi(ns);
                if (!isPrime[v] && dist[v] > curCost + v) {
                    dist[v] = curCost + v;
                    pq.push({dist[v], v});
                }
            }

            if (digit < 9) {
                std::string ns = s;
                ns[i] = static_cast<char>('0' + digit + 1);
                int v = std::stoi(ns);
                if (!isPrime[v] && dist[v] > curCost + v) {
                    dist[v] = curCost + v;
                    pq.push({dist[v], v});
                }
            }
        }
    }

    return -1;
}

