struct DSU {
    std::vector<int> parent;
    std::vector<int> rank;
    DSU(int n) : parent(n), rank(n, 0) {
        for (int i = 0; i < n; ++i) parent[i] = i;
    }
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    void unite(int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return;
        if (rank[ra] < rank[rb]) std::swap(ra, rb);
        parent[rb] = ra;
        if (rank[ra] == rank[rb]) ++rank[ra];
    }
};

int countComponents(std::vector<int>& nums, int threshold) {
    int n = static_cast<int>(nums.size());
    DSU dsu(n);
    std::vector<int> rep(threshold + 1, -1);
    for (int i = 0; i < n; ++i) {
        int val = nums[i];
        if (val > threshold) continue;
        for (int mult = val; mult <= threshold; mult += val) {
            if (rep[mult] == -1) {
                rep[mult] = i;
            } else {
                dsu.unite(i, rep[mult]);
            }
        }
    }
    std::unordered_set<int> components;
    for (int i = 0; i < n; ++i) {
        components.insert(dsu.find(i));
    }
    return static_cast<int>(components.size());
}

