std::vector<int> maxTargetCount(const std::vector<std::vector<int>>& edges1, const std::vector<std::vector<int>>& edges2) {
    int n = static_cast<int>(edges1.size()) + 1;
    int m = static_cast<int>(edges2.size()) + 1;

    std::vector<std::vector<int>> adj1(n);
    for (const auto& e : edges1) {
        int u = e[0], v = e[1];
        adj1[u].push_back(v);
        adj1[v].push_back(u);
    }
    std::vector<std::vector<int>> adj2(m);
    for (const auto& e : edges2) {
        int u = e[0], v = e[1];
        adj2[u].push_back(v);
        adj2[v].push_back(u);
    }

    std::vector<int> color1(n, -1), color2(m, -1);
    std::queue<int> q;

    color1[0] = 0;
    q.push(0);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (int nb : adj1[v]) {
            if (color1[nb] == -1) {
                color1[nb] = color1[v] ^ 1;
                q.push(nb);
            }
        }
    }

    color2[0] = 0;
    q.push(0);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (int nb : adj2[v]) {
            if (color2[nb] == -1) {
                color2[nb] = color2[v] ^ 1;
                q.push(nb);
            }
        }
    }

    long long cnt1_0 = 0, cnt1_1 = 0;
    for (int c : color1) {
        if (c == 0) ++cnt1_0;
        else ++cnt1_1;
    }
    long long cnt2_0 = 0, cnt2_1 = 0;
    for (int c : color2) {
        if (c == 0) ++cnt2_0;
        else ++cnt2_1;
    }

    long long add = cnt2_0 > cnt2_1 ? cnt2_0 : cnt2_1;
    std::vector<int> answer(n);
    for (int i = 0; i < n; ++i) {
        long long base = (color1[i] == 0) ? cnt1_0 : cnt1_1;
        answer[i] = static_cast<int>(base + add);
    }
    return answer;
}

