long long maxSubarraySumDivisibleByK(const std::vector<int>& nums, int k) {
    long long prefix = 0;
    long long answer = std::numeric_limits<long long>::lowest();
    const long long INF = std::numeric_limits<long long>::max();
    std::vector<long long> minPrefix(k, INF);
    minPrefix[0] = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        prefix += nums[i];
        int r = static_cast<int>((i + 1) % static_cast<size_t>(k));
        if (minPrefix[r] != INF) {
            answer = std::max(answer, prefix - minPrefix[r]);
        }
        if (prefix < minPrefix[r]) {
            minPrefix[r] = prefix;
        }
    }
    return answer;
}

#include <bits/stdc++.h>

int maxAreaRectangle(const std::vector<std::vector<int>>& points) {
    int n = static_cast<int>(points.size());
    if (n < 4) return -1;
    std::unordered_set<std::uint64_t> pointSet;
    pointSet.reserve(n * 2);
    std::vector<int> xs, ys;
    xs.reserve(n);
    ys.reserve(n);
    for (const auto& p : points) {
        int x = p[0], y = p[1];
        xs.push_back(x);
        ys.push_back(y);
        std::uint64_t key = (static_cast<std::uint64_t>(static_cast<std::uint32_t>(x)) << 32) |
                            static_cast<std::uint64_t>(static_cast<std::uint32_t>(y));
        pointSet.insert(key);
    }
    std::sort(xs.begin(), xs.end());
    xs.erase(std::unique(xs.begin(), xs.end()), xs.end());
    std::sort(ys.begin(), ys.end());
    ys.erase(std::unique(ys.begin(), ys.end()), ys.end());
    int nx = static_cast<int>(xs.size());
    int ny = static_cast<int>(ys.size());
    std::unordered_map<int, int> xIdx, yIdx;
    xIdx.reserve(nx * 2);
    yIdx.reserve(ny * 2);
    for (int i = 0; i < nx; ++i) xIdx[xs[i]] = i + 1;
    for (int i = 0; i < ny; ++i) yIdx[ys[i]] = i + 1;
    struct Fenwick2D {
        int n, m;
        std::vector<std::vector<int>> bit;
        Fenwick2D(int n_, int m_) : n(n_), m(m_), bit(n_ + 1, std::vector<int>(m_ + 1, 0)) {}
        void add(int x, int y, int delta) {
            for (int i = x; i <= n; i += i & -i)
                for (int j = y; j <= m; j += j & -j)
                    bit[i][j] += delta;
        }
        int sum(int x, int y) const {
            int res = 0;
            for (int i = x; i > 0; i -= i & -i)
                for (int j = y; j > 0; j -= j & -j)
                    res += bit[i][j];
            return res;
        }
        int rangeSum(int x1, int y1, int x2, int y2) const {
            if (x1 > x2 || y1 > y2) return 0;
            return sum(x2, y2) - sum(x1 - 1, y2) - sum(x2, y1 - 1) + sum(x1 - 1, y1 - 1);
        }
    };
    Fenwick2D bit(nx, ny);
    for (const auto& p : points) {
        int cx = xIdx[p[0]];
        int cy = yIdx[p[1]];
        bit.add(cx, cy, 1);
    }
    int best = -1;
    for (int i = 0; i < n; ++i) {
        int x1 = points[i][0];
        int y1 = points[i][1];
        for (int j = i + 1; j < n; ++j) {
            int x2 = points[j][0];
            int y2 = points[j][1];
            if (x1 == x2 || y1 == y2) continue;
            std::uint64_t key1 = (static_cast<std::uint64_t>(static_cast<std::uint32_t>(x1)) << 32) |
                                 static_cast<std::uint64_t>(static_cast<std::uint32_t>(y2));
            std::uint64_t key2 = (static_cast<std::uint64_t>(static_cast<std::uint32_t>(x2)) << 32) |
                                 static_cast<std::uint64_t>(static_cast<std::uint32_t>(y1));
            if (pointSet.find(key1) == pointSet.end() || pointSet.find(key2) == pointSet.end())
                continue;
            int cx1 = xIdx[x1];
            int cx2 = xIdx[x2];
            int cy1 = yIdx[y1];
            int cy2 = yIdx[y2];
            int minCx = std::min(cx1, cx2);
            int maxCx = std::max(cx1, cx2);
            int minCy = std::min(cy1, cy2);
            int maxCy = std::max(cy1, cy2);
            int total = bit.rangeSum(minCx, minCy, maxCx, maxCy);
            if (total - 4 != 0) continue;
            int area = (std::max(x1, x2) - std::min(x1, x2)) * (std::max(y1, y2) - std::min(y1, y2));
            if (area > best) best = area;
        }
    }
    return best;
}

