static inline std::int64_t encodePoint(int x, int y) {
    return (static_cast<std::int64_t>(static_cast<std::uint32_t>(x)) << 32) |
           static_cast<std::uint32_t>(y);
}

int maxArea(const std::vector<int>& xCoord, const std::vector<int>& yCoord) {
    std::size_t n = xCoord.size();
    std::unordered_set<std::int64_t> pointSet;
    pointSet.reserve(n * 2);
    pointSet.max_load_factor(0.7);
    for (std::size_t i = 0; i < n; ++i) {
        pointSet.insert(encodePoint(xCoord[i], yCoord[i]));
    }

    int bestArea = -1;
    for (std::size_t i = 0; i < n; ++i) {
        for (std::size_t j = i + 1; j < n; ++j) {
            int x1 = xCoord[i];
            int y1 = yCoord[i];
            int x2 = xCoord[j];
            int y2 = yCoord[j];
            if (x1 == x2 || y1 == y2) continue;

            std::int64_t p12 = encodePoint(x1, y2);
            std::int64_t p21 = encodePoint(x2, y1);
            if (pointSet.find(p12) == pointSet.end() || pointSet.find(p21) == pointSet.end())
                continue;

            int xLow = std::min(x1, x2);
            int xHigh = std::max(x1, x2);
            int yLow = std::min(y1, y2);
            int yHigh = std::max(y1, y2);

            bool ok = true;
            for (std::size_t k = 0; k < n; ++k) {
                int xp = xCoord[k];
                int yp = yCoord[k];
                if (xp < xLow || xp > xHigh || yp < yLow || yp > yHigh) continue;
                if ((xp == x1 && yp == y1) || (xp == x2 && yp == y2) ||
                    (xp == x1 && yp == y2) || (xp == x2 && yp == y1))
                    continue;
                ok = false;
                break;
            }
            if (!ok) continue;

            int area = (xHigh - xLow) * (yHigh - yLow);
            if (area > bestArea) bestArea = area;
        }
    }
    return bestArea;
}

