int minOperationsToMakeGood(const std::string& s) {
    int n = static_cast<int>(s.size());
    std::vector<int> freq(26, 0);
    for (char c : s) ++freq[c - 'a'];
    std::sort(freq.begin(), freq.end(), std::greater<int>());
    std::vector<int> pref(27, 0);
    for (int i = 0; i < 26; ++i) pref[i + 1] = pref[i] + freq[i];
    int best = n;
    for (int k = 1; k <= 26 && k <= n; ++k) {
        int sumTop = pref[k];
        int extra = n - sumTop;
        int maxF = n / k;
        for (int f = 1; f <= maxF; ++f) {
            int surplus = extra;
            int deficit = 0;
            for (int i = 0; i < k; ++i) {
                if (freq[i] > f) surplus += freq[i] - f;
                else deficit += f - freq[i];
            }
            int ops = surplus > deficit ? surplus : deficit;
            if (ops < best) best = ops;
        }
    }
    return best;
}

