int longestPushButton(const std::vector<std::vector<int>>& events) {
    int prevTime = 0;
    int bestIndex = -1;
    int bestDuration = -1;
    for (size_t i = 0; i < events.size(); ++i) {
        int idx = events[i][0];
        int curTime = events[i][1];
        int duration = curTime - prevTime;
        if (duration > bestDuration) {
            bestDuration = duration;
            bestIndex = idx;
        } else if (duration == bestDuration && idx < bestIndex) {
            bestIndex = idx;
        }
        prevTime = curTime;
    }
    return bestIndex;
}

