int countBeautifulSplits(const std::vector<int>& nums) {
    std::size_t n = nums.size();
    if (n < 2) return 0;
    std::vector<int> suffixMin(n);
    int curMin = nums[n - 1];
    for (std::size_t i = n; i-- > 0;) {
        curMin = std::min(curMin, nums[i]);
        suffixMin[i] = curMin;
    }
    int count = 0;
    int curMax = nums[0];
    for (std::size_t i = 0; i + 1 < n; ++i) {
        curMax = std::max(curMax, nums[i]);
        if (curMax == suffixMin[i + 1]) ++count;
    }
    return count;
}

#include <bits/stdc++.h>
bool isPossibleToCut(int n, std::vector<std::vector<int>>& rectangles) {
    using pii = std::pair<int,int>;
    std::vector<pii> vertIntervals, horizIntervals;
    std::vector<int> candX, candY;
    vertIntervals.reserve(rectangles.size());
    horizIntervals.reserve(rectangles.size());
    candX.reserve(rectangles.size()*2);
    candY.reserve(rectangles.size()*2);
    for (auto &r : rectangles) {
        int x1 = r[0], y1 = r[1], x2 = r[2], y2 = r[3];
        vertIntervals.emplace_back(x1, x2);
        horizIntervals.emplace_back(y1, y2);
        if (x1 > 0 && x1 < n) candX.push_back(x1);
        if (x2 > 0 && x2 < n) candX.push_back(x2);
        if (y1 > 0 && y1 < n) candY.push_back(y1);
        if (y2 > 0 && y2 < n) candY.push_back(y2);
    }
    auto countFree = [&](std::vector<int> cand, const std::vector<pii>& intervals)->int{
        std::sort(cand.begin(), cand.end());
        cand.erase(std::unique(cand.begin(), cand.end()), cand.end());
        std::vector<pii> iv = intervals;
        std::sort(iv.begin(), iv.end(), [](const pii& a, const pii& b){return a.first < b.first;});
        std::priority_queue<int, std::vector<int>, std::greater<int>> pq;
        size_t idx = 0;
        int freeCnt = 0;
        for (int c : cand) {
            while (idx < iv.size() && iv[idx].first < c) {
                pq.push(iv[idx].second);
                ++idx;
            }
            while (!pq.empty() && pq.top() <= c) pq.pop();
            if (pq.empty()) ++freeCnt;
        }
        return freeCnt;
    };
    if (countFree(candX, vertIntervals) >= 2) return true;
    if (countFree(candY, horizIntervals) >= 2) return true;
    return false;
}

