class Solution {
public:
    int subsequencesWithMiddleMode(vector<int>& nums) {
        const int n = nums.size();
        long ans = 0;
        unordered_map<int,int> left, right;
        for (int i = 0; i < 2; ++i) ++left[nums[i]];
        for (int i = 2; i < n; ++i) ++right[nums[i]];
        for (int i = 2; i < n - 2; ++i) {
            const int num = nums[i];
            if (--right[num] == 0) right.erase(num);
            const int leftCount = left[num];
            const int rightCount = right[num];
            const int leftOther = i - leftCount;
            const int rightOther = n - 1 - i - rightCount;
            ans += nC2(leftCount) * nC2(rightCount); ans %= kMod;
            ans += nC2(leftCount) * rightCount % kMod * rightOther % kMod; ans %= kMod;
            ans += leftCount * leftOther % kMod * nC2(rightCount) % kMod; ans %= kMod;
            ans += nC2(leftCount) * nC2(rightOther) % kMod; ans %= kMod;
            ans += nC2(leftOther) * nC2(rightCount) % kMod; ans %= kMod;
            ans += leftCount * leftOther % kMod * rightCount % kMod * rightOther % kMod; ans %= kMod;
            ans += leftCount * calc(num, leftOther, rightOther, left, right) % kMod; ans %= kMod;
            ans += rightCount * calc(num, rightOther, leftOther, right, left) % kMod; ans %= kMod;
            ++left[num];
        }
        return ans % kMod;
    }
private:
    static constexpr int kMod = 1'000'000'007;
    long nC2(long n) { return n * (n - 1) / 2 % kMod; }
    long calc(int a, long other1, long other2, const unordered_map<int,int>& count1, const unordered_map<int,int>& count2) {
        long res = other1 * nC2(other2) % kMod;
        for (const auto& [b, b1] : count1) {
            if (b == a) continue;
            long b2 = count2.count(b) ? count2.at(b) : 0;
            res = (res - b1 * nC2(b2) % kMod + kMod) % kMod;
            res = (res - b1 * b2 % kMod * (other2 - b2) % kMod + kMod) % kMod;
        }
        for (const auto& [b, b2] : count2) {
            if (b == a) continue;
            long b1 = count1.count(b) ? count1.at(b) : 0;
            res = (res - (other1 - b1) * nC2(b2) % kMod + kMod) % kMod;
        }
        return res;
    }
};

#include <bits/stdc++.h>

int count_paths_xor(const std::vector<std::vector<int>>& grid, int k) {
    const int MOD = 1000000007;
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    int totalSteps = m + n - 2;
    int mid = totalSteps / 2;
    int stepsBack = totalSteps - mid;

    std::vector<std::unordered_map<int, int>> forward(m * n);
    std::function<void(int, int, int, int)> dfs_f = [&](int i, int j, int xr, int steps) {
        if (steps == mid) {
            auto &mp = forward[i * n + j];
            mp[xr] = (mp[xr] + 1) % MOD;
            return;
        }
        if (i + 1 < m) dfs_f(i + 1, j, xr ^ grid[i + 1][j], steps + 1);
        if (j + 1 < n) dfs_f(i, j + 1, xr ^ grid[i][j + 1], steps + 1);
    };
    dfs_f(0, 0, grid[0][0], 0);

    std::vector<std::unordered_map<int, int>> backward(m * n);
    std::function<void(int, int, int, int)> dfs_b = [&](int i, int j, int xr, int steps) {
        if (steps == stepsBack) {
            auto &mp = backward[i * n + j];
            mp[xr] = (mp[xr] + 1) % MOD;
            return;
        }
        if (i - 1 >= 0) dfs_b(i - 1, j, xr ^ grid[i - 1][j], steps + 1);
        if (j - 1 >= 0) dfs_b(i, j - 1, xr ^ grid[i][j - 1], steps + 1);
    };
    dfs_b(m - 1, n - 1, grid[m - 1][n - 1], 0);

    long long ans = 0;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i + j != mid) continue;
            const auto &fmap = forward[i * n + j];
            const auto &bmap = backward[i * n + j];
            for (const auto &p : fmap) {
                int xor_f = p.first;
                int cnt_f = p.second;
                int need = xor_f ^ k ^ grid[i][j];
                auto it = bmap.find(need);
                if (it != bmap.end()) {
                    ans = (ans + static_cast<long long>(cnt_f) * it->second) % MOD;
                }
            }
        }
    }
    return static_cast<int>(ans);
}

