int smallestSubstring(const std::string& s, int numOps) {
    int n = static_cast<int>(s.size());
    std::vector<int> runs;
    runs.reserve(n);
    for (int i = 0; i < n; ) {
        int j = i + 1;
        while (j < n && s[j] == s[i]) ++j;
        runs.push_back(j - i);
        i = j;
    }
    int lo = 1, hi = n, ans = n;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        long long needed = 0;
        for (int len : runs) {
            needed += len / (mid + 1);
            if (needed > numOps) break;
        }
        if (needed <= numOps) {
            ans = mid;
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }
    return ans;
}

