long long minOperations(const std::vector<std::vector<int>>& grid) {
    if (grid.empty() || grid[0].empty()) {
        return 0;
    }
    std::size_t m = grid.size();
    std::size_t n = grid[0].size();
    long long total = 0;
    for (std::size_t col = 0; col < n; ++col) {
        long long prev = grid[0][col];
        for (std::size_t row = 1; row < m; ++row) {
            long long required = prev + 1;
            long long cur = grid[row][col];
            if (cur < required) {
                total += required - cur;
                prev = required;
            } else {
                prev = cur;
            }
        }
    }
    return total;
}

