int maxDistinctElements(std::vector<int> nums, int k) {
    std::sort(nums.begin(), nums.end());
    std::int64_t last = -(1LL << 60);
    int distinct = 0;
    for (int a : nums) {
        std::int64_t left = static_cast<std::int64_t>(a) - k;
        std::int64_t right = static_cast<std::int64_t>(a) + k;
        std::int64_t candidate = left > last + 1 ? left : last + 1;
        if (candidate <= right) {
            ++distinct;
            last = candidate;
        }
    }
    return distinct;
}

