int smallestLongestSubstring(const std::string& s, int numOps) {
    int n = static_cast<int>(s.size());
    if (n == 0) return 0;

    auto can = [&](int limit) -> bool {
        int flips = 0;
        char cur = s[0];
        int run = 1;
        for (int i = 1; i < n; ++i) {
            char ch = s[i];
            if (ch == cur) {
                ++run;
            } else {
                cur = ch;
                run = 1;
            }
            if (run > limit) {
                ++flips;
                cur = (cur == '0' ? '1' : '0');
                run = 1;
                if (flips > numOps) return false;
            }
        }
        return flips <= numOps;
    };

    int low = 1, high = n, ans = n;
    while (low <= high) {
        int mid = (low + high) >> 1;
        if (can(mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
}

