class Solution {
public:
    long long numberOfSubsequences(vector<int>& nums) {
        int n = nums.size();
        // suffix[i]: frequency map of nums[i..n-1]
        vector<unordered_map<int,int>> suffix(n + 1);
        for (int i = n - 1; i >= 0; i--) {
            suffix[i] = suffix[i + 1];
            suffix[i][nums[i]]++;
        }
        // leftCount lags behind q by one step: when processing q, it holds frequencies for p in [0, q-2]
        unordered_map<int,int> leftCount;
        long long ans = 0;
        for (int q = 0; q < n; q++) {
            for (int r = q + 2; r < n; r++) {
                auto& rightCount = (r + 2 <= n) ? suffix[r + 2] : suffix[n];
                long long a = nums[q], b = nums[r];
                // condition: nums[p]*nums[r] == nums[q]*nums[s]  =>  s-value = v*b/a for each left value v
                for (auto& [v, cntV] : leftCount) {
                    long long num = (long long) v * b;
                    if (num % a == 0) {
                        long long target = num / a;
                        auto it = rightCount.find((int) target);
                        if (it != rightCount.end()) ans += (long long) cntV * it->second;
                    }
                }
            }
            int idx = q - 1;
            if (idx >= 0) leftCount[nums[idx]]++;
        }
        return ans;
    }
};

