const long long MOD = 1000000007LL;

static long long modPow(long long a, long long e) {
    long long res = 1 % MOD;
    a %= MOD;
    while (e) {
        if (e & 1) res = res * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return res;
}

long long countArrays(int n, int m, int k) {
    if (k < 0 || k > n - 1) return 0;
    int N = n - 1;
    int r = k;
    if (r > N - r) r = N - r;
    std::vector<long long> inv(r + 2);
    if (r >= 1) {
        inv[1] = 1;
        for (int i = 2; i <= r; ++i) {
            inv[i] = MOD - (MOD / i) * inv[MOD % i] % MOD;
        }
    }
    long long comb = 1;
    for (int i = 1; i <= r; ++i) {
        comb = comb * (N - r + i) % MOD;
        comb = comb * inv[i] % MOD;
    }
    long long ways = (static_cast<long long>(m) % MOD) * modPow(m - 1, n - k - 1) % MOD;
    return comb * ways % MOD;
}

