class TaskManager {
public:
    struct Node { int priority, taskId; };
    std::vector<Node> heap;
    std::unordered_map<int, std::pair<int,int>> info;
    static bool less_(const Node& a, const Node& b) {
        if (a.priority != b.priority) return a.priority > b.priority;
        return a.taskId > b.taskId;
    }
    void push(Node node) {
        heap.push_back(node);
        int i = (int)heap.size()-1;
        while (i > 0) {
            int p = (i-1)>>1;
            if (!less_(heap[i], heap[p])) break;
            std::swap(heap[i], heap[p]); i = p;
        }
    }
    Node pop() {
        Node top = heap[0];
        Node last = heap.back(); heap.pop_back();
        if (!heap.empty()) {
            heap[0] = last;
            int i = 0, n = (int)heap.size();
            while (true) {
                int l=i*2+1,r=i*2+2,best=i;
                if (l<n && less_(heap[l],heap[best])) best=l;
                if (r<n && less_(heap[r],heap[best])) best=r;
                if (best==i) break;
                std::swap(heap[i],heap[best]); i=best;
            }
        }
        return top;
    }
    TaskManager(std::vector<std::array<int,3>>& tasks) {
        for (auto& t : tasks) { info[t[1]] = {t[0], t[2]}; push({t[2], t[1]}); }
    }
    void add(int userId, int taskId, int priority) {
        info[taskId] = {userId, priority};
        push({priority, taskId});
    }
    void edit(int taskId, int newPriority) {
        auto it = info.find(taskId);
        if (it != info.end()) { it->second.second = newPriority; push({newPriority, taskId}); }
    }
    void rmv(int taskId) { info.erase(taskId); }
    int execTop() {
        while (!heap.empty()) {
            Node top = pop();
            auto it = info.find(top.taskId);
            if (it != info.end() && it->second.second == top.priority) {
                int userId = it->second.first;
                info.erase(it);
                return userId;
            }
        }
        return -1;
    }
};

#include <bits/stdc++.h>
int maximumSum(std::vector<int> nums) {
    long long best = LLONG_MIN;
    // Kadane without any deletion
    long long cur = 0;
    for (int x : nums) {
        cur = std::max<long long>(x, cur + x);
        best = std::max(best, cur);
    }
    // collect distinct values
    std::unordered_set<int> distinct;
    for (int x : nums) distinct.insert(x);
    // evaluate each possible value to delete
    for (int v : distinct) {
        long long cur2 = 0;
        long long best2 = LLONG_MIN;
        for (int x : nums) {
            long long val = (x == v) ? 0 : x;
            cur2 = std::max<long long>(val, cur2 + val);
            best2 = std::max(best2, cur2);
        }
        best = std::max(best, best2);
    }
    return static_cast<int>(best);
}

#include <bits/stdc++.h>

long long maxCoins(const std::vector<std::vector<int>>& coins, int k) {
    struct Seg { long long l, r, c; };
    std::vector<Seg> segs;
    segs.reserve(coins.size());
    for (const auto& v : coins) segs.push_back({v[0], v[1], v[2]});
    std::sort(segs.begin(), segs.end(), [](const Seg& a, const Seg& b){ return a.l < b.l; });
    int n = segs.size();
    std::vector<long long> L(n), R(n), C(n), pref(n);
    for (int i = 0; i < n; ++i) {
        L[i] = segs[i].l;
        R[i] = segs[i].r;
        C[i] = segs[i].c;
        long long cur = (R[i] - L[i] + 1) * C[i];
        pref[i] = cur + (i ? pref[i - 1] : 0);
    }
    auto getPrefix = [&](long long pos) -> long long {
        if (pos < L[0]) return 0;
        int idx = int(std::upper_bound(L.begin(), L.end(), pos) - L.begin()) - 1;
        if (pos > R[idx]) return pref[idx];
        long long before = (idx ? pref[idx - 1] : 0);
        long long cnt = pos - L[idx] + 1;
        return before + cnt * C[idx];
    };
    long long best = 0;
    std::vector<long long> candidates;
    candidates.reserve(2 * n);
    for (int i = 0; i < n; ++i) {
        candidates.push_back(L[i]);
        long long s2 = R[i] - static_cast<long long>(k) + 1;
        if (s2 < 1) s2 = 1;
        candidates.push_back(s2);
    }
    for (long long s : candidates) {
        if (s < 1) s = 1;
        long long e = s + static_cast<long long>(k) - 1;
        long long sum = getPrefix(e) - getPrefix(s - 1);
        if (sum > best) best = sum;
    }
    return best;
}

#include <bits/stdc++.h>

int longestSubarray(std::vector<int>& nums) {
    const int primes[4] = {2, 3, 5, 7};
    int n = static_cast<int>(nums.size());
    std::vector<std::array<int,4>> exp(n);
    for (int i = 0; i < n; ++i) {
        int x = nums[i];
        for (int j = 0; j < 4; ++j) {
            int p = primes[j];
            int cnt = 0;
            while (x % p == 0) {
                ++cnt;
                x /= p;
            }
            exp[i][j] = cnt;
        }
    }

    int best = 0;
    for (int l = 0; l < n; ++l) {
        std::array<int,4> sum = {0,0,0,0};
        std::array<int,4> mx  = {0,0,0,0};
        std::array<int,4> mn  = {100,100,100,100};
        for (int r = l; r < n; ++r) {
            for (int j = 0; j < 4; ++j) {
                int e = exp[r][j];
                sum[j] += e;
                mx[j] = std::max(mx[j], e);
                mn[j] = std::min(mn[j], e);
            }
            bool ok = true;
            for (int j = 0; j < 4; ++j) {
                if (sum[j] != mx[j] + mn[j]) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                best = std::max(best, r - l + 1);
            }
        }
    }
    return best;
}

