long long mirrorScore(const std::string& s) {
    std::array<std::vector<std::size_t>, 26> waiting;
    long long total = 0;
    for (std::size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        char m = 'z' - (c - 'a');
        std::size_t idxM = static_cast<std::size_t>(m - 'a');
        if (!waiting[idxM].empty()) {
            std::size_t p = waiting[idxM].back();
            waiting[idxM].pop_back();
            total += static_cast<long long>(i - p);
        } else {
            waiting[static_cast<std::size_t>(c - 'a')].push_back(i);
        }
    }
    return total;
}

