std::vector<int> maxScore(std::vector<std::vector<int>>& intervals) {
    int n = intervals.size();
    struct Interval {
        long long l, r, w;
        int idx;
    };
    std::vector<Interval> arr;
    arr.reserve(n);
    for (int i = 0; i < n; ++i) {
        arr.push_back({intervals[i][0], intervals[i][1], intervals[i][2], i});
    }
    std::sort(arr.begin(), arr.end(), [](const Interval& a, const Interval& b) {
        if (a.l != b.l) return a.l < b.l;
        return a.r < b.r;
    });
    std::vector<long long> starts(n);
    for (int i = 0; i < n; ++i) starts[i] = arr[i].l;
    std::vector<int> nxt(n);
    for (int i = 0; i < n; ++i) {
        long long target = arr[i].r + 1;
        nxt[i] = std::lower_bound(starts.begin(), starts.end(), target) - starts.begin();
    }
    const int K = 4;
    std::vector<std::array<long long, K + 1>> dp(n + 1);
    for (int c = 0; c <= K; ++c) dp[n][c] = 0;
    std::vector<std::array<char, K + 1>> take(n);
    for (int i = n - 1; i >= 0; --i) {
        for (int c = 0; c <= K; ++c) {
            long long best = dp[i + 1][c];
            char flag = 0;
            if (c > 0) {
                long long cand = dp[nxt[i]][c - 1] + arr[i].w;
                if (cand > best) {
                    best = cand;
                    flag = 1;
                }
            }
            dp[i][c] = best;
            take[i][c] = flag;
        }
    }
    std::vector<int> result;
    int i = 0, c = K;
    while (i < n && c > 0) {
        if (take[i][c]) {
            result.push_back(arr[i].idx);
            i = nxt[i];
            --c;
        } else {
            ++i;
        }
    }
    std::sort(result.begin(), result.end());
    return result;
}

