bool feasible(vector<vector<pair<int,int>>>& rev, int n, int W) {
    vector<bool> visited(n, false);
    visited[0] = true;
    queue<int> q;
    q.push(0);
    int count = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (auto& [v, w] : rev[u]) {
            if (w <= W && !visited[v]) {
                visited[v] = true;
                count++;
                q.push(v);
            }
        }
    }
    return count == n;
}

int minMaxWeight(int n, vector<vector<int>>& edges, int threshold) {
    vector<vector<pair<int,int>>> rev(n);
    int maxW = 0;
    for (auto& e : edges) {
        rev[e[1]].push_back({e[0], e[2]});
        maxW = max(maxW, e[2]);
    }
    if (!feasible(rev, n, maxW)) return -1;
    int lo = 1, hi = maxW;
    while (lo < hi) {
        int mid = lo + (hi-lo)/2;
        if (feasible(rev, n, mid)) hi = mid; else lo = mid+1;
    }
    return lo;
}

