std::vector<int> zigzagGridTraversal(const std::vector<std::vector<int>>& grid) {
    if (grid.empty() || grid[0].empty()) return {};
    int rows = static_cast<int>(grid.size());
    int cols = static_cast<int>(grid[0].size());
    std::vector<int> result;
    result.reserve((rows * cols + 1) / 2);
    bool take = true;
    for (int r = 0; r < rows; ++r) {
        if (r % 2 == 0) {
            for (int c = 0; c < cols; ++c) {
                if (take) result.push_back(grid[r][c]);
                take = !take;
            }
        } else {
            for (int c = cols - 1; c >= 0; --c) {
                if (take) result.push_back(grid[r][c]);
                take = !take;
            }
        }
    }
    return result;
}

