long long maxProfit(const vector<vector<int>>& coins) {
    int m = coins.size();
    int n = coins[0].size();
    const long long NEG = numeric_limits<long long>::min() / 4;
    vector<vector<array<long long, 3>>> dp(m, vector<array<long long, 3>>(n, {NEG, NEG, NEG}));
    dp[0][0][0] = coins[0][0];
    dp[0][0][1] = 0; // skip the first cell
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i == 0 && j == 0) continue;
            auto update = [&](int pi, int pj) {
                for (int s = 0; s <= 2; ++s) {
                    long long prev = dp[pi][pj][s];
                    if (prev == NEG) continue;
                    // take the cell value
                    dp[i][j][s] = max(dp[i][j][s], prev + coins[i][j]);
                    // skip this cell if possible
                    if (s < 2) {
                        dp[i][j][s + 1] = max(dp[i][j][s + 1], prev);
                    }
                }
            };
            if (i > 0) update(i - 1, j);
            if (j > 0) update(i, j - 1);
        }
    }
    long long ans = NEG;
    for (int k = 0; k <= 2; ++k) ans = max(ans, dp[m - 1][n - 1][k]);
    return ans;
}

