static const long long MOD = 1000000007LL;

static long long modPow(long long base, long long exp) {
    long long res = 1;
    long long b = base % MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * b) % MOD;
        b = (b * b) % MOD;
        exp >>= 1;
    }
    return res;
}

static long long modInv(long long x) {
    return modPow(x, MOD - 2);
}

long long sumMaxMinSubseq(const vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;
    vector<int> sorted(nums);
    sort(sorted.begin(), sorted.end());

    vector<long long> fact(n + 1), invFact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i % MOD;
    invFact[n] = modInv(fact[n]);
    for (int i = n - 1; i >= 0; --i) invFact[i] = invFact[i + 1] * (i + 1) % MOD;

    auto comb = [&](int m, int r) -> long long {
        if (r < 0 || r > m) return 0;
        return fact[m] * invFact[r] % MOD * invFact[m - r] % MOD;
    };

    vector<long long> pref(n);
    pref[0] = 1; // C(0,0)
    for (int i = 1; i < n; ++i) {
        long long sub = (i - 1 >= k - 1) ? comb(i - 1, k - 1) : 0;
        pref[i] = (2 * pref[i - 1] % MOD - sub + MOD) % MOD;
    }

    long long ans = 0;
    int maxChoose = k - 1;
    for (int i = 0; i < n; ++i) {
        long long waysMax = pref[i];
        long long waysMin = pref[n - 1 - i];
        long long val = sorted[i] % MOD;
        long long contrib = val * ((waysMax + waysMin) % MOD) % MOD;
        ans += contrib;
        if (ans >= MOD) ans -= MOD;
    }
    return ans;
}

