std::vector<long long> longestSpecialPath(const std::vector<std::vector<int>>& edges, const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    std::vector<std::vector<std::pair<int,int>>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1], w = e[2];
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }
    std::vector<long long> prefDepth(n, 0);
    std::unordered_map<int,int> lastPos;
    long long bestLen = 0;
    int bestNodes = n + 1;

    struct Frame {
        int u;
        int parent;
        int depth;
        long long curPref;
        int curLeft;
        int childIdx;
        int prevDepth;
        bool had;
        int newLeft;
    };

    std::vector<Frame> stack;
    stack.reserve(n);
    stack.push_back({0, -1, 0, 0LL, 0, -1, -1, false, 0});

    while (!stack.empty()) {
        Frame &f = stack.back();
        if (f.childIdx == -1) {
            int val = nums[f.u];
            auto it = lastPos.find(val);
            f.prevDepth = (it != lastPos.end()) ? it->second : -1;
            f.had = (f.prevDepth != -1);
            f.newLeft = f.curLeft;
            if (f.prevDepth != -1) f.newLeft = std::max(f.newLeft, f.prevDepth + 1);
            prefDepth[f.depth] = f.curPref;
            long long segLen = f.curPref - (f.newLeft == 0 ? 0LL : prefDepth[f.newLeft]);
            int nodeCnt = f.depth - f.newLeft + 1;
            if (segLen > bestLen) {
                bestLen = segLen;
                bestNodes = nodeCnt;
            } else if (segLen == bestLen && nodeCnt < bestNodes) {
                bestNodes = nodeCnt;
            }
            lastPos[val] = f.depth;
            f.childIdx = 0;
        }
        if (f.childIdx < static_cast<int>(adj[f.u].size())) {
            std::pair<int,int> edge = adj[f.u][f.childIdx++];
            int v = edge.first;
            int w = edge.second;
            if (v == f.parent) continue;
            stack.push_back({v, f.u, f.depth + 1, f.curPref + w, f.newLeft, -1, -1, false, 0});
        } else {
            int val = nums[f.u];
            if (f.had) {
                lastPos[val] = f.prevDepth;
            } else {
                lastPos.erase(val);
            }
            stack.pop_back();
        }
    }

    return {bestLen, static_cast<long long>(bestNodes)};
}

