long long mod = 1000000007LL;

long long modPow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % mod;
        a = a * a % mod;
        e >>= 1;
    }
    return r;
}

int totalManhattan(int m, int n, int k) {
    long long M = m;
    long long N = n;
    long long totalCells = M * N;
    if (k < 2) return 0;
    // factorials
    std::vector<long long> fact(totalCells + 1), invFact(totalCells + 1);
    fact[0] = 1;
    for (long long i = 1; i <= totalCells; ++i) fact[i] = fact[i - 1] * i % mod;
    invFact[totalCells] = modPow(fact[totalCells], mod - 2);
    for (long long i = totalCells; i > 0; --i) invFact[i - 1] = invFact[i] * i % mod;
    long long comb = 0;
    if (k - 2 <= totalCells - 2) {
        comb = fact[totalCells - 2] * invFact[k - 2] % mod * invFact[totalCells - k] % mod;
    }
    long long inv6 = modPow(6, mod - 2);
    long long mMod = M % mod;
    long long nMod = N % mod;
    long long m3 = mMod * mMod % mod * mMod % mod;
    long long n3 = nMod * nMod % mod * nMod % mod;
    long long termRows = ( (m3 - mMod + mod) % mod ) * (nMod * nMod % mod) % mod;
    long long termCols = ( (n3 - nMod + mod) % mod ) * (mMod * mMod % mod) % mod;
    long long total = (termRows + termCols) % mod * inv6 % mod;
    long long ans = comb * total % mod;
    return (int)ans;
}

