long long minCost(int n, const std::vector<std::vector<int>>& cost) {
    const long long INF = 4e18;
    long long answer = INF;
    for (int first = 0; first < 3; ++first) {
        std::vector<long long> prev(3, INF);
        prev[first] = cost[0][first];
        for (int i = 1; i < n; ++i) {
            std::vector<long long> cur(3, INF);
            for (int c = 0; c < 3; ++c) {
                long long best = INF;
                for (int pc = 0; pc < 3; ++pc) {
                    if (pc == c) continue;
                    best = std::min(best, prev[pc]);
                }
                cur[c] = cost[i][c] + best;
            }
            prev.swap(cur);
        }
        for (int last = 0; last < 3; ++last) {
            if (last == first) continue;
            answer = std::min(answer, prev[last]);
        }
    }
    return answer;
}

