long long maxMinSumAtMostK(const std::vector<long long>& nums, int k) {
    int n = static_cast<int>(nums.size());
    std::vector<int> leftGreater(n), rightGreater(n), leftSmaller(n), rightSmaller(n);
    std::vector<int> st;

    for (int i = 0; i < n; ++i) {
        while (!st.empty() && nums[st.back()] <= nums[i]) st.pop_back();
        leftGreater[i] = st.empty() ? -1 : st.back();
        st.push_back(i);
    }
    st.clear();
    for (int i = n - 1; i >= 0; --i) {
        while (!st.empty() && nums[st.back()] < nums[i]) st.pop_back();
        rightGreater[i] = st.empty() ? n : st.back();
        st.push_back(i);
    }
    st.clear();
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && nums[st.back()] >= nums[i]) st.pop_back();
        leftSmaller[i] = st.empty() ? -1 : st.back();
        st.push_back(i);
    }
    st.clear();
    for (int i = n - 1; i >= 0; --i) {
        while (!st.empty() && nums[st.back()] > nums[i]) st.pop_back();
        rightSmaller[i] = st.empty() ? n : st.back();
        st.push_back(i);
    }

    long long S = static_cast<long long>(k) + 1;

    auto countPairs = [&](int L, int R) -> long long {
        long long limit = S - static_cast<long long>(R);
        long long a = 0;
        if (limit > 0) a = std::min<long long>(L, limit);
        long long cnt = a * static_cast<long long>(R);
        long long start = a + 1;
        long long end = std::min<long long>(L, S - 1);
        if (start <= end) {
            long long num = end - start + 1;
            long long sum = num * S - ((start + end) * num) / 2;
            cnt += sum;
        }
        return cnt;
    };

    long long ans = 0;
    for (int i = 0; i < n; ++i) {
        int Lmax = i - leftGreater[i];
        int Rmax = rightGreater[i] - i;
        ans += nums[i] * countPairs(Lmax, Rmax);

        int Lmin = i - leftSmaller[i];
        int Rmin = rightSmaller[i] - i;
        ans += nums[i] * countPairs(Lmin, Rmin);
    }
    return ans;
}

#include <bits/stdc++.h>

long long maxFreeTime(long long eventTime, int k, const std::vector<long long>& startTime, const std::vector<long long>& endTime) {
    size_t n = startTime.size();
    if (n == 0) return eventTime;
    size_t m = n + 1;
    std::vector<long long> gaps(m);
    gaps[0] = startTime[0];
    for (size_t i = 1; i < n; ++i) {
        gaps[i] = startTime[i] - endTime[i - 1];
    }
    gaps[m - 1] = eventTime - endTime[n - 1];
    long long totalFree = std::accumulate(gaps.begin(), gaps.end(), 0LL);
    if (k >= static_cast<int>(m - 1)) return totalFree;
    std::vector<std::pair<long long, size_t>> sorted;
    sorted.reserve(m);
    for (size_t i = 0; i < m; ++i) {
        sorted.emplace_back(gaps[i], i);
    }
    std::sort(sorted.begin(), sorted.end(), [](const auto& a, const auto& b) { return a.first > b.first; });
    std::vector<long long> prefix(m + 1, 0);
    for (size_t i = 0; i < m; ++i) {
        prefix[i + 1] = prefix[i] + sorted[i].first;
    }
    std::vector<int> rank(m);
    for (size_t i = 0; i < m; ++i) {
        rank[sorted[i].second] = static_cast<int>(i);
    }
    long long answer = 0;
    for (size_t i = 0; i < m; ++i) {
        long long sumTopK = (rank[i] < k) ? (prefix[k + 1] - gaps[i]) : prefix[k];
        long long candidate = gaps[i] + sumTopK;
        if (candidate > answer) answer = candidate;
    }
    return answer;
}

