using std::vector; using std::string;
vector<int> countMentions(int numberOfUsers, const vector<vector<string>>& events) {
    struct Event { long long time; int priority; string type; string payload; };
    vector<Event> evs;
    for (const auto& e : events) {
        long long t = std::stoll(e[1]);
        int pr = (e[0] == "OFFLINE") ? 0 : 1;
        evs.push_back({t, pr, e[0], e[2]});
    }
    std::stable_sort(evs.begin(), evs.end(), [](const Event& a, const Event& b) {
        if (a.time != b.time) return a.time < b.time;
        return a.priority < b.priority;
    });
    vector<long long> offlineUntil(numberOfUsers, -1);
    vector<int> mentions(numberOfUsers, 0);
    for (const auto& ev : evs) {
        long long ts = ev.time;
        if (ev.type == "OFFLINE") {
            int id = std::stoi(ev.payload);
            offlineUntil[id] = ts + 60;
        } else {
            const string& p = ev.payload;
            if (p == "ALL") {
                for (int i = 0; i < numberOfUsers; ++i) ++mentions[i];
            } else if (p == "HERE") {
                for (int i = 0; i < numberOfUsers; ++i) if (offlineUntil[i] <= ts) ++mentions[i];
            } else {
                size_t pos = 0;
                while (pos < p.size()) {
                    size_t nxt = p.find(' ', pos);
                    if (nxt == string::npos) nxt = p.size();
                    string token = p.substr(pos, nxt - pos);
                    if (token.rfind("id", 0) == 0) ++mentions[std::stoi(token.substr(2))];
                    pos = nxt + 1;
                }
            }
        }
    }
    return mentions;
}

#include <bits/stdc++.h>

int maxFrequencyAfterSubarrayOperation(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    int originalCount = 0;
    std::unordered_set<int> deltaSet;
    deltaSet.reserve(n * 2);
    deltaSet.insert(0);
    for (int v : nums) {
        if (v == k) ++originalCount;
        deltaSet.insert(k - v);
    }
    int answer = originalCount;
    for (int delta : deltaSet) {
        if (delta == 0) continue;
        int cur = 0, best = 0;
        int target = k - delta;
        for (int v : nums) {
            if (v == k) {
                cur -= 1;
            } else if (v == target) {
                cur += 1;
            }
            if (cur < 0) cur = 0;
            if (cur > best) best = cur;
        }
        int candidate = originalCount + best;
        if (candidate > answer) answer = candidate;
    }
    return answer;
}

#include <bits/stdc++.h>
std::vector<std::vector<int>> frequencies(const std::vector<std::string>& words) {
    std::unordered_map<char, int> id;
    std::vector<char> letters;
    for (const std::string& w : words) {
        for (char c : w) {
            if (id.find(c) == id.end()) {
                id[c] = (int)letters.size();
                letters.push_back(c);
            }
        }
    }
    int n = (int)letters.size(); // n <= 16
    bool edge[16][16] = {};
    int forcedBadMask = 0;
    for (const std::string& w : words) {
        int a = id[w[0]];
        int b = id[w[1]];
        edge[a][b] = true;
        if (a == b) forcedBadMask |= (1 << a);
    }
    int inMask[16] = {};
    for (int u = 0; u < n; ++u)
        for (int v = 0; v < n; ++v)
            if (edge[u][v]) inMask[v] |= (1 << u);
    int totalMask = (1 << n) - 1;
    std::vector<char> acyclic(1 << n, 0);
    acyclic[0] = 1;
    for (int mask = 1; mask <= totalMask; ++mask) {
        for (int v = 0; v < n; ++v) if (mask & (1 << v)) {
            if ((mask & inMask[v]) == 0 && acyclic[mask ^ (1 << v)]) {
                acyclic[mask] = 1;
                break;
            }
        }
    }
    int bestSize = n + 1;
    std::vector<int> bestMasks;
    for (int mask = 0; mask <= totalMask; ++mask) {
        if ((mask & forcedBadMask) != forcedBadMask) continue;
        int sz = __builtin_popcount(mask);
        if (sz > bestSize) continue;
        int remain = totalMask ^ mask;
        if (!acyclic[remain]) continue;
        if (sz < bestSize) {
            bestSize = sz;
            bestMasks.clear();
            bestMasks.push_back(mask);
        } else {
            bestMasks.push_back(mask);
        }
    }
    std::vector<std::vector<int>> result;
    for (int mask : bestMasks) {
        std::vector<int> freq(26, 0);
        for (int i = 0; i < n; ++i) {
            int cnt = (mask & (1 << i)) ? 2 : 1;
            freq[letters[i] - 'a'] = cnt;
        }
        result.push_back(std::move(freq));
    }
    std::sort(result.begin(), result.end());
    return result;
}

