using namespace std;

string minCostGoodCaption(const string& caption) {
    int n = (int)caption.size();
    if (n < 3) return "";
    const int INF = 1000000000;
    vector<array<array<int,3>,26>> dp(n);
    for (auto& row : dp) for (auto& arr : row) arr.fill(INF);
    vector<int> minCostArr(n, INF);

    for (int c = 0; c < 26; ++c) dp[n-1][c][0] = abs((caption[n-1]-'a') - c);
    int mc = INF;
    for (int c = 0; c < 26; ++c) mc = min(mc, dp[n-1][c][0]);
    minCostArr[n-1] = mc;

    for (int i = n-2; i >= 0; --i) {
        int newMinCost = INF;
        int ci = caption[i] - 'a';
        for (int c = 0; c < 26; ++c) {
            int changeCost = abs(ci - c);
            dp[i][c][0] = changeCost + minCostArr[i+1];
            dp[i][c][1] = changeCost + dp[i+1][c][0];
            dp[i][c][2] = changeCost + min(dp[i+1][c][1], dp[i+1][c][2]);
            newMinCost = min(newMinCost, dp[i][c][2]);
        }
        minCostArr[i] = newMinCost;
    }

    int bestCost = INF;
    for (int c = 0; c < 26; ++c) bestCost = min(bestCost, dp[0][c][2]);
    if (bestCost >= INF) return "";

    string ans;
    int letter = -1;
    for (int c = 0; c < 26; ++c) if (dp[0][c][2] == bestCost) { letter = c; break; }
    int k = 2;
    for (int i = 0; i < n; ++i) {
        ans.push_back(char('a' + letter));
        int ci = caption[i] - 'a';
        int changeCost = abs(ci - letter);
        if (k == 2) {
            int target = dp[i][letter][2];
            int remaining = target - changeCost;
            if (i+1 < n && dp[i+1][letter][1] == remaining) k = 1;
            else k = 2;
        } else if (k == 1) {
            k = 0;
        } else {
            if (i+1 < n) {
                for (int c2 = 0; c2 < 26; ++c2) {
                    if (dp[i+1][c2][2] == minCostArr[i+1]) { letter = c2; k = 2; break; }
                }
            }
        }
    }
    return ans;
}

