int maxDiffEvenOdd(const std::string& s) {
    std::array<int, 26> freq{};
    for (char ch : s) {
        int idx = static_cast<int>(ch) - 97; // 'a' -> 0
        if (idx >= 0 && idx < 26) {
            ++freq[idx];
        }
    }

    int maxOdd = -1;
    int minEven = std::numeric_limits<int>::max();
    for (int f : freq) {
        if (f == 0) continue;
        if (f & 1) {
            if (f > maxOdd) maxOdd = f;
        } else {
            if (f < minEven) minEven = f;
        }
    }

    if (maxOdd == -1 || minEven == std::numeric_limits<int>::max()) return 0;
    return maxOdd - minEven;
}

