int maxManhattanDistanceAfterKChanges(const std::string& s, int k) {
    long long x = 0, y = 0, inward = 0, answer = 0;
    for (char c : s) {
        if (c == 'N') {
            if (y < 0) ++inward;
            ++y;
        } else if (c == 'S') {
            if (y > 0) ++inward;
            --y;
        } else if (c == 'E') {
            if (x < 0) ++inward;
            ++x;
        } else { // 'W'
            if (x > 0) ++inward;
            --x;
        }
        long long dist = std::llabs(x) + std::llabs(y);
        long long best = dist + 2LL * std::min<long long>(k, inward);
        if (best > answer) answer = best;
    }
    return static_cast<int>(answer);
}

#include <bits/stdc++.h>

static long long gcd_ll(long long a, long long b) {
    while (b) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

long long minimumIncrements(const std::vector<int>& nums, const std::vector<int>& target) {
    int n = static_cast<int>(nums.size());
    int m = static_cast<int>(target.size());
    int fullMask = (1 << m) - 1;
    const long long INF = (long long)4e18;

    std::vector<long long> lcmMask(1 << m, 1);
    for (int mask = 1; mask <= fullMask; ++mask) {
        int bit = __builtin_ctz(mask);
        int prev = mask ^ (1 << bit);
        long long prevL = (prev == 0) ? 1 : lcmMask[prev];
        long long t = target[bit];
        long long g = gcd_ll(prevL, t);
        long long div = prevL / g;
        long long l;
        if (div > INF / t) l = INF;
        else l = div * t;
        lcmMask[mask] = l;
    }

    std::vector<long long> dp(1 << m, INF);
    dp[0] = 0;

    std::vector<long long> costMask(1 << m);
    for (int i = 0; i < n; ++i) {
        long long cur = nums[i];
        costMask[0] = 0;
        for (int mask = 1; mask <= fullMask; ++mask) {
            long long L = lcmMask[mask];
            if (L == INF) {
                costMask[mask] = INF;
                continue;
            }
            long long mult = (cur + L - 1) / L;
            long long nxt;
            if (mult > INF / L) nxt = INF;
            else nxt = mult * L;
            long long inc = (nxt == INF) ? INF : (nxt - cur);
            costMask[mask] = inc;
        }

        std::vector<long long> ndp = dp;
        for (int mask = 0; mask <= fullMask; ++mask) {
            if (dp[mask] == INF) continue;
            for (int sub = 0; sub <= fullMask; ++sub) {
                long long add = costMask[sub];
                if (add == INF) continue;
                int nmask = mask | sub;
                long long cand = dp[mask] + add;
                if (cand < ndp[nmask]) ndp[nmask] = cand;
            }
        }
        dp.swap(ndp);
    }

    return dp[fullMask];
}

#include <bits/stdc++.h>

int maxFreeTime(int eventTime, std::vector<int> startTime, std::vector<int> endTime) {
    int n = (int)startTime.size();
    if (n == 0) return eventTime;
    std::vector<long long> gaps(n + 1);
    gaps[0] = startTime[0];
    for (int i = 1; i < n; ++i) {
        gaps[i] = (long long)startTime[i] - endTime[i - 1];
    }
    gaps[n] = (long long)eventTime - endTime[n - 1];

    std::vector<long long> prefixMax(n + 1), suffixMax(n + 1);
    prefixMax[0] = gaps[0];
    for (int i = 1; i <= n; ++i) {
        prefixMax[i] = std::max(prefixMax[i - 1], gaps[i]);
    }
    suffixMax[n] = gaps[n];
    for (int i = n - 1; i >= 0; --i) {
        suffixMax[i] = std::max(suffixMax[i + 1], gaps[i]);
    }

    long long currentMaxGap = 0;
    for (long long g : gaps) currentMaxGap = std::max(currentMaxGap, g);
    long long answer = currentMaxGap;

    for (int i = 0; i < n; ++i) {
        long long left_gap = gaps[i];
        long long right_gap = gaps[i + 1];
        long long duration = (long long)endTime[i] - startTime[i];
        long long merged_gap = left_gap + duration + right_gap;

        long long max_other_gap = 0;
        if (i - 1 >= 0) max_other_gap = std::max(max_other_gap, prefixMax[i - 1]);
        if (i + 2 <= n) max_other_gap = std::max(max_other_gap, suffixMax[i + 2]);

        long long candidate;
        if (max_other_gap >= duration) {
            candidate = merged_gap;
        } else {
            candidate = std::max(merged_gap - duration, max_other_gap);
        }
        answer = std::max(answer, candidate);
    }

    return (int)answer;
}

