std::vector<std::vector<int>> sortMatrixByDiagonals(const std::vector<std::vector<int>>& grid) {
    int n = grid.size();
    std::vector<std::vector<int>> result = grid;
    for (int d = -(n - 1); d <= n - 1; ++d) {
        std::vector<int> vals;
        std::vector<std::pair<int,int>> positions;
        for (int i = 0; i < n; ++i) {
            int j = i - d;
            if (j >= 0 && j < n) {
                vals.push_back(grid[i][j]);
                positions.emplace_back(i, j);
            }
        }
        if (d >= 0) {
            std::sort(vals.begin(), vals.end(), std::greater<int>());
        } else {
            std::sort(vals.begin(), vals.end());
        }
        for (size_t k = 0; k < positions.size(); ++k) {
            result[positions[k].first][positions[k].second] = vals[k];
        }
    }
    return result;
}

