std::vector<int> assignElements(const std::vector<int>& groups, const std::vector<int>& elements) {
    const int INF = std::numeric_limits<int>::max();
    int maxVal = 0;
    for (int v : elements) if (v > maxVal) maxVal = v;
    std::vector<int> firstIdx(maxVal + 1, INF);
    for (int i = 0; i < static_cast<int>(elements.size()); ++i) {
        int v = elements[i];
        if (v >= 0 && v <= maxVal && firstIdx[v] == INF) firstIdx[v] = i;
    }
    std::vector<int> result;
    result.reserve(groups.size());
    for (int g : groups) {
        int best = INF;
        for (int d = 1; 1LL * d * d <= g; ++d) {
            if (g % d == 0) {
                if (d <= maxVal && firstIdx[d] < best) best = firstIdx[d];
                int d2 = g / d;
                if (d2 != d && d2 <= maxVal && firstIdx[d2] < best) best = firstIdx[d2];
            }
        }
        result.push_back(best == INF ? -1 : best);
    }
    return result;
}

