int maxDifference(const std::string& s, int k) {
    int n = static_cast<int>(s.size());
    if (k > n) return -1;
    int evens = 0, odds = 0;
    for (int i = 0; i < k; ++i) {
        int d = s[i] - '0';
        if (d % 2 == 0) ++evens;
        else ++odds;
    }
    int best = INT_MIN;
    if (evens > 0 && odds > 0) best = evens - odds;
    for (int i = k; i < n; ++i) {
        int out = s[i - k] - '0';
        if (out % 2 == 0) --evens;
        else --odds;
        int in = s[i] - '0';
        if (in % 2 == 0) ++evens;
        else ++odds;
        if (evens > 0 && odds > 0) {
            int diff = evens - odds;
            if (diff > best) best = diff;
        }
    }
    if (best <= 0) return -1;
    return best;
}

