long long maxScore(const std::vector<int>& points, long long m) {
    if (points.empty()) return 0;
    long long maxP = *std::max_element(points.begin(), points.end());
    unsigned long long low = 0;
    unsigned long long high;
    if (maxP == 0) return 0;
    if (maxP > LLONG_MAX / m) {
        high = static_cast<unsigned long long>(LLONG_MAX);
    } else {
        high = static_cast<unsigned long long>(maxP) * static_cast<unsigned long long>(m);
    }
    while (low < high) {
        unsigned long long mid = (low + high + 1) / 2;
        unsigned long long need = 0;
        for (int v : points) {
            need += (mid + static_cast<unsigned long long>(v) - 1) / static_cast<unsigned long long>(v);
            if (need > static_cast<unsigned long long>(m)) break;
        }
        if (need <= static_cast<unsigned long long>(m)) {
            low = mid;
        } else {
            high = mid - 1;
        }
    }
    return static_cast<long long>(low);
}

