long long countDivisibleSubstrings(const std::string& s) {
    long long cnt[10][10] = {};
    long long ndcnt[10][10];
    long long answer = 0;
    for (char ch : s) {
        int cur = ch - '0';
        for (int d = 1; d <= 9; ++d) {
            for (int r = 0; r < d; ++r) {
                ndcnt[d][r] = 0;
            }
        }
        for (int d = 1; d <= 9; ++d) {
            for (int r = 0; r < d; ++r) {
                long long ways = cnt[d][r];
                if (ways) {
                    int nr = (r * 10 + cur) % d;
                    ndcnt[d][nr] += ways;
                }
            }
            int nr = cur % d;
            ndcnt[d][nr] += 1;
        }
        if (cur != 0) {
            answer += ndcnt[cur][0];
        }
        for (int d = 1; d <= 9; ++d) {
            for (int r = 0; r < d; ++r) {
                cnt[d][r] = ndcnt[d][r];
            }
        }
    }
    return answer;
}

