int sumGoodNumbers(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    int total = 0;
    for (int i = 0; i < n; ++i) {
        bool good = true;
        if (i - k >= 0 && !(nums[i] > nums[i - k])) {
            good = false;
        }
        if (i + k < n && !(nums[i] > nums[i + k])) {
            good = false;
        }
        if (good) {
            total += nums[i];
        }
    }
    return total;
}

#include <bits/stdc++.h>

double separateSquares(std::vector<std::vector<int>>& squares) {
    using ld = double;
    if (squares.empty()) return 0.0;
    ld total = 0.0;
    std::vector<std::pair<ld, ld>> events;
    events.reserve(squares.size() * 2);
    ld low = std::numeric_limits<ld>::infinity();
    for (const auto& sq : squares) {
        ld y = static_cast<ld>(sq[1]);
        ld l = static_cast<ld>(sq[2]);
        total += l * l;
        low = std::min(low, y);
        events.emplace_back(y, -l);
        events.emplace_back(y + l, l);
    }
    std::sort(events.begin(), events.end(),
              [](const std::pair<ld, ld>& a, const std::pair<ld, ld>& b) {
                  if (a.first == b.first) return a.second < b.second;
                  return a.first < b.first;
              });
    ld half = total / 2.0;
    ld cur_h = low;
    ld area = total;
    ld slope = 0.0;
    for (size_t i = 0; i < events.size(); ++i) {
        ld next_h = events[i].first;
        if (next_h > cur_h) {
            ld area_next = area + slope * (next_h - cur_h);
            if (area >= half && area_next <= half && slope != 0.0) {
                ld needed = (area - half) / (-slope);
                ld ans = cur_h + needed;
                return std::round(ans * 1e5) / 1e5;
            }
            area = area_next;
            cur_h = next_h;
        }
        slope += events[i].second;
    }
    return std::round(cur_h * 1e5) / 1e5;
}

