bool findSpecialSubstring(const std::string& s, int k) {
    if (k <= 0) return false;
    std::size_t n = s.size();
    if (static_cast<std::size_t>(k) > n) return false;
    if (k == 1) return n > 0;
    int consecutive = 1;
    for (std::size_t i = 1; i < n; ++i) {
        consecutive = (s[i] == s[i - 1]) ? consecutive + 1 : 1;
        if (consecutive >= k) return true;
    }
    return false;
}

#include <bits/stdc++.h>
#include <string>
#include <vector>
#include <climits>

int shortestMatchingSubstring(const std::string& s, const std::string& p) {
    size_t first = p.find('*');
    size_t second = p.find('*', first + 1);
    std::string A = p.substr(0, first);
    std::string B = p.substr(first + 1, second - first - 1);
    std::string C = p.substr(second + 1);
    int n = static_cast<int>(s.size());

    auto getOccurrences = [&](const std::string& pat) -> std::vector<int> {
        std::vector<int> res;
        if (pat.empty()) {
            res.reserve(n + 1);
            for (int i = 0; i <= n; ++i) res.push_back(i);
            return res;
        }
        std::string combined = pat + '#' + s;
        std::vector<int> pi(combined.size(), 0);
        for (size_t i = 1; i < combined.size(); ++i) {
            int j = pi[i - 1];
            while (j > 0 && combined[i] != combined[j]) j = pi[j - 1];
            if (combined[i] == combined[j]) ++j;
            pi[i] = j;
        }
        int m = static_cast<int>(pat.size());
        for (size_t i = pat.size() + 1; i < combined.size(); ++i) {
            if (pi[i] == m) res.push_back(static_cast<int>(i - 2 * m));
        }
        return res;
    };

    std::vector<int> startsA = getOccurrences(A);
    std::vector<int> startsB = getOccurrences(B);
    std::vector<int> startsC = getOccurrences(C);

    std::vector<int> nextB(n + 1, -1), nextC(n + 1, -1);
    size_t idxB = 0, idxC = 0;
    for (int pos = 0; pos <= n; ++pos) {
        while (idxB < startsB.size() && startsB[idxB] < pos) ++idxB;
        if (idxB < startsB.size()) nextB[pos] = startsB[idxB];
        while (idxC < startsC.size() && startsC[idxC] < pos) ++idxC;
        if (idxC < startsC.size()) nextC[pos] = startsC[idxC];
    }

    int best = INT_MAX;
    int lenA = static_cast<int>(A.size());
    int lenB = static_cast<int>(B.size());
    int lenC = static_cast<int>(C.size());

    for (int i : startsA) {
        int posB = i + lenA;
        if (posB > n) continue;
        int j = nextB[posB];
        if (j == -1) continue;
        int posC = j + lenB;
        if (posC > n) continue;
        int k = nextC[posC];
        if (k == -1) continue;
        int len = (k + lenC) - i;
        if (len < best) best = len;
    }

    return best == INT_MAX ? -1 : best;
}

#include <bits/stdc++.h>

double separateSquaresII(const std::vector<std::vector<double>>& squares) {
    struct Event {
        double x;
        int type;
        double y1, y2;
    };

    auto unionArea = [&](const std::vector<std::vector<double>>& rects) -> double {
        if (rects.empty()) return 0.0;
        std::vector<Event> events;
        events.reserve(rects.size() * 2);
        std::vector<double> ys;
        ys.reserve(rects.size() * 2);
        for (const auto& r : rects) {
            double x1 = r[0], x2 = r[1], y1 = r[2], y2 = r[3];
            events.push_back({x1, 1, y1, y2});
            events.push_back({x2, -1, y1, y2});
            ys.push_back(y1);
            ys.push_back(y2);
        }
        std::sort(events.begin(), events.end(),
                  [](const Event& a, const Event& b) { return a.x < b.x; });
        std::sort(ys.begin(), ys.end());
        ys.erase(std::unique(ys.begin(), ys.end()), ys.end());
        if (ys.size() < 2) return 0.0;
        std::size_t m = ys.size() - 1;
        std::vector<int> cnt(4 * m);
        std::vector<double> len(4 * m);

        std::function<void(std::size_t, std::size_t, std::size_t, std::size_t, std::size_t, int)>
        update = [&](std::size_t node, std::size_t l, std::size_t r,
                     std::size_t ql, std::size_t qr, int delta) {
            if (ql > r || qr < l) return;
            if (ql <= l && r <= qr) {
                cnt[node] += delta;
            } else {
                std::size_t mid = (l + r) >> 1;
                update(node * 2, l, mid, ql, qr, delta);
                update(node * 2 + 1, mid + 1, r, ql, qr, delta);
            }
            if (cnt[node] > 0) {
                len[node] = ys[r + 1] - ys[l];
            } else if (l == r) {
                len[node] = 0.0;
            } else {
                len[node] = len[node * 2] + len[node * 2 + 1];
            }
        };

        double area = 0.0;
        double prevX = events.front().x;
        for (const auto& e : events) {
            double dx = e.x - prevX;
            if (dx != 0.0) area += len[1] * dx;
            std::size_t y1Idx = std::lower_bound(ys.begin(), ys.end(), e.y1) - ys.begin();
            std::size_t y2Idx = std::lower_bound(ys.begin(), ys.end(), e.y2) - ys.begin();
            if (y2Idx > 0) --y2Idx;
            if (y1Idx <= y2Idx) update(1, 0, m - 1, y1Idx, y2Idx, e.type);
            prevX = e.x;
        }
        return area;
    };

    std::vector<std::vector<double>> fullRects;
    fullRects.reserve(squares.size());
    for (const auto& s : squares) {
        double x = s[0], y = s[1], l = s[2];
        fullRects.push_back({x, x + l, y, y + l});
    }
    double totalArea = unionArea(fullRects);
    double halfArea = totalArea * 0.5;

    double low = std::numeric_limits<double>::infinity();
    double high = -std::numeric_limits<double>::infinity();
    for (const auto& s : squares) {
        double y = s[1], l = s[2];
        low = std::min(low, y);
        high = std::max(high, y + l);
    }

    for (int it = 0; it < 60; ++it) {
        double mid = (low + high) * 0.5;
        std::vector<std::vector<double>> rects;
        rects.reserve(squares.size());
        for (const auto& s : squares) {
            double x = s[0], y = s[1], l = s[2];
            double y2 = std::min(y + l, mid);
            if (y2 > y) rects.push_back({x, x + l, y, y2});
        }
        double areaBelow = unionArea(rects);
        if (areaBelow >= halfArea) high = mid;
        else low = mid;
    }
    return high;
}

