long long maxSumWithAtMostK(const std::vector<std::vector<int>>& grid, const std::vector<int>& limits, int k) {
    if (k <= 0) {
        return 0;
    }
    std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap;
    for (std::size_t i = 0; i < grid.size(); ++i) {
        const std::vector<int>& row = grid[i];
        int limit_i = (i < limits.size()) ? limits[i] : 0;
        if (limit_i <= 0) {
            continue;
        }
        std::size_t take = std::min(static_cast<std::size_t>(limit_i), row.size());
        if (take == 0) {
            continue;
        }
        std::vector<int> temp(row);
        std::nth_element(temp.begin(), temp.begin() + take, temp.end(), std::greater<int>());
        for (std::size_t j = 0; j < take; ++j) {
            int val = temp[j];
            if (static_cast<int>(minHeap.size()) < k) {
                minHeap.push(val);
            } else if (val > minHeap.top()) {
                minHeap.pop();
                minHeap.push(val);
            }
        }
    }
    long long sum = 0;
    while (!minHeap.empty()) {
        sum += minHeap.top();
        minHeap.pop();
    }
    return sum;
}

