int dfs(vector<vector<int>>& grid, int i, int j, int k, int cnt) {
    if (memo[i][j][k][cnt] != -1) return memo[i][j][k][cnt];
    int target = grid[i][j]==2 ? 0 : 2;
    int best = 0;
    int x = i+dirs[k], y = j+dirs[k+1];
    if (x>=0 && x<m && y>=0 && y<n && grid[x][y]==target) {
        best = dfs(grid, x, y, k, cnt) + 1;
    }
    if (cnt == 0) {
        int k2 = (k+1)%4;
        int x2 = i+dirs[k2], y2 = j+dirs[k2+1];
        if (x2>=0 && x2<m && y2>=0 && y2<n && grid[x2][y2]==target) {
            best = max(best, dfs(grid, x2, y2, k2, 1) + 1);
        }
    }
    memo[i][j][k][cnt] = best;
    return best;
}

int lenOfVDiagonal(vector<vector<int>>& grid) {
    m = grid.size(); n = grid[0].size();
    memo.assign(m, vector<array<array<int,2>,4>>(n));
    for (auto& row : memo) for (auto& cell : row) for (auto& kk : cell) kk.fill(-1);
    int ans = 0;
    for (int i = 0; i < m; i++)
        for (int j = 0; j < n; j++)
            if (grid[i][j] == 1)
                for (int k = 0; k < 4; k++)
                    ans = max(ans, dfs(grid, i, j, k, 0) + 1);
    return ans;
}

