std::string smallestGeneratedString(const std::string& str1, const std::string& str2) {
    std::size_t n = str1.size();
    std::size_t m = str2.size();
    if (n == 0 || m == 0) return "";
    std::size_t L = n + m - 1;
    std::vector<char> word(L, 0);
    for (std::size_t i = 0; i < n; ++i) {
        if (str1[i] == 'T') {
            for (std::size_t j = 0; j < m; ++j) {
                std::size_t pos = i + j;
                char c = str2[j];
                if (word[pos] == 0) {
                    word[pos] = c;
                } else if (word[pos] != c) {
                    return "";
                }
            }
        }
    }
    for (std::size_t i = 0; i < n; ++i) {
        if (str1[i] == 'F') {
            bool alreadyDiff = false;
            for (std::size_t j = 0; j < m; ++j) {
                std::size_t pos = i + j;
                char c = str2[j];
                if (word[pos] != 0 && word[pos] != c) {
                    alreadyDiff = true;
                    break;
                }
            }
            if (alreadyDiff) continue;
            bool changed = false;
            for (std::size_t j = m; j-- > 0;) {
                std::size_t pos = i + j;
                if (word[pos] == 0) {
                    char c = str2[j];
                    word[pos] = (c != 'a' ? 'a' : 'b');
                    changed = true;
                    break;
                }
            }
            if (!changed) return "";
        }
    }
    for (char& c : word) if (c == 0) c = 'a';
    return std::string(word.begin(), word.end());
}

