int minimumRemovalCost(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;
    std::vector<int> left(n, -1), right(n, -1), parent(n, -1);
    std::stack<int> st;
    for (int i = 0; i < n; ++i) {
        int last = -1;
        while (!st.empty() && nums[st.top()] < nums[i]) {
            last = st.top();
            st.pop();
        }
        if (!st.empty()) {
            right[st.top()] = i;
            parent[i] = st.top();
        }
        if (last != -1) {
            left[i] = last;
            parent[last] = i;
        }
        st.push(i);
    }
    int root = 0;
    while (parent[root] != -1) root = parent[root];
    std::vector<long long> dp(n, 0);
    std::vector<int> order;
    order.reserve(n);
    std::stack<int> dfs;
    dfs.push(root);
    while (!dfs.empty()) {
        int u = dfs.top();
        dfs.pop();
        order.push_back(u);
        if (left[u] != -1) dfs.push(left[u]);
        if (right[u] != -1) dfs.push(right[u]);
    }
    for (int i = static_cast<int>(order.size()) - 1; i >= 0; --i) {
        int u = order[i];
        long long l = left[u] == -1 ? 0 : dp[left[u]];
        long long r = right[u] == -1 ? 0 : dp[right[u]];
        dp[u] = static_cast<long long>(nums[u]) + std::min(l, r);
    }
    return static_cast<int>(dp[root]);
}

