static const unsigned long long INF = 1000000000000000000ULL;

static unsigned long long mul_cap(unsigned long long a, unsigned long long b) {
    if (a == 0 || b == 0) return 0;
    if (a > INF / b) return INF;
    unsigned long long res = a * b;
    return res > INF ? INF : res;
}

std::vector<int> getPermutation(int n, long long k) {
    int totalOdd = (n + 1) / 2;
    int totalEven = n / 2;
    std::vector<std::vector<std::array<unsigned long long, 2>>> dp(
        totalOdd + 1, std::vector<std::array<unsigned long long, 2>>(totalEven + 1));
    dp[0][0][0] = dp[0][0][1] = 1;
    for (int o = 0; o <= totalOdd; ++o) {
        for (int e = 0; e <= totalEven; ++e) {
            if (o == 0 && e == 0) continue;
            unsigned long long val0 = 0, val1 = 0;
            if (o > 0) val0 = mul_cap((unsigned long long)o, dp[o - 1][e][1]);
            if (e > 0) val1 = mul_cap((unsigned long long)e, dp[o][e - 1][0]);
            dp[o][e][0] = val0;
            dp[o][e][1] = val1;
        }
    }

    std::vector<int> ans;
    std::vector<char> used(n + 1, 0);
    int oddLeft = totalOdd, evenLeft = totalEven;
    int lastParity = -1;
    unsigned long long K = static_cast<unsigned long long>(k);

    for (int pos = 0; pos < n; ++pos) {
        bool found = false;
        for (int x = 1; x <= n; ++x) {
            if (used[x]) continue;
            int parity = x & 1;
            if (pos > 0 && parity == lastParity) continue;
            int o = oddLeft - (parity == 1);
            int e = evenLeft - (parity == 0);
            unsigned long long cnt = dp[o][e][parity];
            if (cnt >= K) {
                ans.push_back(x);
                used[x] = 1;
                oddLeft = o;
                evenLeft = e;
                lastParity = parity;
                found = true;
                break;
            } else {
                K -= cnt;
            }
        }
        if (!found) return std::vector<int>();
    }
    return ans;
}

