int longestPalindromeSubseqAfterOperations(const std::string& s, int k) {
    int n = static_cast<int>(s.size());
    if (n == 0) return 0;
    int K = k;
    auto dist = [](char a, char b) -> int {
        int diff = std::abs(a - b);
        return std::min(diff, 26 - diff);
    };
    std::vector<std::vector<int>> dpLenMinus2(n, std::vector<int>(K + 1, 0));
    std::vector<std::vector<int>> dpLenMinus1(n, std::vector<int>(K + 1, 0));
    std::vector<std::vector<int>> dpCurr(n, std::vector<int>(K + 1, 0));
    for (int i = 0; i < n; ++i) {
        for (int c = 0; c <= K; ++c) dpLenMinus1[i][c] = 1;
    }
    for (int len = 2; len <= n; ++len) {
        for (int l = 0; l + len - 1 < n; ++l) {
            int r = l + len - 1;
            int d = dist(s[l], s[r]);
            for (int c = 0; c <= K; ++c) {
                int best = std::max(dpLenMinus1[l + 1][c], dpLenMinus1[l][c]);
                if (c >= d) {
                    int inner = (len > 2) ? dpLenMinus2[l + 1][c - d] : 0;
                    best = std::max(best, inner + 2);
                }
                dpCurr[l][c] = best;
            }
        }
        dpLenMinus2.swap(dpLenMinus1);
        dpLenMinus1.swap(dpCurr);
    }
    int ans = 0;
    for (int c = 0; c <= K; ++c) ans = std::max(ans, dpLenMinus1[0][c]);
    return ans;
}

