long long maxSumKSubarrays(const std::vector<int>& nums, int k, int m) {
    int n = static_cast<int>(nums.size());
    const long long NEG_INF = LLONG_MIN / 4;
    std::vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        pref[i + 1] = pref[i] + static_cast<long long>(nums[i]);
    }
    std::vector<long long> dpPrev(n + 1, NEG_INF);
    dpPrev[0] = 0;
    for (int sub = 1; sub <= k; ++sub) {
        std::vector<long long> dpCurr(n + 1, NEG_INF);
        long long best = NEG_INF;
        for (int i = m; i <= n; ++i) {
            long long candidate = dpPrev[i - m] - pref[i - m];
            if (candidate > best) best = candidate;
            long long val = best + pref[i];
            dpCurr[i] = dpCurr[i - 1] > val ? dpCurr[i - 1] : val;
        }
        dpPrev.swap(dpCurr);
    }
    return dpPrev[n];
}

