int largestAlmostMissingInteger(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    if (k <= 0 || k > n) return -1;
    int maxStart = n - k;
    std::unordered_map<int, std::vector<int>> posMap;
    for (int i = 0; i < n; ++i) {
        posMap[nums[i]].push_back(i);
    }
    int answer = -1;
    for (const auto& entry : posMap) {
        const std::vector<int>& positions = entry.second;
        long long windows = 0;
        int curL = -1, curR = -1;
        for (int p : positions) {
            int l = p - k + 1;
            if (l < 0) l = 0;
            int r = p;
            if (r > maxStart) r = maxStart;
            if (l > r) continue;
            if (curL == -1) {
                curL = l;
                curR = r;
            } else if (l <= curR + 1) {
                curR = std::max(curR, r);
            } else {
                windows += static_cast<long long>(curR - curL + 1);
                curL = l;
                curR = r;
            }
        }
        if (curL != -1) {
            windows += static_cast<long long>(curR - curL + 1);
        }
        if (windows == 1 && entry.first > answer) {
            answer = entry.first;
        }
    }
    return answer;
}

