std::vector<long long> chooseKElementsWithMaximumSum(const std::vector<int>& nums1, const std::vector<int>& nums2, int k) {
    int n = static_cast<int>(nums1.size());
    std::vector<int> idx(n);
    std::iota(idx.begin(), idx.end(), 0);
    std::sort(idx.begin(), idx.end(), [&](int a, int b) {
        return nums1[a] < nums1[b];
    });

    std::vector<long long> answer(n);
    std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap;
    long long curSum = 0;

    for (int i = 0; i < n; ) {
        int j = i;
        while (j < n && nums1[idx[j]] == nums1[idx[i]]) ++j;

        for (int p = i; p < j; ++p) {
            answer[idx[p]] = curSum;
        }

        for (int p = i; p < j; ++p) {
            int val = nums2[idx[p]];
            if (static_cast<int>(minHeap.size()) < k) {
                minHeap.push(val);
                curSum += val;
            } else if (k > 0 && val > minHeap.top()) {
                curSum -= minHeap.top();
                minHeap.pop();
                minHeap.push(val);
                curSum += val;
            }
        }
        i = j;
    }

    return answer;
}

