    vector<vector<pair<int,int>>> ending(n + 1); // (val, idx)
    for (int idx = 0; idx < m; ++idx) {
        int a = conflictingPairs[idx].first, b = conflictingPairs[idx].second;
        if (a > b) swap(a, b);
        ending[b].push_back({a + 1, idx});
    }

    vector<int> best1(n + 1, 0), best2(n + 1, 0), idx1(n + 1, -1);
    int curMax1 = 0, curIdx1 = -1, curMax2 = 0;
    for (int r = 1; r <= n; ++r) {
        for (auto& pr : ending[r]) {
            int val = pr.first, idx = pr.second;
            if (val > curMax1) { curMax2 = curMax1; curMax1 = val; curIdx1 = idx; }
            else if (val > curMax2) curMax2 = val;
        }
        best1[r] = curMax1; best2[r] = curMax2; idx1[r] = curIdx1;
    }

    long long total = 0;
    for (int r = 1; r <= n; ++r) {
        int left = best1[r] >= 1 ? best1[r] : 1;
        if (left <= r) total += r - left + 1;
    }

    vector<long long> diffSum(m, 0);
    for (int r = 1; r <= n; ++r) {
        int left1 = best1[r] >= 1 ? best1[r] : 1;
        int left2 = best2[r] >= 1 ? best2[r] : 1;
        long long oldV = (left1 <= r) ? (r - left1 + 1) : 0;
        long long newV = (left2 <= r) ? (r - left2 + 1) : 0;
        long long diff = newV - oldV;
        if (diff != 0 && idx1[r] != -1) diffSum[idx1[r]] += diff;
    }

    long long maxDiff = 0;
    for (long long d : diffSum) maxDiff = max(maxDiff, d);
    return total + maxDiff;
}

