std::vector<long long> longestSpecialPathII(const std::vector<std::vector<int>>& edges, const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    std::vector<std::vector<std::pair<int, int>>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1], w = e[2];
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }

    std::vector<int> uniq = nums;
    std::sort(uniq.begin(), uniq.end());
    uniq.erase(std::unique(uniq.begin(), uniq.end()), uniq.end());
    std::unordered_map<int, int> mp;
    mp.reserve(uniq.size() * 2);
    for (int i = 0; i < static_cast<int>(uniq.size()); ++i) mp[uniq[i]] = i;
    std::vector<int> comp(n);
    for (int i = 0; i < n; ++i) comp[i] = mp[nums[i]];

    std::vector<int> last(uniq.size(), -1);
    std::vector<long long> pref;
    pref.reserve(n + 1);
    pref.push_back(0);
    int left = 0;
    long long bestSum = 0;
    long long bestCnt = 0;

    struct Frame {
        int node;
        int parent;
        int weight;
        int state;
        int prevLast;
        int prevLeft;
    };
    std::vector<Frame> stack;
    stack.reserve(2 * n);
    stack.push_back({0, -1, 0, 0, -1, 0});

    while (!stack.empty()) {
        Frame cur = stack.back();
        stack.pop_back();

        if (cur.state == 0) {
            int node = cur.node;
            int parent = cur.parent;
            int weight = cur.weight;
            int valIdx = comp[node];
            int prevLast = last[valIdx];
            int prevLeft = left;

            int idx = static_cast<int>(pref.size()) - 1;
            pref.push_back(pref.back() + weight);
            left = std::max(left, prevLast + 1);
            last[valIdx] = idx;

            long long curSum = pref.back() - (left > 0 ? pref[left] : 0LL);
            long long curCnt = idx - left + 1; // number of nodes in current window
            if (curSum > bestSum || (curSum == bestSum && curCnt > bestCnt)) {
                bestSum = curSum;
                bestCnt = curCnt;
            }

            stack.push_back({node, parent, weight, 1, prevLast, prevLeft});
            for (const auto& p : adj[node]) {
                int nei = p.first;
                int w = p.second;
                if (nei == parent) continue;
                stack.push_back({nei, node, w, 0, -1, 0});
            }
        } else {
            int node = cur.node;
            int valIdx = comp[node];
            last[valIdx] = cur.prevLast;
            left = cur.prevLeft;
            pref.pop_back();
        }
    }

    return {bestSum, bestCnt};
}

