int countEvenNumbers(const std::vector<int>& digits) {
    std::array<bool, 1000> seen{};
    int n = static_cast<int>(digits.size());
    for (int i = 0; i < n; ++i) {
        if (digits[i] == 0) continue;
        for (int j = 0; j < n; ++j) {
            if (j == i) continue;
            for (int k = 0; k < n; ++k) {
                if (k == i || k == j) continue;
                if (digits[k] % 2 != 0) continue;
                int num = digits[i] * 100 + digits[j] * 10 + digits[k];
                seen[num] = true;
            }
        }
    }
    int count = 0;
    for (bool v : seen) if (v) ++count;
    return count;
}

