class Spreadsheet {
public:
    int rows;
    std::unordered_map<std::string,int> cells;
    Spreadsheet(int rowCount) : rows(rowCount) {}
    void setCell(const std::string& cell, int value) { cells[cell] = value; }
    void resetCell(const std::string& cell) { cells.erase(cell); }
    int getValue(const std::string& formula) {
        if (formula[0] == '=') {
            int total = 0;
            std::string expr = formula.substr(1);
            std::stringstream ss(expr);
            std::string part;
            while (std::getline(ss, part, '+')) {
                if (std::regex_match(part, std::regex("^[A-Z][0-9]+$"))) {
                    auto it = cells.find(part);
                    total += (it != cells.end()) ? it->second : 0;
                } else {
                    total += std::stoi(part);
                }
            }
            return total;
        }
        auto it = cells.find(formula);
        return it != cells.end() ? it->second : 0;
    }
};

