std::vector<int> distanceToClosest(const std::vector<int>& nums, const std::vector<int>& queries) {
    int n = static_cast<int>(nums.size());
    std::unordered_map<int, std::vector<int>> posMap;
    posMap.reserve(n * 2);
    for (int i = 0; i < n; ++i) {
        posMap[nums[i]].push_back(i);
    }
    std::vector<int> forwardDist(n, -1), backwardDist(n, -1);
    for (auto& kv : posMap) {
        const std::vector<int>& vec = kv.second;
        if (vec.size() == 1) continue;
        size_t m = vec.size();
        for (size_t j = 0; j < m; ++j) {
            int cur = vec[j];
            int nxt = vec[(j + 1) % m];
            int prv = vec[(j + m - 1) % m];
            forwardDist[cur] = (nxt - cur + n) % n;
            backwardDist[cur] = (cur - prv + n) % n;
        }
    }
    std::vector<int> answer;
    answer.reserve(queries.size());
    for (int idx : queries) {
        if (forwardDist[idx] == -1) {
            answer.push_back(-1);
        } else {
            answer.push_back(std::min(forwardDist[idx], backwardDist[idx]));
        }
    }
    return answer;
}

#include <bits/stdc++.h>

int minimumQueriesToZeroArray(const std::vector<int>& nums, const std::vector<std::vector<int>>& queries) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;
    bool allZero = true;
    for (int v : nums) if (v != 0) { allZero = false; break; }
    if (allZero) return 0;

    struct Node {
        long long mx;
        long long mn;
        long long lazy;
    };
    std::vector<Node> seg(4 * n);

    std::function<void(int,int,int)> build = [&](int idx, int l, int r) {
        seg[idx].lazy = 0;
        if (l == r) {
            long long val = nums[l];
            seg[idx].mx = seg[idx].mn = val;
            return;
        }
        int mid = (l + r) >> 1;
        build(idx << 1, l, mid);
        build(idx << 1 | 1, mid + 1, r);
        seg[idx].mx = std::max(seg[idx << 1].mx, seg[idx << 1 | 1].mx);
        seg[idx].mn = std::min(seg[idx << 1].mn, seg[idx << 1 | 1].mn);
    };
    build(1, 0, n - 1);

    auto apply = [&](int idx, long long dec) {
        Node &node = seg[idx];
        node.mx = std::max(0LL, node.mx - dec);
        node.mn = std::max(0LL, node.mn - dec);
        node.lazy += dec;
        if (node.mx == 0) node.lazy = 0;
    };

    std::function<void(int)> push = [&](int idx) {
        long long lazy = seg[idx].lazy;
        if (lazy == 0) return;
        apply(idx << 1, lazy);
        apply(idx << 1 | 1, lazy);
        seg[idx].lazy = 0;
    };

    std::function<void(int,int,int,int,int,long long)> update = [&](int idx, int l, int r, int ql, int qr, long long dec) {
        if (ql > r || qr < l || seg[idx].mx == 0) return;
        if (ql <= l && r <= qr) {
            apply(idx, dec);
            return;
        }
        push(idx);
        int mid = (l + r) >> 1;
        update(idx << 1, l, mid, ql, qr, dec);
        update(idx << 1 | 1, mid + 1, r, ql, qr, dec);
        seg[idx].mx = std::max(seg[idx << 1].mx, seg[idx << 1 | 1].mx);
        seg[idx].mn = std::min(seg[idx << 1].mn, seg[idx << 1 | 1].mn);
    };

    for (size_t i = 0; i < queries.size(); ++i) {
        int l = queries[i][0];
        int r = queries[i][1];
        int val = queries[i][2];
        update(1, 0, n - 1, l, r, static_cast<long long>(val));
        if (seg[1].mx == 0) return static_cast<int>(i) + 1;
    }
    return -1;
}

