static long long dfs(int pos, int sum, int prodMod, int started, bool tight,
                     const std::vector<int>& dig, int L, int S,
                     std::vector<std::vector<std::vector<std::array<long long,2>>>>& memo) {
    if (pos == L) {
        return (started && sum == S && prodMod == 0) ? 1LL : 0LL;
    }
    if (!tight && memo[pos][sum][prodMod][started] != -1) {
        return memo[pos][sum][prodMod][started];
    }
    int limit = tight ? dig[pos] : 9;
    long long res = 0;
    for (int d = 0; d <= limit; ++d) {
        int nStarted = started || (d != 0);
        int nSum = sum + (nStarted ? d : 0);
        if (nSum > S) continue;
        int nProdMod;
        if (!nStarted) {
            nProdMod = prodMod;
        } else {
            if (!started) {
                nProdMod = d % S;
            } else {
                nProdMod = (int)((1LL * prodMod * (d % S)) % S);
            }
        }
        res += dfs(pos + 1, nSum, nProdMod, nStarted,
                   tight && (d == limit), dig, L, S, memo);
    }
    if (!tight) memo[pos][sum][prodMod][started] = res;
    return res;
}

static long long countUpTo(long long X) {
    if (X <= 0) return 0;
    std::string s = std::to_string(X);
    std::vector<int> dig;
    dig.reserve(s.size());
    for (char c : s) dig.push_back(c - '0');
    int L = (int)dig.size();
    int maxSum = 9 * L;
    long long total = 0;
    for (int S = 1; S <= maxSum; ++S) {
        std::vector<std::vector<std::vector<std::array<long long,2>>>> memo(
            L, std::vector<std::vector<std::array<long long,2>>>(
                S + 1, std::vector<std::array<long long,2>>(
                    S, { -1LL, -1LL })));
        int initProdMod = 1 % S;
        total += dfs(0, 0, initProdMod, 0, true, dig, L, S, memo);
    }
    return total;
}

long long countBeautiful(long long l, long long r) {
    return countUpTo(r) - countUpTo(l - 1);
}

class Solution {
public:
    long long minTime(vector<int>& skill, vector<int>& mana) {
        int n = skill.size(), m = mana.size();
        vector<long long> prefix(n + 1, 0);
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + skill[i];
        long long total = prefix[n];
        long long start = 0; // start time of the current potion at wizard 0
        for (int j = 1; j < m; j++) {
            // wizard i's start for potion j must be >= wizard i's finish for potion j-1;
            // solving for the minimal valid start[j] gives this per-wizard lower bound, take the max
            long long best = LLONG_MIN;
            for (int i = 0; i < n; i++) {
                long long val = start + (long long) mana[j - 1] * prefix[i + 1] - (long long) mana[j] * prefix[i];
                best = max(best, val);
            }
            start = best;
        }
        return start + (long long) mana[m - 1] * total;
    }
};

