long long maxUniqueSubarraySum(const std::vector<int>& nums) {
    long long best = 0;
    long long curSum = 0;
    std::size_t left = 0;
    std::unordered_set<int> seen;
    seen.reserve(nums.size() * 2);
    for (std::size_t right = 0; right < nums.size(); ++right) {
        int v = nums[right];
        while (seen.find(v) != seen.end()) {
            seen.erase(nums[left]);
            curSum -= nums[left];
            ++left;
        }
        seen.insert(v);
        curSum += v;
        if (curSum > best) best = curSum;
    }
    return best;
}

