long long maxContainers(long long n, long long w, long long maxWeight) {
    if (w <= 0) return 0;
    long long weightLimit = maxWeight / w;
    if (n > weightLimit) return weightLimit;
    bool overflow = (n > 0 && n > LLONG_MAX / n);
    long long deckCapacity = overflow ? LLONG_MAX : n * n;
    return std::min(deckCapacity, weightLimit);
}

