class DSU {
public:
    DSU(int n) : parent(n), rank(n, 0) {
        for (int i = 0; i < n; ++i) parent[i] = i;
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (rank[ra] < rank[rb]) std::swap(ra, rb);
        parent[rb] = ra;
        if (rank[ra] == rank[rb]) ++rank[ra];
    }
private:
    std::vector<int> parent;
    std::vector<int> rank;
};

int numberOfComponents(std::vector<std::vector<int>>& properties, int k) {
    int n = static_cast<int>(properties.size());
    if (n == 0) return 0;
    DSU dsu(n);
    std::unordered_map<int, std::vector<int>> propToNodes;
    propToNodes.reserve(n * 2);
    for (int i = 0; i < n; ++i) {
        std::unordered_set<int> uniq(properties[i].begin(), properties[i].end());
        for (int v : uniq) {
            propToNodes[v].push_back(i);
        }
    }
    std::unordered_map<std::uint64_t, int> pairCount;
    pairCount.reserve(1024);
    for (auto& entry : propToNodes) {
        const std::vector<int>& nodes = entry.second;
        for (size_t a = 0; a < nodes.size(); ++a) {
            for (size_t b = a + 1; b < nodes.size(); ++b) {
                int u = nodes[a];
                int v = nodes[b];
                std::uint64_t key = (static_cast<std::uint64_t>(u) << 32) | static_cast<std::uint64_t>(v);
                int c = ++pairCount[key];
                if (c == k) dsu.unite(u, v);
            }
        }
    }
    std::unordered_set<int> roots;
    roots.reserve(n);
    for (int i = 0; i < n; ++i) {
        roots.insert(dsu.find(i));
    }
    return static_cast<int>(roots.size());
}

