std::vector<int> maxActiveSections(const std::string& s, const std::vector<std::vector<int>>& queries) {
    int n = (int)s.size();
    std::vector<int> prefOne(n + 1, 0), prefZero(n + 1, 0);
    std::vector<int> zeroPos;
    for (int i = 0; i < n; ++i) {
        prefOne[i + 1] = prefOne[i] + (s[i] == '1');
        prefZero[i + 1] = prefZero[i] + (s[i] == '0');
        if (s[i] == '0') zeroPos.push_back(i);
    }
    int totalOnes = prefOne[n];
    std::vector<int> ans;
    ans.reserve(queries.size());
    for (const auto& q : queries) {
        int l = q[0];
        int r = q[1];
        int zerosInside = prefZero[r + 1] - prefZero[l];
        bool canTrade = false;
        if (zerosInside >= 2) {
            auto itL = std::lower_bound(zeroPos.begin(), zeroPos.end(), l);
            if (itL != zeroPos.end() && *itL <= r) {
                int firstZero = *itL;
                auto itR = std::upper_bound(zeroPos.begin(), zeroPos.end(), r);
                if (itR != zeroPos.begin()) {
                    --itR;
                    int lastZero = *itR;
                    if (firstZero < lastZero) {
                        int onesBetween = prefOne[lastZero] - prefOne[firstZero + 1];
                        if (onesBetween > 0) canTrade = true;
                    }
                }
            }
        }
        ans.push_back(canTrade ? totalOnes + zerosInside : totalOnes);
    }
    return ans;
}

