int longestPalindromeAfterConcat(const std::string& s, const std::string& t) {
    int n = static_cast<int>(s.size());
    int m = static_cast<int>(t.size());
    int maxLen = 0;
    for (int lenS = 0; lenS <= n; ++lenS) {
        for (int i = 0; i + lenS <= n; ++i) {
            std::string subS = s.substr(i, lenS);
            for (int lenT = 0; lenT <= m; ++lenT) {
                for (int j = 0; j + lenT <= m; ++j) {
                    std::string subT = t.substr(j, lenT);
                    std::string cand = subS + subT;
                    int l = 0, r = static_cast<int>(cand.size()) - 1;
                    bool ok = true;
                    while (l < r) {
                        if (cand[l] != cand[r]) { ok = false; break; }
                        ++l; --r;
                    }
                    if (ok) {
                        int curLen = static_cast<int>(cand.size());
                        if (curLen > maxLen) maxLen = curLen;
                    }
                }
            }
        }
    }
    return maxLen;
}

