struct SlidingMedianCost {
    multiset<long long> lo, hi;
    long long sumLo = 0, sumHi = 0;

    void rebalance() {
        while (lo.size() > hi.size() + 1) {
            auto it = prev(lo.end());
            long long v = *it;
            sumLo -= v; lo.erase(it);
            hi.insert(v); sumHi += v;
        }
        while (hi.size() > lo.size()) {
            auto it = hi.begin();
            long long v = *it;
            sumHi -= v; hi.erase(it);
            lo.insert(v); sumLo += v;
        }
    }
    void add(long long v) {
        if (lo.empty() || v <= *lo.rbegin()) { lo.insert(v); sumLo += v; }
        else { hi.insert(v); sumHi += v; }
        rebalance();
    }
    void remove(long long v) {
        auto it = lo.find(v);
        if (it != lo.end()) { sumLo -= v; lo.erase(it); }
        else { it = hi.find(v); sumHi -= v; hi.erase(it); }
        rebalance();
    }
    long long cost() const {
        long long loSize = (long long)lo.size();
        long long median = *lo.rbegin();
        long long hiSize = (long long)hi.size();
        return (median * loSize - sumLo) + (sumHi - median * hiSize);
    }
};

int minOperations(vector<int> nums, int x, int k) {
    int n = (int)nums.size();
    if (x == 0 || k == 0) return 0;
    int m = n - x + 1;
    vector<long long> cost(m);
    SlidingMedianCost sw;
    for (int i = 0; i < x; ++i) sw.add(nums[i]);
    cost[0] = sw.cost();
    for (int start = 1; start < m; ++start) {
        sw.remove(nums[start-1]);
        sw.add(nums[start+x-1]);
        cost[start] = sw.cost();
    }

    const long long INF = 1000000000000LL;
    vector<long long> dp(n+1, 0);
    for (int t = 0; t < k; ++t) {
        vector<long long> nxt(n+1, INF);
        for (int pos = 0; pos < m; ++pos) {
            long long val = dp[pos] + cost[pos];
            int np = pos + x;
            if (val < nxt[np]) nxt[np] = val;
        }
        for (int i = 0; i < n; ++i) if (nxt[i] < nxt[i+1]) nxt[i+1] = nxt[i];
        dp.swap(nxt);
    }
    return (int)dp[n];
}

class Solution {
public:
    int maxActiveSectionsAfterTrade(std::string s) {
        int n = s.length();
        int ans = 0, i = 0;
        int pre = INT_MIN, mx = 0;
        while (i < n) {
            int j = i + 1;
            while (j < n && s[j] == s[i]) j++;
            int cur = j - i;
            if (s[i] == '1') ans += cur;
            else { mx = std::max(mx, pre + cur); pre = cur; }
            i = j;
        }
        ans += mx;
        return ans;
    }
};

class Solution {
public:
    long long minimumCost(vector<int>& nums, vector<int>& cost, int k) {
        int n = nums.size();
        vector<long long> prefixNums(n + 1, 0), prefixCost(n + 1, 0);
        for (int i = 0; i < n; i++) {
            prefixNums[i + 1] = prefixNums[i] + nums[i];
            prefixCost[i + 1] = prefixCost[i] + cost[i];
        }
        vector<long long> dp(n + 1, LLONG_MAX);
        dp[n] = 0;
        for (int i = n - 1; i >= 0; i--) {
            for (int j = i; j < n; j++) {
                long long val = prefixNums[j + 1] * (prefixCost[j + 1] - prefixCost[i]) +
                                (long long) k * (prefixCost[n] - prefixCost[i]) + dp[j + 1];
                dp[i] = min(dp[i], val);
            }
        }
        return dp[0];
    }
};

