long long maxProductAlternatingSum(const std::vector<int>& nums, long long k, long long limit) {
    std::unordered_map<long long, long long> dpEven, dpOdd;
    dpEven.reserve(1024);
    dpOdd.reserve(1024);
    for (int x : nums) {
        long long val = static_cast<long long>(x);
        if (val <= limit) {
            auto it = dpOdd.find(val);
            if (it == dpOdd.end() || val > it->second) dpOdd[val] = val;
        }
        std::vector<std::pair<long long, long long>> evenSnap(dpEven.begin(), dpEven.end());
        std::vector<std::pair<long long, long long>> oddSnap(dpOdd.begin(), dpOdd.end());
        for (const auto& p : evenSnap) {
            long long curProd = p.second;
            if (val != 0 && curProd > limit / val) continue;
            long long newProd = curProd * val;
            long long newSum = p.first + val;
            auto it = dpOdd.find(newSum);
            if (it == dpOdd.end() || newProd > it->second) dpOdd[newSum] = newProd;
        }
        for (const auto& p : oddSnap) {
            long long curProd = p.second;
            if (val != 0 && curProd > limit / val) continue;
            long long newProd = curProd * val;
            long long newSum = p.first - val;
            auto it = dpEven.find(newSum);
            if (it == dpEven.end() || newProd > it->second) dpEven[newSum] = newProd;
        }
    }
    long long ans = -1;
    auto it = dpEven.find(k);
    if (it != dpEven.end()) ans = std::max(ans, it->second);
    it = dpOdd.find(k);
    if (it != dpOdd.end()) ans = std::max(ans, it->second);
    return ans;
}

