int longestPalindromeAfterSubstringConcatII(const std::string& s, const std::string& t) {
    auto longestPalindromicSubstring = [](const std::string& str) -> int {
        int n = static_cast<int>(str.size());
        int best = 0;
        for (int center = 0; center < n; ++center) {
            int l = center, r = center;
            while (l >= 0 && r < n && str[l] == str[r]) {
                best = std::max(best, r - l + 1);
                --l;
                ++r;
            }
            l = center;
            r = center + 1;
            while (l >= 0 && r < n && str[l] == str[r]) {
                best = std::max(best, r - l + 1);
                --l;
                ++r;
            }
        }
        return best;
    };

    auto process = [&](const std::string& a, const std::string& b, int& bestEven, int& bestOdd) {
        int n = static_cast<int>(a.size());
        int m = static_cast<int>(b.size());
        std::string revB = b;
        std::reverse(revB.begin(), revB.end());
        std::vector<int> prev(m + 1, 0);
        int maxLen = 0;
        int maxOdd = 0;
        for (int i = 0; i < n; ++i) {
            std::vector<int> cur(m + 1, 0);
            for (int j = 0; j < m; ++j) {
                if (a[i] == revB[j]) {
                    cur[j + 1] = prev[j] + 1;
                    int len = cur[j + 1];
                    if (len > maxLen) maxLen = len;
                    int startInB = m - 1 - j;
                    bool canExtendRightInA = i + 1 < n;
                    bool canExtendLeftInB = startInB > 0;
                    if (canExtendRightInA || canExtendLeftInB) {
                        int oddLen = 2 * len + 1;
                        if (oddLen > maxOdd) maxOdd = oddLen;
                    }
                }
            }
            prev.swap(cur);
        }
        bestEven = std::max(bestEven, 2 * maxLen);
        bestOdd = std::max(bestOdd, maxOdd);
    };

    int bestEven = 0, bestOdd = 0;
    process(s, t, bestEven, bestOdd);
    process(t, s, bestEven, bestOdd);
    int bestSingle = std::max(longestPalindromicSubstring(s), longestPalindromicSubstring(t));
    return std::max({bestSingle, bestEven, bestOdd});
}

