static void fwht(vector<long long>& a, bool invert) {
    int n = (int)a.size();
    for (int h = 1; h < n; h <<= 1) {
        for (int i = 0; i < n; i += h << 1) {
            for (int j = i; j < i + h; ++j) {
                long long x = a[j], y = a[j+h];
                a[j] = x + y; a[j+h] = x - y;
            }
        }
    }
    if (invert) for (auto& x : a) x /= n;
}

size_t countUniqueXorTriplets(const vector<int>& nums) {
    int maxv = *max_element(nums.begin(), nums.end());
    int size = 1;
    while (size <= maxv) size <<= 1;
    vector<long long> a(size, 0);
    for (int v : nums) a[v] = 1;
    fwht(a, false);
    vector<long long> b(size);
    for (int i = 0; i < size; ++i) b[i] = a[i]*a[i]*a[i];
    fwht(b, true);
    unordered_set<int> achievable;
    for (int v : nums) achievable.insert(v);          // i==j==k case
    for (int v = 0; v < size; ++v) if (b[v] != 0) achievable.insert(v);  // any triple (with possible index repeats)
    return achievable.size();
}

