class Router {
public:
    Router(int memoryLimit) : limit(memoryLimit) {}

    bool addPacket(int source, int destination, int timestamp) {
        uint64_t key = ((uint64_t)source << 40) ^ ((uint64_t)destination << 20) ^ (uint64_t)timestamp;
        if (packetSet.find(key) != packetSet.end()) return false;
        if ((int)queue.size() == limit) {
            const Packet &old = queue.front();
            uint64_t oldKey = ((uint64_t)old.source << 40) ^ ((uint64_t)old.dest << 20) ^ (uint64_t)old.time;
            packetSet.erase(oldKey);
            auto itMap = destMap.find(old.dest);
            if (itMap != destMap.end()) {
                auto &ms = itMap->second;
                auto itTs = ms.find(old.time);
                if (itTs != ms.end()) ms.erase(itTs);
                if (ms.empty()) destMap.erase(itMap);
            }
            queue.pop_front();
        }
        Packet p{source, destination, timestamp};
        queue.push_back(p);
        packetSet.insert(key);
        destMap[destination].insert(timestamp);
        return true;
    }

    std::vector<int> forwardPacket() {
        if (queue.empty()) return {};
        const Packet p = queue.front();
        queue.pop_front();
        uint64_t key = ((uint64_t)p.source << 40) ^ ((uint64_t)p.dest << 20) ^ (uint64_t)p.time;
        packetSet.erase(key);
        auto itMap = destMap.find(p.dest);
        if (itMap != destMap.end()) {
            auto &ms = itMap->second;
            auto itTs = ms.find(p.time);
            if (itTs != ms.end()) ms.erase(itTs);
            if (ms.empty()) destMap.erase(itMap);
        }
        return {p.source, p.dest, p.time};
    }

    int getCount(int destination, int startTime, int endTime) {
        auto itMap = destMap.find(destination);
        if (itMap == destMap.end()) return 0;
        const auto &ms = itMap->second;
        auto lo = ms.lower_bound(startTime);
        auto hi = ms.upper_bound(endTime);
        return static_cast<int>(std::distance(lo, hi));
    }

private:
    struct Packet {
        int source;
        int dest;
        int time;
    };
    int limit;
    std::deque<Packet> queue;
    std::unordered_set<uint64_t> packetSet;
    std::unordered_map<int, std::multiset<int>> destMap;
};

