std::string smallestPalindromicPermutation(const std::string& s) {
    std::array<int, 256> freq{};
    for (unsigned char ch : s) {
        ++freq[ch];
    }
    std::string left;
    left.reserve(s.size() / 2);
    char middleChar = '\0';
    bool hasMiddle = false;
    for (int i = 0; i < 256; ++i) {
        int cnt = freq[i];
        if (cnt == 0) continue;
        int half = cnt >> 1;
        if (half) left.append(half, static_cast<char>(i));
        if (cnt & 1) {
            middleChar = static_cast<char>(i);
            hasMiddle = true;
        }
    }
    std::string result;
    result.reserve(s.size());
    result += left;
    if (hasMiddle) result.push_back(middleChar);
    std::string right = left;
    std::reverse(right.begin(), right.end());
    result += right;
    return result;
}

