static const unsigned long long INF = 2000000000000000000ULL;

static vector<unsigned long long> factTable;

static void buildFact(int n) {
    factTable.assign(n + 1, 1);
    for (int i = 1; i <= n; ++i) {
        if (factTable[i - 1] > INF / static_cast<unsigned long long>(i)) {
            factTable[i] = INF;
        } else {
            unsigned long long prod = factTable[i - 1] * static_cast<unsigned long long>(i);
            factTable[i] = prod >= INF ? INF : prod;
        }
    }
}

static unsigned long long countPerms(const vector<int>& cnt, int total) {
    if (factTable[total] == INF) return INF;
    unsigned long long res = factTable[total];
    for (int c : cnt) {
        if (c == 0) continue;
        if (factTable[c] == INF) return INF;
        res /= factTable[c];
    }
    return res >= INF ? INF : res;
}

string smallestPalindromicRearrangementII(const string& s, long long k) {
    if (k <= 0) return "";
    int freq[26] = {0};
    for (char ch : s) freq[ch - 'a']++;
    int oddIdx = -1;
    for (int i = 0; i < 26; ++i) {
        if (freq[i] % 2) {
            if (oddIdx != -1) return "";
            oddIdx = i;
        }
    }
    string middle = "";
    if (oddIdx != -1) middle.push_back('a' + oddIdx);
    vector<int> halfCnt(26, 0);
    int halfLen = 0;
    for (int i = 0; i < 26; ++i) {
        halfCnt[i] = freq[i] / 2;
        halfLen += halfCnt[i];
    }
    buildFact(halfLen);
    unsigned long long totalPerms = countPerms(halfCnt, halfLen);
    if (static_cast<unsigned long long>(k) > totalPerms) return "";
    string left;
    left.reserve(halfLen);
    for (int pos = 0; pos < halfLen; ++pos) {
        for (int i = 0; i < 26; ++i) {
            if (halfCnt[i] == 0) continue;
            halfCnt[i]--;
            unsigned long long cntPerm = countPerms(halfCnt, halfLen - pos - 1);
            if (static_cast<unsigned long long>(k) > cntPerm) {
                k -= cntPerm;
                halfCnt[i]++;
            } else {
                left.push_back('a' + i);
                break;
            }
        }
    }
    string right = left;
    std::reverse(right.begin(), right.end());
    return left + middle + right;
}

