int maxSizeNonDecreasing(const std::vector<int>& nums) {
    std::vector<int> stack;
    stack.reserve(nums.size());
    for (int cur : nums) {
        while (!stack.empty() && stack.back() > cur) {
            cur = std::max(stack.back(), cur);
