}

#include <bits/stdc++.h>
struct Node {
    int prod;
    int cnt[5];
    Node() : prod(1) { cnt[0]=cnt[1]=cnt[2]=cnt[3]=cnt[4]=0; }
};
static int K;
static std::vector<Node> seg;
static std::vector<int> arr;

Node mergeNode(const Node& L, const Node& R){
    Node res;
    res.prod = (int)((1LL * L.prod * R.prod) % K);
    for(int i=0;i<K;i++) res.cnt[i]=L.cnt[i];
    for(int r=0;r<K;r++){
        int shifted = (int)((1LL * L.prod * r) % K);
        res.cnt[shifted] += R.cnt[r];
    }
    return res;
}
void build(int idx,int l,int r){
    if(l==r){
        Node nd;
        nd.prod = arr[l] % K;
        nd.cnt[nd.prod] = 1;
        seg[idx]=nd;
        return;
    }
    int mid=(l+r)/2;
    build(idx*2,l,mid);
    build(idx*2+1,mid+1,r);
    seg[idx]=mergeNode(seg[idx*2],seg[idx*2+1]);
}
void pointUpdate(int idx,int l,int r,int pos,int val){
    if(l==r){
        Node nd;
        nd.prod = val % K;
        nd.cnt[nd.prod] = 1;
        seg[idx]=nd;
        return;
    }
    int mid=(l+r)/2;
    if(pos<=mid) pointUpdate(idx*2,l,mid,pos,val);
    else pointUpdate(idx*2+1,mid+1,r,pos,val);
    seg[idx]=mergeNode(seg[idx*2],seg[idx*2+1]);
}
Node rangeQuery(int idx,int l,int r,int ql,int qr){
    if(ql>r || qr<l){
        Node neutral;
        neutral.prod = 1 % K;
        return neutral;
    }
    if(ql<=l && r<=qr) return seg[idx];
    int mid=(l+r)/2;
    Node left = rangeQuery(idx*2,l,mid,ql,qr);
    Node right = rangeQuery(idx*2+1,mid+1,r,ql,qr);
    return mergeNode(left,right);
}
std::vector<long long> resultArray(std::vector<int> nums, int k, const std::vector<std::vector<int>>& queries){
    K = k;
    int n = (int)nums.size();
    arr = std::move(nums);
    seg.assign(4*n+4, Node());
    build(1,0,n-1);
    std::vector<long long> ans;
    ans.reserve(queries.size());
    for(const auto& q: queries){
        int index = q[0];
        int value = q[1];
        int start = q[2];
        int xi = q[3];
        arr[index]=value;
        pointUpdate(1,0,n-1,index,value);
        Node leftNode;
        if(start==0){
            leftNode.prod = 1 % K;
        }else{
            leftNode = rangeQuery(1,0,n-1,0,start-1);
        }
        int prodBefore = leftNode.prod % K;
        Node rightNode = rangeQuery(1,0,n-1,start,n-1);
        long long cnt=0;
        for(int r=0;r<K;r++){
            if( (int)((1LL*prodBefore*r)%K) == xi ){
                cnt += rightNode.cnt[r];
            }
        }
        ans.push_back(cnt);
    }
    return ans;
}

