std::vector<int> decimalToBase(const std::string& s, int b) {
    if (s == "0") return {0};
    std::string cur = s;
    std::vector<int> rev;
    while (!(cur.size() == 1 && cur[0] == '0')) {
        std::string next;
        int carry = 0;
        for (char ch : cur) {
            int num = carry * 10 + (ch - '0');
            int q = num / b;
            carry = num % b;
            if (!next.empty() || q != 0) next.push_back(char('0' + q));
        }
        rev.push_back(carry);
        cur = next.empty() ? "0" : next;
    }
    std::reverse(rev.begin(), rev.end());
    return rev;
}

std::string decrementString(const std::string& s) {
    std::string res = s;
    int i = (int)res.size() - 1;
    while (i >= 0 && res[i] == '0') {
        res[i] = '9';
        --i;
    }
    if (i >= 0) {
        res[i] = char(res[i] - 1);
    }
    size_t pos = res.find_first_not_of('0');
    if (pos == std::string::npos) return "0";
    return res.substr(pos);
}

long long countUpTo(const std::vector<int>& digits, int b) {
    int n = (int)digits.size();
    std::vector<std::vector<std::vector<long long>>> memo(n, std::vector<std::vector<long long>>(b, std::vector<long long>(2, -1)));
    std::function<long long(int,int,bool,bool)> dfs = [&](int idx, int prev, bool tight, bool started) -> long long {
        if (idx == n) return 1LL;
        if (!tight && memo[idx][prev][started] != -1) return memo[idx][prev][started];
        int limit = tight ? digits[idx] : b - 1;
        long long res = 0;
        for (int d = 0; d <= limit; ++d) {
            bool nstarted = started || d != 0;
            bool ntight = tight && (d == limit);
            if (!nstarted) {
                res += dfs(idx + 1, 0, ntight, false);
            } else {
                if (!started) {
                    res += dfs(idx + 1, d, ntight, true);
                } else if (d >= prev) {
                    res += dfs(idx + 1, d, ntight, true);
                }
            }
            if (res >= MOD) res -= MOD;
        }
        if (!tight) memo[idx][prev][started] = res;
        return res;
    };
    return dfs(0, 0, true, false) % MOD;
}

void solve() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    std::string l, r;
    int b;
    if (!(std::cin >> l >> r >> b)) return;
    std::vector<int> rDigits = decimalToBase(r, b);
    long long cntR = countUpTo(rDigits, b);
    long long cntLMinus = 0;
    if (l != "0") {
        std::string lMinus = decrementString(l);
        std::vector<int> lDigits = decimalToBase(lMinus, b);
        cntLMinus = countUpTo(lDigits, b);
    }
    long long ans = (cntR - cntLMinus) % MOD;
    if (ans < 0) ans += MOD;
    std::cout << ans << "\n";
}

