int countCells(std::vector<std::vector<char>>& grid, std::string pattern) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    int M = m * n;
    int L = static_cast<int>(pattern.size());

    std::string rowStr;
    rowStr.reserve(M);
    for (int i = 0; i < m; ++i)
        for (int j = 0; j < n; ++j)
            rowStr.push_back(grid[i][j]);

    std::string colStr;
    colStr.reserve(M);
    for (int j = 0; j < n; ++j)
        for (int i = 0; i < m; ++i)
            colStr.push_back(grid[i][j]);

    auto kmp = [&](const std::string& text) -> std::vector<int> {
        std::vector<int> pi(L, 0);
        for (int i = 1; i < L; ++i) {
            int j = pi[i - 1];
            while (j > 0 && pattern[i] != pattern[j]) j = pi[j - 1];
            if (pattern[i] == pattern[j]) ++j;
            pi[i] = j;
        }
        std::vector<int> occ;
        int j = 0;
        for (int i = 0; i < static_cast<int>(text.size()); ++i) {
            while (j > 0 && text[i] != pattern[j]) j = pi[j - 1];
            if (text[i] == pattern[j]) ++j;
            if (j == L) {
                occ.push_back(i - L + 1);
                j = pi[j - 1];
            }
        }
        return occ;
    };

    std::vector<int> diffRow(M + 1, 0), diffCol(M + 1, 0);

    for (int start : kmp(rowStr)) {
        diffRow[start] += 1;
        diffRow[start + L] -= 1;
    }
    for (int start : kmp(colStr)) {
        diffCol[start] += 1;
        diffCol[start + L] -= 1;
    }

    std::vector<char> coveredRow(M, 0), coveredCol(M, 0);
    int cur = 0;
    for (int i = 0; i < M; ++i) {
        cur += diffRow[i];
        coveredRow[i] = (cur > 0);
    }
    cur = 0;
    for (int i = 0; i < M; ++i) {
        cur += diffCol[i];
        coveredCol[i] = (cur > 0);
    }

    int ans = 0;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            int idxRow = i * n + j;
            int idxCol = j * m + i;
            if (coveredRow[idxRow] && coveredCol[idxCol]) ++ans;
        }
    }
    return ans;
}

