std::vector<long long> find_x_value(const std::vector<int>& nums, int k) {
    std::vector<long long> result(k, 0);
    std::unordered_map<int, long long> dp, ndp;
    for (int v : nums) {
        int single_rem = v % k;
        if (single_rem < 0) single_rem += k;
        result[single_rem] += 1;
        ndp.clear();
        ndp[single_rem] = 1;
        for (const auto& p : dp) {
            int r = p.first;
            long long cnt = p.second;
            long long prod = static_cast<long long>(r) * v;
            int new_rem = static_cast<int>(prod % k);
            if (new_rem < 0) new_rem += k;
            ndp[new_rem] += cnt;
            result[new_rem] += cnt;
        }
        dp.swap(ndp);
    }
    return result;
}

