std::vector<bool> pathExistenceQueries(int n, const std::vector<int>& nums, int maxDiff, const std::vector<std::vector<int>>& queries) {
    std::vector<int> prefix(n, 0);
    for (int i = 1; i < n; ++i) {
        prefix[i] = prefix[i - 1] + (nums[i] - nums[i - 1] > maxDiff ? 1 : 0);
    }
    std::vector<bool> answer;
    answer.reserve(queries.size());
    for (const auto& q : queries) {
        int u = q[0];
        int v = q[1];
        if (u > v) std::swap(u, v);
        answer.push_back(prefix[v] - prefix[u] == 0);
    }
    return answer;
}

