std::vector<int> baseUnitConversion(const std::vector<std::vector<int>>& conversions) {
    int n = (int)conversions.size() + 1;
    const int MOD = 1000000007;
    std::vector<std::vector<std::pair<int,int>>> adj(n);
    for (const auto& conv : conversions) {
        int src = conv[0];
        int tgt = conv[1];
        int factor = conv[2];
        adj[src].emplace_back(tgt, factor);
    }
    std::vector<int> result(n, 0);
    std::vector<int64_t> temp(n, 0);
    std::vector<char> visited(n, 0);
    std::vector<int> stack;
    stack.reserve(n);
    temp[0] = 1;
    result[0] = 1;
    visited[0] = 1;
    stack.push_back(0);
    while (!stack.empty()) {
        int u = stack.back();
        stack.pop_back();
        for (const auto& p : adj[u]) {
            int v = p.first;
            int factor = p.second;
            if (!visited[v]) {
                temp[v] = (temp[u] * factor) % MOD;
                result[v] = static_cast<int>(temp[v]);
                visited[v] = 1;
                stack.push_back(v);
            }
        }
    }
    return result;
}

