long long maxProfit(int n, const std::vector<std::pair<int,int>>& edges, const std::vector<long long>& score) {
    using uint = unsigned int;
    std::vector<uint> preMask(n, 0);
    for (const auto& e : edges) {
        preMask[e.second] |= (1u << e.first);
    }
    uint totalMask = (1u << n) - 1u;
    const long long NEG = LLONG_MIN / 4;
    std::vector<long long> dp(1u << n, NEG);
    dp[0] = 0;
    std::vector<int> popcnt(1u << n, 0);
    for (uint m = 1; m <= totalMask; ++m) popcnt[m] = popcnt[m >> 1] + (m & 1);
    for (uint mask = 0; mask <= totalMask; ++mask) {
        long long cur = dp[mask];
        if (cur == NEG) continue;
        int pos = popcnt[mask] + 1;
        uint available = (~mask) & totalMask;
        while (available) {
            uint v = __builtin_ctz(available);
            available &= available - 1;
            if ((preMask[v] & ~mask) != 0) continue;
            uint next = mask | (1u << v);
            long long profit = cur + score[v] * pos;
            if (profit > dp[next]) dp[next] = profit;
        }
    }
    return dp[totalMask];
}

