int countBuildings(int n, std::vector<std::vector<int>>& buildings) {
    std::unordered_map<int, std::pair<int, int>> rowMap;
    std::unordered_map<int, std::pair<int, int>> colMap;
    rowMap.reserve(buildings.size() * 2);
    colMap.reserve(buildings.size() * 2);
    for (const auto& b : buildings) {
        int x = b[0];
        int y = b[1];
        auto itRow = rowMap.find(y);
        if (itRow == rowMap.end()) {
            rowMap.emplace(y, std::make_pair(x, x));
        } else {
            itRow->second.first = std::min(itRow->second.first, x);
            itRow->second.second = std::max(itRow->second.second, x);
        }
        auto itCol = colMap.find(x);
        if (itCol == colMap.end()) {
            colMap.emplace(x, std::make_pair(y, y));
        } else {
            itCol->second.first = std::min(itCol->second.first, y);
            itCol->second.second = std::max(itCol->second.second, y);
        }
    }
    int covered = 0;
    for (const auto& b : buildings) {
        int x = b[0];
        int y = b[1];
        const auto& row = rowMap[y];
        const auto& col = colMap[x];
        if (x > row.first && x < row.second && y > col.first && y < col.second) {
            ++covered;
        }
    }
    return covered;
}

class Solution {
public:
    long long minTravelTime(int l, int n, int k, vector<int>& position, vector<int>& time) {
        long long INF = LLONG_MAX / 2;
        vector<long long> prefix(n, 0);
        for (int i = 0; i < n - 1; i++) prefix[i + 1] = prefix[i] + time[i];
        vector<vector<vector<long long>>> dp(n + 1, vector<vector<long long>>(n, vector<long long>(k + 1, INF)));
        dp[0][0][0] = 0;
        for (int c = 0; c < n - 1; c++) {
            for (int pidx = 0; pidx <= n; pidx++) {
                for (int m = 0; m <= k; m++) {
                    long long cost0 = dp[pidx][c][m];
                    if (cost0 >= INF) continue;
                    int p = pidx - 1;
                    long long rate = prefix[c + 1] - prefix[p + 1];
                    for (int i2 = c + 1; i2 < n; i2++) {
                        int mergesAdd = i2 - c - 1;
                        int m2 = m + mergesAdd;
                        if (m2 > k) continue;
                        long long newcost = cost0 + rate * (position[i2] - position[c]);
                        if (newcost < dp[c + 1][i2][m2]) dp[c + 1][i2][m2] = newcost;
                    }
                }
            }
        }
        long long ans = INF;
        for (int pidx = 0; pidx <= n; pidx++) ans = min(ans, dp[pidx][n - 1][k]);
        return ans;
    }
};

