std::vector<int> shortestPathLengths(int n, const std::vector<int>& nums, int maxDiff, const std::vector<std::vector<int>>& queries) {
    std::vector<int> idx(n);
    for (int i = 0; i < n; ++i) idx[i] = i;
    std::sort(idx.begin(), idx.end(), [&](int a, int b) {
        int diff = nums[a] - nums[b];
        return diff != 0 ? diff < 0 : a < b;
    });
    std::vector<int> sortedVals(n), pos(n);
    for (int i = 0; i < n; ++i) {
        sortedVals[i] = nums[idx[i]];
        pos[idx[i]] = i;
    }
    std::vector<int> far(n);
    int r = 0;
    for (int i = 0; i < n; ++i) {
        if (r < i) r = i;
        while (r + 1 < n && sortedVals[r + 1] - sortedVals[i] <= maxDiff) ++r;
        far[i] = r;
    }
    int LOG = static_cast<int>(std::ceil(std::log2(n))) + 1;
    std::vector<std::vector<int>> up(LOG, std::vector<int>(n));
    for (int i = 0; i < n; ++i) up[0][i] = far[i];
    for (int k = 1; k < LOG; ++k) {
        const std::vector<int>& prev = up[k - 1];
        std::vector<int>& cur = up[k];
        for (int i = 0; i < n; ++i) cur[i] = prev[prev[i]];
    }
    std::vector<int> answers(queries.size());
    for (size_t qi = 0; qi < queries.size(); ++qi) {
        int u = queries[qi][0];
        int v = queries[qi][1];
        if (u == v) {
            answers[qi] = 0;
            continue;
        }
        int pu = pos[u];
        int pv = pos[v];
        if (pu > pv) {
            std::swap(pu, pv);
        }
        int cur = pu;
        int steps = 0;
        for (int k = LOG - 1; k >= 0; --k) {
            int nxt = up[k][cur];
            if (nxt < pv) {
                cur = nxt;
                steps += 1 << k;
            }
        }
        answers[qi] = (far[cur] >= pv) ? steps + 1 : -1;
    }
    return answers;
}

