int maxProductTwoDigits(long long n) {
    std::array<int, 10> freq{};
    if (n == 0) {
        freq[0] = 1;
    } else {
        while (n > 0) {
            freq[n % 10]++;
            n /= 10;
        }
    }
    int first = -1;
    for (int d = 9; d >= 0; --d) {
        if (freq[d] > 0) {
            first = d;
            break;
        }
    }
    if (first == -1) return 0;
    if (freq[first] >= 2) return first * first;
    int second = -1;
    for (int d = first - 1; d >= 0; --d) {
        if (freq[d] > 0) {
            second = d;
            break;
        }
    }
    if (second == -1) return 0;
    return first * second;
}

