int minDeletions(const std::string& s, int k) {
    std::unordered_map<char, int> freq;
    for (char ch : s) {
        ++freq[ch];
    }
    std::vector<int> counts;
    counts.reserve(freq.size());
    for (const auto& p : freq) {
        counts.push_back(p.second);
    }
    int distinct = static_cast<int>(counts.size());
    if (distinct <= k) return 0;
    int toRemove = distinct - k;
    std::nth_element(counts.begin(), counts.begin() + toRemove, counts.end());
    int deletions = 0;
    for (int i = 0; i < toRemove; ++i) {
        deletions += counts[i];
    }
    return deletions;
}

