long long subtreeInversionSum(vector<pair<int,int>>& edges, vector<long long>& nums, int k) {
    int n = (int)nums.size();
    vector<vector<int>> g(n);
    for (auto& e : edges) { int x=e.first,y=e.second; g[x].push_back(y); g[y].push_back(x); }
    vector<vector<array<long long,2>>> memo(n, vector<array<long long,2>>(max(k,1), {0,0}));
    vector<vector<char>> computed(n, vector<char>(max(k,1), 0));
    function<long long(int,int,int,bool)> dfs = [&](int x, int fa, int cd, bool parity) -> long long {
        if (computed[x][cd] & (1 << (parity?1:0))) return memo[x][cd][parity];
        long long res = parity ? -nums[x] : nums[x];
        for (int y : g[x]) if (y != fa) res += dfs(y, x, max(cd-1,0), parity);
        if (cd == 0) {
            long long s = parity ? nums[x] : -nums[x];
            for (int y : g[x]) if (y != fa) s += dfs(y, x, k-1, !parity);
            if (s > res) res = s;
        }
        memo[x][cd][parity] = res;
        computed[x][cd] |= (1 << (parity?1:0));
        return res;
    };
    return dfs(0, -1, 0, false);
}

static const long long MOD = 1000000007LL;

int magicalSum(int m, int k, const std::vector<int>& nums) {
    int n = (int)nums.size();
    std::vector<std::vector<long long>> C(m+1, std::vector<long long>(m+1, 0));
    for (int i = 0; i <= m; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j) C[i][j] = (C[i-1][j-1] + (j<=i-1?C[i-1][j]:0)) % MOD;
    }
    std::map<std::tuple<int,int,int,int>, long long> memo;
    std::function<long long(int,int,int,int)> dp = [&](int mm, int kk, int i, int carry) -> long long {
        int popcarry = __builtin_popcount((unsigned)carry);
        if (mm < 0 || kk < 0 || (mm + popcarry < kk)) return 0;
        if (mm == 0) return (kk == popcarry) ? 1 : 0;
        if (i == n) return 0;
        auto key = std::make_tuple(mm, kk, i, carry);
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        long long res = 0;
        for (int count = 0; count <= mm; ++count) {
            long long p = 1, base = nums[i] % MOD; int e = count;
            while (e > 0) { if (e&1) p = p*base%MOD; base=base*base%MOD; e>>=1; }
            long long contribution = C[mm][count] * p % MOD;
            int newCarry = carry + count;
            long long sub = dp(mm-count, kk-(newCarry&1), i+1, newCarry>>1);
            res = (res + contribution * sub) % MOD;
        }
        memo[key] = res;
        return res;
    };
    return (int)dp(m, k, 0, 0);
}

