int mostFrequentVowelConsonant(const std::string& s) {
    std::array<int, 26> freq{}; 
    for (char ch : s) {
        unsigned char uc = static_cast<unsigned char>(ch);
        if (std::isalpha(uc)) {
            char lower = static_cast<char>(std::tolower(uc));
            ++freq[lower - 'a'];
        }
    }
    const std::array<bool, 26> isVowel = []{
        std::array<bool, 26> a{};
        a['a' - 'a'] = a['e' - 'a'] = a['i' - 'a'] = a['o' - 'a'] = a['u' - 'a'] = true;
        return a;
    }();
    int maxVowel = 0, maxConsonant = 0;
    for (int i = 0; i < 26; ++i) {
        int cnt = freq[i];
        if (isVowel[i]) {
            if (cnt > maxVowel) maxVowel = cnt;
        } else {
            if (cnt > maxConsonant) maxConsonant = cnt;
        }
    }
    return maxVowel + maxConsonant;
}

#include <bits/stdc++.h>

int smallestIndex(const std::vector<int>& nums) {
    for (int i = 0, n = static_cast<int>(nums.size()); i < n; ++i) {
        long long v = nums[i];
        if (v < 0) v = -v;
        int digitSum = 0;
        while (v > 0) {
            digitSum += static_cast<int>(v % 10);
            v /= 10;
        }
        if (digitSum == i) return i;
    }
    return -1;
}

#include <bits/stdc++.h>

int maxWeightedKEdgePath(int n, const std::vector<std::vector<int>>& edges, int k, int t) {
    const long long NEG = LLONG_MIN / 4;
    std::vector<long long> prev(n, NEG), cur(n, NEG);
    for (int i = 0; i < n; ++i) prev[i] = 0;
    for (int step = 1; step <= k; ++step) {
        std::fill(cur.begin(), cur.end(), NEG);
        for (const auto& e : edges) {
            int u = e[0];
            int v = e[1];
            int w = e[2];
            if (prev[u] != NEG) {
                long long nw = prev[u] + w;
                if (nw < t && nw > cur[v]) {
                    cur[v] = nw;
                }
            }
        }
        prev.swap(cur);
    }
    long long ans = NEG;
    for (long long val : prev) ans = std::max(ans, val);
    return ans == NEG ? -1 : static_cast<int>(ans);
}

#include <bits/stdc++.h>
#include <vector>

bool equalSumGridPartition(const std::vector<std::vector<int>>& grid) {
    std::size_t m = grid.size();
    if (m == 0) return false;
    std::size_t n = grid[0].size();
    if (n == 0) return false;

    std::vector<long long> rowSums(m, 0);
    std::vector<long long> colSums(n, 0);
    long long total = 0;

    for (std::size_t i = 0; i < m; ++i) {
        const auto& row = grid[i];
        for (std::size_t j = 0; j < n; ++j) {
            int v = row[j];
            total += v;
            rowSums[i] += v;
            colSums[j] += v;
        }
    }

    long long prefix = 0;
    for (std::size_t i = 0; i + 1 < m; ++i) {
        prefix += rowSums[i];
        if (prefix * 2 == total) return true;
    }

    prefix = 0;
    for (std::size_t j = 0; j + 1 < n; ++j) {
        prefix += colSums[j];
        if (prefix * 2 == total) return true;
    }

    return false;
}

#include <bits/stdc++.h>
std::vector<long long> minimumWeightedSubgraph(const std::vector<std::vector<int>>& edges, const std::vector<std::vector<int>>& queries) {
    int maxNode = 0;
    for (const auto& e : edges) {
        maxNode = std::max(maxNode, std::max(e[0], e[1]));
    }
    int n = maxNode + 1;
    std::vector<std::vector<std::pair<int,int>>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1], w = e[2];
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }
    int LOG = 1;
    while ((1 << LOG) <= n) ++LOG;
    std::vector<int> depth(n, 0);
    std::vector<long long> distRoot(n, 0);
    std::vector<std::vector<int>> up(LOG, std::vector<int>(n, -1));
    int root = edges.empty() ? 0 : edges[0][0];
    std::stack<int> st;
    st.push(root);
    up[0][root] = -1;
    while (!st.empty()) {
        int u = st.top(); st.pop();
        for (const auto& p : adj[u]) {
            int v = p.first;
            int w = p.second;
            if (v == up[0][u]) continue;
            up[0][v] = u;
            depth[v] = depth[u] + 1;
            distRoot[v] = distRoot[u] + w;
            st.push(v);
        }
    }
    for (int k = 1; k < LOG; ++k) {
        for (int v = 0; v < n; ++v) {
            int mid = up[k-1][v];
            if (mid != -1) up[k][v] = up[k-1][mid];
        }
    }
    auto lca = [&](int a, int b) {
        if (depth[a] < depth[b]) std::swap(a, b);
        int diff = depth[a] - depth[b];
        for (int k = LOG - 1; k >= 0; --k) {
            if (diff & (1 << k)) a = up[k][a];
        }
        if (a == b) return a;
        for (int k = LOG - 1; k >= 0; --k) {
            if (up[k][a] != -1 && up[k][a] != up[k][b]) {
                a = up[k][a];
                b = up[k][b];
            }
        }
        return up[0][a];
    };
    auto dist = [&](int a, int b) {
        int c = lca(a, b);
        return distRoot[a] + distRoot[b] - 2LL * distRoot[c];
    };
    std::vector<long long> answer;
    answer.reserve(queries.size());
    for (const auto& q : queries) {
        int s1 = q[0], s2 = q[1], d = q[2];
        long long d1 = dist(s1, s2);
        long long d2 = dist(s1, d);
        long long d3 = dist(s2, d);
        answer.push_back((d1 + d2 + d3) / 2);
    }
    return answer;
}

#include <bits/stdc++.h>
using namespace std;

long long maximumEdgeSum(int n, const vector<pair<int,int>>& edges) {
    vector<vector<int>> adj(n);
    for (auto& e : edges) { adj[e.first].push_back(e.second); adj[e.second].push_back(e.first); }
    vector<int> deg(n);
    for (int i = 0; i < n; ++i) deg[i] = (int)adj[i].size();
    bool isCycle = true;
    for (int i = 0; i < n; ++i) if (deg[i] != 2) { isCycle = false; break; }

    vector<int> order;
    if (isCycle) {
        int start = 0;
        order.push_back(start);
        int prev = -1, cur = start;
        while (true) {
            int nxt = -1;
            for (int x : adj[cur]) if (x != prev) { nxt = x; break; }
            if (nxt == start) break;
            order.push_back(nxt);
            prev = cur; cur = nxt;
        }
    } else {
        int start = -1;
        for (int i = 0; i < n; ++i) if (deg[i] == 1) { start = i; break; }
        order.push_back(start);
        int prev = -1, cur = start;
        while (true) {
            int nxt = -1;
            for (int x : adj[cur]) if (x != prev) { nxt = x; break; }
            if (nxt == -1) break;
            order.push_back(nxt);
            prev = cur; cur = nxt;
        }
    }

    deque<int> dq;
    dq.push_back(n);
    bool toggle = true;
    for (int v = n-1; v >= 1; --v) {
        if (toggle) dq.push_front(v); else dq.push_back(v);
        toggle = !toggle;
    }
    vector<long long> valOfNode(n);
    for (int i = 0; i < n; ++i) valOfNode[order[i]] = dq[i];

    long long total = 0;
    for (auto& e : edges) total += valOfNode[e.first] * valOfNode[e.second];
    return total;
}

#include <bits/stdc++.h>
using namespace std;

bool checkSection(vector<vector<int>>& mat) {
    int rows = mat.size(), cols = mat[0].size();
    vector<long long> rowSum(rows,0);
    for (int i=0;i<rows;i++) for (int v: mat[i]) rowSum[i]+=v;
    long long total = 0; for (auto s: rowSum) total += s;
    long long topSum = 0;
    unordered_map<int,int> topFreq, fullFreq;
    for (auto& row: mat) for (int v: row) fullFreq[v]++;
    unordered_map<int,int> botFreq = fullFreq;

    for (int r = 0; r < rows-1; r++) {
        topSum += rowSum[r];
        for (int v: mat[r]) {
            topFreq[v]++;
            botFreq[v]--;
            if (botFreq[v]==0) botFreq.erase(v);
        }
        long long botSum = total - topSum;
        int topRows = r+1, botRows = rows-topRows;
        if (topSum == botSum) return true;
        long long diff = llabs(topSum-botSum);
        if (topSum > botSum) {
            if (topFreq.count((int)diff)) {
                if (topRows>=2 && cols>=2) return true;
                if (topRows==1) { if (mat[0][0]==diff || mat[0][cols-1]==diff) return true; }
                else if (cols==1) { if (mat[0][0]==diff || mat[topRows-1][0]==diff) return true; }
            }
        } else {
            if (botFreq.count((int)diff)) {
                if (botRows>=2 && cols>=2) return true;
                if (botRows==1) { if (mat[r+1][0]==diff || mat[r+1][cols-1]==diff) return true; }
                else if (cols==1) { if (mat[r+1][0]==diff || mat[rows-1][0]==diff) return true; }
            }
        }
    }
    return false;
}

bool equalSumGridPartition(vector<vector<int>>& grid) {
    int m = grid.size(), n = grid[0].size();
    if (checkSection(grid)) return true;
    vector<vector<int>> t(n, vector<int>(m));
    for (int i=0;i<m;i++) for (int j=0;j<n;j++) t[j][i]=grid[i][j];
    if (checkSection(t)) return true;
    return false;
}

