int maxNonIntersectingSubstrings(const std::string& word) {
    int n = static_cast<int>(word.size());
    std::vector<int> nextSame(n, -1);
    std::vector<int> lastSeen(26, -1);
    for (int i = n - 1; i >= 0; --i) {
        int c = word[i] - 'a';
        nextSame[i] = lastSeen[c];
        lastSeen[c] = i;
    }
    std::vector<std::pair<int, int>> intervals;
    intervals.reserve(n);
    for (int i = 0; i < n; ++i) {
        int j = nextSame[i];
        while (j != -1 && j - i < 2) {
            j = nextSame[j];
        }
        if (j != -1) {
            intervals.emplace_back(i, j);
        }
    }
    std::sort(intervals.begin(), intervals.end(),
              [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
                  if (a.second != b.second) return a.second < b.second;
                  return a.first < b.first;
              });
    int ans = 0;
    int last_end = -1;
    for (const auto& seg : intervals) {
        if (seg.first > last_end) {
            ++ans;
            last_end = seg.second;
        }
    }
    return ans;
}

