int minSwaps(const std::vector<int>& nums) {
    auto digitSum = [](int n) {
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum;
    };
    struct Elem { int digitSum; int value; std::size_t idx; };
    std::vector<Elem> elems;
    elems.reserve(nums.size());
    for (std::size_t i = 0; i < nums.size(); ++i) {
        elems.push_back({digitSum(nums[i]), nums[i], i});
    }
    std::sort(elems.begin(), elems.end(), [](const Elem& a, const Elem& b) {
        if (a.digitSum != b.digitSum) return a.digitSum < b.digitSum;
        return a.value < b.value;
    });
    std::vector<std::size_t> targetPos(nums.size());
    for (std::size_t sortedIdx = 0; sortedIdx < elems.size(); ++sortedIdx) {
        targetPos[elems[sortedIdx].idx] = sortedIdx;
    }
    std::vector<char> visited(nums.size(), 0);
    int swaps = 0;
    for (std::size_t i = 0; i < nums.size(); ++i) {
        if (visited[i] || targetPos[i] == i) continue;
        std::size_t cycleLen = 0;
        std::size_t j = i;
        while (!visited[j]) {
            visited[j] = 1;
            j = targetPos[j];
            ++cycleLen;
        }
        if (cycleLen > 1) swaps += static_cast<int>(cycleLen - 1);
    }
    return swaps;
}

