std::string removeAdjacent(std::string s) {
    std::string st;
    st.reserve(s.size());
    for (char c : s) {
        if (!st.empty()) {
            char p = st.back();
            int diff = std::abs(p - c);
            if (diff == 1 || diff == 25) {
                st.pop_back();
                continue;
            }
        }
        st.push_back(c);
    }
    return st;
}

#include <bits/stdc++.h>
int minMoves(const std::vector<std::string>& matrix) {
    int m = static_cast<int>(matrix.size());
    if (m == 0) return -1;
    int n = static_cast<int>(matrix[0].size());
    if (matrix[0][0] == '#' || matrix[m - 1][n - 1] == '#') return -1;
    std::vector<int> dist(m * n, -1);
    std::array<std::vector<int>, 26> portals;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            char c = matrix[i][j];
            if (c >= 'A' && c <= 'Z') {
                portals[c - 'A'].push_back(i * n + j);
            }
        }
    }
    std::vector<bool> used(26, false);
    std::queue<int> q;
    dist[0] = 0;
    q.push(0);
    const int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
    while (!q.empty()) {
        int cur = q.front();
        q.pop();
        int x = cur / n;
        int y = cur % n;
        int d = dist[cur];
        if (x == m - 1 && y == n - 1) return d;
        for (const auto& dir : dirs) {
            int nx = x + dir[0];
            int ny = y + dir[1];
            if (nx < 0 || nx >= m || ny < 0 || ny >= n) continue;
            if (matrix[nx][ny] == '#') continue;
            int nid = nx * n + ny;
            if (dist[nid] != -1) continue;
            dist[nid] = d + 1;
            q.push(nid);
        }
        char c = matrix[x][y];
        if (c >= 'A' && c <= 'Z') {
            int idx = c - 'A';
            if (!used[idx]) {
                used[idx] = true;
                for (int p : portals[idx]) {
                    if (dist[p] == -1) {
                        dist[p] = d;
                        q.push(p);
                    }
                }
            }
        }
    }
    return -1;
}

#include <bits/stdc++.h>

const int MOD = 1000000007;

long long modPow(long long base, long long exp) {
    long long result = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

int assignEdgeWeights(const std::vector<std::vector<int>>& edges) {
    int n = static_cast<int>(edges.size()) + 1;
    std::vector<std::vector<int>> adj(n + 1);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    std::vector<int> depth(n + 1, -1);
    std::queue<int> q;
    depth[1] = 0;
    q.push(1);
    int maxDepth = 0;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            if (depth[v] == -1) {
                depth[v] = depth[u] + 1;
                maxDepth = std::max(maxDepth, depth[v]);
                q.push(v);
            }
        }
    }
    if (maxDepth == 0) return 0;
    long long ans = modPow(2, maxDepth - 1);
    return static_cast<int>(ans);
}

#include <bits/stdc++.h>
using std::vector;
using std::queue;
using std::int64_t;

const int64_t MOD = 1000000007LL;

vector<int> numberOfWays(vector<vector<int>>& edges, vector<vector<int>>& queries) {
    int n = static_cast<int>(edges.size()) + 1;
    vector<vector<int>> adj(n + 1);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    int LOG = 0;
    while ((1 << LOG) <= n) ++LOG;
    vector<vector<int>> up(LOG, vector<int>(n + 1, 0));
    vector<int> depth(n + 1, 0);
    vector<char> visited(n + 1, 0);
    queue<int> q;
    q.push(1);
    visited[1] = 1;
    up[0][1] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = 1;
                depth[v] = depth[u] + 1;
                up[0][v] = u;
                q.push(v);
            }
        }
    }
    for (int k = 1; k < LOG; ++k) {
        for (int v = 1; v <= n; ++v) {
            up[k][v] = up[k - 1][up[k - 1][v]];
        }
    }

    auto lca = [&](int a, int b) {
        if (depth[a] < depth[b]) std::swap(a, b);
        int diff = depth[a] - depth[b];
        int k = 0;
        while (diff) {
            if (diff & 1) a = up[k][a];
            diff >>= 1;
            ++k;
        }
        if (a == b) return a;
        for (int i = LOG - 1; i >= 0; --i) {
            if (up[i][a] != up[i][b]) {
                a = up[i][a];
                b = up[i][b];
            }
        }
        return up[0][a];
    };

    vector<int64_t> pow2(n + 1, 1);
    for (int i = 1; i <= n; ++i) {
        pow2[i] = (pow2[i - 1] * 2) % MOD;
    }

    vector<int> ans;
    ans.reserve(queries.size());
    for (const auto& qv : queries) {
        int u = qv[0], v = qv[1];
        int w = lca(u, v);
        int dist = depth[u] + depth[v] - 2 * depth[w];
        if (dist == 0) {
            ans.push_back(0);
        } else {
            ans.push_back(static_cast<int>(pow2[dist - 1]));
        }
    }
    return ans;
}

