long long minimumCost(int n, int m, int k) {
    int maxLen = std::max(n, m);
    if (maxLen <= k) return 0;
    return static_cast<long long>(k) * (maxLen - k);
}

#include <bits/stdc++.h>

std::vector<std::vector<int>> minAbsDiffInSlidingSubmatrix(const std::vector<std::vector<int>>& grid, int k) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    int rows = m - k + 1;
    int cols = n - k + 1;
    std::vector<std::vector<int>> ans(rows, std::vector<int>(cols, 0));
    if (k <= 1) return ans;

    for (int i = 0; i < rows; ++i) {
        std::unordered_map<int, int> cnt;
        std::set<int> uniq;
        std::multiset<int> diffs;

        auto addDiff = [&](int a, int b) {
            if (a != b) diffs.insert(std::abs(a - b));
        };
        auto removeDiff = [&](int a, int b) {
            if (a != b) {
                auto it = diffs.find(std::abs(a - b));
                if (it != diffs.end()) diffs.erase(it);
            }
        };

        auto insertVal = [&](int v) {
            int prevCount = cnt[v];
            cnt[v] = prevCount + 1;
            if (prevCount == 0) {
                auto it = uniq.insert(v).first;
                auto pred = it, succ = it;
                bool hasPred = false, hasSucc = false;
                if (it != uniq.begin()) {
                    --pred;
                    hasPred = true;
                }
                ++succ;
                if (succ != uniq.end()) {
                    hasSucc = true;
                }
                if (hasPred && hasSucc) {
                    removeDiff(*pred, *succ);
                }
                if (hasPred) addDiff(*pred, v);
                if (hasSucc) addDiff(v, *succ);
            }
        };

        auto eraseVal = [&](int v) {
            auto itCnt = cnt.find(v);
            if (itCnt == cnt.end()) return;
            itCnt->second--;
            if (itCnt->second == 0) {
                cnt.erase(itCnt);
                auto it = uniq.find(v);
                if (it == uniq.end()) return;
                auto pred = it, succ = it;
                bool hasPred = false, hasSucc = false;
                if (it != uniq.begin()) {
                    --pred;
                    hasPred = true;
                }
                ++succ;
                if (succ != uniq.end()) {
                    hasSucc = true;
                }
                if (hasPred) removeDiff(*pred, v);
                if (hasSucc) removeDiff(v, *succ);
                if (hasPred && hasSucc) {
                    addDiff(*pred, *succ);
                }
                uniq.erase(it);
            }
        };

        for (int x = i; x < i + k; ++x) {
            for (int y = 0; y < k; ++y) {
                insertVal(grid[x][y]);
            }
        }
        ans[i][0] = diffs.empty() ? 0 : static_cast<int>(*diffs.begin());

        for (int j = 1; j < cols; ++j) {
            int left = j - 1;
            for (int x = i; x < i + k; ++x) {
                eraseVal(grid[x][left]);
            }
            int right = j + k - 1;
            for (int x = i; x < i + k; ++x) {
                insertVal(grid[x][right]);
            }
            ans[i][j] = diffs.empty() ? 0 : static_cast<int>(*diffs.begin());
        }
    }
    return ans;
}

