int maxProfitFromStocks(int n, const vector<int>& present, const vector<int>& future, const vector<pair<int,int>>& hierarchy, int budget) {
    vector<vector<int>> children(n);
    for (auto& e : hierarchy) { int u=e.first-1, v=e.second-1; children[u].push_back(v); }
    const long long NEG = -1000000000LL;
    function<pair<vector<long long>,vector<long long>>(int)> dfs = [&](int node) -> pair<vector<long long>,vector<long long>> {
        vector<long long> dpNot(budget+1, NEG); dpNot[0]=0;
        long long costFull = present[node]; long long profitFull = (long long)future[node]-costFull;
        vector<long long> dpBuyFull(budget+1, NEG);
        if (costFull <= budget) dpBuyFull[costFull] = profitFull;
        long long costDisc = present[node]/2; long long profitDisc = (long long)future[node]-costDisc;
        vector<long long> dpBuyDisc(budget+1, NEG);
        if (costDisc <= budget) dpBuyDisc[costDisc] = profitDisc;
        for (int ch : children[node]) {
            auto childRes = dfs(ch);
            auto& childF0 = childRes.first; auto& childF1 = childRes.second;
            vector<long long> newNot(budget+1, NEG);
            for (int cur=0; cur<=budget; ++cur) { if (dpNot[cur]==NEG) continue; for (int c=0; c<=budget-cur; ++c) { if (childF0[c]==NEG) continue; long long val=dpNot[cur]+childF0[c]; if (val>newNot[cur+c]) newNot[cur+c]=val; } }
            dpNot = newNot;
            vector<long long> newFull(budget+1, NEG);
            for (int cur=0; cur<=budget; ++cur) { if (dpBuyFull[cur]==NEG) continue; for (int c=0; c<=budget-cur; ++c) { if (childF1[c]==NEG) continue; long long val=dpBuyFull[cur]+childF1[c]; if (val>newFull[cur+c]) newFull[cur+c]=val; } }
            dpBuyFull = newFull;
            vector<long long> newDisc(budget+1, NEG);
            for (int cur=0; cur<=budget; ++cur) { if (dpBuyDisc[cur]==NEG) continue; for (int c=0; c<=budget-cur; ++c) { if (childF1[c]==NEG) continue; long long val=dpBuyDisc[cur]+childF1[c]; if (val>newDisc[cur+c]) newDisc[cur+c]=val; } }
            dpBuyDisc = newDisc;
        }
        vector<long long> f0(budget+1), f1(budget+1);
        for (int c=0; c<=budget; ++c) { f0[c]=max(dpNot[c], dpBuyFull[c]); f1[c]=max(dpNot[c], dpBuyDisc[c]); }
        return {f0, f1};
    };
    auto rootRes = dfs(0);
    long long best = 0;
    for (int c=0; c<=budget; ++c) best = max(best, rootRes.first[c]);
    return (int)best;
}

