bool removable(char a, char b) {
    int diff = (a - b + 26) % 26;
    return diff == 1 || diff == 25;
}

std::string lexicographicallySmallestString(const std::string& s) {
    int n = static_cast<int>(s.size());
    std::vector<std::vector<char>> can(n + 1, std::vector<char>(n + 1, 0));
    for (int i = 0; i <= n; ++i) can[i][i] = 1;
    for (int len = 2; len <= n; ++len) {
        for (int i = 0; i + len <= n; ++i) {
            int j = i + len;
            for (int m = i + 1; m < j; ++m) {
                if (removable(s[i], s[m]) && can[i + 1][m] && can[m + 1][j]) {
                    can[i][j] = 1;
                    break;
                }
            }
        }
    }
    std::vector<std::string> best(n + 1);
    best[n] = "";
    for (int i = n - 1; i >= 0; --i) {
        best[i] = s.substr(i, 1) + best[i + 1];
        for (int m = i + 1; m < n; ++m) {
            if (removable(s[i], s[m]) && can[i + 1][m] && can[m + 1][n]) {
                const std::string& cand = best[m + 1];
                if (cand < best[i]) best[i] = cand;
            }
        }
    }
    return best[0];
}

#include <bits/stdc++.h>
#include <vector>

bool canPartition(const std::vector<int>& nums, int target) {
    std::size_t n = nums.size();
    if (n < 2) {
        return false;
    }
    if (target == 0) {
        return false;
    }

    long long totalProduct = 1;
    for (int v : nums) {
        totalProduct *= static_cast<long long>(v);
        if (totalProduct > static_cast<long long>(target) * static_cast<long long>(target)) {
            // early exit if total product already exceeds target squared
            break;
        }
    }
    if (totalProduct != static_cast<long long>(target) * static_cast<long long>(target)) {
        return false;
    }

    // Depth‑first search to find a non‑empty proper subset with product equal to target
    bool found = false;
    std::function<void(std::size_t, long long, bool)> dfs = [&](std::size_t idx, long long cur, bool used) {
        if (found) return;
        if (cur == target && used && idx != n) {
            // ensure the subset is not the whole array
            found = true;
            return;
        }
        if (idx == n) return;
        // Skip if multiplying would exceed target
        if (cur <= target / nums[idx]) {
            dfs(idx + 1, cur * nums[idx], true);
        }
        dfs(idx + 1, cur, used);
    };

    dfs(0, 1, false);
    return found;
}

#include <bits/stdc++.h>

int minimumMoves(std::vector<std::string> classroom, int energy) {
    int m = static_cast<int>(classroom.size());
    int n = static_cast<int>(classroom[0].size());
    int startR = -1, startC = -1;
    std::vector<std::pair<int, int>> litterPos;
    std::vector<std::vector<int>> litterIdx(m, std::vector<int>(n, -1));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            char ch = classroom[i][j];
            if (ch == 'S') {
                startR = i;
                startC = j;
            } else if (ch == 'L') {
                litterIdx[i][j] = static_cast<int>(litterPos.size());
                litterPos.emplace_back(i, j);
            }
        }
    }
    int L = static_cast<int>(litterPos.size());
    int fullMask = (1 << L) - 1;
    int maxE = energy;
    int maskSize = 1 << L;
    std::size_t totalStates = static_cast<std::size_t>(m) * n * (maxE + 1) * maskSize;
    std::vector<std::uint8_t> visited(totalStates, 0);
    auto encode = [&](int r, int c, int e, int mask) -> std::size_t {
        return (static_cast<std::size_t>(r) * n + c) * (maxE + 1) * maskSize
               + static_cast<std::size_t>(e) * maskSize
               + static_cast<std::size_t>(mask);
    };
    struct Node {
        int r, c, e, mask, dist;
    };
    std::queue<Node> q;
    std::size_t startIdx = encode(startR, startC, maxE, 0);
    visited[startIdx] = 1;
    q.push({startR, startC, maxE, 0, 0});
    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};
    while (!q.empty()) {
        Node cur = q.front();
        q.pop();
        if (cur.mask == fullMask) return cur.dist;
        for (int dir = 0; dir < 4; ++dir) {
            int nr = cur.r + dr[dir];
            int nc = cur.c + dc[dir];
            if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
            char cell = classroom[nr][nc];
            if (cell == 'X') continue;
            if (cur.e == 0) continue;
            int ne = cur.e - 1;
            if (cell == 'R') ne = maxE;
            int nmask = cur.mask;
            if (cell == 'L') {
                int idx = litterIdx[nr][nc];
                if (idx >= 0) nmask |= (1 << idx);
            }
            std::size_t nid = encode(nr, nc, ne, nmask);
            if (!visited[nid]) {
                visited[nid] = 1;
                q.push({nr, nc, ne, nmask, cur.dist + 1});
            }
        }
    }
    return -1;
}

