#include <limits>

long long maximumGoodSubtreeScore(const std::vector<int>& vals, const std::vector<int>& par) {
    constexpr int MOD = 1000000007;
    constexpr int MAX_MASK = 1 << 10;
    constexpr long long NEG_INF = std::numeric_limits<long long>::min() / 4;

    int n = static_cast<int>(vals.size());
    std::vector<std::vector<int>> children(n);
    for (int i = 1; i < n; ++i) children[par[i]].push_back(i);

    std::vector<int> nodeMask(n);
    for (int i = 0; i < n; ++i) {
        int v = vals[i];
        int mask = 0;
        bool ok = true;
        while (v > 0) {
            int d = v % 10;
            if (mask & (1 << d)) { ok = false; break; }
            mask |= 1 << d;
            v /= 10;
        }
        nodeMask[i] = ok ? mask : -1;
    }

    std::vector<long long> maxScore(n, 0);

    std::function<std::array<long long, MAX_MASK>(int)> dfs = [&](int u) -> std::array<long long, MAX_MASK> {
        std::array<long long, MAX_MASK> dp{};
        dp.fill(NEG_INF);
        dp[0] = 0;
        for (int v : children[u]) {
            std::array<long long, MAX_MASK> childDP = dfs(v);
            std::array<long long, MAX_MASK> newDP{};
            newDP.fill(NEG_INF);
            for (int m1 = 0; m1 < MAX_MASK; ++m1) {
                if (dp[m1] == NEG_INF) continue;
                for (int m2 = 0; m2 < MAX_MASK; ++m2) {
                    if (childDP[m2] == NEG_INF) continue;
                    if (m1 & m2) continue;
                    int nm = m1 | m2;
                    long long val = dp[m1] + childDP[m2];
                    if (val > newDP[nm]) newDP[nm] = val;
                }
            }
            for (int m = 0; m < MAX_MASK; ++m) {
                if (newDP[m] > dp[m]) dp[m] = newDP[m];
            }
        }

        int mask = nodeMask[u];
        if (mask != -1) {
            for (int m = 0; m < MAX_MASK; ++m) {
                if (dp[m] == NEG_INF) continue;
                if (m & mask) continue;
                int nm = m | mask;
                long long val = dp[m] + vals[u];
                if (val > dp[nm]) dp[nm] = val;
            }
        }

        long long best = 0;
        for (long long v : dp) if (v > best) best = v;
        maxScore[u] = best;
        return dp;
    };

    dfs(0);

    long long total = 0;
    for (long long v : maxScore) {
        total += v;
        if (total >= MOD) total %= MOD;
    }
    return total % MOD;
}

static const int MAXV = 100000;
static vector<bool> buildSieve() {
    vector<bool> isP(MAXV + 1, true);
    isP[0] = isP[1] = false;
    for (int i = 2; (long long) i * i <= MAXV; i++)
        if (isP[i]) for (int j = i * i; j <= MAXV; j += i) isP[j] = false;
    return isP;
}
static vector<bool> IS_PRIME = buildSieve();

class Solution {
public:
    vector<int> maximizeDistinctPrimeCount(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        vector<int> ans;
        for (auto& q : queries) {
            int idx = q[0], val = q[1];
            nums[idx] = val;
            unordered_map<int, pair<int,int>> positions;
            int totalDistinct = 0;
            for (int i = 0; i < n; i++) {
                int v = nums[i];
                if (v <= MAXV && IS_PRIME[v]) {
                    auto it = positions.find(v);
                    if (it == positions.end()) {
                        positions[v] = {i, i};
                        totalDistinct++;
                    } else {
                        it->second.second = i;
                    }
                }
            }
            vector<int> diff(n + 1, 0);
            for (auto& [v, pr] : positions) {
                int first = pr.first, last = pr.second;
                if (last > first) {
                    int l = first + 1, r = last;
                    diff[l] += 1;
                    diff[r + 1] -= 1;
                }
            }
            int bestOverlap = 0, cur = 0;
            for (int p = 1; p < n; p++) {
                cur += diff[p];
                bestOverlap = max(bestOverlap, cur);
            }
            ans.push_back(totalDistinct + bestOverlap);
        }
        return ans;
    }
};

