static long long llgcd(long long a, long long b) {
    while (b) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

long long maxScore(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    long long best = 0;
    for (int i = 0; i < n; ++i) {
        long long curGcd = 0;
        int minExp = 31;
        int minCnt = 0;
        for (int j = i; j < n; ++j) {
            curGcd = llgcd(curGcd, static_cast<long long>(nums[j]));
            int exp = __builtin_ctz(static_cast<unsigned int>(nums[j]));
            if (exp < minExp) {
                minExp = exp;
                minCnt = 1;
            } else if (exp == minExp) {
                ++minCnt;
            }
            long long len = j - i + 1;
            long long score = len * curGcd;
            if (minCnt <= k) {
                long long score2 = len * curGcd * 2;
                if (score2 > score) score = score2;
            }
            if (score > best) best = score;
        }
    }
    return best;
}

