bool canMakeEqual(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return true;
    if (k > n) {
        for (int i = 1; i < n; ++i) {
            if (nums[i] != nums[0]) return false;
        }
        return true;
    }
    for (int target : {1, -1}) {
        std::vector<int> diff(n + 1, 0);
        int cur = 0;
        bool ok = true;
        for (int i = 0; i < n; ++i) {
            cur += diff[i];
            int val = nums[i];
            if (cur % 2 != 0) val = -val;
            if (i <= n - k) {
                if (val != target) {
                    ++cur;
                    ++diff[i];
                    --diff[i + k];
                }
            } else {
                if (val != target) {
                    ok = false;
                    break;
                }
            }
        }
        if (ok) return true;
    }
    return false;
}

