long long maxYSum(const std::vector<int>& x, const std::vector<int>& y) {
    std::unordered_map<int, long long> best;
    best.reserve(x.size());
    for (size_t i = 0; i < x.size(); ++i) {
        int curX = x[i];
        long long curY = y[i];
        auto it = best.find(curX);
        if (it == best.end() || curY > it->second) {
            best[curX] = curY;
        }
    }
    long long first = std::numeric_limits<long long>::min();
    long long second = std::numeric_limits<long long>::min();
    long long third = std::numeric_limits<long long>::min();
    for (const auto& kv : best) {
        long long val = kv.second;
        if (val > first) {
            third = second;
            second = first;
            first = val;
        } else if (val > second) {
            third = second;
            second = val;
        } else if (val > third) {
            third = val;
        }
    }
    return third == std::numeric_limits<long long>::min() ? -1 : first + second + third;
}

