const long long NEG = LLONG_MIN / 2;

long long maximumProfit(vector<int>& prices, int k) {
    int n = prices.size();
    vector<array<long long,3>> f(k+1, {NEG, NEG, NEG});
    f[0][0] = 0;
    for (int j = 1; j <= k; j++) {
        f[j][0] = 0;
        f[j][1] = -prices[0];
        f[j][2] = prices[0];
    }
    for (int i = 1; i < n; i++) {
        vector<array<long long,3>> nf(k+1, {NEG, NEG, NEG});
        nf[0][0] = 0;
        for (int j = 1; j <= k; j++) {
            long long best0 = f[j][0];
            if (f[j][1] > NEG) best0 = max(best0, f[j][1] + prices[i]);
            if (f[j][2] > NEG) best0 = max(best0, f[j][2] - prices[i]);
            nf[j][0] = best0;

            long long best1 = f[j][1];
            if (f[j-1][0] > NEG) best1 = max(best1, f[j-1][0] - prices[i]);
            nf[j][1] = best1;

            long long best2 = f[j][2];
            if (f[j-1][0] > NEG) best2 = max(best2, f[j-1][0] + prices[i]);
            nf[j][2] = best2;
        }
        f = nf;
    }
    return f[k][0];
}

