#include <bits/stdc++.h>

int countPartitions(const std::vector<int>& nums, int k) {
    constexpr int MOD = 1000000007;
    int n = static_cast<int>(nums.size());
    std::vector<int> pref(n + 1, 0);
    pref[0] = 1; // dp[0] = 1
    std::deque<int> minD, maxD;
    int L = 0;
    int lastDp = 0;
    for (int r = 0; r < n; ++r) {
        while (!minD.empty() && nums[minD.back()] >= nums[r]) minD.pop_back();
        minD.push_back(r);
        while (!maxD.empty() && nums[maxD.back()] <= nums[r]) maxD.pop_back();
        maxD.push_back(r);
        while (!minD.empty() && !maxD.empty() && static_cast<long long>(nums[maxD.front()]) - static_cast<long long>(nums[minD.front()]) > k) {
            if (minD.front() == L) minD.pop_front();
            if (maxD.front() == L) maxD.pop_front();
            ++L;
        }
        int sum = pref[r];
        if (L > 0) {
            sum -= pref[L - 1];
            if (sum < 0) sum += MOD;
        }
        lastDp = sum;
        pref[r + 1] = pref[r] + lastDp;
        if (pref[r + 1] >= MOD) pref[r + 1] -= MOD;
    }
    return lastDp;
}

