std::string generateTag(const std::string& caption) {
    std::string tag = "#";
    bool firstWord = true;
    size_t i = 0, n = caption.size();
    while (i < n) {
        while (i < n && caption[i] == ' ') ++i;
        if (i >= n) break;
        size_t start = i;
        while (i < n && caption[i] != ' ') ++i;
        std::string word = caption.substr(start, i - start);
        if (firstWord) {
            for (char c : word) tag += static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
            firstWord = false;
        } else {
            if (!word.empty()) {
                tag += static_cast<char>(std::toupper(static_cast<unsigned char>(word[0])));
                for (size_t k = 1; k < word.size(); ++k)
                    tag += static_cast<char>(std::tolower(static_cast<unsigned char>(word[k])));
            }
        }
    }
    if (tag.size() > 100) tag = tag.substr(0, 100);
    return tag;
}

