const long long MOD = 1000000007LL;

int countUnlockPermutations(const std::vector<int>& complexity) {
    int n = static_cast<int>(complexity.size());
    if (n == 0) return 0;
    int minVal = *std::min_element(complexity.begin(), complexity.end());
    int cntMin = static_cast<int>(std::count(complexity.begin(), complexity.end(), minVal));
    if (complexity[0] != minVal || cntMin != 1) return 0;
    long long fact = 1;
    for (int i = 2; i <= n - 1; ++i) fact = fact * i % MOD;
    return static_cast<int>(fact);
}

class Solution {
public:
    int minOperations(string word1, string word2) {
        int n = word1.length();
        vector<int> f(n + 1, INT_MAX);
        f[0] = 0;
        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j < i; ++j) {
                if (f[j] == INT_MAX) continue;
                int a = calc(word1, word2, j, i - 1, false);
                int b = 1 + calc(word1, word2, j, i - 1, true);
                int t = min(a, b);
                f[i] = min(f[i], f[j] + t);
            }
        }
        return f[n];
    }
private:
    int calc(const string& word1, const string& word2, int l, int r, bool rev) {
        int cnt[26][26] = {0};
        int res = 0;
        for (int i = l; i <= r; ++i) {
            int j = rev ? r - (i - l) : i;
            int a = word1[j] - 'a';
            int b = word2[i] - 'a';
            if (a != b) {
                if (cnt[b][a] > 0) cnt[b][a]--;
                else { cnt[a][b]++; res++; }
            }
        }
        return res;
    }
};

class Solution {
public:
    vector<int> findMedian(int n, vector<vector<int>>& edges, vector<vector<int>>& queries) {
        vector<vector<pair<int,int>>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
            adj[e[1]].push_back({e[0], e[2]});
        }
        int LOG = max(1, 32 - __builtin_clz(max(n,1)));
        vector<vector<int>> up(LOG, vector<int>(n));
        vector<int> depth(n);
        vector<long long> dist(n);
        vector<bool> visited(n, false);
        vector<int> parent0(n, -1);
        vector<array<int,3>> stack_ = {{0,-1,0}};
        visited[0] = true;
        vector<int> order;
        while (!stack_.empty()) {
            auto [u,p,d] = stack_.back(); stack_.pop_back();
            order.push_back(u);
            parent0[u] = p;
            depth[u] = d;
            for (auto& [v,w] : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    dist[v] = dist[u] + w;
                    stack_.push_back({v,u,d+1});
                }
            }
        }
        for (int v : order) up[0][v] = parent0[v] != -1 ? parent0[v] : v;
        for (int k = 1; k < LOG; k++)
            for (int v = 0; v < n; v++)
                up[k][v] = up[k-1][up[k-1][v]];

        int q = queries.size();
        vector<int> ans(q);
        for (int qi = 0; qi < q; qi++) {
            int u = queries[qi][0], v = queries[qi][1];
            int a = u, b = v;
            if (depth[a] < depth[b]) swap(a,b);
            int diff = depth[a]-depth[b];
            for (int k = 0; k < LOG; k++) if ((diff>>k)&1) a = up[k][a];
            int l;
            if (a == b) l = a;
            else {
                for (int k = LOG-1; k >= 0; k--) {
                    if (up[k][a] != up[k][b]) { a = up[k][a]; b = up[k][b]; }
                }
                l = up[0][a];
            }
            long long total = dist[u] + dist[v] - 2*dist[l];
            if (total == 0) { ans[qi] = u; continue; }
            long long upWeight = dist[u] - dist[l];
            if (2*upWeight >= total) {
                int cur = u;
                for (int k = LOG-1; k >= 0; k--) {
                    int nxt = up[k][cur];
                    if (depth[nxt] >= depth[l] && 2*(dist[u]-dist[nxt]) < total) cur = nxt;
                }
                ans[qi] = up[0][cur];
            } else {
                long long remaining = total - 2*upWeight;
                int cur = v;
                for (int k = LOG-1; k >= 0; k--) {
                    int nxt = up[k][cur];
                    if (depth[nxt] >= depth[l] && 2*(dist[nxt]-dist[l]) >= remaining) cur = nxt;
                }
                ans[qi] = cur;
            }
        }
        return ans;
    }
};

