static const long long MOD = 1000000007LL;

int countSpecialTriplets(vector<int>& nums) {
    int n = (int)nums.size();
    unordered_map<int,long long> right, left;
    for (int v : nums) right[v]++;
    long long total = 0;
    for (int j = 0; j < n; ++j) {
        int v = nums[j];
        right[v]--;
        long long target = 2LL * v;
        long long lv = (target <= INT_MAX) ? left[(int)target] : 0;
        long long rv = (target <= INT_MAX) ? right[(int)target] : 0;
        total = (total + (lv * rv) % MOD) % MOD;
        left[v]++;
    }
    return (int)total;
}

