int minSwaps(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    std::vector<int> evenPos;
    evenPos.reserve(n);
    for (int i = 0; i < n; ++i) {
        if ((nums[i] & 1) == 0) {
            evenPos.push_back(i);
        }
    }
    int evenCnt = static_cast<int>(evenPos.size());
    int oddCnt = n - evenCnt;
    if (std::abs(evenCnt - oddCnt) > 1) {
        return -1;
    }
    long long best = LLONG_MAX;
    if (evenCnt >= oddCnt) {
        long long cur = 0;
        for (int i = 0; i < evenCnt; ++i) {
            int target = 2 * i;
            cur += std::llabs(static_cast<long long>(evenPos[i]) - target);
        }
        best = std::min(best, cur);
    }
    if (oddCnt >= evenCnt) {
        long long cur = 0;
        for (int i = 0; i < evenCnt; ++i) {
            int target = 2 * i + 1;
            cur += std::llabs(static_cast<long long>(evenPos[i]) - target);
        }
        best = std::min(best, cur);
    }
    return static_cast<int>(best);
}

