long long maxArea(const std::vector<std::vector<int>>& coords) {
    if (coords.size() < 3) return -1;
    struct MinMax { int mn = INT_MAX; int mx = INT_MIN; };
    std::unordered_map<int, MinMax> xMap, yMap;
    int globalMinX = INT_MAX, globalMaxX = INT_MIN;
    int globalMinY = INT_MAX, globalMaxY = INT_MIN;
    for (const auto& p : coords) {
        int x = p[0], y = p[1];
        globalMinX = std::min(globalMinX, x);
        globalMaxX = std::max(globalMaxX, x);
        globalMinY = std::min(globalMinY, y);
        globalMaxY = std::max(globalMaxY, y);
        auto& xm = xMap[x];
        xm.mn = std::min(xm.mn, y);
        xm.mx = std::max(xm.mx, y);
        auto& ym = yMap[y];
        ym.mn = std::min(ym.mn, x);
        ym.mx = std::max(ym.mx, x);
    }
    long long best = -1;
    for (const auto& kv : xMap) {
        int x = kv.first;
        int minY = kv.second.mn;
        int maxY = kv.second.mx;
        if (maxY == minY) continue;
        long long base = (long long)maxY - minY;
        long long height = std::max(std::llabs((long long)x - globalMinX), std::llabs((long long)x - globalMaxX));
        if (height == 0) continue;
        best = std::max(best, base * height);
    }
    for (const auto& kv : yMap) {
        int y = kv.first;
        int minX = kv.second.mn;
        int maxX = kv.second.mx;
        if (maxX == minX) continue;
        long long base = (long long)maxX - minX;
        long long height = std::max(std::llabs((long long)y - globalMinY), std::llabs((long long)y - globalMaxY));
        if (height == 0) continue;
        best = std::max(best, base * height);
    }
    return best;
}

