std::vector<int> recoverDenominations(const std::vector<int>& numWays) {
    if (numWays.empty()) return {};
    std::size_t m = numWays.size(); // sums from 1 to m
    std::vector<long long> dp(m + 1, 0);
    dp[0] = 1;
    std::vector<int> ans;
    ans.reserve(m);
    for (std::size_t i = 1; i <= m; ++i) {
        long long cur = dp[i];
        long long target = numWays[i - 1];
        if (cur > target) return {};
        if (cur == target) continue;
        if (target - cur != 1) return {};
        ans.push_back(static_cast<int>(i));
        for (std::size_t j = i; j <= m; ++j) {
            dp[j] += dp[j - i];
        }
    }
    for (std::size_t i = 1; i <= m; ++i) {
        if (dp[i] != numWays[i - 1]) return {};
    }
    return ans;
}

#include <bits/stdc++.h>

int minTouchedNodes(int n, std::vector<std::vector<int>>& edges, std::vector<long long>& cost) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        adj[e[0]].push_back(e[1]);
        adj[e[1]].push_back(e[0]);
    }

    std::vector<int> parent(n, -1);
    std::vector<int> order;
    order.reserve(n);
    std::stack<int> st;
    st.push(0);
    parent[0] = -2; // mark visited
    while (!st.empty()) {
        int u = st.top(); st.pop();
        order.push_back(u);
        for (int v : adj[u]) {
            if (parent[v] == -1) {
                parent[v] = u;
                st.push(v);
            }
        }
    }

    std::vector<long long> maxSum(n, 0);
    std::vector<int> touches(n, 0);

    for (int idx = n - 1; idx >= 0; --idx) {
        int u = order[idx];
        long long best = LLONG_MIN;
        int cntLess = 0;
        int sumTouches = 0;
        bool hasChild = false;
        for (int v : adj[u]) {
            if (v == parent[u]) continue;
            hasChild = true;
            if (maxSum[v] > best) best = maxSum[v];
        }
        if (!hasChild) {
            maxSum[u] = cost[u];
            touches[u] = 0;
            continue;
        }
        for (int v : adj[u]) {
            if (v == parent[u]) continue;
            sumTouches += touches[v];
            if (maxSum[v] < best) {
                ++cntLess;
            }
        }
        touches[u] = sumTouches + cntLess;
        maxSum[u] = cost[u] + best;
    }

    return touches[0];
}

