std::vector<std::string> partitionString(const std::string& s) {
    std::unordered_set<std::string> used;
    std::vector<std::string> segments;
    int n = static_cast<int>(s.size());
    int i = 0;
    while (i < n) {
        std::string cur;
        bool made = false;
        for (int j = i; j < n; ++j) {
            cur.push_back(s[j]);
            if (used.find(cur) == used.end()) {
                segments.push_back(cur);
                used.insert(cur);
                i = j + 1;
                made = true;
                break;
            }
        }
        if (!made) break;
    }
    return segments;
}

