std::vector<int> longestCommonPrefix(const std::vector<std::string>& words) {
    int n = static_cast<int>(words.size());
    if (n == 0) return {};
    if (n == 1) return std::vector<int>(1, 0);
    std::vector<int> lcp(n - 1);
    auto computeLCP = [](const std::string& a, const std::string& b) {
        int len = std::min(a.size(), b.size());
        int i = 0;
        while (i < len && a[i] == b[i]) ++i;
        return i;
    };
    for (int i = 0; i < n - 1; ++i) {
        lcp[i] = computeLCP(words[i], words[i + 1]);
    }
    std::vector<int> prefMax(n - 1), suffMax(n - 1);
    prefMax[0] = lcp[0];
    for (int i = 1; i < n - 1; ++i) prefMax[i] = std::max(prefMax[i - 1], lcp[i]);
    suffMax[n - 2] = lcp[n - 2];
    for (int i = n - 3; i >= 0; --i) suffMax[i] = std::max(suffMax[i + 1], lcp[i]);
    std::vector<int> answer(n, 0);
    for (int i = 0; i < n; ++i) {
        int maxExcluding = 0;
        if (i - 2 >= 0) maxExcluding = std::max(maxExcluding, prefMax[i - 2]);
        if (i + 1 <= n - 2) maxExcluding = std::max(maxExcluding, suffMax[i + 1]);
        int newLcp = 0;
        if (i - 1 >= 0 && i + 1 < n) newLcp = computeLCP(words[i - 1], words[i + 1]);
        answer[i] = std::max(maxExcluding, newLcp);
    }
    return answer;
}

class DSU {
public:
    vector<int> p, sz;
    int components;
    DSU(int n) : p(n), sz(n, 1), components(n) {
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        while (p[x] != x) { p[x] = p[p[x]]; x = p[x]; }
        return x;
    }
    bool unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return false;
        if (sz[ra] < sz[rb]) swap(ra, rb);
        p[rb] = ra; sz[ra] += sz[rb]; components--;
        return true;
    }
};
class Solution {
public:
    long long maxStability(int n, vector<vector<int>>& edges, int k) {
        DSU dsu0(n);
        long long mustMin = LLONG_MAX;
        for (auto& e : edges) {
            if (e[3] == 1) {
                if (!dsu0.unite(e[0], e[1])) return -1;
                mustMin = min(mustMin, (long long) e[2]);
            }
        }
        set<long long> candSet;
        for (auto& e : edges) {
            candSet.insert(e[2]);
            if (e[3] == 0) candSet.insert((long long) e[2] * 2);
        }
        vector<long long> candidates(candSet.begin(), candSet.end());
        auto feasible = [&](long long x) -> bool {
            if (mustMin < x) return false;
            DSU dsu(n);
            for (auto& e : edges) if (e[3] == 1) dsu.unite(e[0], e[1]);
            vector<pair<int,int>> freeEdges, upgradeEdges;
            for (auto& e : edges) {
                if (e[3] == 0) {
                    if (e[2] >= x) freeEdges.push_back({e[0], e[1]});
                    else if ((long long) e[2] * 2 >= x) upgradeEdges.push_back({e[0], e[1]});
                }
            }
            for (auto& [u, v] : freeEdges) dsu.unite(u, v);
            int used = 0;
            for (auto& [u, v] : upgradeEdges) {
                if (dsu.find(u) != dsu.find(v)) {
                    if (used >= k) continue;
                    dsu.unite(u, v);
                    used++;
                }
            }
            return dsu.components == 1;
        };
        int lo = 0, hi = (int) candidates.size() - 1;
        long long best = -1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (feasible(candidates[mid])) { best = candidates[mid]; lo = mid + 1; }
            else hi = mid - 1;
        }
        return best;
    }
};

#include <bits/stdc++.h>

int minMaxXor(const std::vector<int>& nums, int k) {
    const int MAXBIT = 30;
    int n = static_cast<int>(nums.size());
    std::vector<int> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] ^ nums[i];

    auto can = [&](int limit) -> bool {
        std::vector<std::vector<char>> dp(n + 1, std::vector<char>(k + 1, 0));
        dp[0][0] = 1;
        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j < i; ++j) {
                if ((pref[i] ^ pref[j]) <= limit) {
                    for (int cnt = 0; cnt < k; ++cnt) {
                        if (dp[j][cnt]) dp[i][cnt + 1] = 1;
                    }
                }
            }
        }
        return dp[n][k];
    };

    int low = 0, high = (1 << (MAXBIT + 1)) - 1;
    while (low < high) {
        int mid = low + ((high - low) >> 1);
        if (can(mid)) high = mid;
        else low = mid + 1;
    }
    return low;
}

class Solution {
public:
    long long minCost(int m, int n, vector<vector<int>>& waitCost) {
        vector<vector<long long>> f(m, vector<long long>(n, 0));
        f[0][0] = 1;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) continue;
                long long entry = (long long)(i+1)*(j+1);
                long long best = LLONG_MAX;
                if (i > 0) {
                    long long p = f[i-1][j];
                    if (!(i-1 == 0 && j == 0)) p += waitCost[i-1][j];
                    best = min(best, p);
                }
                if (j > 0) {
                    long long p = f[i][j-1];
                    if (!(i == 0 && j-1 == 0)) p += waitCost[i][j-1];
                    best = min(best, p);
                }
                f[i][j] = entry + best;
            }
        }
        return f[m-1][n-1];
    }
};

