std::string solution(int n) {
    auto toBase = [](long long value, int base) -> std::string {
        if (value == 0) return "0";
        const char* digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        std::string res;
        while (value > 0) {
            int d = static_cast<int>(value % base);
            res.push_back(digits[d]);
            value /= base;
        }
        std::reverse(res.begin(), res.end());
        return res;
    };
    long long sq = 1LL * n * n;
    long long cube = 1LL * n * n * n;
    std::string hex = toBase(sq, 16);
    std::string base36 = toBase(cube, 36);
    return hex + base36;
}

