long long minimumTime(int n, std::vector<std::vector<int>>& edges) {
    const long long INF = (1LL << 60);
    struct Edge { int to; long long start; long long end; };
    std::vector<std::vector<Edge>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        long long s = e[2], t = e[3];
        adj[u].push_back({v, s, t});
    }
    std::vector<long long> dist(n, INF);
    dist[0] = 0;
    using State = std::pair<long long, int>;
    std::priority_queue<State, std::vector<State>, std::greater<State>> pq;
    pq.emplace(0, 0);
    while (!pq.empty()) {
        auto top = pq.top();
        pq.pop();
        long long curTime = top.first;
        int u = top.second;
        if (curTime != dist[u]) continue;
        if (u == n - 1) break;
        for (const auto& e : adj[u]) {
            if (curTime > e.end) continue;
            long long wait = e.start > curTime ? e.start - curTime : 0;
            long long arrival = curTime + wait + 1;
            if (arrival < dist[e.to]) {
                dist[e.to] = arrival;
                pq.emplace(arrival, e.to);
            }
        }
    }
    return dist[n - 1] == INF ? -1 : dist[n - 1];
}

