std::vector<std::string> couponCodeValidator(const std::vector<std::string>& code,
                                             const std::vector<std::string>& businessLine,
                                             const std::vector<bool>& isActive) {
    struct Item {
        int line;
        std::string code;
    };
    std::vector<Item> items;
    items.reserve(code.size());
    for (size_t i = 0; i < code.size(); ++i) {
        if (!isActive[i]) continue;
        int line = lineOrder(businessLine[i]);
        if (line < 0) continue;
        if (code[i].empty()) continue;
        bool ok = true;
        for (char c : code[i]) {
            unsigned char uc = static_cast<unsigned char>(c);
            if (!std::isalnum(uc) && c != '_') {
                ok = false;
                break;
            }
        }
        if (!ok) continue;
        items.push_back({line, code[i]});
    }
    std::sort(items.begin(), items.end(), [](const Item& a, const Item& b) {
        return a.line < b.line || (a.line == b.line && a.code < b.code);
    });
    std::vector<std::string> result;
    result.reserve(items.size());
    for (const auto& item : items) {
        result.push_back(item.code);
    }
    return result;
}

