static inline int gcd_int(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int minimumStabilityFactor(const std::vector<int>& nums, int maxC) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;
    std::vector<int> lg(n + 1);
    lg[1] = 0;
    for (int i = 2; i <= n; ++i) lg[i] = lg[i / 2] + 1;
    int K = lg[n] + 1;
    std::vector<std::vector<int>> st(K, std::vector<int>(n));
    for (int i = 0; i < n; ++i) st[0][i] = nums[i];
    for (int k = 1; k < K; ++k) {
        int span = 1 << (k - 1);
        for (int i = 0; i + (1 << k) <= n; ++i) {
            st[k][i] = gcd_int(st[k - 1][i], st[k - 1][i + span]);
        }
    }
    auto query = [&](int l, int r) {
        int len = r - l + 1;
        int k = lg[len];
        return gcd_int(st[k][l], st[k][r - (1 << k) + 1]);
    };
    auto feasible = [&](int L) {
        int need = 0;
        int last = -1;
        int w = L + 1;
        for (int i = 0; i + w - 1 < n; ++i) {
            if (query(i, i + w - 1) >= 2) {
                if (last < i) {
                    ++need;
                    last = i + w - 1;
                    if (need > maxC) return false;
                }
            }
        }
        return need <= maxC;
    };
    int low = 0, high = n;
    while (low < high) {
        int mid = (low + high) / 2;
        if (feasible(mid))
            high = mid;
        else
            low = mid + 1;
    }
    return low;
}

