struct DSU {
    std::vector<int> parent;
    std::vector<int> sz;
    DSU(int n) : parent(n), sz(n, 1) {
        std::iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    bool unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return false;
        if (sz[ra] < sz[rb]) std::swap(ra, rb);
        parent[rb] = ra;
        sz[ra] += sz[rb];
        return true;
    }
};

int minimumTime(int n, std::vector<std::vector<int>> edges, int k) {
    if (k <= 1) return 0;
    std::sort(edges.begin(), edges.end(),
              [](const std::vector<int>& a, const std::vector<int>& b) {
                  return a[2] > b[2];
              });
    DSU dsu(n);
    int components = n;
    for (const auto& e : edges) {
        if (dsu.unite(e[0], e[1])) {
            --components;
            if (components < k) return e[2];
        }
    }
    return 0;
}

#include <bits/stdc++.h>

int minimumMoves(int sx, int sy, int tx, int ty) {
    if (sx > tx || sy > ty) return -1;
    if (sx == tx && sy == ty) return 0;
    using ll = long long;
    std::queue<std::pair<std::pair<ll,ll>, int>> q;
    q.push({{sx, sy}, 0});
    std::unordered_set<unsigned long long> visited;
    auto encode = [&](ll x, ll y) -> unsigned long long {
        return (static_cast<unsigned long long>(x) << 32) ^ static_cast<unsigned long long>(y);
    };
    visited.insert(encode(sx, sy));
    while (!q.empty()) {
        auto cur = q.front(); q.pop();
        ll x = cur.first.first;
        ll y = cur.first.second;
        int d = cur.second;
        ll m = std::max(x, y);
        if (m == 0) continue; // cannot progress
        // move to (x+m, y)
        ll nx = x + m;
        ll ny = y;
        if (nx == tx && ny == ty) return d + 1;
        if (nx <= tx && ny <= ty) {
            unsigned long long code = encode(nx, ny);
            if (!visited.count(code)) {
                visited.insert(code);
                q.push({{nx, ny}, d + 1});
            }
        }
        // move to (x, y+m)
        nx = x;
        ny = y + m;
        if (nx == tx && ny == ty) return d + 1;
        if (nx <= tx && ny <= ty) {
            unsigned long long code = encode(nx, ny);
            if (!visited.count(code)) {
                visited.insert(code);
                q.push({{nx, ny}, d + 1});
            }
        }
    }
    return -1;
}

