std::vector<int> processQueries(int c,
                                const std::vector<std::vector<int>>& connections,
                                const std::vector<std::vector<int>>& queries) {
    std::vector<std::vector<int>> adj(c + 1);
    for (const auto& e : connections) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    std::vector<char> offline(c + 1, 0);
    for (const auto& q : queries) {
        if (q[0] == 2) offline[q[1]] = 1;
    }

    const int INF = 1e9;
    std::vector<int> dist(c + 1, INF), src(c + 1, -1);
    std::queue<int> q;
    for (int i = 1; i <= c; ++i) {
        if (!offline[i]) {
            dist[i] = 0;
            src[i] = i;
            q.push(i);
        }
    }
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : adj[u]) {
            if (dist[v] > dist[u] + 1) {
                dist[v] = dist[u] + 1;
                src[v] = src[u];
                q.push(v);
            } else if (dist[v] == dist[u] + 1 && src[u] < src[v]) {
                src[v] = src[u];
                q.push(v);
            }
        }
    }

    std::vector<int> revAns;
    revAns.reserve(queries.size());
    for (auto it = queries.rbegin(); it != queries.rend(); ++it) {
        int type = (*it)[0];
        int x = (*it)[1];
        if (type == 1) {
            revAns.push_back(src[x] == -1 ? -1 : src[x]);
        } else { // type == 2, add node back online
            if (dist[x] == 0) continue;
            dist[x] = 0;
            src[x] = x;
            q.push(x);
            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (int v : adj[u]) {
                    if (dist[v] > dist[u] + 1) {
                        dist[v] = dist[u] + 1;
                        src[v] = src[u];
                        q.push(v);
                    } else if (dist[v] == dist[u] + 1 && src[u] < src[v]) {
                        src[v] = src[u];
                        q.push(v);
                    }
                }
            }
        }
    }

    std::reverse(revAns.begin(), revAns.end());
    return revAns;
}

