std::string processString(std::string s) {
    std::string out;
    std::string del;
    out.reserve(s.size());
    del.reserve(s.size());
    for (char c : s) {
        if (c >= 'a' && c <= 'z') {
            out.push_back(c);
        } else if (c == '#') {
            if (!out.empty()) {
                del.push_back(out.back());
                out.pop_back();
            }
        } else if (c == '%') {
            if (!del.empty()) {
                out.push_back(del.back());
                del.pop_back();
            }
        } else if (c == '*') {
            del.clear();
        }
    }
    return out;
}

