char getKthChar(const std::string& s, long long k) {
    size_t n = s.size();
    std::vector<long long> len(n + 1);
    len[0] = 0;
    const long long INF = LLONG_MAX / 4;
    for (size_t i = 1; i <= n; ++i) {
        char ch = s[i - 1];
        long long prev = len[i - 1];
        if (ch >= 'a' && ch <= 'z') {
            len[i] = prev + 1;
        } else if (ch == '*') {
            len[i] = prev > 0 ? prev - 1 : 0;
        } else if (ch == '#') {
            if (prev > INF / 2) len[i] = INF;
            else len[i] = prev * 2;
        } else { // '%'
            len[i] = prev;
        }
        if (len[i] > INF) len[i] = INF;
    }
    if (k < 0 || k >= len[n]) return '.';
    for (int i = static_cast<int>(n); i > 0; --i) {
        char ch = s[i - 1];
        long long prev = len[i - 1];
        if (ch >= 'a' && ch <= 'z') {
            if (k == prev) return ch;
        } else if (ch == '*') {
            // no action needed
        } else if (ch == '#') {
            if (k >= prev) k -= prev;
        } else { // '%'
            k = prev - 1 - k;
        }
    }
    return '.';
}

