int longestPalindromePath(int n, std::vector<std::vector<int>>& edges, std::string label) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    auto encode = [&](int mask, int u, int v) -> uint64_t {
        return (static_cast<uint64_t>(mask) << 12) | static_cast<uint64_t>(u * n + v);
    };
    auto decode = [&](uint64_t key, int& mask, int& u, int& v) {
        mask = static_cast<int>(key >> 12);
        int uv = static_cast<int>(key & ((1ULL << 12) - 1));
        u = uv / n;
        v = uv % n;
    };

    std::unordered_map<uint64_t, int> best;
    best.reserve(1 << 15);
    std::queue<uint64_t> q;

    for (int i = 0; i < n; ++i) {
        int m = 1 << i;
        uint64_t key = encode(m, i, i);
        best[key] = 1;
        q.push(key);
    }

    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        if (label[u] == label[v]) {
            int m = (1 << u) | (1 << v);
            uint64_t key1 = encode(m, u, v);
            uint64_t key2 = encode(m, v, u);
            if (best.find(key1) == best.end() || best[key1] < 2) {
                best[key1] = 2;
                q.push(key1);
            }
            if (best.find(key2) == best.end() || best[key2] < 2) {
                best[key2] = 2;
                q.push(key2);
            }
        }
    }

    int answer = 1;
    while (!q.empty()) {
        uint64_t curKey = q.front();
        q.pop();
        int mask, u, v;
        decode(curKey, mask, u, v);
        int curLen = best[curKey];
        if (curLen > answer) answer = curLen;

        for (int a : adj[u]) {
            if (mask & (1 << a)) continue;
            for (int b : adj[v]) {
                if (mask & (1 << b)) continue;
                if (a == b) continue;
                if (label[a] != label[b]) continue;
                int newMask = mask | (1 << a) | (1 << b);
                uint64_t newKey = encode(newMask, a, b);
                int newLen = curLen + 2;
                auto it = best.find(newKey);
                if (it == best.end() || it->second < newLen) {
                    best[newKey] = newLen;
                    q.push(newKey);
                }
            }
        }
    }
    return answer;
}

