int countIslands(const std::vector<std::vector<int>>& grid, int k) {
    int rows = static_cast<int>(grid.size());
    if (rows == 0) return 0;
    int cols = static_cast<int>(grid[0].size());
    std::vector<char> visited(rows * cols, 0);
    int islandCount = 0;
    const int dr[4] = {1, -1, 0, 0};
    const int dc[4] = {0, 0, 1, -1};

    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            int idx = r * cols + c;
            if (grid[r][c] > 0 && !visited[idx]) {
                long long sum = 0;
                std::vector<int> stack;
                stack.push_back(idx);
                visited[idx] = 1;

                while (!stack.empty()) {
                    int cur = stack.back();
                    stack.pop_back();
                    int cr = cur / cols;
                    int cc = cur % cols;
                    sum += grid[cr][cc];

                    for (int d = 0; d < 4; ++d) {
                        int nr = cr + dr[d];
                        int nc = cc + dc[d];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                            int nidx = nr * cols + nc;
                            if (grid[nr][nc] > 0 && !visited[nidx]) {
                                visited[nidx] = 1;
                                stack.push_back(nidx);
                            }
                        }
                    }
                }

                if (k != 0 && sum % k == 0) ++islandCount;
            }
        }
    }

    return islandCount;
}

