int maximumPathScore(const std::vector<std::vector<int>>& edges, const std::vector<bool>& online, long long k) {
    int n = static_cast<int>(online.size());
    std::vector<std::vector<std::pair<int, int>>> adj(n);
    std::vector<int> indeg(n, 0);
    int maxCost = 0;
    for (const auto& e : edges) {
        int u = e[0], v = e[1], c = e[2];
        adj[u].push_back({v, c});
        ++indeg[v];
        if (c > maxCost) maxCost = c;
    }

    std::queue<int> q;
    for (int i = 0; i < n; ++i) {
        if (indeg[i] == 0) q.push(i);
    }
    std::vector<int> topo;
    topo.reserve(n);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        topo.push_back(u);
        for (const auto& p : adj[u]) {
            int v = p.first;
            if (--indeg[v] == 0) q.push(v);
        }
    }

    auto feasible = [&](int B) -> bool {
        const long long INF = std::numeric_limits<long long>::max() / 4;
        std::vector<long long> dist(n, INF);
        if (!online[0]) return false;
        dist[0] = 0;
        for (int u : topo) {
            if (!online[u] || dist[u] == INF) continue;
            for (const auto& p : adj[u]) {
                int v = p.first;
                int c = p.second;
                if (c < B) continue;
                if (!online[v]) continue;
                long long nd = dist[u] + c;
                if (nd < dist[v]) dist[v] = nd;
            }
        }
        return dist[n - 1] <= k;
    };

    int ans = -1;
    int low = 0, high = maxCost;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (feasible(mid)) {
            ans = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return ans;
}

