unsigned long long C[65][65];

unsigned long long countPopcountUpTo(unsigned long long n, int target) {
    unsigned long long ans = 0;
    int ones = 0;
    for (int i = 63; i >= 0; --i) {
        if (n & (1ULL << i)) {
            int need = target - ones;
            if (need >= 0 && i >= need) {
                ans += C[i][need];
            }
            ++ones;
            if (ones > target) break;
        }
    }
    if (ones == target) ans += 1;
    return ans;
}

