    return d;
}

long long countIntegers(long long n, int k) {
    if (n < 1) return 0;
    // precompute binomial coefficients up to 64
    for (int i = 0; i <= 64; ++i) {
        C[i][0] = C[i][i] = 1ULL;
        for (int j = 1; j < i; ++j) {
            C[i][j] = C[i-1][j-1] + C[i-1][j];
        }
    }
    if (k == 0) return 1; // only number 1
    std::vector<int> targets;
    for (int c = 1; c <= 60; ++c) {
        if (depthSmall(c) == k - 1) targets.push_back(c);
    }
    unsigned long long total = 0;
    for (int t : targets) {
        total += countPopcountUpTo(static_cast<unsigned long long>(n), t);
    }
    // exclude x = 1 which is counted only when k == 1
    if (k == 1 && n >= 1) total -= 1;
    return static_cast<long long>(total);
}

