bool isDivisibleBySumAndProduct(long long n) {
    if (n == 0) return false;
    long long sum = 0;
    long long product = 1;
    long long temp = n;
    while (temp > 0) {
        long long digit = temp % 10;
        sum += digit;
        product *= digit;
        temp /= 10;
    }
    long long total = sum + product;
    return total != 0 && n % total == 0;
}

