long long splitArrayByPrimeIndices(const std::vector<int>& nums) {
    std::size_t n = nums.size();
    if (n == 0) return 0;
    long long total = 0;
    for (int v : nums) total += v;
    if (n <= 2) return total >= 0 ? total : -total;
    std::vector<char> isPrime(n, true);
    isPrime[0] = isPrime[1] = false;
    for (std::size_t i = 2; i * i < n; ++i) {
        if (isPrime[i]) {
            for (std::size_t j = i * i; j < n; j += i) {
                isPrime[j] = false;
            }
        }
    }
    long long sumPrime = 0;
    for (std::size_t i = 2; i < n; ++i) {
        if (isPrime[i]) sumPrime += nums[i];
    }
    long long diff = total - 2 * sumPrime;
    return diff >= 0 ? diff : -diff;
}

