int countTrapezoids(std::vector<std::vector<int>>& points) {
    const long long MOD = 1000000007LL;
    std::unordered_map<long long, long long> cnt;
    for (const auto& p : points) {
        cnt[p[1]]++;
    }
    long long sum = 0, sumSq = 0;
    for (const auto& kv : cnt) {
        long long c = kv.second;
        if (c < 2) continue;
        long long comb = (c * (c - 1) / 2) % MOD;
        sum = (sum + comb) % MOD;
        sumSq = (sumSq + comb * comb % MOD) % MOD;
    }
    long long inv2 = (MOD + 1) / 2;
    long long ans = (( (sum * sum) % MOD - sumSq + MOD) % MOD) * inv2 % MOD;
    return static_cast<int>(ans);
}

#include <bits/stdc++.h>
using std::vector;
using std::size_t;

class Fenwick {
    int n_;
    vector<int> bit_;
public:
    Fenwick(int n = 0) : n_(n), bit_(n + 1, 0) {}
    void init(int n) {
        n_ = n;
        bit_.assign(n + 1, 0);
    }
    void add(int idx, int delta) {
        ++idx;
        while (idx <= n_) {
            bit_[idx] += delta;
            idx += idx & -idx;
        }
    }
    int sumPrefix(int idx) const {
        ++idx;
        int res = 0;
        while (idx > 0) {
            res += bit_[idx];
            idx -= idx & -idx;
        }
        return res;
    }
    int rangeSum(int l, int r) const {
        if (l > r) return 0;
        return sumPrefix(r) - (l ? sumPrefix(l - 1) : 0);
    }
};

static int popcountDepth(long long x) {
    int d = 0;
    while (x != 1) {
        x = __builtin_popcountll(static_cast<unsigned long long>(x));
        ++d;
    }
    return d;
}

vector<int> numberOfIntegers(vector<long long>& nums, vector<vector<int>>& queries) {
    int n = static_cast<int>(nums.size());
    vector<int> depth(n);
    for (int i = 0; i < n; ++i) depth[i] = popcountDepth(nums[i]);

    const int MAXK = 6;
    vector<Fenwick> bits(MAXK);
    for (int k = 0; k < MAXK; ++k) bits[k].init(n);
    for (int i = 0; i < n; ++i) bits[depth[i]].add(i, 1);

    vector<int> answer;
    answer.reserve(queries.size());

    for (const auto& q : queries) {
        if (q[0] == 1) {
            int l = q[1];
            int r = q[2];
            int k = q[3];
            answer.push_back(bits[k].rangeSum(l, r));
        } else {
            int idx = q[1];
            long long val = q[2];
            int newDepth = popcountDepth(val);
            int oldDepth = depth[idx];
            if (newDepth != oldDepth) {
                bits[oldDepth].add(idx, -1);
                bits[newDepth].add(idx, 1);
                depth[idx] = newDepth;
            }
            nums[idx] = val;
        }
    }
    return answer;
}

