static long long gcd_ll(long long a, long long b) {
    while (b != 0) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

struct SlopeKey {
    long long dy, dx;
    bool operator==(const SlopeKey& o) const noexcept { return dy == o.dy && dx == o.dx; }
};

struct SlopeHash {
    size_t operator()(const SlopeKey& k) const noexcept {
        size_t h1 = std::hash<long long>{}(k.dy);
        size_t h2 = std::hash<long long>{}(k.dx);
        return h1 ^ (h2 << 1);
    }
};

struct LineKey {
    long long dy, dx, c;
    bool operator==(const LineKey& o) const noexcept { return dy == o.dy && dx == o.dx && c == o.c; }
};

struct LineHash {
    size_t operator()(const LineKey& k) const noexcept {
        size_t h = std::hash<long long>{}(k.dy);
        h ^= std::hash<long long>{}(k.dx) + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= std::hash<long long>{}(k.c) + 0x9e3779b9 + (h << 6) + (h >> 2);
        return h;
    }
};

struct MidKey {
    long long sx, sy;
    bool operator==(const MidKey& o) const noexcept { return sx == o.sx && sy == o.sy; }
};

struct MidHash {
    size_t operator()(const MidKey& k) const noexcept {
        size_t h1 = std::hash<long long>{}(k.sx);
        size_t h2 = std::hash<long long>{}(k.sy);
        return h1 ^ (h2 << 1);
    }
};

struct LineEntry {
    long long count = 0;
    std::unordered_map<int, long long> pointDegLine;
};

struct SlopeEntry {
    long long total = 0;
    std::unordered_map<int, long long> pointDeg;
    std::unordered_map<LineKey, LineEntry, LineHash> lineMap;
};

long long countNumberOfTrapezoids(const std::vector<std::vector<int>>& points) {
    const int n = static_cast<int>(points.size());
    std::unordered_map<SlopeKey, SlopeEntry, SlopeHash> slopeMap;
    std::unordered_map<MidKey, long long, MidHash> midMap;

    for (int i = 0; i < n; ++i) {
        long long xi = points[i][0];
        long long yi = points[i][1];
        for (int j = i + 1; j < n; ++j) {
            long long xj = points[j][0];
            long long yj = points[j][1];
            long long dx = xj - xi;
            long long dy = yj - yi;
            long long g = gcd_ll(std::llabs(dx), std::llabs(dy));
            if (g != 0) {
                dx /= g;
                dy /= g;
            }
            if (dx < 0) {
                dx = -dx;
                dy = -dy;
            } else if (dx == 0 && dy < 0) {
                dy = -dy;
            }
            SlopeKey slopeKey{dy, dx};
            long long c = dy * xi - dx * yi;
            LineKey lineKey{dy, dx, c};
            MidKey midKey{xi + xj, yi + yj};

            ++midMap[midKey];

            SlopeEntry& slopeEntry = slopeMap[slopeKey];
            ++slopeEntry.total;
            ++slopeEntry.pointDeg[i];
            ++slopeEntry.pointDeg[j];

            LineEntry& lineEntry = slopeEntry.lineMap[lineKey];
            ++lineEntry.count;
            ++lineEntry.pointDegLine[i];
            ++lineEntry.pointDegLine[j];
        }
    }

    long long trapezoidPairs = 0;
    for (const auto& sp : slopeMap) {
        const SlopeEntry& se = sp.second;
        long long m = se.total;
        long long totalPairs = m * (m - 1) / 2;

        long long sharePoint = 0;
        for (const auto& pd : se.pointDeg) {
            long long d = pd.second;
            sharePoint += d * (d - 1) / 2;
        }

        long long sameLinePairs = 0;
        long long sameLineSharePoint = 0;
        for (const auto& lp : se.lineMap) {
            const LineEntry& le = lp.second;
            long long t = le.count;
            sameLinePairs += t * (t - 1) / 2;
            for (const auto& pdL : le.pointDegLine) {
                long long dL = pdL.second;
                sameLineSharePoint += dL * (dL - 1) / 2;
            }
        }

        long long valid = totalPairs - sharePoint - sameLinePairs + sameLineSharePoint;
        trapezoidPairs += valid;
    }

    long long parallelogramCount = 0;
    for (const auto& mp : midMap) {
        long long cnt = mp.second;
        if (cnt > 1) {
            parallelogramCount += cnt * (cnt - 1) / 2;
        }
    }

    return trapezoidPairs - parallelogramCount;
}

