long long maxLCT(const std::string& s) {
    int n = static_cast<int>(s.size());
    std::vector<long long> prefixL(n + 1, 0), suffixT(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        prefixL[i + 1] = prefixL[i] + (s[i] == 'L' ? 1 : 0);
    }
    for (int i = n - 1; i >= 0; --i) {
        suffixT[i] = suffixT[i + 1] + (s[i] == 'T' ? 1 : 0);
    }

    long long original = 0;
    for (int i = 0; i < n; ++i) {
        if (s[i] == 'C') {
            original += prefixL[i] * suffixT[i + 1];
        }
    }

    std::vector<long long> suffixCT(n + 1, 0);
    for (int i = n - 1; i >= 0; --i) {
        suffixCT[i] = suffixCT[i + 1];
        if (s[i] == 'C') {
            suffixCT[i] += suffixT[i + 1];
        }
    }

    std::vector<long long> prefixLC(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        prefixLC[i + 1] = prefixLC[i];
        if (s[i] == 'C') {
            prefixLC[i + 1] += prefixL[i];
        }
    }

    long long bestInc = 0;
    for (int pos = 0; pos <= n; ++pos) {
        long long incL = suffixCT[pos];
        long long incT = prefixLC[pos];
        long long incC = prefixL[pos] * suffixT[pos];
        bestInc = std::max(bestInc, std::max(incL, std::max(incT, incC)));
    }

    return original + bestInc;
}

