using namespace std;
int minJumpsPrimeTeleport(vector<int>& nums) {
    int n = nums.size();
    if (n <= 1) return 0;
    int maxVal = *max_element(nums.begin(), nums.end());
    vector<int> spf(maxVal+1, 0);
    for (int i = 2; i <= maxVal; i++) {
        if (spf[i] == 0) {
            spf[i] = i;
            if ((long long)i*i <= maxVal)
                for (int j = i*i; j <= maxVal; j += i) if (spf[j]==0) spf[j] = i;
        }
    }
    auto isPrime = [&](int v) { return v > 1 && spf[v] == v; };

    unordered_map<int, vector<int>> primeToIndices;
    for (int i = 0; i < n; i++) {
        int x = nums[i];
        set<int> facs;
        while (x > 1) {
            int p = spf[x] ? spf[x] : x;
            facs.insert(p);
            while (x % p == 0) x /= p;
        }
        for (int p : facs) primeToIndices[p].push_back(i);
    }

    vector<int> dist(n, -1);
    dist[0] = 0;
    queue<int> q; q.push(0);
    while (!q.empty()) {
        int cur = q.front(); q.pop();
        int curDist = dist[cur];
        if (cur == n-1) return curDist;
        for (int nxt : {cur-1, cur+1}) {
            if (nxt >= 0 && nxt < n && dist[nxt] == -1) { dist[nxt] = curDist+1; q.push(nxt); }
        }
        if (isPrime(nums[cur])) {
            int p = nums[cur];
            for (int nxt : primeToIndices[p]) {
                if (dist[nxt] == -1) { dist[nxt] = curDist+1; q.push(nxt); }
            }
            primeToIndices[p].clear();
        }
    }
    return -1;
}
