    vector<int> a1 = {1,2,4,6};
    cout << minJumpsPrimeTeleport(a1) << "\n";
    vector<int> a2 = {2,3,4,7,9};
    cout << minJumpsPrimeTeleport(a2) << "\n";
    vector<int> a3 = {4,6,5,8};
    cout << minJumpsPrimeTeleport(a3) << "\n";
}

