unsigned long long bestXorSum(const vector<int>& arr) {
    if (arr.empty()) return 0ULL;
    unsigned int T = 0;
    for (int v : arr) T ^= (unsigned int)v;
    unsigned int basis[31] = {0};
    for (int v : arr) {
        unsigned int cur = (unsigned int)v;
        for (int b = 30; b >= 0; --b) {
            if (!((cur >> b) & 1)) continue;
            if (basis[b] == 0) { basis[b] = cur; break; }
            cur ^= basis[b];
        }
    }
    unsigned int x = 0;
    for (int b = 30; b >= 0; --b) {
        if (basis[b] == 0) continue;
        if (!((T >> b) & 1)) x ^= basis[b];
    }
    return (unsigned long long)x + (unsigned long long)(T ^ x);
}

unsigned long long maxXorAndPartition(const vector<int>& nums) {
    int n = (int)nums.size();
    unsigned long long best = 0;
    for (int maskB = 0; maskB < (1 << n); ++maskB) {
        unsigned int andB = 0; bool first = true;
        vector<int> remaining;
        for (int i = 0; i < n; ++i) {
            if ((maskB >> i) & 1) {
                if (first) { andB = (unsigned int)nums[i]; first = false; }
                else andB &= (unsigned int)nums[i];
            } else remaining.push_back(nums[i]);
        }
        if (first) andB = 0;
        unsigned long long cur = bestXorSum(remaining) + (unsigned long long)andB;
        if (cur > best) best = cur;
    }
    return best;
}

