int minRemovals(std::vector<int> nums, int k) {
    std::sort(nums.begin(), nums.end());
    size_t n = nums.size();
    size_t left = 0;
    size_t best = 0;
    for (size_t right = 0; right < n; ++right) {
        while (left <= right && static_cast<long long>(nums[right]) > static_cast<long long>(k) * nums[left]) {
            ++left;
        }
        size_t window = right - left + 1;
        if (window > best) best = window;
    }
    return static_cast<int>(n - best);
}

