int earliestFinishTime(const std::vector<int>& landStartTime, const std::vector<int>& landDuration,
                       const std::vector<int>& waterStartTime, const std::vector<int>& waterDuration) {
    const int INF = std::numeric_limits<int>::max();
    int n = landStartTime.size();
    int m = waterStartTime.size();

    std::vector<std::pair<int,int>> land(n), water(m);
    for (int i = 0; i < n; ++i) land[i] = {landStartTime[i], landStartTime[i] + landDuration[i]};
    for (int i = 0; i < m; ++i) water[i] = {waterStartTime[i], waterStartTime[i] + waterDuration[i]};

    std::sort(land.begin(), land.end(),
              [](const auto& a, const auto& b){ return a.first < b.first; });
    std::sort(water.begin(), water.end(),
              [](const auto& a, const auto& b){ return a.first < b.first; });

    std::vector<int> landStarts(n), landEnds(n), landDiffPrefixMin(n);
    for (int i = 0; i < n; ++i) {
        landStarts[i] = land[i].first;
        landEnds[i] = land[i].second;
    }
    for (int i = 0; i < n; ++i) {
        int diff = landEnds[i] - landStarts[i];
        landDiffPrefixMin[i] = (i == 0) ? diff : std::min(landDiffPrefixMin[i-1], diff);
    }
    std::vector<int> landEndSuffixMin(n);
    for (int i = n-1; i >= 0; --i) {
        landEndSuffixMin[i] = (i == n-1) ? landEnds[i] : std::min(landEnds[i], landEndSuffixMin[i+1]);
    }

    std::vector<int> waterStarts(m), waterEnds(m), waterDiffPrefixMin(m);
    for (int i = 0; i < m; ++i) {
        waterStarts[i] = water[i].first;
        waterEnds[i] = water[i].second;
    }
    for (int i = 0; i < m; ++i) {
        int diff = waterEnds[i] - waterStarts[i];
        waterDiffPrefixMin[i] = (i == 0) ? diff : std::min(waterDiffPrefixMin[i-1], diff);
    }
    std::vector<int> waterEndSuffixMin(m);
    for (int i = m-1; i >= 0; --i) {
        waterEndSuffixMin[i] = (i == m-1) ? waterEnds[i] : std::min(waterEnds[i], waterEndSuffixMin[i+1]);
    }

    int best = INF;

    // land then water
    for (int i = 0; i < n; ++i) {
        int landEnd = landEnds[i];
        int idx = std::lower_bound(waterStarts.begin(), waterStarts.end(), landEnd) - waterStarts.begin();
        int cand = INF;
        if (idx < m) {
            cand = std::min(cand, waterEndSuffixMin[idx]); // start >= landEnd
        }
        if (idx > 0) {
            cand = std::min(cand, landEnd + waterDiffPrefixMin[idx-1]); // start < landEnd
        }
        best = std::min(best, cand);
    }

    // water then land
    for (int i = 0; i < m; ++i) {
        int waterEnd = waterEnds[i];
        int idx = std::lower_bound(landStarts.begin(), landStarts.end(), waterEnd) - landStarts.begin();
        int cand = INF;
        if (idx < n) {
            cand = std::min(cand, landEndSuffixMin[idx]);
        }
        if (idx > 0) {
            cand = std::min(cand, waterEnd + landDiffPrefixMin[idx-1]);
        }
        best = std::min(best, cand);
    }

    return best;
}

