int earliestFinishTime(std::vector<int> landStartTime, std::vector<int> landDuration,
                       std::vector<int> waterStartTime, std::vector<int> waterDuration) {
    using ll = long long;
    const ll INF = (1LL<<60);
    int n = static_cast<int>(landStartTime.size());
    int m = static_cast<int>(waterStartTime.size());

    std::vector<std::pair<int,int>> land(n), water(m);
    for (int i = 0; i < n; ++i) land[i] = {landStartTime[i], landDuration[i]};
    for (int i = 0; i < m; ++i) water[i] = {waterStartTime[i], waterDuration[i]};
    std::sort(land.begin(), land.end(),
              [](const std::pair<int,int>& a, const std::pair<int,int>& b){ return a.first < b.first; });
    std::sort(water.begin(), water.end(),
              [](const std::pair<int,int>& a, const std::pair<int,int>& b){ return a.first < b.first; });

    // preprocess water for queries
    std::vector<ll> suffixBest(m);
    for (int i = m-1; i >= 0; --i) {
        ll val = (ll)water[i].first + (ll)water[i].second;
        suffixBest[i] = (i == m-1) ? val : std::min(val, suffixBest[i+1]);
    }
    std::vector<ll> prefixBest(m);
    for (int i = 0; i < m; ++i) {
        ll val = (ll)water[i].second;
        prefixBest[i] = (i == 0) ? val : std::min(val, prefixBest[i-1]);
    }

    ll best = INF;

    // land -> water
    for (const auto& L : land) {
        ll endLand = (ll)L.first + (ll)L.second;
        int idx = std::lower_bound(water.begin(), water.end(), std::make_pair((int)endLand, INT_MIN),
                                   [](const std::pair<int,int>& a, const std::pair<int,int>& b){
                                       return a.first < b.first;
                                   }) - water.begin();
        ll cand = INF;
        if (idx < m) cand = std::min(cand, suffixBest[idx]);               // water starts after or at endLand
        if (idx > 0) cand = std::min(cand, endLand + prefixBest[idx-1]);   // water starts before endLand
        best = std::min(best, cand);
    }

    // preprocess land for queries (water -> land)
    std::vector<ll> suffixBestL(n);
    for (int i = n-1; i >= 0; --i) {
        ll val = (ll)land[i].first + (ll)land[i].second;
        suffixBestL[i] = (i == n-1) ? val : std::min(val, suffixBestL[i+1]);
    }
    std::vector<ll> prefixBestL(n);
    for (int i = 0; i < n; ++i) {
        ll val = (ll)land[i].second;
        prefixBestL[i] = (i == 0) ? val : std::min(val, prefixBestL[i-1]);
    }

    // water -> land
    for (const auto& W : water) {
        ll endWater = (ll)W.first + (ll)W.second;
        int idx = std::lower_bound(land.begin(), land.end(), std::make_pair((int)endWater, INT_MIN),
                                   [](const std::pair<int,int>& a, const std::pair<int,int>& b){
                                       return a.first < b.first;
                                   }) - land.begin();
        ll cand = INF;
        if (idx < n) cand = std::min(cand, suffixBestL[idx]);
        if (idx > 0) cand = std::min(cand, endWater + prefixBestL[idx-1]);
        best = std::min(best, cand);
    }

    return static_cast<int>(best);
}

