bool isTrionicArray(const std::vector<int>& nums) {
    std::size_t n = nums.size();
    if (n < 3) return false;

    std::vector<bool> incPrefix(n, false);
    incPrefix[0] = true;
    for (std::size_t i = 1; i < n; ++i) {
        incPrefix[i] = incPrefix[i - 1] && (nums[i - 1] < nums[i]);
    }

    std::vector<bool> incSuffix(n, false);
    incSuffix[n - 1] = true;
    for (std::size_t i = n - 1; i-- > 0;) {
        incSuffix[i] = incSuffix[i + 1] && (nums[i] < nums[i + 1]);
    }

    std::vector<int> decFrom(n, 0);
    for (std::size_t i = n - 1; i-- > 0;) {
        if (nums[i] > nums[i + 1]) {
            decFrom[i] = 1 + decFrom[i + 1];
        }
    }

    for (std::size_t p = 0; p <= n - 3; ++p) {
        if (!incPrefix[p]) continue;
        std::size_t start = p + 1;
        if (start >= n - 1) continue;
        int decLen = decFrom[start];
        if (decLen == 0) continue;
        std::size_t q = start + decLen;
        if (q + 1 < n && incSuffix[q + 1]) return true;
    }
    return false;
}

