vector<int> majorityElement(vector<int>& nums, vector<vector<int>>& queries) {
    int n = nums.size();
    int q = queries.size();
    int block = static_cast<int>(std::sqrt(n)) + 1;

    vector<int> uniq = nums;
    std::sort(uniq.begin(), uniq.end());
    uniq.erase(std::unique(uniq.begin(), uniq.end()), uniq.end());
    unordered_map<int, int> toId;
    toId.reserve(uniq.size() * 2);
    for (int i = 0; i < (int)uniq.size(); ++i) toId[uniq[i]] = i;
    vector<int> idAtPos(n);
    for (int i = 0; i < n; ++i) idAtPos[i] = toId[nums[i]];

    struct Q {int l, r, t, idx;};
    vector<Q> qs;
    qs.reserve(q);
    for (int i = 0; i < q; ++i) {
        qs.push_back({queries[i][0], queries[i][1], queries[i][2], i});
    }
    std::sort(qs.begin(), qs.end(), [&](const Q& a, const Q& b) {
        int ba = a.l / block;
        int bb = b.l / block;
        if (ba != bb) return ba < bb;
        if (ba & 1) return a.r < b.r;
        return a.r > b.r;
    });

    vector<int> ans(q);
    vector<int> freq(uniq.size(), 0);
    vector<unordered_set<int>> freqVals(n + 1);
    int curL = 0, curR = -1, curMax = 0;

    auto add = [&](int pos) {
        int id = idAtPos[pos];
        int old = freq[id];
        int nw = old + 1;
        freq[id] = nw;
        if (old > 0) freqVals[old].erase(id);
        freqVals[nw].insert(id);
        if (nw > curMax) curMax = nw;
    };
    auto remove = [&](int pos) {
        int id = idAtPos[pos];
        int old = freq[id];
        int nw = old - 1;
        freq[id] = nw;
        freqVals[old].erase(id);
        if (nw > 0) freqVals[nw].insert(id);
        if (freqVals[curMax].empty()) {
            while (curMax > 0 && freqVals[curMax].empty()) --curMax;
        }
    };

    for (const auto& qq : qs) {
        while (curL > qq.l) add(--curL);
        while (curR < qq.r) add(++curR);
        while (curL < qq.l) remove(curL++);
        while (curR > qq.r) remove(curR--);
        if (curMax >= qq.t) {
            int id = *std::min_element(freqVals[curMax].begin(), freqVals[curMax].end());
            ans[qq.idx] = uniq[id];
        } else {
            ans[qq.idx] = -1;
        }
    }
    return ans;
}

class Solution {
public:
    long long maxSumTrionic(vector<int>& nums) {
        int n = nums.size();
        int i = 0;
        long long ans = LLONG_MIN;
        while (i < n) {
            int l = i;
            i += 1;
            while (i < n && nums[i - 1] < nums[i]) i += 1;
            if (i == l + 1) continue;
            int p = i - 1;
            long long s = (long long) nums[p - 1] + nums[p];
            while (i < n && nums[i - 1] > nums[i]) { s += nums[i]; i += 1; }
            if (i == p + 1 || i == n || nums[i - 1] == nums[i]) continue;
            int q = i - 1;
            s += nums[i];
            i += 1;
            long long mx = 0, t = 0;
            while (i < n && nums[i - 1] < nums[i]) { t += nums[i]; i += 1; mx = max(mx, t); }
            s += mx;
            mx = 0; t = 0;
            int j = p - 2;
            while (j >= l) { t += nums[j]; mx = max(mx, t); j -= 1; }
            s += mx;
            ans = max(ans, s);
            i = q;
        }
        return ans;
    }
};

