int minimumTime(std::string s, std::vector<int> order, long long k) {
    int n = static_cast<int>(s.size());
    long long total = 1LL * n * (n + 1) / 2;
    if (k > total) return -1;
    long long bad = total;
    std::set<int> stars;
    stars.insert(-1);
    stars.insert(n);
    for (int i = 0; i < static_cast<int>(order.size()); ++i) {
        int p = order[i];
        auto itRight = stars.lower_bound(p);
        int right = *itRight;
        int left = *std::prev(itRight);
        long long segLen = right - left - 1;
        long long oldContrib = segLen * (segLen + 1) / 2;
        long long leftLen = p - left - 1;
        long long rightLen = right - p - 1;
        long long newContrib = leftLen * (leftLen + 1) / 2 + rightLen * (rightLen + 1) / 2;
        bad = bad - oldContrib + newContrib;
        long long good = total - bad;
        if (good >= k) return i;
        stars.insert(p);
    }
    return -1;
}

