long long minimumSum(const std::vector<int>& a, int K) {
    long long total = 0;
    long long dp = 0;
    std::unordered_map<int, long long> best;
    best.reserve(a.size() * 2);
    best[0] = 0;
    const long long NEG_INF = std::numeric_limits<long long>::min() / 4;
    for (int v : a) {
        total += v;
        int r = static_cast<int>((total % K + K) % K);
        long long cur = dp;
        auto it = best.find(r);
        if (it != best.end()) {
            long long cand = total + it->second;
            if (cand > cur) cur = cand;
        }
        dp = cur;
        long long val = dp - total;
        auto it2 = best.find(r);
        if (it2 != best.end()) {
            if (val > it2->second) it2->second = val;
        } else {
            best[r] = val;
        }
    }
    return total - dp;
}

