int maximumWallsDestroyed(std::vector<int> robots, std::vector<int> distance, std::vector<int> walls) {
    int n = (int)robots.size();
    std::vector<std::pair<int,int>> arr(n);
    for (int i = 0; i < n; i++) arr[i] = {robots[i], distance[i]};
    std::sort(arr.begin(), arr.end());
    std::sort(walls.begin(), walls.end());

    std::map<std::pair<int,int>, int> memo;
    std::function<int(int,int)> dp = [&](int i, int j) -> int {
        if (i < 0) return 0;
        auto key = std::make_pair(i, j);
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        auto [pos, dist] = arr[i];

        int left = pos - dist;
        if (i > 0) left = std::max(left, arr[i-1].first + 1);
        int l = (int)(std::lower_bound(walls.begin(), walls.end(), left) - walls.begin());
        int r = (int)(std::lower_bound(walls.begin(), walls.end(), pos + 1) - walls.begin());
        int optLeft = dp(i-1, 0) + (r - l);

        int right = pos + dist;
        if (i + 1 < n) {
            auto [npos, ndist] = arr[i+1];
            if (j == 0) right = std::min(right, npos - ndist - 1);
            else right = std::min(right, npos - 1);
        }
        l = (int)(std::lower_bound(walls.begin(), walls.end(), pos) - walls.begin());
        r = (int)(std::lower_bound(walls.begin(), walls.end(), right + 1) - walls.begin());
        int optRight = dp(i-1, 1) + (r - l);

        int res = std::max(optLeft, optRight);
        memo[key] = res;
        return res;
    };
    return dp(n - 1, 1);
}

