bool canPartitionKDistinct(const std::vector<int>& arr, int k) {
    std::size_t n = arr.size();
    if (k <= 0 || n % static_cast<std::size_t>(k) != 0) return false;
    std::size_t groups = n / static_cast<std::size_t>(k);
    std::unordered_map<int, int> freq;
    for (std::size_t i = 0; i < n; ++i) {
