    }
    int totalP=0, maxP=0; for(auto& pr:P){totalP+=pr.second; maxP=std::max(maxP,pr.second);}
    int totalQ=0, maxQ=0; for(auto& pr:Q){totalQ+=pr.second; maxQ=std::max(maxQ,pr.second);}
    int total = totalP+totalQ+Z;
    int bottleneck = std::max(maxP+maxQ, Z);
    return std::min(total/2, total-bottleneck);
}

