int findLeastFrequentDigit(long long num) {
    if (num == 0) {
        return 0;
    }
    if (num < 0) {
        num = -num;
    }
    int freq[10] = {};
    while (num > 0) {
        int d = static_cast<int>(num % 10);
        ++freq[d];
        num /= 10;
    }
    int minCount = INT_MAX;
    int answer = -1;
    for (int d = 0; d < 10; ++d) {
        if (freq[d] > 0 && freq[d] < minCount) {
            minCount = freq[d];
            answer = d;
        }
    }
    return answer;
}

