long long maxProduct(std::vector<int>& nums) {
    if (nums.empty()) return 0;
    int maxVal = 0;
    for (int v : nums) if (v > maxVal) maxVal = v;
    int B = 0;
    while (B < 15 && (1 << B) <= maxVal) ++B;
    if (B == 0) B = 1;
    int SZ = 1 << B;
    std::vector<int> best1(SZ, -1), best2(SZ, -1);
    auto upd = [&](int &first, int &second, int val) {
        if (val > first) {
            second = first;
            first = val;
        } else if (val > second) {
            second = val;
        }
    };
    for (int v : nums) upd(best1[v], best2[v], v);
    for (int i = 0; i < B; ++i) {
        for (int mask = 0; mask < SZ; ++mask) {
            if (mask & (1 << i)) {
                int sub = mask ^ (1 << i);
                int candidates[4] = {best1[mask], best2[mask], best1[sub], best2[sub]};
                int a = -1, b = -1;
                for (int val : candidates) {
                    if (val == -1) continue;
                    if (val > a) {
                        b = a;
                        a = val;
                    } else if (val > b && val != a) {
                        b = val;
                    }
                }
                best1[mask] = a;
                best2[mask] = b;
            }
        }
    }
    long long ans = 0;
    int fullMask = SZ - 1;
    for (int v : nums) {
        int complement = fullMask ^ v;
        int cand = best1[complement];
        if (cand == -1) continue;
        if (cand == v) {
            cand = best2[complement];
            if (cand == -1) continue;
        }
        long long prod = 1LL * v * cand;
        if (prod > ans) ans = prod;
    }
    return ans;
}

