const long long MOD = 1000000007;

long long sumOfBeautifulSubsequencesOptimal(vector<int>& nums) {
    int n = nums.size();
    int maxV = *max_element(nums.begin(), nums.end());
    unordered_map<int, vector<int>> divisorsCache;
    auto divisorsOf = [&](int v) -> vector<int>& {
        auto it = divisorsCache.find(v);
        if (it != divisorsCache.end()) return it->second;
        vector<int> res;
        for (int d = 1; (long long)d*d <= v; d++) {
            if (v % d == 0) { res.push_back(d); if (d != v/d) res.push_back(v/d); }
        }
        divisorsCache[v] = res;
        return divisorsCache[v];
    };
    unordered_map<int, vector<long long>> fenwicks;
    auto getFenwick = [&](int d) -> vector<long long>& {
        auto it = fenwicks.find(d);
        if (it != fenwicks.end()) return it->second;
        fenwicks[d] = vector<long long>(maxV + 2, 0);
        return fenwicks[d];
    };
    auto fenUpdate = [&](vector<long long>& tree, int i, long long val) {
        for (; i <= maxV; i += i & (-i)) tree[i] = (tree[i] + val) % MOD;
    };
    auto fenQuery = [&](vector<long long>& tree, int i) -> long long {
        long long s = 0;
        for (; i > 0; i -= i & (-i)) s = (s + tree[i]) % MOD;
        return s;
    };
    unordered_map<int, long long> dpMultiple;
    for (int v : nums) {
        auto& divs = divisorsOf(v);
        unordered_map<int, long long> dpForThis;
        for (int d : divs) {
            auto& tree = getFenwick(d);
            long long sumLess = fenQuery(tree, v - 1);
            long long val = (sumLess + 1) % MOD;
            dpForThis[d] = val;
        }
        for (auto& [d, val] : dpForThis) {
            auto& tree = getFenwick(d);
            fenUpdate(tree, v, val);
            dpMultiple[d] = (dpMultiple[d] + val) % MOD;
        }
    }
    vector<int> ds;
    for (auto& [d, v] : dpMultiple) ds.push_back(d);
    sort(ds.rbegin(), ds.rend());
    unordered_map<int, long long> exact;
    for (int g : ds) {
        long long val = dpMultiple[g];
        for (int k = 2*g; k <= maxV; k += g) {
            if (exact.count(k)) val = ((val - exact[k]) % MOD + MOD) % MOD;
        }
        exact[g] = val;
    }
    long long ans = 0;
    for (auto& [g, cnt] : exact) ans = (ans + (long long)g * cnt) % MOD;
    return ans;
}

long long sumOfBeautifulSubsequencesAlgo(vector<int>& nums) {
    int n = nums.size();
    map<int, long long> beauty;
    for (int mask = 1; mask < (1<<n); mask++) {
        vector<int> sub;
        for (int i = 0; i < n; i++) if (mask & (1<<i)) sub.push_back(nums[i]);
        bool inc = true;
        for (size_t i = 1; i < sub.size(); i++) if (sub[i] <= sub[i-1]) { inc = false; break; }
        if (!inc) continue;
        int g = sub[0];
        for (size_t i = 1; i < sub.size(); i++) g = __gcd(g, sub[i]);
        beauty[g]++;
    }
    long long total = 0;
    for (auto& [g, c] : beauty) total = (total + (long long)g * c) % MOD;
    return total;
}

