long long countBowlSubarrays(const std::vector<int>& arr) {
    int n = (int)arr.size();
    if (n < 3) return 0;

    std::vector<int> nextGreater(n, -1), prevGreater(n, -1);
    std::vector<int> stack1;
    for (int i = 0; i < n; i++) {
        while (!stack1.empty() && arr[stack1.back()] < arr[i]) {
            nextGreater[stack1.back()] = i;
            stack1.pop_back();
        }
        stack1.push_back(i);
    }
    std::vector<int> stack2;
    for (int i = n - 1; i >= 0; i--) {
        while (!stack2.empty() && arr[stack2.back()] < arr[i]) {
            prevGreater[stack2.back()] = i;
            stack2.pop_back();
        }
        stack2.push_back(i);
    }

    long long count = 0;
    for (int l = 0; l < n; l++) {
        int r = nextGreater[l];
        if (r != -1 && r - l >= 2) count++;
    }
    for (int r = 0; r < n; r++) {
        int l = prevGreater[r];
        if (l != -1 && r - l >= 2) count++;
    }
    return count;
}

