unsigned long long countBinaryPalindromes(unsigned long long N) {
    if (N == 0ULL) return 1ULL; // just the number 0 itself
    std::string bits;
    {
        unsigned long long t = N;
        while (t) { bits.push_back(static_cast<char>('0' + (t & 1ULL))); t >>= 1; }
        std::reverse(bits.begin(), bits.end());
    }
    int L = static_cast<int>(bits.size());
    unsigned long long total = 1ULL; // count the number 0

    for (int l = 1; l < L; ++l) {
        total += 1ULL << ((l - 1) / 2);
    }

    int halfLen = (L + 1) / 2;
    unsigned long long prefix = std::stoull(bits.substr(0, halfLen), nullptr, 2);
    unsigned long long base = 1ULL << (halfLen - 1);
    if (prefix > base) total += (prefix - base);

    std::string frontPart = bits.substr(0, halfLen);
    std::string rev;
    if (L % 2 == 0) {
        rev = frontPart;
    } else {
        rev = bits.substr(0, halfLen - 1);
    }
    std::reverse(rev.begin(), rev.end());
    unsigned long long pal = std::stoull(frontPart + rev, nullptr, 2);
    if (pal <= N) total += 1ULL;

    return total;
}

unsigned long long maxSubsequenceXOR(std::vector<unsigned long long>& nums) {
