    for (unsigned long long x : nums) {
        for (unsigned long long b : basis) x = std::min(x, x ^ b);
        if (x) basis.push_back(x);
    }
    std::sort(basis.rbegin(), basis.rend());
    unsigned long long ans = 0;
    for (unsigned long long b : basis) ans = std::max(ans, ans ^ b);
    return ans;
}

class Solution {
public:
    static const int MAXK = 4001;
    vector<bool> subsequenceSumAfterCapping(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> freq(n + 2, 0);
        for (int v : nums) freq[v]++;
        // freeDP: achievable sums using items whose true value <= current x (uncapped, real value)
        bitset<MAXK> freeDP;
        freeDP[0] = 1;
        int runningCappedCount = n; // items still strictly above current x, each contributing exactly x
        vector<bool> ans(n, false);
        for (int x = 1; x <= n; x++) {
            int cntX = freq[x];
            for (int i = 0; i < cntX; i++) {
                freeDP |= (freeDP << x);
            }
            runningCappedCount -= cntX;
            int m = runningCappedCount;
            int maxJ = min(m, k / x);
            // combine freeDP with 0..m copies of value x (harmonic-series bitset trick)
            bitset<MAXK> combined;
            bitset<MAXK> shifted = freeDP;
            for (int j = 0; j <= maxJ; j++) {
                combined |= shifted;
                shifted <<= x;
            }
            ans[x - 1] = combined[k];
        }
        return ans;
    }
};

