long long numberOfStableSubsequences(vector<int>& nums) {
    const long long MOD = 1000000007;
    long long dp[2][2] = {{0,0},{0,0}};
    for (int x : nums) {
        int p = ((x % 2) + 2) % 2;
        int opp = 1 - p;
        long long addRun1 = (1 + dp[opp][0] + dp[opp][1]) % MOD;
        long long addRun2 = dp[p][0];
        dp[p][0] = (dp[p][0] + addRun1) % MOD;
        dp[p][1] = (dp[p][1] + addRun2) % MOD;
    }
    return (dp[0][0]+dp[0][1]+dp[1][0]+dp[1][1]) % MOD;
}

