int distinctPoints(const std::string& s, int k) {
    int n = static_cast<int>(s.size());
    std::vector<int> xs(n + 1, 0), ys(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        xs[i + 1] = xs[i];
        ys[i + 1] = ys[i];
        char c = s[i];
        if (c == 'L') xs[i + 1]--;
        else if (c == 'R') xs[i + 1]++;
        else if (c == 'U') ys[i + 1]++;
        else if (c == 'D') ys[i + 1]--;
    }
    int totalX = xs[n], totalY = ys[n];
    std::set<std::pair<int,int>> seen;
    for (int i = k; i <= n; ++i) {
        int removedX = xs[i] - xs[i - k];
        int removedY = ys[i] - ys[i - k];
        seen.insert({totalX - removedX, totalY - removedY});
    }
    return static_cast<int>(seen.size());
}

#include <bits/stdc++.h>

long long maxAlternatingSum(const std::vector<int>& arr, const std::vector<std::pair<int,int>>& swaps) {
    int n = static_cast<int>(arr.size());
    if (n == 0) return 0;

    std::vector<int> parent(n), rankv(n, 0);
    for (int i = 0; i < n; ++i) parent[i] = i;

    std::function<int(int)> find = [&](int x) -> int {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    };

    auto unite = [&](int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (rankv[ra] < rankv[rb]) std::swap(ra, rb);
        parent[rb] = ra;
        if (rankv[ra] == rankv[rb]) ++rankv[ra];
    };

    for (const auto& p : swaps) unite(p.first, p.second);

    std::vector<std::vector<int>> comps(n);
    for (int i = 0; i < n; ++i) comps[find(i)].push_back(i);

    long long total = 0;
    std::vector<int> values;
    values.reserve(n);

    for (auto& idxList : comps) {
        if (idxList.empty()) continue;
        values.clear();
        int posCnt = 0;
        for (int idx : idxList) {
            values.push_back(arr[idx]);
            if ((idx & 1) == 0) ++posCnt;
        }
        std::sort(values.begin(), values.end(), std::greater<int>());
        long long posSum = 0, negSum = 0;
        for (size_t k = 0; k < values.size(); ++k) {
            if (static_cast<int>(k) < posCnt) posSum += values[k];
            else negSum += values[k];
        }
        total += posSum - negSum;
    }
    return total;
}

