        for (int r = l; r < n; r++) {
            mx = std::max(mx, nums[r]);
            mn = std::min(mn, nums[r]);
            values.push_back(mx - mn);
        }
    }
    std::sort(values.begin(), values.end(), std::greater<long long>());
    long long total = 0;
    for (long long i = 0; i < k; i++) total += values[i];
    return total;
}

