const long long MOD = 1000000007LL;
std::vector<std::vector<long long>> matMul(std::vector<std::vector<long long>>& A, std::vector<std::vector<long long>>& B) {
    int n = A.size();
    std::vector<std::vector<long long>> C(n, std::vector<long long>(n, 0));
    for (int i = 0; i < n; i++) for (int k = 0; k < n; k++) {
        if (!A[i][k]) continue;
        for (int j = 0; j < n; j++) { if (!B[k][j]) continue; C[i][j] = (C[i][j] + A[i][k]*B[k][j]) % MOD; }
    }
    return C;
}
std::vector<std::vector<long long>> matPow(std::vector<std::vector<long long>> M, long long e) {
    int n = M.size();
    std::vector<std::vector<long long>> R(n, std::vector<long long>(n, 0));
    for (int i = 0; i < n; i++) R[i][i] = 1;
    while (e > 0) { if (e & 1) R = matMul(R, M); M = matMul(M, M); e >>= 1; }
    return R;
}
int zigZagArrays(int n, int l, int r) {
    int m = r - l + 1;
    std::vector<std::vector<long long>> T(m, std::vector<long long>(m, 0));
    for (int j = 0; j < m; j++) for (int i = m-j; i < m; i++) T[i][j] = 1;
    auto powT = matPow(T, n-1);
    long long total = 0;
    for (int i = 0; i < m; i++) for (int j = 0; j < m; j++) total = (total + powT[i][j]) % MOD;
    return (int)((total * 2) % MOD);
}

