using namespace std;
class Solution {
public:
    long long countNoZeroPairs(long long n) {
        string s = to_string(n);
        int m = s.size();
        vector<int> digits(m+1);
        for (int i = 0; i < m; i++) digits[i] = s[m-1-i]-'0';
        digits[m] = 0;
        long long dp[2][2][2] = {};
        dp[0][1][1] = 1;
        for (int pos = 0; pos < m+1; pos++) {
            long long ndp[2][2][2] = {};
            int target = digits[pos];
            for (int carry = 0; carry <= 1; carry++)
            for (int aliveA = 0; aliveA <= 1; aliveA++)
            for (int aliveB = 0; aliveB <= 1; aliveB++) {
                long long ways = dp[carry][aliveA][aliveB];
                if (!ways) continue;
                vector<pair<int,int>> A, B;
                if (aliveA) { for (int d=1;d<=9;d++) A.push_back({d,1}); if (pos>0) A.push_back({0,0}); }
                else A.push_back({0,0});
                if (aliveB) { for (int d=1;d<=9;d++) B.push_back({d,1}); if (pos>0) B.push_back({0,0}); }
                else B.push_back({0,0});
                for (auto& [da,na] : A) for (auto& [db,nb] : B) {
                    int sum = da+db+carry;
                    if (sum % 10 != target) continue;
                    ndp[sum/10][na][nb] += ways;
                }
            }
            memcpy(dp, ndp, sizeof(dp));
        }
        return dp[0][0][0];
    }
};

