std::string removeSubstring(const std::string& s, int k) {
    if (k <= 0) return s;
    const int targetLen = 2 * k;
    std::vector<char> res;
    std::vector<int> dp;
    res.reserve(s.size());
    dp.reserve(s.size());
    for (char c : s) {
        if (c == '(') {
            res.push_back(c);
            dp.push_back(0);
        } else { // c == ')'
            int length = 0;
            if (!res.empty()) {
                if (res.back() == '(') {
                    length = 2;
                } else {
                    int prevLen = dp.back();
                    int idx = static_cast<int>(res.size()) - 1 - prevLen;
                    if (idx >= 0 && res[idx] == '(') {
                        length = prevLen + 2;
                        if (idx - 1 >= 0) {
                            length += dp[idx - 1];
                        }
                    }
                }
            }
            res.push_back(c);
            dp.push_back(length);
            if (length == targetLen) {
                for (int i = 0; i < targetLen; ++i) {
                    res.pop_back();
                    dp.pop_back();
                }
            }
        }
    }
    return std::string(res.begin(), res.end());
}

