int smallestMissingMultiple(const std::vector<int>& arr, int K) {
    if (K == 0) return 0;
    std::unordered_set<int> present;
    present.reserve(arr.size() * 2);
    present.max_load_factor(0.7f);
    for (int v : arr) {
        present.insert(v);
    }
    int candidate = K;
    while (present.find(candidate) != present.end()) {
        if (candidate > std::numeric_limits<int>::max() - K) {
            // overflow protection, return candidate as is (will be out of int range)
            break;
        }
        candidate += K;
    }
    return candidate;
}

