#include <bits/stdc++.h>
int countWays(const std::vector<std::vector<int>>& rows) {
    const int MOD = 1000000007;
    int maxA = 0;
    for (const auto& r : rows) for (int x : r) if (x > maxA) maxA = x;
    if (maxA == 0) return 0;
    std::vector<int> mu(maxA + 1, 0), primes;
    std::vector<bool> isComp(maxA + 1, false);
    mu[1] = 1;
    for (int i = 2; i <= maxA; ++i) {
        if (!isComp[i]) {
            primes.push_back(i);
            mu[i] = -1;
        }
        for (int p : primes) {
            long long v = 1LL * i * p;
            if (v > maxA) break;
            isComp[v] = true;
            if (i % p == 0) {
                mu[v] = 0;
                break;
            } else {
                mu[v] = -mu[i];
            }
        }
    }
    std::vector<long long> prod(maxA + 1, 1);
    std::vector<int> rowsSeen(maxA + 1, 0);
    std::vector<int> cntDiv(maxA + 1, 0);
    std::vector<int> touched;
    int R = rows.size();
    for (const auto& r : rows) {
        touched.clear();
        for (int x : r) {
            for (int d = 1; d * 1LL * d <= x; ++d) {
                if (x % d != 0) continue;
                int d1 = d;
                if (cntDiv[d1] == 0) touched.push_back(d1);
                ++cntDiv[d1];
                int d2 = x / d;
                if (d2 != d1) {
                    if (cntDiv[d2] == 0) touched.push_back(d2);
                    ++cntDiv[d2];
                }
            }
        }
        for (int d : touched) {
            int c = cntDiv[d];
            prod[d] = prod[d] * c % MOD;
            ++rowsSeen[d];
            cntDiv[d] = 0;
        }
    }
    for (int d = 1; d <= maxA; ++d) {
        if (rowsSeen[d] != R) prod[d] = 0;
    }
    long long ans = 0;
    for (int d = 1; d <= maxA; ++d) {
        ans += 1LL * mu[d] * prod[d];
        ans %= MOD;
    }
    if (ans < 0) ans += MOD;
    return static_cast<int>(ans);
}

