std::string solvePalindromicPermutation(const std::string& s, const std::string& t) {
    int n = static_cast<int>(s.size());
    if (n != static_cast<int>(t.size())) return "";
    int cnt[256] = {0};
    for (unsigned char c : s) cnt[c]++;
    int oddCount = 0;
    for (int i = 0; i < 256; ++i) if (cnt[i] % 2) ++oddCount;
    if (oddCount > (n % 2)) return "";
    std::string res(n, ' ');
    int half = n / 2;
    std::function<bool(int, bool)> dfs = [&](int pos, bool greater) -> bool {
        if (pos == half) {
            if (n % 2) {
                unsigned char start = greater ? 0 : static_cast<unsigned char>(t[half]);
                for (int c = start; c < 256; ++c) {
                    if (cnt[c] > 0) {
                        res[half] = static_cast<char>(c);
                        cnt[c]--;
                        if (res > t) return true;
                        cnt[c]++;
                    }
                }
                return false;
            } else {
                return res > t;
            }
        }
        unsigned char start = greater ? 0 : static_cast<unsigned char>(t[pos]);
        for (int c = start; c < 256; ++c) {
            if (cnt[c] >= 2) {
                cnt[c] -= 2;
                res[pos] = res[n - 1 - pos] = static_cast<char>(c);
                bool nextGreater = greater || (c > static_cast<unsigned char>(t[pos]));
                if (dfs(pos + 1, nextGreater)) return true;
                cnt[c] += 2;
            }
        }
        return false;
    };
    if (dfs(0, false)) return res;
    return "";
}

