long long countSubarrays(const std::vector<int>& nums, int x) {
    int n = static_cast<int>(nums.size());
    std::vector<long long> pref(n + 1);
    for (int i = 0; i < n; ++i) {
        pref[i + 1] = pref[i] + (nums[i] == x ? 1 : -1);
    }
    std::vector<long long> uniq = pref;
    std::sort(uniq.begin(), uniq.end());
    uniq.erase(std::unique(uniq.begin(), uniq.end()), uniq.end());
    int m = static_cast<int>(uniq.size());
    std::vector<long long> bit(m + 2, 0);
    auto add = [&](int idx, long long delta) {
        for (int i = idx; i < (int)bit.size(); i += i & -i) bit[i] += delta;
    };
    auto sum = [&](int idx) {
        long long s = 0;
        for (int i = idx; i > 0; i -= i & -i) s += bit[i];
        return s;
    };
    long long ans = 0;
    int idx0 = std::lower_bound(uniq.begin(), uniq.end(), pref[0]) - uniq.begin() + 1;
    add(idx0, 1);
    for (int i = 1; i <= n; ++i) {
        int idx = std::lower_bound(uniq.begin(), uniq.end(), pref[i]) - uniq.begin() + 1;
        ans += sum(idx - 1);
        add(idx, 1);
    }
    return ans;
}

#include <bits/stdc++.h>
long long minTime(std::vector<long long>& d, std::vector<long long>& r) {
    long long d1 = d[0], d2 = d[1], r1 = r[0], r2 = r[1];
    long long lcm = r1 / std::__gcd(r1, r2) * r2;
    auto feasible = [&](long long T) {
        long long a1 = T - T/r1;
        long long a2 = T - T/r2;
        long long atotal = T - T/lcm;
        return a1 >= d1 && a2 >= d2 && atotal >= d1 + d2;
    };
    long long lo = 1, hi = 4000000000LL;
    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2;
        if (feasible(mid)) hi = mid; else lo = mid + 1;
    }
    return lo;
}

