static const long long NEG = LLONG_MIN / 4;
long long linearBest(const std::vector<int>& a, int k) {
    std::vector<std::array<long long,3>> f(k + 1, {NEG, NEG, NEG});
    f[0][1] = 0;
    for (int x : a) {
        auto g = f;
        for (int c = 0; c <= k; c++) for (int bi = 0; bi < 3; bi++) {
            long long cur = f[c][bi];
            if (cur == NEG) continue;
            int b = bi - 1;
            for (int sign : {1, -1}) {
                int nb = b + sign;
                if (nb < -1 || nb > 1) continue;
                int nc = c + (nb == 0 ? 1 : 0);
                if (nc > k) continue;
                long long val = cur + (long long)sign * x;
                if (val > g[nc][nb + 1]) g[nc][nb + 1] = val;
            }
        }
        f = g;
    }
    long long best = NEG;
    for (int c = 0; c <= k; c++) best = std::max(best, f[c][1]);
    return best;
}
long long maxCyclicPartitionScore(std::vector<int>& nums, int k) {
    int n = nums.size();
    long long ans = NEG;
    for (int r = 0; r < n; r++) {
        std::vector<int> a;
        for (int i = 0; i < n; i++) a.push_back(nums[(r + i) % n]);
        ans = std::max(ans, linearBest(a, k));
    }
    return ans;
}

