int longestNonDecreasingAfterOneReplace(const std::vector<int>& arr) {
    std::size_t n = arr.size();
    if (n == 0) return 0;
    if (n <= 2) return static_cast<int>(n);

    std::vector<int> left(n);
    left[0] = 1;
    for (std::size_t i = 1; i < n; ++i) {
        left[i] = (arr[i] >= arr[i - 1]) ? left[i - 1] + 1 : 1;
    }

    std::vector<int> right(n);
    right[n - 1] = 1;
    for (int i = static_cast<int>(n) - 2; i >= 0; --i) {
        right[i] = (arr[i] <= arr[i + 1]) ? right[i + 1] + 1 : 1;
    }

    int best = 1;
    for (std::size_t i = 0; i < n; ++i) {
        best = std::max(best, left[i]);
    }

    for (std::size_t i = 0; i < n; ++i) {
        if (i > 0) best = std::max(best, left[i - 1] + 1);
        if (i + 1 < n) best = std::max(best, right[i + 1] + 1);
        if (i > 0 && i + 1 < n && arr[i - 1] <= arr[i + 1]) {
            best = std::max(best, left[i - 1] + 1 + right[i + 1]);
        }
    }

    return std::min(best, static_cast<int>(n));
}

