std::vector<int> smallestNegatedPermutation(int n, int target) {
    long long total = 1LL * n * (n + 1) / 2;
    long long diff = total - static_cast<long long>(target);
    if (diff < 0 || (diff & 1LL)) {
        return {};
    }
    long long sumNeg = diff / 2;
    std::vector<char> isNeg(n + 1, 0);
    for (int i = n; i >= 1; --i) {
        if (sumNeg >= i) {
            isNeg[i] = 1;
            sumNeg -= i;
        }
    }
    if (sumNeg != 0) {
        return {};
    }
    std::vector<int> ans;
    ans.reserve(n);
    for (int i = n; i >= 1; --i) {
        if (isNeg[i]) {
            ans.push_back(-i);
        }
    }
    for (int i = 1; i <= n; ++i) {
        if (!isNeg[i]) {
            ans.push_back(i);
        }
    }
    return ans;
}

