const long long MOD = 1000000007LL;

int numberOfEffectiveSubsequences(vector<int>& nums) {
    int n = nums.size();
    int maxVal = 0;
    for (int v : nums) maxVal = max(maxVal, v);
    int B = 1;
    while ((1 << B) <= maxVal) B++;
    int size = 1 << B;
    int fullmask = size - 1;

    vector<long long> subsetSum(size, 0);
    for (int v : nums) subsetSum[v]++;
    for (int bit = 0; bit < B; bit++) {
        for (int mask = 0; mask < size; mask++) {
            if (mask & (1 << bit)) {
                subsetSum[mask] += subsetSum[mask ^ (1 << bit)];
            }
        }
    }

    int activeBits = 0;
    for (int v : nums) activeBits |= v;

    vector<long long> pow2(n + 1);
    pow2[0] = 1;
    for (int i = 1; i <= n; i++) pow2[i] = (pow2[i-1] * 2) % MOD;

    long long answer = 0;
    int submask = activeBits;
    while (submask > 0) {
        int bitsSet = __builtin_popcount(submask);
        long long elementsWithNone = subsetSum[fullmask ^ submask];
        long long forced = n - elementsWithNone;
        long long ways = pow2[n - forced];
        if (bitsSet % 2 == 1) {
            answer = (answer + ways) % MOD;
        } else {
            answer = (answer - ways + MOD) % MOD;
        }
        submask = (submask - 1) & activeBits;
    }
    return (int)(answer % MOD);
}

