std::vector<long long> sumAndMultiply(std::string s, std::vector<std::vector<int>>& queries) {
    long long MOD = 1000000007LL;
    int n = s.size();
    std::vector<long long> presum(n+1,0), conval(n+1,0), pow10(n+1,0);
    std::vector<int> cnt(n+1,0);
    pow10[0]=1;
    for (int i=1;i<=n;i++){
        int d = s[i-1]-'0';
        presum[i] = presum[i-1]+d;
        if (d==0){ conval[i]=conval[i-1]; cnt[i]=cnt[i-1]; }
        else { conval[i] = (conval[i-1]*10+d)%MOD; cnt[i]=cnt[i-1]+1; }
        pow10[i] = (pow10[i-1]*10)%MOD;
    }
    std::vector<long long> ans;
    for (auto& q : queries) {
        int l=q[0], r=q[1];
        long long sum = presum[r+1]-presum[l];
        int k = cnt[r+1]-cnt[l];
        long long removed = (conval[l]*pow10[k])%MOD;
        long long x = ((conval[r+1]-removed)%MOD+MOD)%MOD;
