bool isBinaryPalindrome(long long x) {
    string b;
    long long t = x;
    while (t > 0) { b += char('0' + (t & 1)); t >>= 1; }
    reverse(b.begin(), b.end());
    string r = b;
    reverse(r.begin(), r.end());
    return b == r;
}

vector<long long> minOperationsToMakeBinaryPalindrome(const vector<long long>& nums) {
    vector<long long> result;
    for (long long n : nums) {
        long long d = 0;
        while (true) {
            if (n - d >= 1 && isBinaryPalindrome(n - d)) { result.push_back(d); break; }
            if (isBinaryPalindrome(n + d)) { result.push_back(d); break; }
            d++;
        }
    }
    return result;
}

