vector<long long> minimumOperations(vector<int>& nums, int k, vector<vector<int>>& queries) {
    vector<long long> results;
    for (auto& q : queries) {
        int l = q[0], r = q[1];
        vector<int> sub(nums.begin() + l, nums.begin() + r + 1);
        int rem = sub[0] % k;
        bool feasible = true;
        for (int v : sub) if (v % k != rem) { feasible = false; break; }
        if (!feasible) { results.push_back(-1); continue; }
        vector<int> sorted_sub = sub;
        sort(sorted_sub.begin(), sorted_sub.end());
        int target = sorted_sub[sorted_sub.size() / 2];
        long long ops = 0;
        for (int v : sub) ops += abs(v - target);
        results.push_back(ops / k);
    }
    return results;
}

