long long minInversionCount(const std::vector<int>& arr, int k) {
    int n = static_cast<int>(arr.size());
    if (k > n || k <= 0) return 0;
    std::vector<int> sorted = arr;
    std::sort(sorted.begin(), sorted.end());
    sorted.erase(std::unique(sorted.begin(), sorted.end()), sorted.end());
    int m = static_cast<int>(sorted.size());
    std::vector<int> bit(m + 1, 0);
    auto add = [&](int idx, int delta) {
        for (; idx <= m; idx += idx & -idx) bit[idx] += delta;
    };
    auto sum = [&](int idx) {
        int res = 0;
        for (; idx > 0; idx -= idx & -idx) res += bit[idx];
        return res;
    };
    auto getIdx = [&](int val) {
        return int(std::lower_bound(sorted.begin(), sorted.end(), val) - sorted.begin()) + 1;
    };
    long long inv = 0;
    for (int i = 0; i < k; ++i) {
        int idx = getIdx(arr[i]);
        inv += i - sum(idx);
        add(idx, 1);
    }
    long long best = inv;
    for (int left = 0, right = k; right < n; ++left, ++right) {
        int outIdx = getIdx(arr[left]);
        int less = sum(outIdx - 1);
        inv -= less;
        add(outIdx, -1);
        int inIdx = getIdx(arr[right]);
        int greater = (k - 1) - sum(inIdx);
        inv += greater;
        add(inIdx, 1);
        if (inv < best) best = inv;
    }
    return best;
}

