std::vector<int> sortByBinaryReflection(const std::vector<int>& arr) {
    std::vector<std::pair<int, std::uint32_t>> v;
    v.reserve(arr.size());
    for (int num : arr) {
        std::uint32_t reflected = 0;
        std::uint32_t temp = static_cast<std::uint32_t>(num);
        while (temp > 0) {
            reflected = (reflected << 1) | (temp & 1u);
            temp >>= 1;
        }
        v.emplace_back(num, reflected);
    }
    std::sort(v.begin(), v.end(),
        [](const std::pair<int, std::uint32_t>& a,
           const std::pair<int, std::uint32_t>& b) {
            if (a.second != b.second) return a.second < b.second;
            return a.first < b.first;
        });
    std::vector<int> res;
    res.reserve(v.size());
    for (const auto& p : v) {
        res.push_back(p.first);
    }
    return res;
}

