long long maxScore(const vector<int>& technique1, const vector<int>& technique2, int k) {
    int n = (int)technique1.size();
    long long total = 0;
    int natural = 0;
    vector<int> losses;
    for (int i = 0; i < n; i++) {
        int a = technique1[i], b = technique2[i];
        total += max(a, b);
        if (a >= b) natural++;
        else losses.push_back(b - a);
    }
    int need = max(0, k - natural);
    sort(losses.begin(), losses.end());
    for (int i = 0; i < need && i < (int)losses.size(); i++) total -= losses[i];
    return total;
}

class Solution {
public:
    int largestPrime(int n) {
        if (n < 2) return 0;
        vector<bool> isPrime(n + 1, true);
        isPrime[0] = isPrime[1] = false;
        for (int i = 2; (long long) i * i <= n; i++) {
            if (isPrime[i]) {
                for (int j = i * i; j <= n; j += i) isPrime[j] = false;
            }
        }
        int best = 0;
        long long total = 0;
        for (int p = 2; p <= n; p++) {
            if (isPrime[p]) {
                total += p;
                if (total > n) break;
                if (total <= n && isPrime[total]) best = (int) total;
            }
        }
        return best;
    }
};

