long long absDifference(const std::vector<int>& nums, int k) {
    if (k <= 0) return 0;
    std::vector<int> a = nums;
    std::sort(a.begin(), a.end());
    long long sumSmall = 0;
    long long sumLarge = 0;
    for (int i = 0; i < k && i < static_cast<int>(a.size()); ++i) {
        sumSmall += a[i];
        sumLarge += a[a.size() - 1 - i];
    }
    long long diff = sumLarge - sumSmall;
