}

class Solution {
public:
    long long minMoves(vector<int>& balance) {
        int n = balance.size();
        long long total = 0;
        for (auto b : balance) total += b;
        if (total < 0) return -1;
        long long mn = balance[0];
        int idx = 0;
        for (int i = 1; i < n; i++) {
            if (balance[i] < mn) { mn = balance[i]; idx = i; }
        }
        if (mn >= 0) return 0;
        long long need = -mn;
        long long ans = 0;
        for (int j = 1; j < n; j++) {
            long long a = balance[((idx - j) % n + n) % n];
            long long b = balance[(idx + j) % n];
            long long c1 = min(a, need);
            need -= c1;
            ans += c1 * j;
            if (need == 0) break;
            long long c2 = min(b, need);
            need -= c2;
            ans += c2 * j;
            if (need == 0) break;
        }
        return ans;
    }
};

