vector<int> minDeletionsToMakeAlternatingSubstring(string s, vector<vector<int>>& queries) {
    int n = (int)s.size();
    vector<int> bit(n + 2, 0);
    auto add = [&](int i, int delta) { for (; i <= n; i += i & -i) bit[i] += delta; };
    auto sum = [&](int i) { int r = 0; for (; i > 0; i -= i & -i) r += bit[i]; return r; };
    auto rangeSum = [&](int l, int r) { return l > r ? 0 : sum(r) - sum(l - 1); };

    for (int i = 1; i < n; i++) {
        if (s[i] == s[i - 1]) add(i + 1, 1);
    }

    vector<int> answers;
    for (auto& q : queries) {
        if (q[0] == 1) {
            int j = q[1];
            char newChar = (s[j] == 'A') ? 'B' : 'A';
            if (j > 0) {
                int oldEq = (s[j] == s[j-1]) ? 1 : 0;
                int newEq = (newChar == s[j-1]) ? 1 : 0;
                if (oldEq != newEq) add(j + 1, newEq - oldEq);
            }
            if (j + 1 < n) {
                int oldEq = (s[j+1] == s[j]) ? 1 : 0;
                int newEq = (s[j+1] == newChar) ? 1 : 0;
                if (oldEq != newEq) add(j + 2, newEq - oldEq);
            }
            s[j] = newChar;
        } else {
            int l = q[1], r = q[2];
            if (l >= r) answers.push_back(0);
            else answers.push_back(rangeSum(l + 2, r + 1));
        }
    }
    return answers;
}

