long long mirrorDistance(long long n) {
    unsigned long long original;
    if (n < 0) {
        original = static_cast<unsigned long long>(-(n + 1)) + 1ULL;
    } else {
        original = static_cast<unsigned long long>(n);
    }
    unsigned long long rev = 0;
    unsigned long long temp = original;
    while (temp) {
        rev = rev * 10 + (temp % 10);
        temp /= 10;
    }
    unsigned long long diff = original > rev ? original - rev : rev - original;
    return static_cast<long long>(diff);
}

