int minimumSwaps(const std::vector<int>& arr, const std::vector<int>& forbidden) {
    std::size_t n = arr.size();
    std::unordered_map<int, int> cntArr, cntForbidden;
    for (std::size_t i = 0; i < n; ++i) {
        ++cntArr[arr[i]];
        ++cntForbidden[forbidden[i]];
    }
    for (const auto& p : cntArr) {
        int value = p.first;
        int have = p.second;
        int forbid = cntForbidden.count(value) ? cntForbidden[value] : 0;
        if (have > static_cast<int>(n) - forbid) {
            return -1;
        }
    }
    std::size_t bad = 0;
    for (std::size_t i = 0; i < n; ++i) {
        if (arr[i] == forbidden[i]) ++bad;
    }
    return static_cast<int>((bad + 1) / 2);
}

