int maxSumDivisibleByThree(const std::vector<int>& nums) {
    std::array<std::vector<int>, 3> top;
    for (int v : nums) {
        int r = ((v % 3) + 3) % 3;
        auto& vec = top[r];
        if (vec.size() < 3) {
            vec.push_back(v);
            std::sort(vec.begin(), vec.end(), std::greater<int>());
        } else if (v > vec.back()) {
            vec.back() = v;
            std::sort(vec.begin(), vec.end(), std::greater<int>());
        }
    }

    int best = 0;
    bool found = false;

    if (top[0].size() >= 3) {
        best = top[0][0] + top[0][1] + top[0][2];
        found = true;
    }
    if (top[1].size() >= 3) {
        int cand = top[1][0] + top[1][1] + top[1][2];
        if (!found || cand > best) { best = cand; found = true; }
    }
    if (top[2].size() >= 3) {
        int cand = top[2][0] + top[2][1] + top[2][2];
        if (!found || cand > best) { best = cand; found = true; }
    }
    if (!top[0].empty() && !top[1].empty() && !top[2].empty()) {
        int cand = top[0][0] + top[1][0] + top[2][0];
        if (!found || cand > best) { best = cand; found = true; }
    }
    return found ? best : 0;
}

