const long long MOD = 1000000007;

long long countUpTo(long long n) {
    if (n < 11) return 0;
    string s = to_string(n);
    int len = s.size();
    map<tuple<int,int,bool,bool>, long long> memo;
    function<long long(int,int,bool,bool,bool)> dfs = [&](int pos, int diff, bool tight, bool started, bool parityOdd) -> long long {
        if (pos == len) return (started && diff == 0) ? 1 : 0;
        auto key = make_tuple(pos, diff, started, parityOdd);
        if (!tight && memo.count(key)) return memo[key];
        int limit = tight ? (s[pos]-'0') : 9;
        long long res = 0;
        for (int d = 0; d <= limit; d++) {
            if (!started && d == 0) {
                res += dfs(pos+1, diff, tight && d==limit, false, true);
            } else {
                int delta = parityOdd ? -d : d;
                res += dfs(pos+1, diff+delta, tight && d==limit, true, !parityOdd);
            }
        }
        if (!tight) memo[key] = res;
        return res;
    };
