long long numberOfRoutes(vector<string>& grid, int d) {
    const long long MOD = 1000000007;
    int n = grid.size(), m = grid[0].size();
    long long wUpSq = (long long)d * d - 1;
    long long wUp = (wUpSq >= 0) ? (long long)sqrtl((long double)wUpSq) : -1;
    while (wUp >= 0 && wUp * wUp > wUpSq) wUp--;
    while (wUp >= 0 && (wUp + 1) * (wUp + 1) <= wUpSq) wUp++;
    long long wStay = d;

    vector<long long> dpUp(m, 0), dpStay(m, 0);
    for (int c = 0; c < m; c++) if (grid[n-1][c] == '.') dpUp[c] = 1;

    for (int r = n - 1; r > 0; r--) {
        vector<long long> preUp(m + 1, 0);
        for (int c = 0; c < m; c++) preUp[c+1] = (preUp[c] + dpUp[c]) % MOD;
        vector<long long> newStay(m, 0);
        for (int c = 0; c < m; c++) {
            if (grid[r][c] != '.') continue;
            int lo = max(0, (int)(c - wStay)), hi = min(m - 1, (int)(c + wStay));
            long long total = (preUp[hi+1] - preUp[lo] + MOD) % MOD;
            total = (total - dpUp[c] + MOD) % MOD;
            newStay[c] = total;
        }
        dpStay = newStay;

        vector<long long> combined(m);
        for (int c = 0; c < m; c++) combined[c] = (dpUp[c] + dpStay[c]) % MOD;
        vector<long long> preComb(m + 1, 0);
        for (int c = 0; c < m; c++) preComb[c+1] = (preComb[c] + combined[c]) % MOD;

        vector<long long> newUp(m, 0);
        for (int c = 0; c < m; c++) {
            if (grid[r-1][c] != '.' || wUp < 0) continue;
            int lo = max(0, (int)(c - wUp)), hi = min(m - 1, (int)(c + wUp));
            newUp[c] = (preComb[hi+1] - preComb[lo] + MOD) % MOD;
        }
        dpUp = newUp;
        dpStay.assign(m, 0);
    }

    vector<long long> preUp0(m + 1, 0);
    for (int c = 0; c < m; c++) preUp0[c+1] = (preUp0[c] + dpUp[c]) % MOD;
    vector<long long> dpStay0(m, 0);
    for (int c = 0; c < m; c++) {
        if (grid[0][c] != '.') continue;
        int lo = max(0, (int)(c - wStay)), hi = min(m - 1, (int)(c + wStay));
        long long total = (preUp0[hi+1] - preUp0[lo] + MOD) % MOD;
        dpStay0[c] = (total - dpUp[c] + MOD) % MOD;
    }

    long long ans = 0;
    for (int c = 0; c < m; c++) ans = (ans + dpUp[c] + dpStay0[c]) % MOD;
    return ans;
}

