int minSubarrayLength(const std::vector<int>& arr, long long K) {
    int left = 0;
    long long distinctSum = 0;
    std::unordered_map<int, int> freq;
    freq.reserve(arr.size() * 2);
    int best = std::numeric_limits<int>::max();

    for (int right = 0; right < static_cast<int>(arr.size()); ++right) {
        int val = arr[right];
        int& cnt = freq[val];
        if (cnt == 0) distinctSum += val;
        ++cnt;

        while (distinctSum >= K) {
            best = std::min(best, right - left + 1);
            int leftVal = arr[left];
            int& leftCnt = freq[leftVal];
            if (leftCnt == 1) {
                distinctSum -= leftVal;
                freq.erase(leftVal);
            } else {
                --leftCnt;
            }
            ++left;
        }
    }

    return best == std::numeric_limits<int>::max() ? -1 : best;
}

