long long maxValueOfSequence(int n, std::vector<std::vector<int>>& restrictions, std::vector<int>& diff) {
    const long long INF = LLONG_MAX/2;
    std::vector<long long> a(n, INF);
    a[0] = 0;
    for (auto& r : restrictions) a[r[0]] = std::min(a[r[0]], (long long)r[1]);
    for (int i = 1; i < n; i++) a[i] = std::min(a[i], a[i-1] + diff[i-1]);
    for (int i = n-2; i >= 0; i--) a[i] = std::min(a[i], a[i+1] + diff[i]);
    return *std::max_element(a.begin(), a.end());
}

class Solution {
public:
    int minCost(vector<vector<int>>& lists) {
        int n = lists.size();
        int full = 1 << n;
        vector<vector<int>> sortedArr(full);
        sortedArr[0] = {};
        for (int mask = 1; mask < full; mask++) {
            int low = mask & (-mask);
            int idx = __builtin_ctz(low);
            auto& a = sortedArr[mask ^ low];
            auto& b = lists[idx];
            vector<int> merged;
            merge(a.begin(), a.end(), b.begin(), b.end(), back_inserter(merged));
            sortedArr[mask] = merged;
        }
        long long INF = LLONG_MAX / 2;
        vector<long long> dp(full, 0);
        for (int mask = 1; mask < full; mask++) {
            if ((mask & (mask - 1)) == 0) { dp[mask] = 0; continue; }
            long long best = INF;
            for (int sub = (mask - 1) & mask; sub > 0; sub = (sub - 1) & mask) {
                int comp = mask ^ sub;
                if (comp == 0) continue;
                auto& A = sortedArr[sub]; auto& B = sortedArr[comp];
                int medA = A[(A.size() - 1) / 2];
                int medB = B[(B.size() - 1) / 2];
                long long cost = dp[sub] + dp[comp] + (long long)A.size() + B.size() + abs(medA - medB);
                if (cost < best) best = cost;
            }
            dp[mask] = best;
        }
        return dp[full - 1];
    }
};

