long long minimumCost(std::string s, std::string t, long long flipCost, long long swapCost, long long crossCost) {
    long long diff0 = 0, diff1 = 0;
    for (size_t i = 0; i < s.size(); i++) {
        if (s[i] != t[i]) { if (s[i] == '0') diff0++; else diff1++; }
    }
    long long mx = std::max(diff0, diff1), mn = std::min(diff0, diff1);
    long long ans = (diff0 + diff1) * flipCost;
    ans = std::min(ans, mn * swapCost + (mx - mn) * flipCost);
    long long avg = (mx + mn) / 2;
    ans = std::min(ans, (avg - mn) * crossCost + avg * swapCost + (mx + mn - avg * 2) * flipCost);
    return ans;
}

