long long countCaesarCipherPairs(const std::vector<std::string>& words) {
    std::unordered_map<std::string, int> freq;
    freq.reserve(words.size() * 2);
    long long totalPairs = 0;

    for (const std::string& w : words) {
        size_t n = w.size();
        unsigned char base = static_cast<unsigned char>(w[0]);
        std::string key;
        key.resize(4 + n);
        uint32_t len = static_cast<uint32_t>(n);
        key[0] = static_cast<char>(len & 0xFF);
        key[1] = static_cast<char>((len >> 8) & 0xFF);
        key[2] = static_cast<char>((len >> 16) & 0xFF);
        key[3] = static_cast<char>((len >> 24) & 0xFF);
        for (size_t i = 0; i < n; ++i) {
            unsigned char cur = static_cast<unsigned char>(w[i]);
            unsigned char diff = (cur + 26 - base) % 26;
            key[4 + i] = static_cast<char>(diff);
        }
        auto it = freq.find(key);
        if (it != freq.end()) {
            totalPairs += it->second;
            ++(it->second);
        } else {
            freq.emplace(std::move(key), 1);
        }
    }
    return totalPairs;
}

