vector<int>& rotateNonNegative(vector<int>& nums, int k) {
    vector<int> idxs, vals;
    for (int i = 0; i < (int)nums.size(); i++) {
        if (nums[i] >= 0) { idxs.push_back(i); vals.push_back(nums[i]); }
    }
    int m = (int)vals.size();
    if (m == 0) return nums;
    int shift = ((k % m) + m) % m;
    vector<int> rotated;
    rotated.insert(rotated.end(), vals.begin()+shift, vals.end());
    rotated.insert(rotated.end(), vals.begin(), vals.begin()+shift);
    for (int i = 0; i < (int)idxs.size(); i++) nums[idxs[i]] = rotated[i];
    return nums;
}

