    std::string stk;
    for (char c : s) {
        while (!stk.empty() && stk.back() > c && cnt[stk.back() - 'a'] > 1) {
            --cnt[stk.back() - 'a'];
            stk.pop_back();
        }
        stk.push_back(c);
