class Solution {
public:
    vector<long long> prefix_, dpPrev, dpCur;

    long long cost(int p, int i) {
        long long s = prefix_[i] - prefix_[p];
        return s*(s+1)/2;
    }

    void compute(int lo, int hi, int optlo, int opthi) {
        if (lo > hi) return;
        int mid = (lo+hi)/2;
        long long bestVal = LLONG_MAX;
        int bestP = -1;
        int pHi = min(opthi, mid-1);
        for (int p = optlo; p <= pHi; p++) {
            if (dpPrev[p] == LLONG_MAX) continue;
            long long val = dpPrev[p] + cost(p, mid);
            if (val < bestVal) { bestVal = val; bestP = p; }
        }
        dpCur[mid] = bestVal;
        if (bestP == -1) bestP = optlo;
        compute(lo, mid-1, optlo, bestP);
        compute(mid+1, hi, bestP, opthi);
    }

    long long minimumScore(vector<int>& nums, int k) {
        int n = nums.size();
        prefix_.assign(n+1, 0);
        for (int i = 0; i < n; i++) prefix_[i+1] = prefix_[i] + nums[i];
        dpPrev.assign(n+1, LLONG_MAX);
        dpPrev[0] = 0;
        for (int j = 1; j <= k; j++) {
            dpCur.assign(n+1, LLONG_MAX);
            compute(j, n, j-1, n-1);
            dpPrev = dpCur;
        }
        return dpPrev[n];
    }
};

