static unsigned long long binom(int n, int k) {
    if (k < 0 || k > n || n < 0) return 0;
    static unsigned long long C[70][70];
    static bool initialized = false;
    if (!initialized) {
        for (int i = 0; i < 70; ++i) {
            C[i][0] = 1ULL;
            for (int j = 1; j <= i; ++j) {
                C[i][j] = C[i-1][j-1] + (j <= i-1 ? C[i-1][j] : 0ULL);
            }
        }
        initialized = true;
    }
    return C[n][k];
}

long long nthSmallestWithKOnes(long long n, int k) {
    if (k == 0) return (n == 1) ? 0 : -1;
    int pos = k - 1;
    while (static_cast<long long>(binom(pos + 1, k)) < n) ++pos;
    long long remaining = n - 1;
    int bitsLeft = k;
    long long result = 0;
    for (int p = pos; p >= 0; --p) {
        if (bitsLeft == 0) break;
        long long count = (p >= bitsLeft) ? static_cast<long long>(binom(p, bitsLeft)) : 0;
        if (remaining >= count) {
            result |= (1LL << p);
            remaining -= count;
            --bitsLeft;
        }
    }
    return result;
}

