std::string reverseLettersThenSpecials(const std::string& s) {
    std::string chars = s;
    auto isLetter = [](unsigned char c) { return std::isalpha(c); };
    int left = 0;
    int right = static_cast<int>(chars.size()) - 1;
    while (left < right) {
        while (left < right && !isLetter(static_cast<unsigned char>(chars[left]))) ++left;
        while (left < right && !isLetter(static_cast<unsigned char>(chars[right]))) --right;
        if (left < right) {
            std::swap(chars[left], chars[right]);
            ++left;
            --right;
        }
    }
    left = 0;
    right = static_cast<int>(chars.size()) - 1;
    while (left < right) {
        while (left < right && isLetter(static_cast<unsigned char>(chars[left]))) ++left;
        while (left < right && isLetter(static_cast<unsigned char>(chars[right]))) --right;
        if (left < right) {
            std::swap(chars[left], chars[right]);
            ++left;
            --right;
        }
    }
    return chars;
}

