long long minK(const std::vector<int>& nums, long long limit) {
    long long total = 0;
    long long maxVal = 0;
    for (int v : nums) {
        total += v;
        if (v > maxVal) maxVal = v;
    }
    if (total <= limit) return 0;
    long long low = 0, high = maxVal;
    while (low < high) {
        long long mid = (low + high) / 2;
        long long reducedSum = 0;
        for (int v : nums) {
            if (v > mid) reducedSum += v - mid;
        }
        if (reducedSum <= limit) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

