class RideSharingSystem {
public:
    deque<int> riders;
    deque<int> drivers;
    unordered_set<int> cancelled;

    void addRider(int riderId) { riders.push_back(riderId); }
    void addDriver(int driverId) { drivers.push_back(driverId); }
    vector<int> matchDriverWithRider() {
        while (!riders.empty() && cancelled.count(riders.front())) {
            cancelled.erase(riders.front());
            riders.pop_front();
        }
        if (riders.empty() || drivers.empty()) return {-1, -1};
        int riderId = riders.front(); riders.pop_front();
        int driverId = drivers.front(); drivers.pop_front();
        return {driverId, riderId};
    }
    void cancelRider(int riderId) {
        if (find(riders.begin(), riders.end(), riderId) != riders.end()) {
            cancelled.insert(riderId);
        }
    }
};

long long maxScore(vector<int>& nums1, vector<int>& nums2, int K) {
    int n = nums1.size(), m = nums2.size();
    const long long NEG = LLONG_MIN/4;
    vector<vector<long long>> dp(m+1, vector<long long>(K+1, NEG));
    for (int j = 0; j <= m; j++) dp[j][0] = 0;
    for (int i = 1; i <= n; i++) {
        vector<vector<long long>> ndp(m+1, vector<long long>(K+1, NEG));
        ndp[0][0] = 0;
        for (int j = 1; j <= m; j++) {
            for (int t = 0; t <= K; t++) {
                long long best = max(ndp[j-1][t], dp[j][t]);
                if (t >= 1 && dp[j-1][t-1] > NEG) {
                    best = max(best, dp[j-1][t-1] + (long long)nums1[i-1]*nums2[j-1]);
                }
                ndp[j][t] = best;
            }
        }
        dp = ndp;
    }
    return dp[m][K];
}

