int longestAlmostPalindromicSubstring(const std::string& s) {
    int n = static_cast<int>(s.size());
    if (n == 0) return 0;
    std::vector<std::vector<std::uint8_t>> del(n, std::vector<std::uint8_t>(n, 2));
    int best = 1;
    for (int i = 0; i < n; ++i) del[i][i] = 0;
    for (int len = 2; len <= n; ++len) {
        for (int i = 0; i + len - 1 < n; ++i) {
            int j = i + len - 1;
            if (s[i] == s[j]) {
                del[i][j] = (len == 2 ? 0 : del[i + 1][j - 1]);
            } else {
                std::uint8_t a = del[i + 1][j];
                std::uint8_t b = del[i][j - 1];
                del[i][j] = static_cast<std::uint8_t>(1 + std::min(a, b));
                if (del[i][j] > 2) del[i][j] = 2;
            }
            if (del[i][j] <= 1) best = std::max(best, len);
        }
    }
    return best;
}

