std::vector<bool> solve(int n, std::vector<std::vector<int>>& edges, std::string s, std::vector<std::string>& queries) {
    int LOG = std::max(1, (int)std::ceil(std::log2(n+1)));
    std::vector<std::vector<int>> adj(n);
    for (auto& e: edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
    std::vector<int> charBit(n);
    for (int i=0;i<n;i++) charBit[i] = 1 << (s[i]-'a');
    std::vector<std::vector<int>> up(n, std::vector<int>(LOG,0));
    std::vector<int> depth(n,0), tin(n,0), tout(n,0), initMask(n,0);
    int timer=0;
    std::vector<std::array<int,3>> stk; stk.push_back({0,-1,0});
    while(!stk.empty()){
        auto [node,parent,state] = stk.back(); stk.pop_back();
        if (state==0) {
            tin[node]=timer++;
            up[node][0] = parent!=-1?parent:node;
            for (int k=1;k<LOG;k++) up[node][k]=up[up[node][k-1]][k-1];
            depth[node] = parent==-1?0:depth[parent]+1;
            initMask[node] = (parent!=-1?initMask[parent]:0) ^ charBit[node];
            stk.push_back({node,parent,1});
            for (int nb: adj[node]) if (nb!=parent) stk.push_back({nb,node,0});
        } else {
            tout[node]=timer-1;
        }
    }
    auto lca = [&](int u,int v){
        if (depth[u]<depth[v]) std::swap(u,v);
        int diff=depth[u]-depth[v], b=0;
        while(diff){ if(diff&1) u=up[u][b]; diff>>=1; b++; }
        if (u==v) return u;
        for (int k=LOG-1;k>=0;k--) if (up[u][k]!=up[v][k]) { u=up[u][k]; v=up[v][k]; }
        return up[u][0];
    };
    std::vector<int> bit(n+1,0);
    auto bitUpdate = [&](int idx,int val){ int i=idx+1; while(i<=n){ bit[i]^=val; i+= i&(-i);} };
    auto bitPrefix = [&](int idx){ int res=0,i=idx+1; while(i>0){ res^=bit[i]; i-= i&(-i);} return res; };
    std::vector<bool> answers;
    for (auto& q: queries) {
        std::stringstream ss(q); std::string cmd; ss>>cmd;
        if (cmd=="update") {
            int node; std::string c; ss>>node>>c;
            int newBit = 1<<(c[0]-'a');
            int oldBit = charBit[node];
            if (newBit!=oldBit) {
                int delta = oldBit^newBit;
                bitUpdate(tin[node], delta);
                if (tout[node]+1<n) bitUpdate(tout[node]+1, delta);
                charBit[node]=newBit;
            }
        } else {
            int u,v; ss>>u>>v;
            int w = lca(u,v);
            int maskU = initMask[u]^bitPrefix(tin[u]);
            int maskV = initMask[v]^bitPrefix(tin[v]);
            int curW = charBit[w];
            int pathMask = maskU^maskV^curW;
            answers.push_back((pathMask&(pathMask-1))==0);
        }
    }
    return answers;
}

