int maxSubarrayXorBounded(vector<int>& nums, int k) {
    int n = nums.size();
    vector<int> prefix(n+1,0);
    for (int i=0;i<n;i++) prefix[i+1]=prefix[i]^nums[i];
    int maxPref=0; for(int p: prefix) maxPref=max(maxPref,p);
    int maxbit = max(1, maxPref==0?1:(int)floor(log2(maxPref))+1);
    vector<array<int,3>> trie; trie.push_back({-1,-1,0});
    auto insert = [&](int val,int delta){
        int node=0; trie[node][2]+=delta;
        for (int b=maxbit-1;b>=0;b--) {
            int bit=(val>>b)&1;
            if (trie[node][bit]==-1) { trie.push_back({-1,-1,0}); trie[node][bit]=trie.size()-1; }
            node=trie[node][bit];
            trie[node][2]+=delta;
        }
    };
    auto query = [&](int val){
        int node=0, res=0;
        for (int b=maxbit-1;b>=0;b--) {
            int bit=(val>>b)&1, want=1-bit;
            if (trie[node][want]!=-1 && trie[trie[node][want]][2]>0) { res |= (1<<b); node=trie[node][want]; }
            else node=trie[node][bit];
        }
        return res;
    };
    deque<int> maxdq, mindq;
    int l=0, ans=0;
    vector<bool> inserted(n+1,false);
    for (int r=0;r<n;r++) {
        while(!maxdq.empty() && nums[maxdq.back()]<=nums[r]) maxdq.pop_back();
        maxdq.push_back(r);
        while(!mindq.empty() && nums[mindq.back()]>=nums[r]) mindq.pop_back();
        mindq.push_back(r);
        while (nums[maxdq.front()]-nums[mindq.front()] > k) {
            if (inserted[l]) { insert(prefix[l],-1); inserted[l]=false; }
            if (maxdq.front()==l) maxdq.pop_front();
            if (mindq.front()==l) mindq.pop_front();
            l++;
        }
        insert(prefix[r],1); inserted[r]=true;
        ans = max(ans, query(prefix[r+1]));
    }
    return ans;
}

