long long sumKDigitNumbers(const long long& L,
                           const long long& R,
                           const long long& K) {
    const long long MOD = 1000000007LL;

    auto modPow = [&](long long base, long long exp) -> long long {
        long long res = 1 % MOD;
        base %= MOD;
        while (exp > 0) {
            if (exp & 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    };

    long long n = (R - L + 1) % MOD;
    long long sumDigits = ((L + R) % MOD) * ((R - L + 1) % MOD) % MOD;
    sumDigits = (sumDigits * ((MOD + 1) / 2)) % MOD; // divide by 2 using modular inverse of 2 (MOD is odd)

    long long pow_n = (K == 0) ? 1 : modPow(n, K - 1);
    long long pow10_K = modPow(10, K);
    long long inv9 = modPow(9, MOD - 2);
    long long geometric = ( (pow10_K - 1 + MOD) % MOD ) * inv9 % MOD;

    long long result = sumDigits;
    result = result * pow_n % MOD;
    result = result * geometric % MOD;
    return result;
}

class Solution {
public:
    int n;
    long long k;
    vector<int>* numsPtr;
    map<tuple<int,long long,long long>, long long> f;
    long long gcd_(long long a, long long b) { while (b) { long long t = a % b; a = b; b = t; } return a; }
    long long dfs(int i, long long p, long long q) {
        if (i == n) return (p == k && q == 1LL) ? 1 : 0;
        auto key = make_tuple(i, p, q);
        auto it = f.find(key);
        if (it != f.end()) return it->second;
        long long res = dfs(i + 1, p, q);
        long long x = (*numsPtr)[i];
        long long g1 = gcd_(p * x, q);
        res += dfs(i + 1, (p * x) / g1, q / g1);
        long long g2 = gcd_(p, q * x);
        res += dfs(i + 1, p / g2, (q * x) / g2);
        f[key] = res;
        return res;
    }
    long long countSequences(vector<int>& nums, long long k) {
        numsPtr = &nums;
        n = nums.size();
        this->k = k;
        f.clear();
        return dfs(0, 1LL, 1LL);
    }
};

