std::vector<long long> smallestPairWithDifferentFrequencies(const std::vector<long long>& arr) {
    if (arr.empty()) return {};
    std::unordered_map<long long, int> freq;
    for (long long v : arr) {
        ++freq[v];
    }
    long long minVal = LLONG_MAX;
    for (const auto& p : freq) {
        if (p.first < minVal) {
            minVal = p.first;
        }
    }
    int minFreq = freq[minVal];
    long long second = LLONG_MAX;
    for (const auto& p : freq) {
        if (p.second != minFreq && p.first < second) {
            second = p.first;
        }
    }
    if (second == LLONG_MAX) return { -1, -1 };
    return { minVal, second };
}

