    for (int i = 0; i < n; i++) {
        int exp = startParity == 0 ? (i % 2) : (1 - i % 2);
        if (parity[i] == exp) fixedVals.push_back(nums[i]);
        else mismVals.push_back(nums[i]);
    }
    if (mismVals.empty()) {
        if (fixedVals.empty()) return 0;
        return *max_element(fixedVals.begin(), fixedVals.end()) - *min_element(fixedVals.begin(), fixedVals.end());
    }
    long long lo, hi;
    if (!fixedVals.empty()) {
        lo = *min_element(fixedVals.begin(), fixedVals.end());
        hi = *max_element(fixedVals.begin(), fixedVals.end());
    } else {
        lo = hi = mismVals[0] - 1;
        for (auto v : mismVals) { lo = min(lo, v - 1); hi = max(hi, v - 1); }
    }
    vector<long long> allVals = fixedVals;
    for (auto v : mismVals) allVals.push_back(v - 1);
    long long loBound = 0;
    long long hiBound = *max_element(allVals.begin(), allVals.end()) - *min_element(allVals.begin(), allVals.end());

    auto feasible = [&](long long W) -> bool {
        long long baseLo = hi - W, baseHi = lo;
        if (baseLo > baseHi) return false;
        vector<pair<long long,int>> events;
        for (auto v : mismVals) {
            long long aLo = v - 1 - W, aHi = v - 1;
            long long bLo = v + 1 - W, bHi = v + 1;
            if (aHi + 1 >= bLo) {
                events.push_back({aLo, 1});
                events.push_back({bHi + 1, -1});
            } else {
                events.push_back({aLo, 1}); events.push_back({aHi + 1, -1});
                events.push_back({bLo, 1}); events.push_back({bHi + 1, -1});
            }
        }
        vector<long long> pts;
        for (auto& e : events) pts.push_back(e.first);
        pts.push_back(baseLo); pts.push_back(baseHi);
        sort(pts.begin(), pts.end());
        pts.erase(unique(pts.begin(), pts.end()), pts.end());
        sort(events.begin(), events.end());
        size_t idx = 0;
        long long cur = 0;
        long long needed = (long long)mismVals.size();
        for (auto p : pts) {
            while (idx < events.size() && events[idx].first <= p) {
                cur += events[idx].second;
                idx++;
            }
            if (p >= baseLo && p <= baseHi && cur >= needed) return true;
        }
        return false;
    };

    while (loBound < hiBound) {
        long long mid = loBound + (hiBound - loBound) / 2;
        if (feasible(mid)) hiBound = mid;
        else loBound = mid + 1;
    }
    return loBound;
}

vector<int> minOperationsParity(vector<int>& numsInt) {
    int n = numsInt.size();
    vector<long long> nums(numsInt.begin(), numsInt.end());
    vector<int> parity(n);
    for (int i = 0; i < n; i++) parity[i] = (int)(((nums[i] % 2) + 2) % 2);
    int mismA = 0, mismB = 0;
    for (int i = 0; i < n; i++) {
        int expA = i % 2, expB = 1 - i % 2;
        if (parity[i] != expA) mismA++;
        if (parity[i] != expB) mismB++;
    }
    int bestOps = min(mismA, mismB);
    vector<int> candidates;
    if (mismA == bestOps) candidates.push_back(0);
    if (mismB == bestOps) candidates.push_back(1);
    long long bestRange = LLONG_MAX;
    for (int sp : candidates) bestRange = min(bestRange, bestRangeForPattern(nums, parity, sp));
    return {bestOps, (int)bestRange};
}

