int minimumBitwiseORFromGrid(std::vector<std::vector<int>>& grid) {
    int n = static_cast<int>(grid.size());
    if (n == 0) return 0;
    int upper = 0;
    for (const auto& row : grid)
        for (int v : row)
            upper |= v;
    int ans = upper;
    for (int bit = 30; bit >= 0; --bit) {
        int candidate = ans & ~(1 << bit);
        bool feasible = true;
        for (const auto& row : grid) {
            bool row_ok = false;
            for (int v : row) {
                if ((v | candidate) == candidate) {
                    row_ok = true;
                    break;
                }
            }
            if (!row_ok) {
                feasible = false;
                break;
            }
        }
        if (feasible) ans = candidate;
    }
    return ans;
}

