vector<long long> GOOD_SORTED;
set<int> GOOD_SUMS;

void buildGoodSet() {
    set<long long> good;
    // increasing: digits 1..9
    for (int mask = 1; mask < (1<<9); mask++) {
        string s;
        for (int i = 0; i < 9; i++) if (mask & (1<<i)) s += char('1'+i);
        good.insert(stoll(s));
    }
    // decreasing: digits 0..9
    for (int mask = 1; mask < (1<<10); mask++) {
        string s;
        for (int i = 9; i >= 0; i--) if (mask & (1<<i)) s += char('0'+i);
        good.insert(stoll(s));
    }
    GOOD_SORTED.assign(good.begin(), good.end());
    sort(GOOD_SORTED.begin(), GOOD_SORTED.end());
    for (int s = 0; s < 300; s++) if (isGood(s)) GOOD_SUMS.insert(s);
}

long long countGoodUpTo(long long n) {
    if (n < 0) return 0;
    return upper_bound(GOOD_SORTED.begin(), GOOD_SORTED.end(), n) - GOOD_SORTED.begin();
}

long long countDigitSumGoodUpTo(long long n) {
    if (n < 0) return 0;
    string s = to_string(n);
    int length = s.length();
    // memo[pos][total] valid only for non-tight calls
    vector<vector<long long>> memo(length+1, vector<long long>(300, -1));
    function<long long(int,bool,int)> dp = [&](int pos, bool tight, int total) -> long long {
        if (pos == length) return GOOD_SUMS.count(total) ? 1 : 0;
        if (!tight && memo[pos][total] != -1) return memo[pos][total];
        int limit = tight ? (s[pos]-'0') : 9;
        long long res = 0;
        for (int d = 0; d <= limit; d++) {
            res += dp(pos+1, tight && d==limit, total+d);
        }
        if (!tight) memo[pos][total] = res;
        return res;
    };
    return dp(0, true, 0);
}

long long countBothUpTo(long long n) {
    if (n < 0) return 0;
    long long cnt = 0;
    for (long long x : GOOD_SORTED) {
        if (x > n) break;
        if (GOOD_SUMS.count(digitSum(x))) cnt++;
    }
    return cnt;
}

long long fancyCountUpTo(long long n) {
    if (n < 0) return 0;
    return countGoodUpTo(n) + countDigitSumGoodUpTo(n) - countBothUpTo(n);
}

long long countFancyNumbers(long long l, long long r) {
    return fancyCountUpTo(r) - fancyCountUpTo(l - 1);
}

