long long minCost(const string& s, long long encCost, long long flatCost) {
    int n = (int)s.size();
    vector<long long> pre(n+1, 0);
    for (int i = 0; i < n; i++) pre[i+1] = pre[i] + (s[i]=='1' ? 1 : 0);
    unordered_map<long long,long long> memo;
    function<long long(int,int)> dfs = [&](int x, int y) -> long long {
        long long key = (long long)x * 200000 + y;
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        long long L = y - x;
        long long X = pre[y] - pre[x];
        long long whole = (X == 0) ? flatCost : L * X * encCost;
        long long res = whole;
        if (L % 2 == 0) {
            int mid = x + (int)(L/2);
            long long split = dfs(x, mid) + dfs(mid, y);
            res = min(whole, split);
        }
        memo[key] = res;
        return res;
    };
    return dfs(0, n);
}

