int longestArithmeticOptimal(vector<int>& nums) {
    int n = nums.size();
    if (n <= 2) return n;
    vector<int> left(n,2), right(n,2);
    left[0]=1; right[n-1]=1;
    for (int i = 2; i < n; i++) if (nums[i]-nums[i-1]==nums[i-1]-nums[i-2]) left[i]=left[i-1]+1;
    for (int i = n-3; i >= 0; i--) if (nums[i+1]-nums[i]==nums[i+2]-nums[i+1]) right[i]=right[i+1]+1;
    int ans = 2;
    for (int i = 0; i < n; i++) {
        ans = max({ans, left[i], right[i]});
        if (i > 0) ans = max(ans, left[i-1]+1);
        if (i+1 < n) ans = max(ans, right[i+1]+1);
        if (i > 0 && i < n-1) {
            int diffSum = nums[i+1]-nums[i-1];
            if (diffSum % 2 == 0) {
                int diff = diffSum/2;
                int k = 3;
                if (i > 1 && diff == (nums[i-1]-nums[i-2])) k += left[i-1]-1;
                if (i < n-2 && diff == (nums[i+2]-nums[i+1])) k += right[i+1]-1;
                ans = max(ans, k);
            }
        }
    }
    return ans;
}

