    std::unordered_map<int, int> diff;
    for (int x : A) ++diff[x];
    for (int x : B) --diff[x];
    long long swaps = 0;
    for (const auto& p : diff) {
        int d = p.second;
        if (d & 1) return -1;
        if (d > 0) swaps += d / 2;
    }
    return swaps;
