class EventManager {
    std::map<int, std::string> tsToName;
    std::unordered_map<std::string, int> nameToTs;
public:
    void addEvent(const std::string& name, int timestamp) {
        if (nameToTs.count(name)) return;
        nameToTs[name] = timestamp;
        tsToName[timestamp] = name;
    }
    void deleteEvent(const std::string& name) {
        auto it = nameToTs.find(name);
        if (it == nameToTs.end()) return;
        tsToName.erase(it->second);
        nameToTs.erase(it);
    }
    std::string getNextEvent(const std::string& name) {
        auto it = nameToTs.find(name);
        if (it == nameToTs.end()) return "-1";
        auto mit = tsToName.upper_bound(it->second);
        if (mit == tsToName.end()) return "-1";
        return mit->second;
    }
    std::string getPreviousEvent(const std::string& name) {
        auto it = nameToTs.find(name);
        if (it == nameToTs.end()) return "-1";
        auto mit = tsToName.lower_bound(it->second);
        if (mit == tsToName.begin()) return "-1";
        --mit;
        return mit->second;
    }
};

class Solution {
public:
    long long sortableIntegers(vector<int>& nums) {
        int n = nums.size();
        long long total = 0;
        for (int k = 1; k <= n; k++) {
            if (n % k != 0) continue;
            int d = n / k;
            bool ok = true;
            int prevMax = INT_MIN;
            for (int b = 0; b < d && ok; b++) {
                int descents = 0;
                int curMin = INT_MAX, curMax = INT_MIN;
                for (int i = 0; i < k; i++) {
                    int idx = b*k+i;
                    curMin = min(curMin, nums[idx]);
                    curMax = max(curMax, nums[idx]);
                    int nextIdx = b*k + (i+1)%k;
                    if (nums[idx] > nums[nextIdx]) descents++;
                }
                if (descents > 1) { ok = false; break; }
                if (curMin < prevMax) { ok = false; break; }
                prevMax = curMax;
            }
            if (ok) total += k;
        }
        return total;
    }
};

