int minXorPath(const std::vector<std::vector<int>>& grid) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    std::vector<std::vector<std::unordered_set<int>>> dp(m, std::vector<std::unordered_set<int>>(n));
    dp[0][0].insert(grid[0][0]);
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i == 0 && j == 0) continue;
            int val = grid[i][j];
            if (i > 0) {
                for (int x : dp[i - 1][j]) {
                    dp[i][j].insert(x ^ val);
                }
            }
            if (j > 0) {
                for (int x : dp[i][j - 1]) {
                    dp[i][j].insert(x ^ val);
                }
            }
        }
    }
    int answer = INT_MAX;
    for (int x : dp[m - 1][n - 1]) {
        if (x < answer) answer = x;
    }
    return answer;
}

