int mirrorFrequencyDistance(const std::string& s) {
    std::array<int, 26> letterFreq{};
    std::array<int, 10> digitFreq{};
    for (char ch : s) {
        if (ch >= 'a' && ch <= 'z') {
            ++letterFreq[ch - 'a'];
        } else if (ch >= '0' && ch <= '9') {
            ++digitFreq[ch - '0'];
        }
    }
    int distance = 0;
    for (int i = 0; i < 13; ++i) {
        int diff = letterFreq[i] - letterFreq[25 - i];
        if (diff < 0) diff = -diff;
        distance += diff;
    }
    for (int i = 0; i < 5; ++i) {
        int diff = digitFreq[i] - digitFreq[9 - i];
        if (diff < 0) diff = -diff;
        distance += diff;
    }
    return distance;
}

