std::vector<long long> integersWithMultipleSumOfTwoCubes(long long n) {
    long long limit = static_cast<long long>(std::floor(std::cbrt(static_cast<double>(n))));
    struct Node {
        long long sum;
        int a;
        int b;
    };
    struct Cmp {
        bool operator()(Node const& x, Node const& y) const { return x.sum > y.sum; }
    };
    std::priority_queue<Node, std::vector<Node>, Cmp> pq;
    for (int a = 1; a <= limit; ++a) {
        long long a3 = static_cast<long long>(a) * a * a;
        long long s = a3 + a3;
        if (s > n) break;
        pq.push({s, a, a});
    }
    std::vector<long long> result;
    long long prevSum = -1;
    int dupCount = 0;
    while (!pq.empty()) {
        Node cur = pq.top();
        pq.pop();
        if (cur.sum == prevSum) {
            ++dupCount;
            if (dupCount == 2) result.push_back(cur.sum);
        } else {
            prevSum = cur.sum;
            dupCount = 1;
        }
        if (cur.b < limit) {
            int nb = cur.b + 1;
            long long nb3 = static_cast<long long>(nb) * nb * nb;
            long long a3 = static_cast<long long>(cur.a) * cur.a * cur.a;
            long long ns = a3 + nb3;
            if (ns <= n) pq.push({ns, cur.a, nb});
        }
    }
    return result;
}

