int numberOfGoodEdges(int n, vector<vector<int>>& edges) {
    vector<int> parent(n), parity(n,0);
    iota(parent.begin(), parent.end(), 0);
    function<pair<int,int>(int)> find = [&](int x) -> pair<int,int> {
        if (parent[x] == x) return {x,0};
        auto [root,p] = find(parent[x]);
        parity[x] ^= p;
        parent[x] = root;
        return {root, parity[x]};
    };
    int count = 0;
    for (auto& e : edges) {
        int u=e[0], v=e[1], w=e[2];
        auto [ru,pu] = find(u);
        auto [rv,pv] = find(v);
        if (ru != rv) {
            parent[ru] = rv;
            parity[ru] = pu ^ pv ^ w;
            count++;
        } else {
            if ((pu ^ pv) == w) count++;
        }
    }
    return count;
}

class Solution {
public:
    int n;
    vector<int> nums;
    const long long INF = 1e16;

    long long dp(int i, int need, int end, vector<vector<long long>>& memo) {
        if (need == 0) return 0;
        if (i >= end) return INF;
        if (memo[i][need] != -1) return memo[i][need];
        long long skip = dp(i + 1, need, end, memo);
        int prevV = nums[(i - 1 + n) % n];
        int nextV = nums[(i + 1) % n];
        long long cost = max((long long) max(prevV, nextV) + 1, (long long) nums[i]) - nums[i];
        long long take = cost + dp(i + 2, need - 1, end, memo);
        return memo[i][need] = min(skip, take);
    }

    long long solve(int start, int end, int k) {
        vector<vector<long long>> memo(n + 2, vector<long long>(k + 1, -1));
        return dp(start, k, end, memo);
    }

    int minOperations(vector<int>& nums_, int k) {
        nums = nums_;
        n = nums.size();
        long long ans = min(solve(0, n - 1, k), solve(1, n, k));
        return ans >= INF ? -1 : (int) ans;
    }
};

