// Sort sides ascending: a<=b<=c. No positive-area triangle if a+b<=c.
// Otherwise use law of cosines to find each angle (opposite side x):
// angle_x = acos((y^2+z^2-x^2)/(2yz)); result is already ascending since
// larger side is opposite a larger angle.
vector<double> internalAngles(vector<int>& sides) {
    vector<int> s = sides;
    sort(s.begin(), s.end());
    double a = s[0], b = s[1], c = s[2];
    if (a + b <= c) return {};
    auto angleOpp = [](double a, double b, double c) {
        double cosv = (b*b + c*c - a*a) / (2.0*b*c);
        cosv = max(-1.0, min(1.0, cosv));
        return acos(cosv) * 180.0 / M_PI;
    };
    return {angleOpp(a,b,c), angleOpp(b,a,c), angleOpp(c,a,b)};
}

