vector<vector<int>> multiSourceFloodFill(int rows, int cols, vector<vector<int>>& sources) {
    vector<vector<int>> result(rows, vector<int>(cols, 0));
    vector<vector<bool>> visited(rows, vector<bool>(cols, false));
    // min-heap by (dist, -value)
    using T = tuple<int,int,int,int>;
    priority_queue<T, vector<T>, greater<T>> pq;
    for (auto& s: sources) pq.push({0, -s[2], s[0], s[1]});
    int dr[4]={1,-1,0,0}, dc[4]={0,0,1,-1};
    while (!pq.empty()) {
        auto [dist, negV, r, c] = pq.top(); pq.pop();
        if (visited[r][c]) continue;
        visited[r][c] = true;
        result[r][c] = -negV;
        for (int i=0;i<4;i++) {
            int nr=r+dr[i], nc=c+dc[i];
            if (nr>=0&&nr<rows&&nc>=0&&nc<cols&&!visited[nr][nc]) pq.push({dist+1, negV, nr, nc});
        }
    }
    return result;
}

