long long countEvenConnectedSubgraphs(const std::vector<int>& values, const std::vector<std::pair<int, int>>& edges) {
    int n = static_cast<int>(values.size());
    std::vector<std::uint32_t> adjMask(n, 0);
    for (const auto& e : edges) {
        int u = e.first, v = e.second;
        adjMask[u] |= 1u << v;
        adjMask[v] |= 1u << u;
    }
    std::size_t total = 1u << n;
    std::vector<std::uint8_t> parity(total);
    parity[0] = 0;
    for (std::uint32_t mask = 1; mask < total; ++mask) {
        std::uint32_t lsb = mask & -mask;
        int idx = __builtin_ctz(lsb);
        parity[mask] = parity[mask ^ lsb] ^ (values[idx] & 1);
    }
    long long answer = 0;
    for (std::uint32_t mask = 1; mask < total; ++mask) {
        if (parity[mask]) continue;
        std::uint32_t startMask = mask & -mask;
        int start = __builtin_ctz(startMask);
        std::uint32_t reachable = startMask;
        std::uint32_t frontier = startMask;
        while (true) {
            std::uint32_t neigh = 0;
            std::uint32_t f = frontier;
            while (f) {
                std::uint32_t l = f & -f;
                int v = __builtin_ctz(l);
                neigh |= adjMask[v];
                f ^= l;
            }
            std::uint32_t newReach = reachable | (neigh & mask);
            if (newReach == reachable) break;
            frontier = newReach ^ reachable;
            reachable = newReach;
        }
        if (reachable == mask) ++answer;
    }
    return answer;
}

