struct Node {
    int left;
    int right;
    int cnt;
};

static std::vector<Node> seg;

static int update(int prev, int l, int r, int pos) {
    int cur = static_cast<int>(seg.size());
    seg.push_back(seg[prev]);
    seg[cur].cnt = seg[prev].cnt + 1;
    if (l != r) {
        int mid = (l + r) >> 1;
        if (pos <= mid) {
            seg[cur].left = update(seg[prev].left, l, mid, pos);
        } else {
            seg[cur].right = update(seg[prev].right, mid + 1, r, pos);
        }
    }
    return cur;
}

static int queryPrefix(int node, int l, int r, int idx) {
    if (node == 0 || idx < l) return 0;
    if (r <= idx) return seg[node].cnt;
    int mid = (l + r) >> 1;
    int leftSum = queryPrefix(seg[node].left, l, mid, idx);
    int rightSum = queryPrefix(seg[node].right, mid + 1, r, idx);
    return leftSum + rightSum;
}

std::vector<int> kthSmallestEven(const std::vector<int>& arr, const std::vector<std::vector<int>>& queries) {
    std::vector<int> result;
    result.reserve(queries.size());
    int n = static_cast<int>(arr.size());

    std::vector<int> comp;
    comp.reserve(n);
    for (int v : arr) {
        if (v % 2 == 0) comp.push_back(v);
    }
    std::sort(comp.begin(), comp.end());
    comp.erase(std::unique(comp.begin(), comp.end()), comp.end());
    int m = static_cast<int>(comp.size());

    seg.clear();
    seg.reserve(static_cast<size_t>(n) * 20);
    seg.push_back({0, 0, 0}); // null node

    std::vector<int> roots(n);
    for (int i = 0; i < n; ++i) {
        if (arr[i] % 2 == 0) {
            int idx = static_cast<int>(std::lower_bound(comp.begin(), comp.end(), arr[i]) - comp.begin());
            int prevRoot = (i == 0 ? 0 : roots[i - 1]);
            roots[i] = update(prevRoot, 0, m - 1, idx);
        } else {
            roots[i] = (i == 0 ? 0 : roots[i - 1]);
        }
    }

    for (const auto& q : queries) {
        int l = q[0];
        int r = q[1];
        int k = q[2];
        if (l < 0) l = 0;
        if (r >= n) r = n - 1;
        if (l > r || k <= 0) {
            result.push_back(-1);
            continue;
        }

        int leftRoot = (l == 0 ? 0 : roots[l - 1]);
        int rightRoot = roots[r];
        int totalEven = seg[rightRoot].cnt - seg[leftRoot].cnt;

        if (m == 0) {
            result.push_back(2 * k);
            continue;
        }

        int lo = 2;
        int hi = 2 * (k + totalEven);
        if (hi < lo) hi = lo;
        while (lo < hi) {
            int mid = lo + ((hi - lo) / 4) * 2; // ensure even
            if (mid % 2 != 0) ++mid;
            int idx = static_cast<int>(std::upper_bound(comp.begin(), comp.end(), mid) - comp.begin()) - 1;
            int present = (idx >= 0) ? (queryPrefix(rightRoot, 0, m - 1, idx) - queryPrefix(leftRoot, 0, m - 1, idx)) : 0;
            int missing = (mid / 2) - present;
            if (missing >= k) {
                hi = mid;
            } else {
                lo = mid + 2;
            }
        }
        result.push_back(lo);
    }
    return result;
}

