long long sumPrimeBetween(int N) {
    if (N < 0) return 0;
    int rev = 0, temp = N;
    while (temp > 0) {
        rev = rev * 10 + (temp % 10);
        temp /= 10;
    }
    int low = N < rev ? N : rev;
    int high = N > rev ? N : rev;
    if (high < 2) return 0;
    if (low < 2) low = 2;

    int limit = static_cast<int>(std::sqrt(high)) + 1;
    std::vector<char> isPrimeSmall(limit + 1, true);
    isPrimeSmall[0] = isPrimeSmall[1] = false;
    for (int i = 2; i * i <= limit; ++i) {
        if (isPrimeSmall[i]) {
            for (int j = i * i; j <= limit; j += i)
                isPrimeSmall[j] = false;
        }
    }
    std::vector<int> primes;
    for (int i = 2; i <= limit; ++i)
        if (isPrimeSmall[i]) primes.push_back(i);

    int rangeSize = high - low + 1;
    std::vector<char> isPrimeRange(rangeSize, true);
    for (int p : primes) {
        int start = (low + p - 1) / p * p;
        if (start < p * 2) start = p * 2;
        for (int j = start; j <= high; j += p)
            isPrimeRange[j - low] = false;
    }

    long long sum = 0;
    for (int i = 0; i < rangeSize; ++i) {
        if (isPrimeRange[i])
            sum += static_cast<long long>(low + i);
    }
    return sum;
}

