int minFlips(const string& s) {
    int n = s.size();
    int totalOnes = 0;
    for (char c : s) if (c == '1') totalOnes++;
    int costAll0 = totalOnes;
    int costAll1 = n - totalOnes;
    int bestSingle1 = (totalOnes >= 1) ? (totalOnes - 1) : 1;
    int costTwoEnds;
    if (n == 1) {
        costTwoEnds = (s[0] == '1') ? 0 : 1;
    } else {
        int left = (s[0] == '1') ? 0 : 1;
        int right = (s[n-1] == '1') ? 0 : 1;
        int middleOnes = 0;
        for (int i = 1; i < n-1; i++) if (s[i] == '1') middleOnes++;
        costTwoEnds = left + right + middleOnes;
    }
    return min({costAll0, costAll1, bestSingle1, costTwoEnds});
}

class Solution {
public:
    vector<int> minCosts(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        vector<int> closest(n);
        for (int i = 0; i < n; i++) {
            if (i == 0) closest[i] = 1;
            else if (i == n-1) closest[i] = n-2;
            else {
                int dl = nums[i]-nums[i-1], dr = nums[i+1]-nums[i];
                closest[i] = dl <= dr ? i-1 : i+1;
            }
        }
        vector<vector<pair<int,int>>> adj(n);
        for (int i = 0; i < n-1; i++) {
            int w = nums[i+1]-nums[i];
            adj[i].push_back({i+1, w});
            adj[i+1].push_back({i, w});
        }
        for (int i = 0; i < n; i++) adj[i].push_back({closest[i], 1});

        unordered_map<int, vector<long long>> cache;
        vector<int> ans;
        for (auto& q : queries) {
            int l = q[0], r = q[1];
            if (!cache.count(l)) {
                vector<long long> dist(n, LLONG_MAX/2);
                dist[l] = 0;
                priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
                pq.push({0, l});
                while (!pq.empty()) {
                    auto [d, u] = pq.top(); pq.pop();
                    if (d > dist[u]) continue;
                    for (auto& [v, w] : adj[u]) {
                        if (d + w < dist[v]) {
                            dist[v] = d + w;
                            pq.push({dist[v], v});
                        }
                    }
                }
                cache[l] = dist;
            }
            ans.push_back((int) cache[l][r]);
        }
        return ans;
    }
};

