int minimumThreshold(int n, const std::vector<std::vector<int>>& edges, int source, int target, int k) {
    std::vector<std::vector<std::pair<int, int>>> adj(n);
    int maxW = 0;
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        int w = e[2];
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
        if (w > maxW) maxW = w;
    }
    auto feasible = [&](int T) -> bool {
        const int INF = k + 1;
        std::vector<int> dist(n, INF);
        std::deque<int> dq;
        dist[source] = 0;
        dq.push_front(source);
        while (!dq.empty()) {
            int u = dq.front();
            dq.pop_front();
            if (dist[u] > k) continue;
            for (const auto& p : adj[u]) {
                int v = p.first;
                int w = p.second;
                int cost = (w > T) ? 1 : 0;
                int nd = dist[u] + cost;
                if (nd < dist[v] && nd <= k) {
                    dist[v] = nd;
                    if (cost == 0) dq.push_front(v);
                    else dq.push_back(v);
                }
            }
        }
        return dist[target] <= k;
    };
    int lo = 0, hi = maxW;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (feasible(mid)) hi = mid;
        else lo = mid + 1;
    }
    return feasible(lo) ? lo : -1;
}

