long long minimizeArraySum(const std::vector<int>& arr) {
    if (arr.empty()) return 0;
    int maxVal = *std::max_element(arr.begin(), arr.end());
    std::vector<char> exists(maxVal + 1, 0);
    for (int v : arr) exists[v] = 1;
    const int INF = maxVal + 1;
    std::vector<int> minDiv(maxVal + 1, INF);
    for (int d = 1; d <= maxVal; ++d) {
        if (!exists[d]) continue;
        for (int m = d; m <= maxVal; m += d) {
            if (exists[m] && d < minDiv[m]) {
                minDiv[m] = d;
            }
        }
    }
