using namespace std;
int smallestUniqueSubarray(const vector<int>& nums) {
    int n = nums.size();
    if (n == 0) return -1;
    const long long MOD1 = 1000000007, MOD2 = 1000000009, BASE = 91138233, OFFSET = 1000000007;
    vector<long long> pow1(n+1,1), pow2(n+1,1), pref1(n+1,0), pref2(n+1,0);
    for (int i=1;i<=n;i++){ pow1[i]=(pow1[i-1]*BASE)%MOD1; pow2[i]=(pow2[i-1]*BASE)%MOD2; }
    for (int i=0;i<n;i++){
        long long val = nums[i] + OFFSET;
        pref1[i+1] = (pref1[i]*BASE + val) % MOD1;
        pref2[i+1] = (pref2[i]*BASE + val) % MOD2;
    }
    auto hasUnique = [&](int L) -> bool {
        unordered_map<long long, int> cnt;
        cnt.reserve(n);
        for (int i=0; i+L<=n; i++){
            long long h1 = ((pref1[i+L] - pref1[i]*pow1[L]) % MOD1 + MOD1) % MOD1;
            long long h2 = ((pref2[i+L] - pref2[i]*pow2[L]) % MOD2 + MOD2) % MOD2;
            long long key = h1 * 1000000021LL + h2;
            cnt[key]++;
        }
        for (auto& kv: cnt) if (kv.second==1) return true;
        return false;
    };
    int lo=1, hi=n, answer=-1;
    while (lo<=hi){
        int mid=(lo+hi)/2;
        if (hasUnique(mid)) { answer=mid; hi=mid-1; } else lo=mid+1;
    }
    return answer;
}

