    for (int r = 0; r < n; r++) {
        for (int c = 0; c < m; c++) {
            int x = matrix[r][c];
            if (x == 0) continue;
            bool isMax = true;
            for (int dr = -x; dr <= x && isMax; dr++) {
                for (int dc = -x; dc <= x; dc++) {
                    if (abs(dr) == x && abs(dc) == x) continue;
