    vector<vector<int>> dist(2, vector<int>(n, -1));
    dist[0][0] = 0;
    deque<pair<int,int>> q;
    q.push_back({0,0});
    while (!q.empty()) {
        auto [f, s] = q.front(); q.pop_front();
        int d = dist[f][s];
        int ns = (s+1)%n;
        if (dist[f][ns] == -1) { dist[f][ns] = d+1; q.push_back({f,ns}); }
        int nf = 1-f, ns2 = (n-s)%n;
        if (dist[nf][ns2] == -1) { dist[nf][ns2] = d+1; q.push_back({nf,ns2}); }
    }
    int best = INT_MAX;
    if (sourceIsRot && dist[0][p0] != -1) best = min(best, dist[0][p0]);
    if (revIsRot && dist[1][p0r] != -1) best = min(best, dist[1][p0r]);
    return best == INT_MAX ? -1 : best;
}

