    while (num / divisor >= 10) {
        divisor *= 10;
    }
    while (num != 0) {
        long long leading = num / divisor;
        long long trailing = num % 10;
        if (leading != trailing) return false;
        num = (num % divisor) / 10;
        divisor /= 100;
    }
    return true;
}

