    int high = matrix[n - 1][n - 1];
    while (low < high) {
        int mid = low + (high - low) / 2;
        int count = 0;
        int col = static_cast<int>(n) - 1;
        for (std::size_t row = 0; row < n; ++row) {
            while (col >= 0 && matrix[row][col] > mid) {
