int kthSmallest(TreeNode* root, int k) {
    TreeNode* cur = root;
    while (cur) {
        if (cur->left == nullptr) {
            if (--k == 0) return cur->val;
            cur = cur->right;
        } else {
            TreeNode* pred = cur->left;
            while (pred->right && pred->right != cur) {
                pred = pred->right;
            }
            if (pred->right == nullptr) {
                pred->right = cur;
                cur = cur->left;
            } else {
                pred->right = nullptr;
                if (--k == 0) return cur->val;
                cur = cur->right;
            }
        }
    }
    return -1;
}

