struct Trie {
    struct Node {
        std::array<std::unique_ptr<Node>, 26> child{};
        bool isEnd = false;
    };
    std::unique_ptr<Node> root;
    Trie() : root(std::make_unique<Node>()) {}
    void insert(const std::string& word) {
        Node* node = root.get();
        for (char ch : word) {
            int idx = ch - 'a';
            if (!node->child[idx]) {
                node->child[idx] = std::make_unique<Node>();
            }
            node = node->child[idx].get();
        }
        node->isEnd = true;
    }
    bool search(const std::string& word) const {
        const Node* node = root.get();
        for (char ch : word) {
            int idx = ch - 'a';
            if (!node->child[idx]) return false;
            node = node->child[idx].get();
        }
        return node->isEnd;
    }
    bool startsWith(const std::string& prefix) const {
        const Node* node = root.get();
        for (char ch : prefix) {
            int idx = ch - 'a';
            if (!node->child[idx]) return false;
            node = node->child[idx].get();
        }
        return true;
    }
};

