int countComponents(int n, const std::vector<std::vector<int>>& edges) {
    std::vector<int> parent(n);
    std::vector<int> rank(n, 0);
    for (int i = 0; i < n; ++i) parent[i] = i;

    auto find = [&](int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    auto unite = [&](int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return false;
        if (rank[ra] < rank[rb]) {
            parent[ra] = rb;
        } else if (rank[ra] > rank[rb]) {
            parent[rb] = ra;
        } else {
            parent[rb] = ra;
            ++rank[ra];
        }
        return true;
    };

    int components = n;
    for (const auto& e : edges) {
        if (unite(e[0], e[1])) --components;
    }
    return components;
}

#include <bits/stdc++.h>
#include <vector>
#include <string>

std::vector<long long> rangeSumQuery(const std::vector<int>& nums, const std::vector<std::vector<std::string>>& queries) {
    int n = static_cast<int>(nums.size());
    std::vector<long long> answers;
    if (n == 0) {
        for (const auto& q : queries) {
            if (!q.empty() && q[0] != "update") answers.push_back(0);
        }
        return answers;
    }
    std::vector<long long> bit(n + 1, 0);
    std::vector<long long> arr(n);
    for (int i = 0; i < n; ++i) {
        arr[i] = nums[i];
        int idx = i + 1;
        long long val = arr[i];
        while (idx <= n) {
            bit[idx] += val;
            idx += idx & -idx;
        }
    }
    auto add = [&](int idx, long long delta) {
        ++idx;
        while (idx <= n) {
            bit[idx] += delta;
            idx += idx & -idx;
        }
    };
    auto prefix = [&](int idx) {
        long long sum = 0;
        ++idx;
        while (idx > 0) {
            sum += bit[idx];
            idx -= idx & -idx;
        }
        return sum;
    };
    for (const auto& q : queries) {
        if (q.empty()) continue;
        if (q[0] == "update") {
            int idx = std::stoi(q[1]);
            long long val = std::stoll(q[2]);
            long long delta = val - arr[idx];
            arr[idx] = val;
            add(idx, delta);
        } else {
            int left = std::stoi(q[1]);
            int right = std::stoi(q[2]);
            long long res = prefix(right) - (left > 0 ? prefix(left - 1) : 0);
            answers.push_back(res);
        }
    }
    return answers;
}

