std::vector<int> findStableMountains(const std::vector<int>& height, int threshold) {
    std::vector<int> stableMountains;
    stableMountains.reserve(height.size());
    for (size_t i = 0; i < height.size(); ++i) {
        bool leftOk = (i == 0) || (height[i - 1] > threshold);
        bool rightOk = (i + 1 == height.size()) || (height[i + 1] > threshold);
        if (leftOk && rightOk) {
            stableMountains.push_back(static_cast<int>(i));
        }
    }
    return stableMountains;
}

