using namespace std;
vector<int> countHouses(int n, int x, int y) {
    vector<vector<int>> adj(n+1);
    for (int i = 1; i < n; i++) { adj[i].push_back(i+1); adj[i+1].push_back(i); }
    if (x != y) { adj[x].push_back(y); adj[y].push_back(x); }
    vector<int> result(n, 0);
    for (int src = 1; src <= n; src++) {
        vector<int> dist(n+1, -1);
        dist[src] = 0;
        queue<int> q; q.push(src);
        while (!q.empty()) {
            int cur = q.front(); q.pop();
            for (int nxt : adj[cur]) if (dist[nxt] == -1) { dist[nxt] = dist[cur]+1; q.push(nxt); }
        }
        for (int dest = 1; dest <= n; dest++) {
            if (dest == src) continue;
            int d = dist[dest];
            if (d >= 1 && d <= n-1) result[d-1]++;
        }
    }
    return result;
}
int main() {
    for (auto v : countHouses(3,1,3)) cout << v << " "; cout << "\n";
    for (auto v : countHouses(5,2,4)) cout << v << " "; cout << "\n";
    for (auto v : countHouses(4,1,1)) cout << v << " "; cout << "\n";
}

