long long minCost(const std::vector<int>& nums) {
    std::size_t n = nums.size();
    if (n < 3) {
        return 0;
    }
    long long answer = LLONG_MAX;
    int bestSecond = nums[1];
    for (std::size_t j = 2; j < n; ++j) {
        long long cost = static_cast<long long>(nums[0]) + bestSecond + nums[j];
        if (cost < answer) {
            answer = cost;
        }
        if (nums[j] < bestSecond) {
            bestSecond = nums[j];
        }
    }
    return answer;
}

