long long maximumSubarraySum(const std::vector<int>& nums, int k) {
    std::size_t n = nums.size();
    std::vector<long long> pref(n + 1, 0);
    for (std::size_t i = 0; i < n; ++i) {
        pref[i + 1] = pref[i] + static_cast<long long>(nums[i]);
    }

    std::unordered_map<long long, long long> minPref;
    long long best = LLONG_MIN;
    bool found = false;

    for (std::size_t j = 0; j < n; ++j) {
        long long total = pref[j + 1];
        long long val = static_cast<long long>(nums[j]);

        long long targets[2] = { val + static_cast<long long>(k), val - static_cast<long long>(k) };
        for (int t = 0; t < 2; ++t) {
            auto it = minPref.find(targets[t]);
            if (it != minPref.end()) {
                long long candidate = total - it->second;
                if (!found || candidate > best) best = candidate;
                found = true;
            }
        }

        long long curPref = pref[j];
        auto it = minPref.find(val);
        if (it == minPref.end() || curPref < it->second) {
            minPref[val] = curPref;
        }
    }

    return found ? best : 0;
}

#include <bits/stdc++.h>

long long countUpTo(long long bound, int limit) {
    if (bound < 0) return 0;
    std::string s = std::to_string(bound);
    long long dp_tight = 1, dp_loose = 0;
    for (char ch : s) {
        int digit = ch - '0';
        long long ndp_tight = 0, ndp_loose = 0;
        // from tight state
        int maxAllowed = std::min(limit, digit);
        for (int d = 0; d <= maxAllowed; ++d) {
            if (d == digit) ndp_tight += dp_tight;
            else ndp_loose += dp_tight;
        }
        // from loose state
        int maxLoose = std::min(limit, 9);
        ndp_loose += dp_loose * (maxLoose + 1);
        dp_tight = ndp_tight;
        dp_loose = ndp_loose;
    }
    return dp_tight + dp_loose;
}

long long numberOfPowerfulInt(long long start, long long finish, int limit, const std::string& s) {
    // compute suffix value and power of 10
    unsigned long long suffix = 0;
    for (char c : s) {
        suffix = suffix * 10 + (c - '0');
    }
    if (suffix > static_cast<unsigned long long>(finish)) return 0;
    unsigned long long pow10 = 1;
    for (size_t i = 0; i < s.size(); ++i) pow10 *= 10ULL;

    long long lower;
    if (start <= static_cast<long long>(suffix)) {
        lower = 0;
    } else {
        long long diff = start - static_cast<long long>(suffix);
        lower = (diff + static_cast<long long>(pow10) - 1) / static_cast<long long>(pow10);
    }

    long long upper;
    if (finish < static_cast<long long>(suffix)) {
        return 0;
    } else {
        long long diff = finish - static_cast<long long>(suffix);
        upper = diff / static_cast<long long>(pow10);
    }

    if (upper < lower) return 0;

    long long totalUpper = countUpTo(upper, limit);
    long long totalLowerMinusOne = countUpTo(lower - 1, limit);
    return totalUpper - totalLowerMinusOne;
}

