int minimumKeypresses(const std::string& word) {
    int freq[26] = {};
    for (char ch : word) {
        if (ch >= 'a' && ch <= 'z') ++freq[ch - 'a'];
        else if (ch >= 'A' && ch <= 'Z') ++freq[ch - 'A'];
    }
    std::vector<int> counts;
    counts.reserve(26);
    for (int f : freq) if (f) counts.push_back(f);
    std::sort(counts.begin(), counts.end(), std::greater<int>());
    long long total = 0;
    for (size_t i = 0; i < counts.size(); ++i) {
        int weight = static_cast<int>(i / 8) + 1;
        total += static_cast<long long>(counts[i]) * weight;
    }
    return static_cast<int>(total);
}

#include <bits/stdc++.h>

std::vector<int> beautifulIndices(const std::string& s, const std::string& a, const std::string& b, int k) {
    auto getOccurrences = [&](const std::string& text, const std::string& pattern) {
        std::vector<int> occ;
        int n = static_cast<int>(text.size());
        int m = static_cast<int>(pattern.size());
        if (m == 0 || n < m) return occ;
        std::vector<int> pi(m, 0);
        for (int i = 1; i < m; ++i) {
            int j = pi[i - 1];
            while (j > 0 && pattern[i] != pattern[j]) j = pi[j - 1];
            if (pattern[i] == pattern[j]) ++j;
            pi[i] = j;
        }
        int j = 0;
        for (int i = 0; i < n; ++i) {
            while (j > 0 && text[i] != pattern[j]) j = pi[j - 1];
            if (text[i] == pattern[j]) ++j;
            if (j == m) {
                occ.push_back(i - m + 1);
                j = pi[j - 1];
            }
        }
        return occ;
    };

    std::vector<int> aPos = getOccurrences(s, a);
    std::vector<int> bPos = getOccurrences(s, b);
    std::vector<int> result;
    size_t pb = 0;
    for (int i : aPos) {
        while (pb < bPos.size() && bPos[pb] < i - k) ++pb;
        if (pb < bPos.size() && bPos[pb] <= i + k) {
            result.push_back(i);
        } else if (pb > 0 && bPos[pb - 1] >= i - k && bPos[pb - 1] <= i + k) {
            result.push_back(i);
        }
    }
    return result;
}

#include <bits/stdc++.h>
int maximumSetSize(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    std::unordered_set<int> set1(nums1.begin(), nums1.end());
    std::unordered_set<int> set2(nums2.begin(), nums2.end());
    int a = set1.size();
    int b = set2.size();
    int c = 0;
    if (set1.size() < set2.size()) {
        for (int v : set1) if (set2.count(v)) ++c;
    } else {
        for (int v : set2) if (set1.count(v)) ++c;
    }
    int half = nums1.size() / 2;
    int keep1 = std::min(a, half);
    int keep2 = std::min(b, half);
    int totalDistinct = a + b - c;
    return std::min(keep1 + keep2, totalDistinct);
}

#include <bits/stdc++.h>
using namespace std;
long long minCost(vector<int>& nums, int k, int dist) {
    int n = nums.size();
    const long long INF = LLONG_MAX/2;
    long long answer = INF;
    for (int i1 = 1; i1 < n; i1++) {
        int maxLast = min(n-1, i1+dist);
        int minLast = i1 + (k-2) - 1;
        if (minLast > maxLast) continue;
        for (int iLast = minLast; iLast <= maxLast; iLast++) {
            int interiorLen = iLast - i1 - 1;
            int need = max(k-3, 0);
            if (interiorLen < need) continue;
            vector<int> interior(nums.begin()+i1+1, nums.begin()+iLast);
            sort(interior.begin(), interior.end());
            long long sumSmallest = 0;
            for (int x = 0; x < need; x++) sumSmallest += interior[x];
            long long total = nums[0] + nums[i1] + nums[iLast] + sumSmallest;
            if (total < answer) answer = total;
        }
    }
    return answer == INF ? -1 : answer;
}
