    vector<int> a1 = {1,3,2,6,4,2};
    cout << minCost(a1, 3, 3) << "\n";
    vector<int> a2 = {10,1,2,2,2,1};
    cout << minCost(a2, 4, 3) << "\n";
    vector<int> a3 = {10,8,18,9};
    cout << minCost(a3, 3, 1) << "\n";
}

