long long minimumDamage(long long power, const std::vector<long long>& damage, const std::vector<long long>& health) {
    std::size_t n = damage.size();
    std::vector<long long> secs(n);
    for (std::size_t i = 0; i < n; ++i) {
        secs[i] = (health[i] + power - 1) / power;
    }
    std::vector<std::size_t> idx(n);
    for (std::size_t i = 0; i < n; ++i) idx[i] = i;
    std::sort(idx.begin(), idx.end(),
        [&](std::size_t a, std::size_t b) {
            long long left = damage[a] * secs[b];
            long long right = damage[b] * secs[a];
            if (left != right) return left > right;
            return a < b;
        });
    long long total = 0;
    long long elapsed = 0;
    for (std::size_t i : idx) {
        elapsed += secs[i];
        total += damage[i] * elapsed;
    }
    return total;
}

#include <bits/stdc++.h>

bool canSortArray(const std::vector<int>& nums) {
    std::unordered_map<int, std::multiset<int>> groups;
    for (int x : nums) {
        int pc = __builtin_popcount(static_cast<unsigned int>(x));
        groups[pc].insert(x);
    }
    std::vector<int> rebuilt;
    rebuilt.reserve(nums.size());
    for (int x : nums) {
        int pc = __builtin_popcount(static_cast<unsigned int>(x));
        auto& ms = groups[pc];
        int val = *ms.begin();
        rebuilt.push_back(val);
        ms.erase(ms.begin());
    }
    for (size_t i = 1; i < rebuilt.size(); ++i) {
        if (rebuilt[i] < rebuilt[i - 1]) {
            return false;
        }
    }
    return true;
}
